  function* playCard8(next, store, state, effect) {
    const player = effect.player;
    let cards = [];
    let basicEnergyCards = 0;
    player.discard.cards.forEach((c) => {
      if (c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */) {
        basicEnergyCards++;
      }
    });
    if (basicEnergyCards === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    const handTemp = new CardList();
    handTemp.cards = player.hand.cards.filter((c) => c !== effect.trainerCard);
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        handTemp,
        {},
        { min: 1, max: 1, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: effect.trainerCard });
    const max = Math.min(basicEnergyCards, 2);
    return store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.discard,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { min: 1, max, allowCancel: false }
      ),
      (cards2) => {
        cards2 = cards2 || [];
        if (cards2.length > 0) {
          MOVE_CARDS(store, state, player.discard, player.hand, {
            cards: cards2,
            sourceCard: effect.trainerCard
          });
        }
      }
    );
  }
