  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-base-set/item-finder.ts
  init_trainer_card();
  init_card_types();
  init_play_card_effects();
  init_game_error();
  init_game_message();
  init_choose_cards_prompt();
  init_card_list();
  init_show_cards_prompt();
  init_state_utils();
  init_prefabs();
  function* playCard10(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    cards = player.hand.cards.filter((c) => c !== self);
    if (cards.length < 2) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let trainersInDiscard = 0;
    player.discard.cards.forEach((c) => {
      if (c instanceof TrainerCard) {
        trainersInDiscard++;
      }
    });
    if (trainersInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    const handTemp = new CardList();
    handTemp.cards = player.hand.cards.filter((c) => c !== self);
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        handTemp,
        {},
        { min: 2, max: 2, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: self });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.discard,
        { superType: 2 /* TRAINER */ },
        { min: 0, max: 1, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
  }
