  var Machamp = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.set = "BS";
      this.fullName = "Machamp BS";
      this.name = "Machamp";
      this.cardImage = "assets/cardback.png";
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Machoke";
      this.setNumber = "8";
      this.hp = 100;
      this.cardType = [6 /* FIGHTING */];
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [
        {
          name: "Strikes Back",
          powerType: 6 /* POKEMON_POWER */,
          text: "Whenever your opponent's attack damages Machamp (even if Machamp is Knocked Out), this power does 10 damage to the attacking Pok\xE9mon. (Don't apply Weakness and Resistance.) This power can't be used if Machamp is Asleep, Confused, or Paralyzed when your opponent attacks."
        }
      ];
      this.attacks = [
        {
          cost: [6 /* FIGHTING */, 6 /* FIGHTING */, 6 /* FIGHTING */, 9 /* COLORLESS */],
          name: "Seismic Toss",
          damage: 60,
          text: ""
        }
      ];
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        if (cardList.specialConditions.includes(2 /* ASLEEP */) || cardList.specialConditions.includes(1 /* CONFUSED */) || cardList.specialConditions.includes(0 /* PARALYZED */)) {
          return state;
        }
        if (IS_POKEMON_POWER_BLOCKED(store, state, player, this)) {
          return state;
        }
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (effect.damage <= 0 || player === targetPlayer || targetPlayer.active !== effect.target) {
          return state;
        }
        if (state.phase === 3 /* ATTACK */) {
          effect.source.damage += 10;
        }
      }
      return state;
    }
  };

