  var Mewtwo = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 60;
      this.weakness = [{ type: P }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Psychic",
          cost: [P, C],
          damage: 10,
          text: "Does 10 damage plus 10 more damage for each Energy card attached to the Defending Pok\xE9mon."
        },
        {
          name: "Barrier",
          cost: [P, P],
          text: "Discard 1 [P] Energy card attached to Mewtwo in order to prevent all effects of attacks, including damage, done to Mewtwo during your opponent's next turn.",
          damage: 0
        }
      ];
      this.set = "BS";
      this.name = "Mewtwo";
      this.fullName = "Mewtwo BS";
      this.setNumber = "10";
      this.cardImage = "assets/cardback.png";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        const energyCount = checkProvidedEnergyEffect.energyMap.length;
        effect.damage += energyCount * 10;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        if (effect.wotcEnergyCostPaid) {
          PREVENT_DAMAGE(store, state, effect, this);
          PREVENT_EFFECTS_OF_ATTACKS(store, state, effect, this);
          return state;
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [5 /* PSYCHIC */],
          { allowCancel: false }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = player.active;
          store.reduceEffect(state, discardEnergy2);
          PREVENT_DAMAGE(store, state, effect, this);
          PREVENT_EFFECTS_OF_ATTACKS(store, state, effect, this);
        });
      }
      return state;
    }
  };

