  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-base-set/potion.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_game_effects();
  init_play_card_effects();
  function* playCard14(next, store, state, effect) {
    const player = effect.player;
    const blocked = [];
    let hasPokemonWithDamage = false;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      if (cardList.damage === 0) {
        blocked.push(target);
      } else {
        hasPokemonWithDamage = true;
      }
    });
    if (hasPokemonWithDamage === false) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_HEAL,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: false, blocked }
      ),
      (results) => {
        targets = results || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    targets.forEach((target) => {
      const healEffect = new HealEffect(player, target, 20);
      store.reduceEffect(state, healEffect);
    });
    return state;
  }
