  function* playCard15(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let hasPokemonWithEnergy = false;
    const blocked = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target3) => {
      if (cardList.cards.some((c) => c.superType === 3 /* ENERGY */)) {
        hasPokemonWithEnergy = true;
      } else {
        blocked.push(target3);
      }
    });
    if (!hasPokemonWithEnergy) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let oppHasPokemonWithEnergy = false;
    const blocked2 = [];
    opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target3) => {
      if (cardList.cards.some((c) => c.superType === 3 /* ENERGY */)) {
        oppHasPokemonWithEnergy = true;
      } else {
        blocked2.push(target3);
      }
    });
    if (!oppHasPokemonWithEnergy) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_DISCARD_CARDS,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: false, blocked }
      ),
      (results) => {
        targets = results || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    const target = targets[0];
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        target,
        { superType: 3 /* ENERGY */ },
        { min: 1, max: 1, allowCancel: false }
      ),
      (selected) => {
        cards = selected;
        next();
      }
    );
    MOVE_CARDS(store, state, target, player.discard, { cards, sourceCard: effect.trainerCard });
    let targets2 = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_DISCARD_CARDS,
        1 /* TOP_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: false, blocked: blocked2 }
      ),
      (results) => {
        targets2 = results || [];
        next();
      }
    );
    if (targets2.length === 0) {
      return state;
    }
    const target2 = targets2[0];
    let cards2 = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        target2,
        { superType: 3 /* ENERGY */ },
        { min: 1, max: 2, allowCancel: false }
      ),
      (selected) => {
        cards2 = selected;
        next();
      }
    );
    MOVE_CARDS(store, state, target2, opponent.discard, { cards: cards2, sourceCard: effect.trainerCard });
    return state;
  }
