      this.attacks = [
        {
          name: "Prophecy",
          cost: [5 /* PSYCHIC */],
          damage: 0,
          text: "Look at up to 3 cards from the top of either player's deck and rearrange them as you like."
        },
        {
          name: "Dark Mind",
          cost: [5 /* PSYCHIC */, 5 /* PSYCHIC */, 5 /* PSYCHIC */],
          damage: 30,
          text: "If your opponent has any Benched Pok\xE9mon, choose 1 of them and this attack does 10 damage to it. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "FO";
