  init_prefabs();
  var Lapras = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 80;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Water Gun",
        cost: [W],
        damage: 10,
        text: "Does 10 damage plus 10 more damage for each [W] Energy attached to Lapras but not used to pay for this attack's Energy cost. You can't add more than 20 damage in this way."
      }, {
        name: "Confuse Ray",
        cost: [W, W],
        damage: 10,
        text: "Flip a coin. If heads, the Defending Pok\xE9mon is now Confused."
      }];
      this.set = "FO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "10";
      this.name = "Lapras";
      this.fullName = "Lapras FO";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const energy2 = new CheckProvidedEnergyEffect(effect.player, effect.source);
        store.reduceEffect(state, energy2);
        const units = energy2.energyMap.flatMap((e) => e.provides);
        const water = units.filter((t) => t === 3 /* WATER */ || t === 0 /* ANY */).length;
        const other = units.length - water;
        const typedCost = effect.attack.cost.filter((t) => t === 3 /* WATER */).length;
        const colorlessCost = effect.attack.cost.filter((t) => t === 9 /* COLORLESS */).length;
        effect.damage += 10 * Math.min(2, Math.max(0, water - typedCost - Math.max(0, colorlessCost - other)));
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === true) {
            const addSpecialCondition = new AddSpecialConditionsEffect(effect, [1 /* CONFUSED */]);
            store.reduceEffect(state, addSpecialCondition);
          }
        });
        return state;
      }
      return state;
    }
  };

