  var Muk = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Grimer";
      this.cardType = [G];
      this.hp = 70;
      this.weakness = [{ type: P }];
      this.resistance = [];
      this.retreat = [C, C];
      this.powers = [{
        name: "Toxic Gas",
        powerType: 6 /* POKEMON_POWER */,
        text: "Ignore all Pok\xE9mon Powers other than Toxic Gases. This power stops working while Muk is Asleep, Confused, or Paralyzed."
      }];
      this.attacks = [{
        name: "Sludge",
        cost: [G, G, G],
        damage: 30,
        text: "Flip a coin. If heads, the Defending Pok\xE9mon is now Poisoned."
      }];
      this.set = "FO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "13";
      this.name = "Muk";
      this.fullName = "Muk FO";
    }
    reduceEffect(store, state, effect) {
      HANDLE_ABILITY_BLOCK(effect, ({ player, powerEffect }) => {
        if (!IS_ABILITY_LOCKER_IN_PLAY(state, player, this)) {
          return false;
        }
        try {
          const cardList = StateUtils.findCardList(state, this);
          if (cardList.specialConditions.includes(2 /* ASLEEP */) || cardList.specialConditions.includes(1 /* CONFUSED */) || cardList.specialConditions.includes(0 /* PARALYZED */)) {
            return false;
          }
        } catch {
          return false;
        }
        const lockerOwner = StateUtils.findOwner(state, StateUtils.findCardList(state, this));
        return CAN_APPLY_LOCKER_ABILITY(store, state, lockerOwner, this, this.powers[0]);
      }, {
        powerTypes: POKEMON_POWER_TYPES,
        exemptPowerNames: ["Toxic Gas"],
        error: GameMessage.BLOCKED_BY_ABILITY
      });
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        state = COIN_FLIP_PROMPT(store, state, player, (results) => {
          if (results) {
            const specialConditionEffect = new AddSpecialConditionsEffect(effect, [3 /* POISONED */]);
            store.reduceEffect(state, specialConditionEffect);
          }
        });
        return state;
      }
      return state;
    }
  };

