  var Seadra = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Horsea";
      this.cardType = [W];
      this.hp = 60;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [{
        name: "Water Gun",
        cost: [W, C],
        damage: 20,
        text: "Does 20 damage plus 10 more damage for each [W] Energy attached to Seadra but not used to pay for this attack's Energy cost. You can't add more than 20 damage in this way."
      }, {
        name: "Agility",
        cost: [W, C, C],
        damage: 20,
        text: "Flip a coin. If heads, during your opponent's next turn, prevent all effects of attacks, including damage, done to Seadra."
      }];
      this.set = "FO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "42";
      this.name = "Seadra";
      this.fullName = "Seadra FO";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const energy2 = new CheckProvidedEnergyEffect(effect.player, effect.source);
        store.reduceEffect(state, energy2);
        const units = energy2.energyMap.flatMap((e) => e.provides);
        const water = units.filter((t) => t === 3 /* WATER */ || t === 0 /* ANY */).length;
        const other = units.length - water;
        const typedCost = effect.attack.cost.filter((t) => t === 3 /* WATER */).length;
        const colorlessCost = effect.attack.cost.filter((t) => t === 9 /* COLORLESS */).length;
        effect.damage += 10 * Math.min(2, Math.max(0, water - typedCost - Math.max(0, colorlessCost - other)));
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            PREVENT_DAMAGE(store, state, effect, this);
            PREVENT_EFFECTS_OF_ATTACKS(store, state, effect, this);
          }
        });
      }
      return state;
    }
  };

