  init_game();
  init_check_effects();
  init_attack_effects2();
  init_prefabs();
  function* useDamageSwap2(next, store, state, effect) {
    const player = effect.player;
    const maxAllowedDamage = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      const checkHpEffect = new CheckHpEffect(player, cardList);
      store.reduceEffect(state, checkHpEffect);
      maxAllowedDamage.push({ target, damage: checkHpEffect.hp - 10 });
    });
    return store.prompt(state, new MoveDamagePrompt(
      effect.player.id,
      GameMessage.MOVE_DAMAGE,
      2 /* BOTTOM_PLAYER */,
      [1 /* ACTIVE */, 2 /* BENCH */],
      maxAllowedDamage,
      { allowCancel: true, blockedTo: maxAllowedDamage.filter((x) => StateUtils.getTarget(state, player, x.target).getPokemonCard() !== effect.card).map((x) => x.target) }
    ), (transfers) => {
      if (transfers === null) {
        return;
      }
      for (const transfer of transfers) {
        const source = StateUtils.getTarget(state, player, transfer.from);
        const target = StateUtils.getTarget(state, player, transfer.to);
        if (source.damage >= 10) {
          source.damage -= 10;
          target.damage += 10;
        }
      }
    });
  }
