  var Venomoth = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Venonat";
      this.cardType = [G];
      this.hp = 70;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: F, value: -30 }];
      this.powers = [{
        name: "Shift",
        useWhenInPlay: true,
        powerType: 6 /* POKEMON_POWER */,
        text: "Once during your turn (before your attack), you may change the type of Venomoth to the type of any other Pok\xE9mon in play other than Colorless. This power can't be used if Venomoth is Asleep, Confused, or Paralyzed."
      }];
      this.attacks = [{
        name: "Venom Powder",
        cost: [G, G],
        damage: 10,
        text: "Flip a coin. If heads, the Defending Pok\xE9mon is now Confused and Poisoned."
      }];
      this.set = "JU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "13";
      this.name = "Venomoth";
      this.fullName = "Venomoth JU";
      this.SHIFT_MARKER = "SHIFT_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const cardList = StateUtils.findCardList(state, this);
        if (cardList.specialConditions.includes(2 /* ASLEEP */) || cardList.specialConditions.includes(1 /* CONFUSED */) || cardList.specialConditions.includes(0 /* PARALYZED */)) {
          return state;
        }
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card, index) => {
          if (card === this || pokemonHasCardType(card, 9 /* COLORLESS */)) {
            blocked.push(index);
          }
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList2, card, index) => {
          if (card === this || pokemonHasCardType(card, 9 /* COLORLESS */)) {
            blocked.push(index);
          }
        });
        if (player.marker.hasMarker(this.SHIFT_MARKER, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          0 /* ANY */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false, blocked }
        ), (result) => {
          const cardList2 = result[0];
          const cardListPokemon = cardList2.getPokemonCard();
          this.cardType = [...cardListPokemon.cardType];
          player.marker.addMarker(this.SHIFT_MARKER, this);
        });
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.SHIFT_MARKER, this)) {
        effect.player.marker.removeMarker(this.SHIFT_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        state = COIN_FLIP_PROMPT(store, state, player, (results) => {
          if (results) {
            {
              const status = new AddSpecialConditionsEffect(effect, [1 /* CONFUSED */]);
              status.target = opponent.active;
              store.reduceEffect(state, status);
            }
            {
              const status = new AddSpecialConditionsEffect(effect, [3 /* POISONED */]);
              status.target = opponent.active;
              store.reduceEffect(state, status);
            }
          }
        });
        return state;
      }
      return state;
    }
  };

