  var Vileplume = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Gloom";
      this.cardType = [G];
      this.hp = 80;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Heal",
        useWhenInPlay: true,
        powerType: 6 /* POKEMON_POWER */,
        text: "Once during your turn (before your attack), you may flip a coin. If heads, remove 1 damage counter from 1 of your Pok\xE9mon. This power can't be used if Vileplume is Asleep, Confused, or Paralyzed."
      }];
      this.attacks = [{
        name: "Petal Dance",
        cost: [G, G, G],
        damage: 40,
        damageCalculation: "x",
        text: "Flip 3 coins. This attack does 40 damage times the number of heads. Vileplume is now Confused (after doing damage)."
      }];
      this.set = "JU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "15";
      this.name = "Vileplume";
      this.fullName = "Vileplume JU";
      this.HEAL_MARKER = "HEAL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        if (cardList.specialConditions.includes(2 /* ASLEEP */) || cardList.specialConditions.includes(1 /* CONFUSED */) || cardList.specialConditions.includes(0 /* PARALYZED */)) {
          return state;
        }
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card, target) => {
          if (cardList2.damage === 0) {
            blocked.push(target);
          }
        });
        const hasPokeBenchWithDamage = player.bench.some((b) => b.damage > 0);
        const hasActiveWIthDamage = player.active.damage > 0;
        const pokemonInPlayWithDamage = hasPokeBenchWithDamage || hasActiveWIthDamage;
        if (player.marker.hasMarker(this.HEAL_MARKER, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (!pokemonInPlayWithDamage) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        player.marker.addMarker(this.HEAL_MARKER, this);
        return COIN_FLIP_PROMPT(store, state, player, (healCoin) => {
          if (!healCoin) return state;
          player.marker.addMarker(this.HEAL_MARKER, this);
          return COIN_FLIP_PROMPT(store, state, player, (healCoin2) => {
            if (!healCoin2) return state;
            player.marker.addMarker(this.HEAL_MARKER, this);
            return COIN_FLIP_PROMPT(store, state, player, (healCoin3) => {
              if (!healCoin3) return state;
              player.marker.addMarker(this.HEAL_MARKER, this);
              return COIN_FLIP_PROMPT(store, state, player, (healCoin4) => {
                if (!healCoin4) return state;
                player.marker.addMarker(this.HEAL_MARKER, this);
                return COIN_FLIP_PROMPT(store, state, player, (healCoin5) => {
                  if (!healCoin5) return state;
                  player.marker.addMarker(this.HEAL_MARKER, this);
                  return COIN_FLIP_PROMPT(store, state, player, (healCoin6) => {
                    if (!healCoin6) return state;
                    let targets = [];
                    return store.prompt(state, new ChoosePokemonPrompt(
                      player.id,
                      GameMessage.CHOOSE_POKEMON_TO_HEAL,
                      2 /* BOTTOM_PLAYER */,
                      [1 /* ACTIVE */, 2 /* BENCH */],
                      { min: 0, max: 1, allowCancel: false, blocked }
                    ), (results) => {
                      targets = results || [];
                      if (targets.length === 0) {
                        return state;
                      }
                      player.marker.addMarker(this.HEAL_MARKER, this);
                      targets.forEach((target) => {
                        const healEffect = new HealEffect(player, target, 10);
                        store.reduceEffect(state, healEffect);
                      });
                      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2) => {
                        if (cardList2.getPokemonCard() === this) {
                          cardList2.addBoardEffect(0 /* ABILITY_USED */);
                        }
                      });
                      return state;
                    });
                  });
                });
              });
            });
          });
        });
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.HEAL_MARKER, this)) {
        effect.player.marker.removeMarker(this.HEAL_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        state = MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          let heads = 0;
          results.forEach((r) => {
            heads += r ? 1 : 0;
          });
          effect.damage = 40 * heads;
        });
        {
          const status = new AddSpecialConditionsEffect(effect, [1 /* CONFUSED */]);
          status.target = player.active;
          store.reduceEffect(state, status);
        }
        return state;
      }
      return state;
    }
  };

