  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-jungle/exeggutor.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var Exeggutor = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.cardType = [G];
      this.hp = 80;
      this.weakness = [{ type: R }];
      this.retreat = [C, C, C];
      this.evolvesFrom = "Exeggcute";
      this.attacks = [{
        name: "Teleport",
        cost: [P],
        damage: 0,
        text: "Switch Exeggutor with 1 of your Benched Pok\xE9mon."
      }, {
        name: "Big Eggsplosion",
        cost: [C],
        damage: 20,
        damageCalculation: "x",
        text: "Flip a number of coins equal to the number of Energy attached to Exeggutor. This attack does 20 damage times the number of heads."
      }];
      this.set = "JU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "35";
      this.name = "Exeggutor";
      this.fullName = "Exeggutor JU";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            return state;
          }
          const target = selected[0];
          player.switchPokemon(target);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkEnergy);
        const totalEnergy = checkEnergy.energyMap.reduce((sum, energy2) => {
          return sum + energy2.provides.length;
        }, 0);
        if (totalEnergy > 0) {
          MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, totalEnergy, (results) => {
            effect.damage = results.filter((r) => r).length * 20;
          });
        } else {
          effect.damage = 0;
        }
      }
      return state;
    }
  };

