  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-jungle/mankey.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Mankey = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [6 /* FIGHTING */];
      this.hp = 30;
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.powers = [{
        name: "Peek",
        useWhenInPlay: true,
        powerType: 6 /* POKEMON_POWER */,
        text: "Once during your turn (before your attack), you may look at one of the following: the top card of either player's deck, a random card from your opponent's hand, or one of either player's Prizes. This power can't be used if Mankey is Asleep, Confused, or Paralyzed."
      }];
      this.attacks = [{
        name: "Scratch",
        cost: [C],
        damage: 10,
        text: ""
      }];
      this.set = "JU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "55";
      this.name = "Mankey";
      this.fullName = "Mankey JU";
      this.PEEK_MARKER = "PEEK_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const cardList = StateUtils.findCardList(state, this);
        if (cardList.specialConditions.includes(2 /* ASLEEP */) || cardList.specialConditions.includes(1 /* CONFUSED */) || cardList.specialConditions.includes(0 /* PARALYZED */)) {
          return state;
        }
        if (player.marker.hasMarker(this.PEEK_MARKER, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        ABILITY_USED(player, this);
        const options = [
          {
            message: GameMessage.REVEAL_YOUR_TOP_DECK,
            action: () => {
              const deckTop = new CardList();
              MOVE_CARDS(store, state, player.deck, deckTop, { count: 1, sourceCard: this });
              state = store.prompt(
                state,
                new ShowCardsPrompt(
                  player.id,
                  GameMessage.REVEAL_YOUR_TOP_DECK,
                  deckTop.cards
                ),
                () => state
              );
              deckTop.moveToTopOfDestination(player.deck);
              ADD_MARKER(this.PEEK_MARKER, player, this);
              return state;
            }
          },
          {
            message: GameMessage.REVEAL_OPPONENT_TOP_DECK,
            action: () => {
              const deckTop = new CardList();
              MOVE_CARDS(store, state, opponent.deck, deckTop, { count: 1, sourceCard: this });
              state = store.prompt(
                state,
                new ShowCardsPrompt(
                  player.id,
                  GameMessage.REVEAL_OPPONENT_TOP_DECK,
                  deckTop.cards
                ),
                () => state
              );
              deckTop.moveToTopOfDestination(opponent.deck);
              ADD_MARKER(this.PEEK_MARKER, player, this);
              return state;
            }
          },
          {
            message: GameMessage.REVEAL_RANDOM_CARD_IN_OPPONENT_HAND,
            action: () => {
              if (opponent.hand.cards.length === 0) {
                throw new GameError(GameMessage.CANNOT_USE_POWER);
              }
              if (opponent.hand.cards.length > 0) {
                const randomIndex = Math.floor(Math.random() * opponent.hand.cards.length);
                const randomCard = opponent.hand.cards[randomIndex];
                SHOW_CARDS_TO_PLAYER(store, state, player, [randomCard]);
              }
              ADD_MARKER(this.PEEK_MARKER, player, this);
              return state;
            }
          },
          {
            message: GameMessage.REVEAL_AN_OPPONENT_PRIZES,
            action: () => {
              const prizes = opponent.prizes.filter((p) => p.isSecret);
              if (prizes.length === 0) {
                throw new GameError(GameMessage.CANNOT_USE_POWER);
              }
              let list = [];
              const cards = [];
              prizes.forEach((p) => {
                p.cards.forEach((c) => cards.push(c));
              });
              const allPrizeCards = new CardList();
              opponent.prizes.forEach((prizeList) => {
                allPrizeCards.cards.push(...prizeList.cards);
              });
              state = store.prompt(state, new ChooseCardsPrompt(
                player,
                GameMessage.REVEAL_ONE_OF_YOUR_PRIZES,
                allPrizeCards,
                {},
                { min: 1, max: 1, allowCancel: false, isSecret: true }
              ), (chosenPrize) => {
                list = chosenPrize || [];
                if (list.length > 0) {
                  state = store.prompt(state, new ShowCardsPrompt(
                    player.id,
                    GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                    list
                  ), () => state);
                }
              });
              ADD_MARKER(this.PEEK_MARKER, player, this);
              return state;
            }
          },
          {
            message: GameMessage.REVEAL_ONE_OF_YOUR_PRIZES,
            action: () => {
              const prizes = player.prizes.filter((p) => p.isSecret);
              if (prizes.length === 0) {
                throw new GameError(GameMessage.CANNOT_USE_POWER);
              }
              let list = [];
              const cards = [];
              prizes.forEach((p) => {
                p.cards.forEach((c) => cards.push(c));
              });
              const allPrizeCards = new CardList();
              player.prizes.forEach((prizeList) => {
                allPrizeCards.cards.push(...prizeList.cards);
              });
              state = store.prompt(state, new ChooseCardsPrompt(
                player,
                GameMessage.REVEAL_ONE_OF_YOUR_PRIZES,
                allPrizeCards,
                {},
                { min: 1, max: 1, allowCancel: false, isSecret: true }
              ), (chosenPrize) => {
                list = chosenPrize || [];
                if (list.length > 0) {
                  state = store.prompt(state, new ShowCardsPrompt(
                    player.id,
                    GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                    list
                  ), () => state);
                }
              });
              ADD_MARKER(this.PEEK_MARKER, player, this);
              return state;
            }
          }
        ];
        return store.prompt(state, new SelectOptionPrompt(
          player.id,
          GameMessage.CHOOSE_OPTION,
          options.map((opt) => opt.message),
          { allowCancel: false }
        ), (choice) => {
          const option = options[choice];
          option.action();
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.PEEK_MARKER, this);
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-jungle/marowak.ts
