  var Marowak = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.cardType = [F];
      this.hp = 60;
      this.weakness = [{ type: G }];
      this.resistance = [{ type: L, value: -30 }];
      this.retreat = [C];
      this.evolvesFrom = "Cubone";
      this.attacks = [{
        name: "Bonemerang",
        cost: [F, F],
        damage: 30,
        damageCalculation: "x",
        text: "Flip 2 coins. This attack does 30 damage times the number of heads."
      }, {
        name: "Call for Friend",
        cost: [F, F, C],
        damage: 0,
        text: "Search your deck for a [F] Basic Pok\xE9mon card and put it onto your Bench. Shuffle your deck afterward. (You can't use this attack if your Bench is full.)"
      }];
      this.set = "JU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "39";
      this.name = "Marowak";
      this.fullName = "Marowak JU";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        state = MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          let heads = 0;
          results.forEach((r) => {
            heads += r ? 1 : 0;
          });
          effect.damage = 30 * heads;
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (!slots2.length) throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        if (!slots2.length) throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        let cards = [];
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          player.deck,
          { superType: 1 /* POKEMON */, stage: 2 /* BASIC */, cardType: [6 /* FIGHTING */] },
          { min: 0, max: 1, allowCancel: true }
        ), (selected) => {
          cards = selected || [];
          if (cards.length === 0) {
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
          cards.forEach((card, index) => {
            store.reduceEffect(state, new PlayPokemonFromDeckEffect(player, card, slots2[index]));
          });
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      return state;
    }
  };

