  function* useSprout(next, store, state, effect) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const max = Math.min(slots2.length, 1);
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
      player.deck,
      { superType: 1 /* POKEMON */, stage: 2 /* BASIC */, name: "Oddish" },
      { min: 0, max, allowCancel: true }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      store.reduceEffect(state, new PlayPokemonFromDeckEffect(player, card, slots2[index]));
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
