  var DarkVileplume = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Dark Gloom";
      this._tags = ["Dark" /* DARK */];
      this.cardType = [G];
      this.hp = 60;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Hay Fever",
          powerType: 6 /* POKEMON_POWER */,
          text: "No Trainer cards can be played. This power stops working while Dark Vileplume is Asleep, Confused, or Paralyzed."
        }
      ];
      this.attacks = [
        {
          name: "Petal Whirlwind",
          cost: [G, G, G],
          damage: 10,
          text: "Flip 3 coins. This attack does 30 damage times the number of heads. If you get 2 or more heads, Dark Vileplume is now Confused (after doing damage)."
        }
      ];
      this.set = "TR";
      this.setNumber = "13";
      this.cardImage = "assets/cardback.png";
      this.name = "Dark Vileplume";
      this.fullName = "Dark Vileplume TR";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayItemEffect || effect instanceof PlaySupporterEffect || effect instanceof PlayStadiumEffect || effect instanceof AttachPokemonToolEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let vileplumeInPlay = false;
        if (IS_POKEMON_POWER_BLOCKED(store, state, player, this)) {
          return state;
        }
        player.forEachPokemon(2 /* BOTTOM_PLAYER */ && 1 /* TOP_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            vileplumeInPlay = true;
          }
          if (!vileplumeInPlay) {
            return state;
          }
          if (vileplumeInPlay) {
            throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
          }
        });
        opponent.forEachPokemon(2 /* BOTTOM_PLAYER */ && 1 /* TOP_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            vileplumeInPlay = true;
          }
          if (!vileplumeInPlay) {
            return state;
          }
          if (vileplumeInPlay) {
            throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          let heads = 0;
          results.forEach((r) => {
            if (r) heads++;
          });
          effect.damage = 30 * heads;
          if (heads >= 2) {
            ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, player, this);
          }
        });
      }
      return state;
    }
  };

