  function isMassExplosionPokemon(name) {
    return name === "Koffing" || name === "Weezing" || name === "Dark Weezing";
  }
  var DarkWeezing = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Koffing";
      this.hp = 60;
      this.cardType = [G];
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Mass Explosion",
          cost: [G, C],
          damage: 20,
          damageCalculation: "x",
          text: "Does 20 damage times the total number of Koffings, Weezings, and Dark Weezings in play (Apply Weakness and Resistance.). Then, this attack does 20 damage to each Koffing, Weezing, and Dark Weezing (even your own). Don't apply Weakness and Resistance."
        },
        {
          name: "Stun Gas",
          cost: [G, G, G],
          damage: 20,
          text: "Flip a coin. If heads, the Defending Pok\xE9mon is now Poisoned; if tails, the Defending Pok\xE9mon is now Paralyzed."
        }
      ];
      this.set = "TR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "14";
      this.name = "Dark Weezing";
      this.fullName = "Dark Weezing TR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        let count = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (isMassExplosionPokemon(cardList.getPokemonCard()?.name)) {
            count++;
          }
        });
        opponent.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (isMassExplosionPokemon(cardList.getPokemonCard()?.name)) {
            count++;
          }
        });
        effect.damage = 20 * count;
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        let source = player.active;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            source = cardList;
          }
        });
        const attackEffect = new AttackEffect(player, opponent, effect.attack);
        attackEffect.source = source;
        attackEffect.ignoreWeakness = true;
        attackEffect.ignoreResistance = true;
        const dealSecondaryDamage = (cardList) => {
          const damageEffect = new PutDamageEffect(attackEffect, 20);
          damageEffect.target = cardList;
          store.reduceEffect(state, damageEffect);
        };
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (isMassExplosionPokemon(cardList.getPokemonCard()?.name)) {
            dealSecondaryDamage(cardList);
          }
        });
        opponent.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (isMassExplosionPokemon(cardList.getPokemonCard()?.name)) {
            dealSecondaryDamage(cardList);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_PARALYZED(store, state, effect);
            YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_POISIONED(store, state, effect);
          }
        });
      }
      return state;
    }
  };

