  init_card_types();
  init_pokemon_card();
  init_play_card_effects();
  init_choose_cards_prompt();
  init_energy_card();
  init_shuffle_prompt();
  init_prefabs();
  function* playCard20(next, store, state, self, effect) {
    const player = effect.player;
    let pokemonsOrEnergyInDiscard = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      const isPokemon = c instanceof PokemonCard;
      const isBasicEnergy = c instanceof EnergyCard && c.energyType === 0 /* BASIC */;
      if (isPokemon || isBasicEnergy) {
        pokemonsOrEnergyInDiscard += 1;
      } else {
        blocked.push(index);
      }
    });
    if (pokemonsOrEnergyInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        {},
        { min: 1, max: 3, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var NightlyGarbageRun = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this._tags = ["Secret Machine" /* ROCKETS_SECRET_MACHINE */];
      this.set = "TR";
      this.name = "Nightly Garbage Run";
      this.fullName = "Nightly Garbage Run TR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "77";
      this.text = "Choose up to 3 Basic Pok\xE9mon cards, Evolution cards, and/or basic Energy cards from your discard pile. Show them to your opponent and shuffle them into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard20(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

