  var Porygon2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 40;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [];
      this.attacks = [{
        name: "Conversion 1",
        cost: [C],
        damage: 0,
        text: "If the Defending Pok\xE9mon has a Weakness, you may change it to a type of your choice other than [C]."
      }, {
        name: "Psybeam",
        cost: [C, C, C],
        damage: 20,
        text: "Flip a coin. If heads, the Defending Pok\xE9mon is now Confused."
      }];
      this.set = "TR";
      this.setNumber = "48";
      this.cardImage = "assets/cardback.png";
      this.name = "Porygon";
      this.fullName = "Porygon TR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.active.getPokemonCard()?.weakness === void 0) {
          return state;
        }
        const options = [
          { value: 7 /* DARK */, message: "Dark" },
          { value: 11 /* DRAGON */, message: "Dragon" },
          { value: 10 /* FAIRY */, message: "Fairy" },
          { value: 6 /* FIGHTING */, message: "Fighting" },
          { value: 2 /* FIRE */, message: "Fire" },
          { value: 1 /* GRASS */, message: "Grass" },
          { value: 4 /* LIGHTNING */, message: "Lightning" },
          { value: 8 /* METAL */, message: "Metal" },
          { value: 5 /* PSYCHIC */, message: "Psychic" },
          { value: 3 /* WATER */, message: "Water" }
        ];
        return store.prompt(state, new SelectPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGY_TYPE,
          options.map((c) => c.message),
          { allowCancel: false }
        ), (choice) => {
          const option = options[choice];
          if (!option) {
            return state;
          }
          const oppActive = opponent.active.getPokemonCard();
          if (oppActive) {
            oppActive.weakness = [{ type: option.value }];
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
          }
        });
      }
      return state;
    }
  };

