  var Moltres2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [R];
      this.hp = 80;
      this.weakness = [];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [{
        name: "Dry Up",
        cost: [R, R],
        damage: 0,
        text: "Choose 1 of your opponent's Pok\xE9mon and flip a coin until you get tails. For each heads, discard 1 Water Energy card attached to that Pok\xE9mon, if any."
      }, {
        name: "Fire Wing",
        cost: [R, R, R, C],
        damage: 50,
        text: ""
      }];
      this.set = "VS2";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "14";
      this.name = "Moltres";
      this.fullName = "Moltres VS2";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let numFlips = 0;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === true) {
            numFlips++;
            return this.reduceEffect(store, state, effect);
          }
          if (numFlips === 0) {
            return state;
          }
          return store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ), (targets) => {
            targets.forEach((target) => {
              return store.prompt(state, new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
                target,
                // Card source is target Pokemon
                { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
                { min: 0, max: numFlips, allowCancel: false }
              ), (selected) => {
                const cards = selected || [];
                if (cards.length > 0) {
                  targets.forEach((target2) => {
                    const discardEnergy2 = new DiscardCardsEffect(effect, cards);
                    discardEnergy2.target = target2;
                    store.reduceEffect(state, discardEnergy2);
                  });
                }
                return state;
              });
            });
          });
        });
        return state;
      }
      return state;
    }
  };

