  var MrMime2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 50;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Dampening Shield",
        powerType: 6 /* POKEMON_POWER */,
        text: "As long as this Pok\xE9mon is on your Bench, Pok\xE9mon in play (both yours and your opponent's) have no Weakness or Resistance."
      }];
      this.attacks = [{
        name: "Juggling",
        cost: [P, C],
        damage: 10,
        damageCalculation: "x",
        text: "Flip 4 coins. This attack does 10 damage for each heads."
      }];
      this.set = "VS1";
      this.setNumber = "64";
      this.cardImage = "assets/cardback.png";
      this.name = "Mr. Mime";
      this.fullName = "Mr. Mime VS1";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonStatsEffect) {
        let MrMimeOwner = null;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList === p.active) {
              return;
            }
            if (cardList.getPokemonCard() === this) {
              MrMimeOwner = p;
            }
          });
        });
        if (IS_POKEMON_POWER_BLOCKED(store, state, MrMimeOwner, this)) {
          return state;
        }
        if (!MrMimeOwner) {
          return state;
        }
        effect.weakness = [];
        effect.resistance = [];
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 4, (results) => {
          let heads = 0;
          results.forEach((r) => {
            heads += r ? 1 : 0;
          });
          effect.damage = 10 * heads;
        });
      }
      return state;
    }
  };

