  var Mew = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 50;
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Psywave",
          cost: [5 /* PSYCHIC */],
          damage: 10,
          text: "Does 10 damage times the number of Energy cards attached to the Defending Pok\xE9mon."
        },
        {
          name: "Devolution Beam",
          cost: [5 /* PSYCHIC */, 5 /* PSYCHIC */],
          damage: 0,
          text: "Choose an evolved Pok\xE9mon (your own or your opponent's). Return the highest Stage Evolution card on that Pok\xE9mon to its player's hand. That Pok\xE9mon is no longer Asleep, Confused, Paralyzed, or Poisoned, or anything else that might be the result of an attack (just as if you had evolved it)."
        }
      ];
      this.set = "PR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "8";
      this.name = "Mew";
      this.fullName = "Mew PR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        const energyCount = checkProvidedEnergyEffect.energyMap.reduce((left, p) => left + p.provides.length, 0);
        effect.damage = energyCount * 10;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const options = [
          {
            message: GameMessage.DISCARD_AND_DRAW,
            action: () => {
              const blocked = [];
              opponent.forEachPokemon(1 /* TOP_PLAYER */, (list, card, target) => {
                if (card.stage == 2 /* BASIC */) {
                  blocked.push(target);
                }
              });
              return store.prompt(state, new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_PICK_UP,
                1 /* TOP_PLAYER */,
                [1 /* ACTIVE */, 2 /* BENCH */],
                { blocked, allowCancel: false }
              ), (result) => {
                const cardList = result.length > 0 ? result[0] : null;
                if (cardList !== null) {
                  DEVOLVE_POKEMON(store, state, cardList, opponent.hand);
                }
              });
            }
          },
          {
            message: GameMessage.SWITCH_POKEMON,
            action: () => {
              const blocked2 = [];
              player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
                if (card.stage == 2 /* BASIC */) {
                  blocked2.push(target);
                }
              });
              return store.prompt(state, new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_PICK_UP,
                2 /* BOTTOM_PLAYER */,
                [1 /* ACTIVE */, 2 /* BENCH */],
                { blocked: blocked2, allowCancel: false }
              ), (result) => {
                const cardList = result.length > 0 ? result[0] : null;
                if (cardList !== null) {
                  DEVOLVE_POKEMON(store, state, cardList, player.hand);
                }
              });
            }
          }
        ];
        const disabled = [opponent, player].map((owner) => ![owner.active, ...owner.bench].some((list) => list.getPokemonCard()?.stage !== void 0 && list.getPokemonCard().stage !== 2 /* BASIC */));
        if (disabled.every(Boolean)) return state;
        return store.prompt(state, new SelectPrompt(
          player.id,
          GameMessage.CHOOSE_OPTION,
          options.map((opt) => opt.message),
          { allowCancel: false, disabled }
        ), (choice) => {
          const option = options[choice];
          option.action();
        });
      }
      return state;
    }
  };

