  var Mewtwo2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 70;
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Energy Absorption",
          cost: [5 /* PSYCHIC */],
          damage: 0,
          text: "Choose up to 2 Energy cards from your discard pile and attach them to Mewtwo."
        },
        {
          name: "Psyburn",
          cost: [5 /* PSYCHIC */, 5 /* PSYCHIC */, 9 /* COLORLESS */],
          damage: 40,
          text: ""
        }
      ];
      this.set = "PR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "3";
      this.name = "Mewtwo";
      this.fullName = "Mewtwo PR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard;
        });
        if (!hasEnergyInDiscard) {
          return state;
        }
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: 1, max: 2 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            return state;
          }
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
        return state;
      }
      return state;
    }
  };

