  var PokemonTower = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "PR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "42";
      this.name = "Pokemon Tower";
      this.fullName = "Pokemon Tower PR";
      this.text = "If the effect of a Pok\xE9mon Power, attack, Energy card, or Trainer card would put a card in a discard pile into its owner's hand, that card stays in that discard pile instead.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof MoveCardsEffect && StateUtils.getStadiumCard(state) === this) {
        const isDiscardToHand = state.players.some(
          (player) => effect.source === player.discard && effect.destination === player.hand
        );
        if (isDiscardToHand) {
          if (effect.sourceEffect && (effect.sourceEffect.powerType === 6 /* POKEMON_POWER */ || effect.sourceEffect.powerType === 1 /* POKEPOWER */ || effect.sourceEffect.powerType === 0 /* POKEBODY */)) {
            effect.preventDefault = true;
            return state;
          }
          if (effect.sourceCard?.attacks.some((attack3) => attack3.name === effect.sourceEffect?.name)) {
            effect.preventDefault = true;
            return state;
          }
          if (effect.sourceCard instanceof TrainerCard || effect.sourceCard?.superType === 3 /* ENERGY */) {
            effect.preventDefault = true;
            return state;
          }
        }
        return state;
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

