  var ErikasDratini = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this._tags = ["Erika's" /* ERIKAS */];
      this.hp = 40;
      this.weakness = [];
      this.resistance = [{ type: P, value: -30 }];
      this.retreat = [C];
      this.powers = [
        {
          powerType: 6 /* POKEMON_POWER */,
          name: "Strange Barrier",
          text: "Whenever an attack by a Basic Pok\xE9mon (including your own) does 20 or more damage to Erika's Dratini (after applying Weakness and Resistance), reduce that damage to 10. (Any other effects of attacks still happen.) This power stops working while Erika's Dratini is Asleep, Confused, or Paralyzed."
        }
      ];
      this.attacks = [
        {
          name: "Tail Strike",
          cost: [C, C],
          damage: 10,
          text: "Flip a coin. If heads, this attack does 10 damage plus 20 more damage; if tails, this attack does 10 damage."
        }
      ];
      this.set = "G1";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "42";
      this.name = "Erika's Dratini";
      this.fullName = "Erika's Dratini G1";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const targetPokemon = effect.target.getPokemonCard();
        if (targetPokemon === this) {
          const sourcePokemon = effect.source.getPokemonCard();
          if (sourcePokemon && sourcePokemon.stage === 2 /* BASIC */) {
            const hasDisablingCondition = effect.target.specialConditions.includes(2 /* ASLEEP */) || effect.target.specialConditions.includes(1 /* CONFUSED */) || effect.target.specialConditions.includes(0 /* PARALYZED */);
            if (!hasDisablingCondition && effect.damage >= 20) {
              effect.damage = 10;
            }
          }
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const damage = effect.damage;
        const coinFlipEffect = new CoinFlipEffect(player, (result) => {
          if (result) {
            effect.damage = damage + 20;
          } else {
            effect.damage = damage;
          }
        });
        store.reduceEffect(state, coinFlipEffect);
      }
      return state;
    }
  };

