  function* playCard21(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const handCards = player.hand.cards.length;
    if (handCards < 2) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.hand,
        {},
        { min: 2, max: 2, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return;
    }
    MOVE_CARDS(store, state, player.hand, player.deck, {
      cards,
      sourceCard: effect.trainerCard
    });
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (!card.name.includes("Erika")) {
        blocked.push(index);
      }
    });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 1 /* POKEMON */ },
        { min: 0, max: 2, allowCancel: true, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, {
      cards,
      sourceCard: effect.trainerCard
    });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var ErikasMaids = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "G1";
      this.name = "Erika's Maids";
      this.fullName = "Erika's Maids G1";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "109";
      this.text = "Trade 2 of the other cards in your hand for up to 2 Basic Pok\xE9mon and/or Evolution cards with Erika in their names from your deck. Show those cards to your opponent, then put them into your hand. Shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard21(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

