  var ErikasPerfume = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "G1";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "110";
      this.name = "Erika's Perfume";
      this.fullName = "Erika's Perfume G1";
      this.text = "Look at your opponent's hand. If he or she has any Basic Pok\xE9mon cards there, you may put any number of them onto your opponent's Bench (as long as there's room).";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const slots2 = opponent.bench.filter((b) => b.cards.length === 0);
        if (slots2.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        if (opponent.hand.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const max = Math.min(
          opponent.hand.cards.filter(
            (card) => card instanceof PokemonCard && card.stage === 2 /* BASIC */
          ).length,
          slots2.length
        );
        effect.preventDefault = true;
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            opponent.hand,
            { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
            { min: 0, max, allowCancel: true }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length === 0) {
              return;
            }
            cards.forEach((card, index) => {
              MOVE_CARDS(store, state, opponent.hand, slots2[index], {
                cards: [card],
                sourceCard: this
              });
              slots2[index].pokemonPlayedTurn = state.turn;
            });
          }
        );
      }
      return state;
    }
  };

