  var MistysPoliwhirl = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Misty's Poliwag";
      this._tags = ["Misty's" /* MISTYS */];
      this.cardType = [W];
      this.hp = 70;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Rapids",
          cost: [W, C],
          damage: 20,
          text: "If the Defending Pok\xE9mon has any Energy cards attached to it, flip a coin. If heads, choose 1 of those Energy cards and discard it."
        },
        {
          name: "Water Punch",
          cost: [C, C, C],
          damage: 30,
          damageCalculation: "+",
          text: "Flip a number of coins equal to the number of [W] Energy attached to Misty's Poliwhirl. This attack does 30 damage plus 10 damage for each heads."
        }
      ];
      this.set = "G1";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "53";
      this.name = "Misty's Poliwhirl";
      this.fullName = "Misty's Poliwhirl G1";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            store.prompt(
              state,
              new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARD_TO_DISCARD,
                opponent.active,
                { superType: 3 /* ENERGY */ },
                { min: 0, max: 1, allowCancel: false }
              ),
              (selected) => {
                const card = selected[0];
                if (!card) {
                  return;
                }
                MOVE_CARDS(store, state, opponent.active, opponent.discard, { cards: [card], sourceCard: this });
              }
            );
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let waterEnergyCount = 0;
        checkProvidedEnergyEffect.energyMap.forEach((em) => {
          if (em.provides.includes(3 /* WATER */) || em.provides.includes(0 /* ANY */)) {
            waterEnergyCount++;
          }
        });
        if (waterEnergyCount > 0) {
          MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, waterEnergyCount, (results) => {
            effect.damage += results.filter((r) => r).length * 10;
          });
        }
      }
      return state;
    }
  };

