  function* playCard23(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const playerHasBench = player.bench.some((b) => b.cards.length > 0);
    const opponentHasBench = opponent.bench.some((b) => b.cards.length > 0);
    if (!playerHasBench && !opponentHasBench) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: effect.trainerCard
    });
    let targets = [];
    if (opponentHasBench) {
      yield store.prompt(
        state,
        new ChoosePokemonPrompt(
          opponent.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ),
        (results) => {
          targets = results || [];
          next();
        }
      );
      if (targets.length > 0) {
        opponent.switchPokemon(targets[0], store, state);
      }
    }
    if (playerHasBench) {
      yield store.prompt(
        state,
        new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ),
        (results) => {
          targets = results || [];
          next();
        }
      );
      if (targets.length > 0) {
        player.switchPokemon(targets[0], store, state);
      }
    }
    return state;
  }
