  var DoubleGust = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "N1";
      this.name = "Double Gust";
      this.fullName = "Double Gust N1";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "100";
      this.text = "If you have any Benched Pok\xE9mon, your opponent chooses 1 of them and switches it with your Active Pok\xE9mon. Then, if your opponent has any Benched Pok\xE9mon, choose 1 of them and switch it with his or her Active Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const oppBenchCount = opponent.bench.reduce((sum, b) => {
          return sum + (b.cards.length > 0 ? 1 : 0);
        }, 0);
        const playerBenchCount = player.bench.reduce((sum, b) => {
          return sum + (b.cards.length > 0 ? 1 : 0);
        }, 0);
        if (!oppBenchCount && !playerBenchCount) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        store.prompt(
          state,
          new ChoosePokemonPrompt(
            opponent.id,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 0, allowCancel: false }
          ),
          (result) => {
            const cardList = result && result[0];
            if (cardList) {
              player.switchPokemon(cardList);
            }
            store.prompt(
              state,
              new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_SWITCH,
                1 /* TOP_PLAYER */,
                [2 /* BENCH */],
                { min: 0, allowCancel: false }
              ),
              (result2) => {
                const cardList2 = result2 && result2[0];
                if (cardList2) {
                  opponent.switchPokemon(cardList2);
                }
              }
            );
          }
        );
      }
      return state;
    }
  };

