  function canSearchBasicToBench(player) {
    return GET_PLAYER_BENCH_SLOTS(player).length > 0 && player.deck.cards.length > 0;
  }
  function maybeSearchBasicToBench(store, state, player, onComplete) {
    if (!canSearchBasicToBench(player)) {
      onComplete();
      return;
    }
    CONFIRMATION_PROMPT(store, state, player, (result) => {
      if (!result) {
        onComplete();
        return;
      }
      const slots2 = GET_PLAYER_BENCH_SLOTS(player);
      store.prompt(
        state,
        new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          player.deck,
          { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
          { min: 0, max: 1, allowCancel: false }
        ),
        (selected) => {
          const cards = selected || [];
          cards.forEach((card, index) => {
            store.reduceEffect(
              state,
              new PlayPokemonFromDeckEffect(player, card, slots2[index])
            );
          });
          onComplete();
        }
      );
    });
  }
