  function* playCard24(next, store, state, self, effect) {
    const player = effect.player;
    let cards = [];
    cards = player.hand.cards.filter((c) => c !== self);
    if (cards.length < 2) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let basicEnergies = 0;
    player.discard.cards.forEach((c) => {
      if (c instanceof EnergyCard && c.energyType === 0 /* BASIC */) {
        basicEnergies += 1;
      }
    });
    if (basicEnergies === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    const handTemp = new CardList();
    handTemp.cards = player.hand.cards.filter((c) => c !== self);
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        handTemp,
        {},
        { min: 2, max: 2, allowCancel: true }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    let recovered = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.discard,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { min: 1, max: 4, allowCancel: true }
      ),
      (selected) => {
        recovered = selected || [];
        next();
      }
    );
    if (recovered.length === 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: self });
    MOVE_CARDS(store, state, player.discard, player.hand, { cards: recovered, sourceCard: self });
    return state;
  }
  var SuperiorEnergyRetrieval = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "PLF";
      this.name = "Superior Energy Retrieval";
      this.fullName = "Superior Energy Retrieval PLF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "103";
      this.text = "You can use this card only if you discard 2 other cards from your hand.Put up to 4 Basic Energy cards from your discard pile into your hand. (You can't choose a card you discarded with the effect of this card.)";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const discardEffect = new DiscardToHandEffect(player, this);
        store.reduceEffect(state, discardEffect);
        if (discardEffect.preventDefault) {
          return state;
        }
        const generator = playCard24(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

