  var ENERGY_TYPE_MAP = {
    [1 /* GRASS */]: 1 /* GRASS */,
    [2 /* FIRE */]: 2 /* FIRE */,
    [3 /* WATER */]: 3 /* WATER */,
    [4 /* LIGHTNING */]: 4 /* LIGHTNING */,
    [5 /* PSYCHIC */]: 5 /* PSYCHIC */,
    [7 /* DARK */]: 7 /* DARK */,
    [10 /* FAIRY */]: 10 /* FAIRY */
  };
  var Eevee2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.hp = 50;
      this.cardType = [C];
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Energy Evolution",
        powerType: 6 /* POKEMON_POWER */,
        text: "Whenever you attach an Energy card to Eevee, flip a coin. If heads, search your deck for a card that evolves from Eevee that is the same type as the Energy card you attached to Eevee. Attach that card to Eevee. This counts as evolving Eevee. Shuffle your deck afterward. This power can't be used if Eevee is Asleep, Confused, or Paralyzed."
      }];
      this.attacks = [{
        name: "Smash Kick",
        cost: [C],
        damage: 10,
        text: ""
      }];
      this.set = "N2";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "38";
      this.name = "Eevee";
      this.fullName = "Eevee N2";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        try {
          const powerEffect = new PowerEffect(player, this.powers[0], this);
          store.reduceEffect(state, powerEffect);
        } catch {
          return state;
        }
        const coinFlip = new CoinFlipEffect(player);
        state = store.reduceEffect(state, coinFlip);
        if (!coinFlip.result) {
          return state;
        }
        const energyType = effect.energyCard.provides[0];
        if (!energyType) {
          return state;
        }
        const eeveeloutionType = ENERGY_TYPE_MAP[energyType];
        if (!eeveeloutionType || eeveeloutionType === 9 /* COLORLESS */) {
          return state;
        }
        if (player.deck.cards.length === 0) {
          return state;
        }
        let cards = [];
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_EVOLVE,
          player.deck,
          { superType: 1 /* POKEMON */, stage: 3 /* STAGE_1 */, evolvesFrom: "Eevee", cardType: [eeveeloutionType] },
          { min: 0, max: 1, allowCancel: false }
        ), (selected) => {
          cards = selected || [];
          if (cards.length > 0) {
            MOVE_CARDS(store, state, player.deck, player.active, { cards, sourceCard: this });
            player.active.clearEffects();
            player.active.pokemonPlayedTurn = state.turn;
          }
        });
        return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
          player.deck.applyOrder(order);
        });
      }
      return state;
    }
  };

