  var DarkFeraligatr = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Dark Croconaw";
      this._tags = ["Dark" /* DARK */];
      this.cardType = [W];
      this.hp = 80;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Scare",
          powerType: 6 /* POKEMON_POWER */,
          text: "As long as Dark Feraligatr is your Active Pok\xE9mon, all of your opponent's Baby Pok\xE9mon Powers stop working and your opponent's Baby Pok\xE9mon can't attack. This power stops working while Dark Feraligatr is Asleep, Confused, or Paralyzed."
        }
      ];
      this.attacks = [
        {
          name: "Crushing Blow",
          cost: [W, W, W],
          damage: 50,
          text: "If the Defending Pok\xE9mon has any Energy cards attached to it, flip a coin. If heads, choose 1 of those cards and discard it."
        }
      ];
      this.set = "N4";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "5";
      this.name = "Dark Feraligatr";
      this.fullName = "Dark Feraligatr N4";
    }
    reduceEffect(store, state, effect) {
      HANDLE_ABILITY_BLOCK(
        effect,
        ({ player, powerEffect }) => {
          const opponent = StateUtils.getOpponent(state, player);
          if (opponent.active.getPokemonCard() !== this) {
            return false;
          }
          if (opponent.active.specialConditions.includes(2 /* ASLEEP */) || opponent.active.specialConditions.includes(1 /* CONFUSED */) || opponent.active.specialConditions.includes(0 /* PARALYZED */)) {
            return false;
          }
          if (powerEffect && IS_POKEMON_POWER_BLOCKED(store, state, opponent, this)) {
            return false;
          }
          return true;
        },
        {
          powerTypes: [4 /* BABY_RULE */],
          error: GameMessage.BLOCKED_BY_ABILITY
        }
      );
      if (effect instanceof AttackEffect && effect.source.getPokemonCard()?.hasTag("Baby" /* BABY */)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (IS_POKEMON_POWER_BLOCKED(store, state, opponent, this)) {
          return state;
        }
        if (opponent.active.getPokemonCard() === this && (opponent.active.specialConditions.includes(2 /* ASLEEP */) || opponent.active.specialConditions.includes(1 /* CONFUSED */) || opponent.active.specialConditions.includes(0 /* PARALYZED */))) {
          return state;
        }
        if (effect.opponent.active.getPokemonCard() === this) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!opponent.active.cards.some((c) => c.superType === 3 /* ENERGY */)) {
          return state;
        }
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            store.prompt(
              state,
              new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARD_TO_DISCARD,
                opponent.active,
                { superType: 3 /* ENERGY */ },
                { min: 0, max: 1, allowCancel: false }
              ),
              (selected) => {
                const card = selected[0];
                if (!card) {
                  return;
                }
                MOVE_CARDS(store, state, opponent.active, opponent.discard, { cards: [card], sourceCard: this });
              }
            );
          }
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-neo-destiny/energy-stadium.ts
