  var EnergyStadium = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.cardImage = "assets/cardback.png";
      this.setNumber = "99";
      this._trainerType = 2 /* STADIUM */;
      this.set = "N4";
      this.name = "Energy Stadium";
      this.fullName = "Energy Stadium N4";
      this.text = "Once during each player's turn (before attacking), that player may flip a coin. If heads, that player puts a basic Energy card from his or her discard pile into his or her hand.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const discardEffect = new DiscardToHandEffect(player, this);
        store.reduceEffect(state, discardEffect);
        if (discardEffect.preventDefault) {
          MOVE_CARDS(store, state, player.supporter, player.discard, {
            cards: [effect.stadium],
            sourceCard: this
          });
          return state;
        }
        const opponent = StateUtils.getOpponent(state, player);
        let basicEnergyInDiscard = 0;
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          const isPokemon = c instanceof EnergyCard && c.energyType === 0 /* BASIC */;
          if (isPokemon) {
            basicEnergyInDiscard += 1;
          } else {
            blocked.push(index);
          }
        });
        if (basicEnergyInDiscard === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            let cards = [];
            store.prompt(
              state,
              new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARD_TO_HAND,
                player.discard,
                { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
                { min: 0, max: 1, allowCancel: false, blocked }
              ),
              (selectedCards) => {
                cards = selectedCards || [];
                if (cards.length === 0) {
                  return state;
                }
                cards.forEach((card, index) => {
                  MOVE_CARDS(store, state, player.discard, player.hand, {
                    cards: [card],
                    sourceCard: this
                  });
                });
                if (cards.length > 0) {
                  SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
                }
              }
            );
          }
        });
      }
      return state;
    }
  };

