  var ShiningMewtwo = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.hp = 70;
      this.cardType = [P];
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Reflect Shield",
          cost: [P, L],
          damage: 0,
          text: "If an attack does damage to Shining Mewtwo during your opponent's next turn (even if Shining Mewtwo is Knocked Out), flip a coin. If heads, prevent all damage done to Shining Mewtwo from that attack (any other effects of attacks still happen) and do 20 damage to the attacking Pok\xE9mon."
        },
        {
          name: "Psyburst",
          cost: [P, P, R],
          damage: 40,
          damageCalculation: "+",
          text: "Discard a [R] Energy card attached to Shining Mewtwo or this attack does nothing. This attack does 40 damage plus 10 damage for each Energy attached to the Defending Pok\xE9mon."
        }
      ];
      this.set = "N4";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "109";
      this.name = "Shining Mewtwo";
      this.fullName = "Shining Mewtwo N4";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return THIS_POKEMON_RETALIATES_ON_DAMAGE_DURING_OPPONENTS_NEXT_TURN(store, state, effect, this, { damage: 20, coinFlipPrevent: true });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const hasFireEnergy = checkProvidedEnergy.energyMap.some(
          (em) => em.provides.includes(2 /* FIRE */) || em.provides.includes(0 /* ANY */)
        );
        if (!hasFireEnergy) {
          effect.damage = 0;
          return state;
        }
        const checkOpponentEnergy = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, checkOpponentEnergy);
        const energyCount = checkOpponentEnergy.energyMap.reduce(
          (left, p) => left + p.provides.length,
          0
        );
        effect.damage += energyCount * 10;
        return store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [2 /* FIRE */],
          { allowCancel: false }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          if (cards.length === 0) {
            effect.damage = 0;
            return;
          }
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = player.active;
          store.reduceEffect(state, discardEnergy2);
        });
      }
      return state;
    }
  };

