  var Charizard2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Charmeleon";
      this.cardType = [R];
      this.hp = 120;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Burning Energy",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), you may turn all basic Energy attached to all of your Pok\xE9mon into [R] Energy for the rest of the turn. This power can't be used if Charizard is affected by a Special Condition."
      }];
      this.attacks = [{
        name: "Scorching Whirlwind",
        cost: [R, R, R, R],
        damage: 120,
        text: "Flip 2 coins. If 1 of them is tails, discard 2 Energy cards attached to Charizard. If both are tails, discard all Energy cards attached to Charizard."
      }];
      this.set = "EX";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "40";
      this.name = "Charizard";
      this.fullName = "Charizard EX";
      this.BURNING_ENERGY_MARKER = "BURNING_ENERGY_MARKER";
      this.BURNING_ENERGY_USED_MARKER = "BURNING_ENERGY_USED_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (HAS_MARKER(this.BURNING_ENERGY_USED_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        ADD_MARKER(this.BURNING_ENERGY_USED_MARKER, player, this);
        ABILITY_USED(player, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          cardList.cards.forEach((c) => {
            if (c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */) {
              ADD_MARKER(this.BURNING_ENERGY_MARKER, c, this);
            }
          });
        });
      }
      if (effect instanceof CheckProvidedEnergyEffect) {
        effect.source.cards.forEach((c) => {
          if (c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && !effect.energyMap.some((e) => e.card === c)) {
            if (HAS_MARKER(this.BURNING_ENERGY_MARKER, c, this)) {
              effect.energyMap.push({ card: c, provides: [2 /* FIRE */] });
            }
          }
        });
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          cardList.cards.forEach((c) => {
            if (HAS_MARKER(this.BURNING_ENERGY_MARKER, c, this)) {
              REMOVE_MARKER(this.BURNING_ENERGY_MARKER, c, this);
            }
          });
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.BURNING_ENERGY_USED_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          let heads = 0;
          results.forEach((r) => {
            if (r) heads++;
          });
          if (!heads) {
            DISCARD_ALL_ENERGY_FROM_POKEMON(store, state, effect, this);
          }
          if (heads === 1) {
            DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 2);
          }
        });
      }
      return state;
    }
  };

