  var Gengar2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Haunter";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Chaos Move",
        powerType: 1 /* POKEPOWER */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), if your opponent has 3 or fewer Prizes, you may move 1 damage counter from 1 Pok\xE9mon (yours or your opponent's) to another (even if it would Knock Out the other Pok\xE9mon). This power can't be used if Gengar is affected by a Special Condition."
      }];
      this.attacks = [{
        name: "Hide in Shadows",
        cost: [P, P, C],
        damage: 40,
        text: "Switch Gengar with 1 of your Benched Pok\xE9mon, if any."
      }];
      this.set = "EX";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "48";
      this.name = "Gengar";
      this.fullName = "Gengar EX";
      this.SHADY_MARKER = "SHADY_MARKER";
      this.hidInShadows = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.marker.hasMarker(this.SHADY_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (opponent.getPrizeLeft() > 3) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        const maxAllowedDamage = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(opponent, cardList);
          store.reduceEffect(state, checkHpEffect);
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(player, cardList);
          store.reduceEffect(state, checkHpEffect);
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        return store.prompt(state, new MoveDamagePrompt(
          effect.player.id,
          GameMessage.MOVE_DAMAGE,
          0 /* ANY */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          maxAllowedDamage,
          { min: 1, max: 1, allowCancel: false }
        ), (transfers) => {
          if (transfers === null) {
            return;
          }
          player.marker.addMarker(this.SHADY_MARKER, this);
          ABILITY_USED(player, this);
          for (const transfer of transfers) {
            const source = StateUtils.getTarget(state, player, transfer.from);
            const target = StateUtils.getTarget(state, player, transfer.to);
            if (source.damage >= 10) {
              source.damage -= 10;
              target.damage += 10;
            }
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.hidInShadows = true;
      }
      if (effect instanceof AfterAttackEffect && this.hidInShadows === true) {
        SWITCH_ACTIVE_WITH_BENCHED(store, state, effect.player);
      }
      if (effect instanceof EndTurnEffect && this.hidInShadows) {
        this.hidInShadows = false;
      }
      return state;
    }
  };

