  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-expedition/pokemon-nurse.ts
  init_trainer_card();
  init_card_types();
  init_choose_pokemon_prompt();
  init_play_card_effects();
  init_game();
  init_game_effects();
  init_prefabs();
  function* playCard25(next, store, state, effect) {
    const player = effect.player;
    if (player.supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    const blocked = [];
    let hasPokemonWithDamage = false;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      if (cardList.damage === 0) {
        blocked.push(target);
      } else {
        hasPokemonWithDamage = true;
      }
    });
    if (hasPokemonWithDamage === false) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_HEAL,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: true, blocked }
      ),
      (results) => {
        targets = results || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    targets.forEach((target) => {
      const healEffect = new HealEffect(player, target, target.damage);
      store.reduceEffect(state, healEffect);
      const cards = target.cards.filter((c) => c.superType === 3 /* ENERGY */);
      MOVE_CARDS(store, state, target, player.discard, {
        cards,
        sourceCard: effect.trainerCard
      });
    });
    return state;
  }
  var PokemonNurse = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "EX";
      this.name = "Pok\xE9mon Nurse";
      this.fullName = "Pok\xE9mon Nurse EX";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "145";
      this.text = "Remove all damage counters from 1 of your Pok\xE9mon. Then discard all Energy cards attached to it, if any.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard25(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

