  var ApricornForest = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.cardImage = "assets/cardback.png";
      this.setNumber = "118";
      this._trainerType = 2 /* STADIUM */;
      this.set = "AQ";
      this.name = "Apricorn Forest";
      this.fullName = "Apricorn Forest AQ";
      this.text = "Once during each player's turn (before attacking), if that player's Bench isn't full, that player flips a coin. If heads, that player shows his or her opponent a basic Energy card from his or her hand. Then, that player searches his or her deck for a Basic Pok\xE9mon card of the same type (color) as the revealed Energy card and puts it onto his or her Bench. The player shuffles his or her deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_STADIUM);
        }
        if (player.hand.cards.filter(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
        ).length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_STADIUM);
        }
        if (slots2.length == 0) {
          throw new GameError(GameMessage.CANNOT_USE_STADIUM);
        } else {
          COIN_FLIP_PROMPT(store, state, player, (result) => {
            if (result) {
              store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARDS,
                  player.hand,
                  { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
                  { min: 1, max: 1, allowCancel: false }
                ),
                (selectedCards) => {
                  const energyCard = selectedCards[0];
                  const energyColor = energyCard.provides[0];
                  MOVE_CARDS(store, state, player.hand, player.deck, { cards: [energyCard] });
                  const blocked = [];
                  player.deck.cards.forEach((card, index) => {
                    if (!(card instanceof PokemonCard)) {
                      blocked.push(index);
                    }
                    if (card instanceof PokemonCard && !pokemonHasCardType(card, energyColor)) {
                      blocked.push(index);
                    }
                  });
                  let cards = [];
                  store.prompt(
                    state,
                    new ChooseCardsPrompt(
                      player,
                      GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
                      player.deck,
                      { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
                      { min: 0, max: 1, allowCancel: false, blocked }
                    ),
                    (selectedCards2) => {
                      cards = selectedCards2 || [];
                      if (cards.length === 0) {
                        return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                          player.deck.applyOrder(order);
                        });
                      } else {
                        cards.forEach((card, index) => {
                          store.reduceEffect(
                            state,
                            new PlayPokemonFromDeckEffect(player, card, slots2[index])
                          );
                        });
                      }
                      return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                        player.deck.applyOrder(order);
                      });
                    }
                  );
                }
              );
            }
          });
        }
      }
      return state;
    }
  };

