  var Blissey = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Chansey";
      this.cardType = [C];
      this.hp = 120;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Happy Healing",
        powerType: 1 /* POKEPOWER */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), choose 1 of your Benched Pok\xE9mon and flip a coin. If heads, count the number of Energy attached to Blissey and then remove that many damage counters from the chosen Benched Pok\xE9mon. This power can't be used if Blissey is affected by a Special Condition."
      }];
      this.attacks = [{
        name: "Smash Bomber",
        cost: [C, C, C],
        damage: 50,
        text: "Flip a coin. If tails, this attack does nothing."
      }];
      this.set = "AQ";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "6";
      this.name = "Blissey";
      this.fullName = "Blissey AQ";
      this.HAPPY_HEALING_MARKER = "HAPPY_HEALING_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        if (HAS_MARKER(this.HAPPY_HEALING_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        ABILITY_USED(player, this);
        ADD_MARKER(this.HAPPY_HEALING_MARKER, player, this);
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            const player2 = effect.player;
            const cardList = StateUtils.findCardList(state, effect.card);
            const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player2, cardList);
            store.reduceEffect(state, checkProvidedEnergyEffect);
            let energies = 0;
            checkProvidedEnergyEffect.energyMap.forEach((energy2) => {
              energy2.provides.forEach((e) => {
                energies++;
              });
            });
            const blocked = [];
            player2.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card, target) => {
              if (cardList2.damage === 0) {
                blocked.push(target);
              }
            });
            let targets = [];
            return store.prompt(state, new ChoosePokemonPrompt(
              player2.id,
              GameMessage.CHOOSE_POKEMON_TO_HEAL,
              2 /* BOTTOM_PLAYER */,
              [2 /* BENCH */],
              { min: 0, max: 1, allowCancel: true, blocked }
            ), (results) => {
              targets = results || [];
              if (targets.length === 0) {
                return state;
              }
              targets.forEach((target) => {
                const healEffect = new HealEffect(player2, target, 10 * energies);
                store.reduceEffect(state, healEffect);
              });
            });
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.HAPPY_HEALING_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (!result) {
            effect.damage = 0;
          }
        });
      }
      return state;
    }
  };

