  var BoostEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [9 /* COLORLESS */];
      this.energyType = 1 /* SPECIAL */;
      this.set = "AQ";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "145";
      this.name = "Boost Energy";
      this.fullName = "Boost Energy AQ";
      this.text = "Boost Energy can be attached only to an Evolved Pok\xE9mon. Discard Boost Energy at the end of the turn it was attached. Boost Energy provides [C][C][C] Energy. The Pok\xE9mon Boost Energy is attached to can't retreat.\n\nWhen the Pok\xE9mon Boost Energy is attached to is no longer an Evolved Pok\xE9mon, discard Boost Energy.";
      this.BOOST_MARKER = "BOOST_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.energyCard === this) {
        if (effect.target.getPokemons().length < 2) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        effect.player.marker.addMarker(this.BOOST_MARKER, this);
      }
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        const attachedTo = effect.source.getPokemonCard();
        if (!!attachedTo && attachedTo instanceof PokemonCard && effect.source.getPokemons().length > 1) {
          effect.energyMap.push({ card: this, provides: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */] });
        }
        return state;
      }
      if (effect instanceof BetweenTurnsEffect && effect.player.marker.hasMarker(this.BOOST_MARKER, this)) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.cards.includes(this)) {
            MOVE_CARDS(store, state, StateUtils.findCardList(state, this), player.discard, { cards: [this], sourceCard: this });
            effect.player.marker.removeMarker(this.BOOST_MARKER, this);
          }
        });
      }
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (!cardList.cards.includes(this)) {
              return;
            }
            const attachedTo = cardList.getPokemonCard();
            if (!!attachedTo && cardList.getPokemons().length < 2) {
              MOVE_CARDS(store, state, StateUtils.findCardList(state, this), player.discard, { cards: [this] });
            }
          });
        });
        return state;
      }
      if (effect instanceof RetreatEffect && effect.player.active.cards.includes(this)) {
        throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
      }
      return state;
    }
  };

