  var Espeon2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Eevee";
      this.cardType = [P];
      this.hp = 80;
      this.weakness = [{ type: P }];
      this.retreat = [];
      this.powers = [{
        name: "Energy Return",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "As often as you like during your turn (before your attack), choose an Energy card attached to 1 of your Pok\xE9mon and return it to your hand. This power can't be used if Espeon is affected by a Special Condition."
      }];
      this.attacks = [{
        name: "Damage Blast",
        cost: [P, C, C],
        damage: 30,
        damageCalculation: "+",
        text: "Flip a number of coins equal to the number of damage counters on the Defending Pok\xE9mon. This attack does 30 damage plus 10 more damage for each heads."
      }];
      this.set = "AQ";
      this.name = "Espeon";
      this.fullName = "Espeon AQ";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "11";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        let isEnergyOnBench = false;
        let isEnergyOnActive = false;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, player.active);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const activeEnergyCount = checkProvidedEnergy.energyMap.length;
        if (activeEnergyCount > 0) {
          isEnergyOnActive = true;
        }
        const blockedTo = [];
        if (!isEnergyOnActive) {
          const target = {
            player: 2 /* BOTTOM_PLAYER */,
            slot: 1 /* ACTIVE */,
            index: 0
          };
          blockedTo.push(target);
        }
        player.bench.forEach((bench, index) => {
          if (bench.cards.length === 0) {
            return;
          }
          const checkProvidedEnergy2 = new CheckProvidedEnergyEffect(player, bench);
          state = store.reduceEffect(state, checkProvidedEnergy2);
          const energyCount = checkProvidedEnergy2.energyMap.length;
          if (energyCount > 0) {
            isEnergyOnBench = true;
          } else {
            const target = {
              player: 2 /* BOTTOM_PLAYER */,
              slot: 2 /* BENCH */,
              index
            };
            blockedTo.push(target);
          }
        });
        if (!isEnergyOnActive && !isEnergyOnBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false, blocked: blockedTo }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          const checkProvidedEnergy2 = new CheckProvidedEnergyEffect(player, targets[0]);
          state = store.reduceEffect(state, checkProvidedEnergy2);
          return store.prompt(state, new ChooseEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_HAND,
            checkProvidedEnergy2.energyMap,
            [9 /* COLORLESS */],
            { allowCancel: false }
          ), (energy2) => {
            const cards = (energy2 || []).map((e) => e.card);
            MOVE_CARDS(store, state, targets[0], player.hand, { cards, sourceCard: this });
            MOVE_CARDS(store, state, targets[0], player.hand, { cards, sourceCard: this, sourceEffect: this.powers[0] });
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const counterCount = effect.opponent.active.damage / 10;
        if (counterCount > 0) {
          MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, counterCount, (results) => {
            effect.damage += results.filter((r) => r).length * 10;
          });
        }
      }
      return state;
    }
  };

