  var Gloom2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Oddish";
      this.cardType = [G];
      this.hp = 70;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Enervating Pollen",
        powerType: 0 /* POKEBODY */,
        text: "As long as Gloom is in play, Resistance on each player's Active Pok\xE9mon only reduces damage by 10."
      }];
      this.attacks = [{
        name: "Sleep Sap",
        cost: [C, C],
        damage: 20,
        text: "Both the Defending Pok\xE9mon and Gloom are now Asleep (after doing damage)."
      }];
      this.set = "AQ";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "49";
      this.name = "Gloom";
      this.fullName = "Gloom AQ";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonStatsEffect) {
        const player = StateUtils.findOwner(state, effect.target);
        const opponent = StateUtils.getOpponent(state, player);
        if (player.active.getPokemonCard() !== this && opponent.active.getPokemonCard() !== this) {
          return state;
        }
        if (effect.target !== player.active && effect.target !== opponent.active) {
          return state;
        }
        if (IS_POKEBODY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const target = effect.target.getPokemonCard();
        if (target && Array.isArray(target.resistance)) {
          effect.resistance = target.resistance.map((res) => {
            if (typeof res.value === "number") {
              return {
                ...res,
                value: -10
              };
            }
            return res;
          });
        }
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, effect.player, this);
        ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, StateUtils.getOpponent(state, effect.player), this);
      }
      return state;
    }
  };

