        const player = effect.player;
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (target.slot === 2 /* BENCH */) {
            blockedMap.push({ source: target, blocked: cardList.cards.map((_, i) => i) });
          }
        });
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (target.slot === 1 /* ACTIVE */) {
            blockedTo.push(target);
          }
        });
