  function* playCard32(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    let pokemonsOrEnergyInDiscard = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      const isPokemon = c instanceof PokemonCard;
      const isBasicEnergy = c instanceof EnergyCard && c.energyType === 0 /* BASIC */;
      if (isPokemon || isBasicEnergy) {
        pokemonsOrEnergyInDiscard += 1;
      } else {
        blocked.push(index);
      }
    });
    if (pokemonsOrEnergyInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        {},
        { min: 1, max: 5, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var TownVolunteers = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "AQ";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "136";
      this.name = "Town Volunteers";
      this.fullName = "Town Volunteers AQ";
      this.text = "Take 5 Baby Pok\xE9mon, Basic Pok\xE9mon, Evolution, and/or basic Energy cards from your discard pile and then show them to your opponent. Shuffle them into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard32(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

