  var WeaknessGuard = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "AQ";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "141";
      this.name = "Weakness Guard";
      this.fullName = "Weakness Guard AQ";
      this.text = "Attach this card to 1 of your Pok\xE9mon. Discard it at the end of your opponent's next turn.\n\nAs long as this card is attached, this Pok\xE9mon has no Weakness.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        state = store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { min: 1, max: 1, allowCancel: false }
          ),
          (transfers) => {
            MOVE_CARDS(store, state, player.supporter, transfers[0], {
              cards: [effect.trainerCard],
              sourceCard: this
            });
          }
        );
      }
      if (effect instanceof EndTurnEffect) {
        const opponent = effect.player;
        const player = StateUtils.getOpponent(state, opponent);
        const cardList = StateUtils.findCardList(state, this);
        if (effect.player === StateUtils.findOwner(state, cardList)) {
          return state;
        }
        player.forEachPokemon(1 /* TOP_PLAYER */, (cardList2, card, index) => {
          if (cardList2.cards.includes(this)) {
            MOVE_CARDS(store, state, cardList2, player.discard, { cards: [this], sourceCard: this });
          }
        });
      }
      if (effect instanceof CheckPokemonStatsEffect && effect.target.tools.includes(this)) {
        const target = effect.target.getPokemonCard();
        if (target) {
          effect.weakness = [];
        }
      }
      return state;
    }
  };

