  function* playCard34(next, store, state, self, effect) {
    const player = effect.player;
    let cards = [];
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const deckTop = new CardList();
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARDS,
        player.deck,
        {},
        { min: 2, max: 2, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, deckTop, { cards, sourceCard: self });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
      return store.prompt(
        state,
        new OrderCardsPrompt(player.id, GameMessage.CHOOSE_CARDS_ORDER, deckTop, {
          allowCancel: false
        }),
        (order2) => {
          if (order2 === null) {
            return state;
          }
          deckTop.applyOrder(order2);
          deckTop.moveToTopOfDestination(player.deck);
        }
      );
    });
  }
  var Oracle = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "SK";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "138";
      this.name = "Oracle";
      this.fullName = "Oracle SK";
      this.text = "Choose 2 cards from your deck and shuffle the rest of your deck. Put the chosen cards on top of your deck in any order.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard34(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

