  var DarkIvysaur = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Bulbasaur";
      this._tags = ["Dark" /* DARK */];
      this.cardType = [G];
      this.hp = 50;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Vine Pull",
          powerType: 0 /* POKEBODY */,
          text: "Once during your turn when Dark Ivysaur retreats, choose 1 of your opponent's Benched Pok\xE9mon and switch it with his or her Active Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Fury Strikes",
          cost: [G, G],
          damage: 0,
          text: "Your opponent puts 3 markers onto his or her Pok\xE9mon (divided as he or she chooses). (More than 1 marker can be put on the same Pok\xE9mon.) Then, this attack does 10 damage to each Pok\xE9mon for each marker on it. Don't apply Weakness and Resistance. Remove the markers at the end of the turn."
        }
      ];
      this.set = "BP";
      this.setNumber = "6";
      this.cardImage = "assets/cardback.png";
      this.name = "Dark Ivysaur";
      this.fullName = "Dark Ivysaur BP";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof RetreatEffect && effect.player.active.cards.includes(this) && !IS_POKEBODY_BLOCKED(store, state, effect.player, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ),
          (result) => {
            const cardList = result[0];
            if (cardList) {
              opponent.switchPokemon(cardList);
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const maxAllowedDamage = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          maxAllowedDamage.push({ target, damage: card.hp + 30 });
        });
        const damage = 30;
        return store.prompt(
          state,
          new PutDamagePrompt(
            effect.opponent.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            damage,
            maxAllowedDamage,
            { allowCancel: false, damageMultiple: 10 }
          ),
          (targets) => {
            const results = targets || [];
            for (const result of results) {
              const target = StateUtils.getTarget(state, player, result.target);
              const putDamageEffect = new PutDamageEffect(effect, result.damage);
              putDamageEffect.target = target;
              effect.ignoreResistance = true;
              effect.ignoreWeakness = true;
              store.reduceEffect(state, putDamageEffect);
            }
          }
        );
      }
      return state;
    }
  };

