  var Combusken = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Torchic";
      this.cardType = [R];
      this.hp = 80;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.powers = [{
        name: "Natural Cure",
        useWhenInPlay: false,
        powerType: 0 /* POKEBODY */,
        text: "When you attach a [R] Energy card from your hand to Combusken, remove all Special Conditions from Combusken."
      }];
      this.attacks = [{
        name: "Lunge",
        cost: [C, C],
        damage: 50,
        text: "Flip a coin. If tails, this attack does nothing."
      }];
      this.set = "RS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "28";
      this.name = "Combusken";
      this.fullName = "Combusken RS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === false) {
            effect.damage = 0;
          }
        });
      }
      if (effect instanceof AttachEnergyEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        if (effect.target.specialConditions.length === 0) {
          return state;
        }
        if (!effect.energyCard.provides.includes(2 /* FIRE */)) {
          return state;
        }
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (IS_POKEBODY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const conditions = effect.target.specialConditions.slice();
        conditions.forEach((condition) => {
          effect.target.removeSpecialCondition(condition);
        });
      }
      return state;
    }
  };

