  var Delcatty = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Skitty";
      this.cardType = [C];
      this.hp = 70;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [{
        name: "Energy Draw",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), you may discard 1 Energy card from your hand. Then draw up to 3 cards from your deck. This power can't be used if Delcatty is affected by a Special Condition."
      }];
      this.attacks = [
        {
          name: "Max Energy Source",
          cost: [C],
          damage: 10,
          damageCalculation: "x",
          text: "Does 10 damage times the amount of Energy attached to all of your Active Pok\xE9mon."
        }
      ];
      this.set = "RS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "5";
      this.name = "Delcatty";
      this.fullName = "Delcatty RS";
      this.ENERGY_DRAW_MARKER = "ENERGY_DRAW_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c instanceof EnergyCard;
        });
        if (HAS_MARKER(this.ENERGY_DRAW_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.active.cards[0] === this && player.active.specialConditions.length > 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 3 /* ENERGY */ },
          { allowCancel: true, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 3, sourceCard: this });
        });
        ADD_MARKER(this.ENERGY_DRAW_MARKER, player, this);
        ABILITY_USED(player, this);
        return state;
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        REMOVE_MARKER(this.ENERGY_DRAW_MARKER, player, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = player.active;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, cardList);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let energies = 0;
        checkProvidedEnergyEffect.energyMap.forEach((energy2) => {
          energy2.provides.forEach((e) => {
            energies++;
          });
        });
        effect.damage = 10 * energies;
      }
      if (effect instanceof EndTurnEffect) {
        if (HAS_MARKER(this.ENERGY_DRAW_MARKER, effect.player, this)) {
          REMOVE_MARKER(this.ENERGY_DRAW_MARKER, effect.player, this);
        }
      }
      return state;
    }
  };

