  init_pokemon_card();
  var Grovyle = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Treecko";
      this.cardType = [G];
      this.hp = 80;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Natural Cure",
        useWhenInPlay: true,
        powerType: 0 /* POKEBODY */,
        text: "Whenever you attach a [G] Energy card from your hand to Grovyle, remove all Special Conditions from Grovyle."
      }];
      this.attacks = [{
        name: "Slash",
        cost: [W, C],
        damage: 20,
        text: ""
      }];
      this.set = "RS";
      this.name = "Grovyle";
      this.fullName = "Grovyle RS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "32";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        if (effect.target.specialConditions.length === 0) {
          return state;
        }
        if (!effect.energyCard.provides.includes(1 /* GRASS */)) {
          return state;
        }
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (IS_POKEBODY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const conditions = effect.target.specialConditions.slice();
        conditions.forEach((condition) => {
          effect.target.removeSpecialCondition(condition);
        });
      }
      return state;
    }
  };

