  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-ruby-and-sapphire/kirlia2.ts
  init_prefabs();
  init_game();
  init_check_effects();
  init_attack_effects();
  init_card_types();
  init_pokemon_card();
  var Kirlia2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Ralts";
      this.cardType = [P];
      this.hp = 70;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [{
        name: "Dazzle Dance",
        cost: [C],
        damage: 0,
        text: "Flip a coin. If heads, each Defending Pok\xE9mon is now Confused."
      }, {
        name: "Life Drain",
        cost: [P],
        damage: 0,
        text: "Flip a coin. If heads, put damage counters on the Defending Pok\xE9mon until it is 10 HP away from being Knocked Out."
      }];
      this.set = "RS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "35";
      this.name = "Kirlia";
      this.fullName = "Kirlia RS 35";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            const player = effect.player;
            const opponent = StateUtils.getOpponent(state, player);
            const selectedTarget = opponent.active;
            const checkHpEffect = new CheckHpEffect(effect.player, selectedTarget);
            store.reduceEffect(state, checkHpEffect);
            const totalHp = checkHpEffect.hp;
            let damageAmount = totalHp - 10;
            const targetDamage = selectedTarget.damage;
            if (targetDamage > 0) {
              damageAmount = Math.max(0, damageAmount - targetDamage);
            }
            if (damageAmount > 0) {
              const damageEffect = new PutDamageEffect(effect, damageAmount);
              damageEffect.target = selectedTarget;
              store.reduceEffect(state, damageEffect);
            } else if (damageAmount <= 0) {
              const damageEffect = new PutDamageEffect(effect, 0);
              damageEffect.target = selectedTarget;
              store.reduceEffect(state, damageEffect);
            }
          }
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-ruby-and-sapphire/lady-outing.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_prefabs();
  init_trainer_prefabs();
  var LadyOuting = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "RS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "83";
      this.name = "Lady Outing";
      this.fullName = "Lady Outing RS";
      this.text = "Search your deck for up to 3 different types of basic Energy cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        const uniqueBasicEnergies = Math.min(
          3,
          player.deck.cards.filter((c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */).map((e) => e.provides[0]).filter((value, index, self) => self.indexOf(value) === index).length
        );
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min: 0, max: uniqueBasicEnergies, allowCancel: false, differentTypes: true }
          ),
          (selected) => {
            if (selected.length > 1) {
              if (selected[0].name === selected[1].name) {
                throw new GameError(GameMessage.CAN_ONLY_SELECT_TWO_DIFFERENT_ENERGY_TYPES);
              }
            }
            if (selected.length === 0) {
              return state;
            }
            MOVE_CARDS(store, state, player.deck, player.hand, { cards: selected, sourceCard: this });
            SHOW_CARDS_TO_PLAYER(store, state, opponent, selected);
          }
        );
        return state;
      }
      return state;
    }
  };

