  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-ruby-and-sapphire/oran-berry.ts
  init_play_card_action();
  init_card_types();
  init_trainer_card();
  init_game_phase_effects();
  init_prefabs();
  init_state_utils();
  var OranBerry = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "RS";
      this.name = "Oran Berry";
      this.fullName = "Oran Berry RS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "85";
      this.text = "At any time between turns, if the Pok\xE9mon this card is attached to has at least 2 damage counters on it, remove 2 damage counters from it. Then discard Oran Berry.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof BetweenTurnsEffect || effect instanceof BeginTurnEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.damage >= 20 && cardList.tools.includes(this)) {
            cardList.damage -= 20;
            MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
          }
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList.damage >= 20 && cardList.tools.includes(this)) {
            cardList.damage -= 20;
            MOVE_CARDS(store, state, cardList, opponent.discard, { cards: [this], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-ruby-and-sapphire/pokenav.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_trainer_prefabs();
  init_prefabs();
  var PokeNav = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "RS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "88";
      this.name = "Pok\xE9Nav";
      this.fullName = "Pok\xE9Nav RS";
      this.text = "Look at the top 3 cards of your deck. You may reveal a Pok\xE9mon or Energy card you find there and put it into your hand. Put the other cards back in any order.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const temp = new CardList();
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.deck, temp, { count: 3, sourceCard: this });
        const blocked = [];
        temp.cards.forEach((c, index) => {
          const isPokemon = c instanceof PokemonCard;
          const isBasicEnergy = c instanceof EnergyCard;
          if (!isPokemon && !isBasicEnergy) {
            blocked.push(index);
          }
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            temp,
            {},
            { allowCancel: false, min: 0, max: 1, blocked }
          ),
          (chosenCards) => {
            if (chosenCards.length > 0) {
              const chosen = chosenCards[0];
              MOVE_CARDS(store, state, temp, player.hand, { cards: [chosen], sourceCard: this });
              SHOW_CARDS_TO_PLAYER(store, state, opponent, chosenCards);
            }
            const remaining = new CardList();
            temp.cards.forEach((card) => {
              if (!chosenCards.includes(card)) {
                remaining.cards.push(card);
              }
            });
            store.prompt(
              state,
              new OrderCardsPrompt(player.id, GameMessage.CHOOSE_CARDS_ORDER, remaining, {
                allowCancel: false
              }),
              (order) => {
                if (order === null) {
                  return state;
                }
                remaining.applyOrder(order);
                remaining.moveToTopOfDestination(player.deck);
              }
            );
            MOVE_CARDS(store, state, player.supporter, player.discard, {
              cards: [this],
              sourceCard: this
            });
          }
        );
      }
      return state;
    }
  };

