  function* playCard37(next, store, state, effect) {
    const player = effect.player;
    let hasBasicEnergy = false;
    let pokemonCount = 0;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
      pokemonCount += 1;
      const basicEnergyAttached = cardList.cards.some((c) => {
        return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
      });
      hasBasicEnergy = hasBasicEnergy || basicEnergyAttached;
    });
    if (!hasBasicEnergy || pokemonCount <= 1) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let transfers = [];
    yield store.prompt(
      state,
      new MoveEnergyPrompt(
        player.id,
        GameMessage.MOVE_ENERGY_CARDS,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { min: 1, max: 1, allowCancel: false }
      ),
      (result) => {
        transfers = result || [];
        next();
      }
    );
    transfers.forEach((transfer) => {
      const source = StateUtils.getTarget(state, player, transfer.from);
      const target = StateUtils.getTarget(state, player, transfer.to);
      MOVE_CARDS(store, state, source, target, {
        cards: [transfer.card],
        sourceCard: effect.trainerCard
      });
    });
    return state;
  }
  var EnergySwitch = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "SVI";
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "173";
      this.name = "Energy Switch";
      this.fullName = "Energy Switch SVI";
      this.text = "Move a basic Energy from 1 of your Pokemon to another of your Pokemon.";
    }
    canPlay(store, state, player) {
      let hasBasicEnergy = false;
      let pokemonCount = 0;
      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
        pokemonCount += 1;
        const basicEnergyAttached = cardList.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
        });
        hasBasicEnergy = hasBasicEnergy || basicEnergyAttached;
      });
      if (!hasBasicEnergy || pokemonCount <= 1) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard37(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

