  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-sandstorm/pichu.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_game_effects();
  var Pichu2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 40;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [{
        name: "Baby Evolution",
        powerType: 1 /* POKEPOWER */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may put Pikachu from your hand onto Pichu (this counts as evolving Pichu) and remove all damage counters from Pichu."
      }];
      this.attacks = [{
        name: "Energy Retrieval",
        cost: [L],
        damage: 0,
        text: "Search your discard pile for up to 2 basic Energy cards and attach them to 1 of your Pok\xE9mon. Put 1 damage counter on that Pok\xE9mon for each Energy card attached in this way."
      }];
      this.set = "SS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "20";
      this.name = "Pichu";
      this.fullName = "Pichu SS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasPikachu = player.hand.cards.some((card) => card instanceof PokemonCard && card.name === "Pikachu");
        if (!hasPikachu) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        player.hand.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && card.name !== "Pikachu") {
            blocked.push(index);
          }
        });
        let selectedCards = [];
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_EVOLVE,
          player.hand,
          { superType: 1 /* POKEMON */ },
          { min: 1, max: 1, allowCancel: true, blocked }
        ), (selected) => {
          selectedCards = selected || [];
          const evolution = selectedCards[0];
          const target = StateUtils.findCardList(state, this);
          MOVE_CARDS(store, state, player.hand, target, { cards: [evolution], sourceCard: this });
          const pokemonTarget = target;
          pokemonTarget.clearEffects();
          pokemonTarget.pokemonPlayedTurn = state.turn;
          const healEffect = new HealEffect(player, pokemonTarget, pokemonTarget.damage);
          store.reduceEffect(state, healEffect);
          return state;
        });
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        if (!player.discard.cards.some((card) => card instanceof EnergyCard && card.energyType === 0 /* BASIC */)) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { allowCancel: true, min: 0, max: 2 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            return;
          }
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            target.damage += 10;
          }
        });
      }
      return state;
    }
  };

