  function* playCard38(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: effect.trainerCard });
    effect.preventDefault = true;
    const cm = CardManager.getInstance();
    const evolutions = cm.getAllCards().filter((c) => {
      return c instanceof PokemonCard && c.stage !== 2 /* BASIC */;
    });
    const activeCard = player.active.getPokemonCard();
    const evolutionNames = [];
    if (activeCard) {
      evolutions.forEach((e) => {
        if (e.evolvesFrom === activeCard.name && !evolutionNames.includes(e.name)) {
          evolutionNames.push(e.name);
        }
      });
    }
    if (evolutionNames.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (card instanceof PokemonCard && !evolutionNames.includes(card.name)) {
        blocked.push(index);
      }
    });
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_EVOLVE,
        player.deck,
        { superType: 1 /* POKEMON */ },
        { min: 1, max: 1, allowCancel: true, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    const evolution = cards[0];
    const targetList = player.active;
    const pokemonCard = targetList.getPokemonCard();
    if (!pokemonCard || pokemonCard.name !== evolution.evolvesFrom) {
      return state;
    }
    MOVE_CARDS(store, state, player.deck, targetList, { cards: [evolution], sourceCard: effect.trainerCard });
    targetList.clearEffects();
    targetList.pokemonPlayedTurn = state.turn;
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var WallysTraining = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "SS";
      this.name = "Wally's Training";
      this.fullName = "Wally's Training SS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "89";
      this.text = "Search your deck for a card that evolves from your Active Pok\xE9mon (choose 1 if there are 2) and put it on your Active Pok\xE9mon. (This counts as evolving that Pok\xE9mon.) Shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard38(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

