  var Armaldo2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Anorith";
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.cardType = [6 /* FIGHTING */, 8 /* METAL */];
      this.hp = 110;
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Delta Edge",
          cost: [M, C],
          damage: 70,
          text: "If you have any Supporter cards in play, this attack's base damage is 20 instead of 70."
        },
        {
          name: "Fossil Charge",
          cost: [F, C, C],
          damage: 50,
          text: "You may discard a Claw Fossil, Mysterious Fossil, Root Fossil, or Holon Fossil from your hand. If you do, choose 1 of your opponent's Benched Pok\xE9mon and do 30 damage to that Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "HP";
      this.fullName = "Armaldo HP";
      this.name = "Armaldo";
      this.setNumber = "1";
      this.cardImage = "assets/cardback.png";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        if (effect.player.supporterTurn > 0) {
          effect.damage = 20;
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const blocked = [];
        player.hand.cards.forEach((card, index) => {
          if (card.name === "Claw Fossil" || card.name === "Mysterious Fossil" || card.name === "Root Fossil" || card.name === "Holon Fossil") {
            return;
          } else {
            blocked.push(index);
          }
        });
        if (blocked.length === player.hand.cards.length) {
          return state;
        }
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            {},
            { allowCancel: true, min: 0, max: 1, blocked }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length === 0) {
              return;
            }
            MOVE_CARDS(store, state, player.hand, player.discard, {
              cards,
              sourceCard: this,
              sourceEffect: this.attacks[1]
            });
            THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_BENCHED_POKEMON(
              30,
              effect,
              store,
              state
            );
          }
        );
      }
      return state;
    }
  };

