  var Chimecho = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.stage = 2 /* BASIC */;
      this.cardType = [M];
      this.hp = 60;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Delta Support",
          useWhenInPlay: true,
          powerType: 1 /* POKEPOWER */,
          text: "Once during your turn (before your attack), if you have a Supporter card with Holon in its name in play, you may search your discard pile for a basic Energy card or a Delta Rainbow Energy card, show it to your opponent, and put it into your hand. This power can't be used if Chimecho is affected by a Special Condition."
        }
      ];
      this.attacks = [
        {
          name: "Hook",
          cost: [C, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "HP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "37";
      this.name = "Chimecho";
      this.fullName = "Chimecho HP";
      this.HOLON_SUPPORTER_MARKER = "HOLON_SUPPORTER_MARKER";
      this.DELTA_SUPPORT_USED_MARKER = "DELTA_SUPPORT_USED_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlaySupporterEffect) {
        if (effect.trainerCard.hasTag("Delta Species" /* DELTA_SPECIES */)) {
          effect.player.marker.addMarker(this.HOLON_SUPPORTER_MARKER, this);
        }
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        REMOVE_MARKER(this.DELTA_SUPPORT_USED_MARKER, effect.player, this);
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.DELTA_SUPPORT_USED_MARKER, this);
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.HOLON_SUPPORTER_MARKER, this);
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (HAS_MARKER(this.DELTA_SUPPORT_USED_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (!HAS_MARKER(this.HOLON_SUPPORTER_MARKER, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && (c.energyType === 0 /* BASIC */ || c.name === "Delta Rainbow Energy");
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        player.discard.cards.forEach((card, index) => {
          if (!(card.superType === 3 /* ENERGY */ && (card.energyType === 0 /* BASIC */ || card.name === "Delta Rainbow Energy"))) {
            blocked.push(index);
          }
        });
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.discard,
            { superType: 3 /* ENERGY */ },
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (cards) => {
            cards = cards || [];
            MOVE_CARDS(store, state, player.discard, player.hand, {
              cards,
              sourceCard: this,
              sourceEffect: this.powers[0]
            });
          }
        );
        ADD_MARKER(this.DELTA_SUPPORT_USED_MARKER, player, this);
        ABILITY_USED(player, this);
      }
      return state;
    }
  };

