  var CrawdauntEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Corphish";
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [W];
      this.hp = 110;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Splash Back",
          useWhenInPlay: true,
          powerType: 1 /* POKEPOWER */,
          text: "Once during your turn (before your attack), if your opponent has 4 or more Benched Pok\xE9mon, you may choose 1 of them and return that Pok\xE9mon and all cards attached to it to his or her hand. This power can't be used if Crawdaunt ex is affected by a Special Condition."
        }
      ];
      this.attacks = [
        {
          name: "Power Blow",
          cost: [W, C],
          damage: 20,
          damageCalculation: "x",
          text: "Does 20 damage times the amount of Energy attached to Crawdaunt ex."
        }
      ];
      this.set = "HP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "99";
      this.name = "Crawdaunt ex";
      this.fullName = "Crawdaunt ex HP";
      this.SPLASH_BACK_MARKER = "SPLASH_BACK_MARKER";
    }
    reduceEffect(store, state, effect) {
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.SPLASH_BACK_MARKER, this);
      if (effect instanceof PlayPokemonEffect && HAS_MARKER(this.SPLASH_BACK_MARKER, effect.player, this)) {
        effect.player.marker.removeMarker(this.SPLASH_BACK_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const benched = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        if (benched < 4) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        if (HAS_MARKER(this.SPLASH_BACK_MARKER, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        ADD_MARKER(this.SPLASH_BACK_MARKER, player, this);
        ABILITY_USED(player, this);
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_PICK_UP,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false, min: 1, max: 1 }
          ),
          (selected) => {
            const cardList = selected[0] || [];
            if (cardList) {
              MOVE_POKEMON_OFF_BOARD(store, state, cardList, {
                pokemonDestination: opponent.hand,
                sourceCard: this
              });
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = player.active;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
        store.reduceEffect(state, checkProvidedEnergy);
        const energyCount = checkProvidedEnergy.energyMap.length;
        effect.damage = 20 * energyCount;
      }
      return state;
    }
  };

