  var Deoxys = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.cardType = [M];
      this.hp = 80;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Form Change",
          powerType: 1 /* POKEPOWER */,
          useWhenInPlay: true,
          text: "Once during your turn (before your attack), you may search your deck for another Deoxys and switch it with Deoxys. (Any cards attached to Deoxys, damage counters, Special Conditions, and effects on it are now on the new Pok\xE9mon.) If you do, put Deoxys on top of your deck. Shuffle your deck afterward. You can't use more than 1 Form Change Pok\xE9-Power each turn."
        }
      ];
      this.attacks = [
        {
          name: "Delta Reduction",
          cost: [M, C],
          damage: 30,
          text: "During your opponent's next turn, any damage done to Deoxys by attacks is reduced by 30 (before applying Weakness and Resistance)."
        }
      ];
      this.set = "HP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "4";
      this.name = "Deoxys";
      this.fullName = "Deoxys HP";
      this.FORME_CHANGE_MARKER = "FORME_CHANGE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && HAS_MARKER(this.FORME_CHANGE_MARKER, effect.player)) {
        REMOVE_MARKER(this.FORME_CHANGE_MARKER, effect.player);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const targetCardList = StateUtils.findCardList(state, this);
        if (!(targetCardList instanceof PokemonCardList)) {
          throw new GameError(GameMessage.INVALID_TARGET);
        }
        if (IS_POKEPOWER_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        if (HAS_MARKER(this.FORME_CHANGE_MARKER, player)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && card.name !== this.name) {
            blocked.push(index);
          }
        });
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            player.deck,
            { superType: 1 /* POKEMON */ },
            { min: 1, max: 1, allowCancel: true, blocked }
          ),
          (selection) => {
            if (!selection?.length) {
              return state;
            }
            const pokemonCard = selection[0];
            if (!(pokemonCard instanceof PokemonCard)) {
              return state;
            }
            store.log(state, "LOG_PLAYER_TRANSFORMS_INTO_POKEMON" /* LOG_PLAYER_TRANSFORMS_INTO_POKEMON */, {
              name: player.name,
              pokemon: this.name,
              card: pokemonCard.name,
              effect: effect.power.name
            });
            MOVE_CARDS(store, state, player.deck, targetCardList, { cards: [pokemonCard], sourceCard: this });
            MOVE_CARDS(store, state, targetCardList, player.deck, { cards: [this], sourceCard: this });
            SHUFFLE_DECK(store, state, player);
            ADD_MARKER(this.FORME_CHANGE_MARKER, player, this);
            ABILITY_USED(player, this);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return THIS_POKEMON_TAKES_LESS_DAMAGE_FROM_ATTACKS_DURING_OPPONENTS_NEXT_TURN_BEFORE_WEAKNESS_AND_RESISTANCE(store, state, effect, 30);
      }
      return state;
    }
  };

