  var HolonAdventurer = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.set = "HP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "85";
      this.name = "Holon Adventurer";
      this.fullName = "Holon Adventurer HP";
      this.text = `Discard a card from your hand. If you can't discard a card from your hand, you can't play this card.
  
  Draw 3 cards. If you discarded a Pok\xE9mon that has \u03B4 on its card, draw 4 cards instead.`;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.hand.cards.filter((c) => c !== effect.trainerCard).length < 1 || player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            effect.player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            {},
            { allowCancel: false, min: 1, max: 1 }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length === 0) {
              return;
            }
            let cardsToDraw = 3;
            if (cards[0] instanceof PokemonCard && cards[0].hasTag("Delta Species" /* DELTA_SPECIES */)) {
              cardsToDraw = 4;
            }
            MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
            DRAW_CARDS(store, state, player, cardsToDraw);
          }
        );
        return state;
      }
      return state;
    }
  };

