  var Pidgeot2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Pidgeotto";
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.cardType = [L, M];
      this.hp = 100;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Delta Reserve",
          powerType: 0 /* POKEBODY */,
          text: "As long as Pidgeot has any Holon Energy cards attached to it, each player's Pok\xE9mon (excluding Pok\xE9mon that has \u03B4 on its card) can't use any Pok\xE9-Powers."
        }
      ];
      this.attacks = [
        {
          name: "Rotating Claws",
          cost: [L, M, C],
          damage: 50,
          text: "You may discard an Energy card attached to Pidgeot. If you do, search your discard pile for an Energy card (excluding the one you discarded) and attach it to Pidgeot."
        }
      ];
      this.set = "HP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "14";
      this.name = "Pidgeot";
      this.fullName = "Pidgeot HP";
    }
    reduceEffect(store, state, effect) {
      HANDLE_ABILITY_BLOCK(
        effect,
        ({ player, card }) => {
          let isThisInPlay = false;
          let hasHolonEnergy = false;
          let owner;
          [player, StateUtils.getOpponent(state, player)].forEach((p) => {
            p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, pokemon) => {
              if (pokemon === this) {
                isThisInPlay = true;
                owner = p;
                hasHolonEnergy = cardList.cards.some(
                  (c) => c.superType === 3 /* ENERGY */ && c.name.includes("Holon Energy")
                );
              }
            });
          });
          if (!isThisInPlay || !hasHolonEnergy || !owner) {
            return false;
          }
          if (IS_POKEBODY_BLOCKED(store, state, owner, this)) {
            return false;
          }
          if (card.hasTag("Delta Species" /* DELTA_SPECIES */)) {
            return false;
          }
          return true;
        },
        {
          powerTypes: POKEPOWER_TYPES,
          error: GameMessage.BLOCKED_BY_ABILITY
        }
      );
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        if (checkProvidedEnergy.energyMap.length === 0) {
          return state;
        }
        CONFIRMATION_PROMPT(
          store,
          state,
          player,
          (result) => {
            if (!result) {
              return;
            }
            state = store.prompt(
              state,
              new ChooseEnergyPrompt(
                player.id,
                GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
                checkProvidedEnergy.energyMap,
                [9 /* COLORLESS */],
                { allowCancel: false }
              ),
              (energy2) => {
                const cards = (energy2 || []).map((e) => e.card);
                if (cards.length === 0) {
                  return;
                }
                const discarded = cards[0];
                const discardEnergy2 = new DiscardCardsEffect(effect, cards);
                discardEnergy2.target = player.active;
                store.reduceEffect(state, discardEnergy2);
                const blocked = [];
                player.discard.cards.forEach((card, index) => {
                  if (card === discarded || card.superType !== 3 /* ENERGY */) {
                    blocked.push(index);
                  }
                });
                const hasOtherEnergy = player.discard.cards.some(
                  (card, index) => !blocked.includes(index)
                );
                if (!hasOtherEnergy) {
                  return;
                }
                state = store.prompt(
                  state,
                  new AttachEnergyPrompt(
                    player.id,
                    GameMessage.ATTACH_ENERGY_TO_ACTIVE,
                    player.discard,
                    2 /* BOTTOM_PLAYER */,
                    [1 /* ACTIVE */],
                    { superType: 3 /* ENERGY */ },
                    { allowCancel: false, min: 1, max: 1, blocked }
                  ),
                  (transfers) => {
                    transfers = transfers || [];
                    if (transfers.length === 0) {
                      return;
                    }
                    for (const transfer of transfers) {
                      const target = StateUtils.getTarget(state, player, transfer.to);
                      MOVE_CARDS(store, state, player.discard, target, {
                        cards: [transfer.card],
                        sourceCard: this,
                        sourceEffect: this.attacks[0]
                      });
                    }
                  }
                );
              }
            );
          },
          GameMessage.WANT_TO_USE_EFFECT_OF_ATTACK
        );
      }
      return state;
    }
  };

