  var Raichu3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Pikachu";
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.cardType = [M];
      this.hp = 70;
      this.weakness = [{ type: F }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Zzzap",
          cost: [C],
          damage: 20,
          text: "Does 20 damage to each Pok\xE9mon that has any Pok\xE9-Powers or Pok\xE9-Bodies (both yours and your opponent's). Don't apply Weakness or Resistance."
        },
        {
          name: "Metallic Thunder",
          cost: [M, M, C],
          damage: 50,
          text: "You may discard 2 [M] Energy attached to Raichu. If you do, this attack's base damage is 90 instead of 50."
        }
      ];
      this.set = "HP";
      this.name = "Raichu";
      this.fullName = "Raichu HP";
      this.setNumber = "15";
      this.cardImage = "assets/cardback.png";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        [player, opponent].forEach((currentPlayer) => {
          const activeCard = currentPlayer.active.getPokemonCard();
          if (activeCard) {
            const stubPowerEffect = new PowerEffect(
              currentPlayer,
              {
                name: "test",
                powerType: 1 /* POKEPOWER */,
                text: ""
              },
              activeCard
            );
            try {
              store.reduceEffect(state, stubPowerEffect);
              if (activeCard.powers.length) {
                const damageEffect = new PutDamageEffect(effect, 20);
                damageEffect.target = currentPlayer.active;
                store.reduceEffect(state, damageEffect);
              }
            } catch {
              return state;
            }
          }
          currentPlayer.bench.forEach((bench) => {
            const benchCard = bench.getPokemonCard();
            if (benchCard) {
              const stubPowerEffect = new PowerEffect(
                currentPlayer,
                {
                  name: "test",
                  powerType: 1 /* POKEPOWER */,
                  text: ""
                },
                benchCard
              );
              try {
                store.reduceEffect(state, stubPowerEffect);
                if (benchCard.powers.length) {
                  const damageEffect = new PutDamageEffect(effect, 20);
                  damageEffect.target = bench;
                  store.reduceEffect(state, damageEffect);
                }
              } catch {
                return state;
              }
            }
          });
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(
          state,
          new ConfirmPrompt(
            effect.player.id,
            "Do you want to use Metallic Thunder's effect?"
          ),
          (wantToUse) => {
            if (wantToUse) {
              state = store.prompt(
                state,
                new ChooseEnergyPrompt(
                  player.id,
                  GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
                  checkProvidedEnergy.energyMap,
                  [8 /* METAL */, 8 /* METAL */],
                  { allowCancel: false }
                ),
                (energy2) => {
                  const cards = (energy2 || []).map((e) => e.card);
                  const discardEnergy2 = new DiscardCardsEffect(effect, cards);
                  discardEnergy2.target = player.active;
                  store.reduceEffect(state, discardEnergy2);
                  effect.damage += 40;
                  return state;
                }
              );
            }
          }
        );
        return state;
      }
      return state;
    }
  };

