  init_trainer_prefabs();
  var AncientTechnicalMachineIce = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this._tags = ["Technical Machine" /* TECHNICAL_MACHINE */];
      this.set = "HL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "84";
      this.name = "Ancient Technical Machine [Ice]";
      this.fullName = "Ancient Technical Machine [Ice] HL";
      this.attacks = [
        {
          name: "Ice Generator",
          cost: [C],
          damage: 0,
          text: "Discard all of your opponent's Trainer cards in play. If you do, prevent all effects, including damage, done to the Pok\xE9mon using this attack during your opponent's next turn."
        }
      ];
      this.text = "Attach this card to 1 of your Evolved Pok\xE9mon (excluding Pok\xE9mon-ex and Pok\xE9mon that has an owner in its name) in play. That Pok\xE9mon may use this card's attack instead of its own. At the end of your turn, discard Ancient Technical Machine [Ice].";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const blocked = [];
        let eligibleCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, index) => {
          if (cardList.getPokemons().length < 2 || card.hasTag("ex" /* POKEMON_ex */)) {
            blocked.push(index);
          } else {
            eligibleCount++;
          }
        });
        if (eligibleCount === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        state = store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (transfers) => {
            MOVE_CARDS(store, state, player.supporter, transfers[0], { cards: [effect.trainerCard], sourceCard: this });
          }
        );
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, index) => {
          if (cardList.cards.includes(this)) {
            MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
          }
        });
      }
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (!cardList.cards.includes(this)) {
              return;
            }
            const attachedTo = cardList.getPokemonCard();
            if (!!attachedTo && (attachedTo.hasTag("ex" /* POKEMON_ex */) || cardList.getPokemons().length < 2)) {
              MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
            }
          });
        });
      }
      if (effect instanceof CheckAttackCostEffect && effect.attack === this.attacks[0]) {
        const pokemonCard = effect.player.active.getPokemonCard();
        if (pokemonCard && "getColorlessReduction" in pokemonCard) {
          const reduction = pokemonCard.getColorlessReduction(state);
          for (let i = 0; i < reduction && effect.cost.includes(9 /* COLORLESS */); i++) {
            const index = effect.cost.indexOf(9 /* COLORLESS */);
            if (index !== -1) {
              effect.cost.splice(index, 1);
            }
          }
        }
      }
      if (effect instanceof CheckPokemonAttacksEffect && effect.player.active.cards.includes(this) && !effect.attacks.includes(this.attacks[0])) {
        effect.attacks.push(this.attacks[0]);
      }
      if (effect instanceof AttackEffect && effect.attack === this.attacks[0]) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        PREVENT_DAMAGE(store, state, effect, this);
        PREVENT_EFFECTS_OF_ATTACKS(store, state, effect, this);
        if (opponent.stadium.cards.length > 0) {
          MOVE_CARDS(store, state, opponent.stadium, opponent.discard, {
            cards: opponent.stadium.cards
          });
        }
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          const topPokemon = cardList.getPokemonCard();
          const pokemonsInStack = cardList.getPokemons();
          const trainerCards = cardList.cards.filter((c) => c instanceof TrainerCard);
          const tools = cardList.tools.slice();
          if (tools.length > 0) {
            MOVE_CARDS(store, state, cardList, opponent.discard, { cards: tools });
          }
          for (const card of trainerCards) {
            if (card === topPokemon) {
              const allCards = cardList.cards.slice();
              if (allCards.length > 0) {
                MOVE_CARDS(store, state, cardList, opponent.discard, { cards: allCards });
              }
              break;
            }
            if (pokemonsInStack.some((pokemon) => pokemon === card)) {
              continue;
            }
            MOVE_CARDS(store, state, cardList, opponent.discard, { cards: [card] });
          }
        });
      }
      return state;
    }
  };

