  var Bellossom = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Gloom";
      this.cardType = [G];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -30 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Heal Dance",
        powerType: 1 /* POKEPOWER */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may remove 2 damage counters from 1 of your Pok\xE9mon. You can't use more than 1 Heal Dance Pok\xE9-Power each turn.This power can't be used if Bellossom is affected by a Special Condition."
      }];
      this.attacks = [{
        name: "Miracle Powder",
        cost: [G],
        damage: 10,
        text: "Flip a coin. If heads, choose 1 Special Condition. The Defending Pok\xE9mon is now affected by that Special Condition."
      }, {
        name: "Solar Beam",
        cost: [G, C, C],
        damage: 50,
        text: ""
      }];
      this.set = "HL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "16";
      this.name = "Bellossom";
      this.fullName = "Bellossom HL";
      this.HEAL_DANCE_MARKER = "HEAL_DANCE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        if (HAS_MARKER(this.HEAL_DANCE_MARKER, player)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const blocked = [];
        let hasPokemonWithDamage = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.damage === 0) {
            blocked.push(target);
          } else {
            hasPokemonWithDamage = true;
          }
        });
        if (hasPokemonWithDamage === false) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        let targets = [];
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_HEAL,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false, blocked }
        ), (results) => {
          targets = results || [];
          if (targets.length === 0) {
            return state;
          }
          targets.forEach((target) => {
            const healEffect = new HealEffect(player, target, 20);
            store.reduceEffect(state, healEffect);
          });
        });
        ADD_MARKER(this.HEAL_DANCE_MARKER, player, this);
        ABILITY_USED(player, this);
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.HEAL_DANCE_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            const options = [
              { message: GameMessage.SPECIAL_CONDITION_PARALYZED, value: 0 /* PARALYZED */ },
              { message: GameMessage.SPECIAL_CONDITION_CONFUSED, value: 1 /* CONFUSED */ },
              { message: GameMessage.SPECIAL_CONDITION_ASLEEP, value: 2 /* ASLEEP */ },
              { message: GameMessage.SPECIAL_CONDITION_POISONED, value: 3 /* POISONED */ },
              { message: GameMessage.SPECIAL_CONDITION_BURNED, value: 4 /* BURNED */ }
            ];
            store.prompt(state, new SelectPrompt(
              player.id,
              GameMessage.CHOOSE_SPECIAL_CONDITION,
              options.map((c) => c.message),
              { allowCancel: false }
            ), (choice) => {
              const option = options[choice];
              if (option !== void 0) {
                const specialConditionEffect = new AddSpecialConditionsEffect(effect, [option.value]);
                store.reduceEffect(state, specialConditionEffect);
              }
            });
          }
        });
      }
      return state;
    }
  };

