  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  function* playCard39(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_USE_ATTACK);
    }
    const cm = CardManager.getInstance();
    const evolutions = cm.getAllCards().filter((c) => {
      return c instanceof PokemonCard && c.stage !== 2 /* BASIC */;
    });
    const evolutionNames = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
      const valid = evolutions.filter((e) => e.evolvesFrom === card.name);
      valid.forEach((c) => {
        if (!evolutionNames.includes(c.name)) {
          evolutionNames.push(c.name);
        }
      });
    });
    if (evolutionNames.length === 0) {
      throw new GameError(GameMessage.CANNOT_USE_ATTACK);
    }
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (card instanceof PokemonCard && !evolutionNames.includes(card.name)) {
        blocked.push(index);
      }
    });
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_EVOLVE,
      player.deck,
      { superType: 1 /* POKEMON */ },
      { min: 0, max: 1, allowCancel: true, blocked }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length === 0) {
      return state;
    }
    const evolution = cards[0];
    const blocked2 = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
      if (card.name !== evolution.evolvesFrom) {
        blocked2.push(target);
      }
    });
    let targets = [];
    yield store.prompt(state, new ChoosePokemonPrompt(
      player.id,
      GameMessage.CHOOSE_POKEMON_TO_EVOLVE,
      2 /* BOTTOM_PLAYER */,
      [1 /* ACTIVE */, 2 /* BENCH */],
      { allowCancel: false, blocked: blocked2 }
    ), (selection) => {
      targets = selection || [];
      next();
    });
    if (targets.length === 0) {
      return state;
    }
    const pokemonCard = targets[0].getPokemonCard();
    if (pokemonCard === void 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.deck, targets[0], { cards: [evolution], sourceCard: effect.source.getPokemonCard() });
    targets[0].clearEffects();
    targets[0].pokemonPlayedTurn = state.turn;
    effect.source.damage += 10;
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
