  var Vileplumeex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Gloom";
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [G];
      this.hp = 140;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Block Dust",
          powerType: 0 /* POKEBODY */,
          text: "As long as Vileplume ex is your Active Pok\xE9mon, your opponent can't play any Trainer cards (except for Supporter cards) from his or her hand."
        }
      ];
      this.attacks = [
        {
          name: "Special Formula",
          cost: [G, C, C],
          damage: 50,
          text: "Flip a coin. If heads, the Defending Pok\xE9mon is now Asleep and Poisoned. If tails, the Defending Pok\xE9mon is now Confused."
        }
      ];
      this.set = "HL";
      this.setNumber = "100";
      this.cardImage = "assets/cardback.png";
      this.name = "Vileplume ex";
      this.fullName = "Vileplume ex HL";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayItemEffect || effect instanceof AttachPokemonToolEffect || effect instanceof PlayStadiumEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.active.getPokemonCard() !== this && opponent.active.getPokemonCard() !== this) {
          return state;
        }
        if (IS_POKEBODY_BLOCKED(store, state, opponent, this)) {
          return state;
        }
        if (opponent.active.getPokemonCard() === this) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, opponent, this);
            ADD_POISON_TO_PLAYER_ACTIVE(store, state, opponent, this);
          } else {
            ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, opponent, this);
          }
        });
      }
      return state;
    }
  };

