  var Voltorb3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.hp = 40;
      this.cardType = [L];
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Recharge",
          cost: [C],
          damage: 0,
          text: "Search your deck for a [L] Energy card and attach it to Voltorb. Shuffle your deck afterward."
        },
        {
          name: "Rolling Attack",
          cost: [L, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "HL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "80";
      this.name = "Voltorb";
      this.fullName = "Voltorb HL";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blocked = [];
        player.deck.cards.forEach((c, i) => {
          if (!(c instanceof EnergyCard)) blocked.push(i);
          else if (c.energyType !== 0 /* BASIC */) blocked.push(i);
          else if (!c.provides.includes(4 /* LIGHTNING */)) blocked.push(i);
        });
        const hasBasicLightning = player.deck.cards.some((c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(4 /* LIGHTNING */));
        if (!hasBasicLightning) {
          return state;
        }
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_ATTACH,
          player.deck,
          { superType: 3 /* ENERGY */ },
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length > 0) {
            MOVE_CARDS(store, state, player.deck, player.active, { cards: [cards[0]], sourceCard: this });
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
          return state;
        });
      }
      return state;
    }
  };

