  var Walrein = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Sealeo";
      this.cardType = [W];
      this.hp = 120;
      this.weakness = [{ type: M }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Crush Draw",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), you may reveal the top card of your deck. If that card is a basic Energy card, attach it to 1 of your Pok\xE9mon. If not, put the card back on your deck. This power can't be used if Walrein is affected by a Special Condition."
      }];
      this.attacks = [{
        name: "Sheer Cold",
        cost: [W, W, C],
        damage: 50,
        text: "Flip a coin. If heads, each Defending Pok\xE9mon can't attack during your opponent's next turn."
      }];
      this.set = "HL";
      this.setNumber = "15";
      this.cardImage = "assets/cardback.png";
      this.name = "Walrein";
      this.fullName = "Walrein HL";
      this.CRUSH_DRAW_MARKER = "CRUSH_DRAW_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.CRUSH_DRAW_MARKER, this);
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.marker.removeMarker(this.CRUSH_DRAW_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const temp = new CardList();
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.CRUSH_DRAW_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        MOVE_CARDS(store, state, player.deck, temp, { count: 1, sourceCard: this });
        const energyCardsDrawn = temp.cards.filter((card) => {
          return card instanceof EnergyCard && card.energyType === 0 /* BASIC */;
        });
        if (energyCardsDrawn.length == 0) {
          player.marker.addMarker(this.CRUSH_DRAW_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          temp.cards.slice(0, 1).forEach((card) => {
            store.prompt(state, [new ShowCardsPrompt(
              player.id,
              GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
              temp.cards
            )], () => {
              temp.moveToTopOfDestination(player.deck);
            });
          });
        } else {
          return store.prompt(state, new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            temp,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min: 0, max: energyCardsDrawn.length, allowCancel: false }
          ), (transfers) => {
            player.marker.addMarker(this.CRUSH_DRAW_MARKER, this);
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.addBoardEffect(0 /* ABILITY_USED */);
              }
            });
            if (transfers) {
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, temp, target, { cards: [transfer.card], sourceCard: this });
              }
              temp.cards.forEach((card) => {
                MOVE_CARDS(store, state, temp, player.hand, { cards: [card], sourceCard: this });
              });
            }
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            DEFENDING_POKEMON_CANNOT_ATTACK(store, state, effect, this);
          }
        });
      }
      return state;
    }
  };

