  var StevensAdvice = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "PK";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "83";
      this.name = "Steven's Advice";
      this.fullName = "Steven's Advice PK";
      this.text = "Draw a number of cards up to the number of your opponent's Pok\xE9mon in play. If you have 7 or more cards (including this one) in your hand, you can't play this card.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const playerHand = player.hand.cards.filter((c) => c !== this);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (playerHand.length + 1 >= 7) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const opponentBenched = opponent.bench.reduce(
          (left, b) => left + (b.cards.length ? 1 : 0),
          0
        );
        const totalOpponentPokemon = opponentBenched + 1;
        MOVE_CARDS(store, state, player.deck, player.hand, { count: Math.min(totalOpponentPokemon, player.deck.cards.length), sourceCard: this });
      }
      return state;
    }
  };

