  var Ditto3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 60;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Duplicate",
        powerType: 1 /* POKEPOWER */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may search your deck for another Ditto and switch it with Ditto. (Any cards attached to Ditto, damage counters, Special Conditions, and effects on it are now on the new Pok\xE9mon.) If you do, put Ditto on top of your deck. Shuffle your deck afterward. You can't use more than 1 Duplicate Pok\xE9-Power each turn."
      }];
      this.attacks = [{
        name: "Copy",
        cost: [C],
        damage: 0,
        copycatAttack: true,
        text: "Choose 1 of the Defending Pok\xE9mon's attacks. Copy copies that attack. This attack does nothing if Ditto doesn't have the Energy necessary to use that attack. (You must still do anything else required for that attack.) Ditto performs that attack."
      }];
      this.set = "DS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "38";
      this.name = "Ditto";
      this.fullName = "Ditto DS";
      this.DUPLICATE_MARKER = "DUPLICATE_MARKER";
    }
    reduceEffect(store, state, effect) {
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.DUPLICATE_MARKER, this);
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const targetCardList = StateUtils.findCardList(state, this);
        if (!(targetCardList instanceof PokemonCardList)) {
          throw new GameError(GameMessage.INVALID_TARGET);
        }
        if (HAS_MARKER(this.DUPLICATE_MARKER, player)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && card.name !== "Ditto") {
            blocked.push(index);
          }
        });
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          player.deck,
          { superType: 1 /* POKEMON */ },
          { min: 1, max: 1, allowCancel: true, blocked }
        ), (selection) => {
          if (!selection?.length) {
            return state;
          }
          const pokemonCard = selection[0];
          if (!(pokemonCard instanceof PokemonCard)) {
            return state;
          }
          store.log(state, "LOG_PLAYER_TRANSFORMS_INTO_POKEMON" /* LOG_PLAYER_TRANSFORMS_INTO_POKEMON */, {
            name: player.name,
            pokemon: this.name,
            card: pokemonCard.name,
            effect: effect.power.name
          });
          MOVE_CARDS(store, state, player.deck, targetCardList, { cards: [pokemonCard], sourceCard: this });
          MOVE_CARDS(store, state, targetCardList, player.deck, { cards: [this], sourceCard: this });
          SHUFFLE_DECK(store, state, player);
          ADD_MARKER(this.DUPLICATE_MARKER, player, this);
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentActive = opponent.active.getPokemonCard();
        if (!opponentActive) {
          return state;
        }
        const { blocked } = this.buildEnergyBlockedAttacks(state, store, player, opponentActive);
        return COPY_ATTACK_FROM_POKEMON_LIST(store, state, effect, [opponentActive], {
          allowCancel: true,
          blocked
        });
      }
      return state;
    }
    buildEnergyBlockedAttacks(state, store, player, card) {
      const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player);
      store.reduceEffect(state, checkProvidedEnergyEffect);
      const energyMap = checkProvidedEnergyEffect.energyMap;
      const blocked = [];
      const affordableAttacks = card.attacks.filter((attack3) => {
        const checkAttackCost = new CheckAttackCostEffect(player, attack3);
        state = store.reduceEffect(state, checkAttackCost);
        return StateUtils.checkEnoughEnergy(energyMap, checkAttackCost.cost);
      });
      card.attacks.forEach((attack3) => {
        if (!affordableAttacks.includes(attack3)) {
          blocked.push({ index: 0, attack: attack3.name });
        }
      });
      return { blocked };
    }
  };

