  var Dragonite3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Dragonair";
      this.cardType = [L, M];
      this.hp = 100;
      this.weakness = [{ type: C }];
      this.resistance = [{ type: G, value: -30 }, { type: F, value: -30 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Delta Charge",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), you may attach a [L] Energy card from your discard pile to 1 of your Benched Pok\xE9mon. This power can't be used if Dragonite is affected by a Special Condition."
      }];
      this.attacks = [
        {
          name: "Agility",
          cost: [L, C],
          damage: 30,
          text: "Flip a coin. If heads, prevent all effects of an attack, including damage, done to Dragonite during your opponent's next turn."
        },
        {
          name: "Heavy Impact",
          cost: [L, M, C, C],
          damage: 70,
          text: ""
        }
      ];
      this.set = "DS";
      this.name = "Dragonite";
      this.fullName = "Dragonite DS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "3";
      this.DELTA_CHARGE_MARKER = "DELTA_CHARGE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.DELTA_CHARGE_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(4 /* LIGHTNING */);
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.DELTA_CHARGE_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Lightning Energy" },
          { allowCancel: false, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            return;
          }
          ABILITY_USED(player, this);
          ADD_MARKER(this.DELTA_CHARGE_MARKER, player, this);
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return FLIP_COIN_TO_PREVENT_DAMAGE_AND_EFFECTS_DURING_OPPONENTS_NEXT_TURN(store, state, effect, this);
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.DELTA_CHARGE_MARKER, this);
      return state;
    }
  };

