  init_attack_effects2();
  init_check_effects();
  var Gardevoir2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Kirlia";
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.hp = 100;
      this.cardType = [P, M];
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Energy Jump",
          useWhenInPlay: true,
          powerType: 1 /* POKEPOWER */,
          text: "Once during your turn (before your attack), you may move an Energy card attached to 1 of your Pok\xE9mon to another of your Pok\xE9mon. This power can't be used if Gardevoir is affected by a Special Condition."
        }
      ];
      this.attacks = [
        {
          name: "Psychic Rage",
          cost: [M, C],
          damage: 0,
          text: "Choose 1 of your opponent's Pok\xE9mon. This attack does 10 damage for each damage counter on Gardevoir to that Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Black Magic",
          cost: [P, C, C],
          damage: 10,
          damageCalculation: "+",
          text: "Does 10 damage plus 20 more damage times the number of your opponent's Benched Pok\xE9mon."
        }
      ];
      this.set = "DS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "6";
      this.name = "Gardevoir";
      this.fullName = "Gardevoir DS";
      this.ENERGY_JUMP_MARKER = "ENERGY_JUMP_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        REMOVE_MARKER(this.ENERGY_JUMP_MARKER, effect.player, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (HAS_MARKER(this.ENERGY_JUMP_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          const blockedCards = [];
          checkProvidedEnergy.energyMap.forEach((em) => {
            if (em.provides.length === 0) {
              blockedCards.push(em.card);
            }
          });
          const blocked = [];
          blockedCards.forEach((bc) => {
            const index = cardList.cards.indexOf(bc);
            if (index !== -1 && !blocked.includes(index)) {
              blocked.push(index);
            }
          });
          if (blocked.length !== 0) {
            blockedMap.push({ source: target, blocked });
          }
        });
        return store.prompt(
          state,
          new MoveEnergyPrompt(
            effect.player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            {},
            { min: 1, max: 1, allowCancel: false, blockedMap }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              ADD_MARKER(this.ENERGY_JUMP_MARKER, player, this);
              ABILITY_USED(player, this);
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
            return state;
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.ENERGY_JUMP_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_POKEMON(
          effect.player.active.damage,
          effect,
          store,
          state
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentBenched = opponent.bench.reduce(
          (left, b) => left + (b.cards.length ? 1 : 0),
          0
        );
        const totalBenched = opponentBenched;
        effect.damage += totalBenched * 20;
      }
      return state;
    }
  };

