  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-delta-species/holon-farmer.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_prefabs();
  init_trainer_prefabs();
  var HolonFarmer = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.set = "DS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "91";
      this.name = "Holon Farmer";
      this.fullName = "Holon Farmer DS";
      this.text = "Discard a card from your hand. If you can't discard a card from your hand, you can't play this card.\n\nSearch your discard pile for 3 basic Energy cards and any combination of 3 Basic Pok\xE9mon or Evolution cards, show them to your opponent, and put them on top of your deck. Shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        DISCARD_X_CARDS_FROM_YOUR_HAND(effect, store, state, 1, 1);
        const opponent = StateUtils.getOpponent(state, player);
        let cards = [];
        let pokemons = 0;
        let energies = 0;
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          if (c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */) {
            energies += 1;
          } else if (c instanceof PokemonCard) {
            pokemons += 1;
          } else {
            blocked.push(index);
          }
        });
        const maxPokemons = Math.min(pokemons, 3);
        const maxEnergies = Math.min(energies, 3);
        const count = maxPokemons + maxEnergies;
        if (count === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: this });
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DECK,
            player.discard,
            {},
            { min: count, max: count, allowCancel: false, blocked, maxPokemons, maxEnergies }
          ),
          (selected) => {
            cards = selected || [];
            if (cards.length > 0) {
              SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
            }
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-delta-species/holon-lass.ts
  init_game();
