  var HolonLass = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.set = "DS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "92";
      this.name = "Holon Lass";
      this.fullName = "Holon Lass DS";
      this.text = "Discard a card from your hand. If you can't discard a card from your hand, you can't play this card.\n\nCount the total number of Prize cards left(both yours and your opponent's). Look at that many cards from the top of your deck, choose as many Energy cards as you like, show them to your opponent, and put them into your hand. Put the other cards back on top of your deck. Shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        DISCARD_X_CARDS_FROM_YOUR_HAND(effect, store, state, 1, 1);
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        const temp = new CardList();
        const totalPrizes = player.getPrizeLeft() + opponent.getPrizeLeft();
        MOVE_CARDS(store, state, player.deck, temp, { count: totalPrizes, sourceCard: this });
        const energyCount = temp.cards.filter((card) => card.superType === 3 /* ENERGY */).length;
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            temp,
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 0, max: energyCount }
          ),
          (chosenCards) => {
            if (chosenCards.length === 0) {
              temp.cards.forEach((card) => {
                MOVE_CARDS(store, state, temp, player.deck, { cards: [card], sourceCard: this });
              });
            } else {
              chosenCards.forEach((card) => {
                MOVE_CARDS(store, state, temp, player.hand, { cards: [card], sourceCard: this });
              });
              if (chosenCards.length > 0) {
                SHOW_CARDS_TO_PLAYER(store, state, opponent, chosenCards);
              }
              MOVE_CARDS(store, state, temp, player.deck, { sourceCard: this });
            }
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      return state;
    }
  };

