  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-delta-species/metagross.ts
  init_game();
  init_game_message();
  init_card_types();
  init_play_card_effects();
  init_prefabs();
  init_choose_cards_prompt();
  init_card_list();
  var Metagross = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Metang";
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.cardType = [L, M];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Delta Control",
          useWhenInPlay: true,
          powerType: 1 /* POKEPOWER */,
          text: "Once during your turn (before your attack), you may look at the top 4 cards of your deck, choose 1 of them, and put it into your hand. Put the 3 other cards on the bottom of your deck in any order. This power can't be used if Metagross is affected by a Special Condition."
        }
      ];
      this.attacks = [
        {
          name: "Crush and Burn",
          cost: [L, M],
          damage: 30,
          damageCalculation: "+",
          text: "You may discard as many Energy cards as you like attached to your Pok\xE9mon in play. If you do, this attack does 30 damage plus 20 more damage for each Energy card you discarded."
        }
      ];
      this.set = "DS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "11";
      this.name = "Metagross";
      this.fullName = "Metagross DS";
      this.DELTA_CONTROL_MARKER = "DELTA_CONTROL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.DELTA_CONTROL_MARKER, this);
        return state;
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.DELTA_CONTROL_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        const deckBottom = new CardList();
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: 4, sourceCard: this });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            deckTop,
            {},
            { min: 1, max: 1, allowCancel: true }
          ),
          (selected) => {
            ADD_MARKER(this.DELTA_CONTROL_MARKER, player, this);
            ABILITY_USED(player, this);
            MOVE_CARDS(store, state, deckTop, player.hand, { cards: selected, sourceCard: this });
            MOVE_CARDS(store, state, deckTop, deckBottom, { sourceCard: this });
            MOVE_CARDS(store, state, deckBottom, player.deck, { sourceCard: this });
            return state;
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.DELTA_CONTROL_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let totalEnergy = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const energyCount = cardList.cards.filter(
            (card) => card.superType === 3 /* ENERGY */
          ).length;
          totalEnergy += energyCount;
        });
        return store.prompt(
          state,
          new DiscardEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */ },
            { min: 1, max: totalEnergy, allowCancel: false }
          ),
          (transfers) => {
            if (transfers === null) {
              return state;
            }
            transfers.forEach((transfer) => {
              const source = StateUtils.getTarget(state, player, transfer.from);
              MOVE_CARDS(store, state, source, player.discard, { cards: [transfer.card], sourceCard: this });
            });
            effect.damage += transfers.length * 20;
            return state;
          }
        );
      }
      return state;
    }
  };

