  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-delta-species/mewtwo.ts
  init_game_message();
  init_pokemon_card();
  init_card_types();
  init_play_card_effects();
  init_game();
  init_prefabs();
  init_check_effects();
  var Mewtwo3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [R, M];
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.hp = 70;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Delta Switch",
          powerType: 1 /* POKEPOWER */,
          text: "Once during your turn, when you put Mewtwo from your hand onto your Bench, you may move any number of basic Energy cards attached to your Pok\xE9mon to your other Pok\xE9mon (excluding Mewtwo) in any way you like."
        }
      ];
      this.attacks = [
        {
          name: "Energy Burst",
          cost: [R, M],
          damage: 10,
          damageCalculation: "x",
          text: "Does 10 damage times the total amount of Energy attached to Mewtwo and the Defending Pok\xE9mon."
        }
      ];
      this.set = "DS";
      this.name = "Mewtwo";
      this.fullName = "Mewtwo DS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "12";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_POKEPOWER_BLOCKED(store, state, player, this)) {
          return state;
        }
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card.name === this.name) {
            blockedTo.push(target);
          }
        });
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          const blockedCards = [];
          checkProvidedEnergy.energyMap.forEach((em) => {
            if (em.provides.length === 0) {
              blockedCards.push(em.card);
            }
          });
          const blocked = [];
          blockedCards.forEach((bc) => {
            const index = cardList.cards.indexOf(bc);
            if (index !== -1 && !blocked.includes(index)) {
              blocked.push(index);
            }
          });
          if (blocked.length !== 0) {
            blockedMap.push({ source: target, blocked });
          }
        });
        return store.prompt(
          state,
          new MoveEnergyPrompt(
            effect.player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            {},
            { allowCancel: false, blockedMap, blockedTo }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
            return state;
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const playerCardList = player.active;
        const playerCheckProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, playerCardList);
        store.reduceEffect(state, playerCheckProvidedEnergyEffect);
        const opponent = effect.opponent;
        const opponentCardList = opponent.active;
        const opponentCheckProvidedEnergyEffect = new CheckProvidedEnergyEffect(
          opponent,
          opponentCardList
        );
        store.reduceEffect(state, opponentCheckProvidedEnergyEffect);
        let energies = 0;
        playerCheckProvidedEnergyEffect.energyMap.forEach((energy2) => {
          energy2.provides.forEach((e) => {
            energies++;
          });
        });
        opponentCheckProvidedEnergyEffect.energyMap.forEach((energy2) => {
          energy2.provides.forEach((e) => {
            energies++;
          });
        });
        effect.damage = 10 * energies;
      }
      return state;
    }
  };

