  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-dragon/buffer-piece.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_attack_effects();
  init_game_phase_effects();
  init_prefabs();
  init_state_utils();
  init_state();
  var BufferPiece = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "DR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "83";
      this.name = "Buffer Piece";
      this.fullName = "Buffer Piece DR";
      this.text = "Damage done to the Pok\xE9mon Buffer Piece is attached to by an opponent's attack is reduced by 20 (after applying Weakness and Resistance). At the end of your opponent's turn after you played Buffer Piece, discard Buffer Piece.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect) {
        state.players.forEach((player) => {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.tools.includes(this) && StateUtils.findOwner(state, cardList) !== effect.player) {
              if (!IS_TOOL_BLOCKED(store, state, StateUtils.findOwner(state, cardList), this)) {
                MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
              }
            }
          });
        });
      }
      if (effect instanceof PutDamageEffect && effect.target.tools.includes(this)) {
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (targetPlayer === player) {
          effect.reduceDamage(20);
        }
        return state;
      }
      return state;
    }
  };

