  var Kingdraex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Seadra";
      this.cardType = [W];
      this.hp = 150;
      this.weakness = [{ type: G }, { type: L }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Genetic Memory",
          cost: [W],
          damage: 0,
          copycatAttack: true,
          text: "Use any attack from Kingdra ex's Basic Pok\xE9mon card or Stage 1 Evolution card. (Kingdra ex doesn't have to pay for that attack's Energy cost.)"
        },
        {
          name: "Hydrocannon",
          cost: [C, C, C],
          damage: 50,
          damageCalculation: "+",
          text: "Does 50 damage plus 20 more damage for each [W] Energy attached to Kingdra ex but not used to pay for this attack's Energy cost. You can't add more than 40 damage in this way."
        }
      ];
      this.set = "DR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "92";
      this.name = "Kingdra ex";
      this.fullName = "Kingdra ex DR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const evolutionCards = [];
        for (const card of player.active.cards) {
          if (card.superType === 1 /* POKEMON */ && card !== this) {
            evolutionCards.push(card);
          }
        }
        if (evolutionCards.length === 0 || !evolutionCards.some((c) => c.attacks && c.attacks.length > 0)) {
          return state;
        }
        return COPY_ATTACK_FROM_POKEMON_LIST(store, state, effect, evolutionCards);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkCost = new CheckAttackCostEffect(player, this.attacks[1]);
        state = store.reduceEffect(state, checkCost);
        const checkEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkEnergy);
        const waterEnergy = checkEnergy.energyMap.filter((e) => e.provides.includes(3 /* WATER */));
        const extraWaterEnergy = waterEnergy.length - checkCost.cost.length;
        effect.damage += Math.min(extraWaterEnergy, 4) * 20;
      }
      return state;
    }
  };

