  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-dragon/mr-brineys-compassion.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_prefabs();
  var MrBrineysCompassion = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "DR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "87";
      this.name = "Mr. Briney's Compassion";
      this.fullName = "Mr. Briney's Compassion DR";
      this.text = "Choose 1 of your Pok\xE9mon in play (excluding Pok\xE9mon-ex). Return that Pok\xE9mon and all cards attached to it to your hand.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        let hasNonexPokemon = false;
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (!card.hasTag("ex" /* POKEMON_ex */)) {
            hasNonexPokemon = true;
            return;
          }
          if (card.hasTag("ex" /* POKEMON_ex */)) {
            blocked.push(target);
          }
        });
        if (!hasNonexPokemon) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_PICK_UP,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { allowCancel: false, blocked }
          ),
          (result) => {
            const cardList = result.length > 0 ? result[0] : null;
            if (cardList !== null) {
              MOVE_POKEMON_OFF_BOARD(store, state, cardList, {
                pokemonDestination: player.hand,
                sourceCard: this
              });
            }
          }
        );
      }
      return state;
    }
  };

