  var Rayquazaex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["ex" /* POKEMON_ex */];
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 100;
      this.weakness = [{ type: C }];
      this.resistance = [
        { type: W, value: -30 },
        { type: F, value: -30 }
      ];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Spiral Growth",
        cost: [C],
        damage: 0,
        text: "Flip a coin until you get tails. For each heads, search your discard pile for a basic Energy card and attach it to Rayquaza ex."
      }, {
        name: "Dragon Burst",
        cost: [R, L],
        damage: 40,
        damageCalculation: "x",
        text: "Discard either all [R] Energy or all [L] Energy attached to Rayquaza ex. This attack does 40 damage times the amount of [R] or [L] Energy discarded."
      }];
      this.set = "DR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "97";
      this.name = "Rayquaza ex";
      this.fullName = "Rayquaza ex DR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return FLIP_UNTIL_TAILS_AND_COUNT_HEADS(store, state, player, (heads) => {
          state = store.prompt(state, new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_ACTIVE,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: 0, max: heads }
          ), (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this, sourceEffect: this.attacks[0] });
            }
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const options = [
          {
            message: GameMessage.ALL_FIRE_ENERGIES,
            action: () => {
              const player2 = effect.player;
              const cardList = StateUtils.findCardList(state, this);
              if (!(cardList instanceof PokemonCardList))
                throw new GameError(GameMessage.INVALID_TARGET);
              const checkProvidedEnergy = new CheckProvidedEnergyEffect(player2);
              state = store.reduceEffect(state, checkProvidedEnergy);
              const cards = checkProvidedEnergy.energyMap.filter(
                (e) => e.provides.includes(2 /* FIRE */) || e.provides.includes(0 /* ANY */)
              ).map((e) => e.card);
              effect.damage = 40 * cards.length;
              const discardEnergy2 = new DiscardCardsEffect(effect, cards);
              discardEnergy2.target = cardList;
              store.reduceEffect(state, discardEnergy2);
            }
          },
          {
            message: GameMessage.ALL_LIGHTNING_ENERGIES,
            action: () => {
              const player2 = effect.player;
              const cardList = StateUtils.findCardList(state, this);
              if (!(cardList instanceof PokemonCardList))
                throw new GameError(GameMessage.INVALID_TARGET);
              const checkProvidedEnergy = new CheckProvidedEnergyEffect(player2);
              state = store.reduceEffect(state, checkProvidedEnergy);
              const cards = checkProvidedEnergy.energyMap.filter(
                (e) => e.provides.includes(4 /* LIGHTNING */) || e.provides.includes(0 /* ANY */)
              ).map((e) => e.card);
              effect.damage = 40 * cards.length;
              const discardEnergy2 = new DiscardCardsEffect(effect, cards);
              discardEnergy2.target = cardList;
              store.reduceEffect(state, discardEnergy2);
            }
          }
        ];
        return store.prompt(
          state,
          new SelectPrompt(
            player.id,
            GameMessage.CHOOSE_OPTION,
            options.map((opt) => opt.message),
            { allowCancel: false }
          ),
          (choice) => {
            const option = options[choice];
            option.action();
          }
        );
      }
      return state;
    }
  };

