  var Salamence2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Shelgon";
      this.cardType = [C];
      this.hp = 120;
      this.weakness = [{ type: C }];
      this.resistance = [{ type: R, value: -30 }, { type: F, value: -30 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Dragon Wind",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), if Salamence is your Active Pok\xE9mon, you may switch 1 of your opponent's Benched Pok\xE9mon with 1 of the Defending Pok\xE9mon. Your opponent chooses the Defending Pok\xE9mon to switch.This power can't be used if Salamence is affected by a Special Condition."
      }];
      this.attacks = [
        {
          name: "Agility",
          cost: [C, C],
          damage: 20,
          text: "Flip a coin. If heads, prevent all effects of an attack, including damage, done to Salamence during your opponent's next turn."
        },
        {
          name: "Dragon Claw",
          cost: [R, W, C, C],
          damage: 60,
          text: ""
        }
      ];
      this.set = "DR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "10";
      this.name = "Salamence";
      this.fullName = "Salamence DR";
      this.DRAGON_WIND_MARKER = "DRAGON_WIND_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (HAS_MARKER(this.DRAGON_WIND_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        if (player.active.getPokemonCard() !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (!hasBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (result) => {
          const cardList = result[0];
          if (cardList) {
            opponent.switchPokemon(cardList);
          }
        });
        ADD_MARKER(this.DRAGON_WIND_MARKER, player, this);
        ABILITY_USED(player, this);
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return FLIP_COIN_TO_PREVENT_DAMAGE_AND_EFFECTS_DURING_OPPONENTS_NEXT_TURN(store, state, effect, this);
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.DRAGON_WIND_MARKER, this);
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        REMOVE_MARKER(this.DRAGON_WIND_MARKER, player, this);
      }
      return state;
    }
  };

