  var TeamAquasWalrein = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Team Aqua's Sealeo";
      this._tags = ["Team Aqua's" /* TEAM_AQUA */];
      this.cardType = [W, D];
      this.hp = 120;
      this.weakness = [{ type: F }, { type: M }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Power Blow",
          cost: [W],
          damage: 10,
          damageCalculation: "+",
          text: "Does 10 damage plus 10 more damage for each Energy attached to Team Aqua's Walrein."
        },
        {
          name: "Hydro Reverse",
          cost: [W, W, C, C],
          damage: 50,
          damageCalculation: "+",
          text: "You may return any number of basic [W] Energy cards attached to all of your Pok\xE9mon to your hand. If you do, this attack does 50 damage plus 10 more damage for each Energy you returned."
        }
      ];
      this.set = "MA";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "6";
      this.name = "Team Aqua's Walrein";
      this.fullName = "Team Aqua's Walrein MA";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = player.active;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, cardList);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let energies = 0;
        checkProvidedEnergyEffect.energyMap.forEach((energy2) => {
          energy2.provides.forEach((e) => {
            energies++;
          });
        });
        effect.damage += 10 * energies;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        let availableTypedEnergy = 0;
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, pokemonCard, target) => {
          const blocked = [];
          let energyIndex = 0;
          cardList.cards.forEach((card) => {
            if (card.superType !== 3 /* ENERGY */) {
              return;
            }
            const isBasicWater = card instanceof EnergyCard && card.energyType === 0 /* BASIC */ && card.provides.includes(3 /* WATER */);
            if (!isBasicWater) {
              blocked.push(energyIndex);
            } else {
              availableTypedEnergy += 1;
            }
            energyIndex++;
          });
          blockedMap.push({ source: target, blocked });
        });
        if (availableTypedEnergy === 0) {
          return state;
        }
        return store.prompt(
          state,
          new DiscardEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_HAND,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
            { allowCancel: false, blockedMap }
          ),
          (transfers) => {
            if (transfers === null || transfers.length === 0) {
              return state;
            }
            for (const transfer of transfers) {
              const card = transfer.card;
              if (!(card instanceof EnergyCard) || !card.provides.includes(3 /* WATER */)) {
                throw new GameError(GameMessage.INVALID_PROMPT_RESULT);
              }
            }
            transfers.forEach((transfer) => {
              const source = StateUtils.getTarget(state, player, transfer.from);
              MOVE_CARDS(store, state, source, player.hand, { cards: [transfer.card], sourceCard: this });
            });
            effect.damage += 10 * transfers.length;
            return state;
          }
        );
      }
      return state;
    }
  };

