  var Altariaex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Swablu";
      this._tags = ["ex" /* POKEMON_ex */, "Delta Species" /* DELTA_SPECIES */];
      this.cardType = [W];
      this.hp = 100;
      this.weakness = [{ type: C }];
      this.resistance = [
        { type: G, value: -30 },
        { type: F, value: -30 }
      ];
      this.retreat = [C];
      this.powers = [
        {
          name: "Extra Boost",
          useWhenInPlay: true,
          powerType: 1 /* POKEPOWER */,
          text: "Once during your turn (before your attack), you may attach a basic Energy card from your hand to 1 of your Stage 2 Pok\xE9mon-ex. This power can't be used if Altaria ex is affected by a Special Condition."
        }
      ];
      this.attacks = [
        {
          name: "Healing Light",
          cost: [W, C, C],
          damage: 60,
          text: "Remove 1 damage counter from each of your Pok\xE9mon."
        }
      ];
      this.set = "DF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "90";
      this.name = "Altaria ex";
      this.fullName = "Altaria ex DF";
      this.EXTRA_BOOST_MARKER = "EXTRA_BOOST_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        REMOVE_MARKER(this.EXTRA_BOOST_MARKER, player, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (HAS_MARKER(this.EXTRA_BOOST_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        if (!player.hand.cards.some(
          (card) => card.superType === 3 /* ENERGY */ && card.energyType === 0 /* BASIC */
        )) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        let hasStage2Ex = false;
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card.stage !== 4 /* STAGE_2 */ && !card.hasTag("ex" /* POKEMON_ex */)) {
            blockedTo.push(target);
          } else {
            hasStage2Ex = true;
          }
        });
        if (!hasStage2Ex) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.hand,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: true, min: 1, max: 1, blockedTo }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return state;
            }
            for (const transfer of transfers) {
              ADD_MARKER(this.EXTRA_BOOST_MARKER, player, this);
              ABILITY_USED(player, this);
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARD_TO(state, transfer.card, target);
            }
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.EXTRA_BOOST_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const healEffect = new HealEffect(effect.player, cardList, 10);
          state = store.reduceEffect(state, healEffect);
        });
      }
      return state;
    }
  };

