  var CharizardStar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Star" /* STAR */, "Delta Species" /* DELTA_SPECIES */];
      this.cardType = [D];
      this.hp = 90;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Rotating Claws",
          cost: [D, C],
          damage: 20,
          text: "You may discard an Energy card attached to Charizard Star. If you do, search your discard pile for an Energy card (excluding the one you discarded) and attach it to Charizard Star."
        },
        {
          name: "Dark Swirl",
          cost: [D, D, D, D, C],
          damage: 150,
          text: "Discard all Energy cards attached to Charizard Star and discard the top 3 cards from your opponent's deck."
        }
      ];
      this.set = "DF";
      this.setNumber = "100";
      this.cardImage = "assets/cardback.png";
      this.name = "Charizard Star";
      this.fullName = "Charizard Star DF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        CONFIRMATION_PROMPT(
          store,
          state,
          player,
          (result) => {
            if (result) {
              DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1);
              if (player.discard.cards.some((card) => card.superType === 3 /* ENERGY */)) {
                state = store.prompt(
                  state,
                  new AttachEnergyPrompt(
                    player.id,
                    GameMessage.ATTACH_ENERGY_TO_ACTIVE,
                    player.discard,
                    2 /* BOTTOM_PLAYER */,
                    [1 /* ACTIVE */],
                    { superType: 3 /* ENERGY */ },
                    { allowCancel: false, min: 1, max: 1 }
                  ),
                  (transfers) => {
                    transfers = transfers || [];
                    if (transfers.length === 0) {
                      return;
                    }
                    for (const transfer of transfers) {
                      const target = StateUtils.getTarget(state, player, transfer.to);
                      MOVE_CARDS(store, state, player.discard, target, {
                        cards: [transfer.card],
                        sourceCard: this,
                        sourceEffect: this.attacks[0]
                      });
                    }
                  }
                );
              }
            }
          },
          GameMessage.WANT_TO_USE_EFFECT_OF_ATTACK
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const opponent = effect.opponent;
        DISCARD_ALL_ENERGY_FROM_POKEMON(store, state, effect, this);
        MOVE_CARDS(store, state, opponent.deck, opponent.discard, {
          count: 3,
          sourceCard: this,
          sourceEffect: this.attacks[1]
        });
      }
      return state;
    }
  };

