  var Cloyster2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Shelder";
      this.cardType = [F];
      this.hp = 70;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Solid Shell",
          powerType: 0 /* POKEBODY */,
          text: "Prevent all effects of attacks, including damage, done by your opponent's Pok\xE9mon to each of your Benched Pok\xE9mon that has delta on its card."
        }
      ];
      this.attacks = [
        {
          name: "Grind",
          cost: [F],
          damage: 10,
          damageCalculation: "+",
          text: "Does 10 damage plus 10 more damage for each Energy attached to Cloyster."
        }
      ];
      this.set = "DF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "14";
      this.name = "Cloyster";
      this.fullName = "Cloyster DF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkProvidedEnergy);
        const damagePerEnergy = 10;
        effect.damage += checkProvidedEnergy.energyMap.length * damagePerEnergy;
      }
      if (effect instanceof PutDamageEffect || effect instanceof PutCountersEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (effect.target === player.active || effect.target === opponent.active || !effect.target.getPokemonCard()?.hasTag("Delta Species" /* DELTA_SPECIES */)) {
          return state;
        }
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        let isCloysterInPlay = false;
        targetPlayer.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            isCloysterInPlay = true;
          }
        });
        if (!isCloysterInPlay) {
          return state;
        }
        if (IS_POKEBODY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.preventDefault = true;
      }
      return state;
    }
  };

