  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-dragon-frontiers/dragonite-ex.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
