  init_attack_effects2();
  var Dragoniteex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Dragonair";
      this._tags = ["ex" /* POKEMON_ex */, "Delta Species" /* DELTA_SPECIES */];
      this.cardType = [G];
      this.hp = 150;
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Deafen",
          cost: [C, C],
          damage: 40,
          text: "Your opponent can't play any Trainer cards (except for Supporter cards) from his or her hand during your opponent's next turn."
        },
        {
          name: "Dragon Roar",
          cost: [G, G, C, C],
          damage: 0,
          text: "Put 8 damage counters on the Defending Pok\xE9mon. If that Pok\xE9mon would be Knocked Out by this attack, put any damage counters not necessary to Knock Out the Defending Pok\xE9mon on your opponent's Benched Pok\xE9mon in any way you like."
        }
      ];
      this.set = "DF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "91";
      this.name = "Dragonite ex";
      this.fullName = "Dragonite ex DF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return OPPONENT_CANNOT_PLAY_CARDS(store, state, effect, this, { item: true, tool: true, stadium: true });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const opponent = effect.opponent;
        const defending = opponent.active;
        const checkHpEffect = new CheckHpEffect(opponent, defending);
        store.reduceEffect(state, checkHpEffect);
        const currentDamage = defending.damage;
        const damageToKO = Math.max(0, checkHpEffect.hp - currentDamage);
        const damageToPlace = Math.min(80, damageToKO);
        if (damageToPlace > 0) {
          PUT_X_DAMAGE_COUNTERS_ON_YOUR_OPPONENTS_ACTIVE_POKEMON(
            damageToPlace / 10,
            store,
            state,
            effect
          );
        }
        const remainingDamage = 80 - damageToPlace;
        if (remainingDamage > 0) {
          const opponentBench = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
          if (opponentBench === 0) {
            return state;
          }
          const maxAllowedDamage = [];
          opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
            maxAllowedDamage.push({ target, damage: card.hp + (cardList.damage || 0) });
          });
          return store.prompt(state, new PutDamagePrompt(
            effect.player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            remainingDamage,
            maxAllowedDamage,
            { allowCancel: false }
          ), (targets) => {
            const results = targets || [];
            const player = effect.player;
            for (const result of results) {
              const target = StateUtils.getTarget(state, player, result.target);
              const putCountersEffect = new PutCountersEffect(effect, result.damage);
              putCountersEffect.target = target;
              store.reduceEffect(state, putCountersEffect);
            }
          });
        }
      }
      return state;
    }
  };

