  var MrStonesProject = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "DF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "77";
      this.name = "Mr. Stone's Project";
      this.fullName = "Mr. Stone's Project DF";
      this.text = "Search your deck for up to 2 Basic cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward. Or, search your discard pile for up to 2 Basic cards, show them to your opponent, and put them into your hand.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        const options = [
          {
            message: GameMessage.CHOOSE_ENERGY_FROM_DECK,
            action: () => {
              let cards = [];
              store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_HAND,
                  player.deck,
                  { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
                  { min: 0, max: 2, allowCancel: false }
                ),
                (selected) => {
                  cards = selected || [];
                  MOVE_CARDS(store, state, player.deck, player.hand, {
                    cards,
                    sourceCard: this
                  });
                  if (cards.length > 0) {
                    store.prompt(
                      state,
                      new ShowCardsPrompt(
                        opponent.id,
                        GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                        cards
                      ),
                      () => {
                      }
                    );
                  }
                  store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                    player.deck.applyOrder(order);
                  });
                }
              );
              return state;
            }
          },
          {
            message: GameMessage.CHOOSE_ENERGY_FROM_DISCARD,
            action: () => {
              let cards = [];
              store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_HAND,
                  player.discard,
                  { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
                  { min: 0, max: 2, allowCancel: false }
                ),
                (selected) => {
                  cards = selected || [];
                  MOVE_CARDS(store, state, player.discard, player.hand, {
                    cards,
                    sourceCard: this
                  });
                  if (cards.length > 0) {
                    store.prompt(
                      state,
                      new ShowCardsPrompt(
                        opponent.id,
                        GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                        cards
                      ),
                      () => {
                      }
                    );
                  }
                }
              );
              return state;
            }
          }
        ];
        return store.prompt(
          state,
          new SelectPrompt(
            player.id,
            GameMessage.CHOOSE_OPTION,
            options.map((opt) => opt.message),
            { allowCancel: false }
          ),
          (choice) => {
            const option = options[choice];
            option.action();
          }
        );
      }
      return state;
    }
  };

