  var Quagsire = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Wooper";
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.cardType = [G];
      this.hp = 80;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Dig Up",
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, when you play Quagsire from your hand to evolve 1 of your Pok\xE9mon, you may search your discard pile for up to 2 Pok\xE9mon Tool cards, show them to your opponent, and put them into your hand."
        }
      ];
      this.attacks = [
        {
          name: "Pump Out",
          cost: [G, C, C],
          damage: 50,
          damageCalculation: "+",
          text: "If Quagsire has a Pok\xE9mon Tool card attached to it, this attack does 50 damage plus 20 more damage."
        }
      ];
      this.set = "DF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "21";
      this.name = "Quagsire";
      this.fullName = "Quagsire DF";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this)) {
        const player = effect.player;
        const blocked = [];
        player.discard.cards.forEach((card, index) => {
          if (!(card instanceof TrainerCard && card.trainerType === 3 /* TOOL */)) {
            blocked.push(index);
          }
        });
        if (blocked.length === player.discard.cards.length) {
          return state;
        }
        CONFIRMATION_PROMPT(
          store,
          state,
          effect.player,
          (result) => {
            if (!result) {
              return state;
            }
            SEARCH_DISCARD_PILE_FOR_CARDS_TO_HAND(
              store,
              state,
              player,
              this,
              { superType: 2 /* TRAINER */ },
              { min: 0, max: 2, blocked }
            );
          },
          GameMessage.WANT_TO_USE_ABILITY
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        if (effect.source.tools.length > 0) {
          effect.damage += 20;
        }
      }
      return state;
    }
  };

