  var Swablu = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.cardType = [W];
      this.hp = 40;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Splash About",
          cost: [W],
          damage: 10,
          damageCalculation: "+",
          text: "If Swablu has less Energy attached to it than the Defending Pok\xE9mon, this attack does 10 damage plus 10 more damage."
        }
      ];
      this.set = "DF";
      this.name = "Swablu";
      this.fullName = "Swablu DF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "65";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        const playerProvidedEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, playerProvidedEnergy);
        const playerEnergyCount = playerProvidedEnergy.energyMap.reduce(
          (left, p) => left + p.provides.length,
          0
        );
        const opponentProvidedEnergy = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, opponentProvidedEnergy);
        const opponentEnergyCount = opponentProvidedEnergy.energyMap.reduce(
          (left, p) => left + p.provides.length,
          0
        );
        if (playerEnergyCount < opponentEnergyCount) {
          effect.damage += 10;
        }
      }
      return state;
    }
  };

