  init_check_effects();
  var Tropius = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.cardType = [M];
      this.hp = 70;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Tropical Heal",
          powerType: 1 /* POKEPOWER */,
          text: "Once during your turn, when you put Tropius from your hand onto your Bench, you may remove all Special Conditions, Imprison markers, and Shock-wave markers from your Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Grind",
          cost: [M],
          damage: 10,
          damageCalculation: "x",
          text: "Does 10 damage times the amount of Energy attached to Tropius."
        }
      ];
      this.set = "DF";
      this.name = "Tropius";
      this.fullName = "Tropius DF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "23";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_POKEPOWER_BLOCKED(store, state, player, this)) {
          return state;
        }
        CONFIRMATION_PROMPT(store, state, player, (result) => {
          if (result) {
            const powerEffect = new PowerEffect(player, this.powers[0], this);
            store.reduceEffect(state, powerEffect);
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              cardList.removeSpecialCondition(1 /* CONFUSED */);
              cardList.removeSpecialCondition(2 /* ASLEEP */);
              cardList.removeSpecialCondition(3 /* POISONED */);
              cardList.removeSpecialCondition(4 /* BURNED */);
              cardList.removeSpecialCondition(0 /* PARALYZED */);
              cardList.marker.removeMarker("IMPRISON_MARKER");
              cardList.marker.removeMarker("SHOCK_WAVE_MARKER");
            });
            ABILITY_USED(player, this);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = player.active;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, cardList);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        effect.damage = 10 * checkProvidedEnergyEffect.energyMap.reduce((left, p) => left + p.provides.length, 0);
      }
      return state;
    }
  };

