  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-unseen-forces/aipom.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_phase_effects();
  init_attack_effects2();
  init_prefabs();
  var Aipom = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 50;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [{
        name: "Snappy Move",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), if Aipom is on your Bench, you may draw a card. Then, discard all cards attached to Aipom and put Aipom on the bottom of your deck. You can't use more than 1 Snappy Move Pok\xE9-Power each turn."
      }];
      this.attacks = [{
        name: "Snap tail",
        cost: [C],
        damage: 0,
        text: "Choose 1 of your opponent's Pok\xE9mon. This attack does 10 damage to that Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.set = "UF";
      this.name = "Aipom";
      this.fullName = "Aipom UF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "34";
      this.SNAPPY_MOVE_MARKER = "SNAPPY_MOVE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && HAS_MARKER(this.SNAPPY_MOVE_MARKER, effect.player)) {
        effect.player.marker.removeMarker(this.SNAPPY_MOVE_MARKER);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const benchIndex = player.bench.indexOf(cardList);
        if (benchIndex === -1) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (HAS_MARKER(this.SNAPPY_MOVE_MARKER, player)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const aipomSlot = player.bench[benchIndex];
        const aipomCard = aipomSlot.getPokemonCard();
        if (!aipomCard) {
          return state;
        }
        ADD_MARKER(this.SNAPPY_MOVE_MARKER, player, this);
        ABILITY_USED(player, this);
        DRAW_CARDS(store, state, player, 1);
        const pokemons = aipomSlot.getPokemons();
        const otherCards = aipomSlot.cards.filter(
          (card) => !(card instanceof PokemonCard) && !pokemons.includes(card) && (!aipomSlot.tools || !aipomSlot.tools.includes(card))
        );
        const tools = [...aipomSlot.tools];
        if (tools.length > 0) {
          for (const tool of tools) {
            MOVE_CARDS(store, state, aipomSlot, player.discard, { cards: [tool], sourceCard: this });
          }
        }
        if (otherCards.length > 0) {
          MOVE_CARDS(store, state, aipomSlot, player.discard, { cards: otherCards });
        }
        if (pokemons.length > 0) {
          MOVE_CARDS(store, state, aipomSlot, player.deck, { cards: pokemons, toBottom: true });
        }
        aipomSlot.clearEffects();
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_POKEMON(10, effect, store, state);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-unseen-forces/ariados.ts
  init_game();
  init_game_phase_effects();
  init_prefabs();
  var Ariados = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Spinarak";
      this.cardType = [G];
      this.hp = 70;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Reactive Poison",
          cost: [C],
          damage: 10,
          damageCalculation: "+",
          text: "Does 10 damage plus 30 more damage for each Special Condition affecting the Defending Pok\xE9mon."
        },
        {
          name: "Spider Trap",
          cost: [G],
          damage: 0,
          text: "The Defending Pok\xE9mon is now Asleep and Poisoned. Before applying this effect, you may switch 1 of your opponent's Benched Pok\xE9mon with 1 of the Defending Pok\xE9mon. If you do, the new Defending Pok\xE9mon is now Asleep and Poisoned. Your opponent chooses the Defending Pok\xE9mon to switch."
        }
      ];
      this.set = "UF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "2";
      this.name = "Ariados";
      this.fullName = "Ariados UF";
      this.usedSpiderTrap = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const oppActive = opponent.active;
        oppActive.specialConditions.forEach((c) => {
          effect.damage += 30;
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedSpiderTrap = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedSpiderTrap) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const bench = opponent.bench.filter((bench2) => bench2.cards.length > 0);
        if (bench.length === 0) {
          ADD_POISON_TO_PLAYER_ACTIVE(store, state, opponent, this);
          ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, opponent, this);
          this.usedSpiderTrap = false;
          return state;
        }
        CONFIRMATION_PROMPT(store, state, player, (result) => {
          if (!result) {
            ADD_POISON_TO_PLAYER_ACTIVE(store, state, opponent, this);
            ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, opponent, this);
            this.usedSpiderTrap = false;
            return state;
          } else {
            store.prompt(state, new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON_TO_SWITCH,
              1 /* TOP_PLAYER */,
              [2 /* BENCH */],
              { allowCancel: false }
            ), (result2) => {
              const cardList = result2[0];
              opponent.switchPokemon(cardList);
              ADD_POISON_TO_PLAYER_ACTIVE(store, state, opponent, this);
              ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, opponent, this);
              this.usedSpiderTrap = false;
            });
          }
        }, GameMessage.WANT_TO_SWITCH_POKEMON);
      }
      return state;
    }
  };

