  function* useTearAway(next, store, state, effect) {
    const player = effect.player;
    BLOCK_IF_HAS_SPECIAL_CONDITION(player, effect.card);
    let pokemonsWithTool = 0;
    const blocked = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target2) => {
      if (cardList.tools.length > 0) {
        pokemonsWithTool += 1;
      } else {
        blocked.push(target2);
      }
    });
    effect.preventDefault = true;
    const max = Math.min(1, pokemonsWithTool);
    let targets = [];
    yield store.prompt(state, new ChoosePokemonPrompt(
      player.id,
      GameMessage.CHOOSE_POKEMON,
      2 /* BOTTOM_PLAYER */,
      [1 /* ACTIVE */, 2 /* BENCH */],
      { min: 1, max, allowCancel: true, blocked }
    ), (results) => {
      targets = results || [];
      next();
    });
    if (targets.length === 0) {
      return state;
    }
    const target = targets[0];
    const owner = StateUtils.findOwner(state, target);
    if (target.tools.length > 0) {
      if (target.tools.length > 1) {
        const toolsList = new CardList();
        toolsList.cards = [...target.tools];
        let selected = [];
        yield store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_TOOL,
          toolsList,
          {},
          { min: 1, max: 1, allowCancel: false }
        ), (results) => {
          selected = results || [];
          next();
        });
        if (selected && selected.length > 0) {
          MOVE_CARDS(store, state, target, owner.hand, { cards: [selected[0]], sourceCard: effect.card });
        }
      } else {
        MOVE_CARDS(store, state, target, owner.hand, { cards: [target.tools[0]], sourceCard: effect.card });
      }
    }
    return state;
  }
