  var UnownE = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 60;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Shuffle",
        powerType: 1 /* POKEPOWER */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may search your deck for another Unown and switch it with Unown. (Any cards attached to Unown, damage counters, Special Conditions, and effects on it are now on the new Pok\xE9mon.) If you do, put Unown on top of your deck. Shuffle your deck afterward. You can't use more than 1 Shuffle Pok\xE9-Power each turn."
      }];
      this.attacks = [{
        name: "Hidden Power",
        cost: [C],
        damage: 0,
        text: "If your opponent's Bench isn't full, look at his or her hand. Choose 1 Basic Pok\xE9mon you find there and put it onto your opponent's Bench. Then, switch it with the Defending Pok\xE9mon. Your opponent chooses the Defending Pok\xE9mon to switch."
      }];
      this.set = "UF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "E";
      this.name = "Unown";
      this.fullName = "Unown UF";
      this.SHUFFLE_MARKER = "SHUFFLE_MARKER";
    }
    reduceEffect(store, state, effect) {
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.SHUFFLE_MARKER, this);
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const targetCardList = StateUtils.findCardList(state, this);
        if (!(targetCardList instanceof PokemonCardList)) {
          throw new GameError(GameMessage.INVALID_TARGET);
        }
        if (HAS_MARKER(this.SHUFFLE_MARKER, player)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && card.name !== "Unown") {
            blocked.push(index);
          }
        });
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          player.deck,
          { superType: 1 /* POKEMON */ },
          { min: 1, max: 1, allowCancel: true, blocked }
        ), (selection) => {
          if (!selection?.length) {
            return state;
          }
          const pokemonCard = selection[0];
          if (!(pokemonCard instanceof PokemonCard)) {
            return state;
          }
          store.log(state, "LOG_PLAYER_TRANSFORMS_INTO_POKEMON" /* LOG_PLAYER_TRANSFORMS_INTO_POKEMON */, {
            name: player.name,
            pokemon: this.name,
            card: pokemonCard.name,
            effect: effect.power.name
          });
          MOVE_CARDS(store, state, player.deck, targetCardList, { cards: [pokemonCard], sourceCard: this });
          MOVE_CARDS(store, state, targetCardList, player.deck, { cards: [this], sourceCard: this });
          SHUFFLE_DECK(store, state, player);
          ADD_MARKER(this.SHUFFLE_MARKER, player, this);
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const slots2 = opponent.bench.filter((b) => b.cards.length === 0);
        if (slots2.length === 0) {
          return state;
        }
        if (opponent.hand.cards.length === 0) {
          return state;
        }
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_BASIC_POKEMON_TO_BENCH,
          opponent.hand,
          { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
          { min: 0, max: 1, allowCancel: true }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length === 0) {
            return state;
          }
          cards.forEach((card, index) => {
            MOVE_CARDS(store, state, opponent.hand, slots2[index], { cards: [card], sourceCard: this });
            slots2[index].pokemonPlayedTurn = state.turn;
            opponent.switchPokemon(slots2[index]);
          });
        });
      }
      return state;
    }
  };

