  init_trainer_card();
  init_card_types();
  init_play_card_effects();
  init_choose_cards_prompt();
  init_shuffle_prompt();
  init_prefabs();
  function* playCard40(next, store, state, self, effect) {
    const player = effect.player;
    let energyInDiscard = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      const isEnergy = c.superType === 3 /* ENERGY */;
      if (isEnergy) {
        energyInDiscard += 1;
      } else {
        blocked.push(index);
      }
    });
    if (energyInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let coinResult = false;
    yield COIN_FLIP_PROMPT(store, state, player, (result) => {
      coinResult = result;
      next();
    });
    if (!coinResult) {
      return state;
    }
    const number = Math.min(2, energyInDiscard);
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        { superType: 3 /* ENERGY */ },
        { min: number, max: number, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var EnergyCharge = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "DX";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "86";
      this.name = "Energy Charge";
      this.fullName = "Energy Charge DX";
      this.text = "Flip a coin. If heads, search your discard pile for 2 Energy cards (1 if there is only 1), show them to your opponent, and shuffle them into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard40(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

