  var LumBerry = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "EM";
      this.name = "Lum Berry";
      this.fullName = "Lum Berry EM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "78";
      this.text = "At the end of each turn, if the Pok\xE9mon this card is attached to is affected by any Special Conditions, it recovers from all of them, and discard this card.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        if (player.active.cards.includes(this) && player.active.specialConditions.length > 0) {
          player.active.specialConditions.slice().forEach((condition) => {
            player.active.removeSpecialCondition(condition);
          });
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, index) => {
            if (cardList.tools && cardList.tools.includes(this)) {
              MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
            }
          });
        }
        if (opponent.active.cards.includes(this) && opponent.active.specialConditions.length > 0) {
          opponent.active.specialConditions.slice().forEach((condition) => {
            opponent.active.removeSpecialCondition(condition);
          });
          opponent.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, index) => {
            if (cardList.tools && cardList.tools.includes(this)) {
              MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
            }
          });
        }
      }
      return state;
    }
  };

