  var Medichamex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [F];
      this.hp = 110;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Wise Aura",
          powerType: 2 /* ABILITY */,
          text: "As long as Medicham ex is your Active Pok\xE9mon, each Pok\xE9mon (excluding Pok\xE9mon-ex) (both yours and your opponent's) can't use any Pok\xE9-Powers."
        }
      ];
      this.attacks = [
        {
          name: "Pure Power",
          cost: [C, C],
          damage: 0,
          text: "Put 3 damage counters on your opponent's Pok\xE9mon in any way you like."
        },
        {
          name: "Sky Kick",
          cost: [F, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "If the Defending Pok\xE9mon has Fighting Resistance, this attack does 60 damage plus 40 more damage."
        }
      ];
      this.set = "EM";
      this.setNumber = "95";
      this.cardImage = "assets/cardback.png";
      this.name = "Medicham ex";
      this.fullName = "Medicham ex EM";
      this.evolvesFrom = "Meditite";
    }
    reduceEffect(store, state, effect) {
      HANDLE_ABILITY_BLOCK(
        effect,
        ({ player, card }) => {
          if (!IS_ABILITY_LOCKER_ACTIVE(state, player, this)) {
            return false;
          }
          if (card.hasTag("ex" /* POKEMON_ex */)) {
            return false;
          }
          const opponent = StateUtils.getOpponent(state, player);
          const lockerOwner = player.active.getPokemonCard() === this ? player : opponent;
          if (!CAN_APPLY_LOCKER_ABILITY(store, state, lockerOwner, this, this.powers[0])) {
            return false;
          }
          return CAN_APPLY_LOCK_TO_TARGET(store, state, lockerOwner, this, this.powers[0], card);
        },
        {
          powerTypes: POKEPOWER_TYPES,
          error: GameMessage.BLOCKED_BY_ABILITY
        }
      );
      if (WAS_ATTACK_USED(effect, 0, this)) {
        PUT_X_DAMAGE_COUNTERS_IN_ANY_WAY_YOU_LIKE(3, store, state, effect);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const opponent = effect.opponent;
        const defendingPokemon = opponent.active.getPokemonCard();
        if (defendingPokemon && defendingPokemon.resistance) {
          const fightingResistance = defendingPokemon.resistance.find(
            (r) => r.type === 6 /* FIGHTING */
          );
          if (fightingResistance) {
            effect.damage += 40;
          }
        }
      }
      return state;
    }
  };

