  init_game();
  init_game_message();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_choose_cards_prompt();
  init_shuffle_prompt();
  init_prefabs();
  var PokemonRetriever = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "TRR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "84";
      this.name = "Pok\xE9mon Retriever";
      this.fullName = "Pok\xE9mon Retriever TRR";
      this.text = "Search your discard pile for Basic Pok\xE9mon and Evolution cards. You may either show 1 Basic Pok\xE9mon or Evolution card to your opponent and put it into your hand, or show a combination of 3 Basic Pok\xE9mon or Evolution cards to your opponent and shuffle them into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        let pokemonInDiscard = 0;
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          const isPokemon = c instanceof PokemonCard;
          if (isPokemon) {
            pokemonInDiscard += 1;
          } else {
            blocked.push(index);
          }
        });
        if (pokemonInDiscard === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        const options = [
          {
            message: GameMessage.CHOOSE_CARD_TO_DECK,
            action: () => {
              let cards = [];
              store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_DECK,
                  player.discard,
                  { superType: 1 /* POKEMON */ },
                  { min: Math.min(pokemonInDiscard, 3), max: 3, allowCancel: false, blocked }
                ),
                (selected) => {
                  cards = selected || [];
                  MOVE_CARDS(store, state, player.discard, player.deck, {
                    cards,
                    sourceCard: this
                  });
                  return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                    player.deck.applyOrder(order);
                  });
                }
              );
            }
          },
          {
            message: GameMessage.CHOOSE_CARD_TO_HAND,
            action: () => {
              let cards = [];
              store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_HAND,
                  player.discard,
                  { superType: 1 /* POKEMON */ },
                  { min: 1, max: 1, allowCancel: false, blocked }
                ),
                (selected) => {
                  cards = selected || [];
                  MOVE_CARDS(store, state, player.discard, player.hand, {
                    cards,
                    sourceCard: this
                  });
                  return state;
                }
              );
            }
          }
        ];
        return store.prompt(
          state,
          new SelectPrompt(
            player.id,
            GameMessage.CHOOSE_OPTION,
            options.map((opt) => opt.message),
            { allowCancel: false }
          ),
          (choice) => {
            const option = options[choice];
            option.action();
          }
        );
      }
      return state;
    }
  };

