  var REnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [9 /* COLORLESS */];
      this.energyType = 1 /* SPECIAL */;
      this.set = "TRR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "95";
      this.name = "R Energy";
      this.fullName = "R Energy TRR";
      this.text = "R Energy can be attached only to a Pok\xE9mon that has Dark or Rocket's in its name. While in play, R Energy provides 2 [D] Energy. (Doesn't count as a basic Energy card.) If the Pok\xE9mon R Energy is attached to attacks, the attack does 10 more damage to the Active Pok\xE9mon (before applying Weakness and Resistance). When your turn ends, discard R Energy.";
      this.R_MARKER = "R_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.energyCard === this) {
        if (!effect.target.getPokemonCard()?.hasTag("Dark" /* DARK */) && !effect.target.getPokemonCard()?.hasTag("Rocket's" /* ROCKETS */)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        ADD_MARKER(this.R_MARKER, effect.player, this);
      }
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        const attachedTo = effect.source.getPokemonCard();
        if (!!attachedTo && attachedTo instanceof PokemonCard) {
          effect.energyMap.push({ card: this, provides: [7 /* DARK */, 7 /* DARK */] });
        }
        return state;
      }
      if (effect instanceof BetweenTurnsEffect && effect.player.marker.hasMarker(this.R_MARKER, this)) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.cards.includes(this)) {
            MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
            REMOVE_MARKER(this.R_MARKER, effect.player, this);
          }
        });
      }
      if (effect instanceof DealDamageEffect) {
        if (effect.source.cards.includes(this)) {
          const player = effect.player;
          const opponent = StateUtils.getOpponent(state, player);
          if (effect.target !== opponent.active) {
            return state;
          }
          effect.damage += 10;
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-team-rocket-returns/rockets-admin.ts
  init_game();
