  init_game();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_prefabs();
  function* playCard41(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      const isSupporter = c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */;
      const isBasicEnergy = c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
      const isTool = c instanceof TrainerCard && c.trainerType === 3 /* TOOL */;
      if (!isSupporter && !isBasicEnergy && !isTool) {
        blocked.push(index);
      }
    });
    const maxSupporters = 1;
    const maxEnergies = 1;
    const maxTools = 1;
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        {},
        { min: 0, max: 3, allowCancel: true, blocked, maxSupporters, maxEnergies, maxTools }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [self], sourceCard: self });
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var Castaway = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "72";
      this.name = "Castaway";
      this.fullName = "Castaway CG";
      this.text = "Search your deck for a Supporter card, a Pok\xE9mon Tool card, and a basic Energy card. Show them to your opponent, and put them into your hand. Shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard41(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

