  var Absolex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [D];
      this.hp = 100;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -30 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Cursed Eyes",
          powerType: 1 /* POKEPOWER */,
          text: "Once during your turn, when you put Absol ex from your hand onto your Bench, you may move 3 damage counters from 1 of your opponent's Pok\xE9mon to another of his or her Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Psychic Pulse",
          cost: [D, C],
          damage: 30,
          text: "Does 10 damage to each of your opponent's Benched Pok\xE9mon that has any damage counters on it. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "PK";
      this.name = "Absol ex";
      this.fullName = "Absol ex PK";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "92";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_POKEPOWER_BLOCKED(store, state, player, this)) {
          return state;
        }
        const maxAllowedDamage = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(opponent, cardList);
          store.reduceEffect(state, checkHpEffect);
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        return store.prompt(
          state,
          new MoveDamagePrompt(
            effect.player.id,
            GameMessage.MOVE_DAMAGE,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            maxAllowedDamage,
            {
              min: 0,
              max: 3,
              allowCancel: true,
              singleSourceTarget: true,
              singleDestinationTarget: true
            }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            const powerEffect = new PowerEffect(player, this.powers[0], this);
            store.reduceEffect(state, powerEffect);
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              const canApplyAbilityToSource = new EffectOfAbilityEffect(
                player,
                this.powers[0],
                this,
                source
              );
              store.reduceEffect(state, canApplyAbilityToSource);
              if (canApplyAbilityToSource.target && source.damage >= 10) {
                source.damage -= 10;
                const canApplyAbilityToTarget = new EffectOfAbilityEffect(
                  player,
                  this.powers[0],
                  this,
                  target
                );
                store.reduceEffect(state, canApplyAbilityToTarget);
                if (canApplyAbilityToTarget.target) {
                  target.damage += 10;
                }
              }
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        const benched = opponent.bench.filter((b) => b.cards.length > 0);
        benched.forEach((target) => {
          if (target.damage !== 0) {
            const damageEffect = new PutDamageEffect(effect, 10);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          }
        });
      }
      return state;
    }
  };

