  var BattleFrontier = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "PK";
      this.name = "Battle Frontier";
      this.fullName = "Battle Frontier PK";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "71";
      this.text = "Each player's [C] Evolved Pok\xE9mon, [D] Evolved Pok\xE9mon, and [M] Evolved Pok\xE9mon can't use any Pok\xE9-Powers or Pok\xE9-Bodies.";
    }
    reduceEffect(store, state, effect) {
      HANDLE_ABILITY_BLOCK(
        effect,
        ({ card }) => {
          if (StateUtils.getStadiumCard(state) !== this) {
            return false;
          }
          try {
            const cardList = StateUtils.findCardList(state, card);
            if (!(cardList instanceof PokemonCardList)) {
              return false;
            }
            const owner = StateUtils.findOwner(state, cardList);
            if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, cardList)) {
              return false;
            }
            if (cardList.getPokemons().length <= 1) {
              return false;
            }
            const checkPokemonType = new CheckPokemonTypeEffect(cardList);
            store.reduceEffect(state, checkPokemonType);
            const cardTypes = checkPokemonType.cardTypes;
            return cardTypes.includes(9 /* COLORLESS */) || cardTypes.includes(7 /* DARK */) || cardTypes.includes(8 /* METAL */);
          } catch {
            return false;
          }
        },
        {
          powerTypes: POKEPOWER_AND_BODY_TYPES,
          error: GameMessage.BLOCKED_BY_EFFECT
        }
      );
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

