  var PhoebesStadium = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "PK";
      this.name = "Phoebe's Stadium";
      this.fullName = "Phoebe's Stadium PK";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "79";
      this.text = "Each player pays [C][C] less to retreat his or her [P] Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect && StateUtils.getStadiumCard(state) === this && state.phase !== 3 /* ATTACK */) {
        const checkPokemonTypeEffect = new CheckPokemonTypeEffect(effect.target);
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, effect.player, effect.target)) {
          return state;
        }
        store.reduceEffect(state, checkPokemonTypeEffect);
        if (checkPokemonTypeEffect.cardTypes.includes(5 /* PSYCHIC */)) {
          for (let i = 0; i < 2; i++) {
            const colorlessIndex = effect.cost.lastIndexOf(9 /* COLORLESS */);
            if (colorlessIndex === -1) {
              break;
            }
            effect.cost.splice(colorlessIndex, 1);
          }
        }
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

