  var BLOCKED_CONDITIONS = [
    2 /* ASLEEP */,
    1 /* CONFUSED */,
    0 /* PARALYZED */
  ];
  var SidneysStadium = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "PK";
      this.name = "Sidney's Stadium";
      this.fullName = "Sidney's Stadium PK";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "82";
      this.text = "Each player's [D] Pok\xE9mon can't be Asleep, Confused, or Paralyzed.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckTableStateEffect && StateUtils.getStadiumCard(state) === this) {
        state.players.forEach((player) => {
          if (IS_STADIUM_EFFECT_BLOCKED(store, state, player, player.active)) {
            return;
          }
          if (!BLOCKED_CONDITIONS.some((c) => player.active.specialConditions.includes(c))) {
            return;
          }
          const checkPokemonType = new CheckPokemonTypeEffect(player.active);
          store.reduceEffect(state, checkPokemonType);
          if (checkPokemonType.cardTypes.includes(7 /* DARK */)) {
            BLOCKED_CONDITIONS.forEach((c) => player.active.removeSpecialCondition(c));
          }
        });
        return state;
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

