  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-firered-leafgreen/blastoise-ex.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attach_energy_prompt();
  init_play_card_effects();
  init_prefabs();
  init_attack_effects();
  var Blastoiseex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Wartortle";
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [W];
      this.hp = 150;
      this.weakness = [{ type: L }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Energy Rain",
          useWhenInPlay: true,
          powerType: 1 /* POKEPOWER */,
          text: "As often as you like during your turn (before your attack), you may attach a [W] Energy card from your hand to 1 of your Pok\xE9mon. Put 1 damage counter on that Pok\xE9mon. This power can't be used if Blastoise ex is affected by a Special Condition."
        }
      ];
      this.attacks = [
        {
          name: "Hyper Whirlpool",
          cost: [W, W, W, C],
          damage: 80,
          text: "Flip a coin until you get tails. For each heads, your opponent discards an Energy card attached to the Defending Pok\xE9mon."
        }
      ];
      this.set = "RG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "104";
      this.name = "Blastoise ex";
      this.fullName = "Blastoise ex RG";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(3 /* WATER */);
        });
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.hand,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
            { allowCancel: false }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              const energyCard = transfer.card;
              const attachEnergyEffect = new AttachEnergyEffect(player, energyCard, target);
              store.reduceEffect(state, attachEnergyEffect);
              target.damage += 10;
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const active = opponent.active;
        if (!active.cards.some((c) => c.superType === 3 /* ENERGY */)) {
          return state;
        }
        return FLIP_UNTIL_TAILS_AND_COUNT_HEADS(store, state, player, (heads) => {
          const currentOpponent = StateUtils.getOpponent(state, player);
          const currentActive = currentOpponent.active;
          const currentEnergyCards = currentActive.cards.filter(
            (c) => c.superType === 3 /* ENERGY */
          );
          const maxToDiscard = Math.min(heads, currentEnergyCards.length);
          if (maxToDiscard === 0) {
            return;
          }
          state = store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
              currentActive,
              { superType: 3 /* ENERGY */ },
              { min: maxToDiscard, max: maxToDiscard, allowCancel: false }
            ),
            (selected) => {
              const cards = selected || [];
              if (cards.length > 0) {
                const discardEnergy2 = new DiscardCardsEffect(effect, cards);
                discardEnergy2.target = currentActive;
                state = store.reduceEffect(state, discardEnergy2);
              }
            }
          );
        });
      }
      return state;
    }
  };

