  init_game();
  init_check_effects();
  init_prefabs();
  var Ditto4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 60;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Form Variation",
          powerType: 1 /* POKEPOWER */,
          useWhenInPlay: true,
          text: "Once during your turn (before your attack), you may search your discard pile for a Basic Pok\xE9mon (excluding Pok\xE9mon-ex and Ditto) and switch it with Ditto. (Any  cards attached to Ditto, damage counters, Special Conditions, and effects on it are now on the new Pok\xE9mon.) Place Ditto in the discard pile."
        }
      ];
      this.attacks = [
        {
          name: "Energy Ball",
          cost: [C],
          damage: 10,
          text: "Does 10 damage plus 10 more damage for each Energy attached to Ditto but not used to pay for this attack's Energy cost. You can't add more then 20 damage in this way."
        }
      ];
      this.set = "RG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "4";
      this.name = "Ditto";
      this.fullName = "Ditto RG";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const targetCardList = StateUtils.findCardList(state, this);
        if (!(targetCardList instanceof PokemonCardList)) {
          throw new GameError(GameMessage.INVALID_TARGET);
        }
        let canUse = false;
        const blocked = [];
        player.discard.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && (card.name === "Ditto" || card.hasTag("ex" /* POKEMON_ex */))) {
            blocked.push(index);
          } else if (card instanceof PokemonCard && card.stage === 2 /* BASIC */) {
            canUse = true;
          }
        });
        if (!canUse) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            player.discard,
            { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (selection) => {
            if (selection.length <= 0) {
              throw new GameError(GameMessage.INVALID_TARGET);
            }
            const pokemonCard = selection[0];
            if (!(pokemonCard instanceof PokemonCard)) {
              throw new GameError(GameMessage.INVALID_TARGET);
            }
            store.log(state, "LOG_PLAYER_TRANSFORMS_INTO_POKEMON" /* LOG_PLAYER_TRANSFORMS_INTO_POKEMON */, {
              name: player.name,
              pokemon: this.name,
              card: pokemonCard.name,
              effect: effect.power.name
            });
            MOVE_CARDS(store, state, player.discard, targetCardList, { cards: [pokemonCard], sourceCard: this });
            MOVE_CARDS(store, state, targetCardList, player.discard, { cards: [this], sourceCard: this });
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkCost = new CheckAttackCostEffect(player, this.attacks[0]);
        state = store.reduceEffect(state, checkCost);
        const checkEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkEnergy);
        const energy2 = checkEnergy.energyMap;
        const extraEnergy = energy2.length - checkCost.cost.length;
        if (extraEnergy == 1) effect.damage += 10;
        else if (extraEnergy >= 2) effect.damage += 20;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/03-ex-ruby-and-sapphire/set-ex-firered-leafgreen/electrode-ex.ts
