  var Electrodeex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["ex" /* POKEMON_ex */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Voltorb";
      this.cardType = [L];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Extra Energy Bomb",
          useWhenInPlay: true,
          powerType: 1 /* POKEPOWER */,
          knocksOutSelf: true,
          text: "Once during your turn (before your attack), you may discard Electrode ex and all the cards attached to it (this counts as Knocking Out Electrode ex). If you do, search your discard pile for 5 Energy cards and attach them to any of your Pok\xE9mon (excluding Pok\xE9mon-ex) in any way you like. This power can't be used if Electrode ex is affected by a Special Condition."
        }
      ];
      this.attacks = [
        {
          name: "Crash and Burn",
          cost: [L, C],
          damage: 30,
          damageCalculation: "+",
          text: "You may discard as many Energy as you like attached to your Pok\xE9mon in play. If you do, this attack does 30 damage plus 20 more damage for each Energy you discarded."
        }
      ];
      this.set = "RG";
      this.name = "Electrode ex";
      this.fullName = "Electrode ex RG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "107";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        ABILITY_USED(player, this);
        const cardList = StateUtils.findCardList(state, this);
        const pokemons = cardList.getPokemons();
        const attachedCards = cardList.cards.filter((c) => !pokemons.includes(c));
        const tools = cardList.tools.slice();
        attachedCards.forEach((c) => MOVE_CARDS(store, state, cardList, player.discard, { cards: [c], sourceCard: this }));
        tools.forEach((c) => MOVE_CARDS(store, state, cardList, player.discard, { cards: [c], sourceCard: this }));
        cardList.damage += 999;
        let validTargets = 0;
        const blocked2 = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (card.hasTag("ex" /* POKEMON_ex */)) {
            blocked2.push(target);
          }
          validTargets++;
        });
        if (validTargets === 0) {
          return state;
        }
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 0, max: 5, blockedTo: blocked2 }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARD_TO(state, transfer.card, target);
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let totalEnergy = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const energyCount = cardList.cards.filter(
            (card) => card.superType === 3 /* ENERGY */
          ).length;
          totalEnergy += energyCount;
        });
        return store.prompt(
          state,
          new DiscardEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */ },
            { min: 1, max: totalEnergy, allowCancel: false }
          ),
          (transfers) => {
            if (transfers === null) {
              return state;
            }
            transfers.forEach((transfer) => {
              const source = StateUtils.getTarget(state, player, transfer.from);
              MOVE_CARDS(store, state, source, player.discard, { cards: [transfer.card], sourceCard: this });
            });
            effect.damage += transfers.length * 20;
            return state;
          }
        );
      }
      return state;
    }
  };

