  var Raticate2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Rattata";
      this.cardType = [C];
      this.hp = 70;
      this.weakness = [{ type: F }];
      this.retreat = [];
      this.powers = [{
        name: "Thick Skin",
        powerType: 0 /* POKEBODY */,
        text: "Raticate can't be affected by any Special Conditions."
      }];
      this.attacks = [
        {
          name: "Pickup",
          cost: [C],
          damage: 0,
          text: "Search your discard pile for a Basic Pok\xE9mon (or Evolution card), a Trainer card, and an Energy card. Show them to your opponent and put them into your hand."
        },
        {
          name: "Quick Attack",
          cost: [C],
          damage: 10,
          damageCalculation: "+",
          text: "Flip a coin. If heads, this attack does 10 damage plus 40 more damage."
        }
      ];
      this.set = "RG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "48";
      this.name = "Raticate";
      this.fullName = "Raticate RG";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AddSpecialConditionsEffect && effect.target.getPokemonCard() === this) {
        effect.preventDefault = true;
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        let pokemons = 0;
        let energies = 0;
        let trainers = 0;
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          if (c.superType === 3 /* ENERGY */) {
            energies += 1;
          } else if (c instanceof PokemonCard) {
            pokemons += 1;
          } else if (c instanceof TrainerCard) {
            trainers += 1;
          } else {
            blocked.push(index);
          }
        });
        const maxPokemons = Math.min(pokemons, 1);
        const maxEnergies = Math.min(energies, 1);
        const maxTrainers = Math.min(trainers, 1);
        const count = maxPokemons + maxEnergies + maxTrainers;
        let cards = [];
        MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: this, sourceEffect: this.attacks[0] });
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.discard,
          {},
          { min: 0, max: count, allowCancel: false, blocked, maxPokemons, maxEnergies, maxTrainers }
        ), (selected) => {
          cards = selected || [];
          SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        FLIP_A_COIN_IF_HEADS_DEAL_MORE_DAMAGE(store, state, effect, 40);
      }
      return state;
    }
  };

