  var Venusaurex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Ivysaur";
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [G];
      this.hp = 150;
      this.weakness = [{ type: R }, { type: P }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Energy Trans",
          useWhenInPlay: true,
          powerType: 1 /* POKEPOWER */,
          text: "As often as you like during your turn (before your attack), move a [G] Energy card attached to 1 of your Pok\xE9mon to another of your Pok\xE9mon. This power can't be used if Venusaur ex is affected by a Special Condition."
        }
      ];
      this.attacks = [
        {
          name: "Pollen Hazard",
          cost: [G, C, C],
          damage: 20,
          text: "Your opponent's Active Pok\xE9mon is now Poisoned, Burned, and Confused."
        },
        {
          name: "Solar Beam",
          cost: [G, G, G, C, C],
          damage: 90,
          text: ""
        }
      ];
      this.set = "RG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "112";
      this.name = "Venusaur ex";
      this.fullName = "Venusaur ex RG";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_POKEPOWER_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          const blockedCards = [];
          checkProvidedEnergy.energyMap.forEach((em) => {
            if (!em.provides.includes(1 /* GRASS */) && !em.provides.includes(0 /* ANY */)) {
              blockedCards.push(em.card);
            }
          });
          const blocked = [];
          blockedCards.forEach((bc) => {
            const index = cardList.cards.indexOf(bc);
            if (index !== -1 && !blocked.includes(index)) {
              blocked.push(index);
            }
          });
          if (blocked.length !== 0) {
            blockedMap.push({ source: target, blocked });
          }
        });
        store.prompt(
          state,
          new MoveEnergyPrompt(
            effect.player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            {},
            { allowCancel: true, blockedMap }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_POISON_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
        ADD_BURN_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
        ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

