  var Absol = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 70;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -30 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Shining Horn",
          powerType: 0 /* POKEBODY */,
          text: "As long as Absol is the only Pok\xE9mon you have in play, your opponent's Basic Pok\xE9mon can't attack."
        }
      ];
      this.attacks = [
        {
          name: "Extra Call",
          cost: [C],
          damage: 0,
          text: "Search your deck for a Pok\xE9mon-ex, show it to your opponent, and put it into your hand. Shuffle your deck afterward."
        },
        {
          name: "Feint Attack",
          cost: [D, C],
          damage: 0,
          text: "Choose 1 of your opponent's Pok\xE9mon. This attack does 20 damage to that Pok\xE9mon.This attack's damage isn't affected by Weakness, Resistance, Pok\xE9-Powers, Pok\xE9-Bodies, or any other effects on that Pok\xE9mon."
        }
      ];
      this.set = "LM";
      this.setNumber = "15";
      this.cardImage = "assets/cardback.png";
      this.name = "Absol";
      this.fullName = "Absol LM";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttackEffect && !IS_POKEBODY_BLOCKED(store, state, StateUtils.getOpponent(state, effect.player), this) && effect.source.getPokemonCard()?.stage === 2 /* BASIC */) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        let hasBenchPokemon = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          if (cardList === opponent.active) {
            return;
          }
          if (cardList.cards.length > 0) {
            hasBenchPokemon = true;
          }
        });
        if (opponent.active.getPokemonCard() === this && !hasBenchPokemon) {
          throw new GameError(GameMessage.BLOCKED_BY_ABILITY);
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const blocked = [];
        effect.player.deck.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && card.hasTag("ex" /* POKEMON_ex */)) {
            return;
          } else {
            blocked.push(index);
          }
        });
        SEARCH_YOUR_DECK_FOR_POKEMON_AND_PUT_INTO_HAND(
          store,
          state,
          effect.player,
          {},
          { min: 0, max: 1, allowCancel: false, blocked }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const targets = opponent.getPokemonInPlay();
        if (targets.length === 0) return state;
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */]
          ),
          (selected) => {
            const target = selected[0];
            target.damage += 20;
            const afterDamage = new AfterDamageEffect(effect, 20);
            state = store.reduceEffect(state, afterDamage);
          }
        );
      }
      return state;
    }
  };

