  var Banetteex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["ex" /* POKEMON_ex */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Shuppet";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Shady Move",
          useWhenInPlay: true,
          powerType: 1 /* POKEPOWER */,
          text: "Once during your turn (before your attack), if Banette ex is your Active Pok\xE9mon, you may move 1 damage counter from either player's Pok\xE9mon to another Pok\xE9mon (yours or your opponent's). This power can't be used if Banette ex is affected by a Special Condition."
        }
      ];
      this.attacks = [
        {
          name: "Shadow Chant",
          cost: [P, C],
          damage: 30,
          damageCalculation: "+",
          text: "Does 30 damage plus 10 more damage for each Supporter card in your discard pile. You can't add more than 60 damage in this way."
        }
      ];
      this.set = "LM";
      this.setNumber = "85";
      this.cardImage = "assets/cardback.png";
      this.name = "Banette ex";
      this.fullName = "Banette ex LM";
      this.SHADY_MARKER = "SHADY_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.SHADY_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.active.getPokemonCard() !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        if (player.marker.hasMarker(this.SHADY_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const maxAllowedDamage = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(opponent, cardList);
          store.reduceEffect(state, checkHpEffect);
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(player, cardList);
          store.reduceEffect(state, checkHpEffect);
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        if (maxAllowedDamage.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(
          state,
          new MoveDamagePrompt(
            effect.player.id,
            GameMessage.MOVE_DAMAGE,
            0 /* ANY */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            maxAllowedDamage,
            { min: 1, max: 1, allowCancel: false }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            player.marker.addMarker(this.SHADY_MARKER, this);
            ABILITY_USED(player, this);
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              if (source.damage >= 10) {
                source.damage -= 10;
                target.damage += 10;
              }
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let supportersInDiscard = 0;
        player.discard.cards.forEach((c) => {
          if (c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */) {
            supportersInDiscard += 1;
          }
        });
        if (supportersInDiscard > 6) {
          supportersInDiscard = 6;
        }
        effect.damage += supportersInDiscard * 10;
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.SHADY_MARKER, this);
      return state;
    }
  };

