  var Machamp2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Machoke";
      this.cardType = [F];
      this.hp = 120;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Derail",
          cost: [F, C],
          damage: 40,
          text: "Discard a Special Energy card, if any, attached to the Defending Pok\xE9mon."
        },
        {
          name: "Swift Blow",
          cost: [F, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "Does 60 damage plus 20 damage for each React Energy card attached to Machamp."
        }
      ];
      this.set = "LM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "9";
      this.name = "Machamp";
      this.fullName = "Machamp LM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const oppActive = opponent.active;
        const checkEnergy = new CheckProvidedEnergyEffect(player, oppActive);
        store.reduceEffect(state, checkEnergy);
        checkEnergy.energyMap.forEach((em) => {
          const energyCard = em.card;
          if (energyCard.superType === 3 /* ENERGY */ && energyCard.energyType === 1 /* SPECIAL */) {
            let cards = [];
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              oppActive,
              { superType: 3 /* ENERGY */, energyType: 1 /* SPECIAL */ },
              { min: 1, max: 1, allowCancel: false }
            ), (selected) => {
              cards = selected;
            });
            MOVE_CARDS(store, state, oppActive, opponent.discard, { cards, sourceCard: this, sourceEffect: this.attacks[0] });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        let energyCount = 0;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        checkProvidedEnergyEffect.energyMap.forEach((em) => {
          if (em.card.name === "React Energy") {
            energyCount++;
          }
        });
        effect.damage += 20 * energyCount;
      }
      return state;
    }
  };

