  var Mewex = class _Mewex extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["ex" /* POKEMON_ex */];
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Versatile",
          useWhenInPlay: true,
          powerType: 0 /* POKEBODY */,
          text: "Mew ex can use the attacks of all Pok\xE9mon in play as its own. (You still need the necessary Energy to use each attack.)"
        }
      ];
      this.attacks = [
        {
          name: "Power Move",
          cost: [P, C],
          damage: 0,
          text: "Search your deck for an Energy card and attach it to Mew ex. Shuffle your deck afterward. Then, you may switch Mew ex with 1 of your Benched Pok\xE9mon."
        }
      ];
      this.set = "LM";
      this.name = "Mew ex";
      this.fullName = "Mew ex LM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "88";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonAttacksEffect && effect.player.active.getPokemonCard() === this) {
        if (IS_POKEBODY_BLOCKED(store, state, effect.player, this)) return state;
        for (const owner of state.players) {
          for (const list of [owner.active, ...owner.bench]) {
            const donor = list.getPokemonCard();
            if (donor && donor !== this && !list.isSecret) copyAttacks(effect, donor);
          }
        }
        return state;
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_POKEBODY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.ABILITY_BLOCKED);
        }
        return COPY_ATTACK_VIA_ABILITY(store, state, effect, {
          copycatCard: this,
          includeOpponent: true,
          filter: (_cardList, card) => !(card instanceof _Mewex)
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 0, max: 1 }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, {
                cards: [transfer.card],
                sourceCard: this,
                sourceEffect: this.attacks[0]
              });
            }
            state = store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
            CONFIRMATION_PROMPT(store, state, player, (result) => {
              if (result) {
                SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
              }
            });
          }
        );
      }
      return state;
    }
  };

