  var Wynaut2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 50;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Baby Evolution",
        powerType: 1 /* POKEPOWER */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may put Wobbuffet from your hand onto Wynaut (this counts as evolving Wynaut) and remove all damage counters from Wynaut."
      }];
      this.attacks = [{
        name: "Confusion Wave",
        cost: [C],
        damage: 0,
        text: "Both Wynaut and the Defending Pok\xE9mon are now Confused."
      }];
      this.set = "LM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "71";
      this.name = "Wynaut";
      this.fullName = "Wynaut LM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasWobbuffet = player.hand.cards.some((card) => card instanceof PokemonCard && card.name === "Wobbuffet");
        if (!hasWobbuffet) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        player.hand.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && card.name !== "Wobbuffet") {
            blocked.push(index);
          }
        });
        let selectedCards = [];
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_EVOLVE,
          player.hand,
          { superType: 1 /* POKEMON */ },
          { min: 1, max: 1, allowCancel: true, blocked }
        ), (selected) => {
          selectedCards = selected || [];
          const evolution = selectedCards[0];
          const target = StateUtils.findCardList(state, this);
          MOVE_CARDS(store, state, player.hand, target, { cards: [evolution], sourceCard: this });
          const pokemonTarget = target;
          pokemonTarget.clearEffects();
          pokemonTarget.pokemonPlayedTurn = state.turn;
          const healEffect = new HealEffect(player, pokemonTarget, pokemonTarget.damage);
          store.reduceEffect(state, healEffect);
          return state;
        });
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
        ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.player, this);
      }
      return state;
    }
  };

