  var ChampionshipArena = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "NP";
      this.name = "Championship Arena";
      this.fullName = "Championship Arena NP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "28";
      this.text = "At the end of each player's turn, if that player has 8 or more cards in his or her hand, that player discards a number of cards until the player has 7 cards left in his or her hand.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        if (player.hand.cards.length >= 8) {
          const discardAmount = player.hand.cards.length - 7;
          state = store.prompt(
            state,
            new ChooseCardsPrompt(
              effect.player,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              player.hand,
              {},
              { allowCancel: false, min: discardAmount, max: discardAmount }
            ),
            (cards) => {
              cards = cards || [];
              if (cards.length === 0) {
                return;
              }
              MOVE_CARDS(store, state, player.hand, player.discard, {
                cards,
                sourceCard: this
              });
            }
          );
        }
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

