  var Mew2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 50;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [{
        name: "Psywave",
        cost: [C],
        damage: 10,
        damageCalculation: "x",
        text: "Does 10 damage times the amount of Energy attached to the Defending Pok\xE9mon."
      }, {
        name: "Devolution Beam",
        cost: [P],
        damage: 0,
        text: "Flip a coin. If heads, choose 1 of either player's Evolved Pok\xE9mon, remove the highest stage Evolution card from that Pok\xE9mon, and put it into that player's hand."
      }];
      this.set = "NP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "40";
      this.name = "Mew";
      this.fullName = "Mew NP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        store.reduceEffect(state, checkProvidedEnergy);
        const damagePerEnergy = 10;
        effect.damage = checkProvidedEnergy.energyMap.length * damagePerEnergy;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            let canDevolve = false;
            const blocked = [];
            effect.player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
              if (list.getPokemons().length > 1) {
                canDevolve = true;
              } else {
                blocked.push(target);
              }
            });
            effect.opponent.forEachPokemon(1 /* TOP_PLAYER */, (list, card, target) => {
              if (list.getPokemons().length > 1) {
                canDevolve = true;
              } else {
                blocked.push(target);
              }
            });
            if (!canDevolve) {
              return state;
            }
            return store.prompt(
              state,
              new ChoosePokemonPrompt(
                effect.player.id,
                GameMessage.CHOOSE_POKEMON,
                0 /* ANY */,
                [1 /* ACTIVE */, 2 /* BENCH */],
                { allowCancel: false, min: 1, max: 1, blocked }
              ),
              (results) => {
                if (results && results.length > 0) {
                  DEVOLVE_POKEMON(store, state, results[0], effect.opponent.hand);
                }
                return state;
              }
            );
          }
        });
      }
      return state;
    }
  };

