  var Celebiex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [P];
      this.hp = 80;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Time Reversal",
          powerType: 1 /* POKEPOWER */,
          text: "Once during your turn, when you put Celebi ex from your hand onto your Bench, you may search your discard pile for a card, show it to your opponent, and put it on top of your deck."
        }
      ];
      this.attacks = [
        {
          name: "Psychic Shield",
          cost: [P, C],
          damage: 30,
          text: "Prevent all effects of attacks, including damage, done to Celebi ex by your opponent's Pok\xE9mon-ex during your opponent's next turn."
        }
      ];
      this.set = "P2";
      this.setNumber = "17";
      this.cardImage = "assets/cardback.png";
      this.name = "Celebi ex";
      this.fullName = "Celebi ex P2";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.discard.cards.length === 0) {
          return state;
        }
        if (IS_POKEPOWER_BLOCKED(store, state, player, this)) {
          return state;
        }
        CONFIRMATION_PROMPT(
          store,
          state,
          player,
          (wantToUse) => {
            if (wantToUse) {
              const powerEffect = new PowerEffect(player, this.powers[0], this);
              store.reduceEffect(state, powerEffect);
              const deckTop = new CardList();
              return store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_DECK,
                  player.discard,
                  {},
                  { min: 1, max: 1, allowCancel: false }
                ),
                (selected) => {
                  if (selected.length === 0) return;
                  selected.forEach((card) => {
                    MOVE_CARD_TO(state, card, deckTop);
                  });
                  deckTop.moveToTopOfDestination(player.deck);
                  SHOW_CARDS_TO_PLAYER(store, state, opponent, selected);
                  ABILITY_USED(player, this);
                }
              );
            }
          },
          GameMessage.WANT_TO_USE_ABILITY
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const options = { sourceTags: ["ex" /* POKEMON_ex */] };
        PREVENT_DAMAGE(store, state, effect, this, options);
        PREVENT_EFFECTS_OF_ATTACKS(store, state, effect, this, options);
      }
      return state;
    }
  };

