  var Deoxysex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [P];
      this.hp = 110;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Form Change",
          powerType: 1 /* POKEPOWER */,
          useWhenInPlay: true,
          text: "Once during your turn (before your attack), you may search your deck for another Deoxys ex and switch it with Deoxys ex. (Any cards attached to Deoxys ex, damage counters, Special Conditions, and effects on it are now on the new Pok\xE9mon.) If you do, put Deoxys ex on top of your deck. Shuffle your deck afterward. You can't use more than 1 Form Change Pok\xE9-Power each turn."
        }
      ];
      this.attacks = [
        {
          name: "Fastwave",
          cost: [C, C, C],
          damage: 50,
          shredAttack: true,
          text: "This attack's damage isn't affected by Resistance, Pok\xE9-Powers, Pok\xE9-Bodies, or any other effects on the Defending Pok\xE9mon."
        }
      ];
      this.set = "P4";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "17";
      this.name = "Deoxys ex";
      this.fullName = "Deoxys ex P4";
      this.FORME_CHANGE_MARKER = "FORME_CHANGE_MARKER";
    }
    reduceEffect(store, state, effect) {
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.FORME_CHANGE_MARKER, this);
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const targetCardList = StateUtils.findCardList(state, this);
        if (!(targetCardList instanceof PokemonCardList)) {
          throw new GameError(GameMessage.INVALID_TARGET);
        }
        if (HAS_MARKER(this.FORME_CHANGE_MARKER, player)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && card.name !== this.name) {
            blocked.push(index);
          }
        });
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            player.deck,
            { superType: 1 /* POKEMON */ },
            { min: 1, max: 1, allowCancel: true, blocked }
          ),
          (selection) => {
            if (selection.length <= 0) {
              return state;
            }
            const pokemonCard = selection[0];
            if (!(pokemonCard instanceof PokemonCard)) {
              return state;
            }
            store.log(state, "LOG_PLAYER_TRANSFORMS_INTO_POKEMON" /* LOG_PLAYER_TRANSFORMS_INTO_POKEMON */, {
              name: player.name,
              pokemon: this.name,
              card: pokemonCard.name,
              effect: effect.power.name
            });
            MOVE_CARDS(store, state, player.deck, targetCardList, { cards: [pokemonCard], sourceCard: this });
            MOVE_CARDS(store, state, targetCardList, player.deck, { cards: [this], sourceCard: this });
            SHUFFLE_DECK(store, state, player);
            ADD_MARKER(this.FORME_CHANGE_MARKER, player, this);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_ATTACKS_DAMAGE_ISNT_AFFECTED_BY_EFFECTS(store, state, effect, 50);
      }
      return state;
    }
  };

