  var EspeonStar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 70;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Purple Ray",
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn, when you put Espeon Star from your hand onto your Bench, you may use this power. Each Active Pok\xE9mon (both yours and your opponent's) is now Confused."
      }];
      this.attacks = [
        {
          name: "Psychic Boom",
          cost: [P, P, C],
          damage: 30,
          text: "Does 30 damage plus 10 more damage for each Energy attached to the Defending Pok\xE9mon."
        }
      ];
      this.set = "P5";
      this.name = "Espeon Star";
      this.fullName = "Espeon Star P5";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "16";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this && !IS_POKEPOWER_BLOCKED(store, state, effect.player, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        CONFIRMATION_PROMPT(store, state, player, (result) => {
          if (!result) {
            return state;
          }
          const powerEffect = new PowerEffect(player, this.powers[0], this);
          store.reduceEffect(state, powerEffect);
          ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, player, this);
          ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, opponent, this);
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList === opponent.active) {
            const checkProvidedEnergy = new CheckProvidedEnergyEffect(opponent, cardList);
            store.reduceEffect(state, checkProvidedEnergy);
            const blockedCards = [];
            checkProvidedEnergy.energyMap.forEach((em) => {
              if (!em.provides.includes(0 /* ANY */)) {
                blockedCards.push(em.card);
              }
            });
            const damagePerEnergy = 10;
            effect.damage += checkProvidedEnergy.energyMap.length * damagePerEnergy;
          }
        });
      }
      return state;
    }
  };

