  var Mew3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Delta Species" /* DELTA_SPECIES */];
      this.cardType = [R];
      this.hp = 60;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Copy",
          cost: [C],
          damage: 0,
          copycatAttack: true,
          text: "Choose 1 of the Defending Pok\xE9mon's attacks. Copy copies that attack. This attack does nothing if Mew doesn't have the Energy necessary to use that attack. (You must still do anything else required for that attack.) Mew performs that attack."
        },
        {
          name: "Extra Draw",
          cost: [R],
          damage: 0,
          text: "If your opponent has any Pok\xE9mon-ex in play, search your deck for up to 2 basic Energy cards and attach them to Mew. Shuffle your deck afterward."
        }
      ];
      this.set = "P5";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "3";
      this.name = "Mew";
      this.fullName = "Mew P5";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentActive = opponent.active.getPokemonCard();
        if (!opponentActive) {
          return state;
        }
        const { pokemonCards, blocked } = buildAttackListWithEnergyBlocking(state, store, player, {
          extraCards: [opponentActive]
        });
        if (pokemonCards.length === 0) {
          return state;
        }
        return COPY_ATTACK_FROM_POKEMON_LIST(store, state, effect, pokemonCards, {
          allowCancel: true,
          blocked
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let hasexPokemon = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          const pokemonCard = cardList.getPokemonCard();
          if (pokemonCard && pokemonCard.hasTag("ex" /* POKEMON_ex */)) {
            hasexPokemon = true;
          }
        });
        if (hasexPokemon) {
          store.prompt(
            state,
            new AttachEnergyPrompt(
              player.id,
              GameMessage.ATTACH_ENERGY_CARDS,
              player.deck,
              2 /* BOTTOM_PLAYER */,
              [1 /* ACTIVE */],
              { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
              { min: 0, max: 2, allowCancel: true }
            ),
            (transfers) => {
              transfers = transfers || [];
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARD_TO(state, transfer.card, target);
              }
              SHUFFLE_DECK(store, state, player);
            }
          );
        }
      }
      return state;
    }
  };

