  var AurasLucarioex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Aura's" /* AURAS */, "ex" /* POKEMON_ex */];
      this.cardType = [8 /* METAL */];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Aura's Guidance",
          useWhenInPlay: true,
          powerType: 1 /* POKEPOWER */,
          text: "Once during your turn, if Aura's Lucario ex is your Active Pok\xE9mon, you may use this Power. If your opponent used a Supporter card last turn, you may use the effect of that card as the effect of this Power(the Supporter card remains in your opponent's discard pile). This Power can't be used if Aura's Lucario ex is affected by a Special Condition."
        }
      ];
      this.attacks = [
        {
          name: "Battle Blast",
          cost: [M, C, C],
          damage: 50,
          damageCalculation: "+",
          text: "Does 50 damage plus 10 more damage for each [F] Energy attached to Aura's Lucario ex."
        }
      ];
      this.set = "PCGL";
      this.setNumber = "6";
      this.cardImage = "assets/cardback.png";
      this.name = "Aura's Lucario ex";
      this.fullName = "Aura's Lucario ex PCGL";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlaySupporterEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!opponent.supportersForDetour.cards.includes(effect.trainerCard)) {
          opponent.supportersForDetour.cards.push(effect.trainerCard);
        }
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.supportersForDetour.cards.length == 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        if (player.active.getPokemonCard() !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_COPY_EFFECT,
            player.supportersForDetour,
            { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
            { allowCancel: false, min: 1, max: 1 }
          ),
          (cards) => {
            const trainerCard = cards[0];
            player.supporterTurn -= 1;
            const playTrainerEffect = new TrainerEffect(player, trainerCard);
            store.reduceEffect(state, playTrainerEffect);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let energyCount = 0;
        checkProvidedEnergyEffect.energyMap.forEach((em) => {
          if (em.provides.includes(6 /* FIGHTING */) || em.provides.includes(0 /* ANY */)) {
            energyCount += em.provides.length;
          }
        });
        for (let i = 0; i < energyCount; i++) {
          effect.damage += 10;
        }
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.supportersForDetour.cards = [];
      }
      return state;
    }
  };

