  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-pcg-p-promotional-cards/pokeparks-celebi.ts
  init_prefabs();
  init_play_card_effects();
  init_game();
  init_card_types();
  init_pokemon_card();
  var PokeParksCelebi = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 60;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [{
        name: "Natural Cure",
        useWhenInPlay: false,
        powerType: 0 /* POKEBODY */,
        text: "When you attach a [G] Energy card from your hand to this Pok\xE9mon, remove all Special Conditions from this Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Psyshock",
        cost: [G, C],
        damage: 20,
        text: "Flip a coin. If heads, your opponent's Active Pok\xE9mon is now Paralyzed."
      }];
      this.set = "PCGP";
      this.name = "Pok\xE9Park's Celebi";
      this.fullName = "Pok\xE9Park's Celebi PCGP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "44";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        if (effect.target.specialConditions.length === 0) {
          return state;
        }
        if (!effect.energyCard.provides.includes(1 /* GRASS */)) {
          return state;
        }
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (IS_POKEBODY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const conditions = effect.target.specialConditions.slice();
        conditions.forEach((condition) => {
          effect.target.removeSpecialCondition(condition);
        });
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            ADD_PARALYZED_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
          }
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-pcg-p-promotional-cards/pokeparks-jirachi.ts
  init_pokemon_card();
  init_card_types();
  init_prefabs();
  init_game();
  init_attack_effects2();
  var PokeParksJirachi = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [M];
      this.hp = 50;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Future Sight",
          cost: [C],
          damage: 0,
          text: "Look at the top 5 cards of either player's deck and put them back on top of that player's deck in any order."
        },
        {
          name: "Swift",
          cost: [M, C],
          damage: 30,
          shredAttack: true,
          text: "This attack's damage isn't affected by Weakness, Resistance, Pok\xE9-Powers, Pok\xE9-Bodies, or any other effects on the Defending Pok\xE9mon."
        }
      ];
      this.set = "PCGP";
      this.name = "Pok\xE9Park's Jirachi";
      this.fullName = "Pok\xE9Park's Jirachi PCGP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "50";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const options = [
          {
            message: GameMessage.ORDER_YOUR_DECK,
            action: () => {
              if (player.deck.cards.length === 0) {
                throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
              }
              const deckTop = new CardList();
              MOVE_CARDS(store, state, player.deck, deckTop, { count: 5, sourceCard: this });
              return store.prompt(state, new OrderCardsPrompt(
                player.id,
                GameMessage.CHOOSE_CARDS_ORDER,
                deckTop,
                { allowCancel: false }
              ), (order) => {
                if (order === null) {
                  return state;
                }
                deckTop.applyOrder(order);
                deckTop.moveToTopOfDestination(player.deck);
              });
            }
          },
          {
            message: GameMessage.ORDER_OPPONENT_DECK,
            action: () => {
              if (opponent.deck.cards.length === 0) {
                throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
              }
              const deckTop = new CardList();
              MOVE_CARDS(store, state, opponent.deck, deckTop, { count: 5, sourceCard: this });
              return store.prompt(state, new OrderCardsPrompt(
                player.id,
                GameMessage.CHOOSE_CARDS_ORDER,
                deckTop,
                { allowCancel: false }
              ), (order) => {
                if (order === null) {
                  return state;
                }
                deckTop.applyOrder(order);
                deckTop.moveToTopOfDestination(opponent.deck);
              });
            }
          }
        ];
        return store.prompt(state, new SelectPrompt(
          player.id,
          GameMessage.CHOOSE_OPTION,
          options.map((opt) => opt.message),
          { allowCancel: false }
        ), (choice) => {
          const option = options[choice];
          option.action();
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        THIS_ATTACKS_DAMAGE_ISNT_AFFECTED_BY_EFFECTS(store, state, effect, 30);
      }
      return state;
    }
  };

