  var PokeParksMudkip = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 60;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.attacks = [{
        name: "Mud-Slap",
        cost: [C],
        damage: 10,
        text: ""
      }, {
        name: "Flamethrower",
        cost: [W, C, C],
        damage: 30,
        text: "Flip a coin. If heads, discard an Energy attached to your opponent's Active Pok\xE9mon."
      }];
      this.set = "PCGP";
      this.name = "Pok\xE9Park's Mudkip";
      this.fullName = "Pok\xE9Park's Mudkip PCGP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "48";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            const player = effect.player;
            const opponent = effect.opponent;
            if (!opponent.active.energies.cards.some((c) => c.superType === 3 /* ENERGY */)) {
              return state;
            }
            let card;
            return store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              opponent.active,
              { superType: 3 /* ENERGY */ },
              { min: 1, max: 1, allowCancel: false }
            ), (selected) => {
              card = selected[0];
              return store.reduceEffect(state, new DiscardCardsEffect(effect, [card]));
            });
          }
        });
      }
      return state;
    }
  };

