  init_game();
  init_prefabs();
  init_check_effects();
  init_attack_effects2();
  var SamiyasBuizel = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 60;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.powers = [{
        name: "Aqua Lift",
        powerType: 0 /* POKEBODY */,
        text: "If Samiya's Buizel has any [W] Energy attached to it, the Retreat Cost for Samiya's Buizel is 0."
      }];
      this.attacks = [{
        name: "Whirlpool",
        cost: [W, C],
        damage: 20,
        text: "Flip a coin. If heads, discard an Energy attached to the Defending Pok\xE9mon."
      }];
      this.set = "PCGP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "138";
      this.name = "Samiya's Buizel";
      this.fullName = "Samiya's Buizel PCGP 138";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect && effect.player.active.cards.includes(this)) {
        const player = effect.player;
        const pokemonCard = player.active.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (IS_POKEBODY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const hasPsychicEnergy = checkProvidedEnergy.energyMap.some(
          (energy2) => energy2.provides.includes(3 /* WATER */) || energy2.provides.includes(0 /* ANY */)
        );
        if (hasPsychicEnergy) {
          effect.cost = [];
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            return DISCARD_AN_ENERGY_FROM_OPPONENTS_ACTIVE_POKEMON(store, state, effect);
          }
        });
      }
      return state;
    }
  };

