  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-pcg-p-promotional-cards/samiyas-chatot.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  init_copy_attack_prefabs();
  var SamiyasChatot = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 50;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [{
        name: "Copy",
        cost: [C],
        damage: 0,
        copycatAttack: true,
        text: "Choose 1 of the Defending Pok\xE9mon's attacks. Copy copies that attack. This attack does nothing if this Pok\xE9mon doesn't have the Energy necessary to use that attack. (You must still do anything else required for that attack.) This Pok\xE9mon performs that attack."
      }];
      this.set = "PCGP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "143";
      this.name = "Samiya's Chatot";
      this.fullName = "Samiya's Chatot PCGP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentActive = opponent.active.getPokemonCard();
        if (!opponentActive) {
          return state;
        }
        const { blocked } = this.buildEnergyBlockedAttacks(state, store, player, opponentActive);
        return COPY_ATTACK_FROM_POKEMON_LIST(store, state, effect, [opponentActive], {
          allowCancel: true,
          blocked
        });
      }
      return state;
    }
    buildEnergyBlockedAttacks(state, store, player, card) {
      const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player);
      store.reduceEffect(state, checkProvidedEnergyEffect);
      const energyMap = checkProvidedEnergyEffect.energyMap;
      const blocked = [];
      const affordableAttacks = card.attacks.filter((attack3) => {
        const checkAttackCost = new CheckAttackCostEffect(player, attack3);
        state = store.reduceEffect(state, checkAttackCost);
        return StateUtils.checkEnoughEnergy(energyMap, checkAttackCost.cost);
      });
      card.attacks.forEach((attack3) => {
        if (!affordableAttacks.includes(attack3)) {
          blocked.push({ index: 0, attack: attack3.name });
        }
      });
      return { blocked };
    }
  };

