  var SamiyasMantyke = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 50;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Water Sport",
          cost: [W],
          damage: 10,
          damageCalculation: "+",
          text: "If Samiya's Mantyke has less Energy attached to it than the Defending Pok\xE9mon, this attack does 10 damage plus 10 more damage."
        },
        {
          name: "Splash",
          cost: [C, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "PCGP";
      this.name = "Samiya's Mantyke";
      this.fullName = "Samiya's Mantyke PCGP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "137";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        const playerProvidedEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, playerProvidedEnergy);
        const playerEnergyCount = playerProvidedEnergy.energyMap.reduce((left, p) => left + p.provides.length, 0);
        const opponentProvidedEnergy = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, opponentProvidedEnergy);
        const opponentEnergyCount = opponentProvidedEnergy.energyMap.reduce((left, p) => left + p.provides.length, 0);
        if (playerEnergyCount < opponentEnergyCount) {
          effect.damage += 10;
        }
      }
      return state;
    }
  };

