  var SeasManaphy2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 60;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Pickup Power",
          cost: [C],
          damage: 0,
          text: "Search your discard pile for an Energy card, show it to your opponent, and put it into your hand."
        },
        {
          name: "Aqua Blast",
          cost: [W, C],
          damage: 30,
          text: "Discard 1 [W] Energy card attached to Sea's Manaphy in order to use this attack."
        }
      ];
      this.set = "PCGP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "146";
      this.name = "Sea's Manaphy";
      this.fullName = "Sea's Manaphy PCGP 146";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasEnergy = player.discard.cards.some((c) => {
          return c instanceof EnergyCard;
        });
        if (!hasEnergy) {
          return state;
        }
        let cards = [];
        MOVE_CARDS(store, state, player.discard, player.hand, { cards });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.discard,
          { superType: 3 /* ENERGY */ },
          { min: 0, max: 1, allowCancel: true }
        ), (selected) => {
          cards = selected || [];
          if (cards.length > 0) {
            SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1, 3 /* WATER */);
      }
      return state;
    }
  };

