  init_check_effects();
  var SeasManaphy4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 60;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.powers = [{
        name: "Water Absorb",
        useWhenInPlay: false,
        powerType: 0 /* POKEBODY */,
        text: "When you attach a [W] Energy card from your hand to Sea's Manaphy, remove all Special Conditions and 1 damage counter from Sea's Manaphy."
      }];
      this.attacks = [{
        name: "Water Punch",
        cost: [C, C],
        damage: 20,
        damageCalculation: "+",
        text: "Flip a coin for each [W] Energy attached to Sea's Manaphy. This attack does 20 damage plus 10 more damage for each heads."
      }];
      this.set = "PCGP";
      this.name = "Sea's Manaphy";
      this.fullName = "Sea's Manaphy PCGP 150";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "150";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        if (effect.target.specialConditions.length === 0) {
          return state;
        }
        if (!effect.energyCard.provides.includes(3 /* WATER */)) {
          return state;
        }
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (IS_POKEBODY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const healEffect = new HealEffect(player, effect.target, 10);
        state = store.reduceEffect(state, healEffect);
        const conditions = effect.target.specialConditions.slice();
        conditions.forEach((condition) => {
          effect.target.removeSpecialCondition(condition);
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let energyCount = 0;
        checkProvidedEnergyEffect.energyMap.forEach((em) => {
          if (em.provides.includes(3 /* WATER */) || em.provides.includes(0 /* ANY */)) {
            energyCount += em.provides.length;
          }
        });
        if (energyCount > 0) {
          MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, energyCount, (results) => {
            effect.damage += results.filter((r) => r).length * 10;
          });
        }
      }
      return state;
    }
  };

