  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var SkySplittingDeoxys = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 80;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Duplicate",
        powerType: 1 /* POKEPOWER */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may search your deck for another Sky-Splitting Deoxys and switch it with Sky-Splitting Deoxys. (Any cards attached to Sky-Splitting Deoxys, damage counters, Special Conditions, and effects on it are now on the new Pok\xE9mon.) If you do, put Sky-Splitting Deoxys on top of your deck. Shuffle your deck afterward. You can't use more than 1 Forme Change Pok\xE9-Power each turn."
      }];
      this.attacks = [{
        name: "Ozone Drain",
        cost: [P, C, C],
        damage: 40,
        text: "If Magnetic Storm is in play, remove 3 damage counters from Sky-Splitting Deoxys."
      }];
      this.set = "PCGP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "18";
      this.name = "Sky-Splitting Deoxys";
      this.fullName = "Sky-Splitting Deoxys PCGP";
      this.FORME_CHANGE_MARKER = "FORME_CHANGE_MARKER";
    }
    reduceEffect(store, state, effect) {
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.FORME_CHANGE_MARKER, this);
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const targetCardList = StateUtils.findCardList(state, this);
        if (!(targetCardList instanceof PokemonCardList)) {
          throw new GameError(GameMessage.INVALID_TARGET);
        }
        if (HAS_MARKER(this.FORME_CHANGE_MARKER, player)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && card.name !== this.name) {
            blocked.push(index);
          }
        });
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          player.deck,
          { superType: 1 /* POKEMON */ },
          { min: 1, max: 1, allowCancel: true, blocked }
        ), (selection) => {
          if (selection.length <= 0) {
            return state;
          }
          const pokemonCard = selection[0];
          if (!(pokemonCard instanceof PokemonCard)) {
            return state;
          }
          store.log(state, "LOG_PLAYER_TRANSFORMS_INTO_POKEMON" /* LOG_PLAYER_TRANSFORMS_INTO_POKEMON */, {
            name: player.name,
            pokemon: this.name,
            card: pokemonCard.name,
            effect: effect.power.name
          });
          MOVE_CARDS(store, state, player.deck, targetCardList, { cards: [pokemonCard], sourceCard: this });
          MOVE_CARDS(store, state, targetCardList, player.deck, { cards: [this], sourceCard: this });
          SHUFFLE_DECK(store, state, player);
          ADD_MARKER(this.FORME_CHANGE_MARKER, player, this);
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const stadiumCard = StateUtils.getStadiumCard(state);
        if (stadiumCard && stadiumCard.name === "Magnetic Storm") {
          HEAL_X_DAMAGE_FROM_THIS_POKEMON(effect, store, state, 30);
        }
      }
      return state;
    }
  };

