  var PokeParksLatias = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 70;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Psywave",
          cost: [C],
          damage: 10,
          damageCalculation: "x",
          text: "This attack does 10 damage times the amount of Energy attached to your opponent's Active Pok\xE9mon."
        },
        {
          name: "Mist Ball",
          cost: [R, W, C],
          damage: 50,
          text: "Discard a [R] Energy and a [W] Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "PPF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "5";
      this.name = "Pok\xE9Park's Latias";
      this.fullName = "Pok\xE9Park's Latias PPF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        const checkEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        store.reduceEffect(state, checkEnergy);
        const energyCount = checkEnergy.energyMap.length;
        effect.damage = 10 * energyCount;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [2 /* FIRE */, 3 /* WATER */],
          { allowCancel: false }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = player.active;
          store.reduceEffect(state, discardEnergy2);
        });
      }
      return state;
    }
  };

