  var FolkloresLucarioex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [M];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Forge",
          cost: [C],
          damage: 0,
          text: "Attach 1 [F] Energy or 1 [M] Energy from your hand to Folklore's Lucario ex."
        },
        {
          name: "Linear Attack",
          cost: [F, C],
          damage: 0,
          text: "Does 30 damage to 1 of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Extra Claws",
          cost: [M, C, C],
          damage: 50,
          damageCalculation: "+",
          text: "If the Defending Pok\xE9mon is a Pok\xE9mon-ex, this attack does 20 more damage."
        }
      ];
      this.set = "GBM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "6";
      this.name = "Folklore's Lucario ex";
      this.fullName = "Folklore's Lucario ex GBM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blocked = [];
        player.hand.cards.forEach((c, i) => {
          if (!(c instanceof EnergyCard)) blocked.push(i);
          else if (!c.provides.includes(6 /* FIGHTING */) && !c.provides.includes(8 /* METAL */))
            blocked.push(i);
        });
        const hasFightingOrMetalEnergyInHand = player.hand.cards.some(
          (c) => c instanceof EnergyCard && (c.provides.includes(6 /* FIGHTING */) || c.provides.includes(8 /* METAL */))
        );
        if (!hasFightingOrMetalEnergyInHand) {
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_ATTACH,
            player.hand,
            { superType: 3 /* ENERGY */ },
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, player.hand, player.active, { cards: [cards[0]], sourceCard: this });
            }
            return state;
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_POKEMON(30, effect, store, state);
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        if (effect.opponent.active.getPokemonCard()?.hasTag("ex" /* POKEMON_ex */)) {
          effect.damage += 20;
        }
      }
      return state;
    }
  };

