  var Cleffa2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 40;
      this.weakness = [{ type: F, value: 10 }];
      this.retreat = [C];
      this.powers = [{
        name: "Baby Evolution",
        powerType: 1 /* POKEPOWER */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may put Clefairy from your hand onto Cleffa (this counts as evolving Cleffa) and remove all damage counters from Cleffa."
      }];
      this.attacks = [
        {
          name: "Eeek",
          cost: [],
          damage: 0,
          text: "Draw a card."
        }
      ];
      this.set = "DP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "78";
      this.name = "Cleffa";
      this.fullName = "Cleffa DP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasClefairy = player.hand.cards.some((card) => card instanceof PokemonCard && card.name === "Clefairy");
        if (!hasClefairy) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        player.hand.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && card.name !== "Clefairy") {
            blocked.push(index);
          }
        });
        let selectedCards = [];
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_EVOLVE,
          player.hand,
          { superType: 1 /* POKEMON */ },
          { min: 1, max: 1, allowCancel: true, blocked }
        ), (selected) => {
          selectedCards = selected || [];
          const evolution = selectedCards[0];
          const target = StateUtils.findCardList(state, this);
          MOVE_CARDS(store, state, player.hand, target, { cards: [evolution], sourceCard: this });
          const pokemonTarget = target;
          pokemonTarget.clearEffects();
          pokemonTarget.pokemonPlayedTurn = state.turn;
          const healEffect = new HealEffect(player, pokemonTarget, pokemonTarget.damage);
          store.reduceEffect(state, healEffect);
          return state;
        });
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        DRAW_CARDS(store, state, effect.player, 1);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/04-diamond-pearl-platinum/set-diamond-and-pearl/dusknoir.ts
