  var PlusPower2 = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "DP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "109";
      this.name = "PlusPower";
      this.fullName = "PlusPower DP";
      this.text = "Attach PlusPower to 1 of your Pok\xE9mon. Discard this card at the end of your turn.\n\nIf the Pok\xE9mon PlusPower is attached to attacks, the attack does 10 more damage to the Active Pok\xE9mon (before applying Weakness and Resistance).";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        state = store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { min: 1, max: 1, allowCancel: false }
          ),
          (transfers) => {
            MOVE_CARDS(store, state, player.supporter, transfers[0], {
              cards: [effect.trainerCard],
              sourceCard: this
            });
          }
        );
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, index) => {
          if (cardList.cards.includes(this)) {
            MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
          }
        });
      }
      if (effect instanceof DealDamageEffect && effect.source.cards.includes(this)) {
        if (effect.damage && effect.damage > 0 && (effect.target === effect.opponent.active || effect.target === effect.player.active)) {
          effect.damage += 10;
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/04-diamond-pearl-platinum/set-diamond-and-pearl/pokedex-handy.ts
