  function* playCard42(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const deckTop = new CardList();
    MOVE_CARDS(store, state, player.deck, deckTop, { count: 2, sourceCard: effect.trainerCard });
    return store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        deckTop,
        {},
        { min: 1, max: 1, allowCancel: false }
      ),
      (selected) => {
        MOVE_CARDS(store, state, deckTop, player.hand, {
          cards: selected,
          sourceCard: effect.trainerCard
        });
        MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: effect.trainerCard });
      }
    );
  }
  var PokedexHandy = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "DP";
      this.name = "Pokedex HANDY910is";
      this.fullName = "Pokedex HANDY910is DP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "111";
      this.text = "Look at the top 2 cards of your deck, choose 1 of them, and put it into your hand. Put the other card on the bottom of your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard42(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/04-diamond-pearl-platinum/set-diamond-and-pearl/prinplup.ts
  init_game();
