  var Prinplup = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Piplup";
      this.cardType = [W];
      this.hp = 80;
      this.weakness = [{ type: L, value: 20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Aqua Shower",
          cost: [W],
          damage: 0,
          text: "Does 10 damage to each of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Brine",
          cost: [W, W],
          damage: 0,
          text: "Choose 1 of your opponent's Pok\xE9mon that has any damage counters on it. This attack does 40 damage to that Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "DP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "58";
      this.name = "Prinplup";
      this.fullName = "Prinplup DP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        const benched = opponent.bench.filter((b) => b.cards.length > 0);
        effect.damage = 10;
        benched.forEach((target) => {
          const damageEffect = new PutDamageEffect(effect, 10);
          damageEffect.target = target;
          store.reduceEffect(state, damageEffect);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const damagedTargets = [];
        if (opponent.active.cards.length > 0 && opponent.active.damage > 0) {
          damagedTargets.push({ player: 1 /* TOP_PLAYER */, slot: 1 /* ACTIVE */, index: 0 });
        }
        opponent.bench.forEach((b, index) => {
          if (b.cards.length > 0 && b.damage > 0) {
            damagedTargets.push({ player: 1 /* TOP_PLAYER */, slot: 2 /* BENCH */, index });
          }
        });
        if (damagedTargets.length === 0) {
          return state;
        }
        const blocked = [];
        if (opponent.active.damage === 0) {
          blocked.push({ player: 1 /* TOP_PLAYER */, slot: 1 /* ACTIVE */, index: 0 });
        }
        opponent.bench.forEach((b, index) => {
          if (b.cards.length > 0 && b.damage === 0) {
            blocked.push({ player: 1 /* TOP_PLAYER */, slot: 2 /* BENCH */, index });
          }
        });
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (selected) => {
          const targets = selected || [];
          DAMAGE_OPPONENT_POKEMON(store, state, effect, 40, targets);
        });
      }
      return state;
    }
  };

