  function* usePower3(next, store, state, self, effect) {
    const player = effect.player;
    const cardList = StateUtils.findCardList(state, self);
    const benchIndex = player.bench.indexOf(cardList);
    if (benchIndex === -1) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    const pokemonCard = player.bench[benchIndex].getPokemonCard();
    if (pokemonCard !== self) {
      throw new GameError(GameMessage.ILLEGAL_ACTION);
    }
    let hasPokemonWithoutTool = false;
    const blocked = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card, target) => {
      if (cardList2.tools.length === 0 && card !== self) {
        hasPokemonWithoutTool = true;
      } else {
        blocked.push(target);
      }
    });
    if (!hasPokemonWithoutTool) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    return store.prompt(state, new ChoosePokemonPrompt(
      player.id,
      GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
      2 /* BOTTOM_PLAYER */,
      [1 /* ACTIVE */, 2 /* BENCH */],
      { allowCancel: true, blocked }
    ), (targets) => {
      if (targets && targets.length > 0) {
        const unownESlot = player.bench[benchIndex];
        const unownECard = unownESlot.getPokemonCard();
        if (!unownECard) {
          return state;
        }
        const otherCards = unownESlot.cards.filter(
          (card) => !(card instanceof PokemonCard) && !unownESlot.getPokemons().includes(card) && (!unownESlot.tools || !unownESlot.tools.includes(card))
        );
        const tools = [...unownESlot.tools];
        if (tools.length > 0) {
          for (const tool of tools) {
            MOVE_CARDS(store, state, unownESlot, player.discard, { cards: [tool], sourceCard: self });
          }
        }
        if (otherCards.length > 0) {
          MOVE_CARDS(store, state, unownESlot, player.discard, { cards: otherCards });
        }
        MOVE_CARDS(store, state, unownESlot, targets[0], { cards: [unownECard], sourceCard: self });
        targets[0].tools.push(unownECard);
        unownESlot.clearEffects();
      }
    });
  }
  var UnownE2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 50;
      this.weakness = [{ type: P, value: 10 }];
      this.retreat = [C];
      this.powers = [{
        name: "EQUIP",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), if Unown E is on your Bench, you may discard all cards attached to Unown E and attach Unown E to 1 of your Pok\xE9mon as a Pok\xE9mon Tool card. As long as Unown E is attached to a Pok\xE9mon, that Pok\xE9mon gets +10 HP."
      }];
      this.attacks = [{
        name: "Hidden Power",
        cost: [C, C],
        damage: 0,
        text: "**THIS ATTACK DOES NOT WORK LIL BRO**\n\nDuring your opponent's next turn, whenever your opponent flips a coin, treat it as tails."
      }];
      this.set = "MT";
      this.name = "Unown [E]";
      this.fullName = "Unown [E] MT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "65";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const generator = usePower3(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (effect instanceof CheckHpEffect && effect.target.tools.includes(this) && effect.target.getPokemonCard() !== this) {
        const card = effect.target.getPokemonCard();
        if (card === void 0) {
          return state;
        }
        if (card.stage === 2 /* BASIC */) {
          effect.hp += 10;
        }
        return state;
      }
      return state;
    }
  };

