  init_trainer_card();
  init_game_effects();
  init_prefabs();
  init_trainer_prefabs();
  var TeamGalacticsWager = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "MT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "115";
      this.name = "Team Galactic's Wager";
      this.fullName = "Team Galactic's Wager MT";
      this.text = 'Each player shuffles his or her hand into his or her deck, and you and your opponent play "Rock-Paper-Scissors." The player who wins draws up to 6 cards. The player who loses draws up to 3 cards. (You draw your cards first.)';
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        const cards = player.hand.cards.filter((c) => c !== this);
        const opponentCards = opponent.hand.cards.filter((c) => c !== this);
        if (cards.length === 0 && player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const playerMoveEffect = new MoveCardsEffect(player.hand, player.deck, {
          cards,
          sourceCard: this
        });
        state = store.reduceEffect(state, playerMoveEffect);
        const opponentMoveEffect = new MoveCardsEffect(opponent.hand, opponent.deck, {
          cards: opponentCards,
          sourceCard: this
        });
        state = store.reduceEffect(state, opponentMoveEffect);
        SHUFFLE_DECK(store, state, player);
        if (opponentMoveEffect.preventDefault) {
          return state;
        }
        const options = [
          { value: "Rock", message: "Rock" },
          { value: "Paper", message: "Paper" },
          { value: "Scissors", message: "Scissors" }
        ];
        let maxPlayerDraw = 3;
        let maxOpponentDraw = 6;
        store.prompt(state, [
          new SelectPrompt(
            player.id,
            GameMessage.CHOOSE_OPTION,
            options.map((c) => c.message),
            { allowCancel: false }
          ),
          new SelectPrompt(
            opponent.id,
            GameMessage.CHOOSE_OPTION,
            options.map((c) => c.message),
            { allowCancel: false }
          )
        ], (results) => {
          const playerChosenValue = results[0];
          const opponentChosenValue = results[1];
          if (playerChosenValue === opponentChosenValue) {
            return this.reduceEffect(store, state, effect);
          }
          if (playerChosenValue === 1 && opponentChosenValue === 0 || playerChosenValue === 2 && opponentChosenValue === 1 || playerChosenValue === 0 && opponentChosenValue === 2) {
            maxPlayerDraw = 6;
            maxOpponentDraw = 3;
          }
          DRAW_UP_TO_X_CARDS(store, state, player, maxPlayerDraw);
          if (!opponentMoveEffect.preventDefault) {
            DRAW_UP_TO_X_CARDS(store, state, opponent, maxOpponentDraw);
          }
        });
      }
      return state;
    }
  };

