  var TimeSpaceDistortion = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "MT";
      this.name = "Time-Space Distortion";
      this.fullName = "Time-Space Distortion MT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "124";
      this.text = "Flip 3 coins. For each heads, search your discard pile for a Pok\xE9mon, show it to your opponent, and put it into your hand.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        if (!player.discard.cards.some((c) => c.superType === 1 /* POKEMON */)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        effect.preventDefault = true;
        let headsCount = 0;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          results.forEach((result) => {
            if (result) {
              headsCount++;
            }
          });
          if (headsCount === 0) {
            return state;
          }
          const minDiscard = Math.min(
            player.discard.cards.filter((c) => c.superType === 1 /* POKEMON */).length,
            headsCount
          );
          store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_HAND,
              player.discard,
              { superType: 1 /* POKEMON */ },
              { min: minDiscard, max: headsCount, allowCancel: false }
            ),
            (selected) => {
              if (selected && selected.length > 0) {
                MOVE_CARDS(store, state, player.discard, player.hand, {
                  cards: selected,
                  sourceCard: this
                });
              }
            }
          );
        });
      }
      return state;
    }
  };

