  function* playCard46(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let pokemonsOrEnergyInDiscard = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      const isPokemon = c instanceof PokemonCard;
      const isBasicEnergy = c instanceof EnergyCard && c.energyType === 0 /* BASIC */;
      if (isPokemon || isBasicEnergy) {
        pokemonsOrEnergyInDiscard += 1;
      } else {
        blocked.push(index);
      }
    });
    if (pokemonsOrEnergyInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        {},
        { min: 1, max: 3, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
