  init_prefabs();
  var Plusle = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.weakness = [{ type: F, value: 10 }];
      this.resistance = [{ type: M, value: -20 }];
      this.hp = 60;
      this.retreat = [C];
      this.powers = [
        {
          name: "Plus Charge",
          powerType: 1 /* POKEPOWER */,
          useWhenInPlay: true,
          text: "Once during your turn (before your attack), if any of your Pok\xE9mon were Knocked Out during your opponent's last turn, you may search your discard pile for up to 2 basic Energy cards, show them to your opponent, and put them into your hand. You can't use more than 1 Plus Charge Pok\xE9-Power each turn. This power can't be used if Plusle is affected by a Special Condition."
        }
      ];
      this.attacks = [
        {
          name: "Tag Play +",
          cost: [L],
          damage: 20,
          text: "If you have Minun on your Bench, you may do 20 damage to any 1 Benched Pok\xE9mon instead. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "SW";
      this.setNumber = "36";
      this.cardImage = "assets/cardback.png";
      this.name = "Plusle";
      this.fullName = "Plusle SW";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (!HAS_MARKER("OPPONENT_KNOCKOUT_MARKER", player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.active.cards[0] === this && player.active.specialConditions.length > 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.usedPlusCharge == true) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        let basicEnergyCards = 0;
        player.discard.cards.forEach((c) => {
          if (c instanceof EnergyCard && c.energyType === 0 /* BASIC */) {
            basicEnergyCards++;
          }
        });
        if (basicEnergyCards === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        player.usedPlusCharge = true;
        ABILITY_USED(player, this);
        const opponent = StateUtils.getOpponent(state, player);
        const min = Math.min(basicEnergyCards, 2);
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.discard,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min, max: min, allowCancel: false }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: this });
              if (cards.length > 0) {
                MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: this });
                state = store.prompt(
                  state,
                  new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
                  () => state
                );
              }
            }
            if (cards.length > 0) {
            }
          }
        );
      }
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (state.phase !== 3 /* ATTACK */ || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) {
          ADD_MARKER("OPPONENT_KNOCKOUT_MARKER", player, this);
        }
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) {
          REMOVE_OPPONENT_LAST_TURN_MARKER_AT_END_OF_TURN(effect, "OPPONENT_KNOCKOUT_MARKER", this);
        }
        player.usedPlusCharge = false;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let isMinunInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card.name === "Minun") {
            isMinunInPlay = true;
          }
        });
        if (isMinunInPlay) {
          const player2 = effect.player;
          const hasBench = player2.bench.some((b) => b.cards.length > 0);
          if (hasBench === false) {
            return state;
          }
          effect.damage = 0;
          return store.prompt(
            state,
            new ChoosePokemonPrompt(
              player2.id,
              GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
              1 /* TOP_PLAYER */,
              [2 /* BENCH */, 1 /* ACTIVE */],
              { allowCancel: false }
            ),
            (targets) => {
              if (!targets || targets.length === 0) {
                return;
              }
              const damageEffect = new PutDamageEffect(effect, 20);
              damageEffect.target = targets[0];
              store.reduceEffect(state, damageEffect);
            }
          );
        }
        return state;
      }
      return state;
    }
  };

