  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/04-diamond-pearl-platinum/set-secret-wonders/roseannes-research.ts
  init_game();
  init_play_card_effects();
  init_prefabs();
  var RoseannesResearch = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.cardImage = "assets/cardback.png";
      this.set = "SW";
      this.setNumber = "125";
      this.name = "Roseanne's Research";
      this.fullName = "Roseanne's Research SW";
      this.text = "Search your deck for up to 2 in any combination of Basic Pok\xE9mon and basic Energy cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [this], sourceCard: this });
        BLOCK_IF_DECK_EMPTY(player);
        const blocked = [];
        player.deck.cards.forEach((c, index) => {
          const isBasicEnergy = c instanceof EnergyCard && c.energyType === 0 /* BASIC */;
          const isBasicPokemon = c instanceof PokemonCard && c.stage === 2 /* BASIC */;
          if (!(isBasicEnergy || isBasicPokemon)) {
            blocked.push(index);
          }
        });
        effect.preventDefault = true;
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DECK,
            player.deck,
            {},
            { min: 0, max: 2, allowCancel: false, blocked }
          ),
          (cards) => {
            if (!cards || cards.length === 0) {
              return state;
            }
            cards.forEach((card) => MOVE_CARD_TO(state, card, player.hand));
            SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
            SHUFFLE_DECK(store, state, player);
          }
        );
        MOVE_CARDS(store, state, player.supporter, player.discard, {
          cards: [this],
          sourceCard: this
        });
      }
      return state;
    }
  };

