  var Skiploom2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Hoppip";
      this.cardType = [G];
      this.hp = 60;
      this.weakness = [{ type: R, value: 20 }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [];
      this.powers = [{
        name: "Cotton Balloon",
        powerType: 0 /* POKEBODY */,
        text: "If Skiploom has any [G] Energy attached to it, any damage done to Skiploom by attacks from your opponent's Evolved Pok\xE9mon is reduced by 20 (after applying Weakness and Resistance)."
      }];
      this.attacks = [{
        name: "U-turn",
        cost: [G],
        damage: 20,
        text: "Switch Skiploom with 1 of your Benched Pok\xE9mon."
      }];
      this.set = "SW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "65";
      this.name = "Skiploom";
      this.fullName = "Skiploom SW";
      this.usedSmashTurn = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.getPokemonCard() === this) {
        const player = effect.player;
        if (IS_POKEBODY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const hasGrassEnergy = checkProvidedEnergy.energyMap.some(
          (energy2) => energy2.provides.includes(1 /* GRASS */) || energy2.provides.includes(0 /* ANY */)
        );
        if (hasGrassEnergy && effect.source.getPokemons().length > 1) {
          effect.damage -= 20;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedSmashTurn = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedSmashTurn) {
        const player = effect.player;
        SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
        this.usedSmashTurn = false;
      }
      return state;
    }
  };

