  var Baltoy2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 50;
      this.weakness = [{ type: G, value: 10 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Psychic Balance",
          cost: [C],
          damage: 0,
          text: "If you have less cards in your hand than your opponent, draw cards until you have the same number of cards as your opponent. (If you have more or the same number of cards in your hand as your opponent, this attack does nothing.)"
        },
        {
          name: "Spin Turn",
          cost: [F, C],
          damage: 20,
          text: "Switch Baltoy with 1 of your Benched Pok\xE9mon."
        }
      ];
      this.set = "GE";
      this.setNumber = "60";
      this.name = "Baltoy";
      this.fullName = "Baltoy GE";
      this.cardImage = "assets/cardback.png";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        while (player.hand.cards.length < opponent.hand.cards.length) {
          if (player.deck.cards.length === 0) {
            break;
          }
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
        }
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: true }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            return state;
          }
          const target = selected[0];
          player.switchPokemon(target);
        });
      }
      return state;
    }
  };

