  var FelicitysDrawing = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "GE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "98";
      this.name = "Felicity's Drawing";
      this.fullName = "Felicity's Drawing GE";
      this.text = "Discard up to 2 cards from your hand. If you discard 1 card, draw 3 cards. If you discard 2 cards, draw 4 cards.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.hand.cards.length < 2) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            {},
            { allowCancel: true, min: 0, max: 2 }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length === 0) {
              return;
            }
            const drawCount = cards.length === 1 ? 3 : cards.length === 2 ? 4 : 0;
            MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
            DRAW_CARDS(store, state, player, drawCount);
          }
        );
        return state;
      }
      return state;
    }
  };

