  var PremierBall = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "GE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "101";
      this.name = "Premier Ball";
      this.fullName = "Premier Ball GE";
      this.text = "Search your deck or your discard pile for a Pok\xE9mon LV.X, show it to your opponent, and put it into your hand. If you search your deck, shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (!(effect instanceof TrainerEffect) || effect.trainerCard !== this) return state;
      const player = effect.player, opponent = state.players.find((owner) => owner !== player);
      const isLevel = (card) => card.superType === 1 /* POKEMON */ && (card.stage === 11 /* LV_X */ || card.hasTag("Lv.X" /* POKEMON_LV_X */));
      const options = [...player.deck.cards.length ? [player.deck] : [], ...player.discard.cards.some(isLevel) ? [player.discard] : []];
      if (!options.length) throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
      const search = (zone) => store.prompt(state, new ChooseCardsPrompt(player, GameMessage.CHOOSE_CARD_TO_HAND, zone, { superType: 1 /* POKEMON */, stage: 11 /* LV_X */ }, { min: zone === player.deck ? 0 : 1, max: 1, allowCancel: false }), (selected) => {
        const cards = selected || [];
        const finish = () => {
          MOVE_CARDS(store, state, zone, player.hand, { cards, sourceCard: this, sourceEffect: effect });
          if (zone === player.deck) SHUFFLE_DECK(store, state, player);
        };
        if (cards.length) store.prompt(state, new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards), finish);
        else finish();
      });
      if (options.length === 1) return search(options[0]);
      return store.prompt(state, new SelectPrompt(player.id, GameMessage.CHOOSE_OPTION, ["Search deck", "Search discard pile"], { allowCancel: false }), (choice) => search(options[choice]));
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/04-diamond-pearl-platinum/set-great-encounters/unown-g.ts
