  function* usePower4(next, store, state, self, effect) {
    const player = effect.player;
    const cardList = StateUtils.findCardList(state, self);
    const benchIndex = player.bench.indexOf(cardList);
    if (benchIndex === -1) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    const pokemonCard = player.bench[benchIndex].getPokemonCard();
    if (pokemonCard !== self) {
      throw new GameError(GameMessage.ILLEGAL_ACTION);
    }
    let hasPokemonWithoutTool = false;
    const blocked = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card, target) => {
      if (cardList2.tools.length === 0 && card !== self) {
        hasPokemonWithoutTool = true;
      } else {
        blocked.push(target);
      }
    });
    if (!hasPokemonWithoutTool) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    return store.prompt(state, new ChoosePokemonPrompt(
      player.id,
      GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
      2 /* BOTTOM_PLAYER */,
      [1 /* ACTIVE */, 2 /* BENCH */],
      { allowCancel: true, blocked }
    ), (targets) => {
      if (targets && targets.length > 0) {
        MOVE_CARDS(store, state, player.bench[benchIndex], targets[0], { cards: [pokemonCard], sourceCard: self });
        targets[0].tools.push(pokemonCard);
        const unownGSlot = player.bench[benchIndex];
        const unownGCard = unownGSlot.getPokemonCard();
        if (!unownGCard) {
          return state;
        }
        const otherCards = unownGSlot.cards.filter(
          (card) => !(card instanceof PokemonCard) && !unownGSlot.getPokemons().includes(card) && (!unownGSlot.tools || !unownGSlot.tools.includes(card))
        );
        const tools = [...unownGSlot.tools];
        if (tools.length > 0) {
          for (const tool of tools) {
            MOVE_CARDS(store, state, unownGSlot, player.discard, { cards: [tool], sourceCard: self });
          }
        }
        if (otherCards.length > 0) {
          MOVE_CARDS(store, state, unownGSlot, player.discard, { cards: otherCards });
        }
        unownGSlot.clearEffects();
      }
    });
  }
  var UnownG = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 50;
      this.weakness = [{ type: P, value: 10 }];
      this.retreat = [C];
      this.powers = [{
        name: "GUARD",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), if Unown G is on your Bench, you may discard all cards attached to Unown G and attach Unown G to 1 of your Pok\xE9mon as a Pok\xE9mon Tool card. As long as Unown G is attached to a Pok\xE9mon, prevent all effects of attacks, excluding damage, done to that Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Hidden Power",
        cost: [P, C],
        damage: 50,
        text: "If Unown G has any damage counters on it, this attack's base damage is 10."
      }];
      this.set = "GE";
      this.name = "Unown [G]";
      this.fullName = "Unown [G] GE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "57";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const generator = usePower4(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (effect instanceof AttackEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() !== this) {
        const pokemonCard = effect.target.getPokemonCard();
        const sourceCard = effect.source.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (sourceCard) {
          try {
            const player = StateUtils.findOwner(state, effect.target);
            const stub = new PowerEffect(player, {
              name: "test",
              powerType: 2 /* ABILITY */,
              text: ""
            }, this);
            store.reduceEffect(state, stub);
          } catch {
            return state;
          }
          if (effect instanceof ApplyWeaknessEffect) {
            return state;
          }
          if (effect instanceof PutDamageEffect) {
            return state;
          }
          if (effect instanceof DealDamageEffect) {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        if (effect.player.active.damage > 0) {
          effect.damage = 10;
        }
      }
      return state;
    }
  };

