  function* playCard50(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: self });
    effect.preventDefault = true;
    let SPMons = 0;
    let basicEnergy2 = 0;
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      if (c instanceof PokemonCard && c.hasTag("SP" /* POKEMON_SP */)) {
        SPMons += 1;
      } else if (c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */) {
        basicEnergy2 += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxPokemons = Math.min(SPMons, 1);
    const maxBasicEnergies = Math.min(basicEnergy2, 1);
    const count = maxPokemons + maxBasicEnergies;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARDS,
        player.deck,
        {},
        { min: 0, max: count, allowCancel: false, blocked, maxPokemons, maxBasicEnergies }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    cards.forEach((card, index) => {
      store.log(state, "LOG_PLAYER_PUTS_CARD_IN_HAND" /* LOG_PLAYER_PUTS_CARD_IN_HAND */, { name: player.name, card: card.name });
    });
    SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
    SHUFFLE_DECK(store, state, player);
  }
  var AaronsCollection = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "RR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "88";
      this.name = "Aaron's Collection";
      this.fullName = "Aaron's Collection RR";
      this.text = "Search your discard pile for up to 2 in any combination of Pok\xE9mon SP and basic Energy cards, show them to your opponent, and put them into your hand.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard50(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

