  var ToxicroakG = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["SP" /* POKEMON_SP */];
      this.cardType = [F];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Leap Away",
          useWhenInPlay: true,
          powerType: 1 /* POKEPOWER */,
          text: "Once during your turn (before your attack), if Toxicroak G is your Active Pok\xE9mon, you may flip a coin. If heads, return Toxicroak G and all cards attached to it to your hand. This power can't be used if Toxicroak G is affected by a Special Condition."
        }
      ];
      this.attacks = [
        {
          name: "Poison Revenge",
          cost: [P, C],
          damage: 20,
          damageCalculation: "+",
          text: "If any of your Pok\xE9mon were Knocked Out by damage from an opponent's attack during his or her last turn, this attack does 20 damage plus 40 more damage and the Defending Pok\xE9mon is now Poisoned."
        }
      ];
      this.set = "DPP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "41";
      this.name = "Toxicroak G";
      this.fullName = "Toxicroak G DPP";
      this.LEAP_AWAY_MARKER = "LEAP_AWAY_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.LEAP_AWAY_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        BLOCK_IF_HAS_SPECIAL_CONDITION(player, this);
        if (player.active.getPokemonCard() !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (HAS_MARKER(this.LEAP_AWAY_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        ADD_MARKER(this.LEAP_AWAY_MARKER, player, this);
        ABILITY_USED(player, this);
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            const pokemonCardList = cardList;
            if (!pokemonCardList.getPokemonCard()) {
              return state;
            }
            MOVE_POKEMON_OFF_BOARD(store, state, pokemonCardList, {
              pokemonDestination: player.hand,
              attachedDestination: player.discard,
              sourceCard: this
            });
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.LEAP_AWAY_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (WAS_POKEMON_KNOCKED_OUT_DURING_OPPONENTS_LAST_TURN(player, { byAttackDamage: true })) {
          effect.damage += 40;
        }
        return state;
      }
      return state;
    }
  };

