  var MiracleDiamond = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "BRP";
      this.name = "Miracle Diamond";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "1";
      this.fullName = "Miracle Diamond BRP";
      this.text = "Look at all of your face-down Prize cards. You may choose 1 Trainer, Supporter, or Stadium card you find there, show it to your opponent, and put it into your hand. If you do, put this card as a Prize card face up instead of discarding it.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const prizes = player.prizes.filter((p) => p.isSecret);
        if (prizes.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const cards = [];
        prizes.forEach((p) => {
          p.cards.forEach((c) => cards.push(c));
        });
        const blocked = [];
        player.prizes.forEach((c, index) => {
          if (c.faceUpPrize) {
            blocked.push(index);
          }
        });
        prizes.forEach((p) => {
          p.isSecret = false;
        });
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        const allPrizeCards = new CardList();
        player.prizes.forEach((prizeList) => {
          allPrizeCards.cards.push(...prizeList.cards);
        });
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            allPrizeCards,
            { superType: 2 /* TRAINER */ },
            { min: 0, max: 1, allowCancel: false, blocked }
          ),
          (chosenPrize) => {
            if (chosenPrize === null || chosenPrize.length === 0) {
              player.prizes.forEach((p) => {
                p.isSecret = true;
              });
              return state;
            }
            const prizePokemon = chosenPrize[0];
            const hand = player.hand;
            const heavyBall = effect.trainerCard;
            const chosenPrizeList = player.prizes.find(
              (prizeList) => prizeList.cards.includes(prizePokemon)
            );
            if (chosenPrize.length > 0) {
              state = store.prompt(
                state,
                new ShowCardsPrompt(
                  opponent.id,
                  GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                  chosenPrize
                ),
                () => {
                }
              );
            }
            if (chosenPrizeList) {
              MOVE_CARDS(store, state, chosenPrizeList, hand, {
                cards: [prizePokemon],
                sourceCard: this
              });
              MOVE_CARDS(store, state, player.supporter, chosenPrizeList, {
                cards: [heavyBall],
                sourceCard: this
              });
            }
            player.prizes.forEach((p) => {
              p.isSecret = true;
            });
            return state;
          }
        );
      }
      return state;
    }
  };

