  var CheerleadersCheer = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CL";
      this.name = "Cheerleader's Cheer";
      this.fullName = "Cheerleader's Cheer CL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "76";
      this.text = "Draw 3 cards. Your opponent may draw a card.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        DRAW_CARDS(store, state, player, 3);
        if (opponent.deck.cards.length > 0) {
          CONFIRMATION_PROMPT(
            store,
            state,
            opponent,
            (result) => {
              if (result) {
                DRAW_CARDS(store, state, opponent, 1);
              }
            },
            GameMessage.WANT_TO_DRAW_CARDS
          );
        }
      }
      return state;
    }
  };

