  var Jirachi4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 60;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Stardust Song",
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn, when you put Jirachi from your hand onto your Bench, you may flip 3 coins. For each heads, search your discard pile for a [P] Energy card and attach it to Jirachi."
      }];
      this.attacks = [{
        name: "Time Hollow",
        cost: [P],
        damage: 0,
        text: "Choose a number of your opponent's Stage 1 or Stage 2 Evolved Pok\xE9mon up to the amount of Energy attached to Jirachi. Remove the highest Stage Evolution card from each of those Pok\xE9mon and put those cards back into your opponent's hand."
      }];
      this.set = "CL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "11";
      this.name = "Jirachi";
      this.fullName = "Jirachi CL";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (!player.discard.cards.some((c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(5 /* PSYCHIC */))) {
          return state;
        }
        if (IS_POKEPOWER_BLOCKED(store, state, player, this)) {
          return state;
        }
        CONFIRMATION_PROMPT(store, state, player, (wantToUse) => {
          if (wantToUse) {
            const powerEffect = new PowerEffect(player, this.powers[0], this);
            store.reduceEffect(state, powerEffect);
            const blocked = [];
            player.discard.cards.forEach((c, index) => {
              if (!(c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(5 /* PSYCHIC */))) {
                blocked.push(index);
              }
            });
            ABILITY_USED(player, this);
            let heads = 0;
            MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
              results.forEach((r) => {
                if (r) heads++;
              });
              const energyCount = Math.min(heads, player.discard.cards.filter((c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(5 /* PSYCHIC */)).length);
              const blockedTo = [];
              player.bench.forEach((list, index) => {
                if (index !== effect.index) {
                  blockedTo.push({
                    player: 2 /* BOTTOM_PLAYER */,
                    slot: 2 /* BENCH */,
                    index
                  });
                }
              });
              if (energyCount > 0) {
                state = store.prompt(state, new AttachEnergyPrompt(
                  player.id,
                  GameMessage.ATTACH_ENERGY_TO_BENCH,
                  player.discard,
                  2 /* BOTTOM_PLAYER */,
                  [2 /* BENCH */],
                  { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Psychic Energy" },
                  { allowCancel: false, min: energyCount, max: energyCount, blockedTo }
                ), (transfers) => {
                  transfers = transfers || [];
                  if (transfers.length === 0) {
                    return;
                  }
                  for (const transfer of transfers) {
                    const target = StateUtils.getTarget(state, player, transfer.to);
                    MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
                  }
                });
              }
            });
          }
        }, GameMessage.WANT_TO_USE_ABILITY);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let canDevolve = false;
        const blocked = [];
        effect.opponent.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (list.getPokemons().length > 1 && (list.getPokemonCard()?.stage === 3 /* STAGE_1 */ || list.getPokemonCard()?.stage === 4 /* STAGE_2 */)) {
            canDevolve = true;
          } else {
            blocked.push(target);
          }
        });
        if (!canDevolve) {
          return state;
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, player.active);
        state = store.reduceEffect(state, checkProvidedEnergy);
        if (checkProvidedEnergy.energyMap.length === 0) {
          return state;
        }
        store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { allowCancel: false, min: 0, max: checkProvidedEnergy.energyMap.length, blocked }
          ),
          (results) => {
            if (results && results.length > 0) {
              for (const targetPokemon of results) {
                const pokemons = targetPokemon.getPokemons();
                if (pokemons.length > 1) {
                  const highestStagePokemon = pokemons[pokemons.length - 1];
                  MOVE_CARDS(store, state, targetPokemon, effect.opponent.hand, { cards: [highestStagePokemon], sourceCard: this });
                  targetPokemon.clearEffects();
                  targetPokemon.pokemonPlayedTurn = state.turn;
                }
              }
            }
            return state;
          }
        );
      }
      return state;
    }
  };

