  var Pachirisu2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 60;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Self-Generation",
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn, when you put Pachirisu from your hand onto your Bench, you may attach up to 2 [L] Energy cards from your hand to Pachirisu."
      }];
      this.attacks = [
        {
          name: "Shocking Bolt",
          cost: [L, L],
          damage: 50,
          text: "Put all Energy cards attached to Pachirisu in the Lost Zone."
        }
      ];
      this.set = "CL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "18";
      this.name = "Pachirisu";
      this.fullName = "Pachirisu CL";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_POKEPOWER_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            const powerEffect = new PowerEffect(player, this.powers[0], this);
            store.reduceEffect(state, powerEffect);
            const hasEnergyInHand = player.hand.cards.some((c) => {
              return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(4 /* LIGHTNING */);
            });
            if (!hasEnergyInHand) {
              throw new GameError(GameMessage.CANNOT_USE_POWER);
            }
            const cardList = StateUtils.findCardList(state, this);
            if (cardList === void 0) {
              return state;
            }
            return store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_ATTACH,
              player.hand,
              { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Lightning Energy" },
              { min: 0, max: 2, allowCancel: false }
            ), (cards) => {
              cards = cards || [];
              if (cards.length > 0) {
                MOVE_CARDS(store, state, player.hand, cardList, { cards, sourceCard: this, sourceEffect: this.powers[0] });
              }
            });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        if (!(cardList instanceof PokemonCardList))
          throw new GameError(GameMessage.INVALID_TARGET);
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const cards = checkProvidedEnergy.energyMap.map((e) => e.card);
        cards.forEach((card) => {
          MOVE_CARDS(store, state, cardList, player.lostzone, { cards: [card], sourceCard: this, sourceEffect: this.attacks[0] });
        });
      }
      return state;
    }
  };

