  var Cleffa3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [9 /* COLORLESS */];
      this.hp = 30;
      this.retreat = [];
      this.powers = [{
        name: "Sweet Sleeping Face",
        powerType: 0 /* POKEBODY */,
        text: "As long as Cleffa is Asleep, prevent all damage done to Cleffa by attacks."
      }];
      this.attacks = [
        {
          name: "Eeeeeeek",
          cost: [],
          damage: 0,
          text: "Shuffle your hand into your deck, then draw 6 cards. Cleffa is now Asleep."
        }
      ];
      this.set = "HS";
      this.name = "Cleffa";
      this.fullName = "Cleffa HS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "17";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        MOVE_CARDS(store, state, player.hand, player.deck, { sourceCard: this });
        const specialCondition = new AddSpecialConditionsEffect(effect, [2 /* ASLEEP */]);
        specialCondition.target = player.active;
        store.reduceEffect(state, specialCondition);
        return store.prompt(state, [
          new ShuffleDeckPrompt(player.id)
        ], (deckOrder) => {
          player.deck.applyOrder(deckOrder);
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 6, sourceCard: this });
        });
      }
      if (effect instanceof PutDamageEffect) {
        if (effect.target.cards.includes(this)) {
          const pokemonCard = effect.target.getPokemonCard();
          const isAsleep = effect.target.specialConditions.includes(2 /* ASLEEP */);
          if (pokemonCard === this && isAsleep) {
            try {
              const stub = new PowerEffect(effect.player, {
                name: "test",
                powerType: 2 /* ABILITY */,
                text: ""
              }, this);
              store.reduceEffect(state, stub);
            } catch {
              return state;
            }
            effect.preventDefault = true;
          }
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-evolving-skies/copycat.ts
  init_play_card_effects();
  init_trainer_card();
  init_card_types();
  init_shuffle_prompt();
  init_state_utils();
  init_prefabs();
  function* playCard52(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const cards = player.hand.cards.filter((c) => c !== self);
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    if (cards.length > 0) {
      MOVE_CARDS(store, state, player.hand, player.deck, { cards, sourceCard: self });
    }
    yield store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
      next();
    });
    const cardsNumber = opponent.hand.cards.length;
    DRAW_CARDS(store, state, player, cardsNumber);
    return state;
  }
  var Copycat2 = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "EVS";
      this.regulationMark = "E";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "143";
      this.name = "Copycat";
      this.fullName = "Copycat EVS";
      this.text = "Shuffle your hand into your deck. Then, draw a card for each card in your opponent's hand.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard52(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

