  var Ninetales3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Vulpix";
      this.cardType = [R];
      this.hp = 90;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.powers = [{
        name: "Roast Reveal",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), you may discard a [R] Energy card from your hand. If you do, draw 3 cards. This power can't be used if Ninetales is affected by a Special Condition."
      }];
      this.attacks = [
        {
          name: "Will-o'-the-wisp",
          cost: [R, R, C],
          damage: 60,
          text: ""
        }
      ];
      this.set = "HS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "7";
      this.name = "Ninetales";
      this.fullName = "Ninetales HS";
      this.ROAST_REVEAL_MARKER = "ROAST_REVEAL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c instanceof EnergyCard && c.name === "Fire Energy";
        });
        if (HAS_MARKER(this.ROAST_REVEAL_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.active.cards[0] === this && player.active.specialConditions.length > 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 3 /* ENERGY */, name: "Fire Energy" },
          { allowCancel: true, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
          DRAW_CARDS(store, state, player, 3);
        });
        ADD_MARKER(this.ROAST_REVEAL_MARKER, player, this);
        ABILITY_USED(player, this);
        return state;
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        REMOVE_MARKER(this.ROAST_REVEAL_MARKER, player, this);
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.ROAST_REVEAL_MARKER, this);
      return state;
    }
  };

