  var Smeargle = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 70;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [{
        name: "Portrait",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), if Smeargle is your Active Pokemon, you may look at your opponent's hand. If you do, choose a Support card you find there and use the effect of that card as the effect of this power. This power can't be used if Smeargle is affected by a Special Condition."
      }];
      this.attacks = [{
        name: "Tail Rap",
        cost: [C, C],
        damage: 20,
        text: "Flip 2 coins. This attack does 20 damage times the number of heads."
      }];
      this.set = "UD";
      this.name = "Smeargle";
      this.fullName = "Smeargle UD";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "8";
      this.PORTRAIT_MARKER = "PORTRAIT_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.PORTRAIT_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const cardList = StateUtils.findCardList(state, this);
        if (cardList.specialConditions.length > 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (cardList !== player.active) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.PORTRAIT_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.marker.addMarker(this.PORTRAIT_MARKER, this);
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_COPY_EFFECT,
          opponent.hand,
          { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
          { allowCancel: true, min: 1, max: 1 }
        ), (cards) => {
          if (cards === null || cards.length === 0) {
            return;
          }
          const trainerCard = cards[0];
          const playTrainerEffect = new TrainerEffect(player, trainerCard);
          store.reduceEffect(state, playTrainerEffect);
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          let heads = 0;
          results.forEach((r) => {
            heads += r ? 1 : 0;
          });
          effect.damage = 20 * heads;
        });
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.PORTRAIT_MARKER, this)) {
        effect.player.marker.removeMarker(this.PORTRAIT_MARKER, this);
      }
      return state;
    }
  };

