  var Blissey2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Chansey";
      this.cardType = [C];
      this.hp = 130;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Blissful Nurse",
        powerType: 1 /* POKEPOWER */,
        useWhenInPlay: false,
        text: "Once during your turn, when you play Blissey from your hand to evolve 1 of your Pok\xE9mon, you may remove all damage counters from all of your Pok\xE9mon. If you do, discard all Energy attached to those Pok\xE9mon that had any damage counters on them."
      }];
      this.attacks = [{
        name: "Strength",
        cost: [C, C, C],
        damage: 60,
        text: ""
      }];
      this.set = "HS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "106";
      this.name = "Blissey";
      this.fullName = "Blissey HS";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this) && !IS_POKEPOWER_BLOCKED(store, state, effect.player, this)) {
        const player = effect.player;
        CONFIRMATION_PROMPT(store, state, player, (result) => {
          if (result) {
            ABILITY_USED(player, this);
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
              if (cardList.damage > 0) {
                const healEffect = new HealEffect(player, cardList, cardList.damage);
                state = store.reduceEffect(state, healEffect);
                const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
                state = store.reduceEffect(state, checkProvidedEnergy);
                const cards = checkProvidedEnergy.energyMap.map((e) => e.card);
                MOVE_CARDS(store, state, cardList.energies, player.discard, { cards });
              }
            });
          }
        }, GameMessage.WANT_TO_USE_ABILITY);
      }
      return state;
    }
  };

