  var Drowzee3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 60;
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Sleep Inducer",
          cost: [5 /* PSYCHIC */],
          damage: 0,
          text: "Switch the Defending Pokemon with 1 of your opponent's Benched Pokemon. The new Defending Pokemon is now Asleep."
        },
        {
          name: "Gentle Slap",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 20,
          text: ""
        }
      ];
      this.set = "HS";
      this.name = "Drowzee";
      this.fullName = "Drowzee HS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "62";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          opponent.switchPokemon(targets[0]);
          const specialCondition = new AddSpecialConditionsEffect(effect, [2 /* ASLEEP */]);
          specialCondition.target = targets[0];
          store.reduceEffect(state, specialCondition);
        });
      }
      return state;
    }
  };

