  var Hypno2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Drowzee";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Sleep Pendulum",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), you may flip a coin. If heads, the Defending Pokemon is now Asleep. This power can't be used if Hypno is affected by a Special Condition."
      }];
      this.attacks = [{
        name: "Psychic Shot",
        cost: [P, C, C],
        damage: 30,
        text: "Does 10 damage to 1 of your opponent's Benched Pokemon. (Don't apply Weakness and Resistance for Benched Pokemon.)"
      }];
      this.set = "HS";
      this.name = "Hypno";
      this.fullName = "Hypno HS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "23";
      this.SLEEP_PENDULUM_MAREKER = "SLEEP_PENDULUM_MAREKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.SLEEP_PENDULUM_MAREKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const cardList = StateUtils.findCardList(state, this);
        if (cardList.specialConditions.length > 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.SLEEP_PENDULUM_MAREKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.marker.addMarker(this.SLEEP_PENDULUM_MAREKER, this);
        if (opponent.active.specialConditions.includes(2 /* ASLEEP */)) {
          return state;
        }
        state = COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            opponent.active.addSpecialCondition(2 /* ASLEEP */);
          }
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        state = store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          const damageEffect = new PutDamageEffect(effect, 10);
          damageEffect.target = targets[0];
          store.reduceEffect(state, damageEffect);
        });
        return state;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.SLEEP_PENDULUM_MAREKER, this)) {
        effect.player.marker.removeMarker(this.SLEEP_PENDULUM_MAREKER, this);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/05-heartgold-and-soulsilver/set-heartgold-and-soulsilver/pichu.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_effects();
  init_play_card_effects();
  init_attack_effects();
  init_prefabs();
  function* usePlayground(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const specialCondition = new AddSpecialConditionsEffect(effect, [2 /* ASLEEP */]);
    specialCondition.target = player.active;
    store.reduceEffect(state, specialCondition);
    let slots2 = player.bench.filter((b) => b.cards.length === 0);
    let max = slots2.length;
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
      player.deck,
      { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
      { min: 0, max, allowCancel: true }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      store.reduceEffect(state, new PlayPokemonFromDeckEffect(player, card, slots2[index]));
    });
    slots2 = opponent.bench.filter((b) => b.cards.length === 0);
    max = slots2.length;
    yield store.prompt(state, new ChooseCardsPrompt(
      opponent,
      GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
      opponent.deck,
      { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
      { min: 0, max, allowCancel: true }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      store.reduceEffect(state, new PlayPokemonFromDeckEffect(opponent, card, slots2[index]));
    });
    store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
    store.prompt(state, new ShuffleDeckPrompt(opponent.id), (order) => {
      opponent.deck.applyOrder(order);
    });
    return state;
  }
  var Pichu4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 30;
      this.retreat = [];
      this.powers = [{
        name: "Sweet Sleeping Face",
        powerType: 0 /* POKEBODY */,
        text: "As long as Pichu is Asleep, prevent all damage done to Cleffa by attacks."
      }];
      this.attacks = [
        {
          name: "Playground",
          cost: [],
          damage: 0,
          text: "Each player may search his or her deck for as many Basic Pokemon as he or she likes, put them onto his or her Bench, and shuffle his or her deck afterward. (You put your Pokemon on the Bench first.) Pichu is now Asleep."
        }
      ];
      this.set = "HS";
      this.name = "Pichu";
      this.fullName = "Pichu HS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "28";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const generator = usePlayground(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      if (effect instanceof PutDamageEffect) {
        if (effect.target.cards.includes(this)) {
          const pokemonCard = effect.target.getPokemonCard();
          const isAsleep = effect.target.specialConditions.includes(2 /* ASLEEP */);
          if (pokemonCard === this && isAsleep) {
            try {
              const stub = new PowerEffect(effect.player, {
                name: "test",
                powerType: 2 /* ABILITY */,
                text: ""
              }, this);
              store.reduceEffect(state, stub);
            } catch {
              return state;
            }
            effect.preventDefault = true;
          }
        }
      }
      return state;
    }
  };

