  var Sunkern = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 40;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Cure Kernels",
          cost: [C],
          damage: 0,
          text: "Remove 2 damage counters from 1 of your Pok\xE9mon."
        },
        {
          name: "Seed Bomb",
          cost: [G, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "HS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "85";
      this.name = "Sunkern";
      this.fullName = "Sunkern HS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blocked = [];
        let hasPokemonWithDamage = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.damage === 0) {
            blocked.push(target);
          } else {
            hasPokemonWithDamage = true;
          }
        });
        if (hasPokemonWithDamage === false) {
          return state;
        }
        let targets = [];
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_HEAL,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (results) => {
          targets = results || [];
          if (targets.length === 0) {
            return state;
          }
          targets.forEach((target) => {
            const healEffect = new HealEffect(player, target, 20);
            store.reduceEffect(state, healEffect);
          });
        });
      }
      return state;
    }
  };

