  function* useFlareDestroy(next, store, state, effect) {
    const player = effect.player;
    const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
    state = store.reduceEffect(state, checkProvidedEnergy);
    if (player.active.cards.some((c) => c.superType === 3 /* ENERGY */)) {
      yield store.prompt(state, new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
        player.active,
        { superType: 3 /* ENERGY */ },
        { min: 1, max: 1, allowCancel: false }
      ), (selected) => {
        const cards = selected || [];
        const discardEnergy2 = new DiscardCardsEffect(effect, cards);
        discardEnergy2.target = player.active;
        store.reduceEffect(state, discardEnergy2);
        next();
      });
    }
    DISCARD_AN_ENERGY_FROM_OPPONENTS_ACTIVE_POKEMON(store, state, effect);
    return state;
  }
  var Typhlosion2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Quilava";
      this.cardType = [R];
      this.hp = 140;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Afterburner",
        powerType: 1 /* POKEPOWER */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may search your discard pile for a [R] Energy card and attach it to 1 of your Pok\xE9mon. If you do, put 1 damage counter on that Pok\xE9mon. This power can't be used if Typhlosion is affected by a Special Condition."
      }];
      this.attacks = [
        {
          name: "Flare Destroy",
          cost: [R, R, C],
          damage: 70,
          text: "Discard an Energy card attached to Typhlosion and discard an Energy card attached to the Defending Pok\xE9mon."
        }
      ];
      this.set = "HS";
      this.name = "Typhlosion";
      this.fullName = "Typhlosion HS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "110";
      this.AFTERBURNER_MARKER = "AFTERBURNER_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.AFTERBURNER_MARKER, this);
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const generator = useFlareDestroy(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        if (cardList.specialConditions.length > 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.provides.includes(2 /* FIRE */);
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.AFTERBURNER_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { allowCancel: true, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            return;
          }
          player.marker.addMarker(this.AFTERBURNER_MARKER, this);
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            target.damage += 10;
          }
        });
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.AFTERBURNER_MARKER, this);
      }
      return state;
    }
  };

