  function* playCard56(next, store, state, effect) {
    const player = effect.player;
    const prizes = player.prizes.filter((p) => p.isSecret);
    const cards = [];
    prizes.forEach((p) => {
      p.cards.forEach((c) => cards.push(c));
    });
    if (cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    prizes.forEach((p) => {
      p.isSecret = false;
    });
    yield store.prompt(
      state,
      new ShowCardsPrompt(player.id, GameMessage.CARDS_SHOWED_BY_EFFECT, cards),
      () => {
        next();
      }
    );
    prizes.forEach((p) => {
      p.isSecret = true;
    });
    return state;
  }
  var AlphLithograph = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "TM";
      this.name = "Alph Lithograph";
      this.fullName = "Alph Lithograph TM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "FOUR";
      this.text = "LOOK AT ALL OF YOUR FACE DOWN PRIZE CARDS!";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard56(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

