  var BlackBelt = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "TM";
      this.name = "Black Belt";
      this.fullName = "Black Belt TM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "85";
      this.text = "You may use this card only if you have more Prize cards left than your opponent. During this turn, each of your Active Pokemon's attacks does 40 more damage to your opponent's Active Pokemon (before applying Weakness and Resistance).";
      this.BLACK_BELT_MARKER = "BLACK_BELT_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.getPrizeLeft() <= opponent.getPrizeLeft()) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        player.marker.addMarker(this.BLACK_BELT_MARKER, this);
      }
      if (effect instanceof DealDamageEffect && effect.player.marker.hasMarker(this.BLACK_BELT_MARKER, this) && effect.damage > 0) {
        effect.damage += 40;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.BLACK_BELT_MARKER, this)) {
        effect.player.marker.removeMarker(this.BLACK_BELT_MARKER, this);
      }
      return state;
    }
  };

