  var Celebi = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 60;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [{
        name: "Forest Breath",
        powerType: 1 /* POKEPOWER */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), if Celebi is your Active Pok\xE9mon, you may attach a [G] Energy card from your hand to 1 of your Pok\xE9mon. This power can't be used if Celebi is affected by a Special Condition."
      }];
      this.attacks = [
        {
          name: "Time Circle",
          cost: [G, P, C],
          damage: 30,
          text: "During your opponent's next turn, prevent all damage done to Celebi by attacks from your opponent's Stage 1 or Stage 2 Pok\xE9mon."
        }
      ];
      this.set = "TM";
      this.setNumber = "92";
      this.cardImage = "assets/cardback.png";
      this.name = "Celebi";
      this.fullName = "Celebi TM";
      this.FOREST_BREATH_MARKER = "FOREST_BREATH_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.FOREST_BREATH_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        if (cardList.specialConditions.length > 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (cardList !== player.active) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c instanceof EnergyCard && c.name === "Grass Energy";
        });
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.FOREST_BREATH_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.hand,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */, name: "Grass Energy" },
          { allowCancel: true, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          ABILITY_USED(player, this);
          if (transfers.length === 0) {
            return;
          }
          player.marker.addMarker(this.FOREST_BREATH_MARKER, this);
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.hand, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        PREVENT_DAMAGE(store, state, effect, this, { sourceIsEvolution: true });
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.FOREST_BREATH_MARKER, this);
      }
      return state;
    }
  };

