  var Rotom2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 60;
      this.weakness = [{ type: 7 /* DARK */ }];
      this.resistance = [{ type: 9 /* COLORLESS */, value: -20 }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Mischievous Trick",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), you may switch 1 of your face-down Prize cards with the top card of your deck. This power can't be used if Rotom is affected by a Special Condition."
      }];
      this.attacks = [
        {
          name: "Plasma Arrow",
          cost: [4 /* LIGHTNING */],
          damage: 0,
          text: "Choose 1 of your opponent's Pokemon. This attack does 20 damage for each Energy attached to that Pokemon. This attack's damage isn't affected by Weakness or Resistance."
        }
      ];
      this.set = "UD";
      this.name = "Rotom";
      this.fullName = "Rotom UD";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "20";
      this.MISCHIEVOUS_TRICK_MAREKER = "MISCHIEVOUS_TRICK_MAREKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.MISCHIEVOUS_TRICK_MAREKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        if (cardList.specialConditions.length > 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.MISCHIEVOUS_TRICK_MAREKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.marker.addMarker(this.MISCHIEVOUS_TRICK_MAREKER, this);
        state = store.prompt(state, new ChoosePrizePrompt(
          player.id,
          GameMessage.CHOOSE_PRIZE_CARD,
          { count: 1, allowCancel: false }
        ), (prizes) => {
          if (prizes && prizes.length > 0) {
            const temp = player.deck.cards[0];
            player.deck.cards[0] = prizes[0].cards[0];
            prizes[0].cards[0] = temp;
          }
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        state = store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          let damage = 0;
          targets[0].cards.forEach((c) => {
            if (c instanceof EnergyCard) {
              damage += 20 * c.provides.length;
            }
          });
          DAMAGE_OPPONENT_POKEMON(store, state, effect, damage, targets);
        });
        return state;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.MISCHIEVOUS_TRICK_MAREKER, this)) {
        effect.player.marker.removeMarker(this.MISCHIEVOUS_TRICK_MAREKER, this);
      }
      return state;
    }
  };

