  var Slowpoke3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 60;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Rambunctious Party",
          cost: [C],
          damage: 0,
          text: "Look at the top 5 cards of your deck. Choose as many Basic Pok\xE9mon as you like and put them onto your Bench. Shuffle the other cards back into your deck."
        },
        {
          name: "Rain Splash",
          cost: [W, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "UD";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "66";
      this.name = "Slowpoke";
      this.fullName = "Slowpoke UD";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const openSlots = player.bench.filter((b) => b.cards.length === 0);
        if (openSlots.length === 0) {
          return state;
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: 5, sourceCard: this });
        const maxPokemons = Math.min(openSlots.length, deckTop.cards.filter((c) => c instanceof PokemonCard && c.stage === 2 /* BASIC */).length);
        let cards = [];
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          deckTop,
          { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
          { min: 0, max: maxPokemons, allowCancel: false }
        ), (selectedCards) => {
          cards = selectedCards || [];
          cards.forEach((card, index) => {
            MOVE_CARDS(store, state, deckTop, openSlots[index], { cards: [card], sourceCard: this });
            openSlots[index].pokemonPlayedTurn = state.turn;
          });
          MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: this });
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      return state;
    }
  };

