          const revealed = [...temp.cards];
          MOVE_CARDS(store, state, temp, player.discard, { sourceCard: this });
          store.prompt(state, [new ShowCardsPrompt(
            player.id,
            GameMessage.CARDS_SHOWED_BY_EFFECT,
            revealed
          )], () => {
          });
