  var Judge = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "SVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "176";
      this.regulationMark = "G";
      this.name = "Judge";
      this.fullName = "Judge SVI";
      this.text = "Each player shuffles their hand into their deck and draws 4 cards.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (player.hand.cards.length === 0 && player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.hand.cards.filter((c) => c !== this).length === 0 && player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        return SHUFFLE_HAND_INTO_DECK_THEN_DRAW(store, state, player, {
          excludeCard: this,
          sourceCard: this,
          drawCount: 4,
          afterDraw: () => {
            SHUFFLE_HAND_INTO_DECK_THEN_DRAW(store, state, opponent, {
              sourceCard: this,
              drawCount: 4
            });
          }
        });
      }
      return state;
    }
  };

