  var Aipom2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 50;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [{
        name: "Tail Code",
        cost: [C],
        damage: 0,
        text: "Move an Energy card attached to the Defending Pok\xE9mon to another of your opponent's Pok\xE9mon."
      }, {
        name: "Tail Smash",
        cost: [C, C],
        damage: 30,
        text: "Flip a coin. If tails, this attack does nothing."
      }];
      this.set = "UL";
      this.setNumber = "43";
      this.cardImage = "assets/cardback.png";
      this.name = "Aipom";
      this.fullName = "Aipom UL";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        const hasEnergy = opponent.active.cards.some((c) => c.superType === 3 /* ENERGY */);
        if (!hasBenched || !hasEnergy) {
          return state;
        }
        const blocked = [];
        opponent.active.cards.forEach((card, index) => {
          if (card.superType !== 3 /* ENERGY */) {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_ATTACH,
          opponent.active,
          { superType: 3 /* ENERGY */ },
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length === 0) {
            return;
          }
          return store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ), (targets) => {
            if (targets && targets.length > 0) {
              MOVE_CARDS(store, state, opponent.active, targets[0], { cards: [cards[0]], sourceCard: this });
            }
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (!result) {
            effect.damage = 0;
          }
        });
      }
      return state;
    }
  };

