  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/05-heartgold-and-soulsilver/set-unleashed/energy-returner.ts
  init_game_error();
  init_game_message();
  init_trainer_card();
  init_card_types();
  init_play_card_effects();
  init_choose_cards_prompt();
  init_shuffle_prompt();
