  init_state_utils();
  function* playCard62(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let energyInDiscard = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      const isBasicEnergy = c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
      if (isBasicEnergy) {
        energyInDiscard += 1;
      } else {
        blocked.push(index);
      }
    });
    if (energyInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    const min = Math.min(energyInDiscard, 4);
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { min, max: 4, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
    SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var EnergyReturner = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "UL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "74";
      this.name = "Energy Returner";
      this.fullName = "Energy Returner UL";
      this.text = "Search your discard pile for 4 basic Energy cards, show them to your opponent, and shuffle them into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard62(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

