  var InterviewersQuestions = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "UL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "77";
      this.name = "Interviewer's Questions";
      this.fullName = "Interviewer's Questions UL";
      this.text = "Look at the top 8 cards of your deck. Choose as many Energy cards as you like, show them to your opponent, and put them into your hand. Shuffle the other cards back into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const temp = new CardList();
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.deck, temp, { count: 8, sourceCard: this });
        const maxEnergyCards = Math.min(8, temp.cards.filter((c) => c instanceof EnergyCard).length);
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            temp,
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 0, max: maxEnergyCards }
          ),
          (chosenCards) => {
            if (chosenCards.length == 0) {
              temp.cards.forEach((card) => {
                MOVE_CARDS(store, state, temp, player.deck, { cards: [card], sourceCard: this });
              });
            }
            if (chosenCards.length > 0) {
              chosenCards.forEach((card) => {
                MOVE_CARDS(store, state, temp, player.hand, { cards: [card], sourceCard: this });
              });
              if (chosenCards.length > 0) {
                state = store.prompt(
                  state,
                  new ShowCardsPrompt(
                    opponent.id,
                    GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                    chosenCards
                  ),
                  () => state
                );
              }
              MOVE_CARDS(store, state, temp, player.deck, { sourceCard: this });
              if (chosenCards.length > 0) {
                state = store.prompt(
                  state,
                  new ShowCardsPrompt(
                    opponent.id,
                    GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                    chosenCards
                  ),
                  () => state
                );
              }
            }
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      return state;
    }
  };

