  var SuicuneAndEnteiLegendTop = class _SuicuneAndEnteiLegendTop extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 8 /* LEGEND */;
      this._tags = ["Legend" /* LEGEND */, "Dual Legend" /* DUAL_LEGEND */];
      this.cardType = [R, W];
      this.hp = 160;
      this.weakness = [{ type: W }, { type: L }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Legend Assembly",
          text: "Put this card from your hand onto your Bench only with the other half of Entei & Raikou LEGEND.",
          exemptFromAbilityLock: true,
          useFromHand: true,
          powerType: 8 /* LEGEND_ASSEMBLY */
        }
      ];
      this.attacks = [
        {
          name: "Torrent Blade",
          cost: [W, W, C],
          damage: 0,
          text: "Return 2 [W] Energy attached to Suicune & Entei LEGEND to your hand. Choose 1 of your opponent's Benched Pok\xE9mon. This attack does 100 damage to that Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Bursting Inferno",
          cost: [R, C, C],
          damage: 80,
          text: "The Defending Pok\xE9mon is now Burned."
        }
      ];
      this.set = "UL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "94";
      this.name = "Suicune & Entei LEGEND";
      this.fullName = "Suicune & Entei LEGEND (Top) UL";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (slots2.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        let topPiece = false;
        let bottomPiece = false;
        let topCard = null;
        let bottomCard = null;
        player.hand.cards.forEach((card) => {
          if (card instanceof _SuicuneAndEnteiLegendTop && !topPiece) {
            topPiece = true;
            topCard = card;
          }
          if (card instanceof SuicuneAndEnteiLegendBottom && !bottomPiece) {
            bottomPiece = true;
            bottomCard = card;
          }
        });
        if (topPiece && bottomPiece && topCard && bottomCard) {
          if (slots2.length > 0) {
            MOVE_CARDS(store, state, player.hand, slots2[0], { cards: [bottomCard], sourceCard: this });
            MOVE_CARDS(store, state, player.hand, slots2[0], { cards: [topCard], sourceCard: this });
            slots2[0].pokemonPlayedTurn = state.turn;
          }
        } else {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_BENCHED_POKEMON(100, effect, store, state);
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const energyList = [3 /* WATER */, 3 /* WATER */];
        state = store.prompt(
          state,
          new ChooseEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            checkProvidedEnergy.energyMap,
            energyList,
            { allowCancel: false }
          ),
          (energy2) => {
            const cards = (energy2 || []).map((e) => e.card);
            MOVE_CARDS(store, state, player.active, player.hand, {
              cards,
              sourceEffect: this.attacks[0]
            });
          }
        );
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        ADD_BURN_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

