  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-black-and-white/emboar.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attach_energy_prompt();
  init_play_card_effects();
  init_prefabs();
  var Emboar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Pignite";
      this.cardType = [R];
      this.hp = 150;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C, C];
      this.powers = [{
        name: "Inferno Fandango",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "As often as you like during your turn (before your attack), you may attach a [R] Energy card from your hand to 1 of your Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Heat Crash",
        cost: [R, R, C, C],
        damage: 80,
        text: ""
      }];
      this.set = "BLW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "20";
      this.name = "Emboar";
      this.fullName = "Emboar BLW";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(2 /* FIRE */);
        });
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.hand,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { allowCancel: false }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            const energyCard = transfer.card;
            const attachEnergyEffect = new AttachEnergyEffect(player, energyCard, target);
            store.reduceEffect(state, attachEnergyEffect);
          }
        });
      }
      return state;
    }
  };

