      this.attacks = [{
        name: "Glinting Claw",
        cost: [R, C, C],
        damage: 50,
        text: "Flip a coin. If heads, this attack does 30 more damage."
      }, {
        name: "Brave Fire",
        cost: [R, R, C, C],
        damage: 150,
        text: "Flip a coin. If tails, this Pokemon does 50 damage to itself."
      }];
