  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-emerging-powers/tornadus.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_message();
  init_prefabs();
  var Tornadus = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [9 /* COLORLESS */];
      this.hp = 110;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -20 }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Energy Wheel",
          cost: [9 /* COLORLESS */],
          damage: 0,
          text: "Move an Energy from 1 of your Benched Pokemon to this Pokemon."
        },
        {
          name: "Hurricane",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 80,
          text: "Move a basic Energy from this Pokemon to 1 of your Benched Pokemon."
        }
      ];
      this.set = "EPO";
      this.name = "Tornadus";
      this.fullName = "Tornadus EPO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "89";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blockedFrom = [];
        const blockedTo = [];
        let hasEnergyOnBench = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList === player.active) {
            blockedFrom.push(target);
            return;
          }
          blockedTo.push(target);
          if (cardList.cards.some((c) => c.superType === 3 /* ENERGY */)) {
            hasEnergyOnBench = true;
          }
        });
        if (hasEnergyOnBench === false) {
          return state;
        }
        return store.prompt(state, new MoveEnergyPrompt(
          effect.player.id,
          GameMessage.MOVE_ENERGY_TO_ACTIVE,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { min: 1, max: 1, allowCancel: false, blockedFrom, blockedTo }
        ), (result) => {
          const transfers = result || [];
          transfers.forEach((transfer) => {
            const source = StateUtils.getTarget(state, player, transfer.from);
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        const hasBasicEnergy = player.active.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
        });
        if (hasBench === false || hasBasicEnergy === false) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.active,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { allowCancel: false, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

