  function* usePowerBlast(next, store, state, effect) {
    const player = effect.player;
    if (!player.active.energies.cards.some((c) => c.superType === 3 /* ENERGY */)) {
      return state;
    }
    let flipResult = false;
    yield COIN_FLIP_PROMPT(store, state, player, (result) => {
      flipResult = result;
      next();
    });
    if (flipResult) {
      return state;
    }
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        player.active,
        { superType: 3 /* ENERGY */ },
        { min: 1, max: 1, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    const discardEnergy2 = new DiscardCardsEffect(effect, cards);
    discardEnergy2.target = player.active;
    return store.reduceEffect(state, discardEnergy2);
  }
