  var Kyurem = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [3 /* WATER */];
      this.hp = 130;
      this.weakness = [{ type: 8 /* METAL */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Outrage",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 20,
          damageCalculation: "+",
          text: "Does 10 more damage for each damage counter on this Pok\xE9mon."
        },
        {
          name: "Glaciate",
          cost: [3 /* WATER */, 3 /* WATER */, 9 /* COLORLESS */],
          damage: 0,
          text: "This attack does 30 damage to each of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "BWP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "44";
      this.name = "Kyurem";
      this.fullName = "Kyurem BWP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const damageCounters = effect.player.active.damage;
        effect.damage += damageCounters * 10;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const opponent = effect.opponent;
        const benched = opponent.bench.filter((b) => b.cards.length > 0);
        const activeDamageEffect = new DealDamageEffect(effect, 80);
        store.reduceEffect(state, activeDamageEffect);
        benched.forEach((target) => {
          const damageEffect = new PutDamageEffect(effect, 80);
          damageEffect.target = target;
          store.reduceEffect(state, damageEffect);
        });
      }
      return state;
    }
  };

