  init_game();
  init_prefabs();
  function* playCard63(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let basicEnergyCards = 0;
    player.discard.cards.forEach((c) => {
      if (c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */) {
        basicEnergyCards++;
      }
    });
    if (basicEnergyCards === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    const min = Math.min(basicEnergyCards, 2);
    return store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.discard,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { min: 1, max: min, allowCancel: false }
      ),
      (cards) => {
        cards = cards || [];
        if (cards.length > 0) {
          MOVE_CARDS(store, state, player.discard, player.hand, {
            cards,
            sourceCard: effect.trainerCard
          });
          if (cards.length > 0) {
            MOVE_CARDS(store, state, player.discard, player.hand, {
              cards,
              sourceCard: effect.trainerCard
            });
            state = store.prompt(
              state,
              new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
              () => state
            );
          }
        }
        if (cards.length > 0) {
        }
      }
    );
  }
  var EnergyRetrieval2 = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "SVI";
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "171";
      this.name = "Energy Retrieval";
      this.fullName = "Energy Retrieval SVI";
      this.text = "Put 2 basic Energy cards from your discard pile into your hand.";
    }
    canPlay(store, state, player) {
      let basicEnergyCards = 0;
      player.discard.cards.forEach((c) => {
        if (c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */) {
          basicEnergyCards++;
        }
      });
      if (basicEnergyCards === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const discardEffect = new DiscardToHandEffect(player, this);
        store.reduceEffect(state, discardEffect);
        if (discardEffect.preventDefault) {
          return state;
        }
        const generator = playCard63(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

