  var PlusPower3 = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "BLW";
      this.name = "PlusPower";
      this.fullName = "PlusPower BLW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "96";
      this.text = "During this turn, your Pokemon's attacks do 10 more damage to the Active Pokemon (before applying Weakness and Resistance).";
      this.PLUS_POWER_MARKER = "PLUS_POWER_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        player.marker.addMarker(this.PLUS_POWER_MARKER, this);
      }
      if (effect instanceof DealDamageEffect) {
        const marker = effect.player.marker;
        if (marker.hasMarker(this.PLUS_POWER_MARKER, this) && effect.damage > 0) {
          effect.damage += 10;
        }
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.PLUS_POWER_MARKER, this);
      }
      return state;
    }
  };

