  var Pokedex2 = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "BLW";
      // Replace with the appropriate set abbreviation
      this.name = "Pok\xE9dex";
      this.fullName = "Pokedex BLW";
      // Replace with the appropriate set abbreviation
      this.cardImage = "assets/cardback.png";
      // Replace with the appropriate card image path
      this.setNumber = "98";
      // Replace with the appropriate set number
      this.text = "Look at the top 5 cards of your deck and put them back on top of your deck in any order.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: 5, sourceCard: this });
        return store.prompt(
          state,
          new OrderCardsPrompt(player.id, GameMessage.CHOOSE_CARDS_ORDER, deckTop, {
            allowCancel: false
          }),
          (order) => {
            if (order === null) {
              return state;
            }
            deckTop.applyOrder(order);
            deckTop.moveToTopOfDestination(player.deck);
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-black-and-white/professor-juniper.ts
