  var Dewott2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Oshawott";
      this.cardType = [W];
      this.hp = 80;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [{
        name: "Aqua Tail",
        cost: [C, C],
        damage: 30,
        damageCalculation: "+",
        text: "Flip a coin for each [W] Energy attached to this Pok\xE9mon. This attack does 10 more damage for each heads."
      }];
      this.set = "BLW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "30";
      this.name = "Dewott";
      this.fullName = "Dewott BLW 30";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        let waterEnergyCount = 0;
        checkEnergy.energyMap.forEach((em) => {
          waterEnergyCount += em.provides.filter((p) => p === 3 /* WATER */).length;
        });
        if (waterEnergyCount > 0) {
          MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, waterEnergyCount, (results) => {
            const heads = results.filter((r) => r).length;
            effect.damage += 10 * heads;
          });
        }
      }
      return state;
    }
  };

