  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-black-and-white/klinklang.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_pokemon_types();
  init_prefabs();
  init_attack_effects2();
  init_check_effects();
  function* useShiftGear(next, store, state, effect) {
    const player = effect.player;
    const blockedMap = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
      store.reduceEffect(state, checkProvidedEnergy);
      const blockedCards = [];
      checkProvidedEnergy.energyMap.forEach((em) => {
        if (!em.provides.includes(8 /* METAL */) && !em.provides.includes(0 /* ANY */)) {
          blockedCards.push(em.card);
        }
      });
      const blocked = [];
      blockedCards.forEach((bc) => {
        const index = cardList.cards.indexOf(bc);
        if (index !== -1 && !blocked.includes(index)) {
          blocked.push(index);
        }
      });
      if (blocked.length !== 0) {
        blockedMap.push({ source: target, blocked });
      }
    });
    return store.prompt(state, new MoveEnergyPrompt(
      effect.player.id,
      GameMessage.MOVE_ENERGY_CARDS,
      2 /* BOTTOM_PLAYER */,
      [1 /* ACTIVE */, 2 /* BENCH */],
      { superType: 3 /* ENERGY */ },
      { allowCancel: true, min: 0, max: 1, blockedMap }
    ), (transfers) => {
      if (transfers === null) {
        return;
      }
      for (const transfer of transfers) {
        const source = StateUtils.getTarget(state, player, transfer.from);
        const target = StateUtils.getTarget(state, player, transfer.to);
        MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: effect.card });
      }
    });
  }
  var Klinklang = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Klang";
      this.cardType = [M];
      this.hp = 140;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Shift Gear",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "As often as you like during your turn (before your attack), you may move a [M] Energy from 1 of your Pok\xE9mon to another of your Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Gear Saucer",
        cost: [M, M, C],
        damage: 80,
        text: "Does 20 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.set = "BLW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "76";
      this.name = "Klinklang";
      this.fullName = "Klinklang BLW";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        let hasMetalEnergy = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          checkProvidedEnergy.energyMap.forEach((em) => {
            if (em.provides.includes(8 /* METAL */) || em.provides.includes(0 /* ANY */)) {
              hasMetalEnergy = true;
            }
          });
        });
        if (!hasMetalEnergy) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const generator = useShiftGear(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_BENCHED_POKEMON(20, effect, store, state);
      }
      return state;
    }
  };

