  var Klink = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [M];
      this.hp = 60;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Charge Beam",
        cost: [M],
        damage: 10,
        text: "Flip a coin. If heads, attach an Energy card from your discard pile to this Pok\xE9mon."
      }, {
        name: "Bind",
        cost: [M, C, C],
        damage: 30,
        text: ""
      }];
      this.set = "BLW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "74";
      this.name = "Klink";
      this.fullName = "Klink BLW";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergy = player.discard.cards.some((c) => c.superType === 3 /* ENERGY */);
        if (hasEnergy) {
          COIN_FLIP_PROMPT(store, state, player, (result) => {
            if (result) {
              store.prompt(state, new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARD_TO_ATTACH,
                player.discard,
                { superType: 3 /* ENERGY */ },
                { min: 0, max: 1, allowCancel: false }
              ), (cards) => {
                cards = cards || [];
                if (cards.length > 0) {
                  MOVE_CARDS(store, state, player.discard, player.active, { cards, sourceCard: this });
                }
              });
            }
          });
        }
      }
      return state;
    }
  };

