  var Samurott2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Dewott";
      this.cardType = [W];
      this.hp = 140;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Shell Armor",
        powerType: 2 /* ABILITY */,
        text: "Any damage done to this Pok\xE9mon by attacks is reduced by 20 (after applying Weakness and Resistance)."
      }];
      this.attacks = [{
        name: "Hydro Pump",
        cost: [C, C, C],
        damage: 70,
        damageCalculation: "+",
        text: "Does 10 more damage for each [W] Energy attached to this Pok\xE9mon."
      }];
      this.set = "BLW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "32";
      this.name = "Samurott";
      this.fullName = "Samurott BLW 32";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let energyCount = 0;
        checkProvidedEnergyEffect.energyMap.forEach((em) => {
          energyCount += em.provides.filter((cardType) => {
            return cardType === 3 /* WATER */ || cardType === 0 /* ANY */;
          }).length;
        });
        effect.damage += energyCount * 10;
      }
      if (effect instanceof DealDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.damage = Math.max(0, effect.damage - 20);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-black-and-white/simisear.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects();
  init_choose_pokemon_prompt();
  var Simisear = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Pansear";
      this.cardType = [R];
      this.hp = 90;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.attacks = [{
        name: "Flame Burst",
        cost: [R],
        damage: 20,
        text: "Does 20 damage to 2 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }, {
        name: "Fury Swipes",
        cost: [C, C, C],
        damage: 40,
        damageCalculation: "x",
        text: "Flip 3 coins. This attack does 40 damage times the number of heads."
      }];
      this.set = "BLW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "22";
      this.name = "Simisear";
      this.fullName = "Simisear BLW";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const benchedTargets = opponent.bench.filter((b) => b.cards.length > 0);
        if (benchedTargets.length === 0) {
          return state;
        }
        const maxTargets = Math.min(2, benchedTargets.length);
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { min: maxTargets, max: maxTargets, allowCancel: false }
        ), (targets) => {
          if (targets && targets.length > 0) {
            targets.forEach((target) => {
              const putDamage = new PutDamageEffect(effect, 20);
              putDamage.target = target;
              store.reduceEffect(state, putDamage);
            });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 3, (results) => {
          let heads = 0;
          results.forEach((r) => {
            if (r) heads++;
          });
          effect.damage = 40 * heads;
        });
      }
      return state;
    }
  };

