  var Maractus2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 90;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Constant Rattle",
        cost: [G],
        damage: 0,
        text: "Flip 3 coins. If 1 of them is heads, this attack does 10 damage. If 2 of them are heads, this attack does 30 damage. If all of them are heads, this attack does 60 damage."
      }, {
        name: "Giga Drain",
        cost: [G, G, G],
        damage: 50,
        text: "Heal from this Pok\xE9mon the same amount of damage you did to the Defending Pok\xE9mon."
      }];
      this.set = "BLW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "12";
      this.name = "Maractus";
      this.fullName = "Maractus BLW 12";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 3, (results) => {
          const heads = results.filter((r) => r).length;
          if (heads === 1) {
            effect.damage = 10;
          } else if (heads === 2) {
            effect.damage = 30;
          } else if (heads === 3) {
            effect.damage = 60;
          } else {
            effect.damage = 0;
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const afterDamage = new AfterDamageEffect(effect, effect.damage);
        state = store.reduceEffect(state, afterDamage);
        HEAL_X_DAMAGE_FROM_THIS_POKEMON2(effect.damage, effect, store, state);
      }
      return state;
    }
  };

