  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-black-and-white/pikachu.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects();
  init_attach_energy_prompt();
  var Pikachu8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 60;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Energize",
          cost: [C],
          damage: 0,
          text: "Search your discard pile for a [L] Energy card and attach it to this Pok\xE9mon."
        },
        {
          name: "Thunderbolt",
          cost: [L, L, C],
          damage: 80,
          text: "Discard all Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "BLW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "115";
      this.name = "Pikachu";
      this.fullName = "Pikachu BLW";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasLightningEnergyInDiscard = player.discard.cards.some(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(4 /* LIGHTNING */)
        );
        if (!hasLightningEnergyInDiscard) {
          return state;
        }
        const blockedTo = [];
        player.bench.forEach((_, index) => {
          blockedTo.push({
            player: 2 /* BOTTOM_PLAYER */,
            slot: 2 /* BENCH */,
            index
          });
        });
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_ACTIVE,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Lightning Energy" },
          { allowCancel: true, min: 0, max: 1, blockedTo }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const allEnergies = player.active.cards.filter((c) => c.superType === 3 /* ENERGY */);
        if (allEnergies.length > 0) {
          const discardEnergy2 = new DiscardCardsEffect(effect, allEnergies);
          discardEnergy2.target = player.active;
          store.reduceEffect(state, discardEnergy2);
        }
      }
      return state;
    }
  };

