  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-black-and-white/mandibuzz.ts
  init_pokemon_card();
  init_card_types();
  init_pokemon_types();
  init_game();
  init_prefabs();
  var Mandibuzz = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Vullaby";
      this.cardType = [D];
      this.hp = 90;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Dark Pulse",
          cost: [D],
          damage: 20,
          damageCalculation: "x",
          text: "Does 20 damage times the number of [D] Energy attached to all of your Pok\xE9mon."
        },
        {
          name: "Punishment",
          cost: [D, D],
          damage: 40,
          damageCalculation: "+",
          text: "If the Defending Pok\xE9mon has an Ability, this attack does 30 more damage."
        }
      ];
      this.set = "BLW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "73";
      this.name = "Mandibuzz";
      this.fullName = "Mandibuzz BLW";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let darkEnergy = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          cardList.cards.forEach((card) => {
            if (card.superType === 3 /* ENERGY */) {
              darkEnergy += card.provides.filter((e) => e === 7 /* DARK */).length;
            }
          });
        });
        effect.damage = 20 * darkEnergy;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const defendingCard = opponent.active.getPokemonCard();
        if (defendingCard && defendingCard.powers && defendingCard.powers.length > 0) {
          const hasAbility = defendingCard.powers.some((p) => p.powerType === 2 /* ABILITY */);
          if (hasAbility) {
            effect.damage += 30;
          }
        }
      }
      return state;
    }
  };

