  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-black-and-white/stoutland.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_choose_cards_prompt();
  init_show_cards_prompt();
  function* useOdorSleuth(next, store, state, self, player, opponent) {
    BLOCK_IF_DECK_EMPTY(player);
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_HAND,
      player.deck,
      {},
      { min: 0, max: 2, allowCancel: false }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length > 0) {
      MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
      yield store.prompt(state, new ShowCardsPrompt(
        opponent.id,
        GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
        cards
      ), () => next());
    }
    return SHUFFLE_DECK(store, state, player);
  }
  var Stoutland = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Herdier";
      this.cardType = [C];
      this.hp = 140;
      this.weakness = [{ type: F }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Odor Sleuth",
          cost: [C],
          damage: 0,
          text: "Search your deck for up to 2 cards and put them into your hand. Show those cards to your opponent. Shuffle your deck afterward."
        },
        {
          name: "Wild Tackle",
          cost: [C, C, C, C],
          damage: 100,
          text: "This Pok\xE9mon can't attack during your next turn."
        }
      ];
      this.set = "BLW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "83";
      this.name = "Stoutland";
      this.fullName = "Stoutland BLW";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const generator = useOdorSleuth(() => generator.next(), store, state, this, player, opponent);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        player.active.cannotAttackNextTurnPending = true;
      }
      return state;
    }
  };

