  var Audino2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 80;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Busybody",
        useFromHand: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), if this Pok\xE9mon is in your hand, you may reveal it. If you do, heal 10 damage and remove a Special Condition from your Active Pok\xE9mon. Then, discard this Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Hip Bump",
          cost: [C, C],
          damage: 30,
          text: "If the Defending Pok\xE9mon tries to attack during your opponent's next turn, your opponent flips a coin. If tails, that attack does nothing."
        }
      ];
      this.set = "BCR";
      this.setNumber = "126";
      this.cardImage = "assets/cardback.png";
      this.name = "Audino";
      this.fullName = "Audino BCR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (!(effect instanceof PowerEffect) || !player.hand.cards.includes(this)) {
          return state;
        }
        const healEffect = new HealEffect(player, player.active, 10);
        store.reduceEffect(state, healEffect);
        player.active.clearAllSpecialConditions();
        MOVE_CARDS(store, state, player.hand, player.discard, { cards: [this], sourceCard: this });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return DEFENDING_POKEMON_FLIPS_COIN_TO_ATTACK(store, state, effect, this);
      }
      return state;
    }
  };

