  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-boundaries-crossed/celebi-ex.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var CelebiEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["EX" /* POKEMON_EX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 110;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -20 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Time Recall",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Each of your evolved Pok\xE9mon can use any attack from its previous Evolutions. (You still need the necessary Energy to use each attack.)"
        }
      ];
      this.attacks = [
        {
          name: "Wind Whisk",
          cost: [G, C, C],
          damage: 60,
          text: "Switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        }
      ];
      this.set = "BCR";
      this.setNumber = "9";
      this.cardImage = "assets/cardback.png";
      this.name = "Celebi-EX";
      this.fullName = "Celebi-EX BCR";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckTableStateEffect) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner !== player) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        let isCelebiInPlay = false;
        owner.forEachPokemon(2 /* BOTTOM_PLAYER */, (_cardList, card) => {
          if (card === this) {
            isCelebiInPlay = true;
          }
        });
        if (!isCelebiInPlay) {
          return state;
        }
        owner.forEachPokemon(2 /* BOTTOM_PLAYER */, (_cardList, card) => {
          if (card.stage !== 2 /* BASIC */) {
            player.showAllStageAbilities = true;
          }
        });
      }
      if (effect instanceof CheckPokemonAttacksEffect) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner !== player) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        let isCelebiInPlay = false;
        owner.forEachPokemon(2 /* BOTTOM_PLAYER */, (_cardList, card) => {
          if (card === this) {
            isCelebiInPlay = true;
          }
        });
        if (!isCelebiInPlay) {
          return state;
        }
        owner.forEachPokemon(2 /* BOTTOM_PLAYER */, (pokemonCardList, card) => {
          if (card.stage !== 2 /* BASIC */) {
            for (const evolutionCard of pokemonCardList.cards) {
              if (evolutionCard.superType === 1 /* POKEMON */ && evolutionCard !== card) {
                effect.attacks.push(...evolutionCard.attacks || []);
              }
            }
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return state;
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        SWITCH_ACTIVE_WITH_BENCHED(store, state, effect.player);
      }
      return state;
    }
  };

