  var Ditto6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 70;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [{
        name: "Transform",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "During your turn (before your attack), you may put a Basic Pok\xE9mon from your hand on top of this Pok\xE9mon. (This does not count as playing that Pok\xE9mon or evolving.) This Pok\xE9mon is now that Pok\xE9mon. (Any cards attached to this Pok\xE9mon, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pok\xE9mon.)"
      }];
      this.attacks = [];
      this.set = "BCR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "108";
      this.name = "Ditto";
      this.fullName = "Ditto BCR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const targetCardList = StateUtils.findCardList(state, this);
        if (!(targetCardList instanceof PokemonCardList)) {
          throw new GameError(GameMessage.INVALID_TARGET);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
          player.hand,
          { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
          { min: 1, max: 1, allowCancel: false }
        ), (selection) => {
          if (selection.length <= 0) {
            throw new GameError(GameMessage.INVALID_TARGET);
          }
          const pokemonCard = selection[0];
          if (!(pokemonCard instanceof PokemonCard)) {
            throw new GameError(GameMessage.INVALID_TARGET);
          }
          store.log(state, "LOG_PLAYER_TRANSFORMS_INTO_POKEMON" /* LOG_PLAYER_TRANSFORMS_INTO_POKEMON */, {
            name: player.name,
            pokemon: this.name,
            card: pokemonCard.name,
            effect: effect.power.name
          });
          MOVE_CARDS(store, state, player.hand, targetCardList, { cards: [pokemonCard], sourceCard: this });
        });
      }
      return state;
    }
  };

