  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-boundaries-crossed/landorus-ex.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_check_effects();
  init_game_message();
  init_prefabs();
  var LandorusEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["EX" /* POKEMON_EX */];
      this.cardType = [F];
      this.hp = 180;
      this.weakness = [{ type: W }];
      this.resistance = [{ type: L, value: -20 }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Hammerhead",
          cost: [F],
          damage: 30,
          text: "Does 30 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Land's Judgment",
          cost: [F, F, C],
          damage: 80,
          text: "You may discard all [F] Energy attached to this Pok\xE9mon. If you do, this attack does 70 more damage."
        }
      ];
      this.set = "BCR";
      this.setNumber = "89";
      this.cardImage = "assets/cardback.png";
      this.name = "Landorus-EX";
      this.fullName = "Landorus EX BCR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const damageEffect = new PutDamageEffect(effect, 30);
            damageEffect.target = targets[0];
            store.reduceEffect(state, damageEffect);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        return store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_DISCARD_ENERGY),
          (result) => {
            if (result) {
              const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
              store.reduceEffect(state, checkProvidedEnergy);
              const cards = [];
              checkProvidedEnergy.energyMap.forEach((em) => {
                if (em.provides.includes(6 /* FIGHTING */) || em.provides.includes(0 /* ANY */)) {
                  cards.push(em.card);
                }
              });
              effect.damage += 70;
              const discardEnergy2 = new DiscardCardsEffect(effect, cards);
              discardEnergy2.target = player.active;
              return store.reduceEffect(state, discardEnergy2);
            }
          }
        );
      }
      return state;
    }
  };

