  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-boundaries-crossed/mienshao.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Mienshao = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Mienfoo";
      this.cardType = [F];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [{
        name: "Knock Off",
        cost: [F, C],
        damage: 20,
        text: "Discard a random card from your opponent's hand."
      }, {
        name: "Double Whip",
        cost: [F, C, C],
        damage: 70,
        damageCalculation: "x",
        text: "Flip 2 coins. This attack does 70 damage times the number of heads."
      }];
      this.set = "BCR";
      this.setNumber = "88";
      this.cardImage = "assets/cardback.png";
      this.name = "Mienshao";
      this.fullName = "Mienshao BCR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.hand.cards.length === 0) {
          return state;
        }
        const randomIndex = Math.floor(Math.random() * opponent.hand.cards.length);
        const cardToDiscard = opponent.hand.cards[randomIndex];
        MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards: [cardToDiscard], sourceCard: this });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 2, (results) => {
          effect.damage = 70 * results.filter((r) => r).length;
        });
      }
      return state;
    }
  };

