  var Munna2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 60;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Long-Distance Hypnosis",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may flip a coin. If heads, your opponent's Active Pokemon is now Asleep. If tails, your Active Pokemon is now Asleep."
      }];
      this.attacks = [{
        name: "Psyshot",
        cost: [P, C],
        damage: 20,
        text: ""
      }];
      this.set = "BCR";
      this.name = "Munna";
      this.fullName = "Munna BCR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "68";
      this.LONG_DISTANCE_HYPNOSIS_MARKER = "LONG_DISTANCE_HYPNOSIS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.LONG_DISTANCE_HYPNOSIS_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.marker.hasMarker(this.LONG_DISTANCE_HYPNOSIS_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.marker.addMarker(this.LONG_DISTANCE_HYPNOSIS_MARKER, this);
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            opponent.active.addSpecialCondition(2 /* ASLEEP */);
          } else {
            player.active.addSpecialCondition(2 /* ASLEEP */);
          }
        });
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.LONG_DISTANCE_HYPNOSIS_MARKER, this)) {
        effect.player.marker.removeMarker(this.LONG_DISTANCE_HYPNOSIS_MARKER, this);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-boundaries-crossed/musharna.ts
