  var Musharna2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Munna";
      this.cardType = [P];
      this.hp = 100;
      this.weakness = [{ type: P }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Telekinesis",
          cost: [P],
          damage: 0,
          text: "This attack does 30 damage to 1 of your opponent's Pok\xE9mon. This attack's damage isn't affected by Weakness or Resistance."
        },
        {
          name: "Dream Waltz",
          cost: [P, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "This attack can be used even if this Pok\xE9mon is Asleep. If this Pok\xE9mon is Asleep, this attack does 30 more damage."
        }
      ];
      this.set = "BCR";
      this.setNumber = "69";
      this.cardImage = "assets/cardback.png";
      this.name = "Musharna";
      this.fullName = "Musharna BCR";
      this.DREAM_WALTZ_ASLEEP_MARKER = "DREAM_WALTZ_ASLEEP_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return store.prompt(state, new ChoosePokemonPrompt(
          effect.player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          const target = selected[0];
          const damageEffect = new PutDamageEffect(effect, 30);
          damageEffect.target = target;
          store.reduceEffect(state, damageEffect);
        });
      }
      if (effect instanceof UseAttackEffect && effect.attack === this.attacks[1] && effect.player.active.getPokemonCard() === this && effect.player.active.specialConditions.includes(2 /* ASLEEP */)) {
        effect.player.active.removeSpecialCondition(2 /* ASLEEP */);
        effect.player.active.marker.addMarker(this.DREAM_WALTZ_ASLEEP_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        if (effect.player.active.marker.hasMarker(this.DREAM_WALTZ_ASLEEP_MARKER, this)) {
          effect.damage += 30;
          effect.player.active.addSpecialCondition(2 /* ASLEEP */);
          effect.player.active.marker.removeMarker(this.DREAM_WALTZ_ASLEEP_MARKER, this);
        }
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.marker.hasMarker(this.DREAM_WALTZ_ASLEEP_MARKER, this)) {
            cardList.addSpecialCondition(2 /* ASLEEP */);
            cardList.marker.removeMarker(this.DREAM_WALTZ_ASLEEP_MARKER, this);
          }
        });
      }
      return state;
    }
  };

