  var Patrat3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 60;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Patrol",
          cost: [C],
          damage: 0,
          text: "Look at the top 3 cards of your deck and put them back on top of your deck in any order."
        }
      ];
      this.set = "BCR";
      this.setNumber = "118";
      this.cardImage = "assets/cardback.png";
      this.name = "Patrat";
      this.fullName = "Patrat BCR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: 3, sourceCard: this });
        return store.prompt(state, new OrderCardsPrompt(
          player.id,
          GameMessage.CHOOSE_CARDS_ORDER,
          deckTop,
          { allowCancel: false }
        ), (order) => {
          if (order === null) {
            return state;
          }
          deckTop.applyOrder(order);
          deckTop.moveToTopOfDestination(player.deck);
        });
      }
      return state;
    }
  };

