  var Psyduck22 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 70;
      this.weakness = [{ type: L }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Firefighting",
          cost: [W],
          damage: 0,
          text: "Discard a [R] Energy attached to the Defending Pok\xE9mon."
        }
      ];
      this.set = "BCR";
      this.setNumber = "33";
      this.cardImage = "assets/cardback.png";
      this.name = "Psyduck";
      this.fullName = "Psyduck BCR 33";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const fireEnergyCards = checkProvidedEnergy.energyMap.filter((em) => em.provides.includes(2 /* FIRE */) || em.provides.includes(0 /* ANY */)).map((em) => em.card);
        if (fireEnergyCards.length > 0) {
          const cardToDiscard = fireEnergyCards[0];
          if (opponent.active.cards.includes(cardToDiscard)) {
            MOVE_CARDS(store, state, opponent.active, opponent.discard, { cards: [cardToDiscard], sourceCard: this });
          }
        }
      }
      return state;
    }
  };

