  var Stoutland2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.cardType = [C];
      this.hp = 140;
      this.weakness = [{ type: F }];
      this.retreat = [C, C, C];
      this.evolvesFrom = "Herdier";
      this.powers = [{
        name: "Sentinel",
        powerType: 2 /* ABILITY */,
        text: " As long as this Pok\xE9mon is your Active Pok\xE9mon, your opponent can't play any Supporter cards from his or her hand."
      }];
      this.attacks = [{
        name: "Wild Tackle",
        cost: [C, C, C],
        damage: 90,
        text: "Flip a coin. If tails, this Pok\xE9mon does 20 damage to itself."
      }];
      this.set = "BCR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "122";
      this.name = "Stoutland";
      this.fullName = "Stoutland BCR";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlaySupporterEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.active.getPokemonCard() !== this && opponent.active.getPokemonCard() !== this) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (opponent.active.getPokemonCard() === this) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (!result) {
            const dealDamage = new DealDamageEffect(effect, 10);
            dealDamage.target = player.active;
            return store.reduceEffect(state, dealDamage);
          }
        });
      }
      return state;
    }
  };

