  var Vileplume4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Gloom";
      this.cardType = [G];
      this.hp = 140;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Allergy Panic",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Apply Weakness for each Pok\xE9mon (both yours and your opponent's) as \xD74 instead."
      }];
      this.attacks = [
        {
          name: "Pollen Spray",
          cost: [G, C, C, C],
          damage: 50,
          text: "The Defending Pok\xE9mon is now Asleep and Poisoned."
        }
      ];
      this.set = "BCR";
      this.setNumber = "3";
      this.cardImage = "assets/cardback.png";
      this.name = "Vileplume";
      this.fullName = "Vileplume BCR";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonStatsEffect) {
        if (effect.allergyPanicApplied) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        let isInPlay = false;
        owner.forEachPokemon(2 /* BOTTOM_PLAYER */, (_cardList, card) => {
          if (card === this) {
            isInPlay = true;
          }
        });
        if (!isInPlay || IS_ABILITY_BLOCKED(store, state, owner, this)) {
          return state;
        }
        effect.allergyPanicApplied = true;
        effect.weakness = effect.weakness.flatMap((w) => [w, { ...w }]);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_ASLEEP(store, state, effect);
        YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_POISIONED(store, state, effect);
      }
      return state;
    }
  };

