  var RockyHelmet = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this._trainerType = 3 /* TOOL */;
      this.set = "SVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "193";
      this.name = "Rocky Helmet";
      this.fullName = "Rocky Helmet SVI";
      this.text = "If the Pokemon this card is attached to is your Active Pokemon and is damaged by an opponent's attack (even if that Pokemon is Knocked Out), put 2 damage counters on the Attacking Pokemon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (effect.damage <= 0 || player === targetPlayer || targetPlayer.active !== effect.target) {
          return state;
        }
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        if (state.phase === 3 /* ATTACK */) {
          effect.source.damage += 20;
        }
      }
      return state;
    }
  };

