  var Accelgor = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Shelmet";
      this.cardType = [G];
      this.hp = 90;
      this.weakness = [{ type: R }];
      this.retreat = [];
      this.attacks = [{
        name: "Hammer In",
        cost: [G],
        damage: 20,
        text: ""
      }, {
        name: "Deck and Cover",
        cost: [C, C],
        damage: 50,
        text: "The Defending Pok\xE9mon is now Paralyzed and Poisoned. Shuffle this Pok\xE9mon and all cards attached to it into your deck."
      }];
      this.set = "DEX";
      this.name = "Accelgor";
      this.fullName = "Accelgor DEX";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "11";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const addSpecialCondition = new AddSpecialConditionsEffect(effect, [
          0 /* PARALYZED */,
          3 /* POISONED */
        ]);
        store.reduceEffect(state, addSpecialCondition);
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        return SHUFFLE_THIS_POKEMON_AND_ALL_ATTACHED_CARDS_INTO_YOUR_DECK(store, state, effect);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-dark-explorers/aerodactyl.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_game_effects();
  var Aerodactyl3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 1 /* RESTORED */;
      this.evolvesFrom = "Old Amber Aerodactyl";
      this.cardType = [F];
      this.hp = 90;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.powers = [{
        name: "Ancient Scream",
        powerType: 2 /* ABILITY */,
        text: "Your Pok\xE9mon's attacks do 10 more damage to the Active Pok\xE9mon (before applying Weakness and Resistance)."
      }];
      this.attacks = [{
        name: "Wing Attack",
        cost: [C, C, C],
        damage: 40,
        text: ""
      }];
      this.set = "DEX";
      this.setNumber = "53";
      this.cardImage = "assets/cardback.png";
      this.name = "Aerodactyl";
      this.fullName = "Aerodactyl DEX";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        let isThisInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            isThisInPlay = true;
          }
        });
        if (!isThisInPlay) {
          return state;
        }
        try {
          const powerEffect = new PowerEffect(player, this.powers[0], this);
          store.reduceEffect(state, powerEffect);
        } catch {
          return state;
        }
        if (effect.target !== opponent.active) {
          return state;
        }
        if (effect.damage > 0) {
          effect.damage += 10;
        }
      }
      return state;
    }
  };

