  var Bisharp = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Pawniard";
      this.cardType = [D];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.attacks = [{
        name: "Slash",
        cost: [D, C],
        damage: 30,
        text: ""
      }, {
        name: "Fury Cutter",
        cost: [D, C, C],
        damage: 30,
        damageCalculation: "+",
        text: "Flip 3 coins. If 1 of them is heads, this attack does 10 more damage. If 2 of them are heads, this attack does 30 more damage. If all of them are heads, this attack does 60 more damage."
      }];
      this.set = "DEX";
      this.setNumber = "72";
      this.cardImage = "assets/cardback.png";
      this.name = "Bisharp";
      this.fullName = "Bisharp DEX";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 3, (results) => {
          const heads = results.filter((r) => r).length;
          switch (heads) {
            case 1:
              effect.damage += 10;
              break;
            case 2:
              effect.damage += 30;
              break;
            case 3:
              effect.damage += 60;
              break;
            default:
              effect.damage += 0;
              break;
          }
        });
      }
      return state;
    }
  };

