  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-dark-explorers/blissey.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_effects();
  init_play_card_effects();
  init_game_phase_effects();
  init_prefabs();
  var Blissey3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Chansey";
      this.cardType = [C];
      this.hp = 130;
      this.weakness = [{ type: F }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Softboiled",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may flip a coin. If heads, heal 30 damage from your Active Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Double-Edge",
        cost: [C, C, C],
        damage: 90,
        text: "This Pok\xE9mon does 60 damage to itself."
      }];
      this.set = "DEX";
      this.setNumber = "82";
      this.cardImage = "assets/cardback.png";
      this.name = "Blissey";
      this.fullName = "Blissey DEX";
      this.SOFTBOILED_MARKER = "SOFTBOILED_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.SOFTBOILED_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.SOFTBOILED_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.marker.addMarker(this.SOFTBOILED_MARKER, this);
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            const healEffect = new HealEffect(player, player.active, 30);
            store.reduceEffect(state, healEffect);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_POKEMON_DOES_DAMAGE_TO_ITSELF(store, state, effect, 60);
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.SOFTBOILED_MARKER, this);
      }
      return state;
    }
  };

