  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-dark-explorers/carnivine.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_game_phase_effects();
  var Carnivine = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 90;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Lure Poison",
          cost: [G],
          damage: 0,
          text: "Switch the Defending Pok\xE9mon with 1 of your opponent's Benched Pok\xE9mon. The new Defending Pok\xE9mon is now Poisoned."
        },
        {
          name: "Spit Squall",
          cost: [G, G, C],
          damage: 0,
          text: "Your opponent puts the Defending Pok\xE9mon and all cards attached to it into his or her hand."
        }
      ];
      this.set = "DEX";
      this.setNumber = "5";
      this.cardImage = "assets/cardback.png";
      this.name = "Carnivine";
      this.fullName = "Carnivine DEX";
      this.usedLurePoison = false;
      this.usedSpitSquall = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedLurePoison = true;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedSpitSquall = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedLurePoison) {
        this.usedLurePoison = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          ADD_POISON_TO_PLAYER_ACTIVE(store, state, opponent, this);
          return state;
        }
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            return state;
          }
          const target = selected[0];
          opponent.switchPokemon(target);
          ADD_POISON_TO_PLAYER_ACTIVE(store, state, opponent, this);
        });
      }
      if (effect instanceof AfterAttackEffect && this.usedSpitSquall) {
        this.usedSpitSquall = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const defendingPokemon = opponent.active;
        MOVE_CARDS(store, state, defendingPokemon, opponent.hand, { sourceCard: this });
        defendingPokemon.clearEffects();
      }
      if (effect instanceof EndTurnEffect) {
        this.usedLurePoison = false;
        this.usedSpitSquall = false;
      }
      return state;
    }
  };

