  init_choose_cards_prompt();
  var Cofagrigus = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Yamask";
      this.cardType = [P];
      this.hp = 100;
      this.weakness = [{ type: D }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Chuck",
          cost: [C, C],
          damage: 40,
          damageCalculation: "x",
          text: "Discard as many Pok\xE9mon Tool cards as you like from your hand. This attack does 40 damage times the number of cards you discarded."
        },
        {
          name: "Lock Up",
          cost: [P, P],
          damage: 40,
          text: "The Defending Pok\xE9mon can't retreat during your opponent's next turn."
        }
      ];
      this.set = "DEX";
      this.setNumber = "52";
      this.cardImage = "assets/cardback.png";
      this.name = "Cofagrigus";
      this.fullName = "Cofagrigus DEX";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const toolCards = player.hand.cards.filter(
          (card) => card instanceof TrainerCard && card.trainerType === 3 /* TOOL */
        );
        if (toolCards.length === 0) {
          effect.damage = 0;
          return state;
        }
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 2 /* TRAINER */, trainerType: 3 /* TOOL */ },
          { min: 0, max: toolCards.length, allowCancel: false }
        ), (selected) => {
          const cards = selected || [];
          cards.forEach((card) => {
            MOVE_CARDS(store, state, player.hand, player.discard, { cards: [card], sourceCard: this });
          });
          effect.damage = 40 * cards.length;
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        BLOCK_RETREAT(store, state, effect, this);
      }
      return state;
    }
  };

