  var Empoleon2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Prinplup";
      this.cardType = [W];
      this.hp = 140;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Diving Draw",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may discard a card from your hand. If you do, draw 2 cards."
      }];
      this.attacks = [
        {
          name: "Attack Command",
          cost: [W],
          damage: 10,
          text: "Does 10 damage times the number of Pok\xE9mon in play (both yours and your opponent's)."
        }
      ];
      this.set = "DEX";
      this.name = "Empoleon";
      this.fullName = "Empoleon DEX";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "29";
      this.DIVING_DRAW_MAREKER = "DIVING_DRAW_MAREKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.DIVING_DRAW_MAREKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.hand.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.DIVING_DRAW_MAREKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          {},
          { allowCancel: true, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          player.marker.addMarker(this.DIVING_DRAW_MAREKER, this);
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this, sourceEffect: this.powers[0] });
          DRAW_CARDS(store, state, player, 2);
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let pokemonInPlay = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, () => {
          pokemonInPlay += 1;
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, () => {
          pokemonInPlay += 1;
        });
        effect.damage = 10 * pokemonInPlay;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.DIVING_DRAW_MAREKER, this)) {
        effect.player.marker.removeMarker(this.DIVING_DRAW_MAREKER, this);
      }
      return state;
    }
  };

