  var EnteiEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["EX" /* POKEMON_EX */];
      this.cardType = [R];
      this.hp = 180;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Fire Fang",
          cost: [R, C],
          damage: 30,
          text: "The Defending Pok\xE9mon is now Burned."
        },
        {
          name: "Grand Flame",
          cost: [R, R, C],
          damage: 90,
          text: "Attach a [R] Energy card from your discard pile to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.set = "DEX";
      this.setNumber = "13";
      this.cardImage = "assets/cardback.png";
      this.name = "Entei-EX";
      this.fullName = "Entei EX DEX";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_BURN_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasFireEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.name === "Fire Energy";
        });
        const hasBenchedPokemon = player.bench.some((b) => b.cards.length > 0);
        if (!hasFireEnergyInDiscard || !hasBenchedPokemon) {
          return state;
        }
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
            { allowCancel: false, min: 1, max: 1 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card] });
            }
          }
        );
      }
      return state;
    }
  };

