  var Espeon4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Eevee";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Solar Revelation",
        powerType: 2 /* ABILITY */,
        text: "Prevent all effects of your opponent's attacks, except damage, done to each of your Pok\xE9mon that has any Energy attached to it."
      }];
      this.attacks = [{
        name: "Psy Report",
        cost: [P, C, C],
        damage: 60,
        text: "Your opponent reveals his or her hand."
      }];
      this.set = "DEX";
      this.setNumber = "48";
      this.cardImage = "assets/cardback.png";
      this.name = "Espeon";
      this.fullName = "Espeon DEX";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AbstractAttackEffect) {
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        const sourcePlayer = effect.player;
        if (targetPlayer === sourcePlayer) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetPlayer, this)) {
          return state;
        }
        let hasEspeonInPlay = false;
        targetPlayer.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            hasEspeonInPlay = true;
          }
        });
        if (!hasEspeonInPlay) {
          return state;
        }
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(targetPlayer, effect.target);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        const hasEnergy = checkProvidedEnergyEffect.energyMap.length > 0;
        if (hasEnergy) {
          if (effect instanceof ApplyWeaknessEffect) {
            return state;
          }
          if (effect instanceof PutDamageEffect) {
            return state;
          }
          if (effect instanceof DealDamageEffect) {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        return store.prompt(state, new ShowCardsPrompt(
          player.id,
          GameMessage.CARDS_SHOWED_BY_EFFECT,
          opponent.hand.cards
        ), () => {
        });
      }
      return state;
    }
  };

