        {
          name: "Tromp",
          cost: [F, C],
          damage: 20,
          text: "Does 10 damage to each of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Giant Claw",
          cost: [F, F, C],
          damage: 80,
          damageCalculation: "+",
          text: "If the Defending Pok\xE9mon already has 2 or more damage counters on it, this attack does 40 more damage."
        }
