  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-dark-explorers/hooligans-jim-and-cas.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_prefabs();
  init_show_cards_prompt();
  var HooligansJimAndCas = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "DEX";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "95";
      this.name = "Hooligans Jim & Cas";
      this.fullName = "Hooligans Jim & Cas DEX";
      this.text = "Flip a coin. If heads, choose 3 random cards from your opponent's hand. Your opponent reveals those cards and shuffles them into his or her deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result && opponent.hand.cards.length > 0) {
            const cardsToShuffle = Math.min(3, opponent.hand.cards.length);
            const selectedCards = [];
            const handCopy = [...opponent.hand.cards];
            for (let i = 0; i < cardsToShuffle; i++) {
              const randomIndex = Math.floor(Math.random() * handCopy.length);
              selectedCards.push(handCopy[randomIndex]);
              handCopy.splice(randomIndex, 1);
            }
            return store.prompt(
              state,
              [
                new ShowCardsPrompt(player.id, GameMessage.CARDS_SHOWED_BY_EFFECT, selectedCards),
                new ShowCardsPrompt(
                  opponent.id,
                  GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                  selectedCards
                )
              ],
              () => {
                SHUFFLE_CARDS_INTO_DECK(store, state, opponent, selectedCards);
              }
            );
          }
        });
      }
      return state;
    }
  };

