  var Jolteon2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Eevee";
      this.cardType = [L];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.retreat = [];
      this.attacks = [{
        name: "Electrigun",
        cost: [C],
        damage: 20,
        damageCalculation: "+",
        text: "You may discard a [L] Energy attached to this Pok\xE9mon. If you do, this attack does 40 more damage."
      }, {
        name: "Pin Missile",
        cost: [L, C, C],
        damage: 40,
        damageCalculation: "x",
        text: "Flip 4 coins. This attack does 40 damage times the number of heads."
      }];
      this.set = "DEX";
      this.setNumber = "37";
      this.cardImage = "assets/cardback.png";
      this.name = "Jolteon";
      this.fullName = "Jolteon DEX";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasLightningEnergy = player.active.cards.some(
          (c) => c.superType === 3 /* ENERGY */ && c.provides?.includes(4 /* LIGHTNING */)
        );
        if (hasLightningEnergy) {
          return store.prompt(state, new ConfirmPrompt(
            player.id,
            GameMessage.WANT_TO_DEAL_MORE_DAMAGE
          ), (result) => {
            if (result) {
              const lightningEnergy = player.active.cards.find(
                (c) => c.superType === 3 /* ENERGY */ && c.provides?.includes(4 /* LIGHTNING */)
              );
              if (lightningEnergy) {
                MOVE_CARDS(store, state, player.active, player.discard, { cards: [lightningEnergy], sourceCard: this });
                effect.damage += 40;
              }
            }
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 4, (results) => {
          let heads = 0;
          results.forEach((r) => {
            if (r) heads++;
          });
          effect.damage = 40 * heads;
        });
      }
      return state;
    }
  };

