  var KyogreEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["EX" /* POKEMON_EX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 170;
      this.weakness = [{ type: L }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Smash Turn",
          cost: [W, C],
          damage: 30,
          text: "You may switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Dual Splash",
          cost: [W, W, C],
          damage: 0,
          text: "This attack does 50 damage to 2 of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "DEX";
      this.setNumber = "26";
      this.cardImage = "assets/cardback.png";
      this.name = "Kyogre-EX";
      this.fullName = "Kyogre EX DEX";
      this.usedSmashTurn = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedSmashTurn = true;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 2, max: 2, allowCancel: false }
          ),
          (selected) => {
            const targets = selected || [];
            DAMAGE_OPPONENT_POKEMON(store, state, effect, 50, targets);
          }
        );
      }
      if (effect instanceof AfterAttackEffect && this.usedSmashTurn) {
        this.usedSmashTurn = false;
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (hasBenched) {
          return store.prompt(
            state,
            new ConfirmPrompt(player.id, GameMessage.WANT_TO_SWITCH_POKEMON),
            (wantToSwitch) => {
              if (wantToSwitch) {
                SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
              }
            }
          );
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedSmashTurn = false;
      }
      return state;
    }
  };

