  var Leafeon2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Eevee";
      this.cardType = [G];
      this.hp = 90;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Quick Attack",
          cost: [C],
          damage: 10,
          damageCalculation: "+",
          text: "Flip a coin. If heads, this attack does 30 more damage."
        },
        {
          name: "Energy Assist",
          cost: [G, C],
          damage: 40,
          text: "Attach a basic Energy card from your discard pile to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.set = "DEX";
      this.setNumber = "6";
      this.cardImage = "assets/cardback.png";
      this.name = "Leafeon";
      this.fullName = "Leafeon DEX";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        FLIP_A_COIN_IF_HEADS_DEAL_MORE_DAMAGE(store, state, effect, 30);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
        });
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasEnergyInDiscard || !hasBenched) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { allowCancel: false, min: 0, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length > 0) {
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        });
      }
      return state;
    }
  };

