  function* playCard68(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const cards = [];
    let supporter;
    for (let i = 0; i < player.deck.cards.length; i++) {
      const card = player.deck.cards[i];
      cards.push(card);
      if (card instanceof TrainerCard && card.trainerType === 1 /* SUPPORTER */) {
        supporter = card;
        break;
      }
    }
    yield store.prompt(
      state,
      [
        new ShowCardsPrompt(player.id, GameMessage.CARDS_SHOWED_BY_EFFECT, cards),
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards)
      ],
      () => next()
    );
    if (supporter !== void 0) {
      MOVE_CARDS(store, state, player.deck, player.hand, {
        cards: [supporter],
        sourceCard: effect.trainerCard,
        sourceEffect: effect.trainerCard
      });
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
