  function* useStadium(next, store, state, effect) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const hasRestored = player.hand.cards.some((c) => {
      return c instanceof PokemonCard && c.stage === 1 /* RESTORED */;
    });
    if (slots2.length === 0 || !hasRestored) {
      throw new GameError(GameMessage.CANNOT_USE_STADIUM);
    }
    let flipResult = false;
    yield COIN_FLIP_PROMPT(store, state, player, (result) => {
      flipResult = result;
      next();
    });
    if (!flipResult) {
      return state;
    }
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
        player.hand,
        { superType: 1 /* POKEMON */, stage: 1 /* RESTORED */ },
        { min: 1, max: 1, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      MOVE_CARDS(store, state, player.hand, slots2[index], { cards: [card], sourceCard: effect.stadium });
      slots2[index].pokemonPlayedTurn = state.turn;
    });
    return state;
  }
  var TwistMountain = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "DEX";
      this.name = "Twist Mountain";
      this.fullName = "Twist Mountain DEX";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "101";
      this.text = "Once during each player's turn, that player may flip a coin. If heads, the player puts a Restored Pok\xE9mon from his or her hand onto his or her Bench.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const generator = useStadium(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

