  var Dragonair23 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Dratini";
      this.cardType = [N];
      this.hp = 70;
      this.weakness = [{ type: N }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Healing Melody",
        cost: [G],
        damage: 0,
        text: "Heal 10 damage from each of your Pok\xE9mon."
      }, {
        name: "Slam",
        cost: [L, C],
        damage: 30,
        damageCalculation: "x",
        text: "Flip 2 coins. This attack does 30 damage times the number of heads."
      }];
      this.set = "DRV";
      this.setNumber = "4";
      this.cardImage = "assets/cardback.png";
      this.name = "Dragonair";
      this.fullName = "Dragonair DRV 4";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.damage > 0) {
            const healEffect = new HealEffect(player, cardList, 10);
            store.reduceEffect(state, healEffect);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 2, (results) => {
          const heads = results.filter((r) => r).length;
          effect.damage = 30 * heads;
        });
      }
      return state;
    }
  };

