  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-dragon-vault/latias.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects2();
  var Latias2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [N];
      this.hp = 100;
      this.weakness = [{ type: N }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Energy Assist",
          cost: [C],
          damage: 0,
          text: "Attach a basic Energy card from your discard pile to 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Sky Heal",
          cost: [R, P],
          damage: 40,
          text: "If Latios is on your Bench, heal 20 damage from this Pok\xE9mon."
        }
      ];
      this.set = "DRV";
      this.setNumber = "9";
      this.cardImage = "assets/cardback.png";
      this.name = "Latias";
      this.fullName = "Latias DRV";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInDiscard = player.discard.cards.some(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
        );
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasEnergyInDiscard || !hasBenched) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { allowCancel: false, min: 0, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        let hasLatios = false;
        player.bench.forEach((benchSlot) => {
          if (benchSlot.cards.length > 0) {
            const pokemon = benchSlot.getPokemonCard();
            if (pokemon && pokemon.name === "Latios") {
              hasLatios = true;
            }
          }
        });
        if (hasLatios) {
          HEAL_X_DAMAGE_FROM_THIS_POKEMON2(20, effect, store, state);
        }
      }
      return state;
    }
  };

