  var Rayquaza2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [11 /* DRAGON */];
      this.hp = 120;
      this.weakness = [{ type: 11 /* DRAGON */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Dragon Pulse",
          cost: [4 /* LIGHTNING */],
          damage: 40,
          text: "Discard the top 2 cards of your deck."
        },
        {
          name: "Shred",
          cost: [2 /* FIRE */, 4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 90,
          text: "This attack's damage isn't affected by any effects on the Defending Pokemon."
        }
      ];
      this.set = "DRV";
      this.name = "Rayquaza";
      this.fullName = "Rayquaza DRV";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "11";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        MOVE_CARDS(store, state, player.deck, player.discard, { count: 2, sourceCard: this });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const applyWeakness = new ApplyWeaknessEffect(effect, 90);
        store.reduceEffect(state, applyWeakness);
        const damage = applyWeakness.damage;
        effect.damage = 0;
        if (damage > 0) {
          opponent.active.damage += damage;
          const afterDamage = new AfterDamageEffect(effect, damage);
          state = store.reduceEffect(state, afterDamage);
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-dragon-vault/salamence.ts
