  init_attach_energy_prompt();
  init_play_card_action();
  init_state_utils();
  init_pokemon_card_list();
  init_prefabs();
  var ExpShare = class _ExpShare extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this._trainerType = 3 /* TOOL */;
      this.set = "SVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "174";
      this.name = "Exp. Share";
      this.fullName = "Exp. Share SVI";
      this.text = "When your Active Pokemon is Knocked Out by damage from an opponent's attack, you may move 1 basic Energy card that was attached to that Pokemon to the Pokemon this card is attached to.";
      this.EXP_SHARE_MARKER = "EXP_SHARE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target === effect.player.active) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const active = effect.target;
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */ || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        if (active.marker.hasMarker(this.EXP_SHARE_MARKER)) {
          return state;
        }
        let expShareCount = 0;
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList === effect.target) {
            return;
          }
          if (cardList.tools.length > 0 && cardList.tools[0] instanceof _ExpShare) {
            expShareCount++;
          } else {
            blockedTo.push(target);
          }
        });
        if (expShareCount === 0) {
          return state;
        }
        active.marker.addMarker(this.EXP_SHARE_MARKER, this);
        const activeCopy = new PokemonCardList();
        activeCopy.cards = player.active.cards.slice();
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            activeCopy,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: true, min: 1, max: expShareCount, differentTargets: true, blockedTo }
          ),
          (transfers) => {
            transfers = transfers || [];
            active.marker.removeMarker(this.EXP_SHARE_MARKER);
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, {
                cards: [transfer.card],
                sourceCard: this
              });
            }
          }
        );
      }
      return state;
    }
  };

