  var Aggron = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Lairon";
      this.cardType = [M];
      this.hp = 140;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C, C];
      this.powers = [{
        name: "Toppling Wind",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon, you may discard the top 3 cards of your opponent's deck."
      }];
      this.attacks = [{
        name: "Giga Horn",
        cost: [M, M, C],
        damage: 90,
        text: "Flip 2 coins. If both of them are tails, this attack does nothing."
      }];
      this.set = "DRX";
      this.setNumber = "80";
      this.cardImage = "assets/cardback.png";
      this.name = "Aggron";
      this.fullName = "Aggron DRX";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EvolveEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.deck.cards.length === 0) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        return store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            MOVE_CARDS(store, state, opponent.deck, opponent.discard, { count: 3, sourceCard: this });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 2, (results) => {
          if (results.every((r) => !r)) {
            effect.damage = 0;
          }
        });
      }
      return state;
    }
  };

