  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_phase_effects();
  init_prefabs();
  function* useRebirth(next, store, state, self, effect) {
    const player = effect.player;
    if (player.discard.cards.includes(self) === false) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    if (slots2.length === 0) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    if (player.marker.hasMarker(self.REBIRTH_MAREKER, self)) {
      throw new GameError(GameMessage.POWER_ALREADY_USED);
    }
    player.marker.addMarker(self.REBIRTH_MAREKER, self);
    let flipResult = false;
    yield COIN_FLIP_PROMPT(store, state, player, (result) => {
      flipResult = result;
      next();
    });
    if (flipResult === false) {
      return state;
    }
    MOVE_CARDS(store, state, player.discard, slots2[0], { cards: [self], sourceCard: self });
    let basicEnergies = 0;
    const typeMap = {};
    player.discard.cards.forEach((c) => {
      if (c instanceof EnergyCard && c.energyType === 0 /* BASIC */) {
        const cardType = c.provides[0];
        if (typeMap[cardType] === void 0) {
          basicEnergies += 1;
          typeMap[cardType] = true;
        }
      }
    });
    if (basicEnergies === 0) {
      return state;
    }
    const count = Math.min(3, basicEnergies);
    return store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_ATTACH,
        player.discard,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { min: count, max: count, allowCancel: false, differentTypes: true }
      ),
      (selected) => {
        const cards = selected || [];
        MOVE_CARDS(store, state, player.discard, slots2[0], { cards, sourceCard: self });
      }
    );
  }
  var HoOhEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["EX" /* POKEMON_EX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [R];
      this.hp = 160;
      this.weakness = [{ type: W }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Rebirth",
          useFromDiscard: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn (before your attack), if this Pokemon is in your discard pile, you may flip a coin. If heads, put this Pokemon onto your Bench and attach 3 different types of basic Energy cards from your discard pile to this Pokemon."
        }
      ];
      this.attacks = [
        {
          name: "Rainbow Burn",
          cost: [C, C, C],
          damage: 20,
          text: "Does 20 more damage for each different type of basic Energy attached to this Pokemon."
        }
      ];
      this.set = "DRX";
      this.name = "Ho-Oh-EX";
      this.fullName = "Ho-Oh EX DRX";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "22";
      this.REBIRTH_MAREKER = "REBIRTH_MAREKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let basicEnergies = 0;
        const typeMap = {};
        player.active.cards.forEach((c) => {
          if (c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */) {
            const cardType = c.provides[0];
            if (typeMap[cardType] === void 0) {
              basicEnergies += 1;
              typeMap[cardType] = true;
            }
          }
        });
        effect.damage += basicEnergies * 20;
        return state;
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const generator = useRebirth(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.REBIRTH_MAREKER, this)) {
        effect.player.marker.removeMarker(this.REBIRTH_MAREKER, this);
      }
      return state;
    }
  };

