  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-dragons-exalted/hydreigon.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_message();
  init_check_effects();
  init_attack_effects();
  init_prefabs();
  function* useDarkTrance(next, store, state, effect) {
    const player = effect.player;
    const blockedMap = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
      store.reduceEffect(state, checkProvidedEnergy);
      const blockedCards = [];
      checkProvidedEnergy.energyMap.forEach((em) => {
        if (!em.provides.includes(7 /* DARK */) && !em.provides.includes(0 /* ANY */)) {
          blockedCards.push(em.card);
        }
      });
      const blocked = [];
      blockedCards.forEach((bc) => {
        const index = cardList.cards.indexOf(bc);
        if (index !== -1 && !blocked.includes(index)) {
          blocked.push(index);
        }
      });
      if (blocked.length !== 0) {
        blockedMap.push({ source: target, blocked });
      }
    });
    return store.prompt(state, new MoveEnergyPrompt(
      effect.player.id,
      GameMessage.MOVE_ENERGY_CARDS,
      2 /* BOTTOM_PLAYER */,
      [1 /* ACTIVE */, 2 /* BENCH */],
      { superType: 3 /* ENERGY */ },
      { allowCancel: true, blockedMap }
    ), (transfers) => {
      if (transfers === null) {
        return;
      }
      for (const transfer of transfers) {
        const source = StateUtils.getTarget(state, player, transfer.from);
        const target = StateUtils.getTarget(state, player, transfer.to);
        MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: effect.card });
      }
    });
  }
  var Hydreigon = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Zweilous";
      this.cardType = [11 /* DRAGON */];
      this.hp = 150;
      this.weakness = [{ type: 11 /* DRAGON */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Dark Trance",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "As often as you like during your turn (before your attack), you may move a [D] Energy attached to 1 of your Pokemon to another of your Pokemon."
      }];
      this.attacks = [{
        name: "Dragonblast",
        cost: [5 /* PSYCHIC */, 7 /* DARK */, 7 /* DARK */, 9 /* COLORLESS */],
        damage: 140,
        text: "Discard 2 [D] Energy attached to this Pokemon."
      }];
      this.set = "DRX";
      this.name = "Hydreigon";
      this.fullName = "Hydreigon DRX";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "97";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const generator = useDarkTrance(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [7 /* DARK */, 7 /* DARK */],
          { allowCancel: false }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = player.active;
          return store.reduceEffect(state, discardEnergy2);
        });
      }
      return state;
    }
  };

