  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-dragons-exalted/ninjask.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_game_effects();
  init_game_phase_effects();
  init_prefabs();
  var Ninjask = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Nincada";
      this.cardType = [G];
      this.hp = 60;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [{
        name: "Cast-off Shell",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "When you play this Pokemon from your hand to evolve 1 of your Pokemon, you may search your deck for Shedinja and put it onto your Bench. Shuffle your deck afterward."
      }];
      this.attacks = [
        {
          name: "Night Slash",
          cost: [G, C],
          damage: 60,
          text: "You may switch this Pokemon with 1 of your Benched Pokemon."
        }
      ];
      this.set = "DRX";
      this.setNumber = "11";
      this.cardImage = "assets/cardback.png";
      this.name = "Ninjask";
      this.fullName = "Ninjask DRX";
      this.usedNightSlash = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EvolveEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const slots2 = GET_PLAYER_BENCH_SLOTS(player);
        if (slots2.length === 0) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        return store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            const blocked = [];
            player.deck.cards.forEach((card, index) => {
              if (!(card instanceof PokemonCard) || card.name !== "Shedinja") {
                blocked.push(index);
              }
            });
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
              player.deck,
              { superType: 1 /* POKEMON */ },
              { min: 0, max: 1, allowCancel: false, blocked }
            ), (selected) => {
              const cards = selected || [];
              if (cards.length > 0) {
                const benchSlots = GET_PLAYER_BENCH_SLOTS(player);
                if (benchSlots.length > 0) {
                  store.reduceEffect(state, new PlayPokemonFromDeckEffect(player, cards[0], benchSlots[0]));
                }
              }
              SHUFFLE_DECK(store, state, player);
            });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedNightSlash = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedNightSlash) {
        this.usedNightSlash = false;
        const player = effect.player;
        if (player.bench.some((b) => b.cards.length > 0)) {
          return store.prompt(state, new ConfirmPrompt(
            player.id,
            GameMessage.WANT_TO_SWITCH_POKEMON
          ), (wantToSwitch) => {
            if (wantToSwitch) {
              SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
            }
          });
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedNightSlash = false;
      }
      return state;
    }
  };

