  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_move_energy_prompt();
  var Probopass = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Nosepass";
      this.cardType = [M];
      this.hp = 110;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Magnetic Lines",
          cost: [C, C],
          damage: 30,
          text: "You may move an Energy attached to the Defending Pok\xE9mon to 1 of your opponent's Benched Pok\xE9mon."
        },
        {
          name: "Heavy Nose",
          cost: [M, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "If the Defending Pok\xE9mon already has any damage counters on it, this attack does 30 more damage."
        }
      ];
      this.set = "DRX";
      this.setNumber = "82";
      this.cardImage = "assets/cardback.png";
      this.name = "Probopass";
      this.fullName = "Probopass DRX";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentActive = opponent.active;
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        const hasEnergy = opponentActive.cards.some((c) => c.superType === 3 /* ENERGY */);
        if (!hasBench || !hasEnergy) {
          return state;
        }
        const blockedTo = [];
        const blockedFrom = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList === opponentActive) {
            blockedTo.push(target);
            return;
          }
          blockedFrom.push(target);
        });
        return store.prompt(state, new MoveEnergyPrompt(
          player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { min: 0, max: 1, allowCancel: true, blockedFrom, blockedTo }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const source = StateUtils.getTarget(state, opponent, transfer.from);
            const target = StateUtils.getTarget(state, opponent, transfer.to);
            MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.active.damage > 0) {
          effect.damage += 30;
        }
      }
      return state;
    }
  };

