  var Roserade2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Roselia";
      this.cardType = [G];
      this.hp = 90;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Le Parfum",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pokemon from your hand to evolve 1 of your Pokemon, you may search your deck for any card and put it into your hand. Shuffle your deck afterward."
      }];
      this.attacks = [{
        name: "Squeeze",
        cost: [G, C],
        damage: 30,
        text: "Flip a coin. If heads, this attack does 20 more damage and the Defending Pokemon is now Paralyzed."
      }];
      this.set = "DRX";
      this.name = "Roserade";
      this.fullName = "Roserade DRX";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "15";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                store.log(state, "LOG_PLAYER_USES_ABILITY" /* LOG_PLAYER_USES_ABILITY */, { name: player.name, ability: "Le Parfum" });
              }
            });
            ABILITY_USED(player, this);
            SEARCH_DECK_FOR_CARDS_TO_HAND(store, state, player, this, {}, { min: 1, max: 1, allowCancel: false }, this.powers[0]);
            SHUFFLE_DECK(store, state, player);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === true) {
            const addSpecialCondition = new AddSpecialConditionsEffect(effect, [0 /* PARALYZED */]);
            effect.damage += 20;
            store.reduceEffect(state, addSpecialCondition);
          }
        });
      }
      return state;
    }
  };

