  var Rufflet = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 50;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Chirp",
          cost: [C],
          damage: 0,
          text: "Search your deck for 2 Pok\xE9mon with Fighting Resistance, reveal them, and put them into your hand. Shuffle your deck afterward."
        },
        {
          name: "Sharp Beak",
          cost: [C, C],
          damage: 10,
          damageCalculation: "+",
          text: "Flip a coin. If heads, this attack does 20 more damage."
        }
      ];
      this.set = "DRX";
      this.setNumber = "111";
      this.cardImage = "assets/cardback.png";
      this.name = "Rufflet";
      this.fullName = "Rufflet DRX";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || !card.resistance || !card.resistance.some((res) => res.type === 6 /* FIGHTING */)) {
            blocked.push(index);
          }
        });
        const validCount = player.deck.cards.length - blocked.length;
        if (validCount === 0) {
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        }
        const maxToTake = Math.min(2, validCount);
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.deck,
          {},
          { min: 0, max: maxToTake, allowCancel: false, blocked }
        ), (selected) => {
          const selectedCards = selected || [];
          MOVE_CARDS(store, state, player.deck, player.hand, { cards: selectedCards, sourceCard: this });
          if (selectedCards.length > 0) {
            const opponent = StateUtils.getOpponent(state, player);
            store.prompt(state, new ShowCardsPrompt(
              opponent.id,
              GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
              selectedCards
            ), () => state);
          }
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        FLIP_A_COIN_IF_HEADS_DEAL_MORE_DAMAGE(store, state, effect, 20);
      }
      return state;
    }
  };

