  init_game_message();
  init_game_phase_effects();
  init_check_effects();
  init_prefabs();
  var Serperior4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Servine";
      this.cardType = [G];
      this.hp = 130;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Royal Heal",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "At any times between turns, heal 10 damage from each of your Pokemon."
      }];
      this.attacks = [
        {
          name: "Leaf Tornado",
          cost: [G, C],
          damage: 60,
          text: "Move as many [G] Energy attached to your Pokemon to your other Pokemon in any way you like."
        }
      ];
      this.set = "DRX";
      this.setNumber = "125";
      this.cardImage = "assets/cardback.png";
      this.name = "Serperior";
      this.fullName = "Serperior DRX";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof BetweenTurnsEffect) {
        const player = effect.player;
        let hasSerperior = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            if (!IS_ABILITY_BLOCKED(store, state, player, this)) {
              hasSerperior = true;
            }
          }
        });
        if (hasSerperior) {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.damage > 0) {
              cardList.damage = Math.max(0, cardList.damage - 10);
            }
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          const blocked = [];
          cardList.cards.forEach((c, index) => {
            if (c.superType === 3 /* ENERGY */) {
              const energyMap = checkProvidedEnergy.energyMap.find((em) => em.card === c);
              if (!energyMap || !energyMap.provides.includes(1 /* GRASS */) && !energyMap.provides.includes(0 /* ANY */)) {
                blocked.push(index);
              }
            }
          });
          if (blocked.length > 0) {
            blockedMap.push({ source: target, blocked });
          }
        });
        let hasGrassEnergy = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          checkProvidedEnergy.energyMap.forEach((em) => {
            if (em.provides.includes(1 /* GRASS */) || em.provides.includes(0 /* ANY */)) {
              hasGrassEnergy = true;
            }
          });
        });
        if (!hasGrassEnergy) {
          return state;
        }
        return store.prompt(state, new MoveEnergyPrompt(
          player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: true, blockedMap }
        ), (transfers) => {
          if (transfers === null) {
            return;
          }
          for (const transfer of transfers) {
            const source = StateUtils.getTarget(state, player, transfer.from);
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

