  var Sigilyph = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 90;
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [
        {
          name: "Safeguard",
          powerType: 2 /* ABILITY */,
          text: "Prevent all effects of attacks, including damage, done to this Pokemon by Pokemon-EX."
        }
      ];
      this.attacks = [
        {
          name: "Psychic",
          cost: [5 /* PSYCHIC */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 50,
          text: "Does 10 more damage for each Energy attached to the Defending Pokemon."
        }
      ];
      this.set = "DRX";
      this.name = "Sigilyph";
      this.fullName = "Sigilyph DRX";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "52";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        const energyCount = checkProvidedEnergyEffect.energyMap.reduce(
          (left, p) => left + p.provides.length,
          0
        );
        effect.damage += energyCount * 10;
      }
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        const sourceCard = effect.source.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (sourceCard && sourceCard.hasTag("EX" /* POKEMON_EX */)) {
          try {
            const player = StateUtils.findOwner(state, effect.target);
            const stub = new PowerEffect(
              player,
              {
                name: "test",
                powerType: 2 /* ABILITY */,
                text: ""
              },
              this
            );
            store.reduceEffect(state, stub);
          } catch {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      return state;
    }
  };

