  var Slaking = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Vigoroth";
      this.cardType = [C];
      this.hp = 150;
      this.weakness = [{ type: F }];
      this.retreat = [C, C, C, C];
      this.powers = [{
        name: "Unobservant",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "If your opponent's Active Pokemon is a Basic Pokemon, this Pokemon can't attack."
      }];
      this.attacks = [
        {
          name: "Crushing Blow",
          cost: [C, C, C, C],
          damage: 100,
          text: "Discard an Energy attached to the Defending Pokemon."
        }
      ];
      this.set = "DRX";
      this.setNumber = "103";
      this.cardImage = "assets/cardback.png";
      this.name = "Slaking";
      this.fullName = "Slaking DRX";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttackEffect && effect.player.active.getPokemonCard() === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!IS_ABILITY_BLOCKED(store, state, player, this)) {
          const opponentActive = opponent.active.getPokemonCard();
          if (opponentActive && opponentActive.stage === 2 /* BASIC */) {
            throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
          }
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_AN_ENERGY_FROM_OPPONENTS_ACTIVE_POKEMON(store, state, effect);
      }
      return state;
    }
  };

