  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-dragons-exalted/terrakion-ex.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attach_energy_prompt();
  init_prefabs();
  var TerrakionEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["EX" /* POKEMON_EX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 180;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Rock Tumble",
          cost: [F, C],
          damage: 50,
          text: "This attack's damage isn't affected by Resistance."
        },
        {
          name: "Pump-up Smash",
          cost: [F, F, C],
          damage: 90,
          text: "Attach 2 basic Energy cards from your hand to your Benched Pokemon in any way you like."
        }
      ];
      this.set = "DRX";
      this.setNumber = "71";
      this.cardImage = "assets/cardback.png";
      this.name = "Terrakion-EX";
      this.fullName = "Terrakion-EX DRX";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.ignoreResistance = true;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasBasicEnergy = player.hand.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        );
        if (!hasBasicEnergy) {
          return state;
        }
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        const availableCount = player.hand.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        ).length;
        const count = Math.min(2, availableCount);
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.hand,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: count, max: count }
          ),
          (transfers) => {
            if (transfers) {
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, player.hand, target, { cards: [transfer.card], sourceCard: this });
              }
            }
          }
        );
      }
      return state;
    }
  };

