  init_pokemon_card();
  init_card_types();
  init_check_effects();
  init_prefabs();
  var Wailord = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Wailmer";
      this.cardType = [W];
      this.hp = 200;
      this.weakness = [{ type: L }];
      this.retreat = [C, C, C, C];
      this.attacks = [{
        name: "Water Cannon",
        cost: [W],
        damage: 30,
        damageCalculation: "x",
        text: "Flip a coin. If heads, this attack does 30 damage times the amount of [W] Energy attached to this Pok\xE9mon."
      }, {
        name: "Giant Wave",
        cost: [W, C, C, C],
        damage: 80,
        text: "This Pok\xE9mon can't use Giant Wave during your next turn."
      }];
      this.set = "DRX";
      this.setNumber = "26";
      this.cardImage = "assets/cardback.png";
      this.name = "Wailord";
      this.fullName = "Wailord DRX";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
            state = store.reduceEffect(state, checkProvidedEnergy);
            let waterCount = 0;
            for (const energyMap of checkProvidedEnergy.energyMap) {
              waterCount += energyMap.provides.filter((t) => t === 3 /* WATER */ || t === 0 /* ANY */).length;
            }
            effect.damage = 30 * waterCount;
          } else {
            effect.damage = 0;
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        THIS_POKEMON_CANNOT_USE_THIS_ATTACK_NEXT_TURN(effect.player, this.attacks[1]);
      }
      return state;
    }
  };

