  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-dragons-exalted/tool-scrapper.ts
  init_trainer_card();
  init_card_types();
  init_play_card_effects();
  init_prefabs();
  init_game();
  function* playCard71(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let pokemonsWithTool = 0;
    const blocked = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      if (cardList.tools.length > 0) {
        pokemonsWithTool += 1;
      } else {
        blocked.push(target);
      }
    });
    opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
      if (cardList.tools.length > 0) {
        pokemonsWithTool += 1;
      } else {
        blocked.push(target);
      }
    });
    if (pokemonsWithTool === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    const max = Math.min(2, pokemonsWithTool);
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_DISCARD_CARDS,
        0 /* ANY */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { min: 1, max, allowCancel: true, blocked }
      ),
      (results) => {
        targets = results || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    targets.forEach((target) => {
      const owner = StateUtils.findOwner(state, target);
      if (target.tools.length > 0) {
        MOVE_CARDS(store, state, target, owner.discard, {
          cards: [target.tools[0]],
          sourceCard: effect.trainerCard
        });
      }
    });
    return state;
  }
