  var Garchomp3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Gabite";
      this.cardType = [N];
      this.hp = 140;
      this.weakness = [{ type: N }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Mach Cut",
          cost: [F],
          damage: 60,
          text: "Discard a Special Energy attached to the Defending Pok\xE9mon."
        },
        {
          name: "Dragonblade",
          cost: [W, F],
          damage: 100,
          text: "Discard the top 2 cards of your deck."
        }
      ];
      this.set = "PLF";
      this.setNumber = "120";
      this.cardImage = "assets/cardback.png";
      this.name = "Garchomp";
      this.fullName = "Garchomp PLF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasSpecialEnergy = opponent.active.cards.some(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 1 /* SPECIAL */
        );
        if (hasSpecialEnergy) {
          const blocked = [];
          opponent.active.cards.forEach((c, index) => {
            if (c.superType !== 3 /* ENERGY */ || c.energyType !== 1 /* SPECIAL */) {
              blocked.push(index);
            }
          });
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.active,
            { superType: 3 /* ENERGY */ },
            { min: 1, max: 1, allowCancel: false, blocked }
          ), (selected) => {
            if (selected && selected.length > 0) {
              MOVE_CARDS(store, state, opponent.active, opponent.discard, { cards: [selected[0]], sourceCard: this });
            }
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        DISCARD_TOP_X_CARDS_FROM_YOUR_DECK(store, state, player, 2, this, effect);
      }
      return state;
    }
  };

