  var Gothitelle2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Gothorita";
      this.cardType = [P];
      this.hp = 130;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Magic Room",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is your Active Pok\xE9mon, your opponent can't play any Item cards from his or her hand."
      }];
      this.attacks = [{
        name: "Madkinesis",
        cost: [C, C, C],
        damage: 30,
        text: "Does 20 more damage for each [P] Energy attached to this Pok\xE9mon."
      }];
      this.set = "LTR";
      this.setNumber = "72";
      this.cardImage = "assets/cardback.png";
      this.name = "Gothitelle";
      this.fullName = "Gothitelle LTR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let psychicEnergies = 0;
        checkProvidedEnergyEffect.energyMap.forEach((energy2) => {
          energy2.provides.forEach((c) => {
            psychicEnergies += c === 5 /* PSYCHIC */ ? 1 : 0;
          });
        });
        effect.damage += 20 * psychicEnergies;
        return state;
      }
      if (effect instanceof PlayItemEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const pokemonCard = opponent.active.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        throw new GameError(GameMessage.BLOCKED_BY_ABILITY);
      }
      return state;
    }
  };

