  function* playCard73(next, store, state, effect) {
    const player = effect.player;
    const blocked = [];
    let hasPokemonWithDamage = false;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      if (cardList.damage === 0) {
        blocked.push(target);
      } else {
        hasPokemonWithDamage = true;
      }
    });
    if (hasPokemonWithDamage === false) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_HEAL,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: true, blocked }
      ),
      (results) => {
        targets = results || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    targets.forEach((target) => {
      const healEffect = new HealEffect(player, target, target.damage);
      store.reduceEffect(state, healEffect);
      const cards = target.cards.filter((c) => c.superType === 3 /* ENERGY */);
      MOVE_CARDS(store, state, target, player.discard, {
        cards,
        sourceCard: effect.trainerCard
      });
    });
    return state;
  }
