  var Sawsbuck2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Deerling";
      this.cardType = [G];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Push Down",
          cost: [C, C],
          damage: 30,
          text: "Your opponent switches the Defending Pok\xE9mon with 1 of his or her Benched Pok\xE9mon."
        },
        {
          name: "Take Down",
          cost: [G, C],
          damage: 60,
          text: "This Pok\xE9mon does 20 damage to itself."
        }
      ];
      this.set = "EPO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "16";
      this.name = "Sawsbuck";
      this.fullName = "Sawsbuck EPO";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          opponent.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (result) => {
          const cardList = result[0];
          opponent.switchPokemon(cardList);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        THIS_POKEMON_DOES_DAMAGE_TO_ITSELF(store, state, effect, 20);
      }
      return state;
    }
  };

