  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-emerging-powers/simipour.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_move_energy_prompt();
  init_attack_effects2();
  var Simipour2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Panpour";
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Grass' Power",
          cost: [C, C],
          damage: 30,
          text: "If this Pok\xE9mon has any [G] Energy attached to it, heal 20 damage from this Pok\xE9mon."
        },
        {
          name: "Rushing Water",
          cost: [W, C, C],
          damage: 60,
          text: "Move an Energy attached to the Defending Pok\xE9mon to 1 of your opponent's Benched Pok\xE9mon."
        }
      ];
      this.set = "EPO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "23";
      this.name = "Simipour";
      this.fullName = "Simipour EPO";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasGrassEnergy = player.active.cards.some(
          (c) => c.superType === 3 /* ENERGY */ && c.provides.includes(1 /* GRASS */)
        );
        if (hasGrassEnergy) {
          HEAL_X_DAMAGE_FROM_THIS_POKEMON2(20, effect, store, state);
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentActive = opponent.active;
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        const hasEnergy = opponentActive.cards.some((c) => c.superType === 3 /* ENERGY */);
        if (!hasBench || !hasEnergy) {
          return state;
        }
        const blockedTo = [];
        const blockedFrom = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList === opponentActive) {
            blockedTo.push(target);
            return;
          }
          blockedFrom.push(target);
        });
        return store.prompt(state, new MoveEnergyPrompt(
          player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { min: 1, max: 1, allowCancel: false, blockedFrom, blockedTo }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const source = StateUtils.getTarget(state, opponent, transfer.from);
            const target = StateUtils.getTarget(state, opponent, transfer.to);
            MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

