  var Swoobat3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Woobat";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.attacks = [{
        name: "Psyshot",
        cost: [P],
        damage: 30,
        text: ""
      }, {
        name: "Phat Sound",
        cost: [P, C],
        damage: 0,
        text: "Flip 3 coins. This attack does 10 damage times the number of heads to each of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.set = "EPO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "37";
      this.name = "Swoobat";
      this.fullName = "Swoobat EPO";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          let heads = 0;
          results.forEach((r) => {
            if (r) heads++;
          });
          if (heads > 0) {
            const damage = 10 * heads;
            const dealDamage = new DealDamageEffect(effect, damage);
            dealDamage.target = opponent.active;
            store.reduceEffect(state, dealDamage);
            opponent.bench.forEach((bench) => {
              if (bench.cards.length > 0) {
                const putDamage = new PutDamageEffect(effect, damage);
                putDamage.target = bench;
                store.reduceEffect(state, putDamage);
              }
            });
          }
        });
      }
      return state;
    }
  };

