  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-emerging-powers/gigalith.ts
  init_pokemon_card();
  init_card_types();
  init_prefabs();
  init_check_effects();
  var Gigalith2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Boldore";
      this.cardType = [F];
      this.hp = 140;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Shear",
          cost: [F],
          damage: 0,
          text: "Discard the top 5 cards of your deck. If any of those cards are [F] Energy cards, attach them to this Pok\xE9mon."
        },
        {
          name: "Rock Bullet",
          cost: [C, C, C, C],
          damage: 40,
          damageCalculation: "+",
          text: "Does 20 more damage for each [F] Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "EPO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "53";
      this.name = "Gigalith";
      this.fullName = "Gigalith EPO";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cardsToDiscard = player.deck.cards.slice(0, 5);
        cardsToDiscard.forEach((card) => {
          if (card.superType === 3 /* ENERGY */ && card.energyType === 0 /* BASIC */ && card.name === "Fighting Energy") {
            MOVE_CARDS(store, state, player.deck, player.active, { cards: [card], sourceCard: this });
          } else {
            MOVE_CARDS(store, state, player.deck, player.discard, { cards: [card], sourceCard: this });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        let fightingEnergy = 0;
        checkEnergy.energyMap.forEach((em) => {
          fightingEnergy += em.provides.filter((p) => p === 6 /* FIGHTING */).length;
        });
        effect.damage += 20 * fightingEnergy;
      }
      return state;
    }
  };

