  var Ferrothorn = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Ferroseed";
      this.cardType = [M];
      this.hp = 90;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Steel Feelers",
        cost: [M],
        damage: 30,
        damageCalculation: "x",
        text: "Flip 3 coins. This attack does 30 damage times the number of heads."
      }, {
        name: "Gyro Ball",
        cost: [M, C, C],
        damage: 60,
        text: "Switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon. Then, your opponent switches the Defending Pok\xE9mon with 1 of his or her Benched Pok\xE9mon."
      }];
      this.set = "EPO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "72";
      this.name = "Ferrothorn";
      this.fullName = "Ferrothorn EPO";
      this.usedGyroBall = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 3, (results) => {
          let heads = 0;
          results.forEach((r) => {
            if (r) heads++;
          });
          effect.damage = 30 * heads;
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedGyroBall = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedGyroBall) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const playerHasBench = player.bench.some((b) => b.cards.length > 0);
        const opponentHasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (playerHasBench) {
          return store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ), (playerResult) => {
            const playerTarget = playerResult[0];
            player.switchPokemon(playerTarget);
            if (opponentHasBench) {
              return store.prompt(state, new ChoosePokemonPrompt(
                opponent.id,
                GameMessage.CHOOSE_POKEMON_TO_SWITCH,
                1 /* TOP_PLAYER */,
                [2 /* BENCH */],
                { allowCancel: false }
              ), (opponentResult) => {
                const opponentTarget = opponentResult[0];
                opponent.switchPokemon(opponentTarget);
              });
            }
          });
        } else if (opponentHasBench) {
          return store.prompt(state, new ChoosePokemonPrompt(
            opponent.id,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ), (opponentResult) => {
            const opponentTarget = opponentResult[0];
            opponent.switchPokemon(opponentTarget);
          });
        }
      }
      if (effect instanceof EndTurnEffect && this.usedGyroBall) {
        this.usedGyroBall = false;
      }
      return state;
    }
  };

