  var Watchog3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Patrat";
      this.cardType = [C];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [{
        name: "Watcheck",
        cost: [C],
        damage: 0,
        text: "Look at the top 5 cards of your opponent's deck and put them back on top of his or her deck in any order."
      }, {
        name: "Quick Tail Smash",
        cost: [C, C],
        damage: 20,
        damageCalculation: "+",
        text: "Before doing damage, you may flip a coin. If heads, this attack does 60 more damage. If tails, this attack does nothing."
      }];
      this.set = "EPO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "79";
      this.name = "Watchog";
      this.fullName = "Watchog EPO";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.deck.cards.length === 0) {
          return state;
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, opponent.deck, deckTop, { count: 5, sourceCard: this });
        return store.prompt(state, new OrderCardsPrompt(
          player.id,
          GameMessage.CHOOSE_CARDS_ORDER,
          deckTop,
          { allowCancel: false }
        ), (order) => {
          if (order === null) {
            return state;
          }
          deckTop.applyOrder(order);
          deckTop.moveToTopOfDestination(opponent.deck);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            effect.damage += 60;
          } else {
            effect.damage = 0;
          }
        });
      }
      return state;
    }
  };

