  var Audino4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Powerful Slap",
        cost: [C],
        damage: 40,
        damageCalculation: "x",
        text: "Flip a coin for each Energy attached to this Pok\xE9mon. This attack does 40 damage times the number of heads."
      }, {
        name: "Heal Pulse",
        cost: [C, C, C],
        damage: 0,
        text: "Heal 50 damage from 1 of your Pok\xE9mon."
      }];
      this.set = "EPO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "83";
      this.name = "Audino";
      this.fullName = "Audino EPO";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        let energyCount = 0;
        checkEnergy.energyMap.forEach((em) => {
          energyCount += em.provides.length;
        });
        if (energyCount === 0) {
          effect.damage = 0;
          return state;
        }
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, energyCount, (results) => {
          let heads = 0;
          results.forEach((r) => {
            if (r) heads++;
          });
          effect.damage = 40 * heads;
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_HEAL,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false }
        ), (targets) => {
          if (targets && targets.length > 0) {
            const target = targets[0];
            target.damage = Math.max(0, target.damage - 50);
          }
        });
      }
      return state;
    }
  };

