  var Krookodile3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Krokorok";
      this.cardType = [F];
      this.hp = 140;
      this.weakness = [{ type: W }];
      this.resistance = [{ type: L, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Black Eyes",
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), if this Pok\xE9mon is your Active Pok\xE9mon, you may flip a coin. If heads, discard an Energy attached to your opponent's Active Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Thrash",
        cost: [F, F, C],
        damage: 70,
        damageCalculation: "+",
        text: "Flip a coin. If heads, this attack does 20 more damage. If tails, this Pok\xE9mon does 20 damage to itself."
      }];
      this.set = "EPO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "62";
      this.name = "Krookodile";
      this.fullName = "Krookodile EPO";
      this.BLACK_EYES_MARKER = "BLACK_EYES_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.active.getPokemonCard() !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.BLACK_EYES_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.marker.addMarker(this.BLACK_EYES_MARKER, this);
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            const energyCards = opponent.active.cards.filter((c) => c.superType === 3 /* ENERGY */);
            if (energyCards.length > 0) {
              MOVE_CARDS(store, state, opponent.active, opponent.discard, { cards: [energyCards[0]], sourceCard: this });
            }
          }
        });
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.BLACK_EYES_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            effect.damage += 20;
          } else {
            THIS_POKEMON_DOES_DAMAGE_TO_ITSELF(store, state, effect, 20);
          }
        });
      }
      return state;
    }
  };

