  var Empoleon3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Prinplup";
      this.cardType = [W];
      this.hp = 140;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Surf",
          cost: [W, C],
          damage: 50,
          text: ""
        },
        {
          name: "Emperor's Strike",
          cost: [W, W, C],
          damage: 70,
          damageCalculation: "+",
          text: "If this Pok\xE9mon has fewer remaining HP than the Defending Pok\xE9mon, this attack does 60 more damage."
        }
      ];
      this.set = "LTR";
      this.setNumber = "35";
      this.cardImage = "assets/cardback.png";
      this.name = "Empoleon";
      this.fullName = "Empoleon LTR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const myRemainingHP = this.hp - player.active.damage;
        const defenderCard = opponent.active.getPokemonCard();
        const defenderRemainingHP = defenderCard ? defenderCard.hp - opponent.active.damage : 0;
        if (myRemainingHP < defenderRemainingHP) {
          effect.damage += 60;
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-legendary-treasures/excadrill-ex.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects();
  init_card_list();
  var ExcadrillEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["EX" /* POKEMON_EX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 180;
      this.weakness = [{ type: W }];
      this.resistance = [{ type: L, value: -20 }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Dig Out",
          cost: [C, C],
          damage: 40,
          text: "Discard the top card of your deck. If that card is a basic Energy card, attach it to 1 of your Pok\xE9mon."
        },
        {
          name: "Break Ground",
          cost: [F, F, C, C],
          damage: 120,
          text: "Does 10 damage to each of your Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "LTR";
      this.setNumber = "82";
      this.cardImage = "assets/cardback.png";
      this.name = "Excadrill-EX";
      this.fullName = "Excadrill-EX LTR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const topOfDeck = new CardList();
        MOVE_CARDS(store, state, player.deck, topOfDeck, { count: 1, sourceCard: this });
        const discardedEnergy = topOfDeck.cards.filter((card) => {
          return card.superType === 3 /* ENERGY */ && card.energyType === 0 /* BASIC */;
        });
        if (discardedEnergy.length === 0) {
          MOVE_CARDS(store, state, topOfDeck, player.discard, { sourceCard: this });
        } else {
          store.prompt(
            state,
            new AttachEnergyPrompt(
              player.id,
              GameMessage.ATTACH_ENERGY_TO_BENCH,
              topOfDeck,
              2 /* BOTTOM_PLAYER */,
              [1 /* ACTIVE */, 2 /* BENCH */],
              { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
              { allowCancel: false, min: 1, max: 1 }
            ),
            (transfers) => {
              transfers = transfers || [];
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, topOfDeck, target, { cards: [transfer.card], sourceCard: this });
              }
              MOVE_CARDS(store, state, topOfDeck, player.discard, { sourceCard: this });
            }
          );
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList === player.active) {
            return;
          }
          const damage = new PutDamageEffect(effect, 10);
          damage.target = cardList;
          store.reduceEffect(state, damage);
        });
      }
      return state;
    }
  };

