  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var Ninetales5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Vulpix";
      this.cardType = [R];
      this.hp = 90;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Color Coordination",
          cost: [C, C, C],
          damage: 50,
          damageCalculation: "+",
          text: "If this Pok\xE9mon has any basic Energy attached to it that is the same type as the Defending Pok\xE9mon, this attack does 40 more damage."
        }
      ];
      this.set = "LTR";
      this.setNumber = "21";
      this.cardImage = "assets/cardback.png";
      this.name = "Ninetales";
      this.fullName = "Ninetales LTR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const defendingCard = opponent.active.getPokemonCard();
        if (defendingCard) {
          const defendingType = getPrimaryCardType(defendingCard);
          const checkEnergy = new CheckProvidedEnergyEffect(player);
          store.reduceEffect(state, checkEnergy);
          const hasMatchingEnergy = checkEnergy.energyMap.some(
            (em) => em.card.energyType === 0 /* BASIC */ && em.provides.includes(defendingType)
          );
          if (hasMatchingEnergy) {
            effect.damage += 40;
          }
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-legendary-treasures/phione.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_game_phase_effects();
  init_choose_cards_prompt();
  init_show_cards_prompt();
  init_card_list();
  var Phione = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 70;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Pull Out",
          cost: [C],
          damage: 0,
          text: "Put a card from your discard pile on top of your deck."
        },
        {
          name: "Aqua Boomerang",
          cost: [W],
          damage: 20,
          text: "Return this Pok\xE9mon and all cards attached to it to your hand."
        }
      ];
      this.set = "LTR";
      this.setNumber = "36";
      this.cardImage = "assets/cardback.png";
      this.name = "Phione";
      this.fullName = "Phione LTR";
      this.usedAquaBoomerang = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_DISCARD_EMPTY(player);
        let cards = [];
        const deckTop = new CardList();
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARDS_TO_PUT_ON_TOP_OF_THE_DECK,
          player.discard,
          {},
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          cards = selected || [];
          MOVE_CARDS(store, state, player.discard, deckTop, { cards, sourceCard: this });
          deckTop.moveToTopOfDestination(player.deck);
          if (cards.length > 0) {
            store.prompt(state, new ShowCardsPrompt(
              opponent.id,
              GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
              cards
            ), () => {
            });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedAquaBoomerang = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedAquaBoomerang) {
        this.usedAquaBoomerang = false;
        const player = effect.player;
        const activePokemon = player.active;
        MOVE_CARDS(store, state, activePokemon, player.hand, { sourceCard: this });
        activePokemon.clearEffects();
      }
      if (effect instanceof EndTurnEffect) {
        this.usedAquaBoomerang = false;
      }
      return state;
    }
  };

