  init_game();
  init_prefabs();
  init_check_effects();
  var Serperior5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Servine";
      this.cardType = [G];
      this.hp = 140;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Royal Garden",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon has any [G] Energy attached to it, this Pok\xE9mon has no Retreat Cost."
      }];
      this.attacks = [
        {
          name: "Solar Beam",
          cost: [G, C, C],
          damage: 80,
          text: ""
        }
      ];
      this.set = "LTR";
      this.setNumber = "RC3";
      this.cardImage = "assets/cardback.png";
      this.name = "Serperior";
      this.fullName = "Serperior LTR";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect) {
        const player = effect.player;
        if (effect.player.active.getPokemonCard() !== this) {
          return state;
        }
        let isInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            isInPlay = true;
          }
        });
        if (!isInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        const energyMap = checkProvidedEnergyEffect.energyMap;
        const hasGrassEnergy = StateUtils.checkEnoughEnergy(energyMap, [1 /* GRASS */]);
        if (hasGrassEnergy) {
          effect.cost = [];
        }
      }
      return state;
    }
  };

