  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-legendary-treasures/spiritomb.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_prefabs();
  var Spiritomb2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 80;
      this.retreat = [C];
      this.powers = [
        {
          name: "Sealing Scream",
          powerType: 2 /* ABILITY */,
          text: "Each player can't play any ACE SPEC cards from his or her hand."
        }
      ];
      this.attacks = [
        {
          name: "Hexed Mirror",
          cost: [C],
          damage: 0,
          text: "Shuffle your hand into your deck. Then, draw a number of cards equal to the number of cards in your opponent's hand."
        }
      ];
      this.set = "LTR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "87";
      this.name = "Spiritomb";
      this.fullName = "Spiritomb LTR";
      this.OPPONENT_CANNOT_PLAY_ACE_SPECS_MARKER = "OPPONENT_CANNOT_PLAY_ACE_SPECS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayItemEffect && effect.trainerCard.hasTag("Ace Spec" /* ACE_SPEC */)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let isSpiritombInPlay = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card) => {
          if (card === this) {
            isSpiritombInPlay = true;
          }
        });
        if (!isSpiritombInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
      }
      if (effect instanceof AttachPokemonToolEffect && effect.trainerCard.hasTag("Ace Spec" /* ACE_SPEC */)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let isSpiritombInPlay = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card) => {
          if (card === this) {
            isSpiritombInPlay = true;
          }
        });
        if (!isSpiritombInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
      }
      if (effect instanceof AttachEnergyEffect && effect.energyCard.hasTag("Ace Spec" /* ACE_SPEC */)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let isSpiritombInPlay = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card) => {
          if (card === this) {
            isSpiritombInPlay = true;
          }
        });
        if (!isSpiritombInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
      }
      if (effect instanceof PlayStadiumEffect && effect.trainerCard.hasTag("Ace Spec" /* ACE_SPEC */)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let isSpiritombInPlay = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card) => {
          if (card === this) {
            isSpiritombInPlay = true;
          }
        });
        if (!isSpiritombInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        MOVE_CARDS(store, state, player.hand, player.deck, {
          cards: player.hand.cards.filter((c) => c !== this)
        });
        SHUFFLE_DECK(store, state, player);
        DRAW_CARDS(store, state, player, effect.opponent.hand.cards.length);
      }
      return state;
    }
  };

