  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-legendary-treasures/swoobat.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Swoobat4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Woobat";
      this.cardType = [P];
      this.hp = 80;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.attacks = [{
        name: "Energy Gift",
        cost: [C],
        damage: 0,
        text: "Flip a coin. If heads, search your deck for 2 [P] Energy cards and attach them to your Pok\xE9mon in any way you like. Shuffle your deck afterward."
      }, {
        name: "Heart Stamp",
        cost: [P],
        damage: 30,
        text: ""
      }];
      this.set = "LTR";
      this.setNumber = "65";
      this.cardImage = "assets/cardback.png";
      this.name = "Swoobat";
      this.fullName = "Swoobat LTR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            if (player.deck.cards.length === 0) {
              return;
            }
            const psychicEnergyCount = player.deck.cards.filter(
              (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(5 /* PSYCHIC */)
            ).length;
            if (psychicEnergyCount === 0) {
              SHUFFLE_DECK(store, state, player);
              return;
            }
            const maxAttach = Math.min(2, psychicEnergyCount);
            store.prompt(state, new AttachEnergyPrompt(
              player.id,
              GameMessage.ATTACH_ENERGY_TO_BENCH,
              player.deck,
              2 /* BOTTOM_PLAYER */,
              [1 /* ACTIVE */, 2 /* BENCH */],
              { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Psychic Energy" },
              { allowCancel: true, min: 0, max: maxAttach }
            ), (transfers) => {
              transfers = transfers || [];
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
              }
              SHUFFLE_DECK(store, state, player);
            });
          }
        });
      }
      return state;
    }
  };

