  var Ursaring2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Teddiursa";
      this.cardType = [C];
      this.hp = 130;
      this.weakness = [{ type: F }];
      this.retreat = [C, C, C];
      this.attacks = [{
        name: "Picnic Weather",
        cost: [C, C],
        damage: 0,
        text: "Put a Teddiursa from your discard pile onto your Bench. Then, attach an Energy card from your discard pile to that Pok\xE9mon."
      }, {
        name: "Fury Swipes",
        cost: [C, C, C, C],
        damage: 50,
        damageCalculation: "x",
        text: "Flip 3 coins. This attack does 50 damage times the number of heads."
      }];
      this.set = "LTR";
      this.setNumber = "RC16";
      this.cardImage = "assets/cardback.png";
      this.name = "Ursaring";
      this.fullName = "Ursaring LTR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasTeddiursa = player.discard.cards.some(
          (c) => c instanceof PokemonCard && c.name === "Teddiursa"
        );
        const slot = player.bench.find((b) => b.cards.length === 0);
        if (!hasTeddiursa || !slot) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        const blocked = [];
        player.discard.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || card.name !== "Teddiursa") {
            blocked.push(index);
          }
        });
        let cards = [];
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          player.discard,
          { superType: 1 /* POKEMON */ },
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (selected) => {
          cards = selected || [];
          if (cards.length > 0) {
            MOVE_CARDS(store, state, player.discard, slot, { cards, sourceCard: this });
            slot.pokemonPlayedTurn = state.turn;
            const hasEnergy = player.discard.cards.some((c) => c.superType === 3 /* ENERGY */);
            if (hasEnergy) {
              const energyBlocked = [];
              player.discard.cards.forEach((card, index) => {
                if (card.superType !== 3 /* ENERGY */) {
                  energyBlocked.push(index);
                }
              });
              store.prompt(state, new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARD_TO_ATTACH,
                player.discard,
                { superType: 3 /* ENERGY */ },
                { min: 1, max: 1, allowCancel: false, blocked: energyBlocked }
              ), (energySelected) => {
                energySelected = energySelected || [];
                if (energySelected.length > 0) {
                  MOVE_CARDS(store, state, player.discard, slot, { cards: energySelected, sourceCard: this });
                }
              });
            }
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          let heads = 0;
          results.forEach((r) => {
            if (r) heads++;
          });
          effect.damage = 50 * heads;
        });
      }
      return state;
    }
  };

