  var Xatu2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Natu";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [{
        name: "Fortunate Draw",
        cost: [P],
        damage: 0,
        text: "You and your opponent play Rock-Paper-Scissors. The player who wins draws 3 cards. The player who loses discards the top 3 cards of his or her deck."
      }, {
        name: "Miracle Wing",
        cost: [P, C, C],
        damage: 60,
        text: "Flip a coin. If heads, the Defending Pok\xE9mon is now Confused."
      }];
      this.set = "LTR";
      this.setNumber = "56";
      this.cardImage = "assets/cardback.png";
      this.name = "Xatu";
      this.fullName = "Xatu LTR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const options = [
          { value: "Rock", message: "Rock" },
          { value: "Paper", message: "Paper" },
          { value: "Scissors", message: "Scissors" }
        ];
        store.prompt(state, [
          new SelectPrompt(
            player.id,
            GameMessage.CHOOSE_OPTION,
            options.map((c) => c.message),
            { allowCancel: false }
          ),
          new SelectPrompt(
            opponent.id,
            GameMessage.CHOOSE_OPTION,
            options.map((c) => c.message),
            { allowCancel: false }
          )
        ], (results) => {
          const playerChoice = results[0];
          const opponentChoice = results[1];
          if (playerChoice === opponentChoice) {
            return this.reduceEffect(store, state, effect);
          }
          const playerWins = playerChoice === 1 && opponentChoice === 0 || playerChoice === 2 && opponentChoice === 1 || playerChoice === 0 && opponentChoice === 2;
          if (playerWins) {
            DRAW_CARDS(store, state, player, 3);
            const millCount = Math.min(3, opponent.deck.cards.length);
            MOVE_CARDS(store, state, opponent.deck, opponent.discard, { count: millCount, sourceCard: this });
          } else {
            DRAW_CARDS(store, state, opponent, 3);
            const millCount = Math.min(3, player.deck.cards.length);
            MOVE_CARDS(store, state, player.deck, player.discard, { count: millCount, sourceCard: this });
          }
        });
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
          }
        });
      }
      return state;
    }
  };

