  var CedricJuniper = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "LTR";
      this.setNumber = "110";
      this.cardImage = "assets/cardback.png";
      this.name = "Cedric Juniper";
      this.fullName = "Cedric Juniper LTR";
      this.text = "Put a Pok\xE9mon from your hand face down in front of you and tell your opponent its name. Your opponent guesses the height of that Pok\xE9mon. Reveal that Pok\xE9mon. If your opponent guessed right, he or she draws 3 cards. If your opponent guessed wrong, you draw 3 cards. Return the Pok\xE9mon to your hand. (You can't choose a Pok\xE9mon that doesn't have the height printed on the card.) You may play only 1 Supporter card during your turn (before your attack).";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const hasPokemonInHand = player.hand.cards.some((c) => c instanceof PokemonCard);
        if (!hasPokemonInHand) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        const selectedPokemon = new CardList();
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.hand,
            { superType: 1 /* POKEMON */ },
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length === 0) {
              return;
            }
            MOVE_CARDS(store, state, player.hand, selectedPokemon, {
              cards,
              sourceCard: this
            });
            store.prompt(
              state,
              new SelectPrompt(
                opponent.id,
                GameMessage.CHOOSE_OPTION,
                ["Guessed right", "Guessed wrong"],
                { allowCancel: false }
              ),
              (choice) => {
                const opponentGuessedRight = choice === 0;
                MOVE_CARDS(store, state, selectedPokemon, player.hand, { sourceCard: this });
                store.prompt(
                  state,
                  new ShowCardsPrompt(
                    opponent.id,
                    GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                    selectedPokemon.cards
                  ),
                  () => {
                    if (opponentGuessedRight) {
                      DRAW_CARDS(store, state, opponent, 3);
                    } else {
                      DRAW_CARDS(store, state, player, 3);
                    }
                  }
                );
              }
            );
          }
        );
      }
      return state;
    }
  };

