  var VictiniEX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["EX" /* POKEMON_EX */];
      this.cardType = [R];
      this.hp = 110;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Turbo Energize",
          cost: [R],
          damage: 0,
          text: "Search your deck for 2 basic Energy cards and attach them to your Benched Pok\xE9mon in any way you like. Shuffle your deck afterward."
        },
        {
          name: "Intensifying Burn",
          cost: [R, C, C],
          damage: 50,
          damageCalculation: "+",
          text: "If the Defending Pok\xE9mon is a Pok\xE9mon-EX, this attack does 50 more damage."
        }
      ];
      this.set = "PLS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "18";
      this.name = "Victini-EX";
      this.fullName = "Victini EX PLS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const openSlots = player.bench.filter((b) => b.cards.length === 0);
        if (!openSlots) {
          return state;
        }
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: 0, max: 2 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              SHUFFLE_DECK(store, state, player);
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
            }
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        if (effect.opponent.active.getPokemonCard()?.hasTag("EX" /* POKEMON_EX */)) {
          effect.damage += 50;
        }
      }
      return state;
    }
  };

