  init_prefabs();
  init_order_cards_prompt();
  var Reuniclus2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Duosion";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Future Sight",
          cost: [P],
          damage: 0,
          text: "Look at the top 5 cards of your deck and put them back on top of your deck in any order."
        },
        {
          name: "Net Force",
          cost: [P],
          damage: 40,
          damageCalculation: "x",
          text: "Does 40 damage times the number of Reuniclus you have in play."
        }
      ];
      this.set = "NVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "52";
      this.name = "Reuniclus";
      this.fullName = "Reuniclus NVI 52";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const deckTop = new CardList();
        const cardsToLook = Math.min(5, player.deck.cards.length);
        MOVE_CARDS(store, state, player.deck, deckTop, { count: cardsToLook, sourceCard: this });
        return store.prompt(state, new OrderCardsPrompt(
          player.id,
          GameMessage.CHOOSE_CARDS_ORDER,
          deckTop,
          { allowCancel: false }
        ), (order) => {
          if (order === null) {
            return state;
          }
          deckTop.applyOrder(order);
          deckTop.moveToTopOfDestination(player.deck);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        let reuniclusCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const pokemonCard = cardList.getPokemonCard();
          if (pokemonCard && pokemonCard.name === "Reuniclus") {
            reuniclusCount++;
          }
        });
        effect.damage = 40 * reuniclusCount;
      }
      return state;
    }
  };

