  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-noble-victories/leavanny.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_pokemon_types();
  init_prefabs();
  init_check_effects();
  var Leavanny3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Swadloon";
      this.cardType = [G];
      this.hp = 130;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Leaf Tailor",
        powerType: 2 /* ABILITY */,
        text: "Each of your Pok\xE9mon that has any Energy attached to it has no Weakness."
      }];
      this.attacks = [{
        name: "Cutting Arm",
        cost: [G, C, C],
        damage: 40,
        damageCalculation: "+",
        text: "Flip 2 coins. This attack does 20 more damage for each heads."
      }];
      this.set = "NVI";
      this.setNumber = "3";
      this.cardImage = "assets/cardback.png";
      this.name = "Leavanny";
      this.fullName = "Leavanny NVI";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonStatsEffect) {
        let leavannyOwner = null;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              leavannyOwner = p;
            }
          });
        });
        if (!leavannyOwner) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, leavannyOwner, this)) {
          return state;
        }
        let targetOwner = null;
        state.players.forEach((p) => {
          if (p.active === effect.target || p.bench.includes(effect.target)) {
            targetOwner = p;
          }
        });
        if (targetOwner !== leavannyOwner) {
          return state;
        }
        const checkEnergy = new CheckProvidedEnergyEffect(targetOwner, effect.target);
        store.reduceEffect(state, checkEnergy);
        if (checkEnergy.energyMap.length > 0) {
          effect.weakness = [];
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          let heads = 0;
          results.forEach((r) => {
            if (r) heads++;
          });
          effect.damage += 20 * heads;
        });
      }
      return state;
    }
  };

