  var Lucario2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Riolu";
      this.cardType = [F];
      this.hp = 100;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Reflexive Retaliation",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon is your Active Pok\xE9mon and is damaged by an opponent's attack (even if this Pok\xE9mon is Knocked Out), put 2 damage counters on the Attacking Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Aura Sphere",
        cost: [F, F],
        damage: 50,
        text: "Does 20 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.set = "NXD";
      this.setNumber = "64";
      this.cardImage = "assets/cardback.png";
      this.name = "Lucario";
      this.fullName = "Lucario NXD";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (effect.damage <= 0 || player === targetPlayer || targetPlayer.active !== effect.target) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetPlayer, this)) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        effect.source.damage += 20;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (targets) => {
          if (targets && targets.length > 0) {
            const damageEffect = new PutDamageEffect(effect, 20);
            damageEffect.target = targets[0];
            store.reduceEffect(state, damageEffect);
          }
        });
      }
      return state;
    }
  };

