  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-noble-victories/victini-2.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Victini2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [R];
      this.hp = 60;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.powers = [{
        name: "Victory Star",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, after you flip any coins for an attack, you may ignore all effects of those coin flips and begin flipping those coins again. You can't use more than 1 Victory Star Ability each turn."
      }];
      this.attacks = [
        {
          name: "Stored Power",
          cost: [R, C],
          damage: 30,
          text: "Move all Energy attached to this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.set = "NVI";
      this.setNumber = "14";
      this.cardImage = "assets/cardback.png";
      this.name = "Victini";
      this.fullName = "Victini NVI 14";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const attachedEnergies = player.active.cards.filter((card) => {
          return card.superType === 3 /* ENERGY */;
        });
        if (attachedEnergies.length === 0) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.active,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: attachedEnergies.length, max: attachedEnergies.length, sameTarget: true }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

