  var Chandelure = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Lampent";
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 130;
      this.weakness = [{ type: 7 /* DARK */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Cursed Shadow",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before attack), if this Pokemon is your Active Pokemon, you may put 3 damage counters on your opponent's Pokemon in any way you like."
      }];
      this.attacks = [{
        name: "Eerie Glow",
        cost: [5 /* PSYCHIC */, 5 /* PSYCHIC */, 9 /* COLORLESS */],
        damage: 50,
        text: "The Defending Pokemon is now Burned and Confused."
      }];
      this.set = "NVI";
      this.name = "Chandelure";
      this.fullName = "Chandelure NVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "60";
      this.CURSED_SHADOW_MARKER = "CURSED_SHADOW_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.CURSED_SHADOW_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (!player.active.cards.includes(this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.CURSED_SHADOW_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const maxAllowedDamage = [];
        let damageLeft = 0;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(opponent, cardList);
          store.reduceEffect(state, checkHpEffect);
          damageLeft += checkHpEffect.hp - cardList.damage;
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        const damage = Math.min(30, damageLeft);
        return store.prompt(state, new PutDamagePrompt(
          effect.player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          damage,
          maxAllowedDamage,
          { allowCancel: true }
        ), (targets) => {
          const results = targets || [];
          if (results.length === 0) {
            return;
          }
          player.marker.addMarker(this.CURSED_SHADOW_MARKER, this);
          for (const result of results) {
            const target = StateUtils.getTarget(state, player, result.target);
            target.damage += result.damage;
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const specialConditionEffect = new AddSpecialConditionsEffect(effect, [
          4 /* BURNED */,
          1 /* CONFUSED */
        ]);
        store.reduceEffect(state, specialConditionEffect);
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.CURSED_SHADOW_MARKER, this);
      }
      return state;
    }
  };

