  var Hydreigon3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Zweilous";
      this.cardType = [D];
      this.hp = 150;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Dark Aura",
        powerType: 2 /* ABILITY */,
        text: "Each basic Energy attached to your Pok\xE9mon provides [D] Energy instead of its usual type."
      }];
      this.attacks = [{
        name: "Berserker Blade",
        cost: [D, D, C, C],
        damage: 60,
        text: "Does 40 damage to 2 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.set = "NVI";
      this.setNumber = "79";
      this.cardImage = "assets/cardback.png";
      this.name = "Hydreigon";
      this.fullName = "Hydreigon NVI";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect) {
        const player = effect.player;
        let hydreigonInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            hydreigonInPlay = true;
          }
        });
        if (!hydreigonInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        let sourceOwner = null;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList === effect.source) {
            sourceOwner = player;
          }
        });
        if (sourceOwner !== player) {
          return state;
        }
        effect.energyMap.forEach((em) => {
          if (em.card.energyType === 0 /* BASIC */) {
            em.provides = em.provides.map(() => 7 /* DARK */);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { min: 1, max: 2, allowCancel: false }
        ), (targets) => {
          if (targets && targets.length > 0) {
            targets.forEach((target) => {
              const damageEffect = new PutDamageEffect(effect, 40);
              damageEffect.target = target;
              store.reduceEffect(state, damageEffect);
            });
          }
        });
      }
      return state;
    }
  };

