  function* playCard74(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (card instanceof PokemonCard && card.hp > 90) {
        blocked.push(index);
      }
    });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 1 /* POKEMON */ },
        { min: 1, max: 1, allowCancel: true, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: effect.trainerCard });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var LevelBall = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "NXD";
      this.name = "Level Ball";
      this.fullName = "Level Ball NXD";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "89";
      this.text = "Search your deck for a Pokemon with 90 HP or less, reveal it, and put it into your hand. Shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard74(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

