  var Arcanine22 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Growlithe";
      this.cardType = [R];
      this.hp = 130;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Blazing Mane",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon is your Active Pok\xE9mon and is damaged by an opponent's attack (even if this Pok\xE9mon is Knocked Out), the Attacking Pok\xE9mon is now Burned."
      }];
      this.attacks = [{
        name: "Fire Spin",
        cost: [R, R, C],
        damage: 100,
        text: "Flip a coin. If tails, discard 2 Energy attached to this Pok\xE9mon."
      }];
      this.set = "NXD";
      this.setNumber = "12";
      this.cardImage = "assets/cardback.png";
      this.name = "Arcanine";
      this.fullName = "Arcanine NXD 12";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (effect.damage <= 0 || player === targetPlayer || targetPlayer.active !== effect.target) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetPlayer, this)) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        player.active.addSpecialCondition(4 /* BURNED */);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (!result) {
            DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 2);
          }
        });
      }
      return state;
    }
  };

