  var Cilan = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "NXD";
      this.setNumber = "86";
      this.cardImage = "assets/cardback.png";
      this.name = "Cilan";
      this.fullName = "Cilan NXD";
      this.text = "Search your deck for up to 3 basic Energy cards, reveal them, and put them into your hand. Shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        const basicEnergyCount = player.deck.cards.filter(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
        ).length;
        if (basicEnergyCount === 0) {
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        }
        const maxToTake = Math.min(3, basicEnergyCount);
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min: 0, max: maxToTake, allowCancel: false }
          ),
          (selected) => {
            const selectedCards = selected || [];
            if (selectedCards.length > 0) {
              MOVE_CARDS(store, state, player.deck, player.hand, {
                cards: selectedCards,
                sourceCard: this
              });
              SHOW_CARDS_TO_PLAYER(store, state, opponent, selectedCards);
            }
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      return state;
    }
  };

