  var Shiftry = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Nuzleaf";
      this.cardType = [D];
      this.hp = 130;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Giant Fan",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon, you may flip a coin. If heads, choose 1 of your opponent's Pok\xE9mon. Your opponent shuffles that Pok\xE9mon and all cards attached to it into his or her deck."
      }];
      this.attacks = [{
        name: "Whirlwind",
        cost: [D, D, C],
        damage: 60,
        text: "Your opponent switches the Defending Pok\xE9mon with 1 of his or her Benched Pok\xE9mon."
      }];
      this.set = "NXD";
      this.setNumber = "72";
      this.cardImage = "assets/cardback.png";
      this.name = "Shiftry";
      this.fullName = "Shiftry NXD";
      this.usedWhirlwind = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            COIN_FLIP_PROMPT(store, state, player, (result) => {
              if (result) {
                const opponent = StateUtils.getOpponent(state, player);
                store.prompt(state, new ChoosePokemonPrompt(
                  player.id,
                  GameMessage.CHOOSE_POKEMON_TO_PICK_UP,
                  1 /* TOP_PLAYER */,
                  [1 /* ACTIVE */, 2 /* BENCH */],
                  { min: 1, max: 1, allowCancel: false }
                ), (targets) => {
                  if (targets && targets.length > 0) {
                    const targetPokemon = targets[0];
                    const cardsToShuffle = targetPokemon.cards.slice();
                    targetPokemon.clearEffects();
                    targetPokemon.cards = [];
                    SHUFFLE_CARDS_INTO_DECK(store, state, opponent, cardsToShuffle);
                  }
                });
              }
            });
          }
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedWhirlwind = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedWhirlwind) {
        this.usedWhirlwind = false;
        const opponent = StateUtils.getOpponent(state, effect.player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (hasBenched) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        }
      }
      if (effect instanceof EndTurnEffect && this.usedWhirlwind) {
        this.usedWhirlwind = false;
      }
      return state;
    }
  };

