  var Vanilluxe = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Vanillish";
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: M }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Slippery Soles",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may switch your Active Pok\xE9mon with 1 of your Benched Pok\xE9mon. If you do, your opponent switches his or her Active Pok\xE9mon with 1 of his or her Benched Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Crushing Ice",
        cost: [W, C, C],
        damage: 60,
        text: "Does 10 more damage for each Colorless in the Defending Pok\xE9mon's Retreat Cost."
      }];
      this.set = "NXD";
      this.setNumber = "33";
      this.cardImage = "assets/cardback.png";
      this.name = "Vanilluxe";
      this.fullName = "Vanilluxe NXD";
      this.SLIPPERY_SOLES_MARKER = "SLIPPERY_SOLES_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.SLIPPERY_SOLES_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const playerHasBench = player.bench.some((b) => b.cards.length > 0);
        if (!playerHasBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const opponentHasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (!opponentHasBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        player.marker.addMarker(this.SLIPPERY_SOLES_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
        SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
        SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        const defending = opponent.active.getPokemonCard();
        if (defending) {
          const retreatCost = defending.retreat.length;
          effect.damage += retreatCost * 10;
        }
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.SLIPPERY_SOLES_MARKER, this);
      }
      return state;
    }
  };

