  var Hippowdon = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Hippopotas";
      this.cardType = [F];
      this.hp = 130;
      this.weakness = [{ type: W }];
      this.resistance = [{ type: L, value: -20 }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Sand Bazooka",
          cost: [F, C, C],
          damage: 70,
          text: "You may move 1 Energy attached to this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Rock Tumble",
          cost: [F, F, C, C],
          damage: 90,
          text: "This attack's damage isn't affected by Resistance."
        }
      ];
      this.set = "NXD";
      this.setNumber = "66";
      this.cardImage = "assets/cardback.png";
      this.name = "Hippowdon";
      this.fullName = "Hippowdon NXD";
      this.usedSandBazooka = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedSandBazooka = true;
      }
      if (AFTER_ATTACK(effect, 0, this) && this.usedSandBazooka) {
        this.usedSandBazooka = false;
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        const hasEnergy = player.active.cards.some((c) => c.superType === 3 /* ENERGY */);
        if (!hasBenched || !hasEnergy) {
          return state;
        }
        const blocked = [];
        player.active.cards.forEach((card, index) => {
          if (card.superType !== 3 /* ENERGY */) {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_ATTACH,
          player.active,
          { superType: 3 /* ENERGY */ },
          { min: 0, max: 1, allowCancel: true, blocked }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length === 0) {
            return;
          }
          return store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ), (targets) => {
            if (targets && targets.length > 0) {
              MOVE_CARDS(store, state, player.active, targets[0], { cards: [cards[0]], sourceCard: this });
            }
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        effect.ignoreResistance = true;
      }
      return state;
    }
  };

