  init_choose_cards_prompt();
  init_attack_effects();
  init_prefabs();
  var Musharna3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Munna";
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 100;
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Forewarn",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may look at the top 2 cards of your deck, choose 1 of them, and put it into your hand. Put the other card back on top of your deck."
      }];
      this.attacks = [{
        name: "Fluffy Dream",
        cost: [5 /* PSYCHIC */, 5 /* PSYCHIC */],
        damage: 40,
        text: "This Pokemon is now Asleep."
      }];
      this.set = "NXD";
      this.name = "Musharna";
      this.fullName = "Musharna NXD";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "59";
      this.FOREWARN_MARKER = "FOREWARN_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.FOREWARN_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const specialConditionEffect = new AddSpecialConditionsEffect(effect, [2 /* ASLEEP */]);
        specialConditionEffect.target = player.active;
        store.reduceEffect(state, specialConditionEffect);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.FOREWARN_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.marker.addMarker(this.FOREWARN_MARKER, this);
        const deckTop = new CardList();
        deckTop.cards = player.deck.cards.slice(0, 2);
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          deckTop,
          {},
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          MOVE_CARDS(store, state, player.deck, player.hand, { cards: selected, sourceCard: this });
        });
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.FOREWARN_MARKER, this);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-next-destinies/nuzleaf.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Nuzleaf2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Seedot";
      this.cardType = [D];
      this.hp = 80;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Surprise Punch",
          cost: [D, C],
          damage: 20,
          text: "Move an Energy attached to the Defending Pok\xE9mon to 1 of your opponent's Benched Pok\xE9mon."
        }
      ];
      this.set = "NXD";
      this.setNumber = "71";
      this.cardImage = "assets/cardback.png";
      this.name = "Nuzleaf";
      this.fullName = "Nuzleaf NXD";
      this.usedSurprisePunch = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedSurprisePunch = true;
      }
      if (AFTER_ATTACK(effect, 0, this) && this.usedSurprisePunch) {
        this.usedSurprisePunch = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        const hasEnergy = opponent.active.cards.some((c) => c.superType === 3 /* ENERGY */);
        if (!hasBenched || !hasEnergy) {
          return state;
        }
        const blocked = [];
        opponent.active.cards.forEach((card, index) => {
          if (card.superType !== 3 /* ENERGY */) {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_ATTACH,
          opponent.active,
          { superType: 3 /* ENERGY */ },
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length === 0) {
            return;
          }
          return store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ), (targets) => {
            if (targets && targets.length > 0) {
              MOVE_CARDS(store, state, opponent.active, targets[0], { cards: [cards[0]], sourceCard: this });
            }
          });
        });
      }
      return state;
    }
  };

