  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-next-destinies/pokemon-center.ts
  init_game_error();
  init_game_message();
  init_trainer_card();
  init_card_types();
  init_stadium_effect();
  init_state_utils();
  init_game_effects();
  init_play_card_action();
  init_choose_pokemon_prompt();
  var PokemonCenter2 = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "NXD";
      this.name = "Pok\xE9mon Center";
      this.fullName = "Pokemon Center NXD";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "90";
      this.text = "Once during each player's turn, that player may heal 20 damage from 1 of his or her Benched Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const blocked = [];
        let hasPokemonWithDamage = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList === player.active) {
            return;
          }
          if (cardList.damage === 0) {
            blocked.push(target);
          } else {
            hasPokemonWithDamage = true;
          }
        });
        if (hasPokemonWithDamage === false) {
          throw new GameError(GameMessage.CANNOT_USE_STADIUM);
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_HEAL,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: true, blocked }
          ),
          (results) => {
            const targets = results || [];
            if (targets.length === 0) {
              return state;
            }
            targets.forEach((target) => {
              const owner = StateUtils.findOwner(state, target);
              if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, target)) {
                return;
              }
              const healEffect = new HealEffect(player, target, 20);
              store.reduceEffect(state, healEffect);
            });
          }
        );
      }
      return state;
    }
  };

