  var SkyarrowBridge = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "NXD";
      this.name = "Skyarrow Bridge";
      this.fullName = "Skyarrow Bridge NXD";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "91";
      this.text = "The Retreat Cost of each Basic Pok\xE9mon in play is [C] less.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const pokemonCard = player.active.getPokemonCard();
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, effect.player, effect.player.active)) {
          return state;
        }
        if (pokemonCard && pokemonCard.stage == 2 /* BASIC */) {
          const index = effect.cost.indexOf(9 /* COLORLESS */);
          if (index !== -1) {
            effect.cost.splice(index, 1);
          }
        }
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

