  var Darmanitan4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Darumaka";
      this.cardType = [P];
      this.hp = 110;
      this.weakness = [{ type: P }];
      this.retreat = [C, C, C];
      this.attacks = [{
        name: "Synchrodraw",
        cost: [P],
        damage: 0,
        text: "Shuffle your hand into your deck. Then, draw a number of cards equal to the number of cards in your opponent's hand."
      }, {
        name: "DarMAXitan",
        cost: [C, C],
        damage: 50,
        damageCalculation: "x",
        text: "Flip a coin for each Energy attached to this Pok\xE9mon. This attack does 50 damage times the number of heads."
      }];
      this.set = "NXD";
      this.setNumber = "60";
      this.cardImage = "assets/cardback.png";
      this.name = "Darmanitan";
      this.fullName = "Darmanitan NXD";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentHandSize = opponent.hand.cards.length;
        const cardsToShuffle = player.hand.cards.slice();
        MOVE_CARDS(store, state, player.hand, player.deck, { cards: cardsToShuffle, sourceCard: this });
        return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
          player.deck.applyOrder(order);
          if (opponentHandSize > 0) {
            DRAW_CARDS(store, state, player, opponentHandSize);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const energyCount = player.active.cards.filter((c) => c.superType === 3 /* ENERGY */).length;
        if (energyCount === 0) {
          effect.damage = 0;
          return state;
        }
        return MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, energyCount, (results) => {
          const heads = results.filter((r) => r).length;
          effect.damage = 50 * heads;
        });
      }
      return state;
    }
  };

