  var Jellicent2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Frillish";
      this.cardType = [W];
      this.hp = 120;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Vengeful Wish",
          cost: [C],
          damage: 0,
          text: "If this Pok\xE9mon was damaged by an attack during your opponent's last turn, this attack does the same amount of damage done to the Defending Pok\xE9mon."
        },
        {
          name: "Absorb Life",
          cost: [W, W, C],
          damage: 30,
          text: "Heal 30 damage from this Pok\xE9mon."
        }
      ];
      this.set = "NXD";
      this.setNumber = "35";
      this.cardImage = "assets/cardback.png";
      this.name = "Jellicent";
      this.fullName = "Jellicent NXD";
      this.DAMAGE_RECEIVED_MARKER = "DAMAGE_RECEIVED_MARKER";
      this.lastDamageReceived = 0;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (effect.damage > 0 && player !== targetPlayer && state.phase === 3 /* ATTACK */) {
          this.lastDamageReceived = effect.damage;
          targetPlayer.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.cards.includes(this)) {
              ADD_MARKER(this.DAMAGE_RECEIVED_MARKER, cardList, this);
            }
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.cards.includes(this) && HAS_MARKER(this.DAMAGE_RECEIVED_MARKER, cardList, this)) {
            if (this.lastDamageReceived > 0) {
              const putDamageEffect = new PutDamageEffect(effect, this.lastDamageReceived);
              putDamageEffect.target = opponent.active;
              store.reduceEffect(state, putDamageEffect);
            }
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        HEAL_X_DAMAGE_FROM_THIS_POKEMON(effect, store, state, 30);
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.cards.includes(this)) {
            REMOVE_MARKER(this.DAMAGE_RECEIVED_MARKER, cardList, this);
            this.lastDamageReceived = 0;
          }
        });
      }
      return state;
    }
  };

