  var Bisharp3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Pawniard";
      this.cardType = [M];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Energy Stream",
          cost: [C],
          damage: 20,
          text: "Attach a [M] Energy card from your discard pile to this Pok\xE9mon."
        },
        {
          name: "Metal Scissors",
          cost: [C, C, C],
          damage: 40,
          damageCalculation: "+",
          text: "Does 20 more damage for each [M] Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "NVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "82";
      this.name = "Bisharp";
      this.fullName = "Bisharp NVI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasMetalEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides && c.provides.includes(8 /* METAL */);
        });
        if (!hasMetalEnergyInDiscard) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_ACTIVE,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Metal Energy" },
          { allowCancel: false, min: 0, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length > 0) {
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        let metalEnergyCount = 0;
        player.active.cards.forEach((card) => {
          if (card.superType === 3 /* ENERGY */ && card.provides && card.provides.includes(8 /* METAL */)) {
            metalEnergyCount++;
          }
        });
        effect.damage += 20 * metalEnergyCount;
      }
      return state;
    }
  };

