  var Eelektrik2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Tynamo";
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 90;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Dynamotor",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may attach a L Energy card from your discard pile to 1 of your Benched Pokemon."
      }];
      this.attacks = [
        {
          name: "Electric Ball",
          cost: [4 /* LIGHTNING */, 4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 50,
          text: ""
        }
      ];
      this.set = "NVI";
      this.name = "Eelektrik";
      this.fullName = "Eelektrik NVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "40";
      this.DYNAMOTOR_MARKER = "DYNAMOTOR_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.DYNAMOTOR_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(4 /* LIGHTNING */);
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.DYNAMOTOR_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = ATTACH_X_TYPE_ENERGY_FROM_DISCARD_TO_1_OF_YOUR_POKEMON(
          store,
          state,
          player,
          1,
          4 /* LIGHTNING */,
          {
            destinationSlots: [2 /* BENCH */],
            energyFilter: { energyType: 0 /* BASIC */, name: "Lightning Energy" },
            min: 1,
            allowCancel: true,
            onAttached: (transfers) => {
              if (transfers.length > 0) {
                player.marker.addMarker(this.DYNAMOTOR_MARKER, this);
              }
            }
          }
        );
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.DYNAMOTOR_MARKER, this);
      }
      return state;
    }
  };

