  init_game();
  init_prefabs();
  var Karrablast2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 60;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.attacks = [{
        name: "Mysterious Evolution",
        cost: [C],
        damage: 0,
        text: "If Shelmet is in play, search your deck for a card that evolves from this Pok\xE9mon and put it onto this Pok\xE9mon. (This counts as evolving this Pok\xE9mon.) Shuffle your deck afterward."
      }, {
        name: "Fury Attack",
        cost: [C, C],
        damage: 10,
        damageCalculation: "x",
        text: "Flip 3 coins. This attack does 10 damage times the number of heads."
      }];
      this.set = "NVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "8";
      this.name = "Karrablast";
      this.fullName = "Karrablast NVI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let shelmetInPlay = false;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard()?.name === "Shelmet") {
              shelmetInPlay = true;
            }
          });
          p.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard()?.name === "Shelmet") {
              shelmetInPlay = true;
            }
          });
        });
        if (!shelmetInPlay || player.deck.cards.length === 0) {
          return state;
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || card.evolvesFrom !== "Karrablast") {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_EVOLVE,
          player.deck,
          { superType: 1 /* POKEMON */ },
          { min: 0, max: 1, allowCancel: true, blocked }
        ), (cards) => {
          if (cards && cards.length > 0) {
            const evolutionCard = cards[0];
            MOVE_CARDS(store, state, player.deck, player.active, { cards: [evolutionCard], sourceCard: this });
            player.active.clearEffects();
            player.active.pokemonPlayedTurn = state.turn;
          }
          SHUFFLE_DECK(store, state, player);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 3, (results) => {
          const heads = results.filter((r) => r).length;
          effect.damage = 10 * heads;
        });
      }
      return state;
    }
  };

