  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-noble-victories/plume-fossil.ts
  init_trainer_card();
  init_card_types();
  init_play_card_effects();
  init_card_list();
  init_choose_cards_prompt();
  init_game_error();
  init_game_message();
  init_shuffle_prompt();
  function* playCard77(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const max = Math.min(slots2.length, 1);
    const start = player.deck.cards.length < 7 ? 0 : player.deck.cards.length - 7;
    const end = player.deck.cards.length;
    const deckBottom = new CardList();
    deckBottom.cards = player.deck.cards.slice(start, end);
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
        deckBottom,
        { superType: 1 /* POKEMON */, name: "Archen" },
        { min: 0, max, allowCancel: true }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      store.reduceEffect(
        state,
        new PlayPokemonFromDeckEffect(player, card, slots2[index])
      );
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var PlumeFossil = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "NVI";
      this.name = "Plume Fossil";
      this.fullName = "Plume Fossil NVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "93";
      this.text = "Look at the bottom 7 cards of your deck. You may reveal an Archen you find there and put is onto your Bench. Shuffle the other cards back into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard77(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

