  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-noble-victories/shelmet.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Shelmet2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 60;
      this.weakness = [{ type: R }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Mysterious Evolution",
          cost: [C],
          damage: 0,
          text: "If Karrablast is in play, search your deck for a card that evolves from this Pok\xE9mon and put it onto this Pok\xE9mon. (This counts as evolving this Pok\xE9mon.) Shuffle your deck afterward."
        },
        {
          name: "Ram",
          cost: [G],
          damage: 10,
          text: ""
        }
      ];
      this.set = "NVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "11";
      this.name = "Shelmet";
      this.fullName = "Shelmet NVI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let karrablastInPlay = false;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard()?.name === "Karrablast") {
              karrablastInPlay = true;
            }
          });
          p.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard()?.name === "Karrablast") {
              karrablastInPlay = true;
            }
          });
        });
        if (!karrablastInPlay || player.deck.cards.length === 0) {
          return state;
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || card.evolvesFrom !== "Shelmet") {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_EVOLVE,
          player.deck,
          { superType: 1 /* POKEMON */ },
          { min: 0, max: 1, allowCancel: true, blocked }
        ), (cards) => {
          if (cards && cards.length > 0) {
            const evolutionCard = cards[0];
            MOVE_CARDS(store, state, player.deck, player.active, { cards: [evolutionCard], sourceCard: this });
            player.active.clearEffects();
            player.active.pokemonPlayedTurn = state.turn;
          }
          SHUFFLE_DECK(store, state, player);
        });
      }
      return state;
    }
  };

