  var Beheeyem2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Elgyem";
      this.cardType = [P];
      this.hp = 80;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Synchronoise",
          cost: [P],
          damage: 20,
          text: "Does 20 damage to each of your opponent's Benched Pok\xE9mon that shares a type with the Defending Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Psyshot",
          cost: [P, C],
          damage: 40,
          text: ""
        }
      ];
      this.set = "NVI";
      this.setNumber = "56";
      this.cardImage = "assets/cardback.png";
      this.name = "Beheeyem";
      this.fullName = "Beheeyem NVI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const defendingTypeEffect = new CheckPokemonTypeEffect(opponent.active);
        store.reduceEffect(state, defendingTypeEffect);
        const defendingTypes = defendingTypeEffect.cardTypes;
        opponent.bench.forEach((benchSlot) => {
          if (benchSlot.cards.length === 0) {
            return;
          }
          const benchTypeEffect = new CheckPokemonTypeEffect(benchSlot);
          store.reduceEffect(state, benchTypeEffect);
          const benchTypes = benchTypeEffect.cardTypes;
          const sharesType = benchTypes.some((type) => defendingTypes.includes(type));
          if (sharesType) {
            const damageEffect = new PutDamageEffect(effect, 20);
            damageEffect.target = benchSlot;
            store.reduceEffect(state, damageEffect);
          }
        });
      }
      return state;
    }
  };

