  var Litwick22 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 60;
      this.weakness = [{ type: D }];
      this.retreat = [C];
      this.attacks = [{
        name: "Astonish",
        cost: [P],
        damage: 10,
        text: "Choose 1 card from your opponent's hand without looking and shuffle it into your opponent's deck."
      }, {
        name: "Ambush",
        cost: [P, C],
        damage: 10,
        text: "Flip a coin. If heads, this attack does 20 more damage. If tails, switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
      }];
      this.set = "NVI";
      this.setNumber = "58";
      this.cardImage = "assets/cardback.png";
      this.name = "Litwick";
      this.fullName = "Litwick NVI 58";
      this.shouldSwitch = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.hand.cards.length > 0) {
          const randomIndex = Math.floor(Math.random() * opponent.hand.cards.length);
          const card = opponent.hand.cards[randomIndex];
          MOVE_CARDS(store, state, opponent.hand, opponent.deck, { cards: [card], sourceCard: this });
          return store.prompt(state, new ShuffleDeckPrompt(opponent.id), (order) => {
            opponent.deck.applyOrder(order);
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            effect.damage += 20;
          } else {
            this.shouldSwitch = true;
          }
        });
      }
      if (effect instanceof AfterAttackEffect && this.shouldSwitch) {
        this.shouldSwitch = false;
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (hasBenched) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
        }
      }
      if (effect instanceof EndTurnEffect && this.shouldSwitch) {
        this.shouldSwitch = false;
      }
      return state;
    }
  };

