  var Accelgor3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Team Plasma" /* TEAM_PLASMA */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Shelmet";
      this.cardType = [G];
      this.hp = 80;
      this.weakness = [{ type: R }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Retribution",
          cost: [C],
          damage: 20,
          text: "If an Escavalier you had in play was Knocked Out by damage from an opponent's attack during his or her last turn, put all Energy attached to the Defending Pok\xE9mon into your opponent's hand."
        },
        {
          name: "Signal Beam",
          cost: [G, C],
          damage: 30,
          text: "The Defending Pok\xE9mon is now Confused."
        }
      ];
      this.set = "PLB";
      this.setNumber = "8";
      this.cardImage = "assets/cardback.png";
      this.name = "Accelgor";
      this.fullName = "Accelgor PLB";
      this.ESCAVALIER_KO_MARKER = "ESCAVALIER_KO_MARKER";
      this.ESCAVALIER_DAMAGED_BY_OPPONENT_ATTACK_MARKER = "ESCAVALIER_DAMAGED_BY_OPPONENT_ATTACK_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.damage > 0) {
        const damagedCard = effect.target.getPokemonCard();
        if (damagedCard?.name === "Escavalier") {
          const owner = StateUtils.findOwner(state, effect.target);
          if (owner !== effect.player) {
            effect.target.marker.addMarker(this.ESCAVALIER_DAMAGED_BY_OPPONENT_ATTACK_MARKER, this);
          }
        }
      }
      if (effect instanceof KnockOutEffect) {
        const knockedOutCard = effect.target.getPokemonCard();
        if (knockedOutCard?.name === "Escavalier" && effect.target.marker.hasMarker(this.ESCAVALIER_DAMAGED_BY_OPPONENT_ATTACK_MARKER, this)) {
          const owner = StateUtils.findOwner(state, effect.target);
          owner.marker.addMarker(this.ESCAVALIER_KO_MARKER, this);
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.marker.hasMarker(this.ESCAVALIER_KO_MARKER, this)) {
          const energyCards = opponent.active.cards.filter((c) => c.superType === 3 /* ENERGY */);
          energyCards.forEach((card) => {
            MOVE_CARDS(store, state, opponent.active, opponent.hand, { cards: [card], sourceCard: this });
          });
        }
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.ESCAVALIER_KO_MARKER, this);
        state.players.forEach((player) => {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            cardList.marker.removeMarker(this.ESCAVALIER_DAMAGED_BY_OPPONENT_ATTACK_MARKER, this);
          });
        });
      }
      return state;
    }
  };

