  init_attack_effects();
  init_prefabs();
  var Drifblim2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Drifloon";
      this.cardType = [P];
      this.hp = 100;
      this.weakness = [{ type: D }];
      this.retreat = [];
      this.powers = [
        {
          name: "Drifting Balloon",
          powerType: 2 /* ABILITY */,
          text: "This Pok\xE9mon's attacks cost [C] less for each of your opponent's Team Plasma Pok\xE9mon in play."
        }
      ];
      this.attacks = [
        {
          name: "Derail",
          cost: [C, C, C],
          damage: 70,
          text: "Discard a Special Energy attached to the Defending Pok\xE9mon."
        }
      ];
      this.set = "PLB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "35";
      this.name = "Drifblim";
      this.fullName = "Drifblim PLB";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect && (effect.attack === this.attacks[0] || this.tools.some((tool) => tool.attacks && tool.attacks.includes(effect.attack)))) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const countSpecialPokemon = (player2) => {
          const specialTags = ["Team Plasma" /* TEAM_PLASMA */];
          let count = 0;
          const activePokemon = player2.active.getPokemonCard();
          if (activePokemon && specialTags.some((tag) => activePokemon.hasTag(tag))) {
            count++;
          }
          player2.bench.forEach((slot) => {
            const benchPokemon = slot.getPokemonCard();
            if (benchPokemon && specialTags.some((tag) => benchPokemon.hasTag(tag))) {
              count++;
            }
          });
          return count;
        };
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const specialPokemonCount = countSpecialPokemon(opponent);
        const colorlessToRemove = Math.min(specialPokemonCount, 3);
        for (let i = 0; i < colorlessToRemove; i++) {
          const index = effect.cost.indexOf(9 /* COLORLESS */);
          if (index !== -1) {
            effect.cost.splice(index, 1);
          }
        }
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const activeCardList = opponent.active;
        const activePokemonCard = activeCardList.getPokemonCard();
        let hasPokemonWithEnergy = false;
        if (activePokemonCard && activeCardList.energies.cards.some(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 1 /* SPECIAL */
        )) {
          hasPokemonWithEnergy = true;
        }
        if (!hasPokemonWithEnergy) {
          return state;
        }
        let cards = [];
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.active,
            { superType: 3 /* ENERGY */, energyType: 1 /* SPECIAL */ },
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            cards = selected || [];
          }
        );
        const discardEnergy2 = new DiscardCardsEffect(effect, cards);
        return store.reduceEffect(state, discardEnergy2);
      }
      return state;
    }
  };

