  var PalkiaEX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["EX" /* POKEMON_EX */, "Team Plasma" /* TEAM_PLASMA */];
      this.cardType = [N];
      this.hp = 180;
      this.weakness = [{ type: N }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Strafe",
          cost: [C, C, C],
          damage: 50,
          text: "You may switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Dimension Heal",
          cost: [G, W, C, C],
          damage: 80,
          text: "Heal from this Pok\xE9mon 20 damage for each Plasma Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "PLB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "66";
      this.name = "Palkia-EX";
      this.fullName = "Palkia EX PLB";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (hasBenched) {
          CONFIRMATION_PROMPT(store, state, player, (result) => {
            if (result) {
              SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
            }
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const pokemon = player.active;
        const checkEnergy = new CheckProvidedEnergyEffect(player, pokemon);
        store.reduceEffect(state, checkEnergy);
        let totalPlasmaEnergy = 0;
        checkEnergy.energyMap.forEach((em) => {
          const energyCard = em.card;
          if (energyCard.superType === 3 /* ENERGY */ && energyCard.name === "Plasma Energy") {
            totalPlasmaEnergy += 1;
          }
        });
        const healEffect = new HealEffect(player, player.active, 20 * totalPlasmaEnergy);
        store.reduceEffect(state, healEffect);
      }
      return state;
    }
  };

