  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-plasma-blast/porygon-z.ts
  var PorygonZ2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Team Plasma" /* TEAM_PLASMA */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Porygon2";
      this.cardType = [C];
      this.hp = 130;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Plasma Transfer",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "As often as you like during your turn (before your attack), you may move a Plasma Energy attached to 1 of your Pok\xE9mon to another of your Pok\xE9mon."
        }
      ];
      this.attacks = [{
        name: "Tri Attack",
        cost: [C, C, C],
        damage: 50,
        damageCalculation: "x",
        text: "Flip 3 coins. This attack does 50 damage times the number of heads."
      }];
      this.set = "PLB";
      this.setNumber = "74";
      this.cardImage = "assets/cardback.png";
      this.name = "Porygon-Z";
      this.fullName = "Porygon-Z PLB";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const blocked = [];
          cardList.cards.forEach((c, index) => {
            if (!(c instanceof PlasmaEnergy)) {
              blocked.push(index);
            }
          });
          if (blocked.length !== cardList.cards.length) {
            blockedMap.push({ source: target, blocked });
          }
        });
        return store.prompt(
          state,
          new MoveEnergyPrompt(
            effect.player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            {},
            { allowCancel: true, blockedMap }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              if (transfer.from.player === transfer.to.player && transfer.from.slot === transfer.to.slot && transfer.from.index === transfer.to.index) {
                continue;
              }
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          const heads = results.filter((r) => r).length;
          effect.damage = 50 * heads;
        });
      }
      return state;
    }
  };

