  init_choose_cards_prompt();
  init_show_cards_prompt();
  var Relicanth3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Team Plasma" /* TEAM_PLASMA */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Fossil Hunt",
          cost: [C],
          damage: 0,
          text: "Put 2 Item cards that have Fossil in their names from your discard pile into your hand."
        },
        {
          name: "Water Gun",
          cost: [W, C],
          damage: 30,
          text: ""
        }
      ];
      this.set = "PLB";
      this.setNumber = "24";
      this.cardImage = "assets/cardback.png";
      this.name = "Relicanth";
      this.fullName = "Relicanth PLB";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const fossilItems = player.discard.cards.filter(
          (c) => c instanceof TrainerCard && c.trainerType === 0 /* ITEM */ && c.name.includes("Fossil")
        );
        if (fossilItems.length === 0) {
          return state;
        }
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          if (!(c instanceof TrainerCard) || c.trainerType !== 0 /* ITEM */ || !c.name.includes("Fossil")) {
            blocked.push(index);
          }
        });
        const max = Math.min(2, fossilItems.length);
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.discard,
            {},
            { min: max, max, allowCancel: false, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            cards.forEach((card) => {
              MOVE_CARDS(store, state, player.discard, player.hand, { cards: [card], sourceCard: this });
            });
            if (cards.length > 0) {
              store.prompt(
                state,
                new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
                () => {
                }
              );
            }
          }
        );
      }
      return state;
    }
  };

