  init_game();
  init_prefabs();
  init_confirm_prompt();
  var Salamence4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Shelgon";
      this.cardType = [N];
      this.hp = 150;
      this.weakness = [{ type: N }];
      this.retreat = [C, C, C, C];
      this.powers = [{
        name: "Breakwing",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon, you may discard all Pok\xE9mon Tool cards attached to each of your opponent's Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Gaia Crush",
          cost: [R, W, C, C],
          damage: 100,
          text: "Discard any Stadium card in play."
        }
      ];
      this.set = "PLB";
      this.setNumber = "64";
      this.cardImage = "assets/cardback.png";
      this.name = "Salamence";
      this.fullName = "Salamence PLB";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, player);
        let hasTools = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          if (cardList.tools.length > 0) {
            hasTools = true;
          }
        });
        if (!hasTools) {
          return state;
        }
        store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (result) => {
          if (!result) {
            return;
          }
          opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
            const tools = cardList.tools.slice();
            tools.forEach((tool) => {
              MOVE_CARDS(store, state, cardList, opponent.discard, { cards: [tool], sourceCard: this });
            });
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_A_STADIUM_CARD_IN_PLAY(state);
      }
      return state;
    }
  };

