      this.name = "Iris";
      this.fullName = "Iris PLB";
      this.text = "During this turn, your Pok\xE9mon's attacks do 10 more damage to the Active Pok\xE9mon for each Prize card your opponent has taken (before applying Weakness and Resistance). You may play only 1 Supporter card during your turn (before your attack).";
