  function* playCard81(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const max = Math.min(slots2.length, 1);
    const start = player.deck.cards.length < 7 ? 0 : player.deck.cards.length - 7;
    const end = player.deck.cards.length;
    const deckBottom = new CardList();
    deckBottom.cards = player.deck.cards.slice(start, end);
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
        deckBottom,
        { superType: 1 /* POKEMON */, name: "Lileep" },
        { min: 0, max, allowCancel: true }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      store.reduceEffect(
        state,
        new PlayPokemonFromDeckEffect(player, card, slots2[index])
      );
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
