  var ScoopUpCyclone = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this._tags = ["Ace Spec" /* ACE_SPEC */];
      this.regulationMark = "H";
      this.set = "TWM";
      this.name = "Scoop Up Cyclone";
      this.fullName = "Scoop Up Cyclone TWM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "162";
      this.text = "Put 1 of your Pok\xE9mon and all cards attached to it into your hand.";
    }
    canPlay(store, state, player) {
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        effect.preventDefault = true;
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_PICK_UP,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { allowCancel: false }
          ),
          (result) => {
            const cardList = result.length > 0 ? result[0] : null;
            if (cardList !== null) {
              MOVE_POKEMON_OFF_BOARD(store, state, cardList, {
                pokemonDestination: player.hand,
                sourceCard: this
              });
            }
          }
        );
      }
      return state;
    }
  };

