  init_order_cards_prompt();
  init_prefabs();
  var Beldum4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 60;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Calculate",
          cost: [C],
          damage: 0,
          text: "Look at the top 4 cards of your deck and put them back on top of your deck in any order."
        },
        {
          name: "Psypunch",
          cost: [P, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "PLF";
      this.setNumber = "50";
      this.cardImage = "assets/cardback.png";
      this.name = "Beldum";
      this.fullName = "Beldum PLF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const count = Math.min(4, player.deck.cards.length);
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count, sourceCard: this });
        return store.prompt(state, new OrderCardsPrompt(
          player.id,
          GameMessage.CHOOSE_CARDS_ORDER,
          deckTop,
          { allowCancel: false }
        ), (order) => {
          if (order === null) {
            return state;
          }
          deckTop.applyOrder(order);
          deckTop.moveToTopOfDestination(player.deck);
        });
      }
      return state;
    }
  };

