  init_play_card_effects();
  init_game_phase_effects();
  init_prefabs();
  var Electrode5 = class _Electrode extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Voltorb";
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 90;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Magnetic Draw",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may draw cards until you have 4 cards in your hand. "
      }];
      this.attacks = [{
        name: "Electro Ball",
        cost: [4 /* LIGHTNING */, 9 /* COLORLESS */, 9 /* COLORLESS */],
        damage: 60,
        text: ""
      }];
      this.set = "PLF";
      this.setNumber = "33";
      this.cardImage = "assets/cardback.png";
      this.name = "Electrode";
      this.fullName = "Electrode PLF";
      this.MAGNETIC_DRAW_MARKER = "MAGNETIC_DRAW_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.MAGNETIC_DRAW_MARKER, this);
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.marker.removeMarker(this.MAGNETIC_DRAW_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.MAGNETIC_DRAW_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        while (player.hand.cards.length < 4) {
          if (player.deck.cards.length === 0) {
            break;
          }
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
        }
        player.marker.addMarker(this.MAGNETIC_DRAW_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.forEachPokemon(2 /* BOTTOM_PLAYER */, (player) => {
          if (player instanceof _Electrode) {
            player.marker.removeMarker(this.MAGNETIC_DRAW_MARKER);
          }
        });
      }
      return state;
    }
  };

