  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-plasma-freeze/kecleon.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_game_effects();
  init_copy_attack_prefabs();
  init_prefabs();
  var Kecleon3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 70;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [{
        name: "Color Change",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is your Active Pok\xE9mon, this Pok\xE9mon is the same type as the your opponent's Active Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Imittack",
          cost: [C],
          damage: 0,
          copycatAttack: true,
          text: "Choose 1 of the Defending Pok\xE9mon's attacks. If this Pok\xE9mon has the necessary Energy to use that attack, use it as this attack."
        }
      ];
      this.set = "PLF";
      this.setNumber = "94";
      this.cardImage = "assets/cardback.png";
      this.name = "Kecleon";
      this.fullName = "Kecleon PLF";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonTypeEffect && effect.target.getPokemonCard() === this) {
        let owner = null;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList === effect.target) {
              owner = p;
            }
          });
        });
        if (!owner) {
          return state;
        }
        if (owner.active !== effect.target) {
          return state;
        }
        try {
          const stub = new PowerEffect(owner, {
            name: "test",
            powerType: 2 /* ABILITY */,
            text: ""
          }, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, owner);
        const opponentCard = opponent.active.getPokemonCard();
        if (opponentCard) {
          const opponentTypeCheck = new CheckPokemonTypeEffect(opponent.active);
          store.reduceEffect(state, opponentTypeCheck);
          effect.cardTypes = [...opponentTypeCheck.cardTypes];
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentCard = opponent.active.getPokemonCard();
        if (!opponentCard || opponentCard.attacks.length === 0) {
          return state;
        }
        const { pokemonCards, blocked } = buildAttackListWithEnergyBlocking(state, store, player, {
          extraCards: [opponentCard]
        });
        if (pokemonCards.length === 0) {
          return state;
        }
        const allBlocked = opponentCard.attacks.every(
          (attack3) => blocked.some((b) => b.index === 0 && b.attack === attack3.name)
        );
        if (allBlocked) {
          return state;
        }
        return COPY_ATTACK_FROM_POKEMON_LIST(store, state, effect, pokemonCards, {
          allowCancel: false,
          blocked
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-plasma-freeze/kingdra.ts
  init_pokemon_card();
