  var MrMime5 = class _MrMime extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 70;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Bench Barrier",
        powerType: 2 /* ABILITY */,
        text: "Prevent all damage done to your Benched Pokemon by attacks."
      }];
      this.attacks = [{
        name: "Psy Bolt",
        cost: [P, C],
        damage: 20,
        text: "Flip a coin. If heads, the Defending Pokemon is now Paralyzed."
      }];
      this.set = "PLF";
      this.name = "Mr. Mime";
      this.fullName = "Mr. Mime PLF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "47";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === true) {
            const specialConditionEffect = new AddSpecialConditionsEffect(effect, [0 /* PARALYZED */]);
            store.reduceEffect(state, specialConditionEffect);
          }
        });
      }
      if (effect instanceof PutDamageEffect) {
        const defendingPlayer = StateUtils.findOwner(state, effect.target);
        const attackingPlayer = StateUtils.findOwner(state, effect.source);
        if (attackingPlayer === defendingPlayer) {
          return state;
        }
        if (effect.target === defendingPlayer.active) {
          return state;
        }
        let isManaphyInPlay = false;
        defendingPlayer.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card instanceof _MrMime) {
            isManaphyInPlay = true;
          }
        });
        if (!isManaphyInPlay) {
          return state;
        }
        try {
          const stub = new PowerEffect(defendingPlayer, {
            name: "test",
            powerType: 2 /* ABILITY */,
            text: ""
          }, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        effect.preventDefault = true;
      }
      return state;
    }
  };

