  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects();
  var Weavile3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Team Plasma" /* TEAM_PLASMA */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Sneasel";
      this.cardType = [D];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Hail",
          cost: [C],
          damage: 0,
          text: "This attack does 10 damage to each of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Vilify",
          cost: [D, C],
          damage: 30,
          damageCalculation: "x",
          text: "Discard as many Pok\xE9mon as you like from your hand. This attack does 30 damage times the number of Pok\xE9mon you discarded."
        }
      ];
      this.set = "PLF";
      this.setNumber = "66";
      this.cardImage = "assets/cardback.png";
      this.name = "Weavile";
      this.fullName = "Weavile PLF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        const benched = opponent.bench.filter((b) => b.cards.length > 0);
        const activeDamageEffect = new DealDamageEffect(effect, 20);
        store.reduceEffect(state, activeDamageEffect);
        benched.forEach((target) => {
          const damageEffect = new PutDamageEffect(effect, 20);
          damageEffect.target = target;
          store.reduceEffect(state, damageEffect);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const pokemonInHand = player.hand.cards.filter(
          (c) => c.superType === 1 /* POKEMON */
        ).length;
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            { superType: 1 /* POKEMON */ },
            { min: 0, max: pokemonInHand, allowCancel: true }
          ),
          (transfers) => {
            if (!transfers || transfers.length === 0) {
              return state;
            }
            effect.damage = transfers.length * 30;
            for (const transfer of transfers) {
              MOVE_CARDS(store, state, player.hand, player.discard, { cards: [transfer] });
            }
            return state;
          }
        );
      }
      return state;
    }
  };

