  var Amoonguss3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Team Plasma" /* TEAM_PLASMA */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Foongus";
      this.cardType = [G];
      this.hp = 90;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Astonish",
        cost: [C],
        damage: 0,
        text: "Flip a coin. If heads, choose a random card from your opponent's hand. Your opponent reveals that card and shuffles it into his or her deck."
      }, {
        name: "Miracle Powder",
        cost: [G, C],
        damage: 30,
        text: "Flip a coin. If heads, choose a Special Condition. The Defending Pok\xE9mon is now affected by that Special Condition."
      }];
      this.set = "PLS";
      this.setNumber = "13";
      this.cardImage = "assets/cardback.png";
      this.name = "Amoonguss";
      this.fullName = "Amoonguss PLS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result && opponent.hand.cards.length > 0) {
            const randomIndex = Math.floor(Math.random() * opponent.hand.cards.length);
            const cardToShuffle = opponent.hand.cards[randomIndex];
            MOVE_CARDS(store, state, opponent.hand, opponent.deck, { cards: [cardToShuffle], sourceCard: this });
            SHUFFLE_DECK(store, state, opponent);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            store.prompt(
              state,
              new SelectOptionPrompt(
                player.id,
                GameMessage.CHOOSE_OPTION,
                ["Paralyzed", "Confused", "Asleep", "Poisoned", "Burned"],
                { allowCancel: false, defaultValue: 0 }
              ),
              (choice) => {
                const conditionMap = [
                  0 /* PARALYZED */,
                  1 /* CONFUSED */,
                  2 /* ASLEEP */,
                  3 /* POISONED */,
                  4 /* BURNED */
                ];
                const selectedCondition = conditionMap[choice ?? 0];
                const specialConditionEffect = new AddSpecialConditionsEffect(effect, [
                  selectedCondition
                ]);
                store.reduceEffect(state, specialConditionEffect);
              }
            );
          }
        });
      }
      return state;
    }
  };

