  var ArticunoEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["EX" /* POKEMON_EX */, "Team Plasma" /* TEAM_PLASMA */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 170;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Blizzard",
          cost: [W, C, C],
          damage: 60,
          text: "Does 10 damage to each of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Frost Prison",
          cost: [W, W, C, C],
          damage: 80,
          text: "If this Pok\xE9mon has any Plasma Energy attached to it, the Defending Pok\xE9mon is now Paralyzed."
        }
      ];
      this.set = "PLS";
      this.setNumber = "25";
      this.cardImage = "assets/cardback.png";
      this.name = "Articuno-EX";
      this.fullName = "Articuno-EX PLS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        opponent.bench.forEach((benched) => {
          if (benched.cards.length > 0) {
            const damage = new PutDamageEffect(effect, 10);
            damage.target = benched;
            store.reduceEffect(state, damage);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        const hasPlasmaEnergy = checkEnergy.energyMap.some(
          (em) => em.card.superType === 3 /* ENERGY */ && em.card.name === "Plasma Energy"
        );
        if (hasPlasmaEnergy) {
          YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_PARALYZED(store, state, effect);
        }
      }
      return state;
    }
  };

