  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/06-black-and-white/set-plasma-storm/beheeyem.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_prefabs();
  init_move_damage_prompt();
  var Beheeyem3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Team Plasma" /* TEAM_PLASMA */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Elgyem";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Lock Up",
          cost: [P],
          damage: 20,
          text: "The Defending Pok\xE9mon can't retreat during your opponent's next turn."
        },
        {
          name: "Damakinesis",
          cost: [P, C, C],
          damage: 0,
          text: "Move 6 damage counters from any of your Pok\xE9mon to the Defending Pok\xE9mon."
        }
      ];
      this.set = "PLS";
      this.setNumber = "70";
      this.cardImage = "assets/cardback.png";
      this.name = "Beheeyem";
      this.fullName = "Beheeyem PLS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        BLOCK_RETREAT(store, state, effect, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let totalDamageCounters = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          totalDamageCounters += Math.floor(cardList.damage / 10);
        });
        const countersToMove = Math.min(6, totalDamageCounters);
        if (countersToMove === 0) {
          return state;
        }
        const blockedFrom = [];
        const blockedTo = [];
        let opponentActiveTarget;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          blockedTo.push(target);
          if (cardList.damage < 10) {
            blockedFrom.push(target);
          }
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          blockedFrom.push(target);
          if (cardList === opponent.active) {
            opponentActiveTarget = target;
          } else {
            blockedTo.push(target);
          }
        });
        if (opponentActiveTarget === void 0) {
          return state;
        }
        const maxAllowedDamage = [
          { target: opponentActiveTarget, damage: countersToMove * 10 }
        ];
        return store.prompt(
          state,
          new MoveDamagePrompt(
            player.id,
            GameMessage.MOVE_DAMAGE,
            0 /* ANY */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            maxAllowedDamage,
            {
              min: countersToMove,
              max: countersToMove,
              allowCancel: false,
              blockedFrom,
              blockedTo,
              singleDestinationTarget: true
            }
          ),
          (transfers) => {
            if (!transfers) {
              return;
            }
            let totalMoved = 0;
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              if (source.damage >= 10) {
                source.damage -= 10;
                totalMoved += 1;
              }
            }
            if (totalMoved > 0) {
              const countersEffect = new PutCountersEffect(effect, totalMoved * 10);
              countersEffect.target = opponent.active;
              store.reduceEffect(state, countersEffect);
            }
          }
        );
      }
      return state;
    }
  };

