  var Cherrim = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Cherubi";
      this.cardType = [G];
      this.hp = 70;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: W, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Fair-Weather Heal",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may heal 20 damage from 1 of your Pok\xE9mon that has any [G] Energy attached to it."
      }];
      this.attacks = [{
        name: "Random Peck",
        cost: [G, C],
        damage: 20,
        damageCalculation: "+",
        text: "Flip 2 coins. This attack does 20 more damage for each heads."
      }];
      this.set = "PLS";
      this.setNumber = "7";
      this.cardImage = "assets/cardback.png";
      this.name = "Cherrim";
      this.fullName = "Cherrim PLS";
      this.FAIR_WEATHER_HEAL_MARKER = "FAIR_WEATHER_HEAL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        let hasTarget = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkEnergy);
          const hasGrassEnergy = StateUtils.checkEnoughEnergy(checkEnergy.energyMap, [1 /* GRASS */]);
          if (cardList.damage === 0 || !hasGrassEnergy) {
            blocked.push(target);
          } else {
            hasTarget = true;
          }
        });
        if (!hasTarget) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.FAIR_WEATHER_HEAL_MARKER, this);
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_HEAL,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false, blocked }
        ), (targets) => {
          if (targets && targets.length > 0) {
            const healEffect = new HealEffect(player, targets[0], 20);
            store.reduceEffect(state, healEffect);
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.FAIR_WEATHER_HEAL_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 2, (results) => {
          const heads = results.filter((r) => r).length;
          effect.damage += 20 * heads;
        });
      }
      return state;
    }
  };

