  init_game();
  init_game_message();
  init_check_effects();
  init_prefabs();
  var Gallade3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Kirlia";
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 140;
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Powerful Storm",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 20,
          text: "Does 20 damage times the amount of Energy attached to all of your Pokemon."
        },
        {
          name: "Swift Lunge",
          cost: [5 /* PSYCHIC */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 80,
          text: "Your opponent switches the Defending Pokemon with 1 of his or her Benched Pokemon."
        }
      ];
      this.set = "PLS";
      this.name = "Gallade";
      this.fullName = "Gallade PLS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "61";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let energies = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergyEffect);
          checkProvidedEnergyEffect.energyMap.forEach((energy2) => {
            energies += energy2.provides.length;
          });
        });
        effect.damage = 20 * energies;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentHasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!opponentHasBenched) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          opponent.id,
          GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            return state;
          }
          const target = selected[0];
          opponent.switchPokemon(target);
        });
      }
      return state;
    }
  };

