  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var Lucario22 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Riolu";
      this.cardType = [F];
      this.hp = 100;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Dual Armor",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon has any [M] Energy attached to it, this Pok\xE9mon's type is both Fighting and Metal."
      }];
      this.attacks = [
        {
          name: "Hurricane Kick",
          cost: [F, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "Does 30 more damage for each Prize card your opponent has taken."
        }
      ];
      this.set = "PLS";
      this.setNumber = "78";
      this.cardImage = "assets/cardback.png";
      this.name = "Lucario";
      this.fullName = "Lucario PLS 78";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonTypeEffect && effect.target.getPokemonCard() === this) {
        let owner = null;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList === effect.target) {
              owner = p;
            }
          });
        });
        if (!owner) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, owner, this)) {
          return state;
        }
        const checkEnergy = new CheckProvidedEnergyEffect(owner, effect.target);
        store.reduceEffect(state, checkEnergy);
        const hasMetalEnergy = checkEnergy.energyMap.some(
          (em) => em.provides.includes(8 /* METAL */)
        );
        if (hasMetalEnergy) {
          if (!effect.cardTypes.includes(8 /* METAL */)) {
            effect.cardTypes.push(8 /* METAL */);
          }
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        const prizesTaken = 6 - opponent.getPrizeLeft();
        effect.damage += 30 * prizesTaken;
      }
      return state;
    }
  };

