  init_game();
  init_play_card_effects();
  init_game_phase_effects();
  init_prefabs();
  var Magnezone2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Team Plasma" /* TEAM_PLASMA */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Magneton";
      this.cardType = [L];
      this.hp = 140;
      this.weakness = [{ type: F }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Dual Brains",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "During your turn, you may play 2 Supporter cards."
        }
      ];
      this.attacks = [
        {
          name: "Gyro Ball",
          cost: [L, L, C],
          damage: 80,
          text: "Switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon. Then, your opponent switches the Defending Pok\xE9mon with 1 of his or her Benched Pok\xE9mon."
        }
      ];
      this.set = "PLS";
      this.setNumber = "46";
      this.cardImage = "assets/cardback.png";
      this.name = "Magnezone";
      this.fullName = "Magnezone PLS";
      this.usedGyroBall = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard.trainerType === 1 /* SUPPORTER */) {
        const player = effect.player;
        let inPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            inPlay = true;
          }
        });
        if (!inPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (player.supporterTurn === 0) {
          player.supporterTurn = -1;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedGyroBall = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedGyroBall) {
        this.usedGyroBall = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
        }
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedGyroBall = false;
      }
      return state;
    }
  };

