  init_game();
  init_trainer_card();
  init_choose_cards_prompt();
  init_prefabs();
  var Rotom3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Team Plasma" /* TEAM_PLASMA */];
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 60;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Electribonus",
          cost: [C],
          damage: 0,
          text: "Discard a [L] Energy card from your hand. If you do, draw 3 cards."
        },
        {
          name: "Poltergeist",
          cost: [L, C],
          damage: 20,
          damageCalculation: "x",
          text: "Your opponent reveals his or her hand. This attack does 20 damage times the number of Trainer cards in your opponent's hand."
        }
      ];
      this.set = "PLS";
      this.setNumber = "49";
      this.cardImage = "assets/cardback.png";
      this.name = "Rotom";
      this.fullName = "Rotom PLS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const lightningEnergyInHand = player.hand.cards.filter(
          (card) => card.superType === 3 /* ENERGY */ && card.provides.includes(4 /* LIGHTNING */)
        );
        if (lightningEnergyInHand.length === 0) {
          return state;
        }
        const blocked = [];
        player.hand.cards.forEach((c, index) => {
          if (c.superType !== 3 /* ENERGY */ || !c.provides.includes(4 /* LIGHTNING */)) {
            blocked.push(index);
          }
        });
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
              DRAW_CARDS(store, state, player, 3);
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        SHOW_CARDS_TO_PLAYER(store, state, player, opponent.hand.cards);
        const trainerCount = opponent.hand.cards.filter((card) => card instanceof TrainerCard).length;
        effect.damage = 20 * trainerCount;
      }
      return state;
    }
  };

