      this.evolvesFrom = "Carvanha";
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: L }];
      this.retreat = [];
      this.powers = [
        {
          name: "Rough Skin",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "If this Pok\xE9mon is your Active Pok\xE9mon and is damaged by an opponent's attack (even if this Pok\xE9mon is Knocked Out), put 2 damage counters on the Attacking Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Hard Bite",
          cost: [W, C],
          damage: 40,
          damageCalculation: "+",
          text: "Flip a coin. If heads, this attack does 20 more damage."
        }
      ];
