  var Trubbish3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 60;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [{
        name: "Pile Up",
        cost: [P],
        damage: 0,
        text: "Flip a coin. If heads, search your deck for a Pok\xE9mon Tool card, reveal it, and put it into your hand. Shuffle your deck afterward."
      }, {
        name: "Sludge Toss",
        cost: [C, C],
        damage: 20,
        text: ""
      }];
      this.set = "PLS";
      this.setNumber = "63";
      this.cardImage = "assets/cardback.png";
      this.name = "Trubbish";
      this.fullName = "Trubbish PLS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            const toolCards = player.deck.cards.filter(
              (c) => c instanceof PokemonCard === false && c.trainerType === 3 /* TOOL */
            );
            if (toolCards.length === 0) {
              SHUFFLE_DECK(store, state, player);
              return;
            }
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_HAND,
              player.deck,
              { superType: 2 /* TRAINER */, trainerType: 3 /* TOOL */ },
              { min: 1, max: 1, allowCancel: true }
            ), (selected) => {
              selected = selected || [];
              if (selected.length > 0) {
                const opponent = StateUtils.getOpponent(state, player);
                MOVE_CARDS(store, state, player.deck, player.hand, { cards: selected, sourceCard: this });
                SHOW_CARDS_TO_PLAYER(store, state, opponent, selected);
              }
              SHUFFLE_DECK(store, state, player);
            });
          }
        });
      }
      return state;
    }
  };

