  var Vanilluxe4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Vanillish";
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Enefountain",
          cost: [C],
          damage: 30,
          text: "Attach 2 basic Energy cards from your hand to 1 of your Pok\xE9mon."
        },
        {
          name: "Blizzard",
          cost: [W, W, C],
          damage: 70,
          text: "Does 10 damage to each of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "PLS";
      this.setNumber = "37";
      this.cardImage = "assets/cardback.png";
      this.name = "Vanilluxe";
      this.fullName = "Vanilluxe PLS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const basicEnergyCount = player.hand.cards.filter(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
        ).length;
        if (basicEnergyCount === 0) {
          return state;
        }
        const count = Math.min(2, basicEnergyCount);
        return ATTACH_ENERGY_PROMPT(
          store,
          state,
          player,
          2 /* BOTTOM_PLAYER */,
          3 /* HAND */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { min: count, max: count, allowCancel: false, sameTarget: true }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        opponent.bench.forEach((benched) => {
          if (benched.cards.length > 0) {
            const damage = new PutDamageEffect(effect, 10);
            damage.target = benched;
            store.reduceEffect(state, damage);
          }
        });
      }
      return state;
    }
  };

