  function* playCard83(next, store, state, self, effect) {
    const player = effect.player;
    let cards = [];
    cards = player.hand.cards.filter((c) => c !== self);
    if (cards.length < 2) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let trainersInDiscard = 0;
    player.discard.cards.forEach((c) => {
      if (c instanceof TrainerCard) {
        trainersInDiscard += 1;
      }
    });
    if (trainersInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: self });
    effect.preventDefault = true;
    const handTemp = new CardList();
    handTemp.cards = player.hand.cards.filter((c) => c !== self);
    cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        handTemp,
        {},
        { min: 2, max: 2, allowCancel: true }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    let recovered = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.discard,
        { superType: 2 /* TRAINER */ },
        { min: 1, max: 1, allowCancel: true }
      ),
      (selected) => {
        recovered = selected || [];
        next();
      }
    );
    if (recovered.length === 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.hand, player.discard, { cards: [self], sourceCard: self });
    MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: self });
    MOVE_CARDS(store, state, player.discard, player.hand, { cards: recovered, sourceCard: self });
    return state;
  }
