  var TeamPlasmaGrunt = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this._tags = ["Team Plasma" /* TEAM_PLASMA */];
      this.set = "PLS";
      this.setNumber = "125";
      this.cardImage = "assets/cardback.png";
      this.name = "Team Plasma Grunt";
      this.fullName = "Team Plasma Grunt PLS";
      this.text = "Discard a Team Plasma card from your hand. (If you can't discard a Team Plasma card, you can't play this card.) Draw 4 cards.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const plasmaCards = player.hand.cards.filter(
          (c) => c !== this && c.hasTag("Team Plasma" /* TEAM_PLASMA */)
        );
        if (plasmaCards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        const blocked = [];
        player.hand.cards.forEach((c, index) => {
          if (!c.hasTag("Team Plasma" /* TEAM_PLASMA */)) {
            blocked.push(index);
          }
        });
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            {},
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (selected) => {
            selected = selected || [];
            if (selected.length > 0) {
              MOVE_CARDS(store, state, player.hand, player.discard, { cards: selected, sourceCard: this });
              DRAW_CARDS(store, state, player, 4);
            }
            MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [this], sourceCard: this });
          }
        );
      }
      return state;
    }
  };

