  var VictoryPiece = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this._tags = ["Ace Spec" /* ACE_SPEC */];
      this.set = "PLS";
      this.setNumber = "130";
      this.cardImage = "assets/cardback.png";
      this.name = "Victory Piece";
      this.fullName = "Victory Piece PLS";
      this.text = "If this card is attached to Victini-EX, Victini-EX can use its attacks regardless of the amount or type of Energy attached to it. You can't have more than 1 ACE SPEC card in your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect) {
        const cardList = StateUtils.findCardList(state, this);
        if (!(cardList instanceof PokemonCardList)) {
          return state;
        }
        const pokemonCard = cardList.getPokemonCard();
        if (!pokemonCard || pokemonCard.name !== "Victini-EX") {
          return state;
        }
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        if (effect.player.active === cardList) {
          effect.cost = [];
        }
      }
      return state;
    }
  };

