  var Barbaracle = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Binacle";
      this.cardType = [F];
      this.hp = 110;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Rock Rush",
          cost: [F, F],
          damage: 30,
          damageCalculation: "x",
          text: "Discard as many [F] Energy cards as you like from your hand. This attack does 30 damage times the number of Energy cards you discarded."
        },
        {
          name: "Boulder Crush",
          cost: [F, F, F],
          damage: 80,
          text: ""
        }
      ];
      this.set = "FLF";
      this.setNumber = "49";
      this.cardImage = "assets/cardback.png";
      this.name = "Barbaracle";
      this.fullName = "Barbaracle FLF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const fightingEnergyInHand = player.hand.cards.filter(
          (c) => c instanceof EnergyCard && c.provides.includes(6 /* FIGHTING */)
        ).length;
        if (fightingEnergyInHand === 0) {
          effect.damage = 0;
          return state;
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 3 /* ENERGY */, cardType: [6 /* FIGHTING */] },
          { min: 0, max: fightingEnergyInHand, allowCancel: true }
        ), (transfers) => {
          if (!transfers || transfers.length === 0) {
            effect.damage = 0;
            return state;
          }
          effect.damage = transfers.length * 30;
          for (const transfer of transfers) {
            MOVE_CARDS(store, state, player.hand, player.discard, { cards: [transfer] });
          }
          return state;
        });
      }
      return state;
    }
  };

