  var Dragalge = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Skrelp";
      this.cardType = [N];
      this.hp = 100;
      this.weakness = [{ type: Y }];
      this.retreat = [C];
      this.powers = [{
        name: "Poison Barrier",
        powerType: 2 /* ABILITY */,
        text: "Your opponent's Poisoned Pokemon can't retreat."
      }];
      this.attacks = [{
        name: "Poison Breath",
        cost: [W, P, C],
        damage: 60,
        text: "Flip a coin. If heads, your opponent's Active Pokemon is now Poisoned."
      }];
      this.set = "FLF";
      this.name = "Dragalge";
      this.fullName = "Dragalge FLF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "71";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === true) {
            const specialConditionEffect = new AddSpecialConditionsEffect(
              effect,
              [3 /* POISONED */]
            );
            store.reduceEffect(state, specialConditionEffect);
          }
        });
      }
      if (effect instanceof RetreatEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const isPoisoned = player.active.specialConditions.includes(3 /* POISONED */);
        if (!isPoisoned) {
          return state;
        }
        let isDragalgeInPlay = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card) => {
          if (card === this) {
            isDragalgeInPlay = true;
          }
        });
        if (isDragalgeInPlay) {
          try {
            const stub = new PowerEffect(player, {
              name: "test",
              powerType: 2 /* ABILITY */,
              text: ""
            }, this);
            store.reduceEffect(state, stub);
          } catch {
            return state;
          }
          throw new GameError(GameMessage.BLOCKED_BY_ABILITY);
        }
      }
      return state;
    }
  };

