  var Dusknoir3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Dusclops";
      this.cardType = [P];
      this.hp = 130;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Shadow Void",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "As often as you like during your turn (before your attack), you may move 1 damage counter from 1 of your Pokemon to this Pokemon."
      }];
      this.attacks = [
        {
          name: "Pain Pellets",
          cost: [P, C, C],
          damage: 0,
          text: "Put damage counters on 1 of your opponent's Pokemon equal to the number of damage counters on this Pokemon."
        }
      ];
      this.set = "FLF";
      this.setNumber = "40";
      this.cardImage = "assets/cardback.png";
      this.name = "Dusknoir";
      this.fullName = "Dusknoir FLF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        let hasDamaged = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.damage > 0 && cardList.getPokemonCard() !== this) {
            hasDamaged = true;
          }
        });
        if (!hasDamaged) {
          return state;
        }
        ABILITY_USED(player, this);
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: true }
        ), (sourceTargets) => {
          if (!sourceTargets || sourceTargets.length === 0) {
            return;
          }
          const source = sourceTargets[0];
          if (source.damage <= 0 || source.getPokemonCard() === this) {
            return;
          }
          source.damage -= 10;
          const dusknoirList = StateUtils.findCardList(state, this);
          dusknoirList.damage += 10;
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const damageCounters = Math.floor(player.active.damage / 10);
        if (damageCounters === 0) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          const target = targets[0];
          const putCounters = new PutCountersEffect(effect, damageCounters * 10);
          putCounters.target = target;
          store.reduceEffect(state, putCounters);
        });
      }
      return state;
    }
  };

