  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-flashfire/floatzel.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects2();
  var Floatzel3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Buizel";
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.attacks = [{
        name: "Rescue",
        cost: [C],
        damage: 0,
        text: "Shuffle 3 Pok\xE9mon from your discard pile into your deck."
      }, {
        name: "Screw Tail",
        cost: [W, W],
        damage: 30,
        text: "Flip a coin. If heads, discard an Energy attached to your opponent's Active Pok\xE9mon."
      }];
      this.set = "FLF";
      this.setNumber = "29";
      this.cardImage = "assets/cardback.png";
      this.name = "Floatzel";
      this.fullName = "Floatzel FLF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const pokemonInDiscard = player.discard.cards.filter((c) => c instanceof PokemonCard);
        if (pokemonInDiscard.length === 0) {
          return state;
        }
        const blocked = [];
        player.discard.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard)) {
            blocked.push(index);
          }
        });
        const maxCount = Math.min(3, pokemonInDiscard.length);
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DECK,
          player.discard,
          { superType: 1 /* POKEMON */ },
          { min: maxCount, max: maxCount, allowCancel: false, blocked }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length > 0) {
            SHUFFLE_CARDS_INTO_DECK(store, state, player, cards);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            DISCARD_AN_ENERGY_FROM_OPPONENTS_ACTIVE_POKEMON(store, state, effect);
          }
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-flashfire/floette.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var Floette = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Flabebe";
      this.cardType = [Y];
      this.hp = 70;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Flower Veil",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Each of your Grass Pokemon in play gets +20 HP."
      }];
      this.attacks = [
        {
          name: "Fairy Wind",
          cost: [Y],
          damage: 20,
          text: ""
        }
      ];
      this.set = "FLF";
      this.setNumber = "64";
      this.cardImage = "assets/cardback.png";
      this.name = "Floette";
      this.fullName = "Floette FLF";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckHpEffect) {
        const targetCard2 = effect.target.getPokemonCard();
        if (!targetCard2 || !pokemonHasCardType(targetCard2, 1 /* GRASS */)) {
          return state;
        }
        let targetOwner = null;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList === effect.target) {
              targetOwner = p;
            }
          });
        });
        if (!targetOwner) {
          return state;
        }
        let floetteInPlay = false;
        targetOwner.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            floetteInPlay = true;
          }
        });
        if (!floetteInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetOwner, this)) {
          return state;
        }
        effect.hp += 20;
      }
      return state;
    }
  };

