  var Milotic4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Feebas";
      this.cardType = [W];
      this.hp = 100;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Energy Grace",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn (before your attack), you may Knock Out this Pok\xE9mon. If you do, attach 3 basic Energy cards from your discard pile to 1 of your Pok\xE9mon (excluding Pok\xE9mon-EX)."
        }
      ];
      this.attacks = [
        {
          name: "Waterfall",
          cost: [W, C, C],
          damage: 60,
          text: ""
        }
      ];
      this.set = "FLF";
      this.name = "Milotic";
      this.fullName = "Milotic FLF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "23";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const energyInDiscard = player.discard.cards.filter((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
        }).length;
        if (energyInDiscard === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked2 = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (card.hasTag("EX" /* POKEMON_EX */)) {
            blocked2.push(target);
          }
        });
        const attachAmount = Math.min(energyInDiscard, 3);
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: attachAmount, max: attachAmount, blockedTo: blocked2 }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.damage += 999;
              }
            });
          }
        );
        return state;
      }
      return state;
    }
  };

