  var Pyroar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Litleo";
      this.cardType = [R];
      this.hp = 110;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Intimidating Mane",
        powerType: 2 /* ABILITY */,
        text: "Prevent all damage done to this Pok\xE9mon by attacks from your opponent's Basic Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Scorching Fang",
        cost: [R, C, C],
        damage: 60,
        damageCalculation: "+",
        text: "You may discard a [R] Energy attached to this Pok\xE9mon. If you do, this attack does 30 more damage."
      }];
      this.set = "FLF";
      this.name = "Pyroar";
      this.fullName = "Pyroar FLF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "20";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [2 /* FIRE */],
          { allowCancel: true }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          if (cards.length > 0) {
            effect.damage += 30;
            const discardEnergy2 = new DiscardCardsEffect(effect, cards);
            discardEnergy2.target = player.active;
            return store.reduceEffect(state, discardEnergy2);
          }
        });
      }
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */ || !effect.source.isStage(2 /* BASIC */)) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.preventDefault = true;
      }
      return state;
    }
  };

