  var Seedot3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [1 /* GRASS */];
      this.hp = 50;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [{
        name: "Call for Family",
        cost: [9 /* COLORLESS */],
        damage: 0,
        text: "Search your deck for a Basic Pok\xE9mon and put it onto your Bench. Shuffle your deck afterward."
      }];
      this.set = "FLF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "5";
      this.name = "Seedot";
      this.fullName = "Seedot FLF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        let cards = [];
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          player.deck,
          { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
          { min: 1, max: 1, allowCancel: true }
        ), (selected) => {
          cards = selected || [];
          if (cards.length === 0) {
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
          cards.forEach((card, index) => {
            store.reduceEffect(state, new PlayPokemonFromDeckEffect(player, card, slots2[index]));
          });
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      return state;
    }
  };

