  var Shiftry2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.LEAF_DRAW_MARKER = "SHIFTRY_LEAF_DRAW_MARKER";
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Nuzleaf";
      this.cardType = [G];
      this.hp = 140;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Leaf Draw",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may discard a [G] Energy card from your hand. If you do, draw 3 cards."
      }];
      this.attacks = [
        {
          name: "Deranged Dance",
          cost: [G, C, C],
          damage: 20,
          damageCalculation: "x",
          text: "This attack does 20 damage times the number of Benched Pok\xE9mon (both yours and your opponent's)."
        }
      ];
      this.set = "FLF";
      this.setNumber = "7";
      this.cardImage = "assets/cardback.png";
      this.name = "Shiftry";
      this.fullName = "Shiftry FLF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasGrassEnergyInHand = player.hand.cards.some((c) => {
          return c instanceof EnergyCard && c.provides.includes(1 /* GRASS */);
        });
        if (!hasGrassEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.LEAF_DRAW_MARKER, this);
        ABILITY_USED(player, this);
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Grass Energy" },
          { allowCancel: false, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length > 0) {
            MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
            DRAW_CARDS(store, state, player, 3);
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.LEAF_DRAW_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let benchCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList !== player.active && cardList.cards.length > 0) {
            benchCount++;
          }
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          if (cardList !== opponent.active && cardList.cards.length > 0) {
            benchCount++;
          }
        });
        effect.damage = 20 * benchCount;
      }
      return state;
    }
  };

