  var Blacksmith = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "FLF";
      this.name = "Blacksmith";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "88";
      this.fullName = "Blacksmith FLF";
      this.text = "Attach 2 [R] Energy cards from your discard pile to 1 of your [R] Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const fireEnergyCount = player.discard.cards.filter(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(2 /* FIRE */)
        ).length;
        if (fireEnergyCount === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        let hasFirePokemon = false;
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, _pokemonCard, target) => {
          const checkPokemonTypeEffect = new CheckPokemonTypeEffect(cardList);
          store.reduceEffect(state, checkPokemonTypeEffect);
          if (checkPokemonTypeEffect.cardTypes.includes(2 /* FIRE */)) {
            hasFirePokemon = true;
          } else {
            blockedTo.push(target);
          }
        });
        if (!hasFirePokemon) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
            { allowCancel: false, min: 1, max: 2, blockedTo, sameTarget: true }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, {
                cards: [transfer.card],
                sourceCard: this
              });
            }
          }
        );
      }
      return state;
    }
  };

