  var StartlingMegaphone = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "FLF";
      this.name = "Startling Megaphone";
      this.fullName = "Startling Megaphone FLF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "97";
      this.text = "Discard all Pokemon Tool cards attached to each of your opponent's Pokemon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const pokemonsWithTool = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList.tools.length > 0) {
            pokemonsWithTool.push(cardList);
          }
        });
        if (pokemonsWithTool.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        pokemonsWithTool.forEach((target) => {
          if (target.tools.length > 0) {
            for (const tool of [...target.tools]) {
              MOVE_CARDS(store, state, target, opponent.discard, { cards: [tool], sourceCard: this });
            }
          }
        });
      }
      return state;
    }
  };

