  function* playCard90(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const hasSupporter = player.discard.cards.some((c) => {
      return c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */;
    });
    if (!hasSupporter) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
        { min: 0, max: 2, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length > 0) {
      MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
      if (cards.length > 0) {
        state = store.prompt(
          state,
          new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
          () => state
        );
      }
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var PalPad = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this._trainerType = 0 /* ITEM */;
      this.set = "SVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "182";
      this.name = "Pal Pad";
      this.fullName = "Pal Pad SVI";
      this.text = "Shuffle up to 2 Supporter cards from your discard pile into your deck.";
    }
    canPlay(store, state, player) {
      const hasSupporter = player.discard.cards.some((c) => {
        return c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */;
      });
      if (!hasSupporter) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const discardEffect = new TrainerToDeckEffect(player, this);
        store.reduceEffect(state, discardEffect);
        if (discardEffect.preventDefault) {
          return state;
        }
        const generator = playCard90(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

