  var Aurorus = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Amaura";
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: M }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Ice Shield",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Any damage done by an opponent's attack to each of your Water Pok\xE9mon that has any [W] Energy attached to it is reduced by 20 (after applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Icy Wind",
          cost: [W, C, C, C],
          damage: 70,
          text: "Your opponent's Active Pok\xE9mon is now Asleep."
        }
      ];
      this.set = "FFI";
      this.setNumber = "26";
      this.cardImage = "assets/cardback.png";
      this.name = "Aurorus";
      this.fullName = "Aurorus FFI";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect) {
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        let isAurorusInPlay = false;
        targetPlayer.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            isAurorusInPlay = true;
          }
        });
        if (!isAurorusInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetPlayer, this)) {
          return state;
        }
        const checkType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkType);
        if (!checkType.cardTypes.includes(3 /* WATER */)) {
          return state;
        }
        const checkEnergy = new CheckProvidedEnergyEffect(targetPlayer, effect.target);
        store.reduceEffect(state, checkEnergy);
        let hasWaterEnergy = false;
        for (const em of checkEnergy.energyMap) {
          if (em.provides.includes(3 /* WATER */)) {
            hasWaterEnergy = true;
            break;
          }
        }
        if (!hasWaterEnergy) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, targetPlayer);
        const isFromOpponent = opponent.active === effect.source || opponent.bench.includes(effect.source);
        if (!isFromOpponent) {
          return state;
        }
        effect.damage = Math.max(0, effect.damage - 20);
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

