  var Eevee8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 50;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [{
        name: "Energy Evolution",
        powerType: 2 /* ABILITY */,
        text: "When you attach a basic Energy card from your hand to this Pok\xE9mon, you may search your deck for a card that evolves from this Pok\xE9mon that is the same type as that Energy card and put it onto this Pok\xE9mon. (This counts as evolving this Pok\xE9mon.) Shuffle your deck afterward."
      }];
      this.attacks = [
        {
          name: "Gnaw",
          cost: [C, C],
          damage: 10,
          text: ""
        }
      ];
      this.set = "FFI";
      this.setNumber = "80";
      this.cardImage = "assets/cardback.png";
      this.name = "Eevee";
      this.fullName = "Eevee FFI";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        try {
          const powerEffect = new PowerEffect(player, this.powers[0], this);
          store.reduceEffect(state, powerEffect);
        } catch {
          return state;
        }
        let eeveelutionType = 9 /* COLORLESS */;
        switch (effect.energyCard.name) {
          case "Water Energy":
            eeveelutionType = 3 /* WATER */;
            break;
          case "Fire Energy":
            eeveelutionType = 2 /* FIRE */;
            break;
          case "Lightning Energy":
            eeveelutionType = 4 /* LIGHTNING */;
            break;
          case "Grass Energy":
            eeveelutionType = 1 /* GRASS */;
            break;
          case "Psychic Energy":
            eeveelutionType = 5 /* PSYCHIC */;
            break;
          case "Darkness Energy":
            eeveelutionType = 7 /* DARK */;
            break;
          case "Fairy Energy":
            eeveelutionType = 10 /* FAIRY */;
            break;
          default:
            eeveelutionType = 9 /* COLORLESS */;
            break;
        }
        if (eeveelutionType === 9 /* COLORLESS */) {
          return state;
        }
        if (player.deck.cards.length === 0) {
          return state;
        }
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            let cards = [];
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_EVOLVE,
              player.deck,
              { superType: 1 /* POKEMON */, stage: 3 /* STAGE_1 */, evolvesFrom: "Eevee", cardType: [eeveelutionType] },
              { min: 0, max: 1, allowCancel: true }
            ), (selected) => {
              cards = selected || [];
              if (cards.length > 0) {
                MOVE_CARDS(store, state, player.deck, cardList, { cards, sourceCard: this });
                cardList.clearEffects();
                cardList.pokemonPlayedTurn = state.turn;
              }
              SHUFFLE_DECK(store, state, player);
            });
          }
        });
      }
      return state;
    }
  };

