      this.powers = [{
        name: "Teleport Room",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may discard any Stadium card in play. If you do, put a Stadium card with a different name from your discard pile into play."
      }];
