  var Hypno3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Drowzee";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Hand Control",
          cost: [P],
          damage: 0,
          text: "Your opponent reveals his or her hand. You may choose a Supporter card you find there. If you do, your opponent plays that Supporter card. However, you make all decisions for that card. (That Supporter card is discarded.)"
        },
        {
          name: "Hypnoblast",
          cost: [P, P, P],
          damage: 60,
          text: "Your opponent's Active Pok\xE9mon is now Asleep."
        }
      ];
      this.set = "FFI";
      this.setNumber = "36";
      this.cardImage = "assets/cardback.png";
      this.name = "Hypno";
      this.fullName = "Hypno FFI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterCards = opponent.hand.cards.filter(
          (c) => c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */
        );
        if (supporterCards.length === 0) {
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_COPY_EFFECT,
            opponent.hand,
            { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
            { min: 0, max: 1, allowCancel: true }
          ),
          (selected) => {
            selected = selected || [];
            if (selected.length === 0) {
              return;
            }
            const supporterCard = selected[0];
            MOVE_CARDS(store, state, opponent.hand, opponent.supporter, { cards: [supporterCard], sourceCard: this });
            state = WITH_PROMPT_CONTROLLER(store, state, player.id, (s) => {
              s = store.reduceEffect(s, new TrainerEffect(opponent, supporterCard));
              store.log(s, "LOG_PLAYER_PLAYS_SUPPORTER" /* LOG_PLAYER_PLAYS_SUPPORTER */, {
                name: opponent.name,
                card: supporterCard.name
              });
              return s;
            });
            const cleanup = () => {
              if (!opponent.supporter.cards.includes(supporterCard)) {
                return;
              }
              const target = supporterCard.hasTag("Prism Star" /* PRISM_STAR */) ? opponent.lostzone : opponent.discard;
              MOVE_CARDS(store, state, opponent.supporter, target, { cards: [supporterCard], sourceCard: this });
            };
            if (store.hasPrompts()) {
              store.waitPrompt(state, cleanup);
            } else {
              cleanup();
            }
          }
        );
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

