      this.hp = 180;
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Missile Jab",
          cost: [6 /* FIGHTING */],
          damage: 30,
          text: "This attack's damage isn't affected by Resistance."
        },
        {
          name: "Corkscrew Smash",
          cost: [6 /* FIGHTING */, 6 /* FIGHTING */],
          damage: 60,
          text: "You may draw cards until you have 6 cards in your hand."
        },
        {
          name: "Somersault Kick",
          cost: [6 /* FIGHTING */, 6 /* FIGHTING */, 6 /* FIGHTING */],
          damage: 100,
          text: ""
        }
      ];
      this.set = "FFI";
