  var Machamp5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Machoke";
      this.cardType = [F];
      this.hp = 150;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Fighting Fury",
        powerType: 2 /* ABILITY */,
        text: "Each of your Fighting Pok\xE9mon's attacks do 20 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance)."
      }];
      this.attacks = [{
        name: "Machamp Crush",
        cost: [F, F, F],
        damage: 80,
        text: "During your opponent's next turn, any damage done by attacks from the Defending Pok\xE9mon is reduced by 40 (before applying Weakness and Resistance)."
      }];
      this.set = "FFI";
      this.setNumber = "46";
      this.cardImage = "assets/cardback.png";
      this.name = "Machamp";
      this.fullName = "Machamp FFI";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.target === StateUtils.getOpponent(state, effect.player).active) {
        const player = effect.player;
        let isMachampInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            isMachampInPlay = true;
          }
        });
        if (!isMachampInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkType = new CheckPokemonTypeEffect(effect.source);
        store.reduceEffect(state, checkType);
        if (checkType.cardTypes.includes(6 /* FIGHTING */)) {
          effect.damage += 20;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return DEFENDING_POKEMON_DOES_LESS_DAMAGE(store, state, effect, this, 40);
      }
      return state;
    }
  };

