  var Pancham = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 60;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Bad-Influence Evolution",
          cost: [C],
          damage: 0,
          text: "If you have any Darkness Pok\xE9mon on your Bench, search your deck for a card that evolves from this Pok\xE9mon and put it onto this Pok\xE9mon. (This counts as evolving this Pok\xE9mon.) Shuffle your deck afterward."
        },
        {
          name: "Confront",
          cost: [F, C, C],
          damage: 30,
          text: ""
        }
      ];
      this.set = "FFI";
      this.setNumber = "59";
      this.cardImage = "assets/cardback.png";
      this.name = "Pancham";
      this.fullName = "Pancham FFI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let hasDarknessBench = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (cardList !== player.active && pokemonHasCardType(card, 7 /* DARK */)) {
            hasDarknessBench = true;
          }
        });
        if (!hasDarknessBench) {
          return state;
        }
        if (player.deck.cards.length === 0) {
          return state;
        }
        let cards = [];
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_EVOLVE,
          player.deck,
          { superType: 1 /* POKEMON */, evolvesFrom: "Pancham" },
          { min: 0, max: 1, allowCancel: true }
        ), (selected) => {
          cards = selected || [];
          if (cards.length > 0) {
            MOVE_CARDS(store, state, player.deck, player.active, { cards, sourceCard: this });
            player.active.clearEffects();
            player.active.pokemonPlayedTurn = state.turn;
          }
          SHUFFLE_DECK(store, state, player);
        });
      }
      return state;
    }
  };

