  var Pangoro = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Pancham";
      this.cardType = [D];
      this.hp = 120;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Clobber",
          cost: [D, C],
          damage: 30,
          damageCalculation: "+",
          text: "You may discard an Item card from your hand. If you do, this attack does 40 more damage."
        },
        {
          name: "Hammer Arm",
          cost: [D, C, C],
          damage: 80,
          text: "Discard the top card of your opponent's deck."
        }
      ];
      this.set = "FFI";
      this.setNumber = "68";
      this.cardImage = "assets/cardback.png";
      this.name = "Pangoro";
      this.fullName = "Pangoro FFI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasItem = player.hand.cards.some(
          (c) => c instanceof TrainerCard && c.trainerType === 0 /* ITEM */
        );
        if (hasItem) {
          const blocked = [];
          player.hand.cards.forEach((c, index) => {
            if (!(c instanceof TrainerCard) || c.trainerType !== 0 /* ITEM */) {
              blocked.push(index);
            }
          });
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            {},
            { min: 0, max: 1, allowCancel: true, blocked }
          ), (selected) => {
            if (selected && selected.length > 0) {
              MOVE_CARDS(store, state, player.hand, player.discard, { cards: [selected[0]], sourceCard: this });
              effect.damage += 40;
            }
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        MOVE_CARDS(store, state, opponent.deck, opponent.discard, { count: 1 });
      }
      return state;
    }
  };

