  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-furious-fists/sylveon.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects2();
  var Sylveon = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Eevee";
      this.cardType = [Y];
      this.hp = 90;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Curly Ribbon",
          cost: [Y],
          damage: 30,
          text: "Move an Energy attached to your opponent's Active Pok\xE9mon to 1 of his or her Benched Pok\xE9mon."
        },
        {
          name: "Echoed Voice",
          cost: [Y, C, C],
          damage: 50,
          text: "During your next turn, this Pok\xE9mon's Echoed Voice attack does 50 more damage (before applying Weakness and Resistance)."
        }
      ];
      this.set = "FFI";
      this.setNumber = "72";
      this.cardImage = "assets/cardback.png";
      this.name = "Sylveon";
      this.fullName = "Sylveon FFI";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        const hasEnergy = opponent.active.cards.some((c) => c instanceof EnergyCard);
        if (!hasBenched || !hasEnergy) {
          return state;
        }
        const blocked = [];
        opponent.active.cards.forEach((card, index) => {
          if (!(card instanceof EnergyCard)) {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_ATTACH,
          opponent.active,
          { superType: 3 /* ENERGY */ },
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length === 0) {
            return;
          }
          return store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ), (targets) => {
            if (targets && targets.length > 0) {
              MOVE_CARDS(store, state, opponent.active, targets[0], { cards: [cards[0]], sourceCard: this });
            }
          });
        });
      }
      NEXT_TURN_ATTACK_BONUS(effect, {
        attack: this.attacks[1],
        source: this,
        bonusDamage: 50
      });
      return state;
    }
  };

