  init_prefabs();
  var Tornadus2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 110;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Push Down",
          cost: [C, C],
          damage: 20,
          text: "You may have your opponent switch his or her Active Pok\xE9mon with 1 of his or her Benched Pok\xE9mon."
        },
        {
          name: "Twister Throw",
          cost: [C, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "If you have the same number of cards in your hand as your opponent, this attack does 60 more damage."
        }
      ];
      this.set = "FFI";
      this.setNumber = "86";
      this.cardImage = "assets/cardback.png";
      this.name = "Tornadus";
      this.fullName = "Tornadus FFI";
      this.wantsToSwitch = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          CONFIRMATION_PROMPT(store, state, player, (result) => {
            this.wantsToSwitch = result;
          });
        }
      }
      if (effect instanceof AfterAttackEffect && this.wantsToSwitch) {
        this.wantsToSwitch = false;
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.wantsToSwitch = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.hand.cards.length === opponent.hand.cards.length) {
          effect.damage += 60;
        }
      }
      return state;
    }
  };

