        if (effect.target !== opponent.active || !targetCard2?.hasTag("EX" /* POKEMON_EX */) || IS_STADIUM_EFFECT_BLOCKED(store, state, opponent, effect.target)) {
          return state;
        }
        store.reduceEffect(state, checkPokemonType);
        if (checkPokemonType.cardTypes.includes(6 /* FIGHTING */)) {
          effect.damage += 20;
        }
