  var HerbalEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [];
      this.energyType = 1 /* SPECIAL */;
      this.set = "FFI";
      this.name = "Herbal Energy";
      this.fullName = "Herbal Energy FFI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "103";
      this.text = "This card can only be attached to [G] Pok\xE9mon. This card provides [G] Energy only while this card is attached to a [G] Pok\xE9mon.\n\nWhen you attach this card from your hand to 1 of your[G] Pok\xE9mon, heal 30 damage from that Pok\xE9mon.\n\n(If this card is attached to anything other than a [G] Pok\xE9mon, discard this card.)";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        const checkPokemonType = new CheckPokemonTypeEffect(effect.source);
        store.reduceEffect(state, checkPokemonType);
        if (checkPokemonType.cardTypes.includes(1 /* GRASS */)) {
          effect.energyMap.push({ card: this, provides: [1 /* GRASS */] });
        }
      }
      if (effect instanceof AttachEnergyEffect && effect.energyCard === this) {
        const checkPokemonType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkPokemonType);
        if (!checkPokemonType.cardTypes.includes(1 /* GRASS */)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, effect.player, this, effect.target)) {
          return state;
        }
        const healEffect = new HealEffect(effect.player, effect.target, 30);
        store.reduceEffect(state, healEffect);
      }
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (!cardList.cards.includes(this) || IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, cardList)) {
              return;
            }
            const checkPokemonType = new CheckPokemonTypeEffect(cardList);
            store.reduceEffect(state, checkPokemonType);
            if (!checkPokemonType.cardTypes.includes(1 /* GRASS */)) {
              MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
            }
          });
        });
      }
      return state;
    }
  };

