  var AegislashEX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["EX" /* POKEMON_EX */];
      this.cardType = [M];
      this.hp = 170;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Mighty Shield",
          powerType: 2 /* ABILITY */,
          text: "Prevent all damage done to this Pok\xE9mon by attacks from each of your opponent's Pok\xE9mon that has Special Energy attached to it."
        }
      ];
      this.attacks = [
        {
          name: "Slash Blast",
          cost: [C, C, C],
          damage: 40,
          damageCalculation: "+",
          text: "This attack does 20 more damage for each [M] Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "PHF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "65";
      this.name = "Aegislash-EX";
      this.fullName = "Aegislash-EX PHF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let energyCount = 0;
        checkProvidedEnergyEffect.energyMap.forEach((em) => {
          energyCount += em.provides.filter((cardType) => {
            return cardType === 8 /* METAL */ || cardType === 0 /* ANY */;
          }).length;
        });
        effect.damage += energyCount * 20;
      }
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this) && state.phase === 3 /* ATTACK */) {
        const player = StateUtils.findOwner(state, effect.target);
        const opponent = StateUtils.getOpponent(state, effect.player);
        const opponentPokemon = opponent.active;
        const checkEnergy = new CheckProvidedEnergyEffect(opponent, opponentPokemon);
        store.reduceEffect(state, checkEnergy);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        checkEnergy.energyMap.forEach((em) => {
          const energyCard = em.card;
          if (energyCard.superType === 3 /* ENERGY */ && energyCard.energyType === 1 /* SPECIAL */) {
            if (effect instanceof PutDamageEffect && opponent.active.cards.includes(energyCard)) {
              effect.damage = 0;
              return state;
            }
          }
        });
      }
      return state;
    }
  };

