  var Bronzong2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Bronzor";
      this.cardType = [M];
      this.hp = 90;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Metal Links",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may attach a [M] Energy card from your discard pile to 1 of your Benched Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Hammer In",
        cost: [M, M, C],
        damage: 60,
        text: ""
      }];
      this.set = "PHF";
      this.setNumber = "61";
      this.cardImage = "assets/cardback.png";
      this.name = "Bronzong";
      this.fullName = "Bronzong PHF";
      this.METAL_LINKS_MARKER = "METAL_LINKS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.METAL_LINKS_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.provides.includes(8 /* METAL */);
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.METAL_LINKS_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const blocked = [];
        player.discard.cards.forEach((card, index) => {
          if (card instanceof EnergyCard && !card.provides.includes(8 /* METAL */)) {
            blocked.push(index);
          }
        });
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Metal Energy" },
          { allowCancel: false, min: 1, max: 1, blocked }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
          player.marker.addMarker(this.METAL_LINKS_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
        });
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.METAL_LINKS_MARKER, this);
      }
      return state;
    }
  };

