      this.retreat = [C];
      this.usedCobwebTrip = false;
      this.attacks = [
        {
          name: "Cobweb Trip",
          cost: [L],
          damage: 0,
          text: "Switch 1 of your opponent's Benched Pok\xE9mon with your opponent's Active Pok\xE9mon. The new Active Pok\xE9mon is now Confused."
        },
        {
          name: "Electroweb",
          cost: [L, C, C],
          damage: 60,
          text: "The Defending Pok\xE9mon can't retreat during your opponent's next turn."
        }
      ];
