  var Hydreigon5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Zweilous";
      this.cardType = [N];
      this.hp = 140;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Dark Impulse",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may attach a [D] Energy card from your discard pile to your Active Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Crazy Headbutt",
        cost: [P, D, C, C],
        damage: 130,
        text: "Discard an Energy attached to this Pok\xE9mon."
      }];
      this.set = "PHF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "74";
      this.name = "Hydreigon";
      this.fullName = "Hydreigon PHF";
      this.DARK_IMPULSE_MARKER = "DARK_IMPULSE_MARKER";
      this.usedCrazyHeadbutt = false;
    }
    reduceEffect(store, state, effect) {
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.DARK_IMPULSE_MARKER, this);
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.name === "Darkness Energy";
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.DARK_IMPULSE_MARKER, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_ACTIVE,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, name: "Darkness Energy" },
          { allowCancel: false, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          player.marker.addMarker(this.DARK_IMPULSE_MARKER, this);
          ABILITY_USED(player, this);
          if (transfers.length === 0) {
            return;
          }
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
          return state;
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-phantom-forces/jellicent.ts
