  var Jellicent5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Frillish";
      this.cardType = [W];
      this.hp = 100;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Meddling",
          cost: [W],
          damage: 0,
          text: "Attach 3 Energy cards from your opponent's discard pile to his or her Pok\xE9mon in any way you like."
        },
        {
          name: "Ensnaring Spray",
          cost: [W, C, C],
          damage: 50,
          damageCalculation: "+",
          text: "This attack does 10 more damage for each Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "PHF";
      this.setNumber = "21";
      this.cardImage = "assets/cardback.png";
      this.name = "Jellicent";
      this.fullName = "Jellicent PHF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const energyInDiscard = opponent.discard.cards.filter((c) => c instanceof EnergyCard);
        if (energyInDiscard.length === 0) {
          return state;
        }
        const count = Math.min(3, energyInDiscard.length);
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          opponent.discard,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { min: count, max: count, allowCancel: false }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, opponent, transfer.to);
            const energyCard = transfer.card;
            const attachEnergyEffect = new AttachEnergyEffect(player, energyCard, target);
            store.reduceEffect(state, attachEnergyEffect);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        store.reduceEffect(state, checkEnergy);
        let energyCount = 0;
        checkEnergy.energyMap.forEach((em) => {
          energyCount += em.provides.length;
        });
        effect.damage += 10 * energyCount;
      }
      return state;
    }
  };

