  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-phantom-forces/leavanny.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_trainer_card();
  init_game_effects();
  init_check_effects();
  init_choose_pokemon_prompt();
  init_choose_cards_prompt();
  init_prefabs();
  var Leavanny5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Swadloon";
      this.cardType = [G];
      this.hp = 130;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Coordinate",
          cost: [G],
          damage: 0,
          text: "Choose up to 2 of your Benched Pok\xE9mon that have no Pok\xE9mon Tools attached to them. For each of those Pok\xE9mon, search your deck for a Pok\xE9mon Tool card, and attach it to that Pok\xE9mon. Shuffle your deck afterward."
        },
        {
          name: "Leaf Storm",
          cost: [G, G, C],
          damage: 70,
          text: "Heal 20 damage from each of your Grass Pok\xE9mon."
        }
      ];
      this.set = "PHF";
      this.setNumber = "7";
      this.cardImage = "assets/cardback.png";
      this.name = "Leavanny";
      this.fullName = "Leavanny PHF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const benchWithoutTools = player.bench.filter(
          (b) => b.cards.length > 0 && b.tools.length === 0
        );
        if (benchWithoutTools.length === 0 || player.deck.cards.length === 0) {
          return state;
        }
        const hasToolsInDeck = player.deck.cards.some(
          (c) => c instanceof TrainerCard && c.trainerType === 3 /* TOOL */
        );
        if (!hasToolsInDeck) {
          SHUFFLE_DECK(store, state, player);
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { min: 0, max: Math.min(2, benchWithoutTools.length), allowCancel: true }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          const validTargets = targets.filter((t) => t.tools.length === 0);
          const attachToolToNextTarget = (index) => {
            if (index >= validTargets.length) {
              SHUFFLE_DECK(store, state, player);
              return;
            }
            const target = validTargets[index];
            let cards = [];
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_HAND,
              player.deck,
              { superType: 2 /* TRAINER */, trainerType: 3 /* TOOL */ },
              { min: 0, max: 1, allowCancel: true }
            ), (selected) => {
              cards = selected || [];
              if (cards.length > 0) {
                const tool = cards[0];
                MOVE_CARDS(store, state, player.deck, target, { cards: [tool], sourceCard: this });
                const idx = target.cards.indexOf(tool);
                if (idx !== -1) {
                  target.cards.splice(idx, 1);
                }
                target.tools.push(tool);
              }
              attachToolToNextTarget(index + 1);
            });
          };
          attachToolToNextTarget(0);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const checkType = new CheckPokemonTypeEffect(cardList);
          store.reduceEffect(state, checkType);
          if (checkType.cardTypes.includes(1 /* GRASS */) && cardList.damage > 0) {
            const healEffect = new HealEffect(player, cardList, 20);
            store.reduceEffect(state, healEffect);
          }
        });
      }
      return state;
    }
  };

