  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-phantom-forces/m-manectric-ex.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_choose_cards_prompt();
  init_choose_pokemon_prompt();
  init_prefabs();
  var MManectricEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Mega EX" /* MEGA */, "EX" /* POKEMON_EX */];
      this.stage = 9 /* MEGA */;
      this.evolvesFrom = "Manectric-EX";
      this.cardType = [L];
      this.hp = 210;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Turbo Bolt",
          cost: [L, C],
          damage: 110,
          text: "Attach 2 basic Energy cards from your discard pile to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.set = "PHF";
      this.setNumber = "24";
      this.cardImage = "assets/cardback.png";
      this.name = "M Manectric-EX";
      this.fullName = "M Manectric-EX PHF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const basicEnergyInDiscard = player.discard.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        );
        if (basicEnergyInDiscard.length === 0) {
          return state;
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return state;
            }
            const target = targets[0];
            const blocked = [];
            player.discard.cards.forEach((card, index) => {
              if (!(card instanceof EnergyCard) || card.energyType !== 0 /* BASIC */) {
                blocked.push(index);
              }
            });
            const availableCount = basicEnergyInDiscard.length;
            const count = Math.min(2, availableCount);
            return store.prompt(
              state,
              new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARD_TO_ATTACH,
                player.discard,
                { superType: 3 /* ENERGY */ },
                { min: count, max: count, allowCancel: false, blocked }
              ),
              (selected) => {
                const cards = selected || [];
                cards.forEach((card) => {
                  MOVE_CARDS(store, state, player.discard, target, { cards: [card], sourceCard: this });
                });
              }
            );
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-phantom-forces/malamar-ex.ts
