  var MalamarEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["EX" /* POKEMON_EX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 170;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Hyper Hypnosis",
          useWhenInPlay: false,
          powerType: 2 /* ABILITY */,
          text: "When you attach an Energy from your hand to this Pok\xE9mon, you may use this Ability. Your opponent's Active Pok\xE9mon is now Asleep."
        }
      ];
      this.attacks = [{
        name: "MAXamar",
        cost: [D, C],
        damage: 60,
        damageCalculation: "x",
        text: "Flip a coin for each Energy attached to this Pok\xE9mon. This attack does 60 damage times the number of heads."
      }];
      this.set = "PHF";
      this.setNumber = "58";
      this.cardImage = "assets/cardback.png";
      this.name = "Malamar-EX";
      this.fullName = "Malamar-EX PHF";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        try {
          const powerEffect = new PowerEffect(player, this.powers[0], this);
          store.reduceEffect(state, powerEffect);
        } catch {
          return state;
        }
        ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, opponent, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const energyCount = player.active.cards.filter(
          (c) => c.superType === 3 /* ENERGY */
        ).length;
        if (energyCount === 0) {
          effect.damage = 0;
          return state;
        }
        return MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, energyCount, (results) => {
          const heads = results.filter((r) => r).length;
          effect.damage = 60 * heads;
        });
      }
      return state;
    }
  };

