  init_game();
  init_card_types();
  init_pokemon_card();
  init_pokemon_types();
  init_attack_effects();
  init_check_effects();
  init_game_phase_effects();
  init_play_card_effects();
  init_prefabs();
  var Pyroar2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Litleo";
      this.cardType = [2 /* FIRE */];
      this.hp = 110;
      this.weakness = [{ type: 3 /* WATER */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Flare Command",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may discard a [R] Energy attached to this Pok\xE9mon. If you do, switch 1 of your opponent's Benched Pok\xE9mon with his or her Active Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Inferno Onrush",
        cost: [2 /* FIRE */, 2 /* FIRE */, 2 /* FIRE */, 9 /* COLORLESS */],
        damage: 110,
        text: "This Pok\xE9mon does 30 damage to itself."
      }];
      this.set = "PHF";
      this.name = "Pyroar";
      this.fullName = "Pyroar PHF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "12";
      this.FLARE_COMMAND_MARKER = "FLARE_COMMAND_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const dealDamage = new DealDamageEffect(effect, 30);
        dealDamage.target = player.active;
        return store.reduceEffect(state, dealDamage);
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.FLARE_COMMAND_MARKER, this);
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.marker.removeMarker(this.FLARE_COMMAND_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        if (player.marker.hasMarker(this.FLARE_COMMAND_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const hasEnergyAttached = cardList.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.name === "Fire Energy";
        });
        if (!hasEnergyAttached) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.active,
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          selected || [];
          if (selected.length === 0) {
            return;
          }
          MOVE_CARDS(store, state, player.active, player.discard, { cards: selected, sourceCard: this });
          player.marker.addMarker(this.FLARE_COMMAND_MARKER, this);
          const opponent = StateUtils.getOpponent(state, player);
          const hasBench = opponent.bench.some((b) => b.cards.length > 0);
          if (!hasBench) {
            return state;
          }
          return store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ), (result) => {
            const cardList2 = result[0];
            opponent.switchPokemon(cardList2);
            return state;
          });
        });
      }
      return state;
    }
  };

