  var Wobbuffet4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 110;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Bide Barricade",
        powerType: 2 /* ABILITY */,
        abilityLock: true,
        text: "As long as this Pokemon is your Active Pokemon, each Pokemon in play, in each player's hand, and in each player's discard pile has no Abilities (except for [P] Pok\xE9mon)."
      }];
      this.attacks = [{
        name: "Psychic Assault",
        cost: [P, C],
        damage: 10,
        damageCalculation: "+",
        text: "This attack does 10 more damage for each damage counter on your opponent's Active Pokemon."
      }];
      this.set = "PHF";
      this.name = "Wobbuffet";
      this.fullName = "Wobbuffet PHF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "36";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.damage += effect.opponent.active.damage;
        return state;
      }
      HANDLE_ABILITY_LOCK(effect, ({ player, card }) => {
        if (!IS_ABILITY_LOCKER_ACTIVE(state, player, this)) {
          return false;
        }
        try {
          const cardList = StateUtils.findCardList(state, card);
          if (cardList instanceof PokemonCardList) {
            const checkPokemonType = new CheckPokemonTypeEffect(cardList);
            store.reduceEffect(state, checkPokemonType);
            if (checkPokemonType.cardTypes.includes(5 /* PSYCHIC */)) {
              return false;
            }
          } else if (pokemonHasCardType(card, 5 /* PSYCHIC */)) {
            return false;
          }
        } catch {
          return false;
        }
        const opponent = StateUtils.getOpponent(state, player);
        const lockerOwner = player.active.getPokemonCard() === this ? player : opponent;
        if (!LOCKER_ABILITY_APPLIES(store, state, lockerOwner, this, this.powers[0], card)) {
          return false;
        }
        if (!CAN_APPLY_LOCK_TO_TARGET(store, state, lockerOwner, this, this.powers[0], card)) {
          return false;
        }
        return true;
      }, {
        exemptPowerNames: ["Bide Barricade"],
        error: GameMessage.BLOCKED_BY_ABILITY
      });
      return state;
    }
  };

