  var HeadRinger = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "PHF";
      this.setNumber = "97";
      this.cardImage = "assets/cardback.png";
      this.name = "Head Ringer";
      this.fullName = "Head Ringer Team Flare Hyper Gear PHF";
      this.text = "Attach this Pokemon Tool to 1 of your opponent's Pokemon-EX that doesn't already have a Pokemon Tool attached to it.\n\nThe attacks of the Pok\xE9mon this card is attached to cost [C] more.\n\nWhen this card is removed from a Pok\xE9mon for any reason, put this card in its owner's discard pile.";
    }
    // Refs: set-furious-fists/politoed.ts (CheckAttackCostEffect), set-stellar-crown/gravity-gemstone.ts (tool cost modification)
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayItemEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let hasValidTarget = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card) => {
          if (card.hasTag("EX" /* POKEMON_EX */) && cardList.tools.length === 0) {
            hasValidTarget = true;
          }
        });
        if (!hasValidTarget) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        effect.preventDefault = true;
        const blocked = [];
        const opponentActive = opponent.active;
        const opponentActivePokemon = opponentActive.getPokemonCard();
        if (!opponentActivePokemon || !opponentActivePokemon.hasTag("EX" /* POKEMON_EX */) || opponentActive.tools.length > 0) {
          blocked.push({
            player: 1 /* TOP_PLAYER */,
            slot: 1 /* ACTIVE */,
            index: 0
          });
        }
        opponent.bench.forEach((benchSlot, index) => {
          const pokemonCard = benchSlot.getPokemonCard();
          if (!pokemonCard || !pokemonCard.hasTag("EX" /* POKEMON_EX */) || benchSlot.tools.length > 0) {
            blocked.push({
              player: 1 /* TOP_PLAYER */,
              slot: 2 /* BENCH */,
              index
            });
          }
        });
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (targets) => {
            if (targets && targets.length > 0) {
              const target = targets[0];
              MOVE_CARDS(store, state, player.hand, target, { cards: [this], sourceCard: this });
              target.tools.push(this);
            }
          }
        );
      }
      if (effect instanceof CheckAttackCostEffect) {
        const player = effect.player;
        if (!player.active.tools.includes(this)) {
          return state;
        }
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.cost.push(9 /* COLORLESS */);
      }
      return state;
    }
  };

