  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-phantom-forces/xerosic.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_prefabs();
  var Xerosic = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "PHF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "110";
      this.name = "Xerosic";
      this.fullName = "Xerosic PHF";
      this.text = "Choose a Pok\xE9mon Tool or Special Energy card attached to a Pok\xE9mon in play (yours or your opponent's) and discard it.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        let pokemonsWithTool = 0;
        const blocked = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList.tools.length > 0) {
            pokemonsWithTool += 1;
          } else {
            blocked.push(target);
          }
        });
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.tools.length > 0) {
            pokemonsWithTool += 1;
          } else {
            blocked.push(target);
          }
        });
        let specialEnergy = 0;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList.energies.cards.some((c) => c.energyType === 1 /* SPECIAL */)) {
            specialEnergy += 1;
          }
        });
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.energies.cards.some((c) => c.energyType === 1 /* SPECIAL */)) {
            specialEnergy += 1;
          }
        });
        if (pokemonsWithTool === 0 && specialEnergy === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        const toolOption = {
          message: GameMessage.CHOICE_TOOL,
          action: () => {
            let targets = [];
            return store.prompt(
              state,
              new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_DISCARD_CARDS,
                0 /* ANY */,
                [1 /* ACTIVE */, 2 /* BENCH */],
                { min: 1, max: 1, allowCancel: false, blocked }
              ),
              (results) => {
                targets = results || [];
                if (targets.length === 0) {
                  return state;
                }
                const cardList = targets[0];
                if (cardList.isStage(2 /* BASIC */)) {
                  try {
                    const supporterEffect = new SupporterEffect(player, effect.trainerCard);
                    store.reduceEffect(state, supporterEffect);
                  } catch {
                    return state;
                  }
                }
                targets.forEach((target) => {
                  const owner = StateUtils.findOwner(state, target);
                  if (target.tools.length > 0) {
                    if (target.tools.length > 1) {
                      return store.prompt(
                        state,
                        new ChooseCardsPrompt(
                          player,
                          GameMessage.CHOOSE_CARD_TO_DISCARD,
                          target,
                          { superType: 2 /* TRAINER */, trainerType: 3 /* TOOL */ },
                          { min: 1, max: 1, allowCancel: false }
                        ),
                        (selected) => {
                          if (selected && selected.length > 0) {
                            MOVE_CARDS(store, state, target, owner.discard, {
                              cards: [selected[0]],
                              sourceCard: this
                            });
                          }
                          MOVE_CARDS(store, state, player.supporter, player.discard, {
                            cards: [this],
                            sourceCard: this
                          });
                          return state;
                        }
                      );
                    } else {
                      MOVE_CARDS(store, state, target, owner.discard, {
                        cards: [target.tools[0]],
                        sourceCard: this
                      });
                    }
                  }
                  MOVE_CARDS(store, state, player.supporter, player.discard, {
                    cards: [this],
                    sourceCard: this
                  });
                  return state;
                });
                MOVE_CARDS(store, state, player.supporter, player.discard, {
                  cards: [this],
                  sourceCard: this
                });
                return state;
              }
            );
          }
        };
        const specialEnergyBlocked = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList.energies.cards.some((c) => c.energyType === 1 /* SPECIAL */)) {
            return;
          } else {
            specialEnergyBlocked.push(target);
          }
        });
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.energies.cards.some((c) => c.energyType === 1 /* SPECIAL */)) {
            return;
          } else {
            specialEnergyBlocked.push(target);
          }
        });
        const specialEnergyOption = {
          message: GameMessage.CHOICE_SPECIAL_ENERGY,
          action: () => {
            return store.prompt(
              state,
              new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_DISCARD_CARDS,
                0 /* ANY */,
                [1 /* ACTIVE */, 2 /* BENCH */],
                { allowCancel: false, blocked: specialEnergyBlocked }
              ),
              (results) => {
                if (results.length === 0) {
                  return state;
                }
                const target = results[0];
                let cards = [];
                state = store.prompt(
                  state,
                  new ChooseCardsPrompt(
                    player,
                    GameMessage.CHOOSE_CARD_TO_DISCARD,
                    target.energies,
                    { energyType: 1 /* SPECIAL */ },
                    { min: 1, max: 1, allowCancel: false }
                  ),
                  (selected) => {
                    cards = selected || [];
                    if (cards.length > 0) {
                      MOVE_CARDS(store, state, target, opponent.discard, {
                        cards,
                        sourceCard: this
                      });
                    }
                    return state;
                  }
                );
              }
            );
          }
        };
        const options = [];
        if (pokemonsWithTool > 0) {
          options.push(toolOption);
        }
        if (specialEnergy > 0) {
          options.push(specialEnergyOption);
        }
        return store.prompt(
          state,
          new SelectPrompt(
            player.id,
            GameMessage.CHOOSE_OPTION,
            options.map((c) => c.message),
            { allowCancel: false }
          ),
          (choice) => {
            const option = options[choice];
            if (option.action) {
              option.action();
            }
            MOVE_CARDS(store, state, player.supporter, player.discard, {
              cards: [this],
              sourceCard: this
            });
            return state;
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-phantom-forces/mystery-energy.ts
