  var MysteryEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [];
      this.energyType = 1 /* SPECIAL */;
      this.set = "PHF";
      this.name = "Mystery Energy";
      this.fullName = "Mystery Energy PHF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "112";
      this.STRONG_ENERGY_MAREKER = "STRONG_ENERGY_MAREKER";
      this.text = "This card can only be attached to [P] Pokemon. This card provides [P] Energy, but only while this card is attached to a [P] Pokemon.\n\nThe Retreat Cost of the Pokemon this card is attached to is [C][C] less.\n\n(If this card is attached to anything other than a [P] Pokemon, discard this card.)";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        const checkPokemonType = new CheckPokemonTypeEffect(effect.source);
        store.reduceEffect(state, checkPokemonType);
        if (checkPokemonType.cardTypes.includes(5 /* PSYCHIC */)) {
          effect.energyMap.push({ card: this, provides: [5 /* PSYCHIC */] });
        }
      }
      if (effect instanceof AttachEnergyEffect && effect.energyCard === this) {
        const checkPokemonType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkPokemonType);
        if (!checkPokemonType.cardTypes.includes(5 /* PSYCHIC */)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
      }
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (!cardList.cards.includes(this) || IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, cardList)) {
              return;
            }
            const checkPokemonType = new CheckPokemonTypeEffect(cardList);
            store.reduceEffect(state, checkPokemonType);
            if (!checkPokemonType.cardTypes.includes(5 /* PSYCHIC */)) {
              MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
            }
          });
        });
      }
      if (effect instanceof CheckRetreatCostEffect && effect.player.active.cards.includes(this)) {
        const player = effect.player;
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, player.active)) {
          return state;
        }
        if (player.active.cards.includes(this)) {
          for (let i = 0; i < 2; i++) {
            const index = effect.cost.indexOf(9 /* COLORLESS */);
            if (index !== -1) {
              effect.cost.splice(index, 1);
            }
          }
        }
      }
      return state;
    }
  };

