  var ProfessorSycamore = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "XY";
      this.setNumber = "122";
      this.cardImage = "assets/cardback.png";
      this.name = "Professor Sycamore";
      this.fullName = "Professor Sycamore XY";
      this.legacyFullName = "Professor Sycamore XY 122";
      this.text = "Discard your hand and draw 7 cards.";
    }
    canPlay(_, __, player) {
      return !(player.supporterTurn > 0 && player.deck.cards.length === 0);
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const cards = player.hand.cards.filter((c) => c !== this);
        if (cards.length > 0) {
          state = MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
        }
        state = DRAW_CARDS(store, state, player, 7);
      }
      return state;
    }
  };

