  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var Aegislash = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Doublade";
      this.cardType = [M];
      this.hp = 140;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Miracle Guard",
        useWhenInPlay: false,
        powerType: 2 /* ABILITY */,
        text: "Each of your Pok\xE9mon has no Weakness."
      }];
      this.attacks = [
        {
          name: "Protect Charge",
          cost: [M, C, C],
          damage: 80,
          text: "During your opponent's next turn, any damage done to this Pok\xE9mon by attacks is reduced by 20 (after applying Weakness and Resistance)."
        }
      ];
      this.set = "PRC";
      this.setNumber = "100";
      this.cardImage = "assets/cardback.png";
      this.name = "Aegislash";
      this.fullName = "Aegislash PRC";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonStatsEffect) {
        let aegislashOwner = null;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              aegislashOwner = p;
            }
          });
        });
        if (!aegislashOwner) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, aegislashOwner, this)) {
          return state;
        }
        let targetOwner = null;
        state.players.forEach((p) => {
          if (p.active === effect.target || p.bench.includes(effect.target)) {
            targetOwner = p;
          }
        });
        if (targetOwner === aegislashOwner) {
          effect.weakness = [];
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.player.active.damageReductionNextTurn = 20;
      }
      return state;
    }
  };

