  init_game();
  init_energy_card();
  init_attach_energy_prompt();
  init_prefabs();
  var Blaziken4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Combusken";
      this.cardType = [R];
      this.hp = 140;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Spreading Flames",
          cost: [R],
          damage: 0,
          text: "Attach 3 [R] Energy cards from your discard pile to your Pok\xE9mon in any way you like."
        },
        {
          name: "Heat Blow",
          cost: [R, C],
          damage: 100,
          text: "Discard an Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "PRC";
      this.setNumber = "28";
      this.cardImage = "assets/cardback.png";
      this.name = "Blaziken";
      this.fullName = "Blaziken PRC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const fireEnergyInDiscard = player.discard.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(2 /* FIRE */)
        );
        if (fireEnergyInDiscard.length === 0) {
          return state;
        }
        const count = Math.min(3, fireEnergyInDiscard.length);
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { min: count, max: count, allowCancel: false }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-primal-clash/bouffalant.ts
  init_pokemon_card();
