  init_check_effects();
  init_prefabs();
  var Bouffalant5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 110;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Sap Sipper",
        useWhenInPlay: false,
        powerType: 2 /* ABILITY */,
        text: "This Pok\xE9mon's attacks do 40 more damage to your opponent's Grass Pok\xE9mon (before applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Derail",
          cost: [C, C, C],
          damage: 80,
          text: "Discard a Special Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "PRC";
      this.setNumber = "119";
      this.cardImage = "assets/cardback.png";
      this.name = "Bouffalant";
      this.fullName = "Bouffalant PRC";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.source.cards.includes(this)) {
        const player = StateUtils.findOwner(state, effect.source);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkType);
        if (checkType.cardTypes.includes(1 /* GRASS */)) {
          effect.damage += 40;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasSpecialEnergy = opponent.active.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 1 /* SPECIAL */
        );
        if (!hasSpecialEnergy) {
          return state;
        }
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          opponent.active,
          { superType: 3 /* ENERGY */, energyType: 1 /* SPECIAL */ },
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length > 0) {
            const discardEnergy2 = new DiscardCardsEffect(effect, cards);
            discardEnergy2.target = opponent.active;
            store.reduceEffect(state, discardEnergy2);
          }
        });
      }
      return state;
    }
  };

