  var Crawdaunt = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Corphish";
      this.cardType = [D];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Unruly Claw",
        useWhenInPlay: false,
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon, you may discard an Energy attached to your opponent's Active Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Crabhammer",
          cost: [D, C, C],
          damage: 60,
          text: ""
        }
      ];
      this.set = "PRC";
      this.setNumber = "92";
      this.cardImage = "assets/cardback.png";
      this.name = "Crawdaunt";
      this.fullName = "Crawdaunt PRC";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, player);
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        state = store.reduceEffect(state, checkProvidedEnergy);
        if (checkProvidedEnergy.energyMap.length === 0) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            store.prompt(state, new ChooseEnergyPrompt(
              player.id,
              GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
              checkProvidedEnergy.energyMap,
              [9 /* COLORLESS */],
              { allowCancel: false }
            ), (energy2) => {
              const cards = (energy2 || []).map((e) => e.card);
              if (cards.length > 0) {
                MOVE_CARDS(store, state, opponent.active, opponent.discard, { cards, sourceCard: this });
              }
            });
          }
        });
      }
      return state;
    }
  };

