  var Eelektross4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Eelektrik";
      this.cardType = [L];
      this.hp = 140;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Energy Connect",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "As often as you like during your turn (before your attack), you may move a basic Energy attached to 1 of your Benched Pok\xE9mon to your Active Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Electricannon",
          cost: [L, L, C, C],
          damage: 80,
          damageCalculation: "+",
          text: "You may discard all [L] Energy attached to this Pok\xE9mon. If you do, this attack does 50 more damage."
        }
      ];
      this.set = "PRC";
      this.setNumber = "65";
      this.cardImage = "assets/cardback.png";
      this.name = "Eelektross";
      this.fullName = "Eelektross PRC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        let hasBasicEnergyOnBench = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList !== player.active) {
            const checkEnergy = new CheckProvidedEnergyEffect(player, cardList);
            store.reduceEffect(state, checkEnergy);
            if (checkEnergy.energyMap.some((em) => em.card instanceof EnergyCard && em.card.energyType === 0 /* BASIC */)) {
              hasBasicEnergyOnBench = true;
            }
          }
        });
        if (!hasBasicEnergyOnBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blockedFrom = [];
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList === player.active) {
            blockedFrom.push(target);
          } else {
            blockedTo.push(target);
          }
        });
        return store.prompt(state, new MoveEnergyPrompt(
          player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { allowCancel: true, min: 0, max: 1, blockedFrom, blockedTo }
        ), (transfers) => {
          if (transfers && transfers.length > 0) {
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              MOVE_CARDS(store, state, source, player.active, { cards: [transfer.card], sourceCard: this });
            }
            ABILITY_USED(player, this);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkEnergy);
        const lightningCards = [];
        for (const em of checkEnergy.energyMap) {
          if (em.provides.some((t) => t === 4 /* LIGHTNING */ || t === 0 /* ANY */)) {
            lightningCards.push(em.card);
          }
        }
        if (lightningCards.length > 0) {
          state = store.prompt(state, new ConfirmPrompt(
            player.id,
            GameMessage.WANT_TO_USE_ABILITY
          ), (wantToDiscard) => {
            if (wantToDiscard) {
              const discardEnergy2 = new DiscardCardsEffect(effect, lightningCards);
              discardEnergy2.target = player.active;
              store.reduceEffect(state, discardEnergy2);
              effect.damage += 50;
            }
          });
        }
      }
      return state;
    }
  };

