  var Gorebyss2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Clamperl";
      this.cardType = [W];
      this.hp = 80;
      this.weakness = [{ type: G }];
      this.retreat = [];
      this.usedCaptivate = false;
      this.attacks = [
        {
          name: "Captivate",
          cost: [C],
          damage: 0,
          text: "Switch 1 of your opponent's Benched Pok\xE9mon with his or her Active Pok\xE9mon."
        },
        {
          name: "Psychic",
          cost: [W, C],
          damage: 30,
          damageCalculation: "+",
          text: "This attack does 10 more damage for each Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "PRC";
      this.setNumber = "51";
      this.cardImage = "assets/cardback.png";
      this.name = "Gorebyss";
      this.fullName = "Gorebyss PRC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          this.usedCaptivate = true;
        }
      }
      if (effect instanceof AfterAttackEffect && this.usedCaptivate) {
        this.usedCaptivate = false;
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        }
      }
      if (effect instanceof EndTurnEffect && this.usedCaptivate) {
        this.usedCaptivate = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        store.reduceEffect(state, checkEnergy);
        let energyCount = 0;
        checkEnergy.energyMap.forEach((em) => {
          energyCount += em.provides.length;
        });
        effect.damage += 10 * energyCount;
      }
      return state;
    }
  };

