  var Illumise2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 70;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Helping Hand",
          cost: [G],
          damage: 0,
          text: "Search your deck for a basic Energy card and attach it to 1 of your Benched Pok\xE9mon. Shuffle your deck afterward."
        },
        {
          name: "Twirling Sign",
          cost: [C],
          damage: 10,
          text: "Your opponent's Active Pok\xE9mon is now Confused."
        }
      ];
      this.set = "PRC";
      this.setNumber = "18";
      this.cardImage = "assets/cardback.png";
      this.name = "Illumise";
      this.fullName = "Illumise PRC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        if (!player.bench.some((b) => b.cards.length > 0)) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.deck,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { allowCancel: true, min: 0, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
          }
          SHUFFLE_DECK(store, state, player);
        });
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

