  var Ludicolo4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Lombre";
      this.cardType = [G];
      this.hp = 130;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.CAPTIVATING_RHYTHM_MARKER = "LUDICOLO_CAPTIVATING_RHYTHM_MARKER";
      this.powers = [{
        name: "Captivating Rhythm",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may flip a coin. If heads, switch 1 of your opponent's Benched Pok\xE9mon with his or her Active Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Solar Ray",
        cost: [G, C, C],
        damage: 80,
        text: "Heal 20 damage from each of your Pok\xE9mon."
      }];
      this.set = "PRC";
      this.setNumber = "12";
      this.cardImage = "assets/cardback.png";
      this.name = "Ludicolo";
      this.fullName = "Ludicolo PRC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        if (!opponent.bench.some((b) => b.cards.length > 0)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.CAPTIVATING_RHYTHM_MARKER, this);
        ABILITY_USED(player, this);
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.CAPTIVATING_RHYTHM_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.damage > 0) {
            const healEffect = new HealEffect(player, cardList, 20);
            store.reduceEffect(state, healEffect);
          }
        });
      }
      return state;
    }
  };

