  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-primal-clash/manaphy.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_shuffle_prompt();
  init_prefabs();
  var Manaphy3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 70;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Deep Sea Swirl",
          cost: [W],
          damage: 0,
          text: "Shuffle your hand into your deck. Then, draw 6 cards."
        },
        {
          name: "Life Saver",
          cost: [W],
          damage: 0,
          text: "Put 2 Water Pok\xE9mon from your discard pile into your hand."
        }
      ];
      this.set = "PRC";
      this.setNumber = "56";
      this.cardImage = "assets/cardback.png";
      this.name = "Manaphy";
      this.fullName = "Manaphy PRC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cardsToShuffle = player.hand.cards.slice();
        MOVE_CARDS(store, state, player.hand, player.deck, { cards: cardsToShuffle, sourceCard: this });
        return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
          player.deck.applyOrder(order);
          DRAW_CARDS(store, state, player, 6);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const blocked = [];
        let waterPokemonCount = 0;
        player.discard.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || !pokemonHasCardType(card, 3 /* WATER */)) {
            blocked.push(index);
          } else {
            waterPokemonCount++;
          }
        });
        if (waterPokemonCount === 0) {
          return state;
        }
        const count = Math.min(2, waterPokemonCount);
        SEARCH_DISCARD_PILE_FOR_CARDS_TO_HAND(
          store,
          state,
          player,
          this,
          { superType: 1 /* POKEMON */ },
          { min: count, max: 2, allowCancel: false, blocked }
        );
      }
      return state;
    }
  };

