  var Manectric3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Electrike";
      this.cardType = [L];
      this.hp = 100;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C];
      this.usedLightningTurn = false;
      this.attacks = [
        {
          name: "Lightning Turn",
          cost: [L, C],
          damage: 30,
          text: "Switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Electric Shock",
          cost: [L, L, C],
          damage: 70,
          text: "Discard all [L] Energy attached to this Pok\xE9mon. Your opponent's Active Pok\xE9mon is now Paralyzed."
        }
      ];
      this.set = "PRC";
      this.setNumber = "61";
      this.cardImage = "assets/cardback.png";
      this.name = "Manectric";
      this.fullName = "Manectric PRC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedLightningTurn = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedLightningTurn) {
        this.usedLightningTurn = false;
        const player = effect.player;
        if (player.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedLightningTurn = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergy);
        const cards = [];
        for (const energyMap of checkProvidedEnergy.energyMap) {
          if (energyMap.provides.some((t) => t === 4 /* LIGHTNING */ || t === 0 /* ANY */)) {
            cards.push(energyMap.card);
          }
        }
        if (cards.length > 0) {
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = player.active;
          store.reduceEffect(state, discardEnergy2);
        }
        YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_PARALYZED(store, state, effect);
      }
      return state;
    }
  };

