  var Milotic5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Feebas";
      this.cardType = [3 /* WATER */];
      this.hp = 110;
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Sparkling Ripples",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon, you may put a card from your discard pile into your hand."
      }];
      this.attacks = [
        {
          name: "Aqua Swirl",
          cost: [3 /* WATER */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 60,
          text: "You may have your opponent switch his or her Active Pok\xE9mon with 1 of his or her Benched Pok\xE9mon."
        }
      ];
      this.set = "PRC";
      this.name = "Milotic";
      this.fullName = "Milotic PRC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "44";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.deck.cards.length === 0) {
          return state;
        }
        const discardEffect = new DiscardToHandEffect(player, this);
        store.reduceEffect(state, discardEffect);
        if (discardEffect.preventDefault) {
          MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [effect.pokemonCard], sourceCard: this });
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            state = store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_HAND,
              player.discard,
              {},
              { min: 0, max: 1, allowCancel: false }
            ), (selected) => {
              const cards = selected || [];
              MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: this });
              store.prompt(state, [new ShowCardsPrompt(
                opponent.id,
                GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                cards
              )], () => {
              });
            });
          }
        });
      }
      if (effect instanceof AfterDamageEffect && effect.attack === this.attacks[0]) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (hasBench === false) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            return store.prompt(state, new ChoosePokemonPrompt(
              opponent.id,
              GameMessage.CHOOSE_POKEMON_TO_SWITCH,
              2 /* BOTTOM_PLAYER */,
              [2 /* BENCH */],
              { allowCancel: false }
            ), (targets) => {
              if (targets && targets.length > 0) {
                opponent.active.clearEffects();
                opponent.switchPokemon(targets[0]);
                return state;
              }
            });
          }
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-primal-clash/mr-mime.ts
  init_pokemon_card();
