  var MrMime6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [Y];
      this.hp = 80;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Trick",
          cost: [C],
          damage: 0,
          text: "Move a Pok\xE9mon Tool card attached to 1 of either player's Pok\xE9mon to another of that player's Pok\xE9mon that doesn't already have a Pok\xE9mon Tool attached to it. If there is no Pok\xE9mon to move the Pok\xE9mon Tool card to, this attack does nothing."
        },
        {
          name: "Lock Up",
          cost: [Y, C],
          damage: 30,
          text: "The Defending Pok\xE9mon can't retreat during your opponent's next turn."
        }
      ];
      this.set = "PRC";
      this.setNumber = "101";
      this.cardImage = "assets/cardback.png";
      this.name = "Mr. Mime";
      this.fullName = "Mr. Mime PRC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let canMovePlayer = false;
        let canMoveOpponent = false;
        let playerToolCount = 0;
        let playerNoToolCount = 0;
        let opponentToolCount = 0;
        let opponentNoToolCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.tools.length > 0) {
            playerToolCount++;
          } else {
            playerNoToolCount++;
          }
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          if (cardList.tools.length > 0) {
            opponentToolCount++;
          } else {
            opponentNoToolCount++;
          }
        });
        canMovePlayer = playerToolCount > 0 && playerNoToolCount > 0;
        canMoveOpponent = opponentToolCount > 0 && opponentNoToolCount > 0;
        if (!canMovePlayer && !canMoveOpponent) {
          return state;
        }
        const moveToolFromSide = (sidePlayer, sidePlayerType) => {
          const blockedSources = [];
          sidePlayer.forEachPokemon(sidePlayerType, (cardList, _card, target) => {
            if (cardList.tools.length === 0) {
              blockedSources.push(target);
            }
          });
          store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON,
            sidePlayerType,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false, blocked: blockedSources }
          ), (sourceTargets) => {
            if (!sourceTargets || sourceTargets.length === 0) {
              return;
            }
            const source = sourceTargets[0];
            const tool = source.tools[0];
            const blockedDest = [];
            sidePlayer.forEachPokemon(sidePlayerType, (cardList, _card, target) => {
              if (cardList.tools.length > 0 || cardList === source) {
                blockedDest.push(target);
              }
            });
            store.prompt(state, new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON,
              sidePlayerType,
              [1 /* ACTIVE */, 2 /* BENCH */],
              { min: 1, max: 1, allowCancel: false, blocked: blockedDest }
            ), (destTargets) => {
              if (!destTargets || destTargets.length === 0) {
                return;
              }
              const dest = destTargets[0];
              const toolIdx = source.tools.indexOf(tool);
              if (toolIdx !== -1) {
                source.tools.splice(toolIdx, 1);
              }
              MOVE_CARDS(store, state, source, dest, { cards: [tool], sourceCard: this });
              const cardIdx = dest.cards.indexOf(tool);
              if (cardIdx !== -1) {
                dest.cards.splice(cardIdx, 1);
              }
              dest.tools.push(tool);
            });
          });
        };
        if (canMovePlayer && canMoveOpponent) {
          SELECT_PROMPT(store, state, player, ["Your Pok\xE9mon", "Opponent's Pok\xE9mon"], (choice) => {
            if (choice === 0) {
              moveToolFromSide(player, 2 /* BOTTOM_PLAYER */);
            } else {
              moveToolFromSide(opponent, 1 /* TOP_PLAYER */);
            }
          });
        } else if (canMovePlayer) {
          moveToolFromSide(player, 2 /* BOTTOM_PLAYER */);
        } else {
          moveToolFromSide(opponent, 1 /* TOP_PLAYER */);
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        BLOCK_RETREAT(store, state, effect, this);
      }
      return state;
    }
  };

