  var Ninetales6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Vulpix";
      this.cardType = [R];
      this.hp = 90;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.powers = [{
        name: "Barrier Shrine",
        powerType: 2 /* ABILITY */,
        text: "Each player can't play any Stadium cards from his or her hand."
      }];
      this.attacks = [
        {
          name: "Flickering Flames",
          cost: [R, R, C],
          damage: 70,
          text: "Your opponent's Active Pok\xE9mon is now Asleep."
        }
      ];
      this.set = "PRC";
      this.setNumber = "21";
      this.cardImage = "assets/cardback.png";
      this.name = "Ninetales";
      this.fullName = "Ninetales PRC";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayStadiumEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let ninetalesInPlay = false;
        let ninetalesOwner = null;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            ninetalesInPlay = true;
            ninetalesOwner = player;
          }
        });
        if (!ninetalesInPlay) {
          opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card) => {
            if (card === this) {
              ninetalesInPlay = true;
              ninetalesOwner = opponent;
            }
          });
        }
        if (ninetalesInPlay && ninetalesOwner) {
          if (IS_ABILITY_BLOCKED(store, state, ninetalesOwner, this)) {
            return state;
          }
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

