      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Rhydon";
      this.cardType = [F];
      this.hp = 150;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C, C];
      this.attacks = [{
        name: "Rock Shower",
        cost: [F, F, C],
        damage: 0,
        text: "Flip 3 coins. This attack does 20 damage times the number of heads to each of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }, {
        name: "Stone Edge",
        cost: [F, F, C, C],
        damage: 80,
        damageCalculation: "+",
        text: "Flip a coin. If heads, this attack does 40 more damage."
      }];
      this.set = "PRC";
      this.setNumber = "76";
      this.cardImage = "assets/cardback.png";
      this.name = "Rhyperior";
      this.fullName = "Rhyperior PRC";
