  var Rhyperior2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Rhydon";
      this.cardType = [F];
      this.hp = 160;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C, C];
      this.powers = [{
        name: "Rock Wall",
        powerType: 2 /* ABILITY */,
        text: "Any damage done to your Pok\xE9mon by an opponent's attack is reduced by 10 (after applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Hammer Arm",
          cost: [F, F, C, C],
          damage: 100,
          text: "Discard the top card of your opponent's deck."
        }
      ];
      this.set = "PRC";
      this.setNumber = "77";
      this.cardImage = "assets/cardback.png";
      this.name = "Rhyperior";
      this.fullName = "Rhyperior PRC 77";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect || effect instanceof PutDamageEffect) {
        const targetCard2 = effect.target.getPokemonCard();
        if (!targetCard2) {
          return state;
        }
        let targetOwner = null;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList === effect.target) {
              targetOwner = p;
            }
          });
        });
        if (!targetOwner) {
          return state;
        }
        let isInPlay = false;
        targetOwner.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            isInPlay = true;
          }
        });
        if (!isInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetOwner, this)) {
          return state;
        }
        const sourceOwner = effect.player;
        if (sourceOwner === targetOwner) {
          return state;
        }
        effect.damage = Math.max(0, effect.damage - 10);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        MOVE_CARDS(store, state, opponent.deck, opponent.discard, { count: 1, sourceCard: this, sourceEffect: effect });
      }
      return state;
    }
  };

