  var Sceptile3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Grovyle";
      this.cardType = [1 /* GRASS */];
      this.hp = 130;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Nurture and Heal",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may attach a [G] Energy card from your hand to 1 of your Pokemon. If you do, heal 30 damage form that Pokemon."
      }];
      this.attacks = [{
        name: "Jungle Edge",
        cost: [1 /* GRASS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
        damage: 70,
        text: ""
      }];
      this.set = "PRC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "8";
      this.name = "Sceptile";
      this.fullName = "Sceptile PRC";
      this.NURTURE_AND_HEAL_MARKER = "NURTURE_AND_HEAL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.NURTURE_AND_HEAL_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.NURTURE_AND_HEAL_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.hand,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Grass Energy" },
          { allowCancel: true, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            return state;
          }
          for (const transfer of transfers) {
            player.marker.addMarker(this.NURTURE_AND_HEAL_MARKER, this);
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.addBoardEffect(0 /* ABILITY_USED */);
              }
            });
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.hand, target, { cards: [transfer.card], sourceCard: this });
            const healEffect = new HealEffect(player, target, 30);
            state = store.reduceEffect(state, healEffect);
          }
        });
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.NURTURE_AND_HEAL_MARKER, this);
      }
      return state;
    }
  };

