  var Slugma4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [2 /* FIRE */];
      this.hp = 70;
      this.weakness = [{ type: 3 /* WATER */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Grass Fire",
          cost: [2 /* FIRE */],
          damage: 0,
          text: " Discard a [G] Energy attached to your opponent's Active Pok\xE9mon."
        },
        {
          name: "Ram",
          cost: [2 /* FIRE */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 30,
          text: ""
        }
      ];
      this.set = "PRC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "22";
      this.name = "Slugma";
      this.fullName = "Slugma PRC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!opponent.active.cards.some((c) => c.superType === 3 /* ENERGY */ && c.provides.includes(1 /* GRASS */)) && !opponent.active.cards.some((c) => c.superType === 3 /* ENERGY */ && c.provides.includes(0 /* ANY */))) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [1 /* GRASS */, 0 /* ANY */],
          { allowCancel: false }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = opponent.active;
          return store.reduceEffect(state, discardEnergy2);
        });
      }
      return state;
    }
  };

