  var Starmie3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Staryu";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Synchro Star",
          cost: [C],
          damage: 10,
          damageCalculation: "+",
          text: "If this Pok\xE9mon and your opponent's Active Pok\xE9mon have the same amount of Energy attached to them, this attack does 60 more damage."
        }
      ];
      this.set = "PRC";
      this.setNumber = "73";
      this.cardImage = "assets/cardback.png";
      this.name = "Starmie";
      this.fullName = "Starmie PRC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkPlayerEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkPlayerEnergy);
        let playerEnergyCount = 0;
        checkPlayerEnergy.energyMap.forEach((em) => {
          playerEnergyCount += em.provides.length;
        });
        const checkOpponentEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        store.reduceEffect(state, checkOpponentEnergy);
        let opponentEnergyCount = 0;
        checkOpponentEnergy.energyMap.forEach((em) => {
          opponentEnergyCount += em.provides.length;
        });
        if (playerEnergyCount === opponentEnergyCount) {
          effect.damage += 60;
        }
      }
      return state;
    }
  };

