  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-primal-clash/swampert-2.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_shuffle_prompt();
  init_card_list();
  init_prefabs();
  var Swampert22 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Marshtomp";
      this.cardType = [W];
      this.hp = 140;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Diving Search",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may search your deck for a card. Shuffle your deck, then put that card on top of it."
      }];
      this.attacks = [
        {
          name: "Hydro Pump",
          cost: [C, C, C],
          damage: 40,
          damageCalculation: "+",
          text: "This attack does 30 more damage for each [W] Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "PRC";
      this.setNumber = "36";
      this.cardImage = "assets/cardback.png";
      this.name = "Swampert";
      this.fullName = "Swampert PRC 36";
      this.DIVING_SEARCH_MARKER = "SWAMPERT2_DIVING_SEARCH_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.DIVING_SEARCH_MARKER, this);
        ABILITY_USED(player, this);
        let cards = [];
        const deckTop = new CardList();
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARDS_TO_PUT_ON_TOP_OF_THE_DECK,
          player.deck,
          {},
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          cards = selected || [];
        });
        MOVE_CARDS(store, state, player.deck, deckTop, { cards, sourceCard: this });
        return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
          player.deck.applyOrder(order);
          if (order === null) {
            return state;
          }
          deckTop.applyOrder(order);
          deckTop.moveToTopOfDestination(player.deck);
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.DIVING_SEARCH_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(effect.player, effect.player.active);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const totalWaterEnergy = checkProvidedEnergy.energyMap.reduce((sum, em) => {
          return sum + em.provides.filter((type) => type === 3 /* WATER */ || type === 0 /* ANY */).length;
        }, 0);
        effect.damage += totalWaterEnergy * 30;
      }
      return state;
    }
  };

