  function* playCard100(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: effect.trainerCard
    });
    const playerPokemonNames = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (_cardList, card) => {
      if (!playerPokemonNames.includes(card.name)) {
        playerPokemonNames.push(card.name);
      }
    });
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (card instanceof PokemonCard && !playerPokemonNames.includes(card.name)) {
        blocked.push(index);
      }
    });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 1 /* POKEMON */ },
        { min: 1, max: 1, allowCancel: true, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, {
      cards,
      sourceCard: effect.trainerCard
    });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
