  init_state_utils();
  init_state();
  function* playCard101(next, store, state, self, effect) {
    const player = effect.player;
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    if (!player.marker.hasMarker(self.TEAMMATES_MARKER)) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [self], sourceCard: self });
    effect.preventDefault = true;
    let cards = [];
    return store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        {},
        { min: 1, max: Math.min(2, player.deck.cards.length), allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
        MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
        return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
          player.deck.applyOrder(order);
        });
      }
    );
  }
  var Teammates = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "PRC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "141";
      this.name = "Teammates";
      this.fullName = "Teammates PRC";
      this.text = `You can play this card only if 1 of your Pok\xE9mon was Knocked Out during your opponent's last turn.

Search your deck for up to 2 cards and put them into your hand. Shuffle your deck afterward.`;
      this.TEAMMATES_MARKER = "TEAMMATES_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard101(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const duringTurn = [2 /* PLAYER_TURN */, 3 /* ATTACK */].includes(state.phase);
        if (!duringTurn || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) {
          effect.player.marker.addMarker(this.TEAMMATES_MARKER, this);
        }
        return state;
      }
      REMOVE_OPPONENT_LAST_TURN_MARKER_AT_END_OF_TURN(effect, this.TEAMMATES_MARKER, this);
      return state;
    }
  };

