  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-burning-shadows/wicke.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_prefabs();
  var Wicke = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "BUS";
      this.setNumber = "127";
      this.cardImage = "assets/cardback.png";
      this.name = "Wicke";
      this.fullName = "Wicke BUS";
      this.text = "Each player counts the cards in their hand, shuffles those cards into their deck, then draws that many cards. You may play only 1 Supporter card during your turn (before your attack).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const playerHandCount = player.hand.cards.filter((c) => c !== this).length;
        const opponentHandCount = opponent.hand.cards.length;
        const playerCards = player.hand.cards.filter((c) => c !== this);
        MOVE_CARDS(store, state, player.hand, player.deck, { cards: playerCards, sourceCard: this });
        store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
          player.deck.applyOrder(order);
        });
        DRAW_CARDS(store, state, player, Math.min(playerHandCount, player.deck.cards.length));
        const opponentCards = opponent.hand.cards.slice();
        MOVE_CARDS(store, state, opponent.hand, opponent.deck, {
          cards: opponentCards,
          sourceCard: this
        });
        store.prompt(state, new ShuffleDeckPrompt(opponent.id), (order) => {
          opponent.deck.applyOrder(order);
        });
        DRAW_CARDS(store, state, opponent, Math.min(opponentHandCount, opponent.deck.cards.length));
      }
      return state;
    }
  };

