  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-guardians-rising/multi-switch.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_prefabs();
  var MultiSwitch = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "GRI";
      this.setNumber = "129";
      this.cardImage = "assets/cardback.png";
      this.name = "Multi Switch";
      this.fullName = "Multi Switch GRI";
      this.text = "Move an Energy from 1 of your Benched Pok\xE9mon to your Active Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        let hasEnergy = false;
        player.bench.forEach((b) => {
          if (b.cards.length > 0 && b.cards.some((c) => c.superType === 3 /* ENERGY */)) {
            hasEnergy = true;
          }
        });
        if (!hasEnergy) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (target.slot === 1 /* ACTIVE */) {
            blockedMap.push({
              source: target,
              blocked: Array.from({ length: cardList.cards.length }, (_, i) => i)
            });
          }
        });
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (target.slot !== 1 /* ACTIVE */) {
            blockedTo.push(target);
          }
        });
        return store.prompt(
          state,
          new MoveEnergyPrompt(
            player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 1, max: 1, blockedMap, blockedTo }
          ),
          (transfers) => {
            if (transfers && transfers.length > 0) {
              for (const transfer of transfers) {
                const source = StateUtils.getTarget(state, player, transfer.from);
                MOVE_CARDS(store, state, source, player.active, {
                  cards: [transfer.card],
                  sourceCard: this
                });
              }
            }
          }
        );
      }
      return state;
    }
  };

