  var MGardevoirEx2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["EX" /* POKEMON_EX */, "Mega EX" /* MEGA */];
      this.stage = 9 /* MEGA */;
      this.evolvesFrom = "Gardevoir-EX";
      this.cardType = [Y];
      this.hp = 210;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Brilliant Arrow",
          cost: [Y, C, C],
          damage: 30,
          damageCalculation: "x",
          text: "This attack does 30 damage times the amount of [Y] Energy attached to all of your Pok\xE9mon."
        }
      ];
      this.set = "PRC";
      this.name = "M Gardevoir-EX";
      this.fullName = "M Gardevoir-EX2 PRC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "106";
    }
    reduceEffect(store, state, effect) {
      MEGA_EVOLUTION_END_TURN(store, state, effect, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let fairyEnergies = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (card) => {
          const goodEnergy = card.cards.filter(
            (card2) => card2.superType === 3 /* ENERGY */ && card2.name === "Fairy Energy"
          );
          fairyEnergies += goodEnergy.length;
        });
        effect.damage = fairyEnergies * 30;
      }
      return state;
    }
  };

