  var ArchiesAceInTheHole2 = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "PRC";
      this.name = "Archie's Ace in the Hole";
      this.fullName = "Archie's Ace in the Hole PRC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "124";
      this.text = "You can play this card only when it is the last card in your hand. Put a W Pokemon from your discard pile onto your Bench. Then, draw 5 cards.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const cards = player.hand.cards.filter((c) => c !== this);
        const hasPokemon = player.discard.cards.some((c) => {
          return c instanceof PokemonCard && pokemonHasCardType(c, 3 /* WATER */);
        });
        const slot = player.bench.find((b) => b.cards.length === 0);
        const hasEffect = hasPokemon && slot || player.deck.cards.length > 0;
        if (cards.length !== 0 || !hasEffect) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        if (!hasPokemon || slot === void 0) {
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 5, sourceCard: this });
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            player.discard,
            { superType: 1 /* POKEMON */, cardType: [3 /* WATER */] },
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            const cards2 = selected || [];
            MOVE_CARDS(store, state, player.discard, slot, { cards: cards2, sourceCard: this });
            slot.pokemonPlayedTurn = state.turn;
            MOVE_CARDS(store, state, player.deck, player.hand, { count: 5, sourceCard: this });
          }
        );
      }
      return state;
    }
  };

