  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-x-and-y/aromatisse.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_check_effects();
  var Aromatisse = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Spritzee";
      this.cardType = [Y];
      this.hp = 90;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Fairy Transfer",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "As often as you like during your turn (before your attack), you may move a [Y] Energy attached to 1 of your Pok\xE9mon to another of your Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Fairy Wind",
        cost: [Y, Y, C],
        damage: 60,
        text: ""
      }];
      this.set = "XY";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "93";
      this.name = "Aromatisse";
      this.fullName = "Aromatisse XY";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          const blockedCards = [];
          checkProvidedEnergy.energyMap.forEach((em) => {
            if (!em.provides.includes(10 /* FAIRY */) && !em.provides.includes(0 /* ANY */)) {
              blockedCards.push(em.card);
            }
          });
          const blocked = [];
          blockedCards.forEach((bc) => {
            const index = cardList.cards.indexOf(bc);
            if (index !== -1 && !blocked.includes(index)) {
              blocked.push(index);
            }
          });
          if (blocked.length !== 0) {
            blockedMap.push({ source: target, blocked });
          }
        });
        store.prompt(state, new MoveEnergyPrompt(
          effect.player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          {},
          { allowCancel: true, blockedMap }
        ), (transfers) => {
          if (transfers === null) {
            return;
          }
          for (const transfer of transfers) {
            const source = StateUtils.getTarget(state, player, transfer.from);
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

