  var BlastoiseEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.usedRapidSpin = false;
      this._tags = ["EX" /* POKEMON_EX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 180;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Rapid Spin",
          cost: [C, C],
          damage: 30,
          text: "Switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon. Then, your opponent switches his or her Active Pok\xE9mon with 1 of his or her Benched Pok\xE9mon."
        },
        {
          name: "Splash Bomb",
          cost: [W, W, W],
          damage: 120,
          text: "Flip a coin. If tails, this Pok\xE9mon does 30 damage to itself."
        }
      ];
      this.set = "XY";
      this.setNumber = "29";
      this.cardImage = "assets/cardback.png";
      this.name = "Blastoise-EX";
      this.fullName = "Blastoise-EX XY";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedRapidSpin = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedRapidSpin) {
        this.usedRapidSpin = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
        }
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedRapidSpin = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (!result) {
            THIS_POKEMON_DOES_DAMAGE_TO_ITSELF(store, state, effect, 30);
          }
        });
      }
      return state;
    }
  };

