  var Braixen = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Fennekin";
      this.cardType = [2 /* FIRE */];
      this.hp = 80;
      this.weakness = [{ type: 3 /* WATER */ }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Clairvoyant Eye",
          cost: [9 /* COLORLESS */],
          damage: 0,
          text: "Look at the top 3 cards of your deck and put them back on top of your deck in any order."
        },
        {
          name: "Fire Tail Slap",
          cost: [2 /* FIRE */, 9 /* COLORLESS */],
          damage: 40,
          text: "Discard a [R] energy attached to this Pokemon."
        }
      ];
      this.set = "XY";
      this.name = "Braixen";
      this.fullName = "Braixen XY";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "25";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: 3, sourceCard: this });
        return store.prompt(state, new OrderCardsPrompt(
          player.id,
          GameMessage.CHOOSE_CARDS_ORDER,
          deckTop,
          { allowCancel: false }
        ), (order) => {
          if (order === null) {
            return state;
          }
          deckTop.applyOrder(order);
          deckTop.moveToTopOfDestination(player.deck);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [2 /* FIRE */],
          { allowCancel: true }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          if (cards.length > 0) {
            const discardEnergy2 = new DiscardCardsEffect(effect, cards);
            discardEnergy2.target = player.active;
            return store.reduceEffect(state, discardEnergy2);
          }
        });
      }
      return state;
    }
  };

