  var Delcatty6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Skitty";
      this.cardType = [C];
      this.hp = 80;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [{
        name: "Energy Salon",
        cost: [C],
        damage: 0,
        text: "Search your deck for 3 different types of basic Energy cards, reveal them, and put them into your hand. Shuffle your deck afterward."
      }, {
        name: "Fake Out",
        cost: [C, C],
        damage: 30,
        text: "Flip a coin. If heads, your opponent's Active Pok\xE9mon is now Paralyzed."
      }];
      this.set = "XY";
      this.setNumber = "105";
      this.cardImage = "assets/cardback.png";
      this.name = "Delcatty";
      this.fullName = "Delcatty XY";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const basicEnergyInDeck = player.deck.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        );
        if (basicEnergyInDeck.length === 0) {
          return SHUFFLE_DECK(store, state, player);
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (!(card instanceof EnergyCard) || card.energyType !== 0 /* BASIC */) {
            blocked.push(index);
          }
        });
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.deck,
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { min: 0, max: 3, allowCancel: false, blocked, differentTypes: true }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length > 0) {
            cards.forEach((card) => {
              MOVE_CARDS(store, state, player.deck, player.hand, { cards: [card], sourceCard: this });
            });
            store.prompt(state, new ShowCardsPrompt(
              opponent.id,
              GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
              cards
            ), () => {
            });
          }
          SHUFFLE_DECK(store, state, player);
        });
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            ADD_PARALYZED_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
          }
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-x-and-y/delphox.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_game_phase_effects();
  init_prefabs();
  var Delphox = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Braixen";
      this.cardType = [2 /* FIRE */];
      this.hp = 140;
      this.weakness = [{ type: 3 /* WATER */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Mystical Fire",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may draw cards until you have 6 cards in hand."
      }];
      this.attacks = [
        {
          name: "Blaze Ball",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 50,
          text: "This attack does 20 more damage for each [R] Energy attached to this Pokemon."
        }
      ];
      this.set = "XY";
      this.name = "Delphox";
      this.fullName = "Delphox XY";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "26";
      this.MYSTICAL_FIRE_MARKER = "MYSTICAL_FIRE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.MYSTICAL_FIRE_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.MYSTICAL_FIRE_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.MYSTICAL_FIRE_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.MYSTICAL_FIRE_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        while (player.hand.cards.length < 6) {
          if (player.deck.cards.length === 0) {
            break;
          }
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
        }
        player.marker.addMarker(this.MYSTICAL_FIRE_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const pokemon = player.active;
        let fireEnergyCount = 0;
        pokemon.cards.forEach((c) => {
          if (c instanceof EnergyCard) {
            if (c.energyType === 0 /* BASIC */ && c.name == "Fire Energy") {
              fireEnergyCount++;
            }
          }
        });
        effect.damage += fireEnergyCount * 20;
      }
      return state;
    }
  };

