  var Greninja = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Frogadier";
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Water Shuriken",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn (before your attack), you may discard a [W] Energy card from your hand. If you do, put 3 damage counters on 1 of your opponent's Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Mist Slash",
          cost: [W],
          damage: 50,
          shredAttack: true,
          text: "This attack's damage isn't affected by Weakness, Resistance, or any other effects on your opponent's Active Pok\xE9mon. "
        }
      ];
      this.set = "XY";
      this.setNumber = "41";
      this.cardImage = "assets/cardback.png";
      this.name = "Greninja";
      this.fullName = "Greninja XY";
      this.WATER_SHURIKEN_MARKER = "WATER_SHURIKEN_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.WATER_SHURIKEN_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.WATER_SHURIKEN_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        let waterInHand = false;
        player.hand.cards.forEach((card) => {
          if (card.superType === 3 /* ENERGY */ && card.name === "Water Energy") {
            waterInHand = true;
          }
        });
        if (!waterInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            { superType: 3 /* ENERGY */, name: "Water Energy" },
            { allowCancel: false, min: 1, max: 1 }
          ),
          (cards) => {
            cards = cards || [];
            player.marker.addMarker(this.WATER_SHURIKEN_MARKER, this);
            MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
            return store.prompt(
              state,
              new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
                1 /* TOP_PLAYER */,
                [1 /* ACTIVE */, 2 /* BENCH */],
                { allowCancel: false }
              ),
              (result) => {
                const target = result[0];
                target.damage += 30;
                return state;
              }
            );
          }
        );
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const applyWeakness = new ApplyWeaknessEffect(effect, 50);
        store.reduceEffect(state, applyWeakness);
        const damage = applyWeakness.damage;
        effect.damage = 0;
        if (damage > 0) {
          opponent.active.damage += damage;
          const afterDamage = new AfterDamageEffect(effect, damage);
          state = store.reduceEffect(state, afterDamage);
        }
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.WATER_SHURIKEN_MARKER, this)) {
        effect.player.marker.removeMarker(this.WATER_SHURIKEN_MARKER, this);
      }
      return state;
    }
  };

