  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-x-and-y/inkay.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects2();
  var Inkay = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.UPSIDE_DOWN_EVOLUTION_MARKER = "INKAY_UPSIDE_DOWN_EVOLUTION_MARKER";
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 60;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Upside-Down Evolution",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, (before your attack), if this Pok\xE9mon is Confused, you may search your deck for a card that evolves from this Pok\xE9mon and put it onto this Pok\xE9mon. (This counts as evolving this Pok\xE9mon.) Shuffle your deck afterward."
      }];
      this.attacks = [
        {
          name: "Confusion Wave",
          cost: [D],
          damage: 0,
          text: "Both Active Pok\xE9mon are now Confused."
        }
      ];
      this.set = "XY";
      this.setNumber = "74";
      this.cardImage = "assets/cardback.png";
      this.name = "Inkay";
      this.fullName = "Inkay XY";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        if (cardList !== player.active) {
          return state;
        }
        if (!player.active.specialConditions.includes(1 /* CONFUSED */)) {
          return state;
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.UPSIDE_DOWN_EVOLUTION_MARKER, this);
        ABILITY_USED(player, this);
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || card.evolvesFrom !== "Inkay") {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_EVOLVE,
          player.deck,
          { superType: 1 /* POKEMON */ },
          { min: 0, max: 1, allowCancel: true, blocked }
        ), (cards) => {
          if (cards && cards.length > 0) {
            const evolutionCard = cards[0];
            MOVE_CARDS(store, state, player.deck, cardList, { cards: [evolutionCard], sourceCard: this });
            cardList.clearEffects();
            cardList.pokemonPlayedTurn = state.turn;
          }
          SHUFFLE_DECK(store, state, player);
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.UPSIDE_DOWN_EVOLUTION_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_CONFUSED(store, state, effect);
        ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, player, this);
      }
      return state;
    }
  };

