  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-x-and-y/lapras.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_energy_card();
  init_check_effects();
  init_play_card_action();
  init_prefabs();
  var Lapras6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 110;
      this.weakness = [{ type: M }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Seafaring",
        cost: [W],
        damage: 0,
        text: "Flip 3 coins. For each heads, attach a [W] Energy card from your discard pile to your Benched Pok\xE9mon in any way you like."
      }, {
        name: "Hydro Pump",
        cost: [C, C],
        damage: 10,
        damageCalculation: "+",
        text: "This attack does 20 more damage for each [W] Energy attached to this Pok\xE9mon."
      }];
      this.set = "XY";
      this.setNumber = "35";
      this.cardImage = "assets/cardback.png";
      this.name = "Lapras";
      this.fullName = "Lapras XY";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          const heads = results.filter((r) => r).length;
          if (heads === 0) {
            return;
          }
          const waterEnergyInDiscard = player.discard.cards.filter(
            (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(3 /* WATER */)
          );
          if (waterEnergyInDiscard.length === 0) {
            return;
          }
          const maxAttach = Math.min(heads, waterEnergyInDiscard.length);
          store.prompt(state, new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
            { allowCancel: false, min: 0, max: maxAttach }
          ), (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let waterEnergyCount = 0;
        checkProvidedEnergyEffect.energyMap.forEach((em) => {
          waterEnergyCount += em.provides.filter((cardType) => cardType === 3 /* WATER */).length;
        });
        effect.damage += waterEnergyCount * 20;
      }
      return state;
    }
  };

