  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-x-and-y/magcargo.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_energy_card();
  init_prefabs();
  var Magcargo3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Slugma";
      this.cardType = [R];
      this.hp = 110;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Magma Mantle",
          cost: [R, C],
          damage: 30,
          damageCalculation: "+",
          text: "You may discard the top card of your deck. If that card is a [R] Energy card, this attack does 50 more damage."
        },
        {
          name: "Heat Blast",
          cost: [R, R, C],
          damage: 80,
          text: ""
        }
      ];
      this.set = "XY";
      this.setNumber = "21";
      this.cardImage = "assets/cardback.png";
      this.name = "Magcargo";
      this.fullName = "Magcargo XY";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        CONFIRMATION_PROMPT(store, state, player, (result) => {
          if (result) {
            const topOfDeck = new CardList();
            MOVE_CARDS(store, state, player.deck, topOfDeck, { count: 1, sourceCard: this });
            const topCard = topOfDeck.cards[0];
            if (topCard instanceof EnergyCard && topCard.provides.includes(2 /* FIRE */)) {
              effect.damage += 50;
            }
            MOVE_CARDS(store, state, topOfDeck, player.discard, { sourceCard: this });
          }
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-x-and-y/malamar.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects2();
  var Malamar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Inkay";
      this.cardType = [D];
      this.hp = 100;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.attacks = [{
        name: "Mental Trash",
        cost: [D],
        damage: 0,
        text: "Your opponent flips 4 coins. For each tails, he or she discards a card from his or her hand."
      }, {
        name: "Distortion Beam",
        cost: [D, C, C],
        damage: 30,
        text: "Flip a coin. If heads, your opponent's Active Pok\xE9mon is now Asleep. If tails, your opponent's Active Pok\xE9mon is now Confused."
      }];
      this.set = "XY";
      this.setNumber = "76";
      this.cardImage = "assets/cardback.png";
      this.name = "Malamar";
      this.fullName = "Malamar XY";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, opponent, 4, (results) => {
          const tails = results.filter((r) => !r).length;
          if (tails === 0 || opponent.hand.cards.length === 0) {
            return;
          }
          const discardCount = Math.min(tails, opponent.hand.cards.length);
          let cards = [];
          store.prompt(state, new ChooseCardsPrompt(
            opponent,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.hand,
            {},
            { min: discardCount, max: discardCount, allowCancel: false }
          ), (selected) => {
            cards = selected || [];
            MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards });
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_ASLEEP(store, state, effect);
          } else {
            YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_CONFUSED(store, state, effect);
          }
        });
      }
      return state;
    }
  };

