  var MrMime7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [Y];
      this.hp = 80;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Massage",
        cost: [Y, C],
        damage: 0,
        text: "Heal 60 damage from 1 of your Benched Pok\xE9mon."
      }, {
        name: "Slap Down",
        cost: [Y, C, C],
        damage: 40,
        damageCalculation: "+",
        text: "Flip 2 coins. This attack does 20 more damage for each heads."
      }];
      this.set = "XY";
      this.setNumber = "91";
      this.cardImage = "assets/cardback.png";
      this.name = "Mr. Mime";
      this.fullName = "Mr. Mime XY";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBenchedWithDamage = player.bench.some((b) => b.cards.length > 0 && b.damage > 0);
        if (!hasBenchedWithDamage) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_HEAL,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (targets) => {
          if (targets && targets.length > 0) {
            const healEffect = new HealEffect(player, targets[0], 60);
            store.reduceEffect(state, healEffect);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          const heads = results.filter((r) => r).length;
          effect.damage += 20 * heads;
        });
      }
      return state;
    }
  };

