  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_effects();
  init_prefabs();
  var Spritzee2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [Y];
      this.hp = 50;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Sweet Scent",
          cost: [Y],
          damage: 0,
          text: "Heal 20 damage from 1 of your Pok\xE9mon."
        },
        {
          name: "Flop",
          cost: [C, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "XY";
      this.name = "Spritzee";
      this.fullName = "Spritzee XY";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "92";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blocked = [];
        let hasPokemonWithDamage = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.damage === 0) {
            blocked.push(target);
          } else {
            hasPokemonWithDamage = true;
          }
        });
        if (hasPokemonWithDamage === false) {
          return state;
        }
        effect.preventDefault = true;
        let targets = [];
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_HEAL,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false, blocked }
        ), (results) => {
          targets = results || [];
          if (targets.length === 0) {
            return state;
          }
          targets.forEach((target) => {
            const healEffect = new HealEffect(player, target, 20);
            store.reduceEffect(state, healEffect);
          });
          return state;
        });
      }
      return state;
    }
  };

