  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_attack_effects();
  init_prefabs();
  var Talonflame2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Fletchinder";
      this.cardType = [R];
      this.hp = 130;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Devastating Wind",
          cost: [C],
          damage: 0,
          text: "Your opponent shuffles his or her hand into his or her deck and draws 4 cards."
        },
        {
          name: "Flare Blitz",
          cost: [R, R],
          damage: 100,
          text: "Discard all [R] Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "XY";
      this.setNumber = "28";
      this.cardImage = "assets/cardback.png";
      this.name = "Talonflame";
      this.fullName = "Talonflame XY";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        const cardsInHand = [...opponent.hand.cards];
        MOVE_CARDS(store, state, opponent.hand, opponent.deck, { cards: cardsInHand, sourceCard: this });
        return store.prompt(state, new ShuffleDeckPrompt(opponent.id), (order) => {
          opponent.deck.applyOrder(order);
          MOVE_CARDS(store, state, opponent.deck, opponent.hand, { count: 4, sourceCard: this });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergy);
        const cards = [];
        for (const energyMap of checkProvidedEnergy.energyMap) {
          const hasFireEnergy = energyMap.provides.some((t) => t === 2 /* FIRE */ || t === 0 /* ANY */);
          if (hasFireEnergy) {
            cards.push(energyMap.card);
          }
        }
        if (cards.length > 0) {
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = player.active;
          store.reduceEffect(state, discardEnergy2);
        }
      }
      return state;
    }
  };

