  function* playCard106(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const cm = CardManager.getInstance();
    const evolutions = cm.getAllCards().filter((c) => {
      return c instanceof PokemonCard && c.stage !== 2 /* BASIC */;
    });
    const evolutionNames = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
      if (list.pokemonPlayedTurn >= state.turn) {
        return;
      }
      const valid = evolutions.filter((e) => e.evolvesFrom === card.name);
      valid.forEach((c) => {
        if (!evolutionNames.includes(c.name)) {
          evolutionNames.push(c.name);
        }
      });
    });
    if (evolutionNames.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (card instanceof PokemonCard && !evolutionNames.includes(card.name)) {
        blocked.push(index);
      }
    });
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_EVOLVE,
        player.deck,
        { superType: 1 /* POKEMON */ },
        { min: 0, max: 1, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    const evolution = cards[0];
    const blocked2 = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
      if (card.name !== evolution.evolvesFrom || list.pokemonPlayedTurn === state.turn) {
        blocked2.push(target);
      }
    });
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_EVOLVE,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: false, blocked: blocked2 }
      ),
      (selection) => {
        targets = selection || [];
        next();
      }
    );
    if (targets.length === 0) {
      SHUFFLE_DECK(store, state, player);
      return state;
    }
    const pokemonCard = targets[0].getPokemonCard();
    if (pokemonCard === void 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.deck, targets[0], { cards: [evolution], sourceCard: effect.trainerCard });
    targets[0].clearEffects();
    targets[0].pokemonPlayedTurn = state.turn;
    SHUFFLE_DECK(store, state, player);
  }
  var Evosoda = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "XY";
      this.name = "Evosoda";
      this.fullName = "Evosoda XY";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "116";
      this.text = "Search your deck for a card that evolves from 1 of your Pok\xE9mon and put it onto that Pok\xE9mon. (This counts as evolving that Pok\xE9mon.) Shuffle your deck afterward. You can't use this card during your first turn or on a Pok\xE9mon that was put into play this turn.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard106(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

