  var Yveltal = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 130;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Oblivion Wing",
        cost: [D],
        damage: 30,
        text: "Attach a [D] Energy card from your discard pile to 1 of your Benched Pok\xE9mon."
      }, {
        name: "Darkness Blade",
        cost: [D, D, C],
        damage: 100,
        text: "Flip a coin. If tails, this Pok\xE9mon can't attack during your next turn."
      }];
      this.set = "STS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "65";
      this.name = "Yveltal";
      this.fullName = "Yveltal STS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.provides.includes(D);
        });
        if (!hasEnergyInDiscard) {
          return state;
        }
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, name: "Darkness Energy" },
          { allowCancel: false, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            return;
          }
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        return COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (!result) {
            const player = effect.player;
            player.active.cannotAttackNextTurnPending = true;
          }
        });
      }
      return state;
    }
  };

