  var RedCard = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "GEN";
      this.name = "Red Card";
      this.fullName = "Red Card GEN";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "71";
      this.text = "Your opponent shuffles his or her hand into his or her deck and draws 4 cards.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentCards = opponent.hand.cards.filter((c) => c !== this);
        if (opponentCards.length === 0 && opponent.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, opponent.hand, opponent.deck, {
          cards: opponentCards,
          sourceCard: this
        });
        store.prompt(state, new ShuffleDeckPrompt(opponent.id), (order) => {
          opponent.deck.applyOrder(order);
        });
        MOVE_CARDS(store, state, opponent.deck, opponent.hand, { count: 4, sourceCard: this });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-generations/team-flare-grunt.ts
  init_game();
  init_play_card_effects();
  init_trainer_target();
  init_prefabs();
  function* playCard108(next, store, state, effect, trainerCard) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const activeHasEnergy = opponent.active.cards.some((c) => c.superType === 3 /* ENERGY */);
    if (!activeHasEnergy) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    if (player.supporterTurn >= 1) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: effect.trainerCard
    });
    effect.preventDefault = true;
    const target = opponent.active;
    if (TRAINER_TARGET_BLOCKED(store, state, player, trainerCard, target)) {
      return state;
    }
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        target,
        { superType: 3 /* ENERGY */ },
        { min: 1, max: 1, allowCancel: false }
      ),
      (selected) => {
        cards = selected;
        next();
      }
    );
    MOVE_CARDS(store, state, target, opponent.discard, {
      cards,
      sourceCard: effect.trainerCard
    });
    return state;
  }
  var TeamFlareGrunt = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "GEN";
      this.name = "Team Flare Grunt";
      this.fullName = "Team Flare Grunt GEN";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "73";
      this.text = "Discard an Energy attached to your opponent's Active Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard108(() => generator.next(), store, state, effect, this);
        return generator.next().value;
      }
      return state;
    }
  };

