  var Bellossom4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Gloom";
      this.cardType = [G];
      this.hp = 120;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Windmill",
          cost: [G],
          damage: 20,
          text: "Switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Flower Tornado",
          cost: [G, C],
          damage: 60,
          text: "Move as many [G] Energy attached to your Pok\xE9mon to your other Pok\xE9mon in any way you like."
        }
      ];
      this.set = "AOR";
      this.setNumber = "4";
      this.cardImage = "assets/cardback.png";
      this.name = "Bellossom";
      this.fullName = "Bellossom AOR";
      this.usedWindmill = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedWindmill = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedWindmill) {
        this.usedWindmill = false;
        const player = effect.player;
        if (player.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedWindmill = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        let hasGrassEnergy = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.cards.some((c) => c instanceof EnergyCard && c.provides.includes(1 /* GRASS */))) {
            hasGrassEnergy = true;
          }
        });
        if (!hasGrassEnergy) {
          return state;
        }
        return store.prompt(state, new MoveEnergyPrompt(
          player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */, cardType: [1 /* GRASS */] },
          { allowCancel: true }
        ), (transfers) => {
          if (transfers === null) {
            return;
          }
          for (const transfer of transfers) {
            const source = StateUtils.getTarget(state, player, transfer.from);
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

