  init_pokemon_card();
  init_card_types();
  init_energy_card();
  init_game();
  init_attach_energy_prompt();
  init_play_card_effects();
  init_show_cards_prompt();
  init_prefabs();
  var Entei2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [R];
      this.hp = 120;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Burning Roar",
          cost: [C],
          damage: 0,
          text: "Discard the top 4 cards of your deck. If any of those cards are [R] Energy cards, attach them to your Pok\xE9mon in any way you like."
        },
        {
          name: "Combat Blaze",
          cost: [R, R],
          damage: 20,
          damageCalculation: "+",
          text: "This attack does 20 more damage for each of your opponent's Benched Pok\xE9mon."
        }
      ];
      this.set = "AOR";
      this.setNumber = "14";
      this.cardImage = "assets/cardback.png";
      this.name = "Entei";
      this.fullName = "Entei AOR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const cardsToDiscard = player.deck.cards.slice(0, 4);
        const fireEnergies = [];
        cardsToDiscard.forEach((card) => {
          if (card instanceof EnergyCard && card.energyType === 0 /* BASIC */ && card.provides.includes(2 /* FIRE */)) {
            fireEnergies.push(card);
            MOVE_CARDS(store, state, player.deck, player.hand, { cards: [card], sourceCard: this });
          } else {
            MOVE_CARDS(store, state, player.deck, player.discard, { cards: [card], sourceCard: this });
          }
        });
        store.prompt(state, [
          new ShowCardsPrompt(player.id, GameMessage.CARDS_SHOWED_BY_EFFECT, cardsToDiscard),
          new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cardsToDiscard)
        ], () => {
        });
        if (fireEnergies.length > 0) {
          const count = fireEnergies.length;
          store.prompt(state, new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.hand,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
            { min: count, max: count, allowCancel: false }
          ), (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              const energyCard = transfer.card;
              const attachEffect = new AttachEnergyEffect(player, energyCard, target);
              store.reduceEffect(state, attachEffect);
            }
            fireEnergies.forEach((card) => {
              if (player.hand.cards.includes(card)) {
                MOVE_CARDS(store, state, player.hand, player.discard, { cards: [card], sourceCard: this });
              }
            });
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const benchedCount = opponent.bench.reduce((count, b) => count + (b.cards.length > 0 ? 1 : 0), 0);
        effect.damage += 20 * benchedCount;
      }
      return state;
    }
  };

