  var Metagross4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Metang";
      this.cardType = [M];
      this.hp = 150;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C, C];
      this.MAGNETIC_WARP_MARKER = "METAGROSS_AOR_MAGNETIC_WARP_MARKER";
      this.powers = [{
        name: "Magnetic Warp",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may switch your Active Pok\xE9mon with 1 of your Benched Pok\xE9mon. If you do, your opponent switches his or her Active Pok\xE9mon with 1 of his or her Benched Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Iron Cannon",
          cost: [M, M, C, C],
          damage: 80,
          damageCalculation: "+",
          text: "You may discard all [M] Energy attached to this Pok\xE9mon. If you do, this attack does 80 more damage."
        }
      ];
      this.set = "AOR";
      this.setNumber = "49";
      this.cardImage = "assets/cardback.png";
      this.name = "Metagross";
      this.fullName = "Metagross AOR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        if (!player.bench.some((b) => b.cards.length > 0)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.MAGNETIC_WARP_MARKER, this);
        ABILITY_USED(player, this);
        SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        }
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.MAGNETIC_WARP_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkEnergy);
        const metalCards = [];
        for (const em of checkEnergy.energyMap) {
          if (em.card instanceof EnergyCard && em.provides.some((t) => t === 8 /* METAL */ || t === 0 /* ANY */)) {
            metalCards.push(em.card);
          }
        }
        if (metalCards.length > 0) {
          state = store.prompt(state, new ConfirmPrompt(
            player.id,
            GameMessage.WANT_TO_USE_ABILITY
          ), (wantToDiscard) => {
            if (wantToDiscard) {
              const discardEnergy2 = new DiscardCardsEffect(effect, metalCards);
              discardEnergy2.target = player.active;
              store.reduceEffect(state, discardEnergy2);
              effect.damage += 80;
            }
          });
        }
      }
      return state;
    }
  };

