  var Rotom4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 70;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C];
      this.attacks = [{
        name: "Electro Ball",
        cost: [L],
        damage: 20,
        text: ""
      }, {
        name: "Electric Mischief",
        cost: [C, C],
        damage: 0,
        text: "Flip 3 coins. For each heads, choose a random card from your opponent's hand. Your opponent reveals that card and shuffles it into his or her deck."
      }];
      this.set = "AOR";
      this.setNumber = "29";
      this.cardImage = "assets/cardback.png";
      this.name = "Rotom";
      this.fullName = "Rotom AOR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          const heads = results.filter((r) => r).length;
          const cardsToShuffle = Math.min(heads, opponent.hand.cards.length);
          if (cardsToShuffle > 0) {
            const shuffledCards = [];
            for (let i = 0; i < cardsToShuffle; i++) {
              if (opponent.hand.cards.length > 0) {
                const randomIndex = Math.floor(Math.random() * opponent.hand.cards.length);
                const randomCard = opponent.hand.cards[randomIndex];
                shuffledCards.push(randomCard);
                MOVE_CARDS(store, state, opponent.hand, opponent.deck, { cards: [randomCard], sourceCard: this });
              }
            }
            if (shuffledCards.length > 0) {
              SHOW_CARDS_TO_PLAYER(store, state, player, shuffledCards);
              SHUFFLE_DECK(store, state, opponent);
            }
          }
        });
      }
      return state;
    }
  };

