  var Volcarona4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Larvesta";
      this.cardType = [R];
      this.hp = 100;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Solar Birth",
          cost: [C],
          damage: 0,
          text: "Search your deck for a Basic Pok\xE9mon and put it onto your Bench. Then, search your deck for up to 2 basic Energy cards and attach them to that Pok\xE9mon. Shuffle your deck afterward."
        },
        {
          name: "Flamethrower",
          cost: [R, C],
          damage: 60,
          text: "Discard an Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "AOR";
      this.setNumber = "17";
      this.cardImage = "assets/cardback.png";
      this.name = "Volcarona";
      this.fullName = "Volcarona AOR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const slots2 = GET_PLAYER_BENCH_SLOTS(player);
        if (slots2.length === 0) {
          return state;
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard && card.stage === 2 /* BASIC */)) {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          player.deck,
          { superType: 1 /* POKEMON */ },
          { min: 0, max: 1, allowCancel: true, blocked }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length === 0) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          const pokemonCard = cards[0];
          const targetSlot = slots2[0];
          MOVE_CARDS(store, state, player.deck, targetSlot, { cards: [pokemonCard], sourceCard: this });
          targetSlot.pokemonPlayedTurn = state.turn;
          const hasBasicEnergy = player.deck.cards.some(
            (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
          );
          if (!hasBasicEnergy) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          const energyBlocked = [];
          player.deck.cards.forEach((card, index) => {
            if (!(card instanceof EnergyCard && card.energyType === 0 /* BASIC */)) {
              energyBlocked.push(index);
            }
          });
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_ATTACH,
            player.deck,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min: 0, max: 2, allowCancel: true, blocked: energyBlocked }
          ), (energySelected) => {
            const energyCards = energySelected || [];
            energyCards.forEach((card) => {
              MOVE_CARDS(store, state, player.deck, targetSlot, { cards: [card], sourceCard: this });
            });
            SHUFFLE_DECK(store, state, player);
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1);
      }
      return state;
    }
  };

