  var AceTrainer = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "AOR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "69";
      this.name = "Ace Trainer";
      this.fullName = "Ace Trainer AOR";
      this.text = "You can play this card only if you have more Prize cards left than your opponent.\n\nEach player shuffles his or her hand into his or her deck. Then, draw 6 cards. Your opponent draws 3 cards.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        if (player.getPrizeLeft() <= opponent.getPrizeLeft()) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const cards = player.hand.cards.filter((c) => c !== this);
        const playerMoveEffect = new MoveCardsEffect(player.hand, player.deck, {
          cards,
          sourceCard: this
        });
        state = store.reduceEffect(state, playerMoveEffect);
        const opponentMoveEffect = new MoveCardsEffect(opponent.hand, opponent.deck, {
          sourceCard: this
        });
        state = store.reduceEffect(state, opponentMoveEffect);
        if (!opponentMoveEffect.preventDefault) {
          SHUFFLE_DECK(store, state, opponent);
          DRAW_CARDS(store, state, opponent, 3);
        }
        SHUFFLE_DECK(store, state, player);
        DRAW_CARDS(store, state, player, 6);
      }
      return state;
    }
  };

