  init_game();
  init_game_error();
  init_game_message();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_choose_cards_prompt();
  init_prefabs();
  function* playCard111(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const toolCards = player.discard.cards.filter((c) => {
      return c instanceof TrainerCard && c.trainerType === 3 /* TOOL */;
    }).length;
    if (toolCards === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    const min = Math.min(3, toolCards);
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        { superType: 2 /* TRAINER */, trainerType: 3 /* TOOL */ },
        { min, max: 3, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length > 0) {
      MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
      if (cards.length > 0) {
        state = store.prompt(
          state,
          new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
          () => state
        );
      }
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var EcoArm = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "AOR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "71";
      this.name = "Eco Arm";
      this.fullName = "Eco Arm AOR";
      this.text = "Shuffle 3 Pok\xE9mon Tool cards from your discard pile into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard111(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

