  var DangerousEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [C];
      this.energyType = 1 /* SPECIAL */;
      this.set = "AOR";
      this.setNumber = "82";
      this.cardImage = "assets/cardback.png";
      this.name = "Dangerous Energy";
      this.fullName = "Dangerous Energy AOR";
      this.text = "This card can only be attached to Darkness Pok\xE9mon. This card provides [D] Energy only while this card is attached to a Darkness Pok\xE9mon. Whenever the Darkness Pok\xE9mon this card is attached to is your Active Pok\xE9mon and is damaged by an attack from your opponent's Pok\xE9mon-EX (even if that Pok\xE9mon is Knocked Out), put 2 damage counters on the Attacking Pok\xE9mon-EX. (If this card is attached to anything other than a Darkness Pok\xE9mon, discard this card.)";
    }
    // Refs: set-fusion-strike/fusion-strike-energy.ts (type-restricted energy), set-flashfire/qwilfish.ts (ON_DAMAGED_BY_OPPONENT_ATTACK retaliation)
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        const pokemon = effect.source;
        const pokemonCard = pokemon.getPokemonCard();
        if (pokemonCard && pokemonHasCardType(pokemonCard, 7 /* DARK */)) {
          const player = StateUtils.findOwner(state, effect.source);
          if (!IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, effect.source)) {
            effect.energyMap.push({ card: this, provides: [7 /* DARK */] });
          }
        }
      }
      if (effect instanceof AttachEnergyEffect && effect.energyCard === this) {
        const targetPokemon = effect.target.getPokemonCard();
        if (!targetPokemon || !pokemonHasCardType(targetPokemon, 7 /* DARK */)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
      }
      if (effect instanceof AfterDamageEffect && effect.target.cards.includes(this)) {
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        const attackingPlayer = effect.player;
        if (effect.damage <= 0 || attackingPlayer === targetPlayer) {
          return state;
        }
        if (targetPlayer.active !== effect.target) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, targetPlayer, this, effect.target)) {
          return state;
        }
        const attackerPokemon = effect.source.getPokemonCard();
        if (attackerPokemon && attackerPokemon.hasTag("EX" /* POKEMON_EX */)) {
          effect.source.damage += 20;
        }
      }
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (!cardList.cards.includes(this)) {
              return;
            }
            const pokemonCard = cardList.getPokemonCard();
            if (!pokemonCard || !pokemonHasCardType(pokemonCard, 7 /* DARK */)) {
              MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
            }
          });
        });
      }
      return state;
    }
  };

