  var FlashEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [];
      this.energyType = 1 /* SPECIAL */;
      this.set = "AOR";
      this.setNumber = "83";
      this.cardImage = "assets/cardback.png";
      this.name = "Flash Energy";
      this.fullName = "Flash Energy AOR";
      this.text = "This card can only be attached to Lightning Pok\xE9mon. This card provides [L] Energy only while this card is attached to a Lightning Pok\xE9mon. The Lightning Pok\xE9mon this card is attached to has no Weakness. (If this card is attached to anything other than a Lightning Pok\xE9mon, discard this card.)";
    }
    // Ref: set-furious-fists/strong-energy.ts (type-restricted special energy pattern)
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        const checkPokemonType = new CheckPokemonTypeEffect(effect.source);
        store.reduceEffect(state, checkPokemonType);
        if (checkPokemonType.cardTypes.includes(4 /* LIGHTNING */)) {
          effect.energyMap.push({ card: this, provides: [4 /* LIGHTNING */] });
        }
      }
      if (effect instanceof AttachEnergyEffect && effect.energyCard === this) {
        const checkPokemonType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkPokemonType);
        if (!checkPokemonType.cardTypes.includes(4 /* LIGHTNING */)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
      }
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (!cardList.cards.includes(this) || IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, cardList)) {
              return;
            }
            const checkPokemonType = new CheckPokemonTypeEffect(cardList);
            store.reduceEffect(state, checkPokemonType);
            if (!checkPokemonType.cardTypes.includes(4 /* LIGHTNING */)) {
              MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
            }
          });
        });
      }
      if (effect instanceof CheckPokemonStatsEffect) {
        const target = effect.target;
        if (!target.cards.includes(this)) {
          return state;
        }
        let owner = null;
        state.players.forEach((p) => {
          if (p.active === target || p.bench.includes(target)) {
            owner = p;
          }
        });
        if (!owner || IS_SPECIAL_ENERGY_BLOCKED(store, state, owner, this, target)) {
          return state;
        }
        const checkPokemonType = new CheckPokemonTypeEffect(target);
        store.reduceEffect(state, checkPokemonType);
        if (checkPokemonType.cardTypes.includes(4 /* LIGHTNING */)) {
          effect.weakness = [];
        }
      }
      return state;
    }
  };

