  function* playCard112(next, store, state, self, effect) {
    const player = effect.player;
    let energyInDiscard = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      const isBasicEnergy = c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
      if (isBasicEnergy) {
        energyInDiscard += 1;
      } else {
        blocked.push(index);
      }
    });
    if (energyInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { min: 1, max: 5, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
