  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-breakpoint/aegislash.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_game();
  init_prefabs();
  var Aegislash3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Doublade";
      this.cardType = [P];
      this.hp = 140;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Painful Sword",
          cost: [C, C, C],
          damage: 0,
          text: "Double the number of damage counters on each of your opponent's Pok\xE9mon."
        },
        {
          name: "Megaton Slash",
          cost: [P, P, C, C],
          damage: 100,
          text: "This attack does 10 damage to 2 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "BKP";
      this.setNumber = "62";
      this.cardImage = "assets/cardback.png";
      this.name = "Aegislash";
      this.fullName = "Aegislash BKP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.active.damage > 0) {
          const activeDamageEffect = new PutCountersEffect(effect, opponent.active.damage);
          activeDamageEffect.target = opponent.active;
          store.reduceEffect(state, activeDamageEffect);
        }
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          if (cardList !== opponent.active && cardList.cards.length > 0 && cardList.damage > 0) {
            const damageEffect = new PutCountersEffect(effect, cardList.damage);
            damageEffect.target = cardList;
            store.reduceEffect(state, damageEffect);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (hasBenched) {
          THIS_ATTACK_DOES_X_DAMAGE_TO_X_OF_YOUR_OPPONENTS_POKEMON(10, effect, store, state, 1, 2, false, [2 /* BENCH */]);
        }
      }
      return state;
    }
  };

