  init_pokemon_card();
  init_card_types();
  init_game();
  init_energy_card();
  init_prefabs();
  var Camerupt3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Numel";
      this.cardType = [R];
      this.hp = 130;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Ram",
          cost: [C, C],
          damage: 30,
          text: ""
        },
        {
          name: "Eruption",
          cost: [R, R, C],
          damage: 80,
          damageCalculation: "+",
          text: "Each player discards the top card of his or her deck. This attack does 60 more damage for each Energy card discarded in this way."
        }
      ];
      this.set = "BKP";
      this.setNumber = "13";
      this.cardImage = "assets/cardback.png";
      this.name = "Camerupt";
      this.fullName = "Camerupt BKP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let energyCount = 0;
        if (player.deck.cards.length > 0) {
          const card = player.deck.cards[0];
          if (card instanceof EnergyCard) {
            energyCount++;
          }
          MOVE_CARDS(store, state, player.deck, player.discard, { cards: [card], sourceCard: this });
        }
        if (opponent.deck.cards.length > 0) {
          const card = opponent.deck.cards[0];
          if (card instanceof EnergyCard) {
            energyCount++;
          }
          MOVE_CARDS(store, state, opponent.deck, opponent.discard, { cards: [card], sourceCard: this });
        }
        effect.damage += 60 * energyCount;
      }
      return state;
    }
  };

