  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_check_effects();
  init_prefabs();
  var Ferrothorn3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Ferroseed";
      this.cardType = [M];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Metal Claw",
          cost: [M, C],
          damage: 40,
          text: ""
        },
        {
          name: "Spike Lash",
          cost: [M, C, C],
          damage: 0,
          text: "This attack does 10 damage to each of your opponent's Pok\xE9mon for each Colorless in that Pok\xE9mon's Retreat Cost. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "BKP";
      this.setNumber = "80";
      this.cardImage = "assets/cardback.png";
      this.name = "Ferrothorn";
      this.fullName = "Ferrothorn BKP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkRetreatActive = new CheckRetreatCostEffect(opponent);
        store.reduceEffect(state, checkRetreatActive);
        const activeRetreatCost = checkRetreatActive.cost.filter((c) => c === 9 /* COLORLESS */).length;
        if (activeRetreatCost > 0) {
          const dealDamage = new DealDamageEffect(effect, 10 * activeRetreatCost);
          dealDamage.target = opponent.active;
          store.reduceEffect(state, dealDamage);
        }
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          if (cardList === opponent.active || cardList.cards.length === 0) {
            return;
          }
          const pokemonCard = cardList.getPokemonCard();
          const retreatCost = pokemonCard ? pokemonCard.retreat.length : 0;
          if (retreatCost > 0) {
            const putDamage = new PutDamageEffect(effect, 10 * retreatCost);
            putDamage.target = cardList;
            store.reduceEffect(state, putDamage);
          }
        });
      }
      return state;
    }
  };

