  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-breakpoint/golduck-break.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_energy_card();
  init_check_effects();
  init_prefabs();
  var GolduckBreak = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Break" /* BREAK */];
      this.stage = 10 /* BREAK */;
      this.evolvesFrom = "Golduck";
      this.cardType = [W];
      this.hp = 140;
      this.retreat = [];
      this.powers = [
        {
          name: "Hyper Transfer",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "As often as you like during your turn (before your attack), you may move a basic Energy from 1 of your Pok\xE9mon to another of your Pok\xE9mon."
        }
      ];
      this.set = "BKP";
      this.setNumber = "18";
      this.cardImage = "assets/cardback.png";
      this.name = "Golduck BREAK";
      this.fullName = "Golduck BREAK BKP";
    }
    // Ref: set-primal-clash/eelektross.ts (Energy Connect)
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        let hasBasicEnergy = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const checkEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkEnergy);
          if (checkEnergy.energyMap.some(
            (em) => em.card instanceof EnergyCard && em.card.energyType === 0 /* BASIC */
          )) {
            hasBasicEnergy = true;
          }
        });
        if (!hasBasicEnergy) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(
          state,
          new MoveEnergyPrompt(
            player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: true, min: 0, max: 1 }
          ),
          (transfers) => {
            if (transfers && transfers.length > 0) {
              for (const transfer of transfers) {
                const source = StateUtils.getTarget(state, player, transfer.from);
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
              }
              ABILITY_USED(player, this);
            }
          }
        );
      }
      BREAK_RULE(effect, state, this);
      return state;
    }
  };

