  var Greninja2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Frogadier";
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: G }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Shadow Stitching",
          cost: [C],
          damage: 40,
          text: "Until the end of your opponent's next turn, each Pok\xE9mon your opponent has in play, in his or her hand, and in his or her discard pile has no Abilities. (This includes cards that come into play on that turn.)"
        },
        {
          name: "Moonlight Slash",
          cost: [W],
          damage: 60,
          text: " You may return a [W] Energy from this Pok\xE9mon to your hand. If you do, this attack does 20 more damage."
        }
      ];
      this.set = "BKP";
      this.setNumber = "40";
      this.cardImage = "assets/cardback.png";
      this.name = "Greninja";
      this.fullName = "Greninja BKP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return OPPONENT_POKEMON_HAVE_NO_ABILITIES(store, state, effect, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
            state = store.reduceEffect(state, checkProvidedEnergy);
            state = store.prompt(state, new ChooseEnergyPrompt(
              player.id,
              GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
              checkProvidedEnergy.energyMap,
              [3 /* WATER */],
              { allowCancel: false }
            ), (energy2) => {
              const cards = (energy2 || []).map((e) => e.card);
              MOVE_CARDS(store, state, player.active, player.hand, { cards, sourceCard: this });
              effect.damage += 20;
            });
          }
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-breakpoint/greninja-break.ts
  init_game();
  init_card_types();
  init_pokemon_card();
  init_game_effects();
  init_prefabs();
  var GreninjaBREAK = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 10 /* BREAK */;
      this._tags = ["Break" /* BREAK */];
      this.evolvesFrom = "Greninja";
      this.cardType = [W];
      this.hp = 170;
      this.powers = [
        {
          name: "Giant Water Shuriken",
          powerType: 2 /* ABILITY */,
          useWhenInPlay: true,
          text: "Once during your turn (before your attack), if this Pok\xE9mon is your Active Pok\xE9mon, you may discard a [W] Energy card from your hand. If you do, put 6 damage counters on 1 of your opponent's Pok\xE9mon."
        }
      ];
      this.set = "BKP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "41";
      this.name = "Greninja BREAK";
      this.fullName = "Greninja BREAK BKP";
      this.GIANT_WATER_SHURIKEN_MARKER = "GIANT_WATER_SHURIKEN_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.GIANT_WATER_SHURIKEN_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        let waterInHand = false;
        player.hand.cards.forEach((card) => {
          if (card.superType === 3 /* ENERGY */ && card.name === "Water Energy") {
            waterInHand = true;
          }
        });
        if (!waterInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            { superType: 3 /* ENERGY */, name: "Water Energy" },
            { allowCancel: false, min: 1, max: 1 }
          ),
          (cards) => {
            cards = cards || [];
            player.marker.addMarker(this.GIANT_WATER_SHURIKEN_MARKER, this);
            MOVE_CARDS(store, state, player.hand, player.discard, {
              cards,
              sourceCard: this,
              sourceEffect: this.powers[1]
            });
            return store.prompt(
              state,
              new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
                1 /* TOP_PLAYER */,
                [2 /* BENCH */, 1 /* ACTIVE */],
                { min: 1, max: 1, allowCancel: false }
              ),
              (selected) => {
                const targets = selected || [];
                if (targets.length > 0) {
                  const damageEffect = new EffectOfAbilityEffect(
                    player,
                    this.powers[1],
                    this,
                    targets[0]
                  );
                  store.reduceEffect(state, damageEffect);
                  if (damageEffect.target) {
                    damageEffect.target.damage += 60;
                  }
                }
              }
            );
          }
        );
        return state;
      }
      BREAK_RULE(effect, state, this);
      return state;
    }
  };

