  var MScizorEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Mega EX" /* MEGA */, "EX" /* POKEMON_EX */];
      this.stage = 9 /* MEGA */;
      this.evolvesFrom = "Scizor-EX";
      this.cardType = [M];
      this.hp = 220;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Iron Crusher",
          cost: [M, M],
          damage: 120,
          text: "You may discard a Special Energy attached to your opponent's Active Pok\xE9mon or a Stadium card in play."
        }
      ];
      this.set = "BKP";
      this.setNumber = "77";
      this.cardImage = "assets/cardback.png";
      this.name = "M Scizor-EX";
      this.fullName = "M Scizor-EX BKP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasSpecialEnergy = opponent.active.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 1 /* SPECIAL */
        );
        const hasStadium = StateUtils.getStadiumCard(state) !== void 0;
        if (!hasSpecialEnergy && !hasStadium) {
          return state;
        }
        CONFIRMATION_PROMPT(store, state, player, (wantsToUse) => {
          if (!wantsToUse) {
            return;
          }
          if (hasSpecialEnergy && hasStadium) {
            CONFIRMATION_PROMPT(
              store,
              state,
              player,
              (chooseEnergy) => {
                if (chooseEnergy) {
                  this.discardSpecialEnergy(store, state, effect, player, opponent);
                } else {
                  DISCARD_A_STADIUM_CARD_IN_PLAY(state);
                }
              },
              GameMessage.WANT_TO_USE_ABILITY
            );
          } else if (hasSpecialEnergy) {
            this.discardSpecialEnergy(store, state, effect, player, opponent);
          } else {
            DISCARD_A_STADIUM_CARD_IN_PLAY(state);
          }
        });
      }
      return state;
    }
    discardSpecialEnergy(store, state, effect, player, opponent) {
      store.prompt(
        state,
        new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          opponent.active,
          { superType: 3 /* ENERGY */, energyType: 1 /* SPECIAL */ },
          { min: 1, max: 1, allowCancel: false }
        ),
        (selected) => {
          const cards = selected || [];
          if (cards.length > 0) {
            const discardEnergy2 = new DiscardCardsEffect(effect, cards);
            discardEnergy2.target = opponent.active;
            store.reduceEffect(state, discardEnergy2);
          }
        }
      );
    }
  };

