  init_attack_effects2();
  var Slowking3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Slowpoke";
      this.cardType = [W];
      this.hp = 100;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Royal Flash",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may flip a coin. If heads, move an Energy from your opponent's Active Pok\xE9mon to 1 of his or her Benched Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Psych Up",
        cost: [W, C],
        damage: 40,
        text: "During your next turn, this Pok\xE9mon's Psych Up attack does 40 more damage (before applying Weakness and Resistance)."
      }];
      this.set = "BKP";
      this.setNumber = "21";
      this.cardImage = "assets/cardback.png";
      this.name = "Slowking";
      this.fullName = "Slowking BKP";
      this.ROYAL_FLASH_MARKER = "SLOWKING_BKP_ROYAL_FLASH_MARKER";
      this.PSYCH_UP_MARKER = "SLOWKING_BKP_PSYCH_UP_MARKER";
      this.PSYCH_UP_CLEAR_MARKER = "SLOWKING_BKP_PSYCH_UP_CLEAR_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const hasEnergy = opponent.active.cards.some((c) => c instanceof EnergyCard);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasEnergy || !hasBenched) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.ROYAL_FLASH_MARKER, this);
        ABILITY_USED(player, this);
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_ATTACH,
              opponent.active,
              { superType: 3 /* ENERGY */ },
              { min: 1, max: 1, allowCancel: false }
            ), (selected) => {
              const cards = selected || [];
              if (cards.length === 0) {
                return;
              }
              store.prompt(state, new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
                1 /* TOP_PLAYER */,
                [2 /* BENCH */],
                { min: 1, max: 1, allowCancel: false }
              ), (targets) => {
                if (targets && targets.length > 0) {
                  MOVE_CARDS(store, state, opponent.active, targets[0], { cards: [cards[0]], sourceCard: this });
                }
              });
            });
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.ROYAL_FLASH_MARKER, this);
      NEXT_TURN_ATTACK_BONUS(effect, {
        attack: this.attacks[0],
        source: this,
        bonusDamage: 40,
        bonusMarker: this.PSYCH_UP_MARKER,
        clearMarker: this.PSYCH_UP_CLEAR_MARKER
      });
      return state;
    }
  };

