  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-breakpoint/suicune.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_prefabs();
  var Suicune2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 120;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.powers = [{
        name: "Wind Charm",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is your Active Pok\xE9mon, prevent all effects of your opponent's attacks, except damage, done to each of your Pok\xE9mon. (Existing effects are not removed.)"
      }];
      this.attacks = [
        {
          name: "Aurora Beam",
          cost: [W, W, W],
          damage: 110,
          text: ""
        }
      ];
      this.set = "BKP";
      this.setNumber = "30";
      this.cardImage = "assets/cardback.png";
      this.name = "Suicune";
      this.fullName = "Suicune BKP";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AbstractAttackEffect) {
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        let suicuneIsActive = false;
        if (targetPlayer.active.getPokemonCard() === this) {
          suicuneIsActive = true;
        }
        if (!suicuneIsActive) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetPlayer, this)) {
          return state;
        }
        if (effect.player === targetPlayer) {
          return state;
        }
        if (effect instanceof ApplyWeaknessEffect) {
          return state;
        }
        if (effect instanceof PutDamageEffect) {
          return state;
        }
        if (effect instanceof DealDamageEffect) {
          return state;
        }
        effect.preventDefault = true;
      }
      return state;
    }
  };

