  init_prefabs();
  var Trevenant2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Phantump";
      this.cardType = [P];
      this.hp = 110;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Nervous Seed",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is your Active Pok\xE9mon, your opponent's Basic Pok\xE9mon's attacks cost Colorless more."
      }];
      this.attacks = [
        {
          name: "Energy Press",
          cost: [P, C, C],
          damage: 70,
          damageCalculation: "+",
          text: "This attack does 10 more damage for each Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "BKP";
      this.setNumber = "65";
      this.cardImage = "assets/cardback.png";
      this.name = "Trevenant";
      this.fullName = "Trevenant BKP";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.active.getPokemonCard() !== this) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, opponent, this)) {
          return state;
        }
        const attackingPokemon = player.active.getPokemonCard();
        if (attackingPokemon && attackingPokemon.stage === 2 /* BASIC */) {
          effect.cost.push(9 /* COLORLESS */);
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        store.reduceEffect(state, checkEnergy);
        let energyCount = 0;
        checkEnergy.energyMap.forEach((em) => {
          energyCount += em.provides.length;
        });
        effect.damage += 10 * energyCount;
      }
      return state;
    }
  };

