  var Delinquent = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "BKP";
      this.name = "Delinquent";
      this.fullName = "Delinquent BKP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "98";
      this.text = "Discard any Stadium card in play. If you do, your opponent discards 3 cards from his or her hand.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const stadiumCard = StateUtils.getStadiumCard(state);
        if (stadiumCard == void 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [this], sourceCard: this });
        effect.preventDefault = true;
        if (stadiumCard !== void 0) {
          const cardList = StateUtils.findCardList(state, stadiumCard);
          const player2 = StateUtils.findOwner(state, cardList);
          MOVE_CARDS(store, state, cardList, player2.discard, { sourceCard: this });
        }
        const opponentCards = opponent.hand.cards.filter((c) => c !== this);
        if (opponentCards.length <= 3) {
          MOVE_CARDS(store, state, opponent.hand, opponent.discard, { sourceCard: this });
        }
        if (opponentCards.length > 3) {
          let cards = [];
          state = store.prompt(
            state,
            new ChooseCardsPrompt(
              opponent,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              opponent.hand,
              {},
              { min: 3, max: 3, allowCancel: false }
            ),
            (selected) => {
              cards = selected || [];
              MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards, sourceCard: this });
            }
          );
        }
      }
      return state;
    }
  };

