  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-breakpoint/puzzle-of-time.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_prefabs();
  var PuzzleOfTime = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "BKP";
      this.name = "Puzzle of Time";
      this.fullName = "Puzzle of Time BKP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "109";
      this.text = "You may play 2 Puzzle of Time cards at once.\n\n\u2022 If you played 1 card, look at the top 3 cards of your deck and put them back in any order.\n\u2022 If you played 2 cards, put 2 cards from your discard pile into your hand.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.deck.cards.length === 0 && player.hand.cards.filter((c) => c.name === "Puzzle of Time").length < 2) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        state = store.prompt(
          state,
          new SelectOptionPrompt(
            player.id,
            GameMessage.CHOOSE_OPTION,
            [
              "play 1 card, look at the top 3 cards of your deck and put them back in any order.",
              "play 2 cards, put 2 cards from your discard pile into your hand."
            ],
            {
              allowCancel: false,
              defaultValue: 0
            }
          ),
          (choice) => {
            if (choice === 0) {
              if (player.deck.cards.length === 0) {
                throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
              }
              const deckTop = new CardList();
              MOVE_CARDS(store, state, player.deck, deckTop, { count: 3, sourceCard: this });
              return store.prompt(
                state,
                new OrderCardsPrompt(player.id, GameMessage.CHOOSE_CARDS_ORDER, deckTop, {
                  allowCancel: false
                }),
                (order) => {
                  if (order === null) {
                    return state;
                  }
                  deckTop.applyOrder(order);
                  deckTop.moveToTopOfDestination(player.deck);
                }
              );
            } else if (choice === 1) {
              if (player.discard.cards.length === 0) {
                throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
              }
              if (player.hand.cards.filter((c) => c.name === "Puzzle of Time").length === 0) {
                throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
              }
              const secondPuzzle = player.hand.cards.find((c) => c.name === "Puzzle of Time");
              const mincards = Math.min(player.discard.cards.length, 2);
              SEARCH_DISCARD_PILE_FOR_CARDS_TO_HAND(
                store,
                state,
                player,
                this,
                {},
                { min: mincards, max: mincards, allowCancel: false },
                effect
              );
              if (secondPuzzle) {
                MOVE_CARDS(store, state, player.hand, player.discard, {
                  cards: [secondPuzzle],
                  sourceCard: this
                });
              }
            }
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-breakpoint/reverse-valley.ts
  init_game();
