  var ReverseValley = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "BKP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "110";
      this.name = "Reverse Valley";
      this.fullName = "Reverse Valley BKP";
      this.text = "Choose which way this card faces before you play it. The attacks of this \u2193 player's [D] Pok\xE9mon do 10 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance).\n\nChoose which way this card faces before you play it. Any damage done to this \u2193 player's [M] Pok\xE9mon by an opponent's attack is reduced by 10 (after applying Weakness and Resistance).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayStadiumEffect && effect.trainerCard === this) {
        const player = effect.player;
        const options = [
          {
            message: GameMessage.UP,
            action: () => {
              const stadiumCard = StateUtils.getStadiumCard(state);
              if (stadiumCard !== void 0) {
                const cardList = StateUtils.findCardList(state, stadiumCard);
                cardList.stadiumDirection = "up" /* UP */;
              }
            }
          },
          {
            message: GameMessage.DOWN,
            action: () => {
              const stadiumCard = StateUtils.getStadiumCard(state);
              if (stadiumCard !== void 0) {
                const cardList = StateUtils.findCardList(state, stadiumCard);
                cardList.stadiumDirection = "down" /* DOWN */;
              }
            }
          }
        ];
        return store.prompt(
          state,
          new SelectPrompt(
            player.id,
            GameMessage.WHICH_DIRECTION_TO_PLACE_STADIUM,
            options.map((c) => c.message),
            { allowCancel: false }
          ),
          (choice) => {
            const option = options[choice];
            if (option.action) {
              option.action();
            }
            return state;
          }
        );
      }
      if (effect instanceof PutDamageEffect && StateUtils.getStadiumCard(state) === this) {
        const owner = StateUtils.findOwner(state, effect.target);
        const stadiumCardList = StateUtils.findCardList(state, this);
        const stadiumOwner = StateUtils.findOwner(state, stadiumCardList);
        const checkDefenderType = new CheckPokemonTypeEffect(effect.target);
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, effect.target)) {
          return state;
        }
        store.reduceEffect(state, checkDefenderType);
        if (!checkDefenderType.cardTypes.includes(8 /* METAL */)) {
          return state;
        }
        if (stadiumCardList.stadiumDirection === "up" /* UP */ && stadiumOwner !== effect.player || stadiumCardList.stadiumDirection === "down" /* DOWN */ && stadiumOwner === effect.player) {
          effect.reduceDamage(10);
        }
      }
      if (effect instanceof DealDamageEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const stadiumCardList = StateUtils.findCardList(state, this);
        const stadiumOwner = StateUtils.findOwner(state, stadiumCardList);
        const checkPokemonType = new CheckPokemonTypeEffect(player.active);
        if (effect.target !== opponent.active || effect.damage <= 0 || IS_STADIUM_EFFECT_BLOCKED(store, state, player, effect.source)) {
          return state;
        }
        store.reduceEffect(state, checkPokemonType);
        if (!checkPokemonType.cardTypes.includes(7 /* DARK */)) {
          return state;
        }
        if (stadiumCardList.stadiumDirection === "up" /* UP */ && stadiumOwner === player || stadiumCardList.stadiumDirection === "down" /* DOWN */ && stadiumOwner !== player) {
          effect.damage += 10;
        }
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

