  var MistysDetermination = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "EVO";
      this.setNumber = "80";
      this.cardImage = "assets/cardback.png";
      this.name = "Misty's Determination";
      this.fullName = "Misty's Determination EVO";
      this.text = "Discard a card from your hand. If you do, look at the top 8 cards of your deck and put 1 of them into your hand. Shuffle the other cards back into your deck. You may play only 1 Supporter card during your turn (before your attack).";
    }
    // Refs: set-phantom-forces/tierno.ts (Supporter pattern), set-celebrations/mew.ts (look at top X, pick 1)
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const handWithoutThis = player.hand.cards.filter((c) => c !== this);
        if (handWithoutThis.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const generator = playCard116(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };
  function* playCard116(next, store, state, self, effect) {
    const player = effect.player;
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        player.hand,
        {},
        { min: 1, max: 1, allowCancel: false }
      ),
      (selected) => {
        if (selected && selected.length > 0) {
          MOVE_CARDS(store, state, player.hand, player.discard, {
            cards: selected,
            sourceCard: self
          });
        }
        next();
      }
    );
    const topCount = Math.min(8, player.deck.cards.length);
    if (topCount > 0) {
      const deckTop = new CardList();
      MOVE_CARDS(store, state, player.deck, deckTop, { count: topCount, sourceCard: self });
      yield store.prompt(
        state,
        new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          deckTop,
          {},
          { min: 1, max: 1, allowCancel: false }
        ),
        (selected) => {
          if (selected && selected.length > 0) {
            MOVE_CARDS(store, state, deckTop, player.hand, { cards: selected, sourceCard: self });
          }
          MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: self });
          next();
        }
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }

