  var Empoleon4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Prinplup";
      this.cardType = [W];
      this.hp = 140;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Dignified Fighter",
        powerType: 2 /* ABILITY */,
        text: "Each of your Basic Pok\xE9mon's attacks does 20 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Hydro Splash",
          cost: [W, C],
          damage: 70,
          text: ""
        }
      ];
      this.set = "BKT";
      this.setNumber = "38";
      this.cardImage = "assets/cardback.png";
      this.name = "Empoleon";
      this.fullName = "Empoleon BKT";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect) {
        const sourceCard = effect.source.getPokemonCard();
        if (!sourceCard || sourceCard.stage !== 2 /* BASIC */) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.source);
        let empoleonInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            empoleonInPlay = true;
          }
        });
        if (!empoleonInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, player);
        if (effect.target === opponent.active) {
          effect.damage += 20;
        }
      }
      return state;
    }
  };

