  var Granbull = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Snubbull";
      this.cardType = [Y];
      this.hp = 120;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C, C, C];
      this.attacks = [{
        name: "Startling Bark",
        cost: [C, C],
        damage: 0,
        text: "Flip a coin. If heads, choose 3 random cards from your opponent's hand. Your opponent reveals those cards and shuffles them into his or her deck."
      }, {
        name: "Tantrum",
        cost: [Y, C, C],
        damage: 120,
        text: "This Pok\xE9mon is now Confused."
      }];
      this.set = "BKT";
      this.setNumber = "99";
      this.cardImage = "assets/cardback.png";
      this.name = "Granbull";
      this.fullName = "Granbull BKT";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result && opponent.hand.cards.length > 0) {
            const count = Math.min(3, opponent.hand.cards.length);
            const handCopy = [...opponent.hand.cards];
            const cardsToShuffle = [];
            for (let i = 0; i < count; i++) {
              const randomIndex = Math.floor(Math.random() * handCopy.length);
              cardsToShuffle.push(handCopy[randomIndex]);
              handCopy.splice(randomIndex, 1);
            }
            cardsToShuffle.forEach((card) => {
              MOVE_CARDS(store, state, opponent.hand, opponent.deck, { cards: [card], sourceCard: this });
            });
            SHOW_CARDS_TO_PLAYER(store, state, player, cardsToShuffle);
            SHUFFLE_DECK(store, state, opponent);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.player, this);
      }
      return state;
    }
  };

