  init_pokemon_card();
  init_card_types();
  init_game();
  init_choose_cards_prompt();
  init_choose_pokemon_prompt();
  init_prefabs();
  var HoundoomEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["EX" /* POKEMON_EX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [R];
      this.hp = 170;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Melting Horn",
          cost: [R],
          damage: 0,
          text: "Discard the top 2 cards of your opponent's deck."
        },
        {
          name: "Grand Flame",
          cost: [R, R],
          damage: 50,
          text: "Attach a [R] Energy card from your discard pile to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.set = "BKT";
      this.setNumber = "21";
      this.cardImage = "assets/cardback.png";
      this.name = "Houndoom-EX";
      this.fullName = "Houndoom-EX BKT";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_TOP_X_OF_OPPONENTS_DECK(store, state, effect.player, 2, this, effect);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const hasFireEnergy = player.discard.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(2 /* FIRE */)
        );
        if (!hasFireEnergy) {
          return state;
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return state;
            }
            const target = targets[0];
            const blocked = [];
            player.discard.cards.forEach((card, index) => {
              if (!(card instanceof EnergyCard && card.energyType === 0 /* BASIC */ && card.provides.includes(2 /* FIRE */))) {
                blocked.push(index);
              }
            });
            return store.prompt(
              state,
              new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARD_TO_ATTACH,
                player.discard,
                { superType: 3 /* ENERGY */ },
                { min: 1, max: 1, allowCancel: false, blocked }
              ),
              (selected) => {
                const cards = selected || [];
                cards.forEach((card) => {
                  MOVE_CARDS(store, state, player.discard, target, { cards: [card], sourceCard: this });
                });
              }
            );
          }
        );
      }
      return state;
    }
  };

