  var Octillery2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Remoraid";
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Abyssal Hand",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may draw cards until you have 5 cards in your hand."
      }];
      this.attacks = [{
        name: "Hug",
        cost: [W, W, C],
        damage: 40,
        text: "The Defending Pok\xE9mon can't retreat during your opponent's next turn."
      }];
      this.set = "BKT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "33";
      this.name = "Octillery";
      this.fullName = "Octillery BKT";
      this.ABYSSAL_HAND_MARKER = "ABYSSAL_HAND_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.ABYSSAL_HAND_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.ABYSSAL_HAND_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.ABYSSAL_HAND_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.ABYSSAL_HAND_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.hand.cards.length >= 5) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        while (player.hand.cards.length < 5) {
          if (player.deck.cards.length === 0) {
            break;
          }
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
        }
        player.marker.addMarker(this.ABYSSAL_HAND_MARKER, this);
        ABILITY_USED(player, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return BLOCK_RETREAT(store, state, effect, this);
      }
      return state;
    }
  };

