  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-breakthrough/parasect.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects2();
  init_choose_pokemon_prompt();
  init_choose_cards_prompt();
  init_energy_card();
  var Parasect3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Paras";
      this.cardType = [G];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Colorful Spores",
          cost: [C],
          damage: 0,
          text: "Choose 3 of your Pok\xE9mon. For each of those Pok\xE9mon, search your deck for a different type of basic Energy card and attach it to that Pok\xE9mon. Shuffle your deck afterward."
        },
        {
          name: "X-Scissor",
          cost: [G, C],
          damage: 30,
          damageCalculation: "+",
          text: "Flip a coin. If heads, this attack does 30 more damage."
        }
      ];
      this.set = "BKT";
      this.setNumber = "2";
      this.cardImage = "assets/cardback.png";
      this.name = "Parasect";
      this.fullName = "Parasect BKT";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const pokemonCount = 1 + player.bench.filter((b) => b.cards.length > 0).length;
        const maxTargets = Math.min(3, pokemonCount);
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 0, max: maxTargets, allowCancel: true }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          const usedTypes = [];
          const attachToTarget = (index) => {
            if (index >= targets.length) {
              SHUFFLE_DECK(store, state, player);
              return;
            }
            const target = targets[index];
            const blocked = [];
            player.deck.cards.forEach((card, i) => {
              if (!(card instanceof EnergyCard) || card.energyType !== 0 /* BASIC */) {
                blocked.push(i);
              } else if (usedTypes.some((t) => card.provides.includes(t))) {
                blocked.push(i);
              }
            });
            if (blocked.length === player.deck.cards.length) {
              attachToTarget(index + 1);
              return;
            }
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_ATTACH,
              player.deck,
              { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
              { min: 0, max: 1, allowCancel: true, blocked }
            ), (selected) => {
              if (selected && selected.length > 0) {
                const energyCard = selected[0];
                energyCard.provides.forEach((t) => {
                  if (t !== 9 /* COLORLESS */) {
                    usedTypes.push(t);
                  }
                });
                MOVE_CARDS(store, state, player.deck, target, { cards: [energyCard], sourceCard: this });
              }
              attachToTarget(index + 1);
            });
          };
          attachToTarget(0);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        FLIP_A_COIN_IF_HEADS_DEAL_MORE_DAMAGE(store, state, effect, 30);
      }
      return state;
    }
  };

