  var Piloswine2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Swinub";
      this.cardType = [F];
      this.hp = 100;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Push Down",
          cost: [F, C],
          damage: 30,
          text: "Your opponent switches his or her Active Pok\xE9mon with 1 of his or her Benched Pok\xE9mon."
        },
        {
          name: "Gathering Footsteps",
          cost: [F, C, C],
          damage: 30,
          damageCalculation: "+",
          text: "This attack does 10 more damage for each Colorless in the Retreat Cost of your Swinub, Piloswine, and Mamoswine."
        }
      ];
      this.set = "BKT";
      this.setNumber = "81";
      this.cardImage = "assets/cardback.png";
      this.name = "Piloswine";
      this.fullName = "Piloswine BKT";
      this.usedPushDown = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          this.usedPushDown = true;
        }
      }
      if (effect instanceof AfterAttackEffect && this.usedPushDown) {
        this.usedPushDown = false;
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedPushDown = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const targetNames = ["Swinub", "Piloswine", "Mamoswine"];
        let totalColorless = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const pokemonCard = cardList.getPokemonCard();
          if (pokemonCard && targetNames.includes(pokemonCard.name)) {
            totalColorless += pokemonCard.retreat.length;
          }
        });
        effect.damage += 10 * totalColorless;
      }
      return state;
    }
  };

