  var Stunfisk4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 110;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Revenge",
          cost: [L, C],
          damage: 20,
          damageCalculation: "+",
          text: "If any of your Pok\xE9mon were Knocked Out by damage from an opponent's attack during his or her last turn, this attack does 80 more damage."
        },
        {
          name: "Thunder Blast",
          cost: [L, L, C],
          damage: 80,
          text: "Discard an Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "BKT";
      this.setNumber = "56";
      this.cardImage = "assets/cardback.png";
      this.name = "Stunfisk";
      this.fullName = "Stunfisk BKT";
      this.REVENGE_MARKER = "STUNFISK_BKT_REVENGE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const duringTurn = [2 /* PLAYER_TURN */, 3 /* ATTACK */].includes(state.phase);
        if (!duringTurn || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) {
          player.marker.addMarker(this.REVENGE_MARKER, this);
        }
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.REVENGE_MARKER, this)) {
          effect.damage += 80;
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1);
      }
      REMOVE_OPPONENT_LAST_TURN_MARKER_AT_END_OF_TURN(effect, this.REVENGE_MARKER, this);
      return state;
    }
  };

