  var AssaultVest = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "BKT";
      this.setNumber = "133";
      this.cardImage = "assets/cardback.png";
      this.name = "Assault Vest";
      this.fullName = "Assault Vest BKT";
      this.text = "Any damage done to the Pok\xE9mon this card is attached to by attacks from your opponent's Pok\xE9mon that have any Special Energy attached to them is reduced by 40 (after applying Weakness and Resistance).";
    }
    // Ref: set-x-and-y/hard-charm.ts (Tool damage reduction with IS_TOOL_BLOCKED + DealDamageEffect)
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.target.tools.includes(this)) {
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, player);
        if (effect.source === opponent.active || opponent.bench.includes(effect.source)) {
          const hasSpecialEnergy = effect.source.cards.some(
            (c) => c instanceof EnergyCard && c.energyType === 1 /* SPECIAL */
          );
          if (hasSpecialEnergy) {
            effect.damage = Math.max(0, effect.damage - 40);
          }
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-breakthrough/brigette.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_prefabs();
  var Brigette = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "BKT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "134";
      this.regulationMark = "E";
      this.name = "Brigette";
      this.fullName = "Brigette BKT";
      this.text = "Search your deck for 1 Basic Pok\xE9mon-EX or 3 Basic Pok\xE9mon (except for Pok\xE9mon-EX) and put them onto your Bench. Shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        } else {
          const openSlots = player.bench.filter((b) => b.cards.length === 0);
          if (openSlots.length === 0) {
            throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
          }
          const blocked = [];
          player.deck.cards.forEach((c, index) => {
            if (c instanceof PokemonCard && c.stage === 2 /* BASIC */) {
            } else {
              blocked.push(index);
            }
          });
          MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
          effect.preventDefault = true;
          let cards = [];
          const maxCards = Math.min(3, openSlots.length);
          return store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
              player.deck,
              { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
              { min: 0, max: maxCards, allowCancel: false, blocked }
            ),
            (selectedCards) => {
              cards = selectedCards || [];
              if (cards.length > 1 && cards.some((card) => card.hasTag("EX" /* POKEMON_EX */))) {
                return store.prompt(
                  state,
                  new ChooseCardsPrompt(
                    player,
                    GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
                    player.deck,
                    { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
                    { min: 1, max: 1, allowCancel: false, blocked }
                  ),
                  (singleCards) => {
                    const chosen = singleCards || [];
                    if (chosen.length === 0) {
                      return state;
                    }
                    MOVE_CARDS(store, state, player.deck, slots2[0], {
                      cards: [chosen[0]],
                      sourceCard: this
                    });
                    slots2[0].pokemonPlayedTurn = state.turn;
                    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                      player.deck.applyOrder(order);
                    });
                  }
                );
              }
              cards.forEach((card, index) => {
                MOVE_CARDS(store, state, player.deck, slots2[index], {
                  cards: [card],
                  sourceCard: this
                });
                slots2[index].pokemonPlayedTurn = state.turn;
              });
              return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                player.deck.applyOrder(order);
              });
            }
          );
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-breakthrough/buddy-buddy-rescue.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_prefabs();
  var BuddyBuddyRescue = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "BKT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "135";
      this.name = "Buddy-Buddy Rescue";
      this.fullName = "Buddy-Buddy Rescue SSH";
      this.text = "Each player puts a Pok\xE9mon from his or her discard pile into his or her hand. (Your opponent chooses first.)";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let pokemonInPlayersDiscard = 0;
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          if (c instanceof PokemonCard) {
            pokemonInPlayersDiscard += 1;
          } else {
            blocked.push(index);
          }
        });
        let pokemonInOpponentsDiscard = 0;
        const blockedOpponent = [];
        opponent.discard.cards.forEach((c, index) => {
          if (c instanceof PokemonCard) {
            pokemonInOpponentsDiscard += 1;
          } else {
            blockedOpponent.push(index);
          }
        });
        if (pokemonInOpponentsDiscard === 0 && pokemonInPlayersDiscard === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const discardEffect = new DiscardToHandEffect(player, this);
        store.reduceEffect(state, discardEffect);
        if (discardEffect.preventDefault) {
          store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              player.supporter,
              { superType: 2 /* TRAINER */ },
              { min: 1, max: 1, allowCancel: false }
            ),
            (selected) => {
              if (selected && selected.length > 0) {
                MOVE_CARDS(store, state, player.supporter, player.discard, {
                  cards: selected,
                  sourceCard: this
                });
              }
            }
          );
          return state;
        }
        if (pokemonInOpponentsDiscard > 0) {
          store.prompt(
            state,
            new ChooseCardsPrompt(
              opponent,
              GameMessage.CHOOSE_CARD_TO_HAND,
              opponent.discard,
              { superType: 1 /* POKEMON */ },
              { min: 1, max: 1, allowCancel: false, blocked: blockedOpponent }
            ),
            (selected) => {
              if (selected && selected.length > 0) {
                store.prompt(
                  state,
                  new ChooseCardsPrompt(
                    opponent,
                    GameMessage.CHOOSE_CARD_TO_HAND,
                    opponent.discard,
                    { superType: 1 /* POKEMON */ },
                    { min: 1, max: 1, allowCancel: false }
                  ),
                  (selected2) => {
                    if (selected2 && selected2.length > 0) {
                      MOVE_CARDS(store, state, opponent.discard, opponent.hand, {
                        cards: selected2,
                        sourceCard: this
                      });
                    }
                  }
                );
              }
            }
          );
        }
        if (pokemonInPlayersDiscard > 0) {
          store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_HAND,
              player.discard,
              { superType: 1 /* POKEMON */ },
              { min: 1, max: 1, allowCancel: false, blocked }
            ),
            (selected) => {
              if (selected && selected.length > 0) {
                store.prompt(
                  state,
                  new ChooseCardsPrompt(
                    player,
                    GameMessage.CHOOSE_CARD_TO_HAND,
                    player.discard,
                    { superType: 1 /* POKEMON */ },
                    { min: 1, max: 1, allowCancel: false }
                  ),
                  (selected2) => {
                    if (selected2 && selected2.length > 0) {
                      MOVE_CARDS(store, state, player.discard, player.hand, {
                        cards: selected2,
                        sourceCard: this
                      });
                    }
                  }
                );
              }
            }
          );
        }
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.supporter,
            { superType: 2 /* TRAINER */ },
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            if (selected && selected.length > 0) {
              MOVE_CARDS(store, state, player.supporter, player.discard, {
                cards: selected,
                sourceCard: this
              });
            }
          }
        );
        return state;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-breakthrough/giovannis-scheme.ts
  init_trainer_card();
