  var GiovannisScheme = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "BKT";
      this.setNumber = "138";
      this.cardImage = "assets/cardback.png";
      this.name = "Giovanni's Scheme";
      this.fullName = "Giovanni's Scheme BKT";
      this.text = "Choose 1:\n\u2022 Draw cards until you have 5 cards in your hand.\n\u2022 During this turn, your Pok\xE9mon's attacks do 20 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance). You may play only 1 Supporter card during your turn (before your attack).";
      this.GIOVANNIS_SCHEME_MARKER = "GIOVANNIS_SCHEME_MARKER";
    }
    // Refs: set-twilight-masquerade/kieran.ts (choose option + damage boost marker), set-ancient-origins/baltoy-2.ts (SelectPrompt pattern)
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.GIOVANNIS_SCHEME_MARKER, this)) {
        effect.player.marker.removeMarker(this.GIOVANNIS_SCHEME_MARKER, this);
        return state;
      }
      if (effect instanceof DealDamageEffect) {
        const player = effect.player;
        if (player.marker.hasMarker(this.GIOVANNIS_SCHEME_MARKER, this) && effect.damage > 0) {
          const opponent = StateUtils.getOpponent(state, player);
          if (effect.target === opponent.active) {
            effect.damage += 20;
          }
        }
      }
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const options = [
          {
            message: GameMessage.WANT_TO_DRAW_CARDS,
            action: () => {
              DRAW_CARDS_UNTIL_CARDS_IN_HAND(player, 5);
            }
          },
          {
            message: GameMessage.WANT_TO_DEAL_MORE_DAMAGE,
            action: () => {
              player.marker.addMarker(this.GIOVANNIS_SCHEME_MARKER, this);
            }
          }
        ];
        return store.prompt(
          state,
          new SelectPrompt(
            player.id,
            GameMessage.CHOOSE_OPTION,
            options.map((opt) => opt.message),
            { allowCancel: false }
          ),
          (choice) => {
            const option = options[choice];
            option.action();
          }
        );
      }
      return state;
    }
  };

