  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-breakthrough/heavy-boots.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_check_effects();
  init_play_card_effects();
  var HeavyBoots = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "BKT";
      this.setNumber = "141";
      this.cardImage = "assets/cardback.png";
      this.name = "Heavy Boots";
      this.fullName = "Heavy Boots BKT";
      this.text = "If the Retreat Cost of the Pok\xE9mon this card is attached to is 3 or more, that Pok\xE9mon gets +20 HP and can't be Confused. (If that Pok\xE9mon is currently Confused, remove that Special Condition.)";
    }
    isToolActive(store, state, target) {
      const sourceCard = target.getPokemonCard();
      if (!sourceCard || sourceCard.retreat.length < 3) {
        return false;
      }
      try {
        const owner = StateUtils.findOwner(state, target);
        const toolEffect = new ToolEffect(owner, this);
        store.reduceEffect(state, toolEffect);
      } catch {
        return false;
      }
      return true;
    }
    // Refs: set-team-up/buff-padding.ts (CheckHpEffect for HP bonus), set-furious-fists/sparkling-robe.ts (confusion prevention)
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckHpEffect && effect.target.tools.includes(this)) {
        if (this.isToolActive(store, state, effect.target)) {
          effect.hp += 20;
        }
      }
      if (effect instanceof AddSpecialConditionsEffect && effect.target.tools.includes(this)) {
        if (this.isToolActive(store, state, effect.target)) {
          effect.specialConditions = effect.specialConditions.filter(
            (sc) => sc !== 1 /* CONFUSED */
          );
        }
      }
      if (effect instanceof AddSpecialConditionsPowerEffect && effect.target.tools.includes(this)) {
        if (this.isToolActive(store, state, effect.target)) {
          effect.specialConditions = effect.specialConditions.filter(
            (sc) => sc !== 1 /* CONFUSED */
          );
        }
      }
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.tools.includes(this) && cardList.specialConditions.includes(1 /* CONFUSED */) && this.isToolActive(store, state, cardList)) {
              cardList.removeSpecialCondition(1 /* CONFUSED */);
            }
          });
        });
      }
      return state;
    }
  };

