  var ParallelCity = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "BKT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "145";
      this.name = "Parallel City";
      this.fullName = "Parallel City BKT";
      this.text = "Choose which way this card faces before you play it. This \u2193 player can't have more than 3 Benched Pok\xE9mon. (When this card comes into play, this \u2193 player discards Benched Pok\xE9mon until he or she has 3 Pok\xE9mon on the Bench.)\n\nChoose which way this card faces before you play it. Any damage done by attacks from this \u2193 player's [G] [R] or [W] Pok\xE9mon is reduced by 20 (after applying Weakness and Resistance).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayStadiumEffect && effect.trainerCard === this) {
        const player = effect.player;
        const options = [
          {
            message: GameMessage.UP,
            action: () => {
              const stadiumCard = StateUtils.getStadiumCard(state);
              if (stadiumCard !== void 0) {
                StateUtils.findCardList(state, stadiumCard).stadiumDirection = "up" /* UP */;
              }
            }
          },
          {
            message: GameMessage.DOWN,
            action: () => {
              const stadiumCard = StateUtils.getStadiumCard(state);
              if (stadiumCard !== void 0) {
                StateUtils.findCardList(state, stadiumCard).stadiumDirection = "down" /* DOWN */;
              }
            }
          }
        ];
        return store.prompt(
          state,
          new SelectPrompt(
            player.id,
            GameMessage.WHICH_DIRECTION_TO_PLACE_STADIUM,
            options.map((c) => c.message),
            { allowCancel: false }
          ),
          (choice) => {
            const option = options[choice];
            if (option.action) {
              option.action();
            }
            return state;
          }
        );
      }
      if (effect instanceof CheckTableStateEffect && StateUtils.getStadiumCard(state) === this) {
        const stadiumCardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, stadiumCardList);
        const limitedIsOwner = stadiumCardList.stadiumDirection === "down" /* DOWN */;
        effect.benchSizes = state.players.map((p) => {
          const isLimited = limitedIsOwner ? p === owner : p !== owner;
          return isLimited ? 3 : 5;
        });
      }
      if (effect instanceof DealDamageEffect && StateUtils.getStadiumCard(state) === this) {
        const stadiumCardList = StateUtils.findCardList(state, this);
        const stadiumOwner = StateUtils.findOwner(state, stadiumCardList);
        const attackerTypes = effect.player.active.getPokemonCard()?.cardType ?? [];
        const isGrw = attackerTypes.some(
          (t) => t === 2 /* FIRE */ || t === 3 /* WATER */ || t === 1 /* GRASS */
        );
        const affectsAttacker = effect.player === stadiumOwner && stadiumCardList.stadiumDirection === "up" /* UP */ || effect.player !== stadiumOwner && stadiumCardList.stadiumDirection === "down" /* DOWN */;
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, effect.player, effect.source)) {
          return state;
        }
        if (isGrw && affectsAttacker) {
          effect.damage -= 20;
        }
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

