  var ReservedTicket = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "BKT";
      this.setNumber = "147";
      this.cardImage = "assets/cardback.png";
      this.name = "Reserved Ticket";
      this.fullName = "Reserved Ticket BKT";
      this.text = "Flip a coin. If heads, search your deck for a card, shuffle your deck, then put that card on top of it.";
    }
    // Ref: set-silver-tempest/beldum.ts (Magnetic Lift - search deck, shuffle, put on top)
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            if (player.deck.cards.length === 0) {
              return;
            }
            let cards = [];
            const deckTop = new CardList();
            store.prompt(
              state,
              new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARDS,
                player.deck,
                {},
                { min: 1, max: 1, allowCancel: false }
              ),
              (selected) => {
                cards = selected || [];
                if (cards.length > 0) {
                  MOVE_CARDS(store, state, player.deck, deckTop, { cards, sourceCard: this });
                  store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                    player.deck.applyOrder(order);
                    deckTop.moveToTopOfDestination(player.deck);
                  });
                }
              }
            );
          }
        });
      }
      return state;
    }
  };

