  var Arcanine4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Growlithe";
      this.cardType = [R];
      this.hp = 130;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Burning Road",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), if this Pok\xE9mon was on the Bench and became your Active Pok\xE9mon this turn, you may move any number of [R] Energy attached to your Pok\xE9mon to this Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Scorching Breath",
          cost: [R, R, R, C],
          damage: 150,
          text: "This Pok\xE9mon can't attack during your next turn."
        }
      ];
      this.set = "EVO";
      this.setNumber = "18";
      this.cardImage = "assets/cardback.png";
      this.name = "Arcanine";
      this.fullName = "Arcanine EVO";
      this.BURNING_ROAD_MARKER = "ARCANINE_EVO_BURNING_ROAD";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        if (!MOVED_TO_ACTIVE_THIS_TURN(player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.BURNING_ROAD_MARKER, this);
        ABILITY_USED(player, this);
        const blockedFrom = [];
        const blockedTo = [];
        const blockedMap = [];
        let hasFireEnergyOnOtherPokemon = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList === player.active) {
            blockedFrom.push(target);
            return;
          }
          blockedTo.push(target);
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          const blockedCards = [];
          checkProvidedEnergy.energyMap.forEach((em) => {
            if (!em.provides.includes(2 /* FIRE */) && !em.provides.includes(0 /* ANY */)) {
              blockedCards.push(em.card);
            }
          });
          const blocked = [];
          blockedCards.forEach((bc) => {
            const index = cardList.cards.indexOf(bc);
            if (index !== -1 && !blocked.includes(index)) {
              blocked.push(index);
            }
          });
          if (blocked.length > 0) {
            blockedMap.push({ source: target, blocked });
          }
          if (cardList.cards.some((c) => c instanceof EnergyCard && (c.provides.includes(2 /* FIRE */) || c.provides.includes(0 /* ANY */)))) {
            hasFireEnergyOnOtherPokemon = true;
          }
        });
        if (!hasFireEnergyOnOtherPokemon) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(state, new MoveEnergyPrompt(
          player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: true, blockedTo, blockedFrom, blockedMap }
        ), (transfers) => {
          if (!transfers) {
            return;
          }
          for (const transfer of transfers) {
            const target = player.active;
            const source = StateUtils.getTarget(state, player, transfer.from);
            MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.BURNING_ROAD_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.player.active.cannotAttackNextTurnPending = true;
      }
      return state;
    }
  };

