  var DragoniteEX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [9 /* COLORLESS */];
      this.hp = 180;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -20 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this._tags = ["EX" /* POKEMON_EX */];
      this.powers = [
        {
          name: "Pull Up",
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench, you may put 2 Basic Pok\xE9mon (except for Dragonite-EX) from your discard pile into your hand."
        }
      ];
      this.attacks = [
        {
          name: "Hyper Beam",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 130,
          text: "Discard an Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "EVO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "72";
      this.name = "Dragonite-EX";
      this.fullName = "Dragonite EX EVO";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const hasBasicPokemonInDiscard = player.discard.cards.some((c) => {
          return c instanceof PokemonCard && c.stage === 2 /* BASIC */;
        });
        if (!hasBasicPokemonInDiscard) {
          return state;
        }
        const discardEffect = new DiscardToHandEffect(player, this);
        store.reduceEffect(state, discardEffect);
        if (discardEffect.preventDefault) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        return store.prompt(
          state,
          new ConfirmPrompt(player.id, GameMessage.WANT_TO_USE_ABILITY),
          (confirmed) => {
            if (confirmed) {
              const blocked = [];
              player.bench.forEach((card, index) => {
                if (card instanceof PokemonCard && card.name === "Dragonite-EX") {
                  blocked.push(index);
                }
              });
              return store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_HAND,
                  player.discard,
                  { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
                  { min: 0, max: 2, allowCancel: false, blocked }
                ),
                (selected) => {
                  if (selected && selected.length > 0) {
                    selected.forEach((card) => {
                      MOVE_CARDS(store, state, player.discard, player.hand, {
                        cards: [card],
                        sourceCard: this,
                        sourceEffect: this.powers[0]
                      });
                    });
                  }
                  return state;
                }
              );
            }
            return state;
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!opponent.active.energies.cards.some((c) => c.superType === 3 /* ENERGY */)) {
          return state;
        }
        let card;
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.active,
            { superType: 3 /* ENERGY */ },
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            card = selected[0];
            MOVE_CARDS(store, state, opponent.active, opponent.discard, { cards: [card], sourceCard: this });
            return state;
          }
        );
      }
      return state;
    }
  };

