  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-evolutions/mew.ts
  init_attack_effects();
  init_prefabs();
  init_card_types();
  init_state_utils();
  init_pokemon_card();
  init_game();
  var Mew6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 40;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Neutral Shield",
        powerType: 2 /* ABILITY */,
        text: "Prevent all effects of attacks, including damage, done to this Pok\xE9mon by your opponent's Evolution Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Psy Bolt",
        cost: [P, C],
        damage: 30,
        text: "Flip a coin. If heads, your opponent's Active Pok\xE9mon is now Paralyzed."
      }];
      this.set = "EVO";
      this.setNumber = "53";
      this.cardImage = "assets/cardback.png";
      this.name = "Mew";
      this.fullName = "Mew EVO";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this)) {
        const sourceCard = effect.source.getPokemonCard();
        if (sourceCard && sourceCard.stage !== 2 /* BASIC */) {
          const targetPlayer = StateUtils.findOwner(state, effect.target);
          if (IS_ABILITY_BLOCKED(store, state, targetPlayer, this)) {
            return state;
          }
          if (effect instanceof ApplyWeaknessEffect) {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            ADD_PARALYZED_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
          }
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-evolutions/mewtwo.ts
