  var Mewtwo5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 130;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Psychic",
          cost: [C, C],
          damage: 20,
          damageCalculation: "+",
          text: "This attack does 20 more damage for each Energy attached to your opponent's Active Pok\xE9mon."
        },
        {
          name: "Barrier",
          cost: [P, P],
          damage: 0,
          text: "During your opponent's next turn, prevent all effects of attacks, including damage, done to this Pok\xE9mon. If 1 of your Pok\xE9mon used Barrier during your last turn, this attack can't be used."
        }
      ];
      this.set = "EVO";
      this.setNumber = "51";
      this.cardImage = "assets/cardback.png";
      this.name = "Mewtwo";
      this.fullName = "Mewtwo EVO";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        const energyCount = checkProvidedEnergyEffect.energyMap.reduce((total, p) => total + p.provides.length, 0);
        effect.damage += energyCount * 20;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        PREVENT_DAMAGE(store, state, effect, this);
        PREVENT_EFFECTS_OF_ATTACKS(store, state, effect, this);
        effect.player.active.cannotUseAttacksNextTurnPending.push("Barrier");
      }
      return state;
    }
  };

