  init_prefabs();
  function* useSpaceBeacon(next, store, state, effect, self) {
    const player = effect.player;
    let cards = [];
    if (player.hand.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let basicEnergies = 0;
    player.discard.cards.forEach((c) => {
      if (c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */) {
        basicEnergies += 1;
      }
    });
    if (basicEnergies === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_DISCARD,
      player.hand,
      {},
      { min: 1, max: 1, allowCancel: false }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length === 0) {
      return state;
    }
    let recovered = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_HAND,
      player.discard,
      { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
      { min: 1, max: 2, allowCancel: false }
    ), (selected) => {
      recovered = selected || [];
      next();
    });
    if (recovered.length === 0) {
      return state;
    }
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
      if (cardList.getPokemonCard() === effect.card) {
        cardList.addBoardEffect(0 /* ABILITY_USED */);
      }
    });
    MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: self, sourceEffect: self.powers[0] });
    MOVE_CARDS(store, state, player.discard, player.hand, { cards: recovered, sourceCard: self, sourceEffect: self.powers[0] });
    return state;
  }
