  var StarmieBreak = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Break" /* BREAK */];
      this.stage = 10 /* BREAK */;
      this.evolvesFrom = "Starmie";
      this.cardType = [W];
      this.hp = 130;
      this.retreat = [];
      this.attacks = [
        {
          name: "Break Star",
          cost: [W],
          damage: 0,
          text: "This attack does 100 damage to each of your opponent's Pok\xE9mon BREAK. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "EVO";
      this.setNumber = "32";
      this.cardImage = "assets/cardback.png";
      this.name = "Starmie BREAK";
      this.fullName = "Starmie BREAK EVO";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const activePokemon = opponent.active.getPokemonCard();
        if (activePokemon && activePokemon.hasTag("Break" /* BREAK */)) {
          const damage = new DealDamageEffect(effect, 100);
          damage.target = opponent.active;
          store.reduceEffect(state, damage);
        }
        opponent.bench.forEach((benched) => {
          if (benched.cards.length > 0) {
            const benchPokemon = benched.getPokemonCard();
            if (benchPokemon && benchPokemon.hasTag("Break" /* BREAK */)) {
              const damage = new PutDamageEffect(effect, 100);
              damage.target = benched;
              store.reduceEffect(state, damage);
            }
          }
        });
      }
      BREAK_RULE(effect, state, this);
      return state;
    }
  };

