  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-evolutions/brocks-grit.ts
  init_game_error();
  init_game_message();
  init_trainer_card();
  init_card_types();
  init_pokemon_card();
  init_choose_cards_prompt();
  init_shuffle_prompt();
  init_trainer_prefabs();
  init_prefabs();
  var BrocksGrit = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "EVO";
      this.name = "Brock's Grit";
      this.fullName = "Brock's Grit EVO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "74";
      this.text = "Shuffle 6 in any combination of Pok\xE9mon and basic Energy cards from your discard pile into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        let pokemonsOrEnergyInDiscard = 0;
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          const isPokemon = c instanceof PokemonCard;
          const isBasicEnergy = c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
          if (isPokemon || isBasicEnergy) {
            pokemonsOrEnergyInDiscard += 1;
          } else {
            blocked.push(index);
          }
        });
        if (pokemonsOrEnergyInDiscard === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        let cards = [];
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DECK,
            player.discard,
            {},
            { min: 1, max: 6, allowCancel: false, blocked }
          ),
          (selected) => {
            cards = selected || [];
            MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: this });
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      return state;
    }
  };

