  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-evolutions/devolution-spray.ts
  init_game();
  init_card_types();
  init_play_card_effects();
  init_prefabs();
  var DevolutionSpray3 = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.name = "Devolution Spray";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "76";
      this.set = "EVO";
      this.fullName = "Devolution Spray EVO";
      this.superType = 2 /* TRAINER */;
      this._trainerType = 0 /* ITEM */;
      this.text = "Devolve 1 of your evolved Pok\xE9mon and put the highest Stage Evolution card on it into your hand. (That Pok\xE9mon can't evolve this turn.)";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        let canDevolve = false;
        const blocked = [];
        effect.player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (list.getPokemons().length > 1) {
            canDevolve = true;
          } else {
            blocked.push(target);
          }
        });
        if (!canDevolve) {
          throw new GameError("CANNOT_PLAY_THIS_CARD" /* CANNOT_PLAY_THIS_CARD */);
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            effect.player.id,
            GameMessage.CHOOSE_POKEMON,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { allowCancel: false, min: 1, max: 1, blocked }
          ),
          (results) => {
            if (results && results.length > 0) {
              DEVOLVE_POKEMON(store, state, results[0], effect.player.hand);
            }
            return state;
          }
        );
      }
      return state;
    }
  };

