  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-fates-collide/aerodactyl.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_energy_card();
  init_attack_effects();
  init_prefabs();
  var Aerodactyl4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 1 /* RESTORED */;
      this.evolvesFrom = "Old Amber Aerodactyl";
      this.cardType = [C];
      this.hp = 120;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Bite",
          cost: [C],
          damage: 20,
          text: ""
        },
        {
          name: "Jet Draft",
          cost: [C, C],
          damage: 120,
          text: "Discard a Special Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "FCO";
      this.setNumber = "76";
      this.cardImage = "assets/cardback.png";
      this.name = "Aerodactyl";
      this.fullName = "Aerodactyl FCO";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasSpecialEnergy = opponent.active.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 1 /* SPECIAL */
        );
        if (hasSpecialEnergy) {
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.active,
            { superType: 3 /* ENERGY */, energyType: 1 /* SPECIAL */ },
            { min: 1, max: 1, allowCancel: false }
          ), (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              const discardEnergy2 = new DiscardCardsEffect(effect, cards);
              discardEnergy2.target = opponent.active;
              store.reduceEffect(state, discardEnergy2);
            }
          });
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-fates-collide/alakazam-ex.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects();
  init_play_card_effects();
  var AlakazamEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["EX" /* POKEMON_EX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 160;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Kinesis",
          powerType: 2 /* ABILITY */,
          text: "When you play M Alakazam-EX from your hand to evolve this Pok\xE9mon, before it evolves, you may put 2 damage counters on your opponent's Active Pok\xE9mon and 3 damage counters on 1 of your opponent's Benched Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Suppression",
          cost: [P, C],
          damage: 0,
          text: "Put 3 damage counters on each of your opponent's Pok\xE9mon that has any Energy attached to it."
        }
      ];
      this.set = "FCO";
      this.name = "Alakazam-EX";
      this.fullName = "Alakazam EX FCO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "25";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.target.getPokemonCard() === this) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (effect.pokemonCard.name === "M Alakazam-EX") {
          if (IS_ABILITY_BLOCKED(store, state, effect.player, this)) {
            return state;
          }
          CONFIRMATION_PROMPT(store, state, effect.player, (result) => {
            if (result) {
              opponent.active.damage += 20;
              const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
              if (!hasBenched) {
                return state;
              }
              return store.prompt(
                state,
                new ChoosePokemonPrompt(
                  effect.player.id,
                  GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
                  1 /* TOP_PLAYER */,
                  [2 /* BENCH */],
                  { allowCancel: false }
                ),
                (targets) => {
                  if (!targets || targets.length === 0) {
                    return;
                  }
                  targets[0].damage += 30;
                }
              );
            }
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        opponent.forEachPokemon(2 /* BOTTOM_PLAYER */, (card) => {
          const goodEnergy = card.cards.filter((card2) => card2.superType === 3 /* ENERGY */);
          if (goodEnergy.length > 0) {
            const damage = new PutCountersEffect(effect, 30);
            damage.target = card;
            store.reduceEffect(state, damage);
          }
        });
      }
      return state;
    }
  };

