  init_game();
  init_play_card_effects();
  init_prefabs();
  var Barbaracle2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Binacle";
      this.cardType = [W];
      this.hp = 100;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Hand Block",
        powerType: 2 /* ABILITY */,
        text: "If you have a Stadium card in play, your opponent can't attach any Special Energy cards from his or her hand to his or her Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Claw Slash",
          cost: [W, W, C],
          damage: 70,
          text: ""
        }
      ];
      this.set = "FCO";
      this.setNumber = "23";
      this.cardImage = "assets/cardback.png";
      this.name = "Barbaracle";
      this.fullName = "Barbaracle FCO";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.energyCard.energyType === 1 /* SPECIAL */) {
        if (!effect.player.hand.cards.includes(effect.energyCard)) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (!StateUtils.isPokemonInPlay(owner, this)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, owner, this)) {
          return state;
        }
        if (effect.player === owner) {
          return state;
        }
        const stadiumCard = StateUtils.getStadiumCard(state);
        if (stadiumCard === void 0) {
          return state;
        }
        throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
      }
      return state;
    }
  };

