  var DelphoxBreak = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Break" /* BREAK */];
      this.stage = 10 /* BREAK */;
      this.evolvesFrom = "Delphox";
      this.cardType = [R];
      this.hp = 180;
      this.retreat = [];
      this.powers = [
        {
          name: "Flare Witch",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn (before your attack), you may search your deck for a [R] Energy card and attach it to 1 of your Pok\xE9mon. Shuffle your deck afterward."
        }
      ];
      this.set = "FCO";
      this.setNumber = "14";
      this.cardImage = "assets/cardback.png";
      this.name = "Delphox BREAK";
      this.fullName = "Delphox BREAK FCO";
      this.FLARE_WITCH_MARKER = "DELPHOX_BREAK_FCO_FLARE_WITCH_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.FLARE_WITCH_MARKER, this);
        ABILITY_USED(player, this);
        if (player.deck.cards.length === 0) {
          return state;
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (!(card instanceof EnergyCard) || card.energyType !== 0 /* BASIC */ || !card.provides.includes(2 /* FIRE */)) {
            blocked.push(index);
          }
        });
        if (blocked.length === player.deck.cards.length) {
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_ATTACH,
            player.deck,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min: 0, max: 1, allowCancel: true, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              store.prompt(
                state,
                new ChoosePokemonPrompt(
                  player.id,
                  GameMessage.CHOOSE_POKEMON,
                  2 /* BOTTOM_PLAYER */,
                  [1 /* ACTIVE */, 2 /* BENCH */],
                  { min: 1, max: 1, allowCancel: false }
                ),
                (targets) => {
                  if (targets && targets.length > 0) {
                    MOVE_CARDS(store, state, player.deck, targets[0], { cards: [cards[0]], sourceCard: this });
                  }
                  store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                    player.deck.applyOrder(order);
                  });
                }
              );
            } else {
              store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                player.deck.applyOrder(order);
              });
            }
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.FLARE_WITCH_MARKER, this);
      BREAK_RULE(effect, state, this);
      return state;
    }
  };

