  var DiancieEx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["EX" /* POKEMON_EX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [Y];
      this.hp = 150;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Sparkle Veil",
          powerType: 2 /* ABILITY */,
          text: "As long as this Pok\xE9mon is your Active Pok\xE9mon, any damage done to your Pok\xE9mon by an opponent's attack is reduced by 30 (after applying Weakness and Resistance)."
        }
      ];
      this.attacks = [
        {
          name: "Wonder Stage",
          cost: [Y, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "If there is any Stadium card in play, this attack does 50 more damage."
        }
      ];
      this.set = "FCO";
      this.setNumber = "72";
      this.cardImage = "assets/cardback.png";
      this.name = "Diancie-EX";
      this.fullName = "Diancie-EX FCO";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect || effect instanceof PutDamageEffect) {
        const targetCard2 = effect.target.getPokemonCard();
        if (!targetCard2) {
          return state;
        }
        let targetOwner = null;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList === effect.target) {
              targetOwner = p;
            }
          });
        });
        if (!targetOwner) {
          return state;
        }
        if (targetOwner.active.getPokemonCard() !== this) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetOwner, this)) {
          return state;
        }
        const sourceOwner = effect.player;
        if (sourceOwner === targetOwner) {
          return state;
        }
        effect.damage = Math.max(0, effect.damage - 30);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const stadiumCard = StateUtils.getStadiumCard(state);
        if (stadiumCard !== void 0) {
          effect.damage += 50;
        }
      }
      return state;
    }
  };

