  init_game();
  init_game_phase_effects();
  init_choose_cards_prompt();
  init_prefabs();
  var Grumpig3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Spoink";
      this.cardType = [P];
      this.hp = 100;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Head Walking",
          cost: [P],
          damage: 0,
          text: "Put a Basic Pok\xE9mon from your opponent's discard pile onto his or her Bench. Then, put 3 damage counters on that Pok\xE9mon."
        },
        {
          name: "Knock Back",
          cost: [P, P],
          damage: 50,
          text: "Your opponent switches his or her Active Pok\xE9mon with 1 of his or her Benched Pok\xE9mon."
        }
      ];
      this.set = "FCO";
      this.setNumber = "31";
      this.cardImage = "assets/cardback.png";
      this.name = "Grumpig";
      this.fullName = "Grumpig FCO";
      this.usedKnockBack = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const slots2 = opponent.bench.filter((b) => b.cards.length === 0);
        const hasBasicInDiscard = opponent.discard.cards.some(
          (c) => c instanceof PokemonCard && c.stage === 2 /* BASIC */
        );
        if (!hasBasicInDiscard || slots2.length === 0) {
          return state;
        }
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          opponent.discard,
          { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          if (selected && selected.length > 0) {
            MOVE_CARDS(store, state, opponent.discard, slots2[0], { cards: [selected[0]], sourceCard: this });
            slots2[0].pokemonPlayedTurn = state.turn;
            slots2[0].damage = 30;
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedKnockBack = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedKnockBack) {
        this.usedKnockBack = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedKnockBack = false;
      }
      return state;
    }
  };

