  var Lucario4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Riolu";
      this.cardType = [8 /* METAL */];
      this.hp = 110;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.resistance = [{ type: 5 /* PSYCHIC */, value: -20 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Vacuum Wave",
          cost: [8 /* METAL */],
          damage: 50,
          text: "This attack's damage isn't affected by Weakness or Resistance."
        },
        {
          name: "Fight Alone",
          cost: [8 /* METAL */, 9 /* COLORLESS */],
          damage: 30,
          text: "If you have fewer Pokemon in play than your opponent, this attack does 60 more damage for each Pokemon fewer you have in play."
        }
      ];
      this.set = "FCO";
      this.name = "Lucario";
      this.fullName = "Lucario FCO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "63";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.ignoreWeakness = true;
        effect.ignoreResistance = true;
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let playerPokemons = 0;
        let opponentPokemons = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, () => {
          playerPokemons += 1;
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, () => {
          opponentPokemons += 1;
        });
        const fewerPokemons = Math.max(0, opponentPokemons - playerPokemons);
        effect.damage += fewerPokemons * 60;
      }
      return state;
    }
  };

