  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-fates-collide/omastar-break.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var OmastarBreak = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Break" /* BREAK */];
      this.stage = 10 /* BREAK */;
      this.evolvesFrom = "Omastar";
      this.cardType = [W];
      this.hp = 140;
      this.retreat = [];
      this.powers = [
        {
          name: "Dangerous Tentacle",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn (before your attack), you may switch 1 of your opponent's Benched Pok\xE9mon-EX with his or her Active Pok\xE9mon."
        }
      ];
      this.set = "FCO";
      this.setNumber = "19";
      this.cardImage = "assets/cardback.png";
      this.name = "Omastar BREAK";
      this.fullName = "Omastar BREAK FCO";
      this.DANGEROUS_TENTACLE_MARKER = "DANGEROUS_TENTACLE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const benchedEX = [];
        opponent.bench.forEach((b) => {
          if (b.cards.length > 0) {
            const pokemonCard = b.getPokemonCard();
            if (pokemonCard && pokemonCard.hasTag("EX" /* POKEMON_EX */)) {
              benchedEX.push(b);
            }
          }
        });
        if (benchedEX.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.DANGEROUS_TENTACLE_MARKER, this);
        ABILITY_USED(player, this);
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const target = targets[0];
            const targetCard2 = target.getPokemonCard();
            if (!targetCard2 || !targetCard2.hasTag("EX" /* POKEMON_EX */)) {
              return;
            }
            opponent.switchPokemon(target);
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.DANGEROUS_TENTACLE_MARKER, this);
      BREAK_RULE(effect, state, this);
      return state;
    }
  };

