  init_pokemon_card();
  init_card_types();
  init_game();
  init_trainer_card();
  init_confirm_prompt();
  init_prefabs();
  var Tyranitar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Pupitar";
      this.cardType = [D];
      this.hp = 160;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C, C];
      this.powers = [{
        name: "Raging Roar",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon, you may attach 1 [D] Energy from your discard pile to this Pok\xE9mon for each Prize card your opponent has taken."
      }];
      this.attacks = [
        {
          name: "Dark Mountain",
          cost: [D, D, D, D, D],
          damage: 150,
          damageCalculation: "+",
          text: "Discard the top 2 cards of your deck. This attack does 50 more damage for each Supporter card discarded in this way."
        }
      ];
      this.set = "FCO";
      this.setNumber = "56";
      this.cardImage = "assets/cardback.png";
      this.name = "Tyranitar";
      this.fullName = "Tyranitar FCO";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, player);
        const prizesTaken = opponent.prizes.filter((p) => p.cards.length === 0).length;
        if (prizesTaken === 0) {
          return state;
        }
        const darkEnergyInDiscard = player.discard.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(7 /* DARK */)
        ).length;
        if (darkEnergyInDiscard === 0) {
          return state;
        }
        store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (result) => {
          if (!result) {
            return;
          }
          const maxAttach = Math.min(prizesTaken, darkEnergyInDiscard);
          ATTACH_ENERGY_PROMPT(
            store,
            state,
            player,
            2 /* BOTTOM_PLAYER */,
            4 /* DISCARD */,
            [1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Darkness Energy" },
            { min: 1, max: maxAttach, allowCancel: true }
          );
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cardsToDiscard = player.deck.cards.slice(0, 2);
        let supporterCount = 0;
        cardsToDiscard.forEach((card) => {
          if (card instanceof TrainerCard && card.trainerType === 1 /* SUPPORTER */) {
            supporterCount++;
          }
        });
        DISCARD_TOP_X_CARDS_FROM_YOUR_DECK(store, state, player, 2, this, effect);
        effect.damage += 50 * supporterCount;
      }
      return state;
    }
  };

