  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-fates-collide/whimsicott.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_phase_effects();
  init_prefabs();
  var Whimsicott4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Cottonee";
      this.cardType = [Y];
      this.hp = 90;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Light Steps",
          cost: [Y],
          damage: 40,
          text: "Move an Energy from this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.set = "FCO";
      this.setNumber = "71";
      this.cardImage = "assets/cardback.png";
      this.name = "Whimsicott";
      this.fullName = "Whimsicott FCO";
      this.usedLightSteps = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedLightSteps = true;
      }
      if (AFTER_ATTACK(effect, 0, this) && this.usedLightSteps) {
        this.usedLightSteps = false;
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        const hasEnergy = player.active.cards.some((c) => c instanceof EnergyCard);
        if (!hasBenched || !hasEnergy) {
          return state;
        }
        const blocked = [];
        player.active.cards.forEach((card, index) => {
          if (!(card instanceof EnergyCard)) {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_ATTACH,
          player.active,
          { superType: 3 /* ENERGY */ },
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length === 0) {
            return;
          }
          return store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ), (targets) => {
            if (targets && targets.length > 0) {
              MOVE_CARDS(store, state, player.active, targets[0], { cards: [cards[0]], sourceCard: this });
            }
          });
        });
      }
      if (effect instanceof EndTurnEffect) {
        this.usedLightSteps = false;
      }
      return state;
    }
  };

