  var WhiteKyurem2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: M }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Burning Icicles",
          cost: [W, C],
          damage: 40,
          text: "If this Pok\xE9mon has any [R] Energy attached to it, this attack does 20 damage to 2 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Blizzard Burn",
          cost: [W, W, C],
          damage: 130,
          text: "This Pok\xE9mon can't attack during your next turn."
        }
      ];
      this.set = "FCO";
      this.setNumber = "21";
      this.cardImage = "assets/cardback.png";
      this.name = "White Kyurem";
      this.fullName = "White Kyurem FCO";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkEnergy);
        let hasFireEnergy = false;
        checkEnergy.energyMap.forEach((em) => {
          if (em.provides.includes(2 /* FIRE */)) {
            hasFireEnergy = true;
          }
        });
        if (hasFireEnergy) {
          const benchedWithCards = opponent.bench.filter((b) => b.cards.length > 0);
          if (benchedWithCards.length > 0) {
            const maxTargets = Math.min(2, benchedWithCards.length);
            store.prompt(state, new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
              1 /* TOP_PLAYER */,
              [2 /* BENCH */],
              { min: maxTargets, max: maxTargets, allowCancel: false }
            ), (selected) => {
              if (selected) {
                selected.forEach((target) => {
                  const damage = new PutDamageEffect(effect, 20);
                  damage.target = target;
                  store.reduceEffect(state, damage);
                });
              }
            });
          }
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        effect.player.active.cannotAttackNextTurnPending = true;
      }
      return state;
    }
  };

