  function* playCard123(next, store, state, effect) {
    const player = effect.player;
    const movedToBench = player.active;
    const hasBench = player.bench.some((b) => b.cards.length > 0);
    if (hasBench === false) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: effect.trainerCard });
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_SWITCH,
        2 /* BOTTOM_PLAYER */,
        [2 /* BENCH */],
        { allowCancel: false }
      ),
      (results) => {
        targets = results || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    player.switchPokemon(targets[0], store, state);
    state = store.reduceEffect(state, new HealEffect(player, movedToBench, 30));
    return state;
  }
  var Olympia = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "GEN";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "66";
      this.name = "Olympia";
      this.fullName = "Olympia GEN";
      this.text = "Switch your Active Pok\xE9mon with 1 of your Benched Pok\xE9mon. If you do, heal 30 damage from the Pok\xE9mon you moved to your Bench. You may play only 1 Supporter card during your turn (before your attack).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard123(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

