  var JolteonEX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["EX" /* POKEMON_EX */];
      this.cardType = [L];
      this.hp = 160;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Swift",
          cost: [L],
          damage: 30,
          shredAttack: true,
          text: "This attack's damage isn't affected by Weakness, Resistance, or any other effects on your opponent's Active Pok\xE9mon."
        },
        {
          name: "Flash Ray",
          cost: [L, C, C],
          damage: 70,
          text: "During your opponent's next turn, prevent all damage done to this Pok\xE9mon by attacks from Basic Pok\xE9mon."
        }
      ];
      this.set = "GEN";
      this.setNumber = "28";
      this.cardImage = "assets/cardback.png";
      this.name = "Jolteon-EX";
      this.fullName = "Jolteon-EX GEN";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_ATTACKS_DAMAGE_ISNT_AFFECTED_BY_EFFECTS(store, state, effect, 30);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        PREVENT_DAMAGE(store, state, effect, this, { sourceStage: 2 /* BASIC */ });
      }
      return state;
    }
  };

