  function* playCard124(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: effect.trainerCard });
    effect.preventDefault = true;
    const cm = CardManager.getInstance();
    const evolutions = cm.getAllCards().filter((c) => {
      return c instanceof PokemonCard && c.stage !== 2 /* BASIC */ && !c.hasTag("EX" /* POKEMON_EX */);
    });
    const evolutionNames = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
      const valid = evolutions.filter((e) => e.evolvesFrom === card.name);
      valid.forEach((c) => {
        if (!evolutionNames.includes(c.name)) {
          evolutionNames.push(c.name);
        }
      });
    });
    if (evolutionNames.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (card instanceof PokemonCard && !evolutionNames.includes(card.name)) {
        blocked.push(index);
      }
    });
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_EVOLVE,
        player.deck,
        { superType: 1 /* POKEMON */ },
        { min: 1, max: 1, allowCancel: true, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    const evolution = cards[0];
    const blocked2 = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
      if (card.name !== evolution.evolvesFrom && !card.hasTag("EX" /* POKEMON_EX */)) {
        blocked2.push(target);
      }
    });
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_EVOLVE,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: false, blocked: blocked2 }
      ),
      (selection) => {
        targets = selection || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    const pokemonCard = targets[0].getPokemonCard();
    if (pokemonCard === void 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.deck, targets[0], { cards: [evolution], sourceCard: effect.trainerCard });
    targets[0].clearEffects();
    targets[0].pokemonPlayedTurn = state.turn;
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var Wally = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "ROS";
      this.name = "Wally";
      this.fullName = "Wally ROS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "94";
      this.text = "Search your deck for a card that evolves from 1 of your Pok\xE9mon (excluding Pok\xE9mon-EX) and put it onto that Pok\xE9mon. (This counts as evolving that Pok\xE9mon.) Shuffle your deck afterward. You can use this card during your first turn or on a Pok\xE9mon that was put into play this turn.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard124(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

