  init_prefabs();
  function* useMagicalSwap(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const maxAllowedDamage = [];
    opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
      const checkHpEffect = new CheckHpEffect(opponent, cardList);
      store.reduceEffect(state, checkHpEffect);
      maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
    });
    return store.prompt(state, new MoveDamagePrompt(
      effect.player.id,
      GameMessage.MOVE_DAMAGE,
      1 /* TOP_PLAYER */,
      [1 /* ACTIVE */, 2 /* BENCH */],
      maxAllowedDamage,
      { allowCancel: true }
    ), (transfers) => {
      if (transfers === null) {
        return;
      }
      for (const transfer of transfers) {
        const source = StateUtils.getTarget(state, player, transfer.from);
        const target = StateUtils.getTarget(state, player, transfer.to);
        if (source.damage >= 10) {
          source.damage -= 10;
          target.damage += 10;
        }
      }
    });
  }
  var Meowstic3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Espurr";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Ear Influence",
          cost: [P],
          damage: 0,
          text: "Move as many damage counters on your opponent's Pok\xE9mon as you like to any of your opponent's other Pok\xE9mon in any way you like."
        },
        {
          name: "Psychic",
          cost: [P, P, P],
          damage: 60,
          damageCalculation: "+",
          text: "Does 10 more damage for each Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "GEN";
      this.setNumber = "RC15";
      this.cardImage = "assets/cardback.png";
      this.name = "Meowstic";
      this.fullName = "Meowstic GEN";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const generator = useMagicalSwap(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        const energyCount = checkProvidedEnergyEffect.energyMap.reduce((left, p) => left + p.provides.length, 0);
        effect.damage += energyCount * 10;
      }
      return state;
    }
  };

