  var MeowsticEX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["EX" /* POKEMON_EX */];
      this.cardType = [P];
      this.hp = 160;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Shadow Ear",
          powerType: 2 /* ABILITY */,
          useWhenInPlay: true,
          text: "Once during your turn (before your attack), if this Pok\xE9mon is your Active Pok\xE9mon, you may move 1 damage counter from 1 of your Pok\xE9mon to 1 of your opponent's Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Mind Shock",
          cost: [P, C],
          damage: 60,
          text: "This attack's damage isn't affected by Weakness or Resistance."
        }
      ];
      this.set = "GEN";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "37";
      this.name = "Meowstic-EX";
      this.fullName = "Meowstic-EX GEN";
      this.SHADOW_EAR_MARKER = "SHADOW_EAR_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.marker.hasMarker(this.SHADOW_EAR_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.active.getPokemonCard() !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blockedTo = [];
        const blockedFrom = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          blockedTo.push(target);
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          blockedFrom.push(target);
        });
        const maxAllowedDamage = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(opponent, cardList);
          store.reduceEffect(state, checkHpEffect);
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(player, cardList);
          store.reduceEffect(state, checkHpEffect);
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        return store.prompt(
          state,
          new MoveDamagePrompt(
            effect.player.id,
            GameMessage.MOVE_DAMAGE,
            0 /* ANY */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            maxAllowedDamage,
            { min: 1, max: 1, allowCancel: false, blockedTo, blockedFrom }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            player.marker.addMarker(this.SHADOW_EAR_MARKER, this);
            ABILITY_USED(player, this);
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              if (source.damage >= 10) {
                source.damage -= 10;
                target.damage += 10;
              }
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.ignoreWeakness = true;
        effect.ignoreResistance = true;
      }
      return state;
    }
  };

