  var Revitalizer = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "GEN";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "70";
      this.name = "Revitalizer";
      this.fullName = "Revitalizer GEN";
      this.text = "Put 2 [G] Pok\xE9mon from your discard pile into your hand.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        let pokemonInDiscard = 0;
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          if (c instanceof PokemonCard && pokemonHasCardType(c, 1 /* GRASS */)) {
            pokemonInDiscard += 1;
          } else {
            blocked.push(index);
          }
        });
        if (pokemonInDiscard === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const discardEffect = new DiscardToHandEffect(player, this);
        store.reduceEffect(state, discardEffect);
        if (discardEffect.preventDefault) {
          return state;
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        let cards = [];
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.discard,
            { superType: 1 /* POKEMON */ },
            { min: Math.min(pokemonInDiscard, 2), max: 2, allowCancel: false, blocked }
          ),
          (selected) => {
            cards = selected || [];
            MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: this });
            return state;
          }
        );
      }
      return state;
    }
  };

