  var Absol3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 100;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Cursed Eyes",
        powerType: 2 /* ABILITY */,
        exemptFromInitialize: true,
        text: "When you play this Pok\xE9mon from your hand onto your Bench, you may move 3 damage counters from 1 of your opponent's Pok\xE9mon to another of his or her Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Mach Claw",
          cost: [D, C],
          damage: 30,
          text: "This attack's damage isn't affected by Resistance."
        }
      ];
      this.set = "ROS";
      this.setNumber = "40";
      this.cardImage = "assets/cardback.png";
      this.name = "Absol";
      this.fullName = "Absol ROS";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        state = store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (!wantToUse) {
            return;
          }
          try {
            const stub = new PowerEffect(player, this.powers[0], this);
            store.reduceEffect(state, stub);
          } catch {
            return;
          }
          const opponent = StateUtils.getOpponent(state, player);
          let hasDamage = false;
          opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
            if (cardList.damage > 0) {
              hasDamage = true;
            }
          });
          if (!hasDamage) {
            return;
          }
          const blockedFrom = [];
          opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
            if (cardList.damage === 0) {
              blockedFrom.push(target);
            }
          });
          MOVE_DAMAGE_COUNTERS(store, state, player, {
            playerType: 1 /* TOP_PLAYER */,
            slots: [1 /* ACTIVE */, 2 /* BENCH */],
            min: 0,
            max: 3,
            allowCancel: true,
            blockedFrom,
            singleSourceTarget: true
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.ignoreResistance = true;
      }
      return state;
    }
  };

