      this.attacks = [
        {
          name: "Song of Echoes",
          cost: [C],
          damage: 0,
          text: "Shuffle your hand into your deck. Then, draw a number of cards equal to the number of Benched Pok\xE9mon (both yours and your opponent's)."
        },
        {
          name: "Midnight Eyes",
          cost: [W, M],
          damage: 30,
          text: "Your opponent's Active Pok\xE9mon is now Asleep."
        }
      ];
      this.set = "ROS";
