  function* useWhirlwind(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const opponentHasBenched = opponent.bench.some((b) => b.cards.length > 0);
    if (!opponentHasBenched) {
      return state;
    }
    let wantToUse = false;
    yield store.prompt(
      state,
      new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_SWITCH_POKEMON),
      (result) => {
        wantToUse = result;
        next();
      }
    );
    if (!wantToUse) {
      return state;
    }
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
        1 /* TOP_PLAYER */,
        [2 /* BENCH */],
        { allowCancel: false }
      ),
      (selected) => {
        if (!selected || selected.length === 0) {
          return state;
        }
        const target = selected[0];
        opponent.switchPokemon(target);
        next();
      }
    );
    return state;
  }
  var Beautifly2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Silcoon";
      this.cardType = [1 /* GRASS */];
      this.hp = 130;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.retreat = [];
      this.powers = [
        {
          name: "Miraculous Scales",
          powerType: 2 /* ABILITY */,
          text: "Prevent all damage done to this Pokemon by attacks from your opponent's Pokemon-EX."
        }
      ];
      this.attacks = [
        {
          name: "Whirlwind",
          cost: [1 /* GRASS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 80,
          text: "You may have your opponent switch his or her Active Pokemon with 1 of his or her Benched Pokemon."
        }
      ];
      this.set = "ROS";
      this.name = "Beautifly";
      this.fullName = "Beautifly ROS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "5";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const generator = useWhirlwind(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        const sourceCard = effect.source.getPokemonCard();
        if (pokemonCard !== this || sourceCard === void 0) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        const opponent = StateUtils.findOwner(state, effect.source);
        if (player === opponent) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        if (sourceCard.hasTag("EX" /* POKEMON_EX */)) {
          try {
            const stub = new PowerEffect(
              player,
              {
                name: "test",
                powerType: 2 /* ABILITY */,
                text: ""
              },
              this
            );
            store.reduceEffect(state, stub);
          } catch {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      return state;
    }
  };

