  var Dustox2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Cascoon";
      this.cardType = [G];
      this.hp = 130;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [{
        name: "Delta Plus",
        powerType: 3 /* ANCIENT_TRAIT */,
        text: "If your opponent's Pokemon is Knocked Out by damage from an attack of this Pokemon, take 1 more Prize card."
      }];
      this.attacks = [
        {
          name: "Flap",
          cost: [G],
          damage: 20,
          text: ""
        },
        {
          name: "Wind Shard",
          cost: [G, C, C],
          damage: 0,
          text: " This attack does 50 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.) "
        }
      ];
      this.set = "ROS";
      this.cardImage = "assets/cardback.png";
      this.fullName = "Dustox ROS";
      this.name = "Dustox";
      this.setNumber = "8";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        state = store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          const damageEffect = new PutDamageEffect(effect, 50);
          damageEffect.target = targets[0];
          store.reduceEffect(state, damageEffect);
        });
        return state;
      }
      return DELTA_PLUS(store, state, effect, this);
    }
  };

