  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-roaring-skies/electrode.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_game_phase_effects();
  init_prefabs();
  init_attack_effects2();
  var Electrode8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Voltorb";
      this.cardType = [L];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C];
      this.usedEnergyBomb = false;
      this.attacks = [
        {
          name: "Continuous Tumble",
          cost: [C],
          damage: 20,
          damageCalculation: "x",
          text: "Flip a coin until you get tails. This attack does 20 damage times the number of heads."
        },
        {
          name: "Energy Bomb",
          cost: [L, C, C],
          damage: 70,
          text: "You may move all Energy from this Pok\xE9mon to your Benched Pok\xE9mon in any way you like."
        }
      ];
      this.set = "ROS";
      this.setNumber = "22";
      this.cardImage = "assets/cardback.png";
      this.name = "Electrode";
      this.fullName = "Electrode ROS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return FLIP_A_COIN_UNTIL_YOU_GET_TAILS_DO_X_DAMAGE_PER_HEADS(store, state, effect, 20);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedEnergyBomb = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedEnergyBomb) {
        this.usedEnergyBomb = false;
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        CONFIRMATION_PROMPT(store, state, player, (result) => {
          if (result) {
            const blockedCards = [];
            const blockedMap = [];
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
              const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
              store.reduceEffect(state, checkProvidedEnergy);
              checkProvidedEnergy.energyMap.forEach((em) => {
                if (em.provides.length === 0) {
                  blockedCards.push(em.card);
                }
              });
              const blocked = [];
              blockedCards.forEach((bc) => {
                const index = cardList.cards.indexOf(bc);
                if (index !== -1 && !blocked.includes(index)) {
                  blocked.push(index);
                }
              });
              if (blocked.length !== 0) {
                blockedMap.push({ source: target, blocked });
              }
            });
            const attachedEnergies = player.active.cards.filter((c) => !blockedCards.includes(c));
            if (attachedEnergies.length === 0) {
              return;
            }
            const blockedFrom = [];
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
              if (cardList !== player.active) {
                blockedFrom.push(target);
              }
            });
            store.prompt(state, new MoveEnergyPrompt(
              player.id,
              GameMessage.MOVE_ENERGY_CARDS,
              2 /* BOTTOM_PLAYER */,
              [1 /* ACTIVE */, 2 /* BENCH */],
              {},
              { allowCancel: false, min: attachedEnergies.length, max: attachedEnergies.length, blockedMap, blockedFrom }
            ), (transfers) => {
              transfers = transfers || [];
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
              }
            });
          }
        }, GameMessage.MOVE_ENERGY_TO_BENCH);
      }
      if (effect instanceof EndTurnEffect && this.usedEnergyBomb) {
        this.usedEnergyBomb = false;
      }
      return state;
    }
  };

