  var Reshiram4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [N];
      this.weakness = [{ type: Y }];
      this.hp = 130;
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Turboblaze",
          powerType: 2 /* ABILITY */,
          useWhenInPlay: true,
          text: "Once during your turn (before your attack), if this Pok\xE9mon is your Active Pok\xE9mon, you may attach a [R] Energy card from your hand to 1 of your [N] Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Bright Wing",
          cost: [R, R, L, C],
          damage: 110,
          text: "Discard a [R] Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "ROS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "63";
      this.name = "Reshiram";
      this.fullName = "Reshiram ROS";
      this.TURBOBLAZE_MARKER = "TURBOBLAZE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(R);
        });
        if (HAS_MARKER(this.TURBOBLAZE_MARKER, effect.player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.active.cards[0] !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.hand,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { allowCancel: false, max: 1, min: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            const energyCard = transfer.card;
            const attachEnergyEffect = new AttachEnergyEffect(player, energyCard, target);
            store.reduceEffect(state, attachEnergyEffect);
          }
          ABILITY_USED(effect.player, this);
          ADD_MARKER(this.TURBOBLAZE_MARKER, effect.player, this);
          return state;
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1, R);
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.TURBOBLAZE_MARKER, this);
      return state;
    }
  };

