  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-roaring-skies/wurmple.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_game_message();
  init_prefabs();
  function* useFlock(next, store, state, effect) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const max = Math.min(slots2.length, 1);
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
      player.deck,
      { superType: 1 /* POKEMON */, stage: 2 /* BASIC */, name: "Wurmple" },
      { min: 0, max, allowCancel: true }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      store.reduceEffect(state, new PlayPokemonFromDeckEffect(player, card, slots2[index]));
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var Wurmple2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [1 /* GRASS */];
      this.hp = 60;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Flock",
          cost: [1 /* GRASS */],
          damage: 0,
          text: "Search your deck for Wurmple and put it onto your Bench. Shuffle your deck afterward."
        },
        {
          name: "Tackle",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 20,
          text: ""
        }
      ];
      this.set = "ROS";
      this.name = "Wurmple";
      this.fullName = "Wurmple ROS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "3";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const generator = useFlock(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-roaring-skies/xatu.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_trainer_card();
  init_prefabs();
  init_order_cards_prompt();
  var Xatu3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Natu";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Future Sight",
          cost: [C],
          damage: 0,
          text: "Look at the top 5 cards of either player's deck and put them back on top of that player's deck in any order."
        },
        {
          name: "Stressful Eye",
          cost: [P, C],
          damage: 30,
          text: "Your opponent reveals his or her hand. Discard a Trainer card you find there."
        }
      ];
      this.set = "ROS";
      this.setNumber = "29";
      this.cardImage = "assets/cardback.png";
      this.name = "Xatu";
      this.fullName = "Xatu ROS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const options = [
          {
            message: GameMessage.ORDER_YOUR_DECK,
            action: () => {
              if (player.deck.cards.length === 0) {
                return;
              }
              const deckTop = new CardList();
              MOVE_CARDS(store, state, player.deck, deckTop, { count: Math.min(5, player.deck.cards.length), sourceCard: this });
              store.prompt(state, new OrderCardsPrompt(
                player.id,
                GameMessage.CHOOSE_CARDS_ORDER,
                deckTop,
                { allowCancel: false }
              ), (order) => {
                if (order === null) {
                  return;
                }
                deckTop.applyOrder(order);
                deckTop.moveToTopOfDestination(player.deck);
              });
            }
          },
          {
            message: GameMessage.ORDER_OPPONENT_DECK,
            action: () => {
              if (opponent.deck.cards.length === 0) {
                return;
              }
              const deckTop = new CardList();
              MOVE_CARDS(store, state, opponent.deck, deckTop, { count: Math.min(5, opponent.deck.cards.length), sourceCard: this });
              store.prompt(state, new OrderCardsPrompt(
                player.id,
                GameMessage.CHOOSE_CARDS_ORDER,
                deckTop,
                { allowCancel: false }
              ), (order) => {
                if (order === null) {
                  return;
                }
                deckTop.applyOrder(order);
                deckTop.moveToTopOfDestination(opponent.deck);
              });
            }
          }
        ];
        return store.prompt(state, new SelectPrompt(
          player.id,
          GameMessage.CHOOSE_OPTION,
          options.map((opt) => opt.message),
          { allowCancel: false }
        ), (choice) => {
          const option = options[choice];
          option.action();
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        SHOW_CARDS_TO_PLAYER(store, state, player, opponent.hand.cards);
        const trainerCards = opponent.hand.cards.filter((c) => c instanceof TrainerCard);
        if (trainerCards.length > 0) {
          const blocked = [];
          opponent.hand.cards.forEach((card, index) => {
            if (!(card instanceof TrainerCard)) {
              blocked.push(index);
            }
          });
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.hand,
            { superType: 2 /* TRAINER */ },
            { min: 1, max: 1, allowCancel: false, blocked }
          ), (selected) => {
            const cards = selected || [];
            MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards });
          });
        }
      }
      return state;
    }
  };

