  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-roaring-skies/healing-scarf.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_game_effects();
  init_prefabs();
  var HealingScarf = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "ROS";
      this.setNumber = "84";
      this.cardImage = "assets/cardback.png";
      this.name = "Healing Scarf";
      this.fullName = "Healing Scarf ROS";
      this.text = "Whenever you attach an Energy card from your hand to the Pok\xE9mon this card is attached to, heal 20 damage from it.";
    }
    // Ref: set-x-and-y/hard-charm.ts (Tool effect pattern), set-phantom-forces/gliscor.ts (AttachEnergyEffect interception)
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect) {
        if (!effect.target.tools.includes(this)) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (effect.player !== player) {
          return state;
        }
        const healEffect = new HealEffect(player, effect.target, 20);
        store.reduceEffect(state, healEffect);
      }
      return state;
    }
  };

