  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-roaring-skies/mega-turbo.ts
  init_game();
  init_play_card_effects();
  init_prefabs();
  var MegaTurbo = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "ROS";
      this.name = "Mega Turbo";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "86";
      this.fullName = "Mega Turbo ROS";
      this.text = "Attach a basic Energy card from your discard pile to 1 of your Mega Evolution Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        let hasMegaPokemonInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card) => {
          if (list && list.cards.some((card2) => card2.hasTag("Mega EX" /* MEGA */))) {
            hasMegaPokemonInPlay = true;
          }
        });
        if (!hasMegaPokemonInPlay) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked2 = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (!card.hasTag("Mega EX" /* MEGA */)) {
            blocked2.push(target);
          }
        });
        effect.preventDefault = true;
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: 1, max: 1, blockedTo: blocked2 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
            MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [this], sourceCard: this });
          }
        );
      }
      return state;
    }
  };

