  var WideLens = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "ROS";
      this.name = "Wide Lens";
      this.fullName = "Muscle Band ROS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "95";
      this.text = " Damage from the attacks of the Pok\xE9mon this card is attached to is affected by Weakness and Resistance for your opponent's Benched Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.player.active.tools.includes(this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        opponent.bench.forEach((card) => {
          if (effect.damage > 0 && effect.target === card) {
            const applyWeakness = new ApplyWeaknessEffect(effect.attackEffect, effect.damage);
            applyWeakness.target = effect.target;
            state = store.reduceEffect(state, applyWeakness);
            effect.damage = applyWeakness.damage;
          }
          const damage = Math.max(0, effect.damage);
          if (damage > 0) {
            const afterDamageEffect = new AfterDamageEffect(effect.attackEffect, damage);
            afterDamageEffect.target = effect.target;
            store.reduceEffect(state, afterDamageEffect);
          }
        });
        return state;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-roaring-skies/winona.ts
  init_game();
  init_game_message();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_choose_cards_prompt();
  init_show_cards_prompt();
  init_shuffle_prompt();
  init_state_utils();
  init_prefabs();
  function* playCard126(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 1 /* POKEMON */, cardType: [9 /* COLORLESS */] },
        { min: 0, max: 3, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [self], sourceCard: self });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var Winona = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "ROS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "96";
      this.name = "Winona";
      this.fullName = "Winona ROS";
      this.text = "Search your deck for up to 3 [C] Pok\xE9mon, reveal them, and put them into your hand. Shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard126(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

