  var Aipom4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 60;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Fiddle Around",
          cost: [C],
          damage: 0,
          text: "Look at the top 3 cards of your opponent's deck and put them back in any order."
        },
        {
          name: "Tail Jab",
          cost: [C, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "STS";
      this.setNumber = "90";
      this.cardImage = "assets/cardback.png";
      this.name = "Aipom";
      this.fullName = "Aipom STS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.deck.cards.length === 0) {
          return state;
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, opponent.deck, deckTop, { count: Math.min(3, opponent.deck.cards.length), sourceCard: this });
        return store.prompt(state, new OrderCardsPrompt(
          player.id,
          GameMessage.CHOOSE_CARDS_ORDER,
          deckTop,
          { allowCancel: false }
        ), (order) => {
          if (order === null) {
            return;
          }
          deckTop.applyOrder(order);
          deckTop.moveToTopOfDestination(opponent.deck);
        });
      }
      return state;
    }
  };

