  var Armaldo3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Anorith";
      this.cardType = [F];
      this.hp = 150;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Rushing Water",
          cost: [C],
          damage: 40,
          text: "Move an Energy from your opponent's Active Pok\xE9mon to 1 of his or her Benched Pok\xE9mon."
        },
        {
          name: "Guard Claw",
          cost: [F, C, C],
          damage: 100,
          text: "During your opponent's next turn, any damage done to this Pok\xE9mon by attacks is reduced by 30 (after applying Weakness and Resistance)."
        }
      ];
      this.set = "STS";
      this.setNumber = "57";
      this.cardImage = "assets/cardback.png";
      this.name = "Armaldo";
      this.fullName = "Armaldo STS";
      this.usedRushingWater = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedRushingWater = true;
      }
      if (effect instanceof EndTurnEffect && this.usedRushingWater) {
        this.usedRushingWater = false;
      }
      if (effect instanceof AfterAttackEffect && this.usedRushingWater) {
        this.usedRushingWater = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const energyCards = opponent.active.cards.filter((c) => c.superType === 3 /* ENERGY */);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (energyCards.length === 0 || !hasBenched) {
          return state;
        }
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          opponent.active,
          { superType: 3 /* ENERGY */ },
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            return;
          }
          const energyCard = selected[0];
          store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ), (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            MOVE_CARDS(store, state, opponent.active, targets[0], { cards: [energyCard], sourceCard: this });
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        effect.player.active.damageReductionNextTurn = 30;
      }
      return state;
    }
  };

