  var Drifloon4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 60;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Transfer Pain",
          cost: [C],
          damage: 0,
          text: "Move 1 damage counter from 1 of your Pok\xE9mon to 1 of your opponent's Pok\xE9mon."
        }
      ];
      this.set = "STS";
      this.setNumber = "46";
      this.cardImage = "assets/cardback.png";
      this.name = "Drifloon";
      this.fullName = "Drifloon STS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let hasDamage = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.damage > 0) {
            hasDamage = true;
          }
        });
        if (!hasDamage) {
          return state;
        }
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.damage === 0) {
            blocked.push(target);
          }
        });
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (sourceTargets) => {
          if (!sourceTargets || sourceTargets.length === 0) {
            return;
          }
          const source = sourceTargets[0];
          store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ), (destTargets) => {
            if (!destTargets || destTargets.length === 0) {
              return;
            }
            const dest = destTargets[0];
            source.damage -= 10;
            dest.damage += 10;
          });
        });
      }
      return state;
    }
  };

