  init_pokemon_card();
  init_card_types();
  init_game();
  init_trainer_card();
  init_game_effects();
  init_play_card_effects();
  init_choose_cards_prompt();
  init_prefabs();
  var Foongus5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 40;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [{
        name: "Play Ball",
        powerType: 2 /* ABILITY */,
        exemptFromInitialize: true,
        text: "When you play this Pok\xE9mon from your hand onto your Bench, you may put 3 Pok\xE9 Ball cards from your discard pile into your hand."
      }];
      this.attacks = [
        {
          name: "Ram",
          cost: [G],
          damage: 10,
          text: ""
        }
      ];
      this.set = "STS";
      this.setNumber = "12";
      this.cardImage = "assets/cardback.png";
      this.name = "Foongus";
      this.fullName = "Foongus STS";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const pokeBallsInDiscard = player.discard.cards.filter(
          (c) => c instanceof TrainerCard && c.name === "Pok\xE9 Ball"
        );
        if (pokeBallsInDiscard.length === 0) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (!wantToUse) {
            return;
          }
          try {
            const stub = new PowerEffect(player, this.powers[0], this);
            store.reduceEffect(state, stub);
          } catch {
            return;
          }
          const blocked = [];
          player.discard.cards.forEach((card, index) => {
            if (!(card instanceof TrainerCard && card.name === "Pok\xE9 Ball")) {
              blocked.push(index);
            }
          });
          const available = player.discard.cards.length - blocked.length;
          const count = Math.min(3, available);
          if (count > 0) {
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_HAND,
              player.discard,
              { superType: 2 /* TRAINER */ },
              { min: count, max: count, allowCancel: false, blocked }
            ), (selected) => {
              if (selected && selected.length > 0) {
                MOVE_CARDS(store, state, player.discard, player.hand, { cards: selected, sourceCard: this });
              }
            });
          }
        });
      }
      return state;
    }
  };

