  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-steam-siege/klefki.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_effects();
  init_prefabs();
  init_game_phase_effects();
  function* usePower5(next, store, state, self, effect) {
    const player = effect.player;
    const cardList = StateUtils.findCardList(state, self);
    const benchIndex = player.bench.indexOf(cardList);
    if (benchIndex === -1) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    const pokemonCard = player.bench[benchIndex].getPokemonCard();
    if (pokemonCard !== self) {
      throw new GameError(GameMessage.ILLEGAL_ACTION);
    }
    let hasPokemonWithoutTool = false;
    const blocked = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card, target) => {
      if (cardList2.tools.length === 0 && card !== self) {
        hasPokemonWithoutTool = true;
      } else {
        blocked.push(target);
      }
    });
    if (!hasPokemonWithoutTool) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    return store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: true, blocked }
      ),
      (targets) => {
        if (targets && targets.length > 0) {
          MOVE_CARDS(store, state, player.bench[benchIndex], targets[0], { cards: [pokemonCard], sourceCard: self });
          targets[0].tools.push(pokemonCard);
          const unownGSlot = player.bench[benchIndex];
          const unownGCard = unownGSlot.getPokemonCard();
          if (!unownGCard) {
            return state;
          }
          const otherCards = unownGSlot.cards.filter(
            (card) => !(card instanceof PokemonCard) && !unownGSlot.getPokemons().includes(card) && (!unownGSlot.tools || !unownGSlot.tools.includes(card))
          );
          const tools = [...unownGSlot.tools];
          if (tools.length > 0) {
            for (const tool of tools) {
              MOVE_CARDS(store, state, unownGSlot, player.discard, { cards: [tool], sourceCard: self });
            }
          }
          if (otherCards.length > 0) {
            MOVE_CARDS(store, state, unownGSlot, player.discard, { cards: otherCards });
          }
          unownGSlot.clearEffects();
        }
      }
    );
  }
  var Klefki4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [Y];
      this.hp = 70;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Wonder Lock",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn (before your attack), if this Pok\xE9mon is on your Bench, you may discard all cards attached to this Pok\xE9mon and attach it to 1 of your Pok\xE9mon as a Pok\xE9mon Tool card. Prevent any damage done to the Pok\xE9mon this card is attached to by attacks from your opponent's Mega Evolution Pok\xE9mon. If this card is attached to a Pok\xE9mon, discard this card at the end of your opponent's turn."
        }
      ];
      this.attacks = [
        {
          name: "Fairy Wind",
          cost: [Y, C],
          damage: 30,
          text: ""
        }
      ];
      this.set = "STS";
      this.name = "Klefki";
      this.fullName = "Klefki STS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "80";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const generator = usePower5(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (effect instanceof AttackEffect) {
        const target = effect.opponent?.active;
        if (!target || !target.cards.includes(this) || target.getPokemonCard() === this) {
          return state;
        }
        const sourceCard = effect.source?.getPokemonCard();
        if (sourceCard && sourceCard.hasTag("Mega EX" /* MEGA */)) {
          if (IS_ABILITY_BLOCKED(store, state, effect.player, this)) {
            return state;
          }
          effect.damage = 0;
          effect.preventDefault = true;
        }
      }
      if (effect instanceof EndTurnEffect) {
        const opponent = effect.player;
        const player = StateUtils.getOpponent(state, opponent);
        const cardList = StateUtils.findCardList(state, this);
        if (!(cardList instanceof PokemonCardList) || cardList.getPokemonCard() === this) {
          return state;
        }
        if (effect.player === StateUtils.findOwner(state, cardList)) {
          return state;
        }
        player.forEachPokemon(1 /* TOP_PLAYER */, (cardList2, card, index) => {
          if (cardList2.cards.includes(this)) {
            MOVE_CARDS(store, state, cardList2, player.discard, { cards: [this] });
          }
        });
      }
      return state;
    }
  };

