  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/07-x-and-y/set-steam-siege/nidoking.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_prefabs();
  var Nidoking4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Nidorino";
      this.cardType = [P];
      this.hp = 150;
      this.weakness = [{ type: P }];
      this.retreat = [C, C, C, C];
      this.powers = [{
        name: "King's Palace",
        powerType: 2 /* ABILITY */,
        text: "Your Nidoqueen's attacks do 20 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Power Lariat",
          cost: [P, P, C],
          damage: 60,
          damageCalculation: "+",
          text: "This attack does 30 more damage for each Evolution Pok\xE9mon on your Bench."
        }
      ];
      this.set = "STS";
      this.setNumber = "45";
      this.cardImage = "assets/cardback.png";
      this.name = "Nidoking";
      this.fullName = "Nidoking STS";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (effect.target !== opponent.active) {
          return state;
        }
        const attackingCard = player.active.getPokemonCard();
        if (!attackingCard || attackingCard.name !== "Nidoqueen") {
          return state;
        }
        let nidokingInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            nidokingInPlay = true;
          }
        });
        if (!nidokingInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.damage += 20;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let evolutionCount = 0;
        player.bench.forEach((benched) => {
          if (benched.cards.length > 0) {
            const pokemonCard = benched.getPokemonCard();
            if (pokemonCard && pokemonCard.stage !== 2 /* BASIC */) {
              evolutionCount++;
            }
          }
        });
        effect.damage += 30 * evolutionCount;
      }
      return state;
    }
  };

