  init_choose_cards_prompt();
  var Ponyta4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [R];
      this.hp = 60;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Returning Flames",
          cost: [C],
          damage: 0,
          text: "Put 2 [R] Energy cards from your discard pile into your hand."
        },
        {
          name: "Live Coal",
          cost: [R],
          damage: 10,
          text: ""
        }
      ];
      this.set = "STS";
      this.setNumber = "16";
      this.cardImage = "assets/cardback.png";
      this.name = "Ponyta";
      this.fullName = "Ponyta STS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blocked = [];
        player.discard.cards.forEach((card, index) => {
          if (!(card instanceof EnergyCard && card.energyType === 0 /* BASIC */ && card.provides.includes(2 /* FIRE */))) {
            blocked.push(index);
          }
        });
        const available = player.discard.cards.length - blocked.length;
        if (available > 0) {
          const count = Math.min(2, available);
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.discard,
            { superType: 3 /* ENERGY */ },
            { min: count, max: count, allowCancel: false, blocked }
          ), (selected) => {
            if (selected && selected.length > 0) {
              MOVE_CARDS(store, state, player.discard, player.hand, { cards: selected, sourceCard: this });
            }
          });
        }
      }
      return state;
    }
  };

