  var NinjaBoy = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "STS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "103";
      this.name = "Ninja Boy";
      this.fullName = "Ninja Boy STS";
      this.text = "Choose 1 of your Basic Pok\xE9mon in play. Search your deck for a Basic Pok\xE9mon and switch it with that Pok\xE9mon. (Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pok\xE9mon.) Shuffle the first Pok\xE9mon into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card.stage !== 2 /* BASIC */) {
            blocked.push(target);
          }
        });
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { allowCancel: false, blocked }
          ),
          (results) => {
            const target = results || [];
            if (target.length === 0) {
              return state;
            }
            let cards = [];
            return store.prompt(
              state,
              new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
                player.deck,
                { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
                { min: 1, max: 1, allowCancel: false }
              ),
              (selectedCards) => {
                cards = selectedCards || [];
                if (cards.length === 0) {
                  return state;
                }
                cards.forEach((card, index) => {
                  MOVE_CARDS(store, state, target[0], player.deck, {
                    cards: [card],
                    sourceCard: this
                  });
                  MOVE_CARDS(store, state, player.deck, target[0], {
                    cards: [card],
                    sourceCard: this
                  });
                });
                store.log(state, "LOG_PLAYER_SWITCHES_POKEMON_WITH_POKEMON_FROM_DECK" /* LOG_PLAYER_SWITCHES_POKEMON_WITH_POKEMON_FROM_DECK */, {
                  name: player.name,
                  card: target[0].getPokemonCard().name,
                  secondCard: cards[0].name
                });
                return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                  player.deck.applyOrder(order);
                });
              }
            );
          }
        );
      }
      return state;
    }
  };

