  var Altaria5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Swablu";
      this.cardType = [C];
      this.hp = 110;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Miraculous Charm",
          powerType: 2 /* ABILITY */,
          text: "Prevent all damage done to this Pok\xE9mon by attacks from your opponent's Pok\xE9mon V and Pok\xE9mon-GX."
        }
      ];
      this.attacks = [
        {
          name: "Speed Dive",
          cost: [C, C],
          damage: 60,
          text: ""
        }
      ];
      this.regulationMark = "D";
      this.set = "CPA";
      this.setNumber = "49";
      this.cardImage = "assets/cardback.png";
      this.name = "Altaria";
      this.fullName = "Altaria CPA";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        const sourceCard = effect.source.getPokemonCard();
        if (pokemonCard !== this || sourceCard === void 0) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        const attacker = StateUtils.findOwner(state, effect.source);
        if (player === attacker) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        if (sourceCard.hasTag("V" /* POKEMON_V */) || sourceCard.hasTag("GX" /* POKEMON_GX */)) {
          if (IS_ABILITY_BLOCKED(store, state, player, this)) {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      if (effect instanceof DealDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        const sourceCard = effect.source.getPokemonCard();
        if (pokemonCard !== this || sourceCard === void 0) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        const attacker = StateUtils.findOwner(state, effect.source);
        if (player === attacker) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        if (sourceCard.hasTag("V" /* POKEMON_V */) || sourceCard.hasTag("GX" /* POKEMON_GX */)) {
          if (IS_ABILITY_BLOCKED(store, state, player, this)) {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      return state;
    }
  };

