  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-champions-path/eldegoss-v.ts
  init_pokemon_card();
  init_card_types();
  init_play_card_effects();
  init_game();
  init_prefabs();
  var EldegossV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.regulationMark = "D";
      this.stage = 2 /* BASIC */;
      this.cardType = [1 /* GRASS */];
      this.hp = 180;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [
        {
          name: "Happy Match",
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may put a Supporter card from your discard pile into your hand."
        }
      ];
      this.attacks = [
        {
          name: "Float Up",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 50,
          text: "You may shuffle this Pok\xE9mon and all attached cards into your deck."
        }
      ];
      this.set = "CPA";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "5";
      this.name = "Eldegoss V";
      this.fullName = "Eldegoss V CPA";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasSupporterInDiscard = player.discard.cards.some((c) => {
          return c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */;
        });
        if (!hasSupporterInDiscard) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
                if (cardList.getPokemonCard() === this) {
                  store.log(state, "LOG_PLAYER_USES_ABILITY" /* LOG_PLAYER_USES_ABILITY */, {
                    name: player.name,
                    ability: "Happy Match"
                  });
                }
              });
              state = store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_HAND,
                  player.discard,
                  { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
                  { min: 1, max: 1, allowCancel: false }
                ),
                (selected) => {
                  const cards = selected || [];
                  if (cards.length > 0) {
                    MOVE_CARDS(store, state, player.discard, player.hand, {
                      cards,
                      sourceCard: this,
                      sourceEffect: this.powers[0]
                    });
                    store.prompt(
                      state,
                      [
                        new ShowCardsPrompt(
                          opponent.id,
                          GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                          cards
                        )
                      ],
                      () => {
                        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
                          if (cardList.getPokemonCard() === this) {
                            cardList.addBoardEffect(0 /* ABILITY_USED */);
                          }
                        });
                      }
                    );
                  }
                }
              );
            }
          }
        );
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        CONFIRMATION_PROMPT(store, state, effect.player, () => {
          const player = effect.player;
          player.active.clearEffects();
          MOVE_CARDS(store, state, player.active, player.deck, { sourceCard: this });
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      return state;
    }
  };

