  var GalarianObstagoon = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Galarian Linoone";
      this.cardType = [D];
      this.hp = 170;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Wicked Ruler",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn, you may have your opponent discard cards from their hand until they have 4 cards in their hand."
      }];
      this.attacks = [{
        name: "Knuckle Impact",
        cost: [C, C, C],
        damage: 180,
        text: "During your next turn, this Pok\xE9mon can't attack."
      }];
      this.regulationMark = "D";
      this.set = "CPA";
      this.name = "Galarian Obstagoon";
      this.fullName = "Galarian Obstagoon CPA";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "37";
      this.WICKED_RULER_MARKER = "WICKED_RULER_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_POKEMON_CANNOT_ATTACK_NEXT_TURN(effect.player);
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.WICKED_RULER_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const handSize = opponent.hand.cards.length;
        const cardsToRemove = handSize - 4;
        if (handSize <= 4) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.WICKED_RULER_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        try {
          const stub = new PowerEffect(player, {
            name: "test",
            powerType: 2 /* ABILITY */,
            text: ""
          }, this);
          store.reduceEffect(state, stub);
        } catch {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(state, new ChooseCardsPrompt(
          opponent,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          opponent.hand,
          {},
          { min: cardsToRemove, max: cardsToRemove, allowCancel: false }
        ), (selected) => {
          MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards: selected, sourceCard: this, sourceEffect: this.powers[0] });
          selected.forEach((card, index) => {
            store.log(state, "LOG_PLAYER_DISCARDS_CARD" /* LOG_PLAYER_DISCARDS_CARD */, { name: opponent.name, card: card.name, effectName: this.powers[0].name });
          });
          store.prompt(state, new ShowCardsPrompt(
            player.id,
            GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
            selected
          ), () => {
          });
          player.marker.addMarker(this.WICKED_RULER_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          return state;
        });
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.WICKED_RULER_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.WICKED_RULER_MARKER, this);
      }
      return state;
    }
  };

