  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-champions-path/incineroar-v.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_energy_card();
  init_prefabs();
  var IncineroarV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [R];
      this.hp = 220;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Grand Flame",
          cost: [R, R, C],
          damage: 90,
          text: "Attach up to 2 [R] Energy cards from your discard pile to 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Flare Blitzer",
          cost: [R, R, R, C],
          damage: 220,
          text: "This Pok\xE9mon also does 30 damage to itself."
        }
      ];
      this.regulationMark = "D";
      this.set = "CPA";
      this.setNumber = "8";
      this.cardImage = "assets/cardback.png";
      this.name = "Incineroar V";
      this.fullName = "Incineroar V CPA";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        const energyInDiscard = player.discard.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.name === "Fire Energy"
        );
        if (energyInDiscard.length === 0) {
          return state;
        }
        const max = Math.min(2, energyInDiscard.length);
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
            { allowCancel: false, min: 0, max, sameTarget: true }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        THIS_POKEMON_DOES_DAMAGE_TO_ITSELF(store, state, effect, 30);
      }
      return state;
    }
  };

