  function* playCard130(next, store, state, effect) {
    const player = effect.player;
    const blocked = [];
    let hasPokemonWithDamage = false;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target2) => {
      const energyCount = new CheckProvidedEnergyEffect(player, cardList);
      store.reduceEffect(state, energyCount);
      if (cardList.damage === 0 || energyCount.energyMap.length < 2) {
        blocked.push(target2);
      } else {
        hasPokemonWithDamage = true;
      }
    });
    if (hasPokemonWithDamage === false) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_HEAL,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { min: 1, max: 1, allowCancel: false, blocked }
      ),
      (results) => {
        targets = results || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    const target = targets[0];
    const healEffect = new HealEffect(player, target, 120);
    store.reduceEffect(state, healEffect);
    const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, target);
    state = store.reduceEffect(state, checkProvidedEnergy);
    const energyList = [9 /* COLORLESS */, 9 /* COLORLESS */];
    let cards = [];
    yield store.prompt(
      state,
      new ChooseEnergyPrompt(
        player.id,
        GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
        checkProvidedEnergy.energyMap,
        energyList,
        { allowCancel: false }
      ),
      (energy2) => {
        cards = (energy2 || []).map((e) => e.card);
        next();
      }
    );
    if (cards.length > 0) {
      MOVE_CARDS(store, state, target, player.discard, { cards, sourceCard: effect.trainerCard });
    }
    return state;
  }
