  function* playCard131(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: self });
    effect.preventDefault = true;
    let energy2 = 0;
    let pokemon = 0;
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      if (c.superType === 3 /* ENERGY */) {
        energy2 += 1;
      } else if (c instanceof PokemonCard && pokemonHasCardType(c, 7 /* DARK */)) {
        pokemon += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxEnergy = Math.min(energy2, 1);
    const maxPokemon = Math.min(pokemon, 1);
    const count = maxEnergy + maxPokemon;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_ONE_DARK_POKEMON_AND_ONE_ENERGY_TO_HAND,
        player.deck,
        {},
        {
          min: 0,
          max: count,
          allowCancel: false,
          blocked,
          maxEnergies: maxEnergy,
          maxPokemons: maxPokemon
        }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    player.playedPiers = true;
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
