  var Marnie = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "SSH";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "169";
      this.name = "Marnie";
      this.fullName = "Marnie SSH";
      this.text = "Each player shuffles their hand and puts it on the bottom of their deck. If either player put any cards on the bottom of their deck in this way, you draw 5 cards, and your opponent draws 4 cards.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const playerCards = player.hand.cards.filter((c) => c !== this);
        const opponentCards = [...opponent.hand.cards];
        if (playerCards.length === 0 && player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        if (playerCards.length === 0 && opponentCards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        this.shuffleCards(playerCards);
        this.shuffleCards(opponentCards);
        const runOpponent = () => {
          if (opponentCards.length > 0) {
            MOVE_HAND_TO_DECK_THEN_DRAW(store, state, opponent, {
              cards: opponentCards,
              drawCount: 4,
              sourceCard: this
            });
            return;
          }
          if (playerCards.length > 0) {
            DRAW_CARDS(store, state, opponent, 4);
          }
        };
        if (playerCards.length > 0) {
          return MOVE_HAND_TO_DECK_THEN_DRAW(store, state, player, {
            cards: playerCards,
            drawCount: 5,
            sourceCard: this,
            afterDraw: () => runOpponent()
          });
        }
        return MOVE_HAND_TO_DECK_THEN_DRAW(store, state, opponent, {
          cards: opponentCards,
          drawCount: 4,
          sourceCard: this,
          afterDraw: () => {
            DRAW_CARDS(store, state, player, 5);
          },
          onMovePrevented: () => {
            DRAW_CARDS(store, state, player, 5);
          }
        });
      }
      return state;
    }
    shuffleCards(cards) {
      for (let i = cards.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [cards[i], cards[j]] = [cards[j], cards[i]];
      }
    }
  };

