  var AlolanMukGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Alolan Grimer";
      this.cardType = [D];
      this.hp = 220;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Chemical Breath",
          cost: [D, C, C],
          damage: 10,
          damageCalculation: "+",
          text: "This attack does 70 more damage for each Special Condition affecting your opponent's Active Pok\xE9mon."
        },
        {
          name: "Crunch",
          cost: [D, D, C, C],
          damage: 120,
          text: "Discard an Energy from your opponent's Active Pok\xE9mon."
        },
        {
          name: "Tri Hazard-GX",
          cost: [],
          damage: 0,
          text: "Switch 1 of your opponent's Benched Pok\xE9mon with their Active Pok\xE9mon. The new Active Pok\xE9mon is now Burned, Paralyzed, and Poisoned. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "BUS";
      this.setNumber = "84";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Muk-GX";
      this.fullName = "Alolan Muk-GX BUS";
      this.usedTriHazardGx = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        const specialConditionCount = opponent.active.specialConditions.length;
        effect.damage += 70 * specialConditionCount;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        DISCARD_AN_ENERGY_FROM_OPPONENTS_ACTIVE_POKEMON(store, state, effect);
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          this.usedTriHazardGx = true;
          GUST_OPPONENT_BENCHED_POKEMON(store, state, player);
        }
      }
      if (effect instanceof AfterAttackEffect && this.usedTriHazardGx) {
        this.usedTriHazardGx = false;
        const opponent = StateUtils.getOpponent(state, effect.player);
        opponent.active.addSpecialCondition(4 /* BURNED */);
        opponent.active.addSpecialCondition(0 /* PARALYZED */);
        opponent.active.addSpecialCondition(3 /* POISONED */);
      }
      if (effect instanceof EndTurnEffect) {
        this.usedTriHazardGx = false;
      }
      return state;
    }
  };

