  var AlolanNinetales = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Alolan Vulpix";
      this.cardType = [W];
      this.hp = 110;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Luminous Barrier",
          powerType: 2 /* ABILITY */,
          text: "Prevent all effects of attacks, including damage, done to this Pok\xE9mon by your opponent's Pok\xE9mon-GX or Pok\xE9mon-EX."
        }
      ];
      this.attacks = [
        {
          name: "Aurora Beam",
          cost: [W, C, C],
          damage: 80,
          text: ""
        }
      ];
      this.set = "BUS";
      this.setNumber = "28";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Ninetales";
      this.fullName = "Alolan Ninetales BUS";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        const sourceCard = effect.source.getPokemonCard();
        if (pokemonCard !== this || sourceCard === void 0) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        const opponent = StateUtils.findOwner(state, effect.source);
        if (player === opponent) {
          return state;
        }
        if (sourceCard.hasTag("EX" /* POKEMON_EX */) || sourceCard.hasTag("GX" /* POKEMON_GX */)) {
          try {
            const powerEffect = new PowerEffect(player, this.powers[0], this);
            store.reduceEffect(state, powerEffect);
          } catch {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      return state;
    }
  };

