      this.retreat = [C, C, C];
      this.powers = [{
        name: "Dark Invitation",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may have your opponent reveal their hand. Put a Basic Pok\xE9mon you find there onto your opponent's Bench, and put 3 damage counters on that Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Mind Jack",
        cost: [P, C, C],
        damage: 30,
        damageCalculation: "+",
        text: "This attack does 30 more damage for each of your opponent's Benched Pok\xE9mon."
      }];
      this.set = "BUS";
