  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  function* useKingsOrder(next, store, state, effect, self) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const hasBasicInDiscard = player.hand.cards.some((c) => {
      return c instanceof PokemonCard && c.stage === 2 /* BASIC */;
    });
    if (!hasBasicInDiscard) {
      return state;
    }
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
      player.discard,
      { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
      { min: 1, max: 1, allowCancel: false }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      MOVE_CARDS(store, state, player.discard, slots2[index], { cards: [card], sourceCard: self });
      slots2[index].pokemonPlayedTurn = state.turn;
    });
  }
