  var Kingdra5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Seadra";
      this.cardType = [W];
      this.hp = 140;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Brine",
          cost: [W],
          damage: 0,
          text: "This attack does 90 damage to 1 of your opponent's Pok\xE9mon that has any damage counters on it. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Tornado Shot",
          cost: [W],
          damage: 90,
          text: "Discard a [W] Energy from this Pok\xE9mon. This attack does 30 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "BUS";
      this.setNumber = "31";
      this.cardImage = "assets/cardback.png";
      this.name = "Kingdra";
      this.fullName = "Kingdra BUS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasDamagedActive = opponent.active.damage > 0;
        const hasDamagedBench = opponent.bench.some((b) => b.cards.length > 0 && b.damage > 0);
        if (!hasDamagedActive && !hasDamagedBench) {
          return state;
        }
        const blocked = [];
        if (opponent.active.damage === 0) {
          blocked.push({ player: 1 /* TOP_PLAYER */, slot: 1 /* ACTIVE */, index: 0 });
        }
        opponent.bench.forEach((b, index) => {
          if (b.cards.length === 0 || b.damage === 0) {
            blocked.push({ player: 1 /* TOP_PLAYER */, slot: 2 /* BENCH */, index });
          }
        });
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (selected) => {
          const target = selected[0];
          if (target === opponent.active) {
            const damageEffect = new DealDamageEffect(effect, 90);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          } else {
            const damageEffect = new PutDamageEffect(effect, 90);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1, 3 /* WATER */);
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_BENCHED_POKEMON(30, effect, store, state);
      }
      return state;
    }
  };

