  var Lucario5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Riolu";
      this.cardType = [F];
      this.hp = 120;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Stance",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may prevent all effects of your opponent's attacks, including damage, done to this Pok\xE9mon until the end of your opponent's next turn."
      }];
      this.attacks = [
        {
          name: "Submarine Blow",
          cost: [F, F, F],
          damage: 120,
          text: ""
        }
      ];
      this.set = "BUS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "71";
      this.name = "Lucario";
      this.fullName = "Lucario BUS";
      this.STANCE_MARKER = "STANCE_MARKER";
      this.CLEAR_STANCE_MARKER = "CLEAR_STANCE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        CONFIRMATION_PROMPT(store, state, player, (wantToUse) => {
          if (wantToUse) {
            const cardList = StateUtils.findCardList(state, this);
            cardList.marker.addMarker(this.STANCE_MARKER, this);
          }
        }, GameMessage.WANT_TO_USE_ABILITY);
        return state;
      }
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this) && effect.target.marker.hasMarker(this.STANCE_MARKER, this)) {
        effect.preventDefault = true;
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner !== player) {
          cardList.marker?.removeMarker(this.STANCE_MARKER, this);
        }
      }
      return state;
    }
  };

