  var Mudsdale = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.usedKickAway = false;
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Mudbray";
      this.cardType = [F];
      this.hp = 130;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Kick Away",
          cost: [C, C, C],
          damage: 60,
          text: "Your opponent switches their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon."
        },
        {
          name: "Vigorous Dash",
          cost: [F, C, C, C],
          damage: 130,
          text: "This Pok\xE9mon does 30 damage to itself. This attack does 30 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "BUS";
      this.setNumber = "78";
      this.cardImage = "assets/cardback.png";
      this.name = "Mudsdale";
      this.fullName = "Mudsdale BUS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedKickAway = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedKickAway) {
        this.usedKickAway = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedKickAway = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        THIS_POKEMON_DOES_DAMAGE_TO_ITSELF(store, state, effect, 30);
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_BENCHED_POKEMON(30, effect, store, state);
      }
      return state;
    }
  };

