  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-burning-shadows/palossand.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_phase_effects();
  init_prefabs();
  var Palossand = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Sandygast";
      this.cardType = [P];
      this.hp = 130;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Sand Tomb",
          cost: [P, C, C],
          damage: 80,
          text: "The Defending Pok\xE9mon can't retreat during your opponent's next turn."
        },
        {
          name: "Dust Storm",
          cost: [C, C, C, C],
          damage: 100,
          text: "Discard all cards from both Active Pok\xE9mon."
        }
      ];
      this.set = "BUS";
      this.setNumber = "62";
      this.cardImage = "assets/cardback.png";
      this.name = "Palossand";
      this.fullName = "Palossand BUS";
      this.usedDustStorm = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return BLOCK_RETREAT(store, state, effect, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedDustStorm = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedDustStorm) {
        this.usedDustStorm = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const playerPokemons = player.active.getPokemons();
        const playerCards = player.active.cards.filter((c) => !playerPokemons.includes(c));
        playerCards.forEach((c) => {
          MOVE_CARDS(store, state, player.active, player.discard, { cards: [c], sourceCard: this });
        });
        const playerTools = player.active.tools.slice();
        playerTools.forEach((c) => {
          MOVE_CARDS(store, state, player.active, player.discard, { cards: [c], sourceCard: this });
        });
        const opponentPokemons = opponent.active.getPokemons();
        const opponentCards = opponent.active.cards.filter((c) => !opponentPokemons.includes(c));
        opponentCards.forEach((c) => {
          MOVE_CARDS(store, state, opponent.active, opponent.discard, { cards: [c], sourceCard: this });
        });
        const opponentTools = opponent.active.tools.slice();
        opponentTools.forEach((c) => {
          MOVE_CARDS(store, state, opponent.active, opponent.discard, { cards: [c], sourceCard: this });
        });
      }
      if (effect instanceof EndTurnEffect) {
        this.usedDustStorm = false;
      }
      return state;
    }
  };

