  init_game_phase_effects();
  var Seviper = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 100;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [{
        name: "More Poison",
        powerType: 2 /* ABILITY */,
        text: "Put 1 more damage counter on your opponent's Poisoned Pok\xE9mon between turns."
      }];
      this.attacks = [
        {
          name: "Venomous Fang",
          cost: [P, C, C],
          damage: 30,
          text: "Your opponent's Active Pok\xE9mon is now Poisoned."
        }
      ];
      this.set = "BUS";
      this.setNumber = "50";
      this.cardImage = "assets/cardback.png";
      this.name = "Seviper";
      this.fullName = "Seviper BUS";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof BetweenTurnsEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let seviperOwner = null;
        [player, opponent].forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
            if (card === this) {
              seviperOwner = p;
            }
          });
        });
        if (!seviperOwner) {
          return state;
        }
        try {
          const stub = new PowerEffect(seviperOwner, {
            name: "test",
            powerType: 2 /* ABILITY */,
            text: ""
          }, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        const seviperOpponent = StateUtils.getOpponent(state, seviperOwner);
        if (effect.player === seviperOpponent && seviperOpponent.active.specialConditions.includes(3 /* POISONED */)) {
          effect.poisonDamage += 10;
        }
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_POISON_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

