  var Vileplume6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Gloom";
      this.cardType = [G];
      this.hp = 140;
      this.weakness = [{ type: R }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Disgusting Pollen",
          powerType: 2 /* ABILITY */,
          text: "As long as this Pok\xE9mon is your Active Pok\xE9mon, your opponent's Basic Pok\xE9mon can't attack."
        }
      ];
      this.attacks = [
        {
          name: "Downer Shock",
          cost: [G, G, C],
          damage: 60,
          text: "Flip a coin. If heads, your opponent's Active Pok\xE9mon is now Asleep. If tails, your opponent's Active Pok\xE9mon is now Confused."
        }
      ];
      this.set = "BUS";
      this.setNumber = "6";
      this.cardImage = "assets/cardback.png";
      this.name = "Vileplume";
      this.fullName = "Vileplume BUS";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseAttackEffect) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (!effect.source.isStage(2 /* BASIC */) || opponent.active.getPokemonCard() !== this || IS_ABILITY_BLOCKED(store, state, opponent, this)) {
          return state;
        }
        const basicBlockEffect = new EffectOfAbilityEffect(opponent, this.powers[0], this, effect.source);
        store.reduceEffect(state, basicBlockEffect);
        if (basicBlockEffect.target === effect.source) {
          throw new GameError(GameMessage.BLOCKED_BY_ABILITY);
        }
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          const opponent = StateUtils.getOpponent(state, effect.player);
          if (result) {
            ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, opponent, this);
          } else {
            ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, opponent, this);
          }
        });
      }
      return state;
    }
  };

