  var MountLanakila = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "BUS";
      this.setNumber = "118";
      this.cardImage = "assets/cardback.png";
      this.name = "Mount Lanakila";
      this.fullName = "Mount Lanakila BUS";
      this.text = "The Retreat Cost of each Basic Pok\xE9mon in play (both yours and your opponent's) is Colorless more.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect && StateUtils.getStadiumCard(state) === this) {
        const pokemonCard = effect.player.active.getPokemonCard();
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, effect.player, effect.player.active, this)) {
          return state;
        }
        if (pokemonCard && pokemonCard.stage === 2 /* BASIC */) {
          effect.cost.push(9 /* COLORLESS */);
        }
        return state;
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-burning-shadows/olivia.ts
  init_trainer_card();
