  var Olivia = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "BUS";
      this.setNumber = "119";
      this.cardImage = "assets/cardback.png";
      this.name = "Olivia";
      this.fullName = "Olivia BUS";
      this.text = "Search your deck for up to 2 Pok\xE9mon-GX, reveal them, and put them into your hand. Then, shuffle your deck. You may play only 1 Supporter card during your turn (before your attack).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const searchBlocked = [];
        player.deck.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && !card.hasTag("GX" /* POKEMON_GX */)) {
            searchBlocked.push(index);
          }
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            { superType: 1 /* POKEMON */ },
            { min: 0, max: 2, allowCancel: true, blocked: searchBlocked }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              cards.forEach((card) => {
                MOVE_CARDS(store, state, player.deck, player.hand, { cards: [card], sourceCard: this });
              });
              store.prompt(
                state,
                new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
                () => {
                }
              );
            }
            store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      return state;
    }
  };

