  var PoTown = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "BUS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "121";
      this.name = "Po Town";
      this.fullName = "Po Town BUS";
      this.text = "Whenever any player plays a Pok\xE9mon from their hand to evolve 1 of their Pok\xE9mon, put 3 damage counters on that Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      if (effect instanceof EvolveEffect && StateUtils.getStadiumCard(state) === this) {
        const owner = StateUtils.findOwner(state, effect.target);
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, effect.target, this)) {
          return state;
        }
        effect.target.damage += 30;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-burning-shadows/rotom-dex-poke-finder-mode.ts
  init_trainer_card();
