  init_prefabs();
  var RotomDexPokeFinderMode = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "BUS";
      this.setNumber = "122";
      this.cardImage = "assets/cardback.png";
      this.name = "Rotom Dex Pok\xE9 Finder Mode";
      this.fullName = "Rotom Dex Pok\xE9 Finder Mode BUS";
      this.text = "Look at the top 4 cards of your deck and put them back in any order or shuffle them into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, {
          count: Math.min(4, player.deck.cards.length),
          sourceCard: this
        });
        return store.prompt(
          state,
          new ConfirmPrompt(player.id, GameMessage.ORDER_YOUR_DECK),
          (wantToOrder) => {
            if (wantToOrder) {
              store.prompt(
                state,
                new OrderCardsPrompt(player.id, GameMessage.CHOOSE_CARDS_ORDER, deckTop, {
                  allowCancel: false
                }),
                (order) => {
                  if (order === null) {
                    return state;
                  }
                  deckTop.applyOrder(order);
                  deckTop.moveToTopOfDestination(player.deck);
                }
              );
            } else {
              MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: this });
              store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                player.deck.applyOrder(order);
              });
            }
          }
        );
      }
      return state;
    }
  };

