  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-burning-shadows/wishful-baton.ts
  init_game_message();
  init_trainer_card();
  init_card_types();
  init_state();
  init_game_effects();
  init_attach_energy_prompt();
  init_play_card_action();
