  init_prefabs();
  init_card_list();
  var WishfulBaton = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "BUS";
      this.name = "Wishful Baton";
      this.fullName = "Wishful Baton BUS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "128";
      this.text = "If the Pok\xE9mon this card is attached to is your Active Pok\xE9mon and is Knocked Out by damage from an opponent's attack, move up to 3 basic Energy cards from that Pok\xE9mon to 1 of your Benched Pok\xE9mon.";
      this.WISHFUL_BATON_MARKER = "WISHFUL_BATON_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const active = effect.target;
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */ || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        if (active.marker.hasMarker(this.WISHFUL_BATON_MARKER)) {
          return state;
        }
        if (!active.tools.includes(this)) {
          return state;
        }
        const basicEnergyCards = active.cards.filter(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
        );
        if (basicEnergyCards.length === 0) {
          return state;
        }
        active.marker.addMarker(this.WISHFUL_BATON_MARKER, this);
        const energyToAttach = new CardList();
        energyToAttach.cards = basicEnergyCards.slice();
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            energyToAttach,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: true, min: 0, max: 3, sameTarget: true }
          ),
          (transfers) => {
            transfers = transfers || [];
            active.marker.removeMarker(this.WISHFUL_BATON_MARKER);
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card] });
            }
          }
        );
      }
      return state;
    }
  };

