  var AlolanRaticateGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Alolan Rattata";
      this.cardType = [D];
      this.hp = 200;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C];
      this.attacks = [{
        name: "Chuck Away",
        cost: [],
        damage: 40,
        damageCalculation: "x",
        text: "Discard up to 2 cards from your hand. This attack does 40 damage for each card you discarded in this way."
      }, {
        name: "Hyper Fang",
        cost: [D, C, C],
        damage: 150,
        text: "Flip a coin. If tails, this attack does nothing."
      }, {
        name: "Item Maniac-GX",
        cost: [],
        damage: 0,
        text: "Search your deck for up to 6 Item cards, reveal them, and put them into your hand. Then, shuffle your deck. (You can't use more than 1 GX attack in a game.)"
      }];
      this.set = "CES";
      this.setNumber = "85";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Raticate-GX";
      this.fullName = "Alolan Raticate-GX CES";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.hand.cards.length === 0) {
          effect.damage = 0;
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            {},
            { allowCancel: true, min: 0, max: 2 }
          ),
          (cards) => {
            cards = cards || [];
            effect.damage = cards.length * 40;
            MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (!result) {
            effect.damage = 0;
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        BLOCK_IF_DECK_EMPTY(player);
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            { superType: 2 /* TRAINER */, trainerType: 0 /* ITEM */ },
            { min: 0, max: 6, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              cards.forEach((card) => {
                MOVE_CARDS(store, state, player.deck, player.hand, { cards: [card], sourceCard: this });
              });
              store.prompt(
                state,
                new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
                () => {
                }
              );
            }
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      return state;
    }
  };

