  var Ariados3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Spinarak";
      this.cardType = [G];
      this.hp = 70;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Reactive Poison",
          cost: [C],
          damage: 20,
          damageCalculation: "+",
          text: "This attack does 50 more damage for each Special Condition affecting your opponent's Active Pok\xE9mon."
        },
        {
          name: "Spider Trap",
          cost: [G],
          damage: 0,
          text: "You may switch 1 of your opponent's Benched Pok\xE9mon with their Active Pok\xE9mon. Your opponent's Active Pok\xE9mon is now Asleep and Poisoned."
        }
      ];
      this.set = "CES";
      this.setNumber = "6";
      this.cardImage = "assets/cardback.png";
      this.name = "Ariados";
      this.fullName = "Ariados CES";
      this.usedSpiderTrap = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        effect.damage += 50 * opponent.active.specialConditions.length;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedSpiderTrap = true;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          store.prompt(state, new ConfirmPrompt(
            player.id,
            GameMessage.WANT_TO_USE_ABILITY
          ), (wantToSwitch) => {
            if (wantToSwitch) {
              GUST_OPPONENT_BENCHED_POKEMON(store, state, player);
            }
          });
        }
      }
      if (effect instanceof AfterAttackEffect && this.usedSpiderTrap) {
        this.usedSpiderTrap = false;
        const opponent = StateUtils.getOpponent(state, effect.player);
        opponent.active.addSpecialCondition(2 /* ASLEEP */);
        opponent.active.addSpecialCondition(3 /* POISONED */);
      }
      if (effect instanceof EndTurnEffect) {
        this.usedSpiderTrap = false;
      }
      return state;
    }
  };

