  var ArticunoGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 170;
      this.weakness = [{ type: M }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Legendary Ascent",
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may switch it with your Active Pok\xE9mon. If you do, move any number of [W] Energy from your other Pok\xE9mon to this Pok\xE9mon. "
        }
      ];
      this.attacks = [
        {
          name: "Ice Wing",
          cost: [W, W, C],
          damage: 130,
          text: ""
        },
        {
          name: "Cold Crush-GX",
          cost: [W],
          damage: 0,
          gxAttack: true,
          text: "Discard all Energy from both Active Pok\xE9mon. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "CES";
      this.setNumber = "31";
      this.cardImage = "assets/cardback.png";
      this.name = "Articuno-GX";
      this.fullName = "Articuno-GX CES";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              let bench;
              player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
                if (card === this && target.slot === 2 /* BENCH */) {
                  bench = cardList;
                }
              });
              if (bench) {
                player.switchPokemon(bench);
              }
              const blockedFrom = [];
              const blockedTo = [];
              let hasEnergyOnBench = false;
              player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
                if (cardList === player.active) {
                  blockedFrom.push(target);
                  return;
                }
                blockedTo.push(target);
                if (cardList.energies.cards.some(
                  (c) => c.superType === 3 /* ENERGY */ && c.name === "Water Energy"
                )) {
                  hasEnergyOnBench = true;
                }
              });
              if (hasEnergyOnBench === false) {
                return state;
              }
              return store.prompt(
                state,
                new MoveEnergyPrompt(
                  effect.player.id,
                  GameMessage.MOVE_ENERGY_TO_ACTIVE,
                  2 /* BOTTOM_PLAYER */,
                  [1 /* ACTIVE */, 2 /* BENCH */],
                  { superType: 3 /* ENERGY */, name: "Water Energy" },
                  { min: 1, allowCancel: false, blockedFrom, blockedTo }
                ),
                (result) => {
                  const transfers = result || [];
                  transfers.forEach((transfer) => {
                    const source = StateUtils.getTarget(state, player, transfer.from);
                    const target = StateUtils.getTarget(state, player, transfer.to);
                    MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
                  });
                }
              );
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, player.active);
        const opponentEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.reduceEffect(state, opponentEnergy);
        const cards = [];
        const oppCards = [];
        checkProvidedEnergy.energyMap.forEach((em) => {
          cards.push(em.card);
        });
        opponentEnergy.energyMap.forEach((em) => {
          oppCards.push(em.card);
        });
        const discardEnergy2 = new DiscardCardsEffect(effect, oppCards);
        discardEnergy2.target = opponent.active;
        store.reduceEffect(state, discardEnergy2);
        const discardEnergy3 = new DiscardCardsEffect(effect, cards);
        discardEnergy3.target = player.active;
        store.reduceEffect(state, discardEnergy3);
      }
      return state;
    }
  };

