  var Banette3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Shuppet";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Red Eyes",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may put a Basic Pok\xE9mon from your opponent's discard pile onto their Bench."
      }];
      this.attacks = [{
        name: "Enemy Show",
        cost: [P, C],
        damage: 0,
        text: "For each of your opponent's Pok\xE9mon in play, put 1 damage counter on your opponent's Pok\xE9mon in any way you like."
      }];
      this.set = "CES";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "65";
      this.name = "Banette";
      this.fullName = "Banette CES";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const openSlots = opponent.bench.filter((b) => b.cards.length === 0);
        if (openSlots.length === 0) {
          return state;
        }
        if (!opponent.discard.cards.some((c) => c instanceof PokemonCard && c.stage === 2 /* BASIC */)) {
          return state;
        }
        let cards = [];
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_OPPONENTS_BASIC_POKEMON_TO_BENCH,
          opponent.discard,
          { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
          { min: 0, max: 1, allowCancel: false }
        ), (selected) => {
          cards = selected || [];
          if (cards.length > 0) {
            const card = cards[0];
            const slot = openSlots[0];
            MOVE_CARDS(store, state, opponent.discard, slot, { cards: [card], sourceCard: this, sourceEffect: this.powers[0] });
            slot.pokemonPlayedTurn = state.turn;
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        const opponentBench = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        PUT_X_DAMAGE_COUNTERS_IN_ANY_WAY_YOU_LIKE(opponentBench + 1, store, state, effect);
      }
      return state;
    }
  };

