  var BlazikenGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Combusken";
      this.cardType = [R];
      this.hp = 240;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Slash",
          cost: [C, C],
          damage: 60,
          text: ""
        },
        {
          name: "Explosive Kick",
          cost: [R, R, C],
          damage: 210,
          text: "Discard 2 [R] Energy from this Pok\xE9mon."
        },
        {
          name: "Blaze Out-GX",
          cost: [R],
          damage: 0,
          gxAttack: true,
          text: "Discard 2 Energy from your opponent's Pok\xE9mon. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "CES";
      this.setNumber = "28";
      this.cardImage = "assets/cardback.png";
      this.name = "Blaziken-GX";
      this.fullName = "Blaziken-GX CES";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 2, 2 /* FIRE */);
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        let totalEnergy = 0;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          totalEnergy += cardList.cards.filter((c) => c instanceof EnergyCard).length;
        });
        if (totalEnergy === 0) {
          return state;
        }
        const maxDiscard = Math.min(2, totalEnergy);
        return store.prompt(
          state,
          new DiscardEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: maxDiscard, max: maxDiscard }
          ),
          (transfers) => {
            if (transfers === null || transfers.length === 0) {
              return state;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, opponent, transfer.from);
              const discardEffect = new DiscardCardsEffect(effect, [transfer.card]);
              discardEffect.target = target;
              store.reduceEffect(state, discardEffect);
            }
          }
        );
      }
      return state;
    }
  };

