  var Deoxys32 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 100;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Teleportation Burst",
          cost: [P],
          damage: 20,
          text: "You may switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Spear Dive",
          cost: [C, C, C],
          damage: 0,
          text: "This attack does 50 damage to 1 of your opponent's Pok\xE9mon. This damage isn't affected by Weakness or Resistance."
        }
      ];
      this.set = "CES";
      this.setNumber = "69";
      this.cardImage = "assets/cardback.png";
      this.name = "Deoxys";
      this.fullName = "Deoxys CES 69";
      this.usedTeleportationBurst = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedTeleportationBurst = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedTeleportationBurst) {
        this.usedTeleportationBurst = false;
        const player = effect.player;
        if (player.bench.some((b) => b.cards.length > 0)) {
          store.prompt(state, new ConfirmPrompt(
            player.id,
            GameMessage.WANT_TO_SWITCH_POKEMON
          ), (wantToSwitch) => {
            if (wantToSwitch) {
              SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
            }
          });
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedTeleportationBurst = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false }
        ), (targets) => {
          const target = targets[0];
          const putDamage = new PutDamageEffect(effect, 50);
          putDamage.target = target;
          store.reduceEffect(state, putDamage);
        });
      }
      return state;
    }
  };

