  var Donphan3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Phanpy";
      this.cardType = [F];
      this.hp = 130;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Flail",
          cost: [F],
          damage: 10,
          damageCalculation: "x",
          text: "This attack does 10 damage for each damage counter on this Pok\xE9mon."
        },
        {
          name: "Rapid Spin",
          cost: [F, C, C],
          damage: 50,
          text: "Switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon. If you do, your opponent switches their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon."
        }
      ];
      this.set = "CES";
      this.setNumber = "73";
      this.cardImage = "assets/cardback.png";
      this.name = "Donphan";
      this.fullName = "Donphan CES";
      this.usedRapidSpin = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        effect.damage = 10 * (player.active.damage / 10);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedRapidSpin = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedRapidSpin) {
        this.usedRapidSpin = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const playerBench = player.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        if (playerBench === 0) {
          return state;
        }
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            return state;
          }
          const target = selected[0];
          player.switchPokemon(target);
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        });
      }
      if (effect instanceof EndTurnEffect) {
        this.usedRapidSpin = false;
      }
      return state;
    }
  };

