  var Dunsparce6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 50;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [{
        name: "Strike and Run",
        cost: [C],
        damage: 0,
        text: "Search your deck for up to 3 Basic Pok\xE9mon and put them onto your Bench. Then, shuffle your deck. If you put any Pok\xE9mon onto your Bench in this way, you may switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
      }, {
        name: "Sudden Flash",
        cost: [C],
        damage: 10,
        text: "Flip a coin. If heads, your opponent's Active Pok\xE9mon is now Paralyzed."
      }];
      this.set = "CES";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "110";
      this.name = "Dunsparce";
      this.fullName = "Dunsparce CES";
      this.wantsToSwitch = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const openSlots = player.bench.filter((b) => b.cards.length === 0);
        if (player.deck.cards.length === 0 || openSlots.length === 0) {
          return state;
        }
        const maxPokemons = Math.min(openSlots.length, 3);
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          player.deck,
          { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
          { min: 0, max: Math.min(3, maxPokemons), allowCancel: false }
        ), (selectedCards) => {
          const cards = selectedCards || [];
          cards.forEach((card, index) => {
            store.reduceEffect(state, new PlayPokemonFromDeckEffect(player, card, openSlots[index]));
          });
          SHUFFLE_DECK(store, state, player);
          this.wantsToSwitch == true;
        });
      }
      if (effect instanceof AfterAttackEffect && this.wantsToSwitch) {
        const player = effect.player;
        CONFIRMATION_PROMPT(store, state, player, (result) => {
          if (result) {
            SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            ADD_PARALYZED_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
          }
        });
      }
      return state;
    }
  };

