  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-celestial-storm/electrode-gx.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_discard_energy_prompt();
  init_prefabs();
  var ElectrodeGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Voltorb";
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 190;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.resistance = [{ type: 8 /* METAL */, value: -20 }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [
        {
          name: "Extra Energy Bomb",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          knocksOutSelf: true,
          text: "Once during your turn (before your attack), you may attach 5 Energy cards from your discard pile to your Pok\xE9mon, except Pok\xE9mon-GX or Pok\xE9mon-EX, in any way you like. If you do, this Pok\xE9mon is Knocked Out."
        }
      ];
      this.attacks = [
        {
          name: "Electro Ball",
          cost: [4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 50,
          text: ""
        },
        {
          name: "Crash and Burn-GX",
          cost: [4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 30,
          damageCalculation: "+",
          gxAttack: true,
          text: "Discard any amount of Energy from your Pok\xE9mon. This attack does 50 more damage for each card you discarded in this way. (You can't use more than 1 GX attack in a game.) "
        }
      ];
      this.set = "CES";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "48";
      this.name = "Electrode-GX";
      this.fullName = "Electrode-GX CES";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInHand = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */;
        });
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked2 = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (card.hasTag("EX" /* POKEMON_EX */)) {
            blocked2.push(target);
          }
          if (card.hasTag("GX" /* POKEMON_GX */)) {
            blocked2.push(target);
          }
        });
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 0, max: 5, blockedTo: blocked2 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              SHUFFLE_DECK(store, state, player);
              player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
                if (cardList.getPokemonCard() === this) {
                  cardList.damage += 999;
                  return state;
                }
              });
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.damage += 999;
              }
            });
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        let totalEnergy = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const energyCount = cardList.cards.filter(
            (card) => card.superType === 3 /* ENERGY */
          ).length;
          totalEnergy += energyCount;
        });
        console.log("Total Energy: " + totalEnergy);
        return store.prompt(
          state,
          new DiscardEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            // Card source is target Pokemon
            { superType: 3 /* ENERGY */ },
            { min: 1, max: totalEnergy, allowCancel: false }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              let totalDiscarded = 0;
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = player.discard;
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
              totalDiscarded = transfers.length;
              effect.damage += totalDiscarded * 50;
              player.usedGX = true;
            }
            console.log("Total Damage: " + effect.damage);
            return state;
          }
        );
      }
      return state;
    }
  };

