  var JirachiPrismStar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Prism Star" /* PRISM_STAR */];
      this.cardType = [M];
      this.hp = 80;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Wish Upon a Star",
          powerType: 2 /* ABILITY */,
          exemptFromAbilityLock: true,
          text: "If you took this Pok\xE9mon as a face-down Prize card during your turn and your Bench isn't full, before you put it into your hand, you may put it onto your Bench and take 1 more Prize card."
        }
      ];
      this.attacks = [
        {
          name: "Perish Dream",
          cost: [C, C, C],
          damage: 10,
          text: "This Pok\xE9mon is now Asleep. At the end of your opponent's next turn, the Defending Pok\xE9mon will be Knocked Out."
        }
      ];
      this.set = "CES";
      this.setNumber = "97";
      this.cardImage = "assets/cardback.png";
      this.name = "Jirachi Prism Star";
      this.fullName = "Jirachi Prism Star CES";
      this.abilityUsed = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DrawPrizesEffect) {
        const generator = this.handlePrizeEffect(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        KNOCK_OUT_DEFENDING_POKEMON_AT_END_OF_OPPONENTS_NEXT_TURN(store, state, effect, this);
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, effect.player, this);
      }
      return state;
    }
    *handlePrizeEffect(next, store, state, effect) {
      const player = effect.player;
      const prizeCard = effect.prizes.find((cardList) => cardList.cards.includes(this));
      if (!prizeCard || GET_PLAYER_BENCH_SLOTS(player).length === 0 || !prizeCard.isSecret || effect.destination !== player.hand) {
        return state;
      }
      if (this.abilityUsed) {
        return state;
      }
      this.abilityUsed = true;
      if (IS_ABILITY_BLOCKED(store, state, player, this)) {
        return state;
      }
      effect.preventDefault = true;
      let wantToUse = false;
      yield CONFIRMATION_PROMPT(
        store,
        state,
        player,
        (result) => {
          wantToUse = result;
          next();
        },
        GameMessage.WANT_TO_USE_ABILITY_FROM_PRIZES
      );
      const prizeIndex = player.prizes.findIndex((prize) => prize.cards.includes(this));
      const fallback = (prizeIndex2) => {
        if (prizeIndex2 !== -1) {
          TAKE_SPECIFIC_PRIZES(store, state, player, [player.prizes[prizeIndex2]], {
            skipReduce: true
          });
        }
        return;
      };
      if (!wantToUse) {
        effect.preventDefault = false;
        fallback(prizeIndex);
        return state;
      }
      const emptyBenchSlots = GET_PLAYER_BENCH_SLOTS(player);
      if (emptyBenchSlots.length === 0) {
        effect.preventDefault = false;
        fallback(prizeIndex);
        return state;
      }
      this.abilityUsed = true;
      player.prizesTaken += 1;
      const targetSlot = emptyBenchSlots[0];
      for (const [index, prize] of player.prizes.entries()) {
        if (prize.cards.includes(this)) {
          MOVE_CARDS(store, state, player.prizes[index], targetSlot, { sourceCard: this });
          targetSlot.pokemonPlayedTurn = state.turn;
          break;
        }
      }
      yield TAKE_X_PRIZES(
        store,
        state,
        player,
        1,
        {
          promptOptions: {
            blocked: effect.prizes.map((p) => player.prizes.indexOf(p))
          }
        },
        () => next()
      );
      return state;
    }
  };

