  var Lanturn5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Chinchou";
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 110;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.resistance = [{ type: 8 /* METAL */, value: -20 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [
        {
          name: "Energy Grounding",
          powerType: 2 /* ABILITY */,
          text: "When 1 of your Pok\xE9mon is Knocked Out by damage from an opponent's attack, you may move a basic Energy card from that Pok\xE9mon to this Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Lightning Strike",
          cost: [4 /* LIGHTNING */, 4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 70,
          damageCalculation: "+",
          text: "You may discard all [L] Energy from this Pok\xE9mon. If you do, this attack does 70 more damage."
        }
      ];
      this.set = "CES";
      this.setNumber = "50";
      this.cardImage = "assets/cardback.png";
      this.name = "Lanturn";
      this.fullName = "Lanturn CES";
      this.ENERGY_GROUNDING_MARKER = "ENERGY_GROUNDING_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target !== void 0) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (state.players[state.activePlayer] !== opponent) {
          return state;
        }
        let foundLanturn = null;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this && cardList.cards.length > 0) {
            foundLanturn = cardList;
          }
        });
        if (!foundLanturn) {
          return state;
        }
        const basicEnergies = effect.target.cards.filter((c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */);
        if (basicEnergies.length === 0) {
          return state;
        }
        const basicEnergiesList = new CardList();
        basicEnergiesList.cards = basicEnergies;
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          basicEnergiesList,
          {},
          { min: 0, max: 1, allowCancel: false }
        ), (cards) => {
          if (!cards || cards.length === 0) {
            return;
          }
          for (const card of cards) {
            MOVE_CARDS(store, state, effect.target, foundLanturn, { cards: [card], sourceCard: this });
          }
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const active = player.active;
        const lightningEnergies = active.cards.filter((c) => c.superType === 3 /* ENERGY */ && c.provides.includes(4 /* LIGHTNING */));
        if (lightningEnergies.length > 0) {
          const lightningEnergiesList = new CardList();
          lightningEnergiesList.cards = lightningEnergies;
          state = store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.WANT_TO_DISCARD_ENERGY,
            lightningEnergiesList,
            {},
            { min: 0, max: lightningEnergies.length, allowCancel: true }
          ), (cards) => {
            if (cards && cards.length === lightningEnergies.length && cards.length > 0) {
              for (const card of cards) {
                MOVE_CARDS(store, state, active, player.discard, { cards: [card], sourceCard: this });
              }
              effect.damage += 70;
            }
          });
        }
        return state;
      }
      return state;
    }
  };

