  function* useSmoothOver2(next, store, state, self, effect) {
    const player = effect.player;
    let cards = [];
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    const deckTop = new CardList();
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARDS_TO_PUT_ON_TOP_OF_THE_DECK,
      player.deck,
      {},
      { min: 1, max: 1, allowCancel: false }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    MOVE_CARDS(store, state, player.deck, deckTop, { cards, sourceCard: self });
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
      if (cardList.getPokemonCard() === self) {
        cardList.addBoardEffect(0 /* ABILITY_USED */);
      }
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
      if (order === null) {
        return state;
      }
      deckTop.applyOrder(order);
      deckTop.moveToTopOfDestination(player.deck);
    });
  }
