  var Minior = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 90;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Falling Star",
        useFromHand: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), if this Pok\xE9mon is in your hand and your Bench isn't full, you may move your Active Pok\xE9mon to your Bench and play this Pok\xE9mon as your new Active Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Swift",
          cost: [F],
          damage: 30,
          text: "This attack's damage isn't affected by Weakness, Resistance, or any other effects on your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "CES";
      this.setNumber = "83";
      this.cardImage = "assets/cardback.png";
      this.name = "Minior";
      this.fullName = "Minior CES";
      this.FALLING_STAR_MARKER = "MINIOR_FALLING_STAR_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        if (!player.hand.cards.includes(this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const benchSlots = player.bench.filter((b) => b.cards.length === 0);
        if (benchSlots.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.FALLING_STAR_MARKER, this);
        ABILITY_USED(player, this);
        const emptySlot = benchSlots[0];
        MOVE_CARDS(store, state, player.active, emptySlot, { sourceCard: this });
        player.active.clearEffects();
        MOVE_CARDS(store, state, player.hand, player.active, { cards: [this], sourceCard: this });
        player.active.pokemonPlayedTurn = state.turn;
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.FALLING_STAR_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const applyWeakness = new ApplyWeaknessEffect(effect, 30);
        store.reduceEffect(state, applyWeakness);
        effect.damage = 0;
        opponent.active.damage += 30;
        const afterDamage = new AfterDamageEffect(effect, 30);
        state = store.reduceEffect(state, afterDamage);
      }
      return state;
    }
  };

