  var PalossandGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Sandygast";
      this.cardType = [F];
      this.hp = 210;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Eerie Light",
          cost: [F, C, C],
          damage: 60,
          text: "Your opponent's Active Pok\xE9mon is now Confused."
        },
        {
          name: "Absorb Life",
          cost: [F, F, C, C],
          damage: 100,
          text: "Heal 20 damage from this Pok\xE9mon."
        },
        {
          name: "Sandy Fear-GX",
          cost: [F, F, C, C],
          damage: 60,
          damageCalculation: "x",
          text: "Look at the top 13 cards of your opponent's deck and discard any number of Pok\xE9mon you find there. This attack does 60 damage for each card you discarded in this way. Your opponent shuffles the other cards back into their deck. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "CES";
      this.setNumber = "82";
      this.cardImage = "assets/cardback.png";
      this.name = "Palossand-GX";
      this.fullName = "Palossand-GX CES";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        HEAL_X_DAMAGE_FROM_THIS_POKEMON2(20, effect, store, state);
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        if (opponent.deck.cards.length === 0) {
          return state;
        }
        const deckTop = new CardList();
        const count = Math.min(13, opponent.deck.cards.length);
        MOVE_CARDS(store, state, opponent.deck, deckTop, { count, sourceCard: this });
        const hasPokemon = deckTop.cards.some((c) => c.superType === 1 /* POKEMON */);
        if (!hasPokemon) {
          MOVE_CARDS(store, state, deckTop, opponent.deck, { sourceCard: this });
          SHUFFLE_DECK(store, state, opponent);
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            deckTop,
            { superType: 1 /* POKEMON */ },
            { min: 0, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            effect.damage = 60 * cards.length;
            cards.forEach((card) => {
              MOVE_CARDS(store, state, deckTop, opponent.discard, { cards: [card], sourceCard: this });
            });
            MOVE_CARDS(store, state, deckTop, opponent.deck, { sourceCard: this });
            SHUFFLE_DECK(store, state, opponent);
          }
        );
      }
      return state;
    }
  };

