  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-celestial-storm/rayquaza-gx.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_play_card_effects();
  init_prefabs();
  var RayquazaGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [11 /* DRAGON */];
      this.hp = 180;
      this.weakness = [{ type: 10 /* FAIRY */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [
        {
          name: "Stormy Winds",
          useWhenInPlay: false,
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may discard the top 3 cards of your deck. If you do, attach a basic Energy card from your discard pile to this Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Dragon Break",
          cost: [1 /* GRASS */, 4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 30,
          text: "This attack does 30 damage times the amount of basic [G] and basic [L] Energy attached to your Pok\xE9mon."
        },
        {
          name: "Tempest-GX",
          cost: [1 /* GRASS */],
          damage: 0,
          gxAttack: true,
          text: "Discard your hand and draw 10 cards. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "CES";
      this.name = "Rayquaza-GX";
      this.fullName = "Rayquaza-GX CES";
      this.setNumber = "109";
      this.cardImage = "assets/cardback.png";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const hasBasicEnergyInDiscard = player.discard.cards.some(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
        );
        if (!hasBasicEnergyInDiscard) {
          return state;
        }
        if (hasBasicEnergyInDiscard) {
          state = store.prompt(
            state,
            new ConfirmPrompt(player.id, GameMessage.WANT_TO_USE_ABILITY),
            (wantToUse) => {
              if (wantToUse) {
                MOVE_CARDS(store, state, player.deck, player.discard, { count: 3, sourceCard: this });
                const blockedTo = [];
                player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
                  if (card !== this) {
                    blockedTo.push(target);
                  }
                });
                state = store.prompt(
                  state,
                  new AttachEnergyPrompt(
                    player.id,
                    GameMessage.ATTACH_ENERGY_TO_BENCH,
                    player.discard,
                    2 /* BOTTOM_PLAYER */,
                    [1 /* ACTIVE */, 2 /* BENCH */],
                    { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
                    { allowCancel: false, min: 1, max: 1, blockedTo, sameTarget: true }
                  ),
                  (transfers) => {
                    transfers = transfers || [];
                    if (transfers.length === 0) {
                      return;
                    }
                    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
                      if (cardList.getPokemonCard() === this) {
                        cardList.addBoardEffect(0 /* ABILITY_USED */);
                      }
                    });
                    for (const transfer of transfers) {
                      const target = StateUtils.getTarget(state, player, transfer.to);
                      MOVE_CARDS(store, state, player.discard, target, {
                        cards: [transfer.card],
                        sourceCard: this,
                        sourceEffect: this.powers[0]
                      });
                    }
                  }
                );
              }
            }
          );
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let grassAndLightningEnergies = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergyEffect);
          checkProvidedEnergyEffect.energyMap.forEach((energy2) => {
            if (energy2.provides.includes(1 /* GRASS */) || energy2.provides.includes(4 /* LIGHTNING */)) {
              grassAndLightningEnergies += 1;
            }
          });
        });
        effect.damage = grassAndLightningEnergies * 30;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const cards = player.hand.cards.filter((c) => c !== this);
        MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
        MOVE_CARDS(store, state, player.deck, player.hand, { count: 10, sourceCard: this });
      }
      return state;
    }
  };

