  var Sableye7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [7 /* DARK */];
      this.hp = 70;
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Excavate",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may look at the top card of your deck. You may discard that card. "
      }];
      this.attacks = [{
        name: "Disable",
        cost: [9 /* COLORLESS */],
        damage: 10,
        text: "Choose 1 of your opponent's Active Pok\xE9mon's attacks. That Pok\xE9mon can't use that attack during your opponent's next turn. "
      }];
      this.set = "CES";
      this.setNumber = "88";
      this.cardImage = "assets/cardback.png";
      this.name = "Sableye";
      this.fullName = "Sableye CES";
      this.EXCAVATE_MARKER = "EXCAVATE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.EXCAVATE_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: 1, sourceCard: this });
        player.marker.addMarker(this.EXCAVATE_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
        return store.prompt(state, new ShowCardsPrompt(
          player.id,
          GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
          deckTop.cards
        ), () => {
          state = store.prompt(state, new ConfirmPrompt(
            effect.player.id,
            GameMessage.WANT_TO_USE_ABILITY
          ), (wantToUse) => {
            if (wantToUse) {
              MOVE_CARDS(store, state, deckTop, player.discard, { sourceCard: this });
            } else {
              deckTop.moveToTopOfDestination(player.deck);
            }
          });
          return state;
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return OPPONENTS_POKEMON_CANNOT_USE_THAT_ATTACK(store, state, effect, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.EXCAVATE_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.EXCAVATE_MARKER, this);
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.EXCAVATE_MARKER, this);
        return state;
      }
      return state;
    }
  };

