  var ScizorGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Scyther";
      this.cardType = [M];
      this.hp = 210;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Danger Perception",
          powerType: 2 /* ABILITY */,
          text: "If this Pok\xE9mon's remaining HP is 100 or less, its attacks do 80 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance)."
        }
      ];
      this.attacks = [
        {
          name: "Steel Wing",
          cost: [M, C],
          damage: 80,
          text: "During your opponent's next turn, this Pok\xE9mon takes 30 less damage from attacks (after applying Weakness and Resistance)."
        },
        {
          name: "Cross-Cut-GX",
          cost: [C, C, C],
          damage: 100,
          damageCalculation: "+",
          text: "If your opponent's Active Pok\xE9mon is an Evolution Pok\xE9mon, this attack does 100 more damage. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "CES";
      this.setNumber = "90";
      this.cardImage = "assets/cardback.png";
      this.name = "Scizor-GX";
      this.fullName = "Scizor-GX CES";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.source.cards.includes(this)) {
        const pokemonCard = effect.source.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.source);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkHp = new CheckHpEffect(player, effect.source);
        store.reduceEffect(state, checkHp);
        const remainingHp = checkHp.hp - effect.source.damage;
        if (remainingHp <= 100) {
          effect.damage += 80;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.player.active.damageReductionNextTurn = 30;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentActive = opponent.active.getPokemonCard();
        if (opponentActive && opponentActive.stage !== 2 /* BASIC */) {
          effect.damage += 100;
        }
      }
      return state;
    }
  };

