  init_prefabs();
  var Swampert4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.cardType = [3 /* WATER */];
      this.hp = 160;
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.evolvesFrom = "Marshtomp";
      this.powers = [{
        name: "Power Draw",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may discard a card from your hand. If you do, draw 3 cards."
      }];
      this.attacks = [{
        name: "Hydro Pump",
        cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
        damage: 80,
        damageCalculation: "+",
        text: "This attack does 20 more damage times the amount of [W] Energy attached to this Pok\xE9mon."
      }];
      this.set = "CES";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "35";
      this.name = "Swampert";
      this.fullName = "Swampert CES";
      this.POWER_DRAW_MARKER = "POWER_DRAW_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.POWER_DRAW_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.hand.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.POWER_DRAW_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          {},
          { allowCancel: false, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          player.marker.addMarker(this.POWER_DRAW_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this, sourceEffect: this.powers[0] });
          DRAW_CARDS(store, state, player, 3);
        });
        return state;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.POWER_DRAW_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.POWER_DRAW_MARKER, this);
      }
      if (effect instanceof AttackEffect && effect.attack == this.attacks[0]) {
        const player = effect.player;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let energyCount = 0;
        checkProvidedEnergyEffect.energyMap.forEach((em) => {
          energyCount += em.provides.filter((cardType) => {
            return cardType === 3 /* WATER */;
          }).length;
        });
        effect.damage += energyCount * 20;
        return state;
      }
      return state;
    }
  };

