  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-celestial-storm/torkoal.ts
  init_prefabs();
  init_card_types();
  init_game_message();
  init_state_utils();
  init_pokemon_card();
  init_game();
  var Torkoal3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [R];
      this.hp = 120;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Flaming Honk",
          cost: [C, C],
          damage: 30,
          text: "Discard the top 4 cards of your deck. If any of those cards are [R] Energy cards, attach them to your Pok\xE9mon in any way you like."
        },
        {
          name: "Searing Flame",
          cost: [R, R, C],
          damage: 80,
          text: "Your opponent's Active Pok\xE9mon is now Burned."
        }
      ];
      this.set = "CES";
      this.setNumber = "29";
      this.cardImage = "assets/cardback.png";
      this.name = "Torkoal";
      this.fullName = "Torkoal CES";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cardsToProcess = player.deck.cards.slice(0, 4);
        const fireEnergy = [];
        const nonFireCards = [];
        cardsToProcess.forEach((card) => {
          if (card.superType === 3 /* ENERGY */ && card.energyType === 0 /* BASIC */ && card.name === "Fire Energy") {
            fireEnergy.push(card);
          } else {
            nonFireCards.push(card);
          }
        });
        nonFireCards.forEach((card) => {
          MOVE_CARDS(store, state, player.deck, player.discard, { cards: [card], sourceCard: this });
        });
        if (fireEnergy.length > 0) {
          fireEnergy.forEach((card) => {
            MOVE_CARDS(store, state, player.deck, player.discard, { cards: [card], sourceCard: this });
          });
          store.prompt(state, new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
            { allowCancel: false, min: 0, max: fireEnergy.length }
          ), (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
          });
        }
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        ADD_BURN_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

