  var Tyranitar2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Pupitar";
      this.cardType = [D];
      this.hp = 170;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C];
      this.attacks = [{
        name: "Slam",
        cost: [C, C, C],
        damage: 60,
        damageCalculation: "x",
        text: "Flip 2 coins. This attack does 60 damage for each heads."
      }, {
        name: "Trample",
        cost: [D, D, C, C],
        damage: 120,
        text: "For each Benched Pok\xE9mon (both yours and your opponent's), flip a coin. If heads, this attack does 60 damage to that Pok\xE9mon. This attack's damage isn't affected by Weakness or Resistance."
      }];
      this.set = "CES";
      this.setNumber = "87";
      this.cardImage = "assets/cardback.png";
      this.name = "Tyranitar";
      this.fullName = "Tyranitar CES";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 2, (results) => {
          const heads = results.filter((r) => r).length;
          effect.damage = 60 * heads;
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const benchedPokemon = [];
        player.bench.forEach((b) => {
          if (b.cards.length > 0) {
            benchedPokemon.push({ cardList: b, owner: player });
          }
        });
        opponent.bench.forEach((b) => {
          if (b.cards.length > 0) {
            benchedPokemon.push({ cardList: b, owner: opponent });
          }
        });
        const totalBenched = benchedPokemon.length;
        if (totalBenched > 0) {
          MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, totalBenched, (results) => {
            results.forEach((result, index) => {
              if (result && index < benchedPokemon.length) {
                const target = benchedPokemon[index];
                const damage = new PutDamageEffect(effect, 60);
                damage.target = target.cardList;
                store.reduceEffect(state, damage);
              }
            });
          });
        }
      }
      return state;
    }
  };

