  var BeastBall = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "CES";
      this.setNumber = "125";
      this.cardImage = "assets/cardback.png";
      this.name = "Beast Ball";
      this.fullName = "Beast Ball CES";
      this.text = "Look at your face-down Prize cards. You may reveal an Ultra Beast card you find there, put it into your hand, and put this Beast Ball in its place. (If you don't reveal an Ultra Beast card, put this card in the discard pile.) Then, shuffle your face-down Prize cards.";
    }
    // Ref: set-astral-radiance/hisuian-heavy-ball.ts (prize card look/swap pattern)
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const prizes = player.prizes.filter((p) => p.isSecret);
        const originallyFaceDown = player.prizes.map((p) => p.isSecret);
        let faceDownCheck = 0;
        player.prizes.forEach((card) => {
          if (card.isSecret) {
            faceDownCheck++;
          }
        });
        if (!faceDownCheck) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        prizes.forEach((p) => {
          p.isSecret = false;
        });
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        const allPrizeCards = new CardList();
        player.prizes.forEach((prizeList) => {
          allPrizeCards.cards.push(...prizeList.cards);
        });
        const blocked = [];
        allPrizeCards.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || !card.hasTag("Ultra Beast" /* ULTRA_BEAST */)) {
            blocked.push(index);
          }
        });
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            allPrizeCards,
            {},
            { min: 0, max: 1, allowCancel: false, blocked }
          ),
          (chosenPrize) => {
            if (!chosenPrize || chosenPrize.length === 0) {
              player.prizes.forEach((p, index) => {
                if (originallyFaceDown[index]) {
                  p.isSecret = true;
                }
              });
              this.shuffleFaceDownPrizeCards(
                player.prizes.filter((p, index) => originallyFaceDown[index])
              );
              return state;
            }
            const prizeUltraBeast = chosenPrize[0];
            const chosenPrizeList = player.prizes.find(
              (prizeList) => prizeList.cards.includes(prizeUltraBeast)
            );
            if (chosenPrize.length > 0) {
              state = store.prompt(
                state,
                new ShowCardsPrompt(
                  opponent.id,
                  GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                  chosenPrize
                ),
                () => {
                }
              );
            }
            if (chosenPrizeList) {
              MOVE_CARDS(store, state, chosenPrizeList, player.hand, { cards: [prizeUltraBeast], sourceCard: this });
              MOVE_CARDS(store, state, player.supporter, chosenPrizeList, { cards: [effect.trainerCard], sourceCard: this });
            }
            player.prizes.forEach((p, index) => {
              if (originallyFaceDown[index]) {
                p.isSecret = true;
              }
            });
            this.shuffleFaceDownPrizeCards(
              player.prizes.filter((p, index) => originallyFaceDown[index])
            );
            return state;
          }
        );
      }
      return state;
    }
    shuffleFaceDownPrizeCards(array) {
      const faceDownPrizeCards = array.filter((p) => p.isSecret && p.cards.length > 0);
      for (let i = faceDownPrizeCards.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        const temp = faceDownPrizeCards[i];
        faceDownPrizeCards[i] = faceDownPrizeCards[j];
        faceDownPrizeCards[j] = temp;
      }
      const prizePositions = [];
      for (let i = 0; i < array.length; i++) {
        if (array[i].cards.length === 0 || !array[i].isSecret) {
          prizePositions.push(array[i]);
          continue;
        }
        prizePositions.push(faceDownPrizeCards.splice(0, 1)[0]);
      }
      return prizePositions;
    }
  };

