  var LureBall = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "CES";
      this.setNumber = "138";
      this.cardImage = "assets/cardback.png";
      this.name = "Lure Ball";
      this.fullName = "Lure Ball CES";
      this.text = "Flip 3 coins. For each heads, put an Evolution Pok\xE9mon from your discard pile into your hand.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const hasEvolutionInDiscard = player.discard.cards.some(
          (c) => c instanceof PokemonCard && c.stage !== 2 /* BASIC */
        );
        if (!hasEvolutionInDiscard) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          const heads = results.filter((r) => r).length;
          if (heads === 0) {
            return;
          }
          const blocked = [];
          let evolutionCount = 0;
          player.discard.cards.forEach((c, index) => {
            if (c instanceof PokemonCard && c.stage !== 2 /* BASIC */) {
              evolutionCount++;
            } else {
              blocked.push(index);
            }
          });
          const maxChoose = Math.min(heads, evolutionCount);
          store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_HAND,
              player.discard,
              {},
              { min: maxChoose, max: maxChoose, allowCancel: false, blocked }
            ),
            (selected) => {
              if (selected && selected.length > 0) {
                MOVE_CARDS(store, state, player.discard, player.hand, {
                  cards: selected,
                  sourceCard: this
                });
              }
            }
          );
        });
      }
      return state;
    }
  };

