  var RainbowBrush = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "CES";
      this.setNumber = "141";
      this.cardImage = "assets/cardback.png";
      this.name = "Rainbow Brush";
      this.fullName = "Rainbow Brush CES";
      this.text = "Choose an Energy card attached to 1 of your Pok\xE9mon. Search your deck for a basic Energy card and switch it with that card. Shuffle the first Energy card into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        let hasEnergyAttached = false;
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.cards.some((c) => c instanceof EnergyCard)) {
            hasEnergyAttached = true;
          } else {
            blocked.push(target);
          }
        });
        if (!hasEnergyAttached || player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DISCARD_CARDS,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const targetPokemon = targets[0];
            const energyBlocked = [];
            targetPokemon.cards.forEach((c, index) => {
              if (!(c instanceof EnergyCard)) {
                energyBlocked.push(index);
              }
            });
            store.prompt(
              state,
              new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARD_TO_DECK,
                targetPokemon,
                { superType: 3 /* ENERGY */ },
                { min: 1, max: 1, allowCancel: false, blocked: energyBlocked }
              ),
              (selectedEnergy) => {
                if (!selectedEnergy || selectedEnergy.length === 0) {
                  return;
                }
                const energyToReturn = selectedEnergy[0];
                const deckBlocked = [];
                player.deck.cards.forEach((c, index) => {
                  if (!(c instanceof EnergyCard && c.energyType === 0 /* BASIC */)) {
                    deckBlocked.push(index);
                  }
                });
                store.prompt(
                  state,
                  new ChooseCardsPrompt(
                    player,
                    GameMessage.CHOOSE_CARD_TO_HAND,
                    player.deck,
                    { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
                    { min: 0, max: 1, allowCancel: true, blocked: deckBlocked }
                  ),
                  (selectedFromDeck) => {
                    if (selectedFromDeck && selectedFromDeck.length > 0) {
                      const newEnergy = selectedFromDeck[0];
                      MOVE_CARDS(store, state, player.deck, targetPokemon, {
                        cards: [newEnergy],
                        sourceCard: this
                      });
                      MOVE_CARDS(store, state, targetPokemon, player.deck, {
                        cards: [energyToReturn],
                        sourceCard: this
                      });
                    }
                    store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                      player.deck.applyOrder(order);
                    });
                  }
                );
              }
            );
          }
        );
      }
      return state;
    }
  };

