  var ShrineOfPunishment = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "CES";
      this.setNumber = "143";
      this.cardImage = "assets/cardback.png";
      this.name = "Shrine of Punishment";
      this.fullName = "Shrine of Punishment CES";
      this.text = "Between turns, put 1 damage counter on each Pok\xE9mon-GX and Pok\xE9mon-EX (both yours and your opponent's).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof BetweenTurnsEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const owner = StateUtils.findOwner(state, cardList);
          if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, cardList, this)) {
            return;
          }
          const pokemon = cardList.getPokemonCard();
          if (pokemon && (pokemon?.hasTag("GX" /* POKEMON_GX */) || pokemon.hasTag("EX" /* POKEMON_EX */))) {
            cardList.damage += 10;
          }
        });
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-celestial-storm/sky-pillar.ts
  init_game();
