  var SkyPillar = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.regulationMark = "D";
      this.set = "CES";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "144";
      this.name = "Sky Pillar";
      this.fullName = "Sky Pillar CES";
      this.text = "Prevent all effects of the opponent's attacks, including damage, done to Benched Pok\xE9mon (both yours and your opponent's).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      if (effect instanceof PutDamageEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (effect.target === player.active || effect.target === opponent.active) {
          return state;
        }
        const owner = StateUtils.findOwner(state, effect.target);
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, effect.target, this)) {
          return state;
        }
        effect.preventDefault = true;
      }
      if (effect instanceof PutCountersEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (effect.target === player.active || effect.target === opponent.active) {
          return state;
        }
        const owner = StateUtils.findOwner(state, effect.target);
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, effect.target, this)) {
          return state;
        }
        effect.preventDefault = true;
      }
      return state;
    }
  };

