  function* playCard140(next, store, state, effect) {
    const player = effect.player;
    let cards = [];
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        {},
        { min: 0, max: 3, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: effect.trainerCard });
    store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
    const endTurnEffect = new EndTurnEffect(player);
    return store.reduceEffect(state, endTurnEffect);
  }
  var StevensResolve = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CES";
      this.setNumber = "145";
      this.cardImage = "assets/cardback.png";
      this.name = "Steven's Resolve";
      this.fullName = "Steven's Resolve CES";
      this.text = "Search your deck for up to 3 cards and put them into your hand. Then, shuffle your deck. Your turn ends.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard140(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

