  var TateAndLiza = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CES";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "148";
      this.name = "Tate & Liza";
      this.fullName = "Tate & Liza CES";
      this.text = "Choose 1:\u2022 Shuffle your hand into your deck. Then, draw 5 cards.\u2022 Switch your Active Pok\xE9mon with 1 of your Benched Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        const options = [
          {
            message: GameMessage.SWITCH_POKEMON,
            action: () => {
              return store.prompt(
                state,
                new ChoosePokemonPrompt(
                  player.id,
                  GameMessage.CHOOSE_POKEMON_TO_SWITCH,
                  2 /* BOTTOM_PLAYER */,
                  [2 /* BENCH */],
                  { allowCancel: false }
                ),
                (result) => {
                  const cardList = result[0];
                  player.switchPokemon(cardList, store, state);
                }
              );
            }
          },
          {
            message: GameMessage.SHUFFLE_YOUR_HAND,
            action: () => {
              if (player.hand.cards.length > 0) {
                MOVE_CARDS(store, state, player.hand, player.deck, {
                  cards: player.hand.cards.filter((c) => c !== this),
                  sourceCard: this
                });
              }
              store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                player.deck.applyOrder(order);
              });
              DRAW_CARDS(store, state, player, 5);
            }
          }
        ];
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          options.splice(0, 1);
        }
        if (player.deck.cards.length === 0) {
          options.splice(1, 1);
        }
        return store.prompt(
          state,
          new SelectPrompt(
            player.id,
            GameMessage.CHOOSE_OPTION,
            options.map((opt) => opt.message),
            { allowCancel: false }
          ),
          (choice) => {
            const option = options[choice];
            option.action();
          }
        );
      }
      return state;
    }
  };

