  var TheMaskedRoyal = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CES";
      this.setNumber = "139";
      this.cardImage = "assets/cardback.png";
      this.name = "The Masked Royal";
      this.fullName = "The Masked Royal CES";
      this.text = "Attach a basic Energy card from your hand to one of your Stage 2 Grass, Fire, or Water Pok\xE9mon. You may play only 1 Supporter card during your turn (before your attack).";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const hasBasicEnergy = player.hand.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        );
        let hasValidTarget = false;
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const pokemonCard = cardList.getPokemonCard();
          if (pokemonCard && pokemonCard.stage === 4 /* STAGE_2 */ && (pokemonHasCardType(pokemonCard, 1 /* GRASS */) || pokemonHasCardType(pokemonCard, 2 /* FIRE */) || pokemonHasCardType(pokemonCard, 3 /* WATER */))) {
            hasValidTarget = true;
          } else {
            blocked.push(target);
          }
        });
        if (!hasBasicEnergy || !hasValidTarget) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.hand,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min: 1, max: 1, allowCancel: false, blockedTo: blocked }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.hand, target, {
                cards: [transfer.card],
                sourceCard: this
              });
            }
          }
        );
      }
      return state;
    }
  };

