  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-cosmic-eclipse/absol.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_prefabs();
  var Absol5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 100;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Ominous News",
          cost: [C],
          damage: 0,
          text: "Discard a Special Energy from 1 of your opponent's Pok\xE9mon."
        },
        {
          name: "Dirty Throw",
          cost: [D, C],
          damage: 70,
          text: "Discard a card from your hand. If you can't discard a card, this attack does nothing."
        }
      ];
      this.set = "CEC";
      this.setNumber = "133";
      this.cardImage = "assets/cardback.png";
      this.name = "Absol";
      this.fullName = "Absol CEC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let hasSpecialEnergy = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          if (cardList.cards.some((c) => c instanceof EnergyCard && c.energyType === 1 /* SPECIAL */)) {
            hasSpecialEnergy = true;
          }
        });
        if (!hasSpecialEnergy) {
          return state;
        }
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            return;
          }
          const target = selected[0];
          const specialEnergy = target.cards.filter(
            (c) => c instanceof EnergyCard && c.energyType === 1 /* SPECIAL */
          );
          if (specialEnergy.length === 0) {
            return;
          }
          if (specialEnergy.length === 1) {
            const discardEnergy2 = new DiscardCardsEffect(effect, specialEnergy);
            discardEnergy2.target = target;
            store.reduceEffect(state, discardEnergy2);
          } else {
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              target,
              { superType: 3 /* ENERGY */, energyType: 1 /* SPECIAL */ },
              { min: 1, max: 1, allowCancel: false }
            ), (cards) => {
              const selected2 = cards || [];
              if (selected2.length > 0) {
                const discardEnergy2 = new DiscardCardsEffect(effect, selected2);
                discardEnergy2.target = target;
                store.reduceEffect(state, discardEnergy2);
              }
            });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        if (player.hand.cards.length === 0) {
          effect.damage = 0;
          return state;
        }
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          {},
          { allowCancel: false, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length > 0) {
            MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
          }
        });
      }
      return state;
    }
  };

