  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-cosmic-eclipse/arceus-dialga-palkia-gx.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_effects();
  init_check_effects();
  init_prefabs();
  init_attack_effects();
  function* useUltimateRay(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      return state;
    }
    yield store.prompt(
      state,
      new AttachEnergyPrompt(
        player.id,
        GameMessage.ATTACH_ENERGY_TO_BENCH,
        player.deck,
        2 /* BOTTOM_PLAYER */,
        [2 /* BENCH */, 1 /* ACTIVE */],
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { allowCancel: false, min: 0, max: 3 }
      ),
      (transfers) => {
        transfers = transfers || [];
        for (const transfer of transfers) {
          const target = StateUtils.getTarget(state, player, transfer.to);
          MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: effect.source.getPokemonCard() });
          next();
        }
      }
    );
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var ArceusDialgaPalkiaGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */, "Tag Team" /* TAG_TEAM */];
      this.stage = 2 /* BASIC */;
      this.cardType = [N];
      this.hp = 280;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Ultimate Ray",
          cost: [W, M, C],
          damage: 150,
          text: "Search your deck for up to 3 basic Energy cards and attach them to your Pok\xE9mon in any way you like. Then, shuffle your deck."
        },
        {
          name: "Altered Creation-GX",
          cost: [M],
          damage: 0,
          text: "For the rest of this game, your Pok\xE9mon's attacks do 30 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance). If this Pok\xE9mon has at least 1 extra [W] Energy attached to it (in addition to this attack's cost), when your opponent's Active Pok\xE9mon is Knocked Out by damage from those attacks, take 1 more Prize card. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "CEC";
      this.name = "Arceus & Dialga & Palkia-GX";
      this.fullName = "Arceus & Dialga & Palkia GX CEC";
      this.setNumber = "156";
      this.cardImage = "assets/cardback.png";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const generator = useUltimateRay(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        player.alteredCreationDamage = true;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        state = store.reduceEffect(state, checkEnergy);
        const checkAttackCost = new CheckAttackCostEffect(player, this.attacks[1]);
        state = store.reduceEffect(state, checkAttackCost);
        const waterEnergies = checkEnergy.energyMap.filter(
          (e) => e.provides.includes(3 /* WATER */) || e.provides.includes(0 /* ANY */)
        );
        if (waterEnergies.length >= 1) {
          player.usedAlteredCreation = true;
          console.log("Used Altered Creation with Extra Water");
        }
      }
      if (effect instanceof DealDamageEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.alteredCreationDamage === true && effect.target === opponent.active && !effect.damageIncreased) {
          effect.damage += 30;
          effect.damageIncreased = true;
        }
      }
      if (effect instanceof KnockOutEffect) {
        const knockedOutOwner = effect.player;
        const attacker = StateUtils.getOpponent(state, knockedOutOwner);
        if (effect.target === knockedOutOwner.active && state.phase === 3 /* ATTACK */ && state.players[state.activePlayer] === attacker && attacker.usedAlteredCreation === true && !effect.prizeIncreased) {
          effect.prizeCount += 1;
          effect.prizeIncreased = true;
        }
      }
      return state;
    }
  };

