  function* useAscension7(next, store, state, self, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      return state;
    }
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_EVOLVE,
      player.deck,
      { superType: 1 /* POKEMON */, evolvesFrom: "Cosmog" },
      { min: 1, max: 1, allowCancel: true }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length > 0) {
      const pokemonCardList = StateUtils.findCardList(state, self);
      MOVE_CARDS(store, state, player.deck, pokemonCardList, { cards, sourceCard: self });
      pokemonCardList.clearEffects();
      pokemonCardList.pokemonPlayedTurn = state.turn;
    }
    return SHUFFLE_DECK(store, state, player);
  }
