  var Lycanroc3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Rockruff";
      this.cardType = [F];
      this.hp = 120;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Boiling Blood",
          powerType: 2 /* ABILITY */,
          text: "If your opponent has any Pok\xE9mon-GX or Pok\xE9mon-EX in play, this Pok\xE9mon's attacks cost ColorlessColorlessColorless less."
        }
      ];
      this.attacks = [
        {
          name: "Voltage Claw",
          cost: [C, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "If your opponent's Active Pok\xE9mon has any Special Energy attached to it, this attack does 70 more damage."
        }
      ];
      this.set = "CEC";
      this.setNumber = "124";
      this.cardImage = "assets/cardback.png";
      this.name = "Lycanroc";
      this.fullName = "Lycanroc CEC";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect && effect.player.active.cards.includes(this)) {
        if (effect.player.active.getPokemonCard() !== this) {
          return state;
        }
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        let hasGxOrEx = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          const pokemonCard = cardList.getPokemonCard();
          if (pokemonCard && (pokemonCard.hasTag("GX" /* POKEMON_GX */) || pokemonCard.hasTag("EX" /* POKEMON_EX */))) {
            hasGxOrEx = true;
          }
        });
        if (hasGxOrEx) {
          let removed = 0;
          const newCost = [];
          for (const c of effect.cost) {
            if (c === 9 /* COLORLESS */ && removed < 3) {
              removed++;
            } else {
              newCost.push(c);
            }
          }
          effect.cost = newCost;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        const hasSpecialEnergy = opponent.active.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 1 /* SPECIAL */
        );
        if (hasSpecialEnergy) {
          effect.damage += 70;
        }
      }
      return state;
    }
  };

