  init_game();
  init_play_card_effects();
  init_prefabs();
  init_attack_effects();
  var Mimikyu = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 70;
      this.retreat = [C];
      this.attacks = [
        {
          name: "Impersonation",
          cost: [C],
          damage: 0,
          text: "Discard a Supporter card from your hand. If you do, use the effect of that card as the effect of this attack."
        },
        {
          name: "Mischevious Hands",
          cost: [P],
          damage: 0,
          text: "Choose 2 of your opponent's Pok\xE9mon and put 2 damage counters on each of them."
        }
      ];
      this.set = "CEC";
      this.name = "Mimikyu";
      this.fullName = "Mimikyu CEC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "96";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const supportersInHand = player.hand.cards.filter((card) => {
          card instanceof TrainerCard && card.trainerType === 1 /* SUPPORTER */;
        });
        if (!supportersInHand) {
          return state;
        }
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_COPY_EFFECT,
          player.hand,
          { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
          { allowCancel: false, min: 1, max: 1 }
        ), (cards) => {
          if (cards === null || cards.length === 0) {
            return;
          }
          const trainerCard = cards[0];
          player.supporterTurn -= 1;
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
          const playTrainerEffect = new TrainerEffect(player, trainerCard);
          store.reduceEffect(state, playTrainerEffect);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        const benched = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        const count = 1 + Math.min(1, benched);
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: count, max: count, allowCancel: false }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          targets.forEach((target) => {
            const counters = new PutCountersEffect(effect, 20);
            counters.target = target;
            store.reduceEffect(state, counters);
          });
        });
      }
      return state;
    }
  };

