  var Mimikyu2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 70;
      this.retreat = [C];
      this.powers = [
        {
          name: "Shadow Box",
          powerType: 2 /* ABILITY */,
          text: "Pok\xE9mon-GX that have any damage counters on them (both yours and your opponent's) have no Abilities."
        }
      ];
      this.attacks = [{
        name: "Tail Trickery",
        cost: [C, C],
        damage: 20,
        text: "Flip a coin. If heads, your opponent's Active Pok\xE9mon is now Confused."
      }];
      this.set = "CEC";
      this.setNumber = "97";
      this.cardImage = "assets/cardback.png";
      this.name = "Mimikyu";
      this.fullName = "Mimikyu CEC 97";
    }
    reduceEffect(store, state, effect) {
      HANDLE_ABILITY_LOCK(
        effect,
        ({ card }) => {
          if (!card.hasTag("GX" /* POKEMON_GX */)) {
            return false;
          }
          let hasDamage = false;
          try {
            const cardList = StateUtils.findCardList(state, card);
            if (cardList instanceof PokemonCardList && cardList.damage > 0) {
              hasDamage = true;
            }
          } catch {
            return false;
          }
          if (!hasDamage) {
            return false;
          }
          let isInPlay = false;
          let owner;
          for (const player of state.players) {
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                isInPlay = true;
                owner = player;
              }
            });
          }
          if (!isInPlay || !owner) {
            return false;
          }
          return CAN_APPLY_LOCKER_ABILITY(store, state, owner, this, this.powers[0]);
        },
        {
          allowUseFromHand: true,
          allowUseFromDiscard: true,
          error: GameMessage.BLOCKED_BY_EFFECT
        }
      );
      if (AFTER_ATTACK(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
          }
        });
      }
      return state;
    }
  };

