  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-cosmic-eclipse/phione.ts
  init_pokemon_card();
  init_card_types();
  init_pokemon_types();
  init_game();
  init_prefabs();
  var Phione2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [3 /* WATER */];
      this.hp = 70;
      this.retreat = [9 /* COLORLESS */];
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.powers = [{
        name: "Whirlpool Suction",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), if this Pok\xE9mon is on your Bench, you may have your opponent switch their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon. If you do, discard all cards attached to this Pok\xE9mon and put it on the bottom of your deck. "
      }];
      this.attacks = [{
        name: "Rain Splash",
        cost: [3 /* WATER */],
        damage: 10,
        text: ""
      }];
      this.set = "CEC";
      this.setNumber = "57";
      this.cardImage = "assets/cardback.png";
      this.name = "Phione";
      this.fullName = "Phione CEC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        const cardList = StateUtils.findCardList(state, this);
        if (player.active.cards[0] == this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (hasBench === false) {
          return state;
        }
        const benchIndex = player.bench.indexOf(cardList);
        if (benchIndex === -1) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          opponent.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (targets) => {
          if (targets && targets.length > 0) {
            const deckBottom = new CardList();
            const phioneList = player.bench[benchIndex];
            const phioneCard = phioneList.getPokemonCard();
            if (!phioneCard) {
              return state;
            }
            opponent.active.clearEffects();
            opponent.switchPokemon(targets[0]);
            const otherCards = phioneList.cards.filter(
              (card) => !(card instanceof PokemonCard) && !phioneList.getPokemons().includes(card) && (!phioneList.tools || !phioneList.tools.includes(card))
            );
            const tools = [...phioneList.tools];
            if (tools.length > 0) {
              for (const tool of tools) {
                MOVE_CARDS(store, state, phioneList, player.discard, { cards: [tool], sourceCard: this });
              }
            }
            if (otherCards.length > 0) {
              MOVE_CARDS(store, state, phioneList, player.discard, { cards: otherCards });
            }
            MOVE_CARDS(store, state, phioneList, deckBottom, {
              cards: [phioneCard],
              skipCleanup: false
            });
            MOVE_CARDS(store, state, deckBottom, player.deck, {
              toBottom: true
            });
            phioneList.clearEffects();
            return state;
          }
        });
      }
      return state;
    }
  };

