  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  function* useBulldoze(next, store, state, self, effect) {
    const player = effect.player;
    let cards = [];
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    const deckTop = new CardList();
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARDS_TO_PUT_ON_TOP_OF_THE_DECK,
      player.deck,
      {},
      { min: 1, max: 1, allowCancel: false }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    MOVE_CARDS(store, state, player.deck, deckTop, { cards, sourceCard: self });
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
      if (cardList.getPokemonCard() === self) {
        cardList.addBoardEffect(0 /* ABILITY_USED */);
      }
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
      if (order === null) {
        return state;
      }
      deckTop.applyOrder(order);
      deckTop.moveToTopOfDestination(player.deck);
    });
  }
  var Seismitoad5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Palpitoad";
      this.cardType = [F];
      this.hp = 160;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Bulldoze",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may search your deck for a card, shuffle your deck, then put that card on top of it."
      }];
      this.attacks = [
        {
          name: "Tremulous Fist",
          cost: [F, C, C, C],
          damage: 80,
          damageCalculation: "+",
          text: "This attack does 30 more damage for each of your Benched Pok\xE9mon that has any damage counters on it."
        }
      ];
      this.set = "CEC";
      this.setNumber = "117";
      this.cardImage = "assets/cardback.png";
      this.name = "Seismitoad";
      this.fullName = "Seismitoad CEC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const generator = useBulldoze(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let damagedBenchCount = 0;
        player.bench.forEach((b) => {
          if (b.cards.length > 0 && b.damage > 0) {
            damagedBenchCount++;
          }
        });
        effect.damage += damagedBenchCount * 30;
      }
      return state;
    }
  };

