  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-cosmic-eclipse/steelix.ts
  init_game();
  init_prefabs();
  var Steelix4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Onix";
      this.cardType = [M];
      this.hp = 170;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Thumping Fall",
          cost: [C, C],
          damage: 50,
          damageCalculation: "x",
          text: "Discard any number of Pok\xE9mon with a Retreat Cost of exactly 4 from your hand. This attack does 50 damage for each card you discarded in this way."
        },
        {
          name: "Iron Tail",
          cost: [M, C, C, C],
          damage: 100,
          damageCalculation: "x",
          text: "Flip a coin until you get tails. This attack does 100 damage for each heads."
        }
      ];
      this.set = "CEC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "139";
      this.name = "Steelix";
      this.fullName = "Steelix CEC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const bigBoys = player.hand.cards.filter((c) => c instanceof PokemonCard && c.retreat.length === 4);
        const blocked = [];
        player.hand.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && card.retreat.length === 4) {
            return;
          } else {
            blocked.push(index);
          }
        });
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 1 /* POKEMON */ },
          { allowCancel: true, min: 0, max: bigBoys.length, blocked }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
          const monsDiscarded = cards.length;
          effect.damage = monsDiscarded * 50;
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        return FLIP_UNTIL_TAILS_AND_COUNT_HEADS(store, state, player, (heads) => {
          effect.damage = 100 * heads;
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-cosmic-eclipse/stoutland.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_game_effects();
  init_check_effects();
  init_attack_effects();
