  init_prefabs();
  var Stoutland5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.cardType = [9 /* COLORLESS */];
      this.hp = 150;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.evolvesFrom = "Herdier";
      this.powers = [{
        name: "Arf Arf Bark",
        powerType: 2 /* ABILITY */,
        text: " When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may discard an Energy from your opponent's Active Pok\xE9mon.If this Pok\xE9mon is your Active Pok\xE9mon and is Knocked Out by damage from an opponent's attack, you may discard an Energy from your opponent's Active Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Overrun",
        cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
        damage: 110,
        text: " This attack does 30 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.) "
      }];
      this.set = "CEC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "176";
      this.name = "Stoutland";
      this.fullName = "Stoutland CEC";
      this.damageDealt = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        state = store.reduceEffect(state, checkProvidedEnergy);
        if (checkProvidedEnergy.energyMap.length === 0) {
          return state;
        }
        state = store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [9 /* COLORLESS */],
          { allowCancel: false }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          MOVE_CARDS(store, state, opponent.active, opponent.discard, { cards, sourceCard: this });
        });
      }
      if ((effect instanceof DealDamageEffect || effect instanceof PutDamageEffect) && effect.target.cards.includes(this)) {
        const player = StateUtils.getOpponent(state, effect.player);
        console.log("Entered check for DealDamageEffect/PutDamageEffect");
        if (player.active.getPokemonCard() === this) {
          this.damageDealt = true;
          console.log("this.damageDealt inside the DealDamageEffect/PutDamageEffect check: " + this.damageDealt);
        }
      }
      if (effect instanceof KnockOutEffect && effect.target.cards.includes(this) && this.damageDealt) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        state = store.reduceEffect(state, checkProvidedEnergy);
        if (checkProvidedEnergy.energyMap.length === 0) {
          return state;
        }
        state = store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [9 /* COLORLESS */],
          { allowCancel: false }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          MOVE_CARDS(store, state, opponent.active, opponent.discard, { cards, sourceCard: this });
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        state = store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (selected) => {
          const targets = selected || [];
          DAMAGE_OPPONENT_POKEMON(store, state, effect, 30, targets);
        });
        return state;
      }
      if (effect instanceof EndTurnEffect && effect.player === StateUtils.getOpponent(state, effect.player)) {
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === effect.player) {
          this.damageDealt = false;
        }
      }
      return state;
    }
  };

