  var TogepiCleffaIgglybuffGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */, "Tag Team" /* TAG_TEAM */];
      this.stage = 2 /* BASIC */;
      this.cardType = [Y];
      this.hp = 240;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Rolling Panic",
        cost: [Y, Y, C],
        damage: 120,
        damageCalculation: "+",
        text: "Flip a coin until you get tails. This attack does 30 more damage for each heads."
      }, {
        name: "Supreme Puff-GX",
        cost: [Y, Y],
        damage: 0,
        gxAttack: true,
        text: "Take another turn after this one. (Skip the between-turns step.) If this Pok\xE9mon has at least 14 extra [Y] Energy attached to it (in addition to this attack's cost), your opponent shuffles all of their Benched Pok\xE9mon and all cards attached to them into their deck. (You can't use more than 1 GX attack in a game.)"
      }];
      this.set = "CEC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "143";
      this.name = "Togepi & Cleffa & Igglybuff-GX";
      this.fullName = "Togepi & Cleffa & Igglybuff-GX CEC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return FLIP_UNTIL_TAILS_AND_COUNT_HEADS(store, state, player, (heads) => {
          effect.damage += 30 * heads;
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        player.usedTurnSkip = true;
        const extraEffectCost = [Y, Y, Y, Y, Y, Y, Y, Y, Y, Y, Y, Y, Y, Y, Y, Y];
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergy);
        const meetsExtraEffectCost = StateUtils.checkEnoughEnergy(checkProvidedEnergy.energyMap, extraEffectCost);
        if (!meetsExtraEffectCost) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, player);
        opponent.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card !== opponent.active.getPokemonCard()) {
            MOVE_CARDS(store, state, cardList, opponent.deck, { sourceCard: this });
          }
        });
        store.prompt(state, new ShuffleDeckPrompt(opponent.id), (order) => {
          opponent.deck.applyOrder(order);
        });
      }
      return state;
    }
  };

