  var Trevenant3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Phantump";
      this.cardType = [P];
      this.hp = 120;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C];
      this.usedPerplexingForest = false;
      this.attacks = [
        {
          name: "Perplexing Forest",
          cost: [C],
          damage: 20,
          text: "You may have your opponent switch their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon."
        },
        {
          name: "Shadow Impact",
          cost: [P, C, C],
          damage: 120,
          text: "Put 4 damage counters on 1 of your Pok\xE9mon."
        }
      ];
      this.set = "CEC";
      this.setNumber = "94";
      this.cardImage = "assets/cardback.png";
      this.name = "Trevenant";
      this.fullName = "Trevenant CEC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedPerplexingForest = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedPerplexingForest) {
        this.usedPerplexingForest = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          store.prompt(state, new ConfirmPrompt(
            player.id,
            GameMessage.WANT_TO_USE_ABILITY
          ), (result) => {
            if (result) {
              SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
            }
          });
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedPerplexingForest = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          const targets = selected || [];
          targets.forEach((target) => {
            const putCountersEffect = new PutCountersEffect(effect, 40);
            putCountersEffect.target = target;
            store.reduceEffect(state, putCountersEffect);
          });
        });
      }
      return state;
    }
  };

