  var Wishiwashi = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 180;
      this.weakness = [{ type: L }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Scatter",
        powerType: 2 /* ABILITY */,
        text: "At the end of your opponent's turn, if this Pok\xE9mon has any damage counters on it, flip a coin.If tails, shuffle this Pok\xE9mon and all cards attached to it into your deck."
      }];
      this.attacks = [{
        name: "Hydro Splash",
        cost: [W, W, C],
        damage: 130,
        text: ""
      }];
      this.set = "CEC";
      this.setNumber = "62";
      this.cardImage = "assets/cardback.png";
      this.name = "Wishiwashi";
      this.fullName = "Wishiwashi CEC";
      this.SCATTER_MARKER = "SCATTER_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof BeginTurnEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        opponent.marker.addMarker(this.SCATTER_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && StateUtils.getOpponent(state, effect.player).marker.hasMarker(this.SCATTER_MARKER, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            if (cardList.damage > 0) {
              return COIN_FLIP_PROMPT(store, state, opponent, (result) => {
                if (result === false) {
                  MOVE_POKEMON_OFF_BOARD(store, state, cardList, {
                    pokemonDestination: opponent.deck,
                    sourceCard: this
                  });
                  return store.prompt(state, new ShuffleDeckPrompt(opponent.id), (order) => {
                    opponent.deck.applyOrder(order);
                    opponent.marker.removeMarker(this.SCATTER_MARKER, this);
                    return state;
                  });
                }
                opponent.marker.removeMarker(this.SCATTER_MARKER, this);
                return state;
              });
            }
          }
        });
        opponent.marker.removeMarker(this.SCATTER_MARKER, this);
        return state;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-cosmic-eclipse/wishiwashi-gx.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var WishiwashiGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "School Storm",
          cost: [W, C],
          damage: 20,
          damageCalculation: "x",
          text: "This attack does 20 damage for each of your Wishiwashi and Wishiwashi-GX in play."
        },
        {
          name: "Massive Catch-GX",
          cost: [C],
          damage: 0,
          text: "Look at the top 12 cards of your deck and put any number of Basic Pok\xE9mon you find there onto your Bench. Shuffle the other cards back into your deck. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "CEC";
      this.setNumber = "63";
      this.cardImage = "assets/cardback.png";
      this.name = "Wishiwashi-GX";
      this.fullName = "Wishiwashi-GX CEC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let wishiwashiCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const pokemonCard = cardList.getPokemonCard();
          if (pokemonCard && (pokemonCard.name === "Wishiwashi" || pokemonCard.name === "Wishiwashi-GX")) {
            wishiwashiCount++;
          }
        });
        effect.damage = 20 * wishiwashiCount;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: Math.min(12, player.deck.cards.length), sourceCard: this });
        SHOW_CARDS_TO_PLAYER(store, state, player, deckTop.cards);
        const openSlots = player.bench.filter((b) => b.cards.length === 0).length;
        const basicCount = deckTop.cards.filter(
          (c) => c instanceof PokemonCard && c.stage === 2 /* BASIC */
        ).length;
        if (basicCount === 0 || openSlots === 0) {
          MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: this });
          SHUFFLE_DECK(store, state, player);
          return state;
        }
        const maxToSelect = Math.min(basicCount, openSlots);
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            deckTop,
            { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
            { min: 0, max: maxToSelect, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            cards.forEach((card) => {
              const emptySlot = player.bench.find((b) => b.cards.length === 0);
              if (emptySlot) {
                MOVE_CARDS(store, state, deckTop, emptySlot, { cards: [card], sourceCard: this });
                emptySlot.pokemonPlayedTurn = state.turn;
              }
            });
            MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: this });
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      return state;
    }
  };

