  var Beastite = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "CEC";
      this.setNumber = "185";
      this.cardImage = "assets/cardback.png";
      this.name = "Beastite";
      this.fullName = "Beastite CEC";
      this.text = "The attacks of the Ultra Beast this card is attached to do 10 more damage to your opponent's Active Pok\xE9mon for each Prize card you have taken (before applying Weakness and Resistance).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.source.tools.includes(this)) {
        const pokemonCard = effect.source.getPokemonCard();
        if (!pokemonCard || !pokemonCard.hasTag("Ultra Beast" /* ULTRA_BEAST */)) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.source);
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, player);
        if (effect.target !== opponent.active) {
          return state;
        }
        const prizesTaken = 6 - player.getPrizeLeft();
        if (prizesTaken > 0) {
          effect.damage += 10 * prizesTaken;
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-cosmic-eclipse/bellelba-and-brycen-man.ts
  init_game();
