  var IslandChallengeAmulet = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "CEC";
      this.setNumber = "194";
      this.cardImage = "assets/cardback.png";
      this.name = "Island Challenge Amulet";
      this.fullName = "Island Challenge Amulet CEC";
      this.text = "The Pok\xE9mon-GX or Pok\xE9mon-EX this card is attached to gets -100 HP, and when it is Knocked Out by damage from an opponent's attack, that player takes 1 fewer Prize card.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckHpEffect && effect.target.tools.includes(this)) {
        const sourceCard = effect.target.getPokemonCard();
        try {
          const toolEffect = new ToolEffect(effect.player, this);
          store.reduceEffect(state, toolEffect);
        } catch {
          return state;
        }
        if (!sourceCard) {
          return state;
        }
        if (!sourceCard.hasTag("GX" /* POKEMON_GX */) && !sourceCard.hasTag("EX" /* POKEMON_EX */)) {
          return state;
        }
        effect.hp -= 100;
      }
      if (effect instanceof KnockOutEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const sourceCard = effect.target.getPokemonCard();
        if (state.phase !== 3 /* ATTACK */ || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        if (!sourceCard) {
          return state;
        }
        if (!sourceCard.hasTag("GX" /* POKEMON_GX */) && !sourceCard.hasTag("EX" /* POKEMON_EX */)) {
          return state;
        }
        try {
          const toolEffect = new ToolEffect(player, this);
          store.reduceEffect(state, toolEffect);
        } catch {
          return state;
        }
        effect.prizeCount -= 1;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-cosmic-eclipse/lanas-fishing-rod.ts
  init_game();
  init_game_message();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_prefabs();
  init_choose_cards_prompt();
  function* playCard144(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    let tools = 0;
    let pokemons = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      if (c instanceof TrainerCard && c.trainerType === 3 /* TOOL */) {
        tools += 1;
      } else if (c instanceof PokemonCard) {
        pokemons += 1;
      } else {
        blocked.push(index);
      }
    });
    const hasBoth = tools > 0 && pokemons > 0;
    const minCount = hasBoth ? 2 : tools > 0 || pokemons > 0 ? 1 : 0;
    const maxCount = hasBoth ? 2 : 1;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        hasBoth ? GameMessage.CHOOSE_CARD_TO_DECK : GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        {},
        { min: minCount, max: maxCount, allowCancel: false, blocked, maxTools: 1, maxPokemons: 1 }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
