  var NsResolve = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CEC";
      this.setNumber = "200";
      this.cardImage = "assets/cardback.png";
      this.name = "N's Resolve";
      this.fullName = "N's Resolve CEC";
      this.text = "Discard the top 6 cards of your deck. If any of those cards are basic Energy cards, attach them to 1 of your Benched Dragon Pok\xE9mon. You may play only 1 Supporter card during your turn (before your attack).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        let hasDragonBench = false;
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList === player.active) {
            blocked.push(target);
            return;
          }
          if (cardList.cards.length === 0) {
            blocked.push(target);
            return;
          }
          const checkType = new CheckPokemonTypeEffect(cardList);
          store.reduceEffect(state, checkType);
          if (checkType.cardTypes.includes(11 /* DRAGON */)) {
            hasDragonBench = true;
          } else {
            blocked.push(target);
          }
        });
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, {
          count: Math.min(6, player.deck.cards.length),
          sourceCard: this
        });
        const basicEnergies = deckTop.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        );
        const nonEnergies = deckTop.cards.filter(
          (c) => !(c instanceof EnergyCard && c.energyType === 0 /* BASIC */)
        );
        nonEnergies.forEach(
          (c) => MOVE_CARDS(store, state, deckTop, player.discard, { cards: [c], sourceCard: this })
        );
        if (basicEnergies.length === 0 || !hasDragonBench) {
          MOVE_CARDS(store, state, deckTop, player.discard, { sourceCard: this });
          return state;
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (targets) => {
            if (targets && targets.length > 0) {
              const target = targets[0];
              basicEnergies.forEach((energyCard) => {
                const attachEffect = new AttachEnergyEffect(player, energyCard, target);
                store.reduceEffect(state, attachEffect);
                MOVE_CARDS(store, state, deckTop, target, { cards: [energyCard], sourceCard: this });
              });
            }
            MOVE_CARDS(store, state, deckTop, player.discard, { sourceCard: this });
          }
        );
      }
      return state;
    }
  };

