  var RollerSkater = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CEC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "203";
      this.name = "Roller Skater";
      this.fullName = "Roller Skater CEC";
      this.text = "Discard a card from your hand. If you do, draw 2 cards. If you discarded an Energy card in this way, draw 2 more cards.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.hand.cards.filter((c) => c !== effect.trainerCard).length < 1 || player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            effect.player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            {},
            { allowCancel: false, min: 1, max: 1 }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length === 0) {
              return;
            }
            let cardsToDraw = 2;
            if (cards[0].superType === 3 /* ENERGY */) {
              cardsToDraw = 4;
            }
            MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
            DRAW_CARDS(store, state, player, cardsToDraw);
          }
        );
        return state;
      }
      return state;
    }
  };

