  function* playCard146(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    if (!player.marker.hasMarker(self.ROSA_MARKER)) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      const isPokemon = c instanceof PokemonCard;
      const isBasicEnergy = c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
      const isTrainer = c instanceof TrainerCard;
      if (!isPokemon && !isBasicEnergy && !isTrainer) {
        blocked.push(index);
      }
    });
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: self });
    const maxPokemons = 1;
    const maxEnergies = 1;
    const maxTrainers = 1;
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        {},
        { min: 0, max: 3, allowCancel: true, blocked, maxPokemons, maxEnergies, maxTrainers }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var Rosa = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CEC";
      this.setNumber = "204";
      this.cardImage = "assets/cardback.png";
      this.name = "Rosa";
      this.fullName = "Rosa CEC";
      this.text = `You can play this card only if 1 of your Pok\xE9mon was Knocked Out during your opponent's last turn.

Search your deck for a Pok\xE9mon, a Trainer card, and a basic Energy card, reveal them, and put them into your hand. Then, shuffle your deck.`;
      this.ROSA_MARKER = "ROSA_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard146(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const duringTurn = [2 /* PLAYER_TURN */, 3 /* ATTACK */].includes(state.phase);
        if (!duringTurn || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) {
          effect.player.marker.addMarker(this.ROSA_MARKER, this);
        }
        return state;
      }
      REMOVE_OPPONENT_LAST_TURN_MARKER_AT_END_OF_TURN(effect, this.ROSA_MARKER, this);
      return state;
    }
  };

