  var MartialArtsDojo = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.cardImage = "assets/cardback.png";
      this.setNumber = "179";
      this._trainerType = 2 /* STADIUM */;
      this.set = "UNB";
      this.name = "Martial Arts Dojo";
      this.fullName = "Martial Arts Dojo UNB";
      this.text = "The attacks of non-Ultra Beast Pok\xE9mon that have any basic [F] Energy attached to them (both yours and your opponent's) do 10 more damage to the opponent's Active Pok\xE9mon (before applying Weakness and Resistance). If the attacking player has more Prize cards remaining than their opponent, those attacks do 40 more damage instead.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      if (effect instanceof DealDamageEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBasicFightingEnergy = player.active.cards.filter(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.name === "Fighting Energy"
        ).length > 0;
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, player, player.active, this)) {
          return state;
        }
        if (player.active.cards.some((c) => c.hasTag("Ultra Beast" /* ULTRA_BEAST */)) || !hasBasicFightingEnergy) {
          return state;
        }
        if (effect.damage > 0 && effect.target === opponent.active) {
          effect.damage += player.getPrizeLeft() > opponent.getPrizeLeft() ? 40 : 10;
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unbroken-bonds/power-plant.ts
  init_game_error();
