  var PowerPlant = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "UNB";
      this.name = "Power Plant";
      this.fullName = "Power Plant UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "183";
      this.text = "Pok\xE9mon-GX and Pok\xE9mon-EX in play (both yours and your opponent's) have no Abilities.";
    }
    reduceEffect(store, state, effect) {
      HANDLE_ABILITY_LOCK(
        effect,
        ({ card }) => {
          if (StateUtils.getStadiumCard(state) !== this) {
            return false;
          }
          const isEXorGX = card.hasTag("GX" /* POKEMON_GX */) || card.hasTag("EX" /* POKEMON_EX */);
          if (!isEXorGX) {
            return false;
          }
          const slot = StateUtils.findPokemonSlot(state, card);
          if (slot === void 0) {
            return false;
          }
          const owner = StateUtils.findOwner(state, slot);
          if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, slot)) {
            return false;
          }
          return true;
        },
        {
          allowUseFromHand: true,
          allowUseFromDiscard: true,
          error: GameMessage.BLOCKED_BY_EFFECT
        }
      );
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

