  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-crimson-invasion/alolan-marowak.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_energy_card();
  init_check_effects();
  init_prefabs();
  init_attack_effects2();
  var AlolanMarowak = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Cubone";
      this.cardType = [R];
      this.hp = 100;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Dance of Flames",
        cost: [],
        damage: 0,
        text: "For each Energy attached to your opponent's Pok\xE9mon, attach a [R] Energy card from your discard pile to your Pok\xE9mon in any way you like."
      }, {
        name: "Burning Bonemerang",
        cost: [R, R, C],
        damage: 70,
        damageCalculation: "x",
        text: "Flip 2 coins. This attack does 70 damage for each heads. If either of them is heads, your opponent's Active Pok\xE9mon is now Burned."
      }];
      this.set = "CIN";
      this.setNumber = "12";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Marowak";
      this.fullName = "Alolan Marowak CIN";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let totalEnergy = 0;
        const allOpponentPokemon = [opponent.active, ...opponent.bench.filter((b) => b.cards.length > 0)];
        allOpponentPokemon.forEach((pokemonSlot) => {
          const checkEnergy = new CheckProvidedEnergyEffect(opponent, pokemonSlot);
          store.reduceEffect(state, checkEnergy);
          totalEnergy += checkEnergy.energyMap.length;
        });
        if (totalEnergy === 0) {
          return state;
        }
        const fireEnergyInDiscard = player.discard.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(2 /* FIRE */)
        ).length;
        if (fireEnergyInDiscard === 0) {
          return state;
        }
        const maxAttach = Math.min(totalEnergy, fireEnergyInDiscard);
        state = ATTACH_ENERGY_PROMPT(
          store,
          state,
          player,
          2 /* BOTTOM_PLAYER */,
          4 /* DISCARD */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { min: 0, max: maxAttach, allowCancel: true }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          const heads = results.filter((r) => r).length;
          effect.damage = 70 * heads;
          if (heads > 0) {
            YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_BURNED(store, state, effect);
          }
        });
      }
      return state;
    }
  };

