  var BuzzwoleGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */, "Ultra Beast" /* ULTRA_BEAST */];
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 190;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Jet Punch",
          cost: [F],
          damage: 30,
          text: "This attack does 30 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Knuckle Impact",
          cost: [F, F, F],
          damage: 160,
          text: "This Pok\xE9mon can't attack during your next turn."
        },
        {
          name: "Absorption-GX",
          cost: [F, F, F],
          damage: 0,
          gxAttack: true,
          text: "This attack does 40 damage for each of your remaining Prize cards. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "CIN";
      this.name = "Buzzwole-GX";
      this.fullName = "Buzzwole-GX CIN";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "57";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const damageEffect = new PutDamageEffect(effect, 30);
            damageEffect.target = targets[0];
            store.reduceEffect(state, damageEffect);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        player.active.cannotAttackNextTurnPending = true;
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        effect.damage = 40 * player.getPrizeLeft();
        return state;
      }
      return state;
    }
  };

