      this.evolvesFrom = "Minccino";
      this.cardType = [C];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Amazing Plea",
          cost: [C],
          damage: 0,
          text: "Choose 2 cards from your discard pile. Then, ask your opponent if you may put them into your hand. If yes, put those cards into your hand. If no, this attack does 80 damage to your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "CIN";
