  var Emolga5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 60;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Energy Catch",
          cost: [C],
          damage: 0,
          text: "Put 3 basic Energy cards from your discard pile into your hand."
        },
        {
          name: "Volt Switch",
          cost: [L],
          damage: 30,
          text: "Switch this Pok\xE9mon with 1 of your Benched Lightning Pok\xE9mon."
        }
      ];
      this.set = "CIN";
      this.setNumber = "35";
      this.cardImage = "assets/cardback.png";
      this.name = "Emolga";
      this.fullName = "Emolga CIN";
      this.usedVoltSwitch = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const basicEnergyCount = player.discard.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        ).length;
        const count = Math.min(3, basicEnergyCount);
        if (count > 0) {
          SEARCH_DISCARD_PILE_FOR_CARDS_TO_HAND(
            store,
            state,
            player,
            this,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min: count, max: count, allowCancel: false }
          );
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedVoltSwitch = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedVoltSwitch) {
        this.usedVoltSwitch = false;
        const player = effect.player;
        const blocked = [];
        player.bench.forEach((bench, index) => {
          if (bench.cards.length === 0) {
            blocked.push({ player: 2 /* BOTTOM_PLAYER */, slot: 2 /* BENCH */, index });
            return;
          }
          const checkType = new CheckPokemonTypeEffect(bench);
          store.reduceEffect(state, checkType);
          if (!checkType.cardTypes.includes(4 /* LIGHTNING */)) {
            blocked.push({ player: 2 /* BOTTOM_PLAYER */, slot: 2 /* BENCH */, index });
          }
        });
        const hasLightningBench = player.bench.some((bench, index) => {
          return bench.cards.length > 0 && !blocked.some((b) => b.index === index);
        });
        if (hasLightningBench) {
          store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false, blocked }
          ), (selected) => {
            if (selected && selected.length > 0) {
              player.switchPokemon(selected[0], store, state);
            }
          });
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedVoltSwitch = false;
      }
      return state;
    }
  };

