  var Hydreigon7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Zweilous";
      this.cardType = [D];
      this.hp = 160;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Weed Out",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may choose 3 of your Benched Pok\xE9mon. Then, discard your other Benched Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Dark Destruction",
        cost: [D, D, C],
        damage: 120,
        text: "You may discard an Energy from this Pok\xE9mon. If you do, discard an Energy from your opponent's Active Pok\xE9mon."
      }];
      this.set = "CIN";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "62";
      this.name = "Hydreigon";
      this.fullName = "Hydreigon CIN";
      this.WEED_OUT_MARKER = "WEED_OUT_MARKER";
    }
    reduceEffect(store, state, effect) {
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.WEED_OUT_MARKER, this);
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.WEED_OUT_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const playerBench = player.bench.filter((c) => c.cards.length > 0);
        if (playerBench.length <= 3) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        player.marker.addMarker(this.WEED_OUT_MARKER, this);
        ABILITY_USED(player, this);
        if (playerBench.length > 3) {
          store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false, min: Math.min(playerBench.length, 3), max: 3 }
          ), (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (card) => {
              if (card !== player.active && !targets.includes(card)) {
                card.clearEffects();
                MOVE_CARDS(store, state, card, player.discard);
              }
            });
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const activeCardList = opponent.active;
        const activePokemonCard = activeCardList.getPokemonCard();
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_EFFECT_OF_ATTACK
        ), (wantToUse) => {
          if (wantToUse) {
            DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1);
            let hasPokemonWithEnergy = false;
            if (activePokemonCard && activeCardList.cards.some((c) => c.superType === 3 /* ENERGY */)) {
              hasPokemonWithEnergy = true;
            }
            if (!hasPokemonWithEnergy) {
              return state;
            }
            let cards = [];
            state = store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              opponent.active,
              { superType: 3 /* ENERGY */ },
              { min: 1, max: 1, allowCancel: false }
            ), (selected) => {
              cards = selected || [];
              const discardEnergy2 = new DiscardCardsEffect(effect, cards);
              return store.reduceEffect(state, discardEnergy2);
            });
          }
        });
      }
      return state;
    }
  };

