  var Magikarp7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 30;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.powers = [{
        name: "Submerge",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is on your Bench, prevent all damage done to this Pok\xE9mon by attacks (both yours and your opponent's)."
      }];
      this.attacks = [
        {
          name: "Waterfall Evolution",
          cost: [W, C, C],
          damage: 0,
          text: "Search your deck for a card that evolves from this Pok\xE9mon and put it onto this Pok\xE9mon to evolve it. Then, shuffle your deck."
        }
      ];
      this.set = "CIN";
      this.setNumber = "17";
      this.cardImage = "assets/cardback.png";
      this.name = "Magikarp";
      this.fullName = "Magikarp CIN";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this) {
        const player = StateUtils.findOwner(state, effect.target);
        if (effect.target === player.active) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.preventDefault = true;
        return state;
      }
      if (effect instanceof DealDamageEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this) {
        const player = StateUtils.findOwner(state, effect.target);
        if (effect.target === player.active) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.preventDefault = true;
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || card.evolvesFrom !== "Magikarp") {
            blocked.push(index);
          }
        });
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_EVOLVE,
          player.deck,
          { superType: 1 /* POKEMON */ },
          { min: 0, max: 1, allowCancel: true, blocked }
        ), (selected) => {
          if (selected && selected.length > 0) {
            const evolutionCard = selected[0];
            MOVE_CARDS(store, state, player.deck, cardList, { cards: [evolutionCard], sourceCard: this });
            cardList.clearEffects();
            cardList.pokemonPlayedTurn = state.turn;
          }
          SHUFFLE_DECK(store, state, player);
        });
      }
      return state;
    }
  };

