  var Regirock4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 130;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Rock Peak Growl",
        powerType: 2 /* ABILITY */,
        text: "Your Registeel's attacks do 10 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Tough Swing",
          cost: [F, F, C],
          damage: 110,
          text: "This attack's damage isn't affected by Resistance."
        }
      ];
      this.set = "CIN";
      this.setNumber = "53";
      this.cardImage = "assets/cardback.png";
      this.name = "Regirock";
      this.fullName = "Regirock CIN";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const damageSource = effect.source.getPokemonCard();
        if (!player.active.cards.includes(this) && !player.bench.some((b) => b.cards.includes(this))) {
          return state;
        }
        const regirockSlot = player.active.cards.includes(this) ? player.active : player.bench.find((b) => b.cards.includes(this));
        if (!regirockSlot || regirockSlot.getPokemonCard() !== this) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (damageSource && damageSource.name === "Registeel" && effect.target === opponent.active) {
          effect.damage += 10;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.ignoreResistance = true;
      }
      return state;
    }
  };

