  init_game_phase_effects();
  init_game_effects();
  init_prefabs();
  var Staraptor3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.usedSkyHunting = false;
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Staravia";
      this.cardType = [C];
      this.hp = 140;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Clutch",
          cost: [C, C],
          damage: 50,
          text: "The Defending Pok\xE9mon can't retreat during your opponent's next turn."
        },
        {
          name: "Sky Hunting",
          cost: [C, C, C, C],
          damage: 120,
          text: "If your opponent's Pok\xE9mon is Knocked Out by the damage from this attack, switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        }
      ];
      this.set = "CIN";
      this.setNumber = "83";
      this.cardImage = "assets/cardback.png";
      this.name = "Staraptor";
      this.fullName = "Staraptor CIN";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        state = BLOCK_RETREAT(store, state, effect, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedSkyHunting = true;
      }
      if (effect instanceof KnockOutEffect && this.usedSkyHunting) {
        if (state.phase === 3 /* ATTACK */) {
          const player = StateUtils.findOwner(state, effect.target);
          const attacker = StateUtils.getOpponent(state, player);
          if (attacker.active.getPokemonCard() === this) {
            if (attacker.bench.some((b) => b.cards.length > 0)) {
              SWITCH_ACTIVE_WITH_BENCHED(store, state, attacker);
            }
          }
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedSkyHunting = false;
      }
      return state;
    }
  };

