  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-crimson-invasion/starmie.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Starmie7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Staryu";
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.ESCAPE_MARKER = "STARMIE_CIN_ESCAPE_MARKER";
      this.powers = [{
        name: "Escape",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may shuffle this Pok\xE9mon and all cards attached to it into your deck."
      }];
      this.attacks = [
        {
          name: "Spinning Attack",
          cost: [C],
          damage: 40,
          text: ""
        }
      ];
      this.set = "CIN";
      this.setNumber = "16";
      this.cardImage = "assets/cardback.png";
      this.name = "Starmie";
      this.fullName = "Starmie CIN";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.ESCAPE_MARKER, this);
        ABILITY_USED(player, this);
        const cardList = StateUtils.findCardList(state, this);
        if (cardList === player.active && !player.bench.some((b) => b.cards.length > 0)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        MOVE_CARDS(store, state, cardList, player.deck, { sourceCard: this });
        cardList.clearEffects();
        return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
          player.deck.applyOrder(order);
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.ESCAPE_MARKER, this);
      return state;
    }
  };

