  var Wigglytuff5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Jigglypuff";
      this.cardType = [Y];
      this.hp = 120;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Hypnoblast",
          cost: [C, C],
          damage: 30,
          text: "Your opponent's Active Pok\xE9mon is now Asleep."
        },
        {
          name: "Punishing Slap",
          cost: [Y, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "If any of your opponent's Pok\xE9mon have any [D] Energy attached to them, this attack does 60 more damage."
        }
      ];
      this.set = "CIN";
      this.setNumber = "72";
      this.cardImage = "assets/cardback.png";
      this.name = "Wigglytuff";
      this.fullName = "Wigglytuff CIN";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let hasDarkEnergy = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          const checkEnergy = new CheckProvidedEnergyEffect(opponent, cardList);
          store.reduceEffect(state, checkEnergy);
          if (checkEnergy.energyMap.some((em) => em.provides.includes(7 /* DARK */))) {
            hasDarkEnergy = true;
          }
        });
        if (hasDarkEnergy) {
          effect.damage += 60;
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-crimson-invasion/xerneas.ts
