  var Xerneas3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [Y];
      this.hp = 130;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Lead",
          cost: [C],
          damage: 0,
          text: "Search your deck for a Supporter card, reveal it, and put it into your hand. Then, shuffle your deck."
        },
        {
          name: "Bright Horns",
          cost: [Y, Y, Y],
          damage: 130,
          text: "This Pok\xE9mon can't use Bright Horns during your next turn."
        }
      ];
      this.set = "CIN";
      this.name = "Xerneas";
      this.fullName = "Xerneas CIN";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "73";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.deck.cards.length === 0) {
          return state;
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.deck,
          { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
          { min: 0, max: 1, allowCancel: false }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length > 0) {
            MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this, sourceEffect: this.attacks[0] });
            store.prompt(state, [new ShowCardsPrompt(
              opponent.id,
              GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
              cards
            )], () => {
            });
          }
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        if (!player.active.cannotUseAttacksNextTurnPending.includes("Bright Horns")) {
          player.active.cannotUseAttacksNextTurnPending.push("Bright Horns");
        }
      }
      return state;
    }
  };

