  function* playCard148(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const supportersAndStadiumsInDiscard = player.discard.cards.filter(
      (c) => c instanceof TrainerCard && (c.trainerType === 2 /* STADIUM */ || c.trainerType === 1 /* SUPPORTER */)
    ).length;
    if (supportersAndStadiumsInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: self });
    effect.preventDefault = true;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      if (c instanceof TrainerCard && (c.trainerType === 2 /* STADIUM */ || c.trainerType === 1 /* SUPPORTER */)) {
      } else {
        blocked.push(index);
      }
    });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.discard,
        {},
        {
          min: Math.min(2, supportersAndStadiumsInDiscard),
          max: Math.min(2, supportersAndStadiumsInDiscard),
          allowCancel: false,
          blocked
        }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return state;
  }
  var Lusamine = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CIN";
      this.name = "Lusamine";
      this.fullName = "Lusamine CIN";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "96";
      this.text = "Put 2 in any combination of Supporter and Stadium cards from your discard pile into your hand.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const discardEffect = new DiscardToHandEffect(player, this);
        store.reduceEffect(state, discardEffect);
        if (discardEffect.preventDefault) {
          return state;
        }
        const generator = playCard148(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

