  var Altaria7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Swablu";
      this.cardType = [N];
      this.hp = 80;
      this.weakness = [{ type: Y }];
      this.retreat = [C];
      this.powers = [{
        name: "Fight Song",
        powerType: 2 /* ABILITY */,
        text: "Your Dragon Pok\xE9mon\u2019s attacks do 20 more damage to your opponent\u2019s Active Pok\xE9mon (before applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Pierce",
          cost: [C, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "DRM";
      this.setNumber = "40";
      this.cardImage = "assets/cardback.png";
      this.name = "Altaria";
      this.fullName = "Altaria DRM";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.target === StateUtils.getOpponent(state, effect.player).active) {
        const player = effect.player;
        let altariaInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            altariaInPlay = true;
          }
        });
        if (!altariaInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkType = new CheckPokemonTypeEffect(effect.source);
        store.reduceEffect(state, checkType);
        if (checkType.cardTypes.includes(11 /* DRAGON */)) {
          effect.damage += 20;
        }
      }
      return state;
    }
  };

