  var Blaziken5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.cardType = [2 /* FIRE */];
      this.hp = 150;
      this.weakness = [{ type: 3 /* WATER */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.evolvesFrom = "Combusken";
      this.powers = [{
        name: "Firestarter",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: " Once during your turn (before your attack), you may attach a [R] Energy card from your discard pile to 1 of your Benched Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Fire Stream",
        cost: [2 /* FIRE */, 9 /* COLORLESS */, 9 /* COLORLESS */],
        damage: 90,
        text: " Discard a [R] Energy from this Pok\xE9mon. This attack does 20 damage to each of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.) "
      }];
      this.set = "DRM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "6";
      this.name = "Blaziken";
      this.fullName = "Blaziken DRM";
      this.FIRESTARTER_MARKER = "PSYCHIC_RECHARGE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.FIRESTARTER_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.FIRESTARTER_MARKER, this)) {
        effect.player.marker.removeMarker(this.FIRESTARTER_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(2 /* FIRE */);
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.FIRESTARTER_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { allowCancel: true, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            return;
          }
          player.marker.addMarker(this.FIRESTARTER_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const benched = opponent.bench.filter((b) => b.cards.length > 0);
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [2 /* FIRE */],
          { allowCancel: false }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = player.active;
          store.reduceEffect(state, discardEnergy2);
          benched.forEach((target) => {
            const damageEffect = new DealDamageEffect(effect, 20);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          });
        });
      }
      return state;
    }
  };

