      this.cardType = [R];
      this.hp = 80;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Burning Fighter",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may discard the top 5 cards of your deck. If any of those cards are [R] Energy cards, attach them to this Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Flamethrower",
          cost: [R, R, C],
          damage: 80,
          text: "Discard an Energy from this Pok\xE9mon."
        }
      ];
      this.set = "DRM";
      this.setNumber = "2";
      this.cardImage = "assets/cardback.png";
      this.name = "Charmeleon";
      this.fullName = "Charmeleon DRM";
