  var Corsola5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Bubble Shoot",
          cost: [W],
          damage: 0,
          text: "This attack does 20 damage times the amount of [W] Energy attached to this Pok\xE9mon to 1 of your opponent\u2019s Pok\xE9mon. (Don\u2019t apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "DRM";
      this.setNumber = "27";
      this.cardImage = "assets/cardback.png";
      this.name = "Corsola";
      this.fullName = "Corsola DRM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergy);
        let waterEnergyCount = 0;
        checkProvidedEnergy.energyMap.forEach((em) => {
          waterEnergyCount += em.provides.filter((cardType) => cardType === 3 /* WATER */).length;
        });
        const totalDamage = 20 * waterEnergyCount;
        if (totalDamage === 0) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          const target = selected[0];
          if (target === opponent.active) {
            const damageEffect = new DealDamageEffect(effect, totalDamage);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          } else {
            const damageEffect = new PutDamageEffect(effect, totalDamage);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          }
        });
      }
      return state;
    }
  };

