  var DragoniteGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Dragonair";
      this.cardType = [N];
      this.hp = 250;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Dragon Claw",
          cost: [L],
          damage: 70,
          text: ""
        },
        {
          name: "Giga Impact",
          cost: [W, L, C, C],
          damage: 200,
          text: "This Pok\xE9mon can\u2019t attack during your next turn."
        },
        {
          name: "Dragonporter GX",
          cost: [C, C, C],
          damage: 0,
          text: "Put 3 Dragon Pok\xE9mon from your discard pile onto your Bench. (You can\u2019t use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "DRM";
      this.setNumber = "37";
      this.cardImage = "assets/cardback.png";
      this.name = "Dragonite GX";
      this.fullName = "Dragonite GX DRM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        effect.player.active.cannotAttackNextTurnPending = true;
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (slots2.length === 0) {
          return state;
        }
        const dragonInDiscard = player.discard.cards.filter(
          (c) => c instanceof PokemonCard && pokemonHasCardType(c, 11 /* DRAGON */)
        );
        if (dragonInDiscard.length === 0) {
          return state;
        }
        const max = Math.min(3, slots2.length, dragonInDiscard.length);
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          if (!(c instanceof PokemonCard) || !pokemonHasCardType(c, 11 /* DRAGON */)) {
            blocked.push(index);
          }
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            player.discard,
            { superType: 1 /* POKEMON */, cardType: [11 /* DRAGON */] },
            { min: max, max, allowCancel: false, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            cards.forEach((card, index) => {
              if (index < slots2.length) {
                MOVE_CARDS(store, state, player.discard, slots2[index], { cards: [card], sourceCard: this });
                slots2[index].pokemonPlayedTurn = state.turn;
              }
            });
          }
        );
      }
      return state;
    }
  };

