  function* useWashOut(next, store, state, effect) {
    const player = effect.player;
    const blockedMap = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
      store.reduceEffect(state, checkProvidedEnergy);
      const blockedCards = [];
      checkProvidedEnergy.energyMap.forEach((em) => {
        if (!em.provides.includes(3 /* WATER */) && !em.provides.includes(0 /* ANY */)) {
          blockedCards.push(em.card);
        }
      });
      const blocked = [];
      blockedCards.forEach((bc) => {
        const index = cardList.cards.indexOf(bc);
        if (index !== -1 && !blocked.includes(index)) {
          blocked.push(index);
        }
      });
      if (blocked.length !== 0 || target.slot === 1 /* ACTIVE */) {
        blockedMap.push({ source: target, blocked: target.slot === 1 /* ACTIVE */ ? cardList.cards.map((_, i) => i) : blocked });
      }
    });
    const blocked2 = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
      if (player.active.getPokemonCard() !== card) {
        blocked2.push(target);
      }
    });
    return store.prompt(state, new MoveEnergyPrompt(
      effect.player.id,
      GameMessage.MOVE_ENERGY_CARDS,
      2 /* BOTTOM_PLAYER */,
      [2 /* BENCH */, 1 /* ACTIVE */],
      // Only allow moving from bench
      { superType: 3 /* ENERGY */ },
      { allowCancel: false, min: 0, blockedMap, blockedTo: blocked2 }
    ), (transfers) => {
      if (transfers === null) {
        return;
      }
      for (const transfer of transfers) {
        const source = StateUtils.getTarget(state, player, transfer.from);
        const target = player.active;
        MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: effect.card });
      }
    });
  }
