  function* playCard150(next, store, state, effect) {
    const player = effect.player;
    const hasBench = player.bench.some((b) => b.cards.length > 0);
    const checkPokemonTypeEffect = new CheckPokemonTypeEffect(player.active);
    store.reduceEffect(state, checkPokemonTypeEffect);
    const activeIsNotWater = !checkPokemonTypeEffect.cardTypes.includes(3 /* WATER */);
    if (hasBench === false || activeIsNotWater) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: effect.trainerCard });
    const pokemonCard = player.active.getPokemonCard();
    if (pokemonCard) {
      let targets = [];
      yield store.prompt(
        state,
        new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ),
        (results) => {
          targets = results || [];
          next();
        }
      );
      if (targets.length === 0) {
        return state;
      }
      const healEffect = new HealEffect(player, player.active, 30);
      store.reduceEffect(state, healEffect);
      player.active.clearEffects();
      player.switchPokemon(targets[0], store, state);
      return state;
    }
    return state;
  }
