  var AlolanExeggutor = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Exeggcute";
      this.cardType = [G];
      this.hp = 160;
      this.weakness = [{ type: R }];
      this.retreat = [C, C, C];
      this.attacks = [{
        name: "Tropical Shake",
        cost: [G],
        damage: 20,
        text: "This attack does 20 more damage for each type of Basic Energy card in your discard pile. You can't add more than 100 damage in this way."
      }];
      this.set = "FLI";
      this.setNumber = "2";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Exeggutor";
      this.fullName = "Alolan Exeggutor FLI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const energyTypes = [];
        player.discard.cards.forEach((c) => {
          if (c instanceof EnergyCard && c.energyType == 0 /* BASIC */) {
            for (const et of c.provides) {
              if (!energyTypes.includes(et)) {
                energyTypes.push(et);
              }
            }
          }
        });
        effect.damage += Math.min(energyTypes.length * 20, 100);
      }
      return state;
    }
  };

