  init_game_phase_effects();
  init_prefabs();
  init_attack_effects2();
  var Araquanid3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Dewpider";
      this.cardType = [W];
      this.hp = 100;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.BUBBLE_MARKER = "ARAQUANID_FLI_BUBBLE_MARKER";
      this.CLEAR_BUBBLE_MARKER = "ARAQUANID_FLI_CLEAR_BUBBLE_MARKER";
      this.attacks = [{
        name: "Bubble",
        cost: [W],
        damage: 30,
        text: "Flip a coin. If heads, your opponent's Active Pok\xE9mon is now Paralyzed."
      }, {
        name: "Bubble Trap",
        cost: [C, C],
        damage: 40,
        damageCalculation: "+",
        text: "If 1 of your Pok\xE9mon used Bubble during your last turn, this attack does 80 more damage."
      }];
      this.set = "FLI";
      this.setNumber = "33";
      this.cardImage = "assets/cardback.png";
      this.name = "Araquanid";
      this.fullName = "Araquanid FLI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_PARALYZED(store, state, effect);
          }
        });
        player.marker.addMarker(this.BUBBLE_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.CLEAR_BUBBLE_MARKER, this)) {
          effect.damage += 80;
        }
      }
      if (effect instanceof EndTurnEffect) {
        if (effect.player.marker.hasMarker(this.CLEAR_BUBBLE_MARKER, this)) {
          effect.player.marker.removeMarker(this.CLEAR_BUBBLE_MARKER, this);
        }
        if (effect.player.marker.hasMarker(this.BUBBLE_MARKER, this)) {
          effect.player.marker.removeMarker(this.BUBBLE_MARKER, this);
          effect.player.marker.addMarker(this.CLEAR_BUBBLE_MARKER, this);
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-forbidden-light/arceus-prism-star.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_attack_effects();
  init_prefabs();
  var ArceusPrismStar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Prism Star" /* PRISM_STAR */];
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 160;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [
        {
          name: "First Law",
          powerType: 2 /* ABILITY */,
          text: "Prevent all effects of your opponent's attacks, except damage, done to this Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Trinity Star",
          cost: [C],
          damage: 30,
          text: "You can use this attack only if you have [G], [W], and [L] Pok\xE9mon on your Bench. Search your deck for up to 3 basic Energy cards and attach them to your Pok\xE9mon in any way you like. Then, shuffle your deck."
        }
      ];
      this.set = "FLI";
      this.setNumber = "96";
      this.cardImage = "assets/cardback.png";
      this.name = "Arceus Prism Star";
      this.fullName = "Arceus \u25C7 FLI";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this) {
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const attacker = StateUtils.findOwner(state, effect.source);
        if (player === attacker) {
          return state;
        }
        if (effect instanceof ApplyWeaknessEffect) {
          return state;
        }
        if (effect instanceof PutDamageEffect) {
          return state;
        }
        if (effect instanceof DealDamageEffect) {
          return state;
        }
        effect.preventDefault = true;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let hasGrass = false;
        let hasWater = false;
        let hasLightning = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (cardList === player.active) {
            return;
          }
          const checkType = new CheckPokemonTypeEffect(cardList);
          store.reduceEffect(state, checkType);
          if (checkType.cardTypes.includes(1 /* GRASS */)) {
            hasGrass = true;
          }
          if (checkType.cardTypes.includes(3 /* WATER */)) {
            hasWater = true;
          }
          if (checkType.cardTypes.includes(4 /* LIGHTNING */)) {
            hasLightning = true;
          }
        });
        if (!hasGrass || !hasWater || !hasLightning) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        ATTACH_UP_TO_X_ENERGY_FROM_DECK_TO_Y_OF_YOUR_POKEMON(store, state, player, 3, 3, {
          energyFilter: { energyType: 0 /* BASIC */ },
          allowCancel: false,
          min: 0
        });
      }
      return state;
    }
  };

