  var DialgaGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [M];
      this.hp = 180;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Overclock",
          cost: [M],
          damage: 0,
          text: "Draw cards until you have 6 cards in your hand."
        },
        {
          name: "Shred",
          cost: [M, C, C],
          damage: 80,
          shredAttack: true,
          text: "This attack's damage isn't affected by any effects on your opponent's Active Pok\xE9mon."
        },
        {
          name: "Timeless-GX",
          cost: [M, M, M, C, C],
          damage: 150,
          gxAttack: true,
          text: "Take another turn after this one. (Skip the between-turns step.) (You can't use more than 1 GX attack in a game.) "
        }
      ];
      this.set = "FLI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "82";
      this.name = "Dialga-GX";
      this.fullName = "Dialga-GX FLI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        while (player.hand.cards.length < 6) {
          if (player.deck.cards.length === 0) {
            break;
          }
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const applyWeakness = new ApplyWeaknessEffect(effect, 80);
        store.reduceEffect(state, applyWeakness);
        const damage = applyWeakness.damage;
        effect.damage = 0;
        if (damage > 0) {
          opponent.active.damage += damage;
          const afterDamage = new AfterDamageEffect(effect, damage);
          state = store.reduceEffect(state, afterDamage);
        }
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        player.usedTurnSkip = true;
      }
      return state;
    }
  };

