      this.hp = 40;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Secret Blessings",
          cost: [Y],
          damage: 0,
          text: "Shuffle 3 in any combination of Pok\xE9mon and basic Energy cards from your discard pile into your deck."
        }
      ];
      this.set = "FLI";
