  var Frogadier4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.cardType = [3 /* WATER */];
      this.hp = 80;
      this.retreat = [9 /* COLORLESS */];
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.evolvesFrom = "Froakie";
      this.powers = [{
        name: "Gale Shuriken",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may put 2 damage counters on 1 of your opponent's Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Water Drip",
        cost: [3 /* WATER */],
        damage: 20,
        text: ""
      }];
      this.set = "FLI";
      this.name = "Frogadier";
      this.fullName = "Frogadier FLI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "23";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = StateUtils.findOwner(state, effect.target);
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            if (IS_ABILITY_BLOCKED(store, state, player, this)) return state;
            return store.prompt(state, new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
              1 /* TOP_PLAYER */,
              [1 /* ACTIVE */, 2 /* BENCH */],
              { min: 1, max: 1, allowCancel: false }
            ), (selected) => {
              const targets = selected || [];
              if (targets.length > 0) {
                const canApplyAbility = new EffectOfAbilityEffect(player, this.powers[0], this, targets[0]);
                store.reduceEffect(state, canApplyAbility);
                if (canApplyAbility.target) {
                  canApplyAbility.target.damage += 20;
                }
              }
            });
          }
          return state;
        });
      }
      return state;
    }
  };

