  var Goodra4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.cardType = [N];
      this.hp = 160;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C, C];
      this.evolvesFrom = "Sliggoo";
      this.powers = [{
        name: "Hydration",
        powerType: 2 /* ABILITY */,
        text: "Whenever you attach a [W] Energy card from your hand to this Pok\xE9mon, heal 20 damage from it."
      }];
      this.attacks = [{
        name: "Soaking Horn",
        cost: [W, Y, C],
        damage: 80,
        damageCalculation: "+",
        text: "If this Pok\xE9mon was healed during this turn, this attack does 80 more damage."
      }];
      this.set = "FLI";
      this.name = "Goodra";
      this.fullName = "Goodra FLI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "94";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.target.getPokemonCard() === this) {
        if (IS_ABILITY_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        if (effect.energyCard.energyType === 0 /* BASIC */ && effect.energyCard.provides.includes(3 /* WATER */)) {
          const healEffect = new HealEffect(effect.player, effect.target, 20);
          return store.reduceEffect(state, healEffect);
        }
        if (effect.energyCard.energyType === 1 /* SPECIAL */) {
          effect.target.cards.push(effect.energyCard);
          const checkWaterEnergy = new CheckProvidedEnergyEffect(effect.player, effect.target);
          store.reduceEffect(state, checkWaterEnergy);
          effect.target.cards.pop();
          const energyMap = checkWaterEnergy.energyMap.find((element) => element.card === effect.energyCard);
          const providedEnergy = energyMap?.provides;
          if (providedEnergy?.includes(3 /* WATER */) || providedEnergy?.includes(0 /* ANY */)) {
            const healEffect = new HealEffect(effect.player, effect.target, 20);
            return store.reduceEffect(state, healEffect);
          }
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this) && effect.player.active.healedThisTurn) {
        effect.damage += 80;
      }
      return state;
    }
  };

