      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Final Hour",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon is your Active Pok\xE9mon and is Knocked Out by damage from an opponent's attack, put 3 damage counters on 1 of your opponent's Pok\xE9mon."
      }];
