  var Magnezone4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Magneton";
      this.cardType = [L];
      this.hp = 150;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Magnetic Circuit",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "As often as you like during your turn (before your attack), you may attach a [L] Energy card from your hand to 1 of your Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Zap Cannon",
        cost: [L, L, L, C],
        damage: 130,
        text: "This Pokemon can't use Zap Cannon during your next turn."
      }];
      this.set = "FLI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "36";
      this.name = "Magnezone";
      this.fullName = "Magnezone FLI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(L);
        });
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.hand,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Lightning Energy" },
          { allowCancel: true }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            const energyCard = transfer.card;
            const attachEnergyEffect = new AttachEnergyEffect(player, energyCard, target);
            store.reduceEffect(state, attachEnergyEffect);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (!player.active.cannotUseAttacksNextTurnPending.includes("Zap Cannon")) {
          player.active.cannotUseAttacksNextTurnPending.push("Zap Cannon");
        }
      }
      return state;
    }
  };

