  var Malamar6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Inkay";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Psychic Recharge",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may attach a [P] Energy card from your discard pile to 1 of your Benched Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Psychic Sphere",
        cost: [P, P, C],
        damage: 60,
        text: ""
      }];
      this.set = "FLI";
      this.name = "Malamar";
      this.fullName = "Malamar FLI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "51";
      this.PSYCHIC_RECHARGE_MARKER = "PSYCHIC_RECHARGE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.PSYCHIC_RECHARGE_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(5 /* PSYCHIC */);
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.PSYCHIC_RECHARGE_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Psychic Energy" },
          { allowCancel: true, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            return;
          }
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          player.marker.addMarker(this.PSYCHIC_RECHARGE_MARKER, this);
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
        return state;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.PSYCHIC_RECHARGE_MARKER, this)) {
        effect.player.marker.removeMarker(this.PSYCHIC_RECHARGE_MARKER, this);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-forbidden-light/meowstic.ts
  init_pokemon_card();
