  init_prefabs();
  init_attack_effects2();
  var Tyrantrum2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Tyrunt";
      this.cardType = [F];
      this.hp = 160;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Tyrannical Heart",
        powerType: 2 /* ABILITY */,
        text: "As long as you don't have more Pok\xE9mon in play than your opponent, this Pok\xE9mon's attacks do 60 more damage (before applying Weakness and Resistance), and it takes 30 less damage from attacks (after applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Crunch",
          cost: [F, F, C],
          damage: 100,
          text: "Discard an Energy from your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "FLI";
      this.setNumber = "69";
      this.cardImage = "assets/cardback.png";
      this.name = "Tyrantrum";
      this.fullName = "Tyrantrum FLI";
    }
    countPokemonInPlay(player) {
      let count = 1;
      player.bench.forEach((b) => {
        if (b.cards.length > 0) count++;
      });
      return count;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!IS_ABILITY_BLOCKED(store, state, player, this)) {
          const myCount = this.countPokemonInPlay(player);
          const oppCount = this.countPokemonInPlay(opponent);
          if (myCount <= oppCount) {
            effect.damage += 60;
          }
        }
        DISCARD_AN_ENERGY_FROM_OPPONENTS_ACTIVE_POKEMON(store, state, effect);
      }
      if (effect instanceof DealDamageEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this) {
        const player = StateUtils.findOwner(state, effect.target);
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const myCount = this.countPokemonInPlay(player);
        const oppCount = this.countPokemonInPlay(opponent);
        if (myCount <= oppCount) {
          effect.damage = Math.max(0, effect.damage - 30);
        }
      }
      return state;
    }
  };

