  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-forbidden-light/volcanion-prism-star.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_game_phase_effects();
  init_play_card_effects();
  init_prefabs();
  var VolcanionPrismStar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Prism Star" /* PRISM_STAR */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 160;
      this.weakness = [{ type: L }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Jet Geyser",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn (before your attack), you may discard a [W] Energy card from your hand. If you do, your opponent switches their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Sauna Blast",
          cost: [3 /* WATER */, 3 /* WATER */, 3 /* WATER */],
          damage: 100,
          text: "This attack does 20 damage to each of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "FLI";
      this.setNumber = "31";
      this.cardImage = "assets/cardback.png";
      this.name = "Volcanion Prism Star";
      this.fullName = "Volcanion Prism Star FLI";
      this.JET_GEYSER_MARKER = "JET_GEYSER_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.JET_GEYSER_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.hand.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.JET_GEYSER_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            { superType: 3 /* ENERGY */, name: "Water Energy" },
            { allowCancel: false, min: 1, max: 1 }
          ),
          (cards) => {
            cards = cards || [];
            player.marker.addMarker(this.JET_GEYSER_MARKER, this);
            MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
            return store.prompt(
              state,
              new ChoosePokemonPrompt(
                opponent.id,
                GameMessage.CHOOSE_POKEMON_TO_SWITCH,
                2 /* BOTTOM_PLAYER */,
                [2 /* BENCH */],
                { allowCancel: false }
              ),
              (result) => {
                const cardList = result[0];
                opponent.switchPokemon(cardList);
              }
            );
          }
        );
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card) => {
          if (cardList !== opponent.active) {
            const damageEffect = new PutDamageEffect(effect, 20);
            damageEffect.target = cardList;
            store.reduceEffect(state, damageEffect);
          }
        });
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.JET_GEYSER_MARKER, this);
      }
      return state;
    }
  };

