  var BeastRing = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "FLI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "102";
      this.name = "Beast Ring";
      this.fullName = "Beast Ring FLI";
      this.text = "You can play this card only if your opponent has exactly 3 or 4 Prize cards remaining.\n\nSearch your deck for up to 2 basic Energy cards and attach them to 1 of your Ultra Beasts. Then, shuffle your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.getPrizeLeft() !== 3 && opponent.getPrizeLeft() !== 4) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        effect.preventDefault = true;
        let ultraBeastInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card) => {
          if (card.hasTag("Ultra Beast" /* ULTRA_BEAST */)) {
            ultraBeastInPlay = true;
          }
        });
        if (!ultraBeastInPlay) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked2 = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (!card.hasTag("Ultra Beast" /* ULTRA_BEAST */)) {
            blocked2.push(target);
          }
        });
        store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: 0, max: 2, blockedTo: blocked2, sameTarget: true }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
            }
            return state;
          }
        );
      }
      return state;
    }
  };

