  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-forbidden-light/crasher-wake.ts
  init_trainer_card();
  init_card_types();
  init_play_card_effects();
  init_game_error();
  init_game_message();
  init_choose_cards_prompt();
  init_card_list();
  init_show_cards_prompt();
  init_state_utils();
  init_shuffle_prompt();
  init_prefabs();
  function* playCard152(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const hasEnergyInHand = player.hand.cards.filter((c) => {
      return c.superType === 3 /* ENERGY */ && c.name === "Water Energy";
    }).length >= 2;
    if (!hasEnergyInHand) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    const handTemp = new CardList();
    handTemp.cards = player.hand.cards.filter((c) => c !== self);
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        handTemp,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
        { min: 2, max: 2, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: self });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        {},
        { min: 0, max: 2, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length > 0) {
      MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var CrasherWake = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "FLI";
      this.setNumber = "104";
      this.cardImage = "assets/cardback.png";
      this.name = "Crasher Wake";
      this.fullName = "Crasher Wake FLI";
      this.text = "Discard 2 [W] Energy cards from your hand. If you do, search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard152(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-forbidden-light/diantha.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_game_effects();
  init_game_phase_effects();
  init_play_card_effects();
  init_prefabs();
  var Diantha = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "FLI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "105";
      this.name = "Diantha";
      this.fullName = "Diantha FLI";
      this.text = "You can play this card only if 1 of your [Y] Pok\xE9mon was Knocked Out during your opponent's last turn. Put 2 cards from your discard pile into your hand.";
      this.DIANTHA_MARKER = "DIANTHA_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (!player.marker.hasMarker(this.DIANTHA_MARKER)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.discard.cards.length < 2) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.discard,
            {},
            { min: 2, max: 2, allowCancel: false }
          ),
          (cards) => {
            MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: this });
            return state;
          }
        );
      }
      if (effect instanceof KnockOutEffect && pokemonHasCardTypeOptional(effect.target.getPokemonCard(), 10 /* FAIRY */)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const duringTurn = [2 /* PLAYER_TURN */, 3 /* ATTACK */].includes(state.phase);
        if (!duringTurn || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) {
          effect.player.marker.addMarker(this.DIANTHA_MARKER, this);
        }
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) {
          REMOVE_OPPONENT_LAST_TURN_MARKER_AT_END_OF_TURN(effect, this.DIANTHA_MARKER, this);
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-forbidden-light/eneporter.ts
  init_trainer_card();
