  var Eneporter = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "FLI";
      this.setNumber = "106";
      this.cardImage = "assets/cardback.png";
      this.name = "Eneporter";
      this.fullName = "Eneporter FLI";
      this.text = "Move a Special Energy from 1 of your opponent's Pok\xE9mon to another of their Pok\xE9mon.";
    }
    // Ref: set-ultra-prism/roserade.ts (Flower Tornado - MoveEnergyPrompt pattern)
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let totalPokemon = 0;
        let hasSpecialEnergy = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          totalPokemon++;
          if (cardList.cards.some((c) => c instanceof EnergyCard && c.energyType === 1 /* SPECIAL */)) {
            hasSpecialEnergy = true;
          }
        });
        if (totalPokemon < 2 || !hasSpecialEnergy) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        store.prompt(
          state,
          new MoveEnergyPrompt(
            player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 1 /* SPECIAL */ },
            { allowCancel: false, min: 1, max: 1 }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, opponent, transfer.from);
              const target = StateUtils.getTarget(state, opponent, transfer.to);
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      return state;
    }
  };

