  var LysandrePrismStar = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this._tags = ["Prism Star" /* PRISM_STAR */];
      this.set = "FLI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "110";
      this.name = "Lysandre Prism Star";
      this.fullName = "Lysandre Prism Star FLI";
      this.text = "For each of your [R] Pok\xE9mon in play, put a card from your opponent's discard pile in the Lost Zone.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.discard.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        let firesInPlay = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          const pokemonType = new CheckPokemonTypeEffect(cardList);
          store.reduceEffect(state, pokemonType);
          if (pokemonType.cardTypes.includes(R)) {
            firesInPlay++;
          }
        });
        if (!firesInPlay) {
          MOVE_CARDS(store, state, player.supporter, player.lostzone, { cards: [this], sourceCard: this });
          return state;
        }
        let cards = [];
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.discard,
            {},
            {
              min: Math.min(opponent.discard.cards.length, firesInPlay),
              max: Math.min(opponent.discard.cards.length, firesInPlay),
              allowCancel: false
            }
          ),
          (selected) => {
            cards = selected || [];
            if (cards.length === 0) {
              return state;
            }
            MOVE_CARDS(store, state, opponent.discard, opponent.lostzone, { cards, sourceCard: this });
            MOVE_CARDS(store, state, player.supporter, player.lostzone, { cards: [this], sourceCard: this });
            store.log(state, "LOG_PLAYER_DRAWS_CARD" /* LOG_PLAYER_DRAWS_CARD */, { name: player.name });
          }
        );
      }
      return state;
    }
  };

