  var PalkiaGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [N];
      this.hp = 180;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Spatial Control",
          cost: [W],
          damage: 0,
          text: "Move any number of Energy from your Benched Pok\xE9mon to this Pok\xE9mon."
        },
        {
          name: "Hydro Pressure",
          cost: [C, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "This attack does 20 more damage times the amount of [W] Energy attached to this Pok\xE9mon."
        },
        {
          name: "Zero Vanish-GX",
          cost: [W, W, W, C, C],
          damage: 150,
          text: "Shuffle all Energy from each of your opponent's Pok\xE9mon into their deck. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "UPR";
      this.setNumber = "101";
      this.cardImage = "assets/cardback.png";
      this.name = "Palkia-GX";
      this.fullName = "Palkia-GX UPR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blockedTo = player.bench.map((_, index) => {
          return {
            player: 2 /* BOTTOM_PLAYER */,
            slot: 2 /* BENCH */,
            index
          };
        });
        const blockedFrom = [
          {
            player: 2 /* BOTTOM_PLAYER */,
            slot: 1 /* ACTIVE */,
            index: 0
          }
        ];
        store.prompt(
          state,
          new MoveEnergyPrompt(
            player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: true, blockedTo, blockedFrom }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        let waterCount = 0;
        checkEnergy.energyMap.forEach((em) => {
          waterCount += em.provides.filter((p) => p === 3 /* WATER */ || p === 0 /* ANY */).length;
        });
        effect.damage += 20 * waterCount;
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          const energyCards = cardList.cards.filter((c) => c instanceof EnergyCard);
          energyCards.forEach((card) => {
            MOVE_CARDS(store, state, cardList, opponent.deck, { cards: [card], sourceCard: this });
          });
        });
        SHUFFLE_DECK(store, state, opponent);
      }
      return state;
    }
  };

