  var Absol6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 100;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Future Sight",
          cost: [D],
          damage: 0,
          text: "Look at the top 4 cards of either player's deck and put them back in any order."
        },
        {
          name: "Doom News",
          cost: [D, C],
          damage: 0,
          text: "Put all Energy attached to this Pok\xE9mon into your hand. At the end of your opponent's next turn, the Defending Pok\xE9mon will be Knocked Out."
        }
      ];
      this.set = "GRI";
      this.setNumber = "81";
      this.cardImage = "assets/cardback.png";
      this.name = "Absol";
      this.fullName = "Absol GRI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const options = [
          {
            message: GameMessage.ORDER_YOUR_DECK,
            action: () => {
              const deckTop = new CardList();
              MOVE_CARDS(store, state, player.deck, deckTop, { count: Math.min(4, player.deck.cards.length), sourceCard: this });
              return store.prompt(state, new OrderCardsPrompt(
                player.id,
                GameMessage.CHOOSE_CARDS_ORDER,
                deckTop,
                { allowCancel: false }
              ), (order) => {
                if (order === null) {
                  return state;
                }
                deckTop.applyOrder(order);
                deckTop.moveToTopOfDestination(player.deck);
              });
            }
          },
          {
            message: GameMessage.ORDER_OPPONENT_DECK,
            action: () => {
              const opponentDeckTop = new CardList();
              MOVE_CARDS(store, state, opponent.deck, opponentDeckTop, { count: Math.min(4, opponent.deck.cards.length), sourceCard: this });
              return store.prompt(state, new OrderCardsPrompt(
                player.id,
                GameMessage.CHOOSE_CARDS_ORDER,
                opponentDeckTop,
                { allowCancel: false }
              ), (order) => {
                if (order === null) {
                  return state;
                }
                opponentDeckTop.applyOrder(order);
                opponentDeckTop.moveToTopOfDestination(opponent.deck);
              });
            }
          }
        ];
        return store.prompt(state, new SelectPrompt(
          player.id,
          GameMessage.CHOOSE_OPTION,
          options.map((opt) => opt.message),
          { allowCancel: false }
        ), (choice) => {
          const option = options[choice];
          option.action();
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const energyCards = player.active.cards.filter((c) => c instanceof EnergyCard);
        energyCards.forEach((c) => {
          MOVE_CARDS(store, state, player.active, player.hand, { cards: [c], sourceCard: this });
        });
        KNOCK_OUT_DEFENDING_POKEMON_AT_END_OF_OPPONENTS_NEXT_TURN(store, state, effect, this);
      }
      return state;
    }
  };

