  var AlolanGolem = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Alolan Graveler";
      this.cardType = [L];
      this.hp = 160;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C, C, C, C];
      this.attacks = [{
        name: "Electromagnetic Rock Wrecker",
        cost: [L, C, C],
        damage: 80,
        damageCalculation: "x",
        text: "Flip a coin for each [L] Energy attached to this Pok\xE9mon. This attack does 80 damage for each heads."
      }, {
        name: "Heavy Slam",
        cost: [L, C, C, C],
        damage: 200,
        damageCalculation: "-",
        text: "This attack does 30 less damage for each Colorless in your opponent's Active Pok\xE9mon's Retreat Cost."
      }];
      this.set = "GRI";
      this.setNumber = "42";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Golem";
      this.fullName = "Alolan Golem GRI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkEnergy);
        const lightningEnergyCount = checkEnergy.energyMap.reduce((sum, energy2) => {
          return sum + energy2.provides.filter((p) => p === 4 /* LIGHTNING */ || p === 0 /* ANY */).length;
        }, 0);
        if (lightningEnergyCount > 0) {
          MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, lightningEnergyCount, (results) => {
            effect.damage = results.filter((r) => r).length * 80;
          });
        } else {
          effect.damage = 0;
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkRetreatCost = new CheckRetreatCostEffect(opponent);
        store.reduceEffect(state, checkRetreatCost);
        const colorlessCount = checkRetreatCost.cost.filter((c) => c === 9 /* COLORLESS */).length;
        effect.damage = Math.max(0, effect.damage - 30 * colorlessCount);
      }
      return state;
    }
  };

