  function* useWhirlpool3(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    if (!opponent.active.cards.some((c) => c.superType === 3 /* ENERGY */)) {
      return state;
    }
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        opponent.active,
        { superType: 3 /* ENERGY */, energyType: 1 /* SPECIAL */ },
        { min: 1, max: 1, allowCancel: true }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    const discardEnergy2 = new DiscardCardsEffect(effect, cards);
    return store.reduceEffect(state, discardEnergy2);
  }
  var DrampaGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["GX" /* POKEMON_GX */];
      this.cardType = [9 /* COLORLESS */];
      this.hp = 180;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Righteous Edge",
          cost: [9 /* COLORLESS */],
          damage: 20,
          text: "Discard a Special Energy from your opponent's Active Pok\xE9mon."
        },
        {
          name: "Berserk",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 80,
          text: "If your Benched Pok\xE9mon have any damage counters on them, this attack does 70 more damage."
        },
        {
          name: "Big Wheel-GX",
          cost: [9 /* COLORLESS */],
          damage: 0,
          text: "Shuffle your hand into your deck. Then, draw 10 cards. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "GRI";
      this.setNumber = "115";
      this.cardImage = "assets/cardback.png";
      this.name = "Drampa-GX";
      this.fullName = "Drampa-GX GRI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const generator = useWhirlpool3(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        let isThereDamage = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (cardList === player.active) {
            return;
          }
          if (cardList.damage > 0) {
            isThereDamage = true;
          }
        });
        if (isThereDamage) {
          effect.damage += 70;
        }
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        if (player.hand.cards.length > 0) {
          MOVE_CARDS(store, state, player.hand, player.deck, { cards: player.hand.cards, sourceCard: this });
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
            while (player.hand.cards.length < 10) {
              if (player.deck.cards.length === 0) {
                break;
              }
              MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
            }
          });
        }
      }
      return state;
    }
  };

