  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-guardians-rising/goodra.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_check_effects();
  init_game_phase_effects();
  init_prefabs();
  var Goodra5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Sliggoo";
      this.cardType = [N];
      this.hp = 160;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Power Whip",
          cost: [C],
          damage: 0,
          text: "This attack does 20 damage times the amount of Energy attached to this Pok\xE9mon to 1 of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Beat Slider",
          cost: [W, Y, C],
          damage: 130,
          text: "Your opponent switches their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon."
        }
      ];
      this.set = "GRI";
      this.setNumber = "96";
      this.cardImage = "assets/cardback.png";
      this.name = "Goodra";
      this.fullName = "Goodra GRI";
      this.usedBeatSlider = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkEnergy);
        let energyCount = 0;
        checkEnergy.energyMap.forEach((em) => {
          energyCount += em.provides.length;
        });
        const totalDamage = 20 * energyCount;
        if (totalDamage === 0) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          const target = selected[0];
          if (target === opponent.active) {
            const damageEffect = new DealDamageEffect(effect, totalDamage);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          } else {
            const damageEffect = new PutDamageEffect(effect, totalDamage);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedBeatSlider = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedBeatSlider) {
        this.usedBeatSlider = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedBeatSlider = false;
      }
      return state;
    }
  };

