  var Lunala3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Cosmoem";
      this.cardType = [P];
      this.hp = 160;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Shatter Shot",
          cost: [P],
          damage: 40,
          damageCalculation: "x",
          text: "This attack does 40 damage times the amount of [P] Energy attached to this Pok\xE9mon."
        },
        {
          name: "Wings of the Moone",
          cost: [P, P, P],
          damage: 130,
          text: "Move all Energy from this Pok\xE9mon to your Benched Pok\xE9mon in any way you like."
        }
      ];
      this.set = "GRI";
      this.setNumber = "61";
      this.cardImage = "assets/cardback.png";
      this.name = "Lunala";
      this.fullName = "Lunala GRI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        let psychicCount = 0;
        checkEnergy.energyMap.forEach((em) => {
          psychicCount += em.provides.filter((p) => p === 5 /* PSYCHIC */ || p === 0 /* ANY */).length;
        });
        effect.damage = 40 * psychicCount;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const attachedEnergies = player.active.cards.filter(
          (card) => card.superType === 3 /* ENERGY */
        );
        if (attachedEnergies.length === 0) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.active,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: attachedEnergies.length, max: attachedEnergies.length }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

