  var Oricorio22 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Supernatural Dance",
          cost: [C],
          damage: 0,
          text: "For each Pok\xE9mon in your opponent's discard pile, put 1 damage counter on your opponent's Pok\xE9mon in any way you like. "
        },
        {
          name: "Revelation Dance",
          cost: [C],
          damage: 30,
          text: "If there is no Stadium card in play, this attack does nothing."
        }
      ];
      this.set = "GRI";
      this.setNumber = "56";
      this.cardImage = "assets/cardback.png";
      this.name = "Oricorio";
      this.fullName = "Oricorio GRI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let pokemonCount = 0;
        opponent.discard.cards.forEach((c) => {
          if (c instanceof PokemonCard) {
            pokemonCount += 10;
          }
        });
        if (pokemonCount === 0) {
          return state;
        }
        const maxAllowedDamage = [];
        let damageLeft = 0;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(opponent, cardList);
          store.reduceEffect(state, checkHpEffect);
          damageLeft += checkHpEffect.hp - cardList.damage;
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        const damage = Math.min(pokemonCount, damageLeft);
        return store.prompt(
          state,
          new PutDamagePrompt(
            effect.player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            damage,
            maxAllowedDamage,
            { allowCancel: false }
          ),
          (targets) => {
            const results = targets || [];
            for (const result of results) {
              const target = StateUtils.getTarget(state, player, result.target);
              const putCountersEffect = new PutCountersEffect(effect, result.damage);
              putCountersEffect.target = target;
              store.reduceEffect(state, putCountersEffect);
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        if (!StateUtils.getStadiumCard(state)) {
          effect.damage = 0;
        }
      }
      return state;
    }
  };

