  init_attack_effects2();
  var Politoed2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Poliwhirl";
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Roll Call",
          cost: [W],
          damage: 0,
          text: "Search your deck for a Poliwag, a Poliwhirl, and a Poliwrath, and put them onto your Bench. Then, shuffle your deck."
        },
        {
          name: "Hyper Jump",
          cost: [W, C, C],
          damage: 100,
          text: "You may shuffle this Pok\xE9mon and all cards attached to it into your deck."
        }
      ];
      this.set = "GRI";
      this.setNumber = "25";
      this.cardImage = "assets/cardback.png";
      this.name = "Politoed";
      this.fullName = "Politoed GRI";
      this.wantsToShuffle = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.deck.cards.length === 0) {
          return state;
        }
        const openSlots = player.bench.filter((b) => b.cards.length === 0).length;
        if (openSlots === 0) {
          return SHUFFLE_DECK(store, state, player);
        }
        const nameList = ["Poliwag", "Poliwhirl", "Poliwrath"];
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || !nameList.includes(card.name)) {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          player.deck,
          { superType: 1 /* POKEMON */ },
          { min: 0, max: Math.min(3, openSlots), allowCancel: false, blocked }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length > 0) {
            store.prompt(state, new ShowCardsPrompt(
              opponent.id,
              GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
              cards
            ), () => {
            });
            cards.forEach((card) => {
              const emptySlot = player.bench.find((b) => b.cards.length === 0);
              if (emptySlot) {
                store.reduceEffect(state, new PlayPokemonFromDeckEffect(player, card, emptySlot));
              }
            });
          }
          return SHUFFLE_DECK(store, state, player);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToShuffle) => {
          this.wantsToShuffle = wantToShuffle;
        });
      }
      if (effect instanceof AfterAttackEffect && this.wantsToShuffle) {
        this.wantsToShuffle = false;
        return SHUFFLE_THIS_POKEMON_AND_ALL_ATTACHED_CARDS_INTO_YOUR_DECK(store, state, effect);
      }
      if (effect instanceof EndTurnEffect) {
        this.wantsToShuffle = false;
      }
      return state;
    }
  };

