  var Rayquaza3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 120;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Turbo Storm",
          cost: [C, C],
          damage: 30,
          text: "Attach 2 basic Energy cards from your discard pile to 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Dragon Claw",
          cost: [C, C, C],
          damage: 80,
          text: ""
        }
      ];
      this.set = "GRI";
      this.setNumber = "106";
      this.cardImage = "assets/cardback.png";
      this.name = "Rayquaza";
      this.fullName = "Rayquaza GRI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const basicEnergyInDiscard = player.discard.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        );
        if (basicEnergyInDiscard.length === 0) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return state;
          }
          const target = targets[0];
          const blocked = [];
          player.discard.cards.forEach((card, index) => {
            if (!(card instanceof EnergyCard) || card.energyType !== 0 /* BASIC */) {
              blocked.push(index);
            }
          });
          const availableCount = basicEnergyInDiscard.length;
          const count = Math.min(2, availableCount);
          return store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_ATTACH,
            player.discard,
            { superType: 3 /* ENERGY */ },
            { min: count, max: count, allowCancel: false, blocked }
          ), (selected) => {
            const cards = selected || [];
            cards.forEach((card) => {
              MOVE_CARDS(store, state, player.discard, target, { cards: [card], sourceCard: this });
            });
          });
        });
      }
      return state;
    }
  };

