  var TapuKokoGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 170;
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Aero Trail",
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may move any number of [L] Energy from your other Pok\xE9mon to this Pok\xE9mon. If you do, switch this Pok\xE9mon with your Active Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Sky-High Claws",
          cost: [L, L, C],
          damage: 130,
          text: ""
        },
        {
          name: "Tapu Thunder-GX",
          cost: [L, L, C],
          damage: 50,
          damageCalculation: "x",
          gxAttack: true,
          text: "This attack does 50 damage times the amount of Energy attached to all of your opponent's Pok\xE9mon. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "GRI";
      this.setNumber = "47";
      this.cardImage = "assets/cardback.png";
      this.name = "Tapu Koko-GX";
      this.fullName = "Tapu Koko-GX GRI";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              const blockedFrom = [];
              const blockedTo = [];
              let hasEnergyOnBench = false;
              player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
                if (card === this) {
                  blockedFrom.push(target);
                  return;
                }
                blockedTo.push(target);
                if (cardList.cards.some(
                  (c) => c.superType === 3 /* ENERGY */ && c.name === "Lightning Energy"
                )) {
                  hasEnergyOnBench = true;
                }
              });
              if (hasEnergyOnBench === false) {
                return state;
              }
              return store.prompt(
                state,
                new MoveEnergyPrompt(
                  effect.player.id,
                  GameMessage.MOVE_ENERGY_TO_ACTIVE,
                  2 /* BOTTOM_PLAYER */,
                  [1 /* ACTIVE */, 2 /* BENCH */],
                  { superType: 3 /* ENERGY */, name: "Lightning Energy" },
                  { min: 1, allowCancel: false, blockedFrom, blockedTo }
                ),
                (result) => {
                  const transfers = result || [];
                  transfers.forEach((transfer) => {
                    const source = StateUtils.getTarget(state, player, transfer.from);
                    const target = StateUtils.getTarget(state, player, transfer.to);
                    MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
                  });
                  let bench;
                  player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
                    if (card === this && target.slot === 2 /* BENCH */) {
                      bench = cardList;
                    }
                  });
                  if (bench) {
                    player.switchPokemon(bench);
                  }
                }
              );
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        let energies = 0;
        opponent.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          const opponentEnergy = new CheckProvidedEnergyEffect(opponent, cardList);
          state = store.reduceEffect(state, opponentEnergy);
          opponentEnergy.energyMap.forEach((em) => {
            energies++;
          });
        });
        effect.damage = 50 * energies;
      }
      return state;
    }
  };

