  var Wishiwashi3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 30;
      this.weakness = [{ type: L }];
      this.retreat = [];
      this.powers = [{
        name: "Schooling",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may switch this Pok\xE9mon with a Wishiwashi-GX in your hand. Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Sharpshooting",
          cost: [W],
          damage: 0,
          text: "This attack does 10 damage to 1 of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "GRI";
      this.setNumber = "37";
      this.cardImage = "assets/cardback.png";
      this.name = "Wishiwashi";
      this.fullName = "Wishiwashi GRI";
      this.SCHOOLING_MARKER = "WISHIWASHI_GRI_SCHOOLING_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const wishiwashiGxInHand = player.hand.cards.filter(
          (c) => c instanceof PokemonCard && c.name === "Wishiwashi-GX"
        );
        if (wishiwashiGxInHand.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.SCHOOLING_MARKER, this);
        ABILITY_USED(player, this);
        let cardList = null;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list) => {
          if (list.cards.includes(this)) {
            cardList = list;
          }
        });
        if (cardList === null) {
          return state;
        }
        const blocked = [];
        player.hand.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || card.name !== "Wishiwashi-GX") {
            blocked.push(index);
          }
        });
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.hand,
          { superType: 1 /* POKEMON */ },
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            return;
          }
          const newWishiwashi = selected[0];
          const thisIndex = cardList.cards.indexOf(this);
          if (thisIndex !== -1) {
            cardList.cards.splice(thisIndex, 1);
            const handIndex = player.hand.cards.indexOf(newWishiwashi);
            if (handIndex !== -1) {
              player.hand.cards.splice(handIndex, 1);
            }
            cardList.cards.splice(thisIndex, 0, newWishiwashi);
            player.hand.cards.push(this);
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.SCHOOLING_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_POKEMON(10, effect, store, state);
      }
      return state;
    }
  };

