  var WishiwashiGx2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 210;
      this.weakness = [{ type: L }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Water Gun",
          cost: [W],
          damage: 20,
          text: ""
        },
        {
          name: "Torrential Vortex",
          cost: [W, W, W, C, C],
          damage: 120,
          text: "Discard a Special Energy from your opponent's Active Pok\xE9mon."
        },
        {
          name: "Blue Surge-GX",
          cost: [W, W, W, C, C],
          damage: 220,
          text: "Move all Energy from this Pok\xE9mon to your Benched Pok\xE9mon in any way you like. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "GRI";
      this.setNumber = "38";
      this.cardImage = "assets/cardback.png";
      this.name = "Wishiwashi-GX";
      this.fullName = "Wishiwashi-GX GRI";
      this.usedBlueSurge = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentActive = opponent.active;
        let hasSpecialEnergy = false;
        opponentActive.cards.forEach((c) => {
          if (c instanceof EnergyCard && c.energyType === 1 /* SPECIAL */) {
            hasSpecialEnergy = true;
          }
        });
        if (hasSpecialEnergy) {
          state = store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
              opponentActive,
              { superType: 3 /* ENERGY */, energyType: 1 /* SPECIAL */ },
              { min: 1, max: 1, allowCancel: false }
            ),
            (selected) => {
              const cards = selected || [];
              if (cards.length > 0) {
                MOVE_CARDS(store, state, opponentActive, opponent.discard, { cards, sourceCard: this });
              }
              return state;
            }
          );
        }
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        BLOCK_IF_GX_ATTACK_USED(effect.player);
        effect.player.usedGX = true;
        this.usedBlueSurge = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedBlueSurge) {
        this.usedBlueSurge = false;
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const attachedEnergies = player.active.cards.filter((card) => {
          return card.superType === 3 /* ENERGY */;
        });
        if (attachedEnergies.length === 0) {
          return state;
        }
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.active,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: attachedEnergies.length, max: attachedEnergies.length }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      if (effect instanceof EndTurnEffect) {
        this.usedBlueSurge = false;
      }
      return state;
    }
  };

