  var EnergyLoto = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.regulationMark = "F";
      this.set = "ASR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "140";
      this.name = "Energy Loto";
      this.fullName = "Energy Loto ASR";
      this.text = "Look at the top 7 cards of your deck. You may reveal an Energy card you find there and put it into your hand. Shuffle the other cards back into your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const temp = new CardList();
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.deck, temp, { count: 7, sourceCard: this });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            temp,
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 0, max: 1 }
          ),
          (chosenCards) => {
            if (chosenCards && chosenCards.length > 0) {
              const energyCard = chosenCards[0];
              MOVE_CARDS(store, state, temp, player.hand, { cards: [energyCard], sourceCard: this });
              state = store.prompt(
                state,
                new ShowCardsPrompt(
                  opponent.id,
                  GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                  chosenCards
                ),
                () => state
              );
            }
            MOVE_CARDS(store, state, temp, player.deck, { sourceCard: this });
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      return state;
    }
  };

