  var IncineroarGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Torracat";
      this.cardType = [R];
      this.hp = 250;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.attacks = [{
        name: "Hustling Strike",
        cost: [R],
        damage: 10,
        damageCalculation: "+",
        text: "This attack does 20 more damage for each of your Benched Fire Pok\xE9mon."
      }, {
        name: "Tiger Swing",
        cost: [R, R, C],
        damage: 80,
        damageCalculation: "+",
        text: "Flip 2 coins. This attack does 50 more damage for each heads."
      }, {
        name: "Burning Slam-GX",
        cost: [R, R, C],
        damage: 200,
        text: "Your opponent's Active Pok\xE9mon is now Burned. (You can't use more than 1 GX attack in a game.)"
      }];
      this.set = "SUM";
      this.setNumber = "27";
      this.cardImage = "assets/cardback.png";
      this.name = "Incineroar-GX";
      this.fullName = "Incineroar-GX SUM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let fireBenchCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList === player.active) {
            return;
          }
          if (cardList.cards.length === 0) {
            return;
          }
          const checkType = new CheckPokemonTypeEffect(cardList);
          store.reduceEffect(state, checkType);
          if (checkType.cardTypes.includes(2 /* FIRE */)) {
            fireBenchCount++;
          }
        });
        effect.damage += 20 * fireBenchCount;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 2, (results) => {
          const heads = results.filter((r) => r).length;
          effect.damage += 50 * heads;
        });
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_BURNED(store, state, effect);
      }
      return state;
    }
  };

