  var PrimarinaGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Brionne";
      this.cardType = [W];
      this.hp = 250;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Bubble Beat",
          cost: [C, C],
          damage: 10,
          damageCalculation: "+",
          text: "This attack does 20 more damage times the amount of [W] Energy attached to your Pok\xE9mon."
        },
        {
          name: "Roaring Seas",
          cost: [W, W, W, C],
          damage: 120,
          text: "Discard an Energy from your opponent's Active Pok\xE9mon."
        },
        {
          name: "Grand Echo-GX",
          cost: [C, C],
          damage: 0,
          text: "Heal all damage from all of your Pok\xE9mon. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "SUM";
      this.setNumber = "42";
      this.cardImage = "assets/cardback.png";
      this.name = "Primarina-GX";
      this.fullName = "Primarina-GX SUM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let waterEnergyCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const checkEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkEnergy);
          checkEnergy.energyMap.forEach((em) => {
            em.provides.forEach((type) => {
              if (type === 3 /* WATER */ || type === 0 /* ANY */) {
                waterEnergyCount++;
              }
            });
          });
        });
        effect.damage += 20 * waterEnergyCount;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        DISCARD_AN_ENERGY_FROM_OPPONENTS_ACTIVE_POKEMON(store, state, effect);
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.damage > 0) {
            const healEffect = new HealEffect(player, cardList, cardList.damage);
            store.reduceEffect(state, healEffect);
          }
        });
      }
      return state;
    }
  };

