  init_check_effects();
  init_prefabs();
  var Altaria8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Swablu";
      this.cardType = [N];
      this.hp = 80;
      this.weakness = [{ type: Y }];
      this.retreat = [C];
      this.powers = [{
        name: "Fight Song",
        powerType: 2 /* ABILITY */,
        text: "Your Dragon Pok\xE9mon's attacks do 20 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Pierce",
          cost: [C, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "HIF";
      this.setNumber = "SV37";
      this.cardImage = "assets/cardback.png";
      this.name = "Altaria";
      this.fullName = "Altaria HIF";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.target === StateUtils.getOpponent(state, effect.player).active) {
        const player = effect.player;
        let altariaInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            altariaInPlay = true;
          }
        });
        if (!altariaInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkType = new CheckPokemonTypeEffect(effect.source);
        store.reduceEffect(state, checkType);
        if (checkType.cardTypes.includes(11 /* DRAGON */)) {
          effect.damage += 20;
        }
      }
      return state;
    }
  };

