  var AltariaGx4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Swablu";
      this.cardType = [N];
      this.hp = 200;
      this.weakness = [{ type: Y }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Bright Tone",
          cost: [Y, C],
          damage: 50,
          text: "During your opponent's next turn, prevent all damage done to this Pok\xE9mon by attacks from Pok\xE9mon-GX and Pok\xE9mon-EX."
        },
        {
          name: "Sonic Edge",
          cost: [W, Y, C],
          damage: 110,
          text: "This attack's damage isn't affected by any effects on your opponent's Active Pok\xE9mon."
        },
        {
          name: "Euphoria-GX",
          cost: [Y, C],
          damage: 0,
          text: "Your opponent's Active Pok\xE9mon is now Asleep. Heal all damage from all of your Pok\xE9mon. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "HIF";
      this.setNumber = "SV77";
      this.cardImage = "assets/cardback.png";
      this.name = "Altaria-GX";
      this.fullName = "Altaria-GX HIF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        PREVENT_DAMAGE(store, state, effect, this, { sourceTags: ["GX" /* POKEMON_GX */, "EX" /* POKEMON_EX */] });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        THIS_ATTACKS_DAMAGE_ISNT_AFFECTED_BY_EFFECTS(store, state, effect, 110);
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_ASLEEP(store, state, effect);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.damage > 0) {
            const healEffect = new HealTargetEffect(effect, cardList.damage);
            healEffect.target = cardList;
            store.reduceEffect(state, healEffect);
          }
        });
      }
      return state;
    }
  };

