  var Arbok4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Ekans";
      this.cardType = [P];
      this.hp = 120;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Last Pattern",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon is Knocked Out by damage from an opponent's attack, discard 2 random cards from your opponent's hand."
      }];
      this.attacks = [
        {
          name: "Rocket Tail",
          cost: [P, C, C],
          damage: 50,
          damageCalculation: "+",
          text: "If Jessie & James is in your discard pile, this attack does 80 more damage."
        }
      ];
      this.set = "HIF";
      this.setNumber = "27";
      this.cardImage = "assets/cardback.png";
      this.name = "Arbok";
      this.fullName = "Arbok HIF";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this) {
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (effect.player === player) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, player);
        for (let i = 0; i < 2; i++) {
          if (opponent.hand.cards.length > 0) {
            const randomIndex = Math.floor(Math.random() * opponent.hand.cards.length);
            const randomCard = opponent.hand.cards[randomIndex];
            MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards: [randomCard], sourceCard: this });
          }
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasJessieAndJames = player.discard.cards.some(
          (c) => c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */ && c.name === "Jessie & James"
        );
        if (hasJessieAndJames) {
          effect.damage += 80;
        }
      }
      return state;
    }
  };

