  var Charmeleon8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Charmander";
      this.cardType = [R];
      this.hp = 80;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Burning Fighter",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may discard the top 5 cards of your deck. If any of those cards are [R] Energy cards, attach them to this Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Flamethrower",
          cost: [R, R, C],
          damage: 80,
          text: "Discard an Energy from this Pok\xE9mon."
        }
      ];
      this.set = "HIF";
      this.setNumber = "SV7";
      this.cardImage = "assets/cardback.png";
      this.name = "Charmeleon";
      this.fullName = "Charmeleon HIF";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            const cardList = StateUtils.findCardList(state, this);
            const cardsToDiscard = player.deck.cards.slice(0, Math.min(5, player.deck.cards.length));
            const fireEnergies = [];
            cardsToDiscard.forEach((card) => {
              if (card instanceof EnergyCard && card.energyType === 0 /* BASIC */ && card.provides.includes(2 /* FIRE */)) {
                fireEnergies.push(card);
              }
            });
            MOVE_CARDS(store, state, player.deck, player.discard, { count: Math.min(5, player.deck.cards.length), sourceCard: this });
            fireEnergies.forEach((energy2) => {
              MOVE_CARDS(store, state, player.discard, cardList, { cards: [energy2], sourceCard: this });
            });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1);
      }
      return state;
    }
  };

