  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-hidden-fates/ho-oh-gx.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects2();
  var HoOhGx3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [R];
      this.hp = 190;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Sacred Fire",
          cost: [R, C, C],
          damage: 0,
          text: "This attack does 50 damage to 1 of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Phoenix Burn",
          cost: [R, R, R, C],
          damage: 180,
          text: "This Pok\xE9mon can't use Phoenix Burn during your next turn."
        },
        {
          name: "Eternal Light-GX",
          cost: [R, C, C],
          damage: 0,
          text: "Put 3 in any combination of Fire Pok\xE9mon-GX or Fire Pok\xE9mon-EX from your discard pile onto your Bench. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "HIF";
      this.setNumber = "SV50";
      this.cardImage = "assets/cardback.png";
      this.name = "Ho-Oh-GX";
      this.fullName = "Ho-Oh-GX HIF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_POKEMON(50, effect, store, state);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        effect.player.active.cannotUseAttacksNextTurnPending.push("Phoenix Burn");
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (slots2.length === 0) {
          return state;
        }
        const fireGxExInDiscard = player.discard.cards.filter(
          (c) => c instanceof PokemonCard && pokemonHasCardType(c, 2 /* FIRE */) && (c.hasTag("GX" /* POKEMON_GX */) || c.hasTag("EX" /* POKEMON_EX */))
        );
        if (fireGxExInDiscard.length === 0) {
          return state;
        }
        const max = Math.min(3, slots2.length, fireGxExInDiscard.length);
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          if (!(c instanceof PokemonCard) || !pokemonHasCardType(c, 2 /* FIRE */) || !c.hasTag("GX" /* POKEMON_GX */) && !c.hasTag("EX" /* POKEMON_EX */)) {
            blocked.push(index);
          }
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            player.discard,
            { superType: 1 /* POKEMON */, cardType: [2 /* FIRE */] },
            { min: max, max, allowCancel: false, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            cards.forEach((card, index) => {
              if (index < slots2.length) {
                MOVE_CARDS(store, state, player.discard, slots2[index], { cards: [card], sourceCard: this });
                slots2[index].pokemonPlayedTurn = state.turn;
              }
            });
          }
        );
      }
      return state;
    }
  };

