  function* playCard158(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    if (opponent.hand.cards.length > 0) {
      const opponentMax = Math.min(2, opponent.hand.cards.length);
      yield store.prompt(
        state,
        new ChooseCardsPrompt(
          opponent,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          opponent.hand,
          {},
          { min: opponentMax, max: opponentMax, allowCancel: false }
        ),
        (selected) => {
          const cards = selected || [];
          MOVE_CARDS(store, state, opponent.hand, opponent.discard, {
            cards,
            sourceCard: self
          });
          next();
        }
      );
    }
    let playerDiscarded = [];
    const playerCardsInHand = player.hand.cards.length;
    if (playerCardsInHand > 0) {
      const playerMax = Math.min(2, playerCardsInHand);
      yield store.prompt(
        state,
        new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          {},
          { min: playerMax, max: playerMax, allowCancel: false }
        ),
        (selected) => {
          playerDiscarded = selected || [];
          MOVE_CARDS(store, state, player.hand, player.discard, {
            cards: playerDiscarded,
            sourceCard: self
          });
          next();
        }
      );
    }
    const weezingCards = playerDiscarded.filter((c) => c instanceof Weezing7);
    for (const weezingCard of weezingCards) {
      const weezing = weezingCard;
      try {
        const powerEffect = new PowerEffect(player, weezing.powers[0], weezing);
        store.reduceEffect(state, powerEffect);
      } catch {
        continue;
      }
      if (opponent.hand.cards.length > 0) {
        let useAbility2 = false;
        yield store.prompt(
          state,
          new ConfirmPrompt(player.id, GameMessage.WANT_TO_USE_ABILITY),
          (result) => {
            useAbility2 = result;
            next();
          }
        );
        if (useAbility2) {
          const discardCount = Math.min(1, opponent.hand.cards.length);
          yield store.prompt(
            state,
            new ChooseCardsPrompt(
              opponent,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              opponent.hand,
              {},
              { min: discardCount, max: discardCount, allowCancel: false }
            ),
            (selected) => {
              const cards = selected || [];
              MOVE_CARDS(store, state, opponent.hand, opponent.discard, {
                cards,
                sourceCard: self
              });
              next();
            }
          );
        }
      }
    }
    return state;
  }

