  var MistysWaterCommand = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "HIF";
      this.setNumber = "63";
      this.cardImage = "assets/cardback.png";
      this.name = "Misty's Water Command";
      this.fullName = "Misty's Water Command HIF";
      this.text = "Move any number of [W] Energy from your Pok\xE9mon to your Psyduck, Horsea, Staryu, Starmie-GX, Magikarp, Gyarados, or Lapras in any way you like. You may play only 1 Supporter card during your turn (before your attack).";
      this.VALID_POKEMON_NAMES = [
        "Psyduck",
        "Horsea",
        "Staryu",
        "Starmie-GX",
        "Magikarp",
        "Gyarados",
        "Lapras"
      ];
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        let hasWaterEnergy = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.cards.some((c) => c.superType === 3 /* ENERGY */ && c.name === "Water Energy")) {
            hasWaterEnergy = true;
          }
        });
        if (!hasWaterEnergy) {
          return state;
        }
        let hasValidTarget = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const pokemon = cardList.getPokemonCard();
          if (pokemon && this.VALID_POKEMON_NAMES.includes(pokemon.name)) {
            hasValidTarget = true;
          }
        });
        if (!hasValidTarget) {
          return state;
        }
        const blockedTo = [];
        const activePokemon = player.active.getPokemonCard();
        if (!activePokemon || !this.VALID_POKEMON_NAMES.includes(activePokemon.name)) {
          blockedTo.push({ player: 2 /* BOTTOM_PLAYER */, slot: 1 /* ACTIVE */, index: 0 });
        }
        player.bench.forEach((b, index) => {
          const pokemon = b.getPokemonCard();
          if (!pokemon || !this.VALID_POKEMON_NAMES.includes(pokemon.name)) {
            blockedTo.push({ player: 2 /* BOTTOM_PLAYER */, slot: 2 /* BENCH */, index });
          }
        });
        store.prompt(
          state,
          new MoveEnergyPrompt(
            player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */, name: "Water Energy" },
            { allowCancel: true, blockedTo }
          ),
          (transfers) => {
            if (!transfers) {
              return;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      return state;
    }
  };

