  var Oranguru2 = class _Oranguru extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [9 /* COLORLESS */];
      this.hp = 120;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Instruct",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may draw cards until you have 3 cards in your hand."
      }];
      this.attacks = [{
        name: "Psychic",
        cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
        damage: 60,
        text: "This attack does 20 more damage times the amount of Energy attached to your opponent's Active Pokemon."
      }];
      this.set = "SUM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "113";
      this.name = "Oranguru";
      this.fullName = "Oranguru SUM";
      this.INSTRUCT_MARKER = "INSTRUCT_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.INSTRUCT_MARKER, this);
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.marker.removeMarker(this.INSTRUCT_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.INSTRUCT_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        while (player.hand.cards.length < 3) {
          if (player.deck.cards.length === 0) {
            break;
          }
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
        }
        player.marker.addMarker(this.INSTRUCT_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.forEachPokemon(2 /* BOTTOM_PLAYER */, (player) => {
          if (player instanceof _Oranguru) {
            player.marker.removeMarker(this.INSTRUCT_MARKER);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const pokemon = opponent.active;
        let energyCount = 0;
        pokemon.cards.forEach((c) => {
          if (c instanceof EnergyCard) {
            energyCount++;
          }
        });
        effect.damage += energyCount * 20;
      }
      return state;
    }
  };

