  var GlaceonGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Eevee";
      this.cardType = [W];
      this.hp = 200;
      this.weakness = [{ type: M }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Freezing Gaze",
          useWhenInPlay: false,
          powerType: 2 /* ABILITY */,
          abilityLock: true,
          text: "As long as this Pok\xE9mon is your Active Pok\xE9mon, your opponent's Pok\xE9mon-GX and Pok\xE9mon-EX in play, in their hand, and in their discard pile have no Abilities, except for Freezing Gaze."
        }
      ];
      this.attacks = [
        {
          name: "Frost Spear",
          cost: [W, C, C],
          damage: 90,
          text: "This attack does 30 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Polar Spear-GX",
          cost: [W, C, C],
          damage: 50,
          text: "This attack does 50 damage for each damage counter on your opponent's Active Pok\xE9mon. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "UPR";
      this.setNumber = "39";
      this.cardImage = "assets/cardback.png";
      this.name = "Glaceon-GX";
      this.fullName = "Glaceon-GX UPR";
    }
    reduceEffect(store, state, effect) {
      HANDLE_ABILITY_LOCK(
        effect,
        ({ player, card }) => {
          if (!IS_ABILITY_LOCKER_ACTIVE(state, player, this)) {
            return false;
          }
          if (!card.hasTag("GX" /* POKEMON_GX */) && !card.hasTag("EX" /* POKEMON_EX */)) {
            return false;
          }
          const opponent = StateUtils.getOpponent(state, player);
          const lockerOwner = player.active.getPokemonCard() === this ? player : opponent;
          try {
            const targetOwner = StateUtils.findOwner(state, StateUtils.findCardList(state, card));
            if (targetOwner === lockerOwner) {
              return false;
            }
          } catch {
            return false;
          }
          return LOCKER_ABILITY_APPLIES(store, state, lockerOwner, this, this.powers[0], card);
        },
        {
          exemptPowerNames: ["Freezing Gaze"],
          error: GameMessage.BLOCKED_BY_ABILITY
        }
      );
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const damageEffect = new PutDamageEffect(effect, 30);
            damageEffect.target = targets[0];
            store.reduceEffect(state, damageEffect);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const opponent = StateUtils.getOpponent(state, player);
        effect.damage = 5 * opponent.active.damage;
      }
      return state;
    }
  };

