  function* useStadium6(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let basicEnergyInDiscard = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      const isPokemon = c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.name === "Metal Energy";
      if (isPokemon) {
        basicEnergyInDiscard += 1;
      } else {
        blocked.push(index);
      }
    });
    if (basicEnergyInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let cards = [];
    return store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.discard,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Metal Energy" },
        { min: Math.min(basicEnergyInDiscard, 2), max: 2, allowCancel: false, blocked }
      ),
      (selectedCards) => {
        cards = selectedCards || [];
        if (cards.length === 0) {
          return state;
        }
        cards.forEach((card, index) => {
          MOVE_CARDS(store, state, player.discard, player.hand, {
            cards: [card],
            sourceCard: effect.stadium
          });
        });
        if (cards.length > 0) {
          store.prompt(
            state,
            new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
            () => next()
          );
        }
        return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
          player.deck.applyOrder(order);
          return state;
        });
      }
    );
  }
  var MtCoronet = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.cardImage = "assets/cardback.png";
      this.setNumber = "130";
      this._trainerType = 2 /* STADIUM */;
      this.set = "UPR";
      this.name = "Mt. Coronet";
      this.fullName = "Mt. Coronet UPR";
      this.text = "Once during each player's turn, that player may put 2 [M] Energy cards from their discard pile into their hand.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const discardEffect = new DiscardToHandEffect(player, this);
        store.reduceEffect(state, discardEffect);
        if (discardEffect.preventDefault) {
          MOVE_CARDS(store, state, player.supporter, player.discard, {
            cards: [effect.stadium],
            sourceCard: this
          });
          return state;
        }
        const generator = useStadium6(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

