  var UmbreonGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Eevee";
      this.cardType = [D];
      this.hp = 200;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Strafe",
          cost: [D],
          damage: 30,
          text: "You may switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Shadow Bullet",
          cost: [D, C, C],
          damage: 90,
          text: "This attack does 30 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Dark Call-GX",
          cost: [D, C],
          damage: 0,
          text: "Discard 2 Energy from your opponent's Pok\xE9mon. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "SUM";
      this.setNumber = "80";
      this.cardImage = "assets/cardback.png";
      this.name = "Umbreon-GX";
      this.fullName = "Umbreon-GX SUM";
      this.usedStrafe = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedStrafe = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedStrafe) {
        this.usedStrafe = false;
        const player = effect.player;
        if (player.bench.some((b) => b.cards.length > 0)) {
          store.prompt(
            state,
            new ConfirmPrompt(player.id, GameMessage.WANT_TO_SWITCH_POKEMON),
            (wantToSwitch) => {
              if (wantToSwitch) {
                SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
              }
            }
          );
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedStrafe = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_BENCHED_POKEMON(30, effect, store, state);
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        let totalEnergy = 0;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          totalEnergy += cardList.cards.filter((c) => c instanceof EnergyCard).length;
        });
        if (totalEnergy === 0) {
          return state;
        }
        const maxDiscard = Math.min(2, totalEnergy);
        return store.prompt(
          state,
          new DiscardEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: maxDiscard, max: maxDiscard }
          ),
          (transfers) => {
            if (transfers === null || transfers.length === 0) {
              return state;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, opponent, transfer.from);
              const discardEffect = new DiscardCardsEffect(effect, [transfer.card]);
              discardEffect.target = target;
              store.reduceEffect(state, discardEffect);
            }
          }
        );
      }
      return state;
    }
  };

