  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unbroken-bonds/giovannis-exile.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_prefabs();
  var GiovannisExile = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "UNB";
      this.setNumber = "174";
      this.cardImage = "assets/cardback.png";
      this.name = "Giovanni's Exile";
      this.fullName = "Giovanni's Exile UNB";
      this.text = "Discard up to 2 of your Benched Pok\xE9mon that have no damage counters on them and all cards attached to them. You may play only 1 Supporter card during your turn (before your attack).";
    }
    // Ref: set-lost-thunder/cofagrigus.ts (Spirit Juggling - discard benched Pokemon pattern)
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const undamagedBench = player.bench.filter((b) => b.cards.length > 0 && b.damage === 0);
        if (undamagedBench.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked = [];
        player.bench.forEach((b, index) => {
          if (b.cards.length === 0 || b.damage > 0) {
            blocked.push({ player: 2 /* BOTTOM_PLAYER */, slot: 2 /* BENCH */, index });
          }
        });
        store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 2, allowCancel: false, blocked }
          ),
          (selected) => {
            if (selected && selected.length > 0) {
              selected.forEach((target) => {
                MOVE_POKEMON_OFF_BOARD(store, state, target, {
                  pokemonDestination: player.discard,
                  sourceCard: this
                });
              });
            }
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unbroken-bonds/kogas-trap.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_trainer_prefabs();
  init_prefabs();
  init_game_phase_effects();
  var KogasTrap = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "UNB";
      this.setNumber = "177";
      this.cardImage = "assets/cardback.png";
      this.name = "Koga's Trap";
      this.fullName = "Koga's Trap UNB";
      this.text = "Your opponent's Active Pok\xE9mon is now Confused and Poisoned.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        player.playedKogasTrap = true;
        if (!TRAINER_TARGET_BLOCKED(store, state, player, this, opponent.active)) {
          opponent.active.addSpecialCondition(1 /* CONFUSED */);
          opponent.active.addSpecialCondition(3 /* POISONED */);
        }
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.playedKogasTrap = false;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-team-up/sabrinas-suggestion.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_trainer_prefabs();
  var SabrinasSuggestion = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "TEU";
      this.setNumber = "154";
      this.cardImage = "assets/cardback.png";
      this.name = "Sabrina's Suggestion";
      this.fullName = "Sabrina's Suggestion TEU";
      this.text = "Your opponent reveals their hand. You may choose a Supporter card you find there and use the effect of that card as the effect of this card. You may play only 1 Supporter card during your turn (before your attack).";
    }
    canPlay(store, state, player) {
      const opponent = StateUtils.getOpponent(state, player);
      if (player.supporterTurn > 0) {
        return false;
      }
      if (opponent.hand.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const supporterCards = opponent.hand.cards.filter(
          (c) => c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */
        );
        if (supporterCards.length === 0) {
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_COPY_EFFECT,
            opponent.hand,
            { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
            { min: 0, max: 1, allowCancel: true }
          ),
          (selected) => {
            selected = selected || [];
            if (selected.length === 0) {
              return;
            }
            const trainerCard = selected[0];
            const originalSupporterTurn = player.supporterTurn;
            player.supporterTurn = 0;
            try {
              store.reduceEffect(state, new TrainerEffect(player, trainerCard));
            } finally {
              player.supporterTurn = originalSupporterTurn;
            }
          }
        );
      }
      return state;
    }
  };

