  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-lost-thunder/alolan-ninetales-gx.ts
  init_game();
  init_attack_effects();
  init_attack_effects2();
  init_play_card_effects();
  init_prefabs();
  var AlolanNinetalesGX2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Alolan Vulpix";
      this.cardType = [Y];
      this.hp = 200;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Mysterious Guidance",
          useWhenInPlay: false,
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may search your deck for up to 2 Item cards, reveal them, and put them into your hand. Then, shuffle your deck."
        }
      ];
      this.attacks = [
        {
          name: "Snowy Wind",
          cost: [Y, C],
          damage: 70,
          text: "This attack does 30 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Sublimation-GX",
          cost: [Y, C],
          damage: 0,
          gxAttack: true,
          text: "If your opponent's Active Pok\xE9mon is an Ultra Beast, it is Knocked Out. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "LOT";
      this.name = "Alolan Ninetales-GX";
      this.fullName = "Alolan Ninetales-GX LOT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "132";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              return store.prompt(
                state,
                [
                  new ChooseCardsPrompt(
                    player,
                    GameMessage.CHOOSE_CARD_TO_HAND,
                    player.deck,
                    { superType: 2 /* TRAINER */, trainerType: 0 /* ITEM */ },
                    { min: 0, max: 2, allowCancel: false }
                  )
                ],
                (selected) => {
                  const cards = selected || [];
                  player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
                    if (cardList.getPokemonCard() === this) {
                      cardList.addBoardEffect(0 /* ABILITY_USED */);
                    }
                  });
                  MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this });
                  return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                    player.deck.applyOrder(order);
                  });
                }
              );
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const damageEffect = new PutDamageEffect(effect, 30);
            damageEffect.target = targets[0];
            store.reduceEffect(state, damageEffect);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const activePokemon = opponent.active.getPokemonCard();
        if (activePokemon && activePokemon.hasTag("Ultra Beast" /* ULTRA_BEAST */)) {
          KNOCK_OUT_OPPONENTS_ACTIVE_POKEMON(store, state, effect);
          return state;
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-lost-thunder/alolan-persian.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var AlolanPersian = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Alolan Meowth";
      this.cardType = [D];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Empty Threat",
          cost: [],
          damage: 90,
          damageCalculation: "-",
          text: "This attack does 30 less damage times the amount of Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "LOT";
      this.setNumber = "119";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Persian";
      this.fullName = "Alolan Persian LOT";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        store.reduceEffect(state, checkEnergy);
        const energyCount = checkEnergy.energyMap.reduce((total, p) => total + p.provides.length, 0);
        effect.damage = Math.max(0, effect.damage - 30 * energyCount);
      }
      return state;
    }
  };

