  var AlolanVulpix4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 60;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.powers = [{
        name: "Secret Alleyway",
        powerType: 2 /* ABILITY */,
        text: "If you have any Fairy Pok\xE9mon in play, this Pok\xE9mon has no Retreat Cost."
      }];
      this.attacks = [
        {
          name: "Gnaw",
          cost: [C, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "LOT";
      this.setNumber = "53";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Vulpix";
      this.fullName = "Alolan Vulpix LOT";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect && effect.player.active.getPokemonCard() === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        let hasFairy = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const checkType = new CheckPokemonTypeEffect(cardList);
          store.reduceEffect(state, checkType);
          if (checkType.cardTypes.includes(10 /* FAIRY */)) {
            hasFairy = true;
          }
        });
        if (hasFairy) {
          effect.cost = [];
        }
      }
      return state;
    }
  };

