  init_prefabs();
  var BlacephalonGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */, "Ultra Beast" /* ULTRA_BEAST */];
      this.stage = 2 /* BASIC */;
      this.cardType = [2 /* FIRE */];
      this.hp = 180;
      this.weakness = [{ type: 3 /* WATER */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Bursting Burn",
          cost: [2 /* FIRE */],
          damage: 0,
          text: "Your opponent's Active Pok\xE9mon is now Burned and Confused."
        },
        {
          name: "Mind Blown",
          cost: [2 /* FIRE */, 2 /* FIRE */],
          damage: 50,
          text: "Put any amount of [R] Energy attached to your Pok\xE9mon in the Lost Zone. This attack does 50 damage for each card put in the Lost Zone in this way."
        },
        {
          name: "Burst-GX",
          cost: [2 /* FIRE */],
          damage: 0,
          text: "Discard 1 of your Prize cards. If it's an Energy card, attach it to 1 of your Pok\xE9mon. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "LOT";
      this.name = "Blacephalon-GX";
      this.fullName = "Blacephalon-GX LOT";
      this.regulationMark = "LOT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "52";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const specialCondition = new AddSpecialConditionsEffect(effect, [
          1 /* CONFUSED */,
          4 /* BURNED */
        ]);
        return store.reduceEffect(state, specialCondition);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        let totalFireEnergy = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const fireCount = cardList.cards.filter(
            (card) => card instanceof EnergyCard && card.name === "Fire Energy"
          ).length;
          totalFireEnergy += fireCount;
        });
        return store.prompt(
          state,
          new DiscardEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            // Card source is target Pokemon
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
            { min: 1, max: totalFireEnergy, allowCancel: false }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              let totalDiscarded = 0;
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = player.lostzone;
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
              totalDiscarded = transfers.length;
              effect.damage = totalDiscarded * 50;
            }
            return state;
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        return store.prompt(
          state,
          new ChoosePrizePrompt(player.id, GameMessage.CHOOSE_PRIZE_CARD, {
            count: 1,
            allowCancel: false
          }),
          (prizes) => {
            const holdingZone = new CardList();
            MOVE_CARDS(store, state, prizes[0], holdingZone, { sourceCard: this });
            const discardedEnergy = holdingZone.cards.filter((card) => {
              return card instanceof EnergyCard;
            });
            if (discardedEnergy.length == 0) {
              MOVE_CARDS(store, state, holdingZone, player.discard, { sourceCard: this });
            }
            if (discardedEnergy.length > 0) {
              store.prompt(
                state,
                new AttachEnergyPrompt(
                  player.id,
                  GameMessage.ATTACH_ENERGY_TO_BENCH,
                  holdingZone,
                  2 /* BOTTOM_PLAYER */,
                  [1 /* ACTIVE */, 2 /* BENCH */],
                  { superType: 3 /* ENERGY */ },
                  { allowCancel: false, min: 1, max: 1 }
                ),
                (transfers) => {
                  transfers = transfers || [];
                  for (const transfer of transfers) {
                    const target = StateUtils.getTarget(state, player, transfer.to);
                    MOVE_CARDS(store, state, holdingZone, target, { cards: [transfer.card], sourceCard: this });
                  }
                }
              );
            }
          }
        );
      }
      return state;
    }
  };

