  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-lost-thunder/cascoon.ts
  init_pokemon_card();
  init_card_types();
  init_play_card_effects();
  init_game();
  init_prefabs();
  function* useFlock2(next, store, state, effect) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const max = Math.min(slots2.length, 1);
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (card instanceof PokemonCard && !["Silcoon", "Cascoon"].includes(card.name)) {
        blocked.push(index);
      }
    });
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
      player.deck,
      { superType: 1 /* POKEMON */ },
      { min: 0, max, allowCancel: false, blocked }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      store.reduceEffect(state, new PlayPokemonFromDeckEffect(player, card, slots2[index]));
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
