  var Delibird3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Happy Delivery",
          cost: [C],
          damage: 0,
          text: "Choose any number of your Benched Pok\xE9mon that don't already have a Pok\xE9mon Tool attached to them. For each of those Pok\xE9mon, search your deck for a Pok\xE9mon Tool card and attach it to that Pok\xE9mon. Then, shuffle your deck."
        },
        {
          name: "Flap",
          cost: [C, C],
          damage: 30,
          text: ""
        }
      ];
      this.set = "LOT";
      this.setNumber = "57";
      this.cardImage = "assets/cardback.png";
      this.name = "Delibird";
      this.fullName = "Delibird LOT";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const benchWithoutTools = player.bench.filter(
          (b) => b.cards.length > 0 && b.tools.length === 0
        );
        const hasToolsInDeck = player.deck.cards.some(
          (c) => c instanceof TrainerCard && c.trainerType === 3 /* TOOL */
        );
        if (benchWithoutTools.length === 0 || !hasToolsInDeck) {
          return SHUFFLE_DECK(store, state, player);
        }
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { min: 0, max: benchWithoutTools.length, allowCancel: true }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          const attachNext = (index) => {
            if (index >= selected.length) {
              SHUFFLE_DECK(store, state, player);
              return;
            }
            const target = selected[index];
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_ATTACH,
              player.deck,
              { superType: 2 /* TRAINER */, trainerType: 3 /* TOOL */ },
              { min: 0, max: 1, allowCancel: true }
            ), (cards) => {
              cards = cards || [];
              if (cards.length > 0) {
                const tool = cards[0];
                MOVE_CARD_TO(state, tool, target);
                const idx = target.cards.indexOf(tool);
                if (idx !== -1) {
                  target.cards.splice(idx, 1);
                }
                target.tools.push(tool);
              }
              attachNext(index + 1);
            });
          };
          attachNext(0);
        });
      }
      return state;
    }
  };

