  var Forretress3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Pineco";
      this.cardType = [M];
      this.hp = 110;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Thorny Eruption",
        cost: [M],
        damage: 0,
        text: "Flip 3 coins. This attack does 10 damage for each heads to each of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }, {
        name: "Lost Blast",
        cost: [M, M, C],
        damage: 190,
        text: "Put this Pok\xE9mon and all cards attached to it in the Lost Zone."
      }];
      this.set = "LOT";
      this.setNumber = "124";
      this.cardImage = "assets/cardback.png";
      this.name = "Forretress";
      this.fullName = "Forretress LOT";
      this.usedLostBlast = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          const heads = results.filter((r) => r).length;
          if (heads === 0) {
            return;
          }
          const damageAmount = 10 * heads;
          const dealDamage = new DealDamageEffect(effect, damageAmount);
          dealDamage.target = opponent.active;
          store.reduceEffect(state, dealDamage);
          opponent.bench.forEach((benched) => {
            if (benched.cards.length > 0) {
              const putDamage = new PutDamageEffect(effect, damageAmount);
              putDamage.target = benched;
              store.reduceEffect(state, putDamage);
            }
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedLostBlast = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedLostBlast) {
        this.usedLostBlast = false;
        const player = effect.player;
        const tools = player.active.tools.slice();
        tools.forEach((t) => {
          MOVE_CARDS(store, state, player.active, player.lostzone, { cards: [t], sourceCard: this });
        });
        MOVE_CARDS(store, state, player.active, player.lostzone, { sourceCard: this });
      }
      if (effect instanceof EndTurnEffect) {
        this.usedLostBlast = false;
      }
      return state;
    }
  };

