  var Giratina3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 130;
      this.weakness = [{ type: 7 /* DARK */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -20 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Distortion Door",
        useFromDiscard: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), if this Pok\xE9mon is in your discard pile, you may put it onto your Bench. If you do, put 1 damage counter on 2 of your opponent's Benched Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Shadow Impact",
        cost: [5 /* PSYCHIC */, 5 /* PSYCHIC */, 9 /* COLORLESS */],
        damage: 130,
        text: "Put 4 damage counters on 1 of your Pok\xE9mon. "
      }];
      this.set = "LOT";
      this.setNumber = "97";
      this.cardImage = "assets/cardback.png";
      this.name = "Giratina";
      this.fullName = "Giratina LOT";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (!player.discard.cards.includes(this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (slots2.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        const cards = player.discard.cards.filter((c) => c === this);
        cards.forEach((card) => {
          MOVE_CARDS(store, state, player.discard, slots2[0], { cards: [card], sourceCard: this });
        });
        if (!hasBench) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { min: 1, max: 2, allowCancel: false }
        ), (selected) => {
          const targets = selected || [];
          targets.forEach((target) => {
            const canApplyAbility = new EffectOfAbilityEffect(player, this.powers[0], this, target);
            store.reduceEffect(state, canApplyAbility);
            if (canApplyAbility.target) {
              canApplyAbility.target.damage += 10;
            }
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          const targets = selected || [];
          targets.forEach((target) => {
            const putCountersEffect = new PutCountersEffect(effect, 40);
            putCountersEffect.target = target;
            store.reduceEffect(state, putCountersEffect);
          });
          return state;
        });
      }
      return state;
    }
  };

