  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  function* useBeckon(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const hasSupporter = player.discard.cards.some((c) => {
      return c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */;
    });
    if (!hasSupporter) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_HAND,
      player.discard,
      { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
      { min: 1, max: 1, allowCancel: true }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length > 0) {
      MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: effect.source.getPokemonCard() });
    }
    if (cards.length > 0) {
      yield store.prompt(state, new ShowCardsPrompt(
        opponent.id,
        GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
        cards
      ), () => next());
    }
    return state;
  }
