  init_prefabs();
  function* playCard162(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const name = effect.trainerCard.name;
    const benchCount = opponent.bench.reduce((sum, b) => {
      return sum + (b.cards.length > 0 ? 1 : 0);
    }, 0);
    if (benchCount > 0) {
      const second = player.hand.cards.find((c) => {
        return c.name === name && c !== effect.trainerCard;
      });
      if (second !== void 0) {
        MOVE_CARDS(store, state, player.hand, player.discard, {
          cards: [second],
          sourceCard: effect.trainerCard
        });
      }
      const hasBench = player.bench.some((b) => b.cards.length > 0);
      if (hasBench === false) {
        throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
      }
      effect.preventDefault = true;
      return store.prompt(
        state,
        new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ),
        (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          opponent.active.clearEffects();
          opponent.switchPokemon(targets[0]);
          next();
          effect.preventDefault = true;
          let target = [];
          return store.prompt(
            state,
            new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON_TO_SWITCH,
              2 /* BOTTOM_PLAYER */,
              [2 /* BENCH */],
              { allowCancel: false }
            ),
            (results) => {
              target = results || [];
              next();
              if (target.length === 0) {
                return state;
              }
              player.active.clearEffects();
              player.switchPokemon(target[0]);
              return state;
            }
          );
        }
      );
    }
  }
  var CustomCatcher = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "LOT";
      this.name = "Custom Catcher";
      this.fullName = "Custom Catcher LOT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "171";
      this.text = `You may play 2 Custom Catcher cards at once.

  \u2022 If you played 1 card, draw cards until you have 3 cards in your hand.
  \u2022 If you played 2 cards, switch 1 of your opponent's Benched Pok\xE9mon with their Active Pok\xE9mon. (This effect works one time for 2 cards.)`;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        let drawUpToThree = false;
        const count = player.hand.cards.reduce((sum, c) => {
          return sum + (c.name === this.name ? 1 : 0);
        }, 0);
        if (count > 1) {
          state = store.prompt(
            state,
            new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_PLAY_BOTH_CARDS_AT_ONCE),
            (wantToUse) => {
              if (!wantToUse) {
                drawUpToThree = true;
              } else {
                const generator = playCard162(() => generator.next(), store, state, effect);
                return generator.next().value;
              }
            }
          );
        } else {
          drawUpToThree = true;
        }
        if (drawUpToThree) {
          const cards = player.hand.cards.filter((c) => c !== this);
          const cardsToDraw = Math.max(0, 3 - cards.length);
          if (cardsToDraw === 0 || player.deck.cards.length === 0) {
            throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
          }
          MOVE_CARDS(store, state, player.deck, player.hand, {
            count: cardsToDraw,
            sourceCard: this
          });
          MOVE_CARDS(store, state, player.supporter, player.discard, {
            cards: [this],
            sourceCard: this
          });
          for (let i = 0; i < cardsToDraw; i++) {
            store.log(state, "LOG_PLAYER_DRAWS_CARD" /* LOG_PLAYER_DRAWS_CARD */, { name: player.name });
          }
        }
      }
      return state;
    }
  };

