  var SpellTag = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "LOT";
      this.name = "Spell Tag";
      this.fullName = "Spell Tag LOT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "190";
      this.text = "When the [P] Pok\xE9mon this card is attached to is Knocked Out by damage from an opponent's attack, put 4 damage counters on your opponent's Pok\xE9mon in any way you like.";
      this.damageDealt = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttackEffect && effect.player.active.tools.includes(this)) {
        this.damageDealt = false;
      }
      if ((effect instanceof DealDamageEffect || effect instanceof PutDamageEffect) && effect.target.tools.includes(this)) {
        const player = StateUtils.getOpponent(state, effect.player);
        if (player.active.tools.includes(this)) {
          this.damageDealt = true;
        }
      }
      if (effect instanceof EndTurnEffect && effect.player === StateUtils.getOpponent(state, effect.player)) {
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        if (owner === effect.player) {
          this.damageDealt = false;
        }
      }
      if (effect instanceof KnockOutEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        if (this.damageDealt) {
          const opponent = StateUtils.getOpponent(state, player);
          const maxAllowedDamage = [];
          opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
            maxAllowedDamage.push({ target, damage: card.hp + 40 });
          });
          return store.prompt(
            state,
            new PutDamagePrompt(
              effect.player.id,
              GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
              1 /* TOP_PLAYER */,
              [1 /* ACTIVE */, 2 /* BENCH */],
              40,
              maxAllowedDamage,
              { allowCancel: false }
            ),
            (targets) => {
              const results = targets || [];
              for (const result of results) {
                const target = StateUtils.getTarget(state, player, result.target);
                target.damage += result.damage;
              }
            }
          );
        }
        return state;
      }
      return state;
    }
  };

