  var ThunderMountainPrismStar = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this._tags = ["Prism Star" /* PRISM_STAR */];
      this.set = "LOT";
      this.name = "Thunder Mountain Prism Star";
      this.fullName = "Thunder Mountain Prism Star LOT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "191";
      this.text = "The attacks of [L] Pok\xE9mon (both yours and your opponent's) cost [L] less.\n\nWhenever any player plays an Item or Supporter card from their hand, prevent all effects of that card done to this Stadium card.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect && StateUtils.getStadiumCard(state) === this) {
        const index = effect.cost.indexOf(4 /* LIGHTNING */);
        const checkPokemonType = new CheckPokemonTypeEffect(effect.player.active);
        if (index === -1 || IS_STADIUM_EFFECT_BLOCKED(store, state, effect.player, effect.player.active, this)) {
          return state;
        }
        store.reduceEffect(state, checkPokemonType);
        if (checkPokemonType.cardTypes.includes(4 /* LIGHTNING */)) {
          effect.cost.splice(index, 1);
        }
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      if (effect instanceof MoveCardsEffect && StateUtils.getStadiumCard(state) === this) {
        if (effect.sourceCard instanceof TrainerCard && (effect.sourceCard.trainerType === 1 /* SUPPORTER */ || effect.sourceCard.trainerType === 0 /* ITEM */)) {
          const stadiumCard = StateUtils.getStadiumCard(state);
          if (stadiumCard !== void 0) {
            const cardList = StateUtils.findCardList(state, stadiumCard);
            if (effect.source === cardList) {
              effect.preventDefault = true;
            }
          }
        }
      }
      return state;
    }
  };

