  var MemoryEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [C];
      this.energyType = 1 /* SPECIAL */;
      this.set = "LOT";
      this.setNumber = "194";
      this.cardImage = "assets/cardback.png";
      this.name = "Memory Energy";
      this.fullName = "Memory Energy LOT";
      this.text = "This card provides [C] Energy. The Pok\xE9mon this card is attached to can use any attack from its previous Evolutions. (You still need the necessary Energy to use each attack.)";
    }
    // Ref: set-temporal-forces/relicanth.ts (Memory Dive - CheckPokemonAttacksEffect)
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonAttacksEffect) {
        const player = effect.player;
        const activeCard = player.active.getPokemonCard();
        if (!activeCard || activeCard.stage === 2 /* BASIC */) {
          return state;
        }
        if (!player.active.cards.includes(this)) {
          return state;
        }
        for (const card of player.active.cards) {
          if (card.superType === 1 /* POKEMON */ && card !== activeCard) {
            const pokemonCard = card;
            effect.attacks.push(...pokemonCard.attacks || []);
          }
        }
      }
      return state;
    }
  };

