  var Arbok5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Ekans";
      this.cardType = [P];
      this.hp = 120;
      this.weakness = [{ type: P }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Intimidating Pattern",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is your Active Pok\xE9mon, your opponent's Active Pok\xE9mon's attacks do 30 less damage (before applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Venomous Fang",
          cost: [P, C, C],
          damage: 70,
          text: "Your opponent's Active Pok\xE9mon is now Poisoned."
        }
      ];
      this.set = "SLG";
      this.setNumber = "37";
      this.cardImage = "assets/cardback.png";
      this.name = "Arbok";
      this.fullName = "Arbok SLG";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (player.active !== effect.target) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.damage = Math.max(0, effect.damage - 30);
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_POISON_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

