  var Manaphy4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 60;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.powers = [{
        name: "Blessings of the Deep",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may heal 20 damage from 1 of your Pok\xE9mon that has any [W] Energy attached to it."
      }];
      this.attacks = [
        {
          name: "Wave Splash",
          cost: [W, C],
          damage: 30,
          text: ""
        }
      ];
      this.set = "SLG";
      this.setNumber = "25";
      this.cardImage = "assets/cardback.png";
      this.name = "Manaphy";
      this.fullName = "Manaphy SLG";
      this.BLESSINGS_MARKER = "MANAPHY_BLESSINGS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        let hasTarget = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkEnergy);
          const hasWaterEnergy = StateUtils.checkEnoughEnergy(checkEnergy.energyMap, [3 /* WATER */]);
          if (cardList.damage === 0 || !hasWaterEnergy) {
            blocked.push(target);
          } else {
            hasTarget = true;
          }
        });
        if (!hasTarget) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.BLESSINGS_MARKER, this);
        ABILITY_USED(player, this);
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_HEAL,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false, blocked }
        ), (targets) => {
          if (targets && targets.length > 0) {
            const healEffect = new HealEffect(player, targets[0], 20);
            store.reduceEffect(state, healEffect);
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.BLESSINGS_MARKER, this);
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-shining-legends/marshadow.ts
