  init_prefabs();
  var Marshadow2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 70;
      this.weakness = [{ type: 7 /* DARK */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -20 }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Let Loose",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may have each player shuffle their hand into their deck and draw 4 cards."
      }];
      this.attacks = [{
        name: "Shadow Punch",
        cost: [5 /* PSYCHIC */, 9 /* COLORLESS */],
        damage: 30,
        text: "This attack's damage isn't affected by Resistance."
      }];
      this.set = "SLG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "45";
      this.name = "Marshadow";
      this.fullName = "Marshadow SLG";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            const cards = player.hand.cards.filter((c) => c !== this);
            MOVE_CARDS(store, state, player.hand, player.deck, { cards, sourceCard: this });
            MOVE_CARDS(store, state, opponent.hand, opponent.deck, { sourceCard: this });
            store.prompt(state, [
              new ShuffleDeckPrompt(player.id),
              new ShuffleDeckPrompt(opponent.id)
            ], (deckOrder) => {
              player.deck.applyOrder(deckOrder[0]);
              opponent.deck.applyOrder(deckOrder[1]);
              MOVE_CARDS(store, state, player.deck, player.hand, { count: 4, sourceCard: this });
              MOVE_CARDS(store, state, opponent.deck, opponent.hand, { count: 4, sourceCard: this });
            });
          }
          return state;
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.ignoreResistance = true;
      }
      return state;
    }
  };

