  init_attack_effects();
  init_prefabs();
  var ShiningArceus = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 130;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Fabled Defense",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is your Active Pok\xE9mon, prevent all damage done to your Benched Pok\xE9mon by your opponent's attacks."
      }];
      this.attacks = [
        {
          name: "Ultimate Arrow",
          cost: [C, C, C, C],
          damage: 0,
          text: "This attack does 30 damage to each of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "SLG";
      this.setNumber = "57";
      this.cardImage = "assets/cardback.png";
      this.name = "Shining Arceus";
      this.fullName = "Shining Arceus SLG";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect) {
        const defendingPlayer = StateUtils.findOwner(state, effect.target);
        const attackingPlayer = StateUtils.findOwner(state, effect.source);
        if (attackingPlayer === defendingPlayer) {
          return state;
        }
        if (effect.target === defendingPlayer.active) {
          return state;
        }
        if (defendingPlayer.active.getPokemonCard() !== this) {
          return state;
        }
        if (!defendingPlayer.active.cards.includes(this)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, defendingPlayer, this)) {
          return state;
        }
        effect.preventDefault = true;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const damageActive = new DealDamageEffect(effect, 30);
        damageActive.target = opponent.active;
        store.reduceEffect(state, damageActive);
        opponent.bench.forEach((benched) => {
          if (benched.cards.length > 0) {
            const damage = new PutDamageEffect(effect, 30);
            damage.target = benched;
            store.reduceEffect(state, damage);
          }
        });
      }
      return state;
    }
  };

