  var ShiningGenesect = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [1 /* GRASS */];
      this.hp = 130;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Energy Reload",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may move a [G] Energy from 1 of your other Pok\xE9mon to this Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Gaia Blaster",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 50,
          text: "This attack does 20 more damage times the amount of [G] Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "SLG";
      this.name = "Shining Genesect";
      this.fullName = "Shining Genesect SLG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "9";
      this.ENERGY_RELOAD_MARKER = "ENERGY_RELOAD_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.ENERGY_RELOAD_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.ENERGY_RELOAD_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        let pokemonCount = 0;
        let otherPokemonWithEnergy = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card !== this) {
            pokemonCount += 1;
            const hasAttachedEnergy = cardList.cards.some((c) => c.superType === 3 /* ENERGY */ && (c.provides.includes(1 /* GRASS */) || c.provides.includes(0 /* ANY */)));
            otherPokemonWithEnergy = otherPokemonWithEnergy || hasAttachedEnergy;
          }
        });
        if (pokemonCount <= 1 && !otherPokemonWithEnergy) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          const blockedCards = [];
          checkProvidedEnergy.energyMap.forEach((em) => {
            if (!em.provides.includes(1 /* GRASS */) && !em.provides.includes(0 /* ANY */)) {
              blockedCards.push(em.card);
            }
          });
          const blocked = [];
          blockedCards.forEach((bc) => {
            const index = cardList.cards.indexOf(bc);
            if (index !== -1 && !blocked.includes(index)) {
              blocked.push(index);
            }
          });
          if (blocked.length !== 0) {
            blockedMap.push({ source: target, blocked });
          }
        });
        const blockedFrom = [];
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.getPokemonCard() !== this) {
            blockedTo.push(target);
          } else {
            blockedFrom.push(target);
          }
        });
        return store.prompt(state, new MoveEnergyPrompt(
          effect.player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { min: 1, max: 1, allowCancel: false, blockedMap, blockedFrom, blockedTo }
        ), (transfers) => {
          if (transfers === null) {
            return;
          }
          player.marker.addMarker(this.ENERGY_RELOAD_MARKER, this);
          for (const transfer of transfers) {
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.addBoardEffect(0 /* ABILITY_USED */);
              }
            });
            const source = StateUtils.getTarget(state, player, transfer.from);
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
          }
          return state;
        });
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.ENERGY_RELOAD_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkEnergy);
        const totalGrassEnergy = checkEnergy.energyMap.reduce((sum, energy2) => {
          return sum + energy2.provides.filter((type) => type === 1 /* GRASS */ || type === 0 /* ANY */).length;
        }, 0);
        effect.damage += totalGrassEnergy * 20;
      }
      return state;
    }
  };

