  var ShiningJirachi = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.usedStellarReign = false;
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 70;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Stellar Reign",
          cost: [P],
          damage: 10,
          text: "If your opponent\u2019s Active Pok\xE9mon is an evolved Pok\xE9mon, devolve it by putting all of the Evolution cards on it into your opponent\u2019s hand."
        }
      ];
      this.set = "SLG";
      this.setNumber = "42";
      this.cardImage = "assets/cardback.png";
      this.name = "Shining Jirachi";
      this.fullName = "Shining Jirachi SLG";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedStellarReign = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedStellarReign) {
        this.usedStellarReign = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const pokemons = opponent.active.getPokemons();
        if (pokemons.length > 1) {
          while (opponent.active.getPokemons().length > 1) {
            const currentPokemons = opponent.active.getPokemons();
            DEVOLVE_POKEMON(store, state, opponent.active, opponent.hand);
            const newPokemons = opponent.active.getPokemons();
            if (newPokemons.length >= currentPokemons.length) {
              break;
            }
          }
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedStellarReign = false;
      }
      return state;
    }
  };

