  var DamageMover = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "SLG";
      this.setNumber = "58";
      this.cardImage = "assets/cardback.png";
      this.name = "Damage Mover";
      this.fullName = "Damage Mover SLG";
      this.text = "Move 3 damage counters from 1 of your Pok\xE9mon to another of your Pok\xE9mon.";
    }
    canPlay(store, state, player) {
      let totalPokemon = 0;
      let hasPokemonWith30Damage = false;
      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
        totalPokemon++;
        if (cardList.damage >= 30) {
          hasPokemonWith30Damage = true;
        }
      });
      return totalPokemon >= 2 && hasPokemonWith30Damage;
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        if (!this.canPlay(store, state, player)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blockedFrom = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.damage < 30) {
            blockedFrom.push(target);
          }
        });
        return MOVE_DAMAGE_COUNTERS(store, state, player, {
          playerType: 2 /* BOTTOM_PLAYER */,
          slots: [1 /* ACTIVE */, 2 /* BENCH */],
          min: 1,
          max: 1,
          allowCancel: false,
          blockedFrom,
          singleSourceTarget: true,
          singleDestinationTarget: true,
          damageMultiple: 30
        });
      }
      return state;
    }
  };

