  var AlolanDiglett2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [M];
      this.hp = 50;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Spelunk",
          cost: [],
          damage: 0,
          text: "Look at the top 3 cards of your deck and put them back in any order."
        },
        {
          name: "Mud-Slap",
          cost: [M],
          damage: 10,
          text: ""
        }
      ];
      this.set = "SUM";
      this.setNumber = "86";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Diglett";
      this.fullName = "Alolan Diglett SUM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: Math.min(3, player.deck.cards.length), sourceCard: this });
        return store.prompt(state, new OrderCardsPrompt(
          player.id,
          GameMessage.CHOOSE_CARDS_ORDER,
          deckTop,
          { allowCancel: false }
        ), (order) => {
          if (order === null) {
            return state;
          }
          deckTop.applyOrder(order);
          deckTop.moveToTopOfDestination(player.deck);
        });
      }
      return state;
    }
  };

