  var AlolanDugtrio2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Alolan Diglett";
      this.cardType = [M];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Tangling Hair",
        powerType: 2 /* ABILITY */,
        text: "Your opponent's Active Pok\xE9mon's Retreat Cost is Colorless more."
      }];
      this.attacks = [
        {
          name: "Dig Under",
          cost: [C, C, C],
          damage: 0,
          text: "This attack does 50 damage to 1 of your opponent's Pok\xE9mon. This damage isn't affected by Weakness or Resistance."
        }
      ];
      this.set = "SUM";
      this.setNumber = "87";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Dugtrio";
      this.fullName = "Alolan Dugtrio SUM";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!StateUtils.isPokemonInPlay(opponent, this)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, opponent, this)) {
          return state;
        }
        effect.cost.push(9 /* COLORLESS */);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          const target = selected[0];
          const damage = new PutDamageEffect(effect, 50);
          damage.target = target;
          store.reduceEffect(state, damage);
        });
      }
      return state;
    }
  };

