  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-sun-and-moon/alolan-muk.ts
  init_game();
  init_card_types();
  init_pokemon_card();
  init_pokemon_types();
  init_attack_effects();
  init_state_utils();
  init_ability_lock();
  init_prefabs();
  init_game_message();
  init_pokemon_card_list();
  var AlolanMuk2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Alolan Grimer";
      this.cardType = [P];
      this.hp = 120;
      this.weakness = [{ type: P }];
      this.retreat = [C, C, C, C];
      this.powers = [{
        name: "Power of Alchemy",
        powerType: 2 /* ABILITY */,
        text: "Each Basic Pok\xE9mon in play, in each player's hand, and in each player's discard pile has no Abilities."
      }];
      this.attacks = [{
        name: "Crunch",
        cost: [P, P, C, C],
        damage: 90,
        text: "Flip a coin. If heads, discard an Energy from your opponent's Active Pok\xE9mon."
      }];
      this.set = "SUM";
      this.name = "Alolan Muk";
      this.fullName = "Alolan Muk SUM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "58";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!opponent.active.cards.some((c) => c.superType === 3 /* ENERGY */)) {
          return state;
        }
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === true) {
            let card;
            return store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              opponent.active,
              { superType: 3 /* ENERGY */ },
              { min: 1, max: 1, allowCancel: false }
            ), (selected) => {
              card = selected[0];
              return store.reduceEffect(state, new DiscardCardsEffect(effect, [card]));
            });
          }
        });
      }
      HANDLE_ABILITY_LOCK(effect, ({ player, card, powerEffect }) => {
        if (!IS_ABILITY_LOCKER_IN_PLAY(state, player, this)) {
          return false;
        }
        try {
          const cardList = StateUtils.findCardList(state, card);
          if (cardList instanceof PokemonCardList) {
            if (!cardList.isStage(2 /* BASIC */)) {
              return false;
            }
          } else if (card.stage !== 2 /* BASIC */) {
            return false;
          }
        } catch {
          if (card.stage !== 2 /* BASIC */) {
            return false;
          }
        }
        const opponent = StateUtils.getOpponent(state, player);
        let playerHasAlolanMukInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (_cardList, pokemon) => {
          if (pokemon === this) {
            playerHasAlolanMukInPlay = true;
          }
        });
        const lockerOwner = playerHasAlolanMukInPlay ? player : opponent;
        if (!CAN_APPLY_LOCKER_ABILITY(store, state, lockerOwner, this, this.powers[0])) {
          return false;
        }
        if (powerEffect) {
          return CAN_APPLY_LOCK_TO_TARGET(store, state, lockerOwner, this, this.powers[0], card);
        }
        return true;
      }, {
        exemptPowerNames: ["Power of Alchemy"],
        error: GameMessage.BLOCKED_BY_ABILITY
      });
      return state;
    }
  };

