  init_play_card_effects();
  init_choose_cards_prompt();
  init_prefabs();
  function* playCard165(next, store, state, effect) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const openSlots = player.bench.filter((b) => b.cards.length === 0);
    if (openSlots.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
        player.deck,
        { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
        { min: 0, max: 1, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      SHUFFLE_DECK(store, state, player);
      return state;
    }
    cards.forEach((card, index) => {
      const playPokemonFromDeckEffect = new PlayPokemonFromDeckEffect(
        player,
        card,
        slots2[index]
      );
      store.reduceEffect(state, playPokemonFromDeckEffect);
    });
    SHUFFLE_DECK(store, state, player);
    return state;
  }
  var NestBall = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this._trainerType = 0 /* ITEM */;
      this.set = "SVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "181";
      this.name = "Nest Ball";
      this.fullName = "Nest Ball SVI";
      this.text = "Search your deck for a Basic Pok\xE9mon and put it onto your Bench. Then, shuffle your deck.";
    }
    canPlay(store, state, player) {
      if (player.deck.cards.length === 0) {
        return false;
      }
      const openSlots = player.bench.filter((b) => b.cards.length === 0);
      if (openSlots.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard165(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

