  var Fomantis = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [1 /* GRASS */];
      this.hp = 60;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Synthesis",
          cost: [9 /* COLORLESS */],
          damage: 0,
          text: "Search your deck for a [G] Energy card and attach it to 1 of your Pok\xE9mon. Then, shuffle your deck. "
        },
        {
          name: "Leafage",
          cost: [1 /* GRASS */, 9 /* COLORLESS */],
          damage: 20,
          text: ""
        }
      ];
      this.set = "SUM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "14";
      this.name = "Fomantis";
      this.fullName = "Fomantis SUM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.deck,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Grass Energy" },
          { allowCancel: true, min: 0, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            SHUFFLE_DECK(store, state, player);
            return state;
          }
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
          }
          state = store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      return state;
    }
  };

