  var GumshoosGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Yungoos";
      this.cardType = [C];
      this.hp = 210;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Search the Premises",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn (before your attack), you may have your opponent reveal their hand."
        }
      ];
      this.attacks = [
        {
          name: "Headbutt Bounce",
          cost: [C, C, C],
          damage: 100,
          text: ""
        },
        {
          name: "Gumshoe Chance-GX",
          cost: [C],
          damage: 10,
          damageCalculation: "+",
          text: "This attack does 50 damage times the amount of Energy attached to your opponent's Active Pok\xE9mon. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "SUM";
      this.setNumber = "110";
      this.cardImage = "assets/cardback.png";
      this.name = "Gumshoos-GX";
      this.fullName = "Gumshoos-GX SUM";
      this.SEARCH_PREMISES_MARKER = "SEARCH_PREMISES_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.SEARCH_PREMISES_MARKER, this);
        ABILITY_USED(player, this);
        const opponentHand = opponent.hand.cards;
        if (opponentHand.length > 0) {
          store.prompt(
            state,
            new ShowCardsPrompt(player.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, opponentHand),
            () => {
            }
          );
        }
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.SEARCH_PREMISES_MARKER, this);
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const opponentEnergy = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, opponentEnergy);
        const energyCount = opponentEnergy.energyMap.reduce((sum, em) => sum + em.provides.length, 0);
        effect.damage += 50 * energyCount;
      }
      return state;
    }
  };

