  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-sun-and-moon/lunala-gx.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_attack_effects2();
  init_prefabs();
  function* usePsychicTransfer(next, store, state, effect) {
    const player = effect.player;
    const blockedMap = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
      store.reduceEffect(state, checkProvidedEnergy);
      const blockedCards = [];
      checkProvidedEnergy.energyMap.forEach((em) => {
        if (!em.provides.includes(5 /* PSYCHIC */) && !em.provides.includes(0 /* ANY */)) {
          blockedCards.push(em.card);
        }
      });
      const blocked = [];
      blockedCards.forEach((bc) => {
        const index = cardList.cards.indexOf(bc);
        if (index !== -1 && !blocked.includes(index)) {
          blocked.push(index);
        }
      });
      if (blocked.length !== 0) {
        blockedMap.push({ source: target, blocked });
      }
    });
    return store.prompt(
      state,
      new MoveEnergyPrompt(
        effect.player.id,
        GameMessage.MOVE_ENERGY_CARDS,
        2 /* BOTTOM_PLAYER */,
        [2 /* BENCH */, 1 /* ACTIVE */],
        { superType: 3 /* ENERGY */ },
        { allowCancel: true, blockedMap }
      ),
      (transfers) => {
        if (transfers === null) {
          return;
        }
        for (const transfer of transfers) {
          const source = StateUtils.getTarget(state, player, transfer.from);
          const target = StateUtils.getTarget(state, player, transfer.to);
          MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: effect.card });
        }
      }
    );
  }
  var LunalaGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Cosmoem";
      this.cardType = [P];
      this.hp = 250;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Psychic Transfer",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "As often as you like during your turn (before your attack), you may move a [P] Energy from 1 of your Pok\xE9mon to another of your Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Moongeist Beam",
          cost: [P, P, P, P],
          damage: 120,
          text: "The Defending Pok\xE9mon can't be healed during your opponent's next turn."
        },
        {
          name: "Lunar Fall-GX",
          cost: [P, P, P],
          damage: 0,
          text: "Knock Out 1 of your opponent's Basic Pok\xE9mon that isn't a Pok\xE9mon-GX. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "SUM";
      this.setNumber = "66";
      this.cardImage = "assets/cardback.png";
      this.name = "Lunala-GX";
      this.fullName = "Lunala-GX SUM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const generator = usePsychicTransfer(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return BLOCK_HEALING_ON_DEFENDING_POKEMON_DURING_OPPONENTS_NEXT_TURN(store, state, effect, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const blocked = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, pokemonCard, target) => {
          if (pokemonCard.stage !== 2 /* BASIC */ || pokemonCard.hasTag("GX" /* POKEMON_GX */)) {
            blocked.push(target);
          }
        });
        const hasValidTarget = opponent.getPokemonInPlay().some((cardList) => {
          const pokemon = cardList.getPokemonCard();
          return pokemon && pokemon.stage === 2 /* BASIC */ && !pokemon.hasTag("GX" /* POKEMON_GX */);
        });
        if (!hasValidTarget) {
          return state;
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (selected) => {
            KNOCK_OUT_OPPONENTS_ACTIVE_POKEMON(store, state, effect, selected[0]);
          }
        );
      }
      return state;
    }
  };

