      this.weakness = [{ type: R }];
      this.retreat = [C, C, C];
      this.attacks = [{
        name: "Fury Cutter",
        cost: [C, C],
        damage: 10,
        damageCalculation: "+",
        text: "Flip 3 coins. If 1 of them is heads, this attack does 20 more damage. If 2 of them are heads, this attack does 60 more damage. If all of them are heads, this attack does 120 damage."
      }, {
        name: "Mushroom Drain",
        cost: [G, G, C],
        damage: 70,
        text: "Heal 30 damage from this Pok\xE9mon."
      }];
      this.set = "SUM";
      this.setNumber = "5";
