  var Pinsir5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 110;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Roof Fling",
        cost: [C, C],
        damage: 0,
        text: "Flip a coin. If heads, put your opponent's Active Pok\xE9mon and all cards attached to it into your opponent's hand."
      }, {
        name: "Guillotine",
        cost: [G, G],
        damage: 50,
        text: ""
      }];
      this.set = "SUM";
      this.setNumber = "6";
      this.cardImage = "assets/cardback.png";
      this.name = "Pinsir";
      this.fullName = "Pinsir SUM";
      this.usedRoofFling = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            this.usedRoofFling = true;
          }
        });
      }
      if (effect instanceof AfterAttackEffect && this.usedRoofFling) {
        this.usedRoofFling = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const active = opponent.active;
        const tools = active.tools.slice();
        tools.forEach((tool) => {
          MOVE_CARDS(store, state, active, opponent.hand, { cards: [tool], sourceCard: this });
        });
        const cards = active.cards.slice();
        cards.forEach((card) => {
          MOVE_CARDS(store, state, active, opponent.hand, { cards: [card], sourceCard: this });
        });
        active.clearEffects();
      }
      if (effect instanceof EndTurnEffect) {
        this.usedRoofFling = false;
      }
      return state;
    }
  };

