  var Ribombee3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Cutiefly";
      this.cardType = [Y];
      this.hp = 60;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C];
      this.CURATIVE_POLLEN_MARKER = "RIBOMBEE_CURATIVE_POLLEN_MARKER";
      this.powers = [{
        name: "Curative Pollen",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may heal 20 damage from 1 of your Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Fairy Wind",
          cost: [Y],
          damage: 30,
          text: ""
        }
      ];
      this.set = "SUM";
      this.setNumber = "93";
      this.cardImage = "assets/cardback.png";
      this.name = "Ribombee";
      this.fullName = "Ribombee SUM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const blocked = [];
        let hasPokemonWithDamage = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.damage === 0) {
            blocked.push(target);
          } else {
            hasPokemonWithDamage = true;
          }
        });
        if (!hasPokemonWithDamage) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.CURATIVE_POLLEN_MARKER, this);
        ABILITY_USED(player, this);
        let targets = [];
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_HEAL,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false, blocked }
        ), (results) => {
          targets = results || [];
          if (targets.length === 0) {
            return state;
          }
          targets.forEach((target) => {
            const healEffect = new HealEffect(player, target, 20);
            store.reduceEffect(state, healEffect);
          });
          return state;
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.CURATIVE_POLLEN_MARKER, this);
      return state;
    }
  };

