  var BigMalasada = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "SUM";
      this.setNumber = "114";
      this.cardImage = "assets/cardback.png";
      this.name = "Big Malasada";
      this.fullName = "Big Malasada SUM";
      this.text = "Heal 20 damage and remove a Special Condition from your Active Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const healEffect = new HealEffect(player, player.active, 20);
        store.reduceEffect(state, healEffect);
        const specialConditions = player.active.specialConditions;
        if (specialConditions.length === 1) {
          player.active.specialConditions = [];
        } else if (specialConditions.length > 1) {
          const options = specialConditions.map((sc) => SpecialCondition[sc]);
          store.prompt(
            state,
            new SelectPrompt(player.id, GameMessage.CHOOSE_SPECIAL_CONDITION, options, {
              allowCancel: false
            }),
            (choice) => {
              if (choice !== null && choice >= 0 && choice < specialConditions.length) {
                specialConditions.splice(choice, 1);
              }
            }
          );
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-sun-and-moon/ilima.ts
