  var Ilima = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "SUM";
      this.setNumber = "121";
      this.cardImage = "assets/cardback.png";
      this.name = "Ilima";
      this.fullName = "Ilima SUM";
      this.text = "Each player shuffles their hand into their deck and flips a coin. If heads, that player draws 6 cards. If tails, they draw 3 cards. You may play only 1 Supporter card during your turn (before your attack).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const playerCards = player.hand.cards.filter((c) => c !== this);
        MOVE_CARDS(store, state, player.hand, player.deck, { cards: playerCards, sourceCard: this });
        store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
          player.deck.applyOrder(order);
        });
        COIN_FLIP_PROMPT(store, state, player, (playerResult) => {
          const playerDraw = playerResult ? 6 : 3;
          DRAW_CARDS(store, state, player, Math.min(playerDraw, player.deck.cards.length));
        });
        const opponentCards = opponent.hand.cards.slice();
        MOVE_CARDS(store, state, opponent.hand, opponent.deck, {
          cards: opponentCards,
          sourceCard: this
        });
        store.prompt(state, new ShuffleDeckPrompt(opponent.id), (order) => {
          opponent.deck.applyOrder(order);
        });
        COIN_FLIP_PROMPT(store, state, opponent, (opponentResult) => {
          const opponentDraw = opponentResult ? 6 : 3;
          DRAW_CARDS(store, state, opponent, Math.min(opponentDraw, opponent.deck.cards.length));
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-sun-and-moon/poison-barb.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_play_card_effects();
  init_check_effects();
  var PoisonBarb = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "SUM";
      this.setNumber = "124";
      this.cardImage = "assets/cardback.png";
      this.name = "Poison Barb";
      this.fullName = "Poison Barb SUM";
      this.text = "If the Pok\xE9mon this card is attached to is your Active Pok\xE9mon and is damaged by an opponent's attack (even if this Pok\xE9mon is Knocked Out), the Attacking Pok\xE9mon is now Poisoned.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (effect.damage <= 0 || player === targetPlayer || targetPlayer.active !== effect.target) {
          return state;
        }
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        if (state.phase === 3 /* ATTACK */) {
          const poisonEffect = new AddSpecialConditionsPowerEffect(player, this, effect.source, [
            3 /* POISONED */
          ]);
          store.reduceEffect(state, poisonEffect);
        }
      }
      return state;
    }
  };

