  var ProfessorKukui = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "SUM";
      this.name = "Professor Kukui";
      this.fullName = "Professor Kukui SUM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "128";
      this.text = "Draw 2 cards. During this turn, your Pok\xE9mon's attacks do 20 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance).";
      this.PROFESSOR_KUKUI_MARKER = "PROFESSOR_KUKUI_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.NO_CARDS_IN_DECK);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.deck, player.hand, { count: 2, sourceCard: this });
        player.marker.addMarker(this.PROFESSOR_KUKUI_MARKER, this);
        return state;
      }
      if (effect instanceof DealDamageEffect) {
        const marker = effect.player.marker;
        if (marker.hasMarker(this.PROFESSOR_KUKUI_MARKER, this) && effect.damage > 0) {
          effect.damage += 20;
        }
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.PROFESSOR_KUKUI_MARKER, this);
        return state;
      }
      return state;
    }
  };

