  var TeamSkullGrunt = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "SUM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "133";
      this.name = "Team Skull Grunt";
      this.fullName = "Team Skull Grunt SUM";
      this.text = "Your opponent reveals their hand. Discard 2 Energy cards from it.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        if (opponent.hand.cards.length == 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.hand,
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 0, max: 2 }
          ),
          (selectedCard) => {
            const selected = selectedCard || [];
            if (selectedCard === null || selected.length === 0) {
              return;
            }
            MOVE_CARDS(store, state, opponent.hand, opponent.discard, {
              cards: selected,
              sourceCard: this
            });
            MOVE_CARDS(store, state, player.supporter, player.discard, {
              cards: [this],
              sourceCard: this
            });
          }
        );
      }
      return state;
    }
  };

