  var TimerBall = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "SUM";
      this.name = "Timer Ball";
      this.fullName = "Timer Ball SUM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "134";
      this.text = "Flip 2 coins. For each heads, search your deck for an Evolution Pok\xE9mon, reveal it, and put it into your hand. Then, shuffle your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const opponent = StateUtils.getOpponent(state, player);
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        let heads = 0;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          results.forEach((r) => {
            heads += r ? 1 : 0;
          });
          if (heads === 0) {
            return state;
          }
          let cards = [];
          const blocked = [];
          player.deck.cards.forEach((card, index) => {
            if (card instanceof PokemonCard && card.evolvesFrom !== "" && card.stage !== 11 /* LV_X */) {
            } else {
              blocked.push(index);
            }
          });
          store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_HAND,
              player.deck,
              { superType: 1 /* POKEMON */ },
              { min: 0, max: heads, allowCancel: false, blocked }
            ),
            (selected) => {
              cards = selected || [];
              if (cards.length > 0) {
                MOVE_CARDS(store, state, player.deck, player.hand, {
                  cards,
                  sourceCard: this
                });
                return store.prompt(
                  state,
                  new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
                  () => {
                    return state;
                  }
                );
              }
              return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                player.deck.applyOrder(order);
              });
            }
          );
        });
      }
      return state;
    }
  };

