  var TapuKoko2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 110;
      this.retreat = [];
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.resistance = [{ type: 8 /* METAL */, value: -20 }];
      this.attacks = [
        {
          name: "Flying Flip",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 0,
          text: "This attack does 20 damage to each of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Electric Ball",
          cost: [4 /* LIGHTNING */, 4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 100,
          text: ""
        }
      ];
      this.set = "SMP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "30";
      this.name = "Tapu Koko";
      this.fullName = "Tapu Koko SMP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        const benched = opponent.bench.filter((b) => b.cards.length > 0);
        effect.damage = 20;
        benched.forEach((target) => {
          const damageEffect = new PutDamageEffect(effect, 20);
          damageEffect.target = target;
          store.reduceEffect(state, damageEffect);
        });
        return state;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-ultra-prism/dawn-wings-necrozma-gx.ts
  init_game();
