  init_play_card_effects();
  init_prefabs();
  var DawnWingsNecrozmaGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */, "Ultra Beast" /* ULTRA_BEAST */];
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 180;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Invasion",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn (before your attack), if this Pok\xE9mon is on your Bench, you may switch it with your Active Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Dark Flash",
          cost: [P, P, P],
          damage: 120,
          text: "This attack's damage isn't affected by Resistance."
        },
        {
          name: "Moon's Eclipse-GX",
          cost: [P, P, P],
          damage: 180,
          text: "You can use this attack only if you have more Prize cards remaining than your opponent. Prevent all effects of attacks, including damage, done to this Pok\xE9mon during your opponent's next turn. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "UPR";
      this.setNumber = "63";
      this.cardImage = "assets/cardback.png";
      this.name = "Dawn Wings Necrozma-GX";
      this.fullName = "Dawn Wings Necrozma-GX UPR";
      this.INVASION_MARKER = "INVASION_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        effect.player.marker.removeMarker(this.INVASION_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        let bench;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card === this && target.slot === 2 /* BENCH */) {
            bench = cardList;
          }
        });
        if (bench === void 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.INVASION_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.marker.addMarker(this.INVASION_MARKER, this);
        player.switchPokemon(bench);
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.ignoreResistance = true;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.getPrizeLeft() <= opponent.getPrizeLeft()) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        PREVENT_DAMAGE(store, state, effect, this);
        PREVENT_EFFECTS_OF_ATTACKS(store, state, effect, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.INVASION_MARKER, this)) {
        effect.player.marker.removeMarker(this.INVASION_MARKER, this);
      }
      return state;
    }
  };

