  var DuskManeNecrozmaGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */, "Ultra Beast" /* ULTRA_BEAST */];
      this.stage = 2 /* BASIC */;
      this.cardType = [8 /* METAL */];
      this.hp = 190;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.resistance = [{ type: 5 /* PSYCHIC */, value: -20 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Claw Slash",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 60,
          text: ""
        },
        {
          name: "Meteor Tempest",
          cost: [8 /* METAL */, 8 /* METAL */, 8 /* METAL */, 9 /* COLORLESS */],
          damage: 220,
          text: "Discard 3 Energy from this Pok\xE9mon."
        },
        {
          name: "Sun's Eclipse-GX",
          cost: [8 /* METAL */, 8 /* METAL */, 8 /* METAL */],
          damage: 250,
          text: "You can use this attack only if you have more Prize cards remaining than your opponent. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "UPR";
      this.setNumber = "90";
      this.cardImage = "assets/cardback.png";
      this.name = "Dusk Mane Necrozma-GX";
      this.fullName = "Dusk Mane Necrozma-GX UPR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(
          state,
          new ChooseEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            checkProvidedEnergy.energyMap,
            [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
            { allowCancel: false }
          ),
          (energy2) => {
            const cards = (energy2 || []).map((e) => e.card);
            const discardEnergy2 = new DiscardCardsEffect(effect, cards);
            discardEnergy2.target = player.active;
            store.reduceEffect(state, discardEnergy2);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.getPrizeLeft() <= opponent.getPrizeLeft()) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
      }
      return state;
    }
  };

