  var Charizard6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Charmeleon";
      this.cardType = [R];
      this.hp = 150;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Roaring Resolve",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may put 2 damage counters on this Pok\xE9mon. If you do, search your deck for up to 2 [R] Energy cards and attach them to this Pok\xE9mon. Then, shuffle your deck."
      }];
      this.attacks = [
        {
          name: "Continuous Blaze Ball",
          cost: [R, R],
          damage: 30,
          damageCalculation: "+",
          text: "Discard all [R] Energy from this Pok\xE9mon. This attack does 50 more damage for each card you discarded in this way."
        }
      ];
      this.set = "TEU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "14";
      this.name = "Charizard";
      this.fullName = "Charizard TEU";
      this.ROARING_RESEOLVE_MARKER = "ROARING_RESEOLVE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (HAS_MARKER(this.ROARING_RESEOLVE_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.ABILITY_BLOCKED);
        }
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.damage += 20;
          }
        });
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() !== this) {
            blockedTo.push({
              player: 2 /* BOTTOM_PLAYER */,
              slot: cardList === player.active ? 1 /* ACTIVE */ : 2 /* BENCH */,
              index: cardList === player.active ? 0 : player.bench.indexOf(cardList)
            });
          }
        });
        store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.deck,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          {
            min: 0,
            max: 2,
            allowCancel: false,
            blockedTo
          }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
          }
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        let totalDiscarded = 0;
        const cards = checkProvidedEnergy.energyMap.map((e) => e.card);
        const discardEnergy2 = new DiscardCardsEffect(effect, cards);
        discardEnergy2.target = player.active;
        totalDiscarded += discardEnergy2.cards.length;
        store.reduceEffect(state, discardEnergy2);
        effect.damage += totalDiscarded * 50;
      }
      return state;
    }
  };

