  var PikachuZekromGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Tag Team" /* TAG_TEAM */, "GX" /* POKEMON_GX */];
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 240;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.resistance = [{ type: 8 /* METAL */, value: -20 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Full Blitz",
          cost: [4 /* LIGHTNING */, 4 /* LIGHTNING */, 4 /* LIGHTNING */],
          damage: 150,
          text: "Search your deck for up to 3 [L] Energy cards and attach them to 1 of your Pok\xE9mon. Then, shuffle your deck."
        },
        {
          name: "Tag Bolt-GX",
          cost: [4 /* LIGHTNING */, 4 /* LIGHTNING */, 4 /* LIGHTNING */],
          damage: 200,
          gxAttack: true,
          text: " If this Pok\xE9mon has at least 3 extra [L] Energy attached to it (in addition to this attack's cost), this attack does 170 damage to 1 of your opponent's Benched Pok\xE9mon.(Don't apply Weakness and Resistance for Benched Pok\xE9mon.) (You can't use more than 1 GX attack in a game.) "
        }
      ];
      this.set = "SMP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "168";
      this.name = "Pikachu & Zekrom-GX";
      this.fullName = "Pikachu & Zekrom GX SMP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Lightning Energy" },
            { allowCancel: true, min: 0, max: 3, sameTarget: true }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              SHUFFLE_DECK(store, state, player);
              return state;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
            }
            state = store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let energyCount = 0;
        checkProvidedEnergyEffect.energyMap.forEach((em) => {
          energyCount += em.provides.filter(
            (cardType) => cardType === 4 /* LIGHTNING */ || cardType === 0 /* ANY */
          ).length;
        });
        const extraLightningEnergy = energyCount - effect.attack.cost.length;
        if (extraLightningEnergy < 3) {
          return state;
        }
        if (extraLightningEnergy >= 3) {
          state = store.prompt(
            state,
            new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
              1 /* TOP_PLAYER */,
              [2 /* BENCH */],
              { allowCancel: false }
            ),
            (targets) => {
              if (!targets || targets.length === 0) {
                return;
              }
              const damageEffect = new PutDamageEffect(effect, 170);
              damageEffect.target = targets[0];
              store.reduceEffect(state, damageEffect);
            }
          );
          return state;
        }
      }
      return state;
    }
  };

