  var EspeonDeoxysGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */, "Tag Team" /* TAG_TEAM */];
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 260;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Psychic Club",
          cost: [P, C, C],
          damage: 10,
          damageCalculation: "+",
          text: "This attack does 30 more damage for each of your Benched [P] Pok\xE9mon."
        },
        {
          name: "Cross Division-GX",
          cost: [P, C, C],
          damage: 0,
          gxAttack: true,
          text: "Put 10 damage counters on your opponent's Pok\xE9mon in any way you like. If this Pok\xE9mon has at least 3 extra Energy attached to it (in addition to this attack's cost), put 20 damage counters on them instead. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "UNM";
      this.setNumber = "72";
      this.cardImage = "assets/cardback.png";
      this.name = "Espeon & Deoxys-GX";
      this.fullName = "Espeon & Deoxys-GX UNM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let psychics = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (card) => {
          if (pokemonHasCardTypeOptional(card.getPokemonCard(), 5 /* PSYCHIC */)) {
            psychics++;
          }
        });
        effect.damage += psychics * 30;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        let counters = 10;
        const checkCost = new CheckAttackCostEffect(player, this.attacks[1]);
        state = store.reduceEffect(state, checkCost);
        const checkEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkEnergy);
        const totalEnergy = checkEnergy.energyMap.length;
        const attackCost = checkCost.cost.length;
        const extraEnergy = totalEnergy - attackCost;
        if (extraEnergy >= 3) {
          counters = 20;
        }
        PUT_X_DAMAGE_COUNTERS_IN_ANY_WAY_YOU_LIKE(counters, store, state, effect);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/umbreon-and-darkrai-gx.ts
  init_game();
  init_check_effects();
  init_attack_effects();
  init_attack_effects2();
  init_prefabs();
  var UmbreonDarkraiGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */, "Tag Team" /* TAG_TEAM */];
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 270;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Black Lance",
          cost: [D, D, C],
          damage: 150,
          text: "This attack does 60 damage to 1 of your opponent's Benched Pok\xE9mon-GX or Benched Pok\xE9mon-EX. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Dark Moon-GX",
          cost: [C],
          damage: 0,
          gxAttack: true,
          text: "Your opponent can't play any Trainer cards from their hand during their next turn. If this Pok\xE9mon has at least 5 extra [D] Energy attached to it (in addition to this attack's cost), your opponent's Active Pok\xE9mon is Knocked Out. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "UNM";
      this.setNumber = "125";
      this.cardImage = "assets/cardback.png";
      this.name = "Umbreon & Darkrai-GX";
      this.fullName = "Umbreon & Darkrai-GX UNM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        let gxsEXsOnBench = 0;
        const blockedTo = [];
        opponent.bench.forEach((bench, index) => {
          if (bench.cards.length === 0) {
            return;
          }
          if (bench.getPokemonCard()?.hasTag("EX" /* POKEMON_EX */) || bench.getPokemonCard()?.hasTag("GX" /* POKEMON_GX */) || bench.getPokemonCard()?.hasTag("Tag Team" /* TAG_TEAM */)) {
            gxsEXsOnBench++;
          } else {
            const target = {
              player: 2 /* BOTTOM_PLAYER */,
              slot: 2 /* BENCH */,
              index
            };
            blockedTo.push(target);
          }
        });
        if (!gxsEXsOnBench) {
          return state;
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false, blocked: blockedTo }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            for (const target of targets) {
              const damageEffect = new PutDamageEffect(effect, 60);
              damageEffect.target = target;
              store.reduceEffect(state, damageEffect);
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        OPPONENT_CANNOT_PLAY_TRAINER_CARDS(store, state, effect, this);
        const extraEffectCost = [D, D, D, D, D, C];
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergy);
        const meetsExtraEffectCost = StateUtils.checkEnoughEnergy(
          checkProvidedEnergy.energyMap,
          extraEffectCost
        );
        if (meetsExtraEffectCost) {
          const activePokemon = effect.opponent.active.getPokemonCard();
          if (activePokemon) {
            KNOCK_OUT_OPPONENTS_ACTIVE_POKEMON(store, state, effect);
          }
        }
      }
      return state;
    }
  };

