  var CarracostaGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Tirtouga";
      this.cardType = [F];
      this.hp = 250;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C, C];
      this.powers = [
        {
          name: "High Density Armor",
          useWhenInPlay: false,
          powerType: 2 /* ABILITY */,
          text: "If this Pok\xE9mon has full HP, it takes 90 less damage from your opponent's attacks (after applying Weakness and Resistance)."
        }
      ];
      this.attacks = [
        {
          name: "Ground Crush",
          cost: [F, C, C, C],
          damage: 160,
          text: "The Defending Pok\xE9mon can't retreat during your opponent's next turn."
        },
        {
          name: "Stone Age-GX",
          cost: [C],
          damage: 0,
          text: "Put any number of Pok\xE9mon that evolve from Unidentified Fossil from your discard pile onto your Bench. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "SMP";
      this.setNumber = "239";
      this.cardImage = "assets/cardback.png";
      this.name = "Carracosta-GX";
      this.fullName = "Carracosta-GX SMP";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        if (IS_ABILITY_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        if (effect.target.damage === 0) {
          effect.damage -= 80;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return BLOCK_RETREAT(store, state, effect, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        if (player.usedGX) {
          throw new GameError(GameMessage.LABEL_GX_USED);
        }
        player.usedGX = true;
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (player.discard.cards.length === 0) {
          return state;
        }
        const openSlots = player.bench.filter((b) => b.cards.length === 0);
        if (openSlots.length === 0) {
          return state;
        }
        let cards = [];
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            player.discard,
            { evolvesFrom: "Unidentified Fossil" },
            { min: 0, max: openSlots.length, allowCancel: false }
          ),
          (selectedCards) => {
            cards = selectedCards || [];
            cards.forEach((card, index) => {
              MOVE_CARDS(store, state, player.discard, slots2[index], { cards: [card], sourceCard: this });
              slots2[index].pokemonPlayedTurn = state.turn;
            });
          }
        );
      }
      return state;
    }
  };

