      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C];
      this.attacks = [{
        name: "Firefighting",
        cost: [C],
        damage: 0,
        text: "Discard a [R] Energy from your opponent's Active Pok\xE9mon."
      }, {
        name: "Quick Attack",
        cost: [C, C],
        damage: 20,
        damageCalculation: "+",
        text: "Flip a coin. If heads, this attack does 10 more damage."
      }];
      this.set = "SMP";
