  var TsareenaGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Steenee";
      this.cardType = [G];
      this.hp = 230;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "G Side Eye",
          cost: [G],
          damage: 0,
          text: "Switch 1 of your opponent's Benched Pok\xE9mon with their Active Pok\xE9mon. The new Active Pok\xE9mon is now Confused."
        },
        {
          name: "Jumping Side Kick",
          cost: [G, C, C],
          damage: 90,
          damageCalculation: "+",
          text: "If your opponent's Active Pok\xE9mon is Confused, this attack does 90 more damage."
        },
        {
          name: "Queen's Command-GX",
          cost: [G, G, C],
          damage: 0,
          gxAttack: true,
          text: "Your opponent discards 4 cards from their hand. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "SMP";
      this.setNumber = "56";
      this.cardImage = "assets/cardback.png";
      this.name = "Tsareena-GX";
      this.fullName = "Tsareena-GX SMP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        SWITCH_IN_OPPONENT_BENCHED_POKEMON(store, state, player, {
          allowCancel: false,
          onSwitched: () => {
            opponent.active.addSpecialCondition(1 /* CONFUSED */);
          }
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.active.specialConditions.includes(1 /* CONFUSED */)) {
          effect.damage += 90;
        }
        return state;
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const opponent = StateUtils.getOpponent(state, player);
        const n = Math.min(4, opponent.hand.cards.length);
        if (n === 0) {
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            opponent,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.hand,
            {},
            { min: n, max: n, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards, sourceCard: this });
          }
        );
      }
      return state;
    }
  };

