  var Absol7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [7 /* DARK */];
      this.hp = 100;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.resistance = [{ type: 5 /* PSYCHIC */, value: -20 }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Dark Ambition",
        powerType: 2 /* ABILITY */,
        text: "If your opponent's Active Pok\xE9mon is a Basic Pok\xE9mon, its Retreat Cost is [C] more."
      }];
      this.attacks = [{
        name: "Shadow Seeker",
        cost: [7 /* DARK */, 9 /* COLORLESS */, 9 /* COLORLESS */],
        damage: 30,
        text: "This attack does 30 more damage for each [C] in your opponent's Active Pok\xE9mon's Retreat Cost. "
      }];
      this.set = "TEU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "88";
      this.name = "Absol";
      this.fullName = "Absol TEU";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect && StateUtils.isPokemonInPlay(effect.player, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this) || !opponent.active.isStage(2 /* BASIC */)) {
          return state;
        }
        effect.cost.push(9 /* COLORLESS */);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentActiveCard = opponent.active.getPokemonCard();
        if (opponentActiveCard) {
          const retreatCost = opponentActiveCard.retreat.filter((c) => c === 9 /* COLORLESS */).length;
          effect.damage += retreatCost * 30;
          return state;
        }
      }
      return state;
    }
  };

