  var AlolanExeggutor2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Exeggcute";
      this.cardType = [N];
      this.hp = 160;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Paradise Draw",
          cost: [],
          damage: 0,
          text: "You may discard any number of cards from your hand. Then, draw cards until you have 6 cards in your hand."
        },
        {
          name: "Egg Splat",
          cost: [G, C],
          damage: 60,
          damageCalculation: "x",
          text: "Discard any number of Exeggcute from your hand. This attack does 60 damage for each card you discarded in this way."
        }
      ];
      this.set = "TEU";
      this.setNumber = "115";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Exeggutor";
      this.fullName = "Alolan Exeggutor TEU 115";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.hand.cards.length > 0) {
          state = store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            {},
            { min: 0, max: player.hand.cards.length, allowCancel: false }
          ), (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, player.hand, player.discard, { cards });
            }
            DRAW_CARDS_UNTIL_CARDS_IN_HAND(player, 6);
          });
        } else {
          DRAW_CARDS_UNTIL_CARDS_IN_HAND(player, 6);
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const exeggcuteCards = player.hand.cards.filter(
          (c) => c instanceof PokemonCard && c.name === "Exeggcute"
        );
        if (exeggcuteCards.length === 0) {
          effect.damage = 0;
          return state;
        }
        const blocked = [];
        player.hand.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && card.name === "Exeggcute") {
            return;
          }
          blocked.push(index);
        });
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 1 /* POKEMON */ },
          { allowCancel: true, min: 0, max: exeggcuteCards.length, blocked }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            effect.damage = 0;
            return;
          }
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
          effect.damage = 60 * cards.length;
        });
      }
      return state;
    }
  };

