  var CobalionGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["GX" /* POKEMON_GX */];
      this.cardType = [M];
      this.hp = 170;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Metal Symbol",
        powerType: 2 /* ABILITY */,
        text: "Each of your Pok\xE9mon that has any [M] Energy attached to it can't be affected by any Special Conditions. (Remove any Special Conditions affecting those Pok\xE9mon.)"
      }];
      this.attacks = [
        {
          name: "Dueling Saber",
          cost: [M, M],
          damage: 50,
          damageCalculation: "+",
          text: "If there is any Stadium card in play, this attack does 60 more damage."
        },
        {
          name: "Iron Rule-GX",
          cost: [C],
          damage: 0,
          text: "During your opponent's next turn, their Pok\xE9mon can't attack. (This includes Pok\xE9mon that come into play on that turn.) (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "TEU";
      this.setNumber = "106";
      this.cardImage = "assets/cardback.png";
      this.name = "Cobalion-GX";
      this.fullName = "Cobalion-GX TEU";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          if (player.active.specialConditions.length === 0 || IS_ABILITY_BLOCKED(store, state, player, this)) {
            return;
          }
          let hasCobalionInPlay = false;
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
            if (card === this) {
              hasCobalionInPlay = true;
            }
          });
          if (!hasCobalionInPlay) {
            return state;
          }
          const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player);
          store.reduceEffect(state, checkProvidedEnergyEffect);
          const energyMap = checkProvidedEnergyEffect.energyMap;
          const hasMetalEnergy = StateUtils.checkEnoughEnergy(energyMap, [8 /* METAL */]);
          if (hasMetalEnergy) {
            const conditions = player.active.specialConditions.slice();
            conditions.forEach((condition) => {
              player.active.removeSpecialCondition(condition);
            });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        if (StateUtils.getStadiumCard(state) !== void 0) {
          THIS_ATTACK_DOES_X_MORE_DAMAGE(effect, store, state, 60);
        }
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        return OPPONENT_POKEMON_CANNOT_ATTACK_DURING_THEIR_NEXT_TURN(store, state, effect, this);
      }
      return state;
    }
  };

