  var Cosmog4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 50;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Cosmic Guard",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is on your Bench, prevent all damage done to this Pok\xE9mon by attacks (both yours and your opponent's)."
      }];
      this.attacks = [
        {
          name: "Mumble",
          cost: [C],
          damage: 10,
          text: ""
        }
      ];
      this.set = "TEU";
      this.setNumber = "69";
      this.cardImage = "assets/cardback.png";
      this.name = "Cosmog";
      this.fullName = "Cosmog TEU";
    }
    // Ref: set-steam-siege/seedot.ts (damage prevention on bench pattern)
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        const isBenched = player.bench.some((b) => b.getPokemonCard() === this);
        if (!isBenched) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.damage = 0;
      }
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        const isBenched = player.bench.some((b) => b.getPokemonCard() === this);
        if (!isBenched) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.preventDefault = true;
      }
      return state;
    }
  };

