  var Dragonite8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Dragonair";
      this.cardType = [11 /* DRAGON */];
      this.hp = 160;
      this.weakness = [{ type: 10 /* FAIRY */ }];
      this.resistance = [];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Fast Call",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, (before your attack), you may search your deck for a Supporter card, reveal it, and put it into your hand. Then, shuffle your deck."
      }];
      this.attacks = [{
        name: "Dragon Claw",
        cost: [3 /* WATER */, 4 /* LIGHTNING */, 9 /* COLORLESS */],
        damage: 120,
        text: ""
      }];
      this.set = "TEU";
      this.name = "Dragonite";
      this.fullName = "Dragonite TEU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "119";
      this.FAST_CALL_MARKER = "FAST_CALL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.marker.removeMarker(this.FAST_CALL_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.FAST_CALL_MARKER, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.deck,
          { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
          { min: 0, max: 1, allowCancel: false }
        ), (selected) => {
          const cards = selected || [];
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this });
          store.prompt(state, [new ShowCardsPrompt(
            opponent.id,
            GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
            cards
          )], () => {
            player.marker.addMarker(this.FAST_CALL_MARKER, this);
          });
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      return state;
    }
  };

