  var Dratini9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [N];
      this.hp = 70;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Defensive Scales",
        powerType: 2 /* ABILITY */,
        text: "Prevent all effects of your opponent's attacks, except damage, done to this Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Rain Splash",
        cost: [W],
        damage: 10,
        text: ""
      }];
      this.cardImage = "assets/cardback.png";
      this.setNumber = "117";
      this.set = "TEU";
      this.name = "Dratini";
      this.fullName = "Dratini TEU";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AbstractAttackEffect && effect.target.getPokemonCard() === this) {
        const pokemonCard = effect.target.getPokemonCard();
        const sourceCard = effect.source.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (sourceCard) {
          try {
            const player = StateUtils.findOwner(state, effect.target);
            const stub = new PowerEffect(player, {
              name: "test",
              powerType: 2 /* ABILITY */,
              text: ""
            }, this);
            store.reduceEffect(state, stub);
          } catch {
            return state;
          }
          if (effect instanceof ApplyWeaknessEffect) {
            return state;
          }
          if (effect instanceof PutDamageEffect) {
            return state;
          }
          if (effect instanceof DealDamageEffect) {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      return state;
    }
  };

