  var Dratini25 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [N];
      this.hp = 70;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Defensive Scales",
        powerType: 2 /* ABILITY */,
        text: "Prevent all effects of your opponent's attacks, except damage, done to this Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Rain Splash",
          cost: [W],
          damage: 10,
          text: ""
        }
      ];
      this.set = "TEU";
      this.setNumber = "117";
      this.cardImage = "assets/cardback.png";
      this.name = "Dratini";
      this.fullName = "Dratini TEU 117";
    }
    // Ref: set-dragons-majesty/flygon.ts (Dragon Guard - prevent effects except damage)
    reduceEffect(store, state, effect) {
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (player === effect.player) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (effect instanceof ApplyWeaknessEffect) {
          return state;
        }
        if (effect instanceof PutDamageEffect) {
          return state;
        }
        if (effect instanceof DealDamageEffect) {
          return state;
        }
        effect.preventDefault = true;
      }
      return state;
    }
  };

