  var Electrode11 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Voltorb";
      this.cardType = [L];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Electro Shaker",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may move any number of [L] Energy from your Pok\xE9mon to your other Pok\xE9mon in any way you like."
      }];
      this.attacks = [
        {
          name: "Speed Ball",
          cost: [L, C],
          damage: 50,
          text: ""
        }
      ];
      this.set = "TEU";
      this.setNumber = "39";
      this.cardImage = "assets/cardback.png";
      this.name = "Electrode";
      this.fullName = "Electrode TEU";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        let hasLightningEnergy = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.cards.some((c) => c instanceof EnergyCard && c.provides.includes(4 /* LIGHTNING */))) {
            hasLightningEnergy = true;
          }
        });
        if (!hasLightningEnergy) {
          return state;
        }
        CONFIRMATION_PROMPT(store, state, player, (wantToUse) => {
          if (wantToUse) {
            store.prompt(state, new MoveEnergyPrompt(
              player.id,
              GameMessage.MOVE_ENERGY_CARDS,
              2 /* BOTTOM_PLAYER */,
              [2 /* BENCH */, 1 /* ACTIVE */],
              { superType: 3 /* ENERGY */, cardType: [4 /* LIGHTNING */] },
              { allowCancel: true }
            ), (transfers) => {
              if (!transfers) {
                return;
              }
              for (const transfer of transfers) {
                const source = StateUtils.getTarget(state, player, transfer.from);
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
              }
            });
          }
        }, GameMessage.WANT_TO_USE_ABILITY);
        return state;
      }
      return state;
    }
  };

