  var Emolga6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 60;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [];
      this.NUZZLY_GATHERING_MARKER = "NUZZLY_GATHERING_MARKER";
      this.powers = [{
        name: "Nuzzly Gathering",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may search your deck for a Pok\xE9mon that has the Nuzzle attack, reveal it, and put it into your hand. Then, shuffle your deck."
      }];
      this.attacks = [{
        name: "Nuzzle",
        cost: [L],
        damage: 0,
        text: "Flip a coin. If heads, your opponent's Active Pok\xE9mon is now Paralyzed."
      }];
      this.set = "TEU";
      this.setNumber = "46";
      this.cardImage = "assets/cardback.png";
      this.name = "Emolga";
      this.fullName = "Emolga TEU";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        BLOCK_IF_DECK_EMPTY(player);
        USE_ABILITY_ONCE_PER_TURN(player, this.NUZZLY_GATHERING_MARKER, this);
        ABILITY_USED(player, this);
        const blocked = [];
        player.deck.cards.forEach((c, index) => {
          if (!(c instanceof PokemonCard) || !c.attacks.some((a) => a.name === "Nuzzle")) {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.deck,
          { superType: 1 /* POKEMON */ },
          { min: 0, max: 1, allowCancel: true, blocked }
        ), (selected) => {
          const cards = selected || [];
          cards.forEach((c) => {
            MOVE_CARDS(store, state, player.deck, player.hand, { cards: [c], sourceCard: this });
          });
          return SHUFFLE_DECK(store, state, player);
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.NUZZLY_GATHERING_MARKER, this);
      if (AFTER_ATTACK(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            ADD_PARALYZED_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
          }
        });
      }
      return state;
    }
  };

