  var Ferrothorn4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.cardType = [8 /* METAL */];
      this.hp = 120;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.resistance = [{ type: 5 /* PSYCHIC */, value: -20 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.evolvesFrom = "Ferroseed";
      this.attacks = [
        {
          name: "Guard Press",
          cost: [8 /* METAL */],
          damage: 20,
          text: "During your opponent's next turn, this Pok\xE9mon takes 20 less damage from attacks(after applying Weakness and Resistance)."
        },
        {
          name: "Thorn Pod Throw",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 80,
          text: "This attack does 20 damage times the amount of [M] Energy attached to this Pokemon to 1 of your opponent's Benched Pok\xE9mon. You can't do more than 100 damage to a Benched Pok\xE9mon in this way. (Don't apply Weakness or Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "TEU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "103";
      this.name = "Ferrothorn";
      this.fullName = "Ferrothorn TEU";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.player.active.damageReductionNextTurn = 20;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const oppHasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!oppHasBenched) {
          return state;
        }
        let snipeDamage = 0;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, player.active);
        state = store.reduceEffect(state, checkProvidedEnergy);
        checkProvidedEnergy.energyMap.forEach((energy2) => {
          if (energy2.provides.includes(8 /* METAL */) || energy2.provides.includes(0 /* ANY */)) {
            if (snipeDamage < 100) {
              snipeDamage += 20;
            }
          }
        });
        state = store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          const damageEffect = new PutDamageEffect(effect, snipeDamage);
          damageEffect.target = targets[0];
          store.reduceEffect(state, damageEffect);
        });
        return state;
      }
      return state;
    }
  };

