  var Heliolisk6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Helioptile";
      this.cardType = [L];
      this.hp = 100;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C];
      this.usedVoltSwitch = false;
      this.attacks = [
        {
          name: "Random Spark",
          cost: [L],
          damage: 0,
          text: "This attack does 30 damage to 1 of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Volt Switch",
          cost: [L, C, C],
          damage: 90,
          text: "Switch this Pok\xE9mon with 1 of your Benched Lightning Pok\xE9mon."
        }
      ];
      this.set = "TEU";
      this.setNumber = "50";
      this.cardImage = "assets/cardback.png";
      this.name = "Heliolisk";
      this.fullName = "Heliolisk TEU";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_POKEMON(30, effect, store, state);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedVoltSwitch = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedVoltSwitch) {
        this.usedVoltSwitch = false;
        const player = effect.player;
        const blocked = [];
        player.bench.forEach((bench, index) => {
          if (bench.cards.length === 0) {
            blocked.push({ player: 2 /* BOTTOM_PLAYER */, slot: 2 /* BENCH */, index });
            return;
          }
          const checkType = new CheckPokemonTypeEffect(bench);
          store.reduceEffect(state, checkType);
          if (!checkType.cardTypes.includes(4 /* LIGHTNING */)) {
            blocked.push({ player: 2 /* BOTTOM_PLAYER */, slot: 2 /* BENCH */, index });
          }
        });
        const hasLightningBench = player.bench.some((bench, index) => {
          return bench.cards.length > 0 && !blocked.some((b) => b.index === index);
        });
        if (hasLightningBench) {
          store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false, blocked }
          ), (selected) => {
            if (selected && selected.length > 0) {
              player.switchPokemon(selected[0], store, state);
            }
          });
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedVoltSwitch = false;
      }
      return state;
    }
  };

