  var Klefki6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [M];
      this.hp = 60;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Key of Secrets",
        powerType: 2 /* ABILITY */,
        text: "Each of your Metal Pok\xE9mon's Resistance is now -40."
      }];
      this.attacks = [
        {
          name: "Ram",
          cost: [M, C],
          damage: 30,
          text: ""
        }
      ];
      this.set = "TEU";
      this.setNumber = "110";
      this.cardImage = "assets/cardback.png";
      this.name = "Klefki";
      this.fullName = "Klefki TEU";
    }
    // Ref: set-furious-fists/klefki.ts (Secret Key - CheckPokemonStatsEffect resistance modification)
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonStatsEffect) {
        const target = effect.target;
        let klefkiOwner = null;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              klefkiOwner = p;
            }
          });
        });
        if (!klefkiOwner) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, klefkiOwner, this)) {
          return state;
        }
        const targetOwner = StateUtils.findOwner(state, target);
        if (targetOwner !== klefkiOwner) {
          return state;
        }
        const checkType = new CheckPokemonTypeEffect(target);
        store.reduceEffect(state, checkType);
        if (checkType.cardTypes.includes(8 /* METAL */)) {
          effect.resistance = effect.resistance.map((r) => ({
            type: r.type,
            value: -40
          }));
        }
      }
      return state;
    }
  };

