  var LatiasAndLatiosGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Tag Team" /* TAG_TEAM */, "GX" /* POKEMON_GX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [N];
      this.hp = 250;
      this.weakness = [{ type: Y }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Buster Purge",
          cost: [W, P, P, C],
          damage: 240,
          text: "Discard 3 Energy from this Pok\xE9mon."
        },
        {
          name: "Aero Unit-GX",
          cost: [P],
          damage: 0,
          text: "Attach 5 basic Energy cards from your discard pile to your Pok\xE9mon in any way you like. If this Pok\xE9mon has at least 1 extra Energy attached to it (in addition to this attack's cost), prevent all effects of attacks, including damage, done to it during your opponent's next turn. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "TEU";
      this.setNumber = "113";
      this.cardImage = "assets/cardback.png";
      this.name = "Latias & Latios-GX";
      this.fullName = "Latias & Latios-GX TEU";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 3);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        const totalEnergy = checkEnergy.energyMap.reduce((sum, em) => sum + em.provides.length, 0);
        const hasExtraEnergy = totalEnergy >= 2;
        const basicEnergyInDiscard = player.discard.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        );
        if (basicEnergyInDiscard.length > 0) {
          const maxAttach = Math.min(5, basicEnergyInDiscard.length);
          state = store.prompt(
            state,
            new AttachEnergyPrompt(
              player.id,
              GameMessage.ATTACH_ENERGY_CARDS,
              player.discard,
              2 /* BOTTOM_PLAYER */,
              [1 /* ACTIVE */, 2 /* BENCH */],
              { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
              { allowCancel: false, min: maxAttach, max: 5 }
            ),
            (transfers) => {
              transfers = transfers || [];
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
              }
            }
          );
        }
        if (hasExtraEnergy) {
          PREVENT_DAMAGE(store, state, effect, this);
          PREVENT_EFFECTS_OF_ATTACKS(store, state, effect, this);
        }
      }
      return state;
    }
  };

