  var Ninetales8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Vulpix";
      this.cardType = [R];
      this.hp = 100;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.powers = [{
        name: "Nine Temptations",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may discard 2 [R] Energy cards from your hand. If you do, switch 1 of your opponent's Benched Pok\xE9mon with their Active Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Flame Tail",
          cost: [R, C, C],
          damage: 90,
          text: ""
        }
      ];
      this.set = "TEU";
      this.setNumber = "16";
      this.cardImage = "assets/cardback.png";
      this.name = "Ninetales";
      this.fullName = "Ninetales TEU";
      this.NINE_TEMPTATIONS_MARKER = "NINE_TEMPTATIONS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const fireEnergyCount = player.hand.cards.filter((c) => {
          return c instanceof EnergyCard && c.name === "Fire Energy";
        }).length;
        if (fireEnergyCount < 2) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (HAS_MARKER(this.NINE_TEMPTATIONS_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 3 /* ENERGY */, name: "Fire Energy" },
          { allowCancel: true, min: 2, max: 2 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return state;
          }
          const hasBench = opponent.bench.some((b) => b.cards.length > 0);
          if (!hasBench) {
            return state;
          }
          store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ), (result) => {
            const cardList = result[0];
            const gustEffect = new EffectOfAbilityEffect(player, this.powers[0], this, cardList);
            store.reduceEffect(state, gustEffect);
            if (gustEffect.target) {
              opponent.switchPokemon(gustEffect.target);
            }
          });
          ADD_MARKER(this.NINE_TEMPTATIONS_MARKER, player, this);
          ABILITY_USED(player, this);
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
        });
      }
      return state;
    }
  };

