  var Omastar5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Omanyte";
      this.cardType = [F];
      this.hp = 130;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Fossil Bind",
        powerType: 2 /* ABILITY */,
        text: "As long as you have fewer Pok\xE9mon in play than your opponent, they can't play any Item cards from their hand."
      }];
      this.attacks = [
        {
          name: "Bite",
          cost: [F, C],
          damage: 60,
          text: ""
        }
      ];
      this.set = "TEU";
      this.setNumber = "76";
      this.cardImage = "assets/cardback.png";
      this.name = "Omastar";
      this.fullName = "Omastar TEU";
    }
    // Ref: set-x-and-y/trevenant.ts (Forest's Curse - PlayItemEffect block)
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayItemEffect) {
        const player = effect.player;
        let omastarOwner = null;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              omastarOwner = p;
            }
          });
        });
        if (!omastarOwner) {
          return state;
        }
        if (omastarOwner === player) {
          return state;
        }
        let ownerPokemonCount = 0;
        omastarOwner.forEachPokemon(2 /* BOTTOM_PLAYER */, () => {
          ownerPokemonCount++;
        });
        let opponentPokemonCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, () => {
          opponentPokemonCount++;
        });
        if (ownerPokemonCount >= opponentPokemonCount) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, omastarOwner, this)) {
          return state;
        }
        throw new GameError(GameMessage.BLOCKED_BY_ABILITY);
      }
      return state;
    }
  };

