      this.evolvesFrom = "Paras";
      this.cardType = [G];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Panic Spores",
        powerType: 2 /* ABILITY */,
        text: "Put 2 damage counters on your opponent's Confused Pok\xE9mon between turns."
      }];
      this.attacks = [{
        name: "Mysterious Powder",
        cost: [G, C],
        damage: 30,
        text: "Flip a coin. If heads, your opponent's Active Pok\xE9mon is now Confused."
      }];
      this.set = "TEU";
