  var Starmie8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Staryu";
      this.cardType = [P];
      this.hp = 80;
      this.weakness = [{ type: P }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Strange Wave",
          cost: [C],
          damage: 40,
          text: "Search your deck for up to 3 in any combination of Water and [P] Energy cards and attach them to 1 of your Benched Pok\xE9mon. Then, shuffle your deck."
        }
      ];
      this.set = "TEU";
      this.setNumber = "65";
      this.cardImage = "assets/cardback.png";
      this.name = "Starmie";
      this.fullName = "Starmie TEU";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        const blocked = [];
        player.deck.cards.forEach((c, index) => {
          if (!(c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && (c.provides.includes(3 /* WATER */) || c.provides.includes(5 /* PSYCHIC */)))) {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (selectedTargets) => {
          const target = selectedTargets[0];
          return store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_ATTACH,
            player.deck,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min: 0, max: 3, allowCancel: true, blocked }
          ), (cards) => {
            cards = cards || [];
            cards.forEach((card) => {
              MOVE_CARDS(store, state, player.deck, target, { cards: [card], sourceCard: this });
            });
            return SHUFFLE_DECK(store, state, player);
          });
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-team-up/tapu-koko-prism-star.ts
  init_pokemon_card();
