  var TapuKokoPrismStar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this._tags = ["Prism Star" /* PRISM_STAR */];
      this.hp = 130;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Dance of the Ancients",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn (before your attack), if this Pok\xE9mon is on your Bench, you may choose 2 of your Benched Pok\xE9mon and attach a [L] Energy card from your discard pile to each of them. If you do, discard all cards from this Pok\xE9mon and put it in the Lost Zone."
        }
      ];
      this.attacks = [
        {
          name: "Mach Bolt",
          cost: [L, L, C],
          damage: 120,
          text: ""
        }
      ];
      this.set = "TEU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "51";
      this.name = "Tapu Koko Prism Star";
      this.fullName = "Tapu Koko Prism Star TEU";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (player.active.cards[0] == this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const benchIndex = player.bench.indexOf(cardList);
        if (benchIndex === -1) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(4 /* LIGHTNING */);
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_ACTIVE,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Lightning Energy" },
            { allowCancel: false, min: 1, max: 2, differentTargets: true }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2) => {
              if (cardList2.getPokemonCard() === this) {
                MOVE_POKEMON_OFF_BOARD(store, state, cardList2, {
                  pokemonDestination: player.lostzone,
                  attachedDestination: player.discard,
                  sourceCard: this
                });
              }
            });
            return state;
          }
        );
      }
      return state;
    }
  };

