  var Electrocharger = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "TEU";
      this.setNumber = "139";
      this.cardImage = "assets/cardback.png";
      this.name = "Electrocharger";
      this.fullName = "Electrocharger TEU";
      this.text = "Flip 2 coins. For each heads, shuffle an Electropower card from your discard pile into your deck.";
    }
    // Ref: set-unified-minds/beheeyem.ts (trainer effect pattern), AGENTS-patterns.md (coin flips)
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const electropowerCards = player.discard.cards.filter(
          (c) => c instanceof TrainerCard && c.name === "Electropower"
        );
        if (electropowerCards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          const heads = results.filter((r) => r).length;
          if (heads === 0) {
            return;
          }
          const availableCards = player.discard.cards.filter(
            (c) => c instanceof TrainerCard && c.name === "Electropower"
          );
          const maxToShuffle = Math.min(heads, availableCards.length);
          if (maxToShuffle === 0) {
            return;
          }
          store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_DECK,
              player.discard,
              { name: "Electropower" },
              { min: maxToShuffle, max: maxToShuffle, allowCancel: false }
            ),
            (selected) => {
              const cards = selected || [];
              cards.forEach((c) => {
                MOVE_CARDS(store, state, player.discard, player.deck, {
                  cards: [c],
                  sourceCard: this
                });
              });
              if (cards.length > 0) {
                SHUFFLE_DECK(store, state, player);
              }
            }
          );
        });
      }
      return state;
    }
  };

