  var FairyCharmUb = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "TEU";
      this.setNumber = "142";
      this.cardImage = "assets/cardback.png";
      this.name = "Fairy Charm UB";
      this.fullName = "Fairy Charm UB TEU";
      this.text = "Prevent all damage done to the Fairy Pok\xE9mon this card is attached to by attacks from your opponent's Ultra Beast Pok\xE9mon-GX and Ultra Beast Pok\xE9mon-EX.";
    }
    // Ref: set-lost-thunder/fairy-charm-psychic.ts (Fairy Charm tool damage prevention pattern)
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.target.tools.includes(this)) {
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkTargetType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkTargetType);
        if (!checkTargetType.cardTypes.includes(10 /* FAIRY */)) {
          return state;
        }
        const sourceCard = effect.source.getPokemonCard();
        if (sourceCard && sourceCard.hasTag("Ultra Beast" /* ULTRA_BEAST */) && (sourceCard.hasTag("GX" /* POKEMON_GX */) || sourceCard.hasTag("EX" /* POKEMON_EX */))) {
          effect.damage = 0;
        }
      }
      return state;
    }
  };

