  var IngoAndEmmet = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "TEU";
      this.name = "Ingo & Emmet";
      this.fullName = "Ingo & Emmet TEU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "144";
      this.text = "Look at the top card of your deck, and then choose 1:\n\n- Discard your hand and draw 5 cards.\n- Discard your hand and draw 5 cards from the bottom of your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARD_TO(state, effect.trainerCard, player.supporter);
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: 1, sourceCard: this });
        SHOW_CARDS_TO_PLAYER(store, state, player, deckTop.cards);
        MOVE_CARDS(store, state, deckTop, player.deck, { count: 0, sourceCard: this });
        player.deck.cards = deckTop.cards.concat(player.deck.cards);
        state = store.prompt(
          state,
          new SelectOptionPrompt(
            player.id,
            GameMessage.CHOOSE_OPTION,
            [
              "Discard your hand and draw 5 cards.",
              "Discard your hand and draw 5 cards from the bottom of your deck."
            ],
            {
              allowCancel: false,
              defaultValue: 0
            }
          ),
          (choice) => {
            const cards = player.hand.cards.filter((c) => c !== this);
            if (choice === 0) {
              if (cards.length > 0) {
                MOVE_CARDS(store, state, player.hand, player.discard, { cards });
              }
              DRAW_CARDS(store, state, player, 5);
            } else if (choice === 1) {
              if (cards.length > 0) {
                MOVE_CARDS(store, state, player.hand, player.discard, { cards });
              }
              const bottomCards = player.deck.cards.slice(-5);
              MOVE_CARDS(store, state, player.deck, player.hand, { cards: bottomCards });
            }
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-team-up/jasmine.ts
  init_game_message();
