  var Jasmine = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "TEU";
      this.name = "Jasmine";
      this.fullName = "Jasmine TEU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "145";
      this.text = "Search your deck for a [M] Pok\xE9mon, reveal it, and put it into your hand. If you go second and it's your first turn, search for 5 [M] Pok\xE9mon instead of 1. Then, shuffle your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const numPokemon = state.turn <= 2 ? 5 : 1;
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard && pokemonHasCardType(card, 8 /* METAL */))) {
            blocked.push(index);
          }
        });
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            { superType: 1 /* POKEMON */ },
            { min: 0, max: numPokemon, allowCancel: true, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length === 0) {
              return state;
            }
            MOVE_CARDS_TO_HAND(store, state, player, cards);
            SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
            SHUFFLE_DECK(store, state, player);
          }
        );
        return state;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-team-up/judge-whistle.ts
  init_game();
  init_card_types();
