  init_play_card_effects();
  init_prefabs();
  var JudgeWhistle = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "TEU";
      this.name = "Judge Whistle";
      this.fullName = "Judge Whistle TEU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "146";
      this.text = `Choose 1:

  \u2022 Draw a card.
  \u2022 Put a Judge card from your discard pile into your hand.`;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        let isJudgeInDiscard = false;
        player.discard.cards.forEach((card) => {
          if (card instanceof TrainerCard && card.name === "Judge") {
            isJudgeInDiscard = true;
          }
        });
        if (!isJudgeInDiscard && player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        if (!isJudgeInDiscard) {
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
        }
        if (isJudgeInDiscard) {
          const options = [
            {
              // grab a judge
              message: GameMessage.CHOOSE_SUPPORTER_FROM_DISCARD,
              action: () => {
                const blocked = [];
                player.discard.cards.forEach((c, index) => {
                  const isJudge = c instanceof TrainerCard && c.name === "Judge";
                  if (isJudge) {
                    return;
                  } else {
                    blocked.push(index);
                  }
                });
                let cards = [];
                store.prompt(
                  state,
                  new ChooseCardsPrompt(
                    player,
                    GameMessage.CHOOSE_CARD_TO_HAND,
                    player.discard,
                    { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
                    { min: 1, max: 1, allowCancel: false, blocked }
                  ),
                  (selected) => {
                    cards = selected || [];
                    MOVE_CARDS(store, state, player.discard, player.hand, {
                      cards,
                      sourceCard: this
                    });
                    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                      player.deck.applyOrder(order);
                    });
                  }
                );
              }
            },
            {
              message: GameMessage.DRAW,
              action: () => {
                MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
              }
            }
          ];
          return store.prompt(
            state,
            new SelectPrompt(
              player.id,
              GameMessage.CHOOSE_OPTION,
              options.map((opt) => opt.message),
              { allowCancel: false }
            ),
            (choice) => {
              const option = options[choice];
              option.action();
            }
          );
        }
      }
      return state;
    }
  };

