  var MetalGoggles = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "TEU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "148";
      this.name = "Metal Goggles";
      this.fullName = "Metal Goggles TEU";
      this.text = "The [M] Pok\xE9mon this card is attached to takes 30 less damage from your opponent's attacks (after applying Weakness and Resistance), and your opponent's attacks and Abilities can't put damage counters on it.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.tools.includes(this)) {
        const sourceCard = effect.target.getPokemonCard();
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (sourceCard) {
          const checkPokemonTypeEffect = new CheckPokemonTypeEffect(effect.target);
          store.reduceEffect(state, checkPokemonTypeEffect);
          if (checkPokemonTypeEffect.cardTypes.includes(8 /* METAL */)) {
            const targetPlayer = StateUtils.findOwner(state, effect.target);
            if (targetPlayer === player) {
              effect.reduceDamage(30);
            }
            return state;
          }
        }
      }
      if (effect instanceof PutCountersEffect && effect.target.tools.includes(this)) {
        const sourceCard = effect.target.getPokemonCard();
        const player = StateUtils.findOwner(state, effect.target);
        if (sourceCard) {
          const checkPokemonTypeEffect = new CheckPokemonTypeEffect(effect.target);
          store.reduceEffect(state, checkPokemonTypeEffect);
          if (checkPokemonTypeEffect.cardTypes.includes(8 /* METAL */)) {
            const targetPlayer = StateUtils.findOwner(state, effect.target);
            if (targetPlayer === player) {
              effect.preventDefault = true;
            }
            return state;
          }
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-team-up/morgan.ts
  init_trainer_card();
