  init_prefabs();
  var Morgan = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "TEU";
      this.setNumber = "149";
      this.cardImage = "assets/cardback.png";
      this.name = "Morgan";
      this.fullName = "Morgan TEU";
      this.text = "You can play this card only if you discard Dana, Evelyn, and Nita from your hand. Look at the top 12 cards of your deck and attach any number of Energy cards you find there to your Pok\xE9mon in any way you like. Shuffle the other cards back into your deck. You may play only 1 Supporter card during your turn (before your attack).";
    }
    // Ref: set-scarlet-and-violet/electric-generator.ts (LOOK_AT_TOP_X_CARDS_AND_ATTACH_UP_TO_Y_ENERGY)
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const hasDana = player.hand.cards.some((c) => c.name === "Dana");
        const hasEvelyn = player.hand.cards.some((c) => c.name === "Evelyn");
        const hasNita = player.hand.cards.some((c) => c.name === "Nita");
        if (!hasDana || !hasEvelyn || !hasNita) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const danaCard = player.hand.cards.find((c) => c.name === "Dana");
        const evelynCard = player.hand.cards.find((c) => c.name === "Evelyn");
        const nitaCard = player.hand.cards.find((c) => c.name === "Nita");
        if (danaCard) {
          MOVE_CARDS(store, state, player.hand, player.discard, {
            cards: [danaCard],
            sourceCard: this
          });
        }
        if (evelynCard) {
          MOVE_CARDS(store, state, player.hand, player.discard, {
            cards: [evelynCard],
            sourceCard: this
          });
        }
        if (nitaCard) {
          MOVE_CARDS(store, state, player.hand, player.discard, {
            cards: [nitaCard],
            sourceCard: this
          });
        }
        if (player.deck.cards.length === 0) {
          return state;
        }
        return LOOK_AT_TOP_X_CARDS_AND_ATTACH_UP_TO_Y_ENERGY(store, state, player, 12, 12, {
          destinationSlots: [1 /* ACTIVE */, 2 /* BENCH */],
          energyFilter: {},
          remainderDestination: "shuffle"
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-team-up/nanu.ts
  init_trainer_card();
