  init_play_card_effects();
  init_prefabs();
  var Nanu = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "TEU";
      this.setNumber = "150";
      this.cardImage = "assets/cardback.png";
      this.name = "Nanu";
      this.fullName = "Nanu TEU";
      this.text = "Choose a Basic Darkness Pok\xE9mon in your discard pile. Switch it with 1 of your Pok\xE9mon in play. Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pok\xE9mon. You may play only 1 Supporter card during your turn (before your attack).";
    }
    // Ref: set-lost-origin/thorton.ts (Thorton - swap Basic from discard)
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const hasBasicDarkInDiscard = player.discard.cards.some(
          (c) => c instanceof PokemonCard && c.stage === 2 /* BASIC */ && pokemonHasCardType(c, 7 /* DARK */)
        );
        if (!hasBasicDarkInDiscard) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            player.discard,
            { superType: 1 /* POKEMON */, stage: 2 /* BASIC */, cardType: [7 /* DARK */] },
            { min: 1, max: 1, allowCancel: false }
          ),
          (selectedCards) => {
            const card = selectedCards[0];
            if (!card) {
              return state;
            }
            return store.prompt(
              state,
              new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON,
                2 /* BOTTOM_PLAYER */,
                [1 /* ACTIVE */, 2 /* BENCH */],
                { min: 1, max: 1, allowCancel: false }
              ),
              (targets) => {
                if (!targets || targets.length === 0) {
                  return state;
                }
                const targetList = targets[0];
                const pokemons = targetList.getPokemons();
                pokemons.forEach((p) => {
                  MOVE_CARDS(store, state, targetList, player.discard, {
                    cards: [p],
                    sourceCard: this
                  });
                });
                MOVE_CARDS(store, state, player.discard, targetList, {
                  cards: [card],
                  sourceCard: this
                });
              }
            );
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-team-up/nita.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_check_effects();
  init_prefabs();
  var Nita = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "TEU";
      this.setNumber = "151";
      this.cardImage = "assets/cardback.png";
      this.name = "Nita";
      this.fullName = "Nita TEU";
      this.text = "You can play this card only if your opponent's Active Pok\xE9mon is a Basic Pok\xE9mon. Put an Energy from your opponent's Active Pok\xE9mon on top of their deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const opponentActive = opponent.active.getPokemonCard();
        if (!opponentActive || opponentActive.stage !== 2 /* BASIC */) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const checkEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        state = store.reduceEffect(state, checkEnergy);
        if (checkEnergy.energyMap.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        if (TRAINER_TARGET_BLOCKED(store, state, player, this, opponent.active)) {
          return state;
        }
        store.prompt(
          state,
          new ChooseEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            checkEnergy.energyMap,
            [9 /* COLORLESS */],
            { allowCancel: false }
          ),
          (energy2) => {
            const cards = (energy2 || []).map((e) => e.card);
            if (cards.length > 0) {
              MOVE_CARDS(store, state, opponent.active, opponent.deck, {
                cards,
                sourceCard: this
              });
              cards.forEach((c) => {
                const idx = opponent.deck.cards.indexOf(c);
                if (idx > 0) {
                  opponent.deck.cards.splice(idx, 1);
                  opponent.deck.cards.unshift(c);
                }
              });
            }
          }
        );
      }
      return state;
    }
  };

