  var ReturnLabel = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "TEU";
      this.setNumber = "153";
      this.cardImage = "assets/cardback.png";
      this.name = "Return Label";
      this.fullName = "Return Label TEU";
      this.text = "Put a card from your opponent's discard pile on the bottom of their deck.";
    }
    // Ref: set-lost-thunder/morty.ts (choose from opponent's zone pattern)
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.discard.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DECK,
            opponent.discard,
            {},
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, opponent.discard, opponent.deck, {
                cards: [cards[0]],
                sourceCard: this
              });
              const card = opponent.deck.cards.shift();
              if (card) {
                opponent.deck.cards.push(card);
              }
            }
          }
        );
      }
      return state;
    }
  };

