  var WaterMemory = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "TEU";
      this.setNumber = "157";
      this.cardImage = "assets/cardback.png";
      this.name = "Water Memory";
      this.fullName = "Water Memory TEU";
      this.text = "The Silvally-GX this card is attached to is a Water Pok\xE9mon.";
    }
    // Ref: set-ultra-prism/fire-memory.ts (Fire Memory - CheckPokemonTypeEffect)
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonTypeEffect) {
        if (!effect.target.tools.includes(this)) {
          return state;
        }
        const pokemonCard = effect.target.getPokemonCard();
        if (!pokemonCard || pokemonCard.name !== "Silvally-GX") {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.cardTypes = [3 /* WATER */];
      }
      return state;
    }
  };

