  var WondrousLabyrinthPrismStar = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this._tags = ["Prism Star" /* PRISM_STAR */];
      this.set = "TEU";
      this.setNumber = "158";
      this.name = "Wondrous Labyrinth Prism Star";
      this.fullName = "Wondrous Labyrinth Prism Star TEU";
      this.cardImage = "assets/cardback.png";
      this.text = "The attacks of non-[Y] Pok\xE9mon (both yours and your opponent's) cost [C] more.\n\nWhenever any player plays an Item or Supporter card from their hand, prevent all effects of that card done to this Stadium card.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect && StateUtils.getStadiumCard(state) === this) {
        const checkPokemonTypeEffect = new CheckPokemonTypeEffect(effect.player.active);
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, effect.player, effect.player.active, this)) {
          return state;
        }
        store.reduceEffect(state, checkPokemonTypeEffect);
        const isFairyPokemon = checkPokemonTypeEffect.cardTypes.includes(10 /* FAIRY */);
        if (!isFairyPokemon) {
          const index = effect.cost.indexOf(9 /* COLORLESS */);
          if (index > -1) {
            effect.cost.splice(index, 0, 9 /* COLORLESS */);
          } else {
            effect.cost.push(9 /* COLORLESS */);
          }
        }
        return state;
      }
      if (effect instanceof MoveCardsEffect && StateUtils.getStadiumCard(state) === this) {
        if (effect.sourceCard instanceof TrainerCard && (effect.sourceCard.trainerType === 1 /* SUPPORTER */ || effect.sourceCard.trainerType === 0 /* ITEM */)) {
          const stadiumCard = StateUtils.getStadiumCard(state);
          if (stadiumCard !== void 0) {
            const cardList = StateUtils.findCardList(state, stadiumCard);
            if (effect.source === cardList) {
              effect.preventDefault = true;
            }
          }
        }
      }
      return state;
    }
  };

