  var Galvantula7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Joltik";
      this.cardType = [L];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Unnerve",
        powerType: 2 /* ABILITY */,
        text: "Whenever your opponent plays an Item or Supporter card from their hand, prevent all effects of that card done to this Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Spider Thread",
        cost: [L],
        damage: 40,
        text: "Put a card from your discard pile into your hand."
      }];
      this.set = "TEU";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "48";
      this.name = "Galvantula";
      this.fullName = "Galvantula TEU";
    }
    reduceEffect(store, state, effect) {
      if (IS_TRAINER_TARGET(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        let isGalvantulaOnOpponentsSide = false;
        opponent.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            isGalvantulaOnOpponentsSide = true;
          }
        });
        if (!isGalvantulaOnOpponentsSide) {
          return state;
        }
        BLOCK_TRAINER_TARGET(effect);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasCardInDiscard = player.discard.cards.some((c) => {
          return c instanceof Card;
        });
        if (!hasCardInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        return store.prompt(state, [
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.discard,
            {},
            { min: 1, max: 1, allowCancel: false }
          )
        ], (selected) => {
          const cards = selected || [];
          MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: this });
        });
      }
      return state;
    }
  };

