  var Abomasnow4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Snover";
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: M }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Blessings of the Frost",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may attach a [W] Energy card from your discard pile to 1 of your Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Hypno Hammer",
          cost: [W, C, C, C],
          damage: 80,
          text: "Your opponent's Active Pok\xE9mon is now Asleep."
        }
      ];
      this.set = "UPR";
      this.setNumber = "38";
      this.cardImage = "assets/cardback.png";
      this.name = "Abomasnow";
      this.fullName = "Abomasnow UPR";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const hasWaterEnergy = player.discard.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(3 /* WATER */)
        );
        if (!hasWaterEnergy) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            state = store.prompt(state, new AttachEnergyPrompt(
              player.id,
              GameMessage.ATTACH_ENERGY_CARDS,
              player.discard,
              2 /* BOTTOM_PLAYER */,
              [1 /* ACTIVE */, 2 /* BENCH */],
              { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
              { allowCancel: false, min: 1, max: 1 }
            ), (transfers) => {
              transfers = transfers || [];
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
              }
            });
          }
        });
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

