  init_choose_cards_prompt();
  init_prefabs();
  var AlolanDugtrio3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Alolan Diglett";
      this.cardType = [M];
      this.hp = 60;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Gold Rush",
          cost: [],
          damage: 30,
          damageCalculation: "x",
          text: "Discard any number of [M] Energy cards from your hand. This attack does 30 damage for each card you discarded in this way."
        }
      ];
      this.set = "UPR";
      this.setNumber = "79";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Dugtrio";
      this.fullName = "Alolan Dugtrio UPR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const metalEnergyCards = player.hand.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(8 /* METAL */)
        );
        if (metalEnergyCards.length === 0) {
          effect.damage = 0;
          return state;
        }
        const blocked = [];
        player.hand.cards.forEach((card, index) => {
          if (card instanceof EnergyCard && card.energyType === 0 /* BASIC */ && card.provides.includes(8 /* METAL */)) {
            return;
          }
          blocked.push(index);
        });
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 3 /* ENERGY */ },
          { allowCancel: true, min: 0, max: metalEnergyCards.length, blocked }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            effect.damage = 0;
            return;
          }
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
          effect.damage = 30 * cards.length;
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-ultra-prism/alolan-exeggutor.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var AlolanExeggutor3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Exeggcute";
      this.cardType = [N];
      this.hp = 130;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C, C];
      this.attacks = [{
        name: "Exeggutor's Paradise",
        cost: [],
        damage: 0,
        text: "For each of your Benched Exeggcute, search your deck for an Alolan Exeggutor or Alolan Exeggutor-GX and put it onto that Exeggcute to evolve it. Then, shuffle your deck."
      }, {
        name: "Draco Meteor Barrage",
        cost: [G, C, C],
        damage: 80,
        damageCalculation: "x",
        text: "Flip a coin for each [G] Energy attached to this Pok\xE9mon. This attack does 80 damage for each heads."
      }];
      this.set = "UPR";
      this.setNumber = "95";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Exeggutor";
      this.fullName = "Alolan Exeggutor UPR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const benchedExeggcute = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (target.slot === 2 /* BENCH */ && card.name === "Exeggcute" && card.stage === 2 /* BASIC */) {
            benchedExeggcute.push({ list, card });
          }
        });
        if (benchedExeggcute.length === 0 || player.deck.cards.length === 0) {
          return state;
        }
        const generator = useExeggutorsParadise(() => generator.next(), store, state, player, benchedExeggcute, this);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkEnergy);
        let grassCount = 0;
        checkEnergy.energyMap.forEach((em) => {
          grassCount += em.provides.filter((t) => t === 1 /* GRASS */).length;
        });
        if (grassCount > 0) {
          MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, grassCount, (results) => {
            const heads = results.filter((r) => r).length;
            effect.damage = 80 * heads;
          });
        } else {
          effect.damage = 0;
        }
      }
      return state;
    }
  };
  function* useExeggutorsParadise(next, store, state, player, benchedExeggcute, sourceCard) {
    for (const exeggcute of benchedExeggcute) {
      if (player.deck.cards.length === 0) break;
      const blocked = [];
      player.deck.cards.forEach((card, index) => {
        if (!(card instanceof PokemonCard && card.evolvesFrom === "Exeggcute" && (card.name === "Alolan Exeggutor" || card.name === "Alolan Exeggutor-GX"))) {
          blocked.push(index);
        }
      });
      const hasEvolution = player.deck.cards.some(
        (c) => c instanceof PokemonCard && c.evolvesFrom === "Exeggcute" && (c.name === "Alolan Exeggutor" || c.name === "Alolan Exeggutor-GX")
      );
      if (!hasEvolution) continue;
      let cards = [];
      yield store.prompt(state, new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_EVOLVE,
        player.deck,
        { superType: 1 /* POKEMON */, evolvesFrom: "Exeggcute" },
        { min: 0, max: 1, allowCancel: true, blocked }
      ), (selected) => {
        cards = selected || [];
        next();
      });
      if (cards.length > 0) {
        const evolution = cards[0];
        MOVE_CARDS(store, state, player.deck, exeggcute.list, { cards: [evolution], sourceCard });
        exeggcute.list.clearEffects();
        exeggcute.list.pokemonPlayedTurn = state.turn;
      }
    }
    return SHUFFLE_DECK(store, state, player);
  }

