  var Cherrim2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Cherubi";
      this.cardType = [G];
      this.hp = 80;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [{
        name: "Weather Guard",
        powerType: 2 /* ABILITY */,
        text: "Your Grass Pok\xE9mon have no Weakness."
      }];
      this.attacks = [
        {
          name: "Seed Bomb",
          cost: [G],
          damage: 30,
          text: ""
        }
      ];
      this.set = "UPR";
      this.setNumber = "11";
      this.cardImage = "assets/cardback.png";
      this.name = "Cherrim";
      this.fullName = "Cherrim UPR";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonStatsEffect) {
        const targetCard2 = effect.target.getPokemonCard();
        if (!targetCard2) {
          return state;
        }
        const checkType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkType);
        if (!checkType.cardTypes.includes(1 /* GRASS */)) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        let cherrimInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cherrimInPlay = true;
          }
        });
        if (!cherrimInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.weakness = [];
      }
      return state;
    }
  };

