  var DarkraiPrismStar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Prism Star" /* PRISM_STAR */];
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 160;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Nightmare Star",
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may attach 2 [D] Energy cards from your hand to it."
        }
      ];
      this.attacks = [
        {
          name: "Abyssal Sleep",
          cost: [D, D, D, D],
          damage: 120,
          text: "Your opponent's Active Pok\xE9mon is now Asleep. Your opponent flips 2 coins instead of 1 between turns. If either of them is tails, that Pok\xE9mon is still Asleep."
        }
      ];
      this.set = "UPR";
      this.setNumber = "77";
      this.cardImage = "assets/cardback.png";
      this.name = "Darkrai Prism Star";
      this.fullName = "Darkrai \u25C7 UPR";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const darkEnergyInHand = player.hand.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(7 /* DARK */)
        );
        if (darkEnergyInHand.length === 0) {
          return state;
        }
        state = store.prompt(
          state,
          new ConfirmPrompt(player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              const maxAttach = Math.min(2, darkEnergyInHand.length);
              store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_ATTACH,
                  player.hand,
                  { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
                  {
                    min: 0,
                    max: maxAttach,
                    allowCancel: true,
                    blocked: player.hand.cards.reduce((blocked, c, i) => {
                      if (!(c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(7 /* DARK */))) {
                        blocked.push(i);
                      }
                      return blocked;
                    }, [])
                  }
                ),
                (selected) => {
                  const cards = selected || [];
                  const pokemonList = StateUtils.findCardList(state, this);
                  cards.forEach((card) => {
                    MOVE_CARDS(store, state, player.hand, pokemonList, { cards: [card], sourceCard: this });
                  });
                }
              );
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_ASLEEP(store, state, effect);
        opponent.active.sleepFlips = 2;
      }
      return state;
    }
  };

