  function* playCard166(next, store, state, effect) {
    const player = effect.player;
    const blocked = [];
    let hasPokemonWithDamage = false;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target2) => {
      if (cardList.damage === 0 || !cardList.energies.cards.some(
        (c) => c.superType === 3 /* ENERGY */ && c.name === "Grass Energy"
      )) {
        blocked.push(target2);
      } else {
        hasPokemonWithDamage = true;
      }
    });
    if (hasPokemonWithDamage === false) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: effect.trainerCard });
    effect.preventDefault = true;
    if (player.hand.cards.length < 4) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_HEAL,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: false, blocked }
      ),
      (results) => {
        targets = results || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    const target = targets[0];
    const healEffect = new HealEffect(player, target, 80);
    store.reduceEffect(state, healEffect);
    return state;
  }
