  function* playCard167(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    let energy2 = 0;
    let items = 0;
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      if (c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.name === "Lightning Energy") {
        energy2 += 1;
      } else if (c instanceof TrainerCard && c.trainerType === 0 /* ITEM */) {
        items += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxEnergies = Math.min(energy2, 1);
    const maxItems = Math.min(items, 1);
    const count = maxEnergies + maxItems;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_ONE_ITEM_AND_ONE_LIGHTNING_ENERGY_TO_HAND,
        player.deck,
        {},
        { min: 0, max: count, allowCancel: false, blocked, maxEnergies, maxItems }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }

