  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-ultra-prism/lunala-prism-star.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var LunalaPrismStar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Prism Star" /* PRISM_STAR */];
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 160;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Full Moon Star",
          cost: [P],
          damage: 0,
          text: "For each of your opponent's Pok\xE9mon in play, attach a [P] Energy card from your discard pile to your Pok\xE9mon in any way you like."
        },
        {
          name: "Psystorm",
          cost: [P, P, P, P],
          damage: 20,
          damageCalculation: "x",
          text: "This attack does 20 damage times the amount of Energy attached to all Pok\xE9mon."
        }
      ];
      this.set = "UPR";
      this.setNumber = "62";
      this.cardImage = "assets/cardback.png";
      this.name = "Lunala Prism Star";
      this.fullName = "Lunala Prism Star UPR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.name === "Psychic Energy";
        });
        if (!hasEnergyInDiscard) {
          return state;
        }
        const benched = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        if (benched === 0) {
          return state;
        }
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: 0, max: benched }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let energies = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergyEffect);
          checkProvidedEnergyEffect.energyMap.forEach((energy2) => {
            energies += 1;
          });
        });
        opponent.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(opponent, cardList);
          store.reduceEffect(state, checkProvidedEnergyEffect);
          checkProvidedEnergyEffect.energyMap.forEach((energy2) => {
            energies += 1;
          });
        });
        effect.damage = energies * 20;
      }
      return state;
    }
  };

