  init_attack_effects2();
  var Luxray4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Luxio";
      this.cardType = [L];
      this.hp = 150;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [];
      this.powers = [{
        name: "Intimidating Fang",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is your Active Pok\xE9mon, your opponent's Active Pok\xE9mon's attacks do 30 less damage (before applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Volt Bolt",
          cost: [L, L, C],
          damage: 0,
          text: "Discard all [L] Energy from this Pok\xE9mon. This attack does 150 damage to 1 of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "UPR";
      this.setNumber = "48";
      this.cardImage = "assets/cardback.png";
      this.name = "Luxray";
      this.fullName = "Luxray UPR";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        const opponent = StateUtils.findOwner(state, effect.source);
        if (player === opponent) {
          return state;
        }
        if (player.active !== effect.target) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.damage = Math.max(0, effect.damage - 30);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cards = player.active.cards.filter((c) => c instanceof EnergyCard && c.provides.includes(4 /* LIGHTNING */));
        cards.forEach((c) => {
          MOVE_CARDS(store, state, player.active, player.discard, { cards: [c], sourceCard: this });
        });
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_POKEMON(150, effect, store, state);
      }
      return state;
    }
  };

