  var Magearna2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [M];
      this.hp = 90;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.CHANGE_CLOTHES_MARKER = "MAGEARNA_UPR_CHANGE_CLOTHES_MARKER";
      this.powers = [{
        name: "Change Clothes",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may put a Pok\xE9mon Tool card attached to 1 of your Pok\xE9mon into your hand."
      }];
      this.attacks = [
        {
          name: "Rolling Attack",
          cost: [M, C, C],
          damage: 60,
          text: ""
        }
      ];
      this.set = "UPR";
      this.setNumber = "91";
      this.cardImage = "assets/cardback.png";
      this.name = "Magearna";
      this.fullName = "Magearna UPR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        let hasToolPokemon = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.tools.length > 0) {
            hasToolPokemon = true;
          }
        });
        if (!hasToolPokemon) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.CHANGE_CLOTHES_MARKER, this);
        ABILITY_USED(player, this);
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          const target = selected[0];
          if (target.tools.length > 0) {
            const tool = target.tools[0];
            MOVE_CARDS(store, state, target, player.hand, { cards: [tool], sourceCard: this });
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.CHANGE_CLOTHES_MARKER, this);
      return state;
    }
  };

