  var Magmortar4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Magmar";
      this.cardType = [R];
      this.hp = 130;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Incandescent Body",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon is your Active Pok\xE9mon and is damaged by an opponent's attack (even if this Pok\xE9mon is Knocked Out), the Attacking Pok\xE9mon is now Burned."
      }];
      this.attacks = [
        {
          name: "Fire Blaster",
          cost: [R, R, C],
          damage: 80,
          damageCalculation: "+",
          text: "You may discard 2 Energy from this Pok\xE9mon. If you do, this attack does 80 more damage."
        }
      ];
      this.set = "UPR";
      this.setNumber = "19";
      this.cardImage = "assets/cardback.png";
      this.name = "Magmortar";
      this.fullName = "Magmortar UPR";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        const opponent = StateUtils.findOwner(state, effect.source);
        if (player === opponent) {
          return state;
        }
        if (player.active !== effect.target) {
          return state;
        }
        if (effect.damage <= 0) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (state.phase === 3 /* ATTACK */) {
          const burnEffect = new AddSpecialConditionsPowerEffect(opponent, this, effect.source, [4 /* BURNED */]);
          store.reduceEffect(state, burnEffect);
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return DISCARD_UP_TO_X_ENERGY_FROM_YOUR_POKEMON(
          store,
          state,
          effect,
          2,
          {},
          0,
          [1 /* ACTIVE */],
          (transfers) => {
            if (transfers.length >= 2) {
              effect.damage += 80;
            }
          }
        );
      }
      return state;
    }
  };

