  var Roserade4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Roselia";
      this.cardType = [G];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Inviting Poison",
          cost: [G],
          damage: 0,
          text: "Switch 1 of your opponent's Benched Pok\xE9mon with their Active Pok\xE9mon. The new Active Pok\xE9mon is now Poisoned."
        },
        {
          name: "Flower Tornado",
          cost: [G, G, C],
          damage: 100,
          text: "Move any number of [G] Energy from your Pok\xE9mon to your other Pok\xE9mon in any way you like."
        }
      ];
      this.set = "UPR";
      this.setNumber = "5";
      this.cardImage = "assets/cardback.png";
      this.name = "Roserade";
      this.fullName = "Roserade UPR";
      this.usedInvitingPoison = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          this.usedInvitingPoison = true;
          GUST_OPPONENT_BENCHED_POKEMON(store, state, player);
        }
      }
      if (effect instanceof AfterAttackEffect && this.usedInvitingPoison) {
        this.usedInvitingPoison = false;
        const opponent = StateUtils.getOpponent(state, effect.player);
        opponent.active.addSpecialCondition(3 /* POISONED */);
      }
      if (effect instanceof EndTurnEffect) {
        this.usedInvitingPoison = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          const blockedCards = [];
          checkProvidedEnergy.energyMap.forEach((em) => {
            if (!em.provides.includes(1 /* GRASS */) && !em.provides.includes(0 /* ANY */)) {
              blockedCards.push(em.card);
            }
          });
          const blocked = [];
          blockedCards.forEach((bc) => {
            const index = cardList.cards.indexOf(bc);
            if (index !== -1 && !blocked.includes(index)) {
              blocked.push(index);
            }
          });
          if (blocked.length !== 0) {
            blockedMap.push({ source: target, blocked });
          }
        });
        store.prompt(state, new MoveEnergyPrompt(
          player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: true, blockedMap }
        ), (transfers) => {
          if (transfers === null) {
            return;
          }
          for (const transfer of transfers) {
            const source = StateUtils.getTarget(state, player, transfer.from);
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

