  var Shaymin5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 80;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Coax",
          cost: [C],
          damage: 0,
          text: "Search your deck for up to 3 Basic Pok\xE9mon of different types and put them onto your Bench. Then, shuffle your deck."
        },
        {
          name: "Soothing Scent",
          cost: [G, C],
          damage: 30,
          text: "Your opponent's Active Pok\xE9mon is now Asleep."
        }
      ];
      this.set = "UPR";
      this.setNumber = "15";
      this.cardImage = "assets/cardback.png";
      this.name = "Shaymin";
      this.fullName = "Shaymin UPR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const emptyBenchSlots = player.bench.filter((b) => b.cards.length === 0).length;
        if (emptyBenchSlots === 0 || player.deck.cards.length === 0) {
          return state;
        }
        const maxPokemon = Math.min(3, emptyBenchSlots);
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          player.deck,
          { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
          { min: 0, max: maxPokemon, allowCancel: false, differentTypes: true }
        ), (selected) => {
          const cards = selected || [];
          cards.forEach((card) => {
            const emptySlot = player.bench.find((b) => b.cards.length === 0);
            if (emptySlot) {
              store.reduceEffect(state, new PlayPokemonFromDeckEffect(player, card, emptySlot));
            }
          });
          return SHUFFLE_DECK(store, state, player);
        });
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

