  var AncientCrystal = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "UPR";
      this.setNumber = "118";
      this.cardImage = "assets/cardback.png";
      this.name = "Ancient Crystal";
      this.fullName = "Ancient Crystal UPR";
      this.text = "The Regirock, Regice, Registeel, or Regigigas this card is attached to takes 30 less damage from your opponent's attacks (after applying Weakness and Resistance).";
    }
    // Ref: set-x-and-y/hard-charm.ts (Tool damage reduction pattern)
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.target.tools.includes(this)) {
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          return state;
        }
        const pokemonCard = effect.target.getPokemonCard();
        if (!pokemonCard) {
          return state;
        }
        const validNames = ["Regirock", "Regice", "Registeel", "Regigigas"];
        if (!validNames.some((name) => pokemonCard.name.startsWith(name))) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, player);
        if (effect.source === opponent.active || opponent.bench.includes(effect.source)) {
          effect.damage = Math.max(0, effect.damage - 30);
        }
      }
      return state;
    }
  };

