  var CyrusPrismStar = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this._tags = ["Prism Star" /* PRISM_STAR */];
      this.set = "UPR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "120";
      this.name = "Cyrus Prism Star";
      this.fullName = "Cyrus Prism Star UPR";
      this.text = "You can play this card only if your Active Pok\xE9mon is a [W] or [M] Pok\xE9mon.\n\nYour opponent chooses 2 Benched Pok\xE9mon and shuffles the others, and all cards attached to them, into their deck.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        const opponent = StateUtils.getOpponent(state, player);
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        let hasActiveWaterMetal = false;
        const checkPokemonTypeEffect = new CheckPokemonTypeEffect(player.active);
        store.reduceEffect(state, checkPokemonTypeEffect);
        if (checkPokemonTypeEffect.cardTypes.includes(3 /* WATER */) || checkPokemonTypeEffect.cardTypes.includes(8 /* METAL */)) {
          hasActiveWaterMetal = true;
        }
        if (!hasActiveWaterMetal) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const opponentBenched = opponent.bench.filter((c) => c.cards.length > 0);
        if (opponentBenched.length > 2) {
          store.prompt(
            state,
            new ChoosePokemonPrompt(
              opponent.id,
              GameMessage.CHOOSE_CARDS,
              2 /* BOTTOM_PLAYER */,
              [2 /* BENCH */],
              { allowCancel: false, min: Math.min(opponentBenched.length, 2), max: 2 }
            ),
            (targets) => {
              if (!targets || targets.length === 0) {
                return;
              }
              opponent.forEachPokemon(2 /* BOTTOM_PLAYER */, (card) => {
                if (card !== opponent.active && !targets.includes(card)) {
                  card.clearEffects();
                  MOVE_CARDS(store, state, card, opponent.deck);
                  SHUFFLE_DECK(store, state, opponent);
                }
              });
            }
          );
        }
        return state;
      }
      return state;
    }
  };

