  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_choose_cards_prompt();
  init_shuffle_prompt();
  init_prefabs();
  function* playCard168(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: effect.trainerCard
    });
    let coin1Result = false;
    yield COIN_FLIP_PROMPT(store, state, player, (result) => {
      coin1Result = result;
      next();
    });
    let cards = [];
    if (coin1Result) {
      yield store.prompt(
        state,
        new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.deck,
          { superType: 2 /* TRAINER */, trainerType: 0 /* ITEM */ },
          { min: 0, max: 1, allowCancel: false }
        ),
        (selected) => {
          cards = selected || [];
          next();
        }
      );
      if (cards.length > 0) {
        MOVE_CARDS(store, state, player.deck, player.hand, {
          cards,
          sourceCard: effect.trainerCard
        });
      }
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => state
      );
      return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
        player.deck.applyOrder(order);
      });
    }
  }
  var OrderPad = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "UPR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "131";
      this.name = "Order Pad";
      this.fullName = "Order Pad UPR";
      this.text = "Flip a coin. If heads, search your deck for an Item card, reveal it, and put it into your hand. Shuffle your deck afterward.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard168(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

