  var Aromatisse4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Spritzee";
      this.cardType = [Y];
      this.hp = 90;
      this.weakness = [{ type: M }];
      this.resistance = [{ type: D, value: -20 }];
      this.retreat = [C];
      this.attacks = [{
        name: "Pungent Aroma",
        cost: [Y],
        damage: 0,
        text: "Flip 2 coins. If either of them is heads, your opponent reveals their hand. For each heads, choose a card you find there. Your opponent shuffles those cards into their deck."
      }, {
        name: "Miraculous Cologne",
        cost: [C, C],
        damage: 30,
        text: "Flip a coin. If heads, choose a Special Condition. Your opponent's Active Pok\xE9mon is now affected by that Special Condition."
      }];
      this.set = "UNB";
      this.setNumber = "142";
      this.cardImage = "assets/cardback.png";
      this.name = "Aromatisse";
      this.fullName = "Aromatisse UNB";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          const heads = results.filter((r) => r).length;
          if (heads === 0 || opponent.hand.cards.length === 0) {
            return;
          }
          store.prompt(state, new ShowCardsPrompt(
            player.id,
            GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
            opponent.hand.cards
          ), () => {
            const maxCards = Math.min(heads, opponent.hand.cards.length);
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_DECK,
              opponent.hand,
              {},
              { min: maxCards, max: maxCards, allowCancel: false }
            ), (selected) => {
              const cards = selected || [];
              cards.forEach((c) => {
                MOVE_CARDS(store, state, opponent.hand, opponent.deck, { cards: [c], sourceCard: this });
              });
              if (cards.length > 0) {
                SHUFFLE_DECK(store, state, opponent);
              }
            });
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            store.prompt(state, new SelectOptionPrompt(
              player.id,
              GameMessage.CHOOSE_OPTION,
              [
                "Paralyzed",
                "Confused",
                "Asleep",
                "Poisoned",
                "Burned"
              ],
              { allowCancel: false, defaultValue: 0 }
            ), (choice) => {
              const conditionMap = [
                0 /* PARALYZED */,
                1 /* CONFUSED */,
                2 /* ASLEEP */,
                3 /* POISONED */,
                4 /* BURNED */
              ];
              const selectedCondition = conditionMap[choice ?? 0];
              const specialConditionEffect = new AddSpecialConditionsEffect(effect, [selectedCondition]);
              store.reduceEffect(state, specialConditionEffect);
            });
          }
        });
      }
      return state;
    }
  };

