  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unbroken-bonds/caterpie.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_choose_cards_prompt();
  init_state_utils();
  init_game_error();
  var Caterpie6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 40;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.PUPATE_MARKER = "CATERPIE_UNB_PUPATE_MARKER";
      this.powers = [{
        name: "Pupate",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may flip a coin. If heads, search your deck for a card that evolves from this Pok\xE9mon and put it onto this Pok\xE9mon to evolve it. Then, shuffle your deck."
      }];
      this.attacks = [{
        name: "Hook",
        cost: [C, C],
        damage: 10,
        text: ""
      }];
      this.set = "UNB";
      this.setNumber = "2";
      this.cardImage = "assets/cardback.png";
      this.name = "Caterpie";
      this.fullName = "Caterpie UNB";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.PUPATE_MARKER, this);
        ABILITY_USED(player, this);
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (!result) {
            return;
          }
          const blocked = [];
          player.deck.cards.forEach((c, index) => {
            if (c instanceof PokemonCard && c.evolvesFrom === this.name) {
              return;
            }
            blocked.push(index);
          });
          const hasEvolution = player.deck.cards.some(
            (c) => c instanceof PokemonCard && c.evolvesFrom === this.name
          );
          if (!hasEvolution) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_EVOLVE,
            player.deck,
            { superType: 1 /* POKEMON */ },
            { min: 1, max: 1, allowCancel: true, blocked }
          ), (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              const evolutionCard = cards[0];
              const pokemonCardList = StateUtils.findCardList(state, this);
              MOVE_CARDS(store, state, player.deck, pokemonCardList, { cards: [evolutionCard], sourceCard: this });
              pokemonCardList.clearEffects();
              pokemonCardList.pokemonPlayedTurn = state.turn;
            }
            SHUFFLE_DECK(store, state, player);
          });
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.PUPATE_MARKER, this);
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unbroken-bonds/celesteela-gx.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_prefabs();
  var CelesteelaGx3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */, "Ultra Beast" /* ULTRA_BEAST */];
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 200;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C, C, C];
      this.powers = [
        {
          name: "Force Canceler",
          powerType: 2 /* ABILITY */,
          text: "As long as this Pok\xE9mon is your Active Pok\xE9mon, prevent all effects of your opponent's GX attacks, including damage, done to your Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Power Cyclone",
          cost: [C, C, C],
          damage: 110,
          text: "Move an Energy from this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Discovery-GX",
          cost: [C],
          damage: 0,
          text: "Count your Prize cards and put them into your hand. Then, take that many cards from the top of your deck and put them face down as your Prize cards. If you don't have that many cards in your deck, this attack does nothing. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "UNB";
      this.setNumber = "163";
      this.cardImage = "assets/cardback.png";
      this.name = "Celesteela-GX";
      this.fullName = "Celesteela-GX UNB";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AbstractAttackEffect) {
        if (!effect.attack || !effect.attack.name.includes("-GX")) {
          return state;
        }
        const targetOwner = StateUtils.findOwner(state, effect.target);
        if (targetOwner.active.getPokemonCard() !== this) {
          return state;
        }
        const sourceOwner = StateUtils.findOwner(state, effect.source);
        if (targetOwner === sourceOwner) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetOwner, this)) {
          return state;
        }
        effect.preventDefault = true;
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (hasBench) {
          store.prompt(
            state,
            new AttachEnergyPrompt(
              player.id,
              GameMessage.ATTACH_ENERGY_TO_BENCH,
              player.active,
              2 /* BOTTOM_PLAYER */,
              [2 /* BENCH */],
              { superType: 3 /* ENERGY */ },
              { allowCancel: false, min: 1, max: 1 }
            ),
            (transfers) => {
              transfers = transfers || [];
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
              }
            }
          );
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        const prizeCount = player.prizes.filter((p) => p.cards.length > 0).length;
        if (player.deck.cards.length < prizeCount) {
          player.usedGX = true;
          return state;
        }
        player.usedGX = true;
        player.prizes.forEach((prizeList) => {
          if (prizeList.cards.length > 0) {
            MOVE_CARDS(store, state, prizeList, player.hand, { sourceCard: this });
          }
        });
        let placed = 0;
        for (let i = 0; i < player.prizes.length && placed < prizeCount; i++) {
          if (player.prizes[i].cards.length === 0 && player.deck.cards.length > 0) {
            MOVE_CARDS(store, state, player.deck, player.prizes[i], { count: 1, sourceCard: this });
            player.prizes[i].isSecret = true;
            player.prizes[i].isPublic = false;
            placed++;
          }
        }
      }
      return state;
    }
  };

