  var Charjabug2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Grubbin";
      this.cardType = [L];
      this.hp = 80;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Battery",
        powerType: 2 /* ABILITY */,
        useFromHand: true,
        text: "Once during your turn (before your attack), you may attach this card from your hand to 1 of your Vikavolt or Vikavolt-GX as a Special Energy card. This card provides 2 [L] Energy only while it's attached to a Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Pierce",
        cost: [C, C, C],
        damage: 60,
        text: ""
      }];
      this.set = "UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "58";
      this.name = "Charjabug";
      this.fullName = "Charjabug UNB";
      this.provides = [4 /* LIGHTNING */, 4 /* LIGHTNING */];
      this.energyType = 1 /* SPECIAL */;
      // EnergyCard interface properties
      this.text = "";
      this.isBlocked = false;
      this.energyEffect = void 0;
    }
    reduceEffect(store, state, effect) {
      if (this.superType === 3 /* ENERGY */) {
        const cardList = StateUtils.findCardList(state, this);
        if (!(cardList instanceof PokemonCardList) || !cardList.energies.cards.includes(this)) {
          this.superType = 1 /* POKEMON */;
        }
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.energyPlayedTurn === state.turn) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        player.energyPlayedTurn = state.turn;
        let isVikavoltActive = false;
        let isVikavoltBenched = false;
        const blockedTo = [];
        if (player.active.getPokemonCard()?.name !== "Vikavolt" && player.active.getPokemonCard()?.name !== "Vikavolt-GX") {
          const target = {
            player: 2 /* BOTTOM_PLAYER */,
            slot: 1 /* ACTIVE */,
            index: 0
          };
          blockedTo.push(target);
        } else {
          isVikavoltActive = true;
        }
        player.bench.forEach((bench, index) => {
          if (bench.cards.length === 0) {
            return;
          }
          if (bench.getPokemonCard()?.name === "Vikavolt" || bench.getPokemonCard()?.name === "Vikavolt-GX") {
            isVikavoltBenched = true;
          } else {
            const target = {
              player: 2 /* BOTTOM_PLAYER */,
              slot: 2 /* BENCH */,
              index
            };
            blockedTo.push(target);
          }
        });
        if (!isVikavoltActive && !isVikavoltBenched) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false, blocked: blockedTo }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          effect.preventDefault = true;
          MOVE_CARDS(store, state, player.hand, targets[0], { cards: [this], sourceCard: this });
          if (!targets[0].energies.cards.includes(this)) {
            targets[0].energies.cards.push(this);
          }
          this.superType = 3 /* ENERGY */;
        });
      }
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.energies.cards.includes(this)) {
        effect.energyMap.push({ card: this, provides: this.provides });
      }
      return state;
    }
  };

