  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unbroken-bonds/cleffa.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_phase_effects();
  init_prefabs();
  function* useExcitableDraw(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length + player.hand.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    let flipResult = false;
    yield COIN_FLIP_PROMPT(store, state, player, (result) => {
      flipResult = result;
      next();
    });
    if (flipResult) {
      MOVE_CARDS(store, state, player.hand, player.deck, { sourceCard: effect.card });
      yield store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
        player.deck.applyOrder(order);
        MOVE_CARDS(store, state, player.deck, player.hand, { count: 6, sourceCard: effect.card });
        next();
      });
    }
    const endTurnEffect = new EndTurnEffect(player);
    store.reduceEffect(state, endTurnEffect);
    return state;
  }
  var Cleffa4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [Y];
      this.hp = 60;
      this.retreat = [];
      this.powers = [{
        name: "Excitable Draw",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may flip a coin. If heads, shuffle your hand into your deck and then draw 6 cards. If you use this Ability, your turn ends."
      }];
      this.set = "UNB";
      this.name = "Cleffa";
      this.fullName = "Cleffa UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "131";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const generator = useExcitableDraw(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

