  var Crabominable4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Crabrawler";
      this.cardType = [F];
      this.hp = 140;
      this.weakness = [{ type: P }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Fight Alone",
          cost: [C, C],
          damage: 30,
          damageCalculation: "+",
          text: "If you have fewer Pok\xE9mon in play than your opponent, this attack does 50 more damage for each Pok\xE9mon fewer you have in play."
        },
        {
          name: "Magnum Punch",
          cost: [F, C, C],
          damage: 80,
          text: ""
        }
      ];
      this.set = "UNB";
      this.setNumber = "105";
      this.cardImage = "assets/cardback.png";
      this.name = "Crabominable";
      this.fullName = "Crabominable UNB";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let myCount = 1;
        player.bench.forEach((b) => {
          if (b.cards.length > 0) myCount++;
        });
        let oppCount = 1;
        opponent.bench.forEach((b) => {
          if (b.cards.length > 0) oppCount++;
        });
        if (myCount < oppCount) {
          const difference = oppCount - myCount;
          effect.damage += 50 * difference;
        }
      }
      return state;
    }
  };

