  var Crobat7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Golbat";
      this.cardType = [P];
      this.hp = 130;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [];
      this.powers = [{
        name: "Sound Veil",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may prevent all effects of your opponent's attacks, including damage, done to this Pok\xE9mon until the end of your opponent's next turn."
      }];
      this.attacks = [
        {
          name: "Severe Poison",
          cost: [C, C, C],
          damage: 60,
          text: "Your opponent's Active Pok\xE9mon is now Poisoned. Put 4 damage counters instead of 1 on that Pok\xE9mon between turns."
        }
      ];
      this.set = "UNB";
      this.setNumber = "66";
      this.cardImage = "assets/cardback.png";
      this.name = "Crobat";
      this.fullName = "Crobat UNB";
      this.SOUND_VEIL_MARKER = "CROBAT_SOUND_VEIL_MARKER";
      this.CLEAR_SOUND_VEIL_MARKER = "CROBAT_CLEAR_SOUND_VEIL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        CONFIRMATION_PROMPT(store, state, player, (wantToUse) => {
          if (wantToUse) {
            const cardList = StateUtils.findCardList(state, this);
            cardList.marker.addMarker(this.SOUND_VEIL_MARKER, this);
            const opponent = StateUtils.getOpponent(state, player);
            opponent.marker.addMarker(this.CLEAR_SOUND_VEIL_MARKER, this);
          }
        }, GameMessage.WANT_TO_USE_ABILITY);
        return state;
      }
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (!effect.target.marker.hasMarker(this.SOUND_VEIL_MARKER, this)) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        const attacker = StateUtils.findOwner(state, effect.source);
        if (player === attacker) {
          return state;
        }
        effect.preventDefault = true;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.CLEAR_SOUND_VEIL_MARKER, this)) {
        effect.player.marker.removeMarker(this.CLEAR_SOUND_VEIL_MARKER, this);
        const opponent = StateUtils.getOpponent(state, effect.player);
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          cardList.marker.removeMarker(this.SOUND_VEIL_MARKER, this);
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_POISIONED(store, state, effect);
        effect.opponent.active.poisonDamage = 40;
      }
      return state;
    }
  };

