  var DedenneGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["GX" /* POKEMON_GX */];
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 160;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.resistance = [{ type: 8 /* METAL */, value: -20 }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [
        {
          name: "Dedechange",
          powerType: 2 /* ABILITY */,
          text: " When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may discard your hand and draw 6 cards.You can't use more than 1 Dedechange Ability each turn."
        }
      ];
      this.attacks = [
        {
          name: "Static Shock",
          cost: [4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 50,
          text: ""
        },
        {
          name: "Tingly Return-GX",
          cost: [4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 50,
          text: "Your opponent's Active Pok\xE9mon is now Paralyzed. Put this Pok\xE9mon and all cards attached to it into your hand. (You can't use more than 1 GX attack in a game.) "
        }
      ];
      this.set = "UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "57";
      this.name = "Dedenne-GX";
      this.fullName = "Dedenne GX UNB";
      this.legacyFullName = "Dedenne-GX UNB";
      this.DEDECHANGE_MARKER = "DEDECHANGE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.DEDECHANGE_MARKER)) {
        effect.player.marker.removeMarker(this.DEDECHANGE_MARKER, this);
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        if (player.marker.hasMarker(this.DEDECHANGE_MARKER)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        return store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              player.marker.addMarker(this.DEDECHANGE_MARKER, this);
              const cards = player.hand.cards.filter((c) => c !== this);
              MOVE_CARDS(store, state, player.hand, player.discard, {
                cards,
                sourceCard: this
              });
              MOVE_CARDS(store, state, player.deck, player.hand, { count: 6, sourceCard: this });
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const specialConditionEffect = new AddSpecialConditionsEffect(effect, [
          0 /* PARALYZED */
        ]);
        store.reduceEffect(state, specialConditionEffect);
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_PICK_UP,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */],
            { allowCancel: false }
          ),
          (result) => {
            const cardList = result.length > 0 ? result[0] : null;
            if (cardList !== null) {
              const pokemons = cardList.getPokemons();
              MOVE_CARDS(store, state, cardList, player.hand, { cards: pokemons, sourceCard: this });
              MOVE_CARDS(store, state, cardList, player.hand, { sourceCard: this });
              cardList.clearEffects();
            }
          }
        );
      }
      return state;
    }
  };

