  init_prefabs();
  var GardevoirSylveonGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */, "Tag Team" /* TAG_TEAM */];
      this.stage = 2 /* BASIC */;
      this.cardType = [10 /* FAIRY */];
      this.hp = 260;
      this.weakness = [{ type: 8 /* METAL */ }];
      this.resistance = [{ type: 7 /* DARK */, value: -20 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.set = "UNB";
      this.setNumber = "130";
      this.cardImage = "assets/cardback.png";
      this.name = "Gardevoir & Sylveon-GX";
      this.fullName = "Gardevoir & Sylveon-GX UNB";
      this.attacks = [
        {
          name: "Fairy Song",
          cost: [9 /* COLORLESS */],
          damage: 0,
          text: "Search your deck for up to 2 [Y] Energy cards and attach them to your Benched Pokemon in any way you like. Then, shuffle your deck."
        },
        {
          name: "Kaleidostorm",
          cost: [10 /* FAIRY */, 10 /* FAIRY */, 9 /* COLORLESS */],
          damage: 150,
          text: "Move any number of Energy from your Pokemon to your other Pokemon in any way you like."
        },
        {
          name: "Magical Miracle-GX",
          cost: [10 /* FAIRY */, 10 /* FAIRY */, 10 /* FAIRY */],
          damage: 200,
          text: "If this Pokemon has at least 3 extra [Y] Energy attached to it (in addition to this attack's cost), your opponent shuffles their hand into their deck. (You can't use more than 1 GX attack in a game.)"
        }
      ];
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (hasBench === false) {
          return state;
        }
        store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, name: "Fairy Energy" },
            { allowCancel: false, min: 0, max: 2 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              SHUFFLE_DECK(store, state, player);
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
            }
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        return store.prompt(
          state,
          new MoveEnergyPrompt(
            player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: true }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 2, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const extraEffectCost = [
          10 /* FAIRY */,
          10 /* FAIRY */,
          10 /* FAIRY */,
          10 /* FAIRY */,
          10 /* FAIRY */,
          10 /* FAIRY */
        ];
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergy);
        const meetsExtraEffectCost = StateUtils.checkEnoughEnergy(
          checkProvidedEnergy.energyMap,
          extraEffectCost
        );
        if (meetsExtraEffectCost) {
          MOVE_CARDS(store, state, opponent.hand, opponent.deck, { sourceCard: this });
          return store.prompt(state, new ShuffleDeckPrompt(opponent.id), (order) => {
            opponent.deck.applyOrder(order);
          });
        }
      }
      return state;
    }
  };

