  var Gastly8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 40;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Swelling Spite",
        powerType: 2 /* ABILITY */,
        text: "When this Pok\xE9mon is Knocked Out, search your deck for up to 2 Haunter and put them onto your Bench. Then, shuffle your deck."
      }];
      this.attacks = [
        {
          name: "Will-O-Wisp",
          cost: [C, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "67";
      this.name = "Gastly";
      this.fullName = "Gastly UNB";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        try {
          const powerEffect = new PowerEffect(player, this.powers[0], this);
          store.reduceEffect(state, powerEffect);
        } catch {
          return state;
        }
        const openSlots = player.bench.filter((b) => b.cards.length === 0);
        if (player.deck.cards.length === 0 || openSlots.length === 0) {
          return state;
        }
        store.log(state, "LOG_PLAYER_USES_ABILITY" /* LOG_PLAYER_USES_ABILITY */, { name: player.name, card: this.name });
        CONFIRMATION_PROMPT(store, state, player, (result) => {
          if (result) {
            const maxPokemons = Math.min(openSlots.length, 2);
            return store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
              player.deck,
              { superType: 1 /* POKEMON */, name: "Haunter" },
              { min: 0, max: Math.min(2, maxPokemons), allowCancel: false }
            ), (selectedCards) => {
              const cards = selectedCards || [];
              cards.forEach((card, index) => {
                store.reduceEffect(state, new PlayPokemonFromDeckEffect(player, card, openSlots[index]));
              });
              SHUFFLE_DECK(store, state, player);
            });
          }
        });
      }
      return state;
    }
  };

