  var Gligar6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 60;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Free Flight",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon has no Energy attached to it, it has no Retreat Cost."
      }];
      this.attacks = [
        {
          name: "Shinobi Strike",
          cost: [C, C, C],
          damage: 30,
          damageCalculation: "+",
          text: "If you played Janine from your hand during this turn, this attack does 90 more damage."
        }
      ];
      this.set = "UNB";
      this.setNumber = "98";
      this.cardImage = "assets/cardback.png";
      this.name = "Gligar";
      this.fullName = "Gligar UNB";
      this.JANINE_MARKER = "GLIGAR_JANINE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect && effect.player.active.cards.includes(this)) {
        const player = effect.player;
        const pokemonCard = player.active.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        if (checkProvidedEnergy.energyMap.length === 0) {
          effect.cost = [];
        }
      }
      if (effect instanceof TrainerEffect && effect.trainerCard.name === "Janine") {
        const player = effect.player;
        ADD_MARKER(this.JANINE_MARKER, player, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.JANINE_MARKER, this)) {
        effect.player.marker.removeMarker(this.JANINE_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (HAS_MARKER(this.JANINE_MARKER, player, this)) {
          effect.damage += 90;
        }
      }
      return state;
    }
  };

