  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_effects();
  init_check_effects();
  init_attack_effects();
  init_prefabs();
  var Greninja4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Frogadier";
      this.cardType = [D];
      this.hp = 130;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Bring Down",
          cost: [C, C],
          damage: 0,
          text: "The Pok\xE9mon that has the least HP remaining, except for this Pok\xE9mon, is Knocked Out. (If multiple Pok\xE9mon are tied, choose one.)"
        },
        {
          name: "Mist Slash",
          cost: [D, D],
          damage: 70,
          text: "This attack's damage isn't affected by Weakness, Resistance, or any other effects on your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "UNB";
      this.setNumber = "117";
      this.cardImage = "assets/cardback.png";
      this.name = "Greninja";
      this.fullName = "Greninja UNB";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let leastHP = Infinity;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList !== player.active || cardList.getPokemonCard() !== this) {
            const hpCheck = new CheckHpEffect(player, cardList);
            store.reduceEffect(state, hpCheck);
            const remainingHP = hpCheck.hp - cardList.damage;
            if (remainingHP < leastHP) {
              leastHP = remainingHP;
            }
          }
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          const hpCheck = new CheckHpEffect(opponent, cardList);
          store.reduceEffect(state, hpCheck);
          const remainingHP = hpCheck.hp - cardList.damage;
          if (remainingHP < leastHP) {
            leastHP = remainingHP;
          }
        });
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList === player.active && cardList.getPokemonCard() === this) {
            blockedTo.push(target);
          } else {
            const hpCheck = new CheckHpEffect(player, cardList);
            store.reduceEffect(state, hpCheck);
            const remainingHP = hpCheck.hp - cardList.damage;
            if (remainingHP !== leastHP) {
              blockedTo.push(target);
            }
          }
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          const hpCheck = new CheckHpEffect(opponent, cardList);
          store.reduceEffect(state, hpCheck);
          const remainingHP = hpCheck.hp - cardList.damage;
          if (remainingHP !== leastHP) {
            blockedTo.push(target);
          }
        });
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON,
          0 /* ANY */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, blocked: blockedTo }
        ), (target) => {
          if (target && target.length > 0) {
            const damageEffect = new KnockOutEffect(player, target[0]);
            store.reduceEffect(state, damageEffect);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const applyWeakness = new ApplyWeaknessEffect(effect, 70);
        store.reduceEffect(state, applyWeakness);
        effect.damage = 0;
        opponent.active.damage += 70;
        const afterDamage = new AfterDamageEffect(effect, 70);
        state = store.reduceEffect(state, afterDamage);
      }
      return state;
    }
  };

