  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unbroken-bonds/honchkrow-gx.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_effects();
  init_attack_effects();
  init_play_card_effects();
  init_prefabs();
  var HonchkrowGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Murkrow";
      this._tags = ["GX" /* POKEMON_GX */];
      this.cardType = [D];
      this.hp = 210;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Ruler of the Night",
          powerType: 2 /* ABILITY */,
          text: "As long as this Pok\xE9mon is your Active Pok\xE9mon, your opponent can't play any Pok\xE9mon Tool, Special Energy, or Stadium cards from their hand."
        }
      ];
      this.attacks = [
        {
          name: "Feather Storm",
          cost: [D, C, C],
          damage: 90,
          text: "This attack does 30 damage to 2 of your opponent's Benched Pok\xE9mon-GX and Pok\xE9mon-EX. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Unfair-GX",
          cost: [C, C],
          damage: 0,
          gxAttack: true,
          text: "Your opponent reveals their hand. Discard 2 cards from it. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "109";
      this.name = "Honchkrow-GX";
      this.fullName = "Honchkrow-GX UNB";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.energyCard.energyType === 1 /* SPECIAL */ || effect instanceof PlayStadiumEffect || effect instanceof AttachPokemonToolEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.active.getPokemonCard() !== this) {
          return state;
        }
        try {
          const stub = new PowerEffect(
            effect.player,
            {
              name: "test",
              powerType: 2 /* ABILITY */,
              text: ""
            },
            this
          );
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        throw new GameError(GameMessage.BLOCKED_BY_ABILITY);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        let gxsEXsOnBench = 0;
        const blockedTo = [];
        opponent.bench.forEach((bench, index) => {
          if (bench.cards.length === 0) {
            return;
          }
          if (bench.getPokemonCard()?.hasTag("EX" /* POKEMON_EX */) || bench.getPokemonCard()?.hasTag("GX" /* POKEMON_GX */) || bench.getPokemonCard()?.hasTag("Tag Team" /* TAG_TEAM */)) {
            gxsEXsOnBench++;
          } else {
            const target = {
              player: 2 /* BOTTOM_PLAYER */,
              slot: 2 /* BENCH */,
              index
            };
            blockedTo.push(target);
          }
        });
        if (!gxsEXsOnBench) {
          return state;
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            {
              min: Math.min(gxsEXsOnBench, 2),
              max: Math.min(gxsEXsOnBench, 2),
              allowCancel: false,
              blocked: blockedTo
            }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            for (const target of targets) {
              const damageEffect = new PutDamageEffect(effect, 30);
              damageEffect.target = target;
              store.reduceEffect(state, damageEffect);
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.usedGX) {
          throw new GameError(GameMessage.LABEL_GX_USED);
        }
        player.usedGX = true;
        if (opponent.hand.cards.length === 0) {
          return state;
        }
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.hand,
            {},
            {
              allowCancel: false,
              min: Math.min(opponent.hand.cards.length, 2),
              max: Math.min(opponent.hand.cards.length, 2)
            }
          ),
          (cards) => {
            cards = cards || [];
            MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards, sourceCard: this });
          }
        );
      }
      return state;
    }
  };

