  var Kartana2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Ultra Beast" /* ULTRA_BEAST */];
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 70;
      this.weakness = [{ type: R }];
      this.attacks = [{
        name: "Big Cut",
        cost: [G],
        damage: 10,
        text: "If you have exactly 4 Prize cards remaining, this attack does 120 more damage."
      }, {
        name: "False Swipe",
        cost: [G, C, C],
        damage: 0,
        text: " Flip a coin. If heads, put damage counters on your opponent's Active Pok\xE9mon until its remaining HP is 10. "
      }];
      this.set = "UNB";
      this.setNumber = "19";
      this.cardImage = "assets/cardback.png";
      this.name = "Kartana";
      this.fullName = "Kartana UNB";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.getPrizeLeft() === 4) {
          effect.damage += 120;
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === true) {
            const checkHpEffect = new CheckHpEffect(effect.player, opponent.active);
            store.reduceEffect(state, checkHpEffect);
            const totalHp = checkHpEffect.hp;
            let damageAmount = totalHp - 10;
            const targetDamage = opponent.active.damage;
            if (targetDamage > 0) {
              damageAmount = Math.max(0, damageAmount - targetDamage);
            }
            if (damageAmount > 0) {
              const damageEffect = new PutDamageEffect(effect, damageAmount);
              damageEffect.target = opponent.active;
              store.reduceEffect(state, damageEffect);
            } else if (damageAmount <= 0) {
              const damageEffect = new PutDamageEffect(effect, 0);
              damageEffect.target = opponent.active;
              store.reduceEffect(state, damageEffect);
            }
          }
        });
      }
      return state;
    }
  };

