  var Marshadow3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 80;
      this.weakness = [{ type: 7 /* DARK */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -20 }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [
        {
          name: "Resetting Hole",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn (before your attack), if this Pok\xE9mon is on your Bench, you may discard any Stadium card in play. If you do, discard this Pok\xE9mon and all cards attached to it."
        }
      ];
      this.attacks = [
        {
          name: "Red Knuckles",
          cost: [9 /* COLORLESS */],
          damage: 10,
          damageCalculation: "+",
          text: "If your opponent's Active Pok\xE9mon is an Ultra Beast, this attack does 60 more damage."
        }
      ];
      this.set = "UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "81";
      this.name = "Marshadow";
      this.fullName = "Marshadow UNB";
      this.REFRIGERATED_STREAM_MARKER = "REFRIGERATED_STREAM_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const stadiumCard = StateUtils.getStadiumCard(state);
        const player = effect.player;
        if (stadiumCard === void 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const cardList = StateUtils.findCardList(state, stadiumCard);
        const owner = StateUtils.findOwner(state, cardList);
        if (player.active.cards[0] == this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const marshadowCards = StateUtils.findCardList(state, this);
        const benchIndex = player.bench.indexOf(marshadowCards);
        if (benchIndex === -1) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        MOVE_CARDS(store, state, cardList, owner.discard);
        MOVE_CARDS(store, state, player.bench[benchIndex], player.discard, { sourceCard: this });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DEAL_MORE_DAMAGE_IF_OPPONENT_ACTIVE_HAS_CARD_TAG(effect, state, 60, "Ultra Beast" /* ULTRA_BEAST */);
      }
      return state;
    }
  };

