  var Metapod6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Caterpie";
      this.cardType = [G];
      this.hp = 70;
      this.weakness = [{ type: R }];
      this.retreat = [C, C, C];
      this.EMERGE_MARKER = "METAPOD_UNB_EMERGE_MARKER";
      this.powers = [{
        name: "Emerge",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may flip a coin. If heads, search your deck for a card that evolves from this Pok\xE9mon and put it onto this Pok\xE9mon to evolve it. Then, shuffle your deck."
      }];
      this.attacks = [{
        name: "Bug Bite",
        cost: [G, C, C],
        damage: 30,
        text: ""
      }];
      this.set = "UNB";
      this.setNumber = "3";
      this.cardImage = "assets/cardback.png";
      this.name = "Metapod";
      this.fullName = "Metapod UNB";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.EMERGE_MARKER, this);
        ABILITY_USED(player, this);
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (!result) {
            return;
          }
          const blocked = [];
          player.deck.cards.forEach((c, index) => {
            if (c instanceof PokemonCard && c.evolvesFrom === this.name) {
              return;
            }
            blocked.push(index);
          });
          const hasEvolution = player.deck.cards.some(
            (c) => c instanceof PokemonCard && c.evolvesFrom === this.name
          );
          if (!hasEvolution) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_EVOLVE,
            player.deck,
            { superType: 1 /* POKEMON */ },
            { min: 1, max: 1, allowCancel: true, blocked }
          ), (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              const evolutionCard = cards[0];
              const pokemonCardList = StateUtils.findCardList(state, this);
              MOVE_CARDS(store, state, player.deck, pokemonCardList, { cards: [evolutionCard], sourceCard: this });
              pokemonCardList.clearEffects();
              pokemonCardList.pokemonPlayedTurn = state.turn;
            }
            SHUFFLE_DECK(store, state, player);
          });
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.EMERGE_MARKER, this);
      return state;
    }
  };

