  var Raichu12 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Pikachu";
      this.cardType = [L];
      this.hp = 120;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Never Give Up",
          cost: [C],
          damage: 0,
          text: "You can use this attack only if you have at least 3 more Prize cards remaining than your opponent. Attach all [L] Energy cards from your discard pile to your Pok\xE9mon in any way you like."
        },
        {
          name: "Head Bolt",
          cost: [L, L, C],
          damage: 110,
          text: ""
        }
      ];
      this.set = "UNB";
      this.setNumber = "55";
      this.cardImage = "assets/cardback.png";
      this.name = "Raichu";
      this.fullName = "Raichu UNB";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.getPrizeLeft() < opponent.getPrizeLeft() + 3) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        const hasLightningEnergy = player.discard.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(4 /* LIGHTNING */)
        );
        if (!hasLightningEnergy) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Lightning Energy" },
          { allowCancel: false }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            const energyCard = transfer.card;
            const attachEnergyEffect = new AttachEnergyEffect(player, energyCard, target);
            store.reduceEffect(state, attachEnergyEffect);
          }
        });
      }
      return state;
    }
  };

