  init_pokemon_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_game_phase_effects();
  init_prefabs();
  var Salazzle5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.cardType = [2 /* FIRE */];
      this.hp = 100;
      this.weakness = [{ type: 3 /* WATER */ }];
      this.retreat = [9 /* COLORLESS */];
      this.evolvesFrom = "Salandit";
      this.powers = [{
        name: "Roast Reveal",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may discard a [R] Energy card from your hand. If you do, draw 3 cards."
      }];
      this.attacks = [{
        name: "Combustion",
        cost: [2 /* FIRE */, 9 /* COLORLESS */],
        damage: 60,
        text: ""
      }];
      this.set = "UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "31";
      this.name = "Salazzle";
      this.fullName = "Salazzle UNB";
      this.ROAST_REVEAL_MARKER = "ROAST_REVEAL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.ROAST_REVEAL_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.ROAST_REVEAL_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.ROAST_REVEAL_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasFireEnergyInHand = player.hand.cards.some((c) => {
          return c instanceof EnergyCard && c.provides.includes(2 /* FIRE */);
        });
        if (!hasFireEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.ROAST_REVEAL_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { allowCancel: true, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          player.marker.addMarker(this.ROAST_REVEAL_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 3, sourceCard: this });
        });
        return state;
      }
      return state;
    }
  };

