  init_game();
  init_energy_card();
  init_check_effects();
  init_prefabs();
  var Sharpedo5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Carvanha";
      this.cardType = [D];
      this.hp = 110;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Greedy Evolution",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may look at the top 6 cards of your deck and attach any number of [D] Energy cards you find there to this Pok\xE9mon. Shuffle the other cards back into your deck."
      }];
      this.attacks = [
        {
          name: "Bad Fangs",
          cost: [C, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "This attack does 20 more damage times the amount of [D] Energy attached to this Pok\xE9mon."
        }
      ];
      this.set = "UNB";
      this.setNumber = "111";
      this.cardImage = "assets/cardback.png";
      this.name = "Sharpedo";
      this.fullName = "Sharpedo UNB";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (player.deck.cards.length === 0) {
          return state;
        }
        store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            const topCards = new CardList();
            const count = Math.min(6, player.deck.cards.length);
            MOVE_CARDS(store, state, player.deck, topCards, { count, sourceCard: this });
            const darkEnergy = topCards.cards.filter(
              (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(7 /* DARK */)
            );
            const cardList = StateUtils.findCardList(state, this);
            darkEnergy.forEach((card) => {
              MOVE_CARDS(store, state, topCards, cardList, { cards: [card], sourceCard: this });
            });
            MOVE_CARDS(store, state, topCards, player.deck, { sourceCard: this });
            SHUFFLE_DECK(store, state, player);
          }
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        let darkEnergyCount = 0;
        checkEnergy.energyMap.forEach((em) => {
          darkEnergyCount += em.provides.filter((t) => t === 7 /* DARK */ || t === 0 /* ANY */).length;
        });
        effect.damage += 20 * darkEnergyCount;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unbroken-bonds/slowbro.ts
  init_game();
