  var Slowbro5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Slowpoke";
      this.cardType = [W];
      this.hp = 120;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Yawn",
        cost: [W],
        damage: 20,
        text: "Your opponent's Active Pok\xE9mon is now Asleep."
      }, {
        name: "Three Strikes",
        cost: [W, C, C],
        damage: 100,
        damageCalculation: "x",
        text: "Flip 3 coins. This attack does 100 damage for each heads. If all of them are tails, you lose this game."
      }];
      this.set = "UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "43";
      this.name = "Slowbro";
      this.fullName = "Slowbro UNB";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const specialConditionEffect = new AddSpecialConditionsEffect(effect, [2 /* ASLEEP */]);
        state = store.reduceEffect(state, specialConditionEffect);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        return MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          let heads = 0;
          results.forEach((r) => {
            heads += r ? 1 : 0;
          });
          if (heads === 0) {
            for (let i = 0; i < state.players.length; i++) {
              const currentPlayer = state.players[i];
              if (currentPlayer.id === player.id) {
                state.winner = currentPlayer.id === 0 /* PLAYER_1 */ ? 1 /* PLAYER_2 */ : 0 /* PLAYER_1 */;
                state = endGame(store, state, state.winner);
                return;
              }
            }
          }
          effect.damage = heads * 100;
        });
      }
      return state;
    }
  };

