  var Snorlax9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 150;
      this.weakness = [{ type: F }];
      this.retreat = [C, C, C, C];
      this.powers = [
        {
          name: "Lazy Eating",
          powerType: 2 /* ABILITY */,
          text: "Between turns, heal 10 damage from this Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Big Counter",
          cost: [C, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "If your opponent's Active Pok\xE9mon is a TAG TEAM, this attack does 120 more damage."
        }
      ];
      this.set = "UNB";
      this.setNumber = "158";
      this.cardImage = "assets/cardback.png";
      this.name = "Snorlax";
      this.fullName = "Snorlax UNB";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof BetweenTurnsEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let snorlaxOwner = null;
        let snorlaxCardList = null;
        [player, opponent].forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
            if (card === this) {
              snorlaxOwner = p;
              snorlaxCardList = cardList;
            }
          });
        });
        if (!snorlaxOwner || !snorlaxCardList) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, snorlaxOwner, this)) {
          return state;
        }
        if (snorlaxCardList.damage > 0) {
          snorlaxCardList.damage = Math.max(
            0,
            snorlaxCardList.damage - 10
          );
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentCard = opponent.active.getPokemonCard();
        if (opponentCard && opponentCard.hasTag("Tag Team" /* TAG_TEAM */)) {
          effect.damage += 120;
        }
      }
      return state;
    }
  };

