  var Spiritomb8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [7 /* DARK */];
      this.hp = 60;
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Building Spite",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may put 1 damage counter on this Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Anguish Cry",
          cost: [7 /* DARK */],
          damage: 10,
          damageCalculation: "+",
          text: "This attack does 30 more damage for each damage counter on this Pok\xE9mon."
        }
      ];
      this.set = "UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "112";
      this.name = "Spiritomb";
      this.fullName = "Spiritomb UNB";
      this.BUILDING_SPITE_MARKER = "BUILDING_SPITE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.BUILDING_SPITE_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.BUILDING_SPITE_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.BUILDING_SPITE_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.damage += 10;
          }
        });
        player.marker.addMarker(this.BUILDING_SPITE_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const spiritombDamage = effect.player.active.damage;
        const damagePerCounter = 30;
        effect.damage += spiritombDamage * damagePerCounter / 10;
        return state;
      }
      return state;
    }
  };

