  var Zeraora2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 120;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.resistance = [{ type: 8 /* METAL */, value: -20 }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Crushing Claw",
          cost: [4 /* LIGHTNING */],
          damage: 20,
          text: "Discard a Special Energy from your opponent's Active Pok\xE9mon."
        },
        {
          name: "Discharge",
          cost: [4 /* LIGHTNING */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 50,
          text: "Discard all [L] Energy from this Pok\xE9mon. This attack does 50 damage for each card you discarded in this way. "
        }
      ];
      this.set = "UNB";
      this.setNumber = "60";
      this.cardImage = "assets/cardback.png";
      this.name = "Zeraora";
      this.fullName = "Zeraora UNB";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentActive = opponent.active;
        let hasSpecialEnergy = false;
        opponentActive.cards.forEach((c) => {
          if (c instanceof EnergyCard) {
            if (c.energyType === 1 /* SPECIAL */) {
              hasSpecialEnergy = true;
            }
          }
        });
        if (!hasSpecialEnergy) {
          return state;
        } else {
          return store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            opponentActive,
            // Card source is target Pokemon
            { superType: 3 /* ENERGY */, energyType: 1 /* SPECIAL */ },
            { max: 1, allowCancel: false }
          ), (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              const discardEnergy2 = new DiscardCardsEffect(effect, cards);
              discardEnergy2.target = opponentActive;
              MOVE_CARDS(store, state, opponentActive, opponent.discard, { cards, sourceCard: this });
              return state;
            }
            return state;
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        let totalDiscarded = 0;
        const cards = checkProvidedEnergy.energyMap.map((e) => e.card);
        const discardEnergy2 = new DiscardCardsEffect(effect, cards);
        discardEnergy2.target = player.active;
        totalDiscarded += discardEnergy2.cards.length;
        store.reduceEffect(state, discardEnergy2);
        effect.damage += (totalDiscarded - 1) * 50;
      }
      return state;
    }
  };

