  var MetalCoreBarrier = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "180";
      this.name = "Metal Core Barrier";
      this.fullName = "Metal Core Barrier UNB";
      this.text = "If this card is attached to 1 of your Pok\xE9mon, discard it at the end of your opponent's turn. The [M] Pok\xE9mon this card is attached to takes 70 less damage from your opponent's attacks (after applying Weakness and Resistance).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect) {
        state.players.forEach((player) => {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.tools.includes(this) && StateUtils.findOwner(state, cardList) !== effect.player) {
              if (!IS_TOOL_BLOCKED(store, state, StateUtils.findOwner(state, cardList), this)) {
                MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
              }
            }
          });
        });
      }
      if (effect instanceof PutDamageEffect && effect.target.tools.includes(this)) {
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        const checkPokemonType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkPokemonType);
        if (!checkPokemonType.cardTypes.includes(8 /* METAL */)) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (targetPlayer === player) {
          effect.reduceDamage(70);
        }
        return state;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unbroken-bonds/molayne.ts
  init_trainer_card();
