  init_game();
  init_play_card_effects();
  init_choose_cards_prompt();
  init_show_cards_prompt();
  init_prefabs();
  function* playCard173(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const metalEnergyInHand = player.hand.cards.filter(
      (c) => c !== self && c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(8 /* METAL */)
    );
    if (metalEnergyInHand.length < 2) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const trainerInDiscard = player.discard.cards.some((c) => c.superType === 2 /* TRAINER */);
    if (!trainerInDiscard) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    const blocked = [];
    player.hand.cards.forEach((c, index) => {
      if (!(c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(8 /* METAL */))) {
        blocked.push(index);
      }
    });
    let discardedCards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        player.hand,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { min: 2, max: 2, allowCancel: false, blocked }
      ),
      (selected) => {
        discardedCards = selected || [];
        next();
      }
    );
    discardedCards.forEach((c) => {
      MOVE_CARDS(store, state, player.hand, player.discard, { cards: [c], sourceCard: self });
    });
    const blockedDiscard = [];
    player.discard.cards.forEach((c, index) => {
      if (c.superType !== 2 /* TRAINER */) {
        blockedDiscard.push(index);
      }
    });
    let chosenCards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        { superType: 2 /* TRAINER */ },
        { min: 1, max: 1, allowCancel: false, blocked: blockedDiscard }
      ),
      (selected) => {
        chosenCards = selected || [];
        next();
      }
    );
    if (chosenCards.length > 0) {
      chosenCards.forEach((c) => {
        MOVE_CARDS(store, state, player.discard, player.deck, { cards: [c], sourceCard: self });
      });
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, chosenCards),
        () => next()
      );
    }
    return SHUFFLE_DECK(store, state, player);
  }
  var Molayne = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "UNB";
      this.setNumber = "181";
      this.cardImage = "assets/cardback.png";
      this.name = "Molayne";
      this.fullName = "Molayne UNB";
      this.text = "You can play this card only if you discard 2 [M] Energy cards from your hand. Shuffle a Trainer card from your discard pile into your deck. You may play only 1 Supporter card during your turn (before your attack).";
    }
    // Ref: set-sword-and-shield/ordinary-rod.ts (generator pattern for multi-step trainer)
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard173(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

