  var RedsChallenge = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "184";
      this.name = "Red's Challenge";
      this.fullName = "Red's Challenge UNB";
      this.text = "You can play this card only if you discard 2 other cards from your hand.\n\nSearch your deck for a card and put it into your hand.Then, shuffle your deck.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (player.deck.cards.length === 0) {
        return false;
      }
      if (player.hand.cards.filter((c) => c !== this).length < 2) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.hand.cards.filter((c) => c !== this).length < 2) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        DISCARD_X_CARDS_FROM_YOUR_HAND(effect, store, state, 2, 2);
        SEARCH_DECK_FOR_CARDS_TO_HAND(
          store,
          state,
          player,
          this,
          {},
          { min: 1, max: 1, allowCancel: false }
        );
      }
      return state;
    }
  };

