  var UltraForestKartenvoy = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "UNB";
      this.setNumber = "188";
      this.cardImage = "assets/cardback.png";
      this.name = "Ultra Forest Kartenvoy";
      this.fullName = "Ultra Forest Kartenvoy UNB";
      this.text = "During this turn, damage from your Ultra Beasts' attacks isn't affected by any effects on your opponent's Active Pok\xE9mon. You may play only 1 Supporter card during your turn (before your attack).";
      this.KARTENVOY_MARKER = "ULTRA_FOREST_KARTENVOY_MARKER";
    }
    // Refs: set-dragons-majesty/vibrava.ts (damage not affected by effects), set-ultra-prism/garchomp.ts (marker tracking)
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        ADD_MARKER(this.KARTENVOY_MARKER, player, this);
      }
      if (effect instanceof AttackEffect && HAS_MARKER(this.KARTENVOY_MARKER, effect.player, this)) {
        const sourceCard = effect.player.active.getPokemonCard();
        if (sourceCard && sourceCard.hasTag("Ultra Beast" /* ULTRA_BEAST */)) {
          const opponent = StateUtils.getOpponent(state, effect.player);
          const applyWeakness = new ApplyWeaknessEffect(effect, effect.damage);
          store.reduceEffect(state, applyWeakness);
          const damage = applyWeakness.damage;
          effect.damage = 0;
          if (damage > 0) {
            opponent.active.damage += damage;
            const afterDamage = new AfterDamageEffect(effect, damage);
            state = store.reduceEffect(state, afterDamage);
          }
        }
      }
      if (effect instanceof EndTurnEffect && HAS_MARKER(this.KARTENVOY_MARKER, effect.player, this)) {
        REMOVE_MARKER(this.KARTENVOY_MARKER, effect.player, this);
      }
      return state;
    }
  };

