  var TripleAccelerationEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [9 /* COLORLESS */];
      this.energyType = 1 /* SPECIAL */;
      this.set = "UNB";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "190";
      this.name = "Triple Acceleration Energy";
      this.fullName = "Triple Acceleration Energy UNB";
      this.text = "This card can only be attached to Evolution Pok\xE9mon. If this card is attached to 1 of your Pok\xE9mon, discard it at the end of the turn.\n\nThis card provides [C][C][C] Energy only while it is attached to an Evolution Pok\xE9mon.\n\nIf this card is attached to anything other than an Evolution Pok\xE9mon, discard this card.";
      this.TRIPLE_ACCELERATION_MARKER = "TRIPLE_ACCELERATION_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.energyCard === this) {
        const attachedTo = effect.target.getPokemonCard();
        if (!!attachedTo && (attachedTo.stage === 2 /* BASIC */ || attachedTo.stage === 1 /* RESTORED */)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        effect.player.marker.addMarker(this.TRIPLE_ACCELERATION_MARKER, this);
      }
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        const attachedTo = effect.source.getPokemonCard();
        if (!!attachedTo && attachedTo instanceof PokemonCard && attachedTo.stage !== 2 /* BASIC */ && attachedTo.stage !== 1 /* RESTORED */) {
          effect.energyMap.push({ card: this, provides: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */] });
        }
      }
      if (effect instanceof BetweenTurnsEffect && effect.player.marker.hasMarker(this.TRIPLE_ACCELERATION_MARKER, this)) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (!cardList.cards.includes(this) || IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, cardList)) {
            return;
          }
          MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
          effect.player.marker.removeMarker(this.TRIPLE_ACCELERATION_MARKER, this);
        });
      }
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (!cardList.cards.includes(this) || IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, cardList)) {
              return;
            }
            const attachedTo = cardList.getPokemonCard();
            if (!!attachedTo && (attachedTo.stage === 2 /* BASIC */ || attachedTo.stage === 1 /* RESTORED */)) {
              MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
            }
          });
        });
      }
      return state;
    }
  };

