  init_prefabs();
  var Bibarel4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Bidoof";
      this.cardType = [C];
      this.hp = 120;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Unaware",
        powerType: 2 /* ABILITY */,
        text: "Prevent all effects of your opponent's attacks, except damage, done to this Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Amnesia",
        cost: [C, C, C],
        damage: 60,
        text: "Choose 1 of your opponent's Active Pok\xE9mon's attacks. That Pok\xE9mon can't use that attack during your opponent's next turn."
      }];
      this.set = "UNM";
      this.setNumber = "172";
      this.cardImage = "assets/cardback.png";
      this.name = "Bibarel";
      this.fullName = "Bibarel UNM";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (player === effect.player) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (effect instanceof ApplyWeaknessEffect) {
          return state;
        }
        if (effect instanceof PutDamageEffect) {
          return state;
        }
        if (effect instanceof DealDamageEffect) {
          return state;
        }
        effect.preventDefault = true;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return OPPONENTS_POKEMON_CANNOT_USE_THAT_ATTACK(store, state, effect, this);
      }
      return state;
    }
  };

