  init_play_card_effects();
  init_prefabs();
  var Carracosta3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Tirtouga";
      this.cardType = [W];
      this.hp = 160;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Ancient Custom",
        powerType: 2 /* ABILITY */,
        text: "Pok\xE9mon Tool cards attached to your opponent's Pok\xE9mon have no effect."
      }];
      this.attacks = [
        {
          name: "Aqua Impact",
          cost: [F, C, C],
          damage: 80,
          damageCalculation: "+",
          text: "This attack does 20 more damage for each Colorless in your opponent's Active Pok\xE9mon's Retreat Cost."
        }
      ];
      this.set = "UNM";
      this.setNumber = "45";
      this.cardImage = "assets/cardback.png";
      this.name = "Carracosta";
      this.fullName = "Carracosta UNM";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof ToolEffect) {
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        const opponent = StateUtils.getOpponent(state, owner);
        const toolOwner = StateUtils.findOwner(state, StateUtils.findCardList(state, effect.card));
        if (toolOwner !== opponent) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, owner, this)) {
          return state;
        }
        throw new GameError(GameMessage.CANNOT_USE_POWER);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkRetreat = new CheckRetreatCostEffect(opponent);
        store.reduceEffect(state, checkRetreat);
        const colorlessCount = checkRetreat.cost.filter((c) => c === 9 /* COLORLESS */).length;
        effect.damage += 20 * colorlessCount;
      }
      return state;
    }
  };

