  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/chandelure.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Chandelure8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Lampent";
      this.cardType = [R];
      this.hp = 140;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Spirit Burner",
          cost: [R],
          damage: 10,
          damageCalculation: "+",
          text: "Discard the top 5 cards of your deck. This attack does 60 more damage for each Pok\xE9mon you discarded in this way. Then, put any number of Fire Pok\xE9mon you discarded in this way onto your Bench."
        }
      ];
      this.set = "UNM";
      this.setNumber = "30";
      this.cardImage = "assets/cardback.png";
      this.name = "Chandelure";
      this.fullName = "Chandelure UNM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cardsToDiscard = player.deck.cards.slice(0, 5);
        const discardedPokemon = [];
        cardsToDiscard.forEach((card) => {
          MOVE_CARDS(store, state, player.deck, player.discard, { cards: [card], sourceCard: this });
          if (card instanceof PokemonCard) {
            discardedPokemon.push(card);
          }
        });
        effect.damage += 60 * discardedPokemon.length;
        const firePokemon = discardedPokemon.filter((p) => pokemonHasCardType(p, 2 /* FIRE */));
        const openSlots = player.bench.filter((b) => b.cards.length === 0);
        if (firePokemon.length > 0 && openSlots.length > 0) {
          return store.prompt(
            state,
            new ConfirmPrompt(player.id, GameMessage.WANT_TO_USE_EFFECT_OF_ATTACK),
            (wantToPlace) => {
              if (!wantToPlace) {
                return state;
              }
              const max = Math.min(firePokemon.length, openSlots.length);
              const blocked = [];
              player.discard.cards.forEach((card, index) => {
                if (!firePokemon.includes(card)) {
                  blocked.push(index);
                }
              });
              return store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
                  player.discard,
                  { superType: 1 /* POKEMON */ },
                  { min: 0, max, allowCancel: false, blocked }
                ),
                (selected) => {
                  const cards = selected || [];
                  cards.forEach((card, index) => {
                    MOVE_CARDS(store, state, player.discard, openSlots[index], {
                      cards: [card],
                      sourceCard: this
                    });
                    openSlots[index].pokemonPlayedTurn = state.turn;
                  });
                }
              );
            }
          );
        }
      }
      return state;
    }
  };

