  var Dragonair10 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Dratini";
      this.cardType = [N];
      this.hp = 100;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Tail Whip",
        cost: [C],
        damage: 20,
        text: ""
      }, {
        name: "Destructive Whirlpool",
        cost: [W, L, C, C],
        damage: 70,
        text: "Discard an Energy from your opponent's Active Pok\xE9mon."
      }];
      this.set = "UNM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "150";
      this.name = "Dragonair";
      this.fullName = "Dragonair UNM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!opponent.active.energies.cards.some((c) => c.superType === 3 /* ENERGY */)) {
          return state;
        }
        let cards = [];
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          opponent.active,
          { superType: 3 /* ENERGY */ },
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          cards = selected || [];
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          return store.reduceEffect(state, discardEnergy2);
        });
      }
      return state;
    }
  };

