  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/dragonite.ts
  init_pokemon_card();
  init_card_types();
  init_pokemon_types();
  init_game();
  init_game_phase_effects();
  init_play_card_effects();
  init_prefabs();
  init_check_effects();
  var Dragonite9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Dragonair";
      this.cardType = [N];
      this.hp = 160;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Hurricane Charge",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn (before your attack), you may attach a [W] Energy card, a [L] Energy card, or 1 of each from your hand to your Pok\xE9mon in any way you like."
      }];
      this.attacks = [{
        name: "Dragon Impact",
        cost: [W, L, C, C],
        damage: 170,
        text: "Discard 3 Energy from this Pok\xE9mon."
      }];
      this.set = "UNM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "151";
      this.name = "Dragonite";
      this.fullName = "Dragonite UNM";
      this.HURRICANE_CHARGE_MARKER = "HURRICANE_CHARGE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.HURRICANE_CHARGE_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.HURRICANE_CHARGE_MARKER, this)) {
        effect.player.marker.removeMarker(this.HURRICANE_CHARGE_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 3);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInDiscard = player.hand.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && (c.provides.includes(3 /* WATER */) || c.provides.includes(4 /* LIGHTNING */));
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.HURRICANE_CHARGE_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          checkProvidedEnergy.energyMap.forEach((em, index) => {
            if (!(em.provides.includes(3 /* WATER */) || em.provides.includes(4 /* LIGHTNING */))) {
              const globalIndex = cardList.cards.indexOf(em.card);
              if (globalIndex !== -1 && !blocked.includes(globalIndex)) {
                blocked.push(globalIndex);
              }
            }
          });
        });
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.hand,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          {
            allowCancel: false,
            min: 1,
            max: 2,
            blocked,
            differentTypes: true,
            validCardTypes: [3 /* WATER */, 4 /* LIGHTNING */]
          }
        ), (transfers) => {
          transfers = transfers || [];
          player.marker.addMarker(this.HURRICANE_CHARGE_MARKER, this);
          if (transfers.length === 0) {
            return state;
          }
          if (transfers.length > 1) {
            if (transfers[0].card.name === transfers[1].card.name) {
              throw new GameError(GameMessage.CAN_ONLY_SELECT_TWO_DIFFERENT_ENERGY_TYPES);
            }
          }
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.hand, target, { cards: [transfer.card], sourceCard: this });
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.addBoardEffect(0 /* ABILITY_USED */);
              }
            });
          }
        });
      }
      return state;
    }
  };

