  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/druddigon.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_game_phase_effects();
  init_choose_pokemon_prompt();
  init_prefabs();
  var Druddigon8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [N];
      this.hp = 120;
      this.weakness = [{ type: Y }];
      this.retreat = [C, C];
      this.usedDragOff = false;
      this.attacks = [{
        name: "Drag Off",
        cost: [C, C],
        damage: 0,
        text: "Switch 1 of your opponent's Benched Pok\xE9mon with their Active Pok\xE9mon. This attack does 30 damage to the new Active Pok\xE9mon."
      }, {
        name: "Dragon Tail",
        cost: [R, W, C],
        damage: 100,
        damageCalculation: "x",
        text: "Flip 2 coins. This attack does 100 damage for each heads."
      }];
      this.set = "UNM";
      this.setNumber = "157";
      this.cardImage = "assets/cardback.png";
      this.name = "Druddigon";
      this.fullName = "Druddigon UNM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedDragOff = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedDragOff) {
        this.usedDragOff = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (result) => {
          const cardList = result[0];
          opponent.switchPokemon(cardList);
          const damageEffect = new DealDamageEffect(effect, 30);
          damageEffect.target = opponent.active;
          store.reduceEffect(state, damageEffect);
        });
      }
      if (effect instanceof EndTurnEffect) {
        this.usedDragOff = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          const heads = results.filter((r) => r).length;
          effect.damage = 100 * heads;
        });
      }
      return state;
    }
  };

