  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/eelektross.ts
  init_game();
  init_check_effects();
  init_prefabs();
  var Eelektross6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Eelektrik";
      this.cardType = [L];
      this.hp = 150;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Electric Swamp",
          powerType: 2 /* ABILITY */,
          useFromHand: true,
          useFromHandToBench: true,
          text: "Once during your turn (before your attack), if this Pok\xE9mon is in your hand and you have at least 4 [L] Energy cards in play, you may play this Pok\xE9mon onto your Bench. If you do, move any number of [L] Energy from your other Pok\xE9mon to this Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Hover Over",
          cost: [L, C, C, C],
          damage: 130,
          text: "The Defending Pokemon can't retreat during your opponent's next turn"
        }
      ];
      this.set = "UNM";
      this.setNumber = "66";
      this.cardImage = "assets/cardback.png";
      this.name = "Eelektross";
      this.fullName = "Eelektross UNM";
    }
    canUseFromHandToBench(_store, _state, player) {
      const energyCards = [];
      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
        cardList.cards.filter(
          (c) => c instanceof EnergyCard && !energyCards.includes(c) && (c.provides.includes(4 /* LIGHTNING */) || c.provides.includes(0 /* ANY */))
        ).forEach((c) => energyCards.push(c));
      });
      return energyCards.length >= 4;
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (!this.canUseFromHandToBench(store, state, player)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        PLAY_POKEMON_FROM_HAND_TO_BENCH(state, player, this, effect.target);
        const blockedFrom = [];
        const blockedTo = [];
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card === this) {
            blockedFrom.push(target);
          } else {
            blockedTo.push(target);
          }
          const blocked = [];
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          checkProvidedEnergy.energyMap.forEach((em) => {
            if (!em.provides.includes(4 /* LIGHTNING */) && !em.provides.includes(0 /* ANY */)) {
              const index = cardList.cards.indexOf(em.card);
              if (index !== -1 && !blocked.includes(index)) {
                blocked.push(index);
              }
            }
          });
          if (blocked.length !== 0) {
            blockedMap.push({ source: target, blocked });
          }
        });
        return store.prompt(state, new MoveEnergyPrompt(
          player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: true, blockedFrom, blockedTo, blockedMap }
        ), (transfers) => {
          if (transfers === null) {
            return;
          }
          for (const transfer of transfers) {
            const source = StateUtils.getTarget(state, player, transfer.from);
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return BLOCK_RETREAT(store, state, effect, this);
      }
      return state;
    }
  };

