  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/garchomp.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_effects();
  init_check_effects();
  init_attack_effects();
  init_prefabs();
  var Garchomp6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Gabite";
      this.cardType = [F];
      this.hp = 150;
      this.weakness = [{ type: G }];
      this.retreat = [];
      this.powers = [{
        name: "Avenging Aura",
        powerType: 2 /* ABILITY */,
        text: "If you have more Prize cards remaining than your opponent, this Pok\xE9mon's attacks do 80 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance). "
      }];
      this.attacks = [
        {
          name: "Over Slice",
          cost: [F, C],
          damage: 80,
          damageCalculation: "+",
          text: "You may discard an Energy from this Pok\xE9mon. If you do, this attack does 40 more damage."
        }
      ];
      this.set = "UNM";
      this.setNumber = "114";
      this.cardImage = "assets/cardback.png";
      this.name = "Garchomp";
      this.fullName = "Garchomp UNM";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const oppActive = opponent.active.getPokemonCard();
        const damageSource = effect.source.getPokemonCard();
        if (damageSource && damageSource === oppActive) {
          return state;
        }
        if (damageSource && damageSource !== this) {
          return state;
        }
        try {
          const powerEffect = new PowerEffect(player, this.powers[0], this);
          store.reduceEffect(state, powerEffect);
        } catch {
          return state;
        }
        if (opponent.getPrizeLeft() < player.getPrizeLeft()) {
          effect.damage += 80;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
            state = store.reduceEffect(state, checkProvidedEnergy);
            state = store.prompt(state, new ChooseEnergyPrompt(
              player.id,
              GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
              checkProvidedEnergy.energyMap,
              [9 /* COLORLESS */],
              { allowCancel: false }
            ), (energy2) => {
              const cards = (energy2 || []).map((e) => e.card);
              const discardEnergy2 = new DiscardCardsEffect(effect, cards);
              discardEnergy2.target = player.active;
              store.reduceEffect(state, discardEnergy2);
              effect.damage += 40;
            });
          }
        });
      }
      return state;
    }
  };

