      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C];
      this.powers = [{
        name: "Dimension Breach",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may discard a Special Energy from your opponent's Active Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Fade to Black",
          cost: [P, C, C],
          damage: 70,
          text: "Your opponent's Active Pok\xE9mon is now Confused."
        }
      ];
      this.set = "UNM";
      this.setNumber = "86";
      this.cardImage = "assets/cardback.png";
      this.name = "Giratina";
      this.fullName = "Giratina UNM";
