  var HeatranGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.cardType = [R];
      this._tags = ["GX" /* POKEMON_GX */];
      this.hp = 190;
      this.stage = 2 /* BASIC */;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Burning Road",
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, when this Pok\xE9mon moves from your Bench to become your Active Pok\xE9mon, you may move any number of [R] Energy from your other Pok\xE9mon to it."
        }
      ];
      this.attacks = [
        {
          name: "Steaming Stomp",
          cost: [R, R, C],
          damage: 130,
          text: ""
        },
        {
          name: "Hot Burn-GX",
          cost: [R],
          damage: 50,
          damageCalculation: "x",
          gxAttack: true,
          text: "This attack does 50 damage times the amount of [R] Energy attached to this Pok\xE9mon. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "UNM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "25";
      this.name = "Heatran-GX";
      this.fullName = "Heatran-GX UNM";
      this.ABILITY_USED_MARKER = "ABILITY_USED_MARKER";
    }
    reduceEffect(store, state, effect) {
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.ABILITY_USED_MARKER, this);
      const player = state.players[state.activePlayer];
      if (effect instanceof MovedToActiveEffect && effect.pokemonCard === this && state.players[state.activePlayer] === effect.player && MOVED_TO_ACTIVE_THIS_TURN(effect.player, this)) {
        if (player.marker.hasMarker(this.ABILITY_USED_MARKER, this)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const blockedFrom = [];
        const blockedTo = [];
        const blockedMap = [];
        let hasEnergyOnBench = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList === player.active) {
            blockedFrom.push(target);
            return;
          }
          blockedTo.push(target);
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          const blockedCards = [];
          checkProvidedEnergy.energyMap.forEach((em) => {
            if (!em.provides.includes(2 /* FIRE */) && !em.provides.includes(0 /* ANY */)) {
              blockedCards.push(em.card);
            }
          });
          const blocked = [];
          blockedCards.forEach((bc) => {
            const index = cardList.cards.indexOf(bc);
            if (index !== -1 && !blocked.includes(index)) {
              blocked.push(index);
            }
          });
          if (blocked.length > 0) {
            blockedMap.push({ source: target, blocked });
          }
          if (cardList.cards.some(
            (c) => c.superType === 3 /* ENERGY */ && (c.provides.includes(2 /* FIRE */) || c.provides.includes(0 /* ANY */))
          )) {
            hasEnergyOnBench = true;
          }
        });
        if (hasEnergyOnBench === false) {
          return state;
        }
        player.marker.addMarker(this.ABILITY_USED_MARKER, this);
        return store.prompt(
          state,
          new MoveEnergyPrompt(
            player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, blockedTo, blockedFrom, blockedMap }
          ),
          (transfers) => {
            if (!transfers) {
              return;
            }
            for (const transfer of transfers) {
              const target = player.active;
              const source = StateUtils.getTarget(state, player, transfer.from);
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player2 = effect.player;
        BLOCK_IF_GX_ATTACK_USED(player2);
        player2.usedGX = true;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player2);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let energyCount = 0;
        checkProvidedEnergyEffect.energyMap.forEach((em) => {
          energyCount += em.provides.filter((cardType) => {
            return cardType === 2 /* FIRE */ || cardType === 0 /* ANY */;
          }).length;
        });
        effect.damage = energyCount * 50;
      }
      return state;
    }
  };

