  var KeldeoGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["GX" /* POKEMON_GX */];
      this.cardType = [W];
      this.hp = 170;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Pure Heart",
          powerType: 2 /* ABILITY */,
          text: "Prevent all effects of attacks, including damage, done to this Pokemon by your opponent's Pokemon-GX or Pokemon-EX."
        }
      ];
      this.attacks = [
        {
          name: "Sonic Edge",
          cost: [W, W, C],
          damage: 110,
          shredAttack: true,
          text: "This attack's damage isn't affected by any effects on your opponent's Active Pokemon."
        },
        {
          name: "Resolute Blade-GX",
          cost: [W, W, C],
          damage: 0,
          text: "This attack does 50 damage for each of your opponent's Benched Pokemon. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "UNM";
      this.setNumber = "47";
      this.cardImage = "assets/cardback.png";
      this.name = "Keldeo-GX";
      this.fullName = "Keldeo-GX UNM";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        const sourceCard = effect.source.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (sourceCard && (sourceCard.hasTag("EX" /* POKEMON_EX */) || sourceCard.hasTag("GX" /* POKEMON_GX */))) {
          try {
            const player = StateUtils.findOwner(state, effect.target);
            const powerEffect = new PowerEffect(player, this.powers[0], this);
            store.reduceEffect(state, powerEffect);
          } catch {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const applyWeakness = new ApplyWeaknessEffect(effect, 110);
        store.reduceEffect(state, applyWeakness);
        const damage = applyWeakness.damage;
        effect.damage = 0;
        if (damage > 0) {
          opponent.active.damage += damage;
          const afterDamage = new AfterDamageEffect(effect, damage);
          state = store.reduceEffect(state, afterDamage);
        }
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        let benchCount = 0;
        opponent.bench.forEach((b) => benchCount += b.cards.length > 0 ? 1 : 0);
        effect.damage = 50 * benchCount;
      }
      return state;
    }
  };

