  var Lucario8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Riolu";
      this.cardType = [F];
      this.hp = 120;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Tag Coach",
          powerType: 2 /* ABILITY */,
          text: "Your TAG TEAM Pok\xE9mon take 20 less damage from your opponent's attacks (after applying Weakness and Resistance)."
        }
      ];
      this.attacks = [
        {
          name: "Mach Cross",
          cost: [F, C, C],
          damage: 90,
          text: ""
        }
      ];
      this.set = "UNM";
      this.setNumber = "117";
      this.cardImage = "assets/cardback.png";
      this.name = "Lucario";
      this.fullName = "Lucario UNM";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect) {
        const targetCard2 = effect.target.getPokemonCard();
        if (!targetCard2 || !targetCard2.hasTag("Tag Team" /* TAG_TEAM */)) {
          return state;
        }
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        const sourcePlayer = effect.player;
        if (targetPlayer === sourcePlayer) {
          return state;
        }
        let lucarioInPlay = false;
        targetPlayer.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            lucarioInPlay = true;
          }
        });
        if (!lucarioInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetPlayer, this)) {
          return state;
        }
        effect.damage = Math.max(0, effect.damage - 20);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/lumineon.ts
