  var Lumineon2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Finneon";
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: G }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Neon Trickery",
          cost: [C, C],
          damage: 50,
          text: "You may move an Energy from your opponent's Active Pok\xE9mon to 1 of their Benched Pok\xE9mon."
        }
      ];
      this.set = "UNM";
      this.setNumber = "40";
      this.cardImage = "assets/cardback.png";
      this.name = "Lumineon";
      this.fullName = "Lumineon UNM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasEnergy = opponent.active.cards.some((c) => c instanceof EnergyCard);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasEnergy || !hasBenched) {
          return state;
        }
        store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_ATTACH,
              opponent.active,
              { superType: 3 /* ENERGY */ },
              { min: 1, max: 1, allowCancel: false }
            ), (selected) => {
              const cards = selected || [];
              if (cards.length === 0) {
                return;
              }
              store.prompt(state, new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
                1 /* TOP_PLAYER */,
                [2 /* BENCH */],
                { min: 1, max: 1, allowCancel: false }
              ), (targets) => {
                if (targets && targets.length > 0) {
                  MOVE_CARDS(store, state, opponent.active, targets[0], { cards: [cards[0]], sourceCard: this });
                }
              });
            });
          }
        });
      }
      return state;
    }
  };

