  var Lurantis2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Fomantis";
      this.cardType = [G];
      this.hp = 110;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Petal Blizzard",
          cost: [C],
          damage: 0,
          text: "This attack does 10 damage to each of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Sol Slice",
          cost: [G],
          damage: 50,
          damageCalculation: "+",
          text: "If this Pok\xE9mon has any [R] Energy attached to it, this attack does 50 more damage."
        }
      ];
      this.set = "UNM";
      this.setNumber = "16";
      this.cardImage = "assets/cardback.png";
      this.name = "Lurantis";
      this.fullName = "Lurantis UNM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const damageActive = new DealDamageEffect(effect, 10);
        damageActive.target = opponent.active;
        store.reduceEffect(state, damageActive);
        opponent.bench.forEach((benched) => {
          if (benched.cards.length > 0) {
            const damage = new PutDamageEffect(effect, 10);
            damage.target = benched;
            store.reduceEffect(state, damage);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        const hasFireEnergy = checkEnergy.energyMap.some(
          (em) => em.provides.some((t) => t === 2 /* FIRE */ || t === 0 /* ANY */)
        );
        if (hasFireEnergy) {
          effect.damage += 50;
        }
      }
      return state;
    }
  };

