  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/mawile-gx.ts
  init_pokemon_card();
  init_card_types();
  init_play_card_effects();
  init_game();
  init_prefabs();
  var MawileGX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */];
      this.stage = 2 /* BASIC */;
      this.cardType = [M];
      this.hp = 170;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: P, value: -20 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Captivating Wink",
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may have your opponent reveal their hand and put any number of Basic Pok\xE9mon you find there onto their Bench."
        }
      ];
      this.attacks = [
        {
          name: "Wily Bite",
          cost: [M, C],
          damage: 10,
          damageCalculation: "+",
          text: "This attack does 30 more damage for each of your opponent's Benched Pok\xE9mon."
        },
        {
          name: "Big Eater-GX",
          cost: [M, C],
          damage: 0,
          gxAttack: true,
          text: "Your opponent reveals their hand. Discard all Supporter cards you find there. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "UNM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "141";
      this.name = "Mawile-GX";
      this.fullName = "Mawile-GX UNM";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        CONFIRMATION_PROMPT(
          store,
          state,
          player,
          (result) => {
            if (result) {
              const player2 = effect.player;
              const opponent = StateUtils.getOpponent(state, player2);
              const slots2 = opponent.bench.filter((b) => b.cards.length === 0);
              ABILITY_USED(player2, this);
              if (slots2.length === 0) {
                return state;
              }
              if (opponent.hand.cards.length === 0) {
                return state;
              }
              const max = Math.min(
                opponent.hand.cards.filter(
                  (card) => card instanceof PokemonCard && card.stage === 2 /* BASIC */
                ).length,
                slots2.length
              );
              store.prompt(
                state,
                new ChooseCardsPrompt(
                  player2,
                  GameMessage.CHOOSE_BASIC_POKEMON_TO_BENCH,
                  opponent.hand,
                  { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
                  { min: 0, max, allowCancel: true }
                ),
                (selected) => {
                  const cards = selected || [];
                  if (cards.length === 0) {
                    return state;
                  }
                  cards.forEach((card, index) => {
                    MOVE_CARDS(store, state, opponent.hand, slots2[index], { cards: [card], sourceCard: this });
                    slots2[index].pokemonPlayedTurn = state.turn;
                  });
                }
              );
            }
          },
          GameMessage.WANT_TO_USE_ABILITY
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        const opponentBench = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        effect.damage += 30 * opponentBench;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        const opponentHandCopy = [...opponent.hand.cards];
        SHOW_CARDS_TO_PLAYER(store, state, player, opponentHandCopy);
        const supporterCards = opponent.hand.cards.filter(
          (card) => card instanceof TrainerCard && card.trainerType === 1 /* SUPPORTER */
        );
        MOVE_CARDS(store, state, opponent.hand, opponent.discard, {
          cards: supporterCards,
          sourceCard: this,
          sourceEffect: this.attacks[1]
        });
      }
      return state;
    }
  };

