  var Meloetta6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Tag Cheer",
          cost: [C],
          damage: 0,
          text: "Attach an Energy card from your hand to 1 of your TAG TEAM Pok\xE9mon."
        },
        {
          name: "Shooting Star Pirouette",
          cost: [C, C],
          damage: 30,
          damageCalculation: "+",
          text: "Flip a coin until you get tails. This attack does 30 more damage for each heads."
        }
      ];
      this.set = "UNM";
      this.setNumber = "123";
      this.cardImage = "assets/cardback.png";
      this.name = "Meloetta";
      this.fullName = "Meloetta UNM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergy = player.hand.cards.some((c) => c.superType === 3 /* ENERGY */);
        let hasTagTeam = false;
        const slots2 = [];
        if (player.active.getPokemonCard()?.hasTag("Tag Team" /* TAG_TEAM */)) {
          hasTagTeam = true;
          slots2.push(1 /* ACTIVE */);
        }
        player.bench.forEach((b) => {
          if (b.cards.length > 0 && b.getPokemonCard()?.hasTag("Tag Team" /* TAG_TEAM */)) {
            hasTagTeam = true;
            if (!slots2.includes(2 /* BENCH */)) {
              slots2.push(2 /* BENCH */);
            }
          }
        });
        if (!hasEnergy || !hasTagTeam) {
          return state;
        }
        store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.hand,
            2 /* BOTTOM_PLAYER */,
            slots2,
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 1, max: 1 }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              const targetCard2 = target.getPokemonCard();
              if (targetCard2 && targetCard2.hasTag("Tag Team" /* TAG_TEAM */)) {
                MOVE_CARDS(store, state, player.hand, target, { cards: [transfer.card], sourceCard: this });
              }
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        return FLIP_A_COIN_UNTIL_YOU_GET_TAILS_DO_X_MORE_DAMAGE_PER_HEADS(store, state, effect, 30);
      }
      return state;
    }
  };

