  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/munchlax.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_phase_effects();
  init_prefabs();
  var Munchlax = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 60;
      this.powers = [{
        name: "Snack Search",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: " Once during your turn (before your attack), you may flip a coin.If heads, put a card from your discard pile on top of your deck. If you use this Ability, your turn ends. "
      }];
      this.set = "UNM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "173";
      this.name = "Munchlax";
      this.fullName = "Munchlax UNM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let cards = [];
        BLOCK_IF_DISCARD_EMPTY(player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            const deckTop = new CardList();
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARDS_TO_PUT_ON_TOP_OF_THE_DECK,
              player.discard,
              {},
              { min: 1, max: 1, allowCancel: false }
            ), (selected) => {
              cards = selected || [];
              MOVE_CARDS(store, state, player.discard, deckTop, { cards, sourceCard: this });
              deckTop.moveToTopOfDestination(player.deck);
              if (cards.length > 0) {
                MOVE_CARDS(store, state, player.deck, deckTop, { cards, sourceCard: this });
                return store.prompt(state, new ShowCardsPrompt(
                  opponent.id,
                  GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                  cards
                ), () => {
                  return state;
                });
              }
            });
          }
        });
        const endTurnEffect = new EndTurnEffect(player);
        store.reduceEffect(state, endTurnEffect);
        return state;
      }
      return state;
    }
  };

