  var NaganadelGx = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["GX" /* POKEMON_GX */, "Ultra Beast" /* ULTRA_BEAST */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Poipole";
      this.cardType = [N];
      this.hp = 210;
      this.weakness = [{ type: Y }];
      this.retreat = [C];
      this.ULTRA_CONVERSION_MARKER = "NAGANADEL_GX_UNM_ULTRA_CONVERSION_MARKER";
      this.powers = [
        {
          name: "Ultra Conversion",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn (before your attack), you may discard an Ultra Beast card from your hand. If you do, draw 3 cards."
        }
      ];
      this.attacks = [
        {
          name: "Venom Shot",
          cost: [P, C, C, C],
          damage: 0,
          text: "Discard 2 Energy from this Pokemon. This attack does 170 damage to 1 of your opponent's Pokemon. (Don't apply Weakness and Resistance for Benched Pokemon.)"
        },
        {
          name: "Injection-GX",
          cost: [L],
          damage: 0,
          text: "Add a card from your opponent's discard pile to their Prize cards face down. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.set = "UNM";
      this.setNumber = "160";
      this.cardImage = "assets/cardback.png";
      this.name = "Naganadel-GX";
      this.fullName = "Naganadel-GX UNM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const hasUltraBeast = player.hand.cards.some(
          (c) => c instanceof PokemonCard && c.hasTag("Ultra Beast" /* ULTRA_BEAST */)
        );
        if (!hasUltraBeast) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.ULTRA_CONVERSION_MARKER, this);
        ABILITY_USED(player, this);
        const blocked = [];
        player.hand.cards.forEach((c, index) => {
          if (!(c instanceof PokemonCard && c.hasTag("Ultra Beast" /* ULTRA_BEAST */))) {
            blocked.push(index);
          }
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            {},
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, player.hand, player.discard, { cards: [cards[0]], sourceCard: this });
              DRAW_CARDS(store, state, player, 3);
            }
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.ULTRA_CONVERSION_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 2);
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            effect.player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const damageEffect = new PutDamageEffect(effect, 170);
            damageEffect.target = targets[0];
            store.reduceEffect(state, damageEffect);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        if (opponent.discard.cards.length === 0) {
          return state;
        }
        const emptyPrize = opponent.prizes.find((p) => p.cards.length === 0);
        if (!emptyPrize) {
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            opponent.discard,
            {},
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, opponent.discard, emptyPrize, { cards: [cards[0]], sourceCard: this });
              emptyPrize.isSecret = true;
              emptyPrize.isPublic = false;
            }
          }
        );
      }
      return state;
    }
  };

