  function* useCleaningUp(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let pokemonsWithTool = 0;
    const blocked = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      if (cardList.tools.length > 0) {
        pokemonsWithTool += 1;
      } else {
        blocked.push(target);
      }
    });
    opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
      if (cardList.tools.length > 0) {
        pokemonsWithTool += 1;
      } else {
        blocked.push(target);
      }
    });
    effect.preventDefault = true;
    const max = Math.min(1, pokemonsWithTool);
    let targets = [];
    yield store.prompt(state, new ChoosePokemonPrompt(
      player.id,
      GameMessage.CHOOSE_POKEMON_TO_DISCARD_CARDS,
      0 /* ANY */,
      [1 /* ACTIVE */, 2 /* BENCH */],
      { min: 1, max, allowCancel: true, blocked }
    ), (results) => {
      targets = results || [];
      next();
    });
    if (targets.length === 0) {
      return state;
    }
    targets.forEach((target) => {
      const owner = StateUtils.findOwner(state, target);
      if (target.tools.length > 0) {
        if (target.tools.length > 1) {
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            target,
            { superType: 2 /* TRAINER */, trainerType: 3 /* TOOL */ },
            { min: 1, max: 1, allowCancel: false }
          ), (selected) => {
            if (selected && selected.length > 0) {
              MOVE_CARDS(store, state, target, owner.discard, { cards: [selected[0]], sourceCard: effect.source.getPokemonCard() });
            }
          });
        } else {
          MOVE_CARDS(store, state, target, owner.discard, { cards: [target.tools[0]], sourceCard: effect.source.getPokemonCard() });
        }
      }
    });
    return state;
  }
