  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/stunfisk.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var Stunfisk8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.resistance = [{ type: M, value: -20 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Trap Bolt",
          cost: [F],
          damage: 30,
          damageCalculation: "+",
          text: "If, before doing damage, your opponent's Active Pok\xE9mon has more remaining HP than this Pok\xE9mon, this attack does 30 more damage."
        }
      ];
      this.set = "UNM";
      this.setNumber = "67";
      this.cardImage = "assets/cardback.png";
      this.name = "Stunfisk";
      this.fullName = "Stunfisk UNM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkHp = new CheckHpEffect(opponent, opponent.active);
        store.reduceEffect(state, checkHp);
        const opponentRemainingHp = checkHp.hp - opponent.active.damage;
        const checkMyHp = new CheckHpEffect(player, player.active);
        store.reduceEffect(state, checkMyHp);
        const myRemainingHp = checkMyHp.hp - player.active.damage;
        if (opponentRemainingHp > myRemainingHp) {
          effect.damage += 30;
        }
      }
      return state;
    }
  };

