  var Swadloon6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Sewaddle";
      this.cardType = [G];
      this.hp = 70;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Swaddling Leaves",
        powerType: 2 /* ABILITY */,
        text: "This Pok\xE9mon takes 30 less damage from attacks (after applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Bug Bite",
          cost: [C],
          damage: 10,
          text: ""
        }
      ];
      this.set = "UNM";
      this.setNumber = "8";
      this.cardImage = "assets/cardback.png";
      this.name = "Swadloon";
      this.fullName = "Swadloon UNM";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.damage = Math.max(0, effect.damage - 30);
      }
      return state;
    }
  };

