  init_game();
  init_attack_effects();
  init_choose_pokemon_prompt();
  init_prefabs();
  var Thundurus4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 120;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.resistance = [{ type: 8 /* METAL */, value: -20 }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Thunderous Gale",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 20,
          damageCalculation: "+",
          text: "If Tornadus is on your Bench, this attack does 50 more damage."
        },
        {
          name: "Raging Thunder",
          cost: [4 /* LIGHTNING */, 4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 120,
          text: "This attack does 40 damage to 1 of your Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "UNM";
      this.setNumber = "68";
      this.cardImage = "assets/cardback.png";
      this.name = "Thundurus";
      this.fullName = "Thundurus UNM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasTornadus = player.bench.some(
          (b) => b.cards.length > 0 && b.cards[0].name.toLowerCase().includes("tornadus")
        );
        if (hasTornadus) {
          effect.damage += 50;
        }
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const benched = player.bench.filter((b) => b.cards.length > 0);
        if (benched.length === 0) {
          return state;
        }
        state = store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          const damageEffect = new PutDamageEffect(effect, 40);
          damageEffect.target = targets[0];
          store.reduceEffect(state, damageEffect);
        });
        return state;
      }
      return state;
    }
  };

