  var Zygarde7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 90;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.powers = [{
        name: "Cellular Companions",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is on your Bench, your Zygarde's and Zygarde-GX's attacks do 20 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Boost Fang",
          cost: [F],
          damage: 20,
          text: "Attach a [F] Energy card from your discard pile to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.set = "UNM";
      this.setNumber = "124";
      this.cardImage = "assets/cardback.png";
      this.name = "Zygarde";
      this.fullName = "Zygarde UNM";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.damage > 0) {
        const sourceCard = effect.source.getPokemonCard();
        if (!sourceCard) {
          return state;
        }
        if (sourceCard.name !== "Zygarde" && sourceCard.name !== "Zygarde-GX") {
          return state;
        }
        const sourcePlayer = StateUtils.findOwner(state, effect.source);
        const opponent = StateUtils.getOpponent(state, sourcePlayer);
        if (effect.target !== opponent.active) {
          return state;
        }
        let isOnBench = false;
        sourcePlayer.bench.forEach((b) => {
          if (b.getPokemonCard() === this && b.cards.includes(this)) {
            isOnBench = true;
          }
        });
        if (!isOnBench) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, sourcePlayer, this)) {
          return state;
        }
        effect.damage += 20;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fighting Energy" },
          { allowCancel: true, min: 0, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

