  var FlyiniumZAirSlash = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "UNM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "195";
      this.name = "Flyinium Z: Air Slash";
      this.fullName = "Flyinium Z: Air Slash UNM";
      this.attacks = [
        {
          name: "Speeding Skystrike-GX",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 180,
          text: "Prevent all effects of attacks, including damage, done to this Pok\xE9mon during your opponent's next turn. (You can't use more than 1 GX attack in a game.)"
        }
      ];
      this.text = "If the Pok\xE9mon this card is attached to has the Air Slash attack, it can use the GX attack on this card. (You still need the necessary Energy to use this attack.)";
      this.FLYINIUM_Z_MARKER = "FLYINIUM_Z_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonAttacksEffect && effect.player.active.getPokemonCard()?.tools.includes(this) && !effect.attacks.includes(this.attacks[0])) {
        if (!effect.player.active.getPokemonCard()?.attacks.some((attack3) => attack3.name === "Air Slash")) {
          return state;
        }
        effect.attacks.push(this.attacks[0]);
      }
      if (effect instanceof AttackEffect && effect.attack === this.attacks[0]) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        cardList.marker.addMarker(this.FLYINIUM_Z_MARKER, this);
        BLOCK_IF_GX_ATTACK_USED(player);
        player.usedGX = true;
        return state;
      }
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this) && effect.target.marker.hasMarker(this.FLYINIUM_Z_MARKER, this)) {
        effect.preventDefault = true;
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner !== player) {
          cardList.marker?.removeMarker(this.FLYINIUM_Z_MARKER, this);
        }
      }
      return state;
    }
  };

