  var Grimsley = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "UNM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "199";
      this.name = "Grimsley";
      this.fullName = "Grimsley UNM";
      this.text = "Move up to 3 damage counters from 1 of your opponent's Pok\xE9mon to another of their Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const damagedPokemon = [
          ...opponent.bench.filter((b) => b.cards.length > 0 && b.damage > 0),
          ...opponent.active.damage > 0 ? [opponent.active] : []
        ];
        if (damagedPokemon.length === 0) {
          throw new GameError(GameMessage.CANNOT_MOVE_DAMAGE);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        const maxAllowedDamage = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(player, cardList);
          store.reduceEffect(state, checkHpEffect);
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        return store.prompt(
          state,
          new MoveDamagePrompt(
            effect.player.id,
            GameMessage.MOVE_DAMAGE,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            maxAllowedDamage,
            {
              min: 1,
              max: 3,
              allowCancel: false,
              singleSourceTarget: true,
              singleDestinationTarget: true
            }
          ),
          (transfers) => {
            if (transfers === null) {
              MOVE_CARDS(store, state, player.supporter, player.discard, {
                cards: [this],
                sourceCard: this
              });
              return state;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              source.damage -= 10;
              target.damage += 10;
            }
            MOVE_CARDS(store, state, player.supporter, player.discard, {
              cards: [this],
              sourceCard: this
            });
            return state;
          }
        );
      }
      return state;
    }
  };

