  var ResetStamp = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "UNM";
      this.name = "Reset Stamp";
      this.fullName = "Reset Stamp UNM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "206";
      this.text = "Your opponent shuffles their hand into their deck and draws a card for each of their remaining Prize cards.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentCards = opponent.hand.cards.filter((c) => c !== this);
        if (opponentCards.length === 0 && opponent.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, opponent.hand, opponent.deck, {
          cards: opponentCards,
          sourceCard: this
        });
        store.prompt(state, new ShuffleDeckPrompt(opponent.id), (order) => {
          opponent.deck.applyOrder(order);
        });
        MOVE_CARDS(store, state, opponent.deck, opponent.hand, {
          count: Math.min(opponent.getPrizeLeft(), opponent.deck.cards.length),
          sourceCard: this
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/slumbering-forest.ts
  init_game();
