  var SlumberingForest = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "UNM";
      this.name = "Slumbering Forest";
      this.fullName = "Slumbering Forest UNM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "207";
      this.text = "If a Pok\xE9mon is Asleep, its owner flips 2 coins instead of 1 for that Special Condition between turns. If either of them is tails, that Pok\xE9mon is still Asleep.";
      this.SLUMBERING_MARKER = "SLUMBERING_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && StateUtils.getStadiumCard(state) === this) {
        const players = [effect.player, StateUtils.getOpponent(state, effect.player)];
        players.forEach((player) => {
          if (IS_STADIUM_EFFECT_BLOCKED(store, state, player, player.active, this)) {
            return;
          }
          if (player.active.specialConditions.includes(2 /* ASLEEP */)) {
            ADD_MARKER(this.SLUMBERING_MARKER, player, this);
          }
        });
      }
      if (effect instanceof BeginTurnEffect && StateUtils.getStadiumCard(state) === this) {
        const players = [effect.player, StateUtils.getOpponent(state, effect.player)];
        players.forEach((player) => {
          if (IS_STADIUM_EFFECT_BLOCKED(store, state, player, player.active, this)) {
            REMOVE_MARKER(this.SLUMBERING_MARKER, player, this);
            return;
          }
          if (!player.active.specialConditions.includes(2 /* ASLEEP */) && HAS_MARKER(this.SLUMBERING_MARKER, player, this)) {
            COIN_FLIP_PROMPT(store, state, player, (result) => {
              if (!result) {
                player.active.addSpecialCondition(2 /* ASLEEP */);
              }
            });
            REMOVE_MARKER(this.SLUMBERING_MARKER, player, this);
          } else {
            REMOVE_MARKER(this.SLUMBERING_MARKER, player, this);
          }
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/stadium-nav.ts
  init_game();
  init_game_error();
  init_game_message();
