  var StadiumNav = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "UNM";
      this.name = "Stadium Nav";
      this.fullName = "Stadium Nav UNM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "208";
      this.text = "Flip 2 coins. For each heads, search your deck for a Stadium card, reveal it, and put it into your hand. Then, shuffle your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const opponent = StateUtils.getOpponent(state, player);
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        let heads = 0;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          results.forEach((r) => {
            heads += r ? 1 : 0;
          });
          if (heads === 0) {
            return state;
          }
          let cards = [];
          const blocked = [];
          player.deck.cards.forEach((card, index) => {
            if (card instanceof TrainerCard && card.trainerType === 2 /* STADIUM */) {
            } else {
              blocked.push(index);
            }
          });
          store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_HAND,
              player.deck,
              { superType: 2 /* TRAINER */, trainerType: 2 /* STADIUM */ },
              { min: 0, max: heads, allowCancel: false, blocked }
            ),
            (selected) => {
              cards = selected || [];
              if (cards.length > 0) {
                MOVE_CARDS(store, state, player.deck, player.hand, {
                  cards,
                  sourceCard: this
                });
                return store.prompt(
                  state,
                  new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
                  () => {
                    return state;
                  }
                );
              }
              return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                player.deck.applyOrder(order);
              });
            }
          );
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/tag_switch.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_prefabs();
  function* playCard176(next, store, state, effect) {
    const player = effect.player;
    let hasEnergy = false;
    let tagTeamPokemonCount = 0;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
      if (card.hasTag("Tag Team" /* TAG_TEAM */)) {
        tagTeamPokemonCount++;
        const energyAttached = cardList.energies.cards.some((c) => {
          return c.superType === 3 /* ENERGY */;
        });
        hasEnergy = hasEnergy || energyAttached;
      }
    });
    if (!hasEnergy || tagTeamPokemonCount <= 1) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    const blockedFrom = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      if (!card.hasTag("Tag Team" /* TAG_TEAM */)) {
        blockedFrom.push(target);
        return;
      }
    });
    let transfers = [];
    yield store.prompt(
      state,
      new MoveEnergyPrompt(
        player.id,
        GameMessage.MOVE_ENERGY_CARDS,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { superType: 3 /* ENERGY */ },
        { min: 1, max: 2, allowCancel: false, blockedFrom }
      ),
      (result) => {
        transfers = result || [];
        next();
      }
    );
    transfers.forEach((transfer) => {
      const source = StateUtils.getTarget(state, player, transfer.from);
      const target = StateUtils.getTarget(state, player, transfer.to);
      MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: effect.trainerCard });
    });
    return state;
  }
  var TagSwitch = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "UNM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "209";
      this.name = "Tag Switch";
      this.fullName = "Tag Switch UNM";
      this.text = "Move up to 2 Energy from 1 of your TAG TEAM Pok\xE9mon to another of your Pok\xE9mon. ";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard176(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/08-sun-and-moon/set-unified-minds/u-turn-board.ts
  init_card_types();
  init_trainer_card();
  init_attack_effects();
  init_check_effects();
  init_play_card_effects();
  init_prefabs();
  var UTurnBoard = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "UNM";
      this.name = "U-Turn Board";
      this.fullName = "U-Turn Board UNM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "211";
      this.U_TURN_BOARD_MARKER = "U_TURN_BOARD_MARKER";
      this.text = `The Retreat Cost of the Pok\xE9mon this card is attached to is [C] less. 
    
    If this card is discarded from play, put it into your hand instead of the discard pile.`;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DiscardCardsEffect && effect.cards.includes(this)) {
        const player = effect.player;
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        const cardsToMove = effect.cards.filter((c) => c === this);
        if (cardsToMove.length > 0) {
          state = MOVE_CARDS(store, state, effect.target, player.hand, { cards: cardsToMove });
          effect.cards = effect.cards.filter((c) => c !== this);
        }
      }
      if (effect instanceof AttachPokemonToolEffect && effect.trainerCard === this) {
        const player = effect.player;
        player.marker.addMarker(this.U_TURN_BOARD_MARKER, this);
      }
      if (effect instanceof CheckRetreatCostEffect && effect.player.active.tools.includes(this)) {
        const index = effect.cost.indexOf(9 /* COLORLESS */);
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        if (index !== -1) {
          effect.cost.splice(index, 1);
        }
      }
      if (effect instanceof CheckTableStateEffect && state.players.some((p) => p.discard.cards.includes(this))) {
        for (const player of state.players) {
          if (!player.marker.hasMarker(this.U_TURN_BOARD_MARKER, this)) {
            continue;
          }
          const rescued = player.marker.markers.filter((m) => m.name === this.U_TURN_BOARD_MARKER && m.source !== void 0).map((m) => m.source);
          const cardsInDiscard = rescued.filter((c) => player.discard.cards.includes(c));
          if (cardsInDiscard.length > 0) {
            state = MOVE_CARDS(store, state, player.discard, player.hand, { cards: cardsInDiscard });
            player.marker.removeMarker(this.U_TURN_BOARD_MARKER, this);
          }
        }
      }
      return state;
    }
  };

