  var Bulbasaur8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [1 /* GRASS */];
      this.hp = 60;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Find a Friend",
          cost: [1 /* GRASS */],
          damage: 0,
          text: "Search your deck for a [G] Pok\xE9mon, reveal it, and put it into your hand. Then, shuffle your deck."
        }
      ];
      this.set = "DET";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "1";
      this.name = "Bulbasaur";
      this.fullName = "Bulbasaur DET";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        let cards = [];
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          player.deck,
          { superType: 1 /* POKEMON */, cardType: [1 /* GRASS */] },
          { min: 0, max: 1, allowCancel: false }
        ), (selectedCards) => {
          cards = selectedCards || [];
          cards.forEach((card, index) => {
            MOVE_CARDS(store, state, player.deck, player.hand, { cards: [card], sourceCard: this, sourceEffect: this.attacks[0] });
            return state;
          });
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-detective-pikachu/greninja.ts
