  var Greninja5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Frogadier";
      this.cardType = [3 /* WATER */];
      this.hp = 140;
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Evasion Jutsu",
        useWhenInPlay: false,
        powerType: 2 /* ABILITY */,
        text: "If any damage is done to this Pok\xE9mon by attacks, flip a coin. If heads, prevent that damage."
      }];
      this.attacks = [{
        name: "Furious Shurikens",
        cost: [3 /* WATER */, 3 /* WATER */],
        damage: 0,
        text: "This attack does 50 damage to 2 of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.set = "DET";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "9";
      this.name = "Greninja";
      this.fullName = "Greninja DET";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this || state.phase !== 3 /* ATTACK */) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (effect.damage <= 0) {
          return state;
        }
        const coinFlip = new CoinFlipEffect(player);
        store.reduceEffect(state, coinFlip);
        if (coinFlip.result === false) {
          return state;
        }
        effect.preventDefault = true;
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let attackTargets = 0;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (_) => attackTargets += 1);
        const min = Math.min(attackTargets, 2);
        const max = Math.min(attackTargets, 2);
        state = store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { min, max, allowCancel: false }
        ), (selected) => {
          const targets = selected || [];
          DAMAGE_OPPONENT_POKEMON(store, state, effect, 50, targets);
        });
        return state;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-detective-pikachu/mr-mime.ts
  init_game();
