  var Absol8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 100;
      this.attacks = [
        {
          name: "Swirling Diaster",
          cost: [D],
          damage: 0,
          text: "This attack does 10 damage to each of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Claw Rend",
          cost: [D, C],
          damage: 50,
          text: "If your opponent's Active Pok\xE9mon already has any damage counters on it, this attack does 70 more damage."
        }
      ];
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.set = "ASR";
      this.regulationMark = "F";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "97";
      this.name = "Absol";
      this.fullName = "Absol ASR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        const benched = opponent.bench.filter((b) => b.cards.length > 0);
        const activeDamageEffect = new DealDamageEffect(effect, 10);
        activeDamageEffect.target = opponent.active;
        store.reduceEffect(state, activeDamageEffect);
        benched.forEach((target) => {
          const damageEffect = new PutDamageEffect(effect, 10);
          damageEffect.target = target;
          store.reduceEffect(state, damageEffect);
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.active.damage > 0) {
          effect.damage += 70;
        }
        return state;
      }
      return state;
    }
  };

