  var Bastiodon3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Shieldon";
      this.cardType = [M];
      this.hp = 160;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C, C, C];
      this.powers = [
        {
          name: "Primal Fortress",
          powerType: 2 /* ABILITY */,
          text: "Your Pok\xE9mon take 30 less damage from attacks from your opponent's Pok\xE9mon V (after applying Weakness and Resistance)."
        }
      ];
      this.attacks = [
        {
          name: "Iron Tackle",
          cost: [M, M, C],
          damage: 180,
          text: "This Pok\xE9mon also does 30 damage to itself."
        }
      ];
      this.regulationMark = "F";
      this.set = "ASR";
      this.setNumber = "110";
      this.cardImage = "assets/cardback.png";
      this.name = "Bastiodon";
      this.fullName = "Bastiodon ASR 110";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect) {
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (!targetPlayer) {
          return state;
        }
        if (!StateUtils.isPokemonInPlay(targetPlayer, this)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetPlayer, this)) {
          return state;
        }
        const attacker = StateUtils.findOwner(state, effect.source);
        if (targetPlayer === attacker) {
          return state;
        }
        const sourceCard = effect.source.getPokemonCard();
        if (sourceCard && (sourceCard.hasTag("V" /* POKEMON_V */) || sourceCard.hasTag("VMAX" /* POKEMON_VMAX */) || sourceCard.hasTag("VSTAR" /* POKEMON_VSTAR */))) {
          effect.reduceDamage(30);
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_POKEMON_DOES_DAMAGE_TO_ITSELF(store, state, effect, 30);
      }
      return state;
    }
  };

