  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-astral-radiance/darkrai-vstar.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_play_card_effects();
  init_prefabs();
  var DarkraiVSTAR = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VSTAR" /* POKEMON_VSTAR */];
      this.evolvesFrom = "Darkrai V";
      this.regulationMark = "F";
      this.stage = 6 /* VSTAR */;
      this.cardType = [7 /* DARK */];
      this.hp = 270;
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [
        {
          name: "Star Abyss",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "During your turn, you may put up to 2 Item cards from your discard pile into your hand. (You can't use more than 1 VSTAR Power in a game.)"
        }
      ];
      this.attacks = [
        {
          name: "Dark Pulse",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 30,
          text: 'This attack does 30 more damage for each <span class="energy-symbol">[D]</span> Energy attached to all of your Pok\xE9mon.'
        }
      ];
      this.set = "ASR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "99";
      this.name = "Darkrai VSTAR";
      this.fullName = "Darkrai VSTAR ASR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.usedVSTAR === true) {
          throw new GameError(GameMessage.LABEL_VSTAR_USED);
        }
        const hasItem = player.discard.cards.some((c) => {
          return c instanceof TrainerCard && c.trainerType === 0 /* ITEM */;
        });
        if (!hasItem) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const discardEffect = new DiscardToHandEffect(player, this);
        store.reduceEffect(state, discardEffect);
        if (discardEffect.preventDefault) {
          player.usedVSTAR = true;
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          return state;
        }
        player.usedVSTAR = true;
        let cards = [];
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.discard,
            { superType: 2 /* TRAINER */, trainerType: 0 /* ITEM */ },
            { min: 1, max: 2, allowCancel: true }
          ),
          (selected) => {
            cards = selected || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, player.discard, player.hand, {
                cards,
                sourceCard: this,
                sourceEffect: this.powers[0]
              });
            }
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.addBoardEffect(0 /* ABILITY_USED */);
              }
            });
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let energies = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergyEffect);
          checkProvidedEnergyEffect.energyMap.forEach((energy2) => {
            if (energy2.provides.includes(7 /* DARK */)) {
              energies += 1;
            }
          });
        });
        effect.damage = 30 + energies * 30;
      }
      return state;
    }
  };

