  var Eevee14 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 50;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [{
        name: "Resonant Evolution",
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, when you play a Pok\xE9mon from your hand to evolve 1 of your other Eevee, you may search your deck for a card that evolves from this Pok\xE9mon and put it onto this Pok\xE9mon to evolve it. Then, shuffle your deck."
      }];
      this.attacks = [
        {
          name: "Tackle",
          cost: [C, C],
          damage: 20,
          text: ""
        }
      ];
      this.RESONANT_EVOLUTION_MARKER = "EEVEE_ASR_RESONANT_EVOLUTION_MARKER";
      this.regulationMark = "F";
      this.set = "ASR";
      this.setNumber = "119";
      this.cardImage = "assets/cardback.png";
      this.name = "Eevee";
      this.fullName = "Eevee ASR 119";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EvolveEffect && effect.player !== void 0 && effect.pokemonCard.evolvesFrom === "Eevee" && !effect.target.cards.includes(this)) {
        const player = effect.player;
        if (HAS_MARKER(this.RESONANT_EVOLUTION_MARKER, player, this)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        let thisEeveeFound = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            thisEeveeFound = true;
          }
        });
        if (!thisEeveeFound) {
          return state;
        }
        if (player.deck.cards.length === 0) {
          return state;
        }
        store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (!wantToUse) {
            return;
          }
          ADD_MARKER(this.RESONANT_EVOLUTION_MARKER, player, this);
          let cards = [];
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_EVOLVE,
            player.deck,
            { superType: 1 /* POKEMON */, evolvesFrom: "Eevee" },
            { min: 0, max: 1, allowCancel: true }
          ), (selected) => {
            cards = selected || [];
            if (cards.length > 0) {
              const evolutionCard = cards[0];
              player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
                if (cardList.getPokemonCard() === this) {
                  MOVE_CARDS(store, state, player.deck, cardList, { cards: [evolutionCard], sourceCard: this });
                  cardList.clearEffects();
                  cardList.pokemonPlayedTurn = state.turn;
                }
              });
            }
            SHUFFLE_DECK(store, state, player);
          });
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.RESONANT_EVOLUTION_MARKER, this);
      return state;
    }
  };

