  var Gallade6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "F";
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Kirlia";
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 160;
      this.weakness = [{ type: 7 /* DARK */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -30 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Buddy Catch",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may search your deck for a Supporter card, reveal it, and put it into your hand. Then, shuffle your deck."
      }];
      this.attacks = [
        {
          name: "Swirling Slice",
          cost: [5 /* PSYCHIC */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 160,
          text: "Move an Energy from this Pok\xE9mon to 1 of your Benched Pok\xE9mon"
        }
      ];
      this.set = "ASR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "62";
      this.name = "Gallade";
      this.fullName = "Gallade ASR";
      this.BUDDY_CATCH_MARKER = "BUDDY_CATCH_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        const blockedFrom = [];
        const blockedTo = [];
        if (hasBench === false) {
          return state;
        }
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList === player.active) {
            blockedTo.push(target);
            return;
          }
          blockedFrom.push(target);
        });
        return store.prompt(state, new MoveEnergyPrompt(
          effect.player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, blockedFrom, blockedTo, min: 1, max: 1 }
        ), (transfers) => {
          if (transfers === null) {
            return;
          }
          for (const transfer of transfers) {
            const source = StateUtils.getTarget(state, player, transfer.from);
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.BUDDY_CATCH_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.BUDDY_CATCH_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.BUDDY_CATCH_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.marker.hasMarker(this.BUDDY_CATCH_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.deck,
          { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
          { min: 0, max: 1, allowCancel: false }
        ), (cards) => {
          MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this, sourceEffect: this.powers[0] });
          if (cards.length > 0) {
            state = store.prompt(state, new ShowCardsPrompt(
              opponent.id,
              GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
              cards
            ), () => {
            });
          }
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
            player.marker.addMarker(this.BUDDY_CATCH_MARKER, this);
          });
        });
      }
      return state;
    }
  };

