      this.hp = 140;
      this.weakness = [{ type: M }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Massive Ice",
        powerType: 2 /* ABILITY */,
        text: "This Pok\xE9mon takes 30 less damage from attacks (after applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Mountain Gale",
          cost: [W, W, C, C],
          damage: 100,
          damageCalculation: "+",
          text: "If a Stadium is in play, this attack does 120 more damage. Then, discard that Stadium."
        }
      ];
      this.regulationMark = "F";
      this.set = "ASR";
