  var HisuianDecidueyeVSTAR = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 6 /* VSTAR */;
      this.evolvesFrom = "Hisuian Decidueye V";
      this._tags = ["VSTAR" /* POKEMON_VSTAR */];
      this.regulationMark = "F";
      this.cardType = [F];
      this.hp = 270;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Star of Fortune",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "During your turn, you may draw cards until you have 8 cards in your hand. (You can't use more than 1 VSTAR Power in a game.)"
        }
      ];
      this.attacks = [
        {
          name: "Somersault Feathers",
          cost: [F, C, C],
          damage: 160,
          damageCalculator: "+",
          text: "You may discard up to 3 Energy cards from your hand. This attack does 30 more damage for each card you discarded in this way."
        }
      ];
      this.set = "ASR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "84";
      this.name = "Hisuian Decidueye VSTAR";
      this.fullName = "Hisuian Decidueye VSTAR ASR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.usedVSTAR === true) {
          throw new GameError(GameMessage.LABEL_VSTAR_USED);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        player.usedVSTAR = true;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
        DRAW_CARDS_UNTIL_CARDS_IN_HAND(player, 8);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const attackEffect = effect;
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            { superType: 3 /* ENERGY */ },
            { allowCancel: true, min: 0, max: 3 }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length === 0) {
              return;
            }
            MOVE_CARDS(store, state, player.hand, player.discard, {
              cards,
              sourceCard: this,
              sourceEffect: this.attacks[0]
            });
            attackEffect.damage += cards.length * 30;
          }
        );
      }
      return state;
    }
  };

