  var HisuianLilligantVstar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VSTAR" /* POKEMON_VSTAR */];
      this.stage = 6 /* VSTAR */;
      this.evolvesFrom = "Hisuian Lilligant V";
      this.cardType = [G];
      this.hp = 260;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Star Perfume",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "During your turn, you may search your deck for up to 5 in any combination of Grass Pok\xE9mon and [G] Energy cards, reveal them, and put them into your hand. Then, shuffle your deck. (You can't use more than 1 VSTAR Power in a game.)"
        }
      ];
      this.attacks = [
        {
          name: "Parallel Spin",
          cost: [G, G, C],
          damage: 130,
          damageCalculation: "+",
          text: "You may put an Energy attached to this Pok\xE9mon into your hand. If you do, this attack does 100 more damage."
        }
      ];
      this.regulationMark = "F";
      this.set = "ASR";
      this.setNumber = "18";
      this.cardImage = "assets/cardback.png";
      this.name = "Hisuian Lilligant VSTAR";
      this.fullName = "Hisuian Lilligant VSTAR ASR 18";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.usedVSTAR === true) {
          throw new GameError(GameMessage.LABEL_VSTAR_USED);
        }
        player.usedVSTAR = true;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const blocked = [];
        player.deck.cards.forEach((c, index) => {
          const isGrassPokemon = c instanceof PokemonCard && pokemonHasCardType(c, 1 /* GRASS */);
          const isGrassEnergy = c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.name === "Grass Energy";
          if (!isGrassPokemon && !isGrassEnergy) {
            blocked.push(index);
          }
        });
        let cards = [];
        MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            {},
            { min: 0, max: 5, allowCancel: false, blocked }
          ),
          (selected) => {
            cards = selected || [];
            if (cards.length > 0) {
              SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
            }
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const energyCards = player.active.cards.filter((c) => c.superType === 3 /* ENERGY */);
        if (energyCards.length === 0) {
          return state;
        }
        let cards = [];
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.active,
            { superType: 3 /* ENERGY */ },
            { min: 0, max: 1, allowCancel: false }
          ),
          (selected) => {
            cards = selected || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, player.active, player.hand, { cards, sourceCard: this });
              effect.damage += 100;
            }
          }
        );
      }
      return state;
    }
  };

