  var HisuianSamurott = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Dewott";
      this.regulationMark = "F";
      this.cardType = [D];
      this.hp = 170;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Wily Stance",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "You must discard a card from your hand in order to use this Ability. Once during your turn, you may draw 3 cards."
      }];
      this.attacks = [{
        name: "Dark Mastery",
        cost: [D, C, C],
        damage: 60,
        damageCalculation: "+",
        text: "This attack does 20 more damage for each Energy attached to all of your Pok\xE9mon."
      }];
      this.set = "ASR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "100";
      this.name = "Hisuian Samurott";
      this.fullName = "Hisuian Samurott ASR";
      this.WILY_STANCE_MARKER = "WILY_STANCE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.WILY_STANCE_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.hand.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.WILY_STANCE_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          {},
          { allowCancel: true, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          player.marker.addMarker(this.WILY_STANCE_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
          DRAW_CARDS(store, state, player, 3);
        });
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.WILY_STANCE_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let energies = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergyEffect);
          checkProvidedEnergyEffect.energyMap.forEach((energy2) => {
            energies += energy2.provides.length;
          });
        });
        effect.damage += energies * 20;
      }
      return state;
    }
  };

