  var HisuianSamurottV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [7 /* DARK */];
      this.hp = 220;
      this._tags = ["V" /* POKEMON_V */];
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Basket Crash",
          cost: [7 /* DARK */],
          damage: 0,
          text: "Discard up to 2 Pok\xE9mon Tools from your opponent's Pok\xE9mon."
        },
        {
          name: "Shadow Slash",
          cost: [7 /* DARK */, 7 /* DARK */, 7 /* DARK */],
          damage: 180,
          text: "Discard an Energy from this Pok\xE9mon."
        }
      ];
      this.set = "ASR";
      this.regulationMark = "F";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "101";
      this.name = "Hisuian Samurott V";
      this.fullName = "Hisuian Samurott V ASR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let pokemonsWithTool = 0;
        const blocked = [];
        const validTargets = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList.tools.length > 0) {
            pokemonsWithTool += 1;
            validTargets.push(cardList);
          } else {
            blocked.push(target);
          }
        });
        if (pokemonsWithTool === 0) {
          return state;
        }
        const max = Math.min(2, pokemonsWithTool);
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DISCARD_CARDS,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 1, max, allowCancel: false, blocked }
          ),
          (results) => {
            const chosenPokemons = results || [];
            if (chosenPokemons.length === 0) {
              return state;
            }
            if (chosenPokemons.length === 1 && chosenPokemons[0].tools.length > 1) {
              const toolList = new CardList();
              toolList.cards = [...chosenPokemons[0].tools];
              return store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_DISCARD,
                  // You may want a new message for 'choose tool(s) to discard'
                  toolList,
                  { trainerType: 3 /* TOOL */ },
                  { min: 1, max: 2, allowCancel: false }
                ),
                (selectedTools) => {
                  if (selectedTools && selectedTools.length > 0) {
                    const owner = StateUtils.findOwner(state, chosenPokemons[0]);
                    selectedTools.forEach((tool) => {
                      MOVE_CARDS(store, state, chosenPokemons[0], owner.discard, { cards: [tool], sourceCard: this });
                    });
                  }
                  return state;
                }
              );
            }
            chosenPokemons.forEach((pokemon) => {
              if (pokemon.tools.length === 1) {
                const owner = StateUtils.findOwner(state, pokemon);
                MOVE_CARDS(store, state, pokemon, owner.discard, { cards: [pokemon.tools[0]], sourceCard: this });
              } else if (pokemon.tools.length > 1) {
                const toolList = new CardList();
                toolList.cards = [...pokemon.tools];
                store.prompt(
                  state,
                  new ChooseCardsPrompt(
                    player,
                    GameMessage.CHOOSE_CARD_TO_DISCARD,
                    // You may want a new message for 'choose tool to discard'
                    toolList,
                    { trainerType: 3 /* TOOL */ },
                    { min: 1, max: 1, allowCancel: false }
                  ),
                  (selectedTools) => {
                    if (selectedTools && selectedTools.length === 1) {
                      const tool = selectedTools[0];
                      const owner = StateUtils.findOwner(state, pokemon);
                      MOVE_CARDS(store, state, pokemon, owner.discard, { cards: [tool], sourceCard: this });
                    }
                    return state;
                  }
                );
              }
            });
            return state;
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1);
      }
      return state;
    }
  };

