  init_prefabs();
  var Hoothoot6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 50;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Stand Sentry",
        powerType: 2 /* ABILITY */,
        text: "Basic Energy attached to your Benched Pok\xE9mon can't be discarded by an effect of your opponent's Item or Supporter cards."
      }];
      this.attacks = [
        {
          name: "Flap",
          cost: [C, C],
          damage: 20,
          text: ""
        }
      ];
      this.regulationMark = "F";
      this.set = "ASR";
      this.setNumber = "120";
      this.cardImage = "assets/cardback.png";
      this.name = "Hoothoot";
      this.fullName = "Hoothoot ASR 120";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof MoveCardsEffect) {
        const cards = effect.cards || [];
        const hasBasicEnergy = cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.superType === 3 /* ENERGY */
        );
        if (!hasBasicEnergy) {
          return state;
        }
        let sourceOwner = null;
        try {
          sourceOwner = StateUtils.findOwner(state, effect.source);
        } catch {
          return state;
        }
        if (!sourceOwner) {
          return state;
        }
        const isFromBench = sourceOwner.bench.some((b) => b === effect.source);
        if (!isFromBench) {
          return state;
        }
        const isToDiscard = state.players.some((p) => p.discard === effect.destination);
        if (!isToDiscard) {
          return state;
        }
        const sourceCard = effect.sourceCard;
        if (!sourceCard) {
          return state;
        }
        if (!(sourceCard instanceof TrainerCard)) {
          return state;
        }
        if (sourceCard.trainerType !== 0 /* ITEM */ && sourceCard.trainerType !== 1 /* SUPPORTER */) {
          return state;
        }
        let trainerOwner = null;
        try {
          trainerOwner = StateUtils.findOwner(state, StateUtils.findCardList(state, sourceCard));
        } catch {
          return state;
        }
        if (trainerOwner === sourceOwner) {
          return state;
        }
        const hoothootBenched = sourceOwner.bench.some(
          (b) => b.getPokemonCard() === this && !IS_ABILITY_BLOCKED(store, state, sourceOwner, this)
        );
        if (!hoothootBenched) {
          return state;
        }
        effect.cards = cards.filter(
          (c) => !(c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.superType === 3 /* ENERGY */)
        );
        if (effect.cards.length === 0) {
          effect.preventDefault = true;
        }
      }
      return state;
    }
  };

