  var JirachiV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 180;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Wish Connector",
          powerType: 2 /* ABILITY */,
          text: "When 1 of your Basic Pok\xE9mon V is Knocked Out by damage from an attack from your opponent's Pok\xE9mon, you may move a basic Energy card from that Pok\xE9mon to another of your Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Hypnostrike",
          cost: [P, C],
          damage: 60,
          text: "Both Active Pok\xE9mon are now Asleep."
        }
      ];
      this.regulationMark = "F";
      this.set = "ASR";
      this.setNumber = "170";
      this.cardImage = "assets/cardback.png";
      this.name = "Jirachi V";
      this.fullName = "Jirachi V ASR 170";
      this.WISH_CONNECTOR_MARKER = "JIRACHI_V_ASR_WISH_CONNECTOR_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const target = effect.target;
        if (state.phase !== 3 /* ATTACK */ || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        const pokemonCard = target.getPokemonCard();
        if (!pokemonCard || !pokemonCard.hasTag("V" /* POKEMON_V */) || pokemonCard.stage !== 2 /* BASIC */) {
          return state;
        }
        const isJirachiBenched = player.bench.some(
          (b) => b.getPokemonCard() === this && b !== target
        );
        const isJirachiActive = player.active.getPokemonCard() === this && player.active !== target;
        if (!isJirachiBenched && !isJirachiActive) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (target.marker.hasMarker(this.WISH_CONNECTOR_MARKER, this)) {
          return state;
        }
        const hasBasicEnergy = target.cards.some(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
        );
        if (!hasBasicEnergy) {
          return state;
        }
        target.marker.addMarker(this.WISH_CONNECTOR_MARKER, this);
        const targetCopy = new PokemonCardList();
        targetCopy.cards = target.cards.slice();
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, t) => {
          if (cardList === target) {
            blockedTo.push(t);
          }
        });
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            targetCopy,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: true, min: 0, max: 1, differentTargets: false, blockedTo }
          ),
          (transfers) => {
            transfers = transfers || [];
            target.marker.removeMarker(this.WISH_CONNECTOR_MARKER, this);
            for (const transfer of transfers) {
              const t = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, t, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_ASLEEP(store, state, effect);
        ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, player, this);
      }
      return state;
    }
  };

