  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-astral-radiance/kleavor-vstar.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_prefabs();
  var KleavorVstar = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VSTAR" /* POKEMON_VSTAR */];
      this.stage = 6 /* VSTAR */;
      this.evolvesFrom = "Kleavor V";
      this.cardType = [F];
      this.hp = 270;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Axe Break",
          cost: [F, C],
          damage: 120,
          text: "This attack also does 60 damage to 1 of your opponent's Benched Pok\xE9mon V. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Rampaging Star",
          cost: [F],
          damage: 30,
          damageCalculation: "x",
          text: "This attack does 30 damage for each Pok\xE9mon in your discard pile. (You can't use more than 1 VSTAR Power in a game.)"
        }
      ];
      this.regulationMark = "F";
      this.set = "ASR";
      this.setNumber = "196";
      this.cardImage = "assets/cardback.png";
      this.name = "Kleavor VSTAR";
      this.fullName = "Kleavor VSTAR ASR 196";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let hasBenchedV = false;
        opponent.bench.forEach((benchSpot) => {
          const card = benchSpot.getPokemonCard();
          if (card && (card.hasTag("V" /* POKEMON_V */) || card.hasTag("VMAX" /* POKEMON_VMAX */) || card.hasTag("VSTAR" /* POKEMON_VSTAR */))) {
            hasBenchedV = true;
          }
        });
        if (!hasBenchedV) {
          return state;
        }
        const blocked = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (list, card, target) => {
          if (!card.hasTag("V" /* POKEMON_V */) && !card.hasTag("VMAX" /* POKEMON_VMAX */) && !card.hasTag("VSTAR" /* POKEMON_VSTAR */)) {
            blocked.push(target);
          }
        });
        state = store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const damageEffect = new PutDamageEffect(effect, 60);
            damageEffect.target = targets[0];
            store.reduceEffect(state, damageEffect);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        if (player.usedVSTAR === true) {
          throw new GameError(GameMessage.LABEL_VSTAR_USED);
        }
        player.usedVSTAR = true;
        const pokemonCount = player.discard.cards.filter(
          (c) => c.superType === 1 /* POKEMON */
        ).length;
        effect.damage = 30 * pokemonCount;
      }
      return state;
    }
  };

