  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-astral-radiance/kricketune.ts
  init_game();
  init_check_effects();
  init_prefabs();
  var Kricketune4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Kricketot";
      this.cardType = [G];
      this.hp = 90;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Swelling Tune",
          powerType: 2 /* ABILITY */,
          text: "Your [G] Pok\xE9mon in play, except any Kricketune, get +40 HP. You can't apply more than 1 Swelling Tune Ability at a time."
        }
      ];
      this.attacks = [
        {
          name: "Slash",
          cost: [G, C],
          damage: 50,
          text: ""
        }
      ];
      this.set = "ASR";
      this.regulationMark = "F";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "10";
      this.name = "Kricketune";
      this.fullName = "Kricketune ASR";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckHpEffect) {
        const cardList = StateUtils.findCardList(state, this);
        const player = StateUtils.findOwner(state, cardList);
        const isInPlay = player.active.cards.includes(this) || player.bench.some((b) => b.cards.includes(this));
        if (!isInPlay) {
          return state;
        }
        if (effect.nonstackingBoosts.includes(this.powers[0].name)) {
          return state;
        }
        if (effect.player.id !== player.id) {
          return state;
        }
        const targetPokemonCard = effect.target.getPokemonCard();
        if (!targetPokemonCard) {
          return state;
        }
        const checkPokemonTypeEffect = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkPokemonTypeEffect);
        if (!checkPokemonTypeEffect.cardTypes.includes(1 /* GRASS */) || targetPokemonCard.name === "Kricketune") {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.hp += 40;
        effect.nonstackingBoosts.push(this.powers[0].name);
      }
      return state;
    }
  };

