  var Magnezone7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Magneton";
      this.cardType = [8 /* METAL */];
      this.hp = 150;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.resistance = [{ type: 1 /* GRASS */, value: -30 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Giga Magnet",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may look at the top 6 cards of your deck and attach any number of [M] Energy cards you find there to your Pok\xE9mon in any way you like. Shuffle the other cards back into your deck."
      }];
      this.attacks = [{
        name: "Power Beam",
        cost: [8 /* METAL */, 9 /* COLORLESS */, 9 /* COLORLESS */],
        damage: 120,
        text: ""
      }];
      this.regulationMark = "F";
      this.set = "ASR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "107";
      this.name = "Magnezone";
      this.fullName = "Magnezone ASR";
      this.GIGA_MAGNET_MARKER = "GIGA_MAGNET_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.GIGA_MAGNET_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.GIGA_MAGNET_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const temp = new CardList();
        if (player.marker.hasMarker(this.GIGA_MAGNET_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.deck.cards.length == 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        MOVE_CARDS(store, state, player.deck, temp, { count: 6, sourceCard: this });
        const metalEnergyCards = temp.cards.filter(
          (card) => card instanceof EnergyCard && card.name === "Metal Energy"
        );
        if (metalEnergyCards.length === 0) {
          return store.prompt(state, new ShowCardsPrompt(
            player.id,
            GameMessage.CARDS,
            temp.cards
          ), () => {
            MOVE_CARDS(store, state, temp, player.deck, { sourceCard: this });
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
              return state;
            });
          });
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          temp,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, name: "Metal Energy" },
          { min: 0, max: metalEnergyCards.length }
        ), (transfers) => {
          if (transfers) {
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, temp, target, { cards: [transfer.card], sourceCard: this });
            }
          }
          player.marker.addMarker(this.GIGA_MAGNET_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          MOVE_CARDS(store, state, temp, player.deck, { sourceCard: this });
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
            return state;
          });
        });
      }
      return state;
    }
  };

