  var OranguruV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 210;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Back Order",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, if this Pok\xE9mon is in the Active Spot, you may search your deck for up to 2 Pok\xE9mon Tool cards, reveal them, and put them into your hand. Then, shuffle your deck."
        }
      ];
      this.attacks = [
        {
          name: "Psychic",
          cost: [C, C, C],
          damage: 30,
          damageCalculation: "+",
          text: "This attack does 50 more damage for each Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.regulationMark = "F";
      this.set = "ASR";
      this.setNumber = "133";
      this.cardImage = "assets/cardback.png";
      this.name = "Oranguru V";
      this.fullName = "Oranguru V ASR";
      this.BACK_ORDER_MARKER = "BACK_ORDER_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.BACK_ORDER_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.BACK_ORDER_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.active.getPokemonCard() !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        player.marker.addMarker(this.BACK_ORDER_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
        const blocked = [];
        player.deck.cards.forEach((c, index) => {
          if (!(c instanceof TrainerCard && c.trainerType === 3 /* TOOL */)) {
            blocked.push(index);
          }
        });
        SEARCH_DECK_FOR_CARDS_TO_HAND(
          store,
          state,
          player,
          this,
          { superType: 2 /* TRAINER */ },
          { min: 0, max: 2, allowCancel: false, blocked },
          this.powers[0]
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentProvidedEnergy = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, opponentProvidedEnergy);
        const opponentEnergyCount = opponentProvidedEnergy.energyMap.reduce(
          (left, p) => left + p.provides.length,
          0
        );
        effect.damage += opponentEnergyCount * 50;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.BACK_ORDER_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.BACK_ORDER_MARKER, this);
      }
      return state;
    }
  };

