  init_game_phase_effects();
  init_prefabs();
  var RadiantGreninja = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Radiant" /* RADIANT */];
      this.stage = 2 /* BASIC */;
      this.cardType = [3 /* WATER */];
      this.hp = 130;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [
        {
          name: "Concealed Cards",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "You must discard an Energy card from your hand in order to use this ability. Once during your turn, you may draw 2 cards."
        }
      ];
      this.attacks = [
        {
          name: "Moonlight Shuriken",
          cost: [3 /* WATER */, 3 /* WATER */, 9 /* COLORLESS */],
          damage: 0,
          text: "Discard 2 energy from this Pok\xE9mon. This attack does 90 damage to 2 of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.regulationMark = "F";
      this.set = "ASR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "46";
      this.name = "Radiant Greninja";
      this.fullName = "Radiant Greninja ASR";
      this.CONCEALED_CARDS_MARKER = "CONCEALED_CARDS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.CONCEALED_CARDS_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.CONCEALED_CARDS_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.CONCEALED_CARDS_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c.superType === 3 /* ENERGY */;
        });
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.CONCEALED_CARDS_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            { superType: 3 /* ENERGY */ },
            { allowCancel: true, min: 1, max: 1 }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length === 0) {
              return;
            }
            player.marker.addMarker(this.CONCEALED_CARDS_MARKER, this);
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.addBoardEffect(0 /* ABILITY_USED */);
              }
            });
            MOVE_CARDS(store, state, player.hand, player.discard, {
              cards,
              sourceCard: this,
              sourceEffect: this.powers[0]
            });
            DRAW_CARDS(store, state, player, 2);
          }
        );
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentTargets = [opponent.active, ...opponent.bench].filter(
          (p) => p.cards.length > 0
        );
        const numTargets = opponentTargets.length;
        const minMax = numTargets >= 2 ? 2 : 1;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(
          state,
          new ChooseEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            checkProvidedEnergy.energyMap,
            [9 /* COLORLESS */, 9 /* COLORLESS */],
            { allowCancel: false }
          ),
          (energy2) => {
            const cards = (energy2 || []).map((e) => e.card);
            const discardEnergy2 = new DiscardCardsEffect(effect, cards);
            discardEnergy2.target = player.active;
            store.reduceEffect(state, discardEnergy2);
          }
        );
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: minMax, max: minMax, allowCancel: false }
          ),
          (selected) => {
            const targets = selected || [];
            DAMAGE_OPPONENT_POKEMON(store, state, effect, 90, targets);
          }
        );
      }
      return state;
    }
  };

