  var RadiantHawlucha = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Radiant" /* RADIANT */];
      this.cardType = [6 /* FIGHTING */];
      this.hp = 90;
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [
        {
          name: "Big Match",
          powerType: 2 /* ABILITY */,
          text: "As long as this Pok\xE9mon is on your Bench, your Pok\xE9mon's attacks do 30 more damage to your opponent's Active Pok\xE9mon VMAX (before applying Weakness and Resistance)."
        }
      ];
      this.attacks = [
        {
          name: "Spiral Kick",
          cost: [6 /* FIGHTING */, 9 /* COLORLESS */],
          damage: 50,
          text: ""
        }
      ];
      this.regulationMark = "F";
      this.set = "ASR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "81";
      this.name = "Radiant Hawlucha";
      this.fullName = "Radiant Hawlucha ASR";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, effect.player);
        const hawluchaOnBench = player.bench.some((b) => b.getPokemonCard() === this);
        if (!hawluchaOnBench) {
          return state;
        }
        if (effect.target !== opponent.active) {
          return state;
        }
        const targetCard2 = effect.target.getPokemonCard();
        if (targetCard2 && targetCard2.hasTag("VMAX" /* POKEMON_VMAX */)) {
          effect.damage += 30;
        }
      }
      return state;
    }
  };

