  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-astral-radiance/regice.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  function* useRegiGate(next, store, state, effect, self) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const max = Math.min(slots2.length, 1);
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
        player.deck,
        { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
        { min: 0, max, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      MOVE_CARDS(store, state, player.deck, slots2[index], {
        cards: [card],
        sourceCard: self,
        sourceEffect: self.attacks[0]
      });
      slots2[index].pokemonPlayedTurn = state.turn;
    });
    SHUFFLE_DECK(store, state, player);
  }
  var Regice4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: M }];
      this.resistance = [];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Regi Gate",
          cost: [C],
          damage: 0,
          text: "Search your deck for a Basic Pok\xE9mon and put it onto your Bench. Then, shuffle your deck."
        },
        {
          name: "Blizzard Bind",
          cost: [W, W, C],
          damage: 100,
          text: "If the Defending Pok\xE9mon is a Pok\xE9mon V, it can't attack during your opponent's next turn."
        }
      ];
      this.regulationMark = "F";
      this.set = "ASR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "37";
      this.name = "Regice";
      this.fullName = "Regice ASR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const generator = useRegiGate(() => generator.next(), store, state, effect, this);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const defendingPokemon = effect.player.active.getPokemonCard();
        if (defendingPokemon?.hasTag("V" /* POKEMON_V */)) {
          return DEFENDING_POKEMON_CANNOT_ATTACK(store, state, effect, this);
        }
      }
      return state;
    }
  };

