  var Thievul = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Nickit";
      this.cardType = [D];
      this.hp = 100;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Baffling",
          powerType: 2 /* ABILITY */,
          text: "If your opponent has 2 or fewer Prize cards remaining, whenever your opponent plays a Supporter card from their hand, prevent all effects of that card done to your Benched Pok\xE9mon V."
        }
      ];
      this.attacks = [
        {
          name: "Sharp Fang",
          cost: [D, D, C],
          damage: 110,
          text: ""
        }
      ];
      this.regulationMark = "F";
      this.set = "ASR";
      this.setNumber = "104";
      this.cardImage = "assets/cardback.png";
      this.name = "Thievul";
      this.fullName = "Thievul ASR 104";
    }
    reduceEffect(store, state, effect) {
      if (IS_TRAINER_TARGET(effect, { trainerType: 1 /* SUPPORTER */ })) {
        const target = effect.target;
        let thievulOwner = null;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              thievulOwner = p;
            }
          });
        });
        if (!thievulOwner) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, thievulOwner, this)) {
          return state;
        }
        const opponent = effect.player;
        if (opponent === thievulOwner) {
          return state;
        }
        const opponentRemainingPrizes = opponent.prizes.filter((p) => p.cards.length > 0).length;
        if (opponentRemainingPrizes > 2) {
          return state;
        }
        let targetIsOurBenchedV = false;
        thievulOwner.bench.forEach((benchSlot) => {
          if (benchSlot === target) {
            const pokemon = benchSlot.getPokemonCard();
            if (pokemon && (pokemon.hasTag("V" /* POKEMON_V */) || pokemon.hasTag("VMAX" /* POKEMON_VMAX */) || pokemon.hasTag("VSTAR" /* POKEMON_VSTAR */))) {
              targetIsOurBenchedV = true;
            }
          }
        });
        if (targetIsOurBenchedV) {
          BLOCK_TRAINER_TARGET(effect);
        }
      }
      return state;
    }
  };

