  var VirizionV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 200;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Verdant Wind",
          powerType: 2 /* ABILITY */,
          text: "Each of your Pok\xE9mon that has any [G] Energy attached to it can't be affected by any Special Conditions. (Remove any Special Conditions affecting those Pok\xE9mon.)"
        }
      ];
      this.attacks = [
        {
          name: "Emerald Blade",
          cost: [G, G, C],
          damage: 200,
          text: "During your next turn, this Pok\xE9mon can't attack."
        }
      ];
      this.regulationMark = "F";
      this.set = "ASR";
      this.setNumber = "164";
      this.cardImage = "assets/cardback.png";
      this.name = "Virizion V";
      this.fullName = "Virizion V ASR 164";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          let virizionInPlay = false;
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
            if (card === this) {
              virizionInPlay = true;
            }
          });
          if (!virizionInPlay) {
            return;
          }
          if (IS_ABILITY_BLOCKED(store, state, player, this)) {
            return;
          }
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.specialConditions.length === 0) {
              return;
            }
            const checkEnergy = new CheckProvidedEnergyEffect(player, cardList);
            store.reduceEffect(state, checkEnergy);
            const hasGrassEnergy = checkEnergy.energyMap.some(
              (em) => em.provides.includes(1 /* GRASS */)
            );
            if (hasGrassEnergy) {
              const conditions = cardList.specialConditions.slice();
              conditions.forEach((condition) => {
                cardList.removeSpecialCondition(condition);
              });
            }
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        player.active.cannotAttackNextTurnPending = true;
      }
      return state;
    }
  };

