  var Cyllene = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "F";
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "ASR";
      this.setNumber = "138";
      this.cardImage = "assets/cardback.png";
      this.name = "Cyllene";
      this.fullName = "Cyllene ASR";
      this.text = "Flip 2 coins. Put a number of cards up to the number of heads from your discard pile on top of your deck in any order.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let cards = [];
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        let heads = 0;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          results.forEach((r) => {
            heads += r ? 1 : 0;
          });
          if (heads === 0) {
            return state;
          }
          const deckTop = new CardList();
          store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARDS_TO_PUT_ON_TOP_OF_THE_DECK,
              player.discard,
              {},
              { min: Math.min(heads, player.discard.cards.length), max: heads, allowCancel: false }
            ),
            (selected) => {
              cards = selected || [];
              const trainerCards = cards.filter((card) => card instanceof TrainerCard);
              const nonTrainerCards = cards.filter((card) => !(card instanceof TrainerCard));
              let canMoveTrainerCards = true;
              if (trainerCards.length > 0) {
                const discardEffect = new TrainerToDeckEffect(player, this);
                store.reduceEffect(state, discardEffect);
                canMoveTrainerCards = !discardEffect.preventDefault;
              }
              const cardsToMove = canMoveTrainerCards ? cards : nonTrainerCards;
              if (cardsToMove.length > 0) {
                cardsToMove.forEach((card) => {
                  let canMoveCard = true;
                  try {
                    store.reduceEffect(
                      state,
                      new MoveCardsEffect(player.discard, player.deck, { cards: [card] })
                    );
                  } catch {
                    canMoveCard = false;
                  }
                  if (canMoveCard) {
                    MOVE_CARDS(store, state, player.discard, deckTop, {
                      cards: [card],
                      sourceCard: this
                    });
                  }
                });
                return store.prompt(
                  state,
                  new OrderCardsPrompt(player.id, GameMessage.CHOOSE_CARDS_ORDER, deckTop, {
                    allowCancel: false
                  }),
                  (order) => {
                    if (order === null) {
                      return state;
                    }
                    deckTop.applyOrder(order);
                    deckTop.moveToTopOfDestination(player.deck);
                    if (cardsToMove.length > 0) {
                      return store.prompt(
                        state,
                        new ShowCardsPrompt(
                          opponent.id,
                          GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                          cardsToMove
                        ),
                        () => state
                      );
                    }
                    return state;
                  }
                );
              }
              return state;
            }
          );
        });
      }
      return state;
    }
  };

