  function* playCard179(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    const format = store.handler.format;
    let pokemons = 0;
    let itemsOrTools = 0;
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      if (c instanceof PokemonCard && pokemonHasCardType(c, 3 /* WATER */)) {
        pokemons += 1;
      } else if (c instanceof TrainerCard && (c.trainerType === 0 /* ITEM */ || format === 13 /* SWSH */ && c.trainerType === 3 /* TOOL */)) {
        itemsOrTools += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxPokemons = Math.min(pokemons, 1);
    const maxItemsOrTools = Math.min(itemsOrTools, 1);
    const count = maxPokemons + maxItemsOrTools;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        {},
        { min: 0, max: count, allowCancel: false, blocked, maxPokemons, maxItems: maxItemsOrTools }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
