  var ChoiceBelt = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "PAL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "176";
      this.regulationMark = "G";
      this.name = "Choice Belt";
      this.fullName = "Choice Belt PAL";
      this.text = "The attacks of the Pok\xE9mon this card is attached to do 30 more damage to your opponent's Active Pok\xE9mon V (before applying Weakness and Resistance).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.source.tools.includes(this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, effect.player);
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        if (effect.target !== player.active && effect.target !== opponent.active) {
          return state;
        }
        const targetCard2 = effect.target.getPokemonCard();
        if (targetCard2 && targetCard2.hasTag("V" /* POKEMON_V */) || targetCard2 && targetCard2.hasTag("VMAX" /* POKEMON_VMAX */) || targetCard2 && targetCard2.hasTag("VSTAR" /* POKEMON_VSTAR */)) {
          const attack3 = effect.attack;
          if (attack3 && attack3.damage > 0 && effect.target === opponent.active) {
            effect.damage += 30;
          }
        }
        return state;
      }
      return state;
    }
  };

