  var GalarianMoltresV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.regulationMark = "E";
      this.cardType = [7 /* DARK */];
      this._tags = ["V" /* POKEMON_V */];
      this.hp = 220;
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [
        {
          name: "Direflame Wings",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may attach a [D] Energy card from your discard pile to this Pok\xE9mon. You can't use more than 1 Direflame Wings Ability each turn."
        }
      ];
      this.attacks = [
        {
          name: "Aura Burn",
          cost: [7 /* DARK */, 7 /* DARK */, 9 /* COLORLESS */],
          damage: 190,
          text: "This Pok\xE9mon also does 30 damage to itself."
        }
      ];
      this.set = "CRE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "97";
      this.name = "Galarian Moltres V";
      this.fullName = "Galarian Moltres V CRE 97";
      this.DIREFLAME_WINGS_MARKER = "DIREFLAME_WINGS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.DIREFLAME_WINGS_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.DIREFLAME_WINGS_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(7 /* DARK */);
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const cardList = StateUtils.findCardList(state, this);
        if (cardList === void 0) {
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_ATTACH,
            player.discard,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Darkness Energy" },
            { min: 0, max: 1, allowCancel: true }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length > 0) {
              player.marker.addMarker(this.DIREFLAME_WINGS_MARKER, this);
              MOVE_CARDS(store, state, player.discard, cardList, {
                cards,
                sourceCard: this,
                sourceEffect: this.powers[0]
              });
            }
          }
        );
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.DIREFLAME_WINGS_MARKER, this)) {
        effect.player.marker.removeMarker(this.DIREFLAME_WINGS_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const dealDamage = new DealDamageEffect(effect, 30);
        dealDamage.target = player.active;
        return store.reduceEffect(state, dealDamage);
      }
      return state;
    }
  };

