  var ZacianV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["V" /* POKEMON_V */];
      this.cardType = [M];
      this.hp = 220;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.resistance = [{ type: G, value: -30 }];
      this.powers = [
        {
          name: "Intrepid Sword",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may look at the top 3 cards of your deck and attach any number of [M] Energy cards you find there to this Pok\xE9mon. Put the other cards into your hand. If you use this Ability, your turn ends."
        }
      ];
      this.attacks = [
        {
          name: "Brave Blade",
          cost: [M, M, M],
          damage: 230,
          text: "During your next turn, this Pok\xE9mon can't attack."
        }
      ];
      this.regulationMark = "D";
      this.set = "SSH";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "138";
      this.name = "Zacian V";
      this.fullName = "Zacian V SSH";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const topdecks = new CardList();
        MOVE_CARDS(store, state, player.deck, topdecks, { count: 3, sourceCard: this });
        const zacianSlot = StateUtils.findPokemonSlot(state, this);
        if (!zacianSlot) {
          return state;
        }
        let zacianTarget;
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (list === zacianSlot && card === this) {
            zacianTarget = target;
          } else {
            blockedTo.push(target);
          }
        });
        if (!zacianTarget) {
          return state;
        }
        const metalEnergies = topdecks.cards.filter(
          (card) => card instanceof EnergyCard && card.name === "Metal Energy"
        );
        const metals = metalEnergies.length;
        if (metals === 0) {
          MOVE_CARDS(store, state, topdecks, player.hand, { sourceCard: this });
        } else {
          state = store.prompt(
            state,
            new AttachEnergyPrompt(
              player.id,
              GameMessage.ATTACH_ENERGY_CARDS,
              topdecks,
              2 /* BOTTOM_PLAYER */,
              // Only this Zacian V's slot
              [zacianTarget.slot],
              { superType: 3 /* ENERGY */, name: "Metal Energy" },
              { allowCancel: false, min: 0, max: metals, sameTarget: true, blockedTo }
            ),
            (transfers) => {
              transfers = transfers || [];
              for (const transfer of transfers) {
                if (transfer.to.player === zacianTarget.player && transfer.to.slot === zacianTarget.slot && transfer.to.index === zacianTarget.index) {
                  MOVE_CARDS(store, state, topdecks, StateUtils.getTarget(state, player, transfer.to), { cards: [transfer.card], sourceCard: this });
                }
              }
              MOVE_CARDS(store, state, topdecks, player.hand, { sourceCard: this });
            }
          );
        }
        const endTurnEffect = new EndTurnEffect(player);
        return store.reduceEffect(state, endTurnEffect);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_POKEMON_CANNOT_ATTACK_NEXT_TURN(effect.player);
      }
      return state;
    }
  };

