  var Melony = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CRE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "146";
      this.regulationMark = "E";
      this.name = "Melony";
      this.fullName = "Melony CRE";
      this.text = "Attach a [W] Energy card from your discard pile to 1 of your Pok\xE9mon V. If you do, draw 3 cards.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const hasWaterEnergyInDiscard = player.discard.cards.some(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.name === "Water Energy"
        );
        if (!hasWaterEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        let hasValidTarget = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card) => {
          if (card.hasTag("V" /* POKEMON_V */) || card.hasTag("VSTAR" /* POKEMON_VSTAR */) || card.hasTag("VMAX" /* POKEMON_VMAX */) || card.hasTag("V-UNION" /* POKEMON_VUNION */)) {
            hasValidTarget = true;
          }
        });
        if (!hasValidTarget) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blockedTargets = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (!card.hasTag("V" /* POKEMON_V */) && !card.hasTag("VSTAR" /* POKEMON_VSTAR */) && !card.hasTag("VMAX" /* POKEMON_VMAX */) && !card.hasTag("V-UNION" /* POKEMON_VUNION */)) {
            blockedTargets.push(target);
          }
        });
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { min: 1, max: 1, blocked: blockedTargets }
          ),
          (chosen) => {
            if (!chosen || chosen.length === 0) {
              return state;
            }
            const blockedTo = [];
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
              if (!chosen.includes(list)) {
                blockedTo.push(target);
              }
            });
            state = store.prompt(
              state,
              new AttachEnergyPrompt(
                player.id,
                GameMessage.ATTACH_ENERGY_CARDS,
                player.discard,
                2 /* BOTTOM_PLAYER */,
                [2 /* BENCH */, 1 /* ACTIVE */],
                { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
                { allowCancel: false, min: 1, max: 1, blockedTo }
              ),
              (transfers) => {
                if (!transfers || transfers.length === 0) {
                  return state;
                }
                const transfer = transfers[0];
                const targetList = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, player.discard, targetList, {
                  cards: [transfer.card],
                  sourceCard: this,
                  sourceEffect: effect
                });
                DRAW_CARDS(store, state, player, 3);
              }
            );
          }
        );
      }
      return state;
    }
  };

