  init_pokemon_card();
  init_card_types();
  init_game();
  init_choose_cards_prompt();
  init_prefabs();
  var Aegislash7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Doublade";
      this.cardType = [M];
      this.hp = 150;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Stance Change",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may switch this Pok\xE9mon with an Aegislash in your hand. Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Full Metal Blade",
          cost: [M, M, C],
          damage: 210,
          text: "Discard 2 [M] Energy from this Pok\xE9mon."
        }
      ];
      this.regulationMark = "E";
      this.set = "BST";
      this.setNumber = "107";
      this.cardImage = "assets/cardback.png";
      this.name = "Aegislash";
      this.fullName = "Aegislash BST";
      this.STANCE_CHANGE_MARKER = "AEGISLASH_BST_STANCE_CHANGE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const aegislashInHand = player.hand.cards.filter(
          (c) => c instanceof PokemonCard && c.name === "Aegislash"
        );
        if (aegislashInHand.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.STANCE_CHANGE_MARKER, this);
        ABILITY_USED(player, this);
        let cardList = null;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list) => {
          if (list.cards.includes(this)) {
            cardList = list;
          }
        });
        if (cardList === null) {
          return state;
        }
        const currentCardList = cardList;
        const blocked = [];
        player.hand.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || card.name !== "Aegislash") {
            blocked.push(index);
          }
        });
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.hand,
          { superType: 1 /* POKEMON */ },
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            return;
          }
          const newAegislash = selected[0];
          const thisIndex = currentCardList.cards.indexOf(this);
          if (thisIndex !== -1) {
            currentCardList.cards.splice(thisIndex, 1);
            const handIndex = player.hand.cards.indexOf(newAegislash);
            if (handIndex !== -1) {
              player.hand.cards.splice(handIndex, 1);
            }
            currentCardList.cards.splice(thisIndex, 0, newAegislash);
            player.hand.cards.push(this);
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.STANCE_CHANGE_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 2, 8 /* METAL */);
      }
      return state;
    }
  };

