  var Aegislash23 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Doublade";
      this.cardType = [M];
      this.hp = 150;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Stance Change",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may switch this Pok\xE9mon with an Aegislash in your hand. Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Gigaton Bash",
          cost: [M, C],
          damage: 70,
          text: "During your opponent's next turn, prevent all damage done to this Pok\xE9mon by attacks from Pok\xE9mon VMAX."
        }
      ];
      this.regulationMark = "E";
      this.set = "BST";
      this.setNumber = "108";
      this.cardImage = "assets/cardback.png";
      this.name = "Aegislash";
      this.fullName = "Aegislash BST 108";
      this.STANCE_CHANGE_MARKER = "AEGISLASH2_BST_STANCE_CHANGE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const aegislashInHand = player.hand.cards.filter(
          (c) => c instanceof PokemonCard && c.name === "Aegislash" && c !== this
        );
        if (aegislashInHand.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.STANCE_CHANGE_MARKER, this);
        ABILITY_USED(player, this);
        let cardList = null;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list) => {
          if (list.cards.includes(this)) {
            cardList = list;
          }
        });
        if (cardList === null) {
          return state;
        }
        const blocked = [];
        player.hand.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || card.name !== "Aegislash") {
            blocked.push(index);
          }
        });
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.hand,
            { superType: 1 /* POKEMON */ },
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (selected) => {
            if (!selected || selected.length === 0) {
              return;
            }
            const newAegislash = selected[0];
            const thisIndex = cardList.cards.indexOf(this);
            if (thisIndex !== -1) {
              cardList.cards.splice(thisIndex, 1);
              const handIndex = player.hand.cards.indexOf(newAegislash);
              if (handIndex !== -1) {
                player.hand.cards.splice(handIndex, 1);
              }
              if (thisIndex !== -1) {
                cardList.cards.splice(thisIndex, 1);
                const handIndex2 = player.hand.cards.indexOf(newAegislash);
                if (handIndex2 !== -1) {
                  player.hand.cards.splice(handIndex2, 1);
                }
                cardList.cards.splice(thisIndex, 0, newAegislash);
                player.hand.cards.push(this);
              }
            }
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.STANCE_CHANGE_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        PREVENT_DAMAGE(store, state, effect, this, { sourceTags: ["VMAX" /* POKEMON_VMAX */] });
      }
      return state;
    }
  };

