  var Claydol5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Baltoy";
      this.cardType = [P];
      this.hp = 120;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Power Split",
          cost: [C],
          damage: 0,
          text: "Attach [P] Energy cards from your discard pile to your Pok\xE9mon in any way you like until your Pok\xE9mon and your opponent's Pok\xE9mon have the same total amount of Energy attached."
        },
        {
          name: "Psyshot",
          cost: [P, P, C],
          damage: 100,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "BST";
      this.setNumber = "58";
      this.cardImage = "assets/cardback.png";
      this.name = "Claydol";
      this.fullName = "Claydol BST";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let playerEnergyCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const checkEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkEnergy);
          playerEnergyCount += checkEnergy.energyMap.reduce((sum, em) => sum + em.provides.length, 0);
        });
        let opponentEnergyCount = 0;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          const checkEnergy = new CheckProvidedEnergyEffect(opponent, cardList);
          store.reduceEffect(state, checkEnergy);
          opponentEnergyCount += checkEnergy.energyMap.reduce((sum, em) => sum + em.provides.length, 0);
        });
        const diff = opponentEnergyCount - playerEnergyCount;
        if (diff <= 0) {
          return state;
        }
        const psychicEnergyInDiscard = player.discard.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(5 /* PSYCHIC */)
        );
        const maxAttach = Math.min(diff, psychicEnergyInDiscard.length);
        if (maxAttach <= 0) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Psychic Energy" },
          { allowCancel: false, min: maxAttach, max: maxAttach, differentTargets: false }
        ), (transfers) => {
          if (!transfers) return;
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

