  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-battle-styles/emboar.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_prefabs();
  var Emboar5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Single Strike" /* SINGLE_STRIKE */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Pignite";
      this.cardType = [R];
      this.hp = 180;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C, C];
      this.powers = [
        {
          name: "Fighting Fury Stance",
          powerType: 2 /* ABILITY */,
          text: "Your Single Strike Pok\xE9mon's attacks do 30 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance)."
        }
      ];
      this.attacks = [
        {
          name: "Heat Crash",
          cost: [R, R, C, C],
          damage: 130,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "BST";
      this.setNumber = "25";
      this.cardImage = "assets/cardback.png";
      this.name = "Emboar";
      this.fullName = "Emboar BST";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.target === StateUtils.getOpponent(state, effect.player).active) {
        const player = effect.player;
        const attackingPokemon = effect.source.getPokemonCard();
        if (!attackingPokemon || !attackingPokemon.hasTag("Single Strike" /* SINGLE_STRIKE */)) {
          return state;
        }
        let emboarInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            emboarInPlay = true;
          }
        });
        if (!emboarInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.damage += 30;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-battle-styles/empoleon-v.ts
  init_game();
  init_ability_lock();
  init_prefabs();
  var EmpoleonV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */, "Rapid Strike" /* RAPID_STRIKE */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 210;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Emperor's Eyes",
          powerType: 2 /* ABILITY */,
          abilityLock: true,
          text: "As long as this Pok\xE9mon is in the Active Spot, your opponent's Basic Pok\xE9mon in play have no Abilities, except for Pok\xE9mon with a Rule Box (Pok\xE9mon V, Pok\xE9mon-GX, etc. have Rule Boxes)."
        }
      ];
      this.attacks = [
        {
          name: "Swirling Slice",
          cost: [W, C, C],
          damage: 130,
          text: "Move an Energy from this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.regulationMark = "E";
      this.set = "BST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "40";
      this.name = "Empoleon V";
      this.fullName = "Empoleon V BST";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (hasBench === false) {
          return state;
        }
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.active,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 1, max: 1 }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      HANDLE_ABILITY_LOCK(
        effect,
        ({ card }) => {
          const cardList = StateUtils.findCardList(state, this);
          const owner = StateUtils.findOwner(state, cardList);
          const opponent = StateUtils.getOpponent(state, owner);
          if (owner.active.getPokemonCard() !== this) {
            return false;
          }
          let targetBelongsToOpponent = false;
          opponent.forEachPokemon(1 /* TOP_PLAYER */, (_list, pokemon) => {
            if (pokemon === card) {
              targetBelongsToOpponent = true;
            }
          });
          if (!targetBelongsToOpponent) {
            return false;
          }
          const targetCardList = StateUtils.findCardList(state, card);
          if (!(targetCardList instanceof PokemonCardList)) {
            return false;
          }
          if (card.stage !== 2 /* BASIC */) {
            return false;
          }
          if (card.hasRuleBox()) {
            return false;
          }
          return LOCKER_ABILITY_APPLIES(store, state, owner, this, this.powers[0], card);
        },
        {
          allowUseFromHand: true,
          allowUseFromDiscard: true,
          error: GameMessage.BLOCKED_BY_ABILITY
        }
      );
      return state;
    }
  };

