  var Entei5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [R];
      this.hp = 130;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Heat Dash",
          cost: [R],
          damage: 30,
          text: "You may attach a [R] Energy card from your hand to this Pok\xE9mon."
        },
        {
          name: "Fire Fang",
          cost: [R, R, C],
          damage: 90,
          text: "Your opponent's Active Pok\xE9mon is now Burned."
        }
      ];
      this.regulationMark = "E";
      this.set = "BST";
      this.setNumber = "20";
      this.cardImage = "assets/cardback.png";
      this.name = "Entei";
      this.fullName = "Entei BST";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card !== this) {
            blockedTo.push(target);
          }
        });
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_ACTIVE,
          player.hand,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { allowCancel: true, min: 0, max: 1, blockedTo }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            const attachEffect = new AttachEnergyEffect(player, transfer.card, target);
            store.reduceEffect(state, attachEffect);
          }
        });
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        ADD_BURN_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

