  var Houndoom7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Houndour";
      this._tags = ["Single Strike" /* SINGLE_STRIKE */];
      this.cardType = [D];
      this.hp = 130;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Single Strike Roar",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may search your deck for a Single Strike Energy card and attach it to 1 of your Single Strike Pok\xE9mon. Then, shuffle your deck. If you attached Energy to a Pok\xE9mon in this way, put 2 damage counters on that Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Darkness Fang",
          cost: [D, C],
          damage: 50,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "BST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "96";
      this.name = "Houndoom";
      this.fullName = "Houndoom BST";
      this.SINGLE_STRIKE_ROAR_MARKER = "SINGLE_STRIKE_ROAR_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.SINGLE_STRIKE_ROAR_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.SINGLE_STRIKE_ROAR_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const blocked2 = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (!card.hasTag("Single Strike" /* SINGLE_STRIKE */)) {
            blocked2.push(target);
          }
        });
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            {
              superType: 3 /* ENERGY */,
              energyType: 1 /* SPECIAL */,
              name: "Single Strike Energy"
            },
            { allowCancel: false, min: 0, max: 1, blockedTo: blocked2 }
          ),
          (transfers) => {
            transfers = transfers || [];
            ABILITY_USED(player, this);
            if (transfers.length === 0) {
              SHUFFLE_DECK(store, state, player);
              return;
            }
            player.marker.addMarker(this.SINGLE_STRIKE_ROAR_MARKER, this);
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
              SHUFFLE_DECK(store, state, player);
              target.damage += 20;
            }
          }
        );
        return state;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.SINGLE_STRIKE_ROAR_MARKER, this)) {
        effect.player.marker.removeMarker(this.SINGLE_STRIKE_ROAR_MARKER, this);
      }
      return state;
    }
  };

