  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-battle-styles/kingdra.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_game_effects();
  init_prefabs();
  init_attach_energy_prompt();
  init_state();
