  var Kingdra6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Seadra";
      this.cardType = [W];
      this.hp = 150;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.powers = [{
        name: "Deep Sea King",
        powerType: 2 /* ABILITY */,
        text: "When your Active Pok\xE9mon is Knocked Out by damage from an attack from your opponent's Pok\xE9mon, you may move any amount of [W] Energy from that Pok\xE9mon to this Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Aqua Burst",
          cost: [W],
          damage: 40,
          damageCalculation: "x",
          text: "This attack does 40 damage for each [W] Energy attached to this Pok\xE9mon."
        }
      ];
      this.regulationMark = "E";
      this.set = "BST";
      this.setNumber = "33";
      this.cardImage = "assets/cardback.png";
      this.name = "Kingdra";
      this.fullName = "Kingdra BST";
      this.DEEP_SEA_KING_MARKER = "KINGDRA_BST_DEEP_SEA_KING_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target === effect.player.active) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (state.phase !== 3 /* ATTACK */ || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        let kingdraCardList = null;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this && cardList !== effect.target) {
            kingdraCardList = cardList;
          }
        });
        if (!kingdraCardList) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (effect.target.marker.hasMarker(this.DEEP_SEA_KING_MARKER, this)) {
          return state;
        }
        const active = effect.target;
        const waterEnergyCards = active.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(3 /* WATER */)
        );
        if (waterEnergyCards.length === 0) {
          return state;
        }
        active.marker.addMarker(this.DEEP_SEA_KING_MARKER, this);
        const energySnapshot = new CardList();
        energySnapshot.cards = waterEnergyCards.slice();
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList !== kingdraCardList) {
            blockedTo.push(target);
          }
        });
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          energySnapshot,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: true, min: 0, max: waterEnergyCards.length, blockedTo }
        ), (transfers) => {
          transfers = transfers || [];
          active.marker.removeMarker(this.DEEP_SEA_KING_MARKER, this);
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        const waterEnergyCount = checkEnergy.energyMap.reduce((sum, em) => {
          return sum + em.provides.filter((t) => t === 3 /* WATER */ || t === 0 /* ANY */).length;
        }, 0);
        effect.damage = 40 * waterEnergyCount;
      }
      return state;
    }
  };

