  var KricketuneV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.regulationMark = "E";
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 180;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [{
        name: "Exciting Stage",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may draw cards until you have 3 cards in your hand. If this Pok\xE9mon is in the Active Spot, you may draw cards until you have 4 cards in your hand instead. You can't use more than 1 Exciting Stage Ability each turn."
      }];
      this.attacks = [{
        name: "X-Scissor",
        cost: [G, C, C],
        damage: 80,
        text: "Flip a coin. If heads, this attack does 80 more damage."
      }];
      this.set = "BST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "6";
      this.name = "Kricketune V";
      this.fullName = "Kricketune V BST";
      this.EXCITING_STAGE_MARKER = "EXCITING_STAGE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.EXCITING_STAGE_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.EXCITING_STAGE_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.EXCITING_STAGE_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.EXCITING_STAGE_MARKER)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.marker.addMarker(this.EXCITING_STAGE_MARKER, this);
        if (player.active.getPokemonCard() === this) {
          while (player.hand.cards.length < 4) {
            if (player.deck.cards.length === 0) {
              break;
            }
            MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
          }
        } else {
          while (player.hand.cards.length < 3) {
            if (player.deck.cards.length === 0) {
              break;
            }
            MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
          }
        }
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            effect.damage += 80;
          }
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-battle-styles/lickilicky.ts
