  var Lickilicky5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Lickitung";
      this.cardType = [C];
      this.hp = 140;
      this.weakness = [{ type: F }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Selickt",
          cost: [C, C, C],
          damage: 0,
          text: "Your opponent chooses to discard the top 3 cards of their deck or to discard 3 cards from their hand."
        },
        {
          name: "Pitch",
          cost: [C, C, C, C],
          damage: 100,
          text: "Your opponent switches their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon."
        }
      ];
      this.regulationMark = "E";
      this.set = "BST";
      this.setNumber = "114";
      this.cardImage = "assets/cardback.png";
      this.name = "Lickilicky";
      this.fullName = "Lickilicky BST";
      this.usedPitch = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const options = [
          GameMessage.DISCARD_FROM_TOP_OF_DECK,
          GameMessage.CHOOSE_CARD_TO_DISCARD
        ];
        store.prompt(state, new SelectPrompt(
          opponent.id,
          GameMessage.CHOOSE_OPTION,
          options,
          { allowCancel: false }
        ), (choice) => {
          if (choice === 0) {
            DISCARD_TOP_X_CARDS_FROM_YOUR_DECK(store, state, opponent, 3, this, effect);
          } else {
            const discardCount = Math.min(3, opponent.hand.cards.length);
            if (discardCount === 0) return;
            if (opponent.hand.cards.length <= 3) {
              const cards = opponent.hand.cards.slice();
              MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards, sourceCard: this });
            } else {
              store.prompt(state, new ChooseCardsPrompt(
                opponent,
                GameMessage.CHOOSE_CARD_TO_DISCARD,
                opponent.hand,
                {},
                { min: discardCount, max: discardCount, allowCancel: false }
              ), (selected) => {
                const cards = selected || [];
                MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards, sourceCard: this });
              });
            }
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          this.usedPitch = true;
        }
      }
      if (effect instanceof AfterAttackEffect && this.usedPitch) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        this.usedPitch = false;
      }
      if (effect instanceof EndTurnEffect) {
        this.usedPitch = false;
      }
      return state;
    }
  };

