  var Meowstic7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Espurr";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Ear Moves",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may move 1 damage counter from 1 of your Pok\xE9mon to 1 of your opponent's Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Psychic Sphere",
          cost: [P, C],
          damage: 50,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "BST";
      this.setNumber = "61";
      this.cardImage = "assets/cardback.png";
      this.name = "Meowstic";
      this.fullName = "Meowstic BST";
      this.EAR_MOVES_MARKER = "MEOWSTIC_BST_EAR_MOVES_MARKER";
    }
    // Ref: set-silver-tempest/radiant-alakazam.ts (Painful Spoons - once-per-turn ability with MoveDamagePrompt)
    // Ref: set-chilling-reign/agatha.ts (cross-player MoveDamagePrompt - from player's to opponent's)
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const damagedOwnPokemon = [
          ...player.active.damage > 0 ? [player.active] : [],
          ...player.bench.filter((b) => b.cards.length > 0 && b.damage > 0)
        ];
        if (damagedOwnPokemon.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.EAR_MOVES_MARKER, this);
        const maxAllowedDamage = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(opponent, cardList);
          store.reduceEffect(state, checkHpEffect);
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        return store.prompt(state, new MoveDamagePrompt(
          player.id,
          GameMessage.MOVE_DAMAGE,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          maxAllowedDamage,
          { min: 1, max: 1, allowCancel: false, singleSourceTarget: true, singleDestinationTarget: true }
        ), (transfers) => {
          if (!transfers || transfers.length === 0) {
            return;
          }
          for (const transfer of transfers) {
            const source = StateUtils.getTarget(state, player, transfer.from);
            const target = StateUtils.getTarget(state, player, transfer.to);
            if (source.damage >= 10) {
              source.damage -= 10;
              target.damage += 10;
            }
          }
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.EAR_MOVES_MARKER, this);
      return state;
    }
  };

