  var MimikyuV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["V" /* POKEMON_V */];
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 160;
      this.weakness = [
        {
          type: 7 /* DARK */
        }
      ];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [
        {
          name: "Dummmy Doll",
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may prevent all damage done to this Mimikyu V by attacks from your opponent's Pok\xE9mon until the end of your opponent's next turn."
        }
      ];
      this.attacks = [
        {
          name: "Jealous Eyes",
          cost: [5 /* PSYCHIC */],
          damage: 0,
          text: "Put 3 damage counters on your opponent's Active Pok\xE9mon for each Prize card your opponent has taken. "
        }
      ];
      this.set = "BST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "62";
      this.regulationMark = "E";
      this.name = "Mimikyu V";
      this.fullName = "Mimikyu V BST";
      this.DUMMY_DOLL_MARKER = "DUMMY_DOLL_MARKER";
      this.CLEAR_DUMMY_DOLL_MARKER = "CLEAR_DUMMY_DOLL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              const cardList = StateUtils.findCardList(state, this);
              cardList.marker.addMarker(this.DUMMY_DOLL_MARKER, this);
            }
          }
        );
        return state;
      }
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this) && effect.target.marker.hasMarker(this.DUMMY_DOLL_MARKER, this)) {
        effect.preventDefault = true;
        return state;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.DUMMY_DOLL_MARKER, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner !== player) {
          cardList.marker?.removeMarker(this.DUMMY_DOLL_MARKER, this);
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const prizesTaken = 6 - opponent.getPrizeLeft();
        const damagePerPrize = 30 * prizesTaken;
        const damageEffect = new PutCountersEffect(effect, damagePerPrize);
        damageEffect.target = opponent.active;
        store.reduceEffect(state, damageEffect);
      }
      return state;
    }
  };

