  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-battle-styles/primeape.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Primeape6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.evolvesFrom = "Mankey";
      this.stage = 3 /* STAGE_1 */;
      this.cardType = [F];
      this.hp = 120;
      this.weakness = [{ type: P }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: " Field Crush",
          cost: [C],
          damage: 20,
          text: "If your opponent has a Stadium in play, discard it."
        },
        {
          name: "Steamin' Mad Strike",
          cost: [F, F],
          damage: 50,
          damageCalculation: "x",
          text: "This attack does 50 damage for each of your Benched Pok\xE9mon that has any damage counters on it."
        }
      ];
      this.set = "BST";
      this.name = "Primeape";
      this.fullName = "Primeape BST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "67";
      this.regulationMark = "E";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const stadiumCard = StateUtils.getStadiumCard(state);
        if (!stadiumCard) {
          return state;
        }
        const stadiumCardList = StateUtils.findCardList(state, stadiumCard);
        const owner = StateUtils.findOwner(state, stadiumCardList);
        if (owner !== effect.player) {
          DISCARD_A_STADIUM_CARD_IN_PLAY(state);
          return state;
        }
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        let benchPokemonWithDamage = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList === player.active) {
            return;
          }
          if (cardList.damage !== 0) {
            benchPokemonWithDamage++;
          }
        });
        effect.damage = 0;
        THIS_ATTACK_DOES_X_MORE_DAMAGE(effect, store, state, 50 * benchPokemonWithDamage);
      }
      return state;
    }
  };

