  init_game_message();
  init_prefabs();
  var RapidStrikeUrshifuV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */, "Rapid Strike" /* RAPID_STRIKE */];
      this.regulationMark = "E";
      this.stage = 2 /* BASIC */;
      this.cardType = [6 /* FIGHTING */];
      this.hp = 220;
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Strafe",
          cost: [6 /* FIGHTING */],
          damage: 30,
          text: "You may switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Hundred Furious Blows",
          cost: [6 /* FIGHTING */, 6 /* FIGHTING */, 9 /* COLORLESS */],
          damage: 150,
          text: ""
        }
      ];
      this.set = "BST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "87";
      this.name = "Rapid Strike Urshifu V";
      this.fullName = "Rapid Strike Urshifu V BST";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        state = store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              return store.prompt(
                state,
                new ChoosePokemonPrompt(
                  player.id,
                  GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
                  2 /* BOTTOM_PLAYER */,
                  [2 /* BENCH */],
                  { allowCancel: true }
                ),
                (selected) => {
                  if (!selected || selected.length === 0) {
                    return state;
                  }
                  const target = selected[0];
                  player.switchPokemon(target);
                }
              );
            }
            return state;
          }
        );
      }
      return state;
    }
  };

