  init_prefabs();
  var Sandaconda = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Silicobra";
      this.cardType = [F];
      this.hp = 130;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Big Sand Cannon",
          cost: [F],
          damage: 60,
          damageCalculation: "x",
          text: "Discard the top 6 cards of your deck. This attack does 60 damage for each [F] Energy card you discarded in this way."
        },
        {
          name: "Skull Bash",
          cost: [F, F, C],
          damage: 120,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "BST";
      this.setNumber = "82";
      this.cardImage = "assets/cardback.png";
      this.name = "Sandaconda";
      this.fullName = "Sandaconda BST";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const count = Math.min(6, player.deck.cards.length);
        let fightingCount = 0;
        for (let i = 0; i < count; i++) {
          const topCard = player.deck.cards[0];
          MOVE_CARDS(store, state, player.deck, player.discard, { cards: [topCard], sourceCard: this });
          if (topCard instanceof EnergyCard && topCard.energyType === 0 /* BASIC */ && topCard.provides.includes(6 /* FIGHTING */)) {
            fightingCount++;
          }
        }
        effect.damage = 60 * fightingCount;
      }
      return state;
    }
  };

