  var TapuBulu2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 130;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Push Down",
          cost: [G],
          damage: 20,
          text: "Your opponent switches their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon."
        },
        {
          name: "Nature's Judgment",
          cost: [G, G, C],
          damage: 80,
          damageCalculation: "+",
          text: "You may discard all Energy from this Pok\xE9mon. If you do, this attack does 80 more damage."
        }
      ];
      this.regulationMark = "E";
      this.set = "BST";
      this.setNumber = "16";
      this.cardImage = "assets/cardback.png";
      this.name = "Tapu Bulu";
      this.fullName = "Tapu Bulu BST";
      this.usedPushDown = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedPushDown = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedPushDown) {
        this.usedPushDown = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.usedPushDown = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_DISCARD_ENERGY
        ), (wantToDiscard) => {
          if (wantToDiscard) {
            DISCARD_ALL_ENERGY_FROM_POKEMON(store, state, effect, this);
            effect.damage += 80;
          }
        });
      }
      return state;
    }
  };

