  var Bruno = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "E";
      this.set = "BST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "121";
      this.name = "Bruno";
      this.fullName = "Bruno BST";
      this.text = "Shuffle your hand into your deck. Then, draw 4 cards. If any of your Pok\xE9mon were Knocked Out during your opponent's last turn, draw 7 cards instead.";
      this.BRUNO_MARKER = "BRUNO_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const duringTurn = [2 /* PLAYER_TURN */, 3 /* ATTACK */].includes(state.phase);
        if (!duringTurn || state.players[state.activePlayer] !== opponent) return state;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) effect.player.marker.addMarker(this.BRUNO_MARKER, this);
        return state;
      }
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const cardsToDraw = HAS_MARKER(this.BRUNO_MARKER, player, this) ? 7 : 4;
        return SHUFFLE_HAND_INTO_DECK_THEN_DRAW(store, state, player, {
          excludeCard: this,
          drawCount: cardsToDraw
        });
      }
      REMOVE_OPPONENT_LAST_TURN_MARKER_AT_END_OF_TURN(effect, this.BRUNO_MARKER, this);
      return state;
    }
  };

