  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-battle-styles/fan-of-waves.ts
  init_trainer_card();
  init_card_types();
  init_choose_pokemon_prompt();
  init_play_card_effects();
  init_prefabs();
  init_game();
  var FanOfWaves = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "E";
      this._trainerType = 0 /* ITEM */;
      this.set = "BST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "127";
      this.name = "Fan of Waves";
      this.fullName = "Fan of Waves BST";
      this.text = "Put a Special Energy attached to 1 of your opponent's Pok\xE9mon on the bottom of their deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        effect.preventDefault = true;
        let hasPokemonWithEnergy = false;
        const blocked = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target2) => {
          if (cardList.cards.some((c) => c.superType === 3 /* ENERGY */ && 1 /* SPECIAL */)) {
            hasPokemonWithEnergy = true;
          } else {
            blocked.push(target2);
          }
        });
        if (!hasPokemonWithEnergy) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        let targets = [];
        state = store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DISCARD_CARDS,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { allowCancel: false, blocked }
          ),
          (results) => {
            targets = results || [];
          }
        );
        if (targets.length === 0) {
          return state;
        }
        const target = targets[0];
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            target,
            { superType: 3 /* ENERGY */, energyType: 1 /* SPECIAL */ },
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            const cards = selected;
            const opponentDeckBottom = new CardList();
            cards.forEach((card) => {
              MOVE_CARDS(store, state, opponentDeckBottom, opponent.deck, {
                cards: [card],
                sourceCard: this
              });
            });
            return state;
          }
        );
        return state;
      }
      return state;
    }
  };

