  var Phoebe = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "E";
      this.set = "BST";
      this.setNumber = "130";
      this.cardImage = "assets/cardback.png";
      this.name = "Phoebe";
      this.fullName = "Phoebe BST";
      this.text = "During this turn, damage from your Pok\xE9mon VMAX's attacks isn't affected by any effects on your opponent's Active Pok\xE9mon. You may play only 1 Supporter card during your turn.";
      this.PHOEBE_MARKER = "PHOEBE_MARKER";
    }
    // Ref: set-unbroken-bonds/ultra-forest-kartenvoy.ts (Ultra Beast damage not affected by effects on opponent's Active)
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        ADD_MARKER(this.PHOEBE_MARKER, player, this);
      }
      if (effect instanceof AttackEffect && HAS_MARKER(this.PHOEBE_MARKER, effect.player, this)) {
        const sourceCard = effect.player.active.getPokemonCard();
        if (sourceCard && sourceCard.hasTag("VMAX" /* POKEMON_VMAX */)) {
          const opponent = StateUtils.getOpponent(state, effect.player);
          const applyWeakness = new ApplyWeaknessEffect(effect, effect.damage);
          store.reduceEffect(state, applyWeakness);
          const damage = applyWeakness.damage;
          effect.damage = 0;
          if (damage > 0) {
            opponent.active.damage += damage;
            const afterDamage = new AfterDamageEffect(effect, damage);
            state = store.reduceEffect(state, afterDamage);
          }
        }
      }
      if (effect instanceof EndTurnEffect && HAS_MARKER(this.PHOEBE_MARKER, effect.player, this)) {
        REMOVE_MARKER(this.PHOEBE_MARKER, effect.player, this);
      }
      return state;
    }
  };

