  function* playCard182(next, store, state, effect, self) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const trainerCards = player.discard.cards.filter((c) => c.superType === 2 /* TRAINER */);
    if (trainerCards.length === 0) {
      return state;
    }
    let selectedCard;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.discard,
        { superType: 2 /* TRAINER */ },
        { min: 1, max: 1, allowCancel: false }
      ),
      (selected) => {
        selectedCard = selected && selected.length > 0 ? selected[0] : void 0;
        next();
      }
    );
    if (!selectedCard) {
      return state;
    }
    let opponentAllows = false;
    yield store.prompt(
      state,
      new ConfirmPrompt(opponent.id, GameMessage.WANT_TO_USE_ABILITY),
      (result) => {
        opponentAllows = result;
        next();
      }
    );
    if (opponentAllows) {
      MOVE_CARDS(store, state, player.discard, player.hand, { cards: [selectedCard], sourceCard: self });
    } else {
      DRAW_CARDS(store, state, player, 3);
    }
    return state;
  }
