  var AggronV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "F";
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [8 /* METAL */];
      this.hp = 230;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.resistance = [{ type: 1 /* GRASS */, value: -30 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Rock Slide",
          cost: [8 /* METAL */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 90,
          text: "This attack also does 30 damage to 2 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Merciless Strike",
          cost: [
            8 /* METAL */,
            9 /* COLORLESS */,
            9 /* COLORLESS */,
            9 /* COLORLESS */,
            9 /* COLORLESS */
          ],
          damage: 150,
          damageCalculation: "+",
          text: "If your opponent's Active Pok\xE9mon already has any damage counters on it, this attack does 150 more damage."
        }
      ];
      this.set = "BRS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "96";
      this.name = "Aggron V";
      this.fullName = "Aggron V BRS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        state = store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 2, allowCancel: false }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            targets.forEach((target) => {
              const damageEffect = new PutDamageEffect(effect, 30);
              store.reduceEffect(state, damageEffect);
            });
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.active.damage > 0) {
          effect.damage += 150;
        }
      }
      return state;
    }
  };

