  var AggronVMAX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "F";
      this._tags = ["VMAX" /* POKEMON_VMAX */];
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Aggron V";
      this.cardType = [8 /* METAL */];
      this.hp = 330;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.resistance = [{ type: 1 /* GRASS */, value: -30 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Cracking Stomp",
          cost: [8 /* METAL */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 150,
          text: "Discard the top card of your opponent's deck."
        },
        {
          name: "Max Take Down",
          cost: [
            8 /* METAL */,
            8 /* METAL */,
            9 /* COLORLESS */,
            9 /* COLORLESS */,
            9 /* COLORLESS */
          ],
          damage: 270,
          text: "This Pok\xE9mon also does 30 damage to itself."
        }
      ];
      this.set = "BRS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "97";
      this.name = "Aggron VMAX";
      this.fullName = "Aggron VMAX BRS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        MOVE_CARDS(store, state, opponent.deck, opponent.discard, {
          count: 1,
          sourceCard: this,
          sourceEffect: this.attacks[0]
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const dealDamage = new DealDamageEffect(effect, 30);
        dealDamage.target = player.active;
        return store.reduceEffect(state, dealDamage);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-brilliant-stars/alcremie.ts
