  var Alcremie = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "E";
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Milcery";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.powers = [{
        name: "Additional Order",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is in the Active Spot, your turn does not end when you use Caf\xE9 Master."
      }];
      this.attacks = [{
        name: "Rainbow Flavor",
        cost: [C, C],
        damage: 10,
        damageCalculation: "+",
        text: "This attack does 40 more damage for each type of basic Energy attached to all of your Pok\xE9mon."
      }];
      this.set = "BRS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "71";
      this.name = "Alcremie";
      this.fullName = "Alcremie BRS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const uniqueTypes = /* @__PURE__ */ new Set();
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (pokemon) => {
          const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, pokemon);
          store.reduceEffect(state, checkProvidedEnergyEffect);
          checkProvidedEnergyEffect.energyMap.forEach((em) => {
            if (em.card.energyType === 0 /* BASIC */ && em.provides.length > 0) {
              if (em.provides.includes(0 /* ANY */)) {
                [
                  2 /* FIRE */,
                  3 /* WATER */,
                  1 /* GRASS */,
                  4 /* LIGHTNING */,
                  5 /* PSYCHIC */,
                  6 /* FIGHTING */,
                  7 /* DARK */,
                  8 /* METAL */,
                  10 /* FAIRY */
                ].forEach((type) => uniqueTypes.add(type));
              } else {
                em.provides.forEach((type) => uniqueTypes.add(type));
              }
            }
          });
        });
        effect.damage += 40 * uniqueTypes.size;
        return state;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-brilliant-stars/arceus-v.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  function* useTrinityCharge(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      return state;
    }
    const blocked = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      if (!cardList.vPokemon()) {
        blocked.push(target);
      }
    });
    yield store.prompt(
      state,
      new AttachEnergyPrompt(
        player.id,
        GameMessage.ATTACH_ENERGY_TO_BENCH,
        player.deck,
        2 /* BOTTOM_PLAYER */,
        [2 /* BENCH */, 1 /* ACTIVE */],
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { allowCancel: false, min: 0, max: 3, blockedTo: blocked }
      ),
      (transfers) => {
        transfers = transfers || [];
        for (const transfer of transfers) {
          const target = StateUtils.getTarget(state, player, transfer.to);
          MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: effect.source.getPokemonCard() });
          next();
        }
      }
    );
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
