  var Bibarel5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.regulationMark = "F";
      this.evolvesFrom = "Bidoof";
      this.cardType = [C];
      this.hp = 120;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Industrious Incisors",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may draw cards until you have 5 cards in your hand."
      }];
      this.attacks = [{
        name: "Tail Smash",
        cost: [C, C, C],
        damage: 100,
        text: "Flip a coin. If tails, this attack does nothing."
      }];
      this.set = "BRS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "121";
      this.name = "Bibarel";
      this.fullName = "Bibarel BRS";
      this.INDUSTRIOUS_INCISORS_MARKER = "INDUSTRIOUS_INCISORS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.INDUSTRIOUS_INCISORS_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.INDUSTRIOUS_INCISORS_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.INDUSTRIOUS_INCISORS_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.INDUSTRIOUS_INCISORS_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.hand.cards.length >= 5) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        while (player.hand.cards.length < 5) {
          if (player.deck.cards.length === 0) {
            break;
          }
          DRAW_CARDS(store, state, player, 1);
        }
        player.marker.addMarker(this.INDUSTRIOUS_INCISORS_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === false) {
            effect.damage = 0;
          }
        });
      }
      return state;
    }
  };

