  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-brilliant-stars/clefable.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_effects();
  init_prefabs();
  init_choose_cards_prompt();
  init_choose_pokemon_prompt();
  var Clefable9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Clefairy";
      this.cardType = [P];
      this.hp = 100;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.attacks = [{
        name: "Moonlit Miracle",
        cost: [C],
        damage: 0,
        text: "Flip 3 coins. Choose a number of your Pok\xE9mon in play up to the number of heads. For each of those Pok\xE9mon, search your deck for a card that evolves from that Pok\xE9mon and put it onto that Pok\xE9mon to evolve it. Then, shuffle your deck."
      }, {
        name: "Magical Shot",
        cost: [P, C, C],
        damage: 90,
        text: ""
      }];
      this.regulationMark = "F";
      this.set = "BRS";
      this.setNumber = "54";
      this.cardImage = "assets/cardback.png";
      this.name = "Clefable";
      this.fullName = "Clefable BRS 54";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          const heads = results.filter((r) => r).length;
          if (heads === 0) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          if (player.deck.cards.length === 0) {
            return;
          }
          const pokemonInPlay = [];
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.pokemonPlayedTurn === state.turn) {
              return;
            }
            const card = cardList.getPokemonCard();
            if (card) {
              pokemonInPlay.push(card.name);
            }
          });
          const blocked = [];
          player.deck.cards.forEach((card, index) => {
            if (!(card instanceof PokemonCard) || !pokemonInPlay.includes(card.evolvesFrom)) {
              blocked.push(index);
            }
          });
          if (blocked.length === player.deck.cards.length) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          let evolvesRemaining = heads;
          const doOneEvolve = () => {
            if (evolvesRemaining <= 0 || player.deck.cards.length === 0) {
              store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                player.deck.applyOrder(order);
              });
              return;
            }
            const currentPokemonInPlay = [];
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.pokemonPlayedTurn === state.turn) {
                return;
              }
              const card = cardList.getPokemonCard();
              if (card) {
                currentPokemonInPlay.push(card.name);
              }
            });
            const currentBlocked = [];
            player.deck.cards.forEach((card, index) => {
              if (!(card instanceof PokemonCard) || !currentPokemonInPlay.includes(card.evolvesFrom)) {
                currentBlocked.push(index);
              }
            });
            if (currentBlocked.length === player.deck.cards.length) {
              store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                player.deck.applyOrder(order);
              });
              return;
            }
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_EVOLVE,
              player.deck,
              { superType: 1 /* POKEMON */ },
              { min: 0, max: 1, allowCancel: true, blocked: currentBlocked }
            ), (selected) => {
              if (!selected || selected.length === 0) {
                store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                  player.deck.applyOrder(order);
                });
                return;
              }
              const evolutionCard = selected[0];
              const blockedTargets = [];
              player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
                if (card.name !== evolutionCard.evolvesFrom || cardList.pokemonPlayedTurn === state.turn) {
                  blockedTargets.push(target);
                }
              });
              store.prompt(state, new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_EVOLVE,
                2 /* BOTTOM_PLAYER */,
                [1 /* ACTIVE */, 2 /* BENCH */],
                { min: 1, max: 1, allowCancel: false, blocked: blockedTargets }
              ), (targets) => {
                if (targets && targets.length > 0) {
                  const target = targets[0];
                  MOVE_CARDS(store, state, player.deck, target, { cards: [evolutionCard], sourceCard: this });
                  target.clearEffects();
                  target.pokemonPlayedTurn = state.turn;
                  const evolveEffect = new EvolveEffect(player, target, evolutionCard);
                  store.reduceEffect(state, evolveEffect);
                }
                evolvesRemaining--;
                doOneEvolve();
              });
            });
          };
          doOneEvolve();
        });
      }
      return state;
    }
  };

