      this.hp = 160;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Longhair Shot",
          cost: [D],
          damage: 0,
          text: "This attack does 30 damage to 1 of your opponent's Pok\xE9mon for each [D] Energy attached to this Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Darkness Fang",
          cost: [D, C],
          damage: 110,
          text: ""
        }
      ];
      this.regulationMark = "F";
      this.set = "BRS";
      this.setNumber = "94";
