  var Grotle3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Turtwig";
      this.cardType = [G];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Sun-Drenched Shell",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may search your deck for a [G] Pok\xE9mon, reveal it, and put it into your hand. Shuffle your deck afterward."
      }];
      this.attacks = [{
        name: "Razor Leaf",
        cost: [G, C, C],
        damage: 50,
        text: ""
      }];
      this.regulationMark = "F";
      this.set = "BRS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "7";
      this.name = "Grotle";
      this.fullName = "Grotle BRS";
      this.SUN_DRENCHED_SHELL_MARKER = "SUN_DRENCHED_SHELL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.SUN_DRENCHED_SHELL_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.SUN_DRENCHED_SHELL_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.SUN_DRENCHED_SHELL_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (player.marker.hasMarker(this.SUN_DRENCHED_SHELL_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.deck,
          { superType: 1 /* POKEMON */, cardType: [1 /* GRASS */] },
          { min: 0, max: 1, allowCancel: false }
        ), (cards) => {
          ABILITY_USED(player, this);
          player.marker.addMarker(this.SUN_DRENCHED_SHELL_MARKER, this);
          MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this, sourceEffect: this.powers[0] });
          return SHUFFLE_DECK(store, state, player);
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-brilliant-stars/hawlucha.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_choose_cards_prompt();
  init_choose_pokemon_prompt();
  init_prefabs();
  var Hawlucha7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 70;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Showboating Pose",
          cost: [C],
          damage: 0,
          text: "Attach up to 2 basic Energy cards from your discard pile to 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Cross-Cut",
          cost: [C],
          damage: 30,
          damageCalculation: "+",
          text: "If your opponent's Active Pok\xE9mon is an Evolution Pok\xE9mon, this attack does 30 more damage."
        }
      ];
      this.regulationMark = "F";
      this.set = "BRS";
      this.setNumber = "127";
      this.cardImage = "assets/cardback.png";
      this.name = "Hawlucha";
      this.fullName = "Hawlucha BRS 127";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const basicEnergyInDiscard = player.discard.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        );
        if (basicEnergyInDiscard.length === 0) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          const target = targets[0];
          const blocked = [];
          player.discard.cards.forEach((card, index) => {
            if (!(card instanceof EnergyCard) || card.energyType !== 0 /* BASIC */) {
              blocked.push(index);
            }
          });
          const availableCount = basicEnergyInDiscard.length;
          const maxCount = Math.min(2, availableCount);
          return store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_ATTACH,
            player.discard,
            { superType: 3 /* ENERGY */ },
            { min: 1, max: maxCount, allowCancel: false, blocked }
          ), (selected) => {
            const cards = selected || [];
            cards.forEach((card) => {
              MOVE_CARDS(store, state, player.discard, target, { cards: [card], sourceCard: this });
            });
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!opponent.active.isStage(2 /* BASIC */)) {
          effect.damage += 30;
        }
      }
      return state;
    }
  };

