  var Klinklang6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Klang";
      this.cardType = [M];
      this.hp = 150;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Gear Wall",
        powerType: 2 /* ABILITY */,
        text: "Your Basic Pok\xE9mon take 20 less damage from attacks from your opponent's Pok\xE9mon (after applying Weakness and Resistance)."
      }];
      this.attacks = [{
        name: "Tumbling Attack",
        cost: [M, C, C],
        damage: 90,
        damageCalculation: "+",
        text: "Flip a coin. If heads, this attack does 90 more damage."
      }];
      this.regulationMark = "F";
      this.set = "BRS";
      this.setNumber = "104";
      this.cardImage = "assets/cardback.png";
      this.name = "Klinklang";
      this.fullName = "Klinklang BRS 104";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && state.phase === 3 /* ATTACK */) {
        const targetPokemonCard = effect.target.getPokemonCard();
        if (!targetPokemonCard || targetPokemonCard.stage !== 2 /* BASIC */) {
        } else {
          const targetOwner = StateUtils.findOwner(state, effect.target);
          if (!StateUtils.isPokemonInPlay(targetOwner, this)) {
          } else if (IS_ABILITY_BLOCKED(store, state, targetOwner, this)) {
          } else {
            const attackerOwner = StateUtils.findOwner(state, effect.source);
            if (attackerOwner !== targetOwner) {
              effect.damage = Math.max(0, effect.damage - 20);
            }
          }
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            effect.damage += 90;
          }
        });
      }
      return state;
    }
  };

