  init_game_phase_effects();
  init_prefabs();
  var Liepard9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Purrloin";
      this.regulationMark = "F";
      this.cardType = [7 /* DARK */];
      this.hp = 100;
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Trade",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "You must discard a card from your hand in order to use this Ability. Once during your turn, you may draw 2 cards."
      }];
      this.attacks = [
        {
          name: "Slash",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 60,
          text: ""
        }
      ];
      this.set = "BRS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "91";
      this.name = "Liepard";
      this.fullName = "Liepard BRS";
      this.TRADE_MARKER = "TRADE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.TRADE_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.hand.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.TRADE_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          {},
          { allowCancel: true, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          player.marker.addMarker(this.TRADE_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this, sourceEffect: this.powers[0] });
          DRAW_CARDS(store, state, player, 2);
        });
        return state;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.TRADE_MARKER, this)) {
        effect.player.marker.removeMarker(this.TRADE_MARKER, this);
      }
      return state;
    }
  };

