  var Luxray6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Luxio";
      this.cardType = [L];
      this.hp = 150;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Energy Crush",
          cost: [L],
          damage: 50,
          damageCalculation: "x",
          text: "This attack does 50 damage for each Energy attached to all of your opponent's Pok\xE9mon."
        },
        {
          name: "Flash Impact",
          cost: [L],
          damage: 110,
          text: "This attack also does 30 damage to 1 of your Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.regulationMark = "F";
      this.set = "BRS";
      this.setNumber = "51";
      this.cardImage = "assets/cardback.png";
      this.name = "Luxray";
      this.fullName = "Luxray BRS 51";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let totalEnergy = 0;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          const checkProvided = new CheckProvidedEnergyEffect(opponent, cardList);
          store.reduceEffect(state, checkProvided);
          checkProvided.energyMap.forEach((em) => {
            totalEnergy += em.provides.length;
          });
        });
        effect.damage = 50 * totalEnergy;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const myBenched = player.bench.filter((b) => b.cards.length > 0);
        if (myBenched.length > 0) {
          return store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ), (selected) => {
            if (selected && selected.length > 0) {
              const damageEffect = new PutDamageEffect(effect, 30);
              damageEffect.target = selected[0];
              store.reduceEffect(state, damageEffect);
            }
          });
        }
      }
      return state;
    }
  };

