  var AcerolasPremonition = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "E";
      this.set = "BRS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "129";
      this.name = "Acerola's Premonition";
      this.fullName = "Acerola's Premonition BRS";
      this.text = "Your opponent reveals their hand, and you draw a card for each Trainer card you find there.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        const cardsInOpponentHand = opponent.hand.cards.filter((card) => card instanceof TrainerCard);
        state = store.prompt(
          state,
          new ShowCardsPrompt(
            player.id,
            GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
            opponent.hand.cards
          ),
          () => {
            const cardsToMove = cardsInOpponentHand.length;
            DRAW_CARDS(store, state, player, cardsToMove);
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-brilliant-stars/mimikyu-vmax.ts
  var MimikyuVmax = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VMAX" /* POKEMON_VMAX */];
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Mimikyu V";
      this.cardType = [P];
      this.hp = 300;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Ominous Numbers",
          cost: [C, C],
          damage: 0,
          text: "Put 4 damage counters on your opponent's Pok\xE9mon in any way you like. If you played Acerola's Premonition from your hand during this turn, place 13 damage counters instead."
        },
        {
          name: "Max Shadow",
          cost: [P, P],
          damage: 120,
          text: "Discard a random card from your opponent's hand."
        }
      ];
      this.regulationMark = "E";
      this.set = "BRS";
      this.setNumber = "69";
      this.cardImage = "assets/cardback.png";
      this.name = "Mimikyu VMAX";
      this.fullName = "Mimikyu VMAX BRS 69";
      this.ACEROLA_PLAYED_MARKER = "MIMIKYU_VMAX_BRS_ACEROLA_PLAYED_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard instanceof AcerolasPremonition) {
        effect.player.marker.addMarker(this.ACEROLA_PLAYED_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const counters = player.marker.hasMarker(this.ACEROLA_PLAYED_MARKER, this) ? 13 : 4;
        PUT_X_DAMAGE_COUNTERS_IN_ANY_WAY_YOU_LIKE(counters, store, state, effect);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.hand.cards.length > 0) {
          const randomIndex = Math.floor(Math.random() * opponent.hand.cards.length);
          const card = opponent.hand.cards[randomIndex];
          MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards: [card], sourceCard: this });
        }
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.ACEROLA_PLAYED_MARKER, this);
      }
      return state;
    }
  };

