  init_game();
  init_game_message();
  init_discard_energy_prompt();
  init_prefabs();
  var RaichuV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["V" /* POKEMON_V */];
      this.cardType = [L];
      this.hp = 200;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Fast Charge",
          cost: [L],
          damage: 0,
          canUseOnFirstTurn: true,
          text: "If you go first, you can use this attack during your first turn. Search your deck for a [L] Energy card and attach it to this Pok\xE9mon. Then, shuffle your deck."
        },
        {
          name: "Dynamic Spark",
          cost: [L, L],
          damage: 60,
          damageCalculation: "x",
          text: "You may discard any amount of [L] Energy from your Pok\xE9mon. This attack does 60 damage for each card you discarded in this way."
        }
      ];
      this.regulationMark = "F";
      this.set = "BRS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "45";
      this.name = "Raichu V";
      this.fullName = "Raichu V BRS";
    }
    // Implement power
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        if (cardList === void 0) {
          return state;
        }
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Lightning Energy" },
            { allowCancel: false, min: 0, max: 1 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              SHUFFLE_DECK(store, state, player);
              return state;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, {
                cards: [transfer.card],
                sourceCard: this
              });
            }
            SHUFFLE_DECK(store, state, player);
            return state;
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        let totalLightningEnergy = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const lightningCount = cardList.cards.filter(
            (card) => card.superType === 3 /* ENERGY */ && card.name === "Lightning Energy"
          ).length;
          totalLightningEnergy += lightningCount;
        });
        return store.prompt(
          state,
          new DiscardEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            // Card source is target Pokemon
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Lightning Energy" },
            { min: 1, max: totalLightningEnergy, allowCancel: false }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              let totalDiscarded = 0;
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = player.discard;
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
              totalDiscarded = transfers.length;
              effect.damage = totalDiscarded * 60;
            }
            return state;
          }
        );
      }
      return state;
    }
  };

