  var RaikouV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.regulationMark = "F";
      this.stage = 2 /* BASIC */;
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 200;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [
        {
          name: "Fleet-Footed",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, if this Pok\xE9mon is in the Active Spot, you may draw a card."
        }
      ];
      this.attacks = [
        {
          name: "Lightning Rondo",
          cost: [4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 20,
          damageCalculation: "+",
          text: "This attack does 20 more damage for each Benched Pok\xE9mon (both yours and your opponent's)."
        }
      ];
      this.set = "BRS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "48";
      this.name = "Raikou V";
      this.fullName = "Raikou V BRS";
      this.FLEET_FOOTED_MARKER = "FLEET_FOOTED_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.FLEET_FOOTED_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.FLEET_FOOTED_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.FLEET_FOOTED_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.FLEET_FOOTED_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.active.cards[0] !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        DRAW_CARDS(store, state, player, 1);
        player.marker.addMarker(this.FLEET_FOOTED_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const playerBenched = player.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        const opponentBenched = opponent.bench.reduce(
          (left, b) => left + (b.cards.length ? 1 : 0),
          0
        );
        const totalBenched = playerBenched + opponentBenched;
        effect.damage = 20 + totalBenched * 20;
      }
      return state;
    }
  };

