  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-brilliant-stars/sigilyph.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var Sigilyph5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 110;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [{
        name: "Tri Recharge",
        cost: [P],
        damage: 0,
        text: "Flip 3 coins. Attach a number of basic Energy cards up to the number of heads from your discard pile to your Benched Pok\xE9mon in any way you like."
      }, {
        name: "Psychic",
        cost: [P, C],
        damage: 10,
        damageCalculation: "+",
        text: "This attack does 30 more damage for each Energy attached to your opponent's Active Pok\xE9mon."
      }];
      this.regulationMark = "F";
      this.set = "BRS";
      this.setNumber = "66";
      this.cardImage = "assets/cardback.png";
      this.name = "Sigilyph";
      this.fullName = "Sigilyph BRS 66";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          const heads = results.filter((r) => r).length;
          if (heads === 0) {
            return;
          }
          const hasEnergyInDiscard = player.discard.cards.some(
            (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
          );
          const hasBenched = player.bench.some((b) => b.cards.length > 0);
          if (!hasEnergyInDiscard || !hasBenched) {
            return;
          }
          store.prompt(state, new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: 0, max: heads }
          ), (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkProvided = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, checkProvided);
        const energyCount = checkProvided.energyMap.reduce((total, em) => total + em.provides.length, 0);
        effect.damage += 30 * energyCount;
      }
      return state;
    }
  };

