  init_game_phase_effects();
  init_prefabs();
  var Staraptor4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Staravia";
      this.cardType = [C];
      this.hp = 150;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Strong Breeze",
          cost: [C, C, C],
          damage: 0,
          text: "Your opponent shuffles their Active Pok\xE9mon and all attached cards into their deck."
        },
        {
          name: "Spinning Bird",
          cost: [C, C, C, C],
          damage: 180,
          text: "Discard 2 Energy from this Pok\xE9mon."
        }
      ];
      this.regulationMark = "F";
      this.set = "BRS";
      this.setNumber = "119";
      this.cardImage = "assets/cardback.png";
      this.name = "Staraptor";
      this.fullName = "Staraptor BRS 119";
      this.usedStrongBreeze = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedStrongBreeze = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedStrongBreeze) {
        this.usedStrongBreeze = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const cardsToShuffle = opponent.active.cards.slice();
        cardsToShuffle.forEach((card) => {
          MOVE_CARDS(store, state, opponent.active, opponent.deck, { cards: [card], sourceCard: this });
        });
        opponent.active.clearEffects();
        SHUFFLE_DECK(store, state, opponent);
      }
      if (effect instanceof EndTurnEffect) {
        this.usedStrongBreeze = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 2);
      }
      return state;
    }
  };

