  var Tornadus4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 120;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Sudden Cyclone",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand onto your Bench, you may have your opponent switch his or her Active Pok\xE9mon with 1 of his or her Benched Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Blasting Wind",
          cost: [C, C, C],
          damage: 100,
          text: ""
        }
      ];
      this.regulationMark = "F";
      this.set = "BRS";
      this.setNumber = "126";
      this.cardImage = "assets/cardback.png";
      this.name = "Tornadus";
      this.fullName = "Tornadus BRS 126";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!opponent.bench.some((b) => b.cards.length > 0)) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (!wantToUse) {
            return;
          }
          try {
            const stub = new PowerEffect(player, this.powers[0], this);
            store.reduceEffect(state, stub);
          } catch {
            return;
          }
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        });
      }
      return state;
    }
  };

