  var Tropius6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 110;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [{
        name: "Curative Bower",
        powerType: 2 /* ABILITY */,
        text: "All of your Pok\xE9mon that have [G] Energy attached can't be Confused, and if they are already Confused, they recover from that Special Condition."
      }];
      this.attacks = [
        {
          name: "Slicing Blade",
          cost: [G, G, C],
          damage: 100,
          text: ""
        }
      ];
      this.regulationMark = "F";
      this.set = "BRS";
      this.setNumber = "5";
      this.cardImage = "assets/cardback.png";
      this.name = "Tropius";
      this.fullName = "Tropius BRS 5";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          let isTropiusInPlay = false;
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
            if (card === this) {
              isTropiusInPlay = true;
            }
          });
          if (!isTropiusInPlay) {
            return;
          }
          try {
            const stub = new PowerEffect(player, {
              name: "test",
              powerType: 2 /* ABILITY */,
              text: ""
            }, this);
            store.reduceEffect(state, stub);
          } catch {
            return;
          }
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (!cardList.specialConditions.includes(1 /* CONFUSED */)) {
              return;
            }
            const checkEnergy = new CheckProvidedEnergyEffect(player, cardList);
            store.reduceEffect(state, checkEnergy);
            const hasGrassEnergy = StateUtils.checkEnoughEnergy(checkEnergy.energyMap, [1 /* GRASS */]);
            if (hasGrassEnergy) {
              cardList.removeSpecialCondition(1 /* CONFUSED */);
            }
          });
        });
      }
      return state;
    }
  };

