  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Weavile9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Sneasel";
      this.cardType = [D];
      this.hp = 90;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.attacks = [{
        name: "Ransack",
        cost: [D],
        damage: 0,
        text: "Flip 2 coins. If either of them is heads, your opponent reveals their hand. For each heads, choose a card you find there and put it on the bottom of your opponent's deck in any order."
      }, {
        name: "Slash",
        cost: [D, C, C],
        damage: 100,
        text: ""
      }];
      this.regulationMark = "F";
      this.set = "BRS";
      this.setNumber = "87";
      this.cardImage = "assets/cardback.png";
      this.name = "Weavile";
      this.fullName = "Weavile BRS 87";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          const heads = results.filter((r) => r).length;
          if (heads === 0 || opponent.hand.cards.length === 0) {
            return;
          }
          store.prompt(state, new ShowCardsPrompt(
            player.id,
            GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
            opponent.hand.cards
          ), () => {
            const cardsToMove = Math.min(heads, opponent.hand.cards.length);
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARDS_TO_PUT_ON_BOTTOM_OF_THE_DECK,
              opponent.hand,
              {},
              { allowCancel: false, min: cardsToMove, max: cardsToMove }
            ), (selected) => {
              selected = selected || [];
              for (const card of selected) {
                MOVE_CARDS(store, state, opponent.hand, opponent.deck, { cards: [card], sourceCard: this });
                const index = opponent.deck.cards.indexOf(card);
                if (index !== -1) {
                  opponent.deck.cards.splice(index, 1);
                  opponent.deck.cards.push(card);
                }
              }
            });
          });
        });
      }
      return state;
    }
  };

