  var MagmaBasin = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.regulationMark = "F";
      this.set = "BRS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "144";
      this.name = "Magma Basin";
      this.fullName = "Magma Basin BRS";
      this.text = "Once during each player's turn, that player may attach a [R] Energy card from their discard pile to 1 of their Benched [R] Pok\xE9mon. If a player attached Energy to a Pok\xE9mon in this way, put 2 damage counters on that Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const hasFirePokemonOnBench = player.bench.some(
          (b) => b.cards.some((c) => c instanceof PokemonCard && pokemonHasCardType(c, 2 /* FIRE */))
        );
        if (!hasFirePokemonOnBench) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked2 = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (!pokemonHasCardType(card, 2 /* FIRE */)) {
            blocked2.push(target);
          }
        });
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.name == "Fire Energy";
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_STADIUM);
        }
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
            { allowCancel: false, min: 1, max: 1, blockedTo: blocked2 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return state;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              if (IS_STADIUM_EFFECT_BLOCKED(store, state, player, target, this)) {
                MOVE_CARDS(store, state, player.discard, target, {
                  cards: [transfer.card],
                  sourceCard: this
                });
                continue;
              }
              MOVE_CARDS(store, state, player.discard, target, {
                cards: [transfer.card],
                sourceCard: this
              });
              target.damage += 20;
            }
          }
        );
        return state;
      }
      return state;
    }
  };

