  function* playCard186(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const hasValidCard = player.discard.cards.some(
      (c) => c instanceof PokemonCard || c instanceof TrainerCard && c.trainerType === 3 /* TOOL */ || c instanceof TrainerCard && c.trainerType === 2 /* STADIUM */ || c.superType === 3 /* ENERGY */
    );
    if (!hasValidCard) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    let pokemon = 0;
    let tools = 0;
    let stadiums = 0;
    let basicEnergies = 0;
    let specialEnergies = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      if (c instanceof PokemonCard) {
        pokemon += 1;
      } else if (c instanceof TrainerCard && c.trainerType === 3 /* TOOL */) {
        tools += 1;
      } else if (c instanceof TrainerCard && c.trainerType === 2 /* STADIUM */) {
        stadiums += 1;
      } else if (c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */) {
        basicEnergies += 1;
      } else if (c.superType === 3 /* ENERGY */ && c.energyType === 1 /* SPECIAL */) {
        specialEnergies += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxPokemons = Math.min(pokemon, 1);
    const maxTools = Math.min(tools, 1);
    const maxStadiums = Math.min(stadiums, 1);
    const maxEnergies = Math.min(basicEnergies + specialEnergies, 1);
    const maxBasicEnergies = Math.min(basicEnergies, 1);
    const maxSpecialEnergies = Math.min(specialEnergies, 1);
    const count = maxPokemons + maxTools + maxStadiums + maxEnergies;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        {},
        {
          min: 1,
          max: count,
          allowCancel: false,
          blocked,
          maxPokemons,
          maxTools,
          maxStadiums,
          maxEnergies,
          maxBasicEnergies,
          maxSpecialEnergies
        }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var RoseannesBackup = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "BRS";
      this.regulationMark = "F";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "148";
      this.name = "Roseanne's Backup";
      this.fullName = "Roseanne's Backup BRS";
      this.text = `Choose 1 or more:

  \u2022 Shuffle a Pok\xE9mon from your discard pile into your deck.
  \u2022 Shuffle a Pok\xE9mon Tool card from your discard pile into your deck.
  \u2022 Shuffle a Stadium card from your discard pile into your deck.
  \u2022 Shuffle an Energy card from your discard pile into your deck.`;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard186(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

