  function* playCard187(next, store, state, self, effect) {
    const player = effect.player;
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: self });
    effect.preventDefault = true;
    let pokemonOrSupporterInDiscard = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      const isPokemon = c instanceof PokemonCard;
      const isSupporter = c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */;
      if (isPokemon || isSupporter) {
        pokemonOrSupporterInDiscard += 1;
      } else {
        blocked.push(index);
      }
      if (c.name === self.name) {
        blocked.push(index);
        return;
      }
    });
    if (pokemonOrSupporterInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        {},
        { min: 1, max: 3, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
    return state;
  }
