      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 200;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Mean Look",
          cost: [D],
          damage: 30,
          text: "During your opponent's next turn, the Defending Pok\xE9mon can't retreat."
        },
        {
          name: "Moonlight Blade",
          cost: [D, C, C],
          damage: 80,
          text: "If this Pok\xE9mon has any damage counters on it, this attack does 80 more damage."
        }
      ];
      this.regulationMark = "E";
