  var UmbreonVMAX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VMAX" /* POKEMON_VMAX */, "Single Strike" /* SINGLE_STRIKE */];
      this.stage = 5 /* VMAX */;
      this.regulationMark = "E";
      this.evolvesFrom = "Umbreon V";
      this.cardType = [7 /* DARK */];
      this.hp = 310;
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [
        {
          name: "Dark Signal",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may switch 1 of your opponent's Benched Pok\xE9mon with their Active Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Max Darkness",
          cost: [7 /* DARK */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 160,
          text: ""
        }
      ];
      this.set = "EVS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "95";
      this.name = "Umbreon VMAX";
      this.fullName = "Umbreon VMAX EVS";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              const player2 = effect.player;
              const opponent = StateUtils.getOpponent(state, player2);
              const hasBench = opponent.bench.some((b) => b.cards.length > 0);
              if (!hasBench) {
                throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
              }
              return store.prompt(
                state,
                new ChoosePokemonPrompt(
                  player2.id,
                  GameMessage.CHOOSE_POKEMON_TO_SWITCH,
                  1 /* TOP_PLAYER */,
                  [2 /* BENCH */],
                  { allowCancel: false }
                ),
                (result) => {
                  const cardList = result[0];
                  opponent.switchPokemon(cardList);
                  return state;
                }
              );
            } else {
              return state;
            }
          }
        );
      }
      return state;
    }
  };

