  var Charizard7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Charmeleon";
      this.cardType = [R];
      this.hp = 120;
      this.weakness = [{ type: W }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Energy Burn",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "As often as you like during your turn (before your attack), you may turn all Energy attached to Charizard into [R] Energy for the rest of the turn. This power can't be used if Charizard is Asleep, Confused, or Paralyzed."
      }];
      this.attacks = [
        {
          name: "Fire Spin",
          cost: [R, R, R, R],
          damage: 100,
          text: "Discard 2 Energy cards attached to Charizard in order to use this attack."
        }
      ];
      this.set = "CEL";
      this.setNumber = "4A";
      this.cardImage = "assets/cardback.png";
      this.name = "Charizard";
      this.fullName = "Charizard CEL";
      this.ENERGY_BURN_MARKER = "CHARIZARD_CEL_ENERGY_BURN_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        if (cardList.specialConditions.includes(2 /* ASLEEP */) || cardList.specialConditions.includes(1 /* CONFUSED */) || cardList.specialConditions.includes(0 /* PARALYZED */)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        if (player.marker.hasMarker(this.ENERGY_BURN_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (pCardList) => {
          if (pCardList.getPokemonCard() === this) {
            pCardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
        player.marker.addMarker(this.ENERGY_BURN_MARKER, this);
      }
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this) && effect.player.marker.hasMarker(this.ENERGY_BURN_MARKER, this)) {
        effect.source.cards.forEach((c) => {
          if (c instanceof EnergyCard && !effect.energyMap.some((e) => e.card === c)) {
            effect.energyMap.push({ card: c, provides: [2 /* FIRE */] });
          }
        });
      }
      if (effect instanceof AttackEffect && effect.player.marker.hasMarker(this.ENERGY_BURN_MARKER, this)) {
        effect.attack.cost = effect.attack.cost.map(() => 2 /* FIRE */);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 2);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.ENERGY_BURN_MARKER, this)) {
        effect.player.marker.removeMarker(this.ENERGY_BURN_MARKER, this);
      }
      return state;
    }
  };

