  var DarkGyarados = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.cardType = [W];
      this.hp = 70;
      this.weakness = [{ type: G }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Final Beam",
        powerType: 0 /* POKEBODY */,
        text: "When Dark Gyarados is Knocked Out by an attack, flip a coin. If heads, this power does 20 damage for each [W] Energy attached to Dark Gyarados to the Pok\xE9mon that Knocked Out Dark Gyarados. Apply Weakness and Resistance. This power doesn't work if Dark Gyarados is Asleep, Confused, or Paralyzed."
      }];
      this.attacks = [{
        name: "Ice Beam",
        cost: [W, W, W],
        damage: 30,
        text: "Flip a coin. If heads, the Defending Pok\xE9mon is now Paralyzed."
      }];
      this.set = "CEL";
      this.setNumber = "8A";
      this.cardImage = "assets/cardback.png";
      this.name = "Dark Gyarados";
      this.fullName = "Dark Gyarados CEL";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this && effect.player.marker.hasMarker(effect.player.DAMAGE_DEALT_MARKER)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_POKEBODY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const sc = effect.target.specialConditions;
        if (sc.includes(2 /* ASLEEP */) || sc.includes(1 /* CONFUSED */) || sc.includes(0 /* PARALYZED */)) {
          return state;
        }
        const checkEnergy = new CheckProvidedEnergyEffect(player, effect.target);
        store.reduceEffect(state, checkEnergy);
        const waterCount = checkEnergy.energyMap.filter(
          (em) => em.provides.includes(3 /* WATER */) || em.provides.includes(0 /* ANY */)
        ).length;
        if (waterCount === 0) {
          return state;
        }
        const baseDamage = 20 * waterCount;
        COIN_FLIP_PROMPT(store, state, player, (flipResult) => {
          if (flipResult) {
            const target = opponent.active;
            const checkStats = new CheckPokemonStatsEffect(target);
            store.reduceEffect(state, checkStats);
            let damage = baseDamage;
            for (const w of checkStats.weakness) {
              if (w.type === 3 /* WATER */) {
                if (w.value === void 0) {
                  damage *= 2;
                } else {
                  damage += w.value;
                }
              }
            }
            for (const r of checkStats.resistance) {
              if (r.type === 3 /* WATER */) {
                damage += r.value;
              }
            }
            target.damage += Math.max(0, damage);
          }
        });
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            ADD_PARALYZED_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
          }
        });
      }
      return state;
    }
  };

