  var Dialga3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.regulationMark = "D";
      this.cardType = [8 /* METAL */];
      this.hp = 130;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.resistance = [{ type: 1 /* GRASS */, value: -30 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Temporal Backflow",
          cost: [8 /* METAL */],
          damage: 0,
          text: "Put a card from your discard pile into your hand."
        },
        {
          name: "Metal Blast",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 60,
          text: "This attack does 20 more damage for each [M] Energy attached to this Pokemon."
        }
      ];
      this.set = "CEL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "20";
      this.name = "Dialga";
      this.fullName = "Dialga CEL";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        SEARCH_DISCARD_PILE_FOR_CARDS_TO_HAND(store, state, player, this, {}, { min: 1, max: 1, allowCancel: false }, this.attacks[0]);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let energyCount = 0;
        checkProvidedEnergyEffect.energyMap.forEach((em) => {
          energyCount += em.provides.filter((cardType) => {
            return cardType === 8 /* METAL */;
          }).length;
        });
        effect.damage += energyCount * 20;
      }
      return state;
    }
  };

