  var Mew10 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.regulationMark = "E";
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 60;
      this.weakness = [{ type: 7 /* DARK */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -30 }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Mysterious Tail",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, if this Pok\xE9mon is in the Active Spot, you may look at the top 6 cards of your deck, reveal an Item card you find there, and put it into your hand. Shuffle the other cards back into your deck."
      }];
      this.attacks = [
        {
          name: "Psyshot",
          cost: [5 /* PSYCHIC */, 9 /* COLORLESS */],
          damage: 30,
          text: ""
        }
      ];
      this.set = "CEL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "11";
      this.name = "Mew";
      this.fullName = "Mew CEL";
      this.MYSTERIOUS_TAIL_MARKER = "MYSTERIOUS_TAIL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.MYSTERIOUS_TAIL_MARKER, this);
        return state;
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.MYSTERIOUS_TAIL_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.active.cards[0] !== this) {
          return state;
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: 6, sourceCard: this });
        const opponent = StateUtils.getOpponent(state, player);
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          deckTop,
          { superType: 2 /* TRAINER */, trainerType: 0 /* ITEM */ },
          { min: 0, max: 1, allowCancel: false }
        ), (selected) => {
          ABILITY_USED(player, this);
          player.marker.addMarker(this.MYSTERIOUS_TAIL_MARKER, this);
          MOVE_CARDS(store, state, deckTop, player.hand, { cards: selected, sourceCard: this });
          MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: this });
          if (selected.length > 0) {
            return store.prompt(state, new ShowCardsPrompt(
              opponent.id,
              GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
              selected
            ), () => {
            });
          }
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.MYSTERIOUS_TAIL_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.MYSTERIOUS_TAIL_MARKER, this);
      }
      return state;
    }
  };

