  var Solgaleo4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Cosmoem";
      this.cardType = [M];
      this.hp = 170;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Rush In",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, if this Pok\xE9mon is on your Bench, you may switch it with your Active Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Solar Geyser",
          cost: [C, C],
          damage: 100,
          text: "Attach up to 2 basic Energy cards from your discard pile to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.regulationMark = "E";
      this.set = "CEL";
      this.setNumber = "21";
      this.cardImage = "assets/cardback.png";
      this.name = "Solgaleo";
      this.fullName = "Solgaleo CEL";
      this.RUSH_IN_MARKER = "SOLGALEO_CEL_RUSH_IN_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.RUSH_IN_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        let bench;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card === this && target.slot === 2 /* BENCH */) {
            bench = cardList;
          }
        });
        if (bench === void 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.RUSH_IN_MARKER, this);
        ABILITY_USED(player, this);
        player.switchPokemon(bench);
        return state;
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.RUSH_IN_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const basicEnergyInDiscard = player.discard.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        );
        if (basicEnergyInDiscard.length === 0) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          const target = targets[0];
          const blocked = [];
          player.discard.cards.forEach((card, index) => {
            if (!(card instanceof EnergyCard) || card.energyType !== 0 /* BASIC */) {
              blocked.push(index);
            }
          });
          const availableCount = basicEnergyInDiscard.length;
          const maxCount = Math.min(2, availableCount);
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_ATTACH,
            player.discard,
            { superType: 3 /* ENERGY */ },
            { min: 0, max: maxCount, allowCancel: false, blocked }
          ), (selected) => {
            const cards = selected || [];
            cards.forEach((card) => {
              MOVE_CARDS(store, state, player.discard, target, { cards: [card], sourceCard: this });
            });
          });
        });
      }
      return state;
    }
  };

