  var Xerneas4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 120;
      this.weakness = [{ type: M }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Breath of Life",
          cost: [C, C],
          damage: 0,
          text: "Search your deck for up to 3 basic Energy cards of different types and attach them to your Pok\xE9mon in any way you like. Then, shuffle your deck."
        },
        {
          name: "Aurora Horns",
          cost: [P, C, C],
          damage: 100,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "CEL";
      this.setNumber = "12";
      this.cardImage = "assets/cardback.png";
      this.name = "Xerneas";
      this.fullName = "Xerneas CEL";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const basicEnergyInDeck = player.deck.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        );
        if (basicEnergyInDeck.length === 0) {
          return SHUFFLE_DECK(store, state, player);
        }
        const typesAvailable = /* @__PURE__ */ new Set();
        basicEnergyInDeck.forEach((c) => {
          if (c instanceof EnergyCard) {
            c.provides.forEach((t) => typesAvailable.add(t));
          }
        });
        const maxCards = Math.min(3, typesAvailable.size);
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (!(card instanceof EnergyCard) || card.energyType !== 0 /* BASIC */) {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_ATTACH,
          player.deck,
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { min: 0, max: maxCards, allowCancel: false, blocked, differentTypes: true }
        ), (selectedCards) => {
          const cards = selectedCards || [];
          if (cards.length === 0) {
            return SHUFFLE_DECK(store, state, player);
          }
          const attachNext = (index) => {
            if (index >= cards.length) {
              SHUFFLE_DECK(store, state, player);
              return;
            }
            const card = cards[index];
            store.prompt(state, new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
              2 /* BOTTOM_PLAYER */,
              [1 /* ACTIVE */, 2 /* BENCH */],
              { min: 1, max: 1, allowCancel: false }
            ), (targets) => {
              if (targets && targets.length > 0) {
                MOVE_CARDS(store, state, player.deck, targets[0], { cards: [card], sourceCard: this });
              }
              attachNext(index + 1);
            });
          };
          attachNext(0);
        });
      }
      return state;
    }
  };

