  init_game();
  init_prefabs();
  var BlazikenVMAX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 5 /* VMAX */;
      this._tags = ["VMAX" /* POKEMON_VMAX */, "Rapid Strike" /* RAPID_STRIKE */];
      this.evolvesFrom = "Blaziken V";
      this.cardType = [R];
      this.hp = 320;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Clutch",
          cost: [R],
          damage: 60,
          text: "During your opponent's next turn, the Defending Pok\xE9mon can't retreat."
        },
        {
          name: "Max Blaze",
          cost: [C, C],
          damage: 130,
          text: "Choose up to 2 of your Benched Rapid Strike Pok\xE9mon and attach an Energy card from your discard pile to each of them."
        }
      ];
      this.set = "CRE";
      this.regulationMark = "E";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "21";
      this.name = "Blaziken VMAX";
      this.fullName = "Blaziken VMAX CRE";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return BLOCK_RETREAT(store, state, effect, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */;
        });
        if (!hasEnergyInDiscard) {
          return state;
        }
        let rapidStrikePokemonOnBench = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card) => {
          if (card.hasTag("Rapid Strike" /* RAPID_STRIKE */)) {
            rapidStrikePokemonOnBench = true;
          }
        });
        if (!rapidStrikePokemonOnBench) {
          return state;
        }
        const blocked2 = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (!card.hasTag("Rapid Strike" /* RAPID_STRIKE */)) {
            blocked2.push(target);
          }
        });
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { min: 0, max: 2, blocked: blocked2 }
          ),
          (chosen) => {
            chosen.forEach((target) => {
              state = store.prompt(
                state,
                new AttachEnergyPrompt(
                  player.id,
                  GameMessage.ATTACH_ENERGY_TO_BENCH,
                  player.discard,
                  2 /* BOTTOM_PLAYER */,
                  [2 /* BENCH */],
                  { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
                  { allowCancel: true, min: 0, max: 1 }
                ),
                (transfers) => {
                  transfers = transfers || [];
                  if (transfers.length === 0) {
                    return;
                  }
                  for (const transfer of transfers) {
                    const target2 = StateUtils.getTarget(state, player, transfer.to);
                    MOVE_CARDS(store, state, player.discard, target2, { cards: [transfer.card], sourceCard: this });
                  }
                }
              );
            });
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-chilling-reign/blissey-v.ts
  init_game();
