  init_game_phase_effects();
  init_prefabs();
  var BlisseyV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["V" /* POKEMON_V */];
      this.cardType = [9 /* COLORLESS */];
      this.hp = 250;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [
        {
          name: "Natural Cure",
          powerType: 2 /* ABILITY */,
          text: "Whenever you attach an Energy card from your hand to this Pok\xE9mon, it recovers from all Special Conditions."
        }
      ];
      this.attacks = [
        {
          name: "Blissful Blast",
          cost: [9 /* COLORLESS */],
          damage: 10,
          damageCalculation: "+",
          text: "This attack does 30 more damage for each Energy attached to this Pok\xE9mon. If you did any damage with this attack, you may attach up to 3 Energy cards from your discard pile to this Pok\xE9mon."
        }
      ];
      this.set = "CRE";
      this.regulationMark = "E";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "119";
      this.name = "Blissey V";
      this.fullName = "Blissey V CRE";
      this.usedBlissfulBlast = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && this.usedBlissfulBlast) {
        this.usedBlissfulBlast = false;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let energies = 0;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        checkProvidedEnergyEffect.energyMap.forEach((energy2) => {
          energies += energy2.provides.length;
        });
        effect.damage = 10 + 30 * energies;
        this.usedBlissfulBlast = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedBlissfulBlast === true) {
        const player = effect.player;
        if (player.active.getPokemonCard() !== this) {
          this.usedBlissfulBlast = false;
          return state;
        }
        const energyCards = player.discard.cards.filter((c) => c.superType === 3 /* ENERGY */);
        const maxEnergyCards = Math.min(3, energyCards.length);
        if (energyCards.length === 0) {
          this.usedBlissfulBlast = false;
          return state;
        }
        this.usedBlissfulBlast = false;
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 0, max: maxEnergyCards }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
            return state;
          }
        );
      }
      return state;
    }
  };

