  function* useLeParfum(next, store, state, self, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      return state;
    }
    try {
      const stub = new PowerEffect(player, {
        name: "test",
        powerType: 2 /* ABILITY */,
        text: ""
      }, self);
      store.reduceEffect(state, stub);
    } catch {
      return state;
    }
    yield state = store.prompt(state, new AttachEnergyPrompt(
      player.id,
      GameMessage.ATTACH_ENERGY_TO_BENCH,
      player.discard,
      2 /* BOTTOM_PLAYER */,
      [2 /* BENCH */],
      { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
      { allowCancel: true, min: 0, max: 1 }
    ), (transfers) => {
      transfers = transfers || [];
      if (transfers.length === 0) {
        return;
      }
      for (const transfer of transfers) {
        const target = StateUtils.getTarget(state, player, transfer.to);
        MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: self });
      }
    });
  }
