  var GalarianWeezing = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Koffing";
      this.cardType = [D];
      this.hp = 130;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Energy Factory",
        powerType: 2 /* ABILITY */,
        text: "Each basic [D] Energy attached to your Pok\xE9mon that have \u201CWeezing\u201D in their name provides [D][D] Energy. You can't apply more than 1 Energy Factory Ability at a time."
      }];
      this.attacks = [
        {
          name: "Suffocating Gas",
          cost: [D, C],
          damage: 50,
          text: ""
        }
      ];
      this.set = "CRE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "96";
      this.name = "Galarian Weezing";
      this.fullName = "Galarian Weezing CRE";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect) {
        const player = effect.player;
        let hasThisInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            hasThisInPlay = true;
          }
        });
        if (!hasThisInPlay) {
          return state;
        }
        if (hasThisInPlay) {
          if (IS_ABILITY_BLOCKED(store, state, player, this)) {
            return state;
          }
          if (!effect.source.getPokemonCard()?.name.includes("Weezing")) {
            return state;
          }
          effect.source.cards.forEach((c) => {
            if (c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && !effect.energyMap.some((e) => e.card === c)) {
              const providedTypes = c.provides.filter((type) => type === 7 /* DARK */);
              if (providedTypes.length > 0) {
                effect.energyMap.push({ card: c, provides: [7 /* DARK */, 7 /* DARK */] });
              }
            }
          });
          return state;
        }
        return state;
      }
      return state;
    }
  };

