  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-chilling-reign/hatterene.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var Hatterene2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Hattrem";
      this.cardType = [P];
      this.hp = 130;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.WITCH_RONDO_MARKER = "HATTERENE_CRE_WITCH_RONDO_MARKER";
      this.powers = [{
        name: "Witch Rondo",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may switch your Active Pok\xE9mon with 1 of your Benched Pok\xE9mon. If you do, your opponent switches their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Psychic",
          cost: [C, C],
          damage: 30,
          damageCalculation: "+",
          text: "This attack does 50 more damage for each Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.regulationMark = "E";
      this.set = "CRE";
      this.setNumber = "73";
      this.cardImage = "assets/cardback.png";
      this.name = "Hatterene";
      this.fullName = "Hatterene CRE";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        if (!player.bench.some((b) => b.cards.length > 0)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.WITCH_RONDO_MARKER, this);
        ABILITY_USED(player, this);
        const opponent = StateUtils.getOpponent(state, player);
        SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
        }
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.WITCH_RONDO_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        store.reduceEffect(state, checkEnergy);
        const energyCount = checkEnergy.energyMap.reduce((sum, em) => sum + em.provides.length, 0);
        effect.damage += 50 * energyCount;
      }
      return state;
    }
  };

