  init_game_phase_effects();
  init_play_card_effects();
  init_prefabs();
  var Inteleon = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Rapid Strike" /* RAPID_STRIKE */];
      this.regulationMark = "E";
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Drizzile";
      this.cardType = [3 /* WATER */];
      this.hp = 150;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [
        {
          name: "Quick Shooting",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may put 2 damage counters on 1 of your opponent's Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Waterfall",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 70,
          text: ""
        }
      ];
      this.set = "CRE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "43";
      this.name = "Inteleon";
      this.fullName = "Inteleon CRE";
      this.QUICK_SHOOTING_MARKER = "QUICK_SHOOTING_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.QUICK_SHOOTING_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.QUICK_SHOOTING_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.QUICK_SHOOTING_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.QUICK_SHOOTING_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            const targets = selected || [];
            if (targets.length > 0) {
              const placeCountersEffect = new PlaceDamageCountersEffect(player, targets[0], 20, this);
              state = store.reduceEffect(state, placeCountersEffect);
            }
            player.marker.addMarker(this.QUICK_SHOOTING_MARKER, this);
            ABILITY_USED(player, this);
          }
        );
      }
      return state;
    }
  };

