  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-chilling-reign/liepard-v.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_phase_effects();
  init_play_card_effects();
  init_prefabs();
  init_attack_effects2();
  var LiepardV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 190;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Hidden Claw",
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may discard a Pok\xE9mon Tool from a Pok\xE9mon (yours or your opponent's)."
        }
      ];
      this.attacks = [
        {
          name: "Shadow Ripper",
          cost: [D, C, C],
          damage: 110,
          text: "You may put this Pok\xE9mon and all attached cards into your hand."
        }
      ];
      this.regulationMark = "E";
      this.set = "CRE";
      this.setNumber = "104";
      this.cardImage = "assets/cardback.png";
      this.name = "Liepard V";
      this.fullName = "Liepard V CRE";
      this.wantsToShadowRipper = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const hasPokemonWithTools = (() => {
          let found = false;
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.tools.length > 0) found = true;
          });
          opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
            if (cardList.tools.length > 0) found = true;
          });
          return found;
        })();
        if (!hasPokemonWithTools) {
          return state;
        }
        CONFIRMATION_PROMPT(store, state, player, (result) => {
          if (!result) return;
          const blocked = [];
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, _card, target) => {
            if (cardList.tools.length === 0) blocked.push(target);
          });
          opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, _card, target) => {
            if (cardList.tools.length === 0) blocked.push(target);
          });
          store.prompt(
            state,
            new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON_TO_DISCARD_CARDS,
              0 /* ANY */,
              [1 /* ACTIVE */, 2 /* BENCH */],
              { allowCancel: false, min: 1, max: 1, blocked }
            ),
            (selected) => {
              const targets = selected || [];
              if (targets.length === 0) return;
              const target = targets[0];
              if (target.tools.length > 0) {
                const targetOwner = StateUtils.findOwner(state, target);
                MOVE_CARDS(store, state, target, targetOwner.discard, { cards: [target.tools[0]], sourceCard: this });
              }
            }
          );
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.wantsToShadowRipper = true;
      }
      if (effect instanceof AfterAttackEffect && this.wantsToShadowRipper) {
        this.wantsToShadowRipper = false;
        CONFIRMATION_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            PUT_THIS_POKEMON_AND_ALL_ATTACHED_CARDS_INTO_YOUR_HAND(store, state, effect);
          }
        });
      }
      if (effect instanceof EndTurnEffect) {
        this.wantsToShadowRipper = false;
      }
      return state;
    }
  };

