  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  function* useKeepCalling(next, store, state, effect, self) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const max = Math.min(slots2.length, 3);
    const blocked = [];
    for (let i = 0; i < player.deck.cards.length; i++) {
      const card = player.deck.cards[i];
      if (!card.hasTag("Rapid Strike" /* RAPID_STRIKE */)) {
        blocked.push(i);
      }
    }
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
        player.deck,
        { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
        { min: 0, max, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      MOVE_CARDS(store, state, player.deck, slots2[index], {
        cards: [card],
        sourceCard: self,
        sourceEffect: self.attacks[0]
      });
      slots2[index].pokemonPlayedTurn = state.turn;
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var Sobble = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "E";
      this._tags = ["Rapid Strike" /* RAPID_STRIKE */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 60;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Keep Calling",
          cost: [C],
          damage: 0,
          text: "Search your deck for up to 3 Basic Rapid Strike Pok\xE9mon and put them onto your Bench. Then, shuffle your deck."
        },
        {
          name: "Double Spin",
          cost: [C, C],
          damage: 20,
          text: "Flip 2 coins. This attack does 20 damage for each heads."
        }
      ];
      this.set = "CRE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "41";
      this.name = "Sobble";
      this.fullName = "Sobble CRE";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const generator = useKeepCalling(() => generator.next(), store, state, effect, this);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        return MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 2, (results) => {
          let heads = 0;
          results.forEach((r) => {
            heads += r ? 1 : 0;
          });
          effect.damage = 20 * heads;
        });
      }
      return state;
    }
  };

