  var Avery = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CRE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "130";
      this.regulationMark = "E";
      this.name = "Avery";
      this.fullName = "Avery CRE";
      this.text = "Draw 3 cards. If you drew any cards in this way, your opponent discards Pok\xE9mon from their Bench until they have 3.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        DRAW_CARDS(store, state, player, 3);
        const opponent = StateUtils.getOpponent(state, player);
        const opponentBenched = opponent.bench.reduce(
          (left, b) => left + (b.cards.length ? 1 : 0),
          0
        );
        while (opponentBenched > 3) {
          const benchDifference = opponentBenched - 3;
          return store.prompt(
            state,
            new ChoosePokemonPrompt(
              opponent.id,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              2 /* BOTTOM_PLAYER */,
              [2 /* BENCH */],
              {
                allowCancel: false,
                min: benchDifference,
                max: benchDifference
              }
            ),
            (selected) => {
              selected.forEach((cardList) => {
                MOVE_POKEMON_OFF_BOARD(store, state, cardList, {
                  pokemonDestination: opponent.discard,
                  sourceCard: this
                });
              });
              return state;
            }
          );
        }
        MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [effect.trainerCard] });
        return state;
      }
      return state;
    }
  };

