  var RuggedHelmet = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.regulationMark = "E";
      this.set = "CRE";
      this.setNumber = "152";
      this.cardImage = "assets/cardback.png";
      this.name = "Rugged Helmet";
      this.fullName = "Rugged Helmet CRE";
      this.text = "Attach a Pok\xE9mon Tool to 1 of your Pok\xE9mon that doesn't already have a Pok\xE9mon Tool attached. If the Pok\xE9mon this card is attached to is in the Active Spot and is damaged by an attack from your opponent's Pok\xE9mon (even if it is Knocked Out), put an Energy attached to the Attacking Pok\xE9mon into your opponent's hand. You may play any number of Item cards during your turn.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (effect.damage <= 0 || player === targetPlayer || targetPlayer.active !== effect.target) {
          return state;
        }
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        if (state.phase === 3 /* ATTACK */) {
          const attackerEnergyCards = effect.source.cards.filter(
            (c) => c.superType === 3 /* ENERGY */
          );
          if (attackerEnergyCards.length === 0) {
            return state;
          }
          if (attackerEnergyCards.length === 1) {
            MOVE_CARDS(store, state, effect.source, targetPlayer.hand, {
              cards: [attackerEnergyCards[0]],
              sourceCard: this
            });
          } else {
            return store.prompt(
              state,
              new ChooseCardsPrompt(
                targetPlayer,
                GameMessage.MOVE_ENERGY_CARDS,
                effect.source,
                { superType: 3 /* ENERGY */ },
                { min: 1, max: 1, allowCancel: false }
              ),
              (selected) => {
                if (selected && selected.length > 0) {
                  MOVE_CARDS(store, state, effect.source, targetPlayer.hand, {
                    cards: selected,
                    sourceCard: this
                  });
                }
              }
            );
          }
        }
      }
      return state;
    }
  };

