  var Siebold = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this._tags = ["Rapid Strike" /* RAPID_STRIKE */];
      this.regulationMark = "E";
      this.set = "CRE";
      this.setNumber = "153";
      this.cardImage = "assets/cardback.png";
      this.name = "Siebold";
      this.fullName = "Siebold CRE";
      this.text = "Choose up to 2 of your Rapid Strike Pok\xE9mon and heal 60 damage from each of them. You may play only 1 Supporter card during your turn.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        let hasRapidStrikeWithDamage = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card.hasTag("Rapid Strike" /* RAPID_STRIKE */) && cardList.damage > 0) {
            hasRapidStrikeWithDamage = true;
          }
        });
        if (!hasRapidStrikeWithDamage) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (!card.hasTag("Rapid Strike" /* RAPID_STRIKE */) || cardList.damage === 0) {
            blocked.push(target);
          }
        });
        store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_HEAL,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { allowCancel: false, min: 1, max: 2, blocked }
          ),
          (selected) => {
            const targets = selected || [];
            targets.forEach((target) => {
              const healEffect = new HealEffect(player, target, 60);
              store.reduceEffect(state, healEffect);
            });
          }
        );
      }
      return state;
    }
  };

