  var Snorlax10 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 130;
      this.retreat = [C, C, C];
      this.weakness = [{ type: F }];
      this.powers = [{
        name: "Gormandize",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, if this Pokemon is in the Active Spot, you may draw cards until you have 7 cards in your hand. If you use this Ability, your turn ends."
      }];
      this.attacks = [{
        name: "Body Slam",
        cost: [C, C, C, C],
        damage: 100,
        text: "Flip a coin. If heads, your opponent's Active Pokemon is now Paralyzed."
      }];
      this.set = "VIV";
      this.name = "Snorlax";
      this.fullName = "Snorlax VIV";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "131";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.active.getPokemonCard() !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const count = Math.max(0, 7 - player.hand.cards.length);
        if (count === 0 || player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        MOVE_CARDS(store, state, player.deck, player.hand, { count, sourceCard: this });
        const endTurnEffect = new EndTurnEffect(player);
        store.reduceEffect(state, endTurnEffect);
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === true) {
            const specialConditionEffect = new AddSpecialConditionsEffect(effect, [0 /* PARALYZED */]);
            store.reduceEffect(state, specialConditionEffect);
          }
        });
      }
      return state;
    }
  };

