  var Gumshoos3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Yungoos";
      this.cardType = [C];
      this.hp = 120;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Stakeout Headbutt",
          cost: [C, C],
          damage: 30,
          damageCalculation: "+",
          text: "If your opponent's Active Pok\xE9mon moved from the Bench to the Active Spot during your opponent's last turn, this attack does 120 more damage."
        },
        {
          name: "Lunge Out",
          cost: [C, C],
          damage: 60,
          text: ""
        }
      ];
      this.regulationMark = "F";
      this.set = "CRZ";
      this.setNumber = "118";
      this.cardImage = "assets/cardback.png";
      this.name = "Gumshoos";
      this.fullName = "Gumshoos CRZ 118";
      // Track if the opponent's active Pokemon moved from bench this turn
      // Using EndTurnEffect to save the state before movedToActiveThisTurn is cleared
      this.OPPONENT_MOVED_MARKER = "GUMSHOOS_OPPONENT_MOVED_MARKER";
      this.CLEAR_OPPONENT_MOVED_MARKER = "GUMSHOOS_CLEAR_OPPONENT_MOVED_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.marker.hasMarker(this.CLEAR_OPPONENT_MOVED_MARKER, this)) {
          player.marker.removeMarker(this.CLEAR_OPPONENT_MOVED_MARKER, this);
          opponent.active.marker.removeMarker(this.OPPONENT_MOVED_MARKER, this);
        }
        const opponentActiveCard = player.active.getPokemonCard();
        if (opponentActiveCard && MOVED_TO_ACTIVE_THIS_TURN(player, opponentActiveCard)) {
          player.active.marker.addMarker(this.OPPONENT_MOVED_MARKER, this);
          opponent.marker.addMarker(this.CLEAR_OPPONENT_MOVED_MARKER, this);
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.active.marker.hasMarker(this.OPPONENT_MOVED_MARKER, this)) {
          effect.damage += 120;
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-crown-zenith/hatterene-v.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_energy_card();
  init_play_card_effects();
  init_game_phase_effects();
  init_prefabs();
  init_order_cards_prompt();
  var HattereneV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 200;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Horoscope",
          cost: [P],
          damage: 0,
          text: "Look at the top 3 cards of your deck. You may attach any number of Energy cards you find there to this Pok\xE9mon. Put the other cards back in any order."
        },
        {
          name: "Teleportation Burst",
          cost: [P, C, C],
          damage: 80,
          text: "Switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        }
      ];
      this.regulationMark = "F";
      this.set = "CRZ";
      this.setNumber = "65";
      this.cardImage = "assets/cardback.png";
      this.name = "Hatterene V";
      this.fullName = "Hatterene V CRZ 65";
      this.usedTeleportationBurst = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const topCards = new CardList();
        const count = Math.min(3, player.deck.cards.length);
        MOVE_CARDS(store, state, player.deck, topCards, { count, sourceCard: this });
        const energyCards = topCards.cards.filter((c) => c instanceof EnergyCard);
        if (energyCards.length === 0) {
          return store.prompt(
            state,
            new OrderCardsPrompt(player.id, GameMessage.CHOOSE_CARDS_ORDER, topCards, {
              allowCancel: false
            }),
            (order) => {
              if (order !== null) {
                topCards.applyOrder(order);
              }
              topCards.moveToTopOfDestination(player.deck);
            }
          );
        }
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            topCards,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 0, max: energyCards.length }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              const energyCard = transfer.card;
              if (energyCard.energyType === 1 /* SPECIAL */) {
                MOVE_CARDS(store, state, topCards, target, { cards: [energyCard], sourceCard: this });
              } else {
                const attachEnergyEffect = new AttachEnergyEffect(player, energyCard, target);
                store.reduceEffect(state, attachEnergyEffect);
              }
            }
            if (topCards.cards.length > 0) {
              store.prompt(
                state,
                new OrderCardsPrompt(player.id, GameMessage.CHOOSE_CARDS_ORDER, topCards, {
                  allowCancel: false
                }),
                (order) => {
                  if (order !== null) {
                    topCards.applyOrder(order);
                  }
                  topCards.moveToTopOfDestination(player.deck);
                }
              );
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (hasBench) {
          this.usedTeleportationBurst = true;
        }
      }
      if (effect instanceof AfterAttackEffect && this.usedTeleportationBurst) {
        this.usedTeleportationBurst = false;
        const player = effect.player;
        SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
      }
      if (effect instanceof EndTurnEffect) {
        this.usedTeleportationBurst = false;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-crown-zenith/hatterene-vmax.ts
  init_prefabs();
  init_check_effects();
  init_play_card_action();
  init_move_damage_prompt();
