  var HattereneVmax = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VMAX" /* POKEMON_VMAX */];
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Hatterene V";
      this.cardType = [P];
      this.hp = 320;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Witch's Domain",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may move up to 2 damage counters from your Pok\xE9mon to your opponent's Active Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "G-Max Smite",
          cost: [P, C, C],
          damage: 150,
          text: "Your opponent's Active Pok\xE9mon is now Confused."
        }
      ];
      this.regulationMark = "F";
      this.set = "CRZ";
      this.setNumber = "66";
      this.cardImage = "assets/cardback.png";
      this.name = "Hatterene VMAX";
      this.fullName = "Hatterene VMAX CRZ 66";
      this.WITCHS_DOMAIN_MARKER = "HATTERENE_VMAX_WITCHS_DOMAIN_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const damagedOwnPokemon = [
          ...player.active.damage > 0 ? [player.active] : [],
          ...player.bench.filter((b) => b.cards.length > 0 && b.damage > 0)
        ];
        if (damagedOwnPokemon.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.WITCHS_DOMAIN_MARKER, this);
        const maxAllowedDamage = [];
        const checkHpEffect = new CheckHpEffect(opponent, opponent.active);
        store.reduceEffect(state, checkHpEffect);
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList === opponent.active) {
            maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
          }
        });
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          blockedTo.push(target);
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList !== opponent.active) {
            blockedTo.push(target);
          }
        });
        return store.prompt(
          state,
          new MoveDamagePrompt(
            player.id,
            GameMessage.MOVE_DAMAGE,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            maxAllowedDamage,
            { min: 1, max: 2, allowCancel: true, blockedTo }
          ),
          (transfers) => {
            if (!transfers || transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              if (source.damage >= 10) {
                source.damage -= 10;
                target.damage += 10;
              }
            }
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.addBoardEffect(0 /* ABILITY_USED */);
              }
            });
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.WITCHS_DOMAIN_MARKER, this);
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

