  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-crown-zenith/kyogre.ts
  init_game();
  init_game_message();
  init_card_types();
  init_pokemon_card();
  init_check_effects();
  init_prefabs();
  var Kyogre5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [3 /* WATER */];
      this.hp = 140;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Wave Summoning",
          cost: [9 /* COLORLESS */],
          damage: 0,
          text: "Search your deck for a [W] Energy card and attach it to this Pok\xE9mon. Then, shuffle your deck."
        },
        {
          name: "Dynamic Wave",
          cost: [3 /* WATER */, 3 /* WATER */, 3 /* WATER */, 9 /* COLORLESS */],
          damage: 0,
          text: "Put 3 Energy attached to this Pok\xE9mon into your hand. This attack does 180 damage to 1 of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "CRZ";
      this.regulationMark = "F";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "36";
      this.name = "Kyogre";
      this.fullName = "Kyogre CRZ";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_HAND,
          checkProvidedEnergy.energyMap,
          [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          { allowCancel: false }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            return;
          }
          for (const transfer of transfers) {
            MOVE_CARDS(store, state, player.active, player.hand, { cards: [transfer.card], sourceCard: this, sourceEffect: this.attacks[1] });
          }
          const min = Math.min(1);
          const max = Math.min(1);
          return store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min, max, allowCancel: false }
          ), (selected) => {
            const targets = selected || [];
            DAMAGE_OPPONENT_POKEMON(store, state, effect, 180, targets);
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_ACTIVE,
          player.deck,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
          { allowCancel: false, min: 0, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this, sourceEffect: this.attacks[0] });
            SHUFFLE_DECK(store, state, player);
            return state;
          }
        });
      }
      return state;
    }
  };

