  var LeafeonVSTAR = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Leafeon V";
      this.cardType = [G];
      this.hp = 260;
      this._tags = ["VSTAR" /* POKEMON_VSTAR */];
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Ivy Star",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "During your turn, you may switch 1 of your opponent's Benched Pok\xE9mon with their Active Pok\xE9mon. (You can't use more than 1 VSTAR Power in a game.)"
        }
      ];
      this.attacks = [{
        name: "Leaf Guard",
        cost: [G, G, C],
        damage: 180,
        text: "During your opponent's next turn, this Pok\xE9mon takes 30 less damage from attacks (after applying Weakness and Resistance)."
      }];
      this.regulationMark = "F";
      this.set = "SWSH";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "195";
      this.name = "Leafeon VSTAR";
      this.fullName = "Leafeon VSTAR SWSH";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (player.usedVSTAR === true) {
          throw new GameError(GameMessage.LABEL_VSTAR_USED);
        }
        if (!hasBench) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ),
          (result) => {
            const cardList = result[0];
            opponent.switchPokemon(cardList);
            player.usedVSTAR = true;
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.player.active.damageReductionNextTurn = 30;
      }
      return state;
    }
  };

