  var RadiantCharizard = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Radiant" /* RADIANT */];
      this.cardType = [R];
      this.hp = 160;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Excited Heart",
          powerType: 2 /* ABILITY */,
          text: "This Pok\xE9mon's attacks cost [C] less for each Prize card your opponent has taken."
        }
      ];
      this.attacks = [
        {
          name: "Combustion Blast",
          cost: [R, C, C, C, C],
          damage: 250,
          text: "During your next turn, this Pok\xE9mon can't use Combustion Blast."
        }
      ];
      this.regulationMark = "F";
      this.set = "CRZ";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "20";
      this.name = "Radiant Charizard";
      this.fullName = "Radiant Charizard CRZ";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect && effect.attack === this.attacks[0]) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const index = effect.cost.indexOf(9 /* COLORLESS */);
        if (index === -1 || IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        for (let i = 0; i < opponent.prizesTaken; i++) {
          const index2 = effect.cost.indexOf(9 /* COLORLESS */);
          if (index2 !== -1) {
            effect.cost.splice(index2, 1);
          }
        }
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (!player.active.cannotUseAttacksNextTurnPending.includes("Combustion Blast")) {
          player.active.cannotUseAttacksNextTurnPending.push("Combustion Blast");
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-crown-zenith/radiant-charjabug.ts
  init_pokemon_card();
