  init_game();
  init_game_effects();
  init_play_card_effects();
  init_prefabs();
  init_attack_effects2();
  var RadiantCharjabug = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Radiant" /* RADIANT */];
      this.cardType = [L];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Shocking Block",
          powerType: 2 /* ABILITY */,
          text: "Whenever any player attaches an Energy card from their hand to 1 of their Pok\xE9mon V, put 2 damage counters on that Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Linear Attack",
          cost: [L],
          damage: 0,
          text: "This attack does 30 damage to 1 of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.regulationMark = "F";
      this.set = "CRZ";
      this.setNumber = "51";
      this.cardImage = "assets/cardback.png";
      this.name = "Radiant Charjabug";
      this.fullName = "Radiant Charjabug CRZ 51";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect) {
        const attachingPlayer = effect.player;
        const targetCard2 = effect.target.getPokemonCard();
        if (!attachingPlayer.hand.cards.includes(effect.energyCard)) {
          return state;
        }
        if (!targetCard2 || !targetCard2.hasTag("V" /* POKEMON_V */) && !targetCard2.hasTag("VMAX" /* POKEMON_VMAX */) && !targetCard2.hasTag("VSTAR" /* POKEMON_VSTAR */)) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (!StateUtils.isPokemonInPlay(owner, this)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, owner, this)) {
          return state;
        }
        const damageEffect = new PlaceDamageCountersEffect(attachingPlayer, effect.target, 20);
        store.reduceEffect(state, damageEffect);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_POKEMON(30, effect, store, state);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-crown-zenith/radiant-eternatus.ts
  init_game();
  init_play_card_effects();
  init_game_phase_effects();
  init_play_card_effects();
  init_prefabs();
  var RadiantEternatus = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Radiant" /* RADIANT */];
      this.stage = 2 /* BASIC */;
      this.cardType = [11 /* DRAGON */];
      this.hp = 170;
      this.weakness = [];
      this.resistance = [];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [
        {
          name: "Climactic Gate",
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may search your deck for up to 2 Pok\xE9mon VMAX and put them onto your Bench. Then, shuffle your deck. If you use this Ability, your turn ends."
        }
      ];
      this.attacks = [
        {
          name: "Power Beam",
          cost: [2 /* FIRE */, 7 /* DARK */, 9 /* COLORLESS */],
          damage: 200,
          text: ""
        }
      ];
      this.set = "CRZ";
      this.regulationMark = "F";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "105";
      this.name = "Radiant Eternatus";
      this.fullName = "Radiant Eternatus CRZ";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
                if (cardList.getPokemonCard() === this) {
                  store.log(state, "LOG_PLAYER_USES_ABILITY" /* LOG_PLAYER_USES_ABILITY */, {
                    name: player.name,
                    ability: "Climactic Gate"
                  });
                }
              });
              const slots2 = player.bench.filter((b) => b.cards.length === 0);
              if (player.deck.cards.length === 0) {
                throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
              }
              const openSlots = player.bench.filter((b) => b.cards.length === 0);
              if (openSlots.length === 0) {
                throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
              }
              const maxPokemons = Math.min(openSlots.length, 2);
              let cards = [];
              const blocked = [];
              player.deck.cards.forEach((c, index) => {
                if (c instanceof PokemonCard && !c.hasTag("VMAX" /* POKEMON_VMAX */)) {
                  blocked.push(index);
                }
              });
              return store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
                  player.deck,
                  { superType: 1 /* POKEMON */ },
                  { min: 0, max: maxPokemons, allowCancel: false, blocked }
                ),
                (selected) => {
                  cards = selected || [];
                  if (cards.length === 0) {
                    return state;
                  }
                  cards.forEach((card, index) => {
                    store.reduceEffect(
                      state,
                      new PlayPokemonFromDeckEffect(player, card, slots2[index])
                    );
                    return state;
                  });
                  state = store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                    player.deck.applyOrder(order);
                  });
                  const endTurnEffect = new EndTurnEffect(player);
                  store.reduceEffect(state, endTurnEffect);
                  return state;
                }
              );
            }
          }
        );
      }
      return state;
    }
  };

