  init_trainer_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_card_list();
  init_prefabs();
  function* playCard194(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      return state;
    }
    let isHeads = false;
    yield COIN_FLIP_PROMPT(store, state, player, (result) => {
      isHeads = result;
      next();
    });
    const lookCount = isHeads ? 8 : 3;
    const deckLength = player.deck.cards.length;
    const start = Math.max(0, deckLength - lookCount);
    const end = deckLength;
    const deckBottom = new CardList();
    deckBottom.cards = player.deck.cards.slice(start, end);
    if (deckBottom.cards.length === 0) {
      return state;
    }
    let chosen = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        deckBottom,
        {},
        { min: 1, max: 1, allowCancel: false }
      ),
      (selected) => {
        chosen = selected || [];
        next();
      }
    );
    chosen.forEach((card) => {
      MOVE_CARDS(store, state, player.deck, player.hand, {
        cards: [card],
        sourceCard: effect.trainerCard
      });
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
