  var MewV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */, "Fusion Strike" /* FUSION_STRIKE */];
      this.regulationMark = "E";
      this.stage = 2 /* BASIC */;
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 180;
      this.weakness = [{ type: 7 /* DARK */ }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Energy Mix",
          cost: [5 /* PSYCHIC */],
          damage: 0,
          text: "Search your deck for an Energy card and attach it to 1 of  your Fusion Strike Pok\xE9mon. Then, shuffle your deck."
        },
        {
          name: "Psychic Leap",
          cost: [5 /* PSYCHIC */, 9 /* COLORLESS */],
          damage: 70,
          text: "You may shuffle this Pok\xE9mon and all attached cards into your deck."
        }
      ];
      this.set = "FST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "113";
      this.name = "Mew V";
      this.fullName = "Mew V FST";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (!cardList.getPokemons().some((c) => c.hasTag("Fusion Strike" /* FUSION_STRIKE */))) {
            blocked.push(target);
          }
        });
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { min: 0, max: 1, allowCancel: false, blockedTo: blocked }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
            }
            return state;
          }
        );
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        const player = effect.player;
        return store.prompt(
          state,
          new ConfirmPrompt(player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              MOVE_CARDS(store, state, player.active, player.deck, { sourceCard: this });
              player.active.clearEffects();
              return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                player.deck.applyOrder(order);
                return state;
              });
            } else {
              return state;
            }
          }
        );
      }
      return state;
    }
  };

