  var DuraludonVMAX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 5 /* VMAX */;
      this._tags = ["VMAX" /* POKEMON_VMAX */, "Single Strike" /* SINGLE_STRIKE */];
      this.evolvesFrom = "Duraludon V";
      this.cardType = [N];
      this.hp = 330;
      this.weakness = [];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Skyscraper",
        powerType: 2 /* ABILITY */,
        text: "Prevent all damage done to this Pokemon by attacks from your opponent's Pok\xE9mon that have Special Energy attached."
      }];
      this.attacks = [{
        name: "G-Max Pulverization",
        cost: [F, M, M],
        damage: 220,
        shredAttack: true,
        text: "This attack's damage isn't affected by any effects on your opponent's Active Pok\xE9mon."
      }];
      this.regulationMark = "E";
      this.set = "EVS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "123";
      this.name = "Duraludon VMAX";
      this.fullName = "Duraludon VMAX EVS";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this && state.phase === 3 /* ATTACK */) {
        const owner = StateUtils.findOwner(state, effect.target);
        if (IS_ABILITY_BLOCKED(store, state, owner, this)) {
          return state;
        }
        const hasSpecialEnergy = effect.source.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 1 /* SPECIAL */
        );
        if (hasSpecialEnergy) {
          effect.preventDefault = true;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const applyWeakness = new ApplyWeaknessEffect(effect, 220);
        store.reduceEffect(state, applyWeakness);
        const damage = applyWeakness.damage;
        effect.damage = 0;
        if (damage > 0) {
          opponent.active.damage += damage;
          const afterDamage = new AfterDamageEffect(effect, damage);
          state = store.reduceEffect(state, afterDamage);
        }
        return state;
      }
      return state;
    }
  };

