  function* playCard195(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    let pokemons = 0;
    let energies = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      if (c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.name === "Water Energy") {
        energies += 1;
      } else if (c instanceof PokemonCard && pokemonHasCardType(c, 3 /* WATER */)) {
        pokemons += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxPokemons = Math.min(pokemons, 4);
    const maxEnergies = Math.min(energies, 4);
    const count = 4;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.discard,
        {},
        { min: 0, max: count, allowCancel: false, blocked, maxPokemons, maxEnergies }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
