  function* playCard196(next, store, state, self, effect) {
    const player = effect.player;
    const supporterTurn = player.supporterTurn;
    if (!player.marker.hasMarker(self.RAIHAN_MARKER)) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const hasEnergyInDiscard = player.discard.cards.some((c) => {
      return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
    });
    if (!hasEnergyInDiscard) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      const isBasicEnergy = c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
      if (!isBasicEnergy) {
        blocked.push(index);
      }
    });
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    return store.prompt(
      state,
      new AttachEnergyPrompt(
        player.id,
        GameMessage.ATTACH_ENERGY_CARDS,
        player.discard,
        2 /* BOTTOM_PLAYER */,
        [2 /* BENCH */, 1 /* ACTIVE */],
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { allowCancel: false, min: 1, max: 1 }
      ),
      (transfers) => {
        if (transfers && transfers.length > 0) {
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, {
              cards: [transfer.card],
              sourceCard: self
            });
          }
          let cards = [];
          return store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_HAND,
              player.deck,
              {},
              { min: 1, max: 1, allowCancel: false }
            ),
            (selected) => {
              cards = selected || [];
              next();
              MOVE_CARDS(store, state, player.hand, player.supporter, {
                cards: [self],
                sourceCard: self
              });
              MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
              return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                player.deck.applyOrder(order);
              });
            }
          );
        }
        return state;
      }
    );
  }
  var Raihan = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "EVS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "152";
      this.regulationMark = "E";
      this.name = "Raihan";
      this.fullName = "Raihan EVS";
      this.text = `You can play this card only if any of your Pok\xE9mon were Knocked Out during your opponent's last turn.

Attach a basic Energy card from your discard pile to 1 of your Pok\xE9mon. If you do, search your deck for a card and put it into your hand. Then, shuffle your deck.`;
      this.RAIHAN_MARKER = "RAIHAN_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard196(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const duringTurn = [2 /* PLAYER_TURN */, 3 /* ATTACK */].includes(state.phase);
        if (!duringTurn || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) {
          effect.player.marker.addMarker(this.RAIHAN_MARKER, this);
        }
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) {
          REMOVE_OPPONENT_LAST_TURN_MARKER_AT_END_OF_TURN(effect, this.RAIHAN_MARKER, this);
        }
      }
      return state;
    }
  };

