  var ElesasSparkle = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "E";
      this._tags = ["Fusion Strike" /* FUSION_STRIKE */];
      this.set = "FST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "233";
      this.name = "Elesa's Sparkle";
      this.fullName = "Elesa's Sparkle FST";
      this.text = "Choose up to 2 of your Fusion Strike Pok\xE9mon. For each of those Pok\xE9mon, search your deck for a Fusion Strike Energy card and attach it to that Pok\xE9mon. Then, shuffle your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        let hasFusionStrike = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card) => {
          if (card.hasTag("Fusion Strike" /* FUSION_STRIKE */)) {
            hasFusionStrike = true;
          }
        });
        if (!hasFusionStrike) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked2 = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (!card.hasTag("Fusion Strike" /* FUSION_STRIKE */)) {
            blocked2.push(target);
          }
        });
        state = store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { min: 1, max: 2, blocked: blocked2 }
          ),
          (chosen) => {
            if (!chosen) {
              return;
            }
            const allowedTargets = chosen;
            const notAllowedTargets = [];
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
              if (!allowedTargets.some(
                (pokemon) => pokemon === (target.slot === 1 /* ACTIVE */ ? player.active : player.bench[target.index])
              )) {
                notAllowedTargets.push(target);
              }
            });
            state = store.prompt(
              state,
              new AttachEnergyPrompt(
                player.id,
                GameMessage.ATTACH_ENERGY_TO_ACTIVE,
                player.deck,
                2 /* BOTTOM_PLAYER */,
                [2 /* BENCH */, 1 /* ACTIVE */],
                { superType: 3 /* ENERGY */, name: "Fusion Strike Energy" },
                {
                  allowCancel: false,
                  min: 0,
                  max: 2,
                  blockedTo: notAllowedTargets,
                  differentTargets: true
                }
              ),
              (transfers) => {
                transfers = transfers || [];
                if (transfers.length === 0) {
                  SHUFFLE_DECK(store, state, player);
                  return;
                }
                for (const transfer of transfers) {
                  const target = StateUtils.getTarget(state, player, transfer.to);
                  MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
                }
                SHUFFLE_DECK(store, state, player);
              }
            );
          }
        );
      }
      return state;
    }
  };

