  var HisuianZoroarkVSTAR = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 6 /* VSTAR */;
      this.evolvesFrom = "Hisuian Zoroark V";
      this._tags = ["VSTAR" /* POKEMON_VSTAR */];
      this.regulationMark = "F";
      this.cardType = [9 /* COLORLESS */];
      this.hp = 270;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [
        {
          name: "Phantom Star",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "During your turn, you may discard your hand and draw 7 cards. (You can't use more than 1 VSTAR Power in a game.)"
        }
      ];
      this.attacks = [
        {
          name: "Ticking Curse",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 50,
          damageCalculator: "x",
          text: "This attack does 50 damage for each of your Pok\xE9mon that has any damage counters on it."
        }
      ];
      this.set = "LOR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "147";
      this.name = "Hisuian Zoroark VSTAR";
      this.fullName = "Hisuian Zoroark VSTAR LOR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.usedVSTAR === true) {
          throw new GameError(GameMessage.LABEL_VSTAR_USED);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const cards = player.hand.cards.filter((c) => c !== this);
        MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
        MOVE_CARDS(store, state, player.deck, player.hand, { count: 7, sourceCard: this });
        player.usedVSTAR = true;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        let benchPokemonWithDamage = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.damage !== 0) {
            benchPokemonWithDamage++;
          }
        });
        effect.damage = benchPokemonWithDamage * 50;
      }
      return state;
    }
  };

