  var ColresssExperiment = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "LOR";
      this.regulationMark = "F";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "155";
      this.name = "Colress's Experiment";
      this.fullName = "Colress's Experiment LOR";
      this.text = "Look at the top 5 cards of your deck and put 3 of them into your hand. Put the other cards in the Lost Zone.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: 5, sourceCard: this });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            deckTop,
            {},
            { min: 3, max: 3, allowCancel: true }
          ),
          (selected) => {
            MOVE_CARDS(store, state, deckTop, player.hand, { cards: selected, sourceCard: this });
            MOVE_CARDS(store, state, deckTop, player.lostzone, { sourceCard: this });
            return state;
          }
        );
      }
      return state;
    }
  };

