  var Arctozolt = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Rare Fossil";
      this.cardType = [L];
      this.hp = 130;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Biting Whirlpool",
        powerType: 2 /* ABILITY */,
        text: "Whenever your opponent attaches an Energy card from their hand to 1 of their Pok\xE9mon, put 2 damage counters on that Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Electro Ball",
        cost: [L, C],
        damage: 70,
        text: ""
      }];
      this.set = "DAA";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "66";
      this.name = "Arctozolt";
      this.fullName = "Arctozolt DAA";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && StateUtils.isPokemonInPlay(effect.player, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.target.damage += 20;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-darkness-ablaze/ariados.ts
  init_prefabs();
  init_play_card_effects();
  init_card_types();
  init_state_utils();
  init_confirm_prompt();
  init_game_message();
  init_choose_pokemon_prompt();
  init_pokemon_card();
  init_game();
  var Ariados5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Spinarak";
      this.cardType = [D];
      this.hp = 110;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Spider Net",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may switch 1 of your opponent's Benched Evolution Pok\xE9mon with their Active Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Poison Sting",
          cost: [D, C],
          damage: 30,
          text: "Your opponent's Active Pok\xE9mon is now Poisoned."
        }
      ];
      this.regulationMark = "D";
      this.set = "DAA";
      this.setNumber = "103";
      this.cardImage = "assets/cardback.png";
      this.name = "Ariados";
      this.fullName = "Ariados DAA";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const hasEvolutionOnBench = opponent.bench.some((b) => {
          const card = b.getPokemonCard();
          return b.cards.length > 0 && card && card.stage !== 2 /* BASIC */;
        });
        if (!hasEvolutionOnBench) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            const blocked = [];
            opponent.bench.forEach((b, index) => {
              const card = b.getPokemonCard();
              if (b.cards.length === 0 || !card || card.stage === 2 /* BASIC */) {
                blocked.push({ player: 1 /* TOP_PLAYER */, slot: 2 /* BENCH */, index });
              }
            });
            return store.prompt(state, new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON_TO_SWITCH,
              1 /* TOP_PLAYER */,
              [2 /* BENCH */],
              { allowCancel: false, blocked }
            ), (result) => {
              if (!result || result.length === 0) {
                return;
              }
              player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
                if (cardList.getPokemonCard() === this) {
                  cardList.addBoardEffect(0 /* ABILITY_USED */);
                }
              });
              opponent.switchPokemon(result[0]);
            });
          }
        });
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_POISON_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

