  var Corviknight = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Corvisquire";
      this.cardType = [C];
      this.hp = 160;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Flying Taxi",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may put 1 of your Pok\xE9mon, except any Corviknight, and all attached cards into your hand."
      }];
      this.attacks = [
        {
          name: "Blasting Wind",
          cost: [C, C, C],
          damage: 120,
          text: ""
        }
      ];
      this.regulationMark = "D";
      this.set = "DAA";
      this.setNumber = "156";
      this.cardImage = "assets/cardback.png";
      this.name = "Corviknight";
      this.fullName = "Corviknight DAA";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EvolveEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const validBench = player.bench.filter((b) => {
          if (b.cards.length === 0) return false;
          const pokemon = b.getPokemonCard();
          return pokemon !== void 0 && pokemon.name !== "Corviknight";
        });
        if (validBench.length === 0) {
          return state;
        }
        store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            const blocked = [];
            player.bench.forEach((b, index) => {
              if (b.cards.length > 0) {
                const pokemon = b.getPokemonCard();
                if (pokemon && pokemon.name === "Corviknight") {
                  blocked.push({ player: 2 /* BOTTOM_PLAYER */, slot: 2 /* BENCH */, index });
                }
              }
            });
            store.prompt(state, new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON_TO_PICK_UP,
              2 /* BOTTOM_PLAYER */,
              [2 /* BENCH */],
              { min: 1, max: 1, allowCancel: false, blocked }
            ), (selected) => {
              if (!selected || selected.length === 0) {
                return;
              }
              MOVE_POKEMON_OFF_BOARD(store, state, selected[0], {
                pokemonDestination: player.hand,
                sourceCard: this
              });
            });
          }
        });
      }
      return state;
    }
  };

