      this.retreat = [9 /* COLORLESS */];
      this.powers = [
        {
          name: "Dark Asset",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may draw cards until you have 6 cards in your hand. You can't use more than 1 Dark Asset Ability each turn."
        }
      ];
      this.attacks = [
        {
          name: "Venomous Fang",
          cost: [7 /* DARK */, 9 /* COLORLESS */],
          damage: 70,
          text: "Your opponent's Active Pok\xE9mon is now Poisoned."
        }
      ];
      this.set = "DAA";
