  var EternatusVMAX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Eternatus V";
      this._tags = ["VMAX" /* POKEMON_VMAX */];
      this.cardType = [D];
      this.hp = 340;
      this.weakness = [{ type: F }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Eternal Zone",
          powerType: 2 /* ABILITY */,
          text: "If all of your Pok\xE9mon in play are [D] type, you can have up to 8 Pok\xE9mon on your Bench, and you can't put non-[D] Pok\xE9mon into play. (If this Ability stops working, discard Pok\xE9mon from your Bench until you have 5.)"
        }
      ];
      this.attacks = [
        {
          name: "Dread End",
          cost: [D, C],
          damage: 30,
          damageCalculation: "x",
          text: "This attack does 30 damage for each of your [D] Pok\xE9mon in play."
        }
      ];
      this.set = "DAA";
      this.name = "Eternatus VMAX";
      this.fullName = "Eternatus VMAX DAA";
      this.setNumber = "117";
      this.regulationMark = "D";
      this.cardImage = "assets/cardback.png";
      this.ETERNATUS_EXPANDED_BENCH = "ETERNATUS_EXPANDED_BENCH";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckTableStateEffect) {
        effect.benchSizes = state.players.map((player, index) => {
          try {
            const stub = new PowerEffect(
              player,
              {
                name: "test",
                powerType: 2 /* ABILITY */,
                text: ""
              },
              this
            );
            store.reduceEffect(state, stub);
          } catch {
            if (!player.marker.hasMarker(this.ETERNATUS_EXPANDED_BENCH, this)) {
              player.marker.removeMarker(this.ETERNATUS_EXPANDED_BENCH, this);
            }
            return 5;
          }
          let isEternInPlay = false;
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            const pokemon = cardList.getPokemonCard();
            if (!!pokemon && pokemon.name === "Eternatus VMAX" && pokemon.powers.map((p) => p.name).includes(this.powers[0].name)) {
              isEternInPlay = true;
            }
          });
          if (!isEternInPlay) {
            if (!player.marker.hasMarker(this.ETERNATUS_EXPANDED_BENCH, this)) {
              player.marker.removeMarker(this.ETERNATUS_EXPANDED_BENCH, this);
            }
            return 5;
          }
          let darkPokemon = 0;
          let pokemonInPlay = 1;
          const activeType = new CheckPokemonTypeEffect(player.active);
          store.reduceEffect(state, activeType);
          if (activeType.cardTypes.includes(7 /* DARK */)) {
            darkPokemon++;
          }
          player.bench.forEach((benchSpot) => {
            if (benchSpot.cards.length > 0) {
              pokemonInPlay++;
              const benchedType = new CheckPokemonTypeEffect(benchSpot);
              store.reduceEffect(state, benchedType);
              if (benchedType.cardTypes.includes(7 /* DARK */)) {
                darkPokemon++;
              }
            }
          });
          if (darkPokemon === pokemonInPlay) {
            if (!player.marker.hasMarker(this.ETERNATUS_EXPANDED_BENCH, this)) {
              player.marker.addMarker(this.ETERNATUS_EXPANDED_BENCH, this);
            }
            return 8;
          } else {
            if (player.marker.hasMarker(this.ETERNATUS_EXPANDED_BENCH, this)) {
              player.marker.removeMarker(this.ETERNATUS_EXPANDED_BENCH, this);
            }
            return 5;
          }
        });
      }
      if (effect instanceof PlayPokemonEffect && effect.player.marker.hasMarker(this.ETERNATUS_EXPANDED_BENCH, this)) {
        if (!pokemonHasCardType(effect.pokemonCard, D)) {
          throw new GameError(GameMessage.BLOCKED_BY_ABILITY);
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let darksInPlay = 0;
        const activeType = new CheckPokemonTypeEffect(player.active);
        store.reduceEffect(state, activeType);
        if (activeType.cardTypes.includes(7 /* DARK */)) {
          darksInPlay++;
        }
        player.bench.forEach((benchSpot) => {
          if (benchSpot.cards.length > 0) {
            const benchedType = new CheckPokemonTypeEffect(benchSpot);
            store.reduceEffect(state, benchedType);
            if (benchedType.cardTypes.includes(7 /* DARK */)) {
              darksInPlay++;
            }
          }
        });
        effect.damage = 30 * darksInPlay;
      }
      return state;
    }
  };

