  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-darkness-ablaze/lunatone.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_check_effects();
  init_order_cards_prompt();
  var Lunatone9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Future Sight",
          cost: [C],
          damage: 0,
          text: "Look at the top 4 cards of either player's deck and put them back in any order."
        },
        {
          name: "Psychic",
          cost: [P, C],
          damage: 20,
          damageCalculation: "+",
          text: "This attack does 20 more damage for each Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.regulationMark = "D";
      this.set = "DAA";
      this.setNumber = "72";
      this.cardImage = "assets/cardback.png";
      this.name = "Lunatone";
      this.fullName = "Lunatone DAA";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const options = [
          {
            message: GameMessage.ORDER_YOUR_DECK,
            action: () => {
              if (player.deck.cards.length === 0) {
                return;
              }
              const deckTop = new CardList();
              MOVE_CARDS(store, state, player.deck, deckTop, { count: Math.min(4, player.deck.cards.length), sourceCard: this });
              store.prompt(state, new OrderCardsPrompt(
                player.id,
                GameMessage.CHOOSE_CARDS_ORDER,
                deckTop,
                { allowCancel: false }
              ), (order) => {
                if (order !== null) {
                  deckTop.applyOrder(order);
                }
                deckTop.moveToTopOfDestination(player.deck);
              });
            }
          },
          {
            message: GameMessage.ORDER_OPPONENT_DECK,
            action: () => {
              if (opponent.deck.cards.length === 0) {
                return;
              }
              const deckTop = new CardList();
              MOVE_CARDS(store, state, opponent.deck, deckTop, { count: Math.min(4, opponent.deck.cards.length), sourceCard: this });
              store.prompt(state, new OrderCardsPrompt(
                player.id,
                GameMessage.CHOOSE_CARDS_ORDER,
                deckTop,
                { allowCancel: false }
              ), (order) => {
                if (order !== null) {
                  deckTop.applyOrder(order);
                }
                deckTop.moveToTopOfDestination(opponent.deck);
              });
            }
          }
        ];
        return store.prompt(state, new SelectPrompt(
          player.id,
          GameMessage.CHOOSE_OPTION,
          options.map((opt) => opt.message),
          { allowCancel: false }
        ), (choice) => {
          const option = options[choice];
          option.action();
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        store.reduceEffect(state, checkEnergy);
        const energyCount = checkEnergy.energyMap.reduce((sum, em) => sum + em.provides.length, 0);
        effect.damage += 20 * energyCount;
      }
      return state;
    }
  };

