  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-darkness-ablaze/polteageist.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_game_phase_effects();
  init_prefabs();
  var Polteageist = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Sinistea";
      this.cardType = [P];
      this.hp = 60;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Tea Break",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "You must discard a Pok\xE9mon that has the Mad Party attack from your hand in order to use this Ability. Once during your turn, you may draw 2 cards."
        }
      ];
      this.attacks = [
        {
          name: "Mad Party",
          cost: [C, C],
          damage: 20,
          damageCalculation: "x",
          text: "This attack does 20 damage for each Pok\xE9mon in your discard pile that has the Mad Party attack."
        }
      ];
      this.set = "DAA";
      this.name = "Polteageist";
      this.fullName = "Polteageist DAA";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "83";
      this.regulationMark = "D";
      this.ABILITY_USED_MARKER = "ABILITY_USED_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.ABILITY_USED_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.ABILITY_USED_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.ABILITY_USED_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.ABILITY_USED_MARKER, this))
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        if (player.deck.cards.length === 0)
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        const blocked = player.hand.cards.filter((c) => !c.attacks.some((a) => a.name === "Mad Party")).map((c) => player.hand.cards.indexOf(c));
        if (blocked.length == player.hand.cards.length)
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 1 /* POKEMON */ },
          { allowCancel: true, min: 1, max: 1, blocked }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          player.marker.addMarker(this.ABILITY_USED_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this, sourceEffect: this.powers[0] });
          DRAW_CARDS(store, state, player, 2);
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let pokemonCount = 0;
        player.discard.cards.forEach((c) => {
          if (c instanceof PokemonCard && c.attacks.some((a) => a.name === "Mad Party"))
            pokemonCount += 1;
        });
        effect.damage = pokemonCount * 20;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-darkness-ablaze/pupitar.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  function* useRocketEvolution(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      return state;
    }
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_EVOLVE,
      player.deck,
      { superType: 1 /* POKEMON */, evolvesFrom: "Pupitar" },
      { min: 1, max: 1, allowCancel: true }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length > 0) {
      MOVE_CARDS(store, state, player.deck, player.active, { cards, sourceCard: effect.source.getPokemonCard() });
      player.active.clearEffects();
      player.active.pokemonPlayedTurn = state.turn;
    }
    SHUFFLE_DECK(store, state, player);
  }
  var Pupitar5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Larvitar";
      this.cardType = [F];
      this.hp = 80;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Sand Spray",
          cost: [F],
          damage: 20,
          text: ""
        },
        {
          name: "Rocket Evolution",
          cost: [C, C, C],
          damage: 40,
          text: "Search your deck for a card that evolves from this Pok\xE9mon and put it onto this Pok\xE9mon to evolve it. Then, shuffle your deck."
        }
      ];
      this.regulationMark = "D";
      this.set = "DAA";
      this.setNumber = "87";
      this.cardImage = "assets/cardback.png";
      this.name = "Pupitar";
      this.fullName = "Pupitar DAA";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const generator = useRocketEvolution(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

