  var Relicanth6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Fossil Search",
          cost: [C],
          damage: 0,
          text: "Search your deck for up to 2 Rare Fossil cards and put them onto your Bench. Then, shuffle your deck."
        },
        {
          name: "Surf",
          cost: [W, C],
          damage: 40,
          text: ""
        }
      ];
      this.regulationMark = "D";
      this.set = "DAA";
      this.setNumber = "40";
      this.cardImage = "assets/cardback.png";
      this.name = "Relicanth";
      this.fullName = "Relicanth DAA";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (slots2.length === 0) {
          return state;
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (card.name !== "Rare Fossil") {
            blocked.push(index);
          }
        });
        const max = Math.min(2, slots2.length);
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          player.deck,
          {},
          { min: 0, max, allowCancel: false, blocked }
        ), (selected) => {
          const cards = selected || [];
          cards.forEach((card, index) => {
            if (index < slots2.length) {
              const playPokemonEffect = new PlayPokemonEffect(player, card, slots2[index]);
              store.reduceEffect(state, playPokemonEffect);
            }
          });
          SHUFFLE_DECK(store, state, player);
        });
      }
      return state;
    }
  };

