  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_check_effects();
  var Solrock8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 90;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.powers = [{
        name: "Resistance Shade",
        powerType: 2 /* ABILITY */,
        text: "If you have Lunatone in play, your opponent's Pok\xE9mon in play have no Resistance."
      }];
      this.attacks = [
        {
          name: "Rock Throw",
          cost: [F, C],
          damage: 30,
          text: ""
        }
      ];
      this.regulationMark = "D";
      this.set = "DAA";
      this.setNumber = "92";
      this.cardImage = "assets/cardback.png";
      this.name = "Solrock";
      this.fullName = "Solrock DAA";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonStatsEffect) {
        const targetOwner = StateUtils.findOwner(state, effect.target);
        let solrockOwner = null;
        const players = [targetOwner, StateUtils.getOpponent(state, targetOwner)];
        players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              solrockOwner = p;
            }
          });
        });
        if (!solrockOwner || solrockOwner === targetOwner) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, solrockOwner, this)) {
          return state;
        }
        let hasLunatone = false;
        const owner = solrockOwner;
        owner.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard()?.name === "Lunatone") {
            hasLunatone = true;
          }
        });
        if (hasLunatone) {
          effect.resistance = [];
        }
      }
      return state;
    }
  };

