  var Suicune5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 120;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Wave Splash",
          cost: [W],
          damage: 20,
          text: ""
        },
        {
          name: "Aurora Loop",
          cost: [W, W, C],
          damage: 130,
          text: "Put 2 [W] Energy attached to this Pok\xE9mon into your hand."
        }
      ];
      this.regulationMark = "D";
      this.set = "DAA";
      this.setNumber = "37";
      this.cardImage = "assets/cardback.png";
      this.name = "Suicune";
      this.fullName = "Suicune DAA";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        state = store.reduceEffect(state, checkEnergy);
        const waterEnergyMap = checkEnergy.energyMap.filter(
          (em) => em.provides.includes(3 /* WATER */) || em.provides.includes(0 /* ANY */)
        );
        if (waterEnergyMap.length === 0) {
          return state;
        }
        const count = Math.min(2, waterEnergyMap.length);
        store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_HAND,
          waterEnergyMap,
          [9 /* COLORLESS */, 9 /* COLORLESS */],
          { allowCancel: false }
        ), (energy2) => {
          const cards = (energy2 || []).slice(0, count).map((e) => e.card);
          if (cards.length > 0) {
            MOVE_CARDS(store, state, player.active, player.hand, { cards, sourceCard: this });
          }
        });
      }
      return state;
    }
  };

