  var Talonflame7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Fletchinder";
      this.cardType = [R];
      this.hp = 140;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Scorching Feathers",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon is in the Active Spot and is damaged by an attack from your opponent's Pok\xE9mon (even if this Pok\xE9mon is Knocked Out), the Attacking Pok\xE9mon is now Burned."
      }];
      this.attacks = [
        {
          name: "Mach Flight",
          cost: [R, C, C],
          damage: 120,
          text: "During your opponent's next turn, the Defending Pok\xE9mon can't retreat."
        }
      ];
      this.regulationMark = "D";
      this.set = "DAA";
      this.setNumber = "32";
      this.cardImage = "assets/cardback.png";
      this.name = "Talonflame";
      this.fullName = "Talonflame DAA";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.getPokemonCard() === this && state.phase === 3 /* ATTACK */) {
        const owner = StateUtils.findOwner(state, effect.target);
        const opponent = effect.player;
        if (owner === opponent || owner.active !== effect.target) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, owner, this)) {
          return state;
        }
        opponent.active.addSpecialCondition(4 /* BURNED */);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return BLOCK_RETREAT(store, state, effect, this);
      }
      return state;
    }
  };

