  var TurboPatch = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.regulationMark = "D";
      this.set = "DAA";
      this.setNumber = "172";
      this.cardImage = "assets/cardback.png";
      this.name = "Turbo Patch";
      this.fullName = "Turbo Patch DAA";
      this.text = "Flip a coin. If heads, attach a basic Energy card from your discard pile to 1 of your Basic Pok\xE9mon that isn't a Pok\xE9mon-GX. You may play any number of Item cards during your turn.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const hasBasicEnergyInDiscard = player.discard.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        );
        if (!hasBasicEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        let hasValidTarget = false;
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.cards.length === 0) {
            return;
          }
          const pokemon = cardList.getPokemonCard();
          const isBasicNonGX = pokemon && pokemon.stage === 2 /* BASIC */ && !pokemon.hasTag("GX" /* POKEMON_GX */);
          if (isBasicNonGX) {
            hasValidTarget = true;
          } else {
            blockedTo.push(target);
          }
        });
        if (!hasValidTarget) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [this], sourceCard: this });
        state = COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (!result) {
            MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [this], sourceCard: this });
            return;
          }
          state = store.prompt(
            state,
            new AttachEnergyPrompt(
              player.id,
              GameMessage.ATTACH_ENERGY_CARDS,
              player.discard,
              2 /* BOTTOM_PLAYER */,
              [1 /* ACTIVE */, 2 /* BENCH */],
              { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
              { allowCancel: false, min: 1, max: 1, blockedTo }
            ),
            (transfers) => {
              transfers = transfers || [];
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
              }
              MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [this], sourceCard: this });
            }
          );
        });
      }
      return state;
    }
  };

