  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-evolving-skies/ampharos.ts
  init_game();
  init_card_types();
  init_pokemon_card();
  init_prefabs();
  var Ampharos6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Flaaffy";
      this.cardType = [L];
      this.hp = 150;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Thunder Shock",
        cost: [L],
        damage: 40,
        text: "Flip a coin. If heads, your opponent's Active Pok\xE9mon is now Paralyzed."
      }, {
        name: "Electron Crush",
        cost: [L, L, L, C],
        damage: 100,
        damageCalculation: "+",
        text: "You may discard 3 [L] Energy from this Pok\xE9mon. If you do, this attack does 120 more damage."
      }];
      this.regulationMark = "E";
      this.set = "EVS";
      this.setNumber = "56";
      this.cardImage = "assets/cardback.png";
      this.name = "Ampharos";
      this.fullName = "Ampharos EVS";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            ADD_PARALYZED_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const lightningCards = player.active.cards.filter(
          (c) => c instanceof EnergyCard && c.provides.includes(4 /* LIGHTNING */)
        );
        if (lightningCards.length >= 3) {
          state = store.prompt(state, new ConfirmPrompt(
            player.id,
            GameMessage.WANT_TO_USE_ABILITY
          ), (wantToDiscard) => {
            if (wantToDiscard) {
              DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 3, 4 /* LIGHTNING */);
              effect.damage += 120;
            }
          });
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-evolving-skies/appletun.ts
  init_pokemon_card();
  init_card_types();
  init_prefabs();
  init_state_utils();
  init_play_card_action();
  var Appletun = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Applin";
      this.cardType = [N];
      this.hp = 90;
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Thick Mucus",
          cost: [C],
          damage: 70,
          damageCalculation: "x",
          text: "This attack does 70 damage for each Special Energy card attached to your opponent's Pok\xE9mon."
        },
        {
          name: "Fighting Tackle",
          cost: [G, R],
          damage: 80,
          damageCalculation: "+",
          text: "If your opponent's Active Pok\xE9mon is a Pok\xE9mon V, this attack does 80 more damage."
        }
      ];
      this.regulationMark = "E";
      this.set = "EVS";
      this.setNumber = "121";
      this.cardImage = "assets/cardback.png";
      this.name = "Appletun";
      this.fullName = "Appletun EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let specialEnergyCount = 0;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          cardList.energies.cards.forEach((c) => {
            if (c.energyType === 1 /* SPECIAL */) {
              specialEnergyCount++;
            }
          });
        });
        effect.damage = 70 * specialEnergyCount;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentActive = opponent.active.getPokemonCard();
        if (opponentActive && opponentActive.hasTag("V" /* POKEMON_V */)) {
          effect.damage += 80;
        }
      }
      return state;
    }
  };

