  init_game();
  init_prefabs();
  var ArctovishV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 220;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Ancient Freeze",
          cost: [W, C, C],
          damage: 80,
          text: "If the Defending Pok\xE9mon is a Pok\xE9mon V or a Pok\xE9mon-GX, it can't attack during your opponent's next turn."
        },
        {
          name: "Giga Impact",
          cost: [W, W, C, C],
          damage: 220,
          text: "During your next turn, this Pok\xE9mon can't attack."
        }
      ];
      this.regulationMark = "E";
      this.set = "EVS";
      this.setNumber = "48";
      this.cardImage = "assets/cardback.png";
      this.name = "Arctovish V";
      this.fullName = "Arctovish V EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const defending = effect.opponent.active.getPokemonCard();
        const isVOrGX = defending && (defending.hasTag("V" /* POKEMON_V */) || defending.hasTag("VMAX" /* POKEMON_VMAX */) || defending.hasTag("VSTAR" /* POKEMON_VSTAR */) || defending.hasTag("V-UNION" /* POKEMON_VUNION */) || defending.hasTag("GX" /* POKEMON_GX */) || defending.hasTag("Tag Team" /* TAG_TEAM */));
        if (isVOrGX) {
          return DEFENDING_POKEMON_CANNOT_ATTACK(store, state, effect, this);
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        THIS_POKEMON_CANNOT_ATTACK_NEXT_TURN(effect.player);
      }
      return state;
    }
  };

