  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-evolving-skies/cryogonal.ts
  init_game();
  init_prefabs();
  var Cryogonal5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Element Chain",
          cost: [W],
          damage: 0,
          text: "Look at the top 6 cards of your deck and attach any number of basic Energy cards you find there to your Pok\xE9mon in any way you like. Shuffle the other cards back into your deck."
        },
        { name: "Icy Snow", cost: [W, C], damage: 30, text: "" }
      ];
      this.set = "EVS";
      this.regulationMark = "E";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "43";
      this.name = "Cryogonal";
      this.fullName = "Cryogonal EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const temp = new CardList();
        MOVE_CARDS(store, state, player.deck, temp, { count: 6, sourceCard: this });
        SHOW_CARDS_TO_PLAYER(store, state, player, temp.cards);
        const energyCardsDrawn = temp.cards.filter((card) => {
          return card instanceof EnergyCard && card.energyType === 0 /* BASIC */;
        });
        if (energyCardsDrawn.length == 0) {
          SHUFFLE_CARDS_INTO_DECK(store, state, player, temp.cards);
        } else {
          return store.prompt(state, new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            temp,
            // Only show drawn energies
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min: 0, max: energyCardsDrawn.length }
          ), (transfers) => {
            if (transfers) {
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, temp, target, { cards: [transfer.card], sourceCard: this });
              }
              SHUFFLE_CARDS_INTO_DECK(store, state, player, temp.cards);
            }
            return state;
          });
        }
        return state;
      }
      return state;
    }
  };

