  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-evolving-skies/dragonite-v.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_prefabs();
  var DragoniteV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "E";
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [11 /* DRAGON */];
      this.hp = 230;
      this.weakness = [];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Shred",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 50,
          shredAttack: true,
          text: "This attack's damage isn't affected by any effects on your opponent's Active Pok\xE9mon."
        },
        {
          name: "Dragon Gale",
          cost: [3 /* WATER */, 3 /* WATER */, 4 /* LIGHTNING */],
          damage: 250,
          text: "This attack also does 20 damage to each of your Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "EVS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "191";
      this.name = "Dragonite V";
      this.fullName = "Dragonite V EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const applyWeakness = new ApplyWeaknessEffect(effect, 50);
        store.reduceEffect(state, applyWeakness);
        const damage = applyWeakness.damage;
        effect.damage = 0;
        if (damage > 0) {
          opponent.active.damage += damage;
          const afterDamage = new AfterDamageEffect(effect, damage);
          state = store.reduceEffect(state, afterDamage);
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        effect.damage = 250;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (cardList === player.active) {
            return;
          }
          const damageEffect = new PutDamageEffect(effect, 20);
          damageEffect.target = cardList;
          store.reduceEffect(state, damageEffect);
        });
      }
      return state;
    }
  };

