  var Flaaffy8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.regulationMark = "E";
      this.evolvesFrom = "Mareep";
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 90;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Dynamotor",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn (before your attack), you may attach a L Energy card from your discard pile to 1 of your Benched Pokemon."
      }];
      this.attacks = [
        {
          name: "Electro Ball",
          cost: [4 /* LIGHTNING */, 4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 50,
          text: ""
        }
      ];
      this.set = "EVS";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "55";
      this.name = "Flaaffy";
      this.fullName = "Flaaffy EVS";
      this.DYNAMOTOR_MARKER = "DYNAMOTOR_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.DYNAMOTOR_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(4 /* LIGHTNING */);
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.DYNAMOTOR_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Lightning Energy" },
          { allowCancel: false, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          if (transfers.length === 0) {
            return;
          }
          player.marker.addMarker(this.DYNAMOTOR_MARKER, this);
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
        return state;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.DYNAMOTOR_MARKER, this)) {
        effect.player.marker.removeMarker(this.DYNAMOTOR_MARKER, this);
      }
      return state;
    }
  };

