  var Florges5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Rapid Strike" /* RAPID_STRIKE */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Floette";
      this.cardType = [P];
      this.hp = 130;
      this.weakness = [{ type: M }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Rapid Strike Connection",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "As often as you like during your turn, you may move an Energy from 1 of your Pok\xE9mon to 1 of your Rapid Strike Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Wonder Shine",
          cost: [P, C, C],
          damage: 110,
          text: "Your opponent's Active Pok\xE9mon is now Confused."
        }
      ];
      this.regulationMark = "E";
      this.set = "EVS";
      this.setNumber = "73";
      this.cardImage = "assets/cardback.png";
      this.name = "Florges";
      this.fullName = "Florges EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (!card.hasTag("Rapid Strike" /* RAPID_STRIKE */)) {
            blockedTo.push(target);
          }
        });
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          const blocked = [];
          cardList.cards.forEach((c, index) => {
            if (c.superType !== 3 /* ENERGY */) {
              blocked.push(index);
            }
          });
          if (blocked.length > 0) {
            blockedMap.push({ source: target, blocked });
          }
        });
        return store.prompt(
          state,
          new MoveEnergyPrompt(
            player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: true, min: 0, max: 1, blockedTo, blockedMap }
          ),
          (transfers) => {
            if (!transfers || transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const targetSlot = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, source, targetSlot, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        ADD_CONFUSION_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

