  init_prefabs();
  init_attack_effects2();
  init_game_effects();
  init_choose_cards_prompt();
  var GlaceonV2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 210;
      this.weakness = [{ type: M }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Frozen Awakening",
          cost: [W],
          damage: 0,
          text: "Search your deck for a card that evolves from this Pok\xE9mon and put it onto this Pok\xE9mon to evolve it. Then, shuffle your deck."
        },
        {
          name: "Heavy Snow",
          cost: [W, C, C],
          damage: 120,
          text: "Discard a Stadium in play."
        }
      ];
      this.regulationMark = "E";
      this.set = "EVS";
      this.setNumber = "40";
      this.cardImage = "assets/cardback.png";
      this.name = "Glaceon V";
      this.fullName = "Glaceon V EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (card.superType !== 1 /* POKEMON */) {
            blocked.push(index);
            return;
          }
          const pokemonCard = card;
          if (pokemonCard.evolvesFrom !== "Glaceon V") {
            blocked.push(index);
          }
        });
        const hasEvolution = player.deck.cards.some((card, index) => !blocked.includes(index));
        if (!hasEvolution) {
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            { superType: 1 /* POKEMON */ },
            { min: 1, max: 1, allowCancel: true, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length === 0) {
              return;
            }
            const pokemonCard = cards[0];
            MOVE_CARDS(store, state, player.deck, player.hand, { cards: [pokemonCard], sourceCard: this });
            const evolveEffect = new EvolveEffect(player, player.active, pokemonCard);
            store.reduceEffect(state, evolveEffect);
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        DISCARD_A_STADIUM_CARD_IN_PLAY(state);
      }
      return state;
    }
  };

