  init_prefabs();
  init_state_utils();
  var Gourgeist4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Pumpkaboo";
      this.cardType = [P];
      this.hp = 120;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Pandemonium",
          cost: [C, C],
          damage: 60,
          damageCalculation: "x",
          text: "Reveal the top 6 cards of your deck. This attack does 60 damage for each Psychic Pok\xE9mon you find there. Then, shuffle those Pok\xE9mon back into your deck and discard the other cards."
        }
      ];
      this.regulationMark = "E";
      this.set = "EVS";
      this.setNumber = "77";
      this.cardImage = "assets/cardback.png";
      this.name = "Gourgeist";
      this.fullName = "Gourgeist EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const topCards = new CardList();
        const count = Math.min(6, player.deck.cards.length);
        MOVE_CARDS(store, state, player.deck, topCards, { count, sourceCard: this });
        const psychicPokemon = topCards.cards.filter(
          (c) => c instanceof PokemonCard && pokemonHasCardType(c, 5 /* PSYCHIC */)
        );
        if (topCards.cards.length > 0) {
          SHOW_CARDS_TO_PLAYER(store, state, opponent, topCards.cards);
        }
        effect.damage = 60 * psychicPokemon.length;
        const nonPsychicCards = topCards.cards.filter((c) => !psychicPokemon.includes(c));
        nonPsychicCards.forEach((card) => {
          MOVE_CARDS(store, state, topCards, player.discard, { cards: [card], sourceCard: this });
        });
        MOVE_CARDS(store, state, topCards, player.deck, { sourceCard: this });
        SHUFFLE_DECK(store, state, player);
      }
      return state;
    }
  };

