  var JolteonVmax = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VMAX" /* POKEMON_VMAX */];
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Jolteon V";
      this.cardType = [L];
      this.hp = 300;
      this.weakness = [{ type: F }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Max Thunder Rumble",
          cost: [L, C],
          damage: 100,
          text: "This attack also does 100 damage to 1 of your opponent's Benched Pok\xE9mon that has any damage counters on it. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.regulationMark = "E";
      this.set = "EVS";
      this.setNumber = "51";
      this.cardImage = "assets/cardback.png";
      this.name = "Jolteon VMAX";
      this.fullName = "Jolteon VMAX EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasDamagedBenched = opponent.bench.some((b) => b.cards.length > 0 && b.damage > 0);
        if (!hasDamagedBenched) {
          return state;
        }
        const blocked = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList === opponent.active) {
            blocked.push(target);
            return;
          }
          if (cardList.damage === 0) {
            blocked.push(target);
          }
        });
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: true, blocked }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const damageEffect = new PutDamageEffect(effect, 100);
            damageEffect.target = targets[0];
            store.reduceEffect(state, damageEffect);
          }
        );
      }
      return state;
    }
  };

