  var Kyurem7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [N];
      this.hp = 120;
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Extreme Freeze",
          cost: [W, W, M],
          damage: 60,
          damageCalculation: "x",
          text: "Discard any amount of [W] Energy from your Pok\xE9mon. This attack does 60 damage for each card you discarded in this way."
        }
      ];
      this.regulationMark = "E";
      this.set = "EVS";
      this.setNumber = "116";
      this.cardImage = "assets/cardback.png";
      this.name = "Kyurem";
      this.fullName = "Kyurem EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const waterEnergyMap = [];
        const tempList = new CardList();
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          cardList.cards.forEach((card) => {
            if (card instanceof EnergyCard && card.energyType === 0 /* BASIC */ && card.provides.includes(3 /* WATER */)) {
              waterEnergyMap.push({ card, source: cardList });
              tempList.cards.push(card);
            }
          });
        });
        if (tempList.cards.length === 0) {
          effect.damage = 0;
          return state;
        }
        effect.damage = 0;
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          tempList,
          { superType: 3 /* ENERGY */ },
          { min: 0, max: tempList.cards.length, allowCancel: false }
        ), (selected) => {
          const cards = selected || [];
          cards.forEach((card) => {
            const entry = waterEnergyMap.find((e) => e.card === card);
            if (entry) {
              MOVE_CARDS(store, state, entry.source, player.discard, { cards: [card], sourceCard: this });
            }
          });
          effect.damage = 60 * cards.length;
        });
      }
      return state;
    }
  };

