  var LeafeonV2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 200;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this._tags = ["V" /* POKEMON_V */];
      this.powers = [
        {
          name: "Greening Cells",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may search your deck for a [G] Energy card and attach it to 1 of your Pok\xE9mon. Then, shuffle your deck. If you use this Ability, your turn ends."
        }
      ];
      this.attacks = [{
        name: "Leaf Blade",
        cost: [G, C, C],
        damage: 90,
        text: "Flip a coin. If heads, this attack does 60 more damage."
      }];
      this.set = "EVS";
      this.regulationMark = "E";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "7";
      this.name = "Leafeon V";
      this.fullName = "Leafeon V EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Grass Energy" },
            { allowCancel: true, min: 0, max: 1 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              SHUFFLE_DECK(store, state, player);
              return state;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
            }
            state = store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
        const endTurnEffect = new EndTurnEffect(player);
        store.reduceEffect(state, endTurnEffect);
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === true) {
            effect.damage += 60;
          }
        });
      }
      return state;
    }
  };

