  var LycanrocVmax = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VMAX" /* POKEMON_VMAX */];
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Lycanroc V";
      this.cardType = [F];
      this.hp = 320;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Hunting Claw",
          cost: [F],
          damage: 0,
          text: "Knock Out 1 of your opponent's Pok\xE9mon in play that has 60 HP or less remaining."
        },
        {
          name: "Max Edge",
          cost: [F, F, C],
          damage: 190,
          text: "This attack also does 30 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.regulationMark = "E";
      this.set = "EVS";
      this.setNumber = "92";
      this.cardImage = "assets/cardback.png";
      this.name = "Lycanroc VMAX";
      this.fullName = "Lycanroc VMAX EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const blocked = [];
        let hasValidTarget = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList.cards.length === 0) {
            blocked.push(target);
            return;
          }
          const checkHp = new CheckHpEffect(opponent, cardList);
          store.reduceEffect(state, checkHp);
          const remainingHp = checkHp.hp - cardList.damage;
          if (remainingHp <= 60) {
            hasValidTarget = true;
          } else {
            blocked.push(target);
          }
        });
        if (!hasValidTarget) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (selected) => {
            if (!selected || selected.length === 0) return;
            const target = selected[0];
            const koEffect = new KnockOutEffect(opponent, target);
            store.reduceEffect(state, koEffect);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_BENCHED_POKEMON(30, effect, store, state);
        }
      }
      return state;
    }
  };

