  var Regieleki2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 120;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Static Shock",
          cost: [9 /* COLORLESS */],
          damage: 20,
          text: ""
        },
        {
          name: "Teraspark",
          cost: [4 /* LIGHTNING */, 4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 120,
          text: "Discard all [L] Energy from this Pok\xE9mon. This attack also does 40 damage to 2 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "EVS";
      this.regulationMark = "E";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "60";
      this.name = "Regieleki";
      this.fullName = "Regieleki EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const benched = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        const min = Math.min(2, benched);
        const max = Math.min(2, benched);
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { min, max, allowCancel: false }
        ), (selected) => {
          const targets = selected || [];
          targets.forEach((target) => {
            const damageEffect = new PutDamageEffect(effect, 40);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          });
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, player.active);
          state = store.reduceEffect(state, checkProvidedEnergy);
          const cards = [];
          for (const energyMap of checkProvidedEnergy.energyMap) {
            const energy2 = energyMap.provides.filter((t) => t === 4 /* LIGHTNING */ || t === 0 /* ANY */);
            if (energy2.length > 0) {
              cards.push(energyMap.card);
            }
          }
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = player.active;
          store.reduceEffect(state, discardEnergy2);
          return state;
        });
      }
      return state;
    }
  };

