  var VaporeonVmax = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VMAX" /* POKEMON_VMAX */, "Rapid Strike" /* RAPID_STRIKE */];
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Vaporeon V";
      this.cardType = [W];
      this.hp = 320;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Bubble Pod",
          cost: [C],
          damage: 0,
          text: "Put a Water Pok\xE9mon from your discard pile onto your Bench. If you do, attach up to 3 [W] Energy cards from your discard pile to that Pok\xE9mon."
        },
        {
          name: "Max Torrent",
          cost: [W, C, C],
          damage: 100,
          damageCalculation: "+",
          text: "If your opponent's Active Pok\xE9mon already has any damage counters on it, this attack does 100 more damage."
        }
      ];
      this.regulationMark = "E";
      this.set = "EVS";
      this.setNumber = "30";
      this.cardImage = "assets/cardback.png";
      this.name = "Vaporeon VMAX";
      this.fullName = "Vaporeon VMAX EVS";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const openSlots = player.bench.filter((b) => b.cards.length === 0);
        if (openSlots.length === 0) {
          return state;
        }
        const waterPokemonInDiscard = player.discard.cards.filter(
          (c) => c instanceof PokemonCard && pokemonHasCardType(c, 3 /* WATER */)
        );
        if (waterPokemonInDiscard.length === 0) {
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            player.discard,
            { superType: 1 /* POKEMON */, cardType: [3 /* WATER */] },
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length === 0) {
              return;
            }
            const benchSlot = openSlots[0];
            MOVE_CARDS(store, state, player.discard, benchSlot, { cards: [cards[0]], sourceCard: this });
            benchSlot.pokemonPlayedTurn = state.turn;
            const waterEnergyInDiscard = player.discard.cards.filter(
              (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(3 /* WATER */)
            );
            if (waterEnergyInDiscard.length > 0) {
              const benchIndex = player.bench.indexOf(benchSlot);
              ATTACH_ENERGY_PROMPT(
                store,
                state,
                player,
                2 /* BOTTOM_PLAYER */,
                4 /* DISCARD */,
                [2 /* BENCH */],
                { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
                {
                  min: 0,
                  max: 3,
                  allowCancel: false,
                  blockedTo: player.bench.map((b, i) => ({
                    player: 2 /* BOTTOM_PLAYER */,
                    slot: 2 /* BENCH */,
                    index: i
                  })).filter((t) => t.index !== benchIndex)
                }
              );
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.active.damage > 0) {
          effect.damage += 100;
        }
      }
      return state;
    }
  };

