  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-evolving-skies/gordie.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_prefabs();
  function* playCard204(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    if (player.deck.cards.length === 0) {
      return state;
    }
    const topCards = new CardList();
    const count = Math.min(7, player.deck.cards.length);
    MOVE_CARDS(store, state, player.deck, topCards, { count, sourceCard: self });
    const blocked = [];
    topCards.cards.forEach((c, index) => {
      if (c.superType !== 3 /* ENERGY */) {
        blocked.push(index);
      }
    });
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        topCards,
        { superType: 3 /* ENERGY */ },
        { min: 0, max: count, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, topCards, player.hand, { cards, sourceCard: self });
    MOVE_CARDS(store, state, topCards, player.deck, { sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return SHUFFLE_DECK(store, state, player);
  }
