  var ShoppingCenter = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "EVS";
      this.regulationMark = "E";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "157";
      this.name = "Shopping Center";
      this.fullName = "Shopping Center EVS";
      this.text = "Once during each player's turn, that player may put a Pok\xE9mon Tool attached to 1 of their Pok\xE9mon into their hand.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        let pokemonWithTool = false;
        const blockedTo = [];
        if (player.active.tools.length !== 0) {
          pokemonWithTool = true;
        }
        player.bench.forEach((bench, index) => {
          if (bench.cards.length === 0) {
            return;
          }
          if (bench.tools.length !== 0) {
            pokemonWithTool = true;
          } else {
            const target = {
              player: 2 /* BOTTOM_PLAYER */,
              slot: 2 /* BENCH */,
              index
            };
            blockedTo.push(target);
          }
        });
        if (!pokemonWithTool) {
          throw new GameError(GameMessage.CANNOT_USE_STADIUM);
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_CARDS,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { allowCancel: false, blocked: blockedTo }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const target = targets[0];
            const tool = target.tools[0];
            if (tool) {
              MOVE_CARDS(store, state, target, player.hand, { cards: [tool], sourceCard: this });
            }
          }
        );
      }
      return state;
    }
  };

