  var ToyCatcher = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.regulationMark = "E";
      this.set = "EVS";
      this.setNumber = "163";
      this.cardImage = "assets/cardback.png";
      this.name = "Toy Catcher";
      this.fullName = "Toy Catcher EVS";
      this.text = "Switch 1 of your opponent's Benched Pok\xE9mon that has 50 HP or less remaining with your opponent's Active Pok\xE9mon. You may play any number of Item cards during your turn. Attach a Pok\xE9mon Tool to 1 of your Pok\xE9mon that doesn't already have a Pok\xE9mon Tool attached.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let hasValidTarget = false;
        opponent.bench.forEach((b) => {
          if (b.cards.length > 0) {
            const checkHp = new CheckHpEffect(opponent, b);
            store.reduceEffect(state, checkHp);
            const remainingHp = checkHp.hp - b.damage;
            if (remainingHp <= 50) {
              hasValidTarget = true;
            }
          }
        });
        if (!hasValidTarget) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (target.slot !== 2 /* BENCH */) {
            return;
          }
          if (cardList.cards.length === 0) {
            blocked.push(target);
            return;
          }
          const checkHp = new CheckHpEffect(opponent, cardList);
          store.reduceEffect(state, checkHp);
          const remainingHp = checkHp.hp - cardList.damage;
          if (remainingHp > 50) {
            blocked.push(target);
          }
        });
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (selected) => {
            if (selected && selected.length > 0) {
              opponent.switchPokemon(selected[0]);
            }
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-evolving-skies/zinnias-resolve.ts
  init_trainer_card();
  init_card_types();
  init_play_card_effects();
  init_game_error();
  init_game_message();
  init_choose_cards_prompt();
  init_card_list();
  init_state_utils();
  init_prefabs();
  function* playCard206(next, store, state, self, effect) {
    const player = effect.player;
    let cards = [];
    cards = player.hand.cards.filter((c) => c !== self);
    if (cards.length < 2) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const handTemp = new CardList();
    handTemp.cards = player.hand.cards.filter((c) => c !== self);
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        handTemp,
        {},
        { min: 2, max: 2, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: self });
    const opponent = StateUtils.getOpponent(state, player);
    const cardsToDraw = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
    DRAW_CARDS(store, state, player, cardsToDraw);
    return state;
  }
  var ZinniasResolve = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "E";
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "EVS";
      this.setNumber = "164";
      this.cardImage = "assets/cardback.png";
      this.name = "Zinnia's Resolve";
      this.fullName = "Zinnia's Resolve EVS";
      this.text = `You can play this card only if you discard 2 other cards from your hand.

Draw a card for each of your opponent's Pok\xE9mon in play.`;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard206(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

