  var TreasureEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [C];
      this.energyType = 1 /* SPECIAL */;
      this.regulationMark = "E";
      this.set = "EVS";
      this.setNumber = "165";
      this.cardImage = "assets/cardback.png";
      this.name = "Treasure Energy";
      this.fullName = "Treasure Energy EVS";
      this.text = "As long as this card is attached to a Pok\xE9mon, it provides [C] Energy. If you took this card as a face-down Prize card during your turn, before you put it into your hand, you may attach this card to 1 of your Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DrawPrizesEffect) {
        const generator = this.handlePrizeEffect(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
    *handlePrizeEffect(next, store, state, effect) {
      const player = effect.player;
      const prizeCard = effect.prizes.find((cardList) => cardList.cards.includes(this));
      if (!prizeCard || !prizeCard.isSecret || effect.destination !== player.hand) {
        return state;
      }
      effect.preventDefault = true;
      let wantToUse = false;
      yield CONFIRMATION_PROMPT(store, state, player, (result) => {
        wantToUse = result;
        next();
      }, GameMessage.WANT_TO_USE_ITEM_FROM_PRIZES);
      if (!wantToUse) {
        effect.preventDefault = false;
        const prizeIndex2 = player.prizes.findIndex((prize) => prize.cards.includes(this));
        if (prizeIndex2 !== -1) {
          TAKE_SPECIFIC_PRIZES(store, state, player, [player.prizes[prizeIndex2]], { skipReduce: true });
        }
        return state;
      }
      const prizeIndex = player.prizes.findIndex((prize) => prize.cards.includes(this));
      if (prizeIndex !== -1) {
        MOVE_CARDS(store, state, player.prizes[prizeIndex], player.hand, { cards: [this], sourceCard: this });
      }
      let targets = [];
      yield store.prompt(state, new ChoosePokemonPrompt(
        player.id,
        GameMessage.ATTACH_ENERGY_CARDS,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: false }
      ), (result) => {
        targets = result || [];
        next();
      });
      if (targets.length > 0) {
        const target = targets[0];
        const attachEnergyEffect = new AttachEnergyEffect(player, this, target);
        store.reduceEffect(state, attachEnergyEffect);
      }
      return state;
    }
  };

