  init_game_phase_effects();
  init_attack_effects();
  var Absol10 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 100;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Drag Off",
          cost: [C, C],
          damage: 0,
          text: "Switch 1 of your opponent's Benched Pok\xE9mon with their Active Pok\xE9mon. This attack does 30 damage to the new Active Pok\xE9mon."
        },
        {
          name: "Slash",
          cost: [D, C, C],
          damage: 80,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "164";
      this.cardImage = "assets/cardback.png";
      this.name = "Absol";
      this.fullName = "Absol FST 164";
      this.usedDragOff = false;
      this.dragOffAttackEffect = null;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          this.usedDragOff = true;
          this.dragOffAttackEffect = effect;
        }
      }
      if (effect instanceof AfterAttackEffect && this.usedDragOff && this.dragOffAttackEffect) {
        this.usedDragOff = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        GUST_OPPONENT_BENCHED_POKEMON(store, state, player);
        const damageEffect = new DealDamageEffect(this.dragOffAttackEffect, 30);
        damageEffect.target = opponent.active;
        store.reduceEffect(state, damageEffect);
        this.dragOffAttackEffect = null;
      }
      if (effect instanceof EndTurnEffect) {
        this.usedDragOff = false;
        this.dragOffAttackEffect = null;
      }
      return state;
    }
  };

