  var Araquanid7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Dewpider";
      this.cardType = [G];
      this.hp = 120;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Bug Bite",
          cost: [G],
          damage: 30,
          text: ""
        },
        {
          name: "Bubble Launch",
          cost: [G, C, C],
          damage: 110,
          text: "Move an Energy from this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "20";
      this.cardImage = "assets/cardback.png";
      this.name = "Araquanid";
      this.fullName = "Araquanid FST 20";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.active,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

