  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Azumarill7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.cardType = [3 /* WATER */];
      this.hp = 120;
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.evolvesFrom = "Marill";
      this.attacks = [
        {
          name: "Dive and Rescue",
          cost: [3 /* WATER */],
          damage: 0,
          text: "Put up to 3 in any combination of Pok\xE9mon and Supporter cards from your discard pile into your hand. "
        },
        {
          name: "Surf",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 90,
          text: ""
        }
      ];
      this.set = "FST";
      this.setNumber = "59";
      this.regulationMark = "E";
      this.cardImage = "assets/cardback.png";
      this.name = "Azumarill";
      this.fullName = "Azumarill FST";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasSupporterOrPokemonInDiscard = player.discard.cards.some((c) => {
          return c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */ || c instanceof PokemonCard;
        });
        if (!hasSupporterOrPokemonInDiscard) {
          return state;
        }
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          const isPokemon = c instanceof PokemonCard;
          const isSupporter = c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */;
          if (!isPokemon && !isSupporter) {
            blocked.push(index);
          }
        });
        if (hasSupporterOrPokemonInDiscard) {
          let cards = [];
          return store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.discard,
            {},
            { min: 1, max: 3, allowCancel: false, blocked }
          ), (selected) => {
            cards = selected || [];
            MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: this });
          });
        }
      }
      return state;
    }
  };

