  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-fusion-strike/blissey.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_prefabs();
  var Blissey7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Chansey";
      this.cardType = [C];
      this.hp = 130;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Expert in Roundness",
          powerType: 2 /* ABILITY */,
          text: "Prevent all damage done to each of your Pok\xE9mon that has the Let's All Rollout attack by attacks from your opponent's Pok\xE9mon VMAX."
        }
      ];
      this.attacks = [
        {
          name: "Let's All Rollout",
          cost: [C, C, C],
          damage: 20,
          damageCalculation: "x",
          text: "This attack does 20 damage for each of your Benched Pok\xE9mon that has the Let's All Rollout attack."
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "203";
      this.cardImage = "assets/cardback.png";
      this.name = "Blissey";
      this.fullName = "Blissey FST 203";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect || effect instanceof PutDamageEffect) {
        const attackerCard = effect.source.getPokemonCard();
        if (!attackerCard || !attackerCard.hasTag("VMAX" /* POKEMON_VMAX */)) {
          return state;
        }
        const targetOwner = StateUtils.findOwner(state, effect.target);
        if (!targetOwner) {
          return state;
        }
        let blisseyInPlay = false;
        targetOwner.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            blisseyInPlay = true;
          }
        });
        if (!blisseyInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetOwner, this)) {
          return state;
        }
        const targetCard2 = effect.target.getPokemonCard();
        if (!targetCard2) {
          return state;
        }
        const hasRollout = targetCard2.attacks.some((a) => a.name === "Let's All Rollout");
        if (!hasRollout) {
          return state;
        }
        if (effect instanceof DealDamageEffect) {
          effect.damage = 0;
        } else {
          effect.preventDefault = true;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const benchedWithRollout = player.bench.filter((b) => {
          const card = b.getPokemonCard();
          return card && card.attacks.some((a) => a.name === "Let's All Rollout");
        }).length;
        effect.damage = 20 * benchedWithRollout;
      }
      return state;
    }
  };

