  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-fusion-strike/claydol.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_check_effects();
  init_game_phase_effects();
  init_prefabs();
  init_game();
  var Claydol8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Baltoy";
      this.cardType = [F];
      this.hp = 120;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Rapid Spin",
          cost: [C, C],
          damage: 30,
          text: "Switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon. If you do, your opponent switches their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon."
        },
        {
          name: "Ancient Imprint",
          cost: [F, F],
          damage: 0,
          text: "Put damage counters on your opponent's Active Pok\xE9mon until its remaining HP is 60."
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "145";
      this.cardImage = "assets/cardback.png";
      this.name = "Claydol";
      this.fullName = "Claydol FST 145";
      this.usedRapidSpin = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedRapidSpin = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedRapidSpin) {
        this.usedRapidSpin = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const playerBench = player.bench.some((b) => b.cards.length > 0);
        if (!playerBench) {
          return state;
        }
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (selected) => {
          if (!selected || selected.length === 0) return;
          player.switchPokemon(selected[0], store, state);
          if (opponent.bench.some((b) => b.cards.length > 0)) {
            SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
          }
        });
      }
      if (effect instanceof EndTurnEffect) {
        this.usedRapidSpin = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkHpEffect = new CheckHpEffect(player, opponent.active);
        store.reduceEffect(state, checkHpEffect);
        const totalHp = checkHpEffect.hp;
        const targetHp = 60;
        let damageAmount = totalHp - targetHp;
        const existingDamage = opponent.active.damage;
        if (existingDamage > 0) {
          damageAmount = Math.max(0, damageAmount - existingDamage);
        }
        if (damageAmount > 0) {
          const damageEffect = new PutDamageEffect(effect, damageAmount);
          damageEffect.target = opponent.active;
          store.reduceEffect(state, damageEffect);
        }
      }
      return state;
    }
  };

