  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-fusion-strike/cloyster.ts
  init_game();
  init_card_types();
  init_pokemon_card();
  init_pokemon_types();
  init_attack_effects();
  init_state_utils();
  init_state();
  init_prefabs();
  var Cloyster6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "E";
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Shellder";
      this.cardType = [3 /* WATER */];
      this.hp = 130;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Shell Armor",
        powerType: 2 /* ABILITY */,
        text: "This Pokemon takes 30 less damage from attacks (after applying Weakness and Resistance)."
      }];
      this.attacks = [{
        name: "Aqua Split",
        cost: [3 /* WATER */, 9 /* COLORLESS */],
        damage: 60,
        text: "This attack also does 30 damage to 2 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.set = "FST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "51";
      this.name = "Cloyster";
      this.fullName = "Cloyster FST";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.damage = Math.max(0, effect.damage - 30);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const benched = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        const min = Math.min(2, benched);
        const max = Math.min(2, benched);
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { min, max, allowCancel: false }
        ), (selected) => {
          const targets = selected || [];
          targets.forEach((target) => {
            const damageEffect = new PutDamageEffect(effect, 30);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          });
          return state;
        });
      }
      return state;
    }
  };

