  var Corviknight2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Corvisquire";
      this.cardType = [M];
      this.hp = 170;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Steel Wing",
          cost: [M],
          damage: 50,
          text: "During your opponent's next turn, this Pok\xE9mon takes 30 less damage from attacks (after applying Weakness and Resistance)."
        },
        {
          name: "Power Cyclone",
          cost: [M, C, C],
          damage: 160,
          text: "Move an Energy from this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "190";
      this.cardImage = "assets/cardback.png";
      this.name = "Corviknight";
      this.fullName = "Corviknight FST 190";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.player.active.damageReductionNextTurn = 30;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const attachedEnergies = player.active.cards.filter(
          (card) => card.superType === 3 /* ENERGY */
        );
        if (attachedEnergies.length === 0) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.active,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

