  var Delcatty9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Skitty";
      this.cardType = [C];
      this.hp = 100;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [{
        name: "Willful Busybody",
        cost: [C],
        damage: 0,
        text: "Your opponent reveals their hand. Choose a card you find there and put it on the bottom of their deck."
      }, {
        name: "Double Slap",
        cost: [C, C],
        damage: 50,
        damageCalculation: "x",
        text: "Flip 2 coins. This attack does 50 damage for each heads."
      }];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "211";
      this.cardImage = "assets/cardback.png";
      this.name = "Delcatty";
      this.fullName = "Delcatty FST 211";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.hand.cards.length === 0) {
          return state;
        }
        SHOW_CARDS_TO_PLAYER(store, state, player, opponent.hand.cards);
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DECK,
          opponent.hand,
          {},
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length > 0) {
            MOVE_CARDS(store, state, opponent.hand, opponent.deck, { cards, sourceCard: this });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 2, (results) => {
          effect.damage = 50 * results.filter((r) => r).length;
        });
      }
      return state;
    }
  };

