  var Dragapult = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "E";
      this._tags = ["Fusion Strike" /* FUSION_STRIKE */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Drakloak";
      this.cardType = [P];
      this.hp = 150;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [];
      this.attacks = [
        {
          name: "Fusion Strike Assault",
          cost: [P],
          damage: 30,
          damageCalculation: "x",
          text: "This attack does 30 damage for each of your Fusion Strike Pok\xE9mon in play."
        },
        {
          name: "Speed Attack",
          cost: [P, C],
          damage: 120,
          text: ""
        }
      ];
      this.set = "FST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "130";
      this.name = "Dragapult";
      this.fullName = "Dragapult FST";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const playerBench = player.bench;
        let fusionStrikeCount = 0;
        playerBench.forEach((c) => {
          if (c.getPokemonCard() instanceof PokemonCard) {
            if (c.getPokemonCard()?.hasTag("Fusion Strike" /* FUSION_STRIKE */)) {
              fusionStrikeCount++;
            }
          }
        });
        if (player.active.getPokemonCard()?.hasTag("Fusion Strike" /* FUSION_STRIKE */)) {
          fusionStrikeCount++;
        }
        effect.damage = 30 * fusionStrikeCount;
        return state;
      }
      return state;
    }
  };

