  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-fusion-strike/galarian-cursola.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_check_effects();
  init_prefabs();
  init_choose_cards_prompt();
  var GalarianCursola = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Galarian Corsola";
      this.cardType = [P];
      this.hp = 100;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Force Regeneration",
          cost: [P],
          damage: 0,
          text: "Put a Basic Pok\xE9mon V from your opponent's discard pile onto their Bench. If you do, put damage counters on that Pok\xE9mon until its remaining HP is 30."
        },
        {
          name: "Spooky Shot",
          cost: [P, C, C],
          damage: 80,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "118";
      this.cardImage = "assets/cardback.png";
      this.name = "Galarian Cursola";
      this.fullName = "Galarian Cursola FST 118";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const attackEffect = effect;
        const player = attackEffect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const slots2 = opponent.bench.filter((b) => b.cards.length === 0);
        const hasVInDiscard = opponent.discard.cards.some(
          (c) => c instanceof PokemonCard && c.stage === 2 /* BASIC */ && (c.hasTag("V" /* POKEMON_V */) || c.hasTag("VMAX" /* POKEMON_VMAX */) || c.hasTag("VSTAR" /* POKEMON_VSTAR */))
        );
        if (!hasVInDiscard || slots2.length === 0) {
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            opponent.discard,
            { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            if (!selected || selected.length === 0) {
              return;
            }
            const chosenCard = selected[0];
            if (!chosenCard.hasTag("V" /* POKEMON_V */) && !chosenCard.hasTag("VMAX" /* POKEMON_VMAX */) && !chosenCard.hasTag("VSTAR" /* POKEMON_VSTAR */)) {
              return;
            }
            MOVE_CARDS(store, state, opponent.discard, slots2[0], { cards: [chosenCard], sourceCard: this });
            slots2[0].pokemonPlayedTurn = state.turn;
            const checkHp = new CheckHpEffect(opponent, slots2[0]);
            store.reduceEffect(state, checkHp);
            const maxHp = checkHp.hp;
            const existingDamage = slots2[0].damage;
            const damageToPlace = Math.max(0, maxHp - 30 - existingDamage);
            if (damageToPlace > 0) {
              const damageEffect = new PutDamageEffect(attackEffect, damageToPlace);
              damageEffect.target = slots2[0];
              store.reduceEffect(state, damageEffect);
            }
          }
        );
      }
      return state;
    }
  };

