  var Huntail3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Fusion Strike" /* FUSION_STRIKE */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Clamperl";
      this.cardType = [W];
      this.hp = 110;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Single Strike Jammer",
          powerType: 2 /* ABILITY */,
          text: "Your opponent's Single Strike Pok\xE9mon's attacks cost Colorless more."
        }
      ];
      this.attacks = [
        {
          name: "Cavernous Chomp",
          cost: [W, C, C],
          damage: 80,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "66";
      this.cardImage = "assets/cardback.png";
      this.name = "Huntail";
      this.fullName = "Huntail FST 66";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect) {
        const player = effect.player;
        const attackingPokemon = player.active.getPokemonCard();
        if (!attackingPokemon || !attackingPokemon.hasTag("Single Strike" /* SINGLE_STRIKE */)) {
          return state;
        }
        let huntailInPlay = false;
        state.players.forEach((p) => {
          if (p !== player) {
            p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
              if (card === this) {
                huntailInPlay = true;
              }
            });
          }
        });
        if (!huntailInPlay) {
          return state;
        }
        let huntailOwner = state.players.find((p) => p !== player);
        if (!huntailOwner) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, huntailOwner, this)) {
          return state;
        }
        effect.cost.push(9 /* COLORLESS */);
      }
      return state;
    }
  };

