  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-fusion-strike/inteleon-vmax.ts
  init_game();
  init_play_card_effects();
  init_prefabs();
  var InteleonVMAX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Inteleon V";
      this._tags = ["VMAX" /* POKEMON_VMAX */, "Rapid Strike" /* RAPID_STRIKE */];
      this.cardType = [W];
      this.hp = 320;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Double Gunner",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "You must discard a [W] Energy card from your hand in order to use this Ability. Once during your turn, you may choose 2 of your opponent's Benched Pok\xE9mon and put 2 damage counters on each of them."
        }
      ];
      this.attacks = [
        {
          name: "Aqua Bullet",
          cost: [3 /* WATER */, 9 /* COLORLESS */],
          damage: 70,
          text: "You may put an Energy attached to this Pok\xE9mon into your hand. If you do, this attack does 70 more damage."
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "79";
      this.name = "Inteleon VMAX";
      this.fullName = "Inteleon VMAX FST";
      this.DOUBLE_GUNNER_MARKER = "DOUBLE_GUNNER_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        REMOVE_MARKER(this.DOUBLE_GUNNER_MARKER, effect.player, this);
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.DOUBLE_GUNNER_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const attacker = effect.source;
        attacker.pendingEnergyReturnToHand = [];
        const energyCards = attacker.cards.filter((c) => c.superType === 3 /* ENERGY */);
        if (energyCards.length === 0) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (!wantToUse) {
            return;
          }
          const cardList = new CardList();
          cardList.cards = energyCards;
          state = store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_ENERGIES_TO_HAND,
            cardList,
            { superType: 3 /* ENERGY */ },
            { min: 1, max: 1, allowCancel: false }
          ), (energies) => {
            const cards = energies || [];
            if (cards.length === 0) {
              return;
            }
            effect.damage += 70;
            attacker.pendingEnergyReturnToHand = cards;
          });
        });
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        const attacker = player.active;
        const cards = attacker.pendingEnergyReturnToHand;
        if (cards.length === 0) {
          return state;
        }
        attacker.pendingEnergyReturnToHand = [];
        MOVE_CARDS(store, state, attacker, player.hand, { cards, sourceCard: this });
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (HAS_MARKER(this.DOUBLE_GUNNER_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const hasWaterEnergy = player.hand.cards.some(
          (c) => c instanceof EnergyCard && c.name === "Water Energy"
        );
        if (!hasWaterEnergy) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (!opponent.bench.some((b) => b.cards.length > 0)) {
          return state;
        }
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 3 /* ENERGY */, name: "Water Energy" },
          { allowCancel: true, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          MOVE_CARDS(store, state, player.hand, player.discard, {
            cards,
            sourceCard: this,
            sourceEffect: this.powers[0]
          });
          store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 2, allowCancel: false }
          ), (selected) => {
            (selected || []).forEach((target) => {
              target.damage += 20;
            });
            ADD_MARKER(this.DOUBLE_GUNNER_MARKER, player, this);
            ABILITY_USED(player, this);
          });
        });
      }
      return state;
    }
  };

