  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-fusion-strike/landorus.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Landorus4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 120;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Strafe",
          cost: [C],
          damage: 20,
          text: "You may switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Earthen Boom",
          cost: [F, F, C],
          damage: 120,
          text: "Move all Energy from this Pok\xE9mon to your Benched Pok\xE9mon in any way you like."
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "148";
      this.cardImage = "assets/cardback.png";
      this.name = "Landorus";
      this.fullName = "Landorus FST 148";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        if (player.bench.some((b) => b.cards.length > 0)) {
          state = store.prompt(state, new ConfirmPrompt(
            player.id,
            GameMessage.WANT_TO_SWITCH_POKEMON
          ), (wantToUse) => {
            if (wantToUse) {
              SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
            }
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const attachedEnergies = player.active.cards.filter((card) => card instanceof EnergyCard);
        if (attachedEnergies.length === 0) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.active,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: attachedEnergies.length, max: attachedEnergies.length }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

