  var Lapras15 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [3 /* WATER */];
      this.hp = 120;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Icy Wind",
          cost: [9 /* COLORLESS */],
          damage: 0,
          text: "Your opponent's Active Pok\xE9mon is now Asleep."
        },
        {
          name: "Splash Arch",
          cost: [3 /* WATER */, 3 /* WATER */, 9 /* COLORLESS */],
          damage: 0,
          text: "Put all Energy attached to this Pok\xE9mon into your hand. This attack does 100 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "FST";
      this.regulationMark = "E";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "54";
      this.name = "Lapras";
      this.fullName = "Lapras FST";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const attachedEnergy = effect.source.cards.filter((c) => c instanceof EnergyCard);
        for (const energy2 of attachedEnergy) {
          MOVE_CARDS(store, state, player.active, player.hand, { cards: [energy2], sourceCard: this });
        }
        const opponent = StateUtils.getOpponent(state, player);
        const benched = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        const min = Math.min(1, benched);
        const max = Math.min(1, benched);
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { min, max, allowCancel: false }
        ), (selected) => {
          const targets = selected || [];
          targets.forEach((target) => {
            const damageEffect = new PutDamageEffect(effect, 100);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          });
          return state;
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const sleepEffect = new AddSpecialConditionsEffect(effect, [2 /* ASLEEP */]);
        store.reduceEffect(state, sleepEffect);
      }
      return state;
    }
  };

