  var Maractus6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 110;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.attacks = [
        { name: "Venomous Hit", cost: [G], damage: 20, text: "" },
        {
          name: "Ditch and Shake",
          cost: [G, C],
          damage: 50,
          damageCalculation: "x",
          text: "Discard any number of Pok\xE9mon Tool cards from your hand. This attack does 50 damage for each card you discarded in this way. "
        }
      ];
      this.set = "FST";
      this.name = "Maractus";
      this.fullName = "Maractus FST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "12";
      this.regulationMark = "E";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const blocked = player.hand.cards.filter((c) => c instanceof TrainerCard && c.trainerType !== 3 /* TOOL */).map((c) => player.hand.cards.indexOf(c));
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 2 /* TRAINER */ },
          { allowCancel: false, min: 0, blocked }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = player.active;
          store.reduceEffect(state, discardEnergy2);
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
          const damage = cards.length * 50;
          effect.damage = damage;
          return state;
        });
      }
      return state;
    }
  };

