  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-fusion-strike/ninetales-2.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var Ninetales22 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Vulpix";
      this.cardType = [R];
      this.hp = 120;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Byway of the Nine-Tailed Fox",
        powerType: 2 /* ABILITY */,
        text: "The Retreat Cost of each of your Pok\xE9mon that has any [R] Energy attached is ColorlessColorless less."
      }];
      this.attacks = [
        {
          name: "Flame Tail",
          cost: [R, C],
          damage: 60,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "31";
      this.cardImage = "assets/cardback.png";
      this.name = "Ninetales";
      this.fullName = "Ninetales FST 31";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner !== player) {
          return state;
        }
        let isNinetalesInPlay = false;
        owner.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card) => {
          if (card === this) {
            isNinetalesInPlay = true;
          }
        });
        if (!isNinetalesInPlay) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        const hasFireEnergy = checkEnergy.energyMap.some(
          (em) => em.provides.some((t) => t === 2 /* FIRE */ || t === 0 /* ANY */)
        );
        if (hasFireEnergy) {
          let removed = 0;
          effect.cost = effect.cost.filter((c) => {
            if (removed < 2 && c === 9 /* COLORLESS */) {
              removed++;
              return false;
            }
            return true;
          });
        }
      }
      return state;
    }
  };

