  var Pyukumuku4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [3 /* WATER */];
      this.hp = 80;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Pitch a Pyukumuku",
        useFromHand: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, if this Pok\xE9mon is in your hand, you may reveal it and put it on the bottom of your deck. If you do, draw a card. You can't use more than 1 Pitch a Pyukumuku Ability each turn."
      }];
      this.attacks = [{
        name: " Knuckle Punch",
        cost: [3 /* WATER */, 9 /* COLORLESS */, 9 /* COLORLESS */],
        damage: 50,
        text: ""
      }];
      this.set = "FST";
      this.regulationMark = "E";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "77";
      this.name = "Pyukumuku";
      this.fullName = "Pyukumuku FST";
      this.PYUK_MARKER = "PYUK_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.PYUK_MARKER, this)) {
        effect.player.marker.removeMarker(this.PYUK_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.PYUK_MARKER, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const deckBottom = new CardList();
        player.marker.addMarker(this.PYUK_MARKER, this);
        MOVE_CARDS(store, state, player.hand, deckBottom, { cards: [this], sourceCard: this });
        MOVE_CARDS(store, state, deckBottom, player.deck, { sourceCard: this });
        MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
      }
      return state;
    }
  };

