  var RillaboomVmax = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VMAX" /* POKEMON_VMAX */, "Rapid Strike" /* RAPID_STRIKE */];
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Rillaboom V";
      this.cardType = [G];
      this.hp = 330;
      this.weakness = [{ type: R }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "G-Max Drum Solo",
          cost: [G, C, C, C],
          damage: 180,
          text: "This attack also does 40 damage to 2 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "23";
      this.cardImage = "assets/cardback.png";
      this.name = "Rillaboom VMAX";
      this.fullName = "Rillaboom VMAX FST 23";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const benchedPokemon = opponent.bench.filter((b) => b.cards.length > 0);
        if (benchedPokemon.length === 0) {
          return state;
        }
        const max = Math.min(2, benchedPokemon.length);
        const attackEffect = effect;
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: max, max, allowCancel: false }
          ),
          (selected) => {
            const targets = selected || [];
            DAMAGE_OPPONENT_POKEMON(store, state, attackEffect, 40, targets);
          }
        );
      }
      return state;
    }
  };

