  var Smeargle5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Fusion Strike" /* FUSION_STRIKE */];
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 70;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Sketching Trash",
          cost: [C],
          damage: 0,
          text: "Put up to 2 Fusion Strike Trainer cards from your discard pile into your hand."
        },
        {
          name: "Tail Whap",
          cost: [C, C, C],
          damage: 80,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "209";
      this.cardImage = "assets/cardback.png";
      this.name = "Smeargle";
      this.fullName = "Smeargle FST 209";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const fusionTrainers = player.discard.cards.filter(
          (c) => c instanceof TrainerCard && c.superType === 2 /* TRAINER */ && c.hasTag("Fusion Strike" /* FUSION_STRIKE */)
        );
        if (fusionTrainers.length === 0) {
          return state;
        }
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          const isFusionTrainer = c instanceof TrainerCard && c.superType === 2 /* TRAINER */ && c.hasTag("Fusion Strike" /* FUSION_STRIKE */);
          if (!isFusionTrainer) {
            blocked.push(index);
          }
        });
        const max = Math.min(2, fusionTrainers.length);
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.discard,
            { superType: 2 /* TRAINER */ },
            { min: 0, max, allowCancel: false, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: this });
          }
        );
      }
      return state;
    }
  };

