  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-fusion-strike/starmie.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_attack_effects();
  init_prefabs();
  var Starmie10 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Staryu";
      this.cardType = [3 /* WATER */];
      this.hp = 90;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.retreat = [9 /* COLORLESS */];
      this._tags = ["Rapid Strike" /* RAPID_STRIKE */];
      this.attacks = [
        {
          name: "Multishot Star",
          cost: [3 /* WATER */],
          damage: 0,
          text: "Discard any amount of [W] Energy from this Pok\xE9mon. Then, for each Energy you discarded in this way, choose 1 of your opponent's Pok\xE9mon and do 30 damage to it. (You can choose the same Pok\xE9mon more than once.) This damage isn't affected by Weakness or Resistance. "
        }
      ];
      this.set = "FST";
      this.regulationMark = "E";
      this.setNumber = "53";
      this.cardImage = "assets/cardback.png";
      this.name = "Starmie";
      this.fullName = "Starmie FST";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        const waterCards = new Set(
          checkEnergy.energyMap.filter((em) => em.provides.includes(3 /* WATER */) || em.provides.includes(0 /* ANY */)).map((em) => em.card)
        );
        const blocked = [];
        player.active.cards.forEach((c, i) => {
          if (c.superType === 3 /* ENERGY */ && !waterCards.has(c)) {
            blocked.push(i);
          }
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            player.active,
            // Card source is target Pokemon
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              const energyToDiscard = new CardList();
              energyToDiscard.cards.push(...cards);
              const discardEnergy2 = new DiscardCardsEffect(effect, energyToDiscard.cards);
              discardEnergy2.target = player.active;
              store.reduceEffect(state, discardEnergy2);
              const damage = cards.length * 30;
              const maxAllowedDamage = [];
              opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
                maxAllowedDamage.push({ target, damage: card.hp + damage });
              });
              return store.prompt(
                state,
                new PutDamagePrompt(
                  effect.player.id,
                  GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
                  1 /* TOP_PLAYER */,
                  [1 /* ACTIVE */, 2 /* BENCH */],
                  damage,
                  maxAllowedDamage,
                  { allowCancel: false, damageMultiple: 30 }
                ),
                (targets) => {
                  const results = targets || [];
                  for (const result of results) {
                    const target = StateUtils.getTarget(state, player, result.target);
                    const putCountersEffect = new PutCountersEffect(effect, result.damage);
                    putCountersEffect.target = target;
                    store.reduceEffect(state, putCountersEffect);
                  }
                }
              );
            }
            return state;
          }
        );
      }
      return state;
    }
  };

