  var Swampert5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.cardType = [3 /* WATER */];
      this.hp = 170;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.evolvesFrom = "Marshtomp";
      this.powers = [{
        name: "Muddy Maker",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may attach a [W] Energy card or a [F] Energy card from your hand to 1 of your Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Earthquake",
        cost: [3 /* WATER */, 9 /* COLORLESS */, 9 /* COLORLESS */],
        damage: 180,
        text: "This attack also does 20 damage to each of your Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.set = "FST";
      this.regulationMark = "E";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "64";
      this.name = "Swampert";
      this.fullName = "Swampert FST";
      this.MUDDY_MAKER_MARKER = "MUDDY_MAKER_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (cardList === player.active) {
            return;
          }
          const damageEffect = new PutDamageEffect(effect, 20);
          damageEffect.target = cardList;
          store.reduceEffect(state, damageEffect);
        });
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (player.marker.hasMarker(this.MUDDY_MAKER_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const hasEnergyInHand = player.hand.cards.some((c) => {
          const isBasicFightingEnergy = c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.name === "Fightning Energy";
          const isBasicWaterEnergy = c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.name === "Water Energy";
          return isBasicFightingEnergy || isBasicWaterEnergy;
        });
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const options = [
          {
            message: GameMessage.WANT_TO_ATTACH_ONLY_WATER_ENERGY,
            action: () => {
              return store.prompt(state, new AttachEnergyPrompt(
                player.id,
                GameMessage.ATTACH_ENERGY_CARDS,
                player.hand,
                2 /* BOTTOM_PLAYER */,
                [2 /* BENCH */, 1 /* ACTIVE */],
                { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
                { allowCancel: true, min: 1, max: 1 }
              ), (transfers) => {
                transfers = transfers || [];
                for (const transfer of transfers) {
                  const target = StateUtils.getTarget(state, player, transfer.to);
                  const energyCard = transfer.card;
                  const attachEnergyEffect = new AttachEnergyEffect(player, energyCard, target);
                  store.reduceEffect(state, attachEnergyEffect);
                }
                player.marker.addMarker(this.MUDDY_MAKER_MARKER, this);
                player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
                  if (cardList.getPokemonCard() === this) {
                    cardList.addBoardEffect(0 /* ABILITY_USED */);
                  }
                });
              });
            }
          },
          {
            message: GameMessage.WANT_TO_ATTACH_ONLY_FIGHTING_ENERGY,
            action: () => {
              return store.prompt(state, new AttachEnergyPrompt(
                player.id,
                GameMessage.ATTACH_ENERGY_CARDS,
                player.hand,
                2 /* BOTTOM_PLAYER */,
                [2 /* BENCH */, 1 /* ACTIVE */],
                { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fighting Energy" },
                { allowCancel: true, min: 1, max: 1 }
              ), (transfers) => {
                transfers = transfers || [];
                for (const transfer of transfers) {
                  const target = StateUtils.getTarget(state, player, transfer.to);
                  const energyCard = transfer.card;
                  const attachEnergyEffect = new AttachEnergyEffect(player, energyCard, target);
                  store.reduceEffect(state, attachEnergyEffect);
                }
                player.marker.addMarker(this.MUDDY_MAKER_MARKER, this);
                player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
                  if (cardList.getPokemonCard() === this) {
                    cardList.addBoardEffect(0 /* ABILITY_USED */);
                  }
                });
              });
            }
          }
        ];
        return store.prompt(state, new SelectPrompt(
          player.id,
          GameMessage.CHOOSE_OPTION,
          options.map((opt) => opt.message),
          { allowCancel: false }
        ), (choice) => {
          const option = options[choice];
          option.action();
        });
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.MUDDY_MAKER_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.MUDDY_MAKER_MARKER, this);
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.MUDDY_MAKER_MARKER, this);
        return state;
      }
      return state;
    }
  };

