  var Toxtricity22 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Fusion Strike" /* FUSION_STRIKE */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Toxel";
      this.cardType = [L];
      this.hp = 120;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Maximum Downer",
          powerType: 2 /* ABILITY */,
          text: "If all your Pok\xE9mon in play are Fusion Strike Pok\xE9mon, your opponent's Pok\xE9mon VMAX in play get -30 HP."
        }
      ];
      this.attacks = [
        {
          name: "Head Bolt",
          cost: [L, L, C],
          damage: 90,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "108";
      this.cardImage = "assets/cardback.png";
      this.name = "Toxtricity";
      this.fullName = "Toxtricity FST 108";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckHpEffect) {
        const targetCard2 = effect.target.getPokemonCard();
        if (!targetCard2 || !targetCard2.hasTag("VMAX" /* POKEMON_VMAX */)) {
          return state;
        }
        const targetOwner = StateUtils.findOwner(state, effect.target);
        let toxOwner = null;
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              toxOwner = p;
            }
          });
        });
        if (!toxOwner || toxOwner === targetOwner) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, toxOwner, this)) {
          return state;
        }
        let allFusionStrike = true;
        toxOwner.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const card = cardList.getPokemonCard();
          if (card && !card.hasTag("Fusion Strike" /* FUSION_STRIKE */)) {
            allFusionStrike = false;
          }
        });
        if (!allFusionStrike) {
          return state;
        }
        effect.hp = Math.max(10, effect.hp - 30);
      }
      return state;
    }
  };

