  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-fusion-strike/wooloo.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_energy_card();
  init_attack_effects();
  init_prefabs();
  var Wooloo2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 60;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Derail",
          cost: [C],
          damage: 10,
          text: "Discard a Special Energy from your opponent's Active Pok\xE9mon."
        },
        {
          name: "Let's All Rollout",
          cost: [C, C],
          damage: 20,
          damageCalculation: "x",
          text: "This attack does 20 damage for each of your Benched Pok\xE9mon that has the Let's All Rollout attack."
        }
      ];
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "221";
      this.cardImage = "assets/cardback.png";
      this.name = "Wooloo";
      this.fullName = "Wooloo FST 221";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasSpecialEnergy = opponent.active.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 1 /* SPECIAL */
        );
        if (!hasSpecialEnergy) {
          return state;
        }
        const blocked = [];
        opponent.active.cards.forEach((c, index) => {
          if (!(c instanceof EnergyCard) || c.energyType !== 1 /* SPECIAL */) {
            blocked.push(index);
          }
        });
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          opponent.active,
          { superType: 3 /* ENERGY */ },
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length > 0) {
            const discardEnergy2 = new DiscardCardsEffect(effect, cards);
            discardEnergy2.target = opponent.active;
            store.reduceEffect(state, discardEnergy2);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const benchedWithRollout = player.bench.filter((b) => {
          const card = b.getPokemonCard();
          return card && card.attacks.some((a) => a.name === "Let's All Rollout");
        }).length;
        effect.damage = 20 * benchedWithRollout;
      }
      return state;
    }
  };

