  var Sidney = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "241";
      this.cardImage = "assets/cardback.png";
      this.name = "Sidney";
      this.fullName = "Sidney FST 241";
      this.text = "Your opponent reveals their hand. Discard up to 2 in any combination of Pok\xE9mon Tool cards, Special Energy cards, and Stadium cards from it. You may play only 1 Supporter card during your turn.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.hand.cards.length === 0) {
          return state;
        }
        var eligibleCount = 0;
        const blocked = [];
        opponent.hand.cards.forEach((card, index) => {
          const isTool = card instanceof TrainerCard && card.trainerType === 3 /* TOOL */;
          const isSpecialEnergy = card instanceof EnergyCard && card.energyType === 1 /* SPECIAL */;
          const isStadium = card instanceof TrainerCard && card.trainerType === 2 /* STADIUM */;
          if (isTool || isSpecialEnergy || isStadium) {
            eligibleCount++;
          } else {
            blocked.push(index);
          }
        });
        const max = Math.min(2, eligibleCount);
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.hand,
            {},
            { min: 0, max, allowCancel: false, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards, sourceCard: this });
          }
        );
      }
      return state;
    }
  };

