  var SpongyGloves = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.regulationMark = "E";
      this.set = "FST";
      this.setNumber = "243";
      this.cardImage = "assets/cardback.png";
      this.name = "Spongy Gloves";
      this.fullName = "Spongy Gloves FST 243";
      this.text = "The attacks of the Pok\xE9mon this card is attached to do 30 more damage to your opponent's Active Water Pok\xE9mon (before applying Weakness and Resistance). You may play any number of Item cards during your turn. Attach a Pok\xE9mon Tool to 1 of your Pok\xE9mon that doesn't already have a Pok\xE9mon Tool attached.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.source.tools.includes(this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (effect.target !== opponent.active) {
          return state;
        }
        const targetCard2 = opponent.active.getPokemonCard();
        if (targetCard2 && pokemonHasCardType(targetCard2, 3 /* WATER */)) {
          const attack3 = effect.attack;
          if (attack3 && attack3.damage > 0) {
            effect.damage += 30;
          }
        }
      }
      return state;
    }
  };

