  var FusionStrikeEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [9 /* COLORLESS */];
      this._tags = ["Fusion Strike" /* FUSION_STRIKE */];
      this.energyType = 1 /* SPECIAL */;
      this.set = "FST";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "244";
      this.regulationMark = "E";
      this.name = "Fusion Strike Energy";
      this.fullName = "Fusion Strike Energy FST";
      this.text = "This card can only be attached to a Fusion Strike Pok\xE9mon. If this card is attached to anything other than a Fusion Strike Pok\xE9mon, discard this card.\n\nAs long as this card is attached to a Pok\xE9mon, it provides every type of Energy but provides only 1 Energy at a time. Prevent all effects of your opponent's Pok\xE9mon's Abilities done to the Pok\xE9mon this card is attached to.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        const pokemon = effect.source;
        if (pokemon.getPokemonCard()?.hasTag("Fusion Strike" /* FUSION_STRIKE */)) {
          effect.energyMap.push({ card: this, provides: [0 /* ANY */] });
        }
      }
      if (effect instanceof EffectOfAbilityEffect && effect.target?.cards.includes(this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.getPokemonInPlay().includes(effect.target) && effect.target.cards.includes(this)) {
          if (!IS_SPECIAL_ENERGY_BLOCKED(store, state, opponent, this, effect.target, true)) {
            effect.target = void 0;
          }
        }
      }
      if (effect instanceof PlaceDamageCountersEffect && effect.target.energies.cards.includes(this)) {
        effect.preventDefault = true;
      }
      if (effect instanceof AttachEnergyEffect) {
        if (effect.energyCard === this && !effect.target.getPokemonCard()?.hasTag("Fusion Strike" /* FUSION_STRIKE */)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
      }
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (!cardList.cards.includes(this) || IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, cardList)) {
              return;
            }
            if (!cardList.getPokemonCard()?.hasTag("Fusion Strike" /* FUSION_STRIKE */)) {
              MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
            }
          });
        });
      }
      return state;
    }
  };

