  function* playCard211(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    cards = player.hand.cards.filter((c) => c !== self);
    if (cards.length < 1) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    if (cards.length === 1) {
      MOVE_CARDS(store, state, player.hand, player.discard, { cards: [cards[0]], sourceCard: self });
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    const handTemp = new CardList();
    handTemp.cards = player.hand.cards.filter((c) => c !== self);
    if (cards.length > 1) {
      yield store.prompt(
        state,
        new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          handTemp,
          {},
          { min: 1, max: 1, allowCancel: false }
        ),
        (selected) => {
          cards = selected || [];
          next();
        }
      );
    }
    if (cards.length === 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: self });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
        { min: 0, max: 1, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var QuickBall2 = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "SSH";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "179";
      this.regulationMark = "D";
      this.name = "Quick Ball";
      this.fullName = "Quick Ball SSH";
      this.text = "You can play this card only if you discard another card from your hand. Search your deck for a Basic Pokemon, reveal it, and put it into your hand. Then, shuffle your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard211(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

