  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-lost-origin/aerodactyl-vstar.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_ability_lock();
  var AerodactylVstar = class _AerodactylVstar extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VSTAR" /* POKEMON_VSTAR */];
      this.stage = 6 /* VSTAR */;
      this.evolvesFrom = "Aerodactyl V";
      this.cardType = [F];
      this.hp = 260;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Lost Dive",
          cost: [F, C, C],
          damage: 240,
          text: "Put the top 3 cards of your deck in the Lost Zone."
        },
        {
          name: "Ancient Star",
          cost: [C],
          damage: 0,
          text: `Until this Pok\xE9mon leaves play, it gains an Ability that has the effect "Your opponent's Pok\xE9mon V in play, except any Aerodactyl VSTAR, have no Abilities." (You can't use more than 1 VSTAR Power in a game.)`
        }
      ];
      this.regulationMark = "F";
      this.set = "LOR";
      this.setNumber = "93";
      this.cardImage = "assets/cardback.png";
      this.name = "Aerodactyl VSTAR";
      this.fullName = "Aerodactyl VSTAR LOR 93";
      this.ancientStarActive = false;
    }
    static {
      this.V_TAGS = ["V" /* POKEMON_V */, "VMAX" /* POKEMON_VMAX */, "VSTAR" /* POKEMON_VSTAR */];
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const lostCount = Math.min(3, player.deck.cards.length);
        if (lostCount > 0) {
          MOVE_CARDS(store, state, player.deck, player.lostzone, { count: lostCount, sourceCard: this });
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        if (player.usedVSTAR === true) {
          throw new GameError(GameMessage.LABEL_VSTAR_USED);
        }
        player.usedVSTAR = true;
        this.ancientStarActive = true;
      }
      if (this.ancientStarActive) {
        let isInPlay = false;
        let aerodactylPlayer = state.players[0];
        state.players.forEach((p) => {
          p.forEachPokemon(2 /* BOTTOM_PLAYER */, (_cardList, card) => {
            if (card === this) {
              isInPlay = true;
              aerodactylPlayer = p;
            }
          });
        });
        if (!isInPlay) {
          this.ancientStarActive = false;
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, aerodactylPlayer, this)) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, aerodactylPlayer);
        HANDLE_ABILITY_LOCK(
          effect,
          ({ card }) => {
            if (card.name === "Aerodactyl VSTAR") {
              return false;
            }
            if (!_AerodactylVstar.V_TAGS.some((tag) => card.hasTag(tag))) {
              return false;
            }
            let targetBelongsToOpponent = false;
            opponent.forEachPokemon(1 /* TOP_PLAYER */, (_cardList, pokemon) => {
              if (pokemon === card) {
                targetBelongsToOpponent = true;
              }
            });
            if (!targetBelongsToOpponent) {
              return false;
            }
            try {
              return StateUtils.findCardList(state, card) instanceof PokemonCardList;
            } catch {
              return false;
            }
          },
          {
            allowUseFromHand: true,
            allowUseFromDiscard: true,
            error: GameMessage.BLOCKED_BY_ABILITY
          }
        );
      }
      return state;
    }
  };

