  var Ambipom4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Aipom";
      this.cardType = [C];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [{
        name: "All-You-Can-Grab",
        cost: [C],
        damage: 0,
        text: "Flip a coin until you get tails. Search your deck for a number of cards up to the number of heads and put them into your hand. Then, shuffle your deck."
      }, {
        name: "Knock Off",
        cost: [C, C],
        damage: 50,
        text: "Discard a random card from your opponent's hand."
      }];
      this.regulationMark = "F";
      this.set = "LOR";
      this.setNumber = "145";
      this.cardImage = "assets/cardback.png";
      this.name = "Ambipom";
      this.fullName = "Ambipom LOR 145";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        FLIP_UNTIL_TAILS_AND_COUNT_HEADS(store, state, player, (heads) => {
          if (heads > 0 && player.deck.cards.length > 0) {
            const max = Math.min(heads, player.deck.cards.length);
            SEARCH_DECK_FOR_CARDS_TO_HAND(
              store,
              state,
              player,
              this,
              {},
              { min: 0, max, allowCancel: false }
            );
          } else {
            SHUFFLE_DECK(store, state, player);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.hand.cards.length === 0) {
          return state;
        }
        const randomIndex = Math.floor(Math.random() * opponent.hand.cards.length);
        const randomCard = opponent.hand.cards[randomIndex];
        MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards: [randomCard], sourceCard: this });
      }
      return state;
    }
  };

