  var Banette5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Shuppet";
      this.regulationMark = "F";
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 100;
      this.weakness = [{ type: 7 /* DARK */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -30 }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Puppet Offering",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may put a Supporter card from your discard pile into your hand. If you do, put this Pok\xE9mon in the Lost Zone. (Discard all attached cards.)"
      }];
      this.attacks = [
        {
          name: "Spooky Shot",
          cost: [5 /* PSYCHIC */, 5 /* PSYCHIC */],
          damage: 50,
          text: ""
        }
      ];
      this.set = "LOR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "73";
      this.name = "Banette";
      this.fullName = "Banette LOR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasSupporter = player.discard.cards.some((c) => {
          return c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */;
        });
        if (!hasSupporter) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const discardEffect = new DiscardToHandEffect(player, this);
        store.reduceEffect(state, discardEffect);
        if (discardEffect.preventDefault) {
          return state;
        }
        let cards = [];
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DECK,
          player.discard,
          { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          cards = selected || [];
          MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: this });
        });
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            MOVE_POKEMON_OFF_BOARD(store, state, cardList, {
              pokemonDestination: player.lostzone,
              attachedDestination: player.discard,
              sourceCard: this
            });
          }
        });
      }
      return state;
    }
  };

