  var Beautifly4 = class _Beautifly extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Silcoon";
      this.cardType = [1 /* GRASS */];
      this.hp = 130;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Stoked Straw",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may draw cards until you have 6 cards in your hand."
      }];
      this.attacks = [{
        name: "Mega Drain",
        cost: [1 /* GRASS */, 9 /* COLORLESS */],
        damage: 70,
        text: "Heal 30 damage from this Pok\xE9mon."
      }];
      this.regulationMark = "F";
      this.set = "LOR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "8";
      this.name = "Beautifly";
      this.fullName = "Beautifly LOR";
      this.STOKED_STRAW_MARKER = "STOKED_STRAW_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EvolveEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.STOKED_STRAW_MARKER, this);
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.STOKED_STRAW_MARKER, this);
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.marker.removeMarker(this.STOKED_STRAW_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.STOKED_STRAW_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        while (player.hand.cards.length < 6) {
          if (player.deck.cards.length === 0) {
            break;
          }
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
        }
        player.marker.addMarker(this.STOKED_STRAW_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.forEachPokemon(2 /* BOTTOM_PLAYER */, (player) => {
          if (player instanceof _Beautifly) {
            player.marker.removeMarker(this.STOKED_STRAW_MARKER);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const target = player.active;
        const healEffect = new HealEffect(player, target, 30);
        state = store.reduceEffect(state, healEffect);
        return state;
      }
      return state;
    }
  };

