      this.powers = [{
        name: "Moon-Watching Party",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, if this Pok\xE9mon is in the Active Spot, for each of your Benched Clefairy, you may search your deck for a [P] Energy card and attach it to that Clefairy. Then, shuffle your deck."
      }];
