  var EnamorusV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 210;
      this.weakness = [{ type: M }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Guardian of Love",
          powerType: 2 /* ABILITY */,
          text: "Prevent all effects of your opponent's Pok\xE9mon's Abilities done to each of your Pok\xE9mon that has any [P] Energy attached, except any Enamorus V."
        }
      ];
      this.attacks = [
        {
          name: "Blossom Tail",
          cost: [P, C, C],
          damage: 100,
          text: "Attach up to 2 basic Energy cards from your discard pile to your Benched Pok\xE9mon in any way you like."
        }
      ];
      this.regulationMark = "F";
      this.set = "LOR";
      this.setNumber = "82";
      this.cardImage = "assets/cardback.png";
      this.name = "Enamorus V";
      this.fullName = "Enamorus V LOR 82";
    }
    reduceEffect(store, state, effect) {
      const shouldProtectTarget = (targetList, abilityOwnerPlayer) => {
        const targetPokemon = targetList.getPokemonCard();
        if (!targetPokemon) {
          return false;
        }
        if (targetPokemon.name === "Enamorus V") {
          return false;
        }
        const checkEnergy = new CheckProvidedEnergyEffect(abilityOwnerPlayer, targetList);
        store.reduceEffect(state, checkEnergy);
        return checkEnergy.energyMap.some(
          (em) => em.provides.includes(5 /* PSYCHIC */) || em.provides.includes(0 /* ANY */)
        );
      };
      if (effect instanceof EffectOfAbilityEffect && effect.target) {
        let enamorusPlayer = null;
        for (const p of state.players) {
          if (StateUtils.isPokemonInPlay(p, this)) {
            enamorusPlayer = p;
            break;
          }
        }
        if (!enamorusPlayer) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, enamorusPlayer, this)) {
          return state;
        }
        try {
          const targetPlayer = StateUtils.findOwner(state, effect.target);
          if (targetPlayer !== enamorusPlayer) {
            return state;
          }
          if (effect.player === enamorusPlayer) {
            return state;
          }
          if (shouldProtectTarget(effect.target, enamorusPlayer)) {
            effect.target = void 0;
          }
        } catch {
          return state;
        }
      }
      if (effect instanceof AddSpecialConditionsPowerEffect) {
        let enamorusPlayer = null;
        for (const p of state.players) {
          if (StateUtils.isPokemonInPlay(p, this)) {
            enamorusPlayer = p;
            break;
          }
        }
        if (!enamorusPlayer) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, enamorusPlayer, this)) {
          return state;
        }
        try {
          const targetPlayer = StateUtils.findOwner(state, effect.target);
          if (!targetPlayer || targetPlayer !== enamorusPlayer) {
            return state;
          }
          if (effect.player === enamorusPlayer) {
            return state;
          }
          if (shouldProtectTarget(effect.target, enamorusPlayer)) {
            effect.preventDefault = true;
          }
        } catch {
          return state;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBasicEnergyInDiscard = player.discard.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
        );
        if (!hasBasicEnergyInDiscard) {
          return state;
        }
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: true, min: 0, max: 2 }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, {
                cards: [transfer.card],
                sourceCard: this
              });
            }
          }
        );
      }
      return state;
    }
  };

