  var Gengar8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Haunter";
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 120;
      this.weakness = [{ type: 7 /* DARK */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -30 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Netherworld Gate",
        useFromDiscard: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, if this Pok\xE9mon is in your discard pile, you may put it onto your Bench. If you do, put 3 damage counters on this Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Screaming Circle",
        cost: [5 /* PSYCHIC */],
        damage: 0,
        text: "Put 2 damage counters on your opponent's Active Pok\xE9mon for each of your opponent's Benched Pok\xE9mon."
      }];
      this.regulationMark = "F";
      this.set = "LOR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "66";
      this.name = "Gengar";
      this.fullName = "Gengar LOR";
      this.NETHERWORLD_GATE_MARKER = "NETHERWORLD_GATE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (!player.discard.cards.includes(this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.NETHERWORLD_GATE_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (slots2.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        player.marker.addMarker(this.NETHERWORLD_GATE_MARKER, this);
        const cards = player.discard.cards.filter((c) => c === this);
        cards.forEach((card, index) => {
          MOVE_CARDS(store, state, player.discard, slots2[index], { cards: [card], sourceCard: this });
          slots2[index].damage += 30;
        });
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.NETHERWORLD_GATE_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentBenched = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        const damageEffect = new PutCountersEffect(effect, opponentBenched * 20);
        return store.reduceEffect(state, damageEffect);
      }
      return state;
    }
  };

