  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-lost-origin/hisuian-goodra.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects();
  init_state();
  init_check_effects();
  var HisuianGoodra = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Hisuian Sliggoo";
      this.cardType = [N];
      this.hp = 160;
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Metal Lodging",
          powerType: 2 /* ABILITY */,
          text: "Prevent all damage done to each of your Basic Pok\xE9mon that has any [M] Energy attached by attacks from your opponent's Pok\xE9mon V."
        }
      ];
      this.attacks = [
        {
          name: "Heavy Impact",
          cost: [W, M, C],
          damage: 140,
          text: ""
        }
      ];
      this.regulationMark = "F";
      this.set = "LOR";
      this.setNumber = "134";
      this.cardImage = "assets/cardback.png";
      this.name = "Hisuian Goodra";
      this.fullName = "Hisuian Goodra LOR 134";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect) {
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (!targetPlayer) {
          return state;
        }
        if (!StateUtils.isPokemonInPlay(targetPlayer, this)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, targetPlayer, this)) {
          return state;
        }
        const attacker = StateUtils.findOwner(state, effect.source);
        if (targetPlayer === attacker) {
          return state;
        }
        const sourceCard = effect.source.getPokemonCard();
        if (!sourceCard) {
          return state;
        }
        const isV = sourceCard.hasTag("V" /* POKEMON_V */) || sourceCard.hasTag("VMAX" /* POKEMON_VMAX */) || sourceCard.hasTag("VSTAR" /* POKEMON_VSTAR */);
        if (!isV) {
          return state;
        }
        const targetPokemon = effect.target.getPokemonCard();
        if (!targetPokemon || targetPokemon.stage !== 2 /* BASIC */) {
          return state;
        }
        const checkEnergy = new CheckProvidedEnergyEffect(targetPlayer, effect.target);
        store.reduceEffect(state, checkEnergy);
        const hasMetal = checkEnergy.energyMap.some(
          (em) => em.provides.includes(8 /* METAL */) || em.provides.includes(0 /* ANY */)
        );
        if (hasMetal) {
          effect.preventDefault = true;
        }
      }
      return state;
    }
  };

