  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-lost-origin/magnezone-v.ts
  init_game();
  init_attack_effects();
  init_prefabs();
  var MagnezoneV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [4 /* LIGHTNING */];
      this._tags = ["V" /* POKEMON_V */];
      this.hp = 210;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Magnetic Tension",
          cost: [4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 0,
          text: "Switch 1 of your opponent's Benched Pok\xE9mon with their Active Pok\xE9mon. This attack does 40 damage to the new Active Pok\xE9mon."
        },
        {
          name: "Splitting Beam",
          cost: [4 /* LIGHTNING */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 90,
          text: "This attack also does 30 damage to 2 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "LOR";
      this.regulationMark = "F";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "56";
      this.name = "Magnezone V";
      this.fullName = "Magnezone V LOR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ),
          (result) => {
            const cardList = result[0];
            opponent.switchPokemon(cardList);
            const damageEffect = new PutDamageEffect(effect, 40);
            damageEffect.target = opponent.active;
            store.reduceEffect(state, damageEffect);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        state = store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            targets.forEach((target) => {
              const damageEffect = new PutDamageEffect(effect, 30);
              damageEffect.target = targets[0];
              store.reduceEffect(state, damageEffect);
            });
          }
        );
        return state;
      }
      return state;
    }
  };

