  var Nuzleaf8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Seedot";
      this.cardType = [G];
      this.hp = 80;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Push Down",
          cost: [G],
          damage: 30,
          text: "You may have your opponent switch their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon."
        }
      ];
      this.regulationMark = "F";
      this.set = "LOR";
      this.setNumber = "12";
      this.cardImage = "assets/cardback.png";
      this.name = "Nuzleaf";
      this.fullName = "Nuzleaf LOR 12";
      this.usedPushDown = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          this.usedPushDown = true;
        }
      }
      if (effect instanceof AfterAttackEffect && this.usedPushDown) {
        this.usedPushDown = false;
        const player = effect.player;
        state = store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_SWITCH_POKEMON
        ), (wantToSwitch) => {
          if (wantToSwitch) {
            const opponent = StateUtils.getOpponent(state, player);
            SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
          }
        });
      }
      if (effect instanceof EndTurnEffect) {
        this.usedPushDown = false;
      }
      return state;
    }
  };

