  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_check_effects();
  init_play_card_effects();
  var Orbeetle2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Dottler";
      this.cardType = [G];
      this.hp = 110;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [{
        name: "Jamming Attachment",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may attach up to 3 Energy cards from your opponent's discard pile to your opponent's Pok\xE9mon in any way you like."
      }];
      this.attacks = [
        {
          name: "Mysterious Wave",
          cost: [C, C],
          damage: 30,
          damageCalculation: "+",
          text: "This attack does 50 more damage for each Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.regulationMark = "F";
      this.set = "LOR";
      this.setNumber = "20";
      this.cardImage = "assets/cardback.png";
      this.name = "Orbeetle";
      this.fullName = "Orbeetle LOR 20";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, player);
        const hasEnergyInDiscard = opponent.discard.cards.some((c) => c.superType === 3 /* ENERGY */);
        if (!hasEnergyInDiscard) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (!wantToUse) {
            return;
          }
          store.prompt(state, new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            opponent.discard,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 0, max: 3 }
          ), (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, opponent, transfer.to);
              MOVE_CARDS(store, state, opponent.discard, target, { cards: [transfer.card], sourceCard: this, sourceEffect: this.powers[0] });
            }
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        store.reduceEffect(state, checkEnergy);
        const energyCount = checkEnergy.energyMap.reduce((sum, em) => sum + em.provides.length, 0);
        effect.damage += 50 * energyCount;
      }
      return state;
    }
  };

