  var Porygon15 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 60;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Branch Calculation",
          cost: [C],
          damage: 0,
          text: "Look at the top 4 cards of either player's deck and put them back in any order."
        },
        {
          name: "Beam",
          cost: [C],
          damage: 10,
          text: ""
        }
      ];
      this.set = "LOR";
      this.name = "Porygon";
      this.fullName = "Porygon LOR";
      this.regulationMark = "F";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "140";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const options = [
          {
            message: GameMessage.ORDER_YOUR_DECK,
            action: () => {
              if (player.deck.cards.length === 0) {
                throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
              }
              const deckTop = new CardList();
              MOVE_CARDS(store, state, player.deck, deckTop, { count: 4, sourceCard: this });
              return store.prompt(state, new OrderCardsPrompt(
                player.id,
                GameMessage.CHOOSE_CARDS_ORDER,
                deckTop,
                { allowCancel: false }
              ), (order) => {
                if (order === null) {
                  return state;
                }
                deckTop.applyOrder(order);
                deckTop.moveToTopOfDestination(player.deck);
              });
            }
          },
          {
            message: GameMessage.ORDER_OPPONENT_DECK,
            action: () => {
              if (opponent.deck.cards.length === 0) {
                throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
              }
              const deckTop = new CardList();
              MOVE_CARDS(store, state, opponent.deck, deckTop, { count: 4, sourceCard: this });
              return store.prompt(state, new OrderCardsPrompt(
                player.id,
                GameMessage.CHOOSE_CARDS_ORDER,
                deckTop,
                { allowCancel: false }
              ), (order) => {
                if (order === null) {
                  return state;
                }
                deckTop.applyOrder(order);
                deckTop.moveToTopOfDestination(opponent.deck);
              });
            }
          }
        ];
        return store.prompt(state, new SelectPrompt(
          player.id,
          GameMessage.CHOOSE_OPTION,
          options.map((opt) => opt.message),
          { allowCancel: false }
        ), (choice) => {
          const option = options[choice];
          option.action();
        });
      }
      return state;
    }
  };

