  var PorygonZ7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Porygon2";
      this.cardType = [C];
      this.hp = 150;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Downgrading Beam",
          cost: [C, C],
          damage: 0,
          text: "Devolve 1 of your opponent's evolved Pok\xE9mon by removing any number of Evolution cards from it. Your opponent shuffles those cards into their deck."
        },
        {
          name: "Power Beam",
          cost: [C, C, C],
          damage: 130,
          text: ""
        }
      ];
      this.regulationMark = "F";
      this.set = "LOR";
      this.setNumber = "142";
      this.cardImage = "assets/cardback.png";
      this.name = "Porygon-Z";
      this.fullName = "Porygon-Z LOR 142";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const blockedTargets = [];
        let canDevolve = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList.isEvolved()) {
            canDevolve = true;
          } else {
            blockedTargets.push(target);
          }
        });
        if (!canDevolve) {
          return state;
        }
        state = store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_PICK_UP,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false, min: 1, max: 1, blocked: blockedTargets }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            return;
          }
          const target = selected[0];
          const pokemons = target.getPokemons();
          if (pokemons.length <= 1) {
            return;
          }
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_POKEMON_TO_PICK_UP,
            target,
            { superType: 1 /* POKEMON */ },
            { min: 1, max: 1, allowCancel: false }
          ), (selectedCards) => {
            if (!selectedCards || selectedCards.length === 0) {
              return;
            }
            const selectedPokemon = selectedCards[0];
            const selectedIndex = pokemons.findIndex((p) => p === selectedPokemon);
            if (selectedIndex <= 0) {
              return;
            }
            const devolvesNeeded = pokemons.length - selectedIndex;
            for (let i = 0; i < devolvesNeeded; i++) {
              DEVOLVE_POKEMON(store, state, target, opponent.deck);
            }
            SHUFFLE_DECK(store, state, opponent);
          });
        });
      }
      return state;
    }
  };

