  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-lost-origin/seviper.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_phase_effects();
  init_prefabs();
  init_choose_pokemon_prompt();
  init_game_message();
  init_play_card_action();
  init_check_effects();
  var Seviper4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 110;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Sucker Punch and Turn",
          cost: [D, D],
          damage: 60,
          text: "Switch this Pok\xE9mon with 1 of your Benched Darkness Pok\xE9mon."
        }
      ];
      this.regulationMark = "F";
      this.set = "LOR";
      this.setNumber = "116";
      this.cardImage = "assets/cardback.png";
      this.name = "Seviper";
      this.fullName = "Seviper LOR 116";
      this.usedSuckerPunchAndTurn = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedSuckerPunchAndTurn = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedSuckerPunchAndTurn) {
        this.usedSuckerPunchAndTurn = false;
        const player = effect.player;
        const blocked = [];
        let hasDarkBench = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (target.slot !== 2 /* BENCH */) {
            return;
          }
          if (cardList.cards.length === 0) {
            blocked.push(target);
            return;
          }
          const checkType = new CheckPokemonTypeEffect(cardList);
          store.reduceEffect(state, checkType);
          if (checkType.cardTypes.includes(7 /* DARK */)) {
            hasDarkBench = true;
          } else {
            blocked.push(target);
          }
        });
        if (!hasDarkBench) {
          return state;
        }
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false, blocked }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            return;
          }
          const target = selected[0];
          player.switchPokemon(target, store, state);
        });
      }
      if (effect instanceof EndTurnEffect) {
        this.usedSuckerPunchAndTurn = false;
      }
      return state;
    }
  };

