  var Shiftry6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Nuzleaf";
      this.cardType = [G];
      this.hp = 160;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Fan Tornado",
          cost: [G],
          damage: 50,
          text: "You may have your opponent switch their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon."
        },
        {
          name: "Tearing Gust",
          cost: [G],
          damage: 210,
          text: "Put this Pok\xE9mon and all attached cards in the Lost Zone."
        }
      ];
      this.regulationMark = "F";
      this.set = "LOR";
      this.setNumber = "13";
      this.cardImage = "assets/cardback.png";
      this.name = "Shiftry";
      this.fullName = "Shiftry LOR 13";
      this.usedFanTornado = false;
      this.usedTearingGust = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        if (opponent.bench.some((b) => b.cards.length > 0)) {
          this.usedFanTornado = true;
        }
      }
      if (effect instanceof AfterAttackEffect && this.usedFanTornado) {
        this.usedFanTornado = false;
        const player = effect.player;
        state = store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_SWITCH_POKEMON
        ), (wantToSwitch) => {
          if (wantToSwitch) {
            const opponent = StateUtils.getOpponent(state, player);
            SWITCH_ACTIVE_WITH_BENCHED(store, state, opponent);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedTearingGust = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedTearingGust) {
        this.usedTearingGust = false;
        const player = effect.player;
        const tools = player.active.tools.slice();
        tools.forEach((t) => {
          MOVE_CARDS(store, state, player.active, player.lostzone, { cards: [t], sourceCard: this });
        });
        MOVE_CARDS(store, state, player.active, player.lostzone, { sourceCard: this });
      }
      if (effect instanceof EndTurnEffect) {
        this.usedFanTornado = false;
        this.usedTearingGust = false;
      }
      return state;
    }
  };

