  var Spectrier = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 120;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Night Footsteps",
          cost: [P],
          damage: 0,
          text: "Choose 2 of your opponent's Pok\xE9mon and put 2 damage counters on each of them."
        },
        {
          name: "Phantom Strike",
          cost: [P, P, C],
          damage: 120,
          text: "During your next turn, this Pok\xE9mon can't use Phantom Strike."
        }
      ];
      this.regulationMark = "F";
      this.set = "LOR";
      this.setNumber = "81";
      this.cardImage = "assets/cardback.png";
      this.name = "Spectrier";
      this.fullName = "Spectrier LOR 81";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasTargets = opponent.active.cards.length > 0 || opponent.bench.some((b) => b.cards.length > 0);
        if (!hasTargets) {
          return state;
        }
        const maxTargets = Math.min(2, [
          opponent.active.cards.length > 0 ? 1 : 0,
          ...opponent.bench.map((b) => b.cards.length > 0 ? 1 : 0)
        ].reduce((a, b) => a + b, 0));
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: Math.min(2, maxTargets), max: 2, allowCancel: false }
        ), (selected) => {
          const targets = selected || [];
          for (const target of targets) {
            const damage = new PutCountersEffect(effect, 20);
            damage.target = target;
            store.reduceEffect(state, damage);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        effect.player.active.cannotUseAttacksNextTurnPending.push("Phantom Strike");
      }
      return state;
    }
  };

