  var Spiritomb11 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 60;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Cursed Message",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon is Knocked Out by damage from an attack from your opponent's Pok\xE9mon, search your deck for a card and put it into your hand. Then, shuffle your deck."
      }];
      this.attacks = [
        {
          name: "Chain of Spirits",
          cost: [D, D],
          damage: 10,
          damageCalculation: "+",
          text: "This attack does 60 more damage for each Spiritomb in your discard pile."
        }
      ];
      this.regulationMark = "F";
      this.set = "LOR";
      this.setNumber = "117";
      this.cardImage = "assets/cardback.png";
      this.name = "Spiritomb";
      this.fullName = "Spiritomb LOR 117";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target.cards.includes(this)) {
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        const owner = StateUtils.findOwner(state, effect.target);
        if (!owner) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, owner, this)) {
          return state;
        }
        if (owner.deck.cards.length > 0) {
          SEARCH_DECK_FOR_CARDS_TO_HAND(
            store,
            state,
            owner,
            this,
            {},
            { min: 1, max: 1, allowCancel: false }
          );
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const spiritombInDiscard = player.discard.cards.filter(
          (c) => c instanceof PokemonCard && c.name === "Spiritomb"
        ).length;
        effect.damage += 60 * spiritombInDiscard;
      }
      return state;
    }
  };

