  var DamagePump = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "LOR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "156";
      this.regulationMark = "F";
      this.name = "Damage Pump";
      this.fullName = "Damage Pump LOR";
      this.text = "Move up to 2 damage counters from 1 of your Pok\xE9mon to your other Pok\xE9mon in any way you like.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        let hasDamagedPokemon = false;
        const damagedPokemon = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.damage > 0) {
            hasDamagedPokemon = true;
            damagedPokemon.push({ target, damage: cardList.damage });
          }
        });
        if (!hasDamagedPokemon) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const maxAllowedDamage = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(player, cardList);
          store.reduceEffect(state, checkHpEffect);
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        effect.preventDefault = true;
        return store.prompt(
          state,
          new MoveDamagePrompt(
            effect.player.id,
            GameMessage.MOVE_DAMAGE,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            maxAllowedDamage,
            { min: 1, max: 2, allowCancel: false, blockedFrom: [], blockedTo: [] }
          ),
          (transfers) => {
            if (transfers === null) {
              MOVE_CARDS(store, state, player.hand, player.discard, {
                cards: [effect.trainerCard],
                sourceCard: this
              });
              return state;
            }
            let totalDamageMoved = 0;
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              const damageToMove = Math.min(20 - totalDamageMoved, Math.min(10, source.damage));
              if (damageToMove > 0) {
                source.damage -= damageToMove;
                target.damage += damageToMove;
                totalDamageMoved += damageToMove;
              }
              if (totalDamageMoved >= 20) break;
            }
            return state;
          }
        );
      }
      return state;
    }
  };

