  var PanicMask = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "F";
      this._trainerType = 3 /* TOOL */;
      this.set = "LOR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "165";
      this.name = "Panic Mask";
      this.fullName = "Panic Mask LOR";
      this.text = "Prevent all damage done to the Pok\xE9mon this card is attached to by attacks from your opponent's Pok\xE9mon that have 40 HP or less remaining.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        if (effect.damage <= 0 || player === targetPlayer || targetPlayer.active !== effect.target) {
          return state;
        }
        const attackingPokemon = player.active;
        const maxHp = attackingPokemon.getPokemonCard()?.hp || 0;
        const currentHp = maxHp - attackingPokemon.damage;
        if (currentHp <= 40) {
          effect.damage = 0;
        }
      }
      return state;
    }
  };

