  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-lost-origin/gift-energy.ts
  init_card_types();
  init_game_phase_effects();
  init_energy_card();
  init_state();
  init_game_effects();
  init_prefabs();
  var GiftEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [9 /* COLORLESS */];
      this.energyType = 1 /* SPECIAL */;
      this.set = "LOR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "171";
      this.regulationMark = "F";
      this.name = "Gift Energy";
      this.fullName = "Gift Energy LOR";
      this.GIFT_ENERGY_MARKER = "GIFT_ENERGY_MARKER";
      this.text = "As long as this card is attached to a Pok\xE9mon, it provides [C] Energy.  If the Pok\xE9mon this card is attached to is Knocked Out by damage from an attack from your opponent's Pok\xE9mon, draw cards until you have 7 cards in your hand.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, effect.target)) {
          return state;
        }
        const target = effect.target;
        const cards = target.getPokemons();
        cards.forEach((card) => {
          player.marker.addMarker(this.GIFT_ENERGY_MARKER, card);
        });
      }
      if (effect instanceof BetweenTurnsEffect) {
        state.players.forEach((player) => {
          if (!player.marker.hasMarker(this.GIFT_ENERGY_MARKER)) {
            return;
          }
          while (player.hand.cards.length < 7) {
            if (player.deck.cards.length === 0) {
              break;
            }
            MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
          }
          player.marker.removeMarker(this.GIFT_ENERGY_MARKER);
        });
      }
      return state;
    }
  };

