  var HisuianElectrodeV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [1 /* GRASS */];
      this.hp = 210;
      this._tags = ["V" /* POKEMON_V */];
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Tantrum Blast",
          cost: [],
          damage: 100,
          text: "This attack does 100 damage for each Special Condition affecting this Pok\xE9mon."
        },
        {
          name: "Solar Shot",
          cost: [1 /* GRASS */, 9 /* COLORLESS */],
          damage: 120,
          text: "Discard all Energy from this Pok\xE9mon."
        }
      ];
      this.regulationMark = "F";
      this.set = "SWSH";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "294";
      this.name = "Hisuian Electrode V";
      this.fullName = "Hisuian Electrode V SWSH";
      this.SOLAR_SHOT_MARKER = "SOLAR_SHOT_MARKER";
      this.CLEAR_SOLAR_SHOT_MARKER = "CLEAR_SOLAR_SHOT_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const cardList = StateUtils.findCardList(state, this);
        effect.damage = cardList.specialConditions.length * 100;
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const cards = checkProvidedEnergy.energyMap.map((e) => e.card);
        const discardEnergy2 = new DiscardCardsEffect(effect, cards);
        discardEnergy2.target = player.active;
        store.reduceEffect(state, discardEnergy2);
      }
      return state;
    }
  };

