  var LureModule = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.regulationMark = "F";
      this.set = "PGO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "67";
      this.name = "Lure Module";
      this.fullName = "Lure Module PGO";
      this.text = "Each player reveals the top 3 cards of their deck and puts all Pok\xE9mon they find there into their hand. Then, each player shuffles the other cards back into their deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const tempOpp = new CardList();
        effect.preventDefault = true;
        MOVE_CARDS(store, state, opponent.deck, tempOpp, { count: 3, sourceCard: this });
        return store.prompt(
          state,
          new ShowCardsPrompt(player.id, GameMessage.PLAYER_CARDS_REVEALED_BY_EFFECT, tempOpp.cards),
          () => {
            return store.prompt(
              state,
              new ShowCardsPrompt(
                opponent.id,
                GameMessage.PLAYER_CARDS_REVEALED_BY_EFFECT,
                tempOpp.cards
              ),
              () => {
                const pokemonCards = tempOpp.cards.filter((card) => card instanceof PokemonCard);
                const nonPokemonCards = tempOpp.cards.filter(
                  (card) => !(card instanceof PokemonCard)
                );
                pokemonCards.forEach((card) => {
                  MOVE_CARDS(store, state, tempOpp, opponent.hand, {
                    cards: [card],
                    sourceCard: this
                  });
                });
                nonPokemonCards.forEach((card) => {
                  MOVE_CARDS(store, state, tempOpp, opponent.deck, {
                    cards: [card],
                    sourceCard: this
                  });
                });
                const temp = new CardList();
                MOVE_CARDS(store, state, player.deck, temp, { count: 3, sourceCard: this });
                return store.prompt(
                  state,
                  new ShowCardsPrompt(
                    player.id,
                    GameMessage.PLAYER_CARDS_REVEALED_BY_EFFECT,
                    temp.cards
                  ),
                  () => {
                    return store.prompt(
                      state,
                      new ShowCardsPrompt(
                        opponent.id,
                        GameMessage.PLAYER_CARDS_REVEALED_BY_EFFECT,
                        temp.cards
                      ),
                      () => {
                        const pokemonCards2 = temp.cards.filter((card) => card instanceof PokemonCard);
                        const nonPokemonCards2 = temp.cards.filter(
                          (card) => !(card instanceof PokemonCard)
                        );
                        pokemonCards2.forEach((card) => {
                          MOVE_CARDS(store, state, temp, player.hand, {
                            cards: [card],
                            sourceCard: this
                          });
                        });
                        nonPokemonCards2.forEach((card) => {
                          MOVE_CARDS(store, state, temp, player.deck, {
                            cards: [card],
                            sourceCard: this
                          });
                        });
                        MOVE_CARDS(store, state, player.supporter, player.discard, {
                          cards: [this],
                          sourceCard: this
                        });
                        state = store.prompt(
                          state,
                          new ShuffleDeckPrompt(player.id),
                          (playerOrder) => {
                            player.deck.applyOrder(playerOrder);
                            return state;
                          }
                        );
                        return store.prompt(state, new ShuffleDeckPrompt(opponent.id), (oppOrder) => {
                          opponent.deck.applyOrder(oppOrder);
                          return state;
                        });
                      }
                    );
                  }
                );
              }
            );
          }
        );
      }
      return state;
    }
  };

