  function* useVitalitySpring(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      return state;
    }
    yield store.prompt(state, new AttachEnergyPrompt(
      player.id,
      GameMessage.ATTACH_ENERGY_TO_BENCH,
      player.deck,
      2 /* BOTTOM_PLAYER */,
      [2 /* BENCH */, 1 /* ACTIVE */],
      { superType: 3 /* ENERGY */ },
      { allowCancel: false, min: 0, max: 6 }
    ), (transfers) => {
      transfers = transfers || [];
      for (const transfer of transfers) {
        const target = StateUtils.getTarget(state, player, transfer.to);
        MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: effect.card });
        next();
      }
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
      const endTurnEffect = new EndTurnEffect(player);
      store.reduceEffect(state, endTurnEffect);
      return state;
    });
  }
