  var Zapdos11 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [4 /* LIGHTNING */];
      this.hp = 120;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Lightning Symbol",
        powerType: 2 /* ABILITY */,
        text: "Your Basic [L] Pok\xE9mon's attacks, except any Zapdos, do 10 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Electric Ball",
          cost: [4 /* LIGHTNING */, 4 /* LIGHTNING */, 9 /* COLORLESS */],
          damage: 110,
          text: ""
        }
      ];
      this.regulationMark = "F";
      this.set = "PGO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "29";
      this.name = "Zapdos";
      this.fullName = "Zapdos PGO";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const hasZapdosInPlay = player.bench.some((b) => b.cards.includes(this)) || player.active.cards.includes(this);
        let numberOfZapdosInPlay = 0;
        if (hasZapdosInPlay) {
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
            if (cardList.cards.includes(this)) {
              numberOfZapdosInPlay++;
            }
          });
        }
        const checkPokemonTypeEffect = new CheckPokemonTypeEffect(player.active);
        store.reduceEffect(state, checkPokemonTypeEffect);
        if (checkPokemonTypeEffect.cardTypes.includes(4 /* LIGHTNING */) && effect.target === opponent.active) {
          if (effect.player.active.getPokemonCard()?.name !== "Zapdos" && effect.player.active.getPokemonCard()?.stage === 2 /* BASIC */) {
            effect.damage += 10 * numberOfZapdosInPlay;
          }
        }
      }
      return state;
    }
  };

