  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-rebel-clash/appletun.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Appletun2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Applin";
      this.cardType = [G];
      this.hp = 90;
      this.weakness = [{ type: R }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Delicious Aroma",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may flip a coin. If heads, switch 1 of your opponent's Benched Basic Pok\xE9mon with their Active Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Solar Beam",
        cost: [G, C],
        damage: 70,
        text: ""
      }];
      this.regulationMark = "D";
      this.set = "RCL";
      this.setNumber = "23";
      this.cardImage = "assets/cardback.png";
      this.name = "Appletun";
      this.fullName = "Appletun RCL";
      this.DELICIOUS_AROMA_MARKER = "DELICIOUS_AROMA_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const hasBasicBenched = opponent.bench.some((b) => b.cards.length > 0 && b.isStage(2 /* BASIC */));
        if (!hasBasicBenched) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.DELICIOUS_AROMA_MARKER, this);
        ABILITY_USED(player, this);
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            const blocked = [];
            opponent.bench.forEach((bench, index) => {
              if (bench.cards.length === 0 || !bench.isStage(2 /* BASIC */)) {
                blocked.push({ player: 1 /* TOP_PLAYER */, slot: 2 /* BENCH */, index });
              }
            });
            SWITCH_IN_OPPONENT_BENCHED_POKEMON(store, state, player, { blocked });
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.DELICIOUS_AROMA_MARKER, this);
      return state;
    }
  };

