  var EldegossV2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 180;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Happy Match",
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may put a Supporter card from your discard pile into your hand."
        }
      ];
      this.attacks = [
        {
          name: "Float Up",
          cost: [C, C],
          damage: 50,
          text: "You may shuffle this Pok\xE9mon and all attached cards into your deck."
        }
      ];
      this.regulationMark = "D";
      this.set = "RCL";
      this.setNumber = "19";
      this.cardImage = "assets/cardback.png";
      this.name = "Eldegoss V";
      this.fullName = "Eldegoss V RCL";
      this.wantsToShuffle = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const supportersInDiscard = player.discard.cards.filter(
          (c) => c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */
        );
        if (supportersInDiscard.length === 0) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        store.prompt(
          state,
          new ConfirmPrompt(player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              store.prompt(
                state,
                new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_HAND,
                  player.discard,
                  { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
                  { min: 1, max: 1, allowCancel: false }
                ),
                (selected) => {
                  const cards = selected || [];
                  MOVE_CARDS(store, state, player.discard, player.hand, {
                    cards,
                    sourceCard: this,
                    sourceEffect: this.powers[0]
                  });
                }
              );
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        store.prompt(
          state,
          new ConfirmPrompt(player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            this.wantsToShuffle = wantToUse;
          }
        );
      }
      if (effect instanceof AfterAttackEffect && this.wantsToShuffle) {
        this.wantsToShuffle = false;
        return SHUFFLE_THIS_POKEMON_AND_ALL_ATTACHED_CARDS_INTO_YOUR_DECK(store, state, effect);
      }
      if (effect instanceof EndTurnEffect) {
        this.wantsToShuffle = false;
      }
      return state;
    }
  };

