  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-rebel-clash/hatterene.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_attack_effects();
  function* useAbility(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    if (opponent.hand.cards.length > 0) {
      yield store.prompt(state, new ChooseCardsPrompt(
        opponent,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        opponent.hand,
        {},
        { min: 1, max: 1, allowCancel: false }
      ), (selected) => {
        const cards = selected || [];
        MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards, sourceCard: effect.source.getPokemonCard() });
        next();
      });
    }
    if (player.hand.cards.length > 0) {
      yield store.prompt(state, new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        player.hand,
        {},
        { min: 1, max: 1, allowCancel: false }
      ), (selected) => {
        const cards = selected || [];
        MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: effect.source.getPokemonCard() });
        next();
      });
    }
    return state;
  }
  var Hatterene3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Hattrem";
      this.cardType = [P];
      this.hp = 150;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Mind Hat",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may use this Ability. Each player discards a card from their hand. (Your opponent discards first.)"
      }];
      this.attacks = [
        {
          name: "Dripping Grudge",
          cost: [P],
          damage: 0,
          text: "Put 1 damage counter on your opponent's Active Pok\xE9mon for each Pok\xE9mon in your discard pile."
        }
      ];
      this.MIND_HAT_MARKER = "HATTERENE_RCL_MIND_HAT_MARKER";
      this.regulationMark = "D";
      this.set = "RCL";
      this.setNumber = "85";
      this.cardImage = "assets/cardback.png";
      this.name = "Hatterene";
      this.fullName = "Hatterene RCL";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.MIND_HAT_MARKER, this);
        ABILITY_USED(player, this);
        const generator = useAbility(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.MIND_HAT_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const pokemonCount = player.discard.cards.filter((c) => c instanceof PokemonCard).length;
        if (pokemonCount > 0) {
          const putCounters = new PutCountersEffect(effect, 10 * pokemonCount);
          putCounters.target = opponent.active;
          store.reduceEffect(state, putCounters);
        }
      }
      return state;
    }
  };

