  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-rebel-clash/heliolisk.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_prefabs();
  var Heliolisk9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Helioptile";
      this.cardType = [L];
      this.hp = 110;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [{
        name: "Eerie Impulse",
        cost: [L],
        damage: 0,
        text: "Flip a coin. If heads, discard an Energy from 1 of your opponent's Pok\xE9mon."
      }, {
        name: "Thunder",
        cost: [L, C],
        damage: 120,
        text: "This Pok\xE9mon also does 30 damage to itself."
      }];
      this.regulationMark = "D";
      this.set = "RCL";
      this.setNumber = "64";
      this.cardImage = "assets/cardback.png";
      this.name = "Heliolisk";
      this.fullName = "Heliolisk RCL";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            let hasEnergy = false;
            opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
              if (cardList.cards.some((c) => c instanceof EnergyCard)) {
                hasEnergy = true;
              }
            });
            if (!hasEnergy) {
              return;
            }
            store.prompt(state, new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON,
              1 /* TOP_PLAYER */,
              [1 /* ACTIVE */, 2 /* BENCH */],
              { min: 1, max: 1, allowCancel: false }
            ), (selected) => {
              if (!selected || selected.length === 0) {
                return;
              }
              const target = selected[0];
              const energyCards = target.cards.filter((c) => c instanceof EnergyCard);
              if (energyCards.length === 0) {
                return;
              }
              if (energyCards.length === 1) {
                const discardEnergy2 = new DiscardCardsEffect(effect, energyCards);
                discardEnergy2.target = target;
                store.reduceEffect(state, discardEnergy2);
              } else {
                store.prompt(state, new ChooseCardsPrompt(
                  player,
                  GameMessage.CHOOSE_CARD_TO_DISCARD,
                  target,
                  { superType: 3 /* ENERGY */ },
                  { min: 1, max: 1, allowCancel: false }
                ), (cards) => {
                  const selected2 = cards || [];
                  if (selected2.length > 0) {
                    const discardEnergy2 = new DiscardCardsEffect(effect, selected2);
                    discardEnergy2.target = target;
                    store.reduceEffect(state, discardEnergy2);
                  }
                });
              }
            });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        THIS_POKEMON_DOES_DAMAGE_TO_ITSELF(store, state, effect, 30);
      }
      return state;
    }
  };

