  var Pelipper4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Wingull";
      this.cardType = [W];
      this.hp = 120;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Wing Attack",
          cost: [C, C],
          damage: 50,
          text: ""
        },
        {
          name: "Power Cyclone",
          cost: [W, C, C],
          damage: 110,
          text: "Move an Energy from this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.regulationMark = "D";
      this.set = "RCL";
      this.setNumber = "42";
      this.cardImage = "assets/cardback.png";
      this.name = "Pelipper";
      this.fullName = "Pelipper RCL";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const attachedEnergies = player.active.cards.filter(
          (card) => card.superType === 3 /* ENERGY */
        );
        if (attachedEnergies.length === 0) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.active,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

