  var Pidove7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 60;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Chirp",
          cost: [C],
          damage: 0,
          text: "Search your deck for up to 2 Pok\xE9mon with Fighting Resistance, reveal them, and put them into your hand. Then, shuffle your deck."
        },
        {
          name: "Razor Wing",
          cost: [C, C],
          damage: 20,
          text: ""
        }
      ];
      this.regulationMark = "D";
      this.set = "RCL";
      this.setNumber = "143";
      this.cardImage = "assets/cardback.png";
      this.name = "Pidove";
      this.fullName = "Pidove RCL";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.deck.cards.length === 0) {
          return state;
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (card instanceof PokemonCard) {
            const hasF = card.resistance && card.resistance.some((r) => r.type === 6 /* FIGHTING */);
            if (!hasF) {
              blocked.push(index);
            }
          } else {
            blocked.push(index);
          }
        });
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.deck,
          { superType: 1 /* POKEMON */ },
          { min: 0, max: 2, allowCancel: false, blocked }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length > 0) {
            MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this });
            SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
          }
          SHUFFLE_DECK(store, state, player);
        });
      }
      return state;
    }
  };

