  var RillaboomVmax2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VMAX" /* POKEMON_VMAX */];
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Rillaboom V";
      this.cardType = [G];
      this.hp = 330;
      this.weakness = [{ type: R }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Scratch",
          cost: [C],
          damage: 50,
          text: ""
        },
        {
          name: "Max Beating",
          cost: [G, G, G, C],
          damage: 130,
          damageCalculation: "+",
          text: "You may discard up to 3 [G] Energy from this Pok\xE9mon. If you do, this attack does 50 more damage for each card you discarded in this way."
        }
      ];
      this.regulationMark = "D";
      this.set = "RCL";
      this.setNumber = "18";
      this.cardImage = "assets/cardback.png";
      this.name = "Rillaboom VMAX";
      this.fullName = "Rillaboom VMAX RCL";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const grassEnergy = checkProvidedEnergy.energyMap.filter(
          (e) => e.provides.includes(1 /* GRASS */)
        );
        if (grassEnergy.length === 0) {
          return state;
        }
        const max = Math.min(3, grassEnergy.length);
        store.prompt(
          state,
          new ChooseEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            checkProvidedEnergy.energyMap,
            [1 /* GRASS */, 1 /* GRASS */, 1 /* GRASS */].slice(0, max),
            { allowCancel: true }
          ),
          (selected) => {
            const cards = (selected || []).map((e) => e.card);
            if (cards.length === 0) {
              return;
            }
            const discardEnergy2 = new DiscardCardsEffect(effect, cards);
            discardEnergy2.target = player.active;
            store.reduceEffect(state, discardEnergy2);
            effect.damage += 50 * cards.length;
          }
        );
      }
      return state;
    }
  };

