  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-rebel-clash/shuckle.ts
  init_prefabs();
  init_choose_cards_prompt();
  init_card_types();
  init_game_message();
  init_pokemon_card();
  var Shuckle6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 80;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.attacks = [{
        name: "Berry Picking",
        cost: [C],
        damage: 0,
        text: "Shuffle up to 5 basic Energy cards from your discard pile into your deck."
      }, {
        name: "Bind",
        cost: [G, C, C],
        damage: 50,
        text: "Flip a coin. If heads, your opponent's Active Pok\xE9mon is now Paralyzed."
      }];
      this.regulationMark = "D";
      this.set = "RCL";
      this.setNumber = "5";
      this.cardImage = "assets/cardback.png";
      this.name = "Shuckle";
      this.fullName = "Shuckle RCL";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const basicEnergyInDiscard = player.discard.cards.filter(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
        );
        if (basicEnergyInDiscard.length === 0) {
          return state;
        }
        const max = Math.min(5, basicEnergyInDiscard.length);
        store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DECK,
          player.discard,
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { min: 0, max, allowCancel: false }
        ), (selected) => {
          const cards = selected || [];
          cards.forEach((card) => {
            MOVE_CARDS(store, state, player.discard, player.deck, { cards: [card], sourceCard: this });
          });
          SHUFFLE_DECK(store, state, player);
        });
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (result) {
            ADD_PARALYZED_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
          }
        });
      }
      return state;
    }
  };

