  var Sigilyph7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 110;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Counterattack",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon is your Active Pok\xE9mon and is damaged by an opponent's attack (even if this Pok\xE9mon is Knocked Out), put 3 damage counters on the Attacking Pok\xE9mon."
      }];
      this.attacks = [
        {
          name: "Psychic Assault",
          cost: [P, C],
          damage: 30,
          damageCalculation: "+",
          text: "This attack does 10 more damage for each damage counter on your opponent's Active Pok\xE9mon."
        }
      ];
      this.regulationMark = "D";
      this.set = "RCL";
      this.setNumber = "80";
      this.cardImage = "assets/cardback.png";
      this.name = "Sigilyph";
      this.fullName = "Sigilyph RCL";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this) {
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        const attackingPlayer = effect.player;
        if (effect.damage > 0 && attackingPlayer !== targetPlayer && targetPlayer.active === effect.target && state.phase === 3 /* ATTACK */) {
          if (IS_ABILITY_BLOCKED(store, state, targetPlayer, this)) {
            return state;
          }
          effect.source.damage += 30;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const damageCounters = Math.floor(opponent.active.damage / 10);
        effect.damage += 10 * damageCounters;
      }
      return state;
    }
  };

