  var Whiscash5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Barboach";
      this.cardType = [F];
      this.hp = 140;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Submerge",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is on your Bench, prevent all damage done to this Pok\xE9mon by attacks (both yours and your opponent's)."
      }];
      this.attacks = [
        {
          name: "Earthquake",
          cost: [F, F],
          damage: 140,
          text: "This attack also does 20 damage to each of your Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.regulationMark = "D";
      this.set = "RCL";
      this.setNumber = "100";
      this.cardImage = "assets/cardback.png";
      this.name = "Whiscash";
      this.fullName = "Whiscash RCL";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this) {
        const player = StateUtils.findOwner(state, effect.target);
        if (effect.target === player.active) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.preventDefault = true;
        return state;
      }
      if (effect instanceof DealDamageEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this) {
        const player = StateUtils.findOwner(state, effect.target);
        if (effect.target === player.active) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.preventDefault = true;
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList === player.active) {
            return;
          }
          const damageEffect = new PutDamageEffect(effect, 20);
          damageEffect.target = cardList;
          store.reduceEffect(state, damageEffect);
        });
      }
      return state;
    }
  };

