  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-rebel-clash/xatu.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_check_effects();
  var Xatu6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Natu";
      this.cardType = [P];
      this.hp = 120;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Energy Warp",
          cost: [C],
          damage: 0,
          text: "Move an Energy from 1 of your opponent's Benched Pok\xE9mon to their Active Pok\xE9mon."
        },
        {
          name: "Psychic",
          cost: [P],
          damage: 10,
          damageCalculation: "+",
          text: "This attack does 30 more damage for each Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.regulationMark = "D";
      this.set = "RCL";
      this.setNumber = "77";
      this.cardImage = "assets/cardback.png";
      this.name = "Xatu";
      this.fullName = "Xatu RCL";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let hasBenchEnergy = false;
        opponent.bench.forEach((b) => {
          if (b.cards.length > 0 && b.cards.some((c) => c instanceof EnergyCard)) {
            hasBenchEnergy = true;
          }
        });
        if (!hasBenchEnergy) {
          return state;
        }
        const blockedFrom = [
          { player: 1 /* TOP_PLAYER */, slot: 1 /* ACTIVE */, index: 0 }
        ];
        const blockedTo = [];
        opponent.bench.forEach((_, index) => {
          blockedTo.push({ player: 1 /* TOP_PLAYER */, slot: 2 /* BENCH */, index });
        });
        store.prompt(state, new MoveEnergyPrompt(
          player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */ },
          { min: 1, max: 1, allowCancel: false, blockedFrom, blockedTo }
        ), (result) => {
          const transfers = result || [];
          transfers.forEach((transfer) => {
            const source = StateUtils.getTarget(state, player, transfer.from);
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        store.reduceEffect(state, checkEnergy);
        const energyCount = checkEnergy.energyMap.reduce((sum, em) => sum + em.provides.length, 0);
        effect.damage += 30 * energyCount;
      }
      return state;
    }
  };

