  var Dan = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "RCL";
      this.name = "Dan";
      this.fullName = "Dan RCL";
      this.regulationMark = "D";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "158";
      this.text = "Draw 2 cards. You and your opponent play Rock-Paper-Scissors until someone wins. If you win, draw 2 more cards.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        DRAW_CARDS(store, state, player, 2);
        const options = [
          { value: "Rock", message: "Rock" },
          { value: "Paper", message: "Paper" },
          { value: "Scissors", message: "Scissors" }
        ];
        store.prompt(
          state,
          [
            new SelectPrompt(
              player.id,
              GameMessage.CHOOSE_OPTION,
              options.map((c) => c.message),
              { allowCancel: false }
            ),
            new SelectPrompt(
              opponent.id,
              GameMessage.CHOOSE_OPTION,
              options.map((c) => c.message),
              { allowCancel: false }
            )
          ],
          (results) => {
            const playerChosenValue = results[0];
            const opponentChosenValue = results[1];
            if (playerChosenValue === opponentChosenValue) {
              return this.reduceEffect(store, state, effect);
            }
            if (playerChosenValue === 1 && opponentChosenValue === 0 || playerChosenValue === 2 && opponentChosenValue === 1 || playerChosenValue === 0 && opponentChosenValue === 2) {
              DRAW_CARDS(store, state, player, 2);
            }
          }
        );
      }
      return state;
    }
  };

