  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-rebel-clash/oleana.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_prefabs();
  function* playCard213(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    const nonSelfCards = player.hand.cards.filter((c) => c !== effect.trainerCard);
    if (nonSelfCards.length >= 2) {
      yield store.prompt(
        state,
        new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          {},
          { min: 2, max: 2, allowCancel: false }
        ),
        (selected) => {
          const cards = selected || [];
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: self });
          next();
        }
      );
    }
    if (opponent.hand.cards.length > 0) {
      SHOW_CARDS_TO_PLAYER(store, state, player, opponent.hand.cards);
    }
    const trainerCards = opponent.hand.cards.filter((c) => c.superType === 2 /* TRAINER */);
    if (trainerCards.length > 0) {
      yield store.prompt(
        state,
        new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DECK,
          opponent.hand,
          { superType: 2 /* TRAINER */ },
          { min: 0, max: 1, allowCancel: false }
        ),
        (selected) => {
          const cards = selected || [];
          cards.forEach((card) => {
            MOVE_CARDS(store, state, opponent.hand, opponent.deck, {
              cards: [card],
              sourceCard: self
            });
          });
          next();
        }
      );
    }
    return state;
  }
  var Oleana = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "D";
      this.set = "RCL";
      this.setNumber = "163";
      this.cardImage = "assets/cardback.png";
      this.name = "Oleana";
      this.fullName = "Oleana RCL";
      this.text = "You can play this card only if you discard 2 other cards from your hand. Your opponent reveals their hand. Put a Trainer card you find there on the bottom of their deck. You may play only 1 Supporter card during your turn.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const nonSelfCards = player.hand.cards.filter((c) => c !== effect.trainerCard);
        if (nonSelfCards.length < 2) {
          return state;
        }
        const generator = playCard213(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

