  var ScoopUpNet = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.name = "Scoop Up Net";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "165";
      this.set = "RCL";
      this.fullName = "Scoop Up Net RCL";
      this.superType = 2 /* TRAINER */;
      this._trainerType = 0 /* ITEM */;
      this.text = "Put 1 of your Pok\xE9mon that isn't a Pok\xE9mon V or a Pok\xE9mon-GX into your hand. (Discard all attached cards.)";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card instanceof PokemonCard && (card.hasTag("GX" /* POKEMON_GX */) || card.hasTag("V" /* POKEMON_V */) || card.hasTag("VSTAR" /* POKEMON_VSTAR */) || card.hasTag("VMAX" /* POKEMON_VMAX */))) {
            blocked.push(target);
          }
        });
        MOVE_CARD_TO(state, effect.trainerCard, player.supporter);
        effect.preventDefault = true;
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_PICK_UP,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { allowCancel: false, blocked }
          ),
          (result) => {
            const cardList = result.length > 0 ? result[0] : null;
            if (cardList !== null) {
              MOVE_POKEMON_OFF_BOARD(store, state, cardList, {
                pokemonDestination: player.hand,
                attachedDestination: player.discard,
                sourceCard: this
              });
            }
          }
        );
      }
      return state;
    }
  };

