  var HorrorPsychicEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [9 /* COLORLESS */];
      this.energyType = 1 /* SPECIAL */;
      this.regulationMark = "D";
      this.set = "RCL";
      this.name = "Horror Psychic Energy";
      this.fullName = "Horror Psychic Energy RCL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "172";
      this.text = `As long as this card is attached to a Pok\xE9mon, it provides [P] Energy.
    
If the [P] Pok\xE9mon this card is attached to is in the Active Spot and is damaged by an opponent's attack (even if it is Knocked Out), put 2 damage counters on the Attacking Pok\xE9mon.`;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        effect.energyMap.push({ card: this, provides: [5 /* PSYCHIC */] });
        return state;
      }
      if (effect instanceof AfterDamageEffect && effect.target.cards?.includes(this)) {
        const player = effect.player;
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, effect.target)) {
          return state;
        }
        const checkPokemonType = new CheckPokemonTypeEffect(targetPlayer.active);
        store.reduceEffect(state, checkPokemonType);
        if (checkPokemonType.cardTypes.includes(5 /* PSYCHIC */)) {
          if (effect.damage <= 0 || player === targetPlayer || targetPlayer.active !== effect.target) {
            return state;
          }
          if (state.phase === 3 /* ATTACK */) {
            effect.source.damage += 20;
          }
        }
      }
      return state;
    }
  };

