  var GalarianWeezing2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.regulationMark = "D";
      this.cardType = [D];
      this.evolvesFrom = "Koffing";
      this.hp = 130;
      this.weakness = [{ type: F }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Neutralizing Gas",
          powerType: 2 /* ABILITY */,
          abilityLock: true,
          text: "As long as this Pok\xE9mon is in the Active Spot, your opponent's Pok\xE9mon in play have no Abilities, except for Neutralizing Gas."
        }
      ];
      this.attacks = [
        {
          name: "Severe Poison",
          cost: [D],
          damage: 0,
          text: "Your opponent's Active Pok\xE9mon is now Poisoned. Put 4 damage counters instead of 1 on that Pok\xE9mon during Pok\xE9mon Checkup."
        }
      ];
      this.set = "SHF";
      this.name = "Galarian Weezing";
      this.fullName = "Galarian Weezing SHF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "42";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const specialCondition = new AddSpecialConditionsEffect(effect, [
          3 /* POISONED */
        ]);
        specialCondition.poisonDamage = 40;
        store.reduceEffect(state, specialCondition);
      }
      HANDLE_ABILITY_LOCK(effect, ({ player, card }) => {
        if (!IS_ABILITY_LOCKER_ACTIVE(state, player, this)) {
          return false;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        const opponent = StateUtils.getOpponent(state, owner);
        let targetBelongsToOpponent = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (_list, pokemon) => {
          if (pokemon === card) {
            targetBelongsToOpponent = true;
          }
        });
        if (!targetBelongsToOpponent) {
          return false;
        }
        const targetCardList = StateUtils.findCardList(state, card);
        if (!(targetCardList instanceof PokemonCardList)) {
          return false;
        }
        return LOCKER_ABILITY_APPLIES(store, state, owner, this, this.powers[0], card);
      }, {
        exemptPowerNames: ["Neutralizing Gas"],
        allowUseFromHand: true,
        allowUseFromDiscard: true,
        error: GameMessage.BLOCKED_BY_ABILITY
      });
      return state;
    }
  };

