  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-shining-fates/celebi.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Celebi4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 70;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [{
        name: "Woodland Stroll",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, if this Pok\xE9mon is in the Active Spot, you may look at the top 6 cards of your deck, reveal an Energy card you find there, and put it into your hand. Shuffle the other cards back into your deck."
      }];
      this.attacks = [
        {
          name: "Leaf Step",
          cost: [G, C, C],
          damage: 40,
          text: ""
        }
      ];
      this.regulationMark = "E";
      this.set = "SHF";
      this.setNumber = "3";
      this.cardImage = "assets/cardback.png";
      this.name = "Celebi";
      this.fullName = "Celebi SHF";
      this.WOODLAND_STROLL_MARKER = "CELEBI_SHF_WOODLAND_STROLL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        if (player.active.getPokemonCard() !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.WOODLAND_STROLL_MARKER, this);
        ABILITY_USED(player, this);
        LOOK_AT_TOP_X_CARDS_AND_PUT_UP_TO_Y_MATCHING_CARDS_INTO_HAND(
          store,
          state,
          player,
          6,
          1,
          {
            filter: { superType: 3 /* ENERGY */ },
            revealChosenCards: true,
            remainderDestination: "shuffle",
            sourceCard: this
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.WOODLAND_STROLL_MARKER, this);
      return state;
    }
  };

