  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/set-shining-fates/cramorant-vmax.ts
  init_pokemon_card();
  init_card_types();
  init_prefabs();
  init_check_effects();
  var CramorantVmax = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VMAX" /* POKEMON_VMAX */];
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Cramorant V";
      this.cardType = [C];
      this.hp = 320;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Max Jet",
          cost: [C, C, C],
          damage: 80,
          damageCalculation: "x",
          text: "Flip a coin for each Energy attached to this Pok\xE9mon. This attack does 80 damage for each heads."
        }
      ];
      this.regulationMark = "D";
      this.set = "SHF";
      this.setNumber = "55";
      this.cardImage = "assets/cardback.png";
      this.name = "Cramorant VMAX";
      this.fullName = "Cramorant VMAX SHF";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        const energyCount = checkEnergy.energyMap.reduce((sum, energy2) => {
          return sum + energy2.provides.length;
        }, 0);
        if (energyCount > 0) {
          MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, energyCount, (results) => {
            effect.damage = results.filter((r) => r).length * 80;
          });
        } else {
          effect.damage = 0;
        }
      }
      return state;
    }
  };

