  init_choose_cards_prompt();
  init_show_cards_prompt();
  init_shuffle_prompt();
  init_state_utils();
  init_prefabs();
  function* playCard214(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      const regex = /\bBall\b/;
      if (!c.name.match(regex)) {
        blocked.push(index);
      }
    });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 2 /* TRAINER */, trainerType: 0 /* ITEM */ },
        { min: 0, max: 3, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var BallGuy = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "SHF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "57";
      this.name = "Ball Guy";
      this.fullName = "Ball Guy SHF";
      this.text = 'Search your deck for up to 3 different Item cards that have the word "Ball" in their name, reveal them, and put them into your hand. Then, shuffle your deck.';
    }
    canPlay(store, state, player) {
      const supporterTurn = player.supporterTurn;
      if (supporterTurn > 0) {
        return false;
      }
      if (player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard214(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

