  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-sword-and-shield/lapras-v.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_energy_card();
  init_game_phase_effects();
  init_prefabs();
  init_choose_cards_prompt();
  init_check_effects();
  var LaprasV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 210;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Body Surf",
          cost: [C],
          damage: 0,
          text: "Attach a [W] Energy card from your hand to this Pok\xE9mon. If you do, switch it with 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Ocean Loop",
          cost: [W, W, W, C],
          damage: 210,
          text: "Put 2 [W] Energy attached to this Pok\xE9mon into your hand."
        }
      ];
      this.regulationMark = "D";
      this.set = "SSH";
      this.setNumber = "49";
      this.cardImage = "assets/cardback.png";
      this.name = "Lapras V";
      this.fullName = "Lapras V SSH";
      this.bodySurfAttached = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasWaterInHand = player.hand.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(3 /* WATER */)
        );
        if (!hasWaterInHand) {
          return state;
        }
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_ATTACH,
            player.hand,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
            { min: 0, max: 1, allowCancel: false }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length > 0) {
              const cardList = StateUtils.findCardList(state, this);
              if (cardList) {
                MOVE_CARDS(store, state, player.hand, cardList, { cards, sourceCard: this });
              }
              this.bodySurfAttached = true;
            }
          }
        );
      }
      if (effect instanceof AfterAttackEffect && this.bodySurfAttached) {
        this.bodySurfAttached = false;
        const player = effect.player;
        if (player.bench.some((b) => b.cards.length > 0)) {
          SWITCH_ACTIVE_WITH_BENCHED(store, state, player);
        }
      }
      if (effect instanceof EndTurnEffect) {
        this.bodySurfAttached = false;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        state = store.reduceEffect(state, checkEnergy);
        const waterEnergyMap = checkEnergy.energyMap.filter(
          (em) => em.provides.includes(3 /* WATER */) || em.provides.includes(0 /* ANY */)
        );
        if (waterEnergyMap.length === 0) {
          return state;
        }
        const count = Math.min(2, waterEnergyMap.length);
        store.prompt(
          state,
          new ChooseEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_HAND,
            waterEnergyMap,
            [9 /* COLORLESS */, 9 /* COLORLESS */],
            { allowCancel: false }
          ),
          (energy2) => {
            const cards = (energy2 || []).slice(0, count).map((e) => e.card);
            if (cards.length > 0) {
              MOVE_CARDS(store, state, player.active, player.hand, { cards, sourceCard: this });
            }
          }
        );
      }
      return state;
    }
  };

