  var CaraLiss = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "D";
      this.set = "VIV";
      this.setNumber = "149";
      this.cardImage = "assets/cardback.png";
      this.name = "Cara Liss";
      this.fullName = "Cara Liss VIV";
      this.text = "Search your deck for up to 2 Rare Fossil cards and put them onto your Bench. Then, shuffle your deck. You may play only 1 Supporter card during your turn.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (slots2.length > 0 && player.deck.cards.length > 0) {
          const blocked = [];
          player.deck.cards.forEach((card, index) => {
            if (card.name !== "Rare Fossil") {
              blocked.push(index);
            }
          });
          const max = Math.min(2, slots2.length);
          store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
              player.deck,
              {},
              { min: 0, max, allowCancel: false, blocked }
            ),
            (selected) => {
              const cards = selected || [];
              cards.forEach((card, index) => {
                if (index < slots2.length) {
                  const playPokemonEffect = new PlayPokemonEffect(player, card, slots2[index]);
                  store.reduceEffect(state, playPokemonEffect);
                }
              });
              SHUFFLE_DECK(store, state, player);
            }
          );
        } else {
          SHUFFLE_DECK(store, state, player);
        }
      }
      return state;
    }
  };

