  var Cinderace2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.cardType = [2 /* FIRE */];
      this.hp = 170;
      this.weakness = [{ type: 3 /* WATER */ }];
      this.retreat = [9 /* COLORLESS */];
      this.evolvesFrom = "Raboot";
      this.powers = [{
        name: "Libero",
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, when this Pok\xE9mon moves from your Bench to the Active Spot, you may attach up to 2 [R] Energy cards from your discard pile to it."
      }];
      this.attacks = [{
        name: "Flare Striker",
        cost: [2 /* FIRE */, 2 /* FIRE */, 9 /* COLORLESS */],
        damage: 190,
        text: "Discard 2 Energy from this Pok\xE9mon."
      }];
      this.set = "SSH";
      this.regulationMark = "D";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "34";
      this.name = "Cinderace";
      this.fullName = "Cinderace SSH";
      this.ABILITY_USED_MARKER = "ABILITY_USED_MARKER";
    }
    reduceEffect(store, state, effect) {
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.ABILITY_USED_MARKER, this);
      const player = state.players[state.activePlayer];
      if (effect instanceof MovedToActiveEffect && effect.pokemonCard === this && state.players[state.activePlayer] === effect.player && MOVED_TO_ACTIVE_THIS_TURN(effect.player, this)) {
        if (player.marker.hasMarker(this.ABILITY_USED_MARKER, this)) {
          return state;
        }
        try {
          const stub = new PowerEffect(player, {
            name: "test",
            powerType: 2 /* ABILITY */,
            text: ""
          }, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(2 /* FIRE */);
        });
        if (!hasEnergyInDiscard) {
          return state;
        }
        player.marker.addMarker(this.ABILITY_USED_MARKER, this);
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { allowCancel: true, min: 1, max: 2 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            return;
          }
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player2 = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player2);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(state, new ChooseEnergyPrompt(
          player2.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [2 /* FIRE */, 2 /* FIRE */],
          { allowCancel: false }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = player2.active;
          store.reduceEffect(state, discardEnergy2);
        });
      }
      return state;
    }
  };

