  var GalarianRapidash = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Galarian Ponyta";
      this.cardType = [P];
      this.hp = 100;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Pastel Veil",
        powerType: 2 /* ABILITY */,
        text: "Your Pok\xE9mon recover from all Special Conditions and can't be affected by any Special Conditions."
      }];
      this.attacks = [
        {
          name: "Psychic",
          cost: [P, C],
          damage: 30,
          damageCalculation: "+",
          text: "This attack does 30 more damage for each Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.regulationMark = "D";
      this.set = "SSH";
      this.setNumber = "82";
      this.cardImage = "assets/cardback.png";
      this.name = "Galarian Rapidash";
      this.fullName = "Galarian Rapidash SSH";
    }
    reduceEffect(store, state, effect) {
      PREVENT_AND_CLEAR_SPECIAL_CONDITIONS(state, effect, {
        shouldApply: (target) => {
          let owner = null;
          state.players.forEach((p) => {
            p.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList === target) {
                owner = p;
              }
            });
          });
          if (!owner) {
            return false;
          }
          let rapidashInPlay = false;
          owner.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
            if (card === this) {
              rapidashInPlay = true;
            }
          });
          if (!rapidashInPlay) {
            return false;
          }
          return !IS_ABILITY_BLOCKED(store, state, owner, this);
        }
      });
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        const energyCount = checkProvidedEnergyEffect.energyMap.reduce((left, p) => left + p.provides.length, 0);
        effect.damage += 30 * energyCount;
      }
      return state;
    }
  };

