  var Archeops4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.regulationMark = "F";
      this.evolvesFrom = "Archen";
      this.cardType = [9 /* COLORLESS */];
      this.hp = 150;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -30 }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Primal Turbo",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may search your deck for up to 2 Special Energy cards and attach them to 1 of your Pok\xE9mon. Then, shuffle your deck."
      }];
      this.attacks = [
        {
          name: "Speed Wing",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 120,
          text: ""
        }
      ];
      this.set = "SIT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "147";
      this.name = "Archeops";
      this.fullName = "Archeops SIT";
      this.PRIMAL_TURBO_MARKER = "PRIMAL_TURBO_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.PRIMAL_TURBO_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.PRIMAL_TURBO_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.deck,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 1 /* SPECIAL */ },
          { allowCancel: false, min: 0, max: 2, sameTarget: true }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          player.marker.addMarker(this.PRIMAL_TURBO_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
          }
          SHUFFLE_DECK(store, state, player);
        });
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.PRIMAL_TURBO_MARKER, this);
      }
      return state;
    }
  };

