  var Dragapult3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Drakloak";
      this.cardType = [P];
      this.hp = 150;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Dragon Launcher",
          cost: [P],
          damage: 0,
          text: "Discard a number of your Benched Dreepy up to the number of your opponent's Pok\xE9mon in play. Then, for each Dreepy you discarded in this way, choose 1 of your opponent's Pok\xE9mon and do 100 damage to it. You can't choose the same Pok\xE9mon more than once. This damage isn't affected by Weakness or Resistance."
        },
        {
          name: "Spooky Shot",
          cost: [P, C],
          damage: 120,
          text: ""
        }
      ];
      this.regulationMark = "F";
      this.set = "SIT";
      this.setNumber = "89";
      this.cardImage = "assets/cardback.png";
      this.name = "Dragapult";
      this.fullName = "Dragapult SIT 89";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const benchedDreepy = player.bench.filter(
          (b) => b.cards.length > 0 && b.getPokemonCard()?.name === "Dreepy"
        );
        if (benchedDreepy.length === 0) {
          return state;
        }
        let opponentPokemonCount = 1;
        opponentPokemonCount += opponent.bench.filter((b) => b.cards.length > 0).length;
        const maxToDiscard = Math.min(benchedDreepy.length, opponentPokemonCount);
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (!benchedDreepy.includes(cardList)) {
            blocked.push(target);
          }
        });
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DISCARD,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { min: 0, max: maxToDiscard, allowCancel: false, blocked }
        ), (selectedDreepy) => {
          if (!selectedDreepy || selectedDreepy.length === 0) {
            return;
          }
          for (const dreepyList of selectedDreepy) {
            MOVE_CARDS(store, state, dreepyList, player.discard, { sourceCard: this });
          }
          const dreepyDiscarded = selectedDreepy.length;
          if (dreepyDiscarded === 0) {
            return;
          }
          const opponentTargets = [];
          opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
            opponentTargets.push(target);
          });
          store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: dreepyDiscarded, max: dreepyDiscarded, allowCancel: false }
          ), (selectedTargets) => {
            if (!selectedTargets) {
              return;
            }
            for (const target of selectedTargets) {
              const damageEffect = new PutDamageEffect(effect, 100);
              damageEffect.target = target;
              store.reduceEffect(state, damageEffect);
            }
          });
        });
      }
      return state;
    }
  };

