  var Gardevoir10 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Kirlia";
      this.regulationMark = "F";
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 150;
      this.weakness = [{ type: 8 /* METAL */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Refinement",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "You must discard a card from your hand in order to use this Ability. Once during your turn, you may draw 2 cards."
      }];
      this.attacks = [
        {
          name: "Magical Shot",
          cost: [5 /* PSYCHIC */, 9 /* COLORLESS */],
          damage: 120,
          text: ""
        }
      ];
      this.set = "SIT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "69";
      this.name = "Gardevoir";
      this.fullName = "Gardevoir SIT";
      this.REFINEMENT_MARKER = "REFINEMENT_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.REFINEMENT_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.hand.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.REFINEMENT_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          {},
          { allowCancel: true, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          player.marker.addMarker(this.REFINEMENT_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 2, sourceCard: this });
        });
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        effect.player.marker.removeMarker(this.REFINEMENT_MARKER, this);
      }
      return state;
    }
  };

