  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-silver-tempest/hisuian-arcanine-v.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_move_energy_prompt();
  init_prefabs();
  init_energy_card();
  var HisuianArcanineV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 230;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Irresistible Force",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "As often as you like during your turn, you may move a [F] Energy from 1 of your other Pok\xE9mon to this Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Rock Bullet",
          cost: [C, C, C, C],
          damage: 90,
          damageCalculation: "+",
          text: "This attack does 30 more damage for each [F] Energy attached to this Pok\xE9mon."
        }
      ];
      this.regulationMark = "F";
      this.set = "SIT";
      this.setNumber = "90";
      this.cardImage = "assets/cardback.png";
      this.name = "Hisuian Arcanine V";
      this.fullName = "Hisuian Arcanine V SIT 90";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const thisTarget = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card === this) {
            thisTarget.push(target);
          }
        });
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card === this) {
            return;
          }
          const blocked = [];
          cardList.cards.forEach((c, index) => {
            const isFightingEnergy = c instanceof EnergyCard && c.provides.includes(6 /* FIGHTING */);
            if (!isFightingEnergy) {
              blocked.push(index);
            }
          });
          if (blocked.length !== cardList.cards.length) {
            blockedMap.push({ source: target, blocked });
          }
        });
        if (blockedMap.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card !== this) {
            blockedTo.push(target);
          }
        });
        return store.prompt(
          state,
          new MoveEnergyPrompt(
            player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            {},
            { allowCancel: true, blockedMap, blockedTo, min: 1, max: 1 }
          ),
          (transfers) => {
            if (transfers === null || transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let fightingCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            fightingCount = cardList.cards.filter(
              (c) => c instanceof EnergyCard && (c.provides.includes(6 /* FIGHTING */) || c.provides.includes(0 /* ANY */))
            ).length;
          }
        });
        effect.damage += 30 * fightingCount;
      }
      return state;
    }
  };

