  var OmastarV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 190;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [{
        name: "Primal Guidance",
        cost: [C],
        damage: 0,
        text: 'Search your deck for up to 2 Pok\xE9mon that evolve from an Item card that has "Fossil" in its name and put them onto your Bench. Then, shuffle your deck.'
      }, {
        name: "Tentacle Lock",
        cost: [W, C, C],
        damage: 110,
        text: "If the Defending Pok\xE9mon is an Evolution Pok\xE9mon, it can't attack during your opponent's next turn."
      }];
      this.regulationMark = "F";
      this.set = "SIT";
      this.setNumber = "35";
      this.cardImage = "assets/cardback.png";
      this.name = "Omastar V";
      this.fullName = "Omastar V SIT 35";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (slots2.length === 0) {
          return state;
        }
        const blocked = [];
        player.deck.cards.forEach((c, index) => {
          const isFossilPokemon = c instanceof PokemonCard && c.evolvesFrom && c.evolvesFrom.toLowerCase().includes("fossil");
          if (!isFossilPokemon) {
            blocked.push(index);
          }
        });
        const maxPick = Math.min(2, slots2.length);
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            player.deck,
            {},
            { min: 0, max: maxPick, allowCancel: false, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            cards.forEach((card, index) => {
              store.reduceEffect(
                state,
                new PlayPokemonFromDeckEffect(player, card, slots2[index])
              );
            });
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const defending = effect.opponent.active.getPokemonCard();
        if (defending && defending.stage !== 2 /* BASIC */) {
          return DEFENDING_POKEMON_CANNOT_ATTACK(store, state, effect, this);
        }
      }
      return state;
    }
  };

