  var RadiantAlakazam = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["Radiant" /* RADIANT */];
      this.regulationMark = "F";
      this.stage = 2 /* BASIC */;
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 130;
      this.weakness = [{ type: 7 /* DARK */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -30 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [
        {
          name: "Painful Spoons",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may move up to 2 damage counters from 1 of your opponent's Pok\xE9mon to another of their Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Mind Ruler",
          cost: [5 /* PSYCHIC */, 9 /* COLORLESS */],
          damage: 20,
          damageCalculation: "x",
          text: "This attack does 20 damage for each card in your opponent's hand."
        }
      ];
      this.set = "SIT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "59";
      this.name = "Radiant Alakazam";
      this.fullName = "Radiant Alakazam SIT";
      this.PAINFUL_SPOONS_MARKER = "PAINFUL_SPOONS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.PAINFUL_SPOONS_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const damagedPokemon = [
          ...opponent.bench.filter((b) => b.cards.length > 0 && b.damage > 0),
          ...opponent.active.damage > 0 ? [opponent.active] : []
        ];
        if (player.marker.hasMarker(this.PAINFUL_SPOONS_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (damagedPokemon.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const maxAllowedDamage = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkHpEffect = new CheckHpEffect(player, cardList);
          store.reduceEffect(state, checkHpEffect);
          maxAllowedDamage.push({ target, damage: checkHpEffect.hp });
        });
        return store.prompt(
          state,
          new MoveDamagePrompt(
            effect.player.id,
            GameMessage.MOVE_DAMAGE,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            maxAllowedDamage,
            { min: 1, max: 2, allowCancel: false, singleDestinationTarget: true }
          ),
          (transfers) => {
            player.marker.addMarker(this.PAINFUL_SPOONS_MARKER, this);
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              const damageToMove = 10;
              source.damage -= damageToMove;
              target.damage += damageToMove;
            }
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.addBoardEffect(0 /* ABILITY_USED */);
              }
            });
            return state;
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const oppHand = opponent.hand.cards.length;
        effect.damage = 20 * oppHand;
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.marker.removeMarker(this.PAINFUL_SPOONS_MARKER);
        return state;
      }
      return state;
    }
  };

