  var Rapidash7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.cardType = [2 /* FIRE */];
      this.hp = 100;
      this.weakness = [{ type: 3 /* WATER */ }];
      this.evolvesFrom = "Ponyta";
      this.attacks = [{
        name: "Fire Mane",
        cost: [2 /* FIRE */, 9 /* COLORLESS */],
        damage: 60,
        text: ""
      }];
      this.powers = [{
        name: "Heat Boost",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may discard a [R] Energy card from your hand in order to use this Ability. During this turn, your [R] Pok\xE9mon's attacks do 30 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance)."
      }];
      this.retreat = [9 /* COLORLESS */];
      this.regulationMark = "F";
      this.set = "SIT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "22";
      this.name = "Rapidash";
      this.fullName = "Rapidash SIT";
      this.HEAT_BOOST_MARKER = "HEAT_BOOST_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttackEffect && effect.player.marker.hasMarker(this.HEAT_BOOST_MARKER, this) && effect.damage > 0) {
        effect.damage += 30;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.HEAT_BOOST_MARKER, this)) {
        effect.player.marker.removeMarker(this.HEAT_BOOST_MARKER, this);
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.HEAT_BOOST_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c instanceof EnergyCard && c.name === "Fire Energy";
        });
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.HEAT_BOOST_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { allowCancel: true, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          player.marker.addMarker(this.HEAT_BOOST_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
        });
        return state;
      }
      return state;
    }
  };

