  var RegidragoV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["V" /* POKEMON_V */];
      this.cardType = [11 /* DRAGON */];
      this.hp = 220;
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Celestial Roar",
          cost: [9 /* COLORLESS */],
          damage: 0,
          text: "Discard the top 3 cards of your deck. If any of those cards are Energy cards, attach them to this Pok\xE9mon."
        },
        {
          name: "Dragon Laser",
          cost: [1 /* GRASS */, 1 /* GRASS */, 2 /* FIRE */],
          damage: 130,
          text: "This attack also does 30 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.set = "SIT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "135";
      this.regulationMark = "F";
      this.name = "Regidrago V";
      this.fullName = "Regidrago V SIT";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const temp = new CardList();
        MOVE_CARDS(store, state, player.deck, temp, { count: 3, sourceCard: this });
        const energyCardsDrawn = temp.cards.filter((card) => {
          return card instanceof EnergyCard && card.energyType === 0 /* BASIC */;
        });
        if (energyCardsDrawn.length == 0) {
          temp.cards.slice(0, 3).forEach((card) => {
            MOVE_CARDS(store, state, temp, player.discard, { cards: [card], sourceCard: this });
          });
        } else {
          return store.prompt(
            state,
            new AttachEnergyPrompt(
              player.id,
              GameMessage.ATTACH_ENERGY_CARDS,
              temp,
              // Only show drawn energies
              2 /* BOTTOM_PLAYER */,
              [1 /* ACTIVE */],
              { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
              { min: energyCardsDrawn.length, max: energyCardsDrawn.length, allowCancel: false }
            ),
            (transfers) => {
              if (transfers) {
                for (const transfer of transfers) {
                  const target = StateUtils.getTarget(state, player, transfer.to);
                  MOVE_CARDS(store, state, temp, target, { cards: [transfer.card], sourceCard: this });
                }
                temp.cards.forEach((card) => {
                  MOVE_CARDS(store, state, temp, player.discard, { cards: [card], sourceCard: this });
                });
              }
            }
          );
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        state = store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const damageEffect = new PutDamageEffect(effect, 30);
            damageEffect.target = targets[0];
            store.reduceEffect(state, damageEffect);
          }
        );
        return state;
      }
      return state;
    }
  };

