  var Relicanth8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Fossil Finding",
          cost: [C],
          damage: 0,
          text: "Shuffle up to 4 in any combination of Unidentified Fossil and Rare Fossil cards from your discard pile into your deck."
        },
        {
          name: "Water Pulse",
          cost: [W, C],
          damage: 30,
          text: "Your opponent's Active Pok\xE9mon is now Asleep."
        }
      ];
      this.regulationMark = "F";
      this.set = "SIT";
      this.setNumber = "44";
      this.cardImage = "assets/cardback.png";
      this.name = "Relicanth";
      this.fullName = "Relicanth SIT 44";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const fossilsInDiscard = player.discard.cards.filter(
          (c) => c instanceof TrainerCard && c.trainerType === 0 /* ITEM */ && (c.name === "Unidentified Fossil" || c.name === "Rare Fossil")
        );
        if (fossilsInDiscard.length === 0) {
          return state;
        }
        const maxPick = Math.min(4, fossilsInDiscard.length);
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          const isFossil = c instanceof TrainerCard && c.trainerType === 0 /* ITEM */ && (c.name === "Unidentified Fossil" || c.name === "Rare Fossil");
          if (!isFossil) {
            blocked.push(index);
          }
        });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DECK,
          player.discard,
          { superType: 2 /* TRAINER */ },
          { min: 0, max: maxPick, allowCancel: false, blocked }
        ), (selected) => {
          const cards = selected || [];
          if (cards.length > 0) {
            cards.forEach((c) => MOVE_CARDS(store, state, player.discard, player.deck, { cards: [c], sourceCard: this }));
          }
          SHUFFLE_DECK(store, state, player);
        });
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        ADD_SLEEP_TO_PLAYER_ACTIVE(store, state, effect.opponent, this);
      }
      return state;
    }
  };

