  var SkuntankV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [D];
      this.hp = 210;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      // Track the opponent's Pokemon that retreated from the Active Spot during the opponent's last turn.
      // We store the card reference directly since PokemonCardList.clearEffects() wipes all custom markers
      // before the retreat swap completes, making marker-based tracking unreliable.
      // The CLEAR_RETREATED_MARKER is on the player-level marker (not cardlist) and is NOT cleared by clearEffects().
      // Ref: set-steam-siege/seedot.ts (2-marker pattern for opponent's next turn effects)
      this.CLEAR_RETREATED_MARKER = "SKUNTANK_V_SIT_CLEAR_RETREATED_MARKER";
      // Card reference to the Pokemon that retreated during the opponent's last turn
      this.retreatedCard = null;
      this.attacks = [
        {
          name: "Pursuit Blast",
          cost: [C, C],
          damage: 0,
          text: "This attack does 30 damage to 1 of your opponent's Benched Pok\xE9mon. If that Pok\xE9mon retreated from the Active Spot during your opponent's last turn, this attack does 120 damage instead. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Shrieking Poison",
          cost: [D, C, C],
          damage: 90,
          text: "Your opponent's Active Pok\xE9mon is now Confused and Poisoned."
        }
      ];
      this.regulationMark = "F";
      this.set = "SIT";
      this.setNumber = "108";
      this.cardImage = "assets/cardback.png";
      this.name = "Skuntank V";
      this.fullName = "Skuntank V SIT 108";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof RetreatEffect) {
        const retreatingPlayer = effect.player;
        const retreatingCard = retreatingPlayer.active.getPokemonCard();
        if (retreatingCard) {
          this.retreatedCard = retreatingCard;
          retreatingPlayer.marker.addMarker(this.CLEAR_RETREATED_MARKER, this);
        }
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.CLEAR_RETREATED_MARKER, this)) {
        effect.player.marker.removeMarker(this.CLEAR_RETREATED_MARKER, this);
        this.retreatedCard = null;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            if (!selected || selected.length === 0) {
              return;
            }
            const target = selected[0];
            const hasRetreated = this.retreatedCard !== null && target.getPokemonCard() === this.retreatedCard;
            const damage = hasRetreated ? 120 : 30;
            const putDamage = new PutDamageEffect(effect, damage);
            putDamage.target = target;
            store.reduceEffect(state, putDamage);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_CONFUSED(store, state, effect);
        YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_POISIONED(store, state, effect);
      }
      return state;
    }
  };

