        const pokemon = player.active;
        let specialEnergyCount = 0;
        pokemon.cards.forEach((c) => {
          if (c instanceof EnergyCard) {
            if (c.energyType === 1 /* SPECIAL */) {
              specialEnergyCount++;
            }
          }
        });
