  var EarthenSealStone = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.regulationMark = "F";
      this.set = "SIT";
      this.setNumber = "154";
      this.cardImage = "assets/cardback.png";
      this.name = "Earthen Seal Stone";
      this.fullName = "Earthen Seal Stone SIT 154";
      this.text = "The Pok\xE9mon V this card is attached to can use the VSTAR Power on this card. (You still need the necessary Energy to use this attack.) You may play any number of Item cards during your turn. Attach a Pok\xE9mon Tool to 1 of your Pok\xE9mon that doesn't already have a Pok\xE9mon Tool attached.";
      this.attacks = [
        {
          name: "Stone Gift",
          cost: [9 /* COLORLESS */],
          damage: 0,
          text: "You may play any number of Item cards during your turn. Attach a Pok\xE9mon Tool to 1 of your Pok\xE9mon that doesn't already have a Pok\xE9mon Tool attached. (You can't use more than 1 VSTAR Power in a game.)"
        }
      ];
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckPokemonAttacksEffect) {
        if (!effect.player.active.tools.includes(this)) {
          return state;
        }
        const pokemonCard = effect.player.active.getPokemonCard();
        if (!pokemonCard) {
          return state;
        }
        const vTags = [
          "V" /* POKEMON_V */,
          "VMAX" /* POKEMON_VMAX */,
          "VSTAR" /* POKEMON_VSTAR */,
          "V-UNION" /* POKEMON_VUNION */
        ];
        if (!vTags.some((tag) => pokemonCard.hasTag(tag))) {
          return state;
        }
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        if (!effect.attacks.includes(this.attacks[0])) {
          effect.attacks.push(this.attacks[0]);
        }
      }
      if (effect instanceof AttackEffect && effect.attack === this.attacks[0]) {
        const player = effect.player;
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        if (player.usedVSTAR) {
          throw new GameError(GameMessage.LABEL_VSTAR_USED);
        }
        player.usedVSTAR = true;
        const hasTool = player.hand.cards.some(
          (c) => c instanceof TrainerCard && c.trainerType === 3 /* TOOL */
        );
        if (!hasTool) {
          return state;
        }
        const blocked = [];
        player.hand.cards.forEach((c, index) => {
          if (!(c instanceof TrainerCard) || c.trainerType !== 3 /* TOOL */) {
            blocked.push(index);
          }
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_ATTACH,
            player.hand,
            { trainerType: 3 /* TOOL */ },
            { min: 1, max: 1, allowCancel: true, blocked }
          ),
          (selectedCards) => {
            if (!selectedCards || selectedCards.length === 0) {
              return;
            }
            const toolCard = selectedCards[0];
            const validTargets = [];
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
              if (cardList.tools.length === 0) {
                validTargets.push(target);
              }
            });
            if (validTargets.length === 0) {
              return;
            }
            const blockedTargets = [];
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
              if (!validTargets.includes(target)) {
                blockedTargets.push(target);
              }
            });
            store.prompt(
              state,
              new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
                2 /* BOTTOM_PLAYER */,
                [1 /* ACTIVE */, 2 /* BENCH */],
                { min: 1, max: 1, allowCancel: false, blocked: blockedTargets }
              ),
              (selectedPokemon) => {
                if (!selectedPokemon || selectedPokemon.length === 0) {
                  return;
                }
                const attachEffect = new AttachPokemonToolEffect(
                  player,
                  toolCard,
                  selectedPokemon[0]
                );
                store.reduceEffect(state, attachEffect);
              }
            );
          }
        );
      }
      return state;
    }
  };

