  function* playCard216(next, store, state, effect) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: effect.trainerCard
    });
    effect.preventDefault = true;
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const openSlots = player.bench.filter((b) => b.cards.length === 0);
    if (openSlots.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
        { min: 1, max: 1, allowCancel: true }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    cards.forEach((card, index) => {
      store.reduceEffect(
        state,
        new PlayPokemonFromDeckEffect(player, card, slots2[index])
      );
      state = store.prompt(
        state,
        new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
        (wantToUse) => {
          if (wantToUse) {
            if (index === 0 && player.active.cards.length > 0) {
              const activePokemon = player.active;
              activePokemon.clearEffects();
              player.switchPokemon(slots2[index]);
            }
          }
        }
      );
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var FurisodeGirl = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "F";
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "SIT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "157";
      this.name = "Furisode Girl";
      this.fullName = "Furisode Girl SIT";
      this.text = "Search your deck for a Basic Pok\xE9mon and put it onto your Bench. Then, shuffle your deck. You may switch that Pok\xE9mon with your Active Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard216(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

