  var ProfessorLaventon = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "F";
      this.set = "SIT";
      this.setNumber = "162";
      this.cardImage = "assets/cardback.png";
      this.name = "Professor Laventon";
      this.fullName = "Professor Laventon SIT 162";
      this.text = 'Put up to 3 Pok\xE9mon that have "Hisuian" in their names from your discard pile into your hand. You may play only 1 Supporter card during your turn.';
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        const hisuianInDiscard = player.discard.cards.filter(
          (c) => c instanceof PokemonCard && c.name.includes("Hisuian")
        );
        if (hisuianInDiscard.length === 0) {
          return state;
        }
        const maxPick = Math.min(3, hisuianInDiscard.length);
        const blocked = [];
        player.discard.cards.forEach((c, index) => {
          const isHisuian = c instanceof PokemonCard && c.name.includes("Hisuian");
          if (!isHisuian) {
            blocked.push(index);
          }
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.discard,
            { superType: 1 /* POKEMON */ },
            { min: 0, max: maxPick, allowCancel: false, blocked }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: this });
            }
          }
        );
      }
      return state;
    }
  };

