  var Wallace = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "F";
      this.set = "SIT";
      this.setNumber = "166";
      this.cardImage = "assets/cardback.png";
      this.name = "Wallace";
      this.fullName = "Wallace SIT 166";
      this.text = "Draw 3 cards. Your opponent may draw a card. If they do, draw 1 more card. You may play only 1 Supporter card during your turn.";
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        DRAW_CARDS(store, state, player, 3);
        if (opponent.deck.cards.length > 0) {
          CONFIRMATION_PROMPT(
            store,
            state,
            opponent,
            (result) => {
              if (result) {
                DRAW_CARDS(store, state, opponent, 1);
                DRAW_CARDS(store, state, player, 1);
              }
            },
            GameMessage.WANT_TO_DRAW_CARDS
          );
        }
      }
      return state;
    }
  };

