  var Worker = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "SIT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "167";
      this.regulationMark = "F";
      this.name = "Worker";
      this.fullName = "Worker SIT";
      this.text = "Draw 3 cards. Discard a Stadium in play.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.deck, player.hand, { count: 3, sourceCard: this });
        const stadiumCard = StateUtils.getStadiumCard(state);
        if (stadiumCard !== void 0) {
          const cardList = StateUtils.findCardList(state, stadiumCard);
          const player2 = StateUtils.findOwner(state, cardList);
          MOVE_CARDS(store, state, cardList, player2.discard, { sourceCard: this });
          return state;
        }
        return state;
      }
      return state;
    }
  };

