  var RegenerativeEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "F";
      this.provides = [9 /* COLORLESS */];
      this.energyType = 1 /* SPECIAL */;
      this.set = "SIT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "168";
      this.name = "Regenerative Energy";
      this.fullName = "Regenerative Energy SIT";
      this.text = `As long as this card is attached to a Pok\xE9mon, it provides [C] Energy.

Whenever you play a Pok\xE9mon from your hand to evolve the Pok\xE9mon V this card is attached to, heal 100 damage from that Pok\xE9mon.`;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EvolveEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, effect.target)) {
          return state;
        }
        if (effect.target.getPokemonCard()?.hasTag("V" /* POKEMON_V */)) {
          const healEffect = new HealEffect(player, effect.target, 100);
          store.reduceEffect(state, healEffect);
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-silver-tempest/v-guard-energy.ts
