  var VGuardEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [9 /* COLORLESS */];
      this.energyType = 1 /* SPECIAL */;
      this.regulationMark = "F";
      this.set = "SIT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "169";
      this.name = "V Guard Energy";
      this.fullName = "V Guard Energy SIT";
      this.text = "As long as this card is attached to a Pok\xE9mon, it provides [C] Energy.\nThe Pok\xE9mon this card is attached to takes 30 less damage from attacks from your opponent's Pok\xE9mon V (after applying Weakness and Resistance). This effect can't be applied more than once at a time to the same Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, effect.target)) {
          return state;
        }
        const sourceCard = effect.source.getPokemonCard();
        if (sourceCard?.hasTag("V" /* POKEMON_V */ || "VMAX" /* POKEMON_VMAX */ || "VSTAR" /* POKEMON_VSTAR */)) {
          const targetPlayer = StateUtils.findOwner(state, effect.target);
          if (targetPlayer === player) {
            effect.reduceDamage(30, this.name);
          }
          return state;
        }
        return state;
      }
      return state;
    }
  };

