  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-sword-and-shield/bisharp.ts
  init_pokemon_card();
  init_card_types();
  init_prefabs();
  var Bisharp12 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Pawniard";
      this.cardType = [M];
      this.hp = 120;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Charge Order",
          cost: [C],
          damage: 30,
          damageCalculation: "+",
          text: "This attack does 30 more damage for each of your Benched Pawniard."
        },
        {
          name: "Slicing Blade",
          cost: [M, C],
          damage: 60,
          text: ""
        }
      ];
      this.regulationMark = "D";
      this.set = "SSH";
      this.setNumber = "134";
      this.cardImage = "assets/cardback.png";
      this.name = "Bisharp";
      this.fullName = "Bisharp SSH";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let pawniardCount = 0;
        player.bench.forEach((b) => {
          if (b.cards.length > 0) {
            const card = b.getPokemonCard();
            if (card && card.name === "Pawniard") {
              pawniardCount++;
            }
          }
        });
        effect.damage += 30 * pawniardCount;
      }
      return state;
    }
  };

