  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-sword-and-shield/cinderace-3.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_play_card_action();
  var Cinderace3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Raboot";
      this.cardType = [R];
      this.hp = 170;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Flame Cloak",
        cost: [R],
        damage: 40,
        text: "Attach a [R] Energy card from your discard pile to this Pok\xE9mon."
      }, {
        name: "Bright Flame",
        cost: [R, R, C],
        damage: 160,
        text: "Flip a coin. If tails, discard 2 Energy from this Pok\xE9mon."
      }];
      this.regulationMark = "D";
      this.set = "SSH";
      this.setNumber = "36";
      this.cardImage = "assets/cardback.png";
      this.name = "Cinderace";
      this.fullName = "Cinderace SSH 36";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (card !== this) {
            blocked.push(target.index);
          }
        });
        ATTACH_ENERGY_PROMPT(
          store,
          state,
          player,
          2 /* BOTTOM_PLAYER */,
          4 /* DISCARD */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { min: 0, max: 1, allowCancel: false, blocked }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (!result) {
            DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 2);
          }
        });
      }
      return state;
    }
  };

