  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-sword-and-shield/ferrothorn.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Ferrothorn6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Ferroseed";
      this.cardType = [M];
      this.hp = 130;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Triple Smash",
        cost: [C],
        damage: 30,
        damageCalculation: "x",
        text: "Flip 3 coins. This attack does 30 damage for each heads."
      }, {
        name: "Energy Slap",
        cost: [M, M, C],
        damage: 100,
        text: "You may move all Energy from this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
      }];
      this.regulationMark = "D";
      this.set = "SSH";
      this.setNumber = "131";
      this.cardImage = "assets/cardback.png";
      this.name = "Ferrothorn";
      this.fullName = "Ferrothorn SSH";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, effect.player, 3, (results) => {
          const heads = results.filter((r) => r).length;
          effect.damage = 30 * heads;
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const attachedEnergies = player.active.cards.filter(
          (card) => card.superType === 3 /* ENERGY */
        );
        if (attachedEnergies.length === 0) {
          return state;
        }
        CONFIRMATION_PROMPT(store, state, player, (result) => {
          if (result) {
            store.prompt(state, new AttachEnergyPrompt(
              player.id,
              GameMessage.ATTACH_ENERGY_TO_BENCH,
              player.active,
              2 /* BOTTOM_PLAYER */,
              [2 /* BENCH */],
              { superType: 3 /* ENERGY */ },
              { allowCancel: false, min: attachedEnergies.length, max: attachedEnergies.length, sameTarget: true }
            ), (transfers) => {
              transfers = transfers || [];
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
              }
            });
          }
        });
      }
      return state;
    }
  };

