  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-sword-and-shield/noctowl.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_phase_effects();
  init_prefabs();
  init_choose_pokemon_prompt();
  var Noctowl7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Hoothoot";
      this.cardType = [C];
      this.hp = 110;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Wing Attack",
          cost: [C, C],
          damage: 40,
          text: ""
        },
        {
          name: "Carry Off",
          cost: [C, C, C],
          damage: 0,
          text: "Choose 1 of your opponent's Benched Pok\xE9mon. They shuffle that Pok\xE9mon and all attached cards into their deck. Then, shuffle this Pok\xE9mon and all attached cards into your deck."
        }
      ];
      this.regulationMark = "D";
      this.set = "SSH";
      this.setNumber = "144";
      this.cardImage = "assets/cardback.png";
      this.name = "Noctowl";
      this.fullName = "Noctowl SSH";
      this.usedCarryOff = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        this.usedCarryOff = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedCarryOff) {
        this.usedCarryOff = false;
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (selected) => {
          if (selected && selected.length > 0) {
            const benchSlot = selected[0];
            const toolsToMove = benchSlot.tools.slice();
            toolsToMove.forEach((card) => {
              MOVE_CARDS(store, state, benchSlot, opponent.deck, { cards: [card], sourceCard: this });
            });
            const cardsToMove = benchSlot.cards.slice();
            cardsToMove.forEach((card) => {
              MOVE_CARDS(store, state, benchSlot, opponent.deck, { cards: [card], sourceCard: this });
            });
            benchSlot.clearEffects();
            SHUFFLE_DECK(store, state, opponent);
          }
          const selfTools = player.active.tools.slice();
          selfTools.forEach((card) => {
            MOVE_CARDS(store, state, player.active, player.deck, { cards: [card], sourceCard: this });
          });
          const selfCards = player.active.cards.slice();
          selfCards.forEach((card) => {
            MOVE_CARDS(store, state, player.active, player.deck, { cards: [card], sourceCard: this });
          });
          player.active.clearEffects();
          SHUFFLE_DECK(store, state, player);
        });
      }
      if (effect instanceof EndTurnEffect) {
        this.usedCarryOff = false;
      }
      return state;
    }
  };

