  init_game_effects();
  init_prefabs();
  var StonjournerVMAX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Stonjourner V";
      this._tags = ["VMAX" /* POKEMON_VMAX */];
      this.cardType = [F];
      this.hp = 330;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Stone Gift",
          cost: [F],
          damage: 0,
          text: "Attach a [F] Energy card from your hand to 1 of your Pok\xE9mon. If you do, heal 120 damage from that Pok\xE9mon."
        },
        {
          name: "Max Rockfall",
          cost: [F, F, F],
          damage: 200,
          text: ""
        }
      ];
      this.set = "SSH";
      this.regulationMark = "D";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "116";
      this.name = "Stonjourner VMAX";
      this.fullName = "Stonjourner VMAX SSH";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.hand,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fighting Energy" },
            { allowCancel: true, min: 1, max: 1 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return state;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.hand, target, { cards: [transfer.card], sourceCard: this });
              const healEffect = new HealEffect(player, target, 120);
              state = store.reduceEffect(state, healEffect);
            }
          }
        );
      }
      return state;
    }
  };

