  var MetalSaucer = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.regulationMark = "D";
      this.set = "SSH";
      this.name = "Metal Saucer";
      this.fullName = "Metal Saucer SSH";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "170";
      this.text = "Attach a [M] Energy card from your discard pile to 1 of your Benched [M] Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(8 /* METAL */);
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        let hasMetalPokemonOnBench = false;
        const blockedTo = [];
        player.bench.forEach((bench, index) => {
          if (bench.cards.length === 0) {
            return;
          }
          const checkPokemonTypeEffect = new CheckPokemonTypeEffect(bench);
          store.reduceEffect(state, checkPokemonTypeEffect);
          if (checkPokemonTypeEffect.cardTypes.includes(8 /* METAL */)) {
            hasMetalPokemonOnBench = true;
          } else {
            const target = {
              player: 2 /* BOTTOM_PLAYER */,
              slot: 2 /* BENCH */,
              index
            };
            blockedTo.push(target);
          }
        });
        if (!hasMetalPokemonOnBench) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, name: "Metal Energy" },
            { allowCancel: true, min: 1, max: 1, blockedTo }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, {
                cards: [transfer.card],
                sourceCard: this
              });
            }
          }
        );
      }
      return state;
    }
  };

