  function* playCard219(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const pokemonAndEnergyInDiscardPile = player.discard.cards.filter(
      (c) => c instanceof PokemonCard || c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
    ).length;
    if (pokemonAndEnergyInDiscardPile === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    let pokemons = 0;
    let energies = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      if (c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */) {
        energies += 1;
      } else if (c instanceof PokemonCard) {
        pokemons += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxPokemons = Math.min(pokemons, 2);
    const maxEnergies = Math.min(energies, 2);
    const count = maxPokemons + maxEnergies;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        {},
        { min: 0, max: count, allowCancel: false, blocked, maxPokemons, maxEnergies }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
