  var LuckyEgg = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "AR";
      this.name = "Lucky Egg";
      this.fullName = "Lucky Egg AR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "88";
      this.text = "When the Pok\xE9mon this card is attached to is Knocked Out by damage from an opponent's attack, draw cards until you have 7 cards in your hand.";
      this.damageDealt = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttackEffect && effect.player.active.tools.includes(this)) {
        this.damageDealt = false;
      }
      if ((effect instanceof DealDamageEffect || effect instanceof PutDamageEffect) && effect.target.tools.includes(this)) {
        const player = StateUtils.getOpponent(state, effect.player);
        if (player.active.tools.includes(this)) {
          this.damageDealt = true;
        }
      }
      if (effect instanceof EndTurnEffect && effect.player === StateUtils.getOpponent(state, effect.player)) {
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        if (owner === effect.player) {
          this.damageDealt = false;
        }
      }
      if (effect instanceof KnockOutEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        if (this.damageDealt) {
          DRAW_CARDS_UNTIL_CARDS_IN_HAND(player, 7);
        }
        return state;
      }
      return state;
    }
  };

