  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-sword-and-shield-promos/champions-festival.ts
  init_game();
  init_trainer_card();
  init_card_types();
  init_game_effects();
  init_stadium_effect();
  var ChampionsFestival = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "SWSH";
      this.regulationMark = "F";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "296";
      this.name = "Champion's Festival";
      this.fullName = "Champion's Festival SWSH";
      this.text = "Once during each player's turn, if that player has 6 Pok\xE9mon in play, they may heal 10 damage from each of their Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const pokemonInPlay = player.bench.filter((b) => b.cards.length > 0).length + (player.active.cards.length > 0 ? 1 : 0);
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, player, player.active, this)) {
          return state;
        }
        if (pokemonInPlay !== 6) {
          throw new GameError(GameMessage.CANNOT_USE_STADIUM);
        }
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          store.reduceEffect(state, new HealEffect(player, cardList, 10));
        });
      }
      return state;
    }
  };

