  function* useMixedCall(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    let pokemon = 0;
    let supporters = 0;
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      if (c instanceof PokemonCard) {
        pokemon++;
      } else if (c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */) {
        supporters++;
      } else {
        blocked.push(index);
      }
    });
    const maxPokemons = Math.min(pokemon, 1);
    const maxSupporters = Math.min(supporters, 1);
    const count = maxPokemons + maxSupporters;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_ONE_POKEMON_AND_ONE_SUPPORTER_TO_HAND,
        player.deck,
        {},
        { min: 0, max: count, allowCancel: false, blocked, maxPokemons, maxSupporters }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
