  var Celebi5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 60;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Energy Press",
          cost: [G],
          damage: 30,
          damageCalculation: "x",
          text: "This attack does 30 damage for each Energy attached to your opponent's Active Pok\xE9mon."
        },
        {
          name: "Amazing Bloom",
          cost: [L, P],
          damage: 0,
          text: "For each of your Benched Pok\xE9mon, search your deck for a card that evolves from that Pok\xE9mon and put it onto that Pok\xE9mon to evolve it. Then, shuffle your deck."
        }
      ];
      this.regulationMark = "D";
      this.set = "VIV";
      this.setNumber = "9";
      this.cardImage = "assets/cardback.png";
      this.name = "Celebi";
      this.fullName = "Celebi VIV";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkEnergy = new CheckProvidedEnergyEffect(opponent, opponent.active);
        store.reduceEffect(state, checkEnergy);
        const totalEnergy = checkEnergy.energyMap.reduce((sum, e) => sum + e.provides.length, 0);
        effect.damage = 30 * totalEnergy;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const benchedSlots = player.bench.filter((b) => b.cards.length > 0);
        if (benchedSlots.length === 0) {
          return state;
        }
        let slotIndex = 0;
        const evolveNext = () => {
          if (slotIndex >= benchedSlots.length) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          const target = benchedSlots[slotIndex];
          slotIndex++;
          const pokemonCard = target.getPokemonCard();
          if (!pokemonCard) {
            evolveNext();
            return;
          }
          const blocked = [];
          player.deck.cards.forEach((card, index) => {
            if (!(card instanceof PokemonCard) || card.evolvesFrom !== pokemonCard.name) {
              blocked.push(index);
            }
          });
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_EVOLVE,
            player.deck,
            { superType: 1 /* POKEMON */ },
            { min: 0, max: 1, allowCancel: false, blocked }
          ), (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              const evolution = cards[0];
              MOVE_CARDS(store, state, player.deck, target, { cards: [evolution], sourceCard: this });
              target.clearEffects();
              target.pokemonPlayedTurn = state.turn;
            }
            evolveNext();
          });
        };
        evolveNext();
      }
      return state;
    }
  };

