  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-vivid-voltage/chimecho.ts
  init_game();
  init_attack_effects();
  init_prefabs();
  var Chimecho6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 70;
      this.weakness = [{ type: 7 /* DARK */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -30 }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [{
        name: "Auspicious Tone",
        cost: [9 /* COLORLESS */],
        damage: 0,
        text: "Search your deck for a Pok\xE9mon and a Supporter card, reveal them, and put them into your hand. Then, shuffle your deck."
      }, {
        name: "Hypnoblast",
        cost: [5 /* PSYCHIC */, 9 /* COLORLESS */],
        damage: 30,
        text: "Your opponent's Active Pok\xE9mon is now Asleep."
      }];
      this.set = "VIV";
      this.name = "Chimecho";
      this.fullName = "Chimecho VIV";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "72";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const specialConditionEffect = new AddSpecialConditionsEffect(effect, [2 /* ASLEEP */]);
        store.reduceEffect(state, specialConditionEffect);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let supporters = 0;
        let pokemon = 0;
        const blocked = [];
        player.deck.cards.forEach((c, index) => {
          if (c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */) {
            supporters += 1;
          } else if (c instanceof PokemonCard) {
            pokemon += 1;
          } else {
            blocked.push(index);
          }
        });
        const maxSupporters = Math.min(supporters, 1);
        const maxPokemons = Math.min(pokemon, 1);
        let cards = [];
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.deck,
          {},
          { min: 0, max: maxSupporters + maxPokemons, allowCancel: false, maxSupporters, maxPokemons }
        ), (selected) => {
          cards = selected || [];
          cards.forEach((card, index) => {
            MOVE_CARDS(store, state, player.deck, player.hand, { cards: [card], sourceCard: this });
          });
          state = store.prompt(
            state,
            new ShowCardsPrompt(
              opponent.id,
              GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
              cards
            ),
            () => state
          );
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      return state;
    }
  };

