  var Clefable12 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Clefairy";
      this.cardType = [P];
      this.hp = 100;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.LUNAR_BLESSING_MARKER = "CLEFABLE_VIV_LUNAR_BLESSING_MARKER";
      this.powers = [{
        name: "Lunar Blessing",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, if your Active Pok\xE9mon has any [P] Energy attached, you may heal 20 damage from it, and it recovers from a Special Condition."
      }];
      this.attacks = [
        {
          name: "Magical Shot",
          cost: [P, C, C],
          damage: 80,
          text: ""
        }
      ];
      this.regulationMark = "D";
      this.set = "VIV";
      this.setNumber = "64";
      this.cardImage = "assets/cardback.png";
      this.name = "Clefable";
      this.fullName = "Clefable VIV";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const checkEnergy = new CheckProvidedEnergyEffect(player, player.active);
        store.reduceEffect(state, checkEnergy);
        const hasPsychicEnergy = checkEnergy.energyMap.some(
          (em) => em.provides.some((t) => t === 5 /* PSYCHIC */ || t === 0 /* ANY */)
        );
        if (!hasPsychicEnergy) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.LUNAR_BLESSING_MARKER, this);
        ABILITY_USED(player, this);
        player.active.damage = Math.max(0, player.active.damage - 20);
        player.active.specialConditions = [];
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.LUNAR_BLESSING_MARKER, this);
      return state;
    }
  };

