  var CoalossalVmax = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["VMAX" /* POKEMON_VMAX */];
      this.stage = 5 /* VMAX */;
      this.evolvesFrom = "Coalossal V";
      this.cardType = [F];
      this.hp = 330;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Eruption Shot",
          cost: [F],
          damage: 40,
          damageCalculation: "+",
          text: "Discard the top card of your deck. If that card is an Energy card, this attack does 90 more damage, and attach that card to this Pok\xE9mon."
        },
        {
          name: "G-Max Boulder",
          cost: [F, F, F, C],
          damage: 240,
          text: ""
        }
      ];
      this.regulationMark = "D";
      this.set = "VIV";
      this.setNumber = "99";
      this.cardImage = "assets/cardback.png";
      this.name = "Coalossal VMAX";
      this.fullName = "Coalossal VMAX VIV";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const topCard = new CardList();
        MOVE_CARDS(store, state, player.deck, topCard, { count: 1, sourceCard: this });
        const isEnergyCard = topCard.cards.length > 0 && topCard.cards[0] instanceof EnergyCard;
        if (isEnergyCard) {
          const cardList = StateUtils.findCardList(state, this);
          if (cardList) {
            MOVE_CARDS(store, state, topCard, cardList, { cards: [topCard.cards[0]], sourceCard: this });
          } else {
            MOVE_CARDS(store, state, topCard, player.discard, { sourceCard: this });
          }
          effect.damage += 90;
        } else {
          MOVE_CARDS(store, state, topCard, player.discard, { sourceCard: this });
        }
      }
      return state;
    }
  };

