  init_game();
  init_card_types();
  init_pokemon_card();
  init_prefabs();
  var Duskull7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "D";
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 60;
      this.resistance = [{ type: F, value: -30 }];
      this.weakness = [{ type: D }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Future Sight",
          cost: [C],
          damage: 0,
          text: "Look at the top 4 cards of either player's deck and put them back in any order."
        }
      ];
      this.set = "VIV";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "69";
      this.name = "Duskull";
      this.fullName = "Duskull VIV";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const options = [
          {
            message: GameMessage.ORDER_OPPONENT_DECK,
            action: () => {
              const opponentDeckTop = new CardList();
              MOVE_CARDS(store, state, opponent.deck, opponentDeckTop, { count: 4, sourceCard: this });
              return store.prompt(state, new OrderCardsPrompt(
                player.id,
                GameMessage.CHOOSE_CARDS_ORDER,
                opponentDeckTop,
                { allowCancel: false }
              ), (order) => {
                if (order === null) {
                  return state;
                }
                opponentDeckTop.applyOrder(order);
                opponentDeckTop.moveToTopOfDestination(opponent.deck);
              });
            }
          },
          {
            message: GameMessage.ORDER_YOUR_DECK,
            action: () => {
              const player2 = effect.player;
              const playerDeckTop = new CardList();
              MOVE_CARDS(store, state, player2.deck, playerDeckTop, { count: 4, sourceCard: this });
              return store.prompt(state, new OrderCardsPrompt(
                player2.id,
                GameMessage.CHOOSE_CARDS_ORDER,
                playerDeckTop,
                { allowCancel: false }
              ), (order) => {
                if (order === null) {
                  return state;
                }
                playerDeckTop.applyOrder(order);
                playerDeckTop.moveToTopOfDestination(player2.deck);
              });
            }
          }
        ];
        return store.prompt(state, new SelectPrompt(
          player.id,
          GameMessage.CHOOSE_OPTION,
          options.map((opt) => opt.message),
          { allowCancel: false }
        ), (choice) => {
          const option = options[choice];
          option.action();
        });
      }
      return state;
    }
  };

