  var Eelektrik10 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Tynamo";
      this.cardType = [L];
      this.hp = 90;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Shocking Smash",
        cost: [L],
        damage: 0,
        text: "Flip a coin. If heads, discard an Energy from 1 of your opponent's Pok\xE9mon."
      }, {
        name: "Head Bolt",
        cost: [L, C, C],
        damage: 60,
        text: ""
      }];
      this.regulationMark = "D";
      this.set = "VIV";
      this.setNumber = "58";
      this.cardImage = "assets/cardback.png";
      this.name = "Eelektrik";
      this.fullName = "Eelektrik VIV";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (!result) {
            return;
          }
          let hasEnergy = false;
          opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
            if (cardList.cards.some((c) => c.superType === 3 /* ENERGY */)) {
              hasEnergy = true;
            }
          });
          if (!hasEnergy) {
            return;
          }
          store.prompt(state, new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DISCARD_CARDS,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { allowCancel: false }
          ), (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const target = targets[0];
            const energyCards = target.cards.filter((c) => c.superType === 3 /* ENERGY */);
            if (energyCards.length === 0) {
              return;
            }
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              target,
              { superType: 3 /* ENERGY */ },
              { min: 1, max: 1, allowCancel: false }
            ), (selected) => {
              const cards = selected || [];
              if (cards.length > 0) {
                const discardEnergy2 = new DiscardCardsEffect(effect, cards);
                discardEnergy2.target = target;
                store.reduceEffect(state, discardEnergy2);
              }
            });
          });
        });
      }
      return state;
    }
  };

