  var Flareon7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Eevee";
      this.cardType = [R];
      this.hp = 110;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Incandescent Awakening",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon has a Memory Capsule attached, Grass Pok\xE9mon in play (both yours and your opponent's) have no Abilities."
      }];
      this.attacks = [
        {
          name: "Fire Mane",
          cost: [R, R, C],
          damage: 100,
          text: ""
        }
      ];
      this.regulationMark = "D";
      this.set = "VIV";
      this.setNumber = "26";
      this.cardImage = "assets/cardback.png";
      this.name = "Flareon";
      this.fullName = "Flareon VIV";
    }
    findFlareonInPlay(state) {
      for (const player of state.players) {
        let found = null;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            found = cardList;
          }
        });
        if (found) {
          return { cardList: found, owner: player };
        }
      }
      return null;
    }
    hasMemoryCapsule(cardList) {
      return cardList.tools.some(
        (tool) => tool instanceof TrainerCard && tool.name === "Memory Capsule"
      );
    }
    isGrassPokemon(store, state, card) {
      const targetCardList = StateUtils.findCardList(state, card);
      if (!(targetCardList instanceof PokemonCardList)) {
        return false;
      }
      const checkType = new CheckPokemonTypeEffect(targetCardList);
      store.reduceEffect(state, checkType);
      return checkType.cardTypes.includes(1 /* GRASS */);
    }
    reduceEffect(store, state, effect) {
      const isTargetLocked = ({ card }) => {
        if (!this.isGrassPokemon(store, state, card)) {
          return false;
        }
        const flareon = this.findFlareonInPlay(state);
        if (!flareon || !this.hasMemoryCapsule(flareon.cardList)) {
          return false;
        }
        if (IS_ABILITY_BLOCKED(store, state, flareon.owner, this)) {
          return false;
        }
        try {
          return StateUtils.findCardList(state, card) instanceof PokemonCardList;
        } catch {
          return false;
        }
      };
      HANDLE_ABILITY_LOCK(effect, ({ card }) => isTargetLocked({ card }), {
        allowUseFromHand: true,
        allowUseFromDiscard: true,
        error: GameMessage.BLOCKED_BY_EFFECT
      });
      return state;
    }
  };

