  var GalarianPerrserker5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Galarian Meowth";
      this.cardType = [M];
      this.hp = 120;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Stealy Claws",
        cost: [M],
        damage: 20,
        text: "Flip 3 coins. If any of them are heads, your opponent reveals their hand. Then, for each heads, discard a Trainer card from your opponent's hand."
      }, {
        name: "Claw Slash",
        cost: [M, C, C],
        damage: 90,
        text: ""
      }];
      this.set = "VIV";
      this.regulationMark = "D";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "113";
      this.name = "Galarian Perserker";
      this.fullName = "Galarian Perserker VIV";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let headsCount = 0;
        MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          results.forEach((result) => {
            if (result) {
              headsCount++;
            }
          });
          if (headsCount === 0) {
            return state;
          }
          const minDiscard = Math.min(opponent.hand.cards.filter((c) => c.superType === 2 /* TRAINER */).length, headsCount);
          let cards = [];
          store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.hand,
            { superType: 2 /* TRAINER */ },
            { min: minDiscard, max: minDiscard, allowCancel: false }
          ), (selected) => {
            cards = selected || [];
            MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards, sourceCard: this });
          });
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-vivid-voltage/galarian-sirfetchd-v.ts
  init_game();
