  init_prefabs();
  var GalarianSirfetchdV = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["V" /* POKEMON_V */];
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 210;
      this.weakness = [{ type: P }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Resolute Spear",
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, when this Pok\xE9mon moves from your Bench to the Active Spot, you may move any amount of [F] Energy from your other Pok\xE9mon to it."
        }
      ];
      this.attacks = [
        {
          name: "Meteor Smash",
          cost: [F, F, C],
          damage: 200,
          text: "During your next turn, this Pok\xE9mon can't attack."
        }
      ];
      this.regulationMark = "D";
      this.set = "VIV";
      this.setNumber = "174";
      this.cardImage = "assets/cardback.png";
      this.name = "Galarian Sirfetch'd V";
      this.fullName = "Galarian Sirfetch'd V VIV";
      this.ABILITY_USED_MARKER = "GALARIAN_SIRFETCHD_V_ABILITY_USED_MARKER";
    }
    reduceEffect(store, state, effect) {
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.ABILITY_USED_MARKER, this);
      const player = state.players[state.activePlayer];
      if (effect instanceof MovedToActiveEffect && effect.pokemonCard === this && state.players[state.activePlayer] === effect.player && MOVED_TO_ACTIVE_THIS_TURN(effect.player, this)) {
        if (player.marker.hasMarker(this.ABILITY_USED_MARKER, this)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const blockedFrom = [];
        const blockedTo = [];
        let hasFightingEnergyOnBench = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList === player.active) {
            blockedFrom.push(target);
            return;
          }
          blockedTo.push(target);
          if (cardList.cards.some((c) => c.superType === 3 /* ENERGY */)) {
            hasFightingEnergyOnBench = true;
          }
        });
        if (!hasFightingEnergyOnBench) {
          return state;
        }
        return store.prompt(
          state,
          new MoveEnergyPrompt(
            player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fighting Energy" },
            { allowCancel: true, blockedTo, blockedFrom }
          ),
          (transfers) => {
            if (!transfers || transfers.length === 0) {
              return;
            }
            const validTransfers = transfers || [];
            for (const transfer of validTransfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              MOVE_CARDS(store, state, source, player.active, { cards: [transfer.card], sourceCard: this });
            }
            player.marker.addMarker(this.ABILITY_USED_MARKER, this);
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.addBoardEffect(0 /* ABILITY_USED */);
              }
            });
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_POKEMON_CANNOT_ATTACK_NEXT_TURN(effect.player);
      }
      return state;
    }
  };

