  function* useDreamyRevelation(next, store, state, effect) {
    const player = effect.player;
    const deckTop = new CardList();
    MOVE_CARDS(store, state, player.deck, deckTop, { count: 2, sourceCard: effect.card });
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_HAND,
      deckTop,
      {},
      { min: 1, max: 1, allowCancel: true }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    MOVE_CARDS(store, state, deckTop, player.hand, { cards, sourceCard: effect.card });
    deckTop.moveToTopOfDestination(player.deck);
  }
  var Jirachi8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [8 /* METAL */];
      this.hp = 70;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.resistance = [{ type: 1 /* GRASS */, value: -30 }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Dreamy Revelation",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, if this Pok\xE9mon is in the Active Spot, you may look at the top 2 cards of your deck and put 1 of them into your hand. Put the other card back on top of your deck. "
      }];
      this.attacks = [{
        name: "Amazing Star",
        cost: [5 /* PSYCHIC */, 6 /* FIGHTING */, 8 /* METAL */],
        damage: 0,
        text: "Search your deck for up to 7 basic Energy cards and attach them to your Pok\xE9mon in any way you like. Then, shuffle your deck. "
      }];
      this.set = "VIV";
      this.regulationMark = "D";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "119";
      this.name = "Jirachi";
      this.fullName = "Jirachi VIV";
      this.DREAMY_REVELATION_MARKER = "DREAMY_REVELATION_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.DREAMY_REVELATION_MARKER, this);
        return state;
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.DREAMY_REVELATION_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.active.cards[0] !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        player.marker.addMarker(this.DREAMY_REVELATION_MARKER, this);
        const generator = useDreamyRevelation(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.deck,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { allowCancel: true, min: 0, max: 7 }
        ), (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            SHUFFLE_DECK(store, state, player);
            return state;
          }
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
          }
          state = store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.DREAMY_REVELATION_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.DREAMY_REVELATION_MARKER, this);
      }
      return state;
    }
  };

