  var Jolteon7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Eevee";
      this.cardType = [L];
      this.hp = 100;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [{
        name: "Thunderous Awakening",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon has a Memory Capsule attached, Water Pok\xE9mon in play (both yours and your opponent's) have no Abilities."
      }];
      this.attacks = [
        {
          name: "Electric Ball",
          cost: [L, C, C],
          damage: 90,
          text: ""
        }
      ];
      this.regulationMark = "D";
      this.set = "VIV";
      this.setNumber = "47";
      this.cardImage = "assets/cardback.png";
      this.name = "Jolteon";
      this.fullName = "Jolteon VIV";
    }
    findJolteonInPlay(state) {
      for (const player of state.players) {
        let found = null;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            found = cardList;
          }
        });
        if (found) {
          return { cardList: found, owner: player };
        }
      }
      return null;
    }
    hasMemoryCapsule(cardList) {
      return cardList.tools.some(
        (tool) => tool instanceof TrainerCard && tool.name === "Memory Capsule"
      );
    }
    isWaterPokemon(store, state, card) {
      const targetCardList = StateUtils.findCardList(state, card);
      if (!(targetCardList instanceof PokemonCardList)) {
        return false;
      }
      const checkType = new CheckPokemonTypeEffect(targetCardList);
      store.reduceEffect(state, checkType);
      return checkType.cardTypes.includes(3 /* WATER */);
    }
    reduceEffect(store, state, effect) {
      const isTargetLocked = ({ card }) => {
        if (!this.isWaterPokemon(store, state, card)) {
          return false;
        }
        const jolteon = this.findJolteonInPlay(state);
        if (!jolteon || !this.hasMemoryCapsule(jolteon.cardList)) {
          return false;
        }
        if (IS_ABILITY_BLOCKED(store, state, jolteon.owner, this)) {
          return false;
        }
        try {
          return StateUtils.findCardList(state, card) instanceof PokemonCardList;
        } catch {
          return false;
        }
      };
      HANDLE_ABILITY_LOCK(effect, ({ card }) => isTargetLocked({ card }), {
        allowUseFromHand: true,
        allowUseFromDiscard: true,
        error: GameMessage.BLOCKED_BY_EFFECT
      });
      return state;
    }
  };

