  var Metagross7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Metang";
      this.cardType = [M];
      this.hp = 170;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Levitation Field",
        powerType: 2 /* ABILITY */,
        text: "Your Pok\xE9mon in play have no Retreat Cost."
      }];
      this.attacks = [
        {
          name: "Leg Quake",
          cost: [M, C, C],
          damage: 100,
          text: "If the Defending Pok\xE9mon is an Evolution Pok\xE9mon, it can't attack during your opponent's next turn."
        }
      ];
      this.regulationMark = "D";
      this.set = "VIV";
      this.setNumber = "118";
      this.cardImage = "assets/cardback.png";
      this.name = "Metagross";
      this.fullName = "Metagross VIV";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner !== player || !StateUtils.isPokemonInPlay(owner, this)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, owner, this)) {
          return state;
        }
        effect.cost = [];
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const defending = effect.opponent.active.getPokemonCard();
        if (defending && defending.stage !== 2 /* BASIC */) {
          return DEFENDING_POKEMON_CANNOT_ATTACK(store, state, effect, this);
        }
      }
      return state;
    }
  };

