      this.evolvesFrom = "Dewott";
      this.cardType = [W];
      this.hp = 160;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Swaddling Leaves",
        powerType: 2 /* ABILITY */,
        text: "This Pok\xE9mon takes 30 less damage from attacks (after applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Aqua Wash",
          cost: [W, C, C],
          damage: 120,
          text: "You may put 2 Energy attached to your opponent's Active Pok\xE9mon into their hand."
        }
      ];
      this.regulationMark = "D";
