  var Shedinja4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 30;
      this.retreat = [C];
      this.powers = [{
        name: "Shell Survival",
        powerType: 2 /* ABILITY */,
        text: "Put this Pok\xE9mon into play only with the effect of Ninjask's Cast-Off Shell Ability. (When you are setting up to play, you cannot put it face down as your Active Pok\xE9mon or on your Bench.)"
      }];
      this.attacks = [
        {
          name: "Life Squeeze",
          cost: [C, C, C],
          damage: 0,
          text: "Put damage counters on your opponent's Active Pok\xE9mon until its remaining HP is 10."
        }
      ];
      this.regulationMark = "D";
      this.set = "VIV";
      this.setNumber = "66";
      this.cardImage = "assets/cardback.png";
      this.name = "Shedinja";
      this.fullName = "Shedinja VIV";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const selectedTarget = opponent.active;
        const checkHpEffect = new CheckHpEffect(player, selectedTarget);
        store.reduceEffect(state, checkHpEffect);
        const totalHp = checkHpEffect.hp;
        const targetDamage = selectedTarget.damage;
        const damageAmount = Math.max(0, totalHp - 10 - targetDamage);
        const damageEffect = new PutDamageEffect(effect, damageAmount);
        damageEffect.target = selectedTarget;
        store.reduceEffect(state, damageEffect);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-vivid-voltage/shiftry.ts
  init_game();
  init_card_types();
  init_pokemon_card();
  init_play_card_effects();
  init_prefabs();
  var Shiftry7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Nuzleaf";
      this.cardType = [G];
      this.hp = 150;
      this.weakness = [{ type: R }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Shiftry Substitution",
        text: `As long as this Pok\xE9mon is in the Active Spot, each Supporter card in your opponent's hand has the effect "Draw 3 cards." (This happens instead of the card's usual effect.)`,
        useWhenInPlay: false,
        powerType: 2 /* ABILITY */
      }];
      this.attacks = [{
        name: "Fan Tornado",
        cost: [G, C],
        damage: 110,
        damageCalculation: "x",
        text: "You may have your opponent switch their Active Pok\xE9mon with 1 of their Benched Pok\xE9mon."
      }];
      this.regulationMark = "D";
      this.set = "VIV";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "12";
      this.name = "Shiftry";
      this.fullName = "Shiftry VIV";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlaySupporterEffect) {
        const cardList = StateUtils.findCardList(state, this);
        const player = StateUtils.findOwner(state, cardList);
        const opponent = StateUtils.getOpponent(state, player);
        if (effect.player === player) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (player.active === cardList) {
          const supporterTurn = effect.player.supporterTurn;
          if (supporterTurn > 0) {
            throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
          }
          effect.preventDefault = true;
          MOVE_CARDS(store, state, effect.player.hand, effect.player.supporter, { cards: [effect.trainerCard], sourceCard: this });
          MOVE_CARDS(store, state, opponent.deck, opponent.hand, { count: 3, sourceCard: this });
          MOVE_CARDS(store, state, effect.player.supporter, effect.player.discard, { cards: [effect.trainerCard], sourceCard: this });
          effect.player.supporterTurn += 1;
          return state;
        }
        return state;
      }
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_SWITCH_POKEMON
        ), (wantToUse) => {
          if (wantToUse) {
            return store.prompt(state, new ChoosePokemonPrompt(
              opponent.id,
              GameMessage.CHOOSE_POKEMON_TO_SWITCH,
              2 /* BOTTOM_PLAYER */,
              [2 /* BENCH */],
              { allowCancel: false }
            ), (targets) => {
              if (targets && targets.length > 0) {
                opponent.active.clearEffects();
                opponent.switchPokemon(targets[0]);
                return state;
              }
            });
          }
        });
      }
      return state;
    }
  };

