  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/09-sword-and-shield/set-vivid-voltage/trumbeak.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_energy_card();
  init_play_card_effects();
  init_prefabs();
  var Trumbeak3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Pikipek";
      this.cardType = [C];
      this.hp = 80;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Charging Trumpet",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may look at the top 3 cards of your deck and attach any number of basic Energy cards you find there to your Pok\xE9mon in any way you like. Shuffle the other cards back into your deck."
      }];
      this.attacks = [
        {
          name: "Drill Peck",
          cost: [C, C, C],
          damage: 50,
          text: ""
        }
      ];
      this.regulationMark = "D";
      this.set = "VIV";
      this.setNumber = "144";
      this.cardImage = "assets/cardback.png";
      this.name = "Trumbeak";
      this.fullName = "Trumbeak VIV";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (player.deck.cards.length === 0) {
          return state;
        }
        store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (!wantToUse) {
            return;
          }
          const topCards = new CardList();
          const count = Math.min(3, player.deck.cards.length);
          MOVE_CARDS(store, state, player.deck, topCards, { count, sourceCard: this });
          const basicEnergyCards = topCards.cards.filter(
            (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
          );
          if (basicEnergyCards.length === 0) {
            MOVE_CARDS(store, state, topCards, player.deck, { sourceCard: this });
            SHUFFLE_DECK(store, state, player);
            return;
          }
          store.prompt(state, new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            topCards,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: 0, max: basicEnergyCards.length }
          ), (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              const energyCard = transfer.card;
              const attachEnergyEffect = new AttachEnergyEffect(player, energyCard, target);
              store.reduceEffect(state, attachEnergyEffect);
            }
            MOVE_CARDS(store, state, topCards, player.deck, { sourceCard: this });
            SHUFFLE_DECK(store, state, player);
          });
        });
        return state;
      }
      return state;
    }
  };

