  var Vaporeon7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Eevee";
      this.cardType = [W];
      this.hp = 110;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Torrential Awakening",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon has a Memory Capsule attached, Fire Pok\xE9mon in play (both yours and your opponent's) have no Abilities."
      }];
      this.attacks = [
        {
          name: "Aurora Beam",
          cost: [W, C],
          damage: 70,
          text: ""
        }
      ];
      this.regulationMark = "D";
      this.set = "VIV";
      this.setNumber = "30";
      this.cardImage = "assets/cardback.png";
      this.name = "Vaporeon";
      this.fullName = "Vaporeon VIV";
    }
    findVaporeonInPlay(state) {
      for (const player of state.players) {
        let found = null;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            found = cardList;
          }
        });
        if (found) {
          return { cardList: found, owner: player };
        }
      }
      return null;
    }
    hasMemoryCapsule(cardList) {
      return cardList.tools.some(
        (tool) => tool instanceof TrainerCard && tool.name === "Memory Capsule"
      );
    }
    isFirePokemon(store, state, card) {
      const targetCardList = StateUtils.findCardList(state, card);
      if (!(targetCardList instanceof PokemonCardList)) {
        return false;
      }
      const checkType = new CheckPokemonTypeEffect(targetCardList);
      store.reduceEffect(state, checkType);
      return checkType.cardTypes.includes(2 /* FIRE */);
    }
    reduceEffect(store, state, effect) {
      const isTargetLocked = ({ card }) => {
        if (!this.isFirePokemon(store, state, card)) {
          return false;
        }
        const vaporeon = this.findVaporeonInPlay(state);
        if (!vaporeon || !this.hasMemoryCapsule(vaporeon.cardList)) {
          return false;
        }
        if (IS_ABILITY_BLOCKED(store, state, vaporeon.owner, this)) {
          return false;
        }
        try {
          return StateUtils.findCardList(state, card) instanceof PokemonCardList;
        } catch {
          return false;
        }
      };
      HANDLE_ABILITY_LOCK(effect, ({ card }) => isTargetLocked({ card }), {
        allowUseFromHand: true,
        allowUseFromDiscard: true,
        error: GameMessage.BLOCKED_BY_EFFECT
      });
      return state;
    }
  };

