  var AromaticGrassEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [C];
      this.energyType = 1 /* SPECIAL */;
      this.set = "VIV";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "162";
      this.regulationMark = "D";
      this.name = "Aromatic Grass Energy";
      this.fullName = "Aromatic Grass Energy VIV";
      this.text = `As long as this card is attached to a Pok\xE9mon, it provides[G] Energy.
    
The [G] Pok\xE9mon this card is attached to recovers from all Special Conditions and can't be affected by any Special Conditions.`;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        effect.energyMap.push({ card: this, provides: [1 /* GRASS */] });
        return state;
      }
      if (effect instanceof AttachEnergyEffect && effect.target.cards.includes(this)) {
        const pokemon = effect.target;
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, effect.player, this, pokemon)) {
          return state;
        }
        const checkPokemonType = new CheckPokemonTypeEffect(pokemon);
        store.reduceEffect(state, checkPokemonType);
        if (!checkPokemonType.cardTypes.includes(1 /* GRASS */)) {
          return state;
        }
        pokemon.removeSpecialCondition(2 /* ASLEEP */);
        pokemon.removeSpecialCondition(0 /* PARALYZED */);
        pokemon.removeSpecialCondition(1 /* CONFUSED */);
        pokemon.removeSpecialCondition(4 /* BURNED */);
        pokemon.removeSpecialCondition(3 /* POISONED */);
        return state;
      }
      const cardList = StateUtils.findCardList(state, this);
      if (effect instanceof CheckTableStateEffect && cardList instanceof PokemonCardList && cardList.cards.includes(this)) {
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, effect.player, this, cardList)) {
          return state;
        }
        const checkPokemonType = new CheckPokemonTypeEffect(cardList);
        store.reduceEffect(state, checkPokemonType);
        if (!checkPokemonType.cardTypes.includes(1 /* GRASS */)) {
          return state;
        }
        cardList.removeSpecialCondition(2 /* ASLEEP */);
        cardList.removeSpecialCondition(0 /* PARALYZED */);
        cardList.removeSpecialCondition(1 /* CONFUSED */);
        cardList.removeSpecialCondition(4 /* BURNED */);
        cardList.removeSpecialCondition(3 /* POISONED */);
      }
      return state;
    }
  };

