  var CoatingMetalEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [9 /* COLORLESS */];
      this.energyType = 1 /* SPECIAL */;
      this.set = "VIV";
      this.name = "Coating Metal Energy";
      this.fullName = "Coating Metal Energy VIV";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "163";
      this.text = `As long as this card is attached to a Pok\xE9mon, it provides [M] Energy.
    
The [M] Pok\xE9mon this card is attached to has no Weakness.`;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        effect.energyMap.push({ card: this, provides: [8 /* METAL */] });
        return state;
      }
      if (effect instanceof AbstractAttackEffect && effect.target && effect.target.cards.includes(this)) {
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, effect.opponent, this, effect.target)) {
          return state;
        }
        const checkPokemonType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkPokemonType);
        if (checkPokemonType.cardTypes.includes(8 /* METAL */)) {
          if (effect instanceof PutDamageEffect) {
            effect.attackEffect.ignoreWeakness = true;
            return state;
          }
          if (effect instanceof DealDamageEffect) {
            effect.attackEffect.ignoreWeakness = true;
            return state;
          }
        }
      }
      return state;
    }
  };

