  var WashWaterEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [9 /* COLORLESS */];
      this.energyType = 1 /* SPECIAL */;
      this.set = "VIV";
      this.regulationMark = "D";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "165";
      this.name = "Wash Water Energy";
      this.fullName = "Wash Water Energy VIV";
      this.text = `As long as this card is attached to a Pok\xE9mon, it provides [W] Energy.
    
Prevent all effects of attacks from your opponent's Pok\xE9mon done to the [W] Pok\xE9mon this card is attached to. (Existing effects are not removed. Damage is not an effect.)`;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        effect.energyMap.push({ card: this, provides: [3 /* WATER */] });
        return state;
      }
      if (effect instanceof AbstractAttackEffect && effect.target?.cards?.includes(this)) {
        const targetOwner = StateUtils.findOwner(state, effect.target);
        const opponent = StateUtils.getOpponent(state, targetOwner);
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, opponent, this, effect.target)) {
          return state;
        }
        if (!IS_ATTACK_EFFECT_FROM_OPPONENTS_POKEMON(state, effect)) {
          return state;
        }
        const checkPokemonType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkPokemonType);
        if (checkPokemonType.cardTypes.includes(3 /* WATER */)) {
          if (effect instanceof ApplyWeaknessEffect) {
            return state;
          }
          if (effect instanceof PutDamageEffect) {
            return state;
          }
          if (effect instanceof DealDamageEffect) {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      return state;
    }
  };

