  function* playCard226(next, store, state, self, effect) {
    const player = effect.player;
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    let pokemonsInDiscard = 0;
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      const isPokemon = c instanceof PokemonCard;
      if (isPokemon) {
        pokemonsInDiscard += 1;
      } else {
        blocked.push(index);
      }
    });
    if (pokemonsInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        { superType: 1 /* POKEMON */ },
        { min: 1, max: 5, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
    state = store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
    MOVE_CARDS(store, state, player.deck, player.hand, { count: 3, sourceCard: self });
  }
