  var Hawlucha11 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.regulationMark = "G";
      this.cardType = [6 /* FIGHTING */];
      this.hp = 70;
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Flying Entry",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may choose 2 of your opponent's Benched Pok\xE9mon and put 1 damage counter on each of them."
      }];
      this.attacks = [
        {
          name: "Wing Attack",
          cost: [6 /* FIGHTING */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 70,
          text: ""
        }
      ];
      this.set = "SVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "118";
      this.name = "Hawlucha";
      this.fullName = "Hawlucha SVI";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = StateUtils.findOwner(state, effect.target);
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            try {
              const stub = new PowerEffect(player, {
                name: "test",
                powerType: 2 /* ABILITY */,
                text: ""
              }, this);
              store.reduceEffect(state, stub);
            } catch {
              return state;
            }
            return store.prompt(state, new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
              1 /* TOP_PLAYER */,
              [2 /* BENCH */],
              { min: 1, max: 2, allowCancel: false }
            ), (selected) => {
              ABILITY_USED(player, this);
              const targets = selected || [];
              targets.forEach((target) => {
                state = store.reduceEffect(state, new PlaceDamageCountersEffect(player, target, 10, this));
              });
              return state;
            });
          }
        });
      }
      return state;
    }
  };

