  var Kingambit = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Bisharp";
      this.cardType = [7 /* DARK */];
      this.hp = 170;
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Leadership",
        powerType: 2 /* ABILITY */,
        text: "Your Basic Pok\xE9mon's attacks do 30 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance)."
      }];
      this.attacks = [
        {
          name: "Hack At",
          cost: [7 /* DARK */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 160,
          text: ""
        }
      ];
      this.set = "SVI";
      this.setNumber = "134";
      this.cardImage = "assets/cardback.png";
      this.regulationMark = "H";
      this.name = "Kingambit";
      this.fullName = "Kingambit SVI";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let isThisInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            isThisInPlay = true;
          }
        });
        if (!isThisInPlay) {
          return state;
        }
        const oppActive = opponent.active.getPokemonCard();
        const damageSource = effect.source.getPokemonCard();
        if (damageSource && damageSource.stage === 2 /* BASIC */ && damageSource !== oppActive) {
          effect.damage += 30;
          return state;
        }
      }
      return state;
    }
  };

