  var Klefki8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.regulationMark = "G";
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 70;
      this.weakness = [{ type: 8 /* METAL */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Mischievous Lock",
        powerType: 2 /* ABILITY */,
        abilityLock: true,
        text: "As long as this Pok\xE9mon is in the Active Spot, Basic Pok\xE9mon in play (both yours and your opponent's) have no Abilities, except for Mischievous Lock."
      }];
      this.attacks = [{
        name: "Joust",
        cost: [9 /* COLORLESS */],
        damage: 10,
        text: "Before doing damage, discard all Pok\xE9mon Tools from your opponent's Active Pok\xE9mon."
      }];
      this.set = "SVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "96";
      this.name = "Klefki";
      this.fullName = "Klefki SVI";
    }
    reduceEffect(store, state, effect) {
      HANDLE_ABILITY_LOCK(effect, ({ player, card }) => {
        if (!IS_ABILITY_LOCKER_ACTIVE(state, player, this)) {
          return false;
        }
        const targetCardList = StateUtils.findCardList(state, card);
        if (!(targetCardList instanceof PokemonCardList)) {
          return false;
        }
        if (card.stage !== 2 /* BASIC */) {
          return false;
        }
        const lockerOwner = StateUtils.findOwner(state, StateUtils.findCardList(state, this));
        return LOCKER_ABILITY_APPLIES(store, state, lockerOwner, this, this.powers[0], card);
      }, {
        exemptPowerNames: ["Mischievous Lock"],
        allowUseFromHand: true,
        allowUseFromDiscard: true,
        error: GameMessage.BLOCKED_BY_ABILITY
      });
      if (BEFORE_DAMAGE(effect, 0, this)) {
        const tools = [...effect.opponent.active.tools];
        return DISCARD_CARDS_FROM_OPPONENTS_ACTIVE_POKEMON(store, state, effect, tools);
      }
      return state;
    }
  };

