  var RockChestplate = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this._trainerType = 3 /* TOOL */;
      this.set = "SVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "192";
      this.name = "Rock Chestplate";
      this.fullName = "Rock Chestplate SVI";
      this.text = "The [F] Pok\xE9mon this card is attached to takes 30 less damage from attacks from your opponent's Pok\xE9mon (after applying Weakness and Resistance).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.tools.includes(this)) {
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        const sourceCard = player.active.getPokemonCard();
        const opponent = StateUtils.findOwner(state, effect.source);
        if (player === opponent) {
          return state;
        }
        if (pokemonHasCardTypeOptional(sourceCard, 6 /* FIGHTING */)) {
          const targetPlayer = StateUtils.findOwner(state, effect.target);
          if (targetPlayer === player) {
            effect.reduceDamage(30);
          }
          return state;
        }
        return state;
      }
      return state;
    }
  };

