  var Toedscruel = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.cardType = [G];
      this.hp = 120;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.evolvesFrom = "Toedscool";
      this.attacks = [{
        name: "Eerie Tentacles",
        cost: [G],
        damage: 30,
        text: " You may move an Energy from your opponent's Active Pok\xE9mon to 1 of their Benched Pok\xE9mon."
      }, {
        name: "Triple Smash",
        cost: [G, C, C],
        damage: 80,
        damageCalculation: "x",
        text: " Flip 3 coins. This attack does 80 damage for each heads. "
      }];
      this.set = "SVI";
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.fullName = "Toedscruel SVI";
      this.name = "Toedscruel";
      this.setNumber = "26";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (hasBench === false) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          opponent.active,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: 0, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, opponent.active, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        state = MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, 3, (results) => {
          let heads = 0;
          results.forEach((r) => {
            heads += r ? 1 : 0;
          });
          effect.damage = 80 * heads;
        });
        return state;
      }
      return state;
    }
  };

