  var Youngster = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "G";
      this.set = "SVI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "198";
      this.name = "Youngster";
      this.fullName = "Youngster SVI";
      this.text = "Shuffle your hand into your deck. Then, draw 5 cards.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (player.hand.cards.length === 0 && player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        return SHUFFLE_HAND_INTO_DECK_THEN_DRAW(store, state, player, {
          excludeCard: this,
          drawCount: 5
        });
      }
      return state;
    }
  };

