  var IonosKilowattrel = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Iono's Wattrel";
      this._tags = ["Iono's" /* IONOS */];
      this.cardType = [L];
      this.hp = 120;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Flashing Draw",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "You must discard a Basic [L] Energy from this Pok\xE9mon in order to use this Ability. Once during your turn, you may draw cards until you have 6 cards in your hand."
        }
      ];
      this.attacks = [
        {
          name: "Mach Bolt",
          cost: [L, C, C],
          damage: 70,
          text: ""
        }
      ];
      this.regulationMark = "I";
      this.set = "JTG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "55";
      this.name = "Iono's Kilowattrel";
      this.fullName = "Iono's Kilowattrel JTG";
      this.RUMBLING_ENGINE_MARKER = "RUMBLING_ENGINE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.RUMBLING_ENGINE_MARKER, this);
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.marker.removeMarker(this.RUMBLING_ENGINE_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.hand.cards.length >= 6) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.RUMBLING_ENGINE_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const cardList = StateUtils.findCardList(state, this);
        const lightningEnergy = cardList.cards.filter(
          (c) => c instanceof EnergyCard && c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.name === "Lightning Energy"
        );
        if (lightningEnergy.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (lightningEnergy.length === 1) {
          lightningEnergy.forEach((card) => MOVE_CARDS(store, state, cardList, player.discard, { cards: [card], sourceCard: this }));
          DRAW_CARDS_UNTIL_CARDS_IN_HAND(player, 6);
          ADD_MARKER(this.RUMBLING_ENGINE_MARKER, player, this);
          ABILITY_USED(player, this);
          return state;
        }
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            cardList,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Lightning Energy" },
            { allowCancel: true, min: 0, max: 1 }
          ),
          (energy2) => {
            if (energy2 === null || energy2.length === 0) {
              return state;
            }
            energy2.forEach((card) => MOVE_CARDS(store, state, cardList, player.discard, { cards: [card], sourceCard: this }));
            DRAW_CARDS_UNTIL_CARDS_IN_HAND(player, 6);
            ADD_MARKER(this.RUMBLING_ENGINE_MARKER, player, this);
            ABILITY_USED(player, this);
          }
        );
      }
      return state;
    }
  };

