  var BlackBeltsTraining = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "PRE";
      this.name = "Black Belt's Training";
      this.fullName = "Black Belt's Training PRE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "96";
      this.regulationMark = "H";
      this.text = "During this turn, attacks used by your Pok\xE9mon do 40 more damage to your opponent's Active Pok\xE9mon ex (before applying Weakness and Resistance).";
      this.BLACK_BELTS_TRAINING_MARKER = "BLACK_BELTS_TRAINING_MARKER";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        supporterTurn == 1;
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        ADD_MARKER(this.BLACK_BELTS_TRAINING_MARKER, player, this);
      }
      if (DEAL_DAMAGE(effect) && HAS_MARKER(this.BLACK_BELTS_TRAINING_MARKER, effect.player, this) && effect.damage > 0) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const oppActiveCard = effect.target.getPokemonCard();
        if (oppActiveCard && oppActiveCard.hasTag("ex" /* POKEMON_ex */)) {
          if (effect.target !== player.active && effect.target !== opponent.active) {
            return state;
          }
          effect.damage += 40;
        }
      }
      if (effect instanceof EndTurnEffect && HAS_MARKER(this.BLACK_BELTS_TRAINING_MARKER, effect.player, this)) {
        REMOVE_MARKER(this.BLACK_BELTS_TRAINING_MARKER, effect.player, this);
      }
      return state;
    }
  };

