  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-obsidian-flames/togekiss.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_game_effects();
  init_game_phase_effects();
  init_prefabs();
  var Togekiss5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Togetic";
      this.cardType = [P];
      this.hp = 150;
      this.weakness = [{ type: M }];
      this.retreat = [];
      this.powers = [{
        name: "Precious Gift",
        powerType: 2 /* ABILITY */,
        text: "Once at the end of your turn (after your attack), you may use this Ability. Draw cards until you have 8 cards in your hand."
      }];
      this.attacks = [{
        name: "Power Cyclone",
        cost: [C, C],
        damage: 110,
        text: "Move an Energy from this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
      }];
      this.set = "OBF";
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "85";
      this.name = "Togekiss";
      this.fullName = "Togekiss OBF";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        let isTogekissInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            isTogekissInPlay = true;
          }
        });
        if (!isTogekissInPlay) {
          return state;
        }
        try {
          const powerEffect = new PowerEffect(player, this.powers[0], this);
          store.reduceEffect(state, powerEffect);
        } catch {
          return state;
        }
        if (player.hand.cards.length >= 8) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            store.log(state, "LOG_PLAYER_USES_ABILITY" /* LOG_PLAYER_USES_ABILITY */, { name: player.name, card: "Togekiss" });
            while (player.hand.cards.length < 8 && player.deck.cards.length > 0) {
              MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
            }
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        const hasEnergy = player.active.cards.some((c) => {
          return c instanceof EnergyCard;
        });
        if (hasBench === false || hasEnergy === false) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.active,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

