  function* useKingsOrder2(next, store, state, effect) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const max = Math.min(slots2.length, 3);
    const hasWaterPokemonInDiscard = player.discard.cards.some((c) => {
      const discardPokemon = player.discard.cards.filter(
        (card) => card.superType === 1 /* POKEMON */
      );
      const waterDiscardPokemon = discardPokemon.filter((card) => pokemonHasCardType(card, 3 /* WATER */));
      return waterDiscardPokemon.length > 0;
    });
    if (!hasWaterPokemonInDiscard || slots2.length === 0) {
      return state;
    }
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
        player.discard,
        { superType: 1 /* POKEMON */, cardType: [3 /* WATER */] },
        { min: 1, max, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      MOVE_CARDS(store, state, player.discard, slots2[index], { cards: [card], sourceCard: effect.source.getPokemonCard() });
      slots2[index].pokemonPlayedTurn = state.turn;
    });
  }
