  var IronLeavesex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["ex" /* POKEMON_ex */, "Future" /* FUTURE */];
      this.cardType = [G];
      this.hp = 220;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Rapid Vernier",
          powerType: 2 /* ABILITY */,
          exemptFromInitialize: true,
          text: "Once during your turn, when you play this Pok\xE9mon from your hand onto your Bench, you may switch this Pok\xE9mon with your Active Pok\xE9mon. If you do, you may move any number of Energy from your Benched Pok\xE9mon to this Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Prism Edge",
          cost: [G, G, C],
          damage: 180,
          text: "During your next turn, this Pok\xE9mon can't attack."
        }
      ];
      this.regulationMark = "H";
      this.set = "TEF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "25";
      this.name = "Iron Leaves ex";
      this.fullName = "Iron Leaves ex TEF";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard == this) {
        const player = effect.player;
        state = store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              try {
                const stub = new PowerEffect(
                  player,
                  {
                    name: "test",
                    powerType: 2 /* ABILITY */,
                    text: ""
                  },
                  this
                );
                store.reduceEffect(state, stub);
              } catch {
                return state;
              }
              const cardList = StateUtils.findCardList(state, this);
              const benchIndex = player.bench.indexOf(cardList);
              player.switchPokemon(player.bench[benchIndex], store, state);
              const blockedFrom = [];
              const blockedTo = [];
              let hasEnergyOnBench = false;
              player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card, target) => {
                if (cardList2 === player.active) {
                  blockedFrom.push(target);
                  return;
                }
                blockedTo.push(target);
                if (cardList2.cards.some((c) => c.superType === 3 /* ENERGY */)) {
                  hasEnergyOnBench = true;
                }
              });
              if (hasEnergyOnBench === false) {
                return state;
              }
              return store.prompt(
                state,
                new MoveEnergyPrompt(
                  player.id,
                  GameMessage.MOVE_ENERGY_CARDS,
                  2 /* BOTTOM_PLAYER */,
                  [2 /* BENCH */, 1 /* ACTIVE */],
                  // Only allow moving to active
                  { superType: 3 /* ENERGY */ },
                  { allowCancel: false, blockedFrom, blockedTo }
                ),
                (transfers) => {
                  if (!transfers) {
                    return;
                  }
                  for (const transfer of transfers) {
                    const target = player.active;
                    const source = StateUtils.getTarget(state, player, transfer.from);
                    transfers.forEach((transfer2) => {
                      MOVE_CARDS(store, state, source, target, { cards: [transfer2.card], sourceCard: this });
                      return state;
                    });
                  }
                }
              );
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        player.active.cannotAttackNextTurnPending = true;
      }
      return state;
    }
  };

