  var Eevee19 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [9 /* COLORLESS */];
      this.hp = 50;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Boosted Evolution",
        text: "As long as this Pok\xE9mon is in the Active Spot, it can evolve during your first turn or the turn you play it.",
        powerType: 2 /* ABILITY */
      }];
      this.attacks = [{
        name: "Reckless Charge",
        cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
        damage: 30,
        text: "This Pok\xE9mon also does 10 damage to itself."
      }];
      this.regulationMark = "H";
      this.set = "SSP";
      this.name = "Eevee";
      this.fullName = "Eevee SSP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "143";
    }
    reduceEffect(store, state, effect) {
      state = ADAPTIVE_EVOLUTION(store, state, effect, this, { requireActive: true });
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const dealDamage = new DealDamageEffect(effect, 10);
        dealDamage.target = player.active;
        return store.reduceEffect(state, dealDamage);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-twilight-masquerade/bloodmoon-ursaluna-ex.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  var BloodmoonUrsalunaex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["ex" /* POKEMON_ex */];
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 260;
      this.weakness = [{ type: F }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Seasoned Skill",
          powerType: 2 /* ABILITY */,
          text: "Blood Moon used by this Pok\xE9mon costs [C] less for each Prize card your opponent has taken."
        }
      ];
      this.attacks = [
        {
          name: "Blood Moon",
          cost: [C, C, C, C, C],
          damage: 240,
          text: "During your next turn, this Pok\xE9mon can't attack."
        }
      ];
      this.regulationMark = "H";
      this.set = "TWM";
      this.setNumber = "141";
      this.cardImage = "assets/cardback.png";
      this.name = "Bloodmoon Ursaluna ex";
      this.fullName = "Bloodmoon Ursaluna ex TWM";
    }
    // public getColorlessReduction(state: State): number {
    //   const player = state.players[state.activePlayer];
    //   const opponent = StateUtils.getOpponent(state, player);
    //   const remainingPrizes = opponent.getPrizeLeft();
    //   return 6 - remainingPrizes;
    // }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect && effect.attack === this.attacks[0]) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const index = effect.cost.indexOf(9 /* COLORLESS */);
        if (index === -1) {
          return state;
        }
        const remainingPrizes = opponent.getPrizeLeft();
        const prizeToColorlessReduction = {
          5: 1,
          4: 2,
          3: 3,
          2: 4,
          1: 5
        };
        const colorlessToRemove = prizeToColorlessReduction[remainingPrizes] || 0;
        for (let i = 0; i < colorlessToRemove; i++) {
          const index2 = effect.cost.indexOf(9 /* COLORLESS */);
          if (index2 !== -1) {
            effect.cost.splice(index2, 1);
          }
        }
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        player.active.cannotAttackNextTurnPending = true;
      }
      return state;
    }
  };

