  var MarniesMorpeko = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Marnie's" /* MARNIES */];
      this.cardType = [D];
      this.hp = 70;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Spiky Wheel",
          cost: [C, C, C],
          damage: 20,
          damageCalculation: "+",
          text: "This attack does 40 more damage for each [D] Energy attached to this Pok\xE9mon."
        }
      ];
      this.regulationMark = "I";
      this.set = "DRI";
      this.setNumber = "137";
      this.cardImage = "assets/cardback.png";
      this.name = "Marnie's Morpeko";
      this.fullName = "Marnie's Morpeko DRI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        let energyCount = 0;
        checkProvidedEnergyEffect.energyMap.forEach((em) => {
          energyCount += em.provides.filter(
            (cardType) => cardType === 7 /* DARK */ || cardType === 0 /* ANY */
          ).length;
        });
        effect.damage += energyCount * 40;
      }
      return state;
    }
  };

