  var Charmander13 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.regulationMark = "G";
      this.cardType = [R];
      this.hp = 70;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Ember",
          // cost: [CardType.FIRE, CardType.FIRE],
          cost: [R, R],
          damage: 40,
          text: "Discard an Energy from this Pok\xE9mon."
        }
      ];
      this.set = "SVP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "47";
      this.name = "Charmander";
      this.fullName = "Charmander SVP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [C],
          { allowCancel: false }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = player.active;
          store.reduceEffect(state, discardEnergy2);
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-scarlet-and-violet-promos/mimikyu-ex.ts
