  var Mimikyuex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.regulationMark = "G";
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 190;
      this.weakness = [{ type: 8 /* METAL */ }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Void Return",
          cost: [5 /* PSYCHIC */],
          damage: 30,
          text: "You may switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Energy Burst",
          cost: [5 /* PSYCHIC */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 30,
          damageCalculation: "x",
          text: "This attack does 30 damage for each Energy attached to both Active Pok\xE9mon."
        }
      ];
      this.set = "SVP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "4";
      this.name = "Mimikyu ex";
      this.fullName = "Mimikyu ex SVP";
      this.voidReturn = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const playerProvidedEnergy = new CheckProvidedEnergyEffect(player);
        store.reduceEffect(state, playerProvidedEnergy);
        const playerEnergyCount = playerProvidedEnergy.energyMap.reduce(
          (left, p) => left + p.provides.length,
          0
        );
        const opponentProvidedEnergy = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, opponentProvidedEnergy);
        const opponentEnergyCount = opponentProvidedEnergy.energyMap.reduce(
          (left, p) => left + p.provides.length,
          0
        );
        effect.damage = (playerEnergyCount + opponentEnergyCount) * 30;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.voidReturn = true;
      }
      if (effect instanceof EndTurnEffect && this.voidReturn == true) {
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        state = store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_SWITCH_POKEMON),
          (wantToUse) => {
            if (wantToUse) {
              return state = store.prompt(
                state,
                new ChoosePokemonPrompt(
                  player.id,
                  GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
                  2 /* BOTTOM_PLAYER */,
                  [2 /* BENCH */],
                  { allowCancel: false }
                ),
                (selected) => {
                  if (!selected || selected.length === 0) {
                    return state;
                  }
                  const target = selected[0];
                  player.switchPokemon(target);
                  this.voidReturn = false;
                }
              );
            }
          }
        );
      }
      return state;
    }
  };

