  var Clavell = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "PAL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "177";
      this.regulationMark = "G";
      this.name = "Clavell";
      this.fullName = "Clavell PAL";
      this.text = "Search your deck for up to 3 Basic Pok\xE9mon with 120 HP or less, reveal them, and put them into your hand. Then, shuffle your deck.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      return player.deck.cards.length > 0;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked = [];
        player.deck.cards.forEach((c, index) => {
          if (c instanceof PokemonCard && c.stage === 2 /* BASIC */ && c.hp <= 120) {
          } else {
            blocked.push(index);
          }
        });
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        let cards = [];
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
            { min: 0, max: 3, allowCancel: false }
          ),
          (selectedCards) => {
            cards = selectedCards || [];
            MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this });
            MOVE_CARDS(store, state, player.supporter, player.discard, {
              cards: [this],
              sourceCard: this
            });
            state = store.prompt(
              state,
              new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
              () => {
              }
            );
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      return state;
    }
  };

