  init_game_error();
  init_game_message();
  init_choose_cards_prompt();
  init_card_list();
  init_prefabs();
  function* playCard231(next, store, state, self, effect) {
    const player = effect.player;
    let cards = [];
    cards = player.hand.cards.filter((c) => c !== self);
    if (cards.length < 2) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let basicEnergies = 0;
    player.discard.cards.forEach((c) => {
      if (c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */) {
        basicEnergies += 1;
      }
    });
    if (basicEnergies === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    const handTemp = new CardList();
    handTemp.cards = player.hand.cards.filter((c) => c !== self);
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        handTemp,
        {},
        { min: 2, max: 2, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    let recovered = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.discard,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { min: 1, max: 4, allowCancel: false }
      ),
      (selected) => {
        recovered = selected || [];
        next();
      }
    );
    if (recovered.length === 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: self });
    MOVE_CARDS(store, state, player.discard, player.hand, { cards: recovered, sourceCard: self });
    return state;
  }
