  function* useScrapPickup(next, store, state, self, effect) {
    const player = effect.player;
    const hasItem = player.discard.cards.some((c) => {
      return c instanceof TrainerCard && c.trainerType === 0 /* ITEM */;
    });
    if (!hasItem) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_HAND,
      player.discard,
      { superType: 2 /* TRAINER */, trainerType: 0 /* ITEM */ },
      { min: 1, max: 1, allowCancel: true }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length > 0) {
      MOVE_CARDS(store, state, player.hand, player.discard, { cards: [self], sourceCard: self });
      MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: self });
    }
    return state;
  }
