  var Hydreigon11 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.cardType = [7 /* DARK */];
      this.hp = 180;
      this.weakness = [{ type: 1 /* GRASS */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.evolvesFrom = "Zweilous";
      this.powers = [{
        name: "Tri Howl",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: " Once during your turn, you may look at the top 3 cards of your deck and attach any number of Energy cards you find there to your Pok\xE9mon in any way you like. Discard the other cards."
      }];
      this.attacks = [{
        name: "Dark Cutter",
        cost: [7 /* DARK */, 7 /* DARK */, 9 /* COLORLESS */],
        damage: 160,
        text: ""
      }];
      this.set = "PAL";
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "140";
      this.name = "Hydreigon";
      this.fullName = "Hydreigon PAL";
      this.TRI_HOWL_MARKER = "TRI_HOWL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.marker.removeMarker(this.TRI_HOWL_MARKER, this);
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.TRI_HOWL_MARKER, this);
        return state;
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const temp = new CardList();
        if (player.marker.hasMarker(this.TRI_HOWL_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        MOVE_CARDS(store, state, player.deck, temp, { count: 3, sourceCard: this });
        const energyCardsDrawn = temp.cards.filter((card) => {
          return card instanceof EnergyCard;
        });
        if (energyCardsDrawn.length == 0) {
          player.marker.addMarker(this.TRI_HOWL_MARKER, this);
          temp.cards.slice(0, 3).forEach((card) => {
            MOVE_CARDS(store, state, temp, player.discard, { cards: [card], sourceCard: this });
          });
        }
        if (energyCardsDrawn.length > 0) {
          return store.prompt(state, new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            temp,
            // Only show drawn energies
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { min: 0, max: energyCardsDrawn.length, allowCancel: false }
          ), (transfers) => {
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.addBoardEffect(0 /* ABILITY_USED */);
              }
            });
            if (transfers.length === 0) {
              temp.cards.slice(0, 3).forEach((card) => {
                MOVE_CARDS(store, state, temp, player.discard, { cards: [card], sourceCard: this });
                player.marker.addMarker(this.TRI_HOWL_MARKER, this);
              });
            }
            if (transfers) {
              for (const transfer of transfers) {
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, temp, target, { cards: [transfer.card], sourceCard: this });
              }
              temp.cards.forEach((card) => {
                MOVE_CARDS(store, state, temp, player.discard, { cards: [card], sourceCard: this });
                player.marker.addMarker(this.TRI_HOWL_MARKER, this);
              });
            }
            return state;
          });
        }
      }
      return state;
    }
  };

