  var Orthworm = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [8 /* METAL */];
      this.hp = 130;
      this.weakness = [{ type: 2 /* FIRE */ }];
      this.resistance = [{ type: 1 /* GRASS */, value: -30 }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon has 3 or more [M] Energy attached, it gets +100 HP.",
        useWhenInPlay: false,
        name: "Nutritional Iron"
      }];
      this.attacks = [{
        name: "Shoot Through",
        cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
        damage: 100,
        text: "This attack also does 30 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.set = "PAL";
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "151";
      this.name = "Orthworm";
      this.fullName = "Orthworm PAL";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const benched = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        const min = Math.min(1, benched);
        const max = Math.min(1, benched);
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { min, max, allowCancel: false }
        ), (selected) => {
          const targets = selected || [];
          targets.forEach((target) => {
            const damageEffect = new PutDamageEffect(effect, 30);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          });
          return state;
        });
      }
      if (effect instanceof CheckHpEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const thisCardList = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            thisCardList.push(cardList);
          }
        });
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, thisCardList[0]);
        state = store.reduceEffect(state, checkProvidedEnergy);
        let metalEnergy = 0;
        for (const energyMap of checkProvidedEnergy.energyMap) {
          const energy2 = energyMap.provides.filter((t) => t === 8 /* METAL */ || t === 0 /* ANY */);
          if (energy2.length > 0) {
            metalEnergy += energy2.length;
          }
        }
        if (metalEnergy >= 3) {
          effect.hp += 100;
        }
      }
      return state;
    }
  };

