  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-paldea-evolved/theraputic-energy.ts
  init_game();
  init_card_types();
  init_energy_card();
  init_check_effects();
  init_play_card_effects();
  init_prefabs();
  var TherapeuticEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [9 /* COLORLESS */];
      this.energyType = 1 /* SPECIAL */;
      this.set = "PAL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "193";
      this.regulationMark = "G";
      this.name = "Therapeutic Energy";
      this.fullName = "Therapeutic Energy PAL";
      this.text = `As long as this card is attached to a Pok\xE9mon, it provides [C] Energy.

The Pok\xE9mon this card is attached to recovers from being Asleep, Confused, or Paralyzed and can't be affected by those Special Conditions.`;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AttachEnergyEffect && effect.target.cards.includes(this)) {
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, effect.player, this, effect.target)) {
          return state;
        }
        const pokemon = effect.target;
        pokemon.removeSpecialCondition(2 /* ASLEEP */);
        pokemon.removeSpecialCondition(0 /* PARALYZED */);
        pokemon.removeSpecialCondition(1 /* CONFUSED */);
      }
      if (effect instanceof CheckTableStateEffect) {
        const cardList = StateUtils.findCardList(state, this);
        if (cardList instanceof PokemonCardList && cardList.cards.includes(this)) {
          if (IS_SPECIAL_ENERGY_BLOCKED(store, state, effect.player, this, cardList)) {
            return state;
          }
          const conditionsToKeep = [3 /* POISONED */, 4 /* BURNED */];
          const hasSpecialCondition = cardList.specialConditions.some((condition) => !conditionsToKeep.includes(condition));
          if (hasSpecialCondition) {
            cardList.specialConditions = cardList.specialConditions.filter((condition) => conditionsToKeep.includes(condition));
          }
        }
      }
      return state;
    }
  };

