  init_prefabs();
  var Garganacl = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Naclstack";
      this.cardType = [F];
      this.hp = 180;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Blessed Salt",
        powerType: 2 /* ABILITY */,
        text: "During Pok\xE9mon Checkup, heal 20 damage from each of your Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Knocking Hammer",
        cost: [F, F],
        damage: 130,
        text: "Discard the top card of your opponent's deck."
      }];
      this.BLESSED_SALT_MARKER = "BLESSED_SALT_MARKER";
      this.set = "PAL";
      this.name = "Garganacl";
      this.fullName = "Garganacl PAL";
      this.setNumber = "123";
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof BetweenTurnsEffect && effect.player.marker.hasMarker(this.BLESSED_SALT_MARKER, this)) {
        if (state.phase === 6 /* BETWEEN_TURNS */) {
          const player = effect.player;
          try {
            const stub = new PowerEffect(player, {
              name: "test",
              powerType: 2 /* ABILITY */,
              text: ""
            }, this);
            store.reduceEffect(state, stub);
          } catch {
            return state;
          }
          let numOfGargs = 0;
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
            const pokemon = cardList.getPokemonCard();
            if (!!pokemon && pokemon.name === "Garganacl" && pokemon.powers.map((p) => p.name).includes(this.powers[0].name)) {
              numOfGargs += 1;
            }
          });
          console.log("Number of Garganacls: " + numOfGargs + " --------------------------");
          let testVar = 0;
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
            testVar++;
            const healEffect = new HealEffect(player, cardList, 20 * numOfGargs);
            store.reduceEffect(state, healEffect);
          });
          console.log(testVar);
          player.marker.removeMarker(this.BLESSED_SALT_MARKER, this);
          return state;
        }
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        let numOfGargs = 0;
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          const pokemon = cardList.getPokemonCard();
          if (!!pokemon && pokemon.name === "Garganacl" && pokemon.powers.map((p) => p.name).includes(this.powers[0].name)) {
            numOfGargs += 1;
          }
        });
        if (numOfGargs > 0 && !player.marker.hasMarker(this.BLESSED_SALT_MARKER)) {
          player.marker.addMarker(this.BLESSED_SALT_MARKER, this);
        }
        numOfGargs = 0;
        const opponent = StateUtils.getOpponent(state, effect.player);
        opponent.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          const pokemon = cardList.getPokemonCard();
          if (!!pokemon && pokemon.name === "Garganacl" && pokemon.powers.map((p) => p.name).includes(this.powers[0].name)) {
            numOfGargs += 1;
          }
        });
        if (numOfGargs > 0 && !opponent.marker.hasMarker(this.BLESSED_SALT_MARKER)) {
          opponent.marker.addMarker(this.BLESSED_SALT_MARKER, this);
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        MOVE_CARDS(store, state, opponent.deck, opponent.discard, { count: 1, sourceCard: this, sourceEffect: this.attacks[0] });
      }
      return state;
    }
  };

