  var CalamitousWasteland = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "PAL";
      this.regulationMark = "G";
      this.name = "Calamitous Wasteland";
      this.fullName = "Calamitous Wasteland PAL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "175";
      this.text = "The Retreat Cost of each Basic non-[F] Pok\xE9mon in play (both yours and your opponent's) is [C] more.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, effect.player, effect.player.active, this)) {
          return state;
        }
        if (player.active.isStage(2 /* BASIC */)) {
          const checkPokemonTypeEffect = new CheckPokemonTypeEffect(player.active);
          store.reduceEffect(state, checkPokemonTypeEffect);
          if (!checkPokemonTypeEffect.cardTypes.includes(6 /* FIGHTING */)) {
            effect.cost.push(9 /* COLORLESS */);
          }
        }
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

