  var CalamitousSnowyMountain = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "174";
      this._trainerType = 2 /* STADIUM */;
      this.set = "PAL";
      this.name = "Calamitous Snowy Mountain";
      this.fullName = "Calamitous Snowy Mountain PAL";
      this.text = "Whenever any player attaches an Energy card from their hand to 1 of their Basic non-[W] Pok\xE9mon, put 2 damage counters on that Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      if (effect instanceof AttachEnergyEffect && StateUtils.getStadiumCard(state) === this) {
        const owner = StateUtils.findOwner(state, effect.target);
        const checkPokemonTypeEffect = new CheckPokemonTypeEffect(effect.target);
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, effect.target, this)) {
          return state;
        }
        store.reduceEffect(state, checkPokemonTypeEffect);
        if (!effect.target.isStage(2 /* BASIC */) || checkPokemonTypeEffect.cardTypes.includes(3 /* WATER */)) {
          return state;
        }
        store.log(state, "LOG_PLAYER_PLACES_DAMAGE_COUNTERS" /* LOG_PLAYER_PLACES_DAMAGE_COUNTERS */, {
          name: owner.name,
          damage: 20,
          target: effect.target.getPokemonCard().name,
          effect: this.name
        });
        effect.target.damage += 20;
      }
      return state;
    }
  };

