  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-paldea-evolved/gothitelle.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Gothitelle7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Gothorita";
      this.cardType = [P];
      this.hp = 150;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Read the Stars",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn, you may look at the top 2 cards of your opponent's deck and put 1 of them back. Put the other card on the bottom of their deck."
      }];
      this.attacks = [
        {
          name: "Psych Out",
          cost: [P, C],
          damage: 120,
          text: "Discard a random card from your opponent's hand."
        }
      ];
      this.set = "PAL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "92";
      this.name = "Gothitelle";
      this.fullName = "Gothitelle PAL";
      this.READ_THE_STARS_MARKER = "READ_THE_STARS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.deck.cards.length < 2) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (HAS_MARKER(this.READ_THE_STARS_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        let cards = [];
        const deckTop = new CardList();
        MOVE_CARDS(store, state, opponent.deck, deckTop, { count: 2, sourceCard: this });
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ON_BOTTOM,
          deckTop,
          {},
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          cards = selected || [];
          ABILITY_USED(player, this);
          ADD_MARKER(this.READ_THE_STARS_MARKER, player, this);
          MOVE_CARDS(store, state, deckTop, opponent.deck, { cards, sourceCard: this });
          deckTop.moveToTopOfDestination(opponent.deck);
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        if (opponent.hand.cards.length === 0) {
          return state;
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          opponent.hand,
          {},
          { allowCancel: false, min: 1, max: 1, isSecret: true }
        ), (cards) => {
          cards = cards || [];
          MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards, sourceCard: this });
          store.prompt(state, new ShowCardsPrompt(
            player.id,
            GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
            cards
          ), () => []);
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.READ_THE_STARS_MARKER, this);
      return state;
    }
  };

