  var Finizen = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this.stage = 2 /* BASIC */;
      this.cardType = [3 /* WATER */];
      this.hp = 50;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Valiant Evolution",
          cost: [3 /* WATER */],
          damage: 0,
          text: "Switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon. If you do, search your deck for a card that evolves from this Pok\xE9mon and put it onto this Pok\xE9mon to evolve it. Then, shuffle your deck."
        },
        {
          name: "Razor Fin",
          cost: [3 /* WATER */],
          damage: 10,
          text: ""
        }
      ];
      this.set = "OBF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "60";
      this.name = "Finizen";
      this.fullName = "Finizen OBF";
      this.usedSpinTurn = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedSpinTurn = true;
      }
      if (effect instanceof AfterAttackEffect && this.usedSpinTurn === true) {
        const player = effect.player;
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        SWITCH_ACTIVE_WITH_BENCHED(store, state, effect.player);
        let cards = [];
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_EVOLVE,
          player.deck,
          { superType: 1 /* POKEMON */, evolvesFrom: "Finizen" },
          { min: 0, max: 1, allowCancel: false }
        ), (selected) => {
          cards = selected || [];
          let finizensNewBenchIndex = -1;
          player.bench.forEach((benchSpot, index) => {
            if (benchSpot.cards.includes(this)) {
              finizensNewBenchIndex = index;
            }
          });
          if (!selected || selected.length === 0) {
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
          MOVE_CARDS(store, state, player.deck, player.bench[finizensNewBenchIndex], { cards: [cards[0]], sourceCard: this });
          const evolveEffect = new EvolveEffect(player, player.bench[finizensNewBenchIndex], cards[0]);
          store.reduceEffect(state, evolveEffect);
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      if (effect instanceof EndTurnEffect && this.usedSpinTurn) {
        this.usedSpinTurn = false;
      }
      return state;
    }
  };

