  var Pidgeotex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this._tags = ["ex" /* POKEMON_ex */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Pidgeotto";
      this.cardType = [9 /* COLORLESS */];
      this.hp = 280;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.resistance = [{ type: 6 /* FIGHTING */, value: -30 }];
      this.retreat = [];
      this.powers = [
        {
          name: "Quick Search",
          powerType: 2 /* ABILITY */,
          useWhenInPlay: true,
          text: "Once during your turn, you may search your deck for a card and put it into your hand. Then, shuffle your deck. You can't use more than 1 Quick Search Ability each turn. "
        }
      ];
      this.attacks = [
        {
          name: "Blustery Wind",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 120,
          text: "You may discard a Stadium in play."
        }
      ];
      this.set = "OBF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "164";
      this.name = "Pidgeot ex";
      this.fullName = "Pidgeot ex OBF";
      this.QUICK_SEARCH_MARKER = "QUICK_SEARCH_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.marker.removeMarker(this.QUICK_SEARCH_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.QUICK_SEARCH_MARKER)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        player.marker.addMarker(this.QUICK_SEARCH_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            {},
            { min: 1, max: 1, allowCancel: false }
          ),
          (cards) => {
            MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this });
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const stadiumCard = StateUtils.getStadiumCard(state);
        if (stadiumCard !== void 0) {
          state = store.prompt(
            state,
            new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
            (wantToUse) => {
              if (wantToUse) {
                DISCARD_A_STADIUM_CARD_IN_PLAY(state);
              }
              return state;
            }
          );
        }
        return state;
      }
      return state;
    }
  };

