  var Poppy = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "OBF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "193";
      this.name = "Poppy";
      this.fullName = "Poppy OBF";
      this.text = "Move up to 2 Energy from 1 of your Pok\xE9mon to another of your Pok\xE9mon.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      let hasEnergy = false;
      let pokemonCount = 0;
      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
        pokemonCount += 1;
        const energyAttached = cardList.cards.some((c) => c.superType === 3 /* ENERGY */);
        hasEnergy = hasEnergy || energyAttached;
      });
      if (!hasEnergy || pokemonCount <= 1) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        let hasEnergy = false;
        let pokemonCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          pokemonCount += 1;
          const energyAttached = cardList.cards.some((c) => {
            return c instanceof EnergyCard;
          });
          hasEnergy = hasEnergy || energyAttached;
        });
        if (!hasEnergy || pokemonCount <= 1) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        return store.prompt(
          state,
          new MoveEnergyPrompt(
            effect.player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */ },
            { min: 0, max: 2, allowCancel: false }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      return state;
    }
  };

