  var Geeta = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "OBF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "188";
      this.name = "Geeta";
      this.fullName = "Geeta OBF";
      this.text = "Search your deck for up to 2 Basic Energy cards and attach them to 1 of your Pok\xE9mon. Then, shuffle your deck. During this turn, your Pok\xE9mon can't attack. (This includes Pok\xE9mon that come into play this turn.)";
      this.GEETA_MARKER = "GEETA_MARKER";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        let cards = [];
        store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min: 0, max: 2, allowCancel: false }
          ),
          (selected) => {
            cards = selected || [];
            if (cards.length > 0) {
              store.prompt(
                state,
                new ChoosePokemonPrompt(
                  player.id,
                  GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
                  2 /* BOTTOM_PLAYER */,
                  [1 /* ACTIVE */, 2 /* BENCH */],
                  { allowCancel: true }
                ),
                (targets) => {
                  if (!targets || targets.length === 0) {
                    MOVE_CARDS(store, state, player.supporter, player.discard, { sourceCard: this });
                    return;
                  }
                  const target = targets[0];
                  MOVE_CARDS(store, state, player.deck, target, { cards, sourceCard: this });
                  player.marker.addMarker(this.GEETA_MARKER, this);
                  MOVE_CARDS(store, state, player.supporter, player.discard, { sourceCard: this });
                }
              );
            }
          }
        );
        return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
          player.deck.applyOrder(order);
        });
      }
      if (effect instanceof AttackEffect && effect.player.marker.hasMarker(this.GEETA_MARKER, this)) {
        throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.GEETA_MARKER, this)) {
        effect.player.marker.removeMarker(this.GEETA_MARKER, this);
      }
      return state;
    }
  };

