  function* playCard232(next, store, state, self, effect) {
    const player = effect.player;
    if (!player.marker.hasMarker(self.LETTER_OF_ENCOURAGEMENT_MARKER)) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let cards = [];
    return store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { min: 0, max: 3, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
        MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
        return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
          player.deck.applyOrder(order);
        });
      }
    );
  }
  var LetterOfEncouragement = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "OBF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "189";
      this.regulationMark = "G";
      this.name = "Letter of Encouragement";
      this.fullName = "Letter of Encouragement OBF";
      this.text = `You can use this card only if any of your Pok\xE9mon were Knocked Out during your opponent's last turn.

Search your deck for up to 3 Basic Energy cards, reveal them, and put them into your hand. Then, shuffle your deck.`;
      this.LETTER_OF_ENCOURAGEMENT_MARKER = "LETTER_OF_ENCOURAGEMENT_MARKER";
    }
    canPlay(store, state, player) {
      if (player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard232(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const duringTurn = [2 /* PLAYER_TURN */, 3 /* ATTACK */].includes(state.phase);
        if (!duringTurn || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) {
          effect.player.marker.addMarker(this.LETTER_OF_ENCOURAGEMENT_MARKER, this);
        }
        return state;
      }
      REMOVE_OPPONENT_LAST_TURN_MARKER_AT_END_OF_TURN(
        effect,
        this.LETTER_OF_ENCOURAGEMENT_MARKER,
        this
      );
      return state;
    }
  };

