  var Blastoiseex2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["ex" /* POKEMON_ex */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Wartortle";
      this.cardType = [W];
      this.hp = 330;
      this.weakness = [{ type: L }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Solid Shell",
          powerType: 2 /* ABILITY */,
          text: "This Pok\xE9mon takes 30 less damage from attacks (after applying Weakness and Resistance)."
        }
      ];
      this.attacks = [
        {
          name: "Twin Cannons",
          cost: [W, W],
          damage: 140,
          damageCalculation: "x",
          text: "Discard up to 2 Basic [W] Energies from your hand. This attack does 140 damage for each card you discarded in this way."
        }
      ];
      this.regulationMark = "G";
      this.set = "MEW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "9";
      this.name = "Blastoise ex";
      this.fullName = "Blastoise ex MEW";
    }
    // Implement power
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c.superType === 3 /* ENERGY */;
        });
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            { superType: 3 /* ENERGY */ },
            { allowCancel: true, min: 1, max: 2 }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length === 0) {
              return;
            }
            const damage = cards.length * 140;
            effect.damage = damage;
            MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
            return state;
          }
        );
      }
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.damage = Math.max(0, effect.damage - 30);
      }
      return state;
    }
  };

