  var Chansey12 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 110;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Lucky Bonus",
        powerType: 2 /* ABILITY */,
        exemptFromAbilityLock: true,
        text: "If you took this Pok\xE9mon as a face-down Prize card during your turn and your Bench isn't full, before you put it into your hand, you may put it onto your Bench. If you put this Pok\xE9mon onto your Bench in this way, flip a coin. If heads, take 1 more Prize card."
      }];
      this.attacks = [{
        name: "Gentle Slap",
        cost: [C, C, C],
        damage: 70,
        text: ""
      }];
      this.set = "MEW";
      this.setNumber = "113";
      this.cardImage = "assets/cardback.png";
      this.name = "Chansey";
      this.fullName = "Chansey MEW";
      this.abilityUsed = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DrawPrizesEffect) {
        const generator = this.handlePrizeEffect(
          () => generator.next(),
          store,
          state,
          effect
        );
        return generator.next().value;
      }
      return state;
    }
    *handlePrizeEffect(next, store, state, effect) {
      const player = effect.player;
      const prizeCard = effect.prizes.find((cardList) => cardList.cards.includes(this));
      if (!prizeCard || GET_PLAYER_BENCH_SLOTS(player).length === 0 || !prizeCard.isSecret || effect.destination !== player.hand) {
        return state;
      }
      if (this.abilityUsed) {
        return state;
      }
      if (IS_ABILITY_BLOCKED(store, state, player, this)) {
        return state;
      }
      effect.preventDefault = true;
      let wantToUse = false;
      yield CONFIRMATION_PROMPT(store, state, player, (result) => {
        wantToUse = result;
        next();
      }, GameMessage.WANT_TO_USE_ABILITY_FROM_PRIZES);
      const prizeIndex = player.prizes.findIndex((prize) => prize.cards.includes(this));
      const fallback = (prizeIndex2) => {
        if (prizeIndex2 !== -1) {
          TAKE_SPECIFIC_PRIZES(store, state, player, [player.prizes[prizeIndex2]], { skipReduce: true });
        }
        return;
      };
      if (!wantToUse) {
        effect.preventDefault = false;
        fallback(prizeIndex);
        return state;
      }
      const emptyBenchSlots = GET_PLAYER_BENCH_SLOTS(player);
      if (emptyBenchSlots.length === 0) {
        effect.preventDefault = false;
        fallback(prizeIndex);
        return state;
      }
      this.abilityUsed = true;
      player.prizesTaken += 1;
      const targetSlot = emptyBenchSlots[0];
      for (const [index, prize] of player.prizes.entries()) {
        if (prize.cards.includes(this)) {
          MOVE_CARDS(store, state, player.prizes[index], targetSlot, { sourceCard: this });
          targetSlot.pokemonPlayedTurn = state.turn;
          break;
        }
      }
      const coinFlip = new CoinFlipEffect(player);
      store.reduceEffect(state, coinFlip);
      if (coinFlip.result === false) {
        return state;
      }
      yield TAKE_X_PRIZES(store, state, player, 1, {
        promptOptions: {
          blocked: effect.prizes.map((p) => player.prizes.indexOf(p))
        }
      }, () => next());
      return state;
    }
  };

