  var Ditto8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [9 /* COLORLESS */];
      this.hp = 60;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Transformative Start",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your first turn, if this Pok\xE9mon is in the Active Spot, you may search your deck and choose a Basic Pok\xE9mon you find there, except any Ditto. If you do, discard this Pok\xE9mon and all attached cards, and put the chosen Pok\xE9mon in its place. Then, shuffle your deck."
      }];
      this.attacks = [{
        name: "Splup",
        cost: [9 /* COLORLESS */],
        damage: 10,
        text: ""
      }];
      this.set = "MEW";
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "132";
      this.name = "Ditto";
      this.fullName = "Ditto MEW";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const turn = state.turn;
        if (player.active.cards[0] !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && card.name == "Ditto") {
            blocked.push(index);
          }
        });
        if (turn > 2) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        } else {
          let cards = [];
          return store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
              player.deck,
              { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
              { min: 0, max: 1, allowCancel: true, blocked }
            ),
            (selectedCards) => {
              cards = selectedCards || [];
              cards.forEach((card) => {
                effect.player.removePokemonEffects(player.active);
                MOVE_CARDS(store, state, player.active, player.discard, { sourceCard: this });
                MOVE_CARDS(store, state, player.deck, player.active, { cards: [card], sourceCard: this });
                player.active.pokemonPlayedTurn = state.turn;
                effect.player.removePokemonEffects(player.active);
              });
              return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                player.deck.applyOrder(order);
              });
            }
          );
        }
      }
      return state;
    }
  };

