  var Grabber = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this._trainerType = 0 /* ITEM */;
      this.set = "MEW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "162";
      this.name = "Grabber";
      this.fullName = "Grabber MEW";
      this.text = "Your opponent reveals their hand, and you put a Pok\xE9mon you find there on the bottom of their deck.";
    }
    canPlay(store, state, player) {
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const deckBottom = new CardList();
        effect.preventDefault = true;
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DECK,
            opponent.hand,
            { superType: 1 /* POKEMON */ },
            { allowCancel: false, min: 0, max: 1 }
          ),
          (selectedCard) => {
            const selected = selectedCard || [];
            if (selectedCard === null || selected.length === 0) {
              MOVE_CARDS(store, state, player.supporter, player.discard, {
                cards: [this],
                sourceCard: this
              });
              return;
            }
            MOVE_CARDS(store, state, opponent.hand, deckBottom, {
              cards: [selected[0]],
              sourceCard: this
            });
            MOVE_CARDS(store, state, deckBottom, opponent.deck, { sourceCard: this });
            MOVE_CARDS(store, state, player.supporter, player.discard, {
              cards: [this],
              sourceCard: this
            });
          }
        );
      }
      return state;
    }
  };

