  var Haunter14 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Gastly";
      this.hp = 80;
      this.cardType = [P];
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Spirit Return",
        powerType: 2 /* ABILITY */,
        text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may put a Supporter card from your opponent's discard pile into their hand."
      }];
      this.attacks = [{
        name: "Mumble",
        cost: [P, C],
        damage: 30,
        text: ""
      }];
      this.regulationMark = "G";
      this.set = "MEW";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "93";
      this.name = "Haunter";
      this.fullName = "Haunter MEW";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EvolveEffect && effect.pokemonCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasValidCard = opponent.discard.cards.some((c) => {
          return c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */;
        });
        if (!hasValidCard) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (wantToUse) {
            const blocked = [];
            opponent.discard.cards.forEach((c, index) => {
              if (c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */) {
                return;
              } else {
                blocked.push(index);
              }
            });
            return store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_HAND,
              opponent.discard,
              { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
              { min: 1, max: 1, allowCancel: false, blocked }
            ), (selected) => {
              MOVE_CARDS(store, state, opponent.discard, opponent.hand, { cards: selected, sourceCard: this, sourceEffect: this.powers[0] });
              return state;
            });
          }
        });
      }
      return state;
    }
  };

