  var Hitmonchan7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 120;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.powers = [{
        name: "Counterattack",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon is in the Active Spot and is damaged by an attack from your opponent's Pok\xE9mon(even if this Pok\xE9mon is Knocked Out), put 3 damage counters on the Attacking Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Excited Punch",
        cost: [F, F],
        damage: 60,
        text: "During your next turn, this Pok\xE9mon's Excited Punch attack does 60 more damage (before applying Weakness and Resistance)."
      }];
      this.set = "MEW";
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "107";
      this.name = "Hitmonchan";
      this.fullName = "Hitmonchan MEW";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.getPokemonCard() === this && state.phase === 3 /* ATTACK */) {
        const player = StateUtils.findOwner(state, effect.target);
        const opponent = effect.player;
        if (player === opponent || player.active !== effect.target)
          return state;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const damageEffect = new EffectOfAbilityEffect(player, this.powers[0], this, effect.source);
        store.reduceEffect(state, damageEffect);
        if (damageEffect.target) {
          damageEffect.target.damage += 30;
        }
      }
      NEXT_TURN_ATTACK_BONUS(effect, {
        attack: this.attacks[0],
        source: this,
        bonusDamage: 60
      });
      return state;
    }
  };

