  var Hitmonlee6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [6 /* FIGHTING */];
      this.hp = 120;
      this.weakness = [{ type: 5 /* PSYCHIC */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Twister Kick",
          cost: [6 /* FIGHTING */],
          damage: 0,
          text: "This attack does 10 damage to each of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.) Switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Low Kick",
          cost: [6 /* FIGHTING */, 6 /* FIGHTING */, 6 /* FIGHTING */],
          damage: 100,
          text: ""
        }
      ];
      this.set = "MEW";
      this.setNumber = "106";
      this.cardImage = "assets/cardback.png";
      this.regulationMark = "H";
      this.name = "Hitmonlee";
      this.fullName = "Hitmonlee MEW";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          let kickDamage = 10;
          if (cardList === opponent.active) {
            const applyWeakness = new ApplyWeaknessEffect(effect, kickDamage);
            store.reduceEffect(state, applyWeakness);
            kickDamage = applyWeakness.damage;
          }
          const damageEffect = new PutDamageEffect(effect, kickDamage);
          damageEffect.target = cardList;
          store.reduceEffect(state, damageEffect);
        });
        const hasBenched = player.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_SWITCH,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { allowCancel: false }
        ), (result) => {
          const cardList = result[0];
          player.switchPokemon(cardList);
        });
      }
      return state;
    }
  };

