  var Moltres11 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [2 /* FIRE */];
      this.hp = 120;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Flare FLoat",
        powerType: 2 /* ABILITY */,
        text: " If this Pok\xE9mon has any [R] Energy attached, it has no Retreat Cost. "
      }];
      this.attacks = [{
        name: "Blazing Flight",
        cost: [2 /* FIRE */, 2 /* FIRE */, 2 /* FIRE */],
        damage: 0,
        text: " Discard 2 [R] Energy from this Pok\xE9mon. This attack does 120 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.) "
      }];
      this.set = "MEW";
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "146";
      this.name = "Moltres";
      this.fullName = "Moltres MEW";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
            state = store.reduceEffect(state, checkProvidedEnergy);
            checkProvidedEnergy.energyMap.forEach((energy2) => {
              if (energy2.provides.includes(2 /* FIRE */)) {
                effect.cost = [];
                return state;
              }
              if (energy2.provides.includes(0 /* ANY */)) {
                effect.cost = [];
                return state;
              }
            });
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(state, new ChooseEnergyPrompt(
          player.id,
          GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
          checkProvidedEnergy.energyMap,
          [2 /* FIRE */, 2 /* FIRE */],
          { allowCancel: false }
        ), (energy2) => {
          const cards = (energy2 || []).map((e) => e.card);
          const discardEnergy2 = new DiscardCardsEffect(effect, cards);
          discardEnergy2.target = player.active;
          store.reduceEffect(state, discardEnergy2);
        });
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false }
        ), (selected) => {
          const targets = selected || [];
          targets.forEach((target) => {
            const damageEffect = new DealDamageEffect(effect, 120);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          });
          return state;
        });
      }
      return state;
    }
  };

