  var Weezing10 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Koffing";
      this.cardType = [D];
      this.hp = 110;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Let's Have a Blast",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon is in the Active Spot and is Knocked Out by damage from an attack from your opponent's Pok\xE9mon, flip a coin. If heads, the Attacking Pok\xE9mon is Knocked Out."
      }];
      this.attacks = [{
        name: "Spinning Fumes",
        cost: [C, C],
        damage: 50,
        text: "This attack also does 10 damage to each of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.set = "MEW";
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "110";
      this.name = "Weezing";
      this.fullName = "Weezing MEW";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target.getPokemonCard() === this && effect.player.marker.hasMarker(effect.player.DAMAGE_DEALT_MARKER)) {
        const player = StateUtils.findOwner(state, effect.target);
        const opponent = StateUtils.getOpponent(state, player);
        if (state.phase !== 3 /* ATTACK */ || player.active.getPokemonCard() !== this || state.players[state.activePlayer] !== opponent || IS_ABILITY_BLOCKED(store, state, player, this))
          return state;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (!result) {
            return;
          }
          const ko = new KnockOutEffect(opponent, opponent.active);
          store.reduceEffect(state, ko);
          return TAKE_X_PRIZES(store, state, player, ko.prizeCount);
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        const benched = opponent.bench.filter((b) => b.cards.length > 0);
        benched.forEach((target) => {
          const damageEffect = new PutDamageEffect(effect, 10);
          damageEffect.target = target;
          store.reduceEffect(state, damageEffect);
        });
      }
      return state;
    }
  };

