  function* playCard236(next, store, state, self, effect) {
    const player = effect.player;
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    if (!player.marker.hasMarker(self.MELA_MARKER)) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const hasEnergyInDiscard = player.discard.cards.some((c) => {
      return c instanceof EnergyCard && c.name === "Fire Energy";
    });
    if (!hasEnergyInDiscard) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const blocked = [];
    player.discard.cards.forEach((c, index) => {
      const isBasicEnergy = c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(2 /* FIRE */);
      if (!isBasicEnergy) {
        blocked.push(index);
      }
    });
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    return store.prompt(
      state,
      new AttachEnergyPrompt(
        player.id,
        GameMessage.ATTACH_ENERGY_TO_BENCH,
        player.discard,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
        { allowCancel: false, min: 1, max: 1 }
      ),
      (transfers) => {
        if (transfers && transfers.length > 0) {
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, {
              cards: [transfer.card],
              sourceCard: self
            });
          }
        }
        while (player.hand.cards.length < 6) {
          if (player.deck.cards.length === 0) {
            break;
          }
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: self });
        }
        return state;
      }
    );
  }
  var Mela = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "PAR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "167";
      this.regulationMark = "G";
      this.name = "Mela";
      this.fullName = "Mela PAR";
      this.text = `You can use this card only if any of your Pok\xE9mon were Knocked Out during your opponent's last turn.

Attach a Basic [R] Energy card from your discard pile to 1 of your Pok\xE9mon. If you do, draw cards until you have 6 cards in your hand.`;
      this.MELA_MARKER = "MELA_MARKER";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (!player.marker.hasMarker(this.MELA_MARKER)) {
        return false;
      }
      if (player.deck.cards.length === 0) {
        return false;
      }
      const hasFireEnergy = player.discard.cards.some(
        (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(2 /* FIRE */)
      );
      if (!hasFireEnergy) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard236(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const duringTurn = [2 /* PLAYER_TURN */, 3 /* ATTACK */].includes(state.phase);
        if (!duringTurn || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) {
          effect.player.marker.addMarker(this.MELA_MARKER, this);
        }
        return state;
      }
      REMOVE_OPPONENT_LAST_TURN_MARKER_AT_END_OF_TURN(effect, this.MELA_MARKER, this);
      return state;
    }
  };

