  var SandyShocksex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["ex" /* POKEMON_ex */, "Ancient" /* ANCIENT */];
      this.cardType = [F];
      this.hp = 220;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Magnetic Absorption",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, if your opponent has 4 or fewer Prize cards remaining, you may attach a Basic [F] Energy card from your discard pile to this Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Earthen Spike",
          cost: [F, F, C],
          damage: 200,
          text: "During your next turn, this Pok\xE9mon can't attack."
        }
      ];
      this.regulationMark = "G";
      this.set = "PAR";
      this.setNumber = "108";
      this.cardImage = "assets/cardback.png";
      this.name = "Sandy Shocks ex";
      this.fullName = "Sandy Shocks ex PAR";
      this.MAGNETIC_ABSORPTION_MARKER = "MAGNETIC_ABSORPTION_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.MAGNETIC_ABSORPTION_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.MAGNETIC_ABSORPTION_MARKER, this)) {
        effect.player.marker.removeMarker(this.MAGNETIC_ABSORPTION_MARKER, this);
        console.log("marker cleared");
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_POKEMON_CANNOT_ATTACK_NEXT_TURN(effect.player);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const prizes = opponent.getPrizeLeft();
        if (player.marker.hasMarker(this.MAGNETIC_ABSORPTION_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (prizes > 4) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.name == "Fighting Energy";
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fighting Energy" },
            { allowCancel: false, min: 1, max: 1 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return state;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
              player.marker.addMarker(this.MAGNETIC_ABSORPTION_MARKER, this);
            }
            return state;
          }
        );
        return state;
      }
      return state;
    }
  };

