  var Wimpod6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 70;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Sneaky Snacking",
        cost: [C],
        damage: 0,
        text: "Flip a coin. If heads, discard a random card from your opponent's hand."
      }, {
        name: "Ram",
        cost: [W, C, C],
        damage: 30,
        text: ""
      }];
      this.set = "PAR";
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "48";
      this.name = "Wimpod";
      this.fullName = "Wimpod PAR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.hand.cards.length === 0) {
          return state;
        }
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === false) {
            return state;
          }
        });
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          opponent.hand,
          {},
          { allowCancel: false, min: 1, max: 1, isSecret: true }
        ), (cards) => {
          cards = cards || [];
          MOVE_CARDS(store, state, opponent.hand, opponent.discard, { cards, sourceCard: this });
        });
      }
      return state;
    }
  };

