  var Zacian4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [M];
      this.hp = 120;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Iron Roar",
          cost: [M],
          damage: 30,
          text: "Attach a Basic [M] Energy card from your discard pile to 1 of your Benched Pokemon."
        },
        {
          name: "Brave Blade",
          cost: [M, M, C],
          damage: 130,
          text: "During your next turn, this Pok\xE9mon can't attack."
        }
      ];
      this.regulationMark = "G";
      this.set = "PAR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "136";
      this.name = "Zacian";
      this.fullName = "Zacian PAR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.provides.includes(M);
        });
        if (!hasEnergyInDiscard) {
          return state;
        }
        const blocked = [];
        player.discard.cards.forEach((card, index) => {
          if (card.superType === 3 /* ENERGY */ && !card.provides.includes(M)) {
            blocked.push(index);
          }
        });
        state = store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.discard,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { allowCancel: false, min: 1, max: 1, blocked }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
          }
        });
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        player.active.cannotAttackNextTurnPending = true;
      }
      return state;
    }
  };

