  var Atticus = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "77";
      this.set = "PAF";
      this.name = "Atticus";
      this.fullName = "Atticus PAF";
      this.text = "You can use this card only if your opponent's Active Pok\xE9mon is Poisoned.Shuffle your hand into your deck, then draw 7 cards.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      const opponent = StateUtils.getOpponent(state, player);
      if (!opponent.active.specialConditions.includes(3 /* POISONED */)) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!opponent.active.specialConditions.includes(3 /* POISONED */)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        return SHUFFLE_HAND_INTO_DECK_THEN_DRAW(store, state, player, {
          excludeCard: this,
          drawCount: 7
        });
      }
      return state;
    }
  };

