  var StudentsInPaldea = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "85";
      this.set = "PAF";
      this.name = "Paldean Student";
      this.fullName = "Paldean Student PAF";
      this.text = "Search your deck for a Pok\xE9mon that doesn't have a Rule Box, reveal it, and put it into your hand. For each other Students in Paldea in your discard pile, you may search your deck for another Pok\xE9mon that doesn't have a Rule Box. Then, shuffle your deck. (Pok\xE9mon ex, Pok\xE9mon V, etc. have Rule Boxes.)";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        const cardsInDiscard = effect.player.discard.cards.filter(
          (c) => c.name === "Paldean Student"
        );
        const cardsToTake = 1 + cardsInDiscard.length;
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (card.hasRuleBox()) {
            blocked.push(index);
          }
        });
        let cards = [];
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            { superType: 1 /* POKEMON */ },
            { min: 0, max: cardsToTake, allowCancel: false, blocked }
          ),
          (selected) => {
            cards = selected || [];
            MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this });
            state = store.prompt(
              state,
              new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
              () => {
              }
            );
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      return state;
    }
  };

