  var Charmeleon13 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Charmander";
      this.cardType = [2 /* FIRE */];
      this.hp = 90;
      this.weakness = [{ type: 3 /* WATER */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Flare Veil",
        powerType: 2 /* ABILITY */,
        text: "Prevent all effects of attacks used by your opponent's Pok\xE9mon done to this Pok\xE9mon. (Damage is not an effect.)"
      }];
      this.attacks = [
        {
          name: "Combustion",
          cost: [2 /* FIRE */, 2 /* FIRE */],
          damage: 50,
          text: ""
        }
      ];
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "8";
      this.set = "PAF";
      this.name = "Charmeleon";
      this.fullName = "Charmeleon PAF";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AbstractAttackEffect && effect.target.getPokemonCard() === this) {
        const pokemonCard = effect.target.getPokemonCard();
        const sourceCard = effect.source.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (sourceCard) {
          try {
            const player = StateUtils.findOwner(state, effect.target);
            const stub = new PowerEffect(player, {
              name: "test",
              powerType: 2 /* ABILITY */,
              text: ""
            }, this);
            store.reduceEffect(state, stub);
          } catch {
            return state;
          }
          if (effect instanceof ApplyWeaknessEffect) {
            return state;
          }
          if (effect instanceof PutDamageEffect) {
            return state;
          }
          if (effect instanceof DealDamageEffect) {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      return state;
    }
  };

