  function* useNightGate(next, store, state, effect) {
    const player = effect.player;
    const hasBench = player.bench.some((b) => b.cards.length > 0);
    if (hasBench === false) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let targets = [];
    yield store.prompt(state, new ChoosePokemonPrompt(
      player.id,
      GameMessage.CHOOSE_POKEMON_TO_SWITCH,
      2 /* BOTTOM_PLAYER */,
      [2 /* BENCH */],
      { allowCancel: false }
    ), (results) => {
      targets = results || [];
      next();
    });
    if (targets.length > 0) {
      player.active.clearEffects();
      player.switchPokemon(targets[0]);
    }
  }
  var Gengar11 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Haunter";
      this.cardType = [7 /* DARK */];
      this.hp = 130;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [{
        name: "Night Gate",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn, you may switch your Active Pok\xE9mon with 1 of your Benched Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Nightmare",
        cost: [7 /* DARK */, 9 /* COLORLESS */],
        damage: 100,
        text: "Your opponent's Active Pok\xE9mon is now Asleep."
      }];
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "57";
      this.set = "PAF";
      this.name = "Gengar";
      this.fullName = "Gengar PAF";
      this.NIGHT_GATE_MARKER = "NIGHT_GATE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.NIGHT_GATE_MARKER, this);
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.marker.removeMarker(this.NIGHT_GATE_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const generator = useNightGate(() => generator.next(), store, state, effect);
        const player = effect.player;
        if (player.marker.hasMarker(this.NIGHT_GATE_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        effect.player.marker.addMarker(this.NIGHT_GATE_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const specialCondition = new AddSpecialConditionsEffect(effect, [2 /* ASLEEP */]);
        store.reduceEffect(state, specialCondition);
        return state;
      }
      return state;
    }
  };

