  var MoonlightHill = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "81";
      this._trainerType = 2 /* STADIUM */;
      this.set = "PAF";
      this.name = "Moonlit Hill";
      this.fullName = "Moonlit Hill PAF";
      this.text = "Once during each player's turn, that player may discard a Basic [P] Energy from their hand. If they do, they may heal 30 damage from each of their Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const stadiumUsedTurn = player.stadiumUsedTurn;
        const hasPsychicBasic = player.hand.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(5 /* PSYCHIC */)
        );
        if (!hasPsychicBasic) {
          throw new GameError(GameMessage.CANNOT_USE_STADIUM);
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Psychic Energy" },
            { allowCancel: true, min: 1, max: 1 }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length === 0) {
              player.stadiumUsedTurn = stadiumUsedTurn;
              return;
            }
            MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this });
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (IS_STADIUM_EFFECT_BLOCKED(store, state, player, cardList, this)) {
                return;
              }
              store.reduceEffect(state, new HealEffect(player, cardList, 30));
            });
          }
        );
      }
      return state;
    }
  };

