  init_game_phase_effects();
  init_prefabs();
  var TechnicalMachineCrisisPunch = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.regulationMark = "G";
      this.set = "PAF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "90";
      this.name = "Technical Machine: Crisis Punch";
      this.fullName = "Technical Machine: Crisis Punch PAF";
      this.attacks = [
        {
          name: "Crisis Punch",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 280,
          text: "You can use this attack only when your opponent has exactly 1 Prize card remaining."
        }
      ];
      this.text = "The Pok\xE9mon this card is attached to can use the attack on this card. (You still need the necessary Energy to use this attack.) If this card is attached to 1 of your Pok\xE9mon, discard it at the end of your turn.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect && effect.attack === this.attacks[0]) {
        const pokemonCard = effect.player.active.getPokemonCard();
        if (pokemonCard && "getColorlessReduction" in pokemonCard) {
          const reduction = pokemonCard.getColorlessReduction(state);
          for (let i = 0; i < reduction && effect.cost.includes(9 /* COLORLESS */); i++) {
            const index = effect.cost.indexOf(9 /* COLORLESS */);
            if (index !== -1) {
              effect.cost.splice(index, 1);
            }
          }
        }
      }
      if (effect instanceof CheckPokemonAttacksEffect && effect.player.active.getPokemonCard()?.tools.includes(this) && !effect.attacks.includes(this.attacks[0])) {
        effect.attacks.includes(this.attacks[0]);
      }
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          return state;
        }
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, index) => {
          if (cardList.tools && cardList.tools.includes(this)) {
            MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
          }
        });
        return state;
      }
      if (effect instanceof AttackEffect && effect.attack === this.attacks[0]) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_TOOL_BLOCKED(store, state, effect.player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        const prizes = opponent.getPrizeLeft();
        if (prizes !== 1) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return state;
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-paldean-fates/tropius.ts
  init_pokemon_card();
