  var Tropius9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 110;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Leaf Drain",
          cost: [G],
          damage: 20,
          text: "Heal 20 damage from this Pok\xE9mon."
        },
        {
          name: "Tropic Breeze",
          cost: [G, G, C],
          damage: 130,
          text: "Move all Energy from this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.set = "PAL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "7";
      this.name = "Tropius";
      this.fullName = "Tropius PAL";
      this.regulationMark = "G";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        HEAL_X_DAMAGE_FROM_THIS_POKEMON(effect, store, state, 20);
      }
      if (AFTER_ATTACK(effect, 1, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (hasBench === false) {
          return state;
        }
        const attachedEnergies = player.active.cards.filter((card) => {
          return card.superType === 3 /* ENERGY */;
        });
        store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.active,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: attachedEnergies.length, max: attachedEnergies.length, sameTarget: true }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

