  function* playCard240(next, store, state, effect) {
    const player = effect.player;
    if (player.supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    const blocked = [];
    let hasValidTarget = false;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target2) => {
      const checkHpEffect = new CheckHpEffect(player, cardList);
      store.reduceEffect(state, checkHpEffect);
      if (checkHpEffect.hp - cardList.damage > 30) {
        blocked.push(target2);
      } else {
        hasValidTarget = true;
      }
    });
    if (!hasValidTarget) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: effect.trainerCard });
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_HEAL,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: false, blocked }
      ),
      (results) => {
        targets = results || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    const target = targets[0];
    const healEffect = new HealEffect(player, target, target.damage);
    store.reduceEffect(state, healEffect);
    return state;
  }
