  var BuddyBuddyPoffin = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "TEF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "144";
      this.regulationMark = "H";
      this.name = "Buddy-Buddy Poffin";
      this.fullName = "Buddy-Buddy Poffin TEF";
      this.text = "Search your deck for up to 2 Basic Pok\xE9mon with 70 HP or less and put them onto your Bench. Then, shuffle your deck.";
    }
    canPlay(store, state, player) {
      if (player.deck.cards.length === 0) {
        return false;
      }
      const openSlots = player.bench.filter((b) => b.cards.length === 0);
      if (openSlots.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const openSlots = player.bench.filter((b) => b.cards.length === 0);
        if (player.deck.cards.length === 0 || openSlots.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked = player.deck.cards.reduce((acc, c, index) => {
          if (!(c instanceof PokemonCard && c.stage === 2 /* BASIC */ && c.hp <= 70)) {
            acc.push(index);
          }
          return acc;
        }, []);
        const maxPokemons = Math.min(openSlots.length, 2);
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            player.deck,
            { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
            { min: 0, max: maxPokemons, allowCancel: false, blocked, maxPokemons }
          ),
          (selectedCards) => {
            const cards = selectedCards || [];
            cards.forEach((card, index) => {
              const playPokemonFromDeckEffect = new PlayPokemonFromDeckEffect(
                player,
                card,
                openSlots[index]
              );
              store.reduceEffect(state, playPokemonFromDeckEffect);
            });
            MOVE_CARDS(store, state, player.supporter, player.discard, {
              cards: [this],
              sourceCard: this
            });
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
              return state;
            });
          }
        );
      }
      return state;
    }
  };

