  var Eri = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "H";
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "TEF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "146";
      this.name = "Eri";
      this.fullName = "Eri TEF";
      this.text = "Your opponent reveals their hand. Discard up to 2 Item cards you find there.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.hand,
            { superType: 2 /* TRAINER */, trainerType: 0 /* ITEM */ },
            { allowCancel: false, min: 0, max: 2 }
          ),
          (cards) => {
            if (cards === null || cards.length === 0) {
              MOVE_CARDS(store, state, player.supporter, player.discard, {
                cards: [this],
                sourceCard: this
              });
              return;
            }
            MOVE_CARDS(store, state, player.supporter, player.discard, {
              cards: [this],
              sourceCard: this
            });
            cards.forEach((card) => {
              MOVE_CARDS(store, state, opponent.hand, opponent.discard, {
                cards: [card],
                sourceCard: this
              });
            });
          }
        );
      }
      return state;
    }
  };

