  var FullMetalLab = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.regulationMark = "H";
      this.set = "TEF";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "148";
      this.name = "Full Metal Lab";
      this.fullName = "Full Metal Lab TEF";
      this.text = "[M] Pok\xE9mon (both yours and your opponent's) take 30 less damage from attacks from the opponent's Pok\xE9mon (after applying Weakness and Resistance).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && StateUtils.getStadiumCard(state) === this) {
        const owner = StateUtils.findOwner(state, effect.target);
        const checkPokemonType = new CheckPokemonTypeEffect(effect.target);
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, effect.target, this)) {
          return state;
        }
        store.reduceEffect(state, checkPokemonType);
        if (checkPokemonType.cardTypes.includes(8 /* METAL */)) {
          effect.reduceDamage(30);
        }
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

