  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-temporal-forces/heavy-baton.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_game_effects();
  init_prefabs();
  var HeavyBaton = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "H";
      this._trainerType = 3 /* TOOL */;
      this.set = "TEF";
      this.name = "Heavy Baton";
      this.fullName = "Heavy Baton PAR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "151";
      this.text = "If the Pok\xE9mon this card is attached to has a Retreat Cost of 4 or higher, is in the Active Spot, and is Knocked Out by damage from an attack from your opponent's Pok\xE9mon, move up to 3 Basic Energy cards from that Pok\xE9mon to your Benched Pok\xE9mon in any way you like.";
      this.HEAVY_BATON_MARKER = "HEAVY_BATON_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const active = effect.target;
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */ || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        if (active.marker.hasMarker(this.HEAVY_BATON_MARKER)) {
          return state;
        }
        if (!active.tools.includes(this)) {
          return state;
        }
        const pokemonCard = active.getPokemonCard();
        if (!pokemonCard || pokemonCard.retreat.length < 4) {
          return state;
        }
        const basicEnergyCards = active.cards.filter(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
        );
        if (basicEnergyCards.length === 0) {
          return state;
        }
        active.marker.addMarker(this.HEAVY_BATON_MARKER, this);
        const energyToAttach = new CardList();
        energyToAttach.cards = basicEnergyCards.slice();
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            energyToAttach,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: true, min: 0, max: 3, sameTarget: true }
          ),
          (transfers) => {
            transfers = transfers || [];
            active.marker.removeMarker(this.HEAVY_BATON_MARKER);
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card] });
            }
          }
        );
      }
      return state;
    }
  };

