  var RebootPod = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this._tags = ["Ace Spec" /* ACE_SPEC */, "Future" /* FUTURE */];
      this.regulationMark = "H";
      this.set = "TEF";
      this.name = "Reboot Pod";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "158";
      this.fullName = "Reboot Pod TEF";
      this.text = "Attach a Basic Energy card from your discard pile to each of your Future Pok\xE9mon in play.";
    }
    canPlay(store, state, player) {
      const hasBasicEnergy = player.discard.cards.some(
        (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
      );
      if (!hasBasicEnergy) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        let hasEnergyInDiscard = 0;
        player.discard.cards.forEach((c, index) => {
          const isBasicEnergy = c instanceof EnergyCard && c.energyType === 0 /* BASIC */;
          if (isBasicEnergy) {
            hasEnergyInDiscard += 1;
          }
        });
        if (hasEnergyInDiscard === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked2 = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (!card.hasTag("Future" /* FUTURE */)) {
            blocked2.push(target);
          }
        });
        effect.preventDefault = true;
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_ACTIVE,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            {
              allowCancel: false,
              min: 0,
              max: hasEnergyInDiscard,
              blockedTo: blocked2,
              differentTargets: true
            }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [this], sourceCard: this });
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
              MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [this], sourceCard: this });
            }
          }
        );
      }
      return state;
    }
  };

