  function* playCard245(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: self });
    effect.preventDefault = true;
    let grassPokemonOrEnergyCount = 0;
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      const isPokemon = c instanceof PokemonCard && pokemonHasCardType(c, 1 /* GRASS */);
      const isBasicEnergy = c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.name === "Grass Energy";
      if (isPokemon || isBasicEnergy) {
        grassPokemonOrEnergyCount += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxGrassPokemonOrEnergyCount = Math.min(grassPokemonOrEnergyCount, 2);
    const deckTop = new CardList();
    MOVE_CARDS(store, state, player.deck, deckTop, { count: 7, sourceCard: self });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        deckTop,
        {},
        { min: 0, max: maxGrassPokemonOrEnergyCount, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: self });
      return state;
    }
    MOVE_CARDS(store, state, deckTop, player.hand, { cards, sourceCard: self });
    MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
