  function* playCard249(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const opponentBenchNames = opponent.bench.filter((card) => card instanceof PokemonCard).map((card) => card.name);
    const opponentActiveName = opponent.active.cards[0].name;
    const allowedNames = [opponentActiveName, ...opponentBenchNames];
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (card instanceof PokemonCard && !allowedNames.includes(card.name)) {
        blocked.push(index);
      }
    });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 1 /* POKEMON */ },
        { min: 1, max: 1, allowCancel: true, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: effect.trainerCard });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
