  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-twilight-masquerade/perrin.ts
  init_pokemon_card();
  init_trainer_card();
  init_card_types();
  init_state_utils();
  init_play_card_effects();
