  init_show_cards_prompt();
  init_shuffle_prompt();
  init_game_error();
  init_game_message();
  init_prefabs();
  function* playCard250(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    const hasPokemon = player.hand.cards.some((c) => c.superType === 1 /* POKEMON */);
    if (!hasPokemon) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: effect.trainerCard
    });
    effect.preventDefault = true;
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.hand,
        { superType: 1 /* POKEMON */ },
        { min: 1, max: 2, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return;
    }
    MOVE_CARDS(store, state, player.hand, player.deck, {
      cards,
      sourceCard: effect.trainerCard
    });
    yield store.prompt(
      state,
      new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
      () => next()
    );
    const minMax = cards.length;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 1 /* POKEMON */ },
        { min: minMax, max: minMax, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, {
      cards,
      sourceCard: effect.trainerCard
    });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var Perrin = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "H";
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "TWM";
      this.name = "Perrin";
      this.fullName = "Perrin TWM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "160";
      this.text = "Reveal up to 2 Pok\xE9mon from your hand and shuffle them into your deck. If you do, search your deck for up to that many Pok\xE9mon, reveal them, and put them into your hand. Then, shuffle your deck.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      const hasPokemon = player.hand.cards.some((c) => c instanceof PokemonCard);
      if (!hasPokemon) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard250(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

