  var Phione5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [3 /* WATER */];
      this.hp = 70;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.retreat = [9 /* COLORLESS */];
      this.attacks = [
        {
          name: "Beckon",
          cost: [9 /* COLORLESS */],
          damage: 0,
          text: "Put a Supporter card from your discard pile into your hand."
        },
        {
          name: "Energy Press",
          cost: [3 /* WATER */],
          damage: 20,
          damageCalculation: "x",
          text: "This attack does 20 damage for each Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.regulationMark = "H";
      this.set = "TWM";
      this.name = "Phione";
      this.fullName = "Phione TWM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "55";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const itemCount = player.discard.cards.filter((c) => {
          return c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */;
        }).length;
        if (itemCount === 0) {
          return state;
        }
        const max = Math.min(1, itemCount);
        const min = max;
        return store.prompt(state, [
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.discard,
            { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
            { min, max, allowCancel: false }
          )
        ], (selected) => {
          const cards = selected || [];
          MOVE_CARDS(store, state, player.discard, player.hand, { cards, sourceCard: this });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const checkProvidedEnergyEffect = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, checkProvidedEnergyEffect);
        const energyCount = checkProvidedEnergyEffect.energyMap.reduce((left, p) => left + p.provides.length, 0);
        effect.damage = energyCount * 20;
      }
      return state;
    }
  };

