  var WellspringMaskOgerponex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["ex" /* POKEMON_ex */, "Tera" /* POKEMON_TERA */];
      this.cardType = [W];
      this.weakness = [{ type: L }];
      this.hp = 210;
      this.retreat = [C];
      this.attacks = [
        {
          name: "Sob",
          cost: [C],
          damage: 20,
          text: "During your opponent's next turn, the Defending Pok\xE9mon can't retreat."
        },
        {
          name: "Torrential Pump",
          cost: [W, C, C],
          damage: 100,
          text: "You may shuffle 3 Energy attached to this Pok\xE9mon into your Deck. If you do, this attack also does 120 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.regulationMark = "H";
      this.set = "TWM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "64";
      this.name = "Wellspring Mask Ogerpon ex";
      this.fullName = "Wellspring Mask Ogerpon ex TWM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return BLOCK_RETREAT(store, state, effect, this);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(state, new ConfirmPrompt(
          effect.player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          if (!wantToUse) {
            effect.damage = 100;
            return state;
          }
          state = store.prompt(state, new ChooseEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            checkProvidedEnergy.energyMap,
            [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
            { allowCancel: false }
          ), (energy2) => {
            const cards = (energy2 || []).map((e) => e.card);
            MOVE_CARDS(store, state, player.active, player.deck, { cards, sourceCard: this });
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
              return store.prompt(state, new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
                1 /* TOP_PLAYER */,
                [2 /* BENCH */],
                { min: 1, max: 1, allowCancel: false }
              ), (selected) => {
                const target = selected?.[0];
                if (target) {
                  const damageEffect = new PutDamageEffect(effect, 120);
                  damageEffect.target = target;
                  store.reduceEffect(state, damageEffect);
                }
                return state;
              });
            });
          });
          return state;
        });
      }
      TERA_RULE(effect, state, this);
      return state;
    }
  };

