  var Palafin3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Finizen";
      this.cardType = [W];
      this.hp = 100;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.powers = [{
        name: "Zero to Hero",
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, when this Pok\xE9mon moves from the Active Spot to the Bench, you may search your deck for a Palafin ex and switch it with this Pok\xE9mon. Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pok\xE9mon. If you switched a Pok\xE9mon in this way, put this card into your deck. Then, shuffle your deck."
      }];
      this.attacks = [{
        name: "Wave Splash",
        cost: [W, C],
        damage: 30,
        text: ""
      }];
      this.set = "TWM";
      this.setNumber = "60";
      this.regulationMark = "H";
      this.cardImage = "assets/cardback.png";
      this.fullName = "Palafin TWM";
      this.name = "Palafin";
      this.ABILITY_USED_MARKER = "ABILITY_USED_MARKER";
    }
    reduceEffect(store, state, effect) {
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.ABILITY_USED_MARKER, this);
      const player = state.players[state.activePlayer];
      if (effect instanceof MovedFromActiveToBenchEffect && effect.pokemonCard === this && state.players[state.activePlayer] === effect.player && MOVED_FROM_ACTIVE_TO_BENCH_THIS_TURN(effect.player, this)) {
        if (player.marker.hasMarker(this.ABILITY_USED_MARKER, this)) {
          return state;
        }
        try {
          const stub = new PowerEffect(player, {
            name: "test",
            powerType: 2 /* ABILITY */,
            text: ""
          }, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        state = store.prompt(state, new ConfirmPrompt(
          player.id,
          GameMessage.WANT_TO_USE_ABILITY
        ), (wantToUse) => {
          player.marker.addMarker(this.ABILITY_USED_MARKER, this);
          if (!wantToUse) {
            return;
          }
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2) => {
            if (cardList2.getPokemonCard() === this) {
              store.log(state, "LOG_PLAYER_USES_ABILITY" /* LOG_PLAYER_USES_ABILITY */, { name: player.name, ability: "Zero to Hero" });
            }
          });
          if (player.deck.cards.length === 0) {
            return;
          }
          const cardList = StateUtils.findCardList(state, this);
          let cards = [];
          state = store.prompt(state, new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_EVOLVE,
            player.deck,
            { superType: 1 /* POKEMON */, name: "Palafin ex" },
            { min: 0, max: 1, allowCancel: false }
          ), (selected) => {
            cards = selected || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, player.deck, cardList, { cards: [cards[0]], sourceCard: this });
              MOVE_CARDS(store, state, cardList, player.deck, { cards: [this], sourceCard: this });
            }
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          });
        });
      }
      return state;
    }
  };

