  var PerformanceFlute = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "H";
      this._trainerType = 0 /* ITEM */;
      this.set = "TWM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "142";
      this.name = "Accompanying Flute";
      this.fullName = "Accompanying Flute TWM";
      this.text = "Reveal the top 5 cards of your opponent's deck, and put any number of Basic Pok\xE9mon you find there onto your opponent's Bench. Then, they shuffle the remaining cards back into their deck.";
    }
    canPlay(store, state, player) {
      const opponent = StateUtils.getOpponent(state, player);
      const openSlots = opponent.bench.filter((b) => b.cards.length === 0);
      if (openSlots.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const slots2 = opponent.bench.filter((b) => b.cards.length === 0);
        const openSlots = opponent.bench.filter((b) => b.cards.length === 0);
        if (openSlots.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        effect.preventDefault = true;
        if (opponent.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, opponent.deck, deckTop, { count: 5, sourceCard: this });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            deckTop,
            { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
            { min: 0, max: openSlots.length, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length === 0) {
              return store.prompt(
                state,
                new ShowCardsPrompt(
                  opponent.id,
                  GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                  deckTop.cards
                ),
                () => {
                  MOVE_CARDS(store, state, deckTop, opponent.deck, { sourceCard: this });
                  return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                    player.deck.applyOrder(order);
                    return state;
                  });
                }
              );
            }
            cards.forEach((card, index) => {
              MOVE_CARDS(store, state, deckTop, slots2[index], { cards: [card], sourceCard: this });
              slots2[index].pokemonPlayedTurn = state.turn;
            });
            MOVE_CARDS(store, state, deckTop, opponent.deck, { sourceCard: this });
            return store.prompt(state, new ShuffleDeckPrompt(opponent.id), (order) => {
              opponent.deck.applyOrder(order);
              return state;
            });
          }
        );
      }
      return state;
    }
  };

