  init_prefabs();
  function* playCard251(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const handCards = player.hand.cards.filter((c) => c !== effect.trainerCard);
    if (handCards.length < 3) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: self });
    effect.preventDefault = true;
    let tools = 0;
    let items = 0;
    let stadiums = 0;
    let supporters = 0;
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      if (c instanceof TrainerCard && c.trainerType === 3 /* TOOL */) {
        tools += 1;
      } else if (c instanceof TrainerCard && c.trainerType === 0 /* ITEM */) {
        items += 1;
      } else if (c instanceof TrainerCard && c.trainerType === 2 /* STADIUM */) {
        stadiums += 1;
      } else if (c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */) {
        supporters += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxTools = Math.min(tools, 1);
    const maxItems = Math.min(items, 1);
    const maxStadiums = Math.min(stadiums, 1);
    const maxSupporters = Math.min(supporters, 1);
    const count = maxTools + maxItems + maxStadiums + maxSupporters;
    const handTemp = new CardList();
    handTemp.cards = player.hand.cards.filter((c) => c !== self);
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        handTemp,
        {},
        { min: 3, max: 3, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: self });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        {},
        {
          min: 0,
          max: count,
          allowCancel: false,
          blocked,
          maxTools,
          maxItems,
          maxStadiums,
          maxSupporters
        }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var SecretBox = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this._tags = ["Ace Spec" /* ACE_SPEC */];
      this.regulationMark = "H";
      this.set = "TWM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "163";
      this.name = "Secret Box";
      this.fullName = "Secret Box TWM";
      this.text = `You can use this card only if you discard 3 other cards from your hand.

Search your deck for an Item card, a Pok\xE9mon Tool card, a Supporter card, and a Stadium card, reveal them, and put them into your hand. Then, shuffle your deck.`;
    }
    canPlay(store, state, player) {
      if (player.hand.cards.filter((c) => c !== this).length < 3) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard251(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

