  function* playCard252(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    if (!player.marker.hasMarker(self.UNFAIR_STAMP_MARKER)) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const cards = player.hand.cards.filter((c) => c !== self);
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.deck, { cards, sourceCard: self });
    MOVE_CARDS(store, state, opponent.hand, opponent.deck, { sourceCard: self });
    yield store.prompt(
      state,
      [new ShuffleDeckPrompt(player.id), new ShuffleDeckPrompt(opponent.id)],
      (deckOrder) => {
        player.deck.applyOrder(deckOrder[0]);
        opponent.deck.applyOrder(deckOrder[1]);
        MOVE_CARDS(store, state, player.deck, player.hand, { count: 5, sourceCard: self });
        MOVE_CARDS(store, state, opponent.deck, opponent.hand, { count: 2, sourceCard: self });
      }
    );
  }
  var UnfairStamp = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this._tags = ["Ace Spec" /* ACE_SPEC */];
      this.set = "TWM";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "165";
      this.regulationMark = "H";
      this.name = "Unfair Stamp";
      this.fullName = "Unfair Stamp TWM";
      this.text = `You can use this card only if one of your Pok\xE9mon was Knocked Out during your opponent's last turn.

Each player shuffles their hand into their deck. Then, you draw 5 cards, and your opponent draws 2 cards.`;
      this.UNFAIR_STAMP_MARKER = "UNFAIR_STAMP_MARKER";
    }
    canPlay(store, state, player) {
      if (!player.marker.hasMarker(this.UNFAIR_STAMP_MARKER)) {
        return false;
      }
      if (player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard252(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const duringTurn = [2 /* PLAYER_TURN */, 3 /* ATTACK */].includes(state.phase);
        if (!duringTurn || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) {
          effect.player.marker.addMarker(this.UNFAIR_STAMP_MARKER, this);
        }
        return state;
      }
      REMOVE_OPPONENT_LAST_TURN_MARKER_AT_END_OF_TURN(effect, this.UNFAIR_STAMP_MARKER, this);
      return state;
    }
  };

