  function* attack2(next, store, state, effect) {
    const player = effect.player;
    const maxAllowedDamage = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
      const checkHpEffect = new CheckHpEffect(player, cardList);
      store.reduceEffect(state, checkHpEffect);
      maxAllowedDamage.push({ target, damage: checkHpEffect.hp + 90 });
    });
    return store.prompt(
      state,
      new PutDamagePrompt(
        effect.player.id,
        GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */],
        90,
        maxAllowedDamage,
        { allowCancel: false, allowPlacePartialDamage: true }
      ),
      (targets) => {
        const results = targets || [];
        for (const result of results) {
          const target = StateUtils.getTarget(state, player, result.target);
          const putCountersEffect = new PutCountersEffect(effect, result.damage);
          putCountersEffect.target = target;
          store.reduceEffect(state, putCountersEffect);
          effect.damage = result.damage * 2;
        }
      }
    );
  }

