  function* playCard253(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    let trainers = 0;
    let energies = 0;
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      if (c instanceof TrainerCard && c.trainerType === 2 /* STADIUM */) {
        trainers += 1;
      } else if (c instanceof EnergyCard) {
        energies += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxTrainers = Math.min(trainers, 1);
    const maxEnergies = Math.min(energies, 1);
    const count = maxTrainers + maxEnergies;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        {},
        { min: 0, max: count, allowCancel: false, blocked, maxTrainers, maxEnergies }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
