  function* useKingsOrder3(next, store, state, effect) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const max = Math.min(slots2.length, 3);
    const hasDuskullInDiscard = player.hand.cards.some((c) => {
      return c instanceof PokemonCard && c.name === "Duskull";
    });
    if (!hasDuskullInDiscard) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
      player.discard,
      { superType: 1 /* POKEMON */, name: "Duskull" },
      { min: 1, max, allowCancel: false }
    ), (selected) => {
      cards = selected || [];
      next();
    });
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      MOVE_CARDS(store, state, player.discard, slots2[index], { cards: [card], sourceCard: effect.source.getPokemonCard() });
      slots2[index].pokemonPlayedTurn = state.turn;
    });
  }
