  function* useColorfulCatch(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const maxEnergies = 3;
    const uniqueBasicEnergies = Math.min(maxEnergies, player.deck.cards.filter((c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */).map((e) => e.provides[0]).filter((value, index, self) => self.indexOf(value) === index).length);
    let cards = [];
    yield store.prompt(state, new ChooseCardsPrompt(
      player,
      GameMessage.CHOOSE_CARD_TO_HAND,
      player.deck,
      { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
      { min: 0, max: uniqueBasicEnergies, allowCancel: false, differentTypes: true }
    ), (selected) => {
      cards = selected || [];
      if (selected.length > 1) {
        if (selected[0].name === selected[1].name) {
          throw new GameError(GameMessage.CAN_ONLY_SELECT_TWO_DIFFERENT_ENERGY_TYPES);
        }
      }
      MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: effect.source.getPokemonCard() });
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
