  var JaninesSecretTechnique = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "H";
      this.set = "SFA";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "59";
      this.name = "Janine's Secret Art";
      this.fullName = "Janine's Secret Technique SFA";
      this.text = "Choose up to 2 of your [D] Pok\xE9mon. For each of those Pok\xE9mon, search your deck for a Basic [D] Energy card and attach it to that Pok\xE9mon. Then, shuffle your deck. If you attached Energy to your Active Pok\xE9mon in this way, it is now Poisoned.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      let hasDarkPokemon = false;
      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card) => {
        if (pokemonHasCardType(card, 7 /* DARK */)) {
          hasDarkPokemon = true;
        }
      });
      if (!hasDarkPokemon) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        let darkPokemonInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card) => {
          if (pokemonHasCardType(card, 7 /* DARK */)) {
            darkPokemonInPlay = true;
          }
        });
        if (!darkPokemonInPlay) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked2 = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (!pokemonHasCardType(card, 7 /* DARK */)) {
            blocked2.push(target);
          }
        });
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_ACTIVE,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Darkness Energy" },
            { allowCancel: false, min: 0, max: 2, blockedTo: blocked2, differentTargets: true }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              SHUFFLE_DECK(store, state, player);
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, {
                cards: [transfer.card],
                sourceCard: this
              });
              if (target == player.active) {
                player.active.addSpecialCondition(3 /* POISONED */);
              }
            }
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      return state;
    }
  };

