  function* useChainsOfControl(next, store, state, effect) {
    const player = effect.player;
    const hasDarkBench = player.bench.some(
      (b) => pokemonHasCardTypeOptional(b.getPokemonCard(), 7 /* DARK */) && b.getPokemonCard()?.name !== "Pecharunt ex"
    );
    if (player.chainsOfControlUsed == true) {
      throw new GameError(GameMessage.POWER_ALREADY_USED);
    }
    if (hasDarkBench === false) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const blocked = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target2) => {
      if (card.name === "Pecharunt ex") {
        blocked.push(target2);
      }
      if (!pokemonHasCardTypeOptional(list.getPokemonCard(), 7 /* DARK */)) {
        blocked.push(target2);
      }
    });
    let darkPokemonCount = 0;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card) => {
      if (pokemonHasCardType(card, 7 /* DARK */)) {
        darkPokemonCount++;
      }
    });
    if (darkPokemonCount <= 1) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let target = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_SWITCH,
        2 /* BOTTOM_PLAYER */,
        [2 /* BENCH */],
        { allowCancel: false, blocked }
      ),
      (results) => {
        target = results || [];
        next();
      }
    );
    if (target.length > 0) {
      player.active.clearEffects();
      player.switchPokemon(target[0]);
      player.active.addSpecialCondition(3 /* POISONED */);
      player.chainsOfControlUsed = true;
    }
  }
  var Pecharuntex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["ex" /* POKEMON_ex */];
      this.regulationMark = "H";
      this.cardType = [7 /* DARK */];
      this.hp = 190;
      this.weakness = [{ type: 6 /* FIGHTING */ }];
      this.retreat = [9 /* COLORLESS */];
      this.powers = [
        {
          name: "Subjugating Chains",
          powerType: 2 /* ABILITY */,
          useWhenInPlay: true,
          text: "Once during your turn, you may switch 1 of your Benched [D] Pok\xE9mon, except any Pecharunt ex, with your Active Pok\xE9mon. If you do, the new Active Pok\xE9mon is now Poisoned. You can't use more than 1 Subjugating Chains Ability each turn."
        }
      ];
      this.attacks = [
        {
          name: "Irritated Outburst",
          cost: [7 /* DARK */, 7 /* DARK */],
          damage: 60,
          damageCalculation: "x",
          text: "This attack does 60 damage for each Prize card your opponent has taken."
        }
      ];
      this.set = "SFA";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "39";
      this.name = "Pecharunt ex";
      this.fullName = "Pecharunt ex SFA";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.chainsOfControlUsed = false;
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const generator = useChainsOfControl(() => generator.next(), store, state, effect);
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
        return generator.next().value;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const damagePerPrize = 60;
        effect.damage = opponent.prizesTaken * damagePerPrize;
      }
      if (effect instanceof CheckTableStateEffect) {
        state.players.forEach((player) => {
          if (player.active.specialConditions.length === 0) {
            return;
          }
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
            if (card === this) {
              player.pecharuntexIsInPlay = true;
            }
          });
        });
        return state;
      }
      return state;
    }
  };

