  var PowerHourglass = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "H";
      this._trainerType = 3 /* TOOL */;
      this.set = "SFA";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "63";
      this.name = "Powerglass";
      this.fullName = "Powerglass SFA";
      this.text = "At the end of your turn, if the Pok\xE9mon this card is attached to is in the Active Spot, you may attach a Basic Energy from your discard pile to that Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && effect.player.active.tools.includes(this)) {
        const player = effect.player;
        try {
          const stub = new ToolEffect(player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */;
        });
        if (!hasEnergyInDiscard) {
          return state;
        }
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_ACTIVE,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: 0, max: 1 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, {
                cards: [transfer.card],
                sourceCard: this
              });
            }
          }
        );
      }
      return state;
    }
  };

