  var XerosicsScheme = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "H";
      this.set = "SFA";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "64";
      this.name = "Xerosic's Machinations";
      this.fullName = "Xerosic's Machinations SFA";
      this.text = "Your opponent discards cards from their hand until they have 3 cards in their hand.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      const opponent = StateUtils.getOpponent(state, player);
      if (opponent.hand.cards.length <= 3) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const opponentHandLength = opponent.hand.cards.length;
        if (opponentHandLength <= 3) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const discardAmount = opponentHandLength - 3;
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        store.prompt(
          state,
          new ChooseCardsPrompt(
            opponent,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.hand,
            {},
            { min: discardAmount, max: discardAmount, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            MOVE_CARDS(store, state, opponent.hand, opponent.discard, {
              cards,
              sourceCard: this
            });
          }
        );
      }
      return state;
    }
  };

