  var Briar = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "H";
      this.set = "SCR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "132";
      this.name = "Briar";
      this.fullName = "Briar SCR";
      this.text = `You can use this card only if your opponent has exactly 2 Prize cards remaining.

During this turn, if your opponent's Active Pok\xE9mon is Knocked Out by damage from an attack used by your Tera Pok\xE9mon, take 1 more Prize card.`;
      this.extraPrizes = false;
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      const hasPokemon = player.discard.cards.some((c) => c instanceof PokemonCard);
      if (!hasPokemon) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        if (opponent.getPrizeLeft() !== 2) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        this.extraPrizes = true;
        return state;
      }
      if (effect instanceof KnockOutEffect && effect.target === effect.player.active) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (state.phase !== 3 /* ATTACK */ || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        if (effect.target === player.active) {
          const attackingPokemon = opponent.active;
          if (attackingPokemon.isTera() && this.extraPrizes) {
            if (effect.prizeCount > 0) {
              effect.prizeCount += 1;
            }
          }
          this.extraPrizes = false;
        }
        MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [this], sourceCard: this });
        return state;
      }
      return state;
    }
  };

