  init_check_effects();
  init_play_card_effects();
  var SparklingCrystal = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this._tags = ["Ace Spec" /* ACE_SPEC */];
      this.set = "SCR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "142";
      this.regulationMark = "H";
      this.name = "Sparkling Crystal";
      this.fullName = "Sparkling Crystal SCR";
      this.text = "When the Tera Pok\xE9mon this card is attached to uses an attack, that attack costs 1 Energy less. (The Energy can be of any type.)";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect && effect.player.active.tools.includes(this)) {
        const pokemonCard = effect.player.active.getPokemonCard();
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        if (pokemonCard && pokemonCard.hasTag("Tera" /* POKEMON_TERA */)) {
          const checkEnergy = new CheckProvidedEnergyEffect(effect.player);
          store.reduceEffect(state, checkEnergy);
          const availableEnergy = [...checkEnergy.energyMap.flatMap((e) => e.provides)];
          if (effect.cost.length > 0) {
            const contained = [];
            for (const costType of effect.cost) {
              if (costType === 9 /* COLORLESS */ && availableEnergy.length > 0) {
                contained.push(availableEnergy.splice(0, 1)[0]);
                continue;
              }
              let i = availableEnergy.indexOf(costType);
              if (i > -1) {
                contained.push(availableEnergy.splice(i, 1)[0]);
                continue;
              }
              i = availableEnergy.indexOf(0 /* ANY */);
              if (i > -1) {
                contained.push(availableEnergy.splice(i, 1)[0]);
              }
            }
            if (contained.length >= effect.cost.length - 1) {
              effect.cost = contained;
            }
          }
        }
      }
      return state;
    }
  };

