  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-stellar-crown/comfey.ts
  init_game();
  init_prefabs();
  var Comfey3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 70;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.attacks = [{
        name: "Flower Shower",
        cost: [P],
        damage: 0,
        text: "Each player draws 3 cards."
      }, {
        name: "Play Rough",
        cost: [P],
        damage: 20,
        damageCalculation: "+",
        text: "Flip a coin. If heads, this attack does 20 more damage."
      }];
      this.regulationMark = "H";
      this.set = "SCR";
      this.name = "Comfey";
      this.fullName = "Comfey SCR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "63";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        if (opponent.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        MOVE_CARDS(store, state, player.deck, player.hand, { count: 3, sourceCard: this });
        MOVE_CARDS(store, state, opponent.deck, opponent.hand, { count: 3, sourceCard: this });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        return COIN_FLIP_PROMPT(
          store,
          state,
          player,
          (result) => {
            if (result === true) {
              effect.damage += 20;
            }
          }
        );
      }
      return state;
    }
  };

