  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-stellar-crown/deluxe-bomb.ts
  init_trainer_card();
  init_card_types();
  init_state();
  init_attack_effects();
  init_state_utils();
  init_play_card_effects();
  init_prefabs();
  var DeluxeBomb = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "G";
      this._tags = ["Ace Spec" /* ACE_SPEC */];
      this._trainerType = 3 /* TOOL */;
      this.set = "SCR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "134";
      this.name = "Deluxe Bomb";
      this.fullName = "Deluxe Bomb SCR";
      this.text = "If the Pok\xE9mon this card is attached to is in the Active Spot and is damaged by an attack from your opponent's Pok\xE9mon (even if this Pok\xE9mon is Knocked Out), put 12 damage counters on the Attacking Pok\xE9mon. If you placed any damage counters in this way, discard this card.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        if (effect.damage <= 0 || player === targetPlayer || targetPlayer.active !== effect.target) {
          return state;
        }
        if (state.phase === 3 /* ATTACK */) {
          effect.source.damage += 120;
          effect.target.cards.forEach((card) => {
            if (card === this) {
              MOVE_CARDS(store, state, effect.target, targetPlayer.discard, { cards: [card], sourceCard: this });
            }
          });
        }
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-stellar-crown/diancie.ts
  init_game();
