  var Diancie5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 110;
      this.weakness = [{ type: G }];
      this.resistance = [];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Diffuse Reflection",
          cost: [C],
          damage: 40,
          damageCalculation: "x",
          text: "This attack does 40 damage for each Special Energy attached to all of your opponent's Pok\xE9mon."
        },
        {
          name: "Power Gem",
          cost: [F, C],
          damage: 60,
          text: ""
        }
      ];
      this.regulationMark = "H";
      this.set = "SCR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "86";
      this.name = "Diancie";
      this.fullName = "Diancie SCR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let specialEnergyCount = 0;
        opponent.bench.concat([opponent.active]).forEach((pokemon) => {
          if (pokemon) {
            pokemon.cards.forEach((card) => {
              if (card.superType === 3 /* ENERGY */ && card.energyType === 1 /* SPECIAL */) {
                specialEnergyCount++;
              }
            });
          }
        });
        effect.damage = 40 * specialEnergyCount;
      }
      return state;
    }
  };

