  function* useStadium12(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const cm = CardManager.getInstance();
    const evolutions = cm.getAllCards().filter((c) => {
      return c instanceof PokemonCard && c.stage !== 2 /* BASIC */;
    });
    const evolutionNames = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target2) => {
      const playedTurnEffect = new CheckPokemonPlayedTurnEffect(player, list);
      store.reduceEffect(state, playedTurnEffect);
      if (card.stage !== 2 /* BASIC */ || playedTurnEffect.pokemonPlayedTurn === state.turn) {
        return;
      }
      const valid = evolutions.filter((e) => e.evolvesFrom === card.name);
      valid.forEach((c) => {
        if (!evolutionNames.includes(c.name)) {
          evolutionNames.push(c.name);
        }
      });
    });
    if (evolutionNames.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const blocked2 = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target2) => {
      if (card.stage !== 2 /* BASIC */) {
        blocked2.push(target2);
        return;
      }
      const playedTurnEffect = new CheckPokemonPlayedTurnEffect(player, list);
      store.reduceEffect(state, playedTurnEffect);
      if (playedTurnEffect.pokemonPlayedTurn === state.turn) {
        blocked2.push(target2);
      }
    });
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_EVOLVE,
        2 /* BOTTOM_PLAYER */,
        [2 /* BENCH */, 1 /* ACTIVE */],
        { min: 1, max: 1, allowCancel: false, blocked: blocked2 }
      ),
      (selection) => {
        targets = selection || [];
        next();
      }
    );
    if (targets.length === 0) {
      SHUFFLE_DECK(store, state, player);
      return state;
    }
    const target = targets[0];
    const pokemonCard = target.getPokemonCard();
    if (pokemonCard === void 0) {
      return state;
    }
    const targetPlayedTurnEffect = new CheckPokemonPlayedTurnEffect(player, target);
    store.reduceEffect(state, targetPlayedTurnEffect);
    if (pokemonCard.stage !== 2 /* BASIC */ || targetPlayedTurnEffect.pokemonPlayedTurn === state.turn) {
      return state;
    }
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (card instanceof PokemonCard && card.evolvesFrom !== pokemonCard.name) {
        blocked.push(index);
      }
    });
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_EVOLVE,
        player.deck,
        { superType: 1 /* POKEMON */, stage: 3 /* STAGE_1 */, evolvesFrom: pokemonCard.name },
        { min: 1, max: 1, allowCancel: true, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      SHUFFLE_DECK(store, state, player);
      return state;
    }
    const evolution = cards[0];
    MOVE_CARDS(store, state, player.deck, target, { cards: [evolution], sourceCard: effect.stadium });
    target.clearEffects();
    target.pokemonPlayedTurn = state.turn;
    const stage2Evolutions = evolutions.filter((e) => e.evolvesFrom === evolution.name);
    if (stage2Evolutions.length > 0) {
      const blockedStage2 = [];
      player.deck.cards.forEach((card, index) => {
        if (card instanceof PokemonCard && card.evolvesFrom !== evolution.name) {
          blockedStage2.push(index);
        }
      });
      let stage2Cards = [];
      yield store.prompt(
        state,
        new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_EVOLVE,
          player.deck,
          { superType: 1 /* POKEMON */, stage: 4 /* STAGE_2 */, evolvesFrom: evolution.name },
          { min: 1, max: 1, allowCancel: true, blocked: blockedStage2 }
        ),
        (selected) => {
          stage2Cards = selected || [];
          next();
        }
      );
      if (stage2Cards.length > 0) {
        const stage2Evolution = stage2Cards[0];
        MOVE_CARDS(store, state, player.deck, target, { cards: [stage2Evolution], sourceCard: effect.stadium });
        target.clearEffects();
        target.pokemonPlayedTurn = state.turn;
      }
    }
    SHUFFLE_DECK(store, state, player);
  }
