  var Veluza2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [3 /* WATER */];
      this.hp = 130;
      this.weakness = [{ type: 4 /* LIGHTNING */ }];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [
        {
          name: "Food Prep",
          useWhenInPlay: false,
          powerType: 2 /* ABILITY */,
          text: "Attacks used by this Pok\xE9mon cost [C] less for each Kofu card in your discard pile."
        }
      ];
      this.attacks = [
        {
          name: "Sonic Edge",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 110,
          shredAttack: true,
          text: "This attack's damage isn't affected by any effects on your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "SCR";
      this.name = "Veluza";
      this.fullName = "Veluza SCR";
      this.setNumber = "45";
      this.regulationMark = "H";
      this.cardImage = "assets/cardback.png";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect) {
        const player = effect.player;
        if (effect.player !== player || player.active.getPokemonCard() !== this) {
          return state;
        }
        try {
          const powerEffect = new PowerEffect(player, this.powers[0], this);
          store.reduceEffect(state, powerEffect);
        } catch {
          return state;
        }
        let kofuCount = 0;
        player.discard.cards.forEach((c) => {
          if (c instanceof TrainerCard && c.name === "Kofu") {
            kofuCount += 1;
          }
        });
        const index = effect.cost.indexOf(9 /* COLORLESS */);
        effect.cost.splice(index, kofuCount);
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const applyWeakness = new ApplyWeaknessEffect(effect, 110);
        store.reduceEffect(state, applyWeakness);
        const damage = applyWeakness.damage;
        effect.damage = 0;
        if (damage > 0) {
          opponent.active.damage += damage;
          const afterDamage = new AfterDamageEffect(effect, damage);
          state = store.reduceEffect(state, afterDamage);
        }
      }
      return state;
    }
  };

