  var AntiqueRootFossil = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.stage = 2 /* BASIC */;
      this.cardType = [9 /* COLORLESS */];
      this.cardTypez = 9 /* COLORLESS */;
      this.movedToActiveThisTurn = false;
      this.pokemonType = 0 /* NORMAL */;
      this.evolvesFrom = "";
      this.cardTag = [];
      this._tags = ["Antique" /* ANTIQUE */];
      this.tools = [];
      this.evolvesTo = [];
      this.evolvesToStage = [];
      this.archetype = [];
      this.hp = 60;
      this.weakness = [];
      this.retreat = [];
      this.resistance = [];
      this.attacks = [];
      this.attacksThisTurn = 0;
      this.maxAttacksThisTurn = 1;
      this.allowSubsequentAttackChoice = false;
      this.evolvesFromBase = [];
      this.maxTools = 1;
      this.powers = [
        {
          name: "Antique Root Fossil",
          text: "Play this card as a 60 HP Basic [C] Pok\xE9mon. This card can't be affected by Special Conditions and can't retreat. At any time during your turn, you may discard this card from play.",
          useWhenInPlay: true,
          exemptFromAbilityLock: true,
          isFossil: true,
          powerType: 9 /* TRAINER_ABILITY */
        }
      ];
      this.regulationMark = "H";
      this.set = "SCR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "130";
      this.name = "Antique Root Fossil";
      this.fullName = "Antique Root Fossil SCR";
    }
    canPlay(store, state, player) {
      const openSlots = player.bench.filter((b) => b.cards.length === 0);
      if (openSlots.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        store.log(state, "LOG_PLAYER_DISCARDS_CARD" /* LOG_PLAYER_DISCARDS_CARD */, {
          name: player.name,
          card: this.name,
          effect: "Antique Root Fossil"
        });
        const cardList = StateUtils.findCardList(state, this);
        MOVE_CARDS(store, state, cardList, player.discard, { cards: [this], sourceCard: this });
      }
      if (effect instanceof PlayItemEffect && effect.trainerCard === this) {
        const player = effect.player;
        const emptySlots = player.bench.filter((b) => b.cards.length === 0);
        if (emptySlots.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const playPokemonEffect = new PlayPokemonEffect(
          player,
          this,
          emptySlots[0]
        );
        store.reduceEffect(state, playPokemonEffect);
      }
      if (effect instanceof RetreatEffect && effect.player.active.getPokemonCard() === this) {
        throw new GameError(GameMessage.CANNOT_RETREAT);
      }
      if (effect instanceof AddSpecialConditionsEffect && effect.target.getPokemonCard() === this) {
        effect.preventDefault = true;
      }
      return state;
    }
  };

