  var Cradily3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Lileep";
      this.hp = 150;
      this.cardType = [G];
      this.weakness = [{ type: R }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Selective Slime",
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may flip a coin. If heads, choose Burned, Confused, or Poisoned. Your opponent's Active Pok\xE9mon is now affected by that Special Condition.",
        useWhenInPlay: true
      }];
      this.attacks = [{
        name: "Miasma Wind",
        cost: [G],
        damage: 100,
        damageCalculation: "x",
        text: "This attack does 100 damage for each Special Condition affecting your opponent's Active Pok\xE9mon."
      }];
      this.regulationMark = "H";
      this.set = "SCR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "6";
      this.name = "Cradily";
      this.fullName = "Cradily SCR";
      this.SELECTIVE_SLIME_MARKER = "CRADILY_SELECTIVE_SLIME_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        USE_ABILITY_ONCE_PER_TURN(player, this.SELECTIVE_SLIME_MARKER, this);
        ABILITY_USED(player, this);
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            const options = [
              { message: GameMessage.SPECIAL_CONDITION_ASLEEP, value: 2 /* ASLEEP */ },
              { message: GameMessage.SPECIAL_CONDITION_BURNED, value: 4 /* BURNED */ },
              { message: GameMessage.SPECIAL_CONDITION_CONFUSED, value: 1 /* CONFUSED */ },
              { message: GameMessage.SPECIAL_CONDITION_POISONED, value: 3 /* POISONED */ }
            ];
            store.prompt(state, new SelectPrompt(
              player.id,
              GameMessage.CHOOSE_SPECIAL_CONDITION,
              options.map((c) => c.message),
              { allowCancel: false }
            ), (choice) => {
              const option = options[choice];
              if (option !== void 0) {
                const specialConditionEffect = new AddSpecialConditionsPowerEffect(player, this, opponent.active, [option.value]);
                store.reduceEffect(state, specialConditionEffect);
              }
            });
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.SELECTIVE_SLIME_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const specialConditionCount = opponent.active.specialConditions.length;
        effect.damage = 100 * specialConditionCount;
      }
      return state;
    }
  };

