  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-surging-sparks/alolan-exeggutor-ex.ts
  init_game();
  init_attack_effects2();
  init_play_card_effects();
  init_prefabs();
  var AlolanExeggutorex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["ex" /* POKEMON_ex */, "Tera" /* POKEMON_TERA */];
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Exeggcute";
      this.cardType = [N];
      this.hp = 300;
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Tropical Fever",
          cost: [G, W],
          damage: 150,
          text: "Choose any number of Basic Energy cards from your hand and attach them to your Pokemon in any way you like."
        },
        {
          name: "Swinging Sphene",
          cost: [G, W, F],
          damage: 0,
          text: "Flip a coin. If heads, Knock Out your opponent's Active Basic Pokemon. If tails, Knock Out 1 of your opponent's Benched Basic Pokemon."
        }
      ];
      this.regulationMark = "H";
      this.set = "SSP";
      this.setNumber = "133";
      this.cardImage = "assets/cardback.png";
      this.name = "Alolan Exeggutor ex";
      this.fullName = "Alolan Exeggutor ex SSP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c instanceof EnergyCard && c.energyType === 0 /* BASIC */;
        });
        if (!hasEnergyInHand) {
          return state;
        }
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.hand,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              const energyCard = transfer.card;
              const attachEnergyEffect = new AttachEnergyEffect(player, energyCard, target);
              store.reduceEffect(state, attachEnergyEffect);
            }
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const blocked = [];
        const opponentActive = opponent.active.getPokemonCard();
        const opponentBench = opponent.bench.filter(
          (card) => card.getPokemonCard()?.stage === 2 /* BASIC */
        );
        opponentBench.forEach((card) => {
          if (!card.isStage(2 /* BASIC */)) {
            blocked.push();
          }
        });
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result === true) {
            if (opponentActive && opponentActive.stage !== 2 /* BASIC */) {
              return state;
            } else {
              KNOCK_OUT_OPPONENTS_ACTIVE_POKEMON(store, state, effect);
            }
          }
          if (!result) {
            if (!opponentBench) {
              return state;
            }
            if (opponentBench) {
              return store.prompt(
                state,
                new ChoosePokemonPrompt(
                  player.id,
                  GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
                  1 /* TOP_PLAYER */,
                  [2 /* BENCH */],
                  { min: 1, max: 1, allowCancel: false, blocked }
                ),
                (selected) => {
                  const targets = selected || [];
                  targets.forEach((target) => {
                    KNOCK_OUT_OPPONENTS_ACTIVE_POKEMON(store, state, effect, target);
                  });
                }
              );
            }
          }
        });
      }
      TERA_RULE(effect, state, this);
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-surging-sparks/amulet-of-hope.ts
  init_trainer_card();
