  var AmuletofHope = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._tags = ["Ace Spec" /* ACE_SPEC */];
      this._trainerType = 3 /* TOOL */;
      this.set = "SSP";
      this.setNumber = "162";
      this.cardImage = "assets/cardback.png";
      this.regulationMark = "H";
      this.name = "Amulet of Hope";
      this.fullName = "Amulet of Hope SSP";
      this.text = "If the Pok\xE9mon this card is attached to is Knocked Out by damage from an attack from your opponent's Pok\xE9mon, search your deck for up to 3 cards and put them into your hand. Then, shuffle your deck.";
      this.AMULET_OF_HOPE_MARKER = "AMULET_OF_HOPE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        const target = effect.target;
        const cards = target.getPokemons();
        cards.forEach((card) => {
          player.marker.addMarker(this.AMULET_OF_HOPE_MARKER, card);
        });
      }
      if (effect instanceof BetweenTurnsEffect) {
        state.players.forEach((player) => {
          if (!player.marker.hasMarker(this.AMULET_OF_HOPE_MARKER)) {
            return state;
          }
          if (player.deck.cards.length === 0) {
            return state;
          }
          store.log(state, "LOG_PLAYER_USES_ABILITY" /* LOG_PLAYER_USES_ABILITY */, {
            name: player.name,
            card: "Amulet of Hope"
          });
          let cards = [];
          store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_HAND,
              player.deck,
              {},
              { min: 0, max: 3, allowCancel: false }
            ),
            (selected) => {
              cards = selected || [];
              MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this });
            }
          );
          store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
          player.marker.removeMarker(this.AMULET_OF_HOPE_MARKER);
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-surging-sparks/archaludon-ex.ts
