  function* playCard260(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: effect.trainerCard });
    const deckTop = new CardList();
    MOVE_CARDS(store, state, player.deck, deckTop, { count: 7, sourceCard: effect.trainerCard });
    let trainers = 0;
    let pokemons = 0;
    const blocked = [];
    deckTop.cards.forEach((c, index) => {
      if (c instanceof TrainerCard) {
        trainers += 1;
      } else if (c instanceof PokemonCard) {
        pokemons += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxTrainers = Math.min(trainers, 1);
    const maxPokemons = Math.min(pokemons, 1);
    const count = maxTrainers + maxPokemons;
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        deckTop,
        {},
        {
          min: 0,
          max: count,
          allowCancel: false,
          blocked,
          maxTrainers,
          maxPokemons,
          allowDifferentSuperTypes: true,
          differentTypes: true
        }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, deckTop, player.hand, { cards, sourceCard: effect.trainerCard });
    MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: effect.trainerCard });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
