      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Minor Errand-Running",
          cost: [C],
          damage: 0,
          text: "Search your deck for up to 2 Basic Energy cards, reveal them, and put them into your hand. Then, shuffle your deck."
        },
        {
          name: "Tackle",
          cost: [C, C, C],
          damage: 50,
          text: ""
        }
      ];
