      this.evolvesFrom = "Gimmighoul";
      this.attacks = [
        {
          name: "Strike It Rich",
          cost: [8 /* METAL */],
          damage: 30,
          damageCalculation: "+",
          text: "If this Pok\xE9mon evolved from Gimmighoul during this turn, this attack does 90 more damage."
        },
        {
          name: "Surf Back",
          cost: [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */],
          damage: 100,
          text: "You may shuffle this Pok\xE9mon and all attached cards into your deck."
        }
      ];
