  var JasminesGaze = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "SSP";
      this.setNumber = "178";
      this.cardImage = "assets/cardback.png";
      this.regulationMark = "H";
      this.name = "Jasmine's Gaze";
      this.fullName = "Jasmine's Gaze SSP";
      this.text = "During your opponent's next turn, all of your Pok\xE9mon take 30 less damage from attacks from your opponent's Pok\xE9mon (after applying Weakness and Resistance). (This includes new Pok\xE9mon that come into play.)";
      this.JASMINES_GAZE_MARKER = "JASMINES_GAZE_MARKER";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        effect.player.marker.addMarker(this.JASMINES_GAZE_MARKER, this);
      }
      if (effect instanceof PutDamageEffect) {
        const player = StateUtils.findOwner(state, StateUtils.findCardList(state, this));
        const hasMarker = player.marker.hasMarker(this.JASMINES_GAZE_MARKER, this);
        if (hasMarker) {
          effect.damage -= 30;
        }
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        StateUtils.getOpponent(state, effect.player).marker.removeMarker(this.JASMINES_GAZE_MARKER);
      }
      return state;
    }
  };

