  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-surging-sparks/quaquaval.ts
  init_game();
  init_game_phase_effects();
  init_prefabs();
  var Quaquaval = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Quaxwell";
      this.cardType = [W];
      this.hp = 170;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Up-Tempo",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "You must put a card from your hand on the bottom of your deck in order to use this Ability. Once during your turn, you may draw cards until you have 5 cards in your hand."
      }];
      this.attacks = [
        {
          name: "Hydro Splash",
          cost: [W, C],
          damage: 120,
          text: ""
        }
      ];
      this.regulationMark = "H";
      this.set = "SSP";
      this.setNumber = "52";
      this.cardImage = "assets/cardback.png";
      this.name = "Quaquaval";
      this.fullName = "Quaquaval SSP";
      this.UP_TEMPO_MARKER = "UP_TEMPO_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (this.marker.hasMarker(this.UP_TEMPO_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.hand.cards.length > 5 || player.hand.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          {},
          { allowCancel: false, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          ABILITY_USED(player, this);
          this.marker.addMarker(this.UP_TEMPO_MARKER, this);
          player.marker.addMarker(this.UP_TEMPO_MARKER, this);
          MOVE_CARDS(store, state, player.hand, player.deck, { cards, sourceCard: this });
          while (player.hand.cards.length < 5) {
            MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
          }
        });
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.UP_TEMPO_MARKER, this)) {
        effect.player.marker.removeMarker(this.UP_TEMPO_MARKER, this);
        this.marker.removeMarker(this.UP_TEMPO_MARKER, this);
      }
      return state;
    }
  };

