  var Rotom13 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 80;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Crushing Pulse",
          cost: [L],
          damage: 0,
          text: "Your opponent reveals their hand. Discard all Item cards and Pok\xE9mon Tool cards you find there."
        },
        {
          name: "Energy Short",
          cost: [L],
          damage: 20,
          damageCalculation: "x",
          text: "This attack does 20 damage for each Energy attached to your opponent's Active Pok\xE9mon."
        }
      ];
      this.set = "SSP";
      this.regulationMark = "H";
      this.setNumber = "61";
      this.cardImage = "assets/cardback.png";
      this.name = "Rotom";
      this.fullName = "Rotom SSP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        const escrow = new CardList();
        store.prompt(state, new ShowCardsPrompt(
          player.id,
          GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
          opponent.hand.cards
        ), () => {
          opponent.hand.cards.forEach((card) => {
            if (card instanceof TrainerCard && (card.trainerType === 0 /* ITEM */ || card.trainerType === 3 /* TOOL */)) {
              MOVE_CARDS(store, state, opponent.hand, escrow, { cards: [card], sourceCard: this });
            }
          });
          MOVE_CARDS(store, state, escrow, opponent.discard, { sourceCard: this });
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const opponent = effect.opponent;
        const opponentProvidedEnergy = new CheckProvidedEnergyEffect(opponent);
        store.reduceEffect(state, opponentProvidedEnergy);
        const opponentEnergyCount = opponentProvidedEnergy.energyMap.reduce((left, p) => left + p.provides.length, 0);
        effect.damage = opponentEnergyCount * 20;
      }
      return state;
    }
  };

