  init_game_effects();
  init_prefabs();
  var Skeledirge = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Crocalor";
      this.cardType = [2 /* FIRE */];
      this.hp = 180;
      this.weakness = [{ type: 3 /* WATER */ }];
      this.resistance = [];
      this.retreat = [9 /* COLORLESS */, 9 /* COLORLESS */, 9 /* COLORLESS */];
      this.powers = [{
        name: "Unaware",
        powerType: 2 /* ABILITY */,
        text: "Prevent all effects of attacks used by your opponent's Pok\xE9mon done to this Pok\xE9mon. (Damage is not an effect.) "
      }];
      this.attacks = [{
        name: "Torcherto",
        cost: [2 /* FIRE */, 9 /* COLORLESS */],
        damage: 60,
        text: "This attack does 20 more damage for each Benched Pok\xE9mon (both yours and your opponent's)."
      }];
      this.regulationMark = "H";
      this.set = "SSP";
      this.setNumber = "31";
      this.cardImage = "assets/cardback.png";
      this.name = "Skeledirge";
      this.fullName = "Skeledirge SSP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const playerBenched = player.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        const opponentBenched = opponent.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        const totalBenched = playerBenched + opponentBenched;
        effect.damage = 60 + totalBenched * 20;
      }
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        const sourceCard = effect.source.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (sourceCard) {
          try {
            const player = StateUtils.findOwner(state, effect.target);
            const stub = new PowerEffect(player, {
              name: "test",
              powerType: 2 /* ABILITY */,
              text: ""
            }, this);
            store.reduceEffect(state, stub);
          } catch {
            return state;
          }
          if (effect instanceof ApplyWeaknessEffect) {
            return state;
          }
          if (effect instanceof PutDamageEffect) {
            return state;
          }
          if (effect instanceof DealDamageEffect) {
            return state;
          }
          effect.preventDefault = true;
        }
      }
      return state;
    }
  };

