  var Sylveonex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Eevee";
      this._tags = ["ex" /* POKEMON_ex */, "Tera" /* POKEMON_TERA */];
      this.cardType = [P];
      this.hp = 270;
      this.weakness = [{ type: M }];
      this.retreat = [C, C];
      this.ANGELITE_MARKER = "ANGELITE_MARKER";
      this.CLEAR_ANGELITE_MARKER = "CLEAR_ANGELITE_MARKER";
      this.attacks = [
        {
          name: "Magical Charm",
          cost: [P, C, C],
          damage: 160,
          text: "During your opponent's next turn, the Defending Pokemon's attacks do 100 less damage (before applying Weakness and Resistance)."
        },
        {
          name: "Angelite",
          cost: [W, L, P],
          damage: 0,
          text: "Choose 2 of your opponent's Benched Pok\xE9mon. They shuffle those Pok\xE9mon and all attached cards into their deck. If 1 of your Pok\xE9mon used Angelite during your last turn, this attack can't be used."
        }
      ];
      this.regulationMark = "H";
      this.set = "SSP";
      this.setNumber = "86";
      this.cardImage = "assets/cardback.png";
      this.name = "Sylveon ex";
      this.fullName = "Sylveon ex SSP";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.CLEAR_ANGELITE_MARKER, this)) {
        effect.player.marker.removeMarker(this.ANGELITE_MARKER, this);
        effect.player.marker.removeMarker(this.CLEAR_ANGELITE_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.ANGELITE_MARKER, this)) {
        effect.player.marker.addMarker(this.CLEAR_ANGELITE_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return DEFENDING_POKEMON_DOES_LESS_DAMAGE(store, state, effect, this, 100);
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBench = opponent.bench.some((b) => b.cards.length > 0);
        if (hasBench === false) {
          return state;
        }
        if (effect.player.marker.hasMarker(this.ANGELITE_MARKER, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        effect.player.marker.addMarker(this.ANGELITE_MARKER, this);
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 2, allowCancel: false }
          ),
          (selected) => {
            const targets = selected || [];
            player.marker.addMarker(this.ANGELITE_MARKER, this);
            targets.forEach((target) => {
              MOVE_CARDS(store, state, target, opponent.deck, { sourceCard: this });
              return store.prompt(state, new ShuffleDeckPrompt(opponent.id), (order) => {
                opponent.deck.applyOrder(order);
              });
            });
          }
        );
      }
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (effect.target === player.active || effect.target === opponent.active) {
          return state;
        }
        effect.preventDefault = true;
      }
      return state;
    }
  };

