  var Tatsugiriex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["ex" /* POKEMON_ex */, "Tera" /* POKEMON_TERA */];
      this.regulationMark = "H";
      this.cardType = [N];
      this.hp = 160;
      this.weakness = [];
      this.resistance = [];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Surprise Pump",
          cost: [R, W],
          damage: 100,
          shredAttack: true,
          text: "This attack's damage isn't affected by any effects on your opponent's Active Pok\xE9mon."
        },
        {
          name: "Cinnabar Lure",
          cost: [R, W, D],
          damage: 0,
          text: "Look at the top 10 cards of your deck. You may put any number of Pok\xE9mon you find there onto your Bench. Shuffle the other cards back into your deck."
        }
      ];
      this.set = "SSP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "142";
      this.name = "Tatsugiri ex";
      this.fullName = "Tatsugiri ex SSP";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const applyWeakness = new ApplyWeaknessEffect(effect, 100);
        store.reduceEffect(state, applyWeakness);
        const damage = applyWeakness.damage;
        effect.damage = 0;
        if (damage > 0) {
          opponent.active.damage += damage;
          const afterDamage = new AfterDamageEffect(effect, damage);
          state = store.reduceEffect(state, afterDamage);
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const openSlots = player.bench.filter((b) => b.cards.length === 0);
        if (openSlots.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const maxPokemons = openSlots.length;
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: 10, sourceCard: this });
        let cards = [];
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            deckTop,
            { superType: 1 /* POKEMON */ },
            { min: 0, max: maxPokemons, allowCancel: false }
          ),
          (selectedCards) => {
            cards = selectedCards || [];
            cards.forEach((card, index) => {
              MOVE_CARDS(store, state, deckTop, openSlots[index], { cards: [card], sourceCard: this });
              openSlots[index].pokemonPlayedTurn = state.turn;
            });
            MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: this });
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (effect.target === player.active || effect.target === opponent.active) {
          return state;
        }
        effect.preventDefault = true;
      }
      return state;
    }
  };

