  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-surging-sparks/tera-orb.ts
  init_trainer_card();
  init_card_types();
  init_play_card_effects();
  init_choose_cards_prompt();
  init_show_cards_prompt();
  init_shuffle_prompt();
  init_game_message();
  init_game();
  init_prefabs();
  function* playCard264(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (card instanceof PokemonCard && !card.hasTag("Tera" /* POKEMON_TERA */)) {
        blocked.push(index);
      }
    });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 1 /* POKEMON */ },
        { min: 0, max: 1, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: effect.trainerCard });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var TeraOrb = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.regulationMark = "H";
      this.set = "SSP";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "189";
      this.name = "Tera Orb";
      this.fullName = "Tera Orb SSP";
      this.text = "Search your deck for a Tera Pok\xE9mon, reveal it, and put it into your hand. Then, shuffle your deck.";
    }
    canPlay(store, state, player) {
      if (player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard264(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

