  var Togekiss6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Togetic";
      this.cardType = [P];
      this.hp = 140;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.powers = [{
        name: "Wonder Kiss",
        powerType: 2 /* ABILITY */,
        text: "Whenever your opponent's Active Pok\xE9mon gets Knocked Out, flip a coin. If heads, take 1 more Prize card for that Knock Out. This Ability does not stack."
      }];
      this.attacks = [{
        name: "Speed Wing",
        cost: [C, C, C],
        damage: 140,
        text: ""
      }];
      this.regulationMark = "H";
      this.set = "SSP";
      this.setNumber = "72";
      this.cardImage = "assets/cardback.png";
      this.name = "Togekiss";
      this.fullName = "Togekiss SSP";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target === effect.player.active) {
        const knockedOutOwner = effect.player;
        const attacker = StateUtils.getOpponent(state, knockedOutOwner);
        const isInPlay = attacker.active.cards.includes(this) || attacker.bench.some((b) => b.cards.includes(this));
        if (!isInPlay) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */ || state.players[state.activePlayer] !== attacker) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, attacker, this)) {
          return state;
        }
        if (knockedOutOwner.marker.hasMarker("TOGEKISS_KNOCKOUT_FLIP")) {
          return state;
        }
        knockedOutOwner.marker.addMarkerToState("TOGEKISS_KNOCKOUT_FLIP");
        return COIN_FLIP_PROMPT(store, state, attacker, (result) => {
          if (result === true) {
            if (effect.prizeCount > 0) {
              effect.prizeCount += 1;
            }
          }
          knockedOutOwner.marker.removeMarker("TOGEKISS_KNOCKOUT_FLIP");
        });
      }
      return state;
    }
  };

