  function* playCard265(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let isPokemonInHand = false;
    player.hand.cards.forEach((card) => {
      if (card instanceof PokemonCard) {
        isPokemonInHand = true;
      }
    });
    if (!isPokemonInHand) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    if (player.supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    const options = [{ value: 10, message: "10" }];
    for (let i = 2; i <= 50; i++) {
      options.push({ value: 10 * i, message: "" + 10 * i });
    }
    const selectedPokemon = new CardList();
    let pokemonName = "";
    let pokemonHP = 0;
    return store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.hand,
        { superType: 1 /* POKEMON */ },
        { min: 1, max: 1, allowCancel: false }
      ),
      (selected) => {
        selected.forEach((card) => {
          if (card instanceof PokemonCard) {
            pokemonName = card.name;
            pokemonHP = card.hp;
            MOVE_CARDS(store, state, player.hand, selectedPokemon, {
              cards: [card],
              sourceCard: self
            });
          }
        });
        store.log(state, "LOG_PLAYER_CHOOSES" /* LOG_PLAYER_CHOOSES */, { name: player.name, string: pokemonName });
        return store.prompt(
          state,
          new SelectPrompt(
            opponent.id,
            GameMessage.CHOOSE_OPTION,
            options.map((c) => c.message),
            { allowCancel: false }
          ),
          (choice) => {
            const option = options[choice];
            const revealed = [...selectedPokemon.cards];
            if (option.value === pokemonHP) {
              MOVE_CARDS(store, state, opponent.deck, opponent.hand, {
                count: 4,
                sourceCard: self
              });
            } else {
              MOVE_CARDS(store, state, player.deck, player.hand, { count: 4, sourceCard: self });
            }
            MOVE_CARDS(store, state, selectedPokemon, player.hand, { sourceCard: self });
            store.prompt(
              state,
              new ShowCardsPrompt(
                opponent.id,
                GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
                revealed
              ),
              () => {
              }
            );
            MOVE_CARDS(store, state, player.supporter, player.discard, { sourceCard: self });
          }
        );
      }
    );
  }
