  var Amarys = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "PRE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "93";
      this.regulationMark = "H";
      this.name = "Amarys";
      this.fullName = "Amarys PRE";
      this.AMARYS_USED_MARKER = "AMARYS_USED_MARKER";
      this.text = "Draw 4 cards. At the end of this turn, if you have 5 or more cards in your hand, discard your hand.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        DRAW_CARDS(store, state, effect.player, 4);
        ADD_MARKER(this.AMARYS_USED_MARKER, effect.player, this);
      }
      if (effect instanceof EndTurnEffect && HAS_MARKER(this.AMARYS_USED_MARKER, effect.player, this)) {
        const hand = effect.player.hand;
        const discard = effect.player.discard;
        if (hand.cards.length >= 5)
          MOVE_CARDS(store, state, hand, discard, { cards: hand.cards, sourceCard: this });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.AMARYS_USED_MARKER, this);
      return state;
    }
  };

