  var Bronzong12 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Bronzor";
      this.hp = 130;
      this.cardType = [M];
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Protective Bell",
        powerType: 2 /* ABILITY */,
        text: "All of your Pok\xE9mon take 10 less damage from attacks from your opponent's Pok\xE9mon (after applying Weakness and Resistance)."
      }];
      this.attacks = [{
        name: "Heavy Impact",
        cost: [M, C],
        damage: 50,
        text: ""
      }];
      this.regulationMark = "H";
      this.set = "PRE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "67";
      this.name = "Bronzong";
      this.fullName = "Bronzong PRE";
    }
    reduceEffect(store, state, effect) {
      if ((effect instanceof DealDamageEffect || effect instanceof PutDamageEffect) && state.phase === 3 /* ATTACK */) {
        const defender = StateUtils.findOwner(state, effect.target);
        const attacker = StateUtils.findOwner(state, effect.source);
        if (attacker === defender) {
          return state;
        }
        if (!StateUtils.isPokemonInPlay(defender, this)) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, defender, this)) {
          return state;
        }
        effect.damage = Math.max(0, effect.damage - 10);
      }
      return state;
    }
  };

