  function* playCard266(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.discard, { sourceCard: self });
    let pokemons = 0;
    let supporters = 0;
    let energies = 0;
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      if (c instanceof PokemonCard) {
        pokemons += 1;
      } else if (c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */) {
        supporters += 1;
      } else if (c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */) {
        energies += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxPokemons = Math.min(pokemons, 1);
    const maxSupporters = Math.min(supporters, 1);
    const maxEnergies = Math.min(energies, 1);
    const count = maxPokemons + maxSupporters + maxEnergies;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARDS,
        player.deck,
        {},
        { min: 0, max: count, allowCancel: false, blocked, maxPokemons, maxSupporters, maxEnergies }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    cards.forEach((card, index) => {
      store.log(state, "LOG_PLAYER_PUTS_CARD_IN_HAND" /* LOG_PLAYER_PUTS_CARD_IN_HAND */, { name: player.name, card: card.name });
    });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var LarrysSkill = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "H";
      this.set = "PRE";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "115";
      this.name = "Larry's Skill";
      this.fullName = "Larry's Skill PRE";
      this.text = "Discard your hand and search your deck for a Pok\xE9mon, a Supporter card, and a Basic Energy card, reveal them, and put them into your hand. Then, shuffle your deck.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard266(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

