  var Blazikenex2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["ex" /* POKEMON_ex */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Combusken";
      this.cardType = [R];
      this.hp = 320;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Seething Spirit",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may attach a Basic Energy card from your discard pile to 1 of your Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Burning Assault",
          cost: [R, C],
          damage: 200,
          text: "During your next turn, this Pokemon can't attack."
        }
      ];
      this.regulationMark = "H";
      this.set = "JTG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "24";
      this.name = "Blaziken ex";
      this.fullName = "Blaziken ex JTG";
      this.OVERFLOWING_SPIRIT_MARKER = "OVERFLOWING_SPIRIT_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect) {
        const player = effect.player;
        player.marker.removeMarker(this.OVERFLOWING_SPIRIT_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */;
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.OVERFLOWING_SPIRIT_MARKER, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_ACTIVE,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: 1, max: 1 }
          ),
          (transfers) => {
            transfers = transfers || [];
            player.marker.addMarker(this.OVERFLOWING_SPIRIT_MARKER, this);
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList.getPokemonCard() === this) {
                cardList.addBoardEffect(0 /* ABILITY_USED */);
              }
            });
            if (transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
            return state;
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_POKEMON_CANNOT_ATTACK_NEXT_TURN(effect.player);
      }
      return state;
    }
  };

