  function* playCard270(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    const supporterTurn = player.supporterTurn;
    if (supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    effect.preventDefault = true;
    let basics = 0;
    let evolutions = 0;
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      if (c instanceof PokemonCard && c.stage === 2 /* BASIC */) {
        basics += 1;
      } else if (c instanceof PokemonCard && c.stage !== 2 /* BASIC */) {
        evolutions += 1;
      } else {
        blocked.push(index);
      }
    });
    const maxBasics = Math.min(basics, 2);
    const maxEvolutions = Math.min(evolutions, 1);
    const count = maxBasics + maxEvolutions;
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        {},
        { min: 0, max: count, allowCancel: false, blocked, maxBasics, maxEvolutions }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var BrocksScouting = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "I";
      this.set = "JTG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "146";
      this.name = "Brock's Scouting";
      this.fullName = "Brock's Scouting JTG";
      this.text = "Search your deck for up to 2 Basic Pok\xE9mon or 1 Evolution Pok\xE9mon, reveal them, and put them into your hand. Then, shuffle your deck.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard270(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

