  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-journey-together/hops-bag.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_prefabs();
  init_play_card_effects();
  var HopsBag = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "JTG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "147";
      this.regulationMark = "I";
      this.name = "Hop's Bag";
      this.fullName = "Hop's Bag JTG";
      this.text = "Search your deck for up to 2 Basic Hop's Pok\xE9mon and put them onto your Bench. Then, shuffle your deck.";
    }
    canPlay(store, state, player) {
      if (player.deck.cards.length === 0) {
        return false;
      }
      const openSlots = player.bench.filter((b) => b.cards.length === 0);
      if (openSlots.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        const slots2 = player.bench.filter((b) => b.cards.length === 0);
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const openSlots = player.bench.filter((b) => b.cards.length === 0);
        if (openSlots.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked = player.deck.cards.filter((c) => !c.hasTag("Hop's" /* HOPS */)).map((c) => player.deck.cards.indexOf(c));
        effect.preventDefault = true;
        const maxCards = Math.min(2, openSlots.length);
        let cards = [];
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            player.deck,
            { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
            { min: 0, max: maxCards, allowCancel: false, blocked }
          ),
          (selectedCards) => {
            cards = selectedCards || [];
            cards.forEach((card, index) => {
              store.reduceEffect(
                state,
                new PlayPokemonFromDeckEffect(player, card, slots2[index])
              );
            });
            MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [this], sourceCard: this });
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
              return state;
            });
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-journey-together/hops-choice-band.ts
  init_trainer_card();
  init_card_types();
  init_state_utils();
  init_attack_effects();
  init_check_effects();
  init_play_card_effects();
  var HopsChoiceBand = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this._tags = ["Hop's" /* HOPS */];
      this.set = "JTG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "148";
      this.regulationMark = "I";
      this.name = "Hop's Choice Band";
      this.fullName = "Hop's Choice Band JTG";
      this.text = "Attacks used by the Hop's Pok\xE9mon this card is attached to cost [C] less and do 30 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect && effect.player.active.tools.includes(this)) {
        const index = effect.cost.indexOf(9 /* COLORLESS */);
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        if (index === -1) {
          return state;
        }
        const hopsPokemon = effect.player.active.getPokemonCard();
        if (hopsPokemon && hopsPokemon.hasTag("Hop's" /* HOPS */)) {
          effect.cost.splice(index, 1);
        }
        return state;
      }
      if (effect instanceof DealDamageEffect && effect.source.tools.includes(this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        if (effect.target !== opponent.active) return state;
        const sourceCard = effect.source.getPokemonCard();
        if (sourceCard && sourceCard.hasTag("Hop's" /* HOPS */)) {
          effect.damage += 30;
        }
      }
      return state;
    }
  };

