  init_pokemon_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_prefabs();
  function* useCallForFamily18(next, store, state, effect) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    const max = Math.min(slots2.length);
    if (max === 0) {
      return state;
    }
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (card instanceof PokemonCard && !card.hasTag("Lillie's" /* LILLIES */)) {
        blocked.push(index);
      }
    });
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
        player.deck,
        { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
        { min: 0, max, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length > slots2.length) {
      cards.length = slots2.length;
    }
    cards.forEach((card, index) => {
      store.reduceEffect(
        state,
        new PlayPokemonFromDeckEffect(player, card, slots2[index])
      );
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
