  var Maractus8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 110;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Explosive Needle",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon is in the Active Spot and is Knocked Out by damage from an attack from your opponent's Pok\xE9mon, put 6 damage counters on the Attacking Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Corner",
        cost: [C],
        damage: 20,
        text: "During your opponent's next turn, the Defending Pok\xE9mon can't retreat."
      }];
      this.set = "JTG";
      this.regulationMark = "I";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "8";
      this.name = "Maractus";
      this.fullName = "Maractus JTG";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const player = StateUtils.findOwner(state, effect.target);
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this || state.phase !== 3 /* ATTACK */ || IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkHpEffect = new CheckHpEffect(player, effect.target);
        store.reduceEffect(state, checkHpEffect);
        const currentHp = checkHpEffect.hp - effect.target.damage;
        if (effect.damage >= currentHp) {
          effect.source.damage += 60;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        return BLOCK_RETREAT(store, state, effect, this);
      }
      return state;
    }
  };

