  var Postwick = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "JTG";
      this.name = "Postwick";
      this.fullName = "Postwick JTG";
      this.regulationMark = "I";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "154";
      this.text = "The attacks of Hop's Pok\xE9mon (both yours and your opponent's) do 30 more damage to the opponent's Active Pok\xE9mon (before applying Weakness and Resistance).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && StateUtils.getStadiumCard(state) === this) {
        const owner = StateUtils.findOwner(state, effect.target);
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, effect.target, this)) {
          return state;
        }
        if (effect.target !== opponent.active) {
          return state;
        }
        if (!effect.source.getPokemonCard()?.hasTag("Hop's" /* HOPS */)) {
          return state;
        }
        effect.damage += 30;
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

