  var Regirock7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 130;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Metal Shield",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon has any Energy attached, it takes 30 less damage from attacks (after applying Weakness and Resistance)."
      }];
      this.attacks = [{
        name: "Buster Lariat",
        cost: [F, F, F],
        damage: 120,
        text: "This attack's damage isn't affected by Resistance."
      }];
      this.set = "JTG";
      this.regulationMark = "I";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "82";
      this.name = "Regirock";
      this.fullName = "Regirock JTG";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        const player = StateUtils.findOwner(state, effect.target);
        if (pokemonCard !== this || state.phase !== 3 /* ATTACK */ || IS_ABILITY_BLOCKED(store, state, player, this))
          return state;
        const cardList = StateUtils.findCardList(state, this);
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
        state = store.reduceEffect(state, checkProvidedEnergy);
        if (checkProvidedEnergy.energyMap.length > 0)
          effect.damage = Math.max(0, effect.damage - 30);
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this))
        effect.ignoreResistance = true;
      return state;
    }
  };

