  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-destined-rivals/mistys-psyduck.ts
  init_game();
  init_prefabs();
  var MistysPsyduck = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Misty's" /* MISTYS */];
      this.cardType = [W];
      this.hp = 50;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Slapstick Jump",
          powerType: 2 /* ABILITY */,
          useWhenInPlay: true,
          text: "Once during your turn, if this Pok\xE9mon is on your Bench, you may discard the bottom card of your deck. If you do, discard all cards attached to this Pok\xE9mon and put it on top of your deck."
        }
      ];
      this.attacks = [{ name: "Sprinkle Water", cost: [W], damage: 30, text: "" }];
      this.set = "DRI";
      this.regulationMark = "I";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "45";
      this.name = "Misty's Psyduck";
      this.fullName = "Misty's Psyduck DRI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_IF_DECK_EMPTY(player);
        const cardList = StateUtils.findCardList(state, this);
        if (player.active.cards.includes(this) || opponent.active.cards.includes(this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        MOVE_CARDS(store, state, player.deck, player.discard, { cards: GET_CARDS_ON_BOTTOM_OF_DECK(player, 1), sourceCard: this });
        const psyduckCard = cardList.getPokemonCard();
        if (!psyduckCard) {
          return state;
        }
        const otherCards = cardList.cards.filter(
          (card) => !(card instanceof PokemonCard) && !cardList.getPokemons().includes(card) && (!cardList.tools || !cardList.tools.includes(card))
        );
        const tools = [...cardList.tools];
        if (tools.length > 0) {
          for (const tool of tools) {
            MOVE_CARDS(store, state, cardList, player.discard, { cards: [tool], sourceCard: this });
          }
        }
        if (otherCards.length > 0) {
          MOVE_CARDS(store, state, cardList, player.discard, { cards: otherCards });
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, cardList, deckTop, { cards: [psyduckCard] });
        MOVE_CARDS(store, state, deckTop, player.deck, { toTop: true });
        cardList.clearEffects();
      }
      return state;
    }
  };

