  var TeamRocketsArcher = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this._tags = ["Team Rocket's" /* TEAM_ROCKET */];
      this.regulationMark = "I";
      this.set = "DRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "170";
      this.name = "Team Rocket's Archer";
      this.fullName = "Team Rocket's Archer DRI";
      this.text = "You can use this card only if any of your Team Rocket's Pokemon were Knocked Out during your opponent's last turn.\n\nEach player shuffles their hand into their deck. Then, you draw 5 cards, and your opponent draws 3 cards.";
      this.ARCHER_MARKER = "ARCHER_MARKER";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (!player.marker.hasMarker(this.ARCHER_MARKER)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        player.rocketSupporter = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        const cards = player.hand.cards.filter((c) => c !== this);
        const playerMoveEffect = new MoveCardsEffect(player.hand, player.deck, {
          cards,
          sourceCard: this
        });
        state = store.reduceEffect(state, playerMoveEffect);
        const opponentMoveEffect = new MoveCardsEffect(opponent.hand, opponent.deck, {
          sourceCard: this
        });
        state = store.reduceEffect(state, opponentMoveEffect);
        if (!opponentMoveEffect.preventDefault) {
          SHUFFLE_DECK(store, state, opponent);
          DRAW_CARDS(store, state, opponent, 3);
        }
        SHUFFLE_DECK(store, state, player);
        DRAW_CARDS(store, state, player, 5);
      }
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const duringTurn = [2 /* PLAYER_TURN */, 3 /* ATTACK */].includes(state.phase);
        if (!duringTurn || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        const knockedOutPokemon = effect.target.getPokemonCard();
        if (knockedOutPokemon && knockedOutPokemon.hasTag("Team Rocket's" /* TEAM_ROCKET */)) {
          effect.player.marker.addMarker(this.ARCHER_MARKER, this);
        }
        return state;
      }
      REMOVE_OPPONENT_LAST_TURN_MARKER_AT_END_OF_TURN(effect, this.ARCHER_MARKER, this);
      if (effect instanceof EndTurnEffect && effect.player.rocketSupporter) {
        effect.player.rocketSupporter = false;
      }
      return state;
    }
  };

