  var TeamRocketsAriana = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this._tags = ["Team Rocket's" /* TEAM_ROCKET */];
      this.regulationMark = "I";
      this.set = "DRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "171";
      this.name = "Team Rocket's Ariana";
      this.fullName = "Team Rocket's Ariana DRI";
      this.text = "Draw cards until you have 5 cards in your hand. If all of your Pok\xE9mon in play are Team Rocket's Pokemon, draw cards until you have 8 cards in your hand instead.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        player.rocketSupporter = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        let allTeamRocket = true;
        let hasPokemon = false;
        if (player.active.cards.length > 0) {
          hasPokemon = true;
          const activePokemon = player.active.getPokemonCard();
          if (!activePokemon || !activePokemon.hasTag("Team Rocket's" /* TEAM_ROCKET */)) {
            allTeamRocket = false;
          }
        }
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (cardList !== player.active && card instanceof PokemonCard) {
            hasPokemon = true;
            if (!card.hasTag("Team Rocket's" /* TEAM_ROCKET */)) {
              allTeamRocket = false;
            }
          }
        });
        const targetHandSize = hasPokemon && allTeamRocket ? 8 : 5;
        while (player.hand.cards.length < targetHandSize) {
          if (player.deck.cards.length === 0) {
            break;
          }
          MOVE_CARDS(store, state, player.deck, player.hand, { count: 1, sourceCard: this });
        }
        return state;
      }
      if (effect instanceof EndTurnEffect && effect.player.rocketSupporter) {
        effect.player.rocketSupporter = false;
      }
      return state;
    }
  };

