  var TeamRocketsGiovanni = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this._tags = ["Team Rocket's" /* TEAM_ROCKET */];
      this.regulationMark = "I";
      this.set = "DRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "174";
      this.name = "Team Rocket's Giovanni";
      this.fullName = "Team Rocket's Giovanni DRI";
      this.text = "Switch your Active Team Rocket's Pokemon with 1 of your Benched Team Rocket's Pokemon. If you do, switch in 1 of your opponent's Benched Pok\xE9mon to the Active Spot.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      const opponent = StateUtils.getOpponent(state, player);
      const activePokemon = player.active.getPokemonCard();
      if (!activePokemon || !activePokemon.hasTag("Team Rocket's" /* TEAM_ROCKET */)) {
        return false;
      }
      let teamRocketBenchCount = 0;
      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
        if (target.slot === 2 /* BENCH */ && card.hasTag("Team Rocket's" /* TEAM_ROCKET */)) {
          teamRocketBenchCount++;
        }
      });
      if (teamRocketBenchCount === 0) {
        return false;
      }
      const benchCount = opponent.bench.reduce((sum, b) => sum + (b.cards.length > 0 ? 1 : 0), 0);
      if (benchCount === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        player.rocketSupporter = true;
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        const activePokemon = player.active.getPokemonCard();
        if (!activePokemon || !activePokemon.hasTag("Team Rocket's" /* TEAM_ROCKET */)) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked = [];
        let teamRocketBenchCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (target.slot === 2 /* BENCH */) {
            if (!card.hasTag("Team Rocket's" /* TEAM_ROCKET */)) {
              blocked.push(target);
            } else {
              teamRocketBenchCount++;
            }
          }
        });
        if (teamRocketBenchCount === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const benchCount = opponent.bench.reduce((sum, b) => {
          return sum + (b.cards.length > 0 ? 1 : 0);
        }, 0);
        if (benchCount === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_SWITCH,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            {
              allowCancel: false,
              blocked
            }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return state;
            }
            player.active.clearEffects();
            player.switchPokemon(targets[0]);
            return store.prompt(
              state,
              new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_SWITCH,
                1 /* TOP_PLAYER */,
                [2 /* BENCH */],
                { allowCancel: false }
              ),
              (oppTargets) => {
                if (!oppTargets || oppTargets.length === 0) {
                  return state;
                }
                opponent.active.clearEffects();
                opponent.switchPokemon(oppTargets[0]);
                return state;
              }
            );
          }
        );
      }
      if (effect instanceof EndTurnEffect && effect.player.rocketSupporter) {
        effect.player.rocketSupporter = false;
      }
      return state;
    }
  };

