  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-destined-rivals/ethans-cyndaquil.ts
  init_pokemon_card();
  init_card_types();
  init_prefabs();
  var EthansCyndaquil = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Ethan's" /* ETHANS */];
      this.cardType = [R];
      this.hp = 70;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Ember",
          cost: [R],
          damage: 30,
          text: "Discard an Energy from this Pok\xE9mon."
        }
      ];
      this.regulationMark = "I";
      this.set = "DRI";
      this.setNumber = "32";
      this.cardImage = "assets/cardback.png";
      this.name = "Ethan's Cyndaquil";
      this.fullName = "Ethan's Cyndaquil DRI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-destined-rivals/ethans-magcargo.ts
  init_game();
  init_attack_effects();
  init_check_effects();
  init_prefabs();
  var EthansMagcargo = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Ethan's Slugma";
      this._tags = ["Ethan's" /* ETHANS */];
      this.cardType = [R];
      this.hp = 130;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "Melt and Flow",
          powerType: 2 /* ABILITY */,
          text: "If this Pok\xE9mon has no Energy attached, it has no Retreat Cost."
        }
      ];
      this.attacks = [
        {
          name: "Lava Burst",
          cost: [R, R, R],
          damage: 70,
          damageCalculation: "x",
          text: "Discard up to 5 [R] Energy from this Pok\xE9mon. This attack does 70 damage for each card you discarded in this way."
        }
      ];
      this.regulationMark = "I";
      this.set = "DRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "36";
      this.name = "Ethan's Magcargo";
      this.fullName = "Ethan's Magcargo DRI";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect && effect.player.active.cards.includes(this)) {
        const player = effect.player;
        if (!IS_ABILITY_BLOCKED(store, state, player, this)) {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
          state = store.reduceEffect(state, checkProvidedEnergy);
          if (checkProvidedEnergy.energyMap.length === 0) {
            effect.cost = [];
          }
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        state = store.prompt(
          state,
          new DiscardEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */],
            // Card source is target Pokemon
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
            { min: 0, max: 5, allowCancel: false }
          ),
          (energy2) => {
            const cards = (energy2 || []).map((e) => e.card);
            const discardEnergy2 = new DiscardCardsEffect(effect, cards);
            discardEnergy2.target = player.active;
            state = store.reduceEffect(state, discardEnergy2);
            effect.damage = 70 * cards.length;
            return state;
          }
        );
      }
      return state;
    }
  };

