  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-destined-rivals/ethans-quilava.ts
  init_game();
  init_prefabs();
  var EthansQuilava = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Ethan's Cyndaquil";
      this._tags = ["Ethan's" /* ETHANS */];
      this.cardType = [R];
      this.hp = 100;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Adventure Bound",
          powerType: 2 /* ABILITY */,
          useWhenInPlay: true,
          text: "Once during your turn, you may search your deck for a Ethan's Adventure, reveal it, and put it into your hand. Then, shuffle your deck."
        }
      ];
      this.attacks = [
        {
          name: "Combustion",
          cost: [R],
          damage: 40,
          text: ""
        }
      ];
      this.regulationMark = "I";
      this.set = "DRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "33";
      this.name = "Ethan's Quilava";
      this.fullName = "Ethan's Quilava DRI";
      this.ADVENTURE_BOUND_MARKER = "ADVENTURE_BOUND";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        BLOCK_EFFECT_IF_MARKER(this.ADVENTURE_BOUND_MARKER, player, this);
        BLOCK_IF_DECK_EMPTY(player);
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            { name: "Ethan's Adventure" },
            { min: 0, max: 1 }
          ),
          (cards) => {
            if (!cards || cards.length === 0) {
              SHUFFLE_DECK(store, state, player);
              return state;
            }
            MOVE_CARDS(store, state, player.deck, player.hand, {
              cards,
              sourceCard: this,
              sourceEffect: this.powers[0]
            });
            SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
            ADD_MARKER(this.ADVENTURE_BOUND_MARKER, player, this);
            ABILITY_USED(player, this);
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.ADVENTURE_BOUND_MARKER, this);
      return state;
    }
  };

