  var CynthiasGabite = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Cynthia's Gible";
      this._tags = ["Cynthia's" /* CYNTHIAS */];
      this.cardType = [F];
      this.hp = 100;
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Champion's Call",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may search your deck for a Cynthia's Pok\xE9mon, reveal it, and put it into your hand. Then, shuffle your deck."
        }
      ];
      this.attacks = [
        {
          name: "Dragon Slice",
          cost: [F],
          damage: 40,
          text: ""
        }
      ];
      this.regulationMark = "I";
      this.set = "DRI";
      this.setNumber = "103";
      this.cardImage = "assets/cardback.png";
      this.name = "Cynthia's Gabite";
      this.fullName = "Cynthia's Gabite DRI";
      this.CHAMPIONS_CALL_MARKER = "CHAMPIONS_CALL_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        REMOVE_MARKER(this.CHAMPIONS_CALL_MARKER, effect.player, this);
      }
      if (effect instanceof EndTurnEffect && HAS_MARKER(this.CHAMPIONS_CALL_MARKER, effect.player, this)) {
        REMOVE_MARKER(this.CHAMPIONS_CALL_MARKER, effect.player, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (HAS_MARKER(this.CHAMPIONS_CALL_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        ABILITY_USED(player, this);
        const blocked = [];
        player.deck.cards.forEach((card, index) => {
          if (card instanceof PokemonCard && !card.hasTag("Cynthia's" /* CYNTHIAS */)) {
            blocked.push(index);
          }
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            { superType: 1 /* POKEMON */ },
            { min: 0, max: 1, allowCancel: false, blocked }
          ),
          (cards) => {
            if (cards.length > 0) {
              MOVE_CARDS(store, state, player.deck, player.hand, {
                cards,
                sourceCard: this,
                sourceEffect: this.powers[0]
              });
              SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
            }
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
              ADD_MARKER(this.CHAMPIONS_CALL_MARKER, player, this);
            });
          }
        );
      }
      return state;
    }
  };

