  var Zeraora8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 100;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Scratch",
          cost: [C],
          damage: 20,
          text: ""
        },
        {
          name: "Thunder Blitz",
          cost: [L, L, L],
          damage: 0,
          text: "Discard all Energy from this Pok\xE9mon. This attack does 210 damage to 1 of your opponent's Benched ex Pokemon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.regulationMark = "I";
      this.set = "DRI";
      this.setNumber = "78";
      this.cardImage = "assets/cardback.png";
      this.name = "Zeraora";
      this.fullName = "Zeraora DRI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let exPokemonOnOppBench = false;
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (list, card) => {
          if (card.hasTag("ex" /* POKEMON_ex */)) {
            exPokemonOnOppBench = true;
          }
        });
        if (!exPokemonOnOppBench) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const cards = checkProvidedEnergy.energyMap.map((e) => e.card);
        const discardEnergy2 = new DiscardCardsEffect(effect, cards);
        discardEnergy2.target = player.active;
        store.reduceEffect(state, discardEnergy2);
        const blocked = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (list, card, target) => {
          if (!card.hasTag("ex" /* POKEMON_ex */)) {
            blocked.push(target);
          }
        });
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (selected) => {
            const targets = selected || [];
            targets.forEach((target) => {
              const damageEffect = new PutDamageEffect(effect, 210);
              damageEffect.target = target;
              store.reduceEffect(state, damageEffect);
            });
            return state;
          }
        );
      }
      return state;
    }
  };

