  init_game_error();
  init_game_message();
  init_trainer_card();
  init_card_types();
  init_pokemon_card();
  init_play_card_effects();
  init_choose_cards_prompt();
  init_shuffle_prompt();
  init_prefabs();
  function* playCard272(next, store, state, self, effect) {
    const player = effect.player;
    let pokemonsInDiscard = 0;
    const blocked = [];
    player.discard.cards.forEach((c) => {
      if (c instanceof PokemonCard) {
        pokemonsInDiscard += 1;
      }
    });
    if (pokemonsInDiscard === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    const max = Math.min(5, pokemonsInDiscard);
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DECK,
        player.discard,
        { superType: 1 /* POKEMON */ },
        { min: 1, max, allowCancel: true, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: self });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
