  var Gorebyss5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Clamperl";
      this.cardType = [W];
      this.hp = 90;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [{
        name: "Crescendo Wave",
        cost: [W],
        damage: 30,
        damageCalculation: "x",
        text: "This attack does 30 damage for each [W] Energy attached to this Pok\xE9mon. Before doing damage, you may attach as many Basic [W] Energy cards as you like from your hand to this Pok\xE9mon."
      }];
      this.regulationMark = "I";
      this.set = "DRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "56";
      this.name = "Gorebyss";
      this.fullName = "Gorebyss DRI";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const energiesInHand = player.hand.cards.filter((c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.name === "Water Energy");
        if (energiesInHand.length > 0) {
          CONFIRMATION_PROMPT(store, state, effect.player, (result) => {
            if (result) {
              state = store.prompt(state, new AttachEnergyPrompt(
                player.id,
                GameMessage.ATTACH_ENERGY_TO_ACTIVE,
                player.hand,
                2 /* BOTTOM_PLAYER */,
                [1 /* ACTIVE */],
                { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
                { allowCancel: false, min: 0 }
              ), (transfers) => {
                transfers = transfers || [];
                if (transfers.length === 0) {
                  return state;
                }
                for (const transfer of transfers) {
                  const target = StateUtils.getTarget(state, player, transfer.to);
                  MOVE_CARDS(store, state, player.hand, target, { cards: [transfer.card], sourceCard: this });
                }
              });
            }
          });
        }
        const energies = player.active.cards.filter((c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.name === "Water Energy");
        effect.damage = energies.length * 30;
      }
      return state;
    }
  };

