  var GraniteCave = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.regulationMark = "I";
      this.set = "DRI";
      this.setNumber = "166";
      this.cardImage = "assets/cardback.png";
      this.name = "Granite Cave";
      this.fullName = "Granite Cave DRI";
      this.text = "Steven's Pok\xE9mon (both yours and your opponent's) take 30 less damage from attacks from the opponent's Pok\xE9mon (after applying Weakness and Resistance).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && StateUtils.getStadiumCard(state) === this) {
        const owner = StateUtils.findOwner(state, effect.target);
        const card = effect.target.getPokemonCard();
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, effect.target, this)) {
          return state;
        }
        if (card.hasTag("Steven's" /* STEVENS */)) {
          effect.damage = Math.max(0, effect.damage - 30);
        }
      }
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

