  var Huntail4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Clamperl";
      this.cardType = [W];
      this.hp = 110;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Diver Catch",
          powerType: 2 /* ABILITY */,
          text: "You may use this Ability whenever 1 of your [W] Pok\xE9mon is Knocked Out by damage from an opponent's Pok\xE9mon's attack. Return all Basic [W] Energy attached to the Knocked Out Pok\xE9mon to your hand instead of discarding them."
        }
      ];
      this.attacks = [{
        name: "Wave Splash",
        cost: [W, C, C],
        damage: 80,
        text: ""
      }];
      this.regulationMark = "I";
      this.set = "DRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "55";
      this.name = "Huntail";
      this.fullName = "Huntail DRI";
      this.DIVER_CATCH_MARKER = "DIVER_CATCH_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (!pokemonHasCardTypeOptional(effect.target.getPokemonCard(), 3 /* WATER */)) {
          return state;
        }
        let isThisInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (card) => {
          if (card.getPokemonCard() === this) {
            isThisInPlay = true;
          }
        });
        if (!isThisInPlay) {
          return state;
        }
        const target = effect.target;
        const cards = target.cards.filter((card) => card.superType === 3 /* ENERGY */ && card.energyType === 0 /* BASIC */ && card.name === "Water Energy");
        cards.forEach((card) => {
          player.marker.addMarker(this.DIVER_CATCH_MARKER, card);
        });
      }
      if (effect instanceof BetweenTurnsEffect && effect.player.marker.hasMarker(this.DIVER_CATCH_MARKER)) {
        state.players.forEach((player) => {
          if (!player.marker.hasMarker(this.DIVER_CATCH_MARKER)) {
            return;
          }
          CONFIRMATION_PROMPT(store, state, player, (result) => {
            if (result) {
              const rescued = player.marker.markers.filter((m) => m.name === this.DIVER_CATCH_MARKER && m.source !== void 0).map((m) => m.source);
              MOVE_CARDS(store, state, player.discard, player.hand, { cards: rescued });
              player.marker.removeMarker(this.DIVER_CATCH_MARKER);
            }
          });
        });
      }
      return state;
    }
  };

