  var MarniesGrimmsnarlex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Marnie's Morgrem";
      this._tags = ["Marnie's" /* MARNIES */, "ex" /* POKEMON_ex */];
      this.cardType = [D];
      this.hp = 320;
      this.weakness = [{ type: G }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Punk Up",
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon during your turn, you may search your deck for up to 5 Basic [D] Energy cards and attach them to your Marnie's Pok\xE9mon in any way you like. Then, shuffle your deck."
        }
      ];
      this.attacks = [
        {
          name: "Shadow Bullet",
          cost: [D, D],
          damage: 180,
          text: "This attack also does 30 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        }
      ];
      this.regulationMark = "I";
      this.set = "DRI";
      this.setNumber = "136";
      this.cardImage = "assets/cardback.png";
      this.name = "Marnie's Grimmsnarl ex";
      this.fullName = "Marnie's Grimmsnarl ex DRI";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EvolveEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (!card.hasTag("Marnie's" /* MARNIES */)) blockedTo.push(target);
        });
        state = store.prompt(
          state,
          new ConfirmPrompt(effect.player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (wantToUse) {
              return store.prompt(
                state,
                new AttachEnergyPrompt(
                  player.id,
                  GameMessage.ATTACH_ENERGY_CARDS,
                  player.deck,
                  2 /* BOTTOM_PLAYER */,
                  [2 /* BENCH */, 1 /* ACTIVE */],
                  {
                    superType: 3 /* ENERGY */,
                    energyType: 0 /* BASIC */,
                    name: "Darkness Energy"
                  },
                  { allowCancel: true, min: 0, max: 5, blockedTo }
                ),
                (transfers) => {
                  transfers = transfers || [];
                  if (transfers.length === 0) {
                    SHUFFLE_DECK(store, state, player);
                    return state;
                  }
                  for (const transfer of transfers) {
                    const target = StateUtils.getTarget(state, player, transfer.to);
                    MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
                  }
                  state = store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
                    player.deck.applyOrder(order);
                  });
                }
              );
            }
            return state;
          }
        );
        return state;
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasBenched = opponent.bench.some((b) => b.cards.length > 0);
        if (!hasBenched) {
          return state;
        }
        state = store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const damageEffect = new PutDamageEffect(effect, 30);
            damageEffect.target = targets[0];
            store.reduceEffect(state, damageEffect);
          }
        );
        return state;
      }
      return state;
    }
  };

