  init_game_message();
  init_card_types();
  init_trainer_card();
  init_game_effects();
  init_state_utils();
  init_prefabs();
  function* useStadium13(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (card instanceof PokemonCard && !card.hasTag("Marnie's" /* MARNIES */)) blocked.push(index);
    });
    let cards = [];
    return store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 1 /* POKEMON */ },
        { min: 0, max: 1, allowCancel: false, blocked }
      ),
      (selectedCards) => {
        cards = selectedCards || [];
        cards.forEach((card, index) => {
          MOVE_CARDS(store, state, player.deck, player.hand, { cards: [card], sourceCard: effect.stadium });
        });
        if (cards.length > 0) {
          store.prompt(
            state,
            new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
            () => next()
          );
        }
        return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
          player.deck.applyOrder(order);
          return state;
        });
      }
    );
  }
  var SpikemuthGym = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "DRI";
      this.setNumber = "169";
      this.cardImage = "assets/cardback.png";
      this.regulationMark = "I";
      this.name = "Spikemuth Gym";
      this.fullName = "Spikemuth Gym DRI";
      this.text = "Once during each player's turn, that player may search their deck for a Marnie's Pok\xE9mon, reveal it, and put it into their hand. Then, that player shuffles their deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const generator = useStadium13(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

