  var StevensMetagrossex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Steven's Metang";
      this._tags = ["Steven's" /* STEVENS */, "ex" /* POKEMON_ex */];
      this.cardType = [M];
      this.hp = 340;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C, C];
      this.powers = [
        {
          name: "X-Boot",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may search your deck for a Basic [P] Energy card, a Basic [M] Energy card, or 1 of each and attach them to your [P] Pok\xE9mon and [M] Pok\xE9mon in any way you like. Then, shuffle your deck."
        }
      ];
      this.attacks = [{ name: "Metal Stomp", cost: [M, C, C], damage: 200, text: "" }];
      this.regulationMark = "I";
      this.set = "DRI";
      this.setNumber = "145";
      this.cardImage = "assets/cardback.png";
      this.name = "Steven's Metagross ex";
      this.fullName = "Steven's Metagross ex DRI";
      this.X_BOOT_MARKER = "X_BOOT_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.X_BOOT_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        ABILITY_USED(player, this);
        ADD_MARKER(this.X_BOOT_MARKER, player, this);
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            {
              allowCancel: true,
              min: 0,
              max: 2,
              differentTypes: true,
              validCardTypes: [5 /* PSYCHIC */, 8 /* METAL */]
            }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              if (transfers.length > 1) {
                if (transfers[0].card.name === transfers[1].card.name) {
                  throw new GameError(GameMessage.CAN_ONLY_SELECT_TWO_DIFFERENT_ENERGY_TYPES);
                }
              }
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
            }
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.X_BOOT_MARKER, this);
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.X_BOOT_MARKER, this);
      }
      return state;
    }
  };

