        {
          name: "Alert Smog",
          powerType: 2 /* ABILITY */,
          text: "If this Pok\xE9mon is in the Active Spot and is damaged by an attack from your opponent's Pok\xE9mon (even if this Pok\xE9mon is Knocked Out), search your deck for up to 2 Pok\xE9mon with Koffing in their name and put them onto your Bench. Then, shuffle your deck."
        }
