  function* useDarkAwakening(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      return state;
    }
    const cm = CardManager.getInstance();
    const evolutions = cm.getAllCards().filter((c) => {
      return c instanceof PokemonCard && c.stage !== 2 /* BASIC */;
    });
    const evolutionNames = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
      const valid = evolutions.filter(
        (e) => e.evolvesFrom === card.name && pokemonHasCardType(e, 7 /* DARK */)
      );
      valid.forEach((c) => {
        if (!evolutionNames.includes(c.name)) {
          evolutionNames.push(c.name);
        }
      });
    });
    if (evolutionNames.length === 0) {
      return state;
    }
    const blocked2 = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
      if (!pokemonHasCardTypeOptional(list.getPokemonCard(), 7 /* DARK */)) {
        blocked2.push(target);
      }
    });
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_EVOLVE,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { min: 1, max: 2, allowCancel: false, blocked: blocked2 }
      ),
      (selection) => {
        targets = selection || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    const targetNames = targets.map((target) => target.getPokemonCard()?.name).filter(Boolean);
    store.log(state, "LOG_TEXT" /* LOG_TEXT */, {
      text: `${player.name} chooses to evolve ${targetNames.join(" and ")}`
    });
    for (const target of targets) {
      const pokemonCard = target.getPokemonCard();
      if (pokemonCard === void 0) {
        return state;
      }
      const blocked = [];
      player.deck.cards.forEach((card, index) => {
        if (card instanceof PokemonCard && card.evolvesFrom !== pokemonCard.name) {
          blocked.push(index);
        }
      });
      let cards = [];
      yield store.prompt(
        state,
        new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_EVOLVE,
          player.deck,
          { superType: 1 /* POKEMON */ },
          { min: 0, max: 1, allowCancel: false, blocked }
        ),
        (selected) => {
          cards = selected || [];
          next();
        }
      );
      if (cards.length === 0) {
        continue;
      }
      const evolution = cards[0];
      MOVE_CARDS(store, state, player.deck, target, { cards: [evolution], sourceCard: effect.source.getPokemonCard() });
      target.clearEffects();
      target.pokemonPlayedTurn = state.turn;
    }
    SHUFFLE_DECK(store, state, player);
  }
