  var TeamRocketsWatchtower = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "DRI";
      this.regulationMark = "I";
      this.name = "Team Rocket's Watchtower";
      this.fullName = "Team Rocket's Watchtower DRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "180";
      this.text = "[C] Pok\xE9mon in play (both yours and your opponent's) have no Abilities.";
    }
    reduceEffect(store, state, effect) {
      HANDLE_ABILITY_LOCK(
        effect,
        ({ card }) => {
          if (StateUtils.getStadiumCard(state) !== this) {
            return false;
          }
          try {
            const cardList = StateUtils.findCardList(state, card);
            if (!(cardList instanceof PokemonCardList)) {
              return false;
            }
            const owner = StateUtils.findOwner(state, cardList);
            if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, cardList, this)) {
              return false;
            }
            const checkType = new CheckPokemonTypeEffect(cardList);
            store.reduceEffect(state, checkType);
            return checkType.cardTypes.includes(9 /* COLORLESS */);
          } catch {
            return pokemonHasCardType(card, 9 /* COLORLESS */);
          }
        },
        {
          allowUseFromHand: true,
          allowUseFromDiscard: true,
          error: GameMessage.BLOCKED_BY_EFFECT
        }
      );
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        throw new GameError(GameMessage.CANNOT_USE_STADIUM);
      }
      return state;
    }
  };

