  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/10-scarlet-and-violet/set-destined-rivals/tm-machine.ts
  init_trainer_card();
  init_card_types();
  init_game();
  init_play_card_effects();
  init_prefabs();
  function* playCard274(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    let cards = [];
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, {
      cards: [effect.trainerCard],
      sourceCard: self
    });
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      const regex = /\bTechnical Machine\b/;
      if (!c.name.match(regex)) {
        blocked.push(index);
      }
    });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 2 /* TRAINER */, trainerType: 3 /* TOOL */ },
        { min: 0, max: 3, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: self });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
  var TMMachine = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "H";
      this._trainerType = 0 /* ITEM */;
      this.set = "DRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "181";
      this.name = "TM Machine";
      this.fullName = "TM Machine DRI";
      this.text = "Search your deck for up to 3 Pok\xE9mon Tool cards with Technical Machine in their name, reveal them, and put them into your hand. Then, shuffle your deck.";
    }
    canPlay(store, state, player) {
      if (player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard274(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      return state;
    }
  };

