  var Alomomola6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 110;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.powers = [{
        name: "Gentle Fins",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn, if this Pok\xE9mon is in the Active Spot, you may put a Basic Pok\xE9mon with 70HP or less from your discard pile onto your bench."
      }];
      this.attacks = [{
        name: "Waterfall",
        cost: [W, C, C],
        damage: 70,
        text: ""
      }];
      this.regulationMark = "I";
      this.set = "BLK";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "24";
      this.name = "Alomomola";
      this.fullName = "Alomomola SV11B";
      this.GENTLE_FINS_MARKER = "GENTLE_FINS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.GENTLE_FINS_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.GENTLE_FINS_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const openSlots = player.bench.filter((b) => b.cards.length === 0);
        if (player.marker.hasMarker(this.GENTLE_FINS_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.active.cards[0] !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (openSlots.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked = player.discard.cards.reduce((acc, c, index) => {
          if (!(c instanceof PokemonCard && c.stage === 2 /* BASIC */ && c.hp <= 70)) {
            acc.push(index);
          }
          return acc;
        }, []);
        if (blocked.length === player.discard.cards.length) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const maxPokemons = Math.min(openSlots.length, 1);
        effect.preventDefault = true;
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
          player.discard,
          { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
          { min: 1, max: maxPokemons, allowCancel: false, blocked, maxPokemons }
        ), (selectedCards) => {
          const cards = selectedCards || [];
          player.marker.addMarker(this.GENTLE_FINS_MARKER, this);
          cards.forEach((card, index) => {
            const playPokemonFromDiscardEffect = new PlayPokemonFromDiscardEffect(player, card, openSlots[index]);
            store.reduceEffect(state, playPokemonFromDiscardEffect);
          });
          ABILITY_USED(player, this);
        });
      }
      return state;
    }
  };

