  function* playCard275(next, store, state, effect, sourceCard) {
    const player = effect.player;
    let coin1Result = false;
    let coin2Result = false;
    effect.preventDefault = true;
    yield COIN_FLIP_PROMPT(store, state, player, (result) => {
      coin1Result = result;
      next();
    });
    yield COIN_FLIP_PROMPT(store, state, player, (result) => {
      coin2Result = result;
      next();
    });
    if (coin1Result && coin2Result) {
      state = store.prompt(
        state,
        new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_ACTIVE,
          player.deck,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          { allowCancel: false, min: 0, max: 1 }
        ),
        (transfers) => {
          transfers = transfers || [];
          if (transfers.length === 0) {
            SHUFFLE_DECK(store, state, player);
            return;
          }
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.deck, target, {
              cards: [transfer.card],
              sourceCard: effect.trainerCard
            });
          }
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        }
      );
      return state;
    }
  }
