  var Volcarona10 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Larvesta";
      this.cardType = [R];
      this.hp = 120;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.powers = [{
        name: "Heat Wave Scales",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn, you may discard a Basic [R] Energy card from your hand in order to leave your opponent's Active Pok\xE9mon Burned."
      }];
      this.attacks = [{
        name: "Fire Wing",
        cost: [R, C, C],
        damage: 70,
        text: ""
      }];
      this.regulationMark = "I";
      this.set = "BLK";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "16";
      this.name = "Volcarona";
      this.fullName = "Volcarona SV11B";
      this.HEAT_WAVE_SCALES_MARKER = "HEAT_WAVE_SCALES_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.HEAT_WAVE_SCALES_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.HEAT_WAVE_SCALES_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.HEAT_WAVE_SCALES_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.provides.includes(2 /* FIRE */);
        });
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.HEAT_WAVE_SCALES_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        state = store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_DISCARD,
          player.hand,
          { superType: 3 /* ENERGY */, name: "Fire Energy" },
          { allowCancel: true, min: 1, max: 1 }
        ), (cards) => {
          cards = cards || [];
          if (cards.length === 0) {
            return;
          }
          player.marker.addMarker(this.HEAT_WAVE_SCALES_MARKER, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          MOVE_CARDS(store, state, player.hand, player.discard, { cards, sourceCard: this, sourceEffect: this.powers[0] });
          ADD_BURN_TO_PLAYER_ACTIVE(store, state, opponent, this);
        });
        return state;
      }
      return state;
    }
  };

