  init_card_types();
  init_game();
  init_attach_energy_prompt();
  init_show_cards_prompt();
  init_shuffle_prompt();
  init_prefabs();
  function* useEnergyGift(next, store, state, effect) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      return state;
    }
    yield store.prompt(
      state,
      new AttachEnergyPrompt(
        player.id,
        GameMessage.ATTACH_ENERGY_TO_BENCH,
        player.deck,
        2 /* BOTTOM_PLAYER */,
        [2 /* BENCH */, 1 /* ACTIVE */],
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { allowCancel: false, min: 0, max: 3 }
      ),
      (transfers) => {
        transfers = transfers || [];
        for (const transfer of transfers) {
          const target = StateUtils.getTarget(state, player, transfer.to);
          MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: effect.source.getPokemonCard() });
          next();
        }
      }
    );
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
