  var Whirlipede8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Venipede";
      this.hp = 100;
      this.cardType = [D];
      this.weakness = [{ type: F }];
      this.retreat = [C, C, C];
      this.attacks = [{
        name: "Venoshock",
        cost: [C],
        damage: 30,
        damageCalculation: "+",
        text: "If your opponent's Active Pok\xE9mon is Poisoned, this attack does 60 more damage."
      }];
      this.regulationMark = "I";
      this.set = "BLK";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "55";
      this.name = "Whirlipede";
      this.fullName = "Whirlipede BLK";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.active.specialConditions.includes(2 /* ASLEEP */)) {
          effect.damage += 60;
        }
      }
      return state;
    }
  };

