  var Swadloon8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.regulationMark = "I";
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Sewaddle";
      this.cardType = [G];
      this.hp = 80;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Healing Leaves",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may heal 20 damage from your Active Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Bug Buzz",
        cost: [G, C],
        damage: 40,
        text: ""
      }];
      this.set = "WHT";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "2";
      this.name = "Swadloon";
      this.fullName = "Swadloon WHT";
      this.HEALING_LEAVES_MARKER = "HEALING_LEAVES_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.HEALING_LEAVES_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.marker.addMarker(this.HEALING_LEAVES_MARKER, this);
        const healEffect = new HealEffect(player, player.active, 20);
        state = store.reduceEffect(state, healEffect);
        return state;
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.HEALING_LEAVES_MARKER, this);
      return state;
    }
  };

