  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-phantasmal-flames/mega-charizard-x-ex.ts
  init_game();
  init_prefabs();
  var MegaCharizardXex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Charmeleon";
      this._tags = ["Mega ex" /* POKEMON_SV_MEGA */, "ex" /* POKEMON_ex */];
      this.cardType = [R];
      this.hp = 360;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Inferno X",
          cost: [R, R],
          damage: 90,
          damageCalculation: "x",
          text: "Discard any amount of [R] Energy from among your Pok\xE9mon, and this attack does 90 damage for each card you discarded in this way."
        }
      ];
      this.regulationMark = "I";
      this.set = "PFL";
      this.setNumber = "13";
      this.cardImage = "assets/cardback.png";
      this.name = "Mega Charizard X ex";
      this.fullName = "Mega Charizard X ex M2";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let totalEnergy = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const basicEnergyCount = cardList.cards.filter(
            (card) => card.superType === 3 /* ENERGY */ && (card.provides.includes(2 /* FIRE */) || card.provides.includes(0 /* ANY */))
          ).length;
          totalEnergy += basicEnergyCount;
        });
        const blockedFrom = [];
        const blockedMap = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const blockedIndices = [];
          cardList.cards.forEach((energyCard, index) => {
            if (energyCard.superType === 3 /* ENERGY */) {
              if (!energyCard.provides.includes(2 /* FIRE */) && !energyCard.provides.includes(0 /* ANY */)) {
                blockedIndices.push(index);
              }
            }
          });
          if (blockedIndices.length > 0) {
            blockedMap.push({ source: target, blocked: blockedIndices });
          }
        });
        return store.prompt(
          state,
          new DiscardEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            // Card source is target Pokemon
            { superType: 3 /* ENERGY */ },
            { min: 1, max: totalEnergy, allowCancel: false, blockedFrom, blockedMap }
          ),
          (transfers) => {
            if (transfers === null) {
              return;
            }
            for (const transfer of transfers) {
              let totalDiscarded = 0;
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = player.discard;
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
              totalDiscarded = transfers.length;
              effect.damage = totalDiscarded * 90;
            }
            return state;
          }
        );
      }
      return state;
    }
  };

