  var NsZekrom = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["N's" /* NS */];
      this.cardType = [N];
      this.hp = 130;
      this.weakness = [];
      this.resistance = [];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Shred",
          cost: [C, C, C],
          damage: 70,
          shredAttack: true,
          text: "This attack's damage isn't affected by any effects on your opponent's Active Pok\xE9mon."
        },
        {
          name: "Rampaging Thunder",
          cost: [R, L, L, C],
          damage: 250,
          text: "During your next turn, this Pok\xE9mon can't use attacks."
        }
      ];
      this.regulationMark = "I";
      this.set = "ASC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "155";
      this.name = "N's Zekrom";
      this.fullName = "N's Zekrom M2a";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = effect.opponent;
        effect.ignoreResistance = true;
        const applyWeakness = new ApplyWeaknessEffect(effect, 70);
        store.reduceEffect(state, applyWeakness);
        const damage = applyWeakness.damage;
        effect.damage = 0;
        if (damage > 0) {
          opponent.active.damage += damage;
          const afterDamage = new AfterDamageEffect(effect, damage);
          state = store.reduceEffect(state, afterDamage);
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        player.active.cannotAttackNextTurnPending = true;
      }
      return state;
    }
  };

