  var Delphox5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Braixen";
      this.hp = 160;
      this.cardType = [R];
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Flaring Magic",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn, you may discard a Basic [R] Energy card from your hand in order to use this Ability. Draw cards until you have 7 cards in your hand."
      }];
      this.attacks = [{
        name: "Energized Storm",
        cost: [R, R],
        damage: 30,
        damageCalculation: "x",
        text: "This attack does 30 damage for each Energy attached to all Pok\xE9mon."
      }];
      this.regulationMark = "J";
      this.set = "CRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "13";
      this.name = "Delphox";
      this.fullName = "Delphox M4";
      this.FLARING_MAGIC_MARKER = "FLARING_MAGIC_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        effect.player.marker.removeMarker(this.FLARING_MAGIC_MARKER, this);
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.FLARING_MAGIC_MARKER, this);
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.FLARING_MAGIC_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (player.hand.cards.length >= 7) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasBasicFireInHand = player.hand.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(2 /* FIRE */)
        );
        if (!hasBasicFireInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
            { allowCancel: true, min: 1, max: 1 }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length === 0) {
              return;
            }
            MOVE_CARDS(store, state, player.hand, player.discard, {
              cards,
              sourceCard: this,
              sourceEffect: this.powers[0]
            });
            DRAW_CARDS_UNTIL_CARDS_IN_HAND(player, 7);
            player.marker.addMarker(this.FLARING_MAGIC_MARKER, this);
            ABILITY_USED(player, this);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let totalEnergy = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const checkEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkEnergy);
          checkEnergy.energyMap.forEach((em) => {
            totalEnergy += em.provides.length;
          });
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          const checkEnergy = new CheckProvidedEnergyEffect(opponent, cardList);
          store.reduceEffect(state, checkEnergy);
          checkEnergy.energyMap.forEach((em) => {
            totalEnergy += em.provides.length;
          });
        });
        effect.damage = 30 * totalEnergy;
      }
      return state;
    }
  };

