  var Crobat12 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Golbat";
      this.hp = 130;
      this.cardType = [D];
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Nighttime Maneuvers",
          powerType: 2 /* ABILITY */,
          useWhenInPlay: true,
          text: "Once during your turn, if this Pok\xE9mon is in the Active Spot, you may use this Ability. Search your deck for a card. Shuffle your deck, then put that card on top of it."
        }
      ];
      this.attacks = [
        {
          name: "Poison Sound Wave",
          cost: [D],
          damage: 80,
          text: "Your opponent's Active Pok\xE9mon is now Confused and Poisoned."
        }
      ];
      this.regulationMark = "J";
      this.set = "CRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "51";
      this.name = "Crobat";
      this.fullName = "Crobat M4";
      this.NIGHTTIME_MANEUVERS_MARKER = "NIGHTTIME_MANEUVERS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.active.getPokemonCard() !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.NIGHTTIME_MANEUVERS_MARKER, this);
        ABILITY_USED(player, this);
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARDS_TO_PUT_ON_TOP_OF_THE_DECK,
            player.deck,
            {},
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length === 0) return state;
            const deckTop = new CardList();
            MOVE_CARDS(store, state, player.deck, deckTop, { cards, sourceCard: this });
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
              if (order === null) return state;
              deckTop.applyOrder(order);
              deckTop.moveToTopOfDestination(player.deck);
              return state;
            });
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.NIGHTTIME_MANEUVERS_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const specialConditionEffect = new AddSpecialConditionsEffect(effect, [
          1 /* CONFUSED */,
          3 /* POISONED */
        ]);
        store.reduceEffect(state, specialConditionEffect);
      }
      return state;
    }
  };

