  var Inteleon4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Drizzile";
      this.cardType = [W];
      this.hp = 100;
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Bring Down",
          cost: [W],
          damage: 0,
          text: "The Pok\xE9mon in play that has the least HP remaining, except for this Pok\xE9mon, is Knocked Out. (If there are multiple Pok\xE9mon, choose 1.)"
        },
        {
          name: "Water Shot",
          cost: [W, W],
          damage: 110,
          text: "Discard an Energy from this Pok\xE9mon."
        }
      ];
      this.set = "MEG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "41";
      this.name = "Inteleon";
      this.fullName = "Inteleon M1S";
      this.regulationMark = "I";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = effect.opponent;
        let leastHP = Infinity;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (card) => {
          if (card !== player.active) {
            const hpCheck = new CheckHpEffect(player, card);
            if (hpCheck.hp < leastHP) {
              leastHP = hpCheck.hp;
            }
          }
        });
        opponent.forEachPokemon(2 /* BOTTOM_PLAYER */, (card) => {
          const hpCheck = new CheckHpEffect(opponent, card);
          if (hpCheck.hp < leastHP) {
            leastHP = hpCheck.hp;
          }
        });
        if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
          if (effect.target !== effect.player.active) {
            throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
          }
        }
        const blockedTo = [];
        player.forEachPokemon(1 /* TOP_PLAYER */, (list, card, target) => {
          const hpCheck = new CheckHpEffect(player, list);
          if (list === player.active) {
            blockedTo.push(target);
          } else if (hpCheck.hp !== leastHP) {
            blockedTo.push(target);
          }
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (list, card, target) => {
          const hpCheck = new CheckHpEffect(opponent, list);
          if (hpCheck.hp !== leastHP) {
            blockedTo.push(target);
          }
        });
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON,
          0 /* ANY */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: 1, max: 1, blocked: blockedTo }
        ), (target) => {
          const damageEffect = new KnockOutEffect(player, target[0]);
          store.reduceEffect(state, damageEffect);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 1);
      }
      return state;
    }
  };

