  function* moveEnergy(next, store, state, effect) {
    const player = effect.player;
    let pokemonWithEnergy = 0;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
      if (cardList.cards.some((c) => c.superType === 3 /* ENERGY */)) {
        pokemonWithEnergy++;
      }
    });
    if (!pokemonWithEnergy) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    let transfers = [];
    yield store.prompt(
      state,
      new MoveEnergyPrompt(
        player.id,
        GameMessage.MOVE_ENERGY_CARDS,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Grass Energy" },
        { min: 0, allowCancel: false }
      ),
      (result) => {
        transfers = result || [];
        next();
      }
    );
    if (transfers.length === 0) {
      return state;
    }
    for (const transfer of transfers) {
      const source = StateUtils.getTarget(state, player, transfer.from);
      const target = StateUtils.getTarget(state, player, transfer.to);
      MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: effect.card });
    }
    return state;
  }
