  var Oricorioex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [R];
      this.hp = 190;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Excited Turbo",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "As often as you like during your turn, if you have any [R] Mega Evolution Pok\xE9mon ex in play, you may use this Ability. Attach a Basic [R] Energy card from your hand to 1 of your Benched [R] Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Fire Wing",
          cost: [R, R, C],
          damage: 110,
          text: ""
        }
      ];
      this.regulationMark = "I";
      this.set = "PFL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "18";
      this.name = "Oricorio ex";
      this.fullName = "Oricorio ex M2";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const hasMegaEvolutionPokemonInPlay = player.active.cards.some((c) => {
          return c instanceof PokemonCard && c.hasTag("ex" /* POKEMON_ex */) && c.hasTag("Mega ex" /* POKEMON_SV_MEGA */) && pokemonHasCardType(c, 2 /* FIRE */);
        });
        if (!hasMegaEvolutionPokemonInPlay) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasFirePokemonOnBench = player.bench.some(
          (benchSlot) => benchSlot.cards.some((c) => c instanceof PokemonCard && pokemonHasCardType(c, 2 /* FIRE */))
        );
        if (!hasFirePokemonOnBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (!pokemonHasCardType(card, 2 /* FIRE */)) {
            blocked.push(target);
          }
        });
        const hasEnergyInHand = player.hand.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(2 /* FIRE */);
        });
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.hand,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
            { allowCancel: false, blockedTo: blocked }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              const energyCard = transfer.card;
              const attachEnergyEffect = new AttachEnergyEffect(player, energyCard, target);
              store.reduceEffect(state, attachEnergyEffect);
            }
          }
        );
      }
      return state;
    }
  };

