  init_check_effects();
  init_prefabs();
  var Tyrantrum3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Tyrunt";
      this.cardType = [F];
      this.hp = 180;
      this.weakness = [{ type: G }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Tyrannically Gutsy",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon has any Special Energy attached, it gets +150 HP."
      }];
      this.attacks = [{
        name: "Wreak Havoc",
        cost: [F, C],
        damage: 160,
        text: "Flip a coin until you get tails. For each heads, discard the top card of your opponent's deck."
      }];
      this.regulationMark = "J";
      this.set = "POR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "45";
      this.name = "Tyrantrum";
      this.fullName = "Tyrantrum M3";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckHpEffect && effect.target.getPokemonCard() === this) {
        const player = effect.player;
        const checkEnergy = new CheckProvidedEnergyEffect(player, effect.target);
        store.reduceEffect(state, checkEnergy);
        if (IS_ABILITY_BLOCKED(store, state, effect.player, this)) {
          return state;
        }
        const hasSpecialEnergy = checkEnergy.energyMap.some((em) => {
          const card = em.card;
          return card.superType === 3 /* ENERGY */ && card.energyType === 1 /* SPECIAL */;
        });
        if (hasSpecialEnergy) {
          effect.hp += 150;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const flipCoins = (s) => {
          if (opponent.deck.cards.length === 0) {
            return s;
          }
          return COIN_FLIP_PROMPT(store, s, player, (result) => {
            if (result === true) {
              const deckTop = new CardList();
              MOVE_CARDS(store, state, opponent.deck, deckTop, { count: 1, sourceCard: this });
              if (deckTop.cards.length > 0) {
                store.log(s, "LOG_PLAYER_DISCARDS_CARD" /* LOG_PLAYER_DISCARDS_CARD */, { name: opponent.name, card: deckTop.cards[0].name, effectName: "Wreak Havoc" });
                MOVE_CARDS(store, state, deckTop, opponent.discard, { sourceCard: this });
              }
              flipCoins(s);
            }
          });
        };
        return flipCoins(state);
      }
      return state;
    }
  };

