  var Doublade10 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Honedge";
      this.cardType = [M];
      this.hp = 100;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Weaponized Swords",
        cost: [C, C],
        damage: 0,
        text: "Reveal any number of Honedge, Doublade, and Aegislash from your hand, and this attack does 60 damage for each card you revealed in this way."
      }];
      this.regulationMark = "J";
      this.set = "POR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "57";
      this.name = "Doublade";
      this.fullName = "Doublade M3";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const blockedIndices = [];
        player.hand.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || card.name !== "Honedge" && card.name !== "Doublade" && card.name !== "Aegislash") {
            blockedIndices.push(index);
          }
        });
        const validCards = player.hand.cards.filter(
          (card) => card instanceof PokemonCard && (card.name === "Honedge" || card.name === "Doublade" || card.name === "Aegislash")
        );
        if (validCards.length === 0) {
          effect.damage = 0;
          return state;
        }
        let revealedCards = [];
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.hand,
          {},
          { min: 0, max: validCards.length, allowCancel: false, blocked: blockedIndices }
        ), (selected) => {
          revealedCards = selected || [];
          if (revealedCards.length > 0) {
            store.prompt(state, new ShowCardsPrompt(
              opponent.id,
              GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
              revealedCards
            ), () => state);
          }
          effect.damage = revealedCards.length * 60;
        });
      }
      return state;
    }
  };

