  var Grisham = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "M-P";
      this.setNumber = "99";
      this.regulationMark = "J";
      this.cardImage = "assets/cardback.png";
      this.name = "Grisham";
      this.fullName = "Grisham M-P";
      this.text = "Heal 50 damage from all Pok\xE9mon in play (both yours and your opponent's).";
    }
    canPlay(store, state, player) {
      const opponent = StateUtils.getOpponent(state, player);
      let hasDamaged = false;
      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
        if (cardList.damage > 0) {
          hasDamaged = true;
        }
      });
      opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
        if (cardList.damage > 0) {
          hasDamaged = true;
        }
      });
      return hasDamaged;
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.damage > 0) {
            const healEffect = new HealEffect(player, cardList, 50);
            store.reduceEffect(state, healEffect);
          }
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          if (cardList.damage > 0) {
            const healEffect = new HealEffect(player, cardList, 50);
            store.reduceEffect(state, healEffect);
          }
        });
      }
      return state;
    }
  };

