  function* playCard279(next, store, state, self, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    if (player.supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    if (opponent.getPrizeLeft() > 2) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { min: 1, max: 1, allowCancel: false }
      ),
      (results) => {
        targets = results || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    ADD_MARKER(self.MISCHIEF_MARKER, targets[0], self);
    ADD_MARKER(self.CLEAR_MISCHIEF_MARKER, opponent, self);
    return state;
  }
  var AcerolasMischief = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "MEG";
      this.regulationMark = "I";
      this.setNumber = "113";
      this.cardImage = "assets/cardback.png";
      this.name = "Acerola's Mischief";
      this.fullName = "Acerola's Mischief MEG";
      this.text = "You can use this card only if your opponent has 2 or fewer Prize cards remaining.\n\nChoose 1 of your Pok\xE9mon in play. During your opponent's next turn, prevent all damage from and effects of attacks done to that Pok\xE9mon by your opponent's Pok\xE9mon ex.";
      this.MISCHIEF_MARKER = "ACEROLAS_MISCHIEF_MARKER";
      this.CLEAR_MISCHIEF_MARKER = "ACEROLAS_MISCHIEF_CLEAR_MARKER";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      const opponent = StateUtils.getOpponent(state, player);
      return opponent.getPrizeLeft() <= 2;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard279(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (effect instanceof AbstractAttackEffect && effect.target.marker.hasMarker(this.MISCHIEF_MARKER, this)) {
        const targetOwner = StateUtils.findOwner(state, effect.target);
        const sourceCard = effect.source.getPokemonCard();
        if (effect.player !== targetOwner && sourceCard && sourceCard.hasTag("ex" /* POKEMON_ex */)) {
          effect.preventDefault = true;
          return state;
        }
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.CLEAR_MISCHIEF_MARKER, this)) {
        effect.player.marker.removeMarker(this.CLEAR_MISCHIEF_MARKER, this);
        const player = StateUtils.getOpponent(state, effect.player);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          cardList.marker.removeMarker(this.MISCHIEF_MARKER, this);
        });
      }
      return state;
    }
  };

