  var Latios6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [N];
      this.hp = 130;
      this.retreat = [C];
      this.powers = [{
        name: "Luster Assist",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn, when your Mega Latias ex moves from the Bench to the Active Spot, you may move any number of Energy from your Benched Pok\xE9mon to that Active Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Dragon Claw",
        cost: [W, P, C],
        damage: 130,
        text: ""
      }];
      this.regulationMark = "I";
      this.set = "MEG";
      this.setNumber = "101";
      this.cardImage = "assets/cardback.png";
      this.name = "Latios";
      this.fullName = "Latios M1S";
      this.LUSTER_ASSIST_MARKER = "LUSTER_ASSIST_MARKER";
    }
    reduceEffect(store, state, effect) {
      const player = StateUtils.findOwner(state, StateUtils.findCardList(state, this));
      if (player === void 0) {
        return state;
      }
      const activePokemon = player.active.getPokemonCard();
      if (activePokemon && activePokemon.name === "M Latias-EX" && MOVED_TO_ACTIVE_THIS_TURN(player, activePokemon)) {
        if (!player.marker.hasMarker(this.LUSTER_ASSIST_MARKER, this)) {
          let hasEnergyOnBench = false;
          player.bench.forEach((b) => {
            if (b.cards.some((c) => c.superType === 3 /* ENERGY */)) {
              hasEnergyOnBench = true;
            }
          });
          if (hasEnergyOnBench) {
            state = store.prompt(state, new ConfirmPrompt(
              player.id,
              GameMessage.WANT_TO_USE_ABILITY
            ), (wantToUse) => {
              if (wantToUse) {
                player.marker.addMarker(this.LUSTER_ASSIST_MARKER, this);
                const blockedFrom = [{ player: 2 /* BOTTOM_PLAYER */, slot: 1 /* ACTIVE */, index: 0 }];
                const blockedTo = [];
                player.bench.forEach((b, index) => {
                  blockedTo.push({ player: 2 /* BOTTOM_PLAYER */, slot: 2 /* BENCH */, index });
                });
                store.prompt(state, new MoveEnergyPrompt(
                  player.id,
                  GameMessage.MOVE_ENERGY_CARDS,
                  2 /* BOTTOM_PLAYER */,
                  [1 /* ACTIVE */, 2 /* BENCH */],
                  { superType: 3 /* ENERGY */ },
                  { allowCancel: true, blockedFrom, blockedTo }
                ), (transfers) => {
                  transfers = transfers || [];
                  for (const transfer of transfers) {
                    const source = StateUtils.getTarget(state, player, transfer.from);
                    MOVE_CARDS(store, state, source, player.active, { cards: [transfer.card], sourceCard: this });
                  }
                });
              }
            });
          }
        }
      }
      if (effect instanceof EndTurnEffect) {
        player.marker.removeMarker(this.LUSTER_ASSIST_MARKER, this);
      }
      return state;
    }
  };

