  var Marshadow5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [F];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [{
        name: "Shadowy Side Kick",
        cost: [F, F],
        damage: 60,
        text: "If your opponent's Pok\xE9mon is Knocked Out by damage from this attack, during your opponent's next turn, prevent all damage from and effects of attacks done to this Pok\xE9mon."
      }];
      this.set = "MEG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "80";
      this.name = "Marshadow";
      this.fullName = "Marshadow M1L";
      this.regulationMark = "I";
      this.PREVENT_ALL_DAMAGE_AND_EFFECTS = "PREVENT_ALL_DAMAGE_AND_EFFECTS";
      this.CLEAR_PREVENT_ALL_DAMAGE_AND_EFFECTS = "CLEAR_PREVENT_ALL_DAMAGE_AND_EFFECTS";
      this.usedShadowySideKick = false;
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        this.usedShadowySideKick = true;
      }
      if (effect instanceof KnockOutEffect && this.usedShadowySideKick) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (state.phase === 3 /* ATTACK */ && effect.target === opponent.active && effect.target.getPokemonCard()) {
          player.active.marker.addMarker(this.PREVENT_ALL_DAMAGE_AND_EFFECTS, this);
          opponent.marker.addMarker(this.CLEAR_PREVENT_ALL_DAMAGE_AND_EFFECTS, this);
        }
        this.usedShadowySideKick = false;
      }
      if (effect instanceof AbstractAttackEffect && effect.target.cards.includes(this) && effect.target.marker.hasMarker(this.PREVENT_ALL_DAMAGE_AND_EFFECTS, this)) {
        effect.preventDefault = true;
        return state;
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.CLEAR_PREVENT_ALL_DAMAGE_AND_EFFECTS, this)) {
        effect.player.marker.removeMarker(this.CLEAR_PREVENT_ALL_DAMAGE_AND_EFFECTS, this);
        const opponent = StateUtils.getOpponent(state, effect.player);
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          cardList.marker.removeMarker(this.PREVENT_ALL_DAMAGE_AND_EFFECTS, this);
        });
      }
      if (effect instanceof EndTurnEffect) {
        this.usedShadowySideKick = false;
      }
      return state;
    }
  };

