  init_game();
  init_game_effects();
  init_choose_cards_prompt();
  init_prefabs();
  function* useStadium14(next, store, state, effect) {
    const player = effect.player;
    if (player.hand.cards.every((c) => c.superType !== 3 /* ENERGY */)) {
      throw new GameError(GameMessage.CANNOT_USE_STADIUM);
    }
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_DISCARD,
        player.hand,
        { superType: 3 /* ENERGY */ },
        { min: 1, max: 1, allowCancel: true }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length === 0) {
      return state;
    }
    MOVE_CARDS(store, state, player.hand, player.discard, {
      cards,
      sourceCard: effect.stadium
    });
    let psychicPokemon = 0;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
      if (card instanceof PokemonCard && pokemonHasCardType(card, 5 /* PSYCHIC */)) {
        psychicPokemon++;
      }
    });
    const cardsToDraw = psychicPokemon - player.hand.cards.length;
    if (cardsToDraw > 0) {
      MOVE_CARDS(store, state, player.deck, player.hand, {
        count: cardsToDraw,
        sourceCard: effect.stadium
      });
    }
    return state;
  }
