  function* playCard282(next, store, state, effect) {
    const player = effect.player;
    if (player.supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    const blocked = [];
    let hasMegaPokemon = false;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target2) => {
      if (card.hasTag("Mega ex" /* POKEMON_SV_MEGA */) && card.hasTag("ex" /* POKEMON_ex */) && cardList.damage > 0) {
        hasMegaPokemon = true;
      } else {
        blocked.push(target2);
      }
    });
    if (!hasMegaPokemon) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let targets = [];
    yield store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_HEAL,
        2 /* BOTTOM_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: false, blocked }
      ),
      (results) => {
        targets = results || [];
        next();
      }
    );
    if (targets.length === 0) {
      return state;
    }
    const target = targets[0];
    const healEffect = new HealEffect(player, target, target.damage);
    store.reduceEffect(state, healEffect);
    const energy2 = target.cards.filter((c) => c.superType === 3 /* ENERGY */);
    MOVE_CARDS(store, state, target, player.hand, { cards: energy2, sourceCard: effect.trainerCard });
    return state;
  }
  var WallysCompassion = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "MEG";
      this.setNumber = "132";
      this.regulationMark = "I";
      this.name = "Wally's Compassion";
      this.fullName = "Wally's Compassion M1S";
      this.text = "Heal all damage from 1 of your Mega Evolution Pok\xE9mon ex. If you do, put all Energy attached to that Pok\xE9mon back into your hand.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      let hasMegaPokemon = false;
      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
        if (card.hasTag("Mega ex" /* POKEMON_SV_MEGA */) && card.hasTag("ex" /* POKEMON_ex */) && cardList.damage > 0) {
          hasMegaPokemon = true;
        }
      });
      if (!hasMegaPokemon) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard282(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

