  var SurfingBeach = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this.cardImage = "assets/cardback.png";
      this.setNumber = "129";
      this._trainerType = 2 /* STADIUM */;
      this.set = "MEG";
      this.name = "Surfing Beach";
      this.fullName = "Surfing Beach M1S";
      this.regulationMark = "I";
      this.text = "Once during each player's turn, that player may switch their Active [W] Pok\xE9mon with 1 of their Benched [W] Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        let hasBenchWater = false;
        let hasActiveWater = false;
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, cardTarget) => {
          const checkPokemonTypeEffect = new CheckPokemonTypeEffect(cardList);
          store.reduceEffect(state, checkPokemonTypeEffect);
          if (cardList === player.active && checkPokemonTypeEffect.cardTypes.includes(3 /* WATER */)) {
            hasActiveWater = true;
          }
          if (cardList !== player.active && checkPokemonTypeEffect.cardTypes.includes(3 /* WATER */)) {
            hasBenchWater = true;
          } else {
            blocked.push(cardTarget);
          }
        });
        if (!(hasActiveWater && hasBenchWater)) {
          throw new GameError(GameMessage.CANNOT_USE_STADIUM);
        }
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, player, player.active, this)) {
          throw new GameError(GameMessage.CANNOT_USE_STADIUM);
        }
        store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false, blocked }
          ),
          (selected) => {
            if (!selected || selected.length === 0) return state;
            const target = selected[0];
            if (IS_STADIUM_EFFECT_BLOCKED(store, state, player, target, this)) {
              return state;
            }
            player.switchPokemon(target);
          }
        );
      }
      return state;
    }
  };

