  var Tinkatuff4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Tinkatink";
      this.hp = 90;
      this.cardType = [M];
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Haphazard Hammer",
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, when you play this Pok\xE9mon from your hand to evolve 1 of your Pok\xE9mon, you may use this Ability. Flip a coin. If heads, discard an Energy from your opponent's Active Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Light Punch",
        cost: [M],
        damage: 30,
        text: ""
      }];
      this.regulationMark = "I";
      this.set = "MEG";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "97";
      this.name = "Tinkatuff";
      this.fullName = "Tinkatuff MEG";
      this.RUSTLING_WIND_MARKER = "RUSTLING_WIND_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (JUST_EVOLVED(effect, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (player.marker.hasMarker(this.RUSTLING_WIND_MARKER, this)) {
          return state;
        }
        const hasEnergy = opponent.active.energies.cards.some((card) => card.superType === 3 /* ENERGY */);
        if (!hasEnergy) {
          return state;
        }
        player.marker.addMarker(this.RUSTLING_WIND_MARKER, this);
        return COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (result) {
            store.prompt(state, new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              opponent.active,
              { superType: 3 /* ENERGY */ },
              { min: 1, max: 1, allowCancel: false }
            ), (selected) => {
              if (selected && selected.length > 0) {
                const energyCard = selected[0];
                MOVE_CARDS(store, state, opponent.active, opponent.discard, { cards: [energyCard], sourceCard: this });
              }
            });
            ABILITY_USED(player, this);
          }
          return state;
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.RUSTLING_WIND_MARKER, this);
      return state;
    }
  };

