  var IronDefender = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.set = "MEG";
      this.setNumber = "118";
      this.cardImage = "assets/cardback.png";
      this.regulationMark = "I";
      this.name = "Iron Defender";
      this.fullName = "Iron Defender M1L";
      this.text = "During your opponent's next turn, all of your [M] Pok\xE9mon take 30 less damage from attacks from your opponent's Pok\xE9mon (after applying Weakness and Resistance). (This includes new Pok\xE9mon that come into play.)";
      this.IRON_DEFENDER_MARKER = "IRON_DEFENDER_MARKER";
    }
    canPlay(store, state, player) {
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        effect.player.marker.addMarker(this.IRON_DEFENDER_MARKER, this);
      }
      if (effect instanceof PutDamageEffect) {
        const player = StateUtils.findOwner(state, StateUtils.findCardList(state, this));
        const hasMarker = player.marker.hasMarker(this.IRON_DEFENDER_MARKER, this);
        const checkPokemonTypeEffect = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkPokemonTypeEffect);
        if (hasMarker && checkPokemonTypeEffect.cardTypes.includes(8 /* METAL */)) {
          effect.damage -= 30;
        }
        return state;
      }
      if (effect instanceof EndTurnEffect) {
        StateUtils.getOpponent(state, effect.player).marker.removeMarker(this.IRON_DEFENDER_MARKER);
      }
      return state;
    }
  };

