  var Arboliva2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Dolliv";
      this.cardType = [G];
      this.hp = 150;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Oil Slip",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may switch your opponent's Active Pok\xE9mon with 1 of their Benched Pok\xE9mon. (Your opponent chooses which Benched Pok\xE9mon to switch.)"
      }];
      this.attacks = [{
        name: "Mega Drain",
        cost: [G, C],
        damage: 100,
        text: "Heal 30 damage from this Pok\xE9mon."
      }];
      this.regulationMark = "J";
      this.set = "J-MEM";
      this.setNumber = "8";
      this.cardImage = "assets/cardback.png";
      this.name = "Arboliva";
      this.fullName = "Arboliva MEM";
      this.OIL_SLIP_MARKER = "ARBOLIVA_MEM_OIL_SLIP_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        if (!opponent.bench.some((b) => b.cards.length > 0)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.OIL_SLIP_MARKER, this);
        ABILITY_USED(player, this);
        GUST_OPPONENT_BENCHED_POKEMON(store, state, player);
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.OIL_SLIP_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        HEAL_X_DAMAGE_FROM_THIS_POKEMON(effect, store, state, 30);
      }
      return state;
    }
  };

