  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-mega-starter-deck/meowscarada-ex.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_attack_effects();
  init_choose_pokemon_prompt();
  init_prefabs();
  var Meowscaradaex2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["ex" /* POKEMON_ex */];
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Floragato";
      this.cardType = [G];
      this.hp = 320;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Magical Bullet",
        cost: [C, C],
        damage: 120,
        text: "This attack also does 120 damage to 1 of your opponent's Benched Pok\xE9mon that has any damage counters on it. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.regulationMark = "J";
      this.set = "J-MEM";
      this.setNumber = "5";
      this.cardImage = "assets/cardback.png";
      this.name = "Meowscarada ex";
      this.fullName = "Meowscarada ex MEM";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const hasDamagedBenched = opponent.bench.some((b) => b.cards.length > 0 && b.damage > 0);
        if (!hasDamagedBenched) {
          return state;
        }
        const blocked = [];
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList === opponent.active || cardList.damage === 0) {
            blocked.push(target);
          }
        });
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: true, blocked }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const damageEffect = new PutDamageEffect(effect, 120);
            damageEffect.target = targets[0];
            store.reduceEffect(state, damageEffect);
          }
        );
      }
      return state;
    }
  };

