  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-mega-starter-deck/pawmot.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_prefabs();
  var Pawmot2 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Pawmo";
      this.cardType = [L];
      this.hp = 150;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [{
        name: "Power Plant Touch",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may attach a Basic [L] Energy from your discard pile to 1 of your Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Electric Punch",
        cost: [L, C],
        damage: 100,
        text: ""
      }];
      this.regulationMark = "J";
      this.set = "J-MEE";
      this.setNumber = "5";
      this.cardImage = "assets/cardback.png";
      this.name = "Pawmot";
      this.fullName = "Pawmot MEE";
      this.POWER_PLANT_TOUCH_MARKER = "PAWMOT_MEE_POWER_PLANT_TOUCH_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        const hasEnergyInDiscard = player.discard.cards.some(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(4 /* LIGHTNING */)
        );
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.POWER_PLANT_TOUCH_MARKER, this);
        ABILITY_USED(player, this);
        return ATTACH_X_TYPE_ENERGY_FROM_DISCARD_TO_1_OF_YOUR_POKEMON(
          store,
          state,
          player,
          1,
          4 /* LIGHTNING */,
          {
            destinationSlots: [1 /* ACTIVE */, 2 /* BENCH */],
            energyFilter: { energyType: 0 /* BASIC */ },
            min: 1,
            allowCancel: true
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.POWER_PLANT_TOUCH_MARKER, this);
      return state;
    }
  };

