  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-phantasmal-flames/aipom.ts
  init_game();
  init_card_types();
  init_pokemon_card();
  init_prefabs();
  var Aipom9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.hp = 70;
      this.cardType = [C];
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [{
        name: "Astonish",
        cost: [C, C],
        damage: 20,
        text: "Choose a random card from your opponent's hand, and your opponent reveals that card and shuffles it into their deck."
      }];
      this.regulationMark = "I";
      this.set = "PFL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "78";
      this.name = "Aipom";
      this.fullName = "Aipom PFL";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const randomIndex = Math.floor(Math.random() * opponent.hand.cards.length);
        const randomCard = opponent.hand.cards[randomIndex];
        if (opponent.hand.cards.length === 0) {
          return state;
        }
        SHOW_CARDS_TO_PLAYER(store, state, player, [randomCard]);
        MOVE_CARDS(store, state, opponent.hand, opponent.deck, { cards: [randomCard], sourceCard: this, sourceEffect: this.attacks[0] });
        SHUFFLE_DECK(store, state, opponent);
      }
      return state;
    }
  };

