  var GrimsleysGambit = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "PFL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "90";
      this.regulationMark = "I";
      this.name = "Grimsley's Move";
      this.fullName = "Grimsley's Gambit M2";
      this.text = "Look at the top 7 cards of your deck and put a [D] Pok\xE9mon you find there onto your Bench. Shuffle the other cards and put them on the bottom of your deck. You can't use this card on your first turn.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (player.deck.cards.length === 0) {
        return false;
      }
      if (player.bench.filter((b) => b.cards.length === 0).length === 0) {
        return false;
      }
      if (state.turn === 1 || state.turn === 2) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const openSlots = player.bench.filter((b) => b.cards.length === 0);
        if (openSlots.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        if (state.turn === 1 || state.turn === 2) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const deckTop = new CardList();
        state = MOVE_CARDS(store, state, player.deck, deckTop, { count: 7 });
        let cards = [];
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            deckTop,
            { superType: 1 /* POKEMON */, cardType: [7 /* DARK */] },
            { min: 0, max: 1, allowCancel: false }
          ),
          (selectedCards) => {
            cards = selectedCards || [];
            cards.forEach((card, index) => {
              state = MOVE_CARDS(store, state, deckTop, openSlots[index], { cards: [card] });
              openSlots[index].pokemonPlayedTurn = state.turn;
            });
            state = store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              deckTop.applyOrder(order);
            });
            state = MOVE_CARDS(store, state, deckTop, player.deck, { toBottom: true });
            state = MOVE_CARDS(store, state, player.supporter, player.discard, {
              cards: [effect.trainerCard]
            });
            return state;
          }
        );
      }
      return state;
    }
  };

