  var JumboIce = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.regulationMark = "I";
      this.set = "PFL";
      this.name = "Jumbo Ice Cream";
      this.fullName = "Jumbo Ice M2";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "91";
      this.text = "Heal 80 damage from your Active Pok\xE9mon that has 3 or more Energy attached.";
    }
    canPlay(store, state, player) {
      const activePokemon = player.active.getPokemonCard();
      if (!activePokemon) {
        return false;
      }
      if (player.active.damage === 0) {
        return false;
      }
      const energyCount = player.active.energies.cards.length;
      if (energyCount < 3) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const activePokemon = player.active.getPokemonCard();
        if (activePokemon && player.active.damage > 0) {
          const checkEnergy = new CheckProvidedEnergyEffect(player);
          store.reduceEffect(state, checkEnergy);
          if (checkEnergy.energyMap.length >= 3) {
            const healEffect = new HealEffect(player, player.active, 80);
            store.reduceEffect(state, healEffect);
          }
        }
        MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [this], sourceCard: this });
      }
      return state;
    }
  };

