  init_game();
  init_attack_effects();
  init_prefabs();
  var MegaDiancieex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Mega ex" /* POKEMON_SV_MEGA */, "ex" /* POKEMON_ex */];
      this.cardType = [P];
      this.hp = 270;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Diamond Coat",
          powerType: 2 /* ABILITY */,
          text: "This Pok\xE9mon takes 30 less damage from attacks (after applying Weakness and Resistance)."
        }
      ];
      this.attacks = [
        {
          name: "Garland Ray",
          cost: [P, P],
          damage: 120,
          damageCalculation: "x",
          text: "Discard up to 2 Energy cards from this Pok\xE9mon, and this attack does 120 damage for each card you discarded in this way."
        }
      ];
      this.regulationMark = "I";
      this.set = "PFL";
      this.setNumber = "41";
      this.cardImage = "assets/cardback.png";
      this.name = "Mega Diancie ex";
      this.fullName = "Mega Diancie ex M2";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        state = store.prompt(
          state,
          new DiscardEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { min: 1, max: 2, allowCancel: false }
          ),
          (transfers) => {
            if (transfers === null) {
              effect.damage = 0;
              return state;
            }
            const cardsDiscarded = transfers.length;
            effect.damage = 120 * cardsDiscarded;
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = player.discard;
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
            return state;
          }
        );
      }
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const pokemonCard = effect.target.getPokemonCard();
        if (pokemonCard !== this) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        effect.damage = Math.max(0, effect.damage - 30);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-phantasmal-flames/mega-gengar-ex.ts
  init_game();
