  init_check_effects();
  var MegaGengarex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Haunter";
      this._tags = ["Mega ex" /* POKEMON_SV_MEGA */, "ex" /* POKEMON_ex */];
      this.cardType = [D];
      this.hp = 350;
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Shadowy Concealment",
          powerType: 2 /* ABILITY */,
          text: "If 1 of your [D] Pok\xE9mon is Knocked Out by damage from an attack from your opponent's Pok\xE9mon ex, that player takes 1 fewer Prize card. The effect of Shadowy Concealment doesn't stack."
        }
      ];
      this.attacks = [
        {
          name: "Void Gale",
          cost: [D, D],
          damage: 230,
          text: "Move an Energy from this Pokemon to 1 of your Benched Pokemon."
        }
      ];
      this.regulationMark = "I";
      this.set = "PFL";
      this.setNumber = "56";
      this.cardImage = "assets/cardback.png";
      this.name = "Mega Gengar ex";
      this.fullName = "Mega Gengar ex MBG";
      this.VOID_GALE_MARKER = "VOID_GALE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (state.phase !== 3 /* ATTACK */ || state.players[state.activePlayer] !== opponent) {
          return state;
        }
        let hasThisInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            hasThisInPlay = true;
          }
        });
        if (!hasThisInPlay || IS_ABILITY_BLOCKED(store, state, opponent, this)) {
          return state;
        }
        const checkType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkType);
        const isDarkPokemon = checkType.cardTypes.includes(D);
        if (!isDarkPokemon) {
          return state;
        }
        const attackingPokemon = opponent.active.getPokemonCard();
        const attackerIsEx = attackingPokemon?.hasTag("ex" /* POKEMON_ex */) === true;
        if (!attackerIsEx) {
          return state;
        }
        const NON_STACK_MARKER = "MEGA_GENGAR_SHADOW_HIDING_APPLIED";
        if (effect.target.marker.hasMarker(NON_STACK_MARKER, this)) {
          return state;
        }
        effect.target.marker.addMarker(NON_STACK_MARKER, this);
        if (effect.prizeCount > 0) {
          effect.prizeCount -= 1;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        ADD_MARKER(this.VOID_GALE_MARKER, effect.player, this);
        return state;
      }
      if (effect instanceof AfterAttackEffect && HAS_MARKER(this.VOID_GALE_MARKER, effect.player, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (hasBench === false) {
          return state;
        }
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.active,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 1, max: 1 }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.VOID_GALE_MARKER, this);
      return state;
    }
  };

