  var PunkHelmet = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "PFL";
      this.name = "Punk Helmet";
      this.fullName = "Punk Helmet PFL";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "92";
      this.regulationMark = "I";
      this.text = "If the [D] Pok\xE9mon this card is attached to is in the Active Spot and is damaged by an attack from your opponent's Pok\xE9mon (even if this Pok\xE9mon is Knocked Out), place 4 damage counters on the Attacking Pok\xE9mon.";
      this.damageDealt = false;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        if (effect.damage <= 0 || player === targetPlayer || targetPlayer.active !== effect.target) {
          return state;
        }
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        const checkPokemonType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkPokemonType);
        if (checkPokemonType.cardTypes.includes(7 /* DARK */) && state.phase === 3 /* ATTACK */) {
          effect.source.damage += 40;
        }
      }
      return state;
    }
  };

