  var WonderPatch = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.regulationMark = "I";
      this.set = "PFL";
      this.name = "Wondrous Patch";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "94";
      this.fullName = "Wonder Patch MBD";
      this.text = "Attach a basic [P] Energy card from your discard pile to 1 of your Benched [P] Pok\xE9mon.";
    }
    canPlay(store, state, player) {
      const hasEnergyInDiscard = player.discard.cards.some(
        (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(5 /* PSYCHIC */)
      );
      if (!hasEnergyInDiscard) {
        return false;
      }
      let hasPsychicOnBench = false;
      player.bench.forEach((bench) => {
        if (bench.cards.length === 0) {
          return;
        }
        const checkPokemonTypeEffect = new CheckPokemonTypeEffect(bench);
        store.reduceEffect(state, checkPokemonTypeEffect);
        if (checkPokemonTypeEffect.cardTypes.includes(5 /* PSYCHIC */)) {
          hasPsychicOnBench = true;
        }
      });
      if (!hasPsychicOnBench) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides.includes(5 /* PSYCHIC */);
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        let hasDarkPokemonOnBench = false;
        const blockedTo = [];
        player.bench.forEach((bench, index) => {
          if (bench.cards.length === 0) {
            return;
          }
          const checkPokemonTypeEffect = new CheckPokemonTypeEffect(bench);
          store.reduceEffect(state, checkPokemonTypeEffect);
          if (checkPokemonTypeEffect.cardTypes.includes(5 /* PSYCHIC */)) {
            hasDarkPokemonOnBench = true;
          } else {
            const target = {
              player: 2 /* BOTTOM_PLAYER */,
              slot: 2 /* BENCH */,
              index
            };
            blockedTo.push(target);
          }
        });
        if (!hasDarkPokemonOnBench) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        effect.preventDefault = true;
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Psychic Energy" },
            { allowCancel: false, min: 1, max: 1, blockedTo }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, {
                cards: [transfer.card],
                sourceCard: this
              });
            }
          }
        );
      }
      return state;
    }
  };

