  var AntheaAndConcordia = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "I";
      this.set = "ASC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "182";
      this.name = "Anthea & Concordia";
      this.fullName = "Anthea & Concordia M2a";
      this.extraPrizes = false;
      this.text = `You can use this card only if you have N's Darmanitan, N's Zoroark ex, N's Vanilluxe, N's Klinklang, N's Reshiram, and N's Zekrom in play.

During this turn, if your opponent's Active Pok\xE9mon is Knocked Out by damage from an attack used by your N's Pok\xE9mon, take 3 more Prize cards.`;
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      const requiredPokemon = [
        "N's Darmanitan",
        "N's Zoroark ex",
        "N's Vanilluxe",
        "N's Klinklang",
        "N's Reshiram",
        "N's Zekrom"
      ];
      const foundPokemon = /* @__PURE__ */ new Set();
      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, pokemonCard) => {
        if (requiredPokemon.includes(pokemonCard.name)) {
          foundPokemon.add(pokemonCard.name);
        }
      });
      if (foundPokemon.size !== requiredPokemon.length) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const requiredPokemon = [
          "N's Darmanitan",
          "N's Zoroark ex",
          "N's Vanilluxe",
          "N's Klinklang",
          "N's Reshiram",
          "N's Zekrom"
        ];
        const foundPokemon = /* @__PURE__ */ new Set();
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, pokemonCard) => {
          if (requiredPokemon.includes(pokemonCard.name)) {
            foundPokemon.add(pokemonCard.name);
          }
        });
        if (foundPokemon.size !== requiredPokemon.length) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        this.extraPrizes = true;
        return state;
      }
      if (effect instanceof KnockOutEffect && effect.target === effect.player.active) {
        const knockedOutPlayer = effect.player;
        const attacker = StateUtils.getOpponent(state, knockedOutPlayer);
        if (!attacker.supporter.cards.includes(this) || !this.extraPrizes) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */ || state.players[state.activePlayer] !== attacker) {
          return state;
        }
        if (effect.target === knockedOutPlayer.active) {
          const attackingPokemon = attacker.active.getPokemonCard();
          if (attackingPokemon) {
            const isNsPokemon = attackingPokemon.name.startsWith("N's") || attackingPokemon.hasTag("N's" /* NS */);
            if (isNsPokemon && effect.prizeCount > 0) {
              effect.prizeCount += 3;
            }
          }
          this.extraPrizes = false;
          MOVE_CARDS(store, state, attacker.supporter, attacker.discard, { cards: [this], sourceCard: this });
        }
        return state;
      }
      return state;
    }
  };

