  var Camerupt7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Numel";
      this.cardType = [R];
      this.hp = 140;
      this.weakness = [{ type: W }];
      this.resistance = [];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Roasting Burn",
          cost: [R],
          damage: 110,
          text: "If your opponent's Active Pok\xE9mon isn't Burned, this attack does nothing."
        },
        {
          name: "Power Stomp",
          cost: [R, C, C, C],
          damage: 170,
          text: "Discard 2 Energy from this Pok\xE9mon."
        }
      ];
      this.regulationMark = "I";
      this.set = "ASC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "28";
      this.name = "Camerupt";
      this.fullName = "Camerupt M2a";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        const activePokemon = opponent.active;
        if (!activePokemon.specialConditions.includes(4 /* BURNED */)) {
          effect.damage = 0;
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const energyCount = player.active.cards.filter(
          (card) => card.superType === 3 /* ENERGY */
        ).length;
        if (energyCount >= 2) {
          state = store.prompt(state, new DiscardEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: false, min: 2, max: 2 }
          ), (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return state;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              MOVE_CARDS(store, state, source, player.discard, { cards: [transfer.card], sourceCard: this });
            }
          });
        }
      }
      return state;
    }
  };

