  var Frosmoth4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Snom";
      this.cardType = [W];
      this.hp = 110;
      this.weakness = [{ type: M }];
      this.resistance = [];
      this.retreat = [C, C];
      this.powers = [{
        name: "Alluring Wings",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, if this Pok\xE9mon is in your Active Spot, you may use this Ability. Each player draws a card."
      }];
      this.attacks = [{
        name: "Cold Cyclone",
        cost: [W, W],
        damage: 90,
        text: "Move a [W] Energy from this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
      }];
      this.regulationMark = "I";
      this.set = "ASC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "53";
      this.name = "Frosmoth";
      this.fullName = "Frosmoth M2a";
      this.INVITING_WINGS_MARKER = "INVITING_WINGS_MARKER";
      this.COLD_CYCLONE_MARKER = "COLD_CYCLONE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.INVITING_WINGS_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.INVITING_WINGS_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.INVITING_WINGS_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const pokemonCard = player.active.getPokemonCard();
        if (pokemonCard !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.INVITING_WINGS_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const opponent = StateUtils.getOpponent(state, player);
        if (player.deck.cards.length === 0 && opponent.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.deck.cards.length > 0) {
          DRAW_CARDS(store, state, player, 1);
        }
        if (opponent.deck.cards.length > 0) {
          DRAW_CARDS(store, state, opponent, 1);
        }
        player.marker.addMarker(this.INVITING_WINGS_MARKER, this);
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.getPokemonCard() === this) {
            cardList.addBoardEffect(0 /* ABILITY_USED */);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        ADD_MARKER(this.COLD_CYCLONE_MARKER, effect.player, this);
        return state;
      }
      if (effect instanceof AfterAttackEffect && HAS_MARKER(this.COLD_CYCLONE_MARKER, effect.player, this)) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (hasBench === false) {
          return state;
        }
        const validTypes = [3 /* WATER */, 0 /* ANY */];
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.active,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: 1, max: 1, validCardTypes: validTypes }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.COLD_CYCLONE_MARKER, this);
      return state;
    }
  };

