  var NightMine = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.regulationMark = "I";
      this.set = "ASC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "197";
      this.name = "Nighttime Mine";
      this.fullName = "Night Mine M2a";
      this.text = "Attacks used by each Tera Pok\xE9mon in play (both yours and your opponent's) cost [C] more.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const pokemonCard = player.active.getPokemonCard();
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, player, player.active, this)) {
          return state;
        }
        if (pokemonCard && pokemonCard.hasTag("Tera" /* POKEMON_TERA */)) {
          const index = effect.cost.indexOf(9 /* COLORLESS */);
          if (index > -1) {
            effect.cost.splice(index, 0, 9 /* COLORLESS */);
          } else {
            effect.cost.push(9 /* COLORLESS */);
          }
          return state;
        }
        return state;
      }
      return state;
    }
  };

