  var LightBall = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "ASC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "191";
      this.name = "Light Ball";
      this.fullName = "Light Ball M2a";
      this.regulationMark = "I";
      this.text = "Attacks used by the Pikachu ex this card is attached to do 50 more damage to your opponent's Active Pok\xE9mon ex (before applying Weakness and Resistance).";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.source.tools.includes(this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        const sourceCard = effect.source.getPokemonCard();
        if (!sourceCard || sourceCard.name !== "Pikachu ex") {
          return state;
        }
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        if (effect.target !== opponent.active) {
          return state;
        }
        const targetCard2 = effect.target.getPokemonCard();
        if (targetCard2 && targetCard2.hasTag("ex" /* POKEMON_ex */) && effect.damage > 0) {
          effect.damage += 50;
        }
      }
      return state;
    }
  };

