  var TeamRocketsHonchkrow = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Team Rocket's Murkrow";
      this._tags = ["Team Rocket's" /* TEAM_ROCKET */];
      this.cardType = [D];
      this.hp = 130;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Rocket Feathers",
          cost: [C, C],
          damage: 60,
          damageCalculation: "x",
          text: 'You may discard any number of Supporter cards with "Team Rocket" in their name from your hand, and this attack does 60 damage for each card you discarded in this way.'
        },
        {
          name: "Hammer In",
          cost: [D, C, C],
          damage: 100,
          text: ""
        }
      ];
      this.regulationMark = "I";
      this.set = "ASC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "127";
      this.name = "Team Rocket's Honchkrow";
      this.fullName = "Team Rocket's Honchkrow M2a";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hand = player.hand;
        const teamRocketSupporters = hand.cards.filter(
          (card) => card instanceof TrainerCard && card.trainerType === 1 /* SUPPORTER */ && card.name.includes("Team Rocket")
        );
        const blocked = [];
        hand.cards.forEach((card, index) => {
          if (!(card instanceof TrainerCard && card.trainerType === 1 /* SUPPORTER */ && card.name.includes("Team Rocket"))) {
            blocked.push(index);
          }
        });
        state = store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            hand,
            { superType: 2 /* TRAINER */ },
            { min: 0, max: teamRocketSupporters.length, allowCancel: false, blocked }
          ),
          (selected) => {
            const discardCount = selected || [];
            if (discardCount.length === 0) {
              effect.damage = 0;
              return state;
            }
            MOVE_CARDS(store, state, player.hand, player.discard, { cards: discardCount, sourceCard: this });
            effect.damage = 60 * discardCount.length;
          }
        );
      }
      return state;
    }
  };

