  init_prefabs();
  var ErikasVileplumeex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Erika's Gloom";
      this._tags = ["ex" /* POKEMON_ex */, "Erika's" /* ERIKAS */];
      this.cardType = [G];
      this.hp = 310;
      this.weakness = [{ type: R }];
      this.resistance = [];
      this.retreat = [C];
      this.powers = [
        {
          name: "Lovely Fragrance",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may use this Ability. Heal 30 damage from each of your Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Bloom Powder",
          cost: [G, G, C],
          damage: 160,
          text: "Your opponent's Active Pokemon is now Poisoned and Asleep."
        }
      ];
      this.regulationMark = "I";
      this.set = "ASC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "3";
      this.name = "Erika's Vileplume ex";
      this.fullName = "Erika's Vileplume ex MC";
      this.ENVIOUS_SCENT_MARKER = "ENVIOUS_SCENT_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.ENVIOUS_SCENT_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList.damage > 0) {
            const healEffect = new HealEffect(player, cardList, 30);
            store.reduceEffect(state, healEffect);
          }
        });
        player.marker.addMarker(this.ENVIOUS_SCENT_MARKER, this);
        ABILITY_USED(player, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const specialConditionEffect = new AddSpecialConditionsEffect(effect, [
          3 /* POISONED */,
          2 /* ASLEEP */
        ]);
        specialConditionEffect.target = opponent.active;
        return store.reduceEffect(state, specialConditionEffect);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.ENVIOUS_SCENT_MARKER, this)) {
        effect.player.marker.removeMarker(this.ENVIOUS_SCENT_MARKER, this);
      }
      return state;
    }
  };

