  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-ascended-heroes/regice-ex.ts
  init_game();
  init_attack_effects();
  init_prefabs();
  var Regiceex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [W];
      this.hp = 230;
      this.weakness = [{ type: L }];
      this.resistance = [];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Regi Charge",
          cost: [C],
          damage: 0,
          text: "Attach up to 2 Basic [W] Energy cards from your discard pile to this Pok\xE9mon."
        },
        {
          name: "Ice Prison",
          cost: [W, C, C, C],
          damage: 140,
          text: "Discard 2 Energy from this Pok\xE9mon, and your opponent's Active Pok\xE9mon is now Paralyzed."
        }
      ];
      this.regulationMark = "I";
      this.set = "ASC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "48";
      this.name = "Regice ex";
      this.fullName = "Regice ex MC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const hasEnergyInDiscard = player.discard.cards.some((c) => {
          return c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.provides && c.provides.includes(3 /* WATER */);
        });
        if (!hasEnergyInDiscard) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_ACTIVE,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
            { allowCancel: false, min: 1, max: 2 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
        return state;
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const energyCount = player.active.cards.filter(
          (card) => card.superType === 3 /* ENERGY */
        ).length;
        if (energyCount >= 2) {
          state = store.prompt(
            state,
            new DiscardEnergyPrompt(
              player.id,
              GameMessage.CHOOSE_ENERGIES_TO_DISCARD,
              2 /* BOTTOM_PLAYER */,
              [1 /* ACTIVE */],
              { superType: 3 /* ENERGY */ },
              { allowCancel: false, min: 2, max: 2 }
            ),
            (transfers) => {
              transfers = transfers || [];
              if (transfers.length === 0) {
                return state;
              }
              for (const transfer of transfers) {
                const source = StateUtils.getTarget(state, player, transfer.from);
                MOVE_CARDS(store, state, source, player.discard, { cards: [transfer.card], sourceCard: this });
              }
            }
          );
        }
        const specialConditionEffect = new AddSpecialConditionsEffect(effect, [
          0 /* PARALYZED */
        ]);
        specialConditionEffect.target = opponent.active;
        return store.reduceEffect(state, specialConditionEffect);
      }
      return state;
    }
  };

