  init_game();
  init_prefabs();
  var Azumarillex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Marill";
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [P];
      this.hp = 270;
      this.weakness = [{ type: M }];
      this.resistance = [];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Bubble Gathering",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "As often as you like during your turn, you may use this Ability. Move an Energy from 1 of your other Pok\xE9mon to this Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Energy Balloon",
          cost: [C, C, C],
          damage: 60,
          damageCalculation: "+",
          text: "This attack does 40 more damage for each [P] Energy attached to this Pokemon."
        }
      ];
      this.regulationMark = "I";
      this.set = "ASC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "84";
      this.name = "Azumarill ex";
      this.fullName = "Azumarill ex MC";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        return store.prompt(
          state,
          new MoveEnergyPrompt(
            player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: true, min: 0, max: 1 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length > 0) {
              for (const transfer of transfers) {
                if (StateUtils.getTarget(state, player, transfer.to) !== StateUtils.findCardList(state, this)) {
                  throw new GameError(GameMessage.INVALID_TARGET);
                }
                const source = StateUtils.getTarget(state, player, transfer.from);
                const target = StateUtils.getTarget(state, player, transfer.to);
                MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
              }
            }
            ABILITY_USED(player, this);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let psychicEnergyCount = 0;
        player.active.energies.cards.forEach((card) => {
          if (card.superType === 3 /* ENERGY */) {
            const energyCard = card;
            if (energyCard.energyType === "P" || energyCard.provides?.includes("P")) {
              psychicEnergyCount++;
            }
          }
        });
        effect.damage += 40 * psychicEnergyCount;
      }
      return state;
    }
  };

