  var Waitress = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "ASC";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "215";
      this.name = "Waitress";
      this.fullName = "Waitress MC";
      this.text = "Look at the top 6 cards of your deck, and attach a Basic Energy you find there to 1 of your Pok\xE9mon. Shuffle the other cards back into your deck.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const deckTop = new CardList();
        const cardsToLook = Math.min(6, player.deck.cards.length);
        MOVE_CARDS(store, state, player.deck, deckTop, { count: cardsToLook, sourceCard: this });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            deckTop,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { min: 0, max: 1, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              return store.prompt(
                state,
                new AttachEnergyPrompt(
                  player.id,
                  GameMessage.ATTACH_ENERGY_CARDS,
                  deckTop,
                  2 /* BOTTOM_PLAYER */,
                  [1 /* ACTIVE */, 2 /* BENCH */],
                  {},
                  { allowCancel: false, min: 1, max: 1 }
                ),
                (transfers) => {
                  transfers = transfers || [];
                  if (transfers.length > 0) {
                    for (const transfer of transfers) {
                      const target = StateUtils.getTarget(state, player, transfer.to);
                      MOVE_CARDS(store, state, deckTop, target, {
                        cards: [transfer.card],
                        sourceCard: this
                      });
                    }
                  }
                  MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: this });
                  SHUFFLE_DECK(store, state, player);
                }
              );
            } else {
              MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: this });
              SHUFFLE_DECK(store, state, player);
            }
          }
        );
      }
      return state;
    }
  };

