  function* useAttack2(next, store, state, effect) {
    const player = effect.player;
    if (player.active.getPokemonCard()?.name !== "Mega Zygarde ex") {
      throw new GameError(GameMessage.CANNOT_USE_ATTACK);
    }
    const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
    state = store.reduceEffect(state, checkProvidedEnergy);
    const cards = checkProvidedEnergy.energyMap.map((e) => e.card);
    const discardEnergy2 = new DiscardCardsEffect(effect, cards);
    discardEnergy2.target = player.active;
    store.reduceEffect(state, discardEnergy2);
    return state;
  }
  var CoreMemory = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.regulationMark = "J";
      this.set = "POR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "70";
      this.name = "Core Memory";
      this.fullName = "Core Memory M3";
      this.attacks = [
        {
          name: "Geobuster",
          cost: [F, F, F, F],
          damage: 350,
          text: "Discard all Energy attached to this Pok\xE9mon."
        }
      ];
      this.text = "The Mega Zygarde ex this card is attached to can use the attack on this card. (You still need the necessary Energy to use this attack.)";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect && effect.attack === this.attacks[0]) {
        const pokemonCard = effect.player.active.getPokemonCard();
        if (pokemonCard?.name !== "Mega Zygarde ex") {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        if (pokemonCard && "getColorlessReduction" in pokemonCard) {
          const colorlessReudction = pokemonCard.getColorlessReduction(
            state
          );
          for (let i = 0; i < colorlessReudction && effect.cost.includes(9 /* COLORLESS */); i++) {
            const index = effect.cost.indexOf(9 /* COLORLESS */);
            if (index !== -1) {
              effect.cost.splice(index, 1);
            }
          }
        }
      }
      if (effect instanceof CheckPokemonAttacksEffect && effect.player.active.getPokemonCard()?.tools.includes(this) && !effect.attacks.includes(this.attacks[0])) {
        effect.attacks.push(this.attacks[0]);
      }
      if (effect instanceof AttackEffect && effect.attack === this.attacks[0]) {
        const generator = useAttack2(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

