  var Dewgong7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Seel";
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Wash Out",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "As often as you like during your turn, you may use this Ability. Move a [W] Energy from 1 of your Benched Pok\xE9mon to your Active Pok\xE9mon. "
      }];
      this.attacks = [{
        name: "Wave Splash",
        cost: [W, W],
        damage: 60,
        text: ""
      }];
      this.regulationMark = "J";
      this.set = "POR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "19";
      this.name = "Dewgong";
      this.fullName = "Dewgong M3";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        let hasWaterEnergyOnBench = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          if (cardList !== player.active) {
            const checkEnergy = new CheckProvidedEnergyEffect(player, cardList);
            store.reduceEffect(state, checkEnergy);
            if (checkEnergy.energyMap.some((em) => em.provides.includes(3 /* WATER */))) {
              hasWaterEnergyOnBench = true;
            }
          }
        });
        if (!hasWaterEnergyOnBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blockedFrom = [];
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList === player.active) {
            blockedFrom.push(target);
          } else {
            blockedTo.push(target);
          }
        });
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList !== player.active) {
            blockedTo.push(target);
          }
        });
        return store.prompt(state, new MoveEnergyPrompt(
          player.id,
          GameMessage.MOVE_ENERGY_CARDS,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: 0, max: 1, blockedFrom, blockedTo }
        ), (transfers) => {
          if (!transfers || transfers.length === 0) {
            return state;
          }
          for (const transfer of transfers) {
            const source = StateUtils.getTarget(state, player, transfer.from);
            const target = StateUtils.getTarget(state, player, transfer.to);
            const checkEnergy = new CheckProvidedEnergyEffect(player, source);
            store.reduceEffect(state, checkEnergy);
            const energyEntry = checkEnergy.energyMap.find((em) => em.card === transfer.card);
            if (!energyEntry || !energyEntry.provides.includes(3 /* WATER */)) {
              continue;
            }
            if (source.energies.cards.includes(transfer.card)) {
              MOVE_CARDS(store, state, source.energies, target.energies, { cards: [transfer.card], sourceCard: this });
              if (!target.cards.includes(transfer.card)) {
                target.cards.push(transfer.card);
              }
            } else {
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
              if (!target.energies.cards.includes(transfer.card)) {
                target.energies.cards.push(transfer.card);
              }
            }
          }
        });
      }
      return state;
    }
  };

