  var MegaStarmieex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Staryu";
      this._tags = ["Mega ex" /* POKEMON_SV_MEGA */, "ex" /* POKEMON_ex */];
      this.cardType = [W];
      this.hp = 330;
      this.weakness = [{ type: L }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Jetting Blow",
          cost: [W],
          damage: 120,
          text: "This attack also does 50 damage to 1 of your opponent's Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
        },
        {
          name: "Nebula Beam",
          cost: [C, C, C],
          damage: 210,
          shredAttack: true,
          text: "This attack's damage isn't affected by Weakness, Resistance, or any effects on your opponent's Active Pok\xE9mon."
        }
      ];
      this.regulationMark = "J";
      this.set = "POR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "21";
      this.name = "Mega Starmie ex";
      this.fullName = "Mega Starmie ex M3";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const benchedTargets = opponent.bench.filter((b) => b.cards.length > 0);
        if (benchedTargets.length > 0) {
          return store.prompt(
            state,
            new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
              1 /* TOP_PLAYER */,
              [2 /* BENCH */],
              { min: 1, max: 1, allowCancel: false }
            ),
            (selected) => {
              const targets = selected || [];
              if (targets.length > 0) {
                const damageEffect = new PutDamageEffect(effect, 50);
                damageEffect.target = targets[0];
                store.reduceEffect(state, damageEffect);
              }
            }
          );
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const opponent = effect.opponent;
        effect.ignoreResistance = true;
        const applyWeakness = new ApplyWeaknessEffect(effect, 210);
        store.reduceEffect(state, applyWeakness);
        const damage = applyWeakness.damage;
        effect.damage = 0;
        if (damage > 0) {
          opponent.active.damage += damage;
          const afterDamage = new AfterDamageEffect(effect, damage);
          state = store.reduceEffect(state, afterDamage);
        }
      }
      return state;
    }
  };

