  var Salazzleex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Salandit";
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [R];
      this.hp = 260;
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Nasty Plot",
          cost: [R],
          damage: 0,
          text: "Search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck."
        },
        {
          name: "Dire Nails",
          cost: [R, R],
          damage: 100,
          text: "Your opponent's Active Pok\xE9mon is now Burned and Poisoned. Switch this Pok\xE9mon with 1 of your Benched Pok\xE9mon."
        }
      ];
      this.regulationMark = "J";
      this.set = "POR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "16";
      this.name = "Salazzle ex";
      this.fullName = "Salazzle ex M3";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const maxCards = Math.min(2, player.deck.cards.length);
        let cards = [];
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            {},
            { min: 0, max: maxCards, allowCancel: false }
          ),
          (selected) => {
            cards = selected || [];
            MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this });
            return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        YOUR_OPPPONENTS_ACTIVE_POKEMON_IS_NOW_POISIONED(store, state, effect);
        ADD_BURN_TO_PLAYER_ACTIVE(store, state, opponent, this);
      }
      if (effect instanceof AfterAttackEffect && effect.attack === this.attacks[1]) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (hasBench) {
          return store.prompt(
            state,
            new ChoosePokemonPrompt(
              player.id,
              GameMessage.CHOOSE_POKEMON_TO_SWITCH,
              2 /* BOTTOM_PLAYER */,
              [2 /* BENCH */],
              { allowCancel: false }
            ),
            (selected) => {
              const targets = selected || [];
              if (targets.length > 0) {
                player.active.clearEffects();
                player.switchPokemon(targets[0]);
              }
            }
          );
        }
      }
      return state;
    }
  };

