  var Shinx11 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 70;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.attacks = [{
        name: "Double Scratch",
        cost: [L],
        damage: 10,
        damageCalculation: "x",
        text: "Flip 2 coins. This attack does 10 damage for each heads."
      }];
      this.regulationMark = "J";
      this.set = "POR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "26";
      this.name = "Shinx";
      this.fullName = "Shinx M3";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let headsCount = 0;
        let flipsDone = 0;
        const flipCoins = (s) => {
          if (flipsDone >= 2) {
            effect.damage = headsCount * 10;
            return s;
          }
          const coinFlipEffect = new CoinFlipEffect(player, (result) => {
            flipsDone++;
            if (result) {
              headsCount++;
            }
            if (flipsDone < 2) {
              flipCoins(s);
            } else {
              effect.damage = headsCount * 10;
            }
          });
          return store.reduceEffect(s, coinFlipEffect);
        };
        return flipCoins(state);
      }
      return state;
    }
  };

