  var EnergySwatter = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.regulationMark = "J";
      this.set = "POR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "73";
      this.name = "Energy Swatter";
      this.fullName = "Energy Swatter M3";
      this.text = "Your opponent reveals their hand, and you choose an Energy card you find there and put it on the bottom of their deck.";
    }
    canPlay(store, state, player) {
      const opponent = StateUtils.getOpponent(state, player);
      if (opponent.hand.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.hand.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.discard, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        store.prompt(
          state,
          new ShowCardsPrompt(
            player.id,
            GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
            opponent.hand.cards
          ),
          () => state
        );
        const energyCards = opponent.hand.cards.filter((card) => card.superType === 3 /* ENERGY */);
        if (energyCards.length === 0) {
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            opponent.hand,
            { superType: 3 /* ENERGY */ },
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, opponent.hand, opponent.deck, {
                cards: [cards[0]],
                sourceCard: this
              });
            }
          }
        );
      }
      return state;
    }
  };

