  init_game();
  init_play_card_effects();
  init_game_error();
  init_prefabs();
  var RosasEncouragement = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "J";
      this.set = "POR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "84";
      this.name = "Rosa's Encouragement";
      this.fullName = "Rosa's Encouragement M3";
      this.text = `You can use this card only if you have more Prize cards remaining than your opponent.

Attach up to 2 Basic Energy cards from your discard pile to 1 of your Stage 2 Pok\xE9mon.`;
    }
    canPlay(store, state, player) {
      const opponent = StateUtils.getOpponent(state, player);
      if (player.supporterTurn > 0) {
        return false;
      }
      if (player.getPrizeLeft() <= opponent.getPrizeLeft()) {
        return false;
      }
      const basicEnergyInDiscard = player.discard.cards.filter(
        (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
      );
      if (basicEnergyInDiscard.length === 0) {
        return false;
      }
      const stage2Pokemon = [];
      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
        const pokemonCard = cardList.getPokemonCard();
        if (pokemonCard && pokemonCard.stage === 4 /* STAGE_2 */) {
          stage2Pokemon.push(cardList);
        }
      });
      if (stage2Pokemon.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        if (player.getPrizeLeft() <= opponent.getPrizeLeft()) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const basicEnergyInDiscard = player.discard.cards.filter(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */
        );
        if (basicEnergyInDiscard.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const stage2Pokemon = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const pokemonCard = cardList.getPokemonCard();
          if (pokemonCard && pokemonCard.stage === 4 /* STAGE_2 */) {
            stage2Pokemon.push(cardList);
          }
        });
        if (stage2Pokemon.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        const maxToAttach = Math.min(2, basicEnergyInDiscard.length);
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_CARDS,
            player.discard,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, stage: 4 /* STAGE_2 */ },
            { allowCancel: false, min: 0, max: maxToAttach, sameTarget: true }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.discard, target, {
                cards: [transfer.card],
                sourceCard: this
              });
            }
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-perfect-order/jacinthe.ts
  init_game();
