  var Jacinthe = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "J";
      this.set = "POR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "75";
      this.name = "Jacinthe";
      this.fullName = "Jacinthe M3";
      this.text = "Heal 150 damage from 1 of your [P] Pokemon.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      let hasDamagedPsychicPokemon = false;
      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
        const pokemonCard = cardList.getPokemonCard();
        if (pokemonCard && pokemonHasCardType(pokemonCard, 5 /* PSYCHIC */) && cardList.damage > 0) {
          hasDamagedPsychicPokemon = true;
        }
      });
      if (!hasDamagedPsychicPokemon) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const supporterTurn = player.supporterTurn;
        if (supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const psychicPokemon = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const pokemonCard = cardList.getPokemonCard();
          if (pokemonCard) {
            const checkType = new CheckPokemonTypeEffect(cardList);
            store.reduceEffect(state, checkType);
            if (checkType.cardTypes.includes(5 /* PSYCHIC */)) {
              psychicPokemon.push(cardList);
            }
          }
        });
        if (psychicPokemon.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        let hasDamagedPsychicPokemon = false;
        for (const cardList of psychicPokemon) {
          if (cardList.damage > 0) {
            hasDamagedPsychicPokemon = true;
            break;
          }
        }
        if (!hasDamagedPsychicPokemon) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_HEAL,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { allowCancel: false }
          ),
          (selected) => {
            const targets = selected || [];
            if (targets.length > 0) {
              const target = targets[0];
              const checkType = new CheckPokemonTypeEffect(target);
              store.reduceEffect(state, checkType);
              if (checkType.cardTypes.includes(5 /* PSYCHIC */)) {
                const healEffect = new HealEffect(player, target, 150);
                store.reduceEffect(state, healEffect);
              }
            }
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-perfect-order/telepath-psychic-energy.ts
  init_game();
  init_card_types();
  init_energy_card();
  init_play_card_effects();
  init_prefabs();
  init_check_effects();
  init_pokemon_card();
  var TelepathPsychicEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [5 /* PSYCHIC */];
      this.energyType = 1 /* SPECIAL */;
      this.regulationMark = "J";
      this.set = "POR";
      this.name = "Telepathic Psychic Energy";
      this.fullName = "Telepath [P] Energy M3";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "88";
      this.text = "As long as this card is attached to a Pok\xE9mon, it provides [P] Energy.\n\nWhen you attach this card from your hand to a [P] Pok\xE9mon, search your deck for up to 2 Basic [P] Pok\xE9mon and put them onto your Bench. Then, shuffle your deck.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        effect.energyMap.push({ card: this, provides: [5 /* PSYCHIC */] });
      }
      if (effect instanceof AttachEnergyEffect && effect.energyCard === this) {
        const player = effect.player;
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, player, this, effect.target)) {
          return state;
        }
        const checkType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkType);
        if (!checkType.cardTypes.includes(5 /* PSYCHIC */)) {
          return state;
        }
        if (GET_PLAYER_BENCH_SLOTS(player).length === 0) {
          return state;
        }
        const basicPsychicPokemon = player.deck.cards.filter(
          (card) => card instanceof PokemonCard && card.stage === 2 /* BASIC */
        );
        const validPokemon = [];
        for (const card of basicPsychicPokemon) {
          if (card instanceof PokemonCard && pokemonHasCardType(card, 5 /* PSYCHIC */)) {
            validPokemon.push(card);
          }
        }
        if (validPokemon.length === 0) {
          return state;
        }
        const maxToPut = Math.min(2, validPokemon.length, GET_PLAYER_BENCH_SLOTS(player).length);
        SEARCH_YOUR_DECK_FOR_POKEMON_AND_PUT_ONTO_BENCH(
          store,
          state,
          player,
          {
            stage: 2 /* BASIC */,
            cardType: [5 /* PSYCHIC */]
          },
          { min: 0, max: maxToPut }
        );
      }
      return state;
    }
  };

