      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        if (!player.active.cannotUseAttacksNextTurnPending.includes("Dark Strike")) {
          player.active.cannotUseAttacksNextTurnPending.push("Dark Strike");
        }
      }
