  var Aromatisse5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Spritzee";
      this.cardType = [P];
      this.hp = 120;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.powers = [{
        name: "Scent Collection",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, you may use this Ability. Search your deck for up to 2 Basic [P] Energy cards, reveal them, and put them into your hand. Then, shuffle your deck. "
      }];
      this.attacks = [{
        name: "Draining Kiss",
        cost: [P, C],
        damage: 50,
        text: "Heal 30 damage from this Pok\xE9mon."
      }];
      this.regulationMark = "J";
      this.set = "POR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "36";
      this.name = "Aromatisse";
      this.fullName = "Aromatisse M3";
      this.FRAGRANCE_COLLECTION_MARKER = "FRAGRANCE_COLLECTION_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.marker.hasMarker(this.FRAGRANCE_COLLECTION_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        ABILITY_USED(player, this);
        player.marker.addMarkerToState(this.FRAGRANCE_COLLECTION_MARKER);
        const basicPsychicEnergy = player.deck.cards.filter(
          (card) => card.superType === 3 /* ENERGY */ && card.energyType === 0 /* BASIC */ && card.provides.includes(5 /* PSYCHIC */)
        );
        if (basicPsychicEnergy.length === 0) {
          return state;
        }
        const maxToTake = Math.min(2, basicPsychicEnergy.length);
        let selectedCards = [];
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.deck,
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Psychic Energy" },
          { min: 0, max: maxToTake, allowCancel: false }
        ), (selected) => {
          selectedCards = selected || [];
          MOVE_CARDS(store, state, player.deck, player.hand, { cards: selectedCards, sourceCard: this });
          if (selectedCards.length > 0) {
            const opponent = StateUtils.getOpponent(state, player);
            store.prompt(state, new ShowCardsPrompt(
              opponent.id,
              GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
              selectedCards
            ), () => state);
          }
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.FRAGRANCE_COLLECTION_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const healEffect = new HealEffect(player, player.active, 30);
        store.reduceEffect(state, healEffect);
      }
      return state;
    }
  };

