  var Volcanion5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: L }];
      this.retreat = [C, C, C];
      this.attacks = [
        {
          name: "Strength",
          cost: [W, C],
          damage: 50,
          text: ""
        },
        {
          name: "Powerful Steam",
          cost: [W, W, C],
          damage: 90,
          damageCalculation: "x",
          text: "Flip a coin for each [W] Energy attached to this Pok\xE9mon. This attack does 90 damage for each heads."
        }
      ];
      this.regulationMark = "J";
      this.set = "POR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "25";
      this.name = "Volcanion";
      this.fullName = "Volcanion M3";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        let headsCount = 0;
        let flipsDone = 0;
        const waterEnergyCount = player.active.cards.filter(
          (card) => card.superType === 3 /* ENERGY */ && card.provides.includes(3 /* WATER */)
        ).length;
        if (waterEnergyCount === 0) {
          effect.damage = 0;
          return state;
        }
        const flipCoins = (s) => {
          if (flipsDone >= waterEnergyCount) {
            effect.damage = headsCount * 90;
            return s;
          }
          const coinFlipEffect = new CoinFlipEffect(player, (result) => {
            flipsDone++;
            if (result === true) {
              headsCount++;
            }
            if (flipsDone < waterEnergyCount) {
              flipCoins(s);
            } else {
              effect.damage = headsCount * 90;
            }
          });
          return store.reduceEffect(s, coinFlipEffect);
        };
        return flipCoins(state);
      }
      return state;
    }
  };

