  var AdversityPolicy = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.set = "CRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "74";
      this.name = "Adversity Policy";
      this.fullName = "Adversity Policy CRI";
      this.text = "If the Pok\xE9mon this card is attached to has Weakness to your opponent's Active Pok\xE9mon's type, is in the Active Spot, and is damaged by an attack from your opponent's Pok\xE9mon (even if this Pok\xE9mon is Knocked Out), draw 3 cards.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && effect.target.tools.includes(this)) {
        const player = effect.player;
        const targetPlayer = StateUtils.findOwner(state, effect.target);
        try {
          const stub = new ToolEffect(effect.player, this);
          store.reduceEffect(state, stub);
        } catch {
          return state;
        }
        if (effect.damage <= 0 || player === targetPlayer || targetPlayer.active !== effect.target) {
          return state;
        }
        const attachedPokemon = effect.target.getPokemonCard();
        if (attachedPokemon === void 0) {
          return state;
        }
        const checkOpponentType = new CheckPokemonTypeEffect(player.active);
        store.reduceEffect(state, checkOpponentType);
        const opponentTypes = checkOpponentType.cardTypes;
        const hasWeaknessToOpponentActiveType = attachedPokemon.weakness.some(
          (w) => opponentTypes.includes(w.type)
        );
        if (!hasWeaknessToOpponentActiveType) {
          return state;
        }
        MOVE_CARDS(store, state, targetPlayer.deck, targetPlayer.hand, { count: 3, sourceCard: this });
      }
      return state;
    }
  };

