  var Ampharos7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Flaaffy";
      this.hp = 160;
      this.cardType = [L];
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Synchro Pulse",
          powerType: 2 /* ABILITY */,
          text: "If you have the same number of cards in your hand as your opponent, attacks used by this Pok\xE9mon do 80 more damage to your opponent's Active Pok\xE9mon (before applying Weakness and Resistance)."
        }
      ];
      this.attacks = [
        {
          name: "Flashing Bolt",
          cost: [L, C],
          damage: 140,
          text: "During your next turn, this Pok\xE9mon can't use Flashing Bolt."
        }
      ];
      this.regulationMark = "J";
      this.set = "CRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "29";
      this.name = "Ampharos";
      this.fullName = "Ampharos M4";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof DealDamageEffect && effect.source.getPokemonCard() === this) {
        const player = StateUtils.findOwner(state, effect.source);
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (effect.target === opponent.active && player.hand.cards.length === opponent.hand.cards.length) {
          effect.damage += 80;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        effect.player.active.cannotUseAttacksNextTurnPending.push("Flash Bolt");
      }
      return state;
    }
  };

