  var Avalugg5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Bergmite";
      this.hp = 160;
      this.cardType = [W];
      this.weakness = [{ type: M }];
      this.retreat = [C, C, C, C];
      this.attacks = [
        {
          name: "Iceberg Breaker",
          cost: [W],
          damage: 60,
          damageCalculation: "x",
          text: "Discard the top 6 cards of your deck, and this attack does 60 damage for each Basic [W] Energy card you discarded in this way."
        },
        {
          name: "Frost Stamp",
          cost: [W, W, C, C],
          damage: 160,
          text: ""
        }
      ];
      this.regulationMark = "J";
      this.set = "CRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "24";
      this.name = "Avalugg";
      this.fullName = "Avalugg M4";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const count = Math.min(6, player.deck.cards.length);
        const topCards = player.deck.cards.slice(0, count);
        const basicWCount = topCards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(W)
        ).length;
        state = MOVE_CARDS(store, state, player.deck, player.discard, {
          cards: topCards,
          sourceCard: this,
          sourceEffect: effect
        });
        effect.damage = basicWCount * 60;
      }
      return state;
    }
  };

