  var AzsTranquility = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CRI";
      this.regulationMark = "J";
      this.name = "AZ's Tranquility";
      this.fullName = "AZ's Tranquility M4";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "76";
      this.text = "Switch your Active Pok\xE9mon with 1 of your Benched Pok\xE9mon. If you moved a Pok\xE9mon ex to your Bench in this way, heal 80 damage from that Pok\xE9mon.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (!player.bench.some((b) => b.cards.length > 0)) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false }
          ),
          (selected) => {
            if (!selected || selected.length === 0) return state;
            const previousActive = player.active;
            player.switchPokemon(selected[0], store, state);
            if (previousActive.exPokemon()) {
              const healEffect = new HealEffect(player, previousActive, 80);
              return store.reduceEffect(state, healEffect);
            } else {
              return state;
            }
          }
        );
      }
      return state;
    }
  };

