      this.stage = 2 /* BASIC */;
      this._tags = ["ex" /* POKEMON_ex */];
      this.cardType = [M];
      this.hp = 210;
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
