  init_card_types();
  init_game();
  init_prefabs();
  function* useCallingJutsu(next, store, state, effect) {
    const player = effect.player;
    const max = Math.min(
      3,
      player.deck.cards.filter((c) => c.superType === 1 /* POKEMON */).length
    );
    if (max === 0) {
      return state;
    }
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 1 /* POKEMON */ },
        { min: 0, max, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    cards.forEach((c) => MOVE_CARDS(store, state, player.deck, player.hand, { cards: [c], sourceCard: effect.source.getPokemonCard() }));
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
