  var MegaFloetteex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Mega ex" /* POKEMON_SV_MEGA */, "ex" /* POKEMON_ex */];
      this.cardType = [P];
      this.hp = 250;
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Gentle Light",
          cost: [P],
          damage: 0,
          text: "Heal 30 damage from each Pok\xE9mon (both yours and your opponent's)."
        },
        {
          name: "Eternity Bloom",
          cost: [P, P, P],
          damage: 200,
          text: "Search your deck for up to 4 Basic [P] Energy cards and attach them to your Benched Pok\xE9mon in any way you like. Then, shuffle your deck."
        }
      ];
      this.regulationMark = "J";
      this.set = "CRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "35";
      this.name = "Mega Floette ex";
      this.fullName = "Mega Floette ex M4";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const targets = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList.damage > 0) {
            targets.push(cardList);
          }
        });
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
          if (cardList.damage > 0) {
            targets.push(cardList);
          }
        });
        if (targets.length > 0) {
          targets.forEach((target) => {
            const healEffect = new HealEffect(player, target, 30);
            store.reduceEffect(state, healEffect);
          });
        }
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        state = store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Psychic Energy" },
            { allowCancel: false, min: 0, max: 4 }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              return SHUFFLE_DECK(store, state, player);
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, { cards: [transfer.card], sourceCard: this });
            }
            return SHUFFLE_DECK(store, state, player);
          }
        );
      }
      return state;
    }
  };

