  var MegaGreninjaex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Frogadier";
      this._tags = ["Mega ex" /* POKEMON_SV_MEGA */, "ex" /* POKEMON_ex */];
      this.hp = 350;
      this.cardType = [W];
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Mortal Shuriken",
          powerType: 2 /* ABILITY */,
          useWhenInPlay: true,
          text: "Once during your turn, if this Pok\xE9mon is in the Active Spot, you may discard a Basic [W] Energy card from your hand in order to use this Ability. Place 6 damage counters on 1 of your opponent's Pok\xE9mon. "
        }
      ];
      this.attacks = [
        {
          name: "Ninja Spinner",
          cost: [W, W],
          damage: 120,
          text: "You may put a [W] Energy attached to this Pok\xE9mon into your hand and have this attack do 80 more damage."
        }
      ];
      this.regulationMark = "J";
      this.set = "CRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "22";
      this.name = "Mega Greninja ex";
      this.fullName = "Mega Greninja ex M4";
      this.MORTAL_SHURIKEN_MARKER = "MORTAL_SHURIKEN_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.active.getPokemonCard() !== this) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (player.marker.hasMarker(this.MORTAL_SHURIKEN_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const basicWInHand = player.hand.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(3 /* WATER */)
        );
        if (!basicWInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasOpponentPokemon = opponent.active.cards.length > 0 || opponent.bench.some((b) => b.cards.length > 0);
        if (!hasOpponentPokemon) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
            { allowCancel: true, min: 1, max: 1 }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length === 0) {
              return state;
            }
            MOVE_CARDS(store, state, player.hand, player.discard, {
              cards,
              sourceCard: this,
              sourceEffect: this.powers[0]
            });
            return store.prompt(
              state,
              new ChoosePokemonPrompt(
                player.id,
                GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
                1 /* TOP_PLAYER */,
                [1 /* ACTIVE */, 2 /* BENCH */],
                { min: 1, max: 1, allowCancel: false }
              ),
              (selected) => {
                const targets = selected || [];
                if (targets.length > 0) {
                  const placeCounters = new PlaceDamageCountersEffect(player, targets[0], 60, this);
                  store.reduceEffect(state, placeCounters);
                }
                player.marker.addMarker(this.MORTAL_SHURIKEN_MARKER, this);
                ABILITY_USED(player, this);
              }
            );
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.MORTAL_SHURIKEN_MARKER, this);
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        effect.player.marker.removeMarker(this.MORTAL_SHURIKEN_MARKER, this);
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        CONFIRMATION_PROMPT(
          store,
          state,
          player,
          (result) => {
            if (result) {
              PUT_SPECIFIC_ENERGY_FROM_THIS_POKEMON_INTO_HAND(
                store,
                state,
                effect,
                [3 /* WATER */],
                {
                  onEnergyMoved: () => {
                    effect.damage += 80;
                  }
                }
              );
            }
          },
          GameMessage.WANT_TO_USE_EFFECT_OF_ATTACK
        );
      }
      return state;
    }
  };

