  var Phantump8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 70;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Spiteful Evolution",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may use this Ability. Choose a card in your hand that evolves from this Pok\xE9mon and put it onto this Pok\xE9mon to evolve it. If you do, place 2 damage counters on the Pok\xE9mon you evolved in this way. You can't use this Ability during your first turn."
        }
      ];
      this.attacks = [
        {
          name: "Mumble",
          cost: [P],
          damage: 10,
          text: ""
        }
      ];
      this.regulationMark = "J";
      this.set = "CRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "38";
      this.name = "Phantump";
      this.fullName = "Phantump M4";
      this.ENVIOUS_EVOLUTION_MARKER = "ENVIOUS_EVOLUTION_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        if (state.turn <= 2) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const cardList = StateUtils.findCardList(state, this);
        if (!cardList) return state;
        const evolutionInHand = player.hand.cards.filter(
          (c) => c instanceof PokemonCard && c.evolvesFrom === "Phantump"
        );
        if (evolutionInHand.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const blocked = [];
        player.hand.cards.forEach((card, index) => {
          if (!(card instanceof PokemonCard) || card.evolvesFrom !== "Phantump") {
            blocked.push(index);
          }
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_EVOLVE,
            player.hand,
            { superType: 1 /* POKEMON */ },
            { min: 0, max: 1, allowCancel: true, blocked }
          ),
          (cards) => {
            const selected = cards || [];
            if (selected.length === 0) return state;
            USE_ABILITY_ONCE_PER_TURN(player, this.ENVIOUS_EVOLUTION_MARKER, this);
            ABILITY_USED(player, this);
            const evolutionCard = selected[0];
            MOVE_CARDS(store, state, player.hand, cardList, { cards: [evolutionCard], sourceCard: this });
            cardList.clearEffects();
            cardList.pokemonPlayedTurn = state.turn;
            const placeDamage = new PlaceDamageCountersEffect(player, cardList, 20, this);
            store.reduceEffect(state, placeDamage);
            return state;
          }
        );
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.ENVIOUS_EVOLUTION_MARKER, this);
      return state;
    }
  };

