  var Philippe = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "CRI";
      this.regulationMark = "J";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "79";
      this.name = "Philippe";
      this.fullName = "Philippe M4";
      this.text = "Attach up to 2 Basic [M] Energy cards from your discard pile to 1 of your [M] Pok\xE9mon.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      const basicMetalInDiscard = player.discard.cards.filter(
        (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(8 /* METAL */)
      );
      if (basicMetalInDiscard.length === 0) {
        return false;
      }
      let metalPokemonCount = 0;
      player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
        const checkType = new CheckPokemonTypeEffect(cardList);
        store.reduceEffect(state, checkType);
        if (checkType.cardTypes.includes(8 /* METAL */)) {
          metalPokemonCount++;
        }
      });
      if (metalPokemonCount === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (WAS_TRAINER_USED(effect, this)) {
        const player = effect.player;
        const basicMetalInDiscard = player.discard.cards.filter(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(8 /* METAL */)
        );
        if (basicMetalInDiscard.length === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const blocked = [];
        let metalPokemonCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          const checkType = new CheckPokemonTypeEffect(cardList);
          store.reduceEffect(state, checkType);
          if (!checkType.cardTypes.includes(8 /* METAL */)) {
            blocked.push(target);
          } else {
            metalPokemonCount++;
          }
        });
        if (metalPokemonCount === 0) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const discardBlocked = [];
        player.discard.cards.forEach((card, index) => {
          if (!(card instanceof EnergyCard) || card.energyType !== 0 /* BASIC */ || !card.provides.includes(8 /* METAL */)) {
            discardBlocked.push(index);
          }
        });
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false, blocked }
          ),
          (targets) => {
            if (!targets || targets.length === 0) return state;
            const target = targets[0];
            const checkType = new CheckPokemonTypeEffect(target);
            store.reduceEffect(state, checkType);
            if (!checkType.cardTypes.includes(8 /* METAL */)) {
              return state;
            }
            return store.prompt(
              state,
              new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARD_TO_ATTACH,
                player.discard,
                { superType: 3 /* ENERGY */ },
                {
                  min: 0,
                  max: Math.min(2, basicMetalInDiscard.length),
                  allowCancel: false,
                  blocked: discardBlocked
                }
              ),
              (selected) => {
                const cards = selected || [];
                cards.forEach((card) => {
                  MOVE_CARDS(store, state, player.discard, target, { cards: [card], sourceCard: this });
                });
                return state;
              }
            );
          }
        );
      }
      return state;
    }
  };

