  var ROXIE_POISONED_NO_RETREAT = "ROXIE_POISONED_NO_RETREAT";
  var RoxiesPerformance = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "J";
      this.set = "CRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "81";
      this.name = "Roxie's Performance";
      this.fullName = "Roxie's Performance M4";
      this.text = "During your opponent's next turn, their Poisoned Pok\xE9mon can't retreat. (This includes newly Poisoned Pok\xE9mon.)";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        ADD_MARKER(ROXIE_POISONED_NO_RETREAT, opponent, this);
      }
      if (effect instanceof EndTurnEffect) {
        REMOVE_MARKER_AT_END_OF_TURN(effect, ROXIE_POISONED_NO_RETREAT, this);
      }
      if (effect instanceof RetreatEffect || effect instanceof RetreatStartEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (opponent.marker.hasMarker(ROXIE_POISONED_NO_RETREAT, this)) {
          const isPoisoned = player.active.specialConditions.includes(3 /* POISONED */);
          if (isPoisoned) {
            throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
          }
        }
      }
      return state;
    }
  };

