  var PrismTower = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "CRI";
      this.setNumber = "80";
      this.name = "Prism Tower";
      this.fullName = "Prism Tower M4";
      this.cardImage = "assets/cardback.png";
      this.text = "Once during each player's turn, that player may discard 2 cards from their hand in order to draw a card. ";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const stadiumUsedTurn = player.stadiumUsedTurn;
        if (player.stadiumUsedTurn === state.turn) {
          throw new GameError(GameMessage.CANNOT_USE_STADIUM);
        }
        if (player.hand.cards.length < 2) {
          throw new GameError(GameMessage.CANNOT_USE_STADIUM);
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            player.hand,
            {},
            { allowCancel: false, min: 2, max: 2 }
          ),
          (selected) => {
            selected = selected || [];
            if (selected.length === 0) {
              player.stadiumUsedTurn = stadiumUsedTurn;
              return;
            }
            MOVE_CARDS(store, state, player.hand, player.discard, {
              cards: selected,
              sourceCard: this,
              sourceEffect: this
            });
            MOVE_CARDS(store, state, player.deck, player.hand, {
              count: 1,
              sourceCard: this,
              sourceEffect: this
            });
          }
        );
      }
      return state;
    }
  };

