  var SpecialRedCard = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.regulationMark = "J";
      this.set = "CRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "82";
      this.name = "Special Red Card";
      this.fullName = "Special Red Card M4";
      this.text = "You can use this card only if your opponent has 3 or fewer Prize cards remaining.\n\nYour opponent shuffles their hand and puts it on the bottom of their deck. If they put any cards on the bottom of their deck in this way, they draw 3 cards.";
    }
    canPlay(store, state, player) {
      const opponent = StateUtils.getOpponent(state, player);
      const prizeCount = opponent.prizes.filter((p) => p.cards.length > 0).length;
      if (prizeCount > 3) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const prizeCount = opponent.prizes.filter((p) => p.cards.length > 0).length;
        if (prizeCount > 3) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        const cardsInHand = opponent.hand.cards.length;
        if (cardsInHand > 0) {
          const deckBottom = new CardList();
          MOVE_CARDS(store, state, opponent.hand, deckBottom, { sourceCard: this });
          MOVE_CARDS(store, state, deckBottom, opponent.deck, { sourceCard: this });
          DRAW_CARDS(store, state, opponent, Math.min(3, opponent.deck.cards.length));
        }
      }
      return state;
    }
  };

