  var Tauros10 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.hp = 130;
      this.cardType = [C];
      this.weakness = [{ type: F }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Target Together",
        cost: [C, C],
        damage: 0,
        text: `Choose 1 of your opponent's Pok\xE9mon and flip a coin for each of your Pok\xE9mon in play that has "Tauros" in its name. This attack does 50 damage to the chosen Pok\xE9mon for each heads. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)`
      }];
      this.regulationMark = "J";
      this.set = "CRI";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "69";
      this.name = "Tauros";
      this.fullName = "Tauros M4";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let taurosCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card && card.name.includes("Tauros")) taurosCount++;
        });
        const hasOpponentPokemon = opponent.active.cards.length > 0 || opponent.bench.some((b) => b.cards.length > 0);
        if (!hasOpponentPokemon) return state;
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
            1 /* TOP_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { min: 1, max: 1, allowCancel: false }
          ),
          (selected) => {
            const targets = selected || [];
            if (targets.length === 0) return state;
            return MULTIPLE_COIN_FLIPS_PROMPT(store, state, player, taurosCount, (results) => {
              const damage = 50 * results.filter((r) => r).length;
              if (damage > 0) {
                DAMAGE_OPPONENT_POKEMON(store, state, effect, damage, targets);
              }
            });
          }
        );
      }
      return state;
    }
  };

