  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-delta-reign/aarune.ts
  init_game();
  init_play_card_effects();
  init_prefabs();
  var Aarune = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "J";
      this.set = "M6";
      this.setNumber = "68";
      this.cardImage = "assets/cardback.png";
      this.name = "Aarune";
      this.fullName = "Aarune M6";
      this.text = "Search your deck for up to 3 Supporter or Stadium cards in any combination, reveal them, and put them into your hand. Then, shuffle your deck.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        BLOCK_IF_DECK_EMPTY(player);
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        const blocked = [];
        player.deck.cards.forEach((c, index) => {
          const isSupporter = c instanceof TrainerCard && c.trainerType === 1 /* SUPPORTER */;
          const isStadium = c instanceof TrainerCard && c.trainerType === 2 /* STADIUM */;
          if (!(isSupporter || isStadium)) {
            blocked.push(index);
          }
        });
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            player.deck,
            {},
            { min: 0, max: 3, allowCancel: false, blocked }
          ),
          (cards) => {
            cards = cards || [];
            if (cards.length > 0) {
              MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this });
              SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
            }
            MOVE_CARDS(store, state, player.supporter, player.discard, {
              cards: [effect.trainerCard],
              sourceCard: this
            });
            return SHUFFLE_DECK(store, state, player);
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-delta-reign/adventuring-lantern.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_play_card_effects();
  init_prefabs();
  function* playCard288(next, store, state, effect) {
    const player = effect.player;
    const opponent = StateUtils.getOpponent(state, player);
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    effect.preventDefault = true;
    let cards = [];
    const blocked = [];
    player.deck.cards.forEach((c, index) => {
      if (!(c instanceof EnergyCard) || c.energyType !== 0 /* BASIC */) {
        blocked.push(index);
        return;
      }
      const isFire = c.provides.includes(2 /* FIRE */);
      const isLightning = c.provides.includes(4 /* LIGHTNING */);
      if (!isFire && !isLightning) {
        blocked.push(index);
      }
    });
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
        { min: 0, max: 2, allowCancel: false, differentTypes: true, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    state = MOVE_CARDS(store, state, player.deck, player.hand, {
      cards,
      sourceCard: effect.trainerCard
    });
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ShowCardsPrompt(opponent.id, GameMessage.CARDS_SHOWED_BY_THE_OPPONENT, cards),
        () => next()
      );
    }
    yield store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
      next();
    });
    return state;
  }
  var AdventuringLantern = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 0 /* ITEM */;
      this.regulationMark = "J";
      this.set = "M6";
      this.setNumber = "64";
      this.cardImage = "assets/cardback.png";
      this.name = "Adventuring Lantern";
      this.fullName = "Adventuring Lantern M6";
      this.text = "Search your deck for a Basic [R] Energy and a Basic [L] Energy, reveal them, and put them into your hand. Then, shuffle your deck.";
    }
    canPlay(store, state, player) {
      if (player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const generator = playCard288(() => generator.next(), store, state, effect);
        return generator.next().value;
      }
      return state;
    }
  };

