  var Altaria12 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Swablu";
      this.cardType = [C];
      this.hp = 110;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Cotton Carrier",
        powerType: 2 /* ABILITY */,
        text: "Your Basic Pokemon in play have no Retreat Cost."
      }];
      this.attacks = [{
        name: "Wing Flap",
        cost: [C, C, C],
        damage: 80,
        text: ""
      }];
      this.regulationMark = "J";
      this.set = "M6";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "56";
      this.name = "Altaria";
      this.fullName = "Altaria M6";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect) {
        const player = effect.player;
        let altariaInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (_cardList, card) => {
          if (card === this) {
            altariaInPlay = true;
          }
        });
        if (!altariaInPlay || IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const activePokemon = player.active.getPokemonCard();
        if (activePokemon && activePokemon.stage === 2 /* BASIC */) {
          effect.cost = [];
        }
      }
      return state;
    }
  };

