  var LegendaryLavaLakeLeft = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this._tags = ["Dual Stadium" /* DUAL_STADIUM */];
      this.regulationMark = "J";
      this.set = "M6";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "75";
      this.name = "Legendary Lava Lake";
      this.fullName = "Legendary Lava Lake (Left) M6";
      this.text = "You can only put this card into play from your hand with the other half of Legendary Lava Lake, and it counts as one Stadium card while in play.\n\nEvolution Pokemon in play (both yours and your opponent's) have no Abilities.";
      this.powers = [
        {
          name: "Stadium Assembly",
          text: "Put this card from your hand into play only with the other half of Legendary Lava Lake.",
          exemptFromAbilityLock: true,
          useFromHand: true,
          powerType: 9 /* TRAINER_ABILITY */
        }
      ];
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerPowerEffect && effect.power === this.powers[0]) {
        return assembleDualStadiumFromHand(store, state, effect.player, this);
      }
      HANDLE_ABILITY_LOCK(
        effect,
        ({ card }) => {
          if (StateUtils.getStadiumCard(state) !== this) {
            return false;
          }
          if (card.stage === 2 /* BASIC */) {
            return false;
          }
          try {
            const cardList = StateUtils.findCardList(state, card);
            if (!(cardList instanceof PokemonCardList)) {
              return false;
            }
            const owner = StateUtils.findOwner(state, cardList);
            if (IS_STADIUM_EFFECT_BLOCKED(store, state, owner, cardList)) {
              return false;
            }
            return true;
          } catch {
            return false;
          }
        },
        {
          allowUseFromHand: true,
          allowUseFromDiscard: true
        }
      );
      return state;
    }
  };

