  var LegendarySummitLeft = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this._tags = ["Dual Stadium" /* DUAL_STADIUM */];
      this.set = "M6";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "73";
      this.name = "Legendary Summit";
      this.fullName = "Legendary Summit (Left) M6";
      this.text = "You can only put this card into play from your hand with the other half of Legendary Summit, and it counts as one Stadium card while in play.\n\nWhen Knocked Out by damage from an opponent's attack, both player's [C] Pok\xE9mon give up one less Prize card.";
      this.powers = [
        {
          name: "Stadium Assembly",
          text: "Put this card from your hand into play only with the other half of Legendary Summit.",
          exemptFromAbilityLock: true,
          useFromHand: true,
          powerType: 9 /* TRAINER_ABILITY */
        }
      ];
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerPowerEffect && effect.power === this.powers[0]) {
        return assembleDualStadiumFromHand(store, state, effect.player, this);
      }
      if (effect instanceof KnockOutEffect && StateUtils.getStadiumCard(state) === this) {
        const knockedOutOwner = effect.player;
        const attacker = StateUtils.getOpponent(state, knockedOutOwner);
        if (IS_STADIUM_EFFECT_BLOCKED(store, state, knockedOutOwner, effect.target, this)) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */ || state.players[state.activePlayer] !== attacker) {
          return state;
        }
        const checkPokemonTypeEffect = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkPokemonTypeEffect);
        const isColorlessPokemon = checkPokemonTypeEffect.cardTypes.includes(9 /* COLORLESS */);
        if (isColorlessPokemon && effect.prizeCount > 0) {
          effect.prizeCount -= 1;
        }
      }
      return state;
    }
  };

