  var Magmortar9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Magmar";
      this.cardType = [R];
      this.hp = 140;
      this.weakness = [{ type: W }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Buddy Boost",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn, you may attach up to 1 Basic [R] Energy and up to 1 Basic [L] Energy from your hand to your Magmortar or Electivire in any way you like."
      }];
      this.attacks = [{
        name: "Heat Stamp",
        cost: [R, R, C],
        damage: 80,
        text: ""
      }];
      this.regulationMark = "J";
      this.set = "M6";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "13";
      this.name = "Magmortar";
      this.fullName = "Magmortar M6";
      this.BUDDY_BOOST_MARKER = "MAGMORTAR_BUDDY_BOOST_MARKER";
      this.VALID_POKEMON_NAMES = ["Magmortar", "Electivire"];
    }
    getBlockedTargets(player) {
      const blockedTo = [];
      const activePokemon = player.active.getPokemonCard();
      if (!activePokemon || !this.VALID_POKEMON_NAMES.includes(activePokemon.name)) {
        blockedTo.push({ player: 2 /* BOTTOM_PLAYER */, slot: 1 /* ACTIVE */, index: 0 });
      }
      player.bench.forEach((bench, index) => {
        const pokemon = bench.getPokemonCard();
        if (!pokemon || !this.VALID_POKEMON_NAMES.includes(pokemon.name)) {
          blockedTo.push({ player: 2 /* BOTTOM_PLAYER */, slot: 2 /* BENCH */, index });
        }
      });
      return blockedTo;
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        let hasValidTarget = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const pokemon = cardList.getPokemonCard();
          if (pokemon && this.VALID_POKEMON_NAMES.includes(pokemon.name)) {
            hasValidTarget = true;
          }
        });
        if (!hasValidTarget) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.BUDDY_BOOST_MARKER, this);
        ABILITY_USED(player, this);
        const hasValidEnergy = player.hand.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.some((p) => p === 2 /* FIRE */ || p === 4 /* LIGHTNING */)
        );
        if (!hasValidEnergy) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.hand,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
          {
            allowCancel: true,
            min: 0,
            max: 2,
            blockedTo: this.getBlockedTargets(player),
            validCardTypes: [2 /* FIRE */, 4 /* LIGHTNING */],
            maxPerType: 1
          }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.hand, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.BUDDY_BOOST_MARKER, this);
      return state;
    }
  };

