  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-delta-reign/mega-rayquaza-cap.ts
  init_game();
  init_card_types();
  init_trainer_card();
  init_check_effects();
  init_game_effects();
  init_prefabs();
  function buildCapHolderBlockedTo(player, capName) {
    const blocked = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, _card, target) => {
      if (!cardList.tools.some((tool) => tool.name === capName)) {
        blocked.push(target);
      }
    });
    return blocked;
  }
  function countCapHolders(player, capName) {
    let count = 0;
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
      if (cardList.tools.some((tool) => tool.name === capName)) {
        count += 1;
      }
    });
    return count;
  }
  var MegaRayquazaCap = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 3 /* TOOL */;
      this.regulationMark = "J";
      this.set = "M6";
      this.setNumber = "66";
      this.cardImage = "assets/cardback.png";
      this.name = "Mega Rayquaza Cap";
      this.fullName = "Mega Rayquaza Cap M6";
      this.attacks = [
        {
          name: "Delta Gift",
          cost: [9 /* COLORLESS */],
          damage: 0,
          text: "For each of your Pok\xE9mon in play that has a Mega Rayquaza Cap attached to it, search your deck for a Basic Energy and attach it to that Pok\xE9mon. Then, shuffle your deck."
        }
      ];
      this.text = "The Pok\xE9mon this card is attached to can use the attack on this card.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckAttackCostEffect && effect.attack === this.attacks[0]) {
        const pokemonCard = effect.player.active.getPokemonCard();
        if (pokemonCard && "getColorlessReduction" in pokemonCard) {
          const reduction = pokemonCard.getColorlessReduction(state);
          for (let i = 0; i < reduction && effect.cost.includes(9 /* COLORLESS */); i++) {
            const index = effect.cost.indexOf(9 /* COLORLESS */);
            if (index !== -1) {
              effect.cost.splice(index, 1);
            }
          }
        }
      }
      if (effect instanceof CheckPokemonAttacksEffect && effect.player.active.tools.includes(this) && !effect.attacks.includes(this.attacks[0])) {
        effect.attacks.push(this.attacks[0]);
      }
      if (effect instanceof AttackEffect && effect.attack === this.attacks[0]) {
        const player = effect.player;
        if (IS_TOOL_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_ATTACK);
        }
        const capHolderCount = countCapHolders(player, this.name);
        if (capHolderCount === 0) {
          return state;
        }
        if (player.deck.cards.length === 0) {
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
          });
        }
        const blockedTo = buildCapHolderBlockedTo(player, this.name);
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.CHOOSE_CARD_TO_ATTACH,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: 0, max: capHolderCount, blockedTo, differentTargets: true }
          ),
          (transfers) => {
            transfers = transfers || [];
            for (const transfer of transfers) {
              const attachTarget = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, attachTarget, {
                cards: [transfer.card],
                sourceCard: this
              });
            }
            store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
              player.deck.applyOrder(order);
            });
          }
        );
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-delta-reign/mega-rayquaza-ex.ts
  init_game();
