  var MegaRayquazaex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this._tags = ["Mega ex" /* POKEMON_SV_MEGA */, "ex" /* POKEMON_ex */];
      this.cardType = [C];
      this.hp = 280;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Champion's Roar",
          powerType: 2 /* ABILITY */,
          text: "When you play this Pok\xE9mon from your hand onto your Bench during your turn, you may use this Ability. Look at the top 4 cards of your deck and attach a Basic Energy you find there to this Pok\xE9mon. Shuffle the remaining cards and put them on the bottom of your deck."
        }
      ];
      this.attacks = [
        {
          name: "Storm Emeralda",
          cost: [R, L, C],
          damage: 50,
          damageCalculation: "x",
          text: "This attack does 50 damage times the number of [R] and [L] Energy attached to all of your Pok\xE9mon in play."
        }
      ];
      this.regulationMark = "J";
      this.set = "M6";
      this.setNumber = "58";
      this.cardImage = "assets/cardback.png";
      this.name = "Mega Rayquaza ex";
      this.fullName = "Mega Rayquaza ex M6";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this && effect.slot === 2 /* BENCH */ && effect.target.cards.length === 0) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        return store.prompt(
          state,
          new ConfirmPrompt(player.id, GameMessage.WANT_TO_USE_ABILITY),
          (wantToUse) => {
            if (!wantToUse) {
              return;
            }
            const topCards = new CardList();
            const count = Math.min(4, player.deck.cards.length);
            MOVE_CARDS(store, state, player.deck, topCards, { count, sourceCard: this });
            SHOW_CARDS_TO_PLAYER(store, state, player, topCards.cards);
            const hasBasicEnergy = topCards.cards.some(
              (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */
            );
            if (!hasBasicEnergy) {
              MOVE_CARDS(store, state, topCards, player.deck, { toBottom: true });
              return;
            }
            store.prompt(
              state,
              new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARD_TO_ATTACH,
                topCards,
                { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
                { allowCancel: false, min: 0, max: 1 }
              ),
              (cards) => {
                cards = cards || [];
                if (cards.length > 0) {
                  const energyCard = cards[0];
                  MOVE_CARDS(store, state, topCards, effect.target, { cards: [energyCard], sourceCard: this });
                  store.reduceEffect(
                    state,
                    new AttachEnergyEffect(player, energyCard, effect.target)
                  );
                }
                MOVE_CARDS(store, state, topCards, player.deck, { toBottom: true });
              }
            );
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let energyCount = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
          const checkEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkEnergy);
          energyCount += checkEnergy.energyMap.reduce((sum, em) => {
            return sum + em.provides.filter(
              (c) => c === 2 /* FIRE */ || c === 4 /* LIGHTNING */ || c === 0 /* ANY */
            ).length;
          }, 0);
        });
        effect.damage = 50 * energyCount;
      }
      return state;
    }
  };

