  var ZinniasTrust = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "J";
      this.set = "M6";
      this.setNumber = "69";
      this.cardImage = "assets/cardback.png";
      this.name = "Zinnia's Trust";
      this.fullName = "Zinnia's Trust M6";
      this.text = "Switch your Active Pok\xE9mon with 1 of your Benched Pok\xE9mon. If you do, move 1 Energy from your previous Active Pok\xE9mon to your new Active Pok\xE9mon.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (!player.bench.some((b) => b.cards.length > 0)) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
        MOVE_CARDS(store, state, player.hand, player.supporter, {
          cards: [effect.trainerCard],
          sourceCard: this
        });
        effect.preventDefault = true;
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_NEW_ACTIVE_POKEMON,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */],
            { allowCancel: false, min: 1, max: 1 }
          ),
          (selected) => {
            if (!selected || selected.length === 0) {
              return state;
            }
            const previousActive = player.active;
            player.switchPokemon(selected[0], store, state);
            const hasEnergy = previousActive.cards.some((c) => c.superType === 3 /* ENERGY */);
            if (!hasEnergy) {
              MOVE_CARDS(store, state, player.supporter, player.discard, {
                cards: [effect.trainerCard],
                sourceCard: this
              });
              return state;
            }
            return store.prompt(
              state,
              new ChooseCardsPrompt(
                player,
                GameMessage.ATTACH_ENERGY_TO_BENCH,
                previousActive,
                { superType: 3 /* ENERGY */ },
                { allowCancel: false, min: 1, max: 1 }
              ),
              (cards) => {
                cards = cards || [];
                if (cards.length > 0) {
                  MOVE_CARDS(store, state, previousActive, player.active, {
                    cards,
                    sourceCard: this
                  });
                }
                MOVE_CARDS(store, state, player.supporter, player.discard, {
                  cards: [effect.trainerCard],
                  sourceCard: this
                });
                return state;
              }
            );
          }
        );
      }
      return state;
    }
  };

