  function* useStadium16(next, store, state, effect) {
    const player = effect.player;
    const slots2 = player.bench.filter((b) => b.cards.length === 0);
    if (player.deck.cards.length === 0 || slots2.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const maxPick = Math.min(2, slots2.length);
    const blocked = [];
    player.deck.cards.forEach((card, index) => {
      if (!(card instanceof TrainerCard && card.hasTag("Antique" /* ANTIQUE */))) {
        blocked.push(index);
      }
    });
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
        player.deck,
        { superType: 2 /* TRAINER */ },
        { min: 0, max: maxPick, allowCancel: false, blocked }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    cards.forEach((card, index) => {
      const playFromDeck = new PlayPokemonFromDeckEffect(player, card, slots2[index]);
      store.reduceEffect(state, playFromDeck);
      slots2[index].pokemonPlayedTurn = state.turn;
    });
    return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
  }
