  init_choose_cards_prompt();
  init_prefabs();
  var MegaDelphoxex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Braixen";
      this._tags = ["Mega ex" /* POKEMON_SV_MEGA */, "ex" /* POKEMON_ex */];
      this.cardType = [R];
      this.hp = 350;
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Trick Portal",
          cost: [R],
          damage: 0,
          text: "Look at the top 9 cards of your deck, and you may put any number of Pok\xE9mon you find there onto your Bench. Shuffle the other cards back into your deck."
        },
        {
          name: "Eerie Glow",
          cost: [R, C, C],
          damage: 200,
          text: "Your opponent's Active Pok\xE9mon is now Burned and Confused."
        }
      ];
      this.regulationMark = "J";
      this.set = "PBL";
      this.setNumber = "8";
      this.cardImage = "assets/cardback.png";
      this.name = "Mega Delphox ex";
      this.fullName = "Mega Delphox ex M-P";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const deckTop = new CardList();
        MOVE_CARDS(store, state, player.deck, deckTop, { count: Math.min(9, player.deck.cards.length), sourceCard: this });
        SHOW_CARDS_TO_PLAYER(store, state, player, deckTop.cards);
        const openSlots = player.bench.filter((b) => b.cards.length === 0).length;
        const basicCount = deckTop.cards.filter(
          (c) => c instanceof PokemonCard && c.stage === 2 /* BASIC */
        ).length;
        if (basicCount === 0 || openSlots === 0) {
          MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: this });
          SHUFFLE_DECK(store, state, player);
          return state;
        }
        const maxToSelect = Math.min(basicCount, openSlots);
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
            deckTop,
            { superType: 1 /* POKEMON */, stage: 2 /* BASIC */ },
            { min: 0, max: maxToSelect, allowCancel: false }
          ),
          (selected) => {
            const cards = selected || [];
            cards.forEach((card) => {
              const emptySlot = player.bench.find((b) => b.cards.length === 0);
              if (emptySlot) {
                MOVE_CARDS(store, state, deckTop, emptySlot, { cards: [card], sourceCard: this });
                emptySlot.pokemonPlayedTurn = state.turn;
              }
            });
            MOVE_CARDS(store, state, deckTop, player.deck, { sourceCard: this });
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        const active = opponent.active;
        active.addSpecialCondition(4 /* BURNED */);
        active.addSpecialCondition(1 /* CONFUSED */);
      }
      return state;
    }
  };

