  function* playMistysCheerfulness(next, store, state, effect, self) {
    const player = effect.player;
    if (player.deck.cards.length === 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    let cards = [];
    yield store.prompt(
      state,
      new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_HAND,
        player.deck,
        { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
        { min: 0, max: 4, allowCancel: false }
      ),
      (selected) => {
        cards = selected || [];
        next();
      }
    );
    if (cards.length > 0) {
      yield store.prompt(
        state,
        new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
          2 /* BOTTOM_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { allowCancel: false, min: 1, max: 1 }
        ),
        (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          const target = targets[0];
          MOVE_CARDS(store, state, player.deck, target, { cards, sourceCard: self });
          next();
        }
      );
    }
    store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
      player.deck.applyOrder(order);
    });
    const endTurnEffect = new EndTurnEffect(player);
    return store.reduceEffect(state, endTurnEffect);
  }
  var MistysVitality = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "J";
      this.set = "PBL";
      this.setNumber = "80";
      this.cardImage = "assets/cardback.png";
      this.name = "Misty's Vitality";
      this.fullName = "Misty's Cheerfulness M5";
      this.text = "Search your deck for up to 4 Basic [W] Energy cards and attach them to 1 of your Pok\xE9mon. Then, shuffle your deck. Your turn ends.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (player.deck.cards.length === 0) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        if (player.supporterTurn > 0) {
          throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
        }
        const generator = playMistysCheerfulness(() => generator.next(), store, state, effect, this);
        return generator.next().value;
      }
      return state;
    }
  };

