  var Miraidon3 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [L];
      this.hp = 120;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [
        {
          name: "Photon Cord",
          powerType: 2 /* ABILITY */,
          text: "If this Pok\xE9mon is in the Active Spot and is Knocked Out by damage from an attack from your opponent's Pok\xE9mon, move up to 2 Basic [L] Energy cards from this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
        }
      ];
      this.attacks = [
        {
          name: "Thunder",
          cost: [L, L],
          damage: 90,
          text: "This Pok\xE9mon also does 30 damage to itself."
        }
      ];
      this.set = "PBL";
      this.setNumber = "28";
      this.regulationMark = "J";
      this.cardImage = "assets/cardback.png";
      this.name = "Miraidon";
      this.fullName = "Miraidon M5";
    }
    isEligibleBasicLightningEnergy(card) {
      return card instanceof EnergyCard && card.energyType === 0 /* BASIC */ && card.provides.some(
        (p) => p === 4 /* LIGHTNING */ || p === 0 /* ANY */
      );
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect && effect.target.cards.includes(this)) {
        const player = effect.player;
        if (effect.target !== player.active) {
          return state;
        }
        if (!player.marker.hasMarker(player.DAMAGE_DEALT_MARKER)) {
          return state;
        }
        if (!IS_ABILITY_BLOCKED(store, state, player, this)) {
          const activeCopy = new PokemonCardList();
          activeCopy.cards = effect.target.cards.slice();
          const blocked = activeCopy.cards.map((c, idx) => this.isEligibleBasicLightningEnergy(c) ? -1 : idx).filter((idx) => idx >= 0);
          return store.prompt(
            state,
            new AttachEnergyPrompt(
              player.id,
              GameMessage.ATTACH_ENERGY_TO_BENCH,
              activeCopy,
              2 /* BOTTOM_PLAYER */,
              [2 /* BENCH */],
              { superType: 3 /* ENERGY */ },
              {
                blocked,
                validCardTypes: [4 /* LIGHTNING */, 0 /* ANY */],
                allowCancel: false,
                min: 0,
                max: 2
              }
            ),
            (transfers) => {
              transfers = transfers || [];
              let moved = 0;
              for (const transfer of transfers) {
                if (!transfer || !this.isEligibleBasicLightningEnergy(transfer.card)) {
                  continue;
                }
                if (moved >= 2) {
                  break;
                }
                const target = StateUtils.getTarget(state, player, transfer.to);
                state = MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card] });
                moved += 1;
              }
            }
          );
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_POKEMON_DOES_DAMAGE_TO_ITSELF(store, state, effect, 30);
      }
      return state;
    }
  };

