  var RustSyndicateGrunt = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.regulationMark = "J";
      this.set = "PBL";
      this.setNumber = "81";
      this.cardImage = "assets/cardback.png";
      this.name = "Rust Syndicate Grunt";
      this.fullName = "Rust Syndicate Grunt M5";
      this.text = "You can use this card only if any of your Pok\xE9mon were Knocked Out during your opponent's last turn.\n\nDiscard an Energy from 1 of your opponent's Pok\xE9mon.";
    }
    canPlay(store, state, player) {
      if (player.supporterTurn > 0) {
        return false;
      }
      if (player.hand.cards.filter((c) => c !== this).length > 0) {
        return false;
      }
      if (!WAS_POKEMON_KNOCKED_OUT_DURING_OPPONENTS_LAST_TURN(player)) {
        return false;
      }
      const opponent = StateUtils.getOpponent(state, player);
      let anyEnergy = false;
      opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
        if (cardList.energies.cards.length > 0) {
          anyEnergy = true;
        }
      });
      if (!anyEnergy) {
        return false;
      }
      return true;
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        return playRust(store, state, effect, this);
      }
      return state;
    }
  };
  function playRust(store, state, effect, self) {
    const player = effect.player;
    if (player.supporterTurn > 0) {
      throw new GameError(GameMessage.SUPPORTER_ALREADY_PLAYED);
    }
    const otherCards = player.hand.cards.filter((c) => c !== effect.trainerCard);
    if (otherCards.length > 0) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    if (!WAS_POKEMON_KNOCKED_OUT_DURING_OPPONENTS_LAST_TURN(player)) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    const opponent = StateUtils.getOpponent(state, player);
    const blocked = [];
    let anyEnergy = false;
    opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
      if (cardList.energies.cards.length > 0) {
        anyEnergy = true;
      }
    });
    if (!anyEnergy) {
      throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
    }
    opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card, target) => {
      if (cardList.energies.cards.length === 0) {
        blocked.push(target);
      }
    });
    effect.preventDefault = true;
    MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: self });
    return store.prompt(
      state,
      new ChoosePokemonPrompt(
        player.id,
        GameMessage.CHOOSE_POKEMON_TO_DISCARD_CARDS,
        1 /* TOP_PLAYER */,
        [1 /* ACTIVE */, 2 /* BENCH */],
        { allowCancel: false, blocked }
      ),
      (targets) => {
        const tgt = targets && targets[0];
        if (!tgt) {
          CLEAN_UP_SUPPORTER(store, effect, player);
          return state;
        }
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_DISCARD,
            tgt.energies,
            {},
            { min: 1, max: 1, allowCancel: false }
          ),
          (sel) => {
            MOVE_CARDS(store, state, tgt, opponent.discard, { cards: sel || [], sourceCard: self });
            CLEAN_UP_SUPPORTER(store, effect, player);
            return state;
          }
        );
      }
    );
  }

