  var ShadowyDarknessEnergy = class extends EnergyCard {
    constructor() {
      super(...arguments);
      this.provides = [9 /* COLORLESS */];
      this.energyType = 1 /* SPECIAL */;
      this.set = "PBL";
      this.regulationMark = "J";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "83";
      this.name = "Shadowy Darkness Energy";
      this.fullName = "Shadow Darkness Energy M5";
      this.text = "As long as this card is attached to a Pok\xE9mon, it provides [D] Energy.\n\nPrevent all damage done by your opponent's attacks to the Benched [D] Pok\xE9mon this card is attached to.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.cards.includes(this)) {
        try {
          const energyEffect = new EnergyEffect(effect.player, this);
          store.reduceEffect(state, energyEffect);
        } catch {
          return state;
        }
        effect.energyMap.push({ card: this, provides: [7 /* DARK */] });
        return state;
      }
      if ((effect instanceof DealDamageEffect || effect instanceof PutDamageEffect) && state.phase === 3 /* ATTACK */ && effect.target.cards.includes(this)) {
        const defenderOwner = StateUtils.findOwner(state, effect.target);
        if (effect.target === defenderOwner.active) {
          return state;
        }
        if (StateUtils.getOpponent(state, defenderOwner) !== effect.player) {
          return state;
        }
        if (IS_SPECIAL_ENERGY_BLOCKED(store, state, defenderOwner, this, effect.target)) {
          return state;
        }
        const checkType = new CheckPokemonTypeEffect(effect.target);
        store.reduceEffect(state, checkType);
        if (!checkType.cardTypes.includes(7 /* DARK */)) {
          return state;
        }
        effect.damage = 0;
      }
      return state;
    }
  };

