  var Slowpoke13 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 70;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "All-You-Can-Yeet",
          cost: [P],
          damage: 0,
          text: "You may discard any number of cards from your hand."
        },
        {
          name: "Headbutt",
          cost: [C, C],
          damage: 20,
          text: ""
        }
      ];
      this.set = "PBL";
      this.setNumber = "29";
      this.regulationMark = "J";
      this.cardImage = "assets/cardback.png";
      this.name = "Slowpoke";
      this.fullName = "Slowpoke M5";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const self = this;
        const attackEffect = effect;
        const player = attackEffect.player;
        function* yeetCards(next) {
          const max = player.hand.cards.length;
          if (max === 0) {
            return state;
          }
          yield store.prompt(
            state,
            new ChooseCardsPrompt(
              player,
              GameMessage.CHOOSE_CARD_TO_DISCARD,
              player.hand,
              { superType: 4 /* ANY */ },
              { min: 0, max, allowCancel: false }
            ),
            (selected) => {
              const cards = selected || [];
              if (cards.length > 0) {
                MOVE_CARDS(store, state, player.hand, player.discard, {
                  cards,
                  sourceCard: self,
                  sourceEffect: attackEffect
                });
              }
              next();
            }
          );
          return state;
        }
        const generator = yeetCards(() => generator.next());
        return generator.next().value;
      }
      return state;
    }
  };

