  var Toucannon4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      // toucan,
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Trumbeak";
      this.cardType = [C];
      this.hp = 150;
      this.weakness = [{ type: L }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C, C];
      this.powers = [
        {
          name: "Aerial Draw",
          useWhenInPlay: true,
          powerType: 2 /* ABILITY */,
          text: "Once during your turn, you may use this Ability. Draw a card."
        }
      ];
      this.attacks = [
        {
          name: "Feather Rondo",
          cost: [C],
          damage: 60,
          damageCalculation: "+",
          text: "This attack does 20 more damage for each Benched Pok\xE9mon (both yours and your opponent's)."
        }
      ];
      this.set = "PBL";
      this.setNumber = "68";
      this.regulationMark = "J";
      this.cardImage = "assets/cardback.png";
      this.name = "Toucannon";
      this.fullName = "Toucannon M5";
      this.SKY_DRAW_MARKER = "M5_TOUCANNON_SKYDRAW";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        effect.player.marker.removeMarker(this.SKY_DRAW_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.SKY_DRAW_MARKER, this);
        if (player.deck.cards.length === 0) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        player.marker.addMarker(this.SKY_DRAW_MARKER, this);
        DRAW_CARDS(store, state, player, 1);
        ABILITY_USED(player, this);
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.SKY_DRAW_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        let benches = player.bench.filter((b) => b.cards.length > 0).length;
        benches += opponent.bench.filter((b) => b.cards.length > 0).length;
        effect.damage += 20 * benches;
      }
      return state;
    }
  };

