  var Tropius10 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [G];
      this.hp = 110;
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Fruity Aroma",
          cost: [C],
          damage: 0,
          text: "Look at the top 6 cards of your deck, and you may reveal any number of Pok\xE9mon you find there and put them into your hand. Shuffle the other cards back into your deck."
        },
        {
          name: "Solar Beam",
          cost: [G, C],
          damage: 60,
          text: ""
        }
      ];
      this.set = "PBL";
      this.setNumber = "1";
      this.regulationMark = "J";
      this.cardImage = "assets/cardback.png";
      this.name = "Tropius";
      this.fullName = "Tropius M5";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.deck.cards.length === 0) {
          return state;
        }
        const opponent = StateUtils.getOpponent(state, player);
        const topCards = new CardList();
        const count = Math.min(6, player.deck.cards.length);
        MOVE_CARDS(store, state, player.deck, topCards, { count, sourceCard: this });
        const looked = [...topCards.cards];
        SHOW_CARDS_TO_PLAYER(store, state, player, looked);
        SHOW_CARDS_TO_PLAYER(store, state, opponent, looked);
        const pokemonInPreview = looked.filter((c) => c instanceof PokemonCard).length;
        return store.prompt(
          state,
          new ChooseCardsPrompt(
            player,
            GameMessage.CHOOSE_CARD_TO_HAND,
            topCards,
            { superType: 1 /* POKEMON */ },
            { min: 0, max: pokemonInPreview, allowCancel: false }
          ),
          (selected) => {
            const pokemonTaken = selected || [];
            if (pokemonTaken.length > 0) {
              MOVE_CARDS(store, state, topCards, player.hand, { cards: pokemonTaken, sourceCard: this });
              SHOW_CARDS_TO_PLAYER(store, state, opponent, pokemonTaken);
            }
            MOVE_CARDS(store, state, topCards, player.deck, { sourceCard: this });
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      return state;
    }
  };

