  var AlolanExeggutor4 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Exeggcute";
      this.hp = 150;
      this.cardType = [G];
      this.weakness = [{ type: R }];
      this.retreat = [C, C, C, C];
      this.powers = [{
        name: "Scale Up",
        powerType: 2 /* ABILITY */,
        text: "If this Pok\xE9mon has 6 or more [G] Energy attached, it gets +250 HP."
      }];
      this.attacks = [{
        name: "Mega Drain",
        cost: [G, C, C, C],
        damage: 150,
        text: "Heal 50 damage from this Pok\xE9mon."
      }];
      this.regulationMark = "J";
      this.set = "30C";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "2";
      this.name = "Alolan Exeggutor";
      this.fullName = "Alolan Exeggutor 30C";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckHpEffect && effect.target.cards.includes(this) && effect.target.getPokemonCard() === this) {
        const player = StateUtils.findOwner(state, effect.target);
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, effect.target);
        state = store.reduceEffect(state, checkProvidedEnergy);
        let grassEnergy = 0;
        checkProvidedEnergy.energyMap.forEach((em) => {
          grassEnergy += em.provides.filter((t) => t === 1 /* GRASS */ || t === 0 /* ANY */).length;
        });
        if (grassEnergy >= 6) {
          effect.hp += 250;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        HEAL_X_DAMAGE_FROM_THIS_POKEMON(effect, store, state, 50);
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-30th-celebration/articuno.ts
