  var Articuno9 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.hp = 120;
      this.cardType = [W];
      this.weakness = [{ type: M }];
      this.retreat = [C];
      this.powers = [{
        name: "Frosty Flapping",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn, if you have Moltres and Zapdos in play, you may use this Ability. Attach a Basic [W] Energy card from your hand to this Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Hail",
        cost: [W, W, C],
        damage: 0,
        text: "This attack does 30 damage to each of your opponent's Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.regulationMark = "J";
      this.set = "30C";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "18";
      this.name = "Articuno";
      this.fullName = "Articuno 30C";
      this.FROSTY_FLAPPING_MARKER = "FROSTY_FLAPPING_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        let hasMoltres = false;
        let hasZapdos = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card) => {
          if (cardList2.getPokemonCard() !== card) {
            return;
          }
          if (card.name === "Moltres") {
            hasMoltres = true;
          }
          if (card.name === "Zapdos") {
            hasZapdos = true;
          }
        });
        if (!hasMoltres || !hasZapdos) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInHand = player.hand.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(3 /* WATER */)
        );
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.FROSTY_FLAPPING_MARKER, this);
        ABILITY_USED(player, this);
        const cardList = StateUtils.findCardList(state, this);
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_ATTACH,
          player.hand,
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Water Energy" },
          { min: 1, max: 1, allowCancel: false }
        ), (cards) => {
          if (cards && cards.length > 0) {
            MOVE_CARDS(store, state, player.hand, cardList, { cards, sourceCard: this });
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.FROSTY_FLAPPING_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const opponent = StateUtils.getOpponent(state, effect.player);
        const damageActive = new DealDamageEffect(effect, 30);
        damageActive.target = opponent.active;
        store.reduceEffect(state, damageActive);
        opponent.bench.forEach((benched) => {
          if (benched.cards.length > 0) {
            const damage = new PutDamageEffect(effect, 30);
            damage.target = benched;
            store.reduceEffect(state, damage);
          }
        });
      }
      return state;
    }
  };

