  var HoOh5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.hp = 130;
      this.cardType = [R];
      this.weakness = [{ type: W }];
      this.retreat = [C, C];
      this.attacks = [
        {
          name: "Sacred Breath",
          cost: [R, R],
          damage: 0,
          text: "Discard all Energy from this Pok\xE9mon. Heal all damage from 1 of your Benched Pok\xE9mon."
        },
        {
          name: "Fire Wing",
          cost: [R, R, R],
          damage: 100,
          text: ""
        }
      ];
      this.regulationMark = "J";
      this.set = "30C";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "12";
      this.name = "Ho-Oh";
      this.fullName = "Ho-Oh 30C";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        DISCARD_ALL_ENERGY_FROM_POKEMON(store, state, effect, this);
        const hasDamagedBench = player.bench.some((b) => b.cards.length > 0 && b.damage > 0);
        if (!hasDamagedBench) {
          return state;
        }
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card, target) => {
          if (cardList === player.active || cardList.damage === 0) {
            blocked.push(target);
          }
        });
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_HEAL,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { min: 1, max: 1, allowCancel: false, blocked }
        ), (selected) => {
          if (!selected || selected.length === 0) {
            return;
          }
          const target = selected[0];
          const healEffect = new HealTargetEffect(effect, target.damage);
          healEffect.target = target;
          store.reduceEffect(state, healEffect);
        });
      }
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/11-mega-evolution/set-30th-celebration/illumise.ts
  init_game();
  init_attack_effects();
  init_check_effects();
  init_prefabs();
  var Illumise6 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.hp = 80;
      this.cardType = [G];
      this.weakness = [{ type: R }];
      this.retreat = [C];
      this.powers = [{
        name: "Supereffective Pheromones",
        powerType: 2 /* ABILITY */,
        text: "If you have Volbeat in play, apply Weakness for both Active Pok\xE9mon as x3."
      }];
      this.attacks = [{
        name: "Ram",
        cost: [G, C],
        damage: 30,
        text: ""
      }];
      this.regulationMark = "J";
      this.set = "30C";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "4";
      this.name = "Illumise";
      this.fullName = "Illumise 30C";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof ApplyWeaknessEffect) {
        let applicator;
        for (const player of state.players) {
          let hasVolbeat = false;
          const illumises = [];
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
            if (cardList.getPokemonCard() !== card) {
              return;
            }
            if (card.name === "Volbeat") {
              hasVolbeat = true;
            }
            if (card.name === "Illumise" && card.powers.some((p) => p.name === "Supereffective Pheromones")) {
              illumises.push(card);
            }
          });
          if (!hasVolbeat) {
            continue;
          }
          for (const illumise of illumises) {
            if (!IS_ABILITY_BLOCKED(store, state, player, illumise)) {
              applicator = illumise;
              break;
            }
          }
          if (applicator) {
            break;
          }
        }
        if (applicator !== this) {
          return state;
        }
        const checkPokemonType = new CheckPokemonTypeEffect(effect.source);
        store.reduceEffect(state, checkPokemonType);
        const checkPokemonStats = new CheckPokemonStatsEffect(effect.target);
        store.reduceEffect(state, checkPokemonStats);
        const hasWeakness = !effect.ignoreWeakness && checkPokemonStats.weakness.some(
          (w) => w.value === void 0 && checkPokemonType.cardTypes.includes(w.type)
        );
        if (hasWeakness) {
          effect.damage = effect.damage * 1.5;
        }
      }
      return state;
    }
  };

