  var Moltres13 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.hp = 120;
      this.cardType = [R];
      this.weakness = [{ type: W }];
      this.retreat = [C];
      this.powers = [{
        name: "Fiery Flapping",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn, if you have Articuno and Zapdos in play, you may use this Ability. Attach a Basic [R] Energy card from your hand to this Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Fire Spin",
        cost: [R, R, C],
        damage: 130,
        text: "Discard 2 Energy from this Pok\xE9mon."
      }];
      this.regulationMark = "J";
      this.set = "30C";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "11";
      this.name = "Moltres";
      this.fullName = "Moltres 30C";
      this.FIERY_FLAPPING_MARKER = "FIERY_FLAPPING_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        let hasArticuno = false;
        let hasZapdos = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card) => {
          if (cardList2.getPokemonCard() !== card) {
            return;
          }
          if (card.name === "Articuno") {
            hasArticuno = true;
          }
          if (card.name === "Zapdos") {
            hasZapdos = true;
          }
        });
        if (!hasArticuno || !hasZapdos) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInHand = player.hand.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(2 /* FIRE */)
        );
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.FIERY_FLAPPING_MARKER, this);
        ABILITY_USED(player, this);
        const cardList = StateUtils.findCardList(state, this);
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_ATTACH,
          player.hand,
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
          { min: 1, max: 1, allowCancel: false }
        ), (cards) => {
          if (cards && cards.length > 0) {
            MOVE_CARDS(store, state, player.hand, cardList, { cards, sourceCard: this });
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.FIERY_FLAPPING_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_X_ENERGY_FROM_THIS_POKEMON(store, state, effect, 2);
      }
      return state;
    }
  };

