  init_game_effects();
  init_prefabs();
  var Wishiwashi7 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.hp = 30;
      this.cardType = [W];
      this.weakness = [{ type: L }];
      this.retreat = [C];
      this.powers = [{
        name: "Counterattack Grouping",
        powerType: 2 /* ABILITY */,
        text: "If your Wishiwashi or Wishiwashi ex is in the Active Spot and is damaged by an attack from your opponent's Pok\xE9mon (even if your Pok\xE9mon is Knocked Out), place 3 damage counters on the Attacking Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Surprise Attack",
        cost: [W],
        damage: 30,
        text: "Flip a coin. If tails, this attack does nothing."
      }];
      this.regulationMark = "J";
      this.set = "30C";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "22";
      this.name = "Wishiwashi";
      this.fullName = "Wishiwashi 30C";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof AfterDamageEffect && state.phase === 3 /* ATTACK */) {
        const owner = StateUtils.findOwner(state, StateUtils.findCardList(state, this));
        if (!StateUtils.isPokemonInPlay(owner, this)) {
          return state;
        }
        if (effect.player === owner || effect.target !== owner.active) {
          return state;
        }
        const activeCard = owner.active.getPokemonCard();
        if (!activeCard || activeCard.name !== "Wishiwashi" && activeCard.name !== "Wishiwashi ex") {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, owner, this)) {
          return state;
        }
        const damageEffect = new EffectOfAbilityEffect(owner, this.powers[0], this, effect.source);
        store.reduceEffect(state, damageEffect);
        if (damageEffect.target) {
          damageEffect.target.damage += 30;
        }
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        COIN_FLIP_PROMPT(store, state, effect.player, (result) => {
          if (!result) {
            effect.damage = 0;
          }
        });
      }
      return state;
    }
  };

