  var Zapdos14 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.hp = 120;
      this.cardType = [L];
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this.powers = [{
        name: "Flash-Pop Flapping",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn, if you have Moltres and Articuno in play, you may use this Ability. Attach a Basic [L] Energy card from your hand to this Pok\xE9mon."
      }];
      this.attacks = [{
        name: "Thundering Lightning",
        cost: [L, L, L, C],
        damage: 210,
        text: "This Pok\xE9mon also does 60 damage to itself."
      }];
      this.regulationMark = "J";
      this.set = "30C";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "55";
      this.name = "Zapdos";
      this.fullName = "Zapdos 30C";
      this.FLASH_POP_FLAPPING_MARKER = "FLASH_POP_FLAPPING_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.BLOCKED_BY_EFFECT);
        }
        let hasMoltres = false;
        let hasArticuno = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card) => {
          if (cardList2.getPokemonCard() !== card) {
            return;
          }
          if (card.name === "Moltres") {
            hasMoltres = true;
          }
          if (card.name === "Articuno") {
            hasArticuno = true;
          }
        });
        if (!hasMoltres || !hasArticuno) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        const hasEnergyInHand = player.hand.cards.some(
          (c) => c instanceof EnergyCard && c.energyType === 0 /* BASIC */ && c.provides.includes(4 /* LIGHTNING */)
        );
        if (!hasEnergyInHand) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.FLASH_POP_FLAPPING_MARKER, this);
        ABILITY_USED(player, this);
        const cardList = StateUtils.findCardList(state, this);
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_ATTACH,
          player.hand,
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Lightning Energy" },
          { min: 1, max: 1, allowCancel: false }
        ), (cards) => {
          if (cards && cards.length > 0) {
            MOVE_CARDS(store, state, player.hand, cardList, { cards, sourceCard: this });
          }
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.FLASH_POP_FLAPPING_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        THIS_POKEMON_DOES_DAMAGE_TO_ITSELF(store, state, effect, 60);
      }
      return state;
    }
  };

