  init_game();
  init_check_effects();
  init_prefabs();
  var Zoroark11 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Zorua";
      this.hp = 120;
      this.cardType = [D];
      this.weakness = [{ type: G }];
      this.retreat = [C];
      this.powers = [{
        name: "Night Escape Route",
        powerType: 2 /* ABILITY */,
        text: "As long as this Pok\xE9mon is on your Bench, your Active Pok\xE9mon's retreat cost is [C][C] less."
      }];
      this.attacks = [{
        name: "Slash Claw",
        cost: [D, D, C],
        damage: 90,
        text: ""
      }];
      this.regulationMark = "J";
      this.set = "30C";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "96";
      this.name = "Zoroark";
      this.fullName = "Zoroark 30C";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof CheckRetreatCostEffect) {
        const player = effect.player;
        const isBenched = player.bench.some((b) => b.cards.includes(this) && b.getPokemonCard() === this);
        if (!isBenched) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        for (let i = 0; i < 2; i++) {
          const index = effect.cost.indexOf(9 /* COLORLESS */);
          if (index !== -1) {
            effect.cost.splice(index, 1);
          }
        }
      }
      return state;
    }
  };

