  var Solgaleo5 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Cosmoem";
      this.hp = 170;
      this.cardType = [M];
      this.weakness = [{ type: R }];
      this.resistance = [{ type: G, value: -30 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Sunrise",
        powerType: 2 /* ABILITY */,
        useWhenInPlay: true,
        text: "Once during your turn, if this Pok\xE9mon is on your Bench, you may use this Ability. Search your deck for up to 2 Basic [M] Energy cards and attach them to this Pok\xE9mon. Then, shuffle your deck."
      }];
      this.attacks = [{
        name: "Sunsteel Strike",
        cost: [M, M, C, C],
        damage: 220,
        text: "Discard all Energy from this Pok\xE9mon."
      }];
      this.regulationMark = "J";
      this.set = "30C";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "105";
      this.name = "Solgaleo";
      this.fullName = "Solgaleo 30C";
      this.SUNRISE_MARKER = "SUNRISE_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const isBenched = player.bench.some((b) => b === cardList);
        if (!isBenched) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        USE_ABILITY_ONCE_PER_TURN(player, this.SUNRISE_MARKER, this);
        ABILITY_USED(player, this);
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, _card, target) => {
          if (list !== cardList) {
            blockedTo.push(target);
          }
        });
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_CARDS,
          player.deck,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Metal Energy" },
          { allowCancel: true, min: 0, max: 2, blockedTo }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.deck, target, {
              cards: [transfer.card],
              sourceCard: this,
              sourceEffect: this.powers[0]
            });
          }
          SHUFFLE_DECK(store, state, player);
        });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.SUNRISE_MARKER, this);
      if (WAS_ATTACK_USED(effect, 0, this)) {
        DISCARD_ALL_ENERGY_FROM_POKEMON(store, state, effect, this);
      }
      return state;
    }
  };

