  init_play_card_effects();
  init_prefabs();
  var MegaLucarioZex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Riolu";
      this._tags = ["Mega ex" /* POKEMON_SV_MEGA */, "ex" /* POKEMON_ex */];
      this.cardType = [M];
      this.hp = 330;
      this.weakness = [{ type: R }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Aura Seeker",
        useWhenInPlay: true,
        powerType: 2 /* ABILITY */,
        text: "Once during your turn, if this Pok\xE9mon is in the Active Spot, you may use this Ability. Search your deck for a Supporter card, reveal it, and put it into your hand. Then, shuffle your deck."
      }];
      this.attacks = [{
        name: "Dancing Fist",
        cost: [M, M],
        damage: 120,
        damageCalculation: "+",
        text: "If your opponent's Active Pok\xE9mon is a Pok\xE9mon ex, this attack does 120 more damage."
      }];
      this.regulationMark = "J";
      this.set = "FLO";
      this.setNumber = "58";
      this.cardImage = "assets/cardback.png";
      this.name = "Mega Lucario Z ex";
      this.fullName = "Mega Lucario Z ex FLO";
      this.AURA_SEEKER_MARKER = "AURA_SEEKER_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const defending = opponent.active.getPokemonCard();
        if (defending && defending.hasTag("ex" /* POKEMON_ex */)) {
          THIS_ATTACK_DOES_X_MORE_DAMAGE(effect, store, state, 120);
        }
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        player.marker.removeMarker(this.AURA_SEEKER_MARKER, this);
      }
      if (effect instanceof EndTurnEffect && effect.player.marker.hasMarker(this.AURA_SEEKER_MARKER, this)) {
        const player = effect.player;
        player.marker.removeMarker(this.AURA_SEEKER_MARKER, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (player.marker.hasMarker(this.AURA_SEEKER_MARKER, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(state, new ChooseCardsPrompt(
          player,
          GameMessage.CHOOSE_CARD_TO_HAND,
          player.deck,
          { superType: 2 /* TRAINER */, trainerType: 1 /* SUPPORTER */ },
          { min: 0, max: 1, allowCancel: false }
        ), (cards) => {
          MOVE_CARDS(store, state, player.deck, player.hand, { cards, sourceCard: this, sourceEffect: this.powers[0] });
          if (cards.length > 0) {
            state = store.prompt(state, new ShowCardsPrompt(
              opponent.id,
              GameMessage.CARDS_SHOWED_BY_THE_OPPONENT,
              cards
            ), () => {
            });
          }
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          return store.prompt(state, new ShuffleDeckPrompt(player.id), (order) => {
            player.deck.applyOrder(order);
            player.marker.addMarker(this.AURA_SEEKER_MARKER, this);
          });
        });
      }
      return state;
    }
  };

