  var Sigilyphex = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this._tags = ["ex" /* POKEMON_ex */];
      this.stage = 2 /* BASIC */;
      this.cardType = [P];
      this.hp = 210;
      this.weakness = [{ type: D }];
      this.resistance = [{ type: F, value: -30 }];
      this.retreat = [C];
      this.powers = [{
        name: "Mega Protection",
        powerType: 2 /* ABILITY */,
        text: "Prevent all damage done to this Pok\xE9mon by attacks from your opponent's Mega Evolution Pok\xE9mon ex."
      }];
      this.attacks = [{
        name: "Power Cyclone",
        cost: [C, C, C],
        damage: 140,
        text: "Move an Energy from this Pok\xE9mon to 1 of your Benched Pok\xE9mon."
      }];
      this.regulationMark = "J";
      this.set = "FLO";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "32";
      this.name = "Sigilyph ex";
      this.fullName = "Sigilyph ex FLO";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PutDamageEffect && effect.target.cards.includes(this)) {
        const player = StateUtils.findOwner(state, effect.target);
        const opponent = StateUtils.findOwner(state, effect.source);
        const pokemonCard = effect.target.getPokemonCard();
        const sourceCard = effect.source.getPokemonCard();
        if (pokemonCard !== this || sourceCard === void 0) {
          return state;
        }
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        if (player === opponent) {
          return state;
        }
        if (state.phase !== 3 /* ATTACK */) {
          return state;
        }
        if (sourceCard.hasTag("Mega ex" /* POKEMON_SV_MEGA */) && sourceCard.hasTag("ex" /* POKEMON_ex */)) {
          effect.preventDefault = true;
        }
      }
      if (effect instanceof AfterAttackEffect && effect.attack === this.attacks[0]) {
        const player = effect.player;
        const hasBench = player.bench.some((b) => b.cards.length > 0);
        if (!hasBench) {
          return state;
        }
        return store.prompt(state, new AttachEnergyPrompt(
          player.id,
          GameMessage.ATTACH_ENERGY_TO_BENCH,
          player.active,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */],
          { superType: 3 /* ENERGY */ },
          { allowCancel: false, min: 1, max: 1 }
        ), (transfers) => {
          transfers = transfers || [];
          for (const transfer of transfers) {
            const target = StateUtils.getTarget(state, player, transfer.to);
            MOVE_CARDS(store, state, player.active, target, { cards: [transfer.card], sourceCard: this });
          }
        });
      }
      return state;
    }
  };

