  var CynthiasFeelings = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 1 /* SUPPORTER */;
      this.set = "LA";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "131";
      this.name = "Cynthia's Feelings";
      this.fullName = "Cynthia's Feelings LA";
      this.text = "Shuffle your hand into your deck. Then, draw 4 cards. If any of your Pok\xE9mon were Knocked Out during your opponent's last turn, draw 4 more cards.";
      this.FEELINGS_MARKER = "FEELINGS_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof KnockOutEffect) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const duringTurn = [2 /* PLAYER_TURN */, 3 /* ATTACK */].includes(state.phase);
        if (!duringTurn || state.players[state.activePlayer] !== opponent) return state;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner === player) effect.player.marker.addMarker(this.FEELINGS_MARKER, this);
        return state;
      }
      if (effect instanceof TrainerEffect && effect.trainerCard === this) {
        const player = effect.player;
        let cardsToDraw = 4;
        if (HAS_MARKER(this.FEELINGS_MARKER, player, this)) cardsToDraw = 8;
        MOVE_CARDS(store, state, player.hand, player.supporter, { cards: [effect.trainerCard], sourceCard: this });
        effect.preventDefault = true;
        MOVE_CARDS(store, state, player.hand, player.deck, {
          cards: player.hand.cards.filter((c) => c !== this)
        });
        SHUFFLE_DECK(store, state, player);
        DRAW_CARDS(store, state, player, cardsToDraw);
        MOVE_CARDS(store, state, player.supporter, player.discard, { cards: [this], sourceCard: this });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.FEELINGS_MARKER, this);
      return state;
    }
  };

