        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const waterEnergyInDiscard = player.discard.cards.filter(
          (c) => c.superType === 3 /* ENERGY */ && c.energyType === 0 /* BASIC */ && c.name === "Water Energy"
        );
