            MOVE_CARDS(store, state, player.discard, player.deck, { cards, sourceCard: this, sourceEffect: this.attacks[0] });
            SHOW_CARDS_TO_PLAYER(store, state, opponent, cards);
            SHUFFLE_DECK(store, state, player);
