  var MespritLVX = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 11 /* LV_X */;
      this.evolvesFrom = "Mesprit";
      this._tags = ["Lv.X" /* POKEMON_LV_X */];
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P }];
      this.retreat = [C];
      this.attacks = [
        {
          name: "Healing Look",
          cost: [],
          damage: 0,
          text: "Remove 3 damage counters from each of your Benched Pok\xE9mon."
        },
        {
          name: "Supreme Blast",
          cost: [P, P],
          damage: 200,
          text: "If don't have Uxie LV.X and Azelf LV.X in play, this attack does nothing. Discard all Energy attached to Mesprit."
        }
      ];
      this.set = "LA";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "143";
      this.name = "Mesprit";
      this.fullName = "Mesprit Lv. X LA";
    }
    reduceEffect(store, state, effect) {
      if (AFTER_ATTACK(effect, 0, this)) {
        const player = effect.player;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (card) => {
          if (card !== player.active) {
            const healEffect = new HealEffect(player, card, 30);
            store.reduceEffect(state, healEffect);
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        let isMespritInPlay = false;
        let isUxieInPlay = false;
        let isAzelfInPlay = false;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, card) => {
          if (card === this) {
            isMespritInPlay = true;
          } else if (card.name === "Uxie" && card.stage === 11 /* LV_X */) {
            isUxieInPlay = true;
          } else if (card.name === "Azelf" && card.stage === 11 /* LV_X */) {
            isAzelfInPlay = true;
          }
        });
        const isTrioInPlay = isMespritInPlay && isUxieInPlay && isAzelfInPlay;
        if (!isTrioInPlay) {
          effect.damage = 0;
          return state;
        }
        DISCARD_ALL_ENERGY_FROM_POKEMON(store, state, effect, this);
      }
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        if (effect.target !== effect.player.active) {
          throw new GameError(GameMessage.CANNOT_PLAY_THIS_CARD);
        }
      }
      if (effect instanceof CheckTableStateEffect) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner !== player) {
          return state;
        }
        let isThisInPlay = false;
        owner.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card) => {
          if (card === this) {
            isThisInPlay = true;
            player.showAllStageAbilities = true;
          }
        });
        if (!isThisInPlay) {
          return state;
        }
      }
      if (effect instanceof CheckPokemonAttacksEffect) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner !== player) {
          return state;
        }
        let isThisInPlay = false;
        owner.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card) => {
          if (card === this) {
            isThisInPlay = true;
          }
        });
        if (!isThisInPlay) {
          return state;
        }
        for (const evolutionCard of cardList.cards) {
          if (evolutionCard.superType === 1 /* POKEMON */ && evolutionCard !== this && evolutionCard.name === this.evolvesFrom) {
            effect.attacks.push(...evolutionCard.attacks || []);
          }
        }
      }
      if (effect instanceof CheckPokemonPowersEffect) {
        const player = effect.player;
        const cardList = StateUtils.findCardList(state, this);
        const owner = StateUtils.findOwner(state, cardList);
        if (owner !== player) {
          return state;
        }
        let isThisInPlay = false;
        owner.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card) => {
          if (card === this) {
            isThisInPlay = true;
          }
        });
        if (!isThisInPlay) {
          return state;
        }
        for (const evolutionCard of cardList.cards) {
          if (evolutionCard.superType === 1 /* POKEMON */ && evolutionCard !== this && evolutionCard.name === this.evolvesFrom) {
            effect.powers.push(...evolutionCard.powers || []);
          }
        }
      }
      return state;
    }
  };

