  var STARK_TYPES = [2 /* FIRE */, 6 /* FIGHTING */];
  var MOVABLE_ENERGY = [...STARK_TYPES, 0 /* ANY */];
  var StarkMountain = class extends TrainerCard {
    constructor() {
      super(...arguments);
      this._trainerType = 2 /* STADIUM */;
      this.set = "LA";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "135";
      this.name = "Stark Mountain";
      this.fullName = "Stark Mountain LA";
      this.text = "Once during each player's turn, that player may choose a [R] or [F] Energy attached to 1 of his or her Pok\xE9mon and move that Energy to 1 of his or her [R] or [F] Pok\xE9mon.";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof UseStadiumEffect && StateUtils.getStadiumCard(state) === this) {
        const player = effect.player;
        const blockedMap = [];
        const blockedTo = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList, _card, target) => {
          const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, cardList);
          store.reduceEffect(state, checkProvidedEnergy);
          const blocked = checkProvidedEnergy.energyMap.filter((em) => !MOVABLE_ENERGY.some((t) => em.provides.includes(t))).map((em) => cardList.cards.indexOf(em.card)).filter((index) => index !== -1);
          if (blocked.length > 0) {
            blockedMap.push({ source: target, blocked: [...new Set(blocked)] });
          }
          const checkPokemonType = new CheckPokemonTypeEffect(cardList);
          store.reduceEffect(state, checkPokemonType);
          if (!STARK_TYPES.some((t) => checkPokemonType.cardTypes.includes(t))) {
            blockedTo.push(target);
          }
        });
        store.prompt(
          state,
          new MoveEnergyPrompt(
            player.id,
            GameMessage.MOVE_ENERGY_CARDS,
            2 /* BOTTOM_PLAYER */,
            [2 /* BENCH */, 1 /* ACTIVE */],
            { superType: 3 /* ENERGY */ },
            { allowCancel: true, min: 1, max: 1, blockedMap, blockedTo }
          ),
          (transfers) => {
            if (!transfers?.length) {
              return;
            }
            for (const transfer of transfers) {
              const source = StateUtils.getTarget(state, player, transfer.from);
              const target = StateUtils.getTarget(state, player, transfer.to);
              if (!source || !target) {
                continue;
              }
              if (IS_STADIUM_EFFECT_BLOCKED(store, state, player, source, this) || IS_STADIUM_EFFECT_BLOCKED(store, state, player, target, this)) {
                continue;
              }
              MOVE_CARDS(store, state, source, target, { cards: [transfer.card], sourceCard: this });
            }
          }
        );
      }
      return state;
    }
  };

