  var Bronzong15 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 3 /* STAGE_1 */;
      this.evolvesFrom = "Bronzor";
      this.cardType = [P];
      this.hp = 90;
      this.weakness = [{ type: P, value: 20 }];
      this.resistance = [{ type: R, value: -20 }];
      this.retreat = [C, C, C];
      this.powers = [{
        name: "Pain Amplifier",
        powerType: 0 /* POKEBODY */,
        text: "As long as Bronzong is your Active Pok\xE9mon, put 1 damage counter on each of your opponent's Pok\xE9mon that has any Pok\xE9-Powers between turns."
      }];
      this.attacks = [
        {
          name: "Pain Amplifier",
          cost: [],
          damage: 0,
          text: "Put 1 damage counter on each of your opponent's Pok\xE9mon that already has damage counters on it."
        },
        {
          name: "Coating",
          cost: [P, C, C],
          damage: 60,
          text: "During your opponent's next turn, any damage done to Bronzong by attacks is reduced by 20 (after applying Weakness and Resistance)."
        }
      ];
      this.set = "MD";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "16";
      this.name = "Bronzong";
      this.fullName = "Bronzong MD";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof BetweenTurnsEffect && effect.player.active.getPokemonCard() === this) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        if (IS_POKEBODY_BLOCKED(store, state, player, this)) {
          return state;
        }
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList, card) => {
          const pokemon = cardList.getPokemonCard();
          if (pokemon) {
            const powersEffect = new CheckPokemonPowersEffect(opponent, card);
            state = store.reduceEffect(state, powersEffect);
            if (powersEffect.powers.some((p) => p.powerType === 1 /* POKEPOWER */)) {
              cardList.damage += 10;
            }
          }
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        opponent.forEachPokemon(1 /* TOP_PLAYER */, (cardList) => {
          if (cardList.damage === 0) {
            return;
          }
          const damageEffect = new PutCountersEffect(effect, 10);
          damageEffect.target = cardList;
          store.reduceEffect(state, damageEffect);
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        return THIS_POKEMON_TAKES_LESS_DAMAGE_FROM_ATTACKS_DURING_OPPONENTS_NEXT_TURN(store, state, effect, 20);
      }
      return state;
    }
  };

