  var Empoleon8 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 4 /* STAGE_2 */;
      this.evolvesFrom = "Prinplup";
      this.cardType = [W];
      this.hp = 130;
      this.weakness = [{ type: L, value: 30 }];
      this.retreat = [C, C];
      this.attacks = [{
        name: "Dual Splash",
        cost: [W, C],
        damage: 0,
        text: "Choose 2 of your opponent's Pok\xE9mon. This attack does 30 damage to each of them. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }, {
        name: "Aqua Jet",
        cost: [W, W, C],
        damage: 50,
        damageCalculation: "+",
        text: "Does 50 damage plus 10 more damage for each of your Benched Pok\xE9mon. Flip a coin. If tails, this attack does 10 damage to each of your Benched Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.)"
      }];
      this.set = "MD";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "17";
      this.name = "Empoleon";
      this.fullName = "Empoleon MD";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const opponentTargets = [opponent.active, ...opponent.bench].filter((p) => p.cards.length > 0);
        const numTargets = opponentTargets.length;
        const minMax = numTargets >= 2 ? 2 : 1;
        store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          1 /* TOP_PLAYER */,
          [1 /* ACTIVE */, 2 /* BENCH */],
          { min: minMax, max: minMax, allowCancel: false }
        ), (selected) => {
          const targets = selected || [];
          targets.forEach((target) => {
            const damageEffect = new PutDamageEffect(effect, 30);
            damageEffect.target = target;
            store.reduceEffect(state, damageEffect);
          });
          return state;
        });
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        const playerBench = player.bench.reduce((left, b) => left + (b.cards.length ? 1 : 0), 0);
        effect.damage += playerBench * 10;
        COIN_FLIP_PROMPT(store, state, player, (result) => {
          if (!result) {
            player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
              if (cardList === player.active) {
                return;
              }
              const damage = new PutDamageEffect(effect, 10);
              damage.target = cardList;
              store.reduceEffect(state, damage);
            });
          }
        });
      }
      return state;
    }
  };

