  var Moltres14 = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.hp = 100;
      this.cardType = [R];
      this.weakness = [{ type: W }];
      this.resistance = [{ type: F, value: -20 }];
      this.retreat = [C, C];
      this.powers = [{
        name: "Flame Charge",
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn, when you put Moltres from your hand onto your Bench, you may flip a coin. If heads, search your discard pile for up to 3 [R] Energy cards and attach them to Moltres."
      }];
      this.attacks = [{
        name: "Scorching Wing",
        cost: [R, R, C],
        damage: 100,
        text: "Discard all Fire Energy attached to Moltres."
      }];
      this.set = "MD";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "10";
      this.name = "Moltres";
      this.fullName = "Moltres MD";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        const player = effect.player;
        if (IS_ABILITY_BLOCKED(store, state, player, this)) {
          return state;
        }
        state = CONFIRMATION_PROMPT(store, state, effect.player, (wantToUse) => {
          if (wantToUse) {
            COIN_FLIP_PROMPT(store, state, player, (result) => {
              if (!result) {
                return state;
              }
              if (!HAS_CARD_IN_DISCARD(player, { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" })) {
                return state;
              }
              const moltresSlot = StateUtils.findPokemonSlot(state, this);
              if (!moltresSlot) {
                return state;
              }
              let moltresTarget;
              const blockedTo = [];
              player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
                if (list === moltresSlot && card === this) {
                  moltresTarget = target;
                } else {
                  blockedTo.push(target);
                }
              });
              if (!moltresTarget) {
                return state;
              }
              return store.prompt(state, new AttachEnergyPrompt(
                player.id,
                GameMessage.ATTACH_ENERGY_CARDS,
                player.discard,
                2 /* BOTTOM_PLAYER */,
                [moltresTarget.slot],
                { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */, name: "Fire Energy" },
                { min: 0, max: 3, allowCancel: false, sameTarget: true, blockedTo }
              ), (transfers) => {
                transfers = transfers || [];
                for (const transfer of transfers) {
                  const target = StateUtils.getTarget(state, player, transfer.to);
                  MOVE_CARDS(store, state, player.discard, target, { cards: [transfer.card], sourceCard: this });
                }
              });
            });
          }
          return state;
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const cards = checkProvidedEnergy.energyMap.filter((e) => e.provides.includes(2 /* FIRE */) || e.provides.includes(0 /* ANY */)).map((e) => e.card);
        const discardEnergy2 = new DiscardCardsEffect(effect, cards);
        discardEnergy2.target = player.active;
        store.reduceEffect(state, discardEnergy2);
      }
      return state;
    }
  };

