  var UnownP = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.evolvesFrom = "Unown P";
      this.cardType = [P];
      this.hp = 50;
      this.weakness = [{ type: P, value: 10 }];
      this.retreat = [C];
      this.powers = [{
        name: "PUT",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), if Unown P is on your Bench, you may put 1 damage counter on 1 of your Pok\xE9mon (excluding any Unown)."
      }];
      this.attacks = [
        {
          name: "Hidden Power",
          cost: [P],
          damage: 20,
          damageCalculation: "+",
          text: "Each player discards the top card of his or her deck. This attack does 20 damage plus 20 more damage for each Unown discarded in this way."
        }
      ];
      this.set = "MD";
      this.name = "Unown P";
      this.fullName = "Unown P MD";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "33";
      this.PUT_MARKER = "PUT_MARKER";
    }
    reduceEffect(store, state, effect) {
      if (effect instanceof PlayPokemonEffect && effect.pokemonCard === this) {
        REMOVE_MARKER(this.PUT_MARKER, effect.player, this);
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        const isOnBench = player.bench.some((cardList) => cardList.getPokemonCard() === this);
        if (!isOnBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        if (HAS_MARKER(this.PUT_MARKER, player, this)) {
          throw new GameError(GameMessage.POWER_ALREADY_USED);
        }
        const blocked = [];
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (list, card, target) => {
          if (card.name.includes("Unown")) {
            blocked.push(target);
          }
        });
        return store.prompt(state, new ChoosePokemonPrompt(
          player.id,
          GameMessage.CHOOSE_POKEMON_TO_DAMAGE,
          2 /* BOTTOM_PLAYER */,
          [2 /* BENCH */, 1 /* ACTIVE */],
          { allowCancel: false, blocked }
        ), (targets) => {
          if (!targets || targets.length === 0) {
            return;
          }
          ADD_MARKER(this.PUT_MARKER, player, this);
          player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList) => {
            if (cardList.getPokemonCard() === this) {
              cardList.addBoardEffect(0 /* ABILITY_USED */);
            }
          });
          targets.forEach((target) => {
            target.damage += 10;
          });
        });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        const opponent = StateUtils.getOpponent(state, player);
        const playerTopDeck = new CardList();
        const opponentTopDeck = new CardList();
        let damageScaling = 0;
        MOVE_CARDS(store, state, player.deck, playerTopDeck, { count: 1, sourceCard: this });
        MOVE_CARDS(store, state, opponent.deck, opponentTopDeck, { count: 1, sourceCard: this });
        if (playerTopDeck.cards[0] instanceof PokemonCard && playerTopDeck.cards[0].name.includes("Unown")) {
          damageScaling++;
        }
        if (opponentTopDeck.cards[0] instanceof PokemonCard && opponentTopDeck.cards[0].name.includes("Unown")) {
          damageScaling++;
        }
        effect.damage += 20 * damageScaling;
        MOVE_CARDS(store, state, playerTopDeck, player.discard, { sourceCard: this });
        MOVE_CARDS(store, state, opponentTopDeck, opponent.discard, { sourceCard: this });
      }
      REMOVE_MARKER_AT_END_OF_TURN(effect, this.PUT_MARKER, this);
      return state;
    }
  };

  // work/rules-research/twinleafgg-main/ptcg-server/src/sets/04-diamond-pearl-platinum/set-majestic-dawn/unown-q.ts
  init_pokemon_card();
  init_card_types();
  init_game();
  init_check_effects();
  init_prefabs();
  function* usePower7(next, store, state, self, effect) {
    const player = effect.player;
    const cardList = StateUtils.findCardList(state, self);
    const benchIndex = player.bench.indexOf(cardList);
    if (benchIndex === -1) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    const pokemonCard = player.bench[benchIndex].getPokemonCard();
    if (pokemonCard !== self) {
      throw new GameError(GameMessage.ILLEGAL_ACTION);
    }
    let hasPokemonWithoutTool = false;
    const blocked = [];
    player.forEachPokemon(2 /* BOTTOM_PLAYER */, (cardList2, card, target) => {
      if (cardList2.tools.length === 0 && card !== self) {
        hasPokemonWithoutTool = true;
      } else {
        blocked.push(target);
      }
    });
    if (!hasPokemonWithoutTool) {
      throw new GameError(GameMessage.CANNOT_USE_POWER);
    }
    return store.prompt(state, new ChoosePokemonPrompt(
      player.id,
      GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
      2 /* BOTTOM_PLAYER */,
      [1 /* ACTIVE */, 2 /* BENCH */],
      { allowCancel: true, blocked }
    ), (targets) => {
      if (targets && targets.length > 0) {
        const unownQSlot = player.bench[benchIndex];
        const unownQCard = unownQSlot.getPokemonCard();
        if (!unownQCard) {
          return state;
        }
        const otherCards = unownQSlot.cards.filter(
          (card) => !(card instanceof PokemonCard) && !unownQSlot.getPokemons().includes(card) && (!unownQSlot.tools || !unownQSlot.tools.includes(card))
        );
        const tools = [...unownQSlot.tools];
        if (tools.length > 0) {
          for (const tool of tools) {
            MOVE_CARDS(store, state, unownQSlot, player.discard, { cards: [tool], sourceCard: self });
          }
        }
        if (otherCards.length > 0) {
          MOVE_CARDS(store, state, unownQSlot, player.discard, { cards: otherCards });
        }
        MOVE_CARDS(store, state, unownQSlot, targets[0], { cards: [unownQCard], sourceCard: self });
        targets[0].tools.push(unownQCard);
        unownQSlot.clearEffects();
      }
    });
  }
  var UnownQ = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [5 /* PSYCHIC */];
      this.hp = 30;
      this.weakness = [{ type: 5 /* PSYCHIC */, value: 10 }];
      this.retreat = [];
      this.powers = [{
        name: "Quick",
        useWhenInPlay: true,
        powerType: 1 /* POKEPOWER */,
        text: "Once during your turn (before your attack), if Unown Q is on your Bench, you may discard all cards attached to Unown Q and attach Unown Q to 1 of your Pokemon as Pokemon Tool card. As long as Unown Q is attached to a Pokemon, you pay C less to retreat that Pokemon."
      }];
      this.attacks = [
        {
          name: "Hidden Power",
          cost: [9 /* COLORLESS */],
          damage: 20,
          text: ""
        }
      ];
      this.set = "MD";
      this.name = "Unown Q";
      this.fullName = "Unown Q MD";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "49";
    }
    reduceEffect(store, state, effect) {
      if (WAS_POWER_USED(effect, 0, this)) {
        const generator = usePower7(() => generator.next(), store, state, this, effect);
        return generator.next().value;
      }
      if (effect instanceof CheckRetreatCostEffect && effect.player.active.tools.includes(this)) {
        const index = effect.cost.indexOf(9 /* COLORLESS */);
        if (index !== -1) {
          effect.cost.splice(index, 1);
        }
        return state;
      }
      return state;
    }
  };

