  var Arceus = class extends PokemonCard {
    constructor() {
      super(...arguments);
      this.stage = 2 /* BASIC */;
      this.cardType = [C];
      this.hp = 80;
      this.weakness = [{ type: F }];
      this.retreat = [C];
      this._tags = ["Arceus" /* ARCEUS */];
      this.attacks = [
        {
          name: "Ripple Swell",
          cost: [],
          damage: 0,
          text: "If you have 6 Arceus in play and each of them is a different type, search your deck for up to 6 basic Energy cards. Attach each of those Energy cards to a different Pok\xE9mon you have in play. Shuffle your deck afterward"
        },
        {
          name: "Sky Spear",
          cost: [C, C, C],
          damage: 0,
          text: "Choose 1 of your opponent's Pok\xE9mon. This attack does 80 damage to that Pok\xE9mon. (Don't apply Weakness and Resistance for Benched Pok\xE9mon.) Remove all Energy cards attached to Arceus and put them in the Lost Zone"
        }
      ];
      this.set = "AR";
      this.cardImage = "assets/cardback.png";
      this.setNumber = "AR5";
      this.name = "Arceus";
      this.fullName = "Arceus AR";
    }
    reduceEffect(store, state, effect) {
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let arceusInPlay = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (card) => {
          if (card.getPokemonCard()?.name === "Arceus") {
            arceusInPlay++;
          }
        });
        if (arceusInPlay !== 6) {
          return state;
        }
        return store.prompt(
          state,
          new AttachEnergyPrompt(
            player.id,
            GameMessage.ATTACH_ENERGY_TO_BENCH,
            player.deck,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { superType: 3 /* ENERGY */, energyType: 0 /* BASIC */ },
            { allowCancel: false, min: 0, max: 6, differentTargets: true }
          ),
          (transfers) => {
            transfers = transfers || [];
            if (transfers.length === 0) {
              SHUFFLE_DECK(store, state, player);
              return state;
            }
            for (const transfer of transfers) {
              const target = StateUtils.getTarget(state, player, transfer.to);
              MOVE_CARDS(store, state, player.deck, target, {
                cards: [transfer.card],
                sourceCard: this,
                sourceEffect: this.attacks[0]
              });
            }
            SHUFFLE_DECK(store, state, player);
          }
        );
      }
      if (WAS_ATTACK_USED(effect, 1, this)) {
        const player = effect.player;
        THIS_ATTACK_DOES_X_DAMAGE_TO_1_OF_YOUR_OPPONENTS_POKEMON(80, effect, store, state);
        const energies = player.active.cards.filter((card) => card.superType === 3 /* ENERGY */);
        MOVE_CARDS(store, state, player.active, player.lostzone, { cards: energies });
      }
      return state;
    }
  };

